-- Generated by `npm run myplate:parse` from data/myplate/pages/flat. Do not edit by hand.
-- 1124 recipes from the USDA MyPlate Kitchen corpus (public domain, 17 U.S.C. § 105).

insert into public.recipes (slug, source_url, name, description, ingredients, directions, yield, nutrition, notes, contributor)
select slug, source_url, name, description, ingredients, directions, yield, nutrition, notes, contributor
from jsonb_to_recordset('[
{"slug":"2-step-chicken","source_url":"https://www.myplate.gov/recipes/2-step-chicken","name":"2-Step Chicken","description":"The ultimate in simplicity, this recipe calls for chicken and cream of chicken soup. Pair it with a salad, or roasted mixed vegetables for a colorful dinner....","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","2 boneless, skinless chicken breasts","1 can (10.75 ounces) reduced-sodium cream of chicken soup","1/2 cup water"]}],"directions":[{"name":null,"steps":["Heat oil in a skillet at a medium-high setting.","Add chicken and cook for ten minutes.","Remove chicken from pan and set aside.","Stir the soup and water together in the skillet and heat it to a boil.","Return the chicken to the skillet. Reduce the heat to low and simmer for an additional 10 minutes, or until the chicken reaches an internal temperature of 165 degrees F."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 chicken breast","calories":"148.66 kcal","carbohydrateContent":"7.08 g","cholesterolContent":"49.48 mg","fiberContent":"0.30 g","proteinContent":"15.21 g","sodiumContent":"289.25 mg","sugarContent":"0.29 g","fatContent":"6.09 g","saturatedFatContent":"1.20 g"},"notes":"This recipe uses reduced-sodium cream of chicken soup.","contributor":"Recipe adapted from: Simple Healthy Recipes\nOklahoma Nutrition Information and Education (ONIE Project)"},
{"slug":"20-minute-chicken-creole","source_url":"https://www.myplate.gov/recipes/20-minute-chicken-creole","name":"20-Minute Chicken Creole","description":"This Creole-inspired dish uses chili sauce and cayenne pepper to spice it up. Tomatoes, green pepper, celery, onions and garlic spices also surround the chic...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","1 pound skinless, boneless chicken breasts","1 can (14.5 ounces) no salt added diced tomatoes","1 cup chili sauce (see note below)","1 large green pepper (chopped)","2 medium celery stalks (chopped)","1 medium onion (chopped)","2 garlic cloves (minced)","1 teaspoon dried basil","1 teaspoon dried parsley","1/4 teaspoon cayenne pepper"]}],"directions":[{"name":null,"steps":["Heat pan over medium-high heat (350 degrees F in an electric skillet). Add vegetable oil and chicken and cook until the chicken reaches an internal temperature of 165 degrees F (3-5 minutes).","Reduce heat to medium (300 degrees F in electric skillet).","Add tomatoes with juice, chili sauce*, green pepper, celery, onion, garlic, basil, parsley, and cayenne pepper..","Bring to a boil; reduce heat to low and simmer, covered for 10-15 minutes.","Serve over hot, cooked rice or whole wheat pasta.","* Store bought chili sauce can be high in sodium. You can make your own chili sauce by mixing these ingredients:","1 can (8 ounces) tomato sauce","1 Tablespoon vinegar","1 teaspoon packed brown sugar","1 teaspoon chili powder"]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"131.58 kcal","carbohydrateContent":"11.87 g","cholesterolContent":"37.53 mg","fiberContent":"2.57 g","proteinContent":"13.33 g","sodiumContent":"488.75 mg","sugarContent":"7.23 g","fatContent":"3.41 g","saturatedFatContent":"0.58 g"},"notes":null,"contributor":"Recipe Adapted from: Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"3-can-chili","source_url":"https://www.myplate.gov/recipes/3-can-chili","name":"3-Can Chili","description":"With almost no cooking required to prepare this chili, just open cans of beans, corn, and tomatoes, and heat everything together in a pan!","ingredients":[{"name":null,"items":["1 can (15.5 ounces) low-sodium black beans, undrained (or pinto, kidney, or red beans)","1 can (15.2 ounces) reduced sodium corn, drained (or 10-oz package of frozen corn)","1 can (14.5 ounces) low-sodium crushed tomatoes, undrained","1 teaspoon chili powder (or more, to taste)"]}],"directions":[{"name":null,"steps":["Place the contents of all 3 cans into a pan.","Add chili powder to taste.","Stir to mix.","Continue to stir over medium heat until heated thoroughly.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/6 of recipe","1 cup"],"calories":"126.43 kcal","carbohydrateContent":"25.46 g","cholesterolContent":"0.00 mg","fiberContent":"7.81 g","proteinContent":"6.53 g","sodiumContent":"130.18 mg","sugarContent":"5.16 g","fatContent":"1.05 g","saturatedFatContent":"0.15 g"},"notes":null,"contributor":"Recipe Adapted from: Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"5-day-salad","source_url":"https://www.myplate.gov/recipes/5-day-salad","name":"5 A Day Salad","description":"This nutrient-packed salad uses ten different vegetables, and each serving is equal to five cups of vegetables!","ingredients":[{"name":null,"items":["4 cups fresh spinach","4 cups romaine lettuce","2 cups chopped green peppers (or red, yellow, or orange peppers)","2 cups cherry tomatoes","1 cup broccoli (chopped)","1 cup cauliflower (chopped)","1 cup yellow squash (sliced)","1 cup cucumber (sliced)","2 cups carrot (chopped)","1 cup zucchini (sliced)"]}],"directions":[{"name":null,"steps":["Wash all of the vegetables and mix them together in a large mixing bowl.","Top this colorful meal with the nonfat or low-fat dressing of your choice."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (467g)","calories":"100.10 kcal","carbohydrateContent":"20.35 g","cholesterolContent":"0.00 mg","fiberContent":"6.71 g","proteinContent":"5.07 g","sodiumContent":"104.63 mg","sugarContent":"10.28 g","fatContent":"1.11 g","saturatedFatContent":"0.22 g"},"notes":"The dressing is not included in the nutritional analysis.\nEach serving = 5 cups of vegetables (Eight 5-A-Day servings).","contributor":"US Department of Health and Human Services Centers for Disease Control and Prevention (CDC)\n5 A Day for Better Health Program"},
{"slug":"ambrosia","source_url":"https://www.myplate.gov/recipes/ambrosia","name":"Ambrosia","description":"This dessert features fresh fruit, yogurt, and coconut, with a dash of marshmallows for fun. No cooking is required.","ingredients":[{"name":null,"items":["1 can (20 ounces) pineapple chunks in juice, drained","1 1/3 cups canned mandarin orange, drained","1 medium banana, peeled and sliced","1 1/2 cups seedless grapes","3/4 cup miniature marshmallows","1/3 cup flaked coconut","1 cup (8 ounces) low-fat vanilla yogurt"]}],"directions":[{"name":null,"steps":["Drain pineapple and oranges. Use juice as beverage.","Combine fruit with marshmallows and coconut.","Fold in yogurt.","Chill.","Serve."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"130.47 kcal","carbohydrateContent":"27.80 g","cholesterolContent":"1.84 mg","fiberContent":"1.69 g","proteinContent":"2.63 g","sodiumContent":"29.96 mg","sugarContent":"23.86 g","fatContent":"1.83 g","saturatedFatContent":"1.38 g"},"notes":null,"contributor":"A Holiday Dinner\nCornell Cooperative Extension of Onondaga County"},
{"slug":"angel-food-cake","source_url":"https://www.myplate.gov/recipes/angel-food-cake","name":"Angel Food Cake","description":"This recipe gives clear and easy instructions for making the classic, fluffy cake.","ingredients":[{"name":null,"items":["12 large egg whites (about 1 1/2 cups)","1 teaspoon cream of tartar","1 1/2 cups sugar","1 teaspoon vanilla extract","1/4 teaspoon salt","1 cup flour, sifted"]}],"directions":[{"name":null,"steps":["Preheat the oven to 325 degrees F. In a large mixing bowl, beat the egg whites until they are foamy.","Add the cream of tartar and beat until stiff, but not dry. Gradually beat in the sugar","Add the vanilla and salt and then gently fold in the flour.","Pour the mix into an angel food tubular 10-inch pan and bake for 1 hour and 15 minutes, or until the top is nicely browned."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 slice","calories":"156.98 kcal","carbohydrateContent":"33.83 g","cholesterolContent":"0.00 mg","fiberContent":"0.28 g","proteinContent":"4.61 g","sodiumContent":"104.58 mg","sugarContent":"25.26 g","fatContent":"0.18 g","saturatedFatContent":"0.02 g"},"notes":null,"contributor":"Ohio State University Cooperative Extension\nSandusky County Family Nutrition Program"},
{"slug":"angel-food-pastry-fresh-berries-and-whipped-cream","source_url":"https://www.myplate.gov/recipes/angel-food-pastry-fresh-berries-and-whipped-cream","name":"Angel Food Pastry with Fresh Berries and Whipped Cream","description":"Light and fluffy angel food cake is mixed with yogurt and a sprinkle of berries on top.","ingredients":[{"name":null,"items":["1 ounce angel food cake mix (3 tablespoons)","1/8 cup low-fat vanilla yogurt (2 tablespoons)","1/4 cup raspberries","2 strawberries, sliced","1 1/2 tablespoons lite whipped topping"]}],"directions":[{"name":null,"steps":["Scoop 3 tablespoons of angel food cake mix into a microwave-safe cup or mug.","Add 2 tablespoons of vanilla yogurt and stir.","Place in the center of the microwave oven and microwave for 1 minute.","Take out of microwave and let cool for 1 minute.","Using a knife, cut around the sides of the cup to loosen the cake and \"dump\" it on a plate.","Dole 1 tablespoon of whipped topping on top of the cake.","Sprinkle raspberries around the angel cake and add sliced strawberries to top.","Enjoy."]}],"yield":"1 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Angel Food Pastry","calories":"185.63 kcal","carbohydrateContent":"35.84 g","cholesterolContent":"2.05 mg","fiberContent":"3.45 g","proteinContent":"3.84 g","sodiumContent":"201.93 mg","sugarContent":"8.37 g","fatContent":"3.28 g","saturatedFatContent":"1.50 g"},"notes":null,"contributor":"Community Services for Autistic Adults and Children (CSAAC)"},
{"slug":"any-days-picnic-chicken-salad","source_url":"https://www.myplate.gov/recipes/any-days-picnic-chicken-salad","name":"Any Day''s a Picnic Chicken Salad","description":"Onion and pickle relish spice up a traditional chicken salad.","ingredients":[{"name":null,"items":["2 1/2 cups cooked chicken breast, diced","1/2 cup celery, chopped","1/4 cup onion, chopped","3 packages pickle relish (2 tablespoons)","1/2 cup light mayonnaise"]}],"directions":[{"name":null,"steps":["Combine all ingredients.","Refrigerate until ready to serve.","Use within 1-2 days. Chicken salad does not freeze well.","How to use:","Make chicken salad sandwiches.","Make a pasta salad by mixing with 2 cups cooked pasta.","Kids will love this salad served in a tomato or a cucumber boat."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"150.10"},"notes":null,"contributor":"University of Wisconsin Cooperative Extension Service\nA Family Living Program"},
{"slug":"anytime-pizza","source_url":"https://www.myplate.gov/recipes/anytime-pizza","name":"Anytime Pizza","description":"Make your own pizza topped with green peppers, mushrooms, or other vegetables.","ingredients":[{"name":null,"items":["1/4 mini baguette or Italian bread, about 9\" long (split lengthwise, or 2 split English muffins)","1/2 cup pizza sauce","1/2 cup part-skim mozzarella or cheddar cheese, shredded","1/4 cup green pepper, chopped","1/4 cup mushrooms, fresh or canned, sliced","other vegetable toppings (as desired, optional)","Italian seasoning (optional)"]}],"directions":[{"name":null,"steps":["Toast the bread or English muffin until slightly brown.","Top bread or muffin with pizza sauce, vegetables and low-fat cheese.","Sprinkle with Italian seasoning as desired.","Return bread to toaster oven (or regular oven preheated to 350 degrees F).","Heat until cheese melts."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1 English muffin or 1/2 of recipe"],"calories":"175.99 kcal","carbohydrateContent":"17.88 g","cholesterolContent":"19.66 mg","fiberContent":"1.88 g","proteinContent":"10.06 g","sodiumContent":"585.03 mg","sugarContent":"5.70 g","fatContent":"7.25 g","saturatedFatContent":"3.53 g"},"notes":null,"contributor":"Pumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"apple-banana-salad-peanuts","source_url":"https://www.myplate.gov/recipes/apple-banana-salad-peanuts","name":"Apple Banana Salad with Peanuts","description":"Enjoy a fresh, flavorful change of pace with a surprising mix of lettuce, apples, and bananas, topped with a paprika dressing. This is a quick, easy meal for...","ingredients":[{"name":null,"items":["12 ounces lettuce mix","2 ripe bananas","2 1/2 medium apples, sliced (14 oz. of sliced apples)","3/4 cup unsalted dry roasted peanuts"]},{"name":"For the Dressing","items":["1/3 cup plain low-fat yogurt","2 tablespoons fat-reduced mayonnaise","1 tablespoon honey","2 teaspoons paprika"]}],"directions":[{"name":null,"steps":["Whisk together dressing ingredients.","Slice bananas.","In a large salad bowl, toss mixed greens, banana and apple slices, peanuts, and dressing."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"358.85 kcal","carbohydrateContent":"47.44 g","cholesterolContent":"2.46 mg","fiberContent":"7.17 g","proteinContent":"9.76 g","sodiumContent":"102.54 mg","sugarContent":"32.75 g","fatContent":"16.35 g","saturatedFatContent":"2.74 g"},"notes":"Serving Suggestions: Serve with 8 ounce non-fat milk and one slice of rustic whole-grain bread.\nTips on how to select and store bananas:\nChoose bananas that are slightly green on the stem and tip. They should be firm, without bruises.\nStore unripe bananas at room temperature. Store ripe bananas in refrigerator for up to two weeks; peel may turn black.","contributor":"Produce For Better Health Foundation"},
{"slug":"apple-cake","source_url":"https://www.myplate.gov/recipes/apple-cake","name":"Apple Cake","description":"Sliced apples and apricot jam glaze on top make this a great cake for special occasions.","ingredients":[{"name":null,"items":["10 tablespoons unsalted butter (1 full stick + 2 tablespoons)","3/4 cup sugar","3 large eggs","1 3/4 cups flour, sifted","2 teaspoons baking powder","1 tablespoon lemon rind, grated","2 medium apples, pared, cored, sliced","2 teaspoons sugar","8 tablespoons apricot jam (1/2 cup)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 degrees F.","Beat butter with sugar until creamy.","Add eggs one at a time, beating until well blended.","Add flour, baking powder, and lemon rind, beat 4 minutes.","Pour into greased 9-inch spring-form pan.","Arrange the apples on the batter, sprinkle with 2 teaspoons sugar.","Bake 1 hour at 350 degrees F in preheated oven.","Remove from pan, brush apples with jam, cool."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/12 of recipe"],"calories":"280.05 kcal","carbohydrateContent":"41.60 g","cholesterolContent":"76.82 mg","fiberContent":"1.39 g","proteinContent":"3.65 g","sodiumContent":"103.49 mg","sugarContent":"23.78 g","fatContent":"11.12 g","saturatedFatContent":"6.42 g"},"notes":null,"contributor":"Wellness Ways Resource Book: Taste of the World\nUniversity of Illinois Extension Service"},
{"slug":"apple-carrot-soup","source_url":"https://www.myplate.gov/recipes/apple-carrot-soup","name":"Apple Carrot Soup","description":"Ginger and orange peel are the secret ingredients to this pork, apple, and carrot soup.","ingredients":[{"name":null,"items":["1 pound lean pork, cut into chunks","4 medium apples, cored and quartered (with skin)","4 large carrots, peeled and cut into chunks","orange peel, dried (1 teaspoon, optional)","4 slices ginger","1/2 teaspoon salt","20 cups water"]}],"directions":[{"name":null,"steps":["In a large pot over high heat, combine all ingredients, bring to a boil.","Reduce heat to medium and simmer until soup reduces to about 8 cups of liquid, about 3 to 4 hours.","Skim fat from surface and serve.","Store leftover soup covered in refrigerator for up to 3 days."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup (730g)","calories":"150.84 kcal","carbohydrateContent":"17.75 g","cholesterolContent":"31.99 mg","fiberContent":"2.92 g","proteinContent":"13.08 g","sodiumContent":"247.87 mg","sugarContent":"13.48 g","fatContent":"2.90 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Healthy & Delicious: Simple Ways to Low Fat Chinese Cooking\nSan Francisco Department of Public Health\nChinatown Public Health Center"},
{"slug":"apple-chicken-salad","source_url":"https://www.myplate.gov/recipes/apple-chicken-salad","name":"Apple & Chicken Salad","description":"A deliciously balanced blend of crisp Cameo apples, celery, raisins, chicken breast and Greek yogurt-based dressing, served over a bed of lettuce.","ingredients":[{"name":null,"items":["2 red apples (such as Cameo Apples)","2 celery stalks (diced)","2 chicken breasts (skinless, cooked, diced, about 2 cups)","1/4 cup plain non-fat Greek yogurt","1/2 cup raisins","1/4 cup mayonnaise","1/4 teaspoon salt","1/8 teaspoon ground black pepper","16 lettuce leaves (Bibb, Romaine, green or red leaf)"]}],"directions":[{"name":null,"steps":["Cut apples in quarters; remove core and chop.","In a medium size bowl, mix all ingredients, except lettuce.","To serve, arrange lettuce on serving plates top with apple and chicken salad."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"327.87 kcal","carbohydrateContent":"32.66 g","cholesterolContent":"65.82 mg","fiberContent":"3.63 g","proteinContent":"21.38 g","sodiumContent":"298.67 mg","sugarContent":"26.14 g","fatContent":"12.78 g","saturatedFatContent":"2.15 g"},"notes":"Weekly Menu Planning Tip: When you''re planning a dinner with chicken cook up extra chicken breast and refrigerate for later use in this salad.\nServe with 8 ounce non-fat milk and 1 slice rustic whole grain bread.","contributor":"Produce for Better Health Foundation"},
{"slug":"apple-chunk-cake","source_url":"https://www.myplate.gov/recipes/apple-chunk-cake","name":"Apple Chunk Cake","description":"Chunks of juicy apples fill this cake and fresh apples decorate the top.","ingredients":[{"name":null,"items":["1 1/4 cups sugar","1/4 cup vegetable oil (or cooking oil of choice)","2 large eggs","2 cups flour","1 teaspoon salt","1 teaspoon cinnamon","1 teaspoon baking soda","4 cups apples, divided (2 cups chopped into chunks, 2 cups sliced)","1/4 cup unsweetened applesauce"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","In a large bowl, mix sugar, oil and eggs together. Beat well.","In a separate bowl, combine flour, salt, cinnamon, and baking soda. Add to egg batter and mix well.","Add 2 cups of apple chunks and applesauce to the batter. Stir to combine.","Coat an 8x8-inch baking pan with vegetable oil spray and pour in batter.","Bake until done, about 1 hour.","Place 2 cups of apple slices on top of apple cake and serve."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 piece (1 1/2 \" x 2\")","calories":"241.39 kcal","carbohydrateContent":"43.65 g","cholesterolContent":"34.25 mg","fiberContent":"1.61 g","proteinContent":"3.27 g","sodiumContent":"313.10 mg","sugarContent":"26.39 g","fatContent":"5.84 g","saturatedFatContent":"0.95 g"},"notes":"Batter will be very thick. This is normal.","contributor":"Recipe adapted from: Healthy & Delicious: Simple Ways to Low Fat Chinese Cooking\nSan Francisco Department of Public Health\nChinatown Public Health Center"},
{"slug":"apple-cinnamon-bars","source_url":"https://www.myplate.gov/recipes/apple-cinnamon-bars","name":"Apple Cinnamon Bars","description":"Apples are sandwiched between two cinnamon crumb layers for a delicious treat.","ingredients":[{"name":null,"items":["4 medium apples","1 cup flour","1/4 teaspoon salt","1/2 teaspoon baking soda","1/2 teaspoon cinnamon","1/2 cup brown sugar, packed","1 cup oats, uncooked","1/2 cup margarine, 1 stick (or butter)","4 sprays of cooking spray"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 degrees F.","Put the flour, salt, baking soda, cinnamon, brown sugar, and oats in the mixing bowl. Stir together.","Add the margarine to the bowl. Use the 2 table knives to mix the ingredients and cut them into crumbs.","Lightly grease the bottom and sides of the baking dish with cooking spray.","Spread half of the crumb mixture in the greased baking dish.","Remove the core from the apples and slice them. Put the apple slices into the baking dish.","Top the apples with the rest of the crumb mixture.","Bake in the oven for 40-45 minutes.","Cut into squares. It will fall apart easily."]}],"yield":"24 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 bar","1/24 of recipe"],"calories":"103.33 kcal","carbohydrateContent":"15.75 g","cholesterolContent":"0.00 mg","fiberContent":"1.21 g","proteinContent":"1.05 g","sodiumContent":"87.48 mg","sugarContent":"8.53 g","fatContent":"4.12 g","saturatedFatContent":"0.77 g"},"notes":"You can use applesauce (16 ounces) or canned apples in place of fresh apples. You can use either peeled or unpeeled apples.","contributor":"Pennsylvania Nutrition Education Network (original)\nRecipe modification adapted from SNAP-Ed New York, October 2023"},
{"slug":"apple-coffee-cake","source_url":"https://www.myplate.gov/recipes/apple-coffee-cake","name":"Apple Coffee Cake","description":"This coffee cake provides a nice mix of apples, raisins, and pecans.","ingredients":[{"name":null,"items":["5 cups tart apples, cored, peeled, and chopped","1 cup sugar","1 cup raisins","1/2 cup pecans, chopped","1/4 cup vegetable oil (or cooking oil of choice)","2 teaspoons vanilla","1 egg, beaten","2 1/2 cups all-purpose flour, sifted","1 1/2 teaspoons baking soda","2 teaspoons ground cinnamon"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Lightly oil a 13x9x2 inch pan.","In a large mixing bowl, combine apples with sugar, raisins, and pecans; mix well. Let stand 30 minutes.","Stir in oil, vanilla, and egg. Sift together flour, baking soda, and cinnamon; stir into apple mixture about 1/3 at a time, just enough to moisten dry ingredients.","Turn batter into pan. Bake 35-40 minutes. Cool cake slightly before serving."]}],"yield":"20 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 piece (3 1/2\" x 2 1/2\") (70g)","calories":"188.01 kcal","carbohydrateContent":"33.47 g","cholesterolContent":"10.28 mg","fiberContent":"1.81 g","proteinContent":"2.47 g","sodiumContent":"100.17 mg","sugarContent":"19.18 g","fatContent":"5.12 g","saturatedFatContent":"0.67 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"apple-coleslaw","source_url":"https://www.myplate.gov/recipes/apple-coleslaw","name":"Apple Coleslaw","description":"The sweet and crunchy coleslaw blends cabbage, carrot, apple, and green pepper for a colorful side dish. You can also try it without the mayonnaise!","ingredients":[{"name":null,"items":["2 cups shredded cabbage","1 medium carrot, grated","1/2 medium green pepper, chopped","1 medium apple, chopped","5 tablespoons yogurt, low-fat","1 tablespoon mayonnaise, low-fat","1 teaspoon lemon juice","1/4 teaspoon dill weed"]}],"directions":[{"name":null,"steps":["Wash the cabbage. Cut it into fine shreds, until you have 2 cups of cabbage.","Peel the carrot. Grate it with a grater.","Chop half a green pepper into small pieces.","Remove the core, and chop the apple.","Put the cabbage, carrot, green pepper, and apple in a large mixing bowl. Stir together.","Put the yogurt, mayonnaise, lemon juice, and dill weed in a small bowl. Stir together to make a dressing.","Pour the dressing over the salad. Toss to mix.","Add salt and pepper to taste."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (126g)","calories":"72.62 kcal","carbohydrateContent":"13.96 g","cholesterolContent":"1.77 mg","fiberContent":"2.87 g","proteinContent":"1.97 g","sodiumContent":"64.99 mg","sugarContent":"10.07 g","fatContent":"1.35 g","saturatedFatContent":"0.37 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"apple-corn-chili","source_url":"https://www.myplate.gov/recipes/apple-corn-chili","name":"Apple Corn Chili","description":"This quick-fixing chili, with a base of sautéed, puréed red apples and yellow corn, is so thick and flavorful that you''d never know it''s low in fat and sod...","ingredients":[{"name":null,"items":["2 tablespoons olive oil (divided)","8 ounces boneless, skinless chicken breast (cut to 1/2\" cubes)","1 medium onion (chopped)","2 cloves garlic (minced)","1 3/4 cups canned yellow corn (15.2 ounce can, no-salt-added, drained)","2 red apples, such as Braeburn, Empire, or Fuji (chopped, skin on)","1/2 tablespoon ground cumin","1/8 teaspoon cayenne pepper (if desired)","1 can can (15 oz) black beans (low sodium, drained and rinsed)","4 1/2 ounces can diced green chiles (drained)","2 teaspoons chicken bouillon (low sodium)","2 cups water"]},{"name":"Topping","items":["1/4 cup sour cream (reduced-fat)","1/4 cup fresh, chopped cilantro (if desired)"]}],"directions":[{"name":null,"steps":["In a stockpot, heat 1 tbsp. olive oil; add chicken and brown (about 5 minutes). Remove chicken from pan.","Heat remaining olive oil in same pot; add onions and garlic and sauté until soft.","Add corn and sauté until golden brown. Add apple, cumin, and cayenne pepper (if desired); cook about 3-4 minutes. Let cool about 5 minutes.","Set aside about 1 cup of mixture. Purée remainder in food processor or blender, adding a portion of water, if needed, and return to pot.","Add browned chicken, black beans, chiles, bouillon, and water. Bring to boil and simmer about 15 minutes. Chicken should be cooked to 165 ºF.","To serve, ladle soup in bowls and top with non-puréed portion of apple corn mixture."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"383.88 kcal","carbohydrateContent":"50.92 g","cholesterolContent":"42.95 mg","fiberContent":"12.12 g","proteinContent":"21.34 g","sodiumContent":"336.28 mg","sugarContent":"17.40 g","fatContent":"11.53 g","saturatedFatContent":"2.63 g"},"notes":"Serving Suggestions: Serve with a whole-grain tortilla and an 8 ounce glass of fat-free (skim) milk.","contributor":"Produce For Better Health Foundation"},
{"slug":"apple-cranberry-salad-toss","source_url":"https://www.myplate.gov/recipes/apple-cranberry-salad-toss","name":"Apple Cranberry Salad Toss","description":"Enjoy the best of fall flavors with this sweet and tart green salad. Light yet crisp, it’s a perfect dish for the autumnal change of weather.","ingredients":[{"name":null,"items":["1 medium head of lettuce (about 10 cups)","2 medium apples, sliced","1/2 cup chopped walnuts","1 cup dried cranberries","1/2 cup green onions, sliced","3/4 cup vinaigrette dressing"]}],"directions":[{"name":null,"steps":["Toss lettuce, apples, walnuts, cranberries, and onions in a large bowl.","Add dressing; toss to coat. Serve immediately."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"205.46 kcal","carbohydrateContent":"30.08 g","cholesterolContent":"0.00 mg","fiberContent":"3.58 g","proteinContent":"2.23 g","sodiumContent":"233.72 mg","sugarContent":"24.22 g","fatContent":"9.94 g","saturatedFatContent":"1.16 g"},"notes":null,"contributor":"Creative Recipes for Less Familiar USDA Commodities Used by Household Programs\nUSDA, Food and Nutrition Service, Food Distribution Service"},
{"slug":"apple-crisp-0","source_url":"https://www.myplate.gov/recipes/apple-crisp-0","name":"Apple Crisp","description":"This apple crisp is a delicious dessert and a great way to enjoy fall''s bounty from the orchard.","ingredients":[{"name":null,"items":["4 medium apples","1/4 cup oatmeal, quick cooking","1/4 cup flour","1/2 cup brown sugar","1 tablespoon cinnamon","1/4 cup margarine"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F.","Grease the bottom and sides of a square 9 x 9\" pan.","Remove the cores from the apples. Slice the apples. Spread the sliced apples on the bottom of the pan.","Cut the margarine into small pieces and put in a medium-sized bowl.","Add the oatmeal, flour, brown sugar and cinnamon.","Using two knives, cut the margarine into the mixture until it looks like small crumbs.","Sprinkle the mixture over the top of the apples.","Bake in the oven for about 20 minutes."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (103g)","calories":"158.85 kcal","carbohydrateContent":"29.21 g","cholesterolContent":"0.07 mg","fiberContent":"2.98 g","proteinContent":"0.97 g","sodiumContent":"50.04 mg","sugarContent":"20.95 g","fatContent":"4.55 g","saturatedFatContent":"0.91 g"},"notes":"For different tastes, try other fruits like cherries, pears, peaches, or plums.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"apple-fennel-chicken-salad-couscous","source_url":"https://www.myplate.gov/recipes/apple-fennel-chicken-salad-couscous","name":"Apple, Fennel & Chicken Salad with Couscous","description":"A refreshing, crunchy, sweet-savory salad featuring a play of fresh chopped apples, fennel and chicken breast blended with whole wheat couscous and spinach, ...","ingredients":[{"name":null,"items":["12 ounces boneless chicken breast (2-3 breasts)","3 tablespoons olive oil (divided)","1 cup whole wheat couscous","2 medium red apples","1 tablespoon lemon juice (divided)","1 fennel bulb","1 tablespoon balsamic vinegar","1 tablespoon sugar","1/4 teaspoon salt","1/8 teaspoon ground black pepper","3 1/2 cups fresh baby spinach","1/8 cup walnuts (chopped, may use pecans or almonds)"]}],"directions":[{"name":null,"steps":["Slice chicken breasts crosswise into 1/2 inch strips.","Heat 1 tablespoon olive oil in large skillet over medium heat.","Add chicken, cook 8-10 minutes until done, stirring occasionally, remove from heat.","While chicken is sautéing, cook couscous according to package directions, let cool.","Core and chop apples, place in large bowl; toss with 1 tablespoon lemon juice.","Chop fennel bulb (discarding stem and fronds) and add to bowl.","In a small bowl, whisk remaining oil and lemon juice with balsamic vinegar, sugar, salt, and pepper.","Add chicken, couscous, spinach, and nuts to bowl with apples and fennel.","Drizzle with dressing, toss to coat, and serve.","Can be made several hours ahead and refrigerated."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"434.78 kcal","carbohydrateContent":"49.16 g","cholesterolContent":"56.30 mg","fiberContent":"6.13 g","proteinContent":"23.67 g","sodiumContent":"237.00 mg","sugarContent":"17.91 g","fatContent":"15.66 g","saturatedFatContent":"2.43 g"},"notes":"Weekly Menu Planning Tip : When you are planning a dinner with chicken, cook up extra chicken breast and refrigerate for later use with another recipe.\nServe with 8 ounce non-fat milk.","contributor":"Produce for Better Health Foundation"},
{"slug":"apple-oatmeal-muffins","source_url":"https://www.myplate.gov/recipes/apple-oatmeal-muffins","name":"Apple Oatmeal Muffins","description":"Buy apples while they are in season and on sale and make batches of these muffins to put in the freezer for later. You can also substitute whole wheat flour ...","ingredients":[{"name":null,"items":["1/2 cup milk, non-fat","1/3 cup applesauce, unsweetened","1/2 cup all-purpose flour","1/2 cup quick-cooking oats, uncooked","1 cup sugar","1/2 tablespoon baking powder","1/2 teaspoon ground cinnamon","1 tart apple, cored & chopped"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Place 6 cupcake holders in baking tin.","In a mixing bowl, add milk and applesauce. Stir until blended.","Stir in flour, oats, sugar, baking powder, and cinnamon. Mix until moistened (do not over mix).","Gently stir in the chopped apples.","Spoon into cupcake holders.","Bake for 15-20 minutes or until an inserted toothpick comes out clean.","Cool in pan 5 minutes before serving. Store unused portions in an airtight container."]}],"yield":"6 Muffins","nutrition":{"@type":"NutritionInformation","servingSize":"1 muffin","calories":"230.90 kcal","carbohydrateContent":"53.61 g","cholesterolContent":"0.61 mg","fiberContent":"1.92 g","proteinContent":"2.74 g","sodiumContent":"131.47 mg","sugarContent":"39.69 g","fatContent":"0.73 g","saturatedFatContent":"0.11 g"},"notes":"Optional toppings: raisins, walnuts.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education - ONIE Project"},
{"slug":"apple-pistachio-crisp","source_url":"https://www.myplate.gov/recipes/apple-pistachio-crisp","name":"Apple Pistachio Crisp","description":"Fruit-based desserts can contribute to making half your plate fruits and veggies. True to their name, Honeycrisp apples are sweet and crunchy, perfectly deli...","ingredients":[{"name":null,"items":["3 apples (such as Honeycrisp, cored and cut into 1” chunks and unpeeled)","1/2 cup raisins","1/2 lemon (juiced)","1/2 cup old fashion oats","1/4 cup whole wheat flour","1 teaspoon cinnamon","3 tablespoons brown sugar","1/4 cup pistachios (unsalted, chopped)","2 tablespoons margarine or butter (melted)"]}],"directions":[{"name":null,"steps":["Place rack in center of oven and preheat to 350 ºF.","Place sliced apples, raisins, and lemon juice in 8x8 inch pan or baking dish; toss.","In a bowl, mix remaining ingredients except melted margarine.","Add melted margarine and mix until texture is consistent. Sprinkle over apple-raisin mixture.","Bake uncovered 45-50 minutes or until apples are tender."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"327.12 kcal","carbohydrateContent":"60.03 g","cholesterolContent":"0.07 mg","fiberContent":"7.03 g","proteinContent":"4.92 g","sodiumContent":"55.62 mg","sugarContent":"38.63 g","fatContent":"9.11 g","saturatedFatContent":"1.53 g"},"notes":"Serving Suggestion: Serve with an 8 oz. glass of fat-free (skim) milk, 3 oz. boneless, skinless chicken breast, and ½ cup green beans.","contributor":"Produce for Better Health Foundation"},
{"slug":"apple-sage-wild-rice-stuffing","source_url":"https://www.myplate.gov/recipes/apple-sage-wild-rice-stuffing","name":"Apple-Sage Wild Rice Stuffing","description":"This tasty wild rice dish starts with sautéed celery and onions mixed with sweet apples and cranberries. This combination, topped with toasted pecans, sage ...","ingredients":[{"name":null,"items":["4 ounces chopped pecans (unsalted)","4 teaspoons canola oil (divided)","1 1/2 cups diced celery","1 1/2 cups diced onions","1 medium red apple, such as Jonathan or Gala (halved, cored, and diced, about 1 1/2 cup total)","2 cups hot cooked brown rice","1 cup hot cooked wild rice","1/2 cup dried cranberries","1 medium jalapeno pepper (seeded (if desired) and finely chopped OR 1/4 tsp dried pepper flakes)","1 1/2 tablespoons chopped fresh sage (or 1 1/2 tsp dried rubbed sage)","3/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Heat a large skillet over medium-high heat. Add the pecans and cook 2-3 minutes or until beginning to brown, stirring frequently. Set aside on separate plate.","Heat 1 teaspoon of the oil over medium heat. Cook the celery and onion 8 minutes or until beginning to lightly brown on edge, stirring occasionally.","Add the apples and cook 4 minutes or until tender crisp.","Stir in the pecans and the remaining ingredients and cook 3-4 minutes or until the rice mixture is heated, stirring occasionally."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"175.50 kcal","carbohydrateContent":"23.04 g","cholesterolContent":"0.00 mg","fiberContent":"3.06 g","proteinContent":"2.69 g","sodiumContent":"162.57 mg","sugarContent":"8.51 g","fatContent":"8.98 g","saturatedFatContent":"0.84 g"},"notes":"Chef''s Notes: Use any of your favorite nuts in place of pecans. Or, leave them out if someone is allergic.\nMaterials: You will need a large skillet, measuring cups, measuring spoons, mixing spoon, and a sharp knife.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"apple-salad-sweet-tangy-yogurt-dressing","source_url":"https://www.myplate.gov/recipes/apple-salad-sweet-tangy-yogurt-dressing","name":"Apple Salad with Sweet & Tangy Yogurt Dressing","description":"Crisp, light, and refreshing, this salad combines apples, celery, carrots, raisins, and a yogurt dressing.","ingredients":[{"name":null,"items":["1 cup diced apple","1 teaspoon lemon juice","1/2 cup diced celery","1/2 cup grated carrots","1/2 cup raisins","1/2 cup yogurt, low-fat vanilla"]}],"directions":[{"name":null,"steps":["Wash apples, celery, and carrots before dicing/grating.","Toss apples with lemon juice.","Add celery, carrots and raisins.","Fold yogurt into apple mixture.","Cover. Chill for at least 1 hour before serving.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/6 of recipe"],"calories":"73.17 kcal","carbohydrateContent":"16.98 g","cholesterolContent":"1.23 mg","fiberContent":"1.48 g","proteinContent":"1.68 g","sodiumContent":"32.26 mg","sugarContent":"13.85 g","fatContent":"0.42 g","saturatedFatContent":"0.22 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"apple-salad","source_url":"https://www.myplate.gov/recipes/apple-salad","name":"Apple Salad","description":"For this delectable and simple seasonal salad, combine diced apples and celery with raisins and nuts. Add dressing and enjoy!","ingredients":[{"name":null,"items":["2 tablespoons lite mayonnaise-type dressing (or light mayonnaise)","1/16 cup orange juice (1 tablespoon)","2 cups apple, diced","1 cup celery, diced","1/2 cup raisins","1/2 cup nuts"]}],"directions":[{"name":null,"steps":["Mix orange juice with salad dressing or mayonnaise.","Toss apples, celery, raisins and nuts with the dressing mixture."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/8 of recipe (73g)"],"calories":"114.91 kcal","carbohydrateContent":"15.41 g","cholesterolContent":"0.62 mg","fiberContent":"2.03 g","proteinContent":"2.25 g","sodiumContent":"74.67 mg","sugarContent":"11.20 g","fatContent":"5.73 g","saturatedFatContent":"0.83 g"},"notes":null,"contributor":"Fresh Ideas for Fit Families\nUniversity of Kentucky Cooperative Extension Service\nFood and Nutrition Calendar, 2004"},
{"slug":"apple-sandwiches","source_url":"https://www.myplate.gov/recipes/apple-sandwiches","name":"Apple Sandwiches","description":"Vary your apple “sandwich” using different nut butters and dried fruits.","ingredients":[{"name":null,"items":["1 medium apple","2 tablespoons peanut butter","1 tablespoon raisins"]}],"directions":[{"name":null,"steps":["Cut apple in half from the stem down and lay each half cut-side down on a cutting board. Slice each half into 6 half-round slices and cut out the core.","Spread 1/2 teaspoon peanut butter on one side of each apple slice.","Put 4 to 6 raisins on top of the peanut butter on one apple slice. Top with another apple slice, peanut-butter side down. Squeeze gently.","Continue with remaining apple slices."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"178.19 kcal","carbohydrateContent":"22.33 g","cholesterolContent":"0.00 mg","fiberContent":"3.09 g","proteinContent":"3.94 g","sodiumContent":"69.94 mg","sugarContent":"17.04 g","fatContent":"8.34 g","saturatedFatContent":"1.65 g"},"notes":"Sprinkle the peanut butter with grated carrot, chopped nuts, seeds or granola, either with or without the raisins.\nTry other nut or seed butters, such as almond, hazelnut, or sunflower seed butter.\nUse other dried fruit pieces, such as cherries or cranberries.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"apple-slice-pancakes","source_url":"https://www.myplate.gov/recipes/apple-slice-pancakes","name":"Apple Slice Pancakes","description":"Jazz up regular pancakes with apples and cinnamon.","ingredients":[{"name":null,"items":["1 granny smith apple","1 1/4 cups pancake mix (any type)","1/2 teaspoon cinnamon","1 large egg","2 teaspoons canola oil","1 cup milk, 1% low-fat"]}],"directions":[{"name":null,"steps":["Lightly coat a griddle or skillet with cooking spray and heat over medium heat.","Peel, core and thinly slice apple into rings.","In a large mixing bowl, combine ingredients for pancake batter. Stir until ingredients are evenly moist. (Small lumps are ok! Over-mixing makes pancakes tough.)","For each pancake, place apple ring on griddle and pour about 1/4 cup batter over apple ring, starting in the center and covering the apple.","Cook until bubbles appear. Turn and cook other side until lightly brown."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 pancakes","1/6 of recipe (108g)"],"calories":"151.38 kcal","carbohydrateContent":"25.50 g","cholesterolContent":"36.28 mg","fiberContent":"2.22 g","proteinContent":"4.82 g","sodiumContent":"294.50 mg","sugarContent":"7.43 g","fatContent":"3.23 g","saturatedFatContent":"0.67 g"},"notes":"To test the griddle to see if it is hot, sprinkle it with a few drops of water. When the drops sizzle and dance, you are ready to cook! The easiest way to pour the batter onto the hot griddle is to use a 1/4 cup measuring cup for each pancake. If the first pancake is too brown, lower the heat.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"apple-stuffed-squash","source_url":"https://www.myplate.gov/recipes/apple-stuffed-squash","name":"Apple-Stuffed Squash","description":"All you need is a microwave to cook this delicious and seasonal side dish.","ingredients":[{"name":null,"items":["4 acorn squashes, washed","1 tablespoon butter (or margarine)","2 apples, chopped","2 teaspoons brown sugar, packed","1/2 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Cut squash into halves and remove seeds. Place in a glass dish, cover with plastic wrap and microwave on high for 5 minutes.","Melt butter in a separate bowl in the microwave. Mix in apples, sugar, and cinnamon. Microwave for 1 1/2 minutes.","Spoon apple filling into each squash half. Cover and microwave on high for 3-5 minutes until squash and apples are tender.","Serve warm."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 squash with filling","1/8 of recipe"],"calories":"115.98 kcal","carbohydrateContent":"24.86 g","cholesterolContent":"3.82 mg","fiberContent":"6.28 g","proteinContent":"1.74 g","sodiumContent":"2.83 mg","sugarContent":"13.21 g","fatContent":"2.16 g","saturatedFatContent":"1.04 g"},"notes":null,"contributor":"University of Maryland Cooperative Extension\nSNAP-Ed Program"},
{"slug":"apple-tuna-sandwiches","source_url":"https://www.myplate.gov/recipes/apple-tuna-sandwiches","name":"Apple Tuna Sandwiches","description":"A twist on the traditional tuna salad sandwich, this version features a combination of sweet and tangy flavors.","ingredients":[{"name":null,"items":["1 can (6.5 ounces) tuna, packed in water, drained","1 apple","1/4 cup yogurt, low-fat vanilla","1 teaspoon mustard","1 teaspoon honey","6 slices whole wheat bread","3 lettuce leaves"]}],"directions":[{"name":null,"steps":["Wash and peel the apple. Chop it into small pieces.","Drain the water from the can of tuna.","Put the tuna, apple, yogurt, mustard, and honey in a medium bowl. Stir well.","Spread 1/2 cup of the tuna mix onto each 3 slices of bread.","Top each sandwich with a washed lettuce leaf and a slice of bread."]}],"yield":"3","nutrition":{"@type":"NutritionInformation","calories":"239.45"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"apple-wedges-pumpkin-almond-butter","source_url":"https://www.myplate.gov/recipes/apple-wedges-pumpkin-almond-butter","name":"Apple Wedges with Pumpkin Almond Butter","description":"Breakfast is a snap with this simple dip, which can be made ahead of time and refrigerated. Enjoy with Golden Delicious or Granny Smith apple slices.","ingredients":[{"name":"For the Dip","items":["1/2 cup pumpkin puree (canned or from scratch)","1/3 cup almond butter (or crunchy peanut butter)","2 tablespoons maple syrup","1/8 teaspoon cinnamon"]},{"name":"Apple Slices","items":["4 apples, sliced"]}],"directions":[{"name":null,"steps":["Mix together dip ingredients.","Serve with apple slices."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"288.30 kcal","carbohydrateContent":"42.82 g","cholesterolContent":"0.00 mg","fiberContent":"7.31 g","proteinContent":"5.12 g","sodiumContent":"50.68 mg","sugarContent":"32.58 g","fatContent":"12.11 g","saturatedFatContent":"1.49 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"applesauce-cookies","source_url":"https://www.myplate.gov/recipes/applesauce-cookies","name":"Applesauce Cookies","description":"This simple spice cookie is based on applesauce.","ingredients":[{"name":null,"items":["1 cup sugar","1/2 cup (1 stick) margarine (or butter or shortening)","1 egg","2 teaspoons baking soda","2 1/2 cups all-purpose flour","1/2 teaspoon salt","1 teaspoon cinnamon","1 1/2 cups applesauce, unsweetened","1 cup raisins","nuts (1 cup, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Prepare pan or cookie sheet (see below).","Cream together sugar, margarine, and egg.","In a separate bowl, combine baking soda, flour, salt, and cinnamon. Mix well.","Stir flour mixture into shortening mixture just until moist.","Add applesauce, raisins, and nuts (if using).","For Cookies: Drop dough by heaping teaspoon several inches apart on a greased baking sheet. Bake at 350 °F for 10 to 12 minutes.","For Cake: Bake at 350 °F in an 8x8 inch pan for 40 minutes."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"270.59 kcal","carbohydrateContent":"50.80 g","cholesterolContent":"17.22 mg","fiberContent":"1.76 g","proteinContent":"3.72 g","sodiumContent":"381.19 mg","sugarContent":"28.29 g","fatContent":"6.37 g","saturatedFatContent":"1.32 g"},"notes":"To check cake for doneness, pierce top of cake with a toothpick. Cake is done when toothpick comes out clean.","contributor":"Montana State University Extension Service\nMontana Extension Nutrition Education Program"},
{"slug":"applesauce-loaf-cake","source_url":"https://www.myplate.gov/recipes/applesauce-loaf-cake","name":"Applesauce Loaf Cake","description":"Cinnamon, nutmeg, and toasted walnuts make this loaf cake taste as great as it smells.","ingredients":[{"name":null,"items":["1/2 cup walnuts, chopped","1 1/2 cups applesauce, unsweetened","1 egg","1 cup sugar","2 tablespoons vegetable oil (or cooking oil of choice)","1 teaspoon vanilla extract","2 cups all-purpose flour","2 teaspoons baking soda","1/2 teaspoon ground cinnamon","1/2 teaspoon ground nutmeg","1 cup raisins"]}],"directions":[{"name":null,"steps":["Pre-heat the oven to 350 degrees F. Grease two 8x4x2 inch loaf pans.","Toast walnuts in an ungreased skillet pan. Stir while heating on medium-low heat for 5-7 minutes. They are done when they are brown and smell nutty. Set aside to cool.","Mix applesauce, egg, sugar, oil and vanilla in a large bowl.","Mix flour, baking soda, cinnamon, and nutmeg together in a smaller bowl.","Pour flour mixture into applesauce mixture.","Stir in raisins and cooled toasted nuts.","Pour half of the batter into each greased pan. Bake for 45-55 minutes.","Remove cakes from the oven. Cool for 10 minutes. Remove from pans to finish cooling. For best taste, let cakes cool a few hours before serving."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1\" slice","1/16 of recipe (72g)"],"calories":"192.61 kcal","carbohydrateContent":"35.58 g","cholesterolContent":"12.84 mg","fiberContent":"1.43 g","proteinContent":"2.95 g","sodiumContent":"164.97 mg","sugarContent":"21.34 g","fatContent":"4.77 g","saturatedFatContent":"0.62 g"},"notes":null,"contributor":"Food Wise Learn at Home Print Materials\nRutgers University Cooperative Extension"},
{"slug":"applesauce-pancakes","source_url":"https://www.myplate.gov/recipes/applesauce-pancakes","name":"Applesauce Pancakes","description":"Keep a batch of these pancakes in the freezer for those busy mornings when you need a quick breakfast. Just pop them in the microwave or toaster, and enjoy. ...","ingredients":[{"name":null,"items":["1 cup applesauce, unsweetened","1/4 cup dry milk powder, non-fat instant","1 cup water","2 eggs","1 tablespoon canola oil (or cooking oil of choice)","2 cups all-purpose flour","2 tablespoons sugar","1/2 teaspoon cinnamon","2 teaspoons baking powder"]}],"directions":[{"name":null,"steps":["Wash hands with soap and water and clean food preparation area.","In a medium mixing bowl, combine applesauce, dry milk powder, water, eggs, and oil.","Add flour, sugar, cinnamon, and baking powder.","Stir until mixture has only small lumps.","Place large skillet on medium-high heat.","Spray skillet with non-stick cooking spray.","Pour 1/2 cup batter onto skillet.","Turn pancake when bubbles form on top of batter.","Cook the other side for about 1 minute or until golden brown."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (150g)","calories":"241.96 kcal","carbohydrateContent":"42.79 g","cholesterolContent":"69.07 mg","fiberContent":"1.69 g","proteinContent":"7.47 g","sodiumContent":"202.51 mg","sugarContent":"9.62 g","fatContent":"4.48 g","saturatedFatContent":"0.77 g"},"notes":null,"contributor":"Tennessee State University Cooperative Extension Service"},
{"slug":"applesauce","source_url":"https://www.myplate.gov/recipes/applesauce","name":"Applesauce","description":"Homemade applesauce, an easy treat to make, is a wonderful side dish or dessert option.","ingredients":[{"name":null,"items":["7 apples","1/2 cup water","1/4 cup sugar"]}],"directions":[{"name":null,"steps":["Wash and then cut apples in quarters. Apples can be peeled, but fiber will be decreased.","Combine apples and water in saucepan. Heat to boiling. Turn heat to low as soon as the water is boiling.","Simmer over low heat for 15 to 20 minutes or until apples are tender. Stir occasionally to prevent sticking.","Stir in sugar and heat until sugar is dissolved."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe (121g)","calories":"105.45 kcal","carbohydrateContent":"25.70 g","cholesterolContent":"0.00 mg","fiberContent":"2.94 g","proteinContent":"0.24 g","sodiumContent":"0.53 mg","sugarContent":"21.93 g","fatContent":"0.23 g","saturatedFatContent":"0.04 g"},"notes":"Serving suggestion: Add 1 tablespoon cinnamon and stir before serving.\nAdditional sugar can be added to increase sweetness. Brown sugar can be used instead of white.","contributor":"Eating Right Is Basic\nMichigan State University Cooperative Extension Service\nNutrition Education Program"},
{"slug":"apricot-lemon-chicken","source_url":"https://www.myplate.gov/recipes/apricot-lemon-chicken","name":"Apricot & Lemon Chicken","description":"Why wait for dessert to enjoy your fruit? Make it a part of your meal in this main dish.","ingredients":[{"name":null,"items":["4 medium chicken breasts, boneless & skinless","1 teaspoon cumin","5 tablespoons apricot spread (about 1/3 cup)","1 fresh lemon, juiced","2 tablespoons water"]}],"directions":[{"name":null,"steps":["Rub cumin over chicken and place in skillet.","Cook on medium-high for 6 minutes on each side, or until cooked through. Remove from pan and keep warm.","Add apricot spread, lemon juice, and water to skillet. On medium heat, stir until smooth.","Spoon sauce over chicken and serve warm."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 chicken breast with sauce (1/4 of recipe)","calories":"222.42 kcal","carbohydrateContent":"18.32 g","cholesterolContent":"90.02 mg","fiberContent":"0.38 g","proteinContent":"27.99 g","sodiumContent":"53.68 mg","sugarContent":"12.44 g","fatContent":"3.42 g","saturatedFatContent":"0.72 g"},"notes":"May substitute approximately 3 Tablespoons of lemon juice for 1 fresh lemon, juiced. Could also substitute honey for apricot spread. · Honey should not be fed to children under 1 year of age.","contributor":"Oklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"argentinean-grilled-steak-salsa-criolla","source_url":"https://www.myplate.gov/recipes/argentinean-grilled-steak-salsa-criolla","name":"Argentinean Grilled Steak with Salsa Criolla","description":"Tonight, try a recipe from South America! Enjoy these Argentinean-style steaks with a homemade Criolla Sauce, packed with flavor.","ingredients":[{"name":"For the sauce","items":["1 large, ripe tomato (cored, seeded, and finely chopped, about 1/2 cup)","1/4 small red onion (finely chopped, about 1/4 cup)","2 tablespoons fresh parsley (finely chopped)","2 teaspoons extra virgin olive oil","2 teaspoons red wine vinegar","1/2 teaspoon minced garlic","1/4 teaspoon oregano leaf","1/8 teaspoon low-sodium adobo seasoning","1/8 teaspoon crushed red pepper"]},{"name":"For the steak","items":["1 pound skirt steak","1/8 teaspoon low-sodium adobo seasoning"]}],"directions":[{"name":"For the sauce","steps":["In a small bowl, mix together tomato, onions, parsley, olive oil, vinegar, garlic, oregano, low-sodium adobo seasoning and crushed red pepper.","Cover and refrigerate for at least 1 hour or up until 48 hours."]},{"name":"For the steak","steps":["Heat grill to medium-high heat. Sprinkle steak on both sides with low-sodium adobo seasoning. Place steak on hot, greased grill grates.","Cook, flipping once, until steak is well browned on both sides and cooked to 145 °F (about 6 minutes for medium-rare).","Let rest for 5 minutes. Thinly slice steak.","Divide steak evenly among serving plates. Top with reserved Salsa Criolla."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"230.84 kcal","carbohydrateContent":"2.47 g","cholesterolContent":"74.99 mg","fiberContent":"0.69 g","proteinContent":"26.05 g","sodiumContent":"98.75 mg","sugarContent":"1.40 g","fatContent":"12.79 g","saturatedFatContent":"4.36 g"},"notes":"Serving Suggestions: Pair with Arepas (cornmeal patties popular in Colombia and Venezuela) and a healthy Quinoa Salad for a South American Steak Supper.","contributor":"The Best of La Cocina GOYA: Healthy, Tasty, Affordable Latin Cooking/ Lo Mejor de la Cocina GOYA: Cocina Latina Saludable, Rica y Económica\nGOYA Foods"},
{"slug":"argentinian-chimichurri-sauce","source_url":"https://www.myplate.gov/recipes/argentinian-chimichurri-sauce","name":"Argentinian Chimichurri Sauce","description":"Add some South American flair to your meal with this flavorful sauce, which can be used on meat, fish, or vegetables as a marinade or poured over your finish...","ingredients":[{"name":null,"items":["1 cup flat-leaf parsley, lightly packed and chopped without the stalks","4 garlic cloves, minced","1/8 teaspoon salt","1/4 teaspoon peppercorn, freshly ground","1/2 teaspoon chili pepper flakes","1 tablespoon dried oregano","2 tablespoons green onion, minced","1/2 cup olive oil","3/4 cup vinegar","3 tablespoons fresh lemon juice","1/4 cup water"]}],"directions":[{"name":null,"steps":["Place all the ingredients in a blender or food processor and pulse until well chopped, but not pureed.","Spoon the sauce over grilled meats, poultry, seafood, or vegetables. This sauce can also be used as a marinade."]}],"yield":"12","nutrition":{"@type":"NutritionInformation","calories":"88.16"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"arroz-con-pollo-chicken-and-rice","source_url":"https://www.myplate.gov/recipes/arroz-con-pollo-chicken-and-rice","name":"Chicken and Rice","description":"This one skillet meal makes a quick, tasty, and healthy weeknight dinner.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of choice)","1 whole chicken, cut up, skin removed","1 medium green pepper, chopped","1 onion, chopped","3 garlic cloves, minced","2 tomatoes, chopped","2 1/4 cups chicken broth, low-sodium","1 bay leaf","salt (to taste, optional)","pepper (to taste, optional)","1 cup rice, uncooked","1 cup peas"]}],"directions":[{"name":null,"steps":["In a large skillet heat oil over medium-high heat and brown chicken on both sides.","Add green pepper, onion, and garlic and cook for about 5 minutes.","Add tomato, chicken broth, bay leaf. Add salt & pepper to taste.","Cover and cook for 20 minutes.","Add rice, stir well, cover and simmer for 20-30 minutes longer, or until all liquid has been absorbed and chicken is tender.","Add peas, cook until hot. Remove bay leaf before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (297g)","calories":"378.63 kcal","carbohydrateContent":"37.11 g","cholesterolContent":"72.23 mg","fiberContent":"2.53 g","proteinContent":"30.09 g","sodiumContent":"122.74 mg","sugarContent":"3.89 g","fatContent":"11.67 g","saturatedFatContent":"2.57 g"},"notes":null,"contributor":"Wellness Ways Resource Book: Taste of the World\nUniversity of Illinois Extension Service"},
{"slug":"asian-mango-chicken-wraps","source_url":"https://www.myplate.gov/recipes/asian-mango-chicken-wraps","name":"Asian Mango Chicken Wraps","description":"Sweet and juicy ripe mangos are the perfect balance for the savory ingredients in this Asian wrap. Dinner''s ready in 30 minutes, or make ahead for a tasty po...","ingredients":[{"name":null,"items":["2 ripe mangos (peeled, pitted, and diced)","1 1/2 cups chopped roasted chicken breast","2 green onions (sliced)","2 tablespoons fresh basil (chopped)","1/2 red bell pepper (chopped)","1 1/2 cups shredded Savoy or Napa cabbage","2 medium carrots (grated)","1/3 cup fat-free cream cheese","3 tablespoons natural creamy peanut butter","2 teaspoons reduced sodium soy sauce","4 whole-wheat tortillas (8\")"]}],"directions":[{"name":null,"steps":["Cut mangos, vegetables, and chicken. Place in a mixing bowl and toss until well mixed.","In a small mixing bowl, whisk together cream cheese, peanut butter, and soy sauce.","To assemble: lay out tortillas on a flat surface. On each tortilla, spread 1/4 of cream cheese mixture and top with mango, vegetable, and chicken mix. Roll up tightly, tucking in ends of tortilla. Secure with toothpicks.","To serve, cut each wrap in half.","If not serving immediately, refrigerate; keeps well overnight."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Asian Mango Chicken Wrap","calories":"411.04 kcal","carbohydrateContent":"47.07 g","cholesterolContent":"52.39 mg","fiberContent":"8.90 g","proteinContent":"27.76 g","sodiumContent":"618.35 mg","sugarContent":"21.15 g","fatContent":"13.10 g","saturatedFatContent":"4.05 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of non-fat milk.","contributor":"Produce For Better Health Foundation"},
{"slug":"asparagus-gremolata-sauce","source_url":"https://www.myplate.gov/recipes/asparagus-gremolata-sauce","name":"Asparagus with Gremolata Sauce","description":"Asparagus has folate, fiber, as well as vitamins A, C, E, and K. It also has antioxidants, so treat yourself to this dish knowing that you are feeding your b...","ingredients":[{"name":null,"items":["2 cups asparagus, washed and trimmed (about 8 ounces)","2 tablespoons unsalted butter","2 teaspoons lemon peel (grated)","1 large garlic clove (minced)","2 tablespoons lemon juice"]}],"directions":[{"name":null,"steps":["Cook asparagus in a large pot of boiling water until tender, about 4 minutes.","Drain: rinse with cold water to cool quickly, and drain again.","Pat dry; wrap in a paper towel and then plastic wrap and refrigerate.","Melt margarine in a heavy large skillet over medium-high heat.","Add lemon peel and garlic and stir for 30 seconds.","Add asparagus and toss to coat.","Sprinkle with lemon juice. Sauté until asparagus is heated through and coated with Gremolata sauce, about 3 minutes.","Transfer to platter. Sprinkle with parsley and serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"6 ounces (158g)","calories":"44.89 kcal","carbohydrateContent":"2.35 g","cholesterolContent":"10.17 mg","fiberContent":"1.07 g","proteinContent":"1.09 g","sodiumContent":"1.76 mg","sugarContent":"1.01 g","fatContent":"3.91 g","saturatedFatContent":"2.41 g"},"notes":null,"contributor":"Eat Smart New York!\nCornell University Cooperative Extension"},
{"slug":"asparagus-mandarin-orange-chicken-and-rice","source_url":"https://www.myplate.gov/recipes/asparagus-mandarin-orange-chicken-and-rice","name":"Asparagus, Mandarin Orange, Chicken, and Rice","description":"Fresh California asparagus, mandarin oranges, chicken, and brown rice make perfect compliments in this Asian-influenced salad.","ingredients":[{"name":"For the Vinaigrette","items":["2 tablespoons extra virgin olive oil","2 tablespoons rice vinegar","3 tablespoons mandarin orange juice (reserved from oranges)","1 tablespoon soy sauce, reduced sodium"]},{"name":"For the Salad","items":["3 1/3 cups fresh asparagus (trimmed)","2 - 11 oz cans mandarin oranges (drained, reserve juice)","12 ounces cooked chicken breast (cut into chunks)","3 cups cooked instant brown rice"]}],"directions":[{"name":null,"steps":["In a small bowl, whisk vinaigrette ingredients, set aside.","Cook rice according to package directions.","Place whole trimmed asparagus in a large skillet with 1 1/2 inches of water.","Bring to a boil, reduce heat and simmer, uncovered, for 2-5 minutes.","Rinse with cool water and cut into 1-inch pieces.","In a medium size bowl, toss all ingredients."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"460.96 kcal","carbohydrateContent":"57.18 g","cholesterolContent":"84.03 mg","fiberContent":"5.54 g","proteinContent":"33.38 g","sodiumContent":"201.08 mg","sugarContent":"17.12 g","fatContent":"11.24 g","saturatedFatContent":"2.03 g"},"notes":"Weekly Meal Planning Tip: When you''re planning a dinner with chicken, cook up extra chicken breast and refrigerate for later use in this salad.","contributor":"Produce for Better Health Foundation"},
{"slug":"au-gratin-potatoes","source_url":"https://www.myplate.gov/recipes/au-gratin-potatoes","name":"Au Gratin Potatoes","description":"One serving of this creamy potato side dish will provide you with half your daily value of vitamin C, almost a quarter of your daily value of fiber, and some...","ingredients":[{"name":null,"items":["6 medium russet potatoes, peeled and sliced into 1/4 inch slices","1 cup onion, chopped","1 1/2 cups cheddar cheese, low-fat, shredded","2 tablespoons margarine","4 tablespoons flour","1/2 teaspoon salt","1 dash black pepper","2 cups milk, non-fat"]}],"directions":[{"name":"Quickest Method","steps":["Prepare a large casserole baking pan (9\" x 13\") by coating lightly with oil or cooking oil spray.","Place a layer of potatoes in pan, using approximately 1/4 of potatoes.","Sprinkle layer with 1/4 cup chopped raw onion, 1/4 of the cheese, 1/2 tablespoon margarine, 1 tablespoon flour, 1/4 teaspoon salt, and sprinkling of black pepper.","Repeat layers, making a total of 4.","Meanwhile heat milk over low heat.","Pour warm milk over all ingredients in casserole dish.","Bake at 350 degrees F for one hour.","Refrigerate leftovers within two hours."]},{"name":"Creamiest Method","steps":["Wash hands with soap and water.","Prepare a large casserole baking pan (9\" x 13\") by coating lightly with oil or cooking oil spray.","Make a white sauce by melting margarine in a small pan. Stir in flour. Gradually add milk, stirring constantly.","Cook, stirring constantly, until slightly thickened. Remove from heat. Stir in cheese until melted and smooth.","Add salt and pepper.","Place a layer of potatoes and onion in a prepared casserole pan, using approximately 1/4 of the potatoes and 1/4 cup onion.","Spread with 1/2 cup of the sauce prepared in steps 2 and 3.","Repeat layers, making a total of 4.","Bake at 350 degrees F for one hour.","Refrigerate leftovers within two hours."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (334g)","calories":"249.50 kcal","carbohydrateContent":"35.76 g","cholesterolContent":"17.97 mg","fiberContent":"3.31 g","proteinContent":"11.77 g","sodiumContent":"343.46 mg","sugarContent":"5.53 g","fatContent":"6.69 g","saturatedFatContent":"3.18 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"autumn-vegetable-succotash","source_url":"https://www.myplate.gov/recipes/autumn-vegetable-succotash","name":"Autumn Vegetable Succotash","description":"This medley of vegetables mixes fresh and frozen vegetables for a side dish that takes a short time to prepare.","ingredients":[{"name":null,"items":["1/4 cup olive oil (or cooking oil of choice)","1 cup onion, diced","2 garlic cloves, finely chopped","2 cups red bell pepper, diced","2 cups zucchini, diced","2 cups yellow summer squash, diced","3 cups lima beans, frozen","3 cups corn kernels, frozen","2 teaspoons dried sage (or 2 tablespoons fresh, coarsely chopped)"]}],"directions":[{"name":null,"steps":["In a large deep skillet over medium-high heat, add oil.","Add onion; cook until translucent (2 minutes). Add garlic, bell peppers, zucchini, squash, lima beans, and corn.","Season as desired; cook, stirring, until vegetables are tender (10 minutes or longer).","Stir in sage and serve."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (226g)","calories":"212.54 kcal","carbohydrateContent":"31.50 g","cholesterolContent":"0.00 mg","fiberContent":"6.50 g","proteinContent":"6.90 g","sodiumContent":"52.21 mg","sugarContent":"6.72 g","fatContent":"7.93 g","saturatedFatContent":"1.28 g"},"notes":"Can use dry or fresh herbs. Add others as desired.","contributor":"More Matters Recipes\nUS Department of Health and Human Services\nCenters for Disease Control and Prevention (CDC)"},
{"slug":"avocado-and-corn-salsa","source_url":"https://www.myplate.gov/recipes/avocado-and-corn-salsa","name":"Avocado and Corn Salsa","description":"Avocado and corn are given a flavor boost by fresh cilantro and lime. Serve this salsa with our Baked Chicken for an easy weekday meal.","ingredients":[{"name":null,"items":["1 avocado, diced","3/4 cup frozen corn kernels, thawed","1/2 cup grape tomatoes, quartered","1 tablespoon fresh cilantro, chopped","2 teaspoons lime juice","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Toss avocado, corn, tomatoes, cilantro, lime juice, and salt in a medium bowl.","Chill one hour and then serve."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"72.27 kcal","carbohydrateContent":"8.23 g","cholesterolContent":"0.00 mg","fiberContent":"2.84 g","proteinContent":"1.39 g","sodiumContent":"121.30 mg","sugarContent":"1.47 g","fatContent":"4.63 g","saturatedFatContent":"0.67 g"},"notes":null,"contributor":"Bronson Wellness Center\nBronson Healthcare - Michigan"},
{"slug":"avocado-black-bean-taquitos","source_url":"https://www.myplate.gov/recipes/avocado-black-bean-taquitos","name":"Avocado Black Bean Taquitos","description":"A twist on the traditional favorite, this taquitos recipe is easy and satisfying. Golden brown and crispy in minutes in an air fryer, these taquitos are burs...","ingredients":[{"name":null,"items":["1 ripe, fresh avocado, halved, pitted, peeled, and mashed","1/2 cup canned black beans, rinsed (low sodium)","1/2 tablespoon cumin","1 teaspoon garlic powder","1/2 teaspoon salt","10 (6-inch) corn tortillas","1 cup rainbow cherry tomatoes, chopped","1/2 cup red or yellow bell peppers, seeded and diced","1 tablespoon fresh jalapeño, seeded and minced","1 tablespoon onion, minced","1 tablespoon fresh lime juice","2 tablespoons fresh cilantro leaves, chopped","1/2 cup plain non-fat Greek yogurt (4 oz)"]}],"directions":[{"name":null,"steps":["Using a fork, mash the avocado and black beans together in bowl. Stir in cumin, garlic powder and salt.","Spread approximately 2 Tbsp. of the mixture onto a corn tortilla, dividing equally between 10 tortillas. Roll tightly to form 10 taquitos.","Place taquitos into air fryer at 400°F degrees for 5 minutes. When timer goes off, flip and put back into air fryer for 5 more minutes. Depending on air fryer you may need to decrease time to 3 to 4 minutes per side.","While taquitos are cooking, combine cherry tomatoes, bell peppers, jalapeño, onion, cilantro, and lime juice in a small bowl to make fresh pico de gallo.","Once taquitos are golden brown and crispy, remove from air fryer and top with fresh pico de gallo and Greek yogurt."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 taquitos","calories":"181.12 kcal","carbohydrateContent":"27.22 g","cholesterolContent":"1.23 mg","fiberContent":"6.92 g","proteinContent":"7.37 g","sodiumContent":"300.41 mg","sugarContent":"3.24 g","fatContent":"5.94 g","saturatedFatContent":"0.88 g"},"notes":"For more information, visit: https://loveonetoday.com/","contributor":"Created by Fresh Avocados Love One Today, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"avocado-breakfast-bruschetta","source_url":"https://www.myplate.gov/recipes/avocado-breakfast-bruschetta","name":"Avocado Breakfast Bruschetta","description":"Start your day with a breakfast twist on classic bruschetta: avocados, tomato, hard-boiled egg, and ricotta with basil atop toasted rustic whole-grain bread....","ingredients":[{"name":null,"items":["1 ripe avocado","2 medium tomatoes","1 green onion","1/2 cup chopped fresh basil (plus 2 tablespoons for garnish)","4 eggs (hard-boiled)","12 slices whole-wheat baguette bread","1/4 cup ricotta cheese (reduced-fat)","cracked black pepper to taste"]}],"directions":[{"name":null,"steps":["Dice avocado, tomatoes, and green onions.","Peel and chop hard-boiled eggs.","Reserving 2 tbsp. basil for garnish, gently toss first five ingredients in a small bowl. Add pepper to taste.","Toast baguette slices and smear with ricotta cheese.","Top with avocado mix and garnish with chopped basil."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"396.55 kcal","carbohydrateContent":"54.48 g","cholesterolContent":"210.27 mg","fiberContent":"7.44 g","proteinContent":"17.37 g","sodiumContent":"445.57 mg","sugarContent":"2.14 g","fatContent":"12.93 g","saturatedFatContent":"3.18 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of fat-free (skim) milk.","contributor":"Produce for Better Health Foundation"},
{"slug":"avocado-melon-breakfast-smoothie","source_url":"https://www.myplate.gov/recipes/avocado-melon-breakfast-smoothie","name":"Avocado Melon Breakfast Smoothie","description":"A delightful concoction of green fruits and vegetables plus fat-free dairy. With convenience built in, this refreshing smoothie can be made a day ahead....","ingredients":[{"name":null,"items":["1 large, ripe avocado","1 cup honeydew melon chunks (about 1 slice)","lime, juiced (1 1/2 tsp lime juice)","1 cup milk (fat free)","1 cup fat-free yogurt (plain)","1/2 cup 100% apple juice or white grape juice","1 tablespoon honey"]}],"directions":[{"name":null,"steps":["Cut avocado in half, remove pit.","Scoop out flesh, place in blender.","Add remaining ingredients; blend well.","Serve cold. (Keeps well in refrigerator up to 24 hours. If made ahead, stir gently before pouring into glasses.)"]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"330.09 kcal","carbohydrateContent":"44.74 g","cholesterolContent":"8.55 mg","fiberContent":"5.80 g","proteinContent":"13.16 g","sodiumContent":"164.68 mg","sugarContent":"36.78 g","fatContent":"12.67 g","saturatedFatContent":"2.48 g"},"notes":"Serving Suggestions: Serve with one slice toasted whole-wheat bread.","contributor":"Produce for Better Health Foundation"},
{"slug":"avocado-pita-pockets","source_url":"https://www.myplate.gov/recipes/avocado-pita-pockets","name":"Avocado Pita Pockets","description":"Creative snack idea to help keep the midday munchies away. And it’s quick to prepare.","ingredients":[{"name":null,"items":["1 ripe, fresh avocado, halved, pitted, peeled and diced","2 whole grain pita bread pockets, cut in half","1/4 cup canned chickpeas, rinsed and drained","2 tablespoons crumbled Cotija or Feta cheese","salt and pepper, to taste"]}],"directions":[{"name":null,"steps":["Fill pita pocket half with avocado, chickpeas and cheese, dividing evenly. Heat in microwave for 15 to 20 seconds if desired. Season to taste with salt and pepper."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 pita pocket half","calories":"163.52 kcal","carbohydrateContent":"21.83 g","cholesterolContent":"4.17 mg","fiberContent":"5.07 g","proteinContent":"5.13 g","sodiumContent":"212.84 mg","sugarContent":"1.55 g","fatContent":"7.37 g","saturatedFatContent":"1.52 g"},"notes":"For more information, visit: https://loveonetoday.com/","contributor":"Created by Fresh Avocados Love One Today, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"avocado-potato-and-grilled-chicken-salad","source_url":"https://www.myplate.gov/recipes/avocado-potato-and-grilled-chicken-salad","name":"Avocado, Potato, and Grilled Chicken Salad","description":"Fresh avocado with red potatoes, chicken, and a lemon-yogurt dressing are a winning combination for this main-dish salad.","ingredients":[{"name":null,"items":["3 medium red potatoes","1 ripe avocado","1 teaspoon lemon juice","4 green onions (chopped)","1/2 medium red bell pepper (chopped)","8 ounces frozen pre-cooked grilled chicken strips (about 8 strips) (thawed, cut into bite-size pieces)","1 tablespoon olive oil","1 tablespoon cider vinegar","1/2 cup lemon non-fat yogurt","1 teaspoon ground black pepper"]}],"directions":[{"name":null,"steps":["In a medium sauce pan, boil potatoes about 20 minutes, until just tender; run under cold water to cool, and cut into chunks.","Peel avocado and cut into chunks; coat with lemon juice.","Whisk olive oil, vinegar, yogurt, and pepper in a small bowl.","Place all ingredients in large bowl. Gently toss."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"327.47 kcal","carbohydrateContent":"34.21 g","cholesterolContent":"56.63 mg","fiberContent":"5.70 g","proteinContent":"23.18 g","sodiumContent":"72.29 mg","sugarContent":"6.30 g","fatContent":"11.37 g","saturatedFatContent":"1.88 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of non-fat milk, 1 slice of whole-grain bread, and apple slices.","contributor":"Produce for Better Health Foundation"},
{"slug":"avocado-veggie-bake","source_url":"https://www.myplate.gov/recipes/avocado-veggie-bake","name":"Avocado Veggie Bake","description":"No chips missing here in this new take on a snack favorite. A great way to enjoy extra veggies!","ingredients":[{"name":null,"items":["2 tablespoons olive oil","1 tablespoon chili powder","1/2 teaspoon garlic powder","1 teaspoon ground cumin","1/4 teaspoon salt","1/2 medium head of cauliflower, cut into 1/2-inch thick slices, then cut into 2-inch pieces, 8 oz. total","1 medium zucchini, sliced into 1/2-inch thick rounds","1 cup reduced fat shredded Mexican or taco seasoned cheese","1 can low-sodium black beans, drained and rinsed (~15 oz)","1 cup canned corn kernels, drained","1 cup cherry tomatoes, halved lengthwise","1 ripe, fresh avocado, halved, pitted, peeled and diced","2 scallions, sliced on diagonal (about 1/2 cup)","1 jalapeño, seeded and sliced","2 tablespoons cilantro leaves"]}],"directions":[{"name":null,"steps":["Preheat oven to 425F.","Combine olive oil, chili powder, cumin, garlic powder and salt.","Brush half of oil mixture on bottom of a 15-inch x 10-inch baking sheet with shallow sides.","Arrange cauliflower and zucchini on baking sheet in single layer and brush with remaining oil mixture.","Roast 20 minutes or until fork tender. Top with black beans, corn and cheese and roast an additional 5 minutes or until heated through and cheese is melted.","Top with tomatoes, avocado, scallions, jalapeño and cilantro."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup","calories":"197.09 kcal","carbohydrateContent":"19.40 g","cholesterolContent":"10.74 mg","fiberContent":"7.24 g","proteinContent":"9.66 g","sodiumContent":"286.03 mg","sugarContent":"3.68 g","fatContent":"10.03 g","saturatedFatContent":"2.94 g"},"notes":"For more information, visit: https://loveonetoday.com","contributor":"Created by Fresh Avocados Love One Today, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"baked-apples-and-sweet-potatoes","source_url":"https://www.myplate.gov/recipes/baked-apples-and-sweet-potatoes","name":"Baked Apples and Sweet Potatoes","description":"Layer sweet potatoes and apples to make this sweet and satisfying hot side dish.","ingredients":[{"name":null,"items":["5 medium sweet potatoes","4 medium apples","1/2 cup brown sugar, packed","1/2 teaspoon salt","1/4 cup margarine","1 teaspoon nutmeg","1/4 cup hot water","2 tablespoons honey"]}],"directions":[{"name":null,"steps":["Boil 5 sweet potatoes in water until they are almost tender.","After the sweet potatoes cool, peel and slice them.","Peel the apples. Remove the cores, and slice the apples.","Preheat the oven to 400 °F.","Grease the casserole dish with butter or margarine.","Put a layer of sweet potatoes on the bottom of the dish.","Add a layer of apple slices.","Add some sugar, salt, and tiny pieces of margarine to the apple layer.","Repeat steps 6, 7, and 8 to make more layers of sweet potatoes, apples, and sugar/salt.","On the top layer of apples, sprinkle the rest of the brown sugar and margarine pieces.","Sprinkle the top layer with nutmeg.","Mix the hot water and honey together. Pour the mix over the top layer.","Bake for about 30 minutes until apples are tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"299.29 kcal","carbohydrateContent":"60.95 g","cholesterolContent":"0.09 mg","fiberContent":"5.69 g","proteinContent":"2.00 g","sodiumContent":"295.88 mg","sugarContent":"44.87 g","fatContent":"6.04 g","saturatedFatContent":"1.31 g"},"notes":"Honey should not be fed to children under 1 year of age.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"baked-bananas","source_url":"https://www.myplate.gov/recipes/baked-bananas","name":"Baked Bananas","description":"Bananas make the perfect dessert when you add brown sugar and raisins!","ingredients":[{"name":null,"items":["6 bananas, sliced lengthwise","3 tablespoons packed brown sugar","4 tablespoons margarine or butter, unsalted","1/2 cup raisins, or other dried chopped fruit","1/3 cup chopped pecans"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Lightly grease a 9x13 inch pan.","Arrange the split bananas in the pan.","Top evenly with brown sugar, small pieces of margarine, raisins, and pecans.","Bake for 30 minutes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"293.66 kcal","carbohydrateContent":"46.74 g","cholesterolContent":"8.21 mg","fiberContent":"3.25 g","proteinContent":"1.95 g","sodiumContent":"8.01 mg","sugarContent":"35.51 g","fatContent":"11.92 g","saturatedFatContent":"3.01 g"},"notes":"Try adding ½ teaspoon (or more) cinnamon or a dash of cayenne to the other toppings.\nWhen bananas are peeled or cut, the flesh starts to brown. Browned bananas might not look attractive but they are safe to eat. Reduce browning by peeling or cutting just before using.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"baked-beans","source_url":"https://www.myplate.gov/recipes/baked-beans","name":"Baked Beans","description":"Double or triple this easy recipe to feed a crowd. It’s perfect for a picnic or potluck.","ingredients":[{"name":null,"items":["1 1/2 cups navy, kidney, or lima beans (dry, sorted, and rinsed)","2 cups water","2 cups 100% apple juice","1 teaspoon salt","2 tablespoons molasses","1/2 cup ketchup","2 teaspoons vinegar","1 teaspoon dry mustard"]}],"directions":[{"name":null,"steps":["Combine apple juice and water. Bring to a boil.","Add beans and simmer for 2 1/2 hours until beans are tender.","Drain beans, reserve the liquid.","Put beans and other ingredients in greased baking dish.","Cover and bake at 250 °F for 3 to 4 hours.","Uncover the last hour of baking and add some reserved liquid if beans become dry."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 recipe (234g)","calories":"224.54 kcal","carbohydrateContent":"45.57 g","cholesterolContent":"0.00 mg","fiberContent":"8.42 g","proteinContent":"9.90 g","sodiumContent":"616.13 mg","sugarContent":"18.58 g","fatContent":"0.96 g","saturatedFatContent":"0.10 g"},"notes":null,"contributor":"The Bold and Beautiful Book of Bean Recipes\nWashington State WIC Program"},
{"slug":"baked-cauliflower-tots","source_url":"https://www.myplate.gov/recipes/baked-cauliflower-tots","name":"Baked Cauliflower Tots","description":"The cheesy flavor makes this riced cauliflower feel very indulgent.","ingredients":[{"name":null,"items":["2 cups grated or finely chopped cauliflower rice (about half a medium head)","1 egg","3 tablespoons flour","1/4 cup grated cheddar cheese","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Lightly grease a baking sheet.","In a medium bowl, combine all ingredients and mix well.","Press mixture together to make about 15 small balls or logs and put them on the baking sheet with space between each one.","Bake for 20 minutes or until cooked through. For extra crispy tots, broil for an extra 2 minutes. Watch closely to avoid burning."]}],"yield":"3 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"109.34 kcal","carbohydrateContent":"10.03 g","cholesterolContent":"77.92 mg","fiberContent":"1.71 g","proteinContent":"6.49 g","sodiumContent":"302.39 mg","sugarContent":"1.50 g","fatContent":"5.15 g","saturatedFatContent":"2.45 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"baked-chicken-nuggets","source_url":"https://www.myplate.gov/recipes/baked-chicken-nuggets","name":"Baked Chicken Nuggets","description":"Make chicken nuggets at home using cereal crumbs, spices, and herbs. You can cook them in the microwave or the oven.","ingredients":[{"name":null,"items":["1 1/2 pounds chicken thighs, boneless, skinless","1 cup ready-to-eat cereal, cornflakes","1 teaspoon paprika","1/2 teaspoon Italian herb seasoning","1/4 teaspoon garlic powder","1/4 teaspoon onion powder"]}],"directions":[{"name":null,"steps":["Remove skin and bone; cut thighs into bite-sized pieces.","Place cornflakes in plastic bag and crush by using a rolling pin.","Add remaining ingredients to crushed cornflakes. Close bag tightly and shake until blended.","Add a few chicken pieces at a time to crumb mixture. Shake to coat evenly."]},{"name":"Conventional Method","steps":["Preheat oven to 400 °F. Lightly grease a cooking sheet.","Place chicken pieces on cooking sheet so they are not touching.","Bake until golden brown, about 12 to 14 minutes."]},{"name":"Microwave Method","steps":["Lightly grease an 8x12 inch baking dish.","Place chicken pieces on baking dish so they are not touching. Cover with waxed paper and cook on high.","Rotate chicken every 2 to 3 minutes. Cook until tender, about 6 to 8 minutes."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"about 3 ounces","calories":"234.23 kcal","carbohydrateContent":"6.53 g","cholesterolContent":"151.34 mg","fiberContent":"0.50 g","proteinContent":"28.81 g","sodiumContent":"173.94 mg","sugarContent":"0.78 g","fatContent":"9.48 g","saturatedFatContent":"2.67 g"},"notes":"To remove bone from chicken thigh:\nPlace chicken on cutting board. Remove skin from thighs.\nTurn chicken thighs over.\nCut around bone and remove it.","contributor":"Recipes and Tips for Healthy, Thrifty Meals\nUSDA Center for Nutrition Policy and Promotion"},
{"slug":"baked-chicken-vegetables","source_url":"https://www.myplate.gov/recipes/baked-chicken-vegetables","name":"Baked Chicken with Vegetables","description":"Carrots, potatoes, and onions are roasted along with chicken for a complete oven-baked meal.","ingredients":[{"name":null,"items":["4 medium potatoes, sliced","6 medium carrots, sliced","1 large onion, quartered","1 whole chicken, raw, cut into pieces, skin removed","1/2 cup water","1 teaspoon thyme","1/4 teaspoon ground black pepper"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Place potatoes, carrots, and onions in a large roasting pan.","Put chicken pieces on top of the vegetables.","Mix water, thyme, and pepper. Pour over chicken and vegetables.","Spoon juices over chicken once or twice during cooking.","Bake at 400 °F for one hour or more until browned and tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (314g)","calories":"296.23 kcal","carbohydrateContent":"32.30 g","cholesterolContent":"72.23 mg","fiberContent":"4.68 g","proteinContent":"27.19 g","sodiumContent":"123.18 mg","sugarContent":"5.14 g","fatContent":"6.35 g","saturatedFatContent":"1.73 g"},"notes":null,"contributor":"Go With Chicken\nUniversity of Wisconsin Cooperative Extension Service\nEau Claire County"},
{"slug":"baked-chicken","source_url":"https://www.myplate.gov/recipes/baked-chicken","name":"Baked Chicken","description":"Take the mystery out of baking chicken. A little garlic powder and pepper are all the added flavorings you need.","ingredients":[{"name":null,"items":["1 pound chicken, boneless, skinless","1 teaspoon garlic powder","1 teaspoon ground black pepper","salt (optional)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F.","Put the chicken in a baking pan or casserole dish.","Sprinkle with garlic powder and pepper to taste.","Bake for 1 hour."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe (56g)","calories":"101.86 kcal","carbohydrateContent":"0.75 g","cholesterolContent":"60.05 mg","fiberContent":"0.17 g","proteinContent":"18.66 g","sodiumContent":"29.93 mg","sugarContent":"0.02 g","fatContent":"2.18 g","saturatedFatContent":"0.47 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"baked-eggs-cheese","source_url":"https://www.myplate.gov/recipes/baked-eggs-cheese","name":"Baked Eggs & Cheese","description":"Add your favorite veggies to dress up this cheese and egg dish, or serve with fresh salsa.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","6 eggs","1/2 cup fat-free milk","1/2 cup fat-free cheese, grated","1 teaspoon garlic powder","1 1/2 teaspoons oregano"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Put oil in a medium baking dish or small cake pan and heat in the oven for a few minutes.","In a medium bowl, beat eggs. Mix in remaining ingredients. Pour into hot pan.","Bake 20 minutes or until eggs are firm. Serve immediately."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"173.39 kcal","carbohydrateContent":"3.74 g","cholesterolContent":"311.71 mg","fiberContent":"0.61 g","proteinContent":"15.01 g","sodiumContent":"214.84 mg","sugarContent":"1.95 g","fatContent":"11.03 g","saturatedFatContent":"2.91 g"},"notes":"* 4 eggs and 4 egg whites may be used instead of 6 eggs to reduce fat and cholesterol.","contributor":"Adapted from Sure To Please Baked Eggs and Cheese, Healthy Snacks\nUniversity of Wisconsin Cooperative Extension Service"},
{"slug":"baked-fish-0","source_url":"https://www.myplate.gov/recipes/baked-fish-0","name":"Baked Fish","description":"Herbs and spices give this fish lots of flavor for an easy weekday meal.","ingredients":[{"name":null,"items":["1 pound cod fillets (fresh or frozen)","1/4 teaspoon paprika","1/4 teaspoon garlic powder","1/4 teaspoon onion powder","1/8 teaspoon ground black pepper","1/4 teaspoon dried oregano","1/4 teaspoon dried thyme","1 tablespoon lemon juice","1 1/2 tablespoons margarine (melted)"]}],"directions":[{"name":null,"steps":["Thaw frozen fish according to package directions, if using frozen fillets.","Preheat oven to 350 °F.","Separate fish into four fillets or pieces.","Place fish in ungreased 13x9 baking dish.","Combine paprika, garlic powder, onion powder, pepper, oregano, and thyme in a small bowl.","Sprinkle seasoning mixture and lemon juice evenly over fish.","Drizzle melted margarine evenly over fish.","Bake until fish flakes easily with a fork, about 20-25 minutes."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"96.85 kcal","carbohydrateContent":"0.83 g","cholesterolContent":"47.78 mg","fiberContent":"0.20 g","proteinContent":"16.09 g","sodiumContent":"140.69 mg","sugarContent":"0.13 g","fatContent":"3.38 g","saturatedFatContent":"0.68 g"},"notes":null,"contributor":"Bronson Wellness Center\nBronson Healthcare - Michigan"},
{"slug":"baked-fish-and-vegetables","source_url":"https://www.myplate.gov/recipes/baked-fish-and-vegetables","name":"Baked Fish and Vegetables","description":"Frozen fish is a good option when you need a quick meal. Wrap it up in some foil with vegetables and bake!","ingredients":[{"name":null,"items":["4 white fish fillets (frozen, or cod or perch 4 oz each)","2 cups frozen mixed vegetables (or other vegetables you have on hand)","1 small onion (diced)","1 teaspoon lemon juice (or fresh lemon, sliced thin)","1 tablespoon parsley flakes, dried (or fresh, chopped)","lemon zest (optional)","aluminum foil (10x12 inches square)"]}],"directions":[{"name":null,"steps":["Preheat oven to 450 °F.","Separate and place fish fillets in center of each tin foil square.","Combine vegetables and diced onion in bowl and mix. Spoon vegetables around fillets.","Sprinkle with lemon juice, top with lemon slices or add lemon zest.","Top with parsley or other herbs if desired.","Fold ends of tin foil together to form leak-proof seal.","Bake for 20 minutes. Serve.","Refrigerate leftovers."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["4 oz. fish and 1/2 C. vegetables","1/4 of recipe (306g)"],"calories":"142.19 kcal","carbohydrateContent":"15.50 g","cholesterolContent":"48.82 mg","fiberContent":"4.71 g","proteinContent":"19.44 g","sodiumContent":"142.41 mg","sugarContent":"4.44 g","fatContent":"0.40 g","saturatedFatContent":"0.09 g"},"notes":null,"contributor":"Simply Good Eating Recipe Cards, Vol. 1, 2000\nUniversity of Minnesota Cooperative Extension Service"},
{"slug":"baked-fish-creole-sauce","source_url":"https://www.myplate.gov/recipes/baked-fish-creole-sauce","name":"Baked Fish with Creole Sauce","description":"This tomato-based Creole sauce includes onion, green pepper, and spices to liven up the fish of your choice.","ingredients":[{"name":null,"items":["1 pound fish fillets (fresh or frozen, unbreaded)","1/2 medium onion, thinly sliced","1/2 medium green pepper, thinly sliced","1 can (8 ounces) tomato sauce, low-sodium","1 teaspoon chili powder","1/8 teaspoon ground black pepper","salt (1/4 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Thaw fish in refrigerator overnight.","Preheat oven to 375 °F.","Arrange fish in a single layer in baking dish.","Top fish with onion and pepper slices.","In a separate bowl, mix tomato sauce, chili powder, salt, and pepper.","Pour tomato sauce mixture over fish and vegetables.","Cover dish and bake until fish flakes easily with a fork (20-30 minutes).","Refrigerate leftovers."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"92.87 kcal","carbohydrateContent":"6.09 g","cholesterolContent":"47.73 mg","fiberContent":"1.59 g","proteinContent":"17.09 g","sodiumContent":"131.50 mg","sugarContent":"3.31 g","fatContent":"0.51 g","saturatedFatContent":"0.09 g"},"notes":"Atlantic cod fillets used for nutrition analysis.\nIf fish is more than one layer thick in baking dish, cooking time will be longer.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"baked-fish-tomatoes-peppers-onions","source_url":"https://www.myplate.gov/recipes/baked-fish-tomatoes-peppers-onions","name":"Baked Fish with Tomatoes, Peppers, and Onions","description":"Make dinner in a flash. This fast and easy fish is delicious and perfect for a busy evening. A fresh green salad and a whole grain roll or brown rice would m...","ingredients":[{"name":null,"items":["1 pound cod fillets, fresh or frozen, skinless and thawed (or other white fleshed fish)","1/4 cup green bell pepper, chopped","1/2 can (14.5 ounces) low-sodium tomatoes (about 8 ounces)","1/4 cup onion, chopped","1/4 teaspoon oregano"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Oil or spray a 9 x 13-inch baking dish with vegetable spray.","Cut fish into four pieces and place in baking dish.","Top fish with green peppers, tomatoes, onions and oregano. Bake about 20 minutes or until fish flakes."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 fish piece","1/4 of recipe"],"calories":"80.78 kcal","carbohydrateContent":"3.40 g","cholesterolContent":"47.73 mg","fiberContent":"1.30 g","proteinContent":"16.59 g","sodiumContent":"110.61 mg","sugarContent":"2.03 g","fatContent":"0.36 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"Adapted from Spicy Baked Fish\nMontana State University Extension Service\nNutrition Education Program"},
{"slug":"baked-fish","source_url":"https://www.myplate.gov/recipes/baked-fish","name":"Baked Fish","description":"This dish can be served with vegetables and rice, pastas, or potatoes.","ingredients":[{"name":null,"items":["nonstick cooking spray","1 pound fish fillets (whitefish, trout, or tilapia)","1 onion, sliced","1/4 teaspoon salt","1/4 teaspoon black pepper","2 teaspoons vegetable oil","1/4 teaspoon lemon pepper seasoning (optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Place about a 12-inch piece of foil on the counter. Coat the foil with nonstick cooking spray.","Place the fillets in the middle of the foil. If the fillets have skin, place the skin side down.","Spread the onions, salt, pepper, and oil on top of the fillets. If using lemon pepper seasoning, add that too.","Fold the foil over the fish to wrap it. Place foil pouch on a baking sheet, and place it in the oven.","Bake the fish for 15 to 20 minutes until the fish is flaky when tested with a fork.","Divide into four portions and serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"138.39 kcal","carbohydrateContent":"3.58 g","cholesterolContent":"45.25 mg","fiberContent":"0.67 g","proteinContent":"21.18 g","sodiumContent":"193.59 mg","sugarContent":"1.57 g","fatContent":"4.54 g","saturatedFatContent":"1.09 g"},"notes":"Tip for cooking fish: The recommended safe minimum internal temperature for fish is 145 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nAdapted from a recipe by Veronica “Babe” Newago, Red Cliff Ojibwe"},
{"slug":"baked-lemon-chicken","source_url":"https://www.myplate.gov/recipes/baked-lemon-chicken","name":"Baked Lemon Chicken","description":"Lemon, onions, and thyme decorate this oven-baked chicken.","ingredients":[{"name":null,"items":["3 1/2 pounds whole chicken, skinned and cut into 10 pieces","1/4 teaspoon salt","1/4 teaspoon ground black pepper","1 1/2 cloves of garlic, thinly sliced (or 1 tsp garlic powder)","4 teaspoons fresh thyme (or 1 tsp dried thyme)","3 cups medium onion, thinly sliced","1 1/2 cups chicken broth, low-sodium (or water)","1/4 cup lemon juice","1 lemon (sliced into 10 slices, seeds removed)"]}],"directions":[{"name":null,"steps":["Combine salt, pepper, garlic, and thyme.","Lay chicken pieces into a 11x13 inch baking pan. Sprinkle seasonings over chicken.","Combine onions, stock, and lemon juice in a sauce pan. Heat to a boil.","Pour hot lemon mixture around chicken. Top each chicken piece with a lemon slice.","Bake for 30 minutes at 400 °F until golden brown and juices are clear colored."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe (521g)","calories":"376.99 kcal","carbohydrateContent":"12.26 g","cholesterolContent":"149.37 mg","fiberContent":"2.23 g","proteinContent":"51.36 g","sodiumContent":"291.39 mg","sugarContent":"4.69 g","fatContent":"13.03 g","saturatedFatContent":"3.61 g"},"notes":null,"contributor":"Food Family Fun\nUSDA Food and Nutrition Service\nTeam Nutrition"},
{"slug":"baked-lentils-casserole","source_url":"https://www.myplate.gov/recipes/baked-lentils-casserole","name":"Baked Lentils Casserole","description":"Baked lentils, vegetables, and cheese make a complete vegetarian dinner in one dish.","ingredients":[{"name":null,"items":["1 cup lentils, rinsed","3/4 cup water","1/2 teaspoon salt","ground black pepper (1/4 teaspoon, optional)","garlic powder (1/4 teaspoon, optional)","1/2 cup medium onion, chopped","1 can (14.5 ounces) tomatoes, low-sodium","2 medium carrots, thinly sliced","1/2 cup cheddar cheese, shredded"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Combine lentils, water, seasonings, onion, and tomatoes.","Place in 2 quart casserole dish.","Cover tightly with lid or foil.","Bake at 350 °F for 30 minutes.","Remove from oven and add carrots. Stir.","Cover and bake 30 minutes longer.","Remove cover and sprinkle cheese on top.","Bake, uncovered 5 minutes, until cheese melts."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe (216g)","calories":"203.70 kcal","carbohydrateContent":"29.16 g","cholesterolContent":"11.30 mg","fiberContent":"11.30 g","proteinContent":"13.69 g","sodiumContent":"338.55 mg","sugarContent":"5.90 g","fatContent":"4.54 g","saturatedFatContent":"2.26 g"},"notes":null,"contributor":"Let’s Make Meatless Meals\nUniversity of Wisconsin Cooperative Extension Service"},
{"slug":"baked-meatballs","source_url":"https://www.myplate.gov/recipes/baked-meatballs","name":"Baked Meatballs","description":"Make your own meatballs to use now or freeze them for a quick dinner at another time.","ingredients":[{"name":null,"items":["1 pound ground beef, 90% lean (or ground turkey)","1 egg","1/2 teaspoon dried parsley","1/2 cup bread crumbs","1/2 cup milk, 1% (or non-fat)","1/4 teaspoon ground black pepper","1 teaspoon onion powder"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 °F.","Mix all ingredients, shape into balls (about 24 meatballs).","Arrange on baking sheets that have been sprayed with non-stick cooking spray.","Bake at 425 °F for 12-15 minutes. It is best to use a food safety thermometer to check for doneness. It should read 160 °F for ground beef and 165 °F for ground turkey.","If meatballs are being saved for future use, chill rapidly; package in amounts needed per meal and freeze immediately."]}],"yield":"8 servings (3 meatballs)","nutrition":{"@type":"NutritionInformation","servingSize":["1/8 of recipe","(3 meatballs)"],"calories":"123.26 kcal","carbohydrateContent":"6.01 g","cholesterolContent":"59.31 mg","fiberContent":"0.38 g","proteinContent":"12.10 g","sodiumContent":"93.14 mg","sugarContent":"1.21 g","fatContent":"5.31 g","saturatedFatContent":"2.01 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"baked-parmesan-fish","source_url":"https://www.myplate.gov/recipes/baked-parmesan-fish","name":"Baked Parmesan Fish","description":"This parmesan-crusted fish is topped with mushrooms, onions, green onions, and garlic. It''s the perfect heart-healthy meal to cook for a loved one.","ingredients":[{"name":null,"items":["1/3 cup grated parmesan cheese, non-fat","1/3 tablespoon all-purpose flour (1 teaspoon)","1 teaspoon thyme sprigs, leaves removed and crushed","4 (6 ounces each) tilapia fish fillets (or other white fish)","1 medium onion, chopped","1 cup halved mushroom caps","1/2 cup green onions (scallions), finely sliced","1 clove garlic, crushed"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Place cheese, flour, and thyme in paper bag.","Individually coat fish by gently shaking in bag; discard coating ingredients.","Place fillets in baking pan on rack. Bake for 20 minutes or until fish flakes easily when tested with fork.","Heat skillet over medium-high heat. Add onion, mushrooms, green onions, and garlic. Cook, stirring frequently, until onions are tender. Season with ground black pepper.","Serve baked fish topped with mushroom mixture."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 fish fillet with toppings (1/4 of recipe)","calories":"168.02 kcal","carbohydrateContent":"9.76 g","cholesterolContent":"48.26 mg","fiberContent":"1.18 g","proteinContent":"26.42 g","sodiumContent":"163.94 mg","sugarContent":"2.33 g","fatContent":"2.78 g","saturatedFatContent":"1.10 g"},"notes":"Talapia fillets used in cost & nutrition analysis.\nSuggest serving over pasta or rice.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"baked-pork-chops","source_url":"https://www.myplate.gov/recipes/baked-pork-chops","name":"Baked Pork Chops","description":"Green and red peppers top these festive pork chops.","ingredients":[{"name":null,"items":["6 pork chops, lean center-cut, 1/2-inch thick","1 medium onion, thinly sliced","1/2 cup medium green pepper, chopped","1/2 cup medium red pepper, chopped","1/8 teaspoon black pepper","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Trim fat from pork chops. Place chops in a 13x9 inch baking pan.","Spread onion and peppers on top of chops. Sprinkle with pepper and salt. Refrigerate for 1 hour.","Preheat oven to 375 °F.","Cover pan and cook 30 minutes.","Uncover, turn chops and re-cover with onions and peppers, and continue cooking for an additional 15 minutes or until internal temperature reaches 145 °F.","Garnish with fresh parsley."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 pork chop","1/6 of recipe (196g)"],"calories":"268.15 kcal","carbohydrateContent":"3.95 g","cholesterolContent":"104.39 mg","fiberContent":"0.72 g","proteinContent":"41.66 g","sodiumContent":"283.92 mg","sugarContent":"1.96 g","fatContent":"8.81 g","saturatedFatContent":"3.00 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"baked-potatoes-primavera","source_url":"https://www.myplate.gov/recipes/baked-potatoes-primavera","name":"Baked Potatoes Primavera","description":"A simple primavera sauce mixed with frozen vegetables takes baked potatoes to a new level.","ingredients":[{"name":null,"items":["4 medium potatoes","4 cups mixed vegetables (frozen)","1 cup sour cream, non-fat","1/2 teaspoon dried oregano","1/2 teaspoon dried basil","black pepper (to taste)"]}],"directions":[{"name":null,"steps":["Pierce each potato several times with a fork. Microwave on high until tender, about 3-4 minutes per potato.","Steam mixed vegetables until hot.","Mix the sour cream with the herbs and pepper.","Split the potatoes in the center and fill with steamed veggies. Top with sour cream and serve hot."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 potato with 1/4 of topping","1/4 of recipe (475g)"],"calories":"323.94 kcal","carbohydrateContent":"69.47 g","cholesterolContent":"5.40 mg","fiberContent":"11.92 g","proteinContent":"11.38 g","sodiumContent":"166.23 mg","sugarContent":"7.91 g","fatContent":"0.51 g","saturatedFatContent":"0.11 g"},"notes":null,"contributor":"Food and Health Communications, Inc."},
{"slug":"baked-rice-spinach","source_url":"https://www.myplate.gov/recipes/baked-rice-spinach","name":"Baked Rice with Spinach","description":"The vegetarian dish combines leafy greens and high fiber brown rice to make a wholesome side dish or a satisfying main dish.","ingredients":[{"name":null,"items":["sprays of nonstick vegetable spray","1 package (10 ounce) frozen spinach, thawed","1 cup brown rice, cooked","2 tablespoons olive oil (or cooking oil of choice)","1 cup egg-white substitute, liquid","3/4 cup mozzarella cheese, shredded fat-free","1 cup fat-free milk","1/2 medium onion, chopped","1/2 teaspoon Worcestershire sauce","1/4 teaspoon dried marjoram","1/4 teaspoon dried thyme","1/4 teaspoon dried rosemary"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Spray a 2-quart baking dish with vegetable oil spray.","Place thawed spinach in a colander and press to remove excess water.","Place the spinach in a large mixing bowl and add remaining ingredients. Mix until combined.","Transfer the mixture to the baking dish and place in the preheated oven. Bake for 30 minutes.","Cut the casserole into eight squares and serve."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 Cup","calories":"118.97 kcal","carbohydrateContent":"11.52 g","cholesterolContent":"2.82 mg","fiberContent":"2.10 g","proteinContent":"9.88 g","sodiumContent":"182.12 mg","sugarContent":"2.58 g","fatContent":"4.09 g","saturatedFatContent":"0.69 g"},"notes":"Source \"Brazilian Rice\"\nThis casserole can be prepared 1 day in advance and refrigerated.","contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"baked-salmon-herbs-lemon","source_url":"https://www.myplate.gov/recipes/baked-salmon-herbs-lemon","name":"Baked Salmon with Herbs and Lemon","description":"Roast your favorite seasonal veggies while baking this fish for a wonderful dinner any time of the year.","ingredients":[{"name":null,"items":["16 ounces salmon, fresh or frozen (or any white fish)","1/4 teaspoon paprika","1/4 teaspoon onion powder","1/4 teaspoon garlic powder","1/8 teaspoon black pepper","1/8 teaspoon dried oregano","1/8 teaspoon dried thyme","1 tablespoon lemon juice","1 1/2 tablespoons margarine, melted"]}],"directions":[{"name":null,"steps":["If using frozen fish, thaw in refrigerator according to package directions.","Preheat oven to 350 degrees F.","Separate (or cut) fish into 4 pieces. Place fish in a 13x9x2-inch baking pan.","Combine paprika, garlic and onion powders, pepper, oregano, and thyme in a small bowl.","Sprinkle herb mixture and lemon juice evenly over the fish. Then drizzle melted margarine on top.","Bake until fish flakes easily with a fork, about 20 to 25 minutes."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"4 oz. prepared fish or 1/4 of recipe","calories":"229.42 kcal","carbohydrateContent":"0.77 g","cholesterolContent":"60.78 mg","fiberContent":"0.16 g","proteinContent":"21.41 g","sodiumContent":"94.60 mg","sugarContent":"0.13 g","fatContent":"15.08 g","saturatedFatContent":"2.96 g"},"notes":null,"contributor":"Adapted from Spicy Baked Fish\nPumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"baked-squash-apple-spices","source_url":"https://www.myplate.gov/recipes/baked-squash-apple-spices","name":"Baked Squash with Apples and Spices","description":"What a delicious autumn side dish! Use your favorite varieties of apples and winter squash for this tasty recipe.","ingredients":[{"name":null,"items":["2 1/2 cups winter squash (acorn, butternut, or Hubbard)","1 1/2 cups apples (Macintosh, Granny Smith, or Rome)","1/2 teaspoon nutmeg","1 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Wash and prepare squash and apples (for extra fiber, keep peel on apples).","Cut squash and apples into slices.","Alternate layers of squash and apples in 8x8-inch pan; end with apples.","Sprinkle spices over top layer.","Cover with aluminum foil.","Bake in preheated oven for 45 to 60 minutes, until squash is tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"39.50 kcal","carbohydrateContent":"9.45 g","cholesterolContent":"0.00 mg","fiberContent":"2.32 g","proteinContent":"0.52 g","sodiumContent":"0.69 mg","sugarContent":"5.43 g","fatContent":"0.29 g","saturatedFatContent":"0.09 g"},"notes":null,"contributor":"Adapted from Baked Squash with Apples and Spices\nPumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"baked-tofu","source_url":"https://www.myplate.gov/recipes/baked-tofu","name":"Baked Tofu","description":"Ginger, soy sauce, and garlic fill this tofu with flavor. This dish is protein-packed and friendly to a vegetable-based diet.","ingredients":[{"name":null,"items":["2 tablespoons soy sauce, reduced-sodium","1 clove garlic, minced (or 1/4 teaspoon garlic powder)","1 teaspoon fresh ginger, minced","1 teaspoon vegetable oil (or cooking oil of choice)","1 package (14 ounces) firm or extra firm tofu, water packed"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Line a rimmed baking sheet with foil.","Drain water from tofu. Wrap tofu in paper towels. Let set for about 5 minutes.","While tofu is draining, combine soy sauce, garlic, ginger, and vegetable oil in a small bowl.","Slice tofu into 1/2 inch thick slices. Place tofu slices on foil lined baking sheet.","Pour soy sauce mixture over tofu. Using a spatula or pancake turner, gently turn slices over to coat both sides with sauce.","Bake tofu for 15 minutes. Turn slices over and bake for another 15 minutes. Tofu should be light golden brown and firm.","Serve hot in place of meat or cut into slices or cubes and add to a stir-fry, fried rice, soup, or salad."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 slices","1/4 of recipe (124g)"],"calories":"98.89 kcal","carbohydrateContent":"1.92 g","cholesterolContent":"0.00 mg","fiberContent":"1.08 g","proteinContent":"10.69 g","sodiumContent":"292.16 mg","sugarContent":"0.76 g","fatContent":"6.42 g","saturatedFatContent":"1.08 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"baked-tortilla-chips","source_url":"https://www.myplate.gov/recipes/baked-tortilla-chips","name":"Baked Tortilla Chips","description":"Use this recipe to make your own whole wheat flour or corn flour tortilla chips.","ingredients":[{"name":null,"items":["3 whole wheat flour tortillas, 10\" across","3 sprays of cooking oil spray","salt (dash, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven or toaster oven to 400 °F.","Lightly grease a baking sheet with the cooking spray.","Cut tortillas into 8 sections (as if you were cutting a pizza) and place on baking sheet.","Spray tops of tortilla sections with cooking spray and lightly salt, if desired.","Bake for 10 minutes, until crisp and light brown, watching closely so the chips don''t burn."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["4 chips","1/6 of recipe"],"calories":"111.24 kcal","carbohydrateContent":"16.33 g","cholesterolContent":"0.00 mg","fiberContent":"3.48 g","proteinContent":"3.47 g","sodiumContent":"219.12 mg","sugarContent":"0.87 g","fatContent":"3.58 g","saturatedFatContent":"1.74 g"},"notes":"Corn tortillas may also be used for less calories and fat.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"baked-trout","source_url":"https://www.myplate.gov/recipes/baked-trout","name":"Baked Trout","description":"Tangy lime, sweet tomatoes, and savory onions make this trout colorful and tasty.","ingredients":[{"name":null,"items":["2 pounds trout fillets, cut into six pieces (or other fish)","3 tablespoons lime juice (about 2-3 limes)","1 medium tomato (chopped)","1/2 medium onion (chopped)","3 tablespoons cilantro (chopped)","1/2 teaspoon olive oil (or cooking oil of choice)","1/4 teaspoon black pepper","1/4 teaspoon salt","1/2 cup fresh red pepper (chopped)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Pat fish dry and place in baking dish.","In a separate dish, mix remaining ingredients together and pour over fish.","Bake for 15 to 20 minutes or until fork-tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 piece fish","1/6 of recipe (204g)"],"calories":"191.74 kcal","carbohydrateContent":"2.60 g","cholesterolContent":"74.09 mg","fiberContent":"0.40 g","proteinContent":"25.55 g","sodiumContent":"165.79 mg","sugarContent":"1.10 g","fatContent":"8.24 g","saturatedFatContent":"1.82 g"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"banaha-bread","source_url":"https://www.myplate.gov/recipes/banaha-bread","name":"Banaha Bread","description":"Yes, it is Banaha and not Banana. Banaha Bread is a delicious cornmeal-based food that is great with any meal.","ingredients":[{"name":null,"items":["6 cups water","4-6 handfuls corn shucks","2 cups cornmeal","1 teaspoon baking soda","1 teaspoon salt"]}],"directions":[{"name":null,"steps":["In a large pot, bring 6 cups of water to a boil over medium to high heat.","Boil corn shucks for about 10 minutes. Remove carefully.","Strip a few shucks into strings. Tie two strings together to make longer strings.","In a medium-sized bowl, mix the dry ingredients.","Keep mixing and slowly add a little water until the mixture is firm enough to handle easily.","Form cornmeal mixture into 8 oval shaped balls about 3 inches long.","Wrap the balls in corn shucks and tie the ends closed with the corn shuck strings.","Gently put wrapped balls into the large pot of boiling water. The pot should be about 2/3 full of water. Cover the pot with a lid and cook for 30-45 minutes over medium to high heat.","Remove corn shuck covering and serve hot."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"127.00"},"notes":"Tip: Spice up your bread with peppers, onions, and peas. It can be refrigerated and reheated in a pan or microwave oven.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe by Trista Winnett, Choctaw Nation"},
{"slug":"banana-berry-muffins","source_url":"https://www.myplate.gov/recipes/banana-berry-muffins","name":"Banana Berry Muffins","description":"These moist muffins have a fruity flavor and are full of whole grain goodness. Serve them anytime.","ingredients":[{"name":null,"items":["nonstick cooking spray","1/4 cup applesauce","1/4 cup sugar","2 tablespoons dried egg mix (or 1 egg)","2 ripe bananas, mashed","2 tablespoons water","1/4 cup all-purpose flour","1/4 cup whole wheat flour","1/4 cup quick cooking oats","1/2 teaspoon baking powder","1/2 teaspoon baking soda","1/4 teaspoon salt","1/4 cup blueberries or strawberries (fresh or frozen)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Spray a 12-cup muffin pan with non-stick cooking spray.","In a medium-size bowl, combine applesauce, sugar, dried egg mix, banana, and water. Mix well.","In a large bowl mix flours, oats, baking powder, baking soda, and salt.","Add the applesauce mixture to the bowl with the dry ingredients; mix just until the batter is moist.","Gently add berries into the mixture.","Fill each muffin cup about 3/4 full of batter.","Bake for 25-30 minutes until lightly brown.","Cool for 10 minutes and remove from pan."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 muffin","calories":"70.15 kcal","carbohydrateContent":"14.85 g","cholesterolContent":"13.58 mg","fiberContent":"1.00 g","proteinContent":"1.40 g","sodiumContent":"126.38 mg","sugarContent":"8.26 g","fatContent":"0.66 g","saturatedFatContent":"0.18 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe submitted by Alicson Scott, Chickasaw Nation, Get Fresh! Nutrition Education Program"},
{"slug":"banana-bread","source_url":"https://www.myplate.gov/recipes/banana-bread","name":"Banana Bread","description":"This banana bread recipe packs in 3 large bananas per loaf! It’s a terrific way to use over-ripe bananas.","ingredients":[{"name":null,"items":["3 large bananas (well-ripened)","1 egg","2 tablespoons vegetable oil (or cooking oil of choice)","1/3 cup skim milk","1/3 cup sugar","1 teaspoon salt","1 teaspoon baking soda","1/2 teaspoon baking powder","1 1/2 cups flour"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F.","Peel the bananas. Put them in a mixing bowl. Mash the bananas with a fork.","Add the egg, oil, milk, sugar, salt, baking soda, and baking powder. Mix well with the fork.","Slowly stir the flour into the banana mixture. Stir for 20 seconds until the flour is moistened.","Lightly grease a 8 x 4-inch to 10 x5-inch bread pan with a little oil or cooking spray. Or, line the pan with wax paper.","Pour the batter into the bread pan.","Bake for 45 minutes until a toothpick inserted near the middle comes out clean.","Let the bread cool for 5 minutes before removing it from the pan."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/12 of recipe"],"calories":"138.83 kcal","carbohydrateContent":"24.98 g","cholesterolContent":"17.33 mg","fiberContent":"0.96 g","proteinContent":"2.59 g","sodiumContent":"330.42 mg","sugarContent":"10.86 g","fatContent":"3.01 g","saturatedFatContent":"0.52 g"},"notes":"The key to good banana bread is to use well-ripened bananas that are covered with brown speckles. Try using half whole wheat flour to add some fiber.","contributor":"Adapted from the Pennsylvania Nutrition Education Network"},
{"slug":"banana-cocoa-yogurt-pops","source_url":"https://www.myplate.gov/recipes/banana-cocoa-yogurt-pops","name":"Banana Cocoa Yogurt Pops","description":"Take a bite out of these creamy yogurt pops! Banana, cocoa, and yogurt are the perfect combo for a frozen treat.","ingredients":[{"name":null,"items":["1 cup low-fat vanilla yogurt","1 medium banana","2 teaspoons cocoa powder","mini muffin cups or paper cups","paper straws or popsicle sticks"]}],"directions":[{"name":null,"steps":["Mash banana with a fork.","Add yogurt to banana and mix well.","Stir in cocoa powder.","Divide into 8 mini muffin cups or 4 small paper cups.","Place in cut paper straws or popsicle sticks.","Freeze and enjoy!"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 yogurt mini cups","calories":"77.17 kcal","carbohydrateContent":"13.65 g","cholesterolContent":"3.68 mg","fiberContent":"0.84 g","proteinContent":"3.51 g","sodiumContent":"41.83 mg","sugarContent":"11.01 g","fatContent":"1.13 g","saturatedFatContent":"0.70 g"},"notes":"Create your own yogurt pops and experiment with different flavors or try out one of these recipes:\nStrawberry Yogurt Pops\nTropical Yogurt Pops\nStrawberry Kiwi Yogurt Pops","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"banana-cupcakes","source_url":"https://www.myplate.gov/recipes/banana-cupcakes","name":"Banana Cupcakes","description":"Add some potassium and flavor to your cupcakes by making them banana cupcakes.","ingredients":[{"name":null,"items":["1/2 cup shortening (solid vegetable)","3/4 cup sugar","2 large eggs","1 teaspoon vanilla extract","1 1/2 cups flour","1 teaspoon baking powder","1/2 teaspoon baking soda","1/2 teaspoon salt","1 cup banana, mashed"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a large mixing bowl, cream shortening and sugar using an electric mixer. Add eggs and vanilla, mixing well.","In a medium mixing bowl, combine flour, baking powder, baking soda, and salt.","Add dry ingredients (flour mixture) and bananas to creamed mixture (the egg mixture). Mix well until combined.","Place paper baking cups in muffin tin or lightly coat muffin tin with cooking spray. Fill muffin cups 2/3 full of batter.","Bake 20-22 minutes, until golden brown. Remove cupcakes from muffin tin and place on a rack to cool."]}],"yield":"12 cupcakes","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe (65g)","calories":"209.04 kcal","carbohydrateContent":"28.86 g","cholesterolContent":"34.25 mg","fiberContent":"0.74 g","proteinContent":"2.79 g","sodiumContent":"202.97 mg","sugarContent":"15.54 g","fatContent":"9.08 g","saturatedFatContent":"2.31 g"},"notes":null,"contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"banana-oat-cookies","source_url":"https://www.myplate.gov/recipes/banana-oat-cookies","name":"Banana Oat Cookies","description":"With whole-grains, fruit, and no added sugar, these cookies make a healthy and tasty treat.","ingredients":[{"name":null,"items":["1 cup banana, mashed, use overripe banana","1/2 cup yogurt, low-fat plain","1/4 cup water","1 cup quick oats (not \"instant\")","raisins (1/2 cup, optional)","sunflower seeds (1/2 cup, optional)","cinnamon (optional)"]}],"directions":[{"name":null,"steps":["Wash hands with soap and water. Make sure utensils and counter top are clean.","Preheat oven to 375 °F.","Mix mashed bananas with yogurt and water.","Add quick oats. Mix well.","Add optional raisins or sunflower seeds if you wish and mix well.","Add optional cinnamon to taste if you wish and mix well.","The batter should be thick and easily to scoop with a spoon.","Grease a baking sheet. Place a tablespoon of dough on the sheet, press lightly a make a flat disk. Repeat with remaining dough. Refrigerate if any is remaining in the bowl.","Bake at 375 °F for 20 minutes. Flip cookies over and return to oven to bake 15 minutes longer or until cookie are crisp."]}],"yield":"25 Small Cookies","nutrition":{"@type":"NutritionInformation","servingSize":["1 small cookie","1/25 of recipe"],"calories":"23.95 kcal","carbohydrateContent":"4.55 g","cholesterolContent":"0.29 mg","fiberContent":"0.48 g","proteinContent":"0.75 g","sodiumContent":"3.72 mg","sugarContent":"1.80 g","fatContent":"0.31 g","saturatedFatContent":"0.09 g"},"notes":null,"contributor":"Adapted from University of Minnesota Cooperative Extension Service"},
{"slug":"banana-oatmeal-pancakes-lentils","source_url":"https://www.myplate.gov/recipes/banana-oatmeal-pancakes-lentils","name":"Banana Oatmeal Pancakes with Lentils","description":"A delicious way to start your day, these pancakes bring whole grains, protein, and fiber to your breakfast table.","ingredients":[{"name":null,"items":["1/4 cup dried red lentils","1 cup old fashioned oats","1 cup all-purpose flour","1/4 cup brown sugar, packed","1 teaspoon cinnamon","2 teaspoons baking powder","1/2 teaspoon baking soda","1/4 teaspoon salt","3/4 cup plain yogurt, low-fat","3/4 cup milk, low-fat","1/4 cup canola oil (or melted butter or cooking oil of choice)","2 large eggs","1 teaspoon vanilla","2 bananas, mashed, over-ripe","maple syrup (optional, to serve with pancakes)"]}],"directions":[{"name":null,"steps":["In a small saucepan of boiling water, cook the lentils for 15-20 minutes, until soft. Drain well and set aside.","In a large bowl, stir together the oats, flour, brown sugar, cinnamon, baking powder, baking soda, and salt.","In a smaller bowl, whisk together the yogurt, milk, oil, eggs, and vanilla. Add to the dry ingredients along with the mashed banana and lentils, and stir until just combined.","Set a heavy skillet over medium-high heat, add a drizzle of oil and wipe it around with a paper towel to coat the bottom of the pan.","Cook about 1/2 a cup of batter at a time, spreading it out with the back of a spoon if needed (it will be thick). Cook for a couple of minutes, until bubbles begin to break through the surface and the bottom is golden. Keep the heat to medium, as these will take longer to cook through that most pancakes, and you do not want to burn the bottoms.","Flip with a thin spatula and cook until they are golden on the other side, and springy to the touch. Keep the pancakes warm on a rack set on a baking sheet in a 250 °F oven while you finish cooking the rest.","Serve drizzled with maple syrup, if desired."]}],"yield":"10 pancakes","nutrition":{"@type":"NutritionInformation","servingSize":["1 pancake","1/10 of recipe (116g)"],"calories":"223.70 kcal","carbohydrateContent":"31.72 g","cholesterolContent":"43.12 mg","fiberContent":"2.82 g","proteinContent":"6.63 g","sodiumContent":"255.00 mg","sugarContent":"11.96 g","fatContent":"7.83 g","saturatedFatContent":"1.12 g"},"notes":null,"contributor":"The Big Book of Lentils Cookbook\nCanadian Lentils"},
{"slug":"banana-oatmeal-raisin-cookies","source_url":"https://www.myplate.gov/recipes/banana-oatmeal-raisin-cookies","name":"Banana Oatmeal Raisin Cookies","description":"No one will know that these tasty cookies don''t have any added sugar.","ingredients":[{"name":null,"items":["3 bananas (ripe)","1/3 cup margarine (or butter)","2 cups quick-cooking oats (uncooked)","1/4 cup fat-free or low-fat milk","1/2 cup raisins","1 teaspoon vanilla extract"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Put the margarine in a small saucepan. Melt it on low heat.","Put all the ingredients in a mixing bowl. Mix really well.","Let the mix stand for about 5 minutes, until the oats are wet.","Lightly grease the cookie sheet.","For each cookie, spoon out about 1 tablespoon of dough and drop it onto the greased cookie sheet.","Bake the cookies for 15 to 20 minutes.","Let the cookies cool on the cookie sheet for about 1 minute.","Move the cookies to wire racks or a towel. Let them cool completely."]}],"yield":"15 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cookies of 1/15 of recipe (49g)","calories":"109.27 kcal","carbohydrateContent":"17.45 g","cholesterolContent":"0.17 mg","fiberContent":"1.75 g","proteinContent":"1.92 g","sodiumContent":"36.93 mg","sugarContent":"7.81 g","fatContent":"3.73 g","saturatedFatContent":"0.75 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"banana-pancakes-apple-topping","source_url":"https://www.myplate.gov/recipes/banana-pancakes-apple-topping","name":"Banana Pancakes with Apple Topping","description":"Kick your pancakes up a notch with fresh bananas and an apple topping. The whole wheat flour and the fresh fruit in the recipe add extra fiber to your breakf...","ingredients":[{"name":null,"items":["3 apples","3 tablespoons sugar","1/4 cup water","2 eggs","1 1/2 cups low-fat or fat-free milk","1 tablespoon honey","3 tablespoons vegetable oil (or cooking oil of choice)","3/4 cup whole wheat flour","3/4 cup flour (all purpose)","2 teaspoons baking powder","2 bananas","1 teaspoon cinnamon"]}],"directions":[{"name":"Apple Topping","steps":["Wash apples, remove cores, and slice thinly with peel still on.","Combine apples with the sugar, cinnamon, and water.","Cook in skillet for 10 minutes. Set aside while making pancakes."]},{"name":"Pancakes","steps":["Beat eggs. Beat in milk, honey, and oil.","Add flours and baking powder.","Slice bananas and add to mixture.","Coat a large, non-stick frying pan or griddle with non-stick cooking spray. Warm the pan over medium heat for 2 minutes.","Spoon 1/4 cup of the batter onto the heated griddle for each pancake (adjust more or less depending on pancake size).","Cook until the tops are bubbly and the pancakes are dry around the edges. Flip and cook for 2-3 minutes or until golden on both sides. Place pancakes on a platter and keep warm.","Repeat steps 5 and 6 until batter has been used, using more nonstick cooking spray as needed.","Serve pancakes topped with cooked apples."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (252g)","calories":"359.76 kcal","carbohydrateContent":"60.12 g","cholesterolContent":"71.55 mg","fiberContent":"5.08 g","proteinContent":"8.23 g","sodiumContent":"209.08 mg","sugarContent":"30.88 g","fatContent":"10.06 g","saturatedFatContent":"2.01 g"},"notes":"Infants 12 months and under should NOT be given honey.","contributor":"Pumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"banana-pudding","source_url":"https://www.myplate.gov/recipes/banana-pudding","name":"Banana Pudding","description":"Dress up instant pudding mix with this dessert that combines low fat dairy and fruit for a tasty, nourishing treat.","ingredients":[{"name":null,"items":["1 (3.4 ounce) box instant pudding mix, banana or vanilla","2 cups fat-free (skim) milk (or 1% milk)","1 (8 ounce) container of fat-free plain yogurt (or non-dairy whipped topping)","2 medium bananas, sliced (or other sliced fruit)"]}],"directions":[{"name":null,"steps":["In a medium bowl, combine pudding and milk. Beat with wooden spoon, wire whisk, or electric mixer on lowest speed for 2 minutes","Gently mix yogurt (or whipped topping) with pudding mixture. Refrigerate for 30 minutes.","Layer fruit slices in the bottom of 8 dessert cups.","Pour the pudding mixture over sliced fruit. Top with more fruit.","Refrigerate until ready to serve, at least 5 minutes. The taste is better if it''s refrigerated longer."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"115.75 kcal","carbohydrateContent":"23.64 g","cholesterolContent":"3.53 mg","fiberContent":"0.54 g","proteinContent":"3.81 g","sodiumContent":"218.04 mg","sugarContent":"21.54 g","fatContent":"0.65 g","saturatedFatContent":"0.40 g"},"notes":null,"contributor":"Choices: Steps Toward Health, Adapted from: Lisa''s Famous Dessert\nUniversity of Massachusetts\nExtension Nutrition Education Program"},
{"slug":"banana-split-oatmeal","source_url":"https://www.myplate.gov/recipes/banana-split-oatmeal","name":"Banana Split Oatmeal","description":"Frozen yogurt and bananas turn oatmeal into a healthy dessert or satisfying snack.","ingredients":[{"name":null,"items":["1/3 cup quick-cooking oatmeal","1/8 teaspoon salt","3/4 cup water","1/2 banana (sliced)","1/2 cup low-fat frozen yogurt","3 leaves mint, fresh (optional for garnish)"]}],"directions":[{"name":null,"steps":["In a microwave safe cereal bowl, mix together the oatmeal and salt. Stir in water.","Microwave on high power for 1 minute. Stir. Microwave on high power for another minute. Stir again.","Microwave an additional 30-60 seconds on high power until the cereal reaches the desired thickness. Stir again.","Top with banana slices and frozen yogurt."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 full recipe (357g)","calories":"282.10 kcal","carbohydrateContent":"50.44 g","cholesterolContent":"39.15 mg","fiberContent":"3.74 g","proteinContent":"10.91 g","sodiumContent":"354.83 mg","sugarContent":"28.49 g","fatContent":"4.07 g","saturatedFatContent":"1.68 g"},"notes":"The banana split oatmeal can be a snack by itself.","contributor":"University of Nebraska Cooperative Extension"},
{"slug":"banana-waldorf","source_url":"https://www.myplate.gov/recipes/banana-waldorf","name":"Banana Waldorf","description":"Sweetened with bananas and apples, this recipe makes a healthy dessert, a satisfying afternoon snack, or even a tasty breakfast.","ingredients":[{"name":null,"items":["3 bananas (peeled and sliced)","1 apple (cored and sliced, with peel)","4 cups nonfat vanilla yogurt","1/8 teaspoon cinnamon","1/8 cup walnuts"]}],"directions":[{"name":null,"steps":["Mix all ingredients together in large mixing bowl.","Place in individual serving dishes and chill until ready to serve, up to 1 hour."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"320.86"},"notes":"This dish looks great when topped with a sprinkle of ground cinnamon.","contributor":"Food and Health Communications, Inc."},
{"slug":"banana-walnut-oatmeal","source_url":"https://www.myplate.gov/recipes/banana-walnut-oatmeal","name":"Banana Walnut Oatmeal","description":"If your bananas are turning ripe before you''re ready to eat them or use them in a recipe that calls for very ripe or mashed bananas, pop them in the freezer ...","ingredients":[{"name":null,"items":["2/3 cup non-fat dry milk mixed with 2 cups water (or 2 cups fluid non-fat or low-fat milk)","1/16 teaspoon salt (dash) (optional)","2 3/4 cups water","2 cups quick cooking oats","2 ripe bananas (mashed)","2 tablespoons 100% maple syrup","2 tablespoons walnuts (chopped)"]}],"directions":[{"name":null,"steps":["In a small saucepan, combine reconstituted non-fat dry milk, salt, and additional water. Heat over medium heat until steaming hot, but not boiling.","Add oats and cook, stirring until creamy, 1 to 2 minutes.","Remove the pan from heat and stir in mashed banana and maple syrup. Divide between 4 bowls, garnish with walnuts, and serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"304.47 kcal","carbohydrateContent":"54.52 g","cholesterolContent":"2.28 mg","fiberContent":"5.36 g","proteinContent":"10.44 g","sodiumContent":"106.62 mg","sugarContent":"22.42 g","fatContent":"5.32 g","saturatedFatContent":"0.80 g"},"notes":"You can substitute 2 cups water or 2 cups skim milk for the reconstituted non-fat dry milk.","contributor":"USDA’S Collection of Nonfat Dry Milk (NDM) Recipes\nUSDA Food and Nutrition Service\nFood Distribution Service"},
{"slug":"bananas-with-caramel-sauce","source_url":"https://www.myplate.gov/recipes/bananas-with-caramel-sauce","name":"Bananas with Caramel Sauce","description":"Sweet and delicious, this banana dessert will be a hit with the whole family! The recipe makes 12 servings, making it a wonderful choice for social gathering...","ingredients":[{"name":null,"items":["6 large bananas","6 tablespoons butter","1 cup sugar","1/2 cup evaporated skim milk","2 teaspoons cornstarch, dissolved in 2 teaspoons water"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Place unpeeled banana on a baking sheet. Prick the skin of each banana several times with the prongs of a fork.","Cook the bananas for about 8 minutes. The skin will turn black.","Over moderate heat, cook the butter, water, and sugar to a medium brown color (it will look like caramel). Remove from heat.","Combine the milk and cornstarch slurry to the caramel mixture. Stir to dissolve.","Return to the heat and bring to a boil, stirring constantly.","Remove from heat and cool slightly.","Serve on top of the bananas that have been peeled and sliced lengthwise."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"188.73 kcal","carbohydrateContent":"32.51 g","cholesterolContent":"15.69 mg","fiberContent":"1.08 g","proteinContent":"1.32 g","sodiumContent":"13.06 mg","sugarContent":"27.79 g","fatContent":"6.01 g","saturatedFatContent":"3.67 g"},"notes":null,"contributor":"Originally named \"Ivory Coast Bananas with Caramel Sauce\"\nAfrican American Recipes\nContra Costa County Health Services\nNutrition, Physical Activity, and Food Security Project"},
{"slug":"barley-jambalaya","source_url":"https://www.myplate.gov/recipes/barley-jambalaya","name":"Barley Jambalaya","description":null,"ingredients":[{"name":null,"items":["1 cup instant pearl barley","4 cups water","2 whole bay leaves","3 medium onions","2 small celery stalks","1 cup diced green, red, yellow, or orange bell pepper","2 medium cloves garlic","1 tablespoon canola oil","4 ounces ground turkey","2 (14.5-oz) cans diced tomato (no salt added)","1 teaspoon salt","1/2 teaspoon ground cayenne pepper","1 1/2 teaspoons dried oregano","1 teaspoon ground black pepper"]}],"directions":[{"name":"In Advance","steps":["In a colander, rinse barley under cold water.","In a medium pot over high heat, bring barley, water, and bay leaves to a boil. Reduce heat to low and cover. Cook barley until tender and water is absorbed, about 20-30 minutes.","In a colander, drain barley. Set aside."]},{"name":"Preparation","steps":["Peel, rinse, and dice onions. Rinse and dice celery and pepper. Peel and mince garlic.","In a large pot over medium-high heat, heat oil.","Add onions, celery, pepper, and garlic to pot. Mix well. Cook until veggies are soft, about 5 minutes.","Add ground turkey. Cook until internal temperature registers 165 °F on a food thermometer, about 5 minutes more.","Add tomatoes and their juices. Bring to a simmer.","Add spices. Stir to combine. Cover and reduce heat. Cook at a low simmer for 15 minutes.","Add cooked barley to the mixture. Stir to combine. Add more water or broth, if needed. Cook over low heat to bled flavors, about 5-10 minutes more.","Remove bay leaves and serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"One Serving: 1.5 Cups","calories":"278.60 kcal","carbohydrateContent":"51.17 g","cholesterolContent":"14.02 mg","fiberContent":"9.70 g","proteinContent":"8.61 g","sodiumContent":"443.24 mg","sugarContent":"7.97 g","fatContent":"5.74 g","saturatedFatContent":"0.98 g"},"notes":"To save time, cook barley up to 2 days in advance. Refrigerate until ready to use. Add to pot in step 7 above. Or, use another whole grain you have made in advance, like brown rice.\nWhen doubling this recipe, do not double cayenne pepper unless you prefer a very spicy dish.\nFor a vegetarian option, use cooked or canned pinto or black beans, rinsed and drained, in place of meat.\nMaterials: You will need a can opener, colander, cutting board, large pot with lid, measuring spoons, medium pot with lid, mixing spoon, and a sharp knife.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"barley-pilaf","source_url":"https://www.myplate.gov/recipes/barley-pilaf","name":"Barley Pilaf","description":"Short on time? Using quick-cooking barley will cut this recipe time in half. See the notes for more information.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","1 cup onion, chopped","1/2 cup celery, chopped","green or red bell pepper, chopped (1/2 cup, optional)","1 cup mushrooms, sliced (or 4 ounce can mushrooms, drained)","1 cup pearl barley, uncooked","1 teaspoon low-sodium bouillon (vegetable, beef or chicken)","2 1/2 cups water"]}],"directions":[{"name":null,"steps":["Place a medium pan over medium heat; add vegetable oil, onion and celery. Cook, stirring often until onion is soft.","Add bell pepper (if using), mushrooms and pearl barley. Stir well.","Add water and bouillon and stir to dissolve bouillon. Bring to a boil, lower heat and cover pan.","Cook for 50 to 60 minutes or until barley is tender and liquid is absorbed."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/8 of recipe (146g)"],"calories":"148.05 kcal","carbohydrateContent":"30.01 g","cholesterolContent":"0.04 mg","fiberContent":"4.22 g","proteinContent":"2.75 g","sodiumContent":"16.67 mg","sugarContent":"1.43 g","fatContent":"2.28 g","saturatedFatContent":"0.35 g"},"notes":"This can be used as a side dish, or stuffing for pork chops or chicken.\nTo serve as a main dish, add 2 cups of any chopped cooked meat during the last fifteen minutes of cooking.\nIf using quick-cooking barley the recipe can be prepared in 15 minutes or less. Reduce water to 2 cups and cook for 10 to 15 minutes.","contributor":"Montana State University Extension Service"},
{"slug":"basic-custard","source_url":"https://www.myplate.gov/recipes/basic-custard","name":"Basic Custard","description":"Eggs, milk, and a bit of sugar combine into a wholesome dessert that can be enjoyed by all ages.","ingredients":[{"name":null,"items":["1 egg","2 tablespoons sugar","1 cup skim milk (or reconstituted non-fat dry milk)","vanilla extract (1/2 teaspoon, optional)"]}],"directions":[{"name":"Stovetop version","steps":["Beat egg and sugar together in a saucepan.","Add milk.","Place saucepan with egg/milk mixture in another pan containing 1-2 inches boiling water.","Stir custard constantly while cooking. Cook until foam disappears and custard coats the spoon. Remove from heat.","Add vanilla, if using and stir. Pour into individual dishes and cool in the refrigerator. Custard will be soft."]},{"name":"Baked version","steps":["Beat together egg and sugar in a baking dish.","Add milk and mix. Add vanilla, if using and mix thoroughly.","Set baking dish in a shallow pan of hot water.","Bake at 350 °F until the tip of a knife inserted in the center of the custard comes out clean (50-60 minutes). Do not overcook. Eat warm or refrigerate for later."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/4 of recipe (81g)"],"calories":"63.68 kcal","carbohydrateContent":"9.35 g","cholesterolContent":"53.21 mg","fiberContent":"0.00 g","proteinContent":"3.64 g","sodiumContent":"41.20 mg","sugarContent":"9.34 g","fatContent":"1.31 g","saturatedFatContent":"0.43 g"},"notes":"An additional egg can be added during step 1.","contributor":"Eating Right is Basic\nMichigan State University Cooperative Extension Service\nNutrition Education Program"},
{"slug":"basic-muffins","source_url":"https://www.myplate.gov/recipes/basic-muffins","name":"Basic Muffins","description":"Don''t let the name fool you! These muffins combine the goodness of walnuts, raisins, carrots, and spices to result in a muffin that can be tailored to your t...","ingredients":[{"name":null,"items":["1/4 cup vegetable oil","1 cup sugar","1 egg","1 1/4 cups applesauce, unsweetened","1 1/2 teaspoons cinnamon","1 teaspoon baking soda","1/4 teaspoon salt","1 cup all-purpose flour","1 cup whole wheat flour","carrots, raisins, and/or walnuts (optional)","fat-free milk (1/2 cup optional, only if adding carrots, raisins or walnuts)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Line muffin tin with paper baking cups or grease bottom of tin with cooking spray.","Cream margarine and sugar with an electric mixer, or by hand.","Add egg, milk, and applesauce, mixing well.","Blend in cinnamon, baking soda, salt, and flour.","Add carrots, raisins, and/or walnuts if desired. If any of these items are added, also add milk and mix.","Fill muffin tins 2/3 full and bake for 15 to 18 minutes."]}],"yield":"12 Muffins","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"198.23 kcal","carbohydrateContent":"34.93 g","cholesterolContent":"17.13 mg","fiberContent":"1.80 g","proteinContent":"2.97 g","sodiumContent":"160.55 mg","sugarContent":"19.11 g","fatContent":"5.52 g","saturatedFatContent":"0.84 g"},"notes":"Tip: Muffins turn out better when mixed by hand.","contributor":"University of Wisconsin Cooperative Extension Service - Sawyer County and the Lac Courte Oreilles Tribe"},
{"slug":"basic-quiche","source_url":"https://www.myplate.gov/recipes/basic-quiche","name":"Basic Quiche","description":"You can vary this recipe by using whatever vegetables you have on hand (fresh, frozen, or canned)!","ingredients":[{"name":null,"items":["1 (9-inch) pie crust, baked","1 cup vegetables, chopped (broccoli, zucchini, or mushrooms)","1/2 cup cheese, shredded","3 large eggs, beaten","1 cup milk. fat-free","1/2 teaspoon salt","1/2 teaspoon ground black pepper","1/2 teaspoon garlic powder"]}],"directions":[{"name":null,"steps":["Preheat the oven to 375 °F.","Shred the cheese with a grater. Put it in a small bowl for now.","Chop the vegetables until you have 1 cup of chopped vegetables.","Cook the vegetables until they are cooked, but still crisp.","Put the cooked vegetables and shredded cheese into a pie shell.","Mix the eggs, milk, salt, pepper, and garlic powder in a bowl.","Pour the egg mix over the cheese and vegetables","Bake for 30-40 minutes, or until a knife inserted near the center comes out clean.","Let the quiche cool for 5 minutes before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/6 of recipe (128g)"],"calories":"130.15 kcal","carbohydrateContent":"9.03 g","cholesterolContent":"113.39 mg","fiberContent":"1.53 g","proteinContent":"7.88 g","sodiumContent":"337.49 mg","sugarContent":"3.25 g","fatContent":"6.97 g","saturatedFatContent":"3.03 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"basic-soup-and-sauce-mix","source_url":"https://www.myplate.gov/recipes/basic-soup-and-sauce-mix","name":"Basic Soup and Sauce Mix","description":"This pantry staple can be used in casseroles, soups, dips, and many more dishes!","ingredients":[{"name":null,"items":["2 cups milk, nonfat powdered","3/4 cup cornstarch","12 teaspoons chicken bouillon, low-sodium","2 tablespoons onion flakes, dried","2 teaspoons Italian seasoning"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a plastic bag.","Mix well.","Yield: Equal to about 3 cups dry or makes up to 9 cans equivalent cream soup."]},{"name":"To use as a substitute for 1 can of cream soup","steps":["Combine 1/3 cup of dry mix with 1 1/4 cups of cold water.","Cook and stir on stove top or in microwave until thickened.","Add thickened mixture to casseroles as you would a can of soup.","Storage: Store in closed plastic bag or air-tight container until ready to use. It does not have to be refrigerated."]}],"yield":"9 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 cup dry mix","calories":"113.24 kcal","carbohydrateContent":"20.49 g","cholesterolContent":"3.47 mg","fiberContent":"0.17 g","proteinContent":"6.15 g","sodiumContent":"118.96 mg","sugarContent":"8.65 g","fatContent":"0.61 g","saturatedFatContent":"0.20 g"},"notes":"The final product of this recipe is intended to be used as an ingredient in other recipes. It is not intended as a ready-to-eat product.","contributor":"Utah State University Cooperative Extension"},
{"slug":"basic-steamed-collards","source_url":"https://www.myplate.gov/recipes/basic-steamed-collards","name":"Basic Steamed Collards","description":"Making this side dish is a simple way to add leafy greens to your meal.","ingredients":[{"name":null,"items":["3 cups collard greens","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Wash and cut 5 large collard leaves, removing the thick stems.","Place greens in a pot with about 1 inch of water, cover with a lid, and bring to a boil.","After water boils, reduce to low heat and steam for about 3-5 minutes.","Add salt and pepper, to taste."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe (25g)","calories":"8.55 kcal","carbohydrateContent":"1.46 g","cholesterolContent":"0.00 mg","fiberContent":"1.08 g","proteinContent":"0.81 g","sodiumContent":"4.66 mg","sugarContent":"0.12 g","fatContent":"0.16 g","saturatedFatContent":"0.02 g"},"notes":null,"contributor":"University of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"batido-smoothie","source_url":"https://www.myplate.gov/recipes/batido-smoothie","name":"Batido (Smoothie)","description":"This refreshing smoothie is a blend of papaya, banana, and yogurt and makes a satisfying part of breakfast or any time of day. Mix in frozen or fresh berries...","ingredients":[{"name":null,"items":["2 cups papaya chunks (fresh or frozen)","2 bananas (overripe, sliced)","1 cup plain low-fat yogurt","1 cup ice cubes"]}],"directions":[{"name":null,"steps":["Put all the ingredients in the blender.","Put the lid on tightly. Turn the blender to a medium setting and blend until the ice is chopped and the mixture is smooth, about 1 minute.","Serve right away or cover and refrigerate up to 4 hours."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"8 ounces","calories":"135.17 kcal","carbohydrateContent":"27.52 g","cholesterolContent":"3.68 mg","fiberContent":"2.47 g","proteinContent":"4.07 g","sodiumContent":"51.88 mg","sugarContent":"20.72 g","fatContent":"1.34 g","saturatedFatContent":"0.75 g"},"notes":"One cup of low-fat milk, soy, rice, almond or coconut milk can be used instead of yogurt.\nStrawberries, blueberries, or raspberries can be used in addition to or instead of papaya.\nSee how to make this recipe and more on USDA''s MyPlate Kitchen YouTube site.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"bbq-chicken-pizza","source_url":"https://www.myplate.gov/recipes/bbq-chicken-pizza","name":"BBQ Chicken Pizza","description":"BBQ sauce, chicken, and bell peppers jazz up these English muffin pizzas.","ingredients":[{"name":null,"items":["6 English muffins (whole wheat)","1 bell pepper, chopped","3/4 cup barbecue sauce","1 1/2 cups chicken breast, skinless, cooked (cut-up or shredded)","3/4 cup smoked cheddar cheese, shredded (or regular)"]}],"directions":[{"name":null,"steps":["Heat oven to 450 °F.","Slice English muffins in half and place on ungreased, large cookie sheet.","Cut up bell pepper.","Spread barbecue sauce on English muffins to within ¼ inch of edges. Top with chicken, cheese and bell pepper.","Bake 7 to 12 minutes or until cheese is melted.","* Substitutions:\nEnglish muffins = Pizza bread\nChicken = Pinto beans, chopped tomatoes, and chopped onions"]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 pizza (1/2 English muffin)","calories":"152.87 kcal","carbohydrateContent":"20.74 g","cholesterolContent":"23.73 mg","fiberContent":"1.60 g","proteinContent":"9.53 g","sodiumContent":"332.03 mg","sugarContent":"6.43 g","fatContent":"3.71 g","saturatedFatContent":"1.58 g"},"notes":null,"contributor":"Texas Cooperative Extension Expanded Nutrition Program\nThe Texas A&M University System"},
{"slug":"bean-and-rice-burritos","source_url":"https://www.myplate.gov/recipes/bean-and-rice-burritos","name":"Bean and Rice Burritos","description":"These baked burritos are a great way to use leftover cooked rice. Try them with brown rice for a whole grain boost.","ingredients":[{"name":null,"items":["2 cups cooked rice","1 small onion, chopped","2 cups cooked kidney beans (1 (15 ounce) can, low-sodium, drained)","8 medium flour tortillas","1/2 cup salsa","1/2 cup cheese, shredded"]}],"directions":[{"name":null,"steps":["Preheat the oven to 300 °F.","Peel the onion, and chop it into small pieces.","Drain the liquid from the cooked (or canned) kidney beans.","Mix the rice, chopped onion, and beans in a bowl.","Put each tortilla on a flat surface.","Put 1/2 cup of the rice and bean mix in the middle of each tortilla.","Fold the sides of the tortilla to hold the rice and beans.","Put each filled tortilla (burrito) in the baking pan.","Bake for 15 minutes.","While the burritos are baking, grate 1/2 cup cheese.","Pour the salsa over the baked burritos. Add cheese.","Serve the burritos warm."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 burrito","1/8 of recipe"],"calories":"279.28 kcal","carbohydrateContent":"45.14 g","cholesterolContent":"7.06 mg","fiberContent":"5.61 g","proteinContent":"10.00 g","sodiumContent":"519.35 mg","sugarContent":"4.29 g","fatContent":"6.37 g","saturatedFatContent":"2.80 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"bean-and-vegetable-salad","source_url":"https://www.myplate.gov/recipes/bean-and-vegetable-salad","name":"Bean and Vegetable Salad","description":"Crunchy and colorful, this salad is packed with vegetables, flavor, and vitamins C and A.","ingredients":[{"name":null,"items":["1/2 head of red cabbage","1/2 head of romaine lettuce","3 medium carrot","1 medium cucumber","1 medium green pepper","2 broccoli stalks","3 medium tomatoes","3 cans (15.5 ounces each) low-sodium kidney beans or garbanzo beans","6 ounces low-fat cheddar cheese, grated","1/4 cup fat-free salad dressing"]}],"directions":[{"name":null,"steps":["Wash vegetables.","Thickly slice red cabbage, tear lettuce into pieces, peel and grate (or slice) carrots and cucumber","Dice the green pepper.","Cut broccoli into florets and tomato into wedges.","Combine all salad ingredients in a bowl.","Add salad dressing and toss together lightly just before serving."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"208.74 kcal","carbohydrateContent":"30.82 g","cholesterolContent":"10.77 mg","fiberContent":"10.24 g","proteinContent":"13.60 g","sodiumContent":"324.94 mg","sugarContent":"7.27 g","fatContent":"4.01 g","saturatedFatContent":"2.03 g"},"notes":null,"contributor":"Wellness Ways Resource Book, Adapted from Main Dish Salad\nUniversity of Illinois Extension Service"},
{"slug":"bean-dip","source_url":"https://www.myplate.gov/recipes/bean-dip","name":"Bean Dip","description":"Serve this easy-to-make bean and cheese dip at a party or as an after-school snack at home.","ingredients":[{"name":null,"items":["2 cups kidney beans, low-sodium, canned","1 tablespoon vinegar","3/4 teaspoon chili powder","1/8 teaspoon ground cumin","2 tablespoons onion, finely chopped","1 cup cheddar cheese, low-fat, shredded"]}],"directions":[{"name":null,"steps":["Drain the kidney beans, but save the liquid in a small bowl","Place the beans, vinegar, chili powder, and cumin in a blender. Blend until smooth. Add enough saved bean liquid to make the dip easy to spread.","Stir in the chopped onion and grated cheese.","Store in a tightly covered container and place in the fridge","Serve with raw vegetable sticks or crackers."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/6 of recipe"],"calories":"131.59 kcal","carbohydrateContent":"13.66 g","cholesterolContent":"14.31 mg","fiberContent":"4.70 g","proteinContent":"9.70 g","sodiumContent":"228.04 mg","sugarContent":"1.86 g","fatContent":"4.21 g","saturatedFatContent":"2.49 g"},"notes":"If you don’t have a blender, you can mix the first 4 ingredients in a medium bowl and mash with a fork. Then stir in the onion and cheese.\nYou can store this dip in the fridge for up to 4 or 5 days.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"bean-enchiladas","source_url":"https://www.myplate.gov/recipes/bean-enchiladas","name":"Bean Enchiladas","description":"Make this easy enchilada recipe tonight for a quick and healthy dinner. Serve it with Brazillian Rice on the side.","ingredients":[{"name":null,"items":["4 cups canned pinto beans, low-sodium (2 (15 ounce) cans)","1/2 cup Monterey Jack cheese, reduced-fat","1 tablespoon chili powder","8 (6 inch) flour tortillas","salsa (optional)"]}],"directions":[{"name":null,"steps":["Place beans in a large bowl and mash coarsely with a fork or potato masher; stir in chili powder.","Wrap tortillas in a damp paper towel. Microwave on high for 45 seconds, or until tortillas are soft and warm.","Divide bean mixture among tortillas and spread down center of tortilla. Sprinkle cheese on bean mixture.","Roll tortillas to enclose mixture.","Spray a 9x13 inch baking dish with nonstick cooking spray","Place enchiladas, seam side down, into baking dish.","Cover with foil and bake at 350 °F for 20 minutes or until heated through.","Serve warm with salsa."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"6\" enchiladas","calories":"224.31 kcal","carbohydrateContent":"35.06 g","cholesterolContent":"4.59 mg","fiberContent":"7.02 g","proteinContent":"10.35 g","sodiumContent":"501.91 mg","sugarContent":"2.56 g","fatContent":"4.98 g","saturatedFatContent":"2.12 g"},"notes":null,"contributor":"In the Kitchen with Chef Stephanie Green\nArizona Nutrition Network"},
{"slug":"beef-and-bean-chile-verde","source_url":"https://www.myplate.gov/recipes/beef-and-bean-chile-verde","name":"Beef and Bean Chile Verde","description":"This recipe blends flavors and packs a nutritional punch as a source of iron, vitamin C, and fiber. Bell pepper, onion, and tomatoes bring color to the dish....","ingredients":[{"name":null,"items":["2/3 pound 90% lean ground beef","1 large bell pepper (chopped)","1 can no salt added diced tomatoes (14.5 ounces)","1 large onion (chopped)","6 garlic cloves (chopped)","1 tablespoon chili powder","2 teaspoons ground cumin","2 cups fresh tomatillos (chopped or 16 ounce jar of enchilada sauce)","1/2 cup white vinegar","1 can low-sodium pinto or kidney beans (15 ounce can - rinsed and drained)"]}],"directions":[{"name":null,"steps":["Place meat, bell pepper, tomatoes, and onion in large sauce pan. Cook over medium heat for 8-10 minutes, stirring frequently until the meat is browned; drain fat.","Add garlic, chili powder and cumin; cook until fragrant (15 seconds).","Stir in tomatillos and vingear bring to a boil.","Reduce heat and simmer; cover and cook 10-15 minutes, stirring occasionally.","Add beans and cook until heated."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"187.16 kcal","carbohydrateContent":"21.74 g","cholesterolContent":"29.36 mg","fiberContent":"6.79 g","proteinContent":"14.12 g","sodiumContent":"183.02 mg","sugarContent":"6.11 g","fatContent":"5.22 g","saturatedFatContent":"1.70 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"beef-and-cabbage-dinner-tonight","source_url":"https://www.myplate.gov/recipes/beef-and-cabbage-dinner-tonight","name":"Beef and Cabbage","description":"The cabbage in this simple skillet dinner loads the recipe with vitamin C and fiber.","ingredients":[{"name":null,"items":["1 green cabbage head (washed and cut into bite-sized pieces)","1 onion, medium (chopped)","1 pound ground beef (90% lean)","2 sprays of non-stick cooking spray","1 teaspoon garlic powder","1/4 teaspoon black pepper","salt (to taste, optional)","red pepper flakes (to taste, optional)"]}],"directions":[{"name":null,"steps":["Chop cabbage and onion, set aside.","In a large skillet, cook the ground beef on medium heat until browned. Drain the fat. Set beef aside.","Spray skillet with non-stick cooking spray. Cook chopped onion using medium heat until soft.","Add cabbage to the chopped onion and cook until cabbage starts to brown.","Stir the beef into the cabbage and onion mixture.","Season with garlic powder, salt (optional), and pepper. Add red pepper flakes (optional) to the cabbage if you like it spicy."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"234.91 kcal","carbohydrateContent":"17.20 g","cholesterolContent":"65.73 mg","fiberContent":"6.37 g","proteinContent":"23.16 g","sodiumContent":"100.71 mg","sugarContent":"8.78 g","fatContent":"8.74 g","saturatedFatContent":"3.39 g"},"notes":null,"contributor":"\"Beef and Cabbage for Dinner Tonight\"\nUniversity of Maryland Cooperative Extension\nFood Supplement Nutrition Education Program"},
{"slug":"beef-and-vegetable-soup","source_url":"https://www.myplate.gov/recipes/beef-and-vegetable-soup","name":"Beef and Vegetable Soup","description":"One large pot and 1 hour are all that you need for this hearty soup. Make it for lunch or serve it for dinner.","ingredients":[{"name":null,"items":["1 pound ground beef","1 1/2 cans reduced sodium whole kernel corn (about 23 ounces)","1 can reduced sodium carrots (about 15 ounces)","1 can potatoes (sliced, about 15 ounces)","1 can no salt added diced tomatoes (about 15 ounces)","1 small onion, diced","1/2 cup macaroni, dry","1 teaspoon garlic powder","1 teaspoon onion powder"]}],"directions":[{"name":null,"steps":["In a large pan, brown ground beef over medium heat for 8-10 minutes. Drain off fat.","Add corn, carrots, potatoes, tomatoes, and onions to pot.","Cook for 25 minutes over medium heat. Stir every 10 minutes.","Add macaroni, garlic powder, and onion powder to pot.","Cook for 20 minutes over medium heat. Stir every 10 minutes."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"202.41 kcal","carbohydrateContent":"27.00 g","cholesterolContent":"32.86 mg","fiberContent":"4.60 g","proteinContent":"13.83 g","sodiumContent":"65.01 mg","sugarContent":"7.23 g","fatContent":"5.27 g","saturatedFatContent":"1.78 g"},"notes":"Tip for cooking ground beef: The recommended safe minimum internal temperature for ground beef is 160 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe submitted by Alicson Scott, Chickasaw Nation, Get Fresh! Nutrition Education Program"},
{"slug":"beef-and-vegetables","source_url":"https://www.myplate.gov/recipes/beef-and-vegetables","name":"Beef and Vegetables","description":"This dish can be prepared in about 35 minutes and may be served for lunch or dinner.","ingredients":[{"name":null,"items":["4 cups water","2 cups rice, uncooked","1 pound ground beef (or 1 can, about 24 ounces, canned beef)","2 cups steamed green beans (or 1 can, about 15 ounces, low-sodium green beans)","1 1/2 cups fresh cooked corn kernels (or 1 can, about 15 ounces, low-sodium corn)","1 can no salt added tomato sauce (about 15 ounces)","1/2 teaspoon garlic powder","1/2 teaspoon onion powder"]}],"directions":[{"name":null,"steps":["In a large pot, add water to rice and bring to a boil. Cover and cook on low heat for 15 minutes (do not remove the lid) until water is gone.","While the rice is cooking, put ground beef in a large pan and cook over medium heat on the stove for 8 to 10 minutes. Drain fat.","Let rice stand for about 3 minutes. Arrange rice on a platter like a doughnut ring. Set aside.","Add green beans, corn, tomato sauce, garlic powder, and onion powder to pan with meat.","Cook until steaming hot. Pour into center of rice ring and serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup","calories":"410.62 kcal","carbohydrateContent":"68.74 g","cholesterolContent":"43.82 mg","fiberContent":"4.02 g","proteinContent":"21.59 g","sodiumContent":"63.51 mg","sugarContent":"6.81 g","fatContent":"5.60 g","saturatedFatContent":"2.05 g"},"notes":"Tip for cooking ground beef: The recommended safe minimum internal temperature for ground beef is 160 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe by Lela Gabbard, Pala Indian Reservation"},
{"slug":"beef-noodles","source_url":"https://www.myplate.gov/recipes/beef-noodles","name":"Beef & Noodles","description":"This protein-filled dinner makes it easy to put food on the table even when you''re short on ingredients. Serve it with cooked vegetables from the freezer for...","ingredients":[{"name":null,"items":["3/4 pound 85% lean ground beef","1 1/2 cups water (can take up to 2 cups water)","2 cups egg noodles, uncooked (or any shaped pasta)","1/2 Eating Smart Seasoning Mix","salt (optional)"]}],"directions":[{"name":null,"steps":["Brown ground beef in a large skillet, drain the fat.","Add water, egg noodles or pasta, and seasoning mix. Stir.","Bring to a boil, reduce heat to low and simmer covered for 15-20 minutes or until noodles are tender.","Taste, then add a small amount of salt, if needed.","Refrigerate leftovers."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"235.19 kcal","carbohydrateContent":"18.33 g","cholesterolContent":"63.75 mg","fiberContent":"0.92 g","proteinContent":"19.07 g","sodiumContent":"89.08 mg","sugarContent":"4.55 g","fatContent":"9.10 g","saturatedFatContent":"3.29 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"beef-pot-roast","source_url":"https://www.myplate.gov/recipes/beef-pot-roast","name":"Beef Pot Roast","description":"This pot roast recipe is seasoned with orange juice, allspice, and pepper for a savory meal.","ingredients":[{"name":null,"items":["1 low-sodium beef bouillon cube","2 cups hot water","1/16 cup orange juice (1 tablespoon)","1/4 teaspoon allspice","1/8 teaspoon black pepper","1/2 cup onion, chopped","2 tablespoons water","2 1/2 pounds boneless lean beef chuck roast"]}],"directions":[{"name":null,"steps":["In a small bowl, put the bouillon cube in 2 cups hot water. Stir it until the bouillon cube dissolves. This will make 2 cups of beef broth.","In a medium bowl, stir together the broth, orange juice, allspice, and pepper.","Peel and chop the onion, to make 1/2 cup chopped onion.","Put 2 tablespoons water in the skillet. Heat on medium.","Put the onion in the skillet. Simmer it until tender.","Add the roast to the skillet. Brown it on all sides.","Pour the broth mix over the meat in the skillet.","Cover and simmer for 2 hours."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"236.63 kcal","carbohydrateContent":"1.49 g","cholesterolContent":"92.42 mg","fiberContent":"0.20 g","proteinContent":"26.18 g","sodiumContent":"65.33 mg","sugarContent":"0.64 g","fatContent":"14.17 g","saturatedFatContent":"5.58 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"beef-potatoes","source_url":"https://www.myplate.gov/recipes/beef-potatoes","name":"Beef & Potatoes","description":"The Eating Smart Seasoning Mix helps make this a quick and flavorful dinner of beef and potatoes. Try sweet potatoes or other types for increased variety.","ingredients":[{"name":null,"items":["1 pound 90% lean ground beef","1 1/3 cups water","7 medium potatoes, peeled and thinly sliced","3/4 Eating Smart Seasoning Mix","salt (to taste, optional)"]}],"directions":[{"name":null,"steps":["Wash and peel the potatoes.","Collect, slice, and measure all ingredients before starting to prepare the recipe.","Brown ground beef in a large skillet. Drain the fat.","Add water, potatoes, and seasoning mix. Stir to combine with the beef.","Bring to a boil, reduce heat to low, cover, and simmer for 20-30 minutes or until potatoes are tender.","Uncover and cook until excess water is evaporated.","Taste; then add a small amount of salt, if needed.","Refrigerate leftovers within 2 hours. Eat within 3 to 5 days."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"493.27 kcal","carbohydrateContent":"72.41 g","cholesterolContent":"67.77 mg","fiberContent":"7.15 g","proteinContent":"31.46 g","sodiumContent":"149.84 mg","sugarContent":"10.10 g","fatContent":"8.87 g","saturatedFatContent":"3.43 g"},"notes":"Be creative! Add chopped, cooked vegetables or frozen vegetables such as onion, carrots, peas, green beans, or corn after simmering.","contributor":"Eating Smart Being Active Recipes\nColorado State University and University of California at Davis"},
{"slug":"beef-pozole-soup","source_url":"https://www.myplate.gov/recipes/beef-pozole-soup","name":"Beef Pozole Soup","description":"This savory soup is full of tomatoes, beef, hominy, and cilantro, and will quickly become a favorite in your home.","ingredients":[{"name":null,"items":["32 ounces lean beef (2 pounds, cubed)","1 tablespoon olive oil","1 onion (large)","1 garlic clove (finely chopped)","1/4 teaspoon salt","1/8 teaspoon black pepper","1/4 cup cilantro","1 can stewed tomatoes (15 ounces, low sodium)","2 ounces tomato paste, low-sodium","2 cans hominy (2-14.5 oz cans or 1-1 lb. 13 ounce can)"]}],"directions":[{"name":null,"steps":["In a large pot, heat oil. Brown beef cubes.","Add onion, garlic, salt, pepper, cilantro, and enough water to cover the meat.","Cover pot and cook over low heat until meat is tender.","Add tomatoes and tomato paste. Continue cooking for about 20 minutes.","Add hominy and continue cooking another 15 minutes, stirring occasionally, over low heat. If too thick, add water for desired consistency."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared soup","1/10 of recipe (238g)"],"calories":"283.65 kcal","carbohydrateContent":"8.71 g","cholesterolContent":"92.36 mg","fiberContent":"2.12 g","proteinContent":"27.22 g","sodiumContent":"212.94 mg","sugarContent":"2.87 g","fatContent":"15.92 g","saturatedFatContent":"5.84 g"},"notes":"Note: Skinless, boneless chicken breasts may be used instead of beef cubes.","contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"beef-stroganoff","source_url":"https://www.myplate.gov/recipes/beef-stroganoff","name":"Beef Stroganoff","description":"Mushrooms and nutmeg make a delicious yogurt-based sauce for the pasta in this beef recipe.","ingredients":[{"name":null,"items":["1 pound beef, lean (top round)","2 teaspoons vegetable oil, divided (or cooking oil of choice)","3/4 tablespoon onion, finely chopped","1 pound mushrooms, sliced","1/4 teaspoon salt","1 dash black pepper","1/4 teaspoon nutmeg","1/2 teaspoon dried basil","1/4 cup low-sodium beef broth","1 cup low-fat yogurt, plain","6 cups macaroni (cooked in unsalted water)"]}],"directions":[{"name":null,"steps":["Cut beef into 1-inch cubes. Heat 1 teaspoon oil in non-stick skillet. Sauté onion for 2 minutes.","Add beef and sauté for additional 5 minutes. Turn to brown evenly. Remove from pan and keep hot.","Add remaining oil to pan; sauté mushrooms.","Add beef and onions to pan with seasonings.","Add beef broth and yogurt; gently stir in. Heat, but do not boil.","Serve with macaroni."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"6 ounces","calories":"450.45 kcal","carbohydrateContent":"59.05 g","cholesterolContent":"58.90 mg","fiberContent":"3.95 g","proteinContent":"34.44 g","sodiumContent":"233.31 mg","sugarContent":"6.13 g","fatContent":"7.32 g","saturatedFatContent":"2.29 g"},"notes":"Note: If thickening is desired, use 2 teaspoons cornstarch. The calories are the same as flour, but cornstarch has double the thickening power. These calories are not figured into the nutrients per serving.","contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"beef-vegetable-six-layer-dinner","source_url":"https://www.myplate.gov/recipes/beef-vegetable-six-layer-dinner","name":"Beef & Vegetable Six-Layer Dinner","description":"Savor this delicious casserole that will satisfy your comfort food cravings. This is a great weeknight dinner that''s perfect to serve your family or your gue...","ingredients":[{"name":null,"items":["2 medium potatoes, sliced","2 cups carrots, sliced","1/4 teaspoon black pepper","1/2 cup onion, sliced","1 pound 90% lean ground beef, browned and drained","1 1/2 cups green beans","1 can low-sodium tomato soup"]}],"directions":[{"name":null,"steps":["Lightly oil or spray baking dish with cooking spray.","Layer ingredients in order given. Cover.","Bake at 350 degrees F for 45 minutes or until tender and thoroughly heated.","Uncover and bake 15 more minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"221.57 kcal","carbohydrateContent":"25.51 g","cholesterolContent":"43.82 mg","fiberContent":"3.82 g","proteinContent":"16.34 g","sodiumContent":"84.54 mg","sugarContent":"7.92 g","fatContent":"6.09 g","saturatedFatContent":"2.31 g"},"notes":"For variation, use peas or corn instead of green beans. Use your favorite cream soup instead of tomato soup.","contributor":"Adapted from Sensational Six-Layer Dinner, One Dish Meals\nUniversity of Wisconsin Cooperative Extension Service\nA Family Living Program"},
{"slug":"beef-vegetable-soup","source_url":"https://www.myplate.gov/recipes/beef-vegetable-soup","name":"Beef & Vegetable Soup","description":"Did you know that people who frequently eat canned foods may have healthier diets than people who don’t? So when you’re looking for a wholesome, deliciou...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1 pound lean ground beef","1 medium onion, diced","2 cloves garlic, minced","1 can low sodium beef broth (14.5-ounce can)","1 can reduced sodium sliced carrots, drained (14.5-ounce can)","1 can reduced sodium cut green beans (14.5-ounce can)","1 can no salt added stewed tomatoes (14.5-ounce can)","1 teaspoon dried basil","1 cup cooked egg noodles"]}],"directions":[{"name":null,"steps":["In 4-quart saucepan over medium-high heat in hot oil, cook ground beef until well browned on all sides, stirring frequently.","With slotted spoon, remove beef to bowl. In drippings remaining in saucepan over medium heat, cook onion and garlic until tender-crisp.","Add beef broth, carrots, green beans, stewed tomatoes, basil and ground beef; over high heat, heat to boiling.","Reduce heat to low; cover and simmer 10 to 15 minutes to blend flavors, stirring occasionally.","Stir in cooked egg noodles."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1.5 cups","calories":"210.52 kcal","carbohydrateContent":"19.09 g","cholesterolContent":"43.82 mg","fiberContent":"4.80 g","proteinContent":"17.56 g","sodiumContent":"223.34 mg","sugarContent":"5.29 g","fatContent":"7.40 g","saturatedFatContent":"2.22 g"},"notes":null,"contributor":"Cans Get You Cooking"},
{"slug":"beefy-macaroni-and-cheese","source_url":"https://www.myplate.gov/recipes/beefy-macaroni-and-cheese","name":"Beefy Macaroni and Cheese","description":"The tomatoes in this dish provide extra vitamin C and B vitamins, while the Eating Smart Seasoning Mix gives you the option of adding flavor without adding a...","ingredients":[{"name":null,"items":["3/4 pound ground beef, 90% lean","1 1/2 cups water","1 cup macaroni, uncooked","1 can (14.5 ounces) diced tomatoes, undrained, low-sodium","1/2 Eating Smart Seasoning Mix","1/2 cup shredded cheese, low-fat","salt (optional, to taste)"]}],"directions":[{"name":null,"steps":["Brown ground beef in a large skillet; drain the fat.","Add water, macaroni, tomatoes, and seasoning mix; stir.","Bring to a boil, reduce heat to low and simmer, covered for 15-20 minutes or until macaroni is tender.","Remove from heat and add 1/2 cup grated cheese.","Taste; then add a small amount of salt if needed.","Refrigerate leftovers."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"316.82 kcal","carbohydrateContent":"29.63 g","cholesterolContent":"61.39 mg","fiberContent":"3.43 g","proteinContent":"25.99 g","sodiumContent":"185.23 mg","sugarContent":"7.37 g","fatContent":"10.08 g","saturatedFatContent":"4.43 g"},"notes":"Swiss cheese used in nutrition analysis and costing.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"beet-white-bean-salad","source_url":"https://www.myplate.gov/recipes/beet-white-bean-salad","name":"Beet & White Bean Salad","description":"Nutritious and flavorful canned beans and beets are just two of the many versatile canned ingredients in your pantry – they can be added to just about anyt...","ingredients":[{"name":"Dressing","items":["2 tablespoons cider vinegar","1 tablespoon Dijon mustard","1/2 teaspoon sugar","1/4 cup extra virgin olive oil","salt and ground black pepper, to taste"]},{"name":"Salad","items":["2 3/4 cups whole beets, well drained and each cut in half (or 16-ounce can)","1 can white kidney beans (cannellini) (15-ounce can)","1/2 cup reduced fat crumbled blue cheese","1/2 cup coarsely chopped walnuts, toasted","baby arugula leaves (optional)"]}],"directions":[{"name":null,"steps":["Prepare dressing: In small bowl combine cider vinegar, Dijon mustard, and sugar. Gradually add olive oil until well blended. Season with salt and pepper.","Prepare Salad: In large bowl combine beets and white kidney beans; toss with dressing.","To serve, place arugula leaves on platter or in serving bowl; top with beet mixture.","Sprinkle with crumbled blue cheese and walnuts."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"326.59 kcal","carbohydrateContent":"11.75 g","cholesterolContent":"12.66 mg","fiberContent":"3.29 g","proteinContent":"7.14 g","sodiumContent":"463.87 mg","sugarContent":"7.53 g","fatContent":"28.92 g","saturatedFatContent":"6.28 g"},"notes":null,"contributor":"Cans Get You Cooking"},
{"slug":"beets-beans-and-greens","source_url":"https://www.myplate.gov/recipes/beets-beans-and-greens","name":"Beets, Beans, and Greens","description":"This salad is full of protein and nutrients thanks to its bright beets and cooked beans.","ingredients":[{"name":null,"items":["1/4 cup lemon juice (or vinegar)","1 garlic clove, finely chopped","2 teaspoons mustard","salt and pepper (to taste, optional)","2 tablespoons vegetable oil (or cooking oil of your choice)","2 cups sliced cooked beets, fresh or low-sodium canned","1 head of lettuce, washed and torn into pieces","2 cups cooked beans, rinsed (any kind)"]}],"directions":[{"name":null,"steps":["To make dressing, combine lemon juice, garlic, mustard, oil, salt and pepper (optional) in a large bowl.","Place the sliced beets in a small bowl. Toss 1 tablespoon of the dressing with the beets to coat.","Toss the greens and beans with the remaining dressing in the large bowl.","Place onto plates and top with beets."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1.5 cup","calories":"167.59 kcal","carbohydrateContent":"24.24 g","cholesterolContent":"0.00 mg","fiberContent":"6.65 g","proteinContent":"7.94 g","sodiumContent":"85.61 mg","sugarContent":"5.72 g","fatContent":"5.19 g","saturatedFatContent":"0.74 g"},"notes":null,"contributor":"University of Maryland Cooperative Extension\nFood Supplement Nutrition Education Program"},
{"slug":"bell-pepper-and-apple-coleslaw","source_url":"https://www.myplate.gov/recipes/bell-pepper-and-apple-coleslaw","name":"Bell Pepper and Apple Coleslaw","description":"Apples and bell peppers liven up this coleslaw made with an easy vinegar mustard dressing. Add more color with red, orange or yellow bell peppers. Use your f...","ingredients":[{"name":"For the Dressing","items":["1 tablespoon vegetable oil","1/4 cup apple juice","2 tablespoons cider vinegar","2 teaspoons Dijon mustard","1/4 teaspoon salt","1 dash black pepper"]},{"name":"For the Salad","items":["1 small head green or Napa cabbage","1 orange or red bell pepper","1 Gala or Fuji apple","1/4 cup sliced almonds"]}],"directions":[{"name":null,"steps":["Whisk together dressing ingredients.","Shred or thinly slice cabbage.","Cut apple and pepper into small chunks.","Place cabbage, apples, pepper and almonds in large bowl.","Drizzle with dressing and toss."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"186.08 kcal","carbohydrateContent":"25.72 g","cholesterolContent":"0.00 mg","fiberContent":"8.43 g","proteinContent":"5.21 g","sodiumContent":"217.69 mg","sugarContent":"15.98 g","fatContent":"8.37 g","saturatedFatContent":"0.92 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"bell-pepper-and-potato-salad","source_url":"https://www.myplate.gov/recipes/bell-pepper-and-potato-salad","name":"Bell Pepper and Potato Salad","description":"A zesty and colorful side dish that the whole family will enjoy!","ingredients":[{"name":null,"items":["6 small red potatoes, quartered","1/2 cup Italian dressing, fat-free","1 1/2 teaspoons mustard, spicy brown","1 tablespoon fresh parsley, chopped","1/2 teaspoon garlic salt","1/4 teaspoon ground black pepper","1/2 cup green bell pepper, chopped","1/2 cup red bell pepper, chopped","1/2 cup green onion, sliced"]}],"directions":[{"name":null,"steps":["Cook potatoes in boiling water over high heat until tender, about 10 minutes.","Drain well and let cool.","Place potatoes in a medium bowl and set aside.","In a small bowl, combine dressing, mustard, parsley, and seasonings.","Pour mixture over potatoes and toss well.","Carefully stir in bell peppers and green onions.","Cover and chill until ready to serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup prepared salad","calories":"138.59 kcal","carbohydrateContent":"30.77 g","cholesterolContent":"0.39 mg","fiberContent":"3.38 g","proteinContent":"3.82 g","sodiumContent":"330.38 mg","sugarContent":"4.72 g","fatContent":"0.50 g","saturatedFatContent":"0.14 g"},"notes":null,"contributor":"California Department of Health Services\nCalifornia Children’s 5-A-Day Power Play Campaign"},
{"slug":"bell-pepper-and-vidalia-onion-strata-fresh-salsa","source_url":"https://www.myplate.gov/recipes/bell-pepper-and-vidalia-onion-strata-fresh-salsa","name":"Bell Pepper and Vidalia Onion Strata with Fresh Salsa","description":"Loaded with sweet Vidalia onions and bell peppers, this delicious baked breakfast or brunch dish can be assembled ahead of time, leaving just the baking for ...","ingredients":[{"name":null,"items":["1 Vidalia onion (divided)","1/2 red bell pepper (sliced vertically)","1/2 green bell pepper (sliced vertically)","1 tablespoon olive oil","4 large eggs","4 egg whites","1/2 cup fat-free (skim) milk","1/8 teaspoon ground black pepper","cooking spray","4 slices whole-grain bread (4-6 slices, dry or toasted, cubed)","1/2 cup reduced-fat Italian blend cheese","10 cherry tomatoes (or 2 tomatoes)","1 garlic clove"]}],"directions":[{"name":null,"steps":["Pack rack in center of oven and preheat oven to 350 ºF.","Cut Vidalia onion into slices vertically; reserve about 1/4 of onion. Heat oil in a 10-inch non-stick skillet. Sauté onion and pepper slices for 5-8 minutes, until tender and just starting to brown. Remove from heat.","Beat eggs, egg whites, milk, and pepper in large bowl, set aside.","Spray 8- or 9-inch baking pan (square or round) with cooking spray.","Arrange bread cubes in bottom of pan. Sprinkle with shredded cheese.","Add sautéed vegetables and pour in egg mix.","Bake uncovered for 45 minutes, until set. Egg dishes should be cooked to 160 ºF.","While strata is baking, prepare salsa, by dicing and mixing cherry tomatoes, garlic, and remaining Vidalia onion."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"295.03 kcal","carbohydrateContent":"26.03 g","cholesterolContent":"215.60 mg","fiberContent":"3.43 g","proteinContent":"19.63 g","sodiumContent":"398.85 mg","sugarContent":"7.29 g","fatContent":"12.86 g","saturatedFatContent":"4.11 g"},"notes":"Serving Suggestions: Serve with 8 ounce glass of fat-free (skim) milk and 1/2 cup cantaloupe chunks.","contributor":"Produce for Better Health Foundation"},
{"slug":"bell-pepper-nachos","source_url":"https://www.myplate.gov/recipes/bell-pepper-nachos","name":"Bell Pepper Nachos","description":"Try this deliciously different way to use bell peppers. Use any color of peppers and any type of beans.","ingredients":[{"name":null,"items":["4 bell peppers, any color","1 cup salsa","2 teaspoons seasoning (try a mixture-chili powder, garlic powder, ground cumin, pepper)","1 cup cooked chicken, shredded or chopped (or tofu -- or try a combination)","1 cup canned or cooked beans, drained (any type)","3/4 cup cheddar cheese, shredded"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Wash bell peppers, remove seeds and cut into bite-sized pieces. Arrange pieces close together in a single layer on a large foil-lined baking sheet.","In a medium bowl, combine salsa, seasonings and meat, beans or tofu. Spoon the mixture evenly over pepper pieces. Top with cheese.","Bake for 15 minutes, or until peppers are heated through and cheese is melted. Serve warm."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"118.45 kcal","carbohydrateContent":"10.12 g","cholesterolContent":"27.27 mg","fiberContent":"2.64 g","proteinContent":"9.82 g","sodiumContent":"274.67 mg","sugarContent":"2.87 g","fatContent":"4.62 g","saturatedFatContent":"2.24 g"},"notes":"Chili powder used for cost and nutritional analysis.\nTry topping with chopped green onions or black olives.\nTry adding cilantro on top for more flavor.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"berries-banana-cream","source_url":"https://www.myplate.gov/recipes/berries-banana-cream","name":"Berries with Banana Cream","description":"Make your own \"banana cream\" with yogurt, banana, and fruit juice. Then, add on top of fresh sliced strawberries for a delicious dessert or snack. Add honey ...","ingredients":[{"name":null,"items":["1/3 cup yogurt, low-fat plain","1/2 banana, ripe","1/2 ounce 100% fruit juice (orange works well)","2 cups sliced strawberries","1 teaspoon honey","1/8 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Combine yogurt, banana, and juice and mash with a fork until most chunks are gone.","Wash and slice strawberries.","Top the berries with the yogurt banana mixture.","Top with honey and cinnamon."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"61.36 kcal","carbohydrateContent":"12.55 g","cholesterolContent":"1.21 mg","fiberContent":"1.68 g","proteinContent":"1.70 g","sodiumContent":"21.72 mg","sugarContent":"9.60 g","fatContent":"0.54 g","saturatedFatContent":"0.22 g"},"notes":"Honey should not be fed to children under 1 year of age.","contributor":"Iowa Department of Public Health\nIowa Nutrition Network"},
{"slug":"berry-bread-pudding","source_url":"https://www.myplate.gov/recipes/berry-bread-pudding","name":"Berry Bread Pudding","description":"This no-cook variation of bread pudding, uses bread, berries, yogurt, and time to create a pudding style dish.","ingredients":[{"name":null,"items":["1 1/2 cups berries, unsweetened frozen blueberries, sliced strawberries, or raspberries, thawed","5 slices whole wheat bread (crusts removed)","sugar (1/2 teaspoon, optional)","vanilla yogurt, low-fat (optional)"]}],"directions":[{"name":null,"steps":["Combine the thawed berries and sugar (if you choose to use the sugar).","Layer a spoonful of berries on the bottom of a small 2 cup deep dish. Cover the berries and the bottom of the dish with a layer of bread. Continue layering berries and bread until the dish is full, finishing with a layer of bread.","Cover the dish with plastic wrap and place a plate or bowl over the top of the berry dish that fits just inside of it. Place a heavy object on top to press down on the fruit and bread layers.","Refrigerate overnight. Check the dish to be sure juice does not run over the top. You may need to replace the heavy object with a lighter one to prevent spills.","Serve with a dollop of vanilla yogurt or a sprinkle of powdered sugar."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"158.98 kcal","carbohydrateContent":"30.97 g","cholesterolContent":"0.00 mg","fiberContent":"5.44 g","proteinContent":"5.39 g","sodiumContent":"181.13 mg","sugarContent":"11.27 g","fatContent":"2.14 g","saturatedFatContent":"0.35 g"},"notes":"In the summer, fresh berries can be used.","contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"berry-good-dessert","source_url":"https://www.myplate.gov/recipes/berry-good-dessert","name":"Berry Good Dessert","description":"Berries and fruit juice give this simple gelatin dessert all the sweetness it needs.","ingredients":[{"name":null,"items":["1 envelope (approximately 2.5 teaspoons) unflavored gelatin","2 cups sliced strawberries","1 cup grape juice"]}],"directions":[{"name":null,"steps":["Wash and slice the berries and then place in a shallow dish (9x9 inch brownie pan works well).","Combine gelatin and grape juice in a small pan and warm over low heat until the gelatin dissolves (about 5 minutes).","Pour gelatin and grape juice over berries and refrigerate until firm (about 1 hour)."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"73.03 kcal","carbohydrateContent":"15.46 g","cholesterolContent":"0.00 mg","fiberContent":"1.47 g","proteinContent":"2.09 g","sodiumContent":"14.65 mg","sugarContent":"12.81 g","fatContent":"0.34 g","saturatedFatContent":"0.02 g"},"notes":"Unflavored gelatin can be found in the same aisle as flavored gelatin.","contributor":"Iowa Department of Public Health\nIowa Nutrition Network"},
{"slug":"better-baking-mix","source_url":"https://www.myplate.gov/recipes/better-baking-mix","name":"Better Baking Mix","description":"From biscuits to pizza dough, this baking mix makes can be used for many recipes.","ingredients":[{"name":null,"items":["4 cups all-purpose flour","4 cups quick rolled oats (or whole wheat flour)","1 1/3 cups non-fat dry milk","4 teaspoons baking powder","1 teaspoon salt"]}],"directions":[{"name":null,"steps":["In a large mixing bowl, stir all ingredients until well mixed.","Store in a closed, covered can or rigid plastic container, or sealed heavy plastic bag.","Label and date the container. Use within 6 months.","Stir lightly before use in recipes."]}],"yield":"9 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup prepared mix","calories":"374.44 kcal","carbohydrateContent":"72.26 g","cholesterolContent":"2.01 mg","fiberContent":"5.10 g","proteinContent":"14.07 g","sodiumContent":"536.02 mg","sugarContent":"5.73 g","fatContent":"2.94 g","saturatedFatContent":"0.53 g"},"notes":"To use old fashioned oats, whirl the oats in a blender about 30 seconds to make smaller flakes.\nBetter Baking Mix is used in the following recipes:\nDrop Biscuits\nEasy-As-A-Mix Pizza\nMuffins\nPancakes\nSugar and Spice Cookies","contributor":"Washington State University Extension"},
{"slug":"black-bean-and-couscous-salad","source_url":"https://www.myplate.gov/recipes/black-bean-and-couscous-salad","name":"Black Bean and Couscous Salad","description":"This simple recipe is perfect for dinner tonight and a packed lunch tomorrow. It''s full of colorful veggies and is filling and tasty.","ingredients":[{"name":null,"items":["1/2 cup chicken broth, low-sodium (or low-sodium vegetable broth)","1/2 cup couscous, uncooked","1 1/2 teaspoons apple cider vinegar","1/2 teaspoon ground cumin","fresh lime juice (1 tablespoon, optional)","1 can (15 ounce) black beans, low-sodium (drained and rinsed)","1/2 medium onion, minced","1/2 medium red or green pepper, minced (minced)","1 cup frozen corn, thawed (or fresh, or low-sodium canned)","fresh cilantro (2 tablespoons chopped, optional)"]}],"directions":[{"name":null,"steps":["Before starting to prepare the recipe: Wash red or green pepper and cilantro (if using). Wash and juice the lime into a small bowl (if using). Drain and rinse the black beans and corn (if using canned corn). Collect, mince, and measure all ingredients.","Bring broth to a boil in a small pot, and stir in couscous.","Cover the pot, and remove it from the heat. Let stand for 5 minutes.","In a large bowl, whisk together oil, vinegar, cumin, and lime juice (if using).","Add beans, onion, red or green pepper, and corn to the vinegar and oil mixture, and toss.","Fluff the couscous well with a fork, breaking up any chunks. Add to beans and vegetables, and mix well.","Taste. Add salt and black pepper if desired.","Add cilantro (if using) and serve.","Refrigerate leftovers within 2 hours. Eat within 3 to 5 days."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"103.93 kcal","carbohydrateContent":"20.20 g","cholesterolContent":"0.00 mg","fiberContent":"4.76 g","proteinContent":"5.35 g","sodiumContent":"82.78 mg","sugarContent":"2.20 g","fatContent":"0.61 g","saturatedFatContent":"0.15 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University"},
{"slug":"black-bean-and-rice-salad","source_url":"https://www.myplate.gov/recipes/black-bean-and-rice-salad","name":"Black Bean and Rice Salad","description":"Full of protein, fiber, and flavor, this salad works well as a side dish or stands alone as a main dish. It can also be made ahead of time and refrigerated. ...","ingredients":[{"name":null,"items":["1/2 cup onion, chopped","1/2 cup bell pepper, chopped (green or red)","1 cup brown rice, cooked and cooled","1 can (15 ounce) black beans, low-sodium, drained and rinsed","1/4 cup rice vinegar (or white wine vinegar or lemon juice)","mustard powder (1/2 teaspoon, optional)","1 clove garlic, chopped (or 1/2 teaspoon garlic powder)","1/2 teaspoon salt","1/4 teaspoon black pepper","2 tablespoons vegetable oil (or cooking oil of choice)"]}],"directions":[{"name":null,"steps":["In a mixing bowl, stir together onion, red or green pepper, rice, and beans.","In a jar with a tight fitting lid, add vinegar, dry mustard, garlic, salt, pepper and vegetable oil. Shake until dressing is evenly mixed.","Pour dressing over bean mixture and stir to mix evenly. Chill for at least one hour. Serve cold as a side dish or main dish."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"235.47 kcal","carbohydrateContent":"33.05 g","cholesterolContent":"0.00 mg","fiberContent":"8.84 g","proteinContent":"8.15 g","sodiumContent":"445.52 mg","sugarContent":"2.04 g","fatContent":"7.83 g","saturatedFatContent":"1.19 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"black-bean-and-sweet-potato-quesadillas","source_url":"https://www.myplate.gov/recipes/black-bean-and-sweet-potato-quesadillas","name":"Black Bean and Sweet Potato Quesadillas","description":"Enjoy a simple twist on the classical quesadilla. These quesadillas can be served as a tasty lunch, dinner, or side dish.","ingredients":[{"name":null,"items":["2 sprays of nonstick cooking spray","1 small onion, chopped","1 clove garlic, minced","1 medium sweet potato, cooked and cut into pieces","1 cup black beans, canned low-sodium","1 1/2 teaspoons ground cumin","1 1/2 teaspoons paprika","1/2 large jalapeno pepper","4 whole wheat tortillas","1/2 cup baby spinach","1/4 cup cheddar cheese, reduced-fat","sour cream, low-fat (2 Tablespoons optional or reduced fat plain yogurt)"]}],"directions":[{"name":null,"steps":["Sauté onion and garlic (using nonstick cooking spray) in a medium size pan until soft.","Add sweet potatoes, black beans, garlic, onions, spices, and jalapeno.","Heat until just warm.","Spread potato mixture over tortilla, then top with baby spinach and cheese.","Fold tortilla in half.","Heat a pan on high heat and spray with nonstick cooking spray.","Brown quesadilla about one minute on each side until the inside is warm and the cheese is melted."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Quesadilla","calories":"263.94 kcal","carbohydrateContent":"40.85 g","cholesterolContent":"5.37 mg","fiberContent":"10.53 g","proteinContent":"11.32 g","sodiumContent":"421.03 mg","sugarContent":"4.68 g","fatContent":"6.56 g","saturatedFatContent":"3.21 g"},"notes":null,"contributor":"Bronson Wellness Center\nBronson Healthcare - Michigan"},
{"slug":"black-bean-burgers","source_url":"https://www.myplate.gov/recipes/black-bean-burgers","name":"Black Bean Burgers","description":"Black beans and cooked rice are used as the base of these delicious burgers. Flavored with scallions, garlic, and spices, these are sure to please the whole ...","ingredients":[{"name":null,"items":["1 can (15.5 oz) low-sodium black beans (drained and rinsed with cold water)","1 large egg","1/2 cup cooked brown rice","2 scallions (green and white minced about 1/4 cup)","2 tablespoons chopped fresh cilantro (or basil leaves or a combination)","1 clove garlic (peeled and minced)","1/4 teaspoon dried oregano or basil","1 teaspoon vegetable oil","1/4 teaspoon salt","1/2 teaspoon black pepper","4 whole-wheat buns"]}],"directions":[{"name":null,"steps":["Add beans to a bowl and mash with a fork until chunky. Add the egg and mix well.","Add precooked rice, scallions, garlic and oregano, salt and pepper and mix until well combined.","Divide the mixture into 4 portions and form each portion into a patty about 3/4 to 1 inch thick.","Place a large skillet on the stove on high heat. When the skillet is hot, add oil. Add burgers and cook 4 to 5 minutes per side until browned on both sides and heated throughout. Place on a whole wheat bun."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"3 ounce","calories":"276.89 kcal","carbohydrateContent":"44.73 g","cholesterolContent":"51.38 mg","fiberContent":"9.69 g","proteinContent":"12.56 g","sodiumContent":"538.37 mg","sugarContent":"1.22 g","fatContent":"5.70 g","saturatedFatContent":"1.36 g"},"notes":"Use old-fashioned rolled oats, leftover cooked barley or Panko breadcrumbs instead of prepared rice.\nServe with your favorite toppings such as lettuce, tomato, guacamole, salsa, low-fat cheese, or low-fat yogurt.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"black-bean-burrito","source_url":"https://www.myplate.gov/recipes/black-bean-burrito","name":"Black Bean Burrito","description":"The protein and fiber in this bean and vegetable burrito make it a great breakfast burrito, or enjoy it any time of day.","ingredients":[{"name":null,"items":["1 1/3 cups cooked black beans (mashed, or low-sodium canned)","1 teaspoon canola oil","2 tablespoons onion (chopped)","1/2 cup tomatoes (chopped)","4 corn tortillas","1/2 cup fresh tomato salsa","4 tablespoons yogurt, non-fat plain","2 tablespoons cilantro (chopped)"]}],"directions":[{"name":null,"steps":["Mash beans with canola oil and mix with onion and tomatoes.","Microwave tortillas between the two sheets of slightly damp white paper towels on high for 15 seconds.","Divide bean mixture between the tortillas.","Fold each tortilla to enclose filling.","Place on microwave-safe dish and spoon salsa over each burrito.","Microwave on high for 15 seconds.","Serve topped with yogurt and cilantro."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 burrito","1/4 of recipe"],"calories":"164.35 kcal","carbohydrateContent":"29.33 g","cholesterolContent":"0.31 mg","fiberContent":"7.97 g","proteinContent":"7.74 g","sodiumContent":"268.59 mg","sugarContent":"3.13 g","fatContent":"2.34 g","saturatedFatContent":"0.30 g"},"notes":null,"contributor":"Healthy Recipes\nMichigan Department of Community Health"},
{"slug":"black-bean-quesadillas","source_url":"https://www.myplate.gov/recipes/black-bean-quesadillas","name":"Black Bean Quesadillas","description":"Enjoy a quesadilla any night of the week! This quesadilla recipe can be served as a tasty lunch, dinner, or side dish.","ingredients":[{"name":null,"items":["3/4 cup chunky salsa (or pico de gallo)","1 can (15.5 oz) low-sodium black beans (drained and rinsed)","2 cups shredded reduced-fat Colby & Monterey Jack cheese","2 tablespoons fresh cilantro (finely chopped)","4 flour tortillas (8 inch)","1/2 teaspoon extra virgin olive oil"]}],"directions":[{"name":null,"steps":["Using a small-hole strainer, drain liquid from salsa; discard liquid.","Transfer leftover tomato mixture to a medium bowl.","Mix in black beans, cheese, and cilantro until combined.","Divide black bean mixture evenly over half of each tortilla (about 1/2 cup each).","Fold tortillas in half.","Heat large griddle or skillet over medium-high heat.","Brush with oil.","Place filled tortillas on a griddle.","Cook, carefully flipping once, until tortillas are gold brown and crisp and cheese filling melts, about 5 minutes.","Cut quesadillas into wedges."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"213.91 kcal","carbohydrateContent":"20.72 g","cholesterolContent":"21.47 mg","fiberContent":"6.13 g","proteinContent":"13.31 g","sodiumContent":"489.40 mg","sugarContent":"1.23 g","fatContent":"8.44 g","saturatedFatContent":"4.75 g"},"notes":"Serves 8 as a side dish.\nServing suggestions: For a wholesome dinner, serve with Tasty Lemon and Herb Chicken, Brown Rice with Vegetables, and a piece of fruit for dessert.","contributor":"The Best of La Cocina GOYA: Healthy, Tasty, Affordable Latin Cooking/ Lo Mejor de la Cocina GOYA: Cocina Latina Saludable, Rica y Económica\nGOYA Foods"},
{"slug":"black-bean-salsa","source_url":"https://www.myplate.gov/recipes/black-bean-salsa","name":"Black Bean Salsa","description":"This salsa uses fresh and canned vegetables that are available year-round and add flavor and beautiful color. Kids and grown-ups alike can''t resist how good ...","ingredients":[{"name":null,"items":["1 can (15.5 ounces) black beans, low-sodium (drained and rinsed)","2 cans (14.5 ounces) diced tomatoes, low-sodium (drained)","1 green bell pepper (diced)","1 red bell pepper (diced)","1 onion (diced)","2 cloves garlic (diced)","2 teaspoons ground cumin","1 teaspoon dried cilantro","3 tablespoons rice vinegar (can use other vinegar such as red wine vinegar or apple cider vinegar)"]}],"directions":[{"name":null,"steps":["Drain and rinse beans.","Put beans and canned tomatoes into large mixing bowl.","Dice peppers, onion, and garlic. Add to mixing bowl.","Mix cumin, cilantro, and vinegar. Pour on top of beans and vegetables.","Stir well."]}],"yield":"26 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 Tablespoons","calories":"26.23 kcal","carbohydrateContent":"5.05 g","cholesterolContent":"0.00 mg","fiberContent":"2.07 g","proteinContent":"1.46 g","sodiumContent":"27.37 mg","sugarContent":"1.50 g","fatContent":"0.20 g","saturatedFatContent":"0.03 g"},"notes":"Serve with baked whole grain tortilla chips.","contributor":"Cornell University Cooperative Extension"},
{"slug":"black-bean-soup-0","source_url":"https://www.myplate.gov/recipes/black-bean-soup-0","name":"Black Bean Soup","description":"Black beans, carrots, celery, and seasonings are simmered into this hearty soup. Bring out the delicious flavors with a splash of lime juice and spoonful of ...","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of your choice)","1 onion (chopped)","2 carrots (diced)","2 celery sticks (diced)","4 garlic cloves (peeled and minced)","1 teaspoon dried basil","1 teaspoon dried oregano","2 teaspoons chili powder (or more to taste)","3 cans low-sodium black beans (14.5-ounce cans, drained and rinsed, or use 6 cups cooked (dried) black beans)","8 cups water","1 cube low-sodium chicken bouillon","1 lime (juiced)","plain low-fat yogurt (optional)"]}],"directions":[{"name":null,"steps":["Place a large pot on the stove over medium heat, add the oil when it''s hot. Add the onion, carrots, celery, garlic, basil, oregano, and chili powder and cook about 10 minutes until the onion is soft.","Add the beans, water, and bouillon cube and raise the heat to high and bring to a boil. Turn the heat down to low and cook about 30 minutes or until the beans are very tender.","Just before serving, squeeze the juice of 1/4 lime on each serving and a tablespoon of yogurt.","If you want a pureed soup, set the soup aside to cool for about 20 minutes. Put 2 cups soup in a blender and put the top on, halfway (this will allow the soup to expand and any steam to escape) and blend until smooth. Transfer to a large container. Repeat using the rest of the soup."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2.5 cups","calories":"319.68 kcal","carbohydrateContent":"50.49 g","cholesterolContent":"0.09 mg","fiberContent":"19.75 g","proteinContent":"16.60 g","sodiumContent":"436.88 mg","sugarContent":"3.52 g","fatContent":"6.75 g","saturatedFatContent":"1.06 g"},"notes":"Garnish black bean soup with lime slices, chopped fresh cilantro, basil leaves, or scallions.","contributor":null},
{"slug":"black-bean-soup","source_url":"https://www.myplate.gov/recipes/black-bean-soup","name":"Black Bean Soup","description":"Cumin, onion powder, oregano, and garlic pack a flavorful punch in this bean soup.","ingredients":[{"name":null,"items":["1 cup medium onion, chopped","3/4 cup celery, chopped","2 teaspoons garlic, chopped","1 1/2 cups low-sodium beef broth, fat removed","2 cans (15 ounces each) low-sodium black beans, drained and rinsed","1/2 cup thick and chunky salsa","1 1/2 teaspoons cumin","1/2 teaspoon onion powder","1/4 teaspoon dried oregano"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a medium or large saucepan.","Cover and simmer for 20 to 25 minutes or until vegetables are tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cups","calories":"231.28 kcal","carbohydrateContent":"42.34 g","cholesterolContent":"0.00 mg","fiberContent":"16.31 g","proteinContent":"14.95 g","sodiumContent":"633.09 mg","sugarContent":"3.36 g","fatContent":"1.03 g","saturatedFatContent":"0.25 g"},"notes":null,"contributor":"Good Food Cookbook: A Special Collection of Quick and Healthy Bean Recipes\nCornell Cooperative Extension of Onondaga County"},
{"slug":"black-beans","source_url":"https://www.myplate.gov/recipes/black-beans","name":"Black Beans","description":"Pair these black beans with some brown rice and a green salad for a complete and delicious meal.","ingredients":[{"name":null,"items":["2 cans (15.5 ounces each) low-sodium black beans","1/2 medium onion","2 garlic cloves","2 tablespoons vegetable oil (or cooking oil of choice)","1/2 teaspoon ground cumin","salt (1/2 teaspoon, optional)","1/4 teaspoon dried oregano (or fresh)"]}],"directions":[{"name":null,"steps":["Carefully drain the juice from one can of black beans. Pour the drained black beans into a bowl. Use a potato masher to mash the beans until they are no longer whole. Set the mashed beans aside.","Chop the onion in to 1/4-inch pieces. Set it aside. Peel the garlic cloves and mince them finely. Set the garlic aside.","In a medium saucepan, heat the oil over medium high heat. Add the onions and sauté for 1 to 2 minutes. Stir in the garlic and cumin and cook for 30 seconds more.","Stir in the mashed black beans and the second can of black beans, including the juice. When the beans begin to boil, reduce the heat to low, stir in the salt, if using, and oregano and simmer for 10 minutes, uncovered."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"274.01 kcal","carbohydrateContent":"38.74 g","cholesterolContent":"0.00 mg","fiberContent":"15.60 g","proteinContent":"13.62 g","sodiumContent":"304.78 mg","sugarContent":"1.32 g","fatContent":"7.74 g","saturatedFatContent":"1.15 g"},"notes":null,"contributor":"Kids a Cookin’\nKansas Family Nutrition Program and the USDA Food Stamp Nutrition Education Program\nRecipe by Lynn Walters and Jane Stacey"},
{"slug":"black-eyed-pea-and-collard-greens-soup","source_url":"https://www.myplate.gov/recipes/black-eyed-pea-and-collard-greens-soup","name":"Black-Eyed Pea and Collard Greens Soup","description":"This hearty and delicious soup will make a great meal on a cold night. Serve with some whole wheat bread and a salad for an easy weekday dinner.","ingredients":[{"name":null,"items":["3 cups collard greens, stems removed and chopped (about 1/2 pound)","4 cups no-salt added black-eyed peas (or 2 cans -15 ounce each)","1 tablespoon vegetable oil (or cooking oil of choice)","1 medium onion (chopped)","1/8 teaspoon garlic powder","1/4 pound deli ham (sliced)","1 can low-sodium broth (14.5 ounce - chicken or vegetable)","salt and pepper to taste (optional)","2 teaspoons apple cider vinegar"]}],"directions":[{"name":null,"steps":["Wash the collard greens.*","Drain and rinse the black-eyed peas.","Collect, chop, dice, and measure all ingredients before starting to prepare the recipe.","Place oil, onion, garlic, and ham in a large pot with a lid over medium heat. Stir occasionally until onion is clear, about 3 to 5 minutes.","Add collard greens and broth to the pot.","Cover and simmer for about 20 minutes until the collard greens are tender.","Place half of the black-eyed peas in a small bowl, and mash with a fork. Stir the mashed and whole peas into the soup. Simmer for another 5 minutes.","Taste, and add a small amount of salt and black pepper if desired.","Stir in vinegar just before serving.","Refrigerate leftovers within 2 hours. Eat within 3 to 5 days."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"218.24 kcal","carbohydrateContent":"31.40 g","cholesterolContent":"7.75 mg","fiberContent":"8.58 g","proteinContent":"15.11 g","sodiumContent":"227.80 mg","sugarContent":"6.30 g","fatContent":"4.36 g","saturatedFatContent":"0.72 g"},"notes":"* Preparing collard greens: First, remove any damaged outer leaves. Fill a large bowl with cold water, and dunk the greens. Swish them around for a few minutes to help loosen any dirt on the leaves. Pour out the dirty water and fill the bowl with clean water. Swish the leaves under the clean water again to remove any additional dirt. Continue this process until the water in the bowl remains clear. To cut collard greens, fold each leaf in half with the stem at the fold crease. Either cut or tear the stem off. Stack several leaves on top of each other and roll the leaves up. Cut the roll of leaves in 1 inch thick pieces.\nBe Creative! - Top with shredded cheese!","contributor":"Eating Smart, Being Active\nColorado State University Extension"},
{"slug":"black-skillet-beef-greens-and-red-potatoes","source_url":"https://www.myplate.gov/recipes/black-skillet-beef-greens-and-red-potatoes","name":"Black Skillet Beef with Greens and Red Potatoes","description":"This is an easy, filling meal with carrots, kale, and potatoes that can be made in a single dish.","ingredients":[{"name":null,"items":["1 pound beef, top round","1 tablespoon paprika","1 1/2 teaspoons oregano","1/2 teaspoon chili powder","1/4 teaspoon garlic powder","1/4 teaspoon black pepper","1/8 teaspoon crushed red pepper","1/8 teaspoon dry mustard","non-stick cooking spray","8 medium red-skinned potatoes, halved","3 cups onions, finely chopped","2 cups beef broth. reduced-sodium","2 large garlic cloves, minced","2 large carrots, peeled, cut into very thin 2 1/2 inch strips","4 cups kale (1 bunch)"]}],"directions":[{"name":null,"steps":["Partially freeze beef. Thinly slice across the grain into long strips 1/8 inch thick and 3 inches wide.","Combine paprika, oregano, chili powder, garlic powder, black pepper, red pepper, and dry mustard. Coat strips of meat with the spice mixture.","Spray a large heavy skillet nonstick cooking spray. Preheat pan over high heat.","Add meat; cook, stirring for 5 minutes.","Add potatoes, onion, broth, and garlic. Cook covered, over medium heat for 20 minutes.","Stir in carrots, lay greens over top and cook, covered, until carrots are tender, about 15 minutes.","Serve in large serving bowl, with crusty bread for dunking."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"7 ounces (538g)","calories":"382.85 kcal","carbohydrateContent":"56.93 g","cholesterolContent":"49.26 mg","fiberContent":"7.60 g","proteinContent":"21.95 g","sodiumContent":"256.99 mg","sugarContent":"8.06 g","fatContent":"8.55 g","saturatedFatContent":"3.20 g"},"notes":null,"contributor":"Stay Young at Heart: Cooking the Heart-Healthy Way\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"blue-corn-pan-bread","source_url":"https://www.myplate.gov/recipes/blue-corn-pan-bread","name":"Blue Corn Pan Bread","description":"This traditional Native American dish uses blue cornmeal and sprouted wheat. Many health benefits have been noted for different sprouted grains, and the ingr...","ingredients":[{"name":null,"items":["3 cups water","2 cups blue cornmeal (yellow may be used)","1 cup yellow cornmeal","3/4 cup raisins","1/2 cup sprouted wheat","1/3 cup brown sugar (packed)"]}],"directions":[{"name":null,"steps":["Preheat oven to 300 °F. Line 8x8 inch cake pan with foil.","Bring water to boil in a large pot. Add each ingredient, one at a time.","Stir well until mixture is smooth and pour into foil-lined cake pan. Cover with a piece of aluminum foil.","Bake for 2 hours. Bread is done when toothpick inserted in center comes out clean."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 piece approx. 2x2.5\"","calories":"230.62 kcal","carbohydrateContent":"49.53 g","cholesterolContent":"0.00 mg","fiberContent":"4.68 g","proteinContent":"5.50 g","sodiumContent":"14.38 mg","sugarContent":"13.81 g","fatContent":"2.03 g","saturatedFatContent":"0.31 g"},"notes":"To sprout wheat: Wash untreated wheat grains; drain, but do not dry. Spread in a single layer in shallow pans and cover with damp cloths. Keep damp in a warm, dark place.","contributor":"A River of Recipes: Native American Recipes Using Commodity Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"blue-cornmeal-pancakes","source_url":"https://www.myplate.gov/recipes/blue-cornmeal-pancakes","name":"Blue Cornmeal Pancakes","description":"This blue cornmeal pancake is easy to make and a delicious way to start your day!","ingredients":[{"name":null,"items":["3/4 cup blue cornmeal","1/4 teaspoon salt","1 cup water, boiling","1/2 cup milk","2 tablespoons margarine, melted","1 egg (or 2 tablespoons egg mix + 1/4 cup water)","3/4 cup flour","2 teaspoons baking powder","Cooking spray","Light syrup or honey (optional)"]}],"directions":[{"name":null,"steps":["In a large bowl, mix the cornmeal and salt. Stir in the boiling water until the ingredients are wet. Cover and let stand for 3 minutes.","In a separate bowl, mix the milk, melted margarine, and egg or egg mix and water mixture. Add to the cornmeal mixture.","Add flour and baking powder to the bowl and mix until combined.","Heat a large skillet over medium heat and spray with cooking spray.","Spoon ¼ cup of the batter on the skillet. When bubbles appear, flip, and cook the other side until golden brown. Serve with syrup, honey, yogurt, or fresh fruit if desired."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"94.56 kcal","carbohydrateContent":"14.20 g","cholesterolContent":"17.63 mg","fiberContent":"1.05 g","proteinContent":"2.68 g","sodiumContent":"158.96 mg","sugarContent":"0.71 g","fatContent":"3.02 g","saturatedFatContent":"0.65 g"},"notes":"This recipe contains one or more ingredients considered to be traditional or indigenous to Native American communities in certain regions across North America.","contributor":"Recipe adapted from Chickasaw Nation Nutrition Services, Get Fresh Initiative"},
{"slug":"blueberry-baked-oats","source_url":"https://www.myplate.gov/recipes/blueberry-baked-oats","name":"Blueberry Baked Oats","description":"Blueberry Baked Oats are a cozy, delicious way to start your day, especially as the weather gets chilly. Break out your ramekins – this recipe makes four l...","ingredients":[{"name":null,"items":["2 eggs","2 cups dry quick-cooking rolled oats","1 cup 1% milk","1 teaspoon baking powder","1/4 teaspoon salt","2 large bananas","1 cup fresh or frozen blueberries","2 tablespoons honey","1 teaspoon vanilla extract","1/2 cup fresh blueberries, divided","1 cup fat-free plain Greek yogurt","1 tablespoon lemon zest"]}],"directions":[{"name":null,"steps":["Preheat oven to 350°F. Grease four 8-oz ramekins.","In a blender on high speed, blend eggs, oats, milk, baking powder and salt until the mixture is puréed and mixture resembles pancake batter. Add bananas, blueberries, honey, and vanilla; pulse until puréed to smoothie texture.","Divide oats mixture among ramekins, filling about ¾ of the way full then divide ¼ cup fresh blueberries over top. Transfer ramekins to a baking sheet.","Bake for 25 to 30 minutes or until golden around the edges and puffed. Let cool for 5 minutes before serving.","Serve baked oats with dollops of Greek yogurt, remaining fresh blueberries and garnish with lemon zest."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"377.63 kcal","carbohydrateContent":"64.10 g","cholesterolContent":"108.86 mg","fiberContent":"6.64 g","proteinContent":"17.69 g","sodiumContent":"351.08 mg","sugarContent":"29.44 g","fatContent":"6.27 g","saturatedFatContent":"1.75 g"},"notes":"If using frozen blueberries, make sure to rinse and thaw before use.","contributor":"Created by U.S. Highbush Blueberry Council, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"blueberry-chicken-pasta-salad-field-greens","source_url":"https://www.myplate.gov/recipes/blueberry-chicken-pasta-salad-field-greens","name":"Blueberry Chicken Pasta Salad with Field Greens","description":"Lively mix of fresh blueberries, red pepper, whole-grain penne pasta and field greens tossed with a blueberry vinaigrette.","ingredients":[{"name":"For the Blueberry Vinaigrette","items":["1/2 cup fresh blueberries","2 tablespoons extra virgin olive oil","2 tablespoons balsamic vinegar","1/2 teaspoon Dijon mustard","2 teaspoons honey","1/4 teaspoon salt"]},{"name":"For the Salad","items":["1 1/2 cups fresh blueberries","3 cups cooked whole grain penne pasta (cooled)","12 ounces cooked chicken breast (sliced)","4 cups field greens","1/2 cup red onion (chopped)","1 medium red bell pepper (chopped)"]}],"directions":[{"name":null,"steps":["Blend vinaigrette ingredients in a blender, set aside.","In a medium size bowl, toss all ingredients with dressing."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"433.62 kcal","carbohydrateContent":"49.73 g","cholesterolContent":"84.03 mg","fiberContent":"7.34 g","proteinContent":"33.80 g","sodiumContent":"218.27 mg","sugarContent":"13.78 g","fatContent":"12.29 g","saturatedFatContent":"2.05 g"},"notes":"Weekly Meal Planning Tip: When you''re planning a dinner with chicken cook up extra chicken breast and refrigerate for use in this salad.","contributor":"Produce for Better Health Foundation"},
{"slug":"blueberry-coffee-cake","source_url":"https://www.myplate.gov/recipes/blueberry-coffee-cake","name":"Blueberry Coffee Cake","description":"A delicious addition to your breakfast table, or enjoy a slice as an afternoon snack. Fresh berries work well, but if they aren’t available or in season, t...","ingredients":[{"name":null,"items":["1 egg","1/2 cup fat-free (skim) milk","1/2 cup fat-free vanilla yogurt","3 tablespoons canola oil (or cooking oil of choice)","2 teaspoons lemon peel, grated (yellow only)","1/4 teaspoon cinnamon","2 cups all purpose flour","1/2 cup sugar","4 teaspoons baking powder","1/2 teaspoon salt","1 1/2 cups fresh blueberries (or frozen unsweetened)"]},{"name":"Topping Ingredients","items":["3 tablespoons sugar","1/8 cup walnuts, coarsely chopped"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F. Position rack in the center of the oven.","In a large bowl whisk together the egg, milk, yogurt, oil and lemon peel.","Sift the cinnamon, flour, sugar, baking powder and salt onto the liquid ingredients. Using a fork, stir very lightly, just until ingredients are combined.","Gently fold in the blueberries. Pour the batter into an 8- or 9-inch baking pan coated with nonstick spray.","In a small bowl combine the topping ingredients. Sprinkle evenly over the cake batter.","Bake a 400 °F for 30 to 35 minutes or until the top is lightly browned and a wooden toothpick inserted in the center comes out clean.","Allow the cake to cool in the baking pan on a wire rack for at least 10 minutes.","Serve warm or at room temperature."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"284.59 kcal","carbohydrateContent":"48.50 g","cholesterolContent":"26.45 mg","fiberContent":"1.75 g","proteinContent":"5.89 g","sodiumContent":"418.30 mg","sugarContent":"22.49 g","fatContent":"7.64 g","saturatedFatContent":"0.75 g"},"notes":"When tightly wrapped in plastic wrap, this coffee cake will keep for 3 to 4 days in the refrigerator. It also freezes very well.","contributor":"California’s Chefs Cook Lean, Adapted from Lo''s Blueberry Coffee Cake\nCalifornia Department of Health Services"},
{"slug":"blueberry-muffins","source_url":"https://www.myplate.gov/recipes/blueberry-muffins","name":"Blueberry Muffins","description":"Make your own muffins from scratch with this recipe. If fresh blueberries are unavailable or costly, try using frozen blueberries.","ingredients":[{"name":null,"items":["1/2 cup vegetable oil (or cooking oil of choice)","1 cup sugar","2 eggs","1/2 cup milk, low-fat, 1%","1 teaspoon vanilla","2 cups flour","2 teaspoons baking powder","1/2 teaspoon salt","2 cups blueberries (fresh or frozen)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 375 °F.","Grease the muffin pans.","In a large mixing bowl, stir the oil and sugar until creamy.","Add eggs, milk and vanilla. Mix until blended.","In a medium mixing bowl, stir together the flour, baking powder, and salt.","Add the flour mix to the oil and sugar in the large bowl. Stir together.","Stir the blueberries into the batter.","Fill each muffin cup 2/3 full with batter.","Bake for 25 to 30 minutes."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"258.62 kcal","carbohydrateContent":"36.99 g","cholesterolContent":"34.76 mg","fiberContent":"1.16 g","proteinContent":"3.71 g","sodiumContent":"195.21 mg","sugarContent":"19.74 g","fatContent":"10.60 g","saturatedFatContent":"1.64 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"bosnian-pot","source_url":"https://www.myplate.gov/recipes/bosnian-pot","name":"The Bosnian Pot","description":"This hearty beef and vegetable stew is a filling meal on a cold evening. Serve with whole wheat pita bread.","ingredients":[{"name":null,"items":["2 1/4 pounds beef stew meat","1 head cabbage","2 1/2 large carrots (2 or 3)","3 1/2 large fresh tomatoes","3 1/2 large potatoes","2 medium onions","2 garlic cloves","2 green peppers","1/2 tablespoon vegetable oil (or cooking oil of your choice)","1/2 tablespoon vinegar","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Chop all the vegetables.","Combine with the meat and seasonings in a large pot.","Add enough water to completely cover the mixture and add the oil and vinegar.","Cook, covered, for two to three hours on low heat until everything is well done."]}],"yield":"10 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe (411g)","calories":"323.81 kcal","carbohydrateContent":"34.65 g","cholesterolContent":"66.50 mg","fiberContent":"6.02 g","proteinContent":"23.53 g","sodiumContent":"83.95 mg","sugarContent":"7.72 g","fatContent":"11.22 g","saturatedFatContent":"4.15 g"},"notes":"Bosnian cuisine contains lots of fresh produce. Tomatoes, peppers, carrots, and beans are common in everyday menus.\nTo reduce cost, frozen and/or canned vegetables can be substituted for fresh vegetables.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"braised-chicken-thighs-spinach","source_url":"https://www.myplate.gov/recipes/braised-chicken-thighs-spinach","name":"Braised Chicken Thighs with Spinach","description":"Chicken thighs are cooked until golden brown then simmered in a rich onion, garlic, thyme, and rosemary sauce with tender spinach.","ingredients":[{"name":null,"items":["4 boneless, skinless chicken thighs","1 teaspoon vegetable oil","1/2 teaspoon salt","1/2 teaspoon black pepper","1 small yellow onion, chopped","3 cloves garlic, minced","1 teaspoon dried thyme","1/2 teaspoon dried rosemary","1 cup water","1 package 10-ounce frozen spinach (or 1 bunch fresh spinach)"]}],"directions":[{"name":null,"steps":["Heat skillet over medium-high heat. Add 1 teaspoon oil. Add chicken, top side down. Cook on each side until deeply browned. Remove the chicken to a plate and set aside.","Reheat skillet over medium heat. Add the onion, garlic, thyme, and rosemary. Cook about 5 minutes until the onion is soft and golden. Return the chicken to the pan.","Add the water and cover. Continue cooking for about 30 minutes.","Add frozen spinach and cook for about 10 minutes. Or, add the fresh spinach and cook about 2 minutes, until it wilts. Serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"233.67 kcal","carbohydrateContent":"8.02 g","cholesterolContent":"132.57 mg","fiberContent":"3.59 g","proteinContent":"28.17 g","sodiumContent":"473.77 mg","sugarContent":"1.96 g","fatContent":"10.02 g","saturatedFatContent":"2.63 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"bran-flake-raisin-muffins","source_url":"https://www.myplate.gov/recipes/bran-flake-raisin-muffins","name":"Bran Flake Raisin Muffins","description":"Try these bran and whole wheat muffins for a quick and healthy start to your day.","ingredients":[{"name":null,"items":["1/2 cup all purpose flour","3/4 cup whole wheat flour","1/4 teaspoon salt","2 teaspoons baking soda","1/2 cup sugar","1 3/4 cups bran flake cereal with raisins","1 egg","1 cup buttermilk","2 tablespoons vegetable oil (or cooking oil of choice)"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 °F. Spray or grease the bottoms of a muffin tin.","Put flour in a large bowl. Add salt, baking soda, and sugar. Mix well.","Stir in the bran flake cereal. Mix well.","Make a well in the center of mixture and set aside.","In another bowl, beat the egg, buttermilk, and oil together.","Pour the egg mixture into the well of the cereal mixture and stir until all ingredients are moist. Do not over mix.","Fill the tins 2/3 full.","Bake for 15-20 minutes or until golden brown.","If not eaten right away, wrap the baked muffins in foil or a plastic bag and store in the freezer. Thaw for 15 seconds in the microwave or overnight in the refrigerator."]}],"yield":"10 Muffins","nutrition":{"@type":"NutritionInformation","servingSize":"1 muffin","calories":"177.99 kcal","carbohydrateContent":"30.71 g","cholesterolContent":"23.23 mg","fiberContent":"2.43 g","proteinContent":"4.09 g","sodiumContent":"379.64 mg","sugarContent":"14.31 g","fatContent":"4.55 g","saturatedFatContent":"1.07 g"},"notes":"Substitute for buttermilk: Add 1 tablespoon vinegar or lemon juice to 1 cup milk.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"bran-muffins","source_url":"https://www.myplate.gov/recipes/bran-muffins","name":"Bran Muffins","description":"Looking for a creative way to cook with breakfast cereal? Look no further than this recipe.","ingredients":[{"name":null,"items":["5 cups all purpose flour","2 teaspoons salt","2 teaspoons baking soda","3 cups sugar","8 cups raisin bran (about 15 oz)","4 eggs, beaten","4 cups buttermilk","1 cup vegetable oil (or cooking oil of choice)","sprays of vegetable oil spray (or oil)"]}],"directions":[{"name":null,"steps":["Measure flour into a large bowl.","Add salt, soda, sugar and raisin bran to the flour and mix well with spoon.","With a spoon make a \"well\" in the center of the dry ingredients.","In the medium size bowl, beat the eggs with a fork until whites and yolk are evenly blended.","Add milk and oil to eggs. Beat with fork.","Add liquid to dry ingredients. Stir until dry ingredients are moistened (mixture will be lumpy).","Lightly oil the bottoms of the paper cups in the muffin pan (or use muffin cups). Fill the muffin cups to 3/4 full.","Bake at 425 °F for 15-20 minutes.","Baked muffins can be frozen for future use."]}],"yield":"30 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/30 of recipe","calories":"309.42 kcal","carbohydrateContent":"50.06 g","cholesterolContent":"30.98 mg","fiberContent":"2.55 g","proteinContent":"5.32 g","sodiumContent":"340.18 mg","sugarContent":"26.31 g","fatContent":"9.66 g","saturatedFatContent":"1.91 g"},"notes":null,"contributor":"Quick and Healthy Meals: Tips and Tools for Planning Meals for Your Family\nOhio State University Cooperative Extension\nCuyahoga County"},
{"slug":"brazilian-rice","source_url":"https://www.myplate.gov/recipes/brazilian-rice","name":"Brazilian Rice","description":"The vegetarian dish combines leafy greens and high fiber brown rice to make a wholesome side dish or a satisfying main dish.","ingredients":[{"name":null,"items":["sprays of nonstick vegetable spray","1 package (10 ounce) frozen spinach, thawed","1 cup brown rice, cooked","2 tablespoons olive oil (or cooking oil of choice)","1 cup egg-white substitute, liquid","3/4 cup mozzarella cheese, shredded fat-free","1 cup fat-free milk","1/2 medium onion, chopped","1/2 teaspoon Worcestershire sauce","1/4 teaspoon dried marjoram","1/4 teaspoon dried thyme","1/4 teaspoon dried rosemary"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Spray a 2-quart baking dish with vegetable oil spray.","Place thawed spinach in a colander and press to remove excess water.","Place the spinach in a large mixing bowl and add remaining ingredients. Mix until combined.","Transfer the mixture to the baking dish and place in the preheated oven. Bake for 30 minutes.","Cut the casserole into eight squares and serve."]}],"yield":"8","nutrition":{"@type":"NutritionInformation","calories":"108.43"},"notes":"This casserole can be prepared 1 day in advance and refrigerated.","contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"bread-bag","source_url":"https://www.myplate.gov/recipes/bread-bag","name":"Bread in a Bag","description":"This yeast bread recipe is a great way to engage learners both young and old.","ingredients":[{"name":null,"items":["2 cups all purpose flour (plus extra for kneading)","1 cup whole wheat flour","3 tablespoons powdered milk, nonfat","3 tablespoons sugar","1 teaspoon salt","1 tablespoon rapid rise yeast","3 tablespoons vegetable oil","1 cup warm water, 120 to 130 °F"]}],"directions":[{"name":null,"steps":["Combine flour, whole wheat flour, yeast, sugar, salt and powdered milk in a one gallon resealable freezer bag. Squeeze upper part of bag to force out air and seal bag. Shake and work bag with fingers to blend ingredients.","Add oil and warm water to dry ingredients. Reseal bag. Mix by working bag with fingers until dough is completely mixed and pulls away from bag.","On a floured surface, knead dough 5 minutes or until smooth and elastic, adding flour as needed. Put dough back into bag and let it rest 10 minutes.","Shape dough on greased baking sheet or put into a 4x8 inch greased loaf pan. Cover with a clean cloth or plastic wrap and let rise until doubled in bulk.","Preheat oven to 350 °F and bake for about 30 minutes or until golden brown. (This may take between 25 and 45 minutes to bake.)","Remove from pan and cool on a wire rack or clean dish towel."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of loaf","calories":"160.96 kcal","carbohydrateContent":"27.17 g","cholesterolContent":"0.21 mg","fiberContent":"1.90 g","proteinContent":"4.26 g","sodiumContent":"204.37 mg","sugarContent":"3.77 g","fatContent":"4.05 g","saturatedFatContent":"0.57 g"},"notes":null,"contributor":"Montana State University Recipes\nMontana State University Extension\nNutrition Education Programs"},
{"slug":"bread-bake-chicken-cheese-vegetables","source_url":"https://www.myplate.gov/recipes/bread-bake-chicken-cheese-vegetables","name":"Bread Bake with Chicken, Cheese, and Vegetables","description":"You''ll want to tell everyone about this bread bake that features broccoli, chicken, cheese, onion, eggs, and milk.","ingredients":[{"name":null,"items":["6 slices bread, cubed (approximately 6 cups)","1 1/2 cups broccoli, frozen, chopped and cooked","1 cup cheddar cheese, low-fat shredded","onion, minced (optional, 1 tablespoon)","1 cup cooked chicken, skinless and diced","3 eggs","4 egg whites","2 cups milk, non-fat"]}],"directions":[{"name":null,"steps":["Place half the bread in a well greased 9x9 inch pan.","Top with broccoli, cheese, onion, and meat.","Place remaining bread on top.","In a bowl, mix eggs and milk.","Pour egg mixture over bread in pan.","Cover. Refrigerate overnight or at least 1 hour.","Bake uncovered at 325 °F for 1 to 1 1/4 hours, or until center is firm and lightly browned."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"258.62 kcal","carbohydrateContent":"21.51 g","cholesterolContent":"141.73 mg","fiberContent":"2.04 g","proteinContent":"24.33 g","sodiumContent":"370.08 mg","sugarContent":"6.54 g","fatContent":"8.26 g","saturatedFatContent":"3.62 g"},"notes":null,"contributor":"Adapted from \"Brag About It Bread Bake\" Bread Fact Sheet\nUniversity of Wisconsin Cooperative Extension Service\nA Family Living Program"},
{"slug":"bread-pudding-vanilla-sauce","source_url":"https://www.myplate.gov/recipes/bread-pudding-vanilla-sauce","name":"Bread Pudding with Vanilla Sauce","description":"A vanilla sauce gives this stove-top bread pudding a little extra sweetness.","ingredients":[{"name":null,"items":["1 tablespoon margarine","5 slices whole wheat bread","3 eggs","1/3 cup sugar","1 dash salt","2 cups milk, non-fat, warmed","1 1/2 teaspoons vanilla extract","1/4 cup raisins","1 teaspoon cinnamon (and/or nutmeg)"]},{"name":"Vanilla Sauce","items":["1 tablespoon cornstarch","1/3 cup sugar","1 cup water","1 tablespoon margarine (or butter)","1 1/2 teaspoons vanilla extract"]}],"directions":[{"name":null,"steps":["Melt margarine in a medium sized skillet over low heat.","Tear bread in pieces and spread on bottom of skillet.","Beat eggs and stir in sugar, salt, warmed milk and vanilla. Sprinkle raisins over bread and pour egg mixture over all.","Cover and cook over very low heat for 20 minutes.","Pudding is done when custard is set in the middle.","Allow to cool in the skillet.","Prepare vanilla sauce while pudding cools.","Combine cornstarch and sugar in a small saucepan. Gradually add water, stirring well.","Cook over medium low heat until thick and clear, stirring constantly.","Add margarine and vanilla, stirring until margarine melts. Remove from heat.","Spoon over individual servings of bread pudding.","Refrigerate leftover bread pudding and vanilla sauce within two hours."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"213.62 kcal","carbohydrateContent":"34.68 g","cholesterolContent":"78.93 mg","fiberContent":"1.76 g","proteinContent":"7.37 g","sodiumContent":"196.32 mg","sugarContent":"24.04 g","fatContent":"4.88 g","saturatedFatContent":"1.22 g"},"notes":null,"contributor":"Ohio SNAP-Ed Nutrition Education Program"},
{"slug":"breakfast-burrito-salsa","source_url":"https://www.myplate.gov/recipes/breakfast-burrito-salsa","name":"Breakfast Burrito with Salsa","description":"Start your day off strong with this hearty breakfast burrito made of eggs, vegetables, and a mix of other ingredients.","ingredients":[{"name":null,"items":["4 large eggs","1/8 cup frozen corn (2 tablespoons)","1 tablespoon 1% milk","1/8 cup green pepper, diced (2 tablespoons)","1/4 cup onion, minced","1/16 cup tomatoes, diced (1 tablespoon)","1 teaspoon mustard","1/4 teaspoon garlic powder","hot pepper sauce (optional)","4 (8-inch) flour tortillas","1/4 cup fresh tomato salsa"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a large mixing bowl, blend the eggs, corn, milk, green peppers, onions, tomatoes, mustard, garlic, hot pepper sauce, and salt for 1 minute until eggs are smooth.","Pour egg mixture into a lightly oiled 9x9x2 inch baking dish and cover with foil.","Bake for 20-25 minutes until eggs are set and thoroughly cooked.","Wrap tortillas in plastic and microwave for 20 seconds until warm. Be careful when unwrapping the tortillas -- the steam can be hot.","Cut baked egg mixture into 4 equal pieces and roll 1 piece of cooked egg in each tortilla.","Serve each burrito topped with 2 tablespoons of salsa."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 burrito","1/4 of recipe"],"calories":"224.98 kcal","carbohydrateContent":"26.05 g","cholesterolContent":"205.69 mg","fiberContent":"2.18 g","proteinContent":"10.52 g","sodiumContent":"478.33 mg","sugarContent":"3.10 g","fatContent":"8.73 g","saturatedFatContent":"2.95 g"},"notes":null,"contributor":"Food Family Fun\nUSDA Food and Nutrition Service\nTeam Nutrition"},
{"slug":"breakfast-parfait","source_url":"https://www.myplate.gov/recipes/breakfast-parfait","name":"Breakfast Parfait","description":"This colorful parfait features four types of fruit: fresh, frozen, canned, and dried.","ingredients":[{"name":null,"items":["2 cups pineapple, canned and chopped","1 cup frozen berries, unsweetened and thawed","1 cup yogurt, low-fat vanilla","1 banana, peeled and sliced","1/3 cup raisins"]}],"directions":[{"name":null,"steps":["In glasses or bowls, layer pineapple, berries, yogurt, banana, and raisins."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"192.66 kcal","carbohydrateContent":"43.15 g","cholesterolContent":"3.68 mg","fiberContent":"3.12 g","proteinContent":"4.48 g","sodiumContent":"50.36 mg","sugarContent":"36.61 g","fatContent":"1.43 g","saturatedFatContent":"0.67 g"},"notes":null,"contributor":"University of Illinois Extension Service"},
{"slug":"breakfast-potato-egg-burritos","source_url":"https://www.myplate.gov/recipes/breakfast-potato-egg-burritos","name":"Breakfast Potato and Egg Burritos","description":"These potato and egg burritos are great for breakfast or enjoy them for lunch or even dinner! Enjoy them with your favorite fruit on the side.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","4 cups potatoes, finely chopped","1 medium onion, chopped","1 medium red or green bell pepper, chopped","3 garlic cloves, pressed or finely chopped","2 eggs, beaten","1 teaspoon black pepper","1/2 teaspoon salt","cheddar cheese (1/2 cup grated, optional)","hot sauce (to taste, or salsa, optional)","9 flour tortillas (or corn)"]}],"directions":[{"name":null,"steps":["In a large skillet, heat oil on medium-high setting.","Add potatoes, onion, bell pepper, and garlic. Cook until potatoes are tender, about 10 minutes. Raw potatoes may need longer; check if done with a fork.","Reduce heat to medium setting, spread potato mix out to the sides of the skillet, leaving a space in the middle for the eggs. Add the eggs and scramble them until cooked (do not mix potatoes until eggs are cooked firm). Stir all ingredients together.","Wrap tortillas around the filling and top with salsa and cheese, if using."]}],"yield":"9 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 burrito","calories":"193.57 kcal","carbohydrateContent":"30.65 g","cholesterolContent":"45.67 mg","fiberContent":"2.87 g","proteinContent":"5.83 g","sodiumContent":"395.09 mg","sugarContent":"3.00 g","fatContent":"5.42 g","saturatedFatContent":"1.56 g"},"notes":null,"contributor":"Adapted from Speedy Burritos, Eat Better, Eat Together\nWashington State University"},
{"slug":"brilliant-chili-topped-walnuts","source_url":"https://www.myplate.gov/recipes/brilliant-chili-topped-walnuts","name":"Brilliant Chili Topped with Walnuts","description":"This is a modern take on a family favorite. Featuring toasted walnuts, this chili features three types of protein foods.","ingredients":[{"name":null,"items":["2 tablespoons extra virgin olive oil","1 onion, medium-large, chopped","1 carrot, large, sliced","1/4 teaspoon salt","2 teaspoons cumin","2 tablespoons chili powder","1 pound turkey breast, 85% lean, ground","1 bell pepper, small, red or yellow, minced","2 cans (16-ounce) red kidney beans, low sodium rinsed, drained","2 cans (14.5-ounce) tomatoes, no salt added, chopped or crushed","1 1/2 cups walnuts, lightly toasted, chopped","parsley, flat leaf, chopped (optional)"]}],"directions":[{"name":null,"steps":["Heat olive oil in large, deep pan. Add onion and sauté over medium heat until translucent. Add carrots, salt, and spices; sauté until spices are toasted. Crumble in the ground turkey breast, and sprinkle in the minced bell pepper and cook until the turkey breast is cooked through and becomes white and opaque.","Add the beans and tomatoes, and stir gently so as not to break the beans. Bring to a boil then lower heat and cook, partly covered, over medium-low heat for another 20 minutes.","Serve hot, topped with a sprinkling of walnuts and parsley."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"405.63 kcal","carbohydrateContent":"26.73 g","cholesterolContent":"42.07 mg","fiberContent":"10.65 g","proteinContent":"20.58 g","sodiumContent":"310.77 mg","sugarContent":"6.98 g","fatContent":"26.22 g","saturatedFatContent":"3.98 g"},"notes":null,"contributor":"Created by the California Walnut Commission, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"broccoli-alfredo","source_url":"https://www.myplate.gov/recipes/broccoli-alfredo","name":"Broccoli Alfredo","description":"This dish features whole wheat pasta and reduced fat Parmesan cheese.","ingredients":[{"name":null,"items":["4 cups broccoli, cooked","4 cups whole wheat pasta, cooked","2 1/8 cups low-fat milk, divided (1/8 cup or 2 tablespoons is used later in the recipe)","1 teaspoon dried basil","1/2 teaspoon garlic powder","1 cup reduced-fat Parmesan cheese","2 tablespoons cornstarch","black pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Placed cooked broccoli and pasta in a bowl.","Heat milk over medium heat and then add basil and garlic powder. When hot, add Parmesan cheese.","Mix cornstarch with 2 or 3 tablespoons of milk and add to hot mixture. Heat until thickened.","Pour mixture over pasta and broccoli. Serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"416.01 kcal","carbohydrateContent":"64.50 g","cholesterolContent":"23.70 mg","fiberContent":"11.26 g","proteinContent":"24.64 g","sodiumContent":"358.30 mg","sugarContent":"10.32 g","fatContent":"9.63 g","saturatedFatContent":"4.40 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"broccoli-and-corn-bake","source_url":"https://www.myplate.gov/recipes/broccoli-and-corn-bake","name":"Broccoli and Corn Bake","description":"This recipe will help you make half your plate fruits and vegetables. Serve this broccoli and corn dish warm at any meal.","ingredients":[{"name":null,"items":["1 can (15 ounce) cream-style corn, low-sodium","3 3/4 cups broccoli, cooked","1 egg, beaten","1/2 cup cracker crumbs, crushed","1/4 cup vegetable oil (or cooking oil of choice)"]},{"name":"Topping","items":["6 saltine crackers, crushed","1 tablespoon tub margarine (or butter), melted"]}],"directions":[{"name":null,"steps":["Mix corn, broccoli, egg, cracker crumbs, and oil together in greased 1 1/2 quart casserole.","Mix topping ingredients together in small bowl. Sprinkle over corn mixture.","Bake at 350 °F for 40 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"220.97 kcal","carbohydrateContent":"24.22 g","cholesterolContent":"34.27 mg","fiberContent":"4.52 g","proteinContent":"6.51 g","sodiumContent":"109.05 mg","sugarContent":"4.07 g","fatContent":"12.61 g","saturatedFatContent":"2.02 g"},"notes":null,"contributor":"Kentucky Families on the Move\nUniversity of Kentucky Cooperative Extension Service"},
{"slug":"broccoli-baked-potatoes","source_url":"https://www.myplate.gov/recipes/broccoli-baked-potatoes","name":"Broccoli Baked Potatoes","description":"Use those broccoli stalks in this dish instead of throwing them away. This makes a delicious side, a hearty snack, or a light meal.","ingredients":[{"name":null,"items":["6 medium potatoes","3 broccoli stalks","1/4 cup 1% milk","1 cup cheddar cheese, low-fat shredded, divided","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Scrub potatoes. Prick the skin with a fork in several places.","Baked at 350 °F for 30 to 60 minutes, until soft, depending on size.","Peel broccoli stems. Steam broccoli just until tender and chop into small pieces.","Slices the potatoes in half. Scoop the insides into a bowl with the broccoli. Add milk, 3/4 cup cheese, salt and pepper. Mash together until the mixture is pale green with dark green flecks.","Put the potato mixture into the potato skins and sprinkle with remaining 1/4 cup of cheese. Microwave to heat through."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 potato","1/6 of recipe"],"calories":"231.44 kcal","carbohydrateContent":"38.44 g","cholesterolContent":"14.82 mg","fiberContent":"4.20 g","proteinContent":"10.23 g","sodiumContent":"145.87 mg","sugarContent":"2.82 g","fatContent":"4.22 g","saturatedFatContent":"2.49 g"},"notes":"Potatoes can be microwaved instead of baked. For instructions, see the recipe for Microwave Baked Potato.","contributor":"University of Maryland Cooperative Extension"},
{"slug":"broccoli-cheddar-frittata","source_url":"https://www.myplate.gov/recipes/broccoli-cheddar-frittata","name":"Broccoli-Cheddar Frittata","description":"This egg dish provides a quarter cup serving of vegetables during breakfast and uses reduced-fat cheddar cheese and non-fat milk to limit fat. Prep and cook ...","ingredients":[{"name":null,"items":["1 package (10-oz) frozen chopped broccoli","1/4 cup water","8 eggs","1/4 cup nonfat or low-fat milk","2 teaspoons prepared mustard","3/4 teaspoon seasoned salt","1/8 teaspoon pepper","3/4 cup shredded reduced-fat cheddar cheese (3 ounces)","1 tablespoon chopped green onion","1 small carrot, diced","nonstick cooking spray"]}],"directions":[{"name":null,"steps":["Combine broccoli, carrot (if desired), and water in 10-inch nonstick skillet.","Cook over medium heat until tender, stirring occasionally to break up broccoli, about 10 minutes; drain well.","Beat eggs, milk, mustard, salt, and pepper in large bowl until blended.","Add broccoli mixture, cheese, and green onion; mix well.","Coat same skillet with cooking spray; heat over medium heat until eggs are almost set, 8 to 10 minutes. Remove from heat.","Cover and let stand until eggs are completely set and no visible liquid egg remains, 8 to 10 minutes. Cut into wedges."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"162.27 kcal","carbohydrateContent":"5.16 g","cholesterolContent":"285.04 mg","fiberContent":"1.80 g","proteinContent":"14.13 g","sodiumContent":"504.79 mg","sugarContent":"1.88 g","fatContent":"9.67 g","saturatedFatContent":"3.94 g"},"notes":"Broil option: After removing from heat, frittata can be broiled, 6 inches from heat until eggs are completely set and no visible liquid egg remains, 2 to 3 minutes.\nThree ways to serve a frittata: Serve wedges right from pan, slide uncut frittata topside-up onto platter, or invert it onto platter to show its nicely-browned bottom.\nMaterials: You will ne a 10-inch skillet, large bowl, measuring cups, measuring spoons, mixing spoon, and a sharp knife.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"broccoli-omelet","source_url":"https://www.myplate.gov/recipes/broccoli-omelet","name":"Broccoli Omelet","description":"This omelet is lower in fat and cholesterol than a traditional omelet and stuffed with a vibrant mix of broccoli florets, red bell pepper, and mush...","ingredients":[{"name":null,"items":["3 cups broccoli florets","1 large red bell pepper (cut into strips)","16 button mushrooms (sliced)","cooking spray","4 eggs","8 egg whites (from 8 eggs)","1/4 cup milk (fat-free)","1/2 cup ricotta cheese","2 tablespoons grated Parmesan cheese","1/8 teaspoon salt","1/8 teaspoon pepper"]}],"directions":[{"name":null,"steps":["Cut vegetables as directed.","Whisk eggs and milk in a medium mixing bowl.","Spray 10-inch non-stick skillet with cooking spray; heat.","Add broccoli, peppers, and mushrooms; sauté about 3-5 minutes, then remove from pan."]},{"name":"To cook each omelet","steps":["Use cooking spray as needed.","Add 1/4 of the egg-milk mixture to hot skillet, and let spread to cover bottom of pan.","When egg begins to thicken on top, sprinkle with 1/4 of the Parmesan cheese.","Dab 1/2 of the omelet with ricotta cheese and spread a portion of the vegetable mixture.","Fold the other 1/2 of omelet over the vegetables and let cook about 1 more minute.","Slide onto plate. Season lightly with salt and pepper.","Repeat steps 1-6 to cook all omelets.","Garnish omelets with remaining vegetable sauté mix."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"220.33 kcal","carbohydrateContent":"13.68 g","cholesterolContent":"217.64 mg","fiberContent":"2.69 g","proteinContent":"22.02 g","sodiumContent":"352.27 mg","sugarContent":"4.99 g","fatContent":"8.67 g","saturatedFatContent":"3.60 g"},"notes":"Serving Suggestions: Serve with melon and whole wheat toast.","contributor":"Produce for Better Health Foundation"},
{"slug":"broccoli-potato-soup","source_url":"https://www.myplate.gov/recipes/broccoli-potato-soup","name":"Broccoli Potato Soup","description":"A tasty and made-from-scratch soup that comes together quickly with the help of instant mashed potatoes and powdered milk.","ingredients":[{"name":null,"items":["4 cups broccoli (chopped)","1 small onion (chopped)","4 cups low-sodium chicken broth (can also use vegetable broth)","1 cup non-fat evaporated milk","1/2 cup instant mashed potatoes, prepare with water for 1 cup potatoes (or 1 cup leftover mashed potatoes.)","salt and pepper (to taste, optional)","1/4 cup cheddar cheese, shredded"]}],"directions":[{"name":null,"steps":["Combine broccoli, onion, and broth in large saucepan.","Bring to a boil.","Reduce heat. Cover and simmer about 10 minutes or until vegetables are tender.","Add milk to saucepan. Slowly stir in potatoes.","Cook, stirring constantly, until bubbly and thickened.","Season with salt and pepper; stir in a little more milk or water if soup starts to become too thick.","Ladle into serving bowls.","Sprinkle about 1 tablespoon cheese over each serving."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"194.82 kcal","carbohydrateContent":"25.67 g","cholesterolContent":"9.58 mg","fiberContent":"3.38 g","proteinContent":"14.65 g","sodiumContent":"231.72 mg","sugarContent":"10.65 g","fatContent":"4.35 g","saturatedFatContent":"1.93 g"},"notes":null,"contributor":"Don’t Play With Your Food: Fall and Winter Cookbook\nArizona Nutrition Network"},
{"slug":"broccoli-rice-casserole","source_url":"https://www.myplate.gov/recipes/broccoli-rice-casserole","name":"Broccoli Rice Casserole","description":"Pantry staples and frozen veggies combine to make a hearty, home-made main dish for dinner.","ingredients":[{"name":null,"items":["1 1/2 cups rice, uncooked","3 1/2 cups water, divided","3 tablespoons margarine (or butter)","1 medium onion, chopped","1 can (10.75 ounce) condensed cream of mushroom soup, reduced sodium (or reduced sodium chicken, celery, or cheese soup)","1 1/2 cups 1% milk","7 1/2 cups frozen broccoli or cauliflower or mixed vegetables, chopped","8 ounces low-fat cheddar cheese, grated"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F and grease a 12x9x2 inch baking pan.","In a saucepan, mix rice, salt, and 3 cups of water and bring to a boil.","Cover and simmer for 15 minutes. Remove saucepan from heat and set aside for additional 15 minutes.","Sauté onions in margarine (or butter) until tender.","Mix soup, milk, 1/2 cup of water, onions, and rice. Spoon mixture into baking pan.","Thaw and drain the vegetables and then spread over the rice mixture.","Spread the cheese evenly over the top and bake at 350 °F for 25 to 30 minutes until cheese is melted and rice is bubbly."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"234.29 kcal","carbohydrateContent":"31.53 g","cholesterolContent":"16.67 mg","fiberContent":"4.13 g","proteinContent":"12.15 g","sodiumContent":"266.44 mg","sugarContent":"4.35 g","fatContent":"7.01 g","saturatedFatContent":"3.20 g"},"notes":null,"contributor":"Quick and Healthy Meals: Tips and Tools for Planning Meals for Your Family\nOhio State University Cooperative Extension\nCuyahoga County"},
{"slug":"broccoli-salad","source_url":"https://www.myplate.gov/recipes/broccoli-salad","name":"Broccoli Salad","description":"Chopped broccoli, raisins, onion and crumbled bacon make this colorful salad a tasty side dish.","ingredients":[{"name":null,"items":["6 cups broccoli (chopped)","1 cup raisins","1 red onion (medium, peeled and diced)","2 tablespoons sugar","bacon slices (8 slices, cooked and crumbled, optional)","2 tablespoons lemon juice","3/4 cup light mayonnaise"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a medium bowl, and mix well.","Chill for 1 to 2 hours.","Serve."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"162.32 kcal","carbohydrateContent":"27.20 g","cholesterolContent":"3.75 mg","fiberContent":"2.85 g","proteinContent":"2.65 g","sodiumContent":"223.58 mg","sugarContent":"19.11 g","fatContent":"5.52 g","saturatedFatContent":"0.86 g"},"notes":null,"contributor":"In the Kitchen with Chef Stephanie Green\nArizona Nutrition Network"},
{"slug":"broccoli-strawberry-orzo-salad","source_url":"https://www.myplate.gov/recipes/broccoli-strawberry-orzo-salad","name":"Broccoli Strawberry Orzo Salad","description":"Fresh broccoli and strawberries are colorful additions to this refreshing summer delight. Lemon dressing brings a bright flavor to this pasta dish.","ingredients":[{"name":null,"items":["3/4 cup orzo pasta, uncooked","2 cups fresh broccoli, chopped","2 cups fresh strawberries, diced","1/4 cup sunflower seeds"]},{"name":"Lemon Poppy Seed Dressing","items":["1 tablespoon lemon juice, fresh or bottled","2 tablespoons apple cider vinegar","2 tablespoons olive oil (or cooking oil of choice)","1 teaspoon sugar (or honey)","poppy seeds (1 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Cook orzo pasta according to directions. Drain and rinse with cold water.","In a large bowl, combine orzo pasta, broccoli, strawberries, and sunflower seeds. Drizzle with lemon poppy seed vinaigrette and toss to combine.","Season with salt and pepper. Chill in refrigerator until ready to serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"161.37 kcal","carbohydrateContent":"18.00 g","cholesterolContent":"0.00 mg","fiberContent":"2.88 g","proteinContent":"4.12 g","sodiumContent":"16.74 mg","sugarContent":"4.22 g","fatContent":"8.17 g","saturatedFatContent":"1.11 g"},"notes":"Honey should not be fed to children under 1 year of age.","contributor":"Community Fit!\nSouth Haven Health System"},
{"slug":"broiled-tomatoes-and-cheese","source_url":"https://www.myplate.gov/recipes/broiled-tomatoes-and-cheese","name":"Broiled Tomatoes and Cheese","description":"This recipe is especially tasty when using tomatoes that are fresh from the garden or farmers market.","ingredients":[{"name":null,"items":["3 large, firm tomatoes","8 ounces low-fat cottage cheese","1/2 teaspoon dried basil","1/8 teaspoon black pepper","3 tablespoons bread crumbs","2 sprays of cooking spray (or vegetable oil)"]}],"directions":[{"name":null,"steps":["Wash tomatoes and cut in half.","Mix cottage cheese, basil, and pepper.","Spread cheese on tomato halves.","Sprinkle with bread crumbs and spray with cooking spray.","Spray broiler pan with cooking spray. Place prepared tomatoes on a pan and broil about 10 minutes."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 prepared tomato halves","1/3 of recipe"],"calories":"116.03 kcal","carbohydrateContent":"13.38 g","cholesterolContent":"9.07 mg","fiberContent":"1.92 g","proteinContent":"10.31 g","sodiumContent":"297.40 mg","sugarContent":"6.81 g","fatContent":"2.65 g","saturatedFatContent":"1.09 g"},"notes":null,"contributor":"Choices: Steps Toward Health\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"bronco-beans","source_url":"https://www.myplate.gov/recipes/bronco-beans","name":"Bronco Beans","description":"This versatile recipe combines a variety of seasonings and beans including black, kidney, white, and chickpeas with an added kick of chili powder and jalapen...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","2 yellow onions (peeled and chopped)","1 bell pepper (cored, seeded, and chopped)","2 jalapeno peppers (chopped)","4 cloves garlic (peeled and chopped)","1 tablespoon dried oregano","1 tablespoon dried thyme","1 teaspoon chili powder","4 cans (15.5 ounce) assorted low-sodium beans, including black, kidney, white, and chickpeas (drained and rinsed with cold water)","2 cans (14.5 ounce) low-sodium diced tomatoes (including the liquid)","1 1/2 cups water"]}],"directions":[{"name":null,"steps":["Put the pot over medium heat and when it is hot, add the oil.","Add the onions, garlic, bell pepper, jalapenos, oregano, thyme and chili powder and cook until tender, about 15 minutes.","Add the drained beans, tomatoes and 1 1/2 cups water and raise the heat to high and bring to a boil. Lower the heat to low and let cook, partially covered, for 1 1/2 hours. If the mixture gets too thick, add the remaining 1/2 cup water.","Serve immediately or transfer to a container once cooled. Cover and refrigerate up to 2 days.","Garnish with cilantro and/or low-fat plain yogurt."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"236.66 kcal","carbohydrateContent":"42.27 g","cholesterolContent":"0.00 mg","fiberContent":"15.13 g","proteinContent":"13.13 g","sodiumContent":"281.56 mg","sugarContent":"8.97 g","fatContent":"3.00 g","saturatedFatContent":"0.61 g"},"notes":"Serve the Bronco Beans with brown rice and apple slices. Use leftovers in a quesadilla or omelet.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"brown-rice-pilaf-sage-walnuts-and-dried","source_url":"https://www.myplate.gov/recipes/brown-rice-pilaf-sage-walnuts-and-dried","name":"Brown Rice Pilaf with Sage, Walnuts, and Dried Fruit","description":"Dried fruit and sage combine to give this whole grain dish a flavor of fall, but you can enjoy it any time of the year!","ingredients":[{"name":null,"items":["1 medium onion, chopped","1 medium celery stalk, ends trimmed and chopped","2 cups brown rice, uncooked","2 1/2 cups water","2 cups vegetable broth, reduced sodium, fat-free","1/4 cup raisins","1/4 cup dried apricots, chopped","walnuts (1/4 cup, chopped, optional)","1 teaspoon dried sage","salt (to taste, optional)","black pepper (to taste, optional)","2 teaspoons sage (fresh, chopped)"]}],"directions":[{"name":null,"steps":["Spray the large skillet with canola cooking spray. Heat skillet over medium heat.","Sauté onion and celery until tender, about 5 minutes. Add brown rice and sauté for 5 minutes.","Add water, broth, raisins, and apricots; heat to boiling. Reduce heat to low, cover and simmer until rice is tender and liquid is absorbed, about 50 minutes.","Stir in sage and walnuts if desired. Season with optional salt and pepper to taste.","Transfer to serving dish. Garnish with fresh sage and serve immediately."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"235.54 kcal","carbohydrateContent":"49.42 g","cholesterolContent":"0.00 mg","fiberContent":"3.58 g","proteinContent":"6.05 g","sodiumContent":"34.06 mg","sugarContent":"7.24 g","fatContent":"1.95 g","saturatedFatContent":"0.55 g"},"notes":null,"contributor":"Diet & Cancer\nAmerican Institute for Cancer Research"},
{"slug":"brown-rice-pilaf","source_url":"https://www.myplate.gov/recipes/brown-rice-pilaf","name":"Brown Rice Pilaf","description":"Parsley, almonds, and spices spruce up this brown rice dish. Rice cooker required.","ingredients":[{"name":null,"items":["1 1/2 cups brown rice (uncooked)","3 cups water","1/4 cup almonds, sliced","1 teaspoon dried parsley","1/2 teaspoon garlic powder","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Place all ingredients in a rice cooker and cook until the water evaporates, about 30 minutes.","Fluff cooked rice with a fork."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared pilaf","1/4 of recipe"],"calories":"338.03 kcal","carbohydrateContent":"61.68 g","cholesterolContent":"0.00 mg","fiberContent":"4.94 g","proteinContent":"8.36 g","sodiumContent":"17.82 mg","sugarContent":"0.96 g","fatContent":"6.65 g","saturatedFatContent":"0.95 g"},"notes":"This dish goes very well with fish and chicken. Add a large green salad to complete the meal. The dish may be made on the stovetop as well but may require more water.","contributor":"Food and Health Communications, Inc."},
{"slug":"brown-rice-sizzling-chicken-and-vegetables","source_url":"https://www.myplate.gov/recipes/brown-rice-sizzling-chicken-and-vegetables","name":"Brown Rice with Sizzling Chicken and Vegetables","description":"This rice bowl with vegetables and chicken is simple to prepare and appealing to children and adults alike!","ingredients":[{"name":null,"items":["3 cups hot cooked brown rice","3 tablespoons reduced-sodium soy sauce","1/4 cup water","1 tablespoon honey","1 tablespoon cornstarch","1 1/2 tablespoons canola or corn oil","16 ounces boneless chicken breast (cut into 1-inch cubes)","2 cloves garlic (minced)","1 small white onion, cut into small wedges (about 1/8 inch thick)","3 medium carrots, peeled and thinly sliced (1 cup total)","1 1/2 cups small broccoli florets","1 medium red bell pepper (cut into 1 -inch pieces)"]}],"directions":[{"name":null,"steps":["Mix soy sauce, water, honey, and cornstarch in a small bowl; set aside.","Heat oil in a wok or large skillet. Add minced garlic; sauté about 1 minutes until garlic is golden.","Add chicken; cook about 5-6 minutes, then push chicken to the side.","Add onions to center of skillet; cook until slightly tender and push to the side.","Continue with carrots, broccoli, and peppers separately, placing each in center of pan, cooking until slightly tender and pushing to the side.","Pour soy sauce mixture into center of skillet. Leaving other ingredients and at the sides of the pan, stir sauce until it thickens.","Mix in with vegetables and chicken. Serve immediately over cooked brown rice."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"436.35 kcal","carbohydrateContent":"56.12 g","cholesterolContent":"75.06 mg","fiberContent":"5.53 g","proteinContent":"30.33 g","sodiumContent":"520.61 mg","sugarContent":"9.90 g","fatContent":"9.72 g","saturatedFatContent":"1.37 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of non-fat milk.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"brown-rice-tabbouleh","source_url":"https://www.myplate.gov/recipes/brown-rice-tabbouleh","name":"Brown Rice Tabbouleh","description":"Try this refreshing Mediterranean inspired dish with tomatoes and cucumbers and seasoned with mint and parsley. Ready in less than 30 minutes or make the nig...","ingredients":[{"name":null,"items":["3 cups brown rice (cooked)","3/4 cup cucumber (chopped)","3/4 cup tomato (chopped)","1/2 cup fresh parsley (chopped)","1/4 cup fresh mint leaves (chopped)","1/4 cup green onions (sliced)","1/4 cup olive oil","1/4 cup lemon juice","1/2 teaspoon salt","1/4 teaspoon freshly ground black pepper"]}],"directions":[{"name":null,"steps":["Combine rice, cucumber, tomato, parsley, mint, green onions, olive oil, lemon juice, salt, and pepper in large bowl.","Toss well and chill."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"216.19 kcal","carbohydrateContent":"27.77 g","cholesterolContent":"0.00 mg","fiberContent":"2.37 g","proteinContent":"3.28 g","sodiumContent":"208.48 mg","sugarContent":"1.38 g","fatContent":"10.43 g","saturatedFatContent":"1.73 g"},"notes":"Use leftover brown rice from a meal cooked earlier in the week. Or, make a big batch on the weekend to use in this dish and for other easy weeknight meals.\nFor best taste, refrigerate for at least 1 hour to allow flavors to blend.\nServe over fish or lean meats, with hummus and pita, or as a stuffing inside fresh tomatoes.\nMaterials: You will need a large bowl, measuring cups, measuring spoons, mixing spoon, and a sharp knife.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"brunswick-stew","source_url":"https://www.myplate.gov/recipes/brunswick-stew","name":"Brunswick Stew","description":"This hearty stew makes 8 servings or you can double it for a crowd. Skip the trip to the grocery store by using fresh leftover cooked chicken or turkey that ...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","1 medium onion, chopped","2 cups chicken broth, low-sodium","2 cups boneless chicken or turkey, cooked, and diced","2 cups tomatoes, low sodium canned or cooked","2 cups lima beans, cooked (or canned, low-sodium)","2 cups whole kernel corn, canned, low-sodium (or cooked)"]}],"directions":[{"name":null,"steps":["Heat oil in a large pan. Add onion and cook in oil until tender.","Add all remaining ingredients. Bring to a simmer for 30 minutes at medium-low.","Makes 8 servings of about 1 cup each."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared stew","1/8 of recipe"],"calories":"176.65 kcal","carbohydrateContent":"20.73 g","cholesterolContent":"33.34 mg","fiberContent":"4.49 g","proteinContent":"15.91 g","sodiumContent":"53.71 mg","sugarContent":"4.92 g","fatContent":"3.95 g","saturatedFatContent":"0.69 g"},"notes":null,"contributor":"Healthy Futures\nVirginia Cooperative Extension"},
{"slug":"brussel-sprouts-cranberry-and-bulgur-salad","source_url":"https://www.myplate.gov/recipes/brussel-sprouts-cranberry-and-bulgur-salad","name":"Brussel Sprouts, Cranberry, and Bulgur Salad","description":"Step up your salad game with this delicious dish, perfect for a gathering of friends or an easy lunch. Try substituting sunflower or pumpkin seeds for a nut-...","ingredients":[{"name":null,"items":["1/3 cup dried bulgur","1 cup boiling water","2 cups Brussels sprouts (1/2 pound)","1/2 cup dried cranberries","1/4 cup chopped nuts (any type)","1/4 cup orange juice","2 tablespoons vegetable oil","2 tablespoons vinegar","1/4 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Cover bulgur with boiling water and let stand until soft, about 30 minutes. Pour off any excess water.","Rinse and trim Brussels sprouts. Cut in half lengthwise then slice crosswise into thin strips.","In a large bowl combine bulgur, Brussels sprouts, cranberries and nuts.","In a small bowl or jar with a lid, combine orange juice, oil, vinegar, salt and pepper. Mix or shake well. Pour dressing over salad and serve."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"193.09 kcal","carbohydrateContent":"25.64 g","cholesterolContent":"0.00 mg","fiberContent":"4.38 g","proteinContent":"3.42 g","sodiumContent":"132.16 mg","sugarContent":"13.63 g","fatContent":"9.93 g","saturatedFatContent":"1.19 g"},"notes":"No nuts? Use sunflower or pumpkin seeds.\nNo dried cranberries? Use any type of dried fruit.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"brussels-sprouts-mushroom-sauce","source_url":"https://www.myplate.gov/recipes/brussels-sprouts-mushroom-sauce","name":"Brussels Sprouts with Mushroom Sauce","description":"This side dish is delicious when made with brussels sprouts, and you could also make it with broccoli, cabbage, kale, collards, or turnips. Cooking time may ...","ingredients":[{"name":null,"items":["2 cups Brussels sprouts (or broccoli, cabbage, kale, collards, or turnips)","1/2 cup chicken broth, low-sodium","1 teaspoon lemon juice","1 teaspoon spicy brown mustard","1/2 teaspoon dried thyme","1/2 cup mushrooms, sliced"]}],"directions":[{"name":null,"steps":["Trim brussels sprouts and cut in half. Steam until tender -- about 6 to 10 minutes. Or, microwave on high for 3 to 4 minutes.","In a non-stick pot bring the broth to a boil.","Mix in the lemon juice, mustard, and thyme. Add the mushrooms.","Boil until the broth is reduced by half, about 5 to 8 minutes.","Add the brussels sprouts (or other cooked vegetable).","Toss well to coat with the sauce."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"62.14 kcal","carbohydrateContent":"11.07 g","cholesterolContent":"0.00 mg","fiberContent":"4.24 g","proteinContent":"5.26 g","sodiumContent":"72.66 mg","sugarContent":"2.74 g","fatContent":"0.84 g","saturatedFatContent":"0.19 g"},"notes":null,"contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"bugs-log","source_url":"https://www.myplate.gov/recipes/bugs-log","name":"Bugs on a Log","description":"Kids and adults can create their own combinations of the ingredients for a fun and healthy snack activity.","ingredients":[{"name":"\"Logs\"","items":["1 celery stalk, cut into 3 pieces","apple slices","carrot, sliced into 3 inch pieces"]},{"name":"Spread","items":["1 tablespoon cream cheese, low-fat"]},{"name":"\"Bugs\"","items":["1 tablespoon raisins, regular or golden","unsweetened whole grain cereal","peanuts, chopped"]}],"directions":[{"name":null,"steps":["Choose one \"log\" option and top with a spread.","Sprinkle with a \"bug.\""]}],"yield":"1 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"3\" celery log with spread and bugs","calories":"65.65 kcal","carbohydrateContent":"10.34 g","cholesterolContent":"8.10 mg","fiberContent":"1.09 g","proteinContent":"1.78 g","sodiumContent":"88.45 mg","sugarContent":"7.93 g","fatContent":"2.39 g","saturatedFatContent":"1.39 g"},"notes":"Recipe cost and nutrient analysis are based on using celery, low-fat cream cheese, and raisins.","contributor":"National Network for Childcare"},
{"slug":"bulgur-chickpea-salad","source_url":"https://www.myplate.gov/recipes/bulgur-chickpea-salad","name":"Bulgur Chickpea Salad","description":"This salad is a great way to add some healthy grains, fruits, vegetables, and garbanzo beans to your meal.","ingredients":[{"name":null,"items":["1 1/4 cups water","1 cup bulgur","1 teaspoon dried parsley","1/3 tablespoon onion, minced","1 teaspoon soy sauce, reduced sodium","1/2 cup scallions, chopped (green onions)","1/2 cup raisins","1/2 cup carrots, chopped","3/4 cup canned chickpeas, low-sodium, drained and rinsed (garbanzo beans)"]},{"name":"Dressing","items":["2 tablespoons oil","2 tablespoons lemon juice","1 tablespoon soy sauce, reduced sodium","1 garlic clove, minced","black pepper (optional, to taste)"]}],"directions":[{"name":null,"steps":["Bring water to boil in medium saucepan. Stir in bulgur, parsley, minced onion, and soy sauce. Cover and reduce heat; simmer 15-20 minutes (until all water is absorbed and bulgur is not too crunchy). Do not overcook.","Remove from heat and allow to cool; fluff with fork.","Combine dressing ingredients; stir well. Pour over bulgur mixture and mix well.","Stir in scallions, raisins, carrots, and chickpeas. Cover and chill for several hours. Store in refrigerator."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"198.44 kcal","carbohydrateContent":"34.60 g","cholesterolContent":"0.00 mg","fiberContent":"6.79 g","proteinContent":"5.48 g","sodiumContent":"186.78 mg","sugarContent":"10.42 g","fatContent":"5.58 g","saturatedFatContent":"0.76 g"},"notes":null,"contributor":"Making It Fit: Piecing Together Your Food Needs\nUniversity of Vermont Extension"},
{"slug":"bulgur-wheat-veggie-chickpea-salad","source_url":"https://www.myplate.gov/recipes/bulgur-wheat-veggie-chickpea-salad","name":"Bulgur Wheat, Veggie & Chickpea Salad","description":"Bulgur is the star whole grain of this simple and colorful salad.","ingredients":[{"name":null,"items":["1 medium onion, chopped","1 cup broccoli, chopped","1 cup carrots, shredded","1 small green pepper, chopped (or red or yellow pepper)","1/3 cup fresh parsley, chopped (or 2 tablespoons dried)","1 teaspoon canola oil (or cooking oil of choice)","1 1/2 cups dry bulgur","2 cups low-sodium chicken broth","1 cup low-sodium canned chickpeas, drained (garbanzo beans)"]}],"directions":[{"name":null,"steps":["Wash and chop fresh onion, broccoli, carrots, pepper and parsley (if using fresh parsley).","Heat canola oil in a large skillet over medium-high heat. Add onions and cook until soft.","Add bulgur and stir to coat. Add 2 cups chicken broth to the skillet, bring to a boil.","Lower the heat, add remaining vegetables and chickpeas. Cook for 10 minutes or until the liquid is absorbed.","Add parsley and stir. Serve warm or cold."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"150.09 kcal","carbohydrateContent":"28.84 g","cholesterolContent":"0.00 mg","fiberContent":"7.27 g","proteinContent":"6.70 g","sodiumContent":"79.49 mg","sugarContent":"2.73 g","fatContent":"1.91 g","saturatedFatContent":"0.27 g"},"notes":"Bulgur comes from wheat. It is actually the kernel of wheat, cracked for cooking. It has a nutty, chewy flavor that is sure to please the healthy appetite, and contains fiber. Canola oil is a healthy choice for vegetable oil.","contributor":"Recipe Adapted from: 5 A Day Bulger Wheat\nChoices: Steps Toward Health\nUniversity of Massachusetts Extension Nutrition Education Program"},
{"slug":"butterfly-bite","source_url":"https://www.myplate.gov/recipes/butterfly-bite","name":"Butterfly Bite","description":"Designed with kids in mind, this recipe puts a new spin on snack time. Try different vegetables or dried fruit for a different looking \"butterfly.\"","ingredients":[{"name":null,"items":["3 celery stalks","12 twist pretzels (large, 3 ring)","6 tablespoons creamy peanut butter","3 tablespoons raisins"]}],"directions":[{"name":null,"steps":["Clean celery with vegetable brush under cool running water.","Cut celery in half cross wise.","Fill center of each celery stick with one tablespoon of peanut butter. This is the body of the butterfly","Add two pretzels to form the butterfly’s wings.","Use extra pretzel pieces for antenna and raisins for decoration."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 butterfly bite","calories":"143.03 kcal","carbohydrateContent":"12.95 g","cholesterolContent":"0.00 mg","fiberContent":"1.52 g","proteinContent":"4.50 g","sodiumContent":"160.34 mg","sugarContent":"5.34 g","fatContent":"8.40 g","saturatedFatContent":"1.65 g"},"notes":null,"contributor":"The Texas A&M University System\nTexas Cooperative Extension Expanded Nutrition Program"},
{"slug":"buttermilk-scones","source_url":"https://www.myplate.gov/recipes/buttermilk-scones","name":"Buttermilk Scones","description":"These scones taste better than those from your local bakery -- and you do not even have to change out of your pajamas! You can make many variations of this r...","ingredients":[{"name":null,"items":["1 cup whole-wheat flour","3/4 cup all-purpose flour","1/3 cup sugar","1 teaspoon baking powder","1/2 teaspoon baking soda","1/4 teaspoon salt","1 cup raisins","4 tablespoons butter, melted (1/4 cup)","2/3 cup buttermilk"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Combine the flours, sugar, baking powder, baking soda and salt in a medium bowl. Mix well.","Add raisins and mix lightly.","In a small bowl, combine melted butter and buttermilk. Add liquid ingredients to flour mixture; mix gently.","Spoon dough into 9 equal mounds on a greased baking sheet. Bake until well browned, 18 to 20 minutes.","Serve hot or at room temperature. Best eaten the same day you bake them."]}],"yield":"9 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Scone","calories":"222.60 kcal","carbohydrateContent":"39.98 g","cholesterolContent":"15.57 mg","fiberContent":"2.51 g","proteinContent":"4.06 g","sodiumContent":"214.61 mg","sugarContent":"19.88 g","fatContent":"6.22 g","saturatedFatContent":"3.62 g"},"notes":"Substitute vegetable oil for the butter to reduce saturated fat.\nTry other dried fruit.\nSprinkle with cinnamon before baking.\nTry mixing in 1 1/2 teaspoons grated lemon or orange zest (grate the outer colored part of the peel).\nNo buttermilk? Place 1 tablespoon of lemon juice or vinegar in measuring cup and fill to the 1 cup line with milk. Stir and let set to thicken slightly.\nWhole wheat flour can be replaced with all-purpose flour.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"butternut-squash-apple-soup","source_url":"https://www.myplate.gov/recipes/butternut-squash-apple-soup","name":"Butternut Squash & Apple Soup","description":null,"ingredients":[{"name":null,"items":["1 medium onion (chopped)","1 medium celery stalk (chopped)","1 medium carrot (chopped)","2 tablespoons olive oil (or cooking oil of choice)","4 cups water","1 medium butternut squash (peeled, seeded, and chopped)","1 medium tart apple (peeled, cored, and chopped)","3 teaspoons low-sodium bouillon (1 tablespoon)","1/8 teaspoon cayenne pepper","1/8 teaspoon black pepper","1/8 teaspoon cinnamon","1/8 teaspoon nutmeg","1/8 teaspoon salt"]}],"directions":[{"name":null,"steps":["In a stockpot, add the onion, celery, carrot, and oil. Sauté for about 5 minutes or until the vegetables are tender.","Add water, squash, apple, and bouillon to the pot. Bring to a boil. Reduce heat to low, then cover, and simmer.","Continue cooking for 30 minutes or until the squash and carrots are soft.","Carefully transfer soup to a food processor or blender and puree. NOTE: If an immersion blender is available, the soup does not need to be transferred.","Add seasonings. Serve warm."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"158.57 kcal","carbohydrateContent":"21.82 g","cholesterolContent":"0.25 mg","fiberContent":"4.95 g","proteinContent":"1.77 g","sodiumContent":"127.17 mg","sugarContent":"12.35 g","fatContent":"7.78 g","saturatedFatContent":"1.27 g"},"notes":"Tart apple varieties include: Granny Smith, Rome, McIntosh, Jonagold, and Jazz.\nVary your veggies! Eating a variety of colored vegetables provides you with the most nutritional value.","contributor":"Virginia Cooperative Extension - www.eatsmartmovemoreva.org"},
{"slug":"butternut-squash-black-beans","source_url":"https://www.myplate.gov/recipes/butternut-squash-black-beans","name":"Butternut Squash with Black Beans","description":"Butternut squash and black beans make a hearty side dish that is delicious and full of fiber and protein.","ingredients":[{"name":null,"items":["2 3/4 cups butternut squash, cubed (1 small squash, about 1 pound)","1 small onion, chopped","1 teaspoon vegetable oil (or cooking oil of choice)","1/4 teaspoon garlic powder","1/4 cup red wine vinegar","1/4 cup water","2 cans (15.5 ounces each) low-sodium black beans, rinsed and drained","1/2 teaspoon oregano"]}],"directions":[{"name":null,"steps":["Heat the squash in the microwave on high heat for 1 to 2 minutes. This will soften the skin.","Carefully peel the squash with a vegetable peeler or small knife.","Cut the squash into 1/2 inch cubes.","Peel and chop the onion.","In a large pan, heat the oil. Add the onion, garlic powder, and squash.","Cook for 5 minutes on medium heat.","Add vinegar and water. Cook on low heat until the squash is tender, about 10 minutes.","Add the beans and oregano. Cook until the beans are heated through."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"173.34 kcal","carbohydrateContent":"31.67 g","cholesterolContent":"0.00 mg","fiberContent":"12.13 g","proteinContent":"9.63 g","sodiumContent":"204.84 mg","sugarContent":"3.23 g","fatContent":"1.43 g","saturatedFatContent":"0.28 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"butternut-squash-pasta-bake","source_url":"https://www.myplate.gov/recipes/butternut-squash-pasta-bake","name":"Butternut Squash Pasta Bake","description":"Tired of tomatoes? Try topping pasta with creamy low-fat ricotta and sweet roasted butternut squash for a weeknight dinner that’s anything but ordinary.","ingredients":[{"name":null,"items":["2 1/2 cups butternut squash","4 ounces dried whole wheat shell pasta","3 tablespoons shallot, diced","1 tablespoon sage, minced","1 garlic clove","1/8 teaspoon salt","1/4 teaspoon black pepper","1/2 cup low-sodium vegetable broth","3/4 cup low-fat ricotta","2 ounces low-fat mozzarella, grated"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 °F. Cut butternut squash in half and scoop out the seeds. Place the cut sides down in a large baking dish and fill with 1/4 inch water. Bake butternut squash until tender (about 45 minutes). Remove from oven and let cool slightly.","While the squash bakes, bring a pot of water to a boil. Add pasta and cook until just tender. Drain and set aside. Reduce oven to 375 °F.","From the butternut squash, measure out 2 cups of the squash. Place in a food processor along the shallot, sage, garlic, salt, and pepper. Pulse until squash is smooth. Add in low-sodium vegetable broth and pulse until well-combined.","In a small baking dish, place a third of the squash purée in the bottom. Add half the noodles, followed by the low-fat ricotta. Top the ricotta with the next third of the sauce, then the remaining noodles. Finish with remaining sauce and low-fat shredded mozzarella.","Bake pasta for 25 minutes at 375 °F. Cheese should be browned. Remove and serve warm."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"514.61 kcal","carbohydrateContent":"69.62 g","cholesterolContent":"47.03 mg","fiberContent":"11.21 g","proteinContent":"28.53 g","sodiumContent":"482.18 mg","sugarContent":"7.40 g","fatContent":"16.50 g","saturatedFatContent":"8.43 g"},"notes":"This dish works well with any type of squash purée, pumpkin, or sweet potatoes.\nAny small shape of pasta would work – use what you have on hand!","contributor":"Created by the Grain Foods Foundation, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"cabbage-roll-casserole","source_url":"https://www.myplate.gov/recipes/cabbage-roll-casserole","name":"Cabbage Roll Casserole","description":"Minute rice and canned tomatoes combined with cabbage make this a quick, easy, and healthy recipe.","ingredients":[{"name":null,"items":["1/2 pound ground beef (90% lean)","1 onion (chopped)","1 garlic clove (minced)","1 1/2 cups water","1 can (14.5 ounces) diced tomatoes, low-sodium","1 1/2 cups tomato sauce, low-sodium (or tomato juice)","1 cabbage head (small to medium, chopped in bite-sized pieces)","1/4 cup minute brown rice"]}],"directions":[{"name":null,"steps":["Brown ground beef in a skillet with onion and garlic. Drain off any fat.","Place meat in a large pot and add water, tomatoes, tomato sauce (or juice), and cabbage. Cook until cabbage is almost tender.","Add minute rice and cook five minutes longer. Serve."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"119.02 kcal","carbohydrateContent":"17.53 g","cholesterolContent":"16.43 mg","fiberContent":"5.12 g","proteinContent":"8.09 g","sodiumContent":"48.26 mg","sugarContent":"7.38 g","fatContent":"2.67 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"cabbage-salad","source_url":"https://www.myplate.gov/recipes/cabbage-salad","name":"Cabbage Salad","description":"Dill, mustard, and lemon juice give this crunchy salad a zesty flavor. Make the dressing ahead to save time later.","ingredients":[{"name":null,"items":["4 cups cabbage (shredded or thinly sliced)","1/4 cup carrot (grated or finely sliced)","1/4 cup celery (thinly sliced)","1/4 cup green pepper (chopped)","1 teaspoon onion (finely chopped)","1/2 teaspoon dried dill (may also use dried basil or parsley)","1/2 cup mayonnaise, light or low-fat","1/2 cup plain yogurt, non-fat","1 teaspoon mustard","1/2 teaspoon lemon juice","1/2 teaspoon sugar"]}],"directions":[{"name":null,"steps":["Wash and prepare vegetables for chopping.","Use a cheese grater or slice all vegetables thinly with a sharp knife.","Put in a large bowl.","Add dill and/or other herbs to taste.","Mix mayonnaise, yogurt, mustard, lemon juice, and sugar in a small bowl. Blend well. Add to vegetables.","Mix well. Keep in refrigerator until ready to eat."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"61.87 kcal","carbohydrateContent":"6.30 g","cholesterolContent":"2.81 mg","fiberContent":"1.41 g","proteinContent":"1.66 g","sodiumContent":"161.93 mg","sugarContent":"3.81 g","fatContent":"3.59 g","saturatedFatContent":"0.58 g"},"notes":null,"contributor":"From the Farm to the Table\nUniversity of Connecticut Cooperative Extension\nHispanic Health Council"},
{"slug":"cabbage-stir-fry","source_url":"https://www.myplate.gov/recipes/cabbage-stir-fry","name":"Cabbage Stir-Fry","description":"This one-skillet vegetable stir-fry has cabbage, green peppers, onion, and garlic; is quick to make; and is full of flavor.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","1 cup chopped onion","2 medium green peppers, chopped","1 small head cabbage, chopped","2 cloves garlic, chopped (or 1/2 teaspoon of garlic powder)","2 tablespoons soy sauce, low-sodium"]}],"directions":[{"name":null,"steps":["Wash green peppers and cabbage before chopping.","Heat oil in a large skillet.","Add onions, peppers, cabbage, and garlic to skillet and cook over medium heat until vegetables are tender.","Add soy sauce and stir until sauce boils.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/6 of recipe"],"calories":"84.47 kcal","carbohydrateContent":"14.35 g","cholesterolContent":"0.00 mg","fiberContent":"4.74 g","proteinContent":"3.12 g","sodiumContent":"220.65 mg","sugarContent":"7.19 g","fatContent":"2.60 g","saturatedFatContent":"0.40 g"},"notes":"Two cloves garlic and 2 tablespoons reduced-sodium soy sauce used in nutrition analysis.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"cafe-mocha","source_url":"https://www.myplate.gov/recipes/cafe-mocha","name":"Cafe Mocha","description":"Jazz up this hot drink by adding cinnamon.","ingredients":[{"name":null,"items":["1/3 cup nonfat dry milk","1 cup water","1 cup brewed coffee","4 tablespoons hot chocolate mix","lite whipped topping (optional)","cinnamon (optional)"]}],"directions":[{"name":null,"steps":["Heat reconstituted non-fat dried milk in saucepan until warm; do not boil.","Add coffee and hot chocolate mix. Stir well and heat to desired temperature.","Divide coffee mixture between two mugs. Top with non-fat whipped topping and cinnamon, if desired."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"64.62 kcal","carbohydrateContent":"11.62 g","cholesterolContent":"2.24 mg","fiberContent":"3.70 g","proteinContent":"6.17 g","sodiumContent":"69.33 mg","sugarContent":"6.01 g","fatContent":"1.48 g","saturatedFatContent":"0.86 g"},"notes":"You can substitute 1 cup skim milk for the reconstituted nonfat dried milk.","contributor":"USDA’S Collection of Nonfat Dry Milk (NDM) Recipes\nUSDA Food and Nutrition Service\nFood Distribution Service"},
{"slug":"cajun-catfish","source_url":"https://www.myplate.gov/recipes/cajun-catfish","name":"Cajun Catfish","description":"Catfish is breaded with cornmeal and baked in the oven for a healthier way to add flavor and crunch!","ingredients":[{"name":null,"items":["Cooking spray","1/4 cup cornmeal (about 4 tablespoons)","1/2 tablespoon paprika","1/2 teaspoon garlic powder","1/2 teaspoon onion powder","1/2 teaspoon oregano","1/4 teaspoon black pepper","3/4 teaspoon lemon pepper seasoning, no salt added","1/8 teaspoon salt","1 pound catfish fillets, frozen, thawed, drained (about 4 fillets)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400°F. Spray a baking sheet with cooking spray.","Combine cornmeal and spices in a shallow dish.","Dip each fillet in the cornmeal mixture. Coat evenly.","Place fillets on a baking sheet.","Bake 20–25 minutes flipping catfish halfway through. Catfish should reach a final internal cook temperature of 145 F as measured with a food thermometer before serving."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 filet","calories":"147.57 kcal","carbohydrateContent":"7.09 g","cholesterolContent":"52.39 mg","fiberContent":"1.07 g","proteinContent":"15.51 g","sodiumContent":"234.97 mg","sugarContent":"0.18 g","fatContent":"6.11 g","saturatedFatContent":"1.33 g"},"notes":"This recipe contains one or more ingredients considered to be traditional or indigenous to Native American communities in certain regions across North America.","contributor":"Recipe adapted from Chickasaw Nation Nutrition Services, Get Fresh Initiative"},
{"slug":"california-avocado-super-summer-wrap","source_url":"https://www.myplate.gov/recipes/california-avocado-super-summer-wrap","name":"California Avocado Super Summer Wrap","description":"Fresh avocado doubles for dressing and filling complementing blueberries, carrots, arugula, and chicken in this appetizing summer wrap.","ingredients":[{"name":null,"items":["1 ripe avocado (seeded, peeled, and cut into chunks)","1/2 cup plain nonfat Greek yogurt","1 teaspoon lime juice","1/2 cup blueberries","1/2 cup carrots (grated)","1/4 cup red onion (chopped)","2 cups fresh arugula (chopped)","12 ounces cooked chicken breast (cubed)","4 8-inch whole wheat tortillas"]}],"directions":[{"name":null,"steps":["Mash half the avocado chunks with yogurt and lime juice in a medium bowl.","Add remaining filling ingredients, including the rest of the avocado chunks; mix gently.","Top each tortilla with 1/4 of filling mixture.","Roll tuck in ends. Slice in half diagonally, securing with toothpicks, if needed."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"379.07 kcal","carbohydrateContent":"30.44 g","cholesterolContent":"85.56 mg","fiberContent":"8.13 g","proteinContent":"34.82 g","sodiumContent":"345.89 mg","sugarContent":"5.73 g","fatContent":"13.21 g","saturatedFatContent":"3.70 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"candied-yams","source_url":"https://www.myplate.gov/recipes/candied-yams","name":"Candied Yams","description":"Enjoy this side dish for a Thanksgiving treat or anytime yams are in season.","ingredients":[{"name":null,"items":["1 1/2 cups yams","1/4 cup brown sugar, packed","1 teaspoon flour, sifted","1/4 teaspoon salt","1/4 teaspoon ground cinnamon","1/4 teaspoon ground nutmeg","1/4 teaspoon orange peel","1 teaspoon unsalted margarine","1/2 cup orange juice"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Cut yams in half and boil until tender, but firm (about 20 minutes). When cool enough to handle, peel and slice into 1/4 inch thickness.","Combine sugar, flour, salt, cinnamon, nutmeg, and grated orange peel.","Place half of sliced yams in medium-sized casserole dish. Sprinkle with spiced sugar mixture.","Dot with half the amount of margarine.","Add second layer of yams, using the rest of the ingredients in the order above. Add orange juice.","Bake uncovered for 20 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 Cup (66g)","calories":"73.08 kcal","carbohydrateContent":"16.92 g","cholesterolContent":"0.00 mg","fiberContent":"1.02 g","proteinContent":"0.76 g","sodiumContent":"114.85 mg","sugarContent":"12.25 g","fatContent":"0.45 g","saturatedFatContent":"0.11 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"cantaloupe-cooler","source_url":"https://www.myplate.gov/recipes/cantaloupe-cooler","name":"Cantaloupe Cooler","description":"Cool down in the heat with this fruit cooler. Refreshing orange juice mixed with sweet cantaloupe creates the perfect, easy-to-make drink! You can even get c...","ingredients":[{"name":null,"items":["1 ripe cantaloupe","2 1/2 cups orange juice, divided (cold)","2 tablespoons sugar","crushed ice"]}],"directions":[{"name":null,"steps":["Cut melon in half. Scoop out seeds, remove rind, and discard. Cut melon into 1-inch cubes.","In blender or food processor, blend melon cubes with 1/2 cup orange juice until smooth.","Pour purée into pitcher and stir in the remaining orange juice and the sugar. Stir until sugar is dissolved.","Pour into glasses filled with crushed ice."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"75.08 kcal","carbohydrateContent":"16.47 g","cholesterolContent":"0.00 mg","fiberContent":"0.78 g","proteinContent":"1.19 g","sodiumContent":"20.66 mg","sugarContent":"14.80 g","fatContent":"0.41 g","saturatedFatContent":"0.04 g"},"notes":"For a new twist, try other melons or strawberries in place of the cantaloupe.","contributor":"Celebrate Health with a Lowfat Fiesta\nCalifornia Department of Health Services\nCalifornia Project LEAN"},
{"slug":"caramel-sauce","source_url":"https://www.myplate.gov/recipes/caramel-sauce","name":"Caramel Sauce","description":"Serve this sauce over fruit or frozen yogurt for a dessert or special snack.","ingredients":[{"name":null,"items":["8 1/3 tablespoons nonfat dry milk (1/2 cup + 1 teaspoon)","1 1/4 cups water","1 tablespoon cornstarch","2 tablespoons butter","1/2 cup brown sugar, packed","1 teaspoon vanilla extract"]}],"directions":[{"name":null,"steps":["Reconstitute non-fat dried milk with water. Combine reconstituted milk and cornstarch in a small saucepan and mix until cornstarch is thoroughly dissolved.","Add the butter and brown sugar and cook over medium heat, stirring constantly with a wire whisk until mixture thickens and comes to a boil. Continue to boil 1 minute.","Remove pan from heat and stir in vanilla. Serve warm over baked French toast, ice cream, or fruit."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 Tablespoons","calories":"66.03 kcal","carbohydrateContent":"11.18 g","cholesterolContent":"5.68 mg","fiberContent":"0.01 g","proteinContent":"1.10 g","sodiumContent":"19.70 mg","sugarContent":"10.47 g","fatContent":"1.94 g","saturatedFatContent":"1.21 g"},"notes":null,"contributor":"USDA’S Collection of Nonfat Dry Milk (NDM) Recipes\nUSDA Food and Nutrition Service\nFood Distribution Service"},
{"slug":"caribbean-bean-salad","source_url":"https://www.myplate.gov/recipes/caribbean-bean-salad","name":"Caribbean Bean Salad","description":"A refreshing and delicious salad that includes tomatoes, oranges, beans, onions, and lettuce.","ingredients":[{"name":null,"items":["4 cups romaine lettuce, chopped","1/4 cup red onion, chopped","1 cup canned black beans, low-sodium (drained and rinsed)","1 orange, peeled and diced","1 tomato, diced","1 tablespoon olive oil (or cooking oil of choice)","3 tablespoons red wine vinegar","1 teaspoon oregano","black pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Toss all ingredients together in large salad bowl.","Serve immediately or refrigerate up to one hour."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared bean salad","1/4 of recipe"],"calories":"124.21 kcal","carbohydrateContent":"18.00 g","cholesterolContent":"0.00 mg","fiberContent":"6.18 g","proteinContent":"4.83 g","sodiumContent":"96.24 mg","sugarContent":"5.33 g","fatContent":"3.90 g","saturatedFatContent":"0.63 g"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"caribbean-casserole","source_url":"https://www.myplate.gov/recipes/caribbean-casserole","name":"Caribbean Casserole","description":"This quick one skillet casserole dish of beans, bell peppers, tomatoes, and oregano uses instant brown rice to reduce cooking time.","ingredients":[{"name":null,"items":["1 medium onion, chopped","1/2 medium green pepper, diced (diced)","1 tablespoon canola oil (or cooking oil of choice)","1 can (14.5 ounces) stewed tomatoes, low-sodium","1 can (15.5 ounces) black beans, low sodium (or beans of your choice)","1 teaspoon oregano leaves","1/2 teaspoon garlic powder","1 1/2 cups instant brown rice, uncooked"]}],"directions":[{"name":null,"steps":["Sauté onion and green pepper in canola oil, in a large pan, until tender. Do not brown.","Add tomatoes, beans (include liquid from both), oregano, and garlic powder. Bring to a boil.","Stir in rice and cover.","Reduce heat to simmer for 5 minutes.","Remove from heat and let stand for 5 minutes."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Cup","calories":"181.70 kcal","carbohydrateContent":"34.44 g","cholesterolContent":"0.00 mg","fiberContent":"5.72 g","proteinContent":"5.78 g","sodiumContent":"69.49 mg","sugarContent":"2.20 g","fatContent":"2.56 g","saturatedFatContent":"0.39 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"caribbean-pink-beans","source_url":"https://www.myplate.gov/recipes/caribbean-pink-beans","name":"Caribbean Pink Beans","description":"Plantains, tomatoes, and onions come together to give this side dish a Caribbean flavor.","ingredients":[{"name":null,"items":["1 pound dry pinto beans","10 cups water","2 medium plantains, finely chopped","1 large tomato, finely chopped","1 small red pepper, finely chopped","1 medium white onion, finely chopped","3 garlic clove, finely chopped","1 1/2 teaspoons salt"]}],"directions":[{"name":null,"steps":["Rinse and pick through the beans. Put the beans in a large pot and add 10 cups of water. Place the pot in the refrigerator and allow the beans to soak overnight.","Cook the beans until they are soft. Add more water as needed while the beans are cooking.","Add the plantains, tomato, pepper, onion, garlic, and salt. Continue cooking at low heat until the plantains are soft.","*Option: Serve with rice."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"128.78 kcal","carbohydrateContent":"26.01 g","cholesterolContent":"0.00 mg","fiberContent":"6.63 g","proteinContent":"6.55 g","sodiumContent":"230.36 mg","sugarContent":"4.82 g","fatContent":"0.54 g","saturatedFatContent":"0.10 g"},"notes":null,"contributor":"Stay Young at Heart: Cooking the Heart-Healthy Way\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"carrot-cookies","source_url":"https://www.myplate.gov/recipes/carrot-cookies","name":"Carrot Cookies","description":"Carrots give this traditional oatmeal and raisin cookie a colorful and tasty twist.","ingredients":[{"name":null,"items":["1/2 cup margarine, soft","1 cup honey","1 cup carrots, grated","2 egg whites, beaten","2 cups all-purpose flour","2 teaspoons baking powder","1/4 teaspoon baking soda","1/4 teaspoon salt","1 teaspoon cinnamon","2 cups oatmeal, quick cooking, uncooked","1 cup raisins"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a large bowl, cream together margarine and honey. Stir in carrots and egg whites.","Stir together flour, baking powder, baking soda, salt, cinnamon, oatmeal and raisins. Gradually stir flour-oatmeal mixture into creamed mixture, just until all flour is mixed. Do not over mix.","Drop from teaspoon on greased baking sheet. Flatten slightly and bake at 350 °F for 10 minutes, or until lightly browned."]}],"yield":"30 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 cookies","1/30 of recipe"],"calories":"121.93 kcal","carbohydrateContent":"23.59 g","cholesterolContent":"0.04 mg","fiberContent":"1.18 g","proteinContent":"2.05 g","sodiumContent":"96.43 mg","sugarContent":"12.51 g","fatContent":"2.69 g","saturatedFatContent":"0.53 g"},"notes":"Honey should not be fed to children under 1 year of age.\nInstead of honey, you can use 1 1/4 cups sugar mixed with 1/4 cup water.","contributor":"Healthy Futures\nVirginia Cooperative Extension"},
{"slug":"carrot-raisin-salad","source_url":"https://www.myplate.gov/recipes/carrot-raisin-salad","name":"Carrot Raisin Salad","description":"This easy and healthy side salad has a sweet and tangy flavor. Make it ahead of time and serve it chilled.","ingredients":[{"name":null,"items":["4 medium carrots, peeled and grated","1/4 cup raisins","2 teaspoons sugar","1 lemon, juiced"]}],"directions":[{"name":null,"steps":["In a medium bowl, thoroughly mix carrots, raisins, sugar, and lemon juice.","Serve chilled."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"65.51 kcal","carbohydrateContent":"16.58 g","cholesterolContent":"0.00 mg","fiberContent":"2.17 g","proteinContent":"0.93 g","sodiumContent":"44.14 mg","sugarContent":"11.76 g","fatContent":"0.20 g","saturatedFatContent":"0.03 g"},"notes":null,"contributor":"Cent$ible Nutrition Cook Book\nUniversity of Wyoming Cooperative Extension"},
{"slug":"carrots-tomatoes-and-macaroni","source_url":"https://www.myplate.gov/recipes/carrots-tomatoes-and-macaroni","name":"Carrots with Tomatoes and Macaroni","description":"Each serving of this delicious and quick pasta dish provides 1 1/2 cups of veggies.","ingredients":[{"name":null,"items":["1 tablespoon olive oil (or cooking oil of choice)","1 small onion, chopped","4 plum tomatoes, chopped","1/2 cup canned tomato juice, low-sodium","6 large carrots, peeled and sliced","1/4 teaspoon salt","1/4 teaspoon black pepper","1/4 teaspoon sugar","2 tablespoons fresh parsley, chopped (or 1 teaspoon dried)","1 teaspoon butter","1 cup elbow macaroni, cooked"]}],"directions":[{"name":null,"steps":["In a saucepan, cook the onion in the oil until soft but not brown. Add the tomatoes, tomato juice, carrots, salt, pepper, and sugar.","Cover and cook over low heat for 5 minutes. Remove the cover and cook over low heat, stirring often, for another 5 minutes, or until the carrots are tender and the tomatoes are cooked down to a sauce.","Stir in the parsley.","Mix the butter with the cooked macaroni.","Add the macaroni to the carrot mixture and stir together."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"164.69 kcal","carbohydrateContent":"26.40 g","cholesterolContent":"2.69 mg","fiberContent":"4.25 g","proteinContent":"4.07 g","sodiumContent":"233.69 mg","sugarContent":"8.20 g","fatContent":"5.25 g","saturatedFatContent":"1.30 g"},"notes":null,"contributor":"University of Rhode Island Cooperative Extension\nExpanded Food and Nutrition Education Program"},
{"slug":"catfish-stew-and-rice","source_url":"https://www.myplate.gov/recipes/catfish-stew-and-rice","name":"Catfish Stew and Rice","description":"Chili and spice seasoning give this seafood stew a punch of flavor. Serve it with brown rice for added whole grains.","ingredients":[{"name":null,"items":["2 medium potatoes","1 can low-sodium diced tomatoes (14.5 ounce can)","1 cup chopped onion","2 cups water","2 garlic cloves (minced)","1/2 head of cabbage (coarsely chopped)","1 pound catfish fillets","1 1/2 tablespoons Chili and Spice Seasoning","green onion (sliced, as needed)","2 cups cooked brown rice"]}],"directions":[{"name":null,"steps":["Cut potatoes into quarters.","In large pot, combine potatoes, tomatoes and their juice, onion, water, and garlic. Bring to boil and reduce heat. Cook covered over medium-low heat for 10 minutes.","Add cabbage and return to boil. Reduce heat. Cook covered for 5 minutes, stirring occasionally.","Meanwhile, cut fillets into 2-inch lengths. Coat with Chili and Spice Seasoning.","Add fish to vegetables. Reduce heat and simmer covered for 5 minutes or until fish flakes easily with fork.","Serve in soup dishes. Garnish with sliced green onion, if desired. Serve with scoop of hot cooked brown rice."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup stew with 1/2 cup rice","calories":"384.03 kcal","carbohydrateContent":"58.81 g","cholesterolContent":"52.39 mg","fiberContent":"9.77 g","proteinContent":"22.54 g","sodiumContent":"159.48 mg","sugarContent":"9.29 g","fatContent":"7.35 g","saturatedFatContent":"1.67 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"cauliflower-shells-cheese","source_url":"https://www.myplate.gov/recipes/cauliflower-shells-cheese","name":"Cauliflower Shells with Cheese","description":"Creamy cauliflower and low-fat cheese make a delicious sauce for this pasta dish.","ingredients":[{"name":null,"items":["1 pound whole wheat pasta shells","8 cups water","2 cups cauliflower, chopped","1 1/2 cups milk, non-fat, divided","1 teaspoon garlic salt","1/4 cup flour","1/4 cup vegetable oil (or cooking oil of choice)","1 cup cheese, low-fat"]}],"directions":[{"name":null,"steps":["Fill 1 pot with 6 cups of water and bring to a boil. Once the water is boiling, add pasta and cook for 8 minutes.","Drain pasta and fill the same pot with 2 cups of water, bring to a boil.","Place the chopped cauliflower in the boiling water and cook until the florets are soft (about 4 minutes). Drain cauliflower.","Placed the cooked cauliflower, 1/2 cup milk, and garlic salt in a blender and blend until smooth.","In a separate pot, heat oil. Add the flour and whisk until the mixture is smooth. Add 1 cup of milk and cook the mixture until it bubbles and thickens. Add the cheese and cauliflower mixture and stir..","Remove from heat. Add the pasta back into the sauce and serve."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"382.43 kcal","carbohydrateContent":"55.08 g","cholesterolContent":"12.11 mg","fiberContent":"6.94 g","proteinContent":"15.95 g","sodiumContent":"252.28 mg","sugarContent":"4.09 g","fatContent":"12.77 g","saturatedFatContent":"3.19 g"},"notes":null,"contributor":"With Veggies, More Matters!\nMichigan State University Extension - Midland County"},
{"slug":"celery-apricot-blue-cheese-spread","source_url":"https://www.myplate.gov/recipes/celery-apricot-blue-cheese-spread","name":"Celery with Apricot Blue Cheese Spread","description":"Crunchy, sweet celery is a versatile snack food, just right for this flavorful spread. Filled with dried fruit and nuts, this enticing and quick low-fat spre...","ingredients":[{"name":null,"items":["2 tablespoons crumbled blue cheese","3 tablespoons fat-free cream cheese","1/2 cup fat-free yogurt (plain)","4 dried apricots","4 dried figs or dates","1/4 cup pecans","8 stalks celery"]}],"directions":[{"name":null,"steps":["Chop dried fruit and pecans.","Mix blue cheese, cream cheese, and yogurt with a fork or hand mixer until smooth.","Stir in chopped, dried fruit and pecans. Refrigerate spread until ready for use.","Slice celery stalks into 3-4 inch sticks.","Fill celery pieces with spread."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"140.06 kcal","carbohydrateContent":"16.65 g","cholesterolContent":"5.13 mg","fiberContent":"3.23 g","proteinContent":"6.07 g","sodiumContent":"216.67 mg","sugarContent":"12.41 g","fatContent":"6.18 g","saturatedFatContent":"1.34 g"},"notes":"Tips on how to select, store, and serve celery:\nChoose straight, rigid celery stalks with fresh leaves. Avoid pithy, woody, or limp stalks.\nRefrigerate in a plastic bag for a week or more.\nAdd chopped celery stalks and celery leaves to your soups, stews, and casseroles for extra nutrition, flavor, and crunch.\nAdd diced celery to your favorite tuna, chicken, egg, or vegetable salad recipe for extra texture.\nCut-up celery for a flavorful addition to healthy stir-fry dishes.","contributor":"Produce for Better Health Foundation"},
{"slug":"chapatis-flatbread","source_url":"https://www.myplate.gov/recipes/chapatis-flatbread","name":"Chapatis Flatbread","description":"Just four ingredients is all you need to make delicious flatbread at home! Serve with dip at your next gathering or as a side to dinner.","ingredients":[{"name":null,"items":["2 cups whole wheat flour","2/3 cup warm water","2 teaspoons vegetable oil (or cooking oil of choice)","1 dash salt"]}],"directions":[{"name":null,"steps":["Place the flour in a large mixing bowl. Add water, oil, and salt. Mix with fork and then with hands. Keep mixing until you can make a ball.","Knead the dough for about 10 minutes. Let rest for 30 minutes in the bowl, covered with a damp cloth.","Roll the ball into a 12-inch log and cut into 6 chunks.","Roll each chunk into a very thin pancake, about 7 inches in diameter. Don''t worry about making the dough into a perfect circle-just try to get it as thin as you can.","Heat a cast iron skillet (lightly greased) on medium-high heat. Place one chapati in the skillet and cook for 30 seconds.","Use a spatula to lift bread. When chapati gets brown spots and bubbles, flip it over and cook for another 30 seconds.","Wrap the cooked chapati in a cloth napkin while cooking the rest.","Eat them right away with a little butter or margarine, or use as scoops for eating other dishes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 chapatis","calories":"150.00 kcal","carbohydrateContent":"28.79 g","cholesterolContent":"0.00 mg","fiberContent":"4.28 g","proteinContent":"5.28 g","sodiumContent":"27.67 mg","sugarContent":"0.16 g","fatContent":"2.56 g","saturatedFatContent":"0.39 g"},"notes":null,"contributor":"Wellness Ways Resource Book: Taste of the World\nUniversity of Illinois Extension Service"},
{"slug":"cheese-and-corn-chowder","source_url":"https://www.myplate.gov/recipes/cheese-and-corn-chowder","name":"Cheese and Corn Chowder","description":"This is a hearty vegetarian soup for a filling and healthy meal on a chilly night. If you have leftovers that have been properly handled, you can add ham, ch...","ingredients":[{"name":null,"items":["2 cups potatoes, diced","1 cup carrot, sliced","1 cup celery, chopped","1/2 cup onion, chopped","1/4 teaspoon black pepper","1 can (14.75 ounce) cream-style corn, low-sodium","1 1/2 cups milk, non-fat","1/2 cup cheddar or American cheese, shredded"]}],"directions":[{"name":null,"steps":["Combine potatoes, carrots, celery, onion and seasonings in pan. Add 1 cup water. Cover and simmer 10 minutes.","Add corn and pepper. Cook 5 more minutes or until vegetables are cooked.","Add milk and cheese. Stir until cheese melts and chowder is heated through. Do not boil.","Serve hot."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"163.60 kcal","carbohydrateContent":"28.15 g","cholesterolContent":"11.25 mg","fiberContent":"2.84 g","proteinContent":"6.99 g","sodiumContent":"122.62 mg","sugarContent":"7.58 g","fatContent":"3.69 g","saturatedFatContent":"1.92 g"},"notes":"To make a Ham, Cheese, and Corn Chowder: Add 1/2 cup cubed, cooked ham.","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"cheese-roni-bake","source_url":"https://www.myplate.gov/recipes/cheese-roni-bake","name":"Cheese-A-Roni Bake","description":"Bright layers of spaghetti sauce, cheese, and macaroni cook together for one hour in the oven to make a hot meal.","ingredients":[{"name":null,"items":["1 jar (24 ounces) spaghetti sauce, meatless, low-sodium","1/3 cup water","6 ounces cottage cheese, fat-free","1 egg, slightly beaten","1/2 teaspoon oregano","1 cup dry macaroni","4 ounces mozzarella cheese, part skim, shredded"]}],"directions":[{"name":null,"steps":["In a bowl combine sauce and water.","In another bowl combine cottage cheese, egg and oregano.","Grease 1 quart casserole.","Spoon in 1/3 sauce.","Layer with 1/2 cup macaroni, 1/2 cottage cheese mixture, 1/2 mozzarella cheese and 1/3 of the spaghetti sauce.","Repeat layers one more time.","Cover with aluminum foil.","Bake in a 350 °F oven for 45 minutes.","Uncover and bake 15 minutes longer."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"275.48 kcal","carbohydrateContent":"33.27 g","cholesterolContent":"72.78 mg","fiberContent":"3.81 g","proteinContent":"18.44 g","sodiumContent":"392.81 mg","sugarContent":"7.75 g","fatContent":"8.27 g","saturatedFatContent":"3.98 g"},"notes":null,"contributor":"USDA Supplemental Nutrition Assistance Program (SNAP)"},
{"slug":"cheese-stuffed-potatoes","source_url":"https://www.myplate.gov/recipes/cheese-stuffed-potatoes","name":"Cheese Stuffed Potatoes","description":"These potatoes are light and fluffy on the inside and baked twice to give a crunchy crust.","ingredients":[{"name":null,"items":["4 medium baking potatoes","1 cup cottage cheese, low-fat","2 tablespoons 1% milk","2 tablespoons onion, chopped","1/4 teaspoon paprika"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 °F.","Scrub the potatoes.","Put the potatoes in the oven. Bake 30 to 40 minutes until tender.","Slice each potato in half lengthwise.","Use a spoon to scoop out the inside of each potato. Leave about 1/2 inch of potato next to the skin. Save the inside part of each potato in a small bowl.","Peel the onion. Chop it to make 2 tablespoons chopped onion.","Put the cheese, milk, and onion in another small bowl. Add the insides of the potatoes. Mix with a fork until light and fluffy.","Divide this mix into 8 parts. Put part of the mix inside each potato.","Sprinkle paprika over the potatoes.","Return to the oven for 5 minutes to reheat."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 potato halves","1/4 of recipe"],"calories":"213.10 kcal","carbohydrateContent":"39.73 g","cholesterolContent":"7.16 mg","fiberContent":"3.95 g","proteinContent":"10.85 g","sodiumContent":"202.30 mg","sugarContent":"5.04 g","fatContent":"1.62 g","saturatedFatContent":"0.81 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"cheesy-chicken-broccoli-and-rice-bake","source_url":"https://www.myplate.gov/recipes/cheesy-chicken-broccoli-and-rice-bake","name":"Cheesy Chicken, Broccoli, and Rice Bake","description":"A great recipe to use leftover chicken that has been properly handled. Combine with broccoli, cheese, onions, garlic, and brown rice to create a quick dinner...","ingredients":[{"name":null,"items":["5 cups water","2 1/2 cups brown rice","1/4 cup onion, chopped","1 garlic clove, chopped","1 cup skim milk","1 can (10.75 ounces) condensed cream of mushroom soup, reduced-sodium","1/4 teaspoon salt","1/4 teaspoon black pepper","3/4 cup low-fat cheddar cheese, grated","2 cups chicken, cooked, shredded","2 cups broccoli, chopped"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. In large saucepan, bring water to boil. Add rice, onion, and garlic. Cook for about 30 minutes or until rice is soft.","While rice is cooking combine milk, soup, salt, and pepper, mix well. When rice is done combine with milk mixture, chicken, and broccoli. Mix well.","Grease 9x13 pan and pour mixture into pan. Bake in preheated oven for 18 minutes. Sprinkle with cheese. Bake for another 6 minutes or until cheese is melted.","Serve immediately."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Cup","calories":"244.98 kcal","carbohydrateContent":"37.56 g","cholesterolContent":"28.95 mg","fiberContent":"2.68 g","proteinContent":"13.79 g","sodiumContent":"223.10 mg","sugarContent":"2.25 g","fatContent":"3.98 g","saturatedFatContent":"1.55 g"},"notes":null,"contributor":"Healthy Recipes\nOregon State University Cooperative Extension Service"},
{"slug":"cherry-melon-grape-salad","source_url":"https://www.myplate.gov/recipes/cherry-melon-grape-salad","name":"Cherry, Melon, & Grape Salad","description":"A delicious fruit salad with an added twist of cherries and coconut flakes. You will feel like you are in a tropical paradise eating this salad.","ingredients":[{"name":null,"items":["1/2 cup sweet cherries, pitted and cut in half","1 cup cubed cantaloupe","1 cup seedless green grapes, cut in half","1 medium banana, peeled and sliced","1/4 cup orange juice (juice from 1/2 orange)","1/4 cup flaked coconut (optional)"]}],"directions":[{"name":null,"steps":["In a large bowl, mix together the cut fruit.","Pour orange juice over fruit and stir in coconut, if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"90.25 kcal","carbohydrateContent":"21.65 g","cholesterolContent":"0.00 mg","fiberContent":"1.62 g","proteinContent":"1.15 g","sodiumContent":"12.38 mg","sugarContent":"17.50 g","fatContent":"0.31 g","saturatedFatContent":"0.08 g"},"notes":"Try using different types of melon or grapes.","contributor":"Food Hero, Adapted from Cherry Salad\nOregon State University Cooperative Extension Service"},
{"slug":"cherry-puff-pancake","source_url":"https://www.myplate.gov/recipes/cherry-puff-pancake","name":"Cherry Puff Pancake","description":"Smells of vanilla, cinnamon, and fruit will fill your home after baking these cherry puff pancakes. If you don’t like cherries, try using peaches, pears, o...","ingredients":[{"name":null,"items":["3 eggs","1/2 cup fat-free milk","1 teaspoon vanilla extract","1/2 cup all-purpose flour","1 tablespoon sugar","1/8 teaspoon cinnamon","2 tablespoons butter, unsalted","2 cups halved, pitted sweet cherries, fresh or frozen, thawed and drained","¼ cup sliced almonds (optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 450 °F.","In a medium bowl or blender, beat the eggs, milk, and vanilla together until well blended.","Mix the flour, sugar, and cinnamon together. Add to the liquid ingredients and mix until there are no lumps.","Put margarine or butter in a 10- or 11-inch oven proof skillet or a 2 1/2- to 3-quart baking dish. Place the skillet or dish in the hot oven until the margarine or butter is melted and bubbly. Remove from the oven. Quickly spread the cherries across the bottom of the hot skillet or dish.","Pour the batter over the cherries and sprinkle with almond slices, if using.","Return to the oven and bake for 15 to 20 minutes until the edges are browned and the puffs in the middle are golden. Cool slightly before cutting into 4 pieces. The center puffs will flatten during cooling."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"234.79 kcal","carbohydrateContent":"29.10 g","cholesterolContent":"170.31 mg","fiberContent":"2.04 g","proteinContent":"8.17 g","sodiumContent":"62.11 mg","sugarContent":"14.52 g","fatContent":"9.83 g","saturatedFatContent":"4.86 g"},"notes":"Try using other fruit, such as peaches, pears, or blueberries.\nServe with plain or vanilla yogurt.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"chicken-and-beans","source_url":"https://www.myplate.gov/recipes/chicken-and-beans","name":"Chicken and Beans","description":"This simple one-pot dinner mixes kidney beans and chicken in a savory tomato sauce.","ingredients":[{"name":null,"items":["1 can (15 ounces) kidney beans, low-sodium","1 clove garlic","1 medium onion","5 chicken thighs","1 can (8 ounces) tomato sauce, low-sodium","1/4 cup vinegar","1 teaspoon sugar","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Drain and rinse beans.","Crush garlic.","Dice onion.","Dice chicken thighs.","In large, pot, cook chicken until half done.","Add tomato sauce, vinegar, onion, garlic, sugar, salt, and pepper.","Simmer for about 30 to 40 minutes or until chicken is tender.","Add kidney beans and simmer for 5-10 more minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"196.49 kcal","carbohydrateContent":"16.11 g","cholesterolContent":"74.67 mg","fiberContent":"4.88 g","proteinContent":"18.64 g","sodiumContent":"286.86 mg","sugarContent":"4.49 g","fatContent":"6.65 g","saturatedFatContent":"1.74 g"},"notes":"Cider, white, and Japanese wine vinegars differ in flavor. Try other vegetables. Dry beans may be used. See package for cooking directions.","contributor":"Lifeskills in Food Education, Food Skills Cookbook\nUniversity of Hawaii at Manoa Cooperative Extension"},
{"slug":"chicken-and-broccoli-bake","source_url":"https://www.myplate.gov/recipes/chicken-and-broccoli-bake","name":"Chicken and Broccoli Bake","description":"Use fresh-cooked chicken or leftovers that have been properly handled to save time in this baked casserole.","ingredients":[{"name":null,"items":["1 cup rice, uncooked","2 tablespoons margarine (or butter)","1/4 cup flour","2 cups chicken broth, low-sodium","1/4 cup Parmesan cheese, optional","1 package (10 ounces) frozen broccoli, thawed","3 cups boneless chicken, cooked"]}],"directions":[{"name":null,"steps":["Cook rice according to package directions.","Melt margarine in large sauce pan. Add flour to melted margarine and stir. This will be lumpy.","Slowly add chicken broth to margarine/flour mixture. Stir to remove lumps and thicken.","Add cheese and stir.","Add rice, broccoli, and chicken. Stir.","Put in a casserole pan and bake at 350 °F for 30 minutes or until thoroughly heated."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"227.06 kcal","carbohydrateContent":"25.69 g","cholesterolContent":"50.05 mg","fiberContent":"1.46 g","proteinContent":"20.03 g","sodiumContent":"71.01 mg","sugarContent":"0.65 g","fatContent":"4.53 g","saturatedFatContent":"0.99 g"},"notes":null,"contributor":"Supermarket Smarts: The 5 A Day Way\nProduce for Better Health and Connecticut Departments of Public Health and Social Services"},
{"slug":"chicken-and-cranberry-salad","source_url":"https://www.myplate.gov/recipes/chicken-and-cranberry-salad","name":"Chicken and Cranberry Salad","description":"A simple and delicious salad topped with almonds and dried cranberries for bursts of flavor.","ingredients":[{"name":null,"items":["12 ounces chicken, cooked and diced (1 1/2 cups)","1/2 cup vinaigrette dressing","1/2 cup dried cranberries (or cherries)","1/8 cup almonds, sliced","1 head of lettuce, chopped"]}],"directions":[{"name":null,"steps":["Toss chicken, cranberries, and almonds with dressing.","Serve on a mound of chopped lettuce."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"394.46 kcal","carbohydrateContent":"20.45 g","cholesterolContent":"84.03 mg","fiberContent":"2.89 g","proteinContent":"28.20 g","sodiumContent":"190.01 mg","sugarContent":"15.50 g","fatContent":"22.47 g","saturatedFatContent":"3.16 g"},"notes":null,"contributor":"Creative Recipes for Less Familiar USDA Commodities Used by Household Programs\nUSDA Food and Nutrition Service\nFood Distribution Service"},
{"slug":"chicken-and-dumpling-soup","source_url":"https://www.myplate.gov/recipes/chicken-and-dumpling-soup","name":"Chicken and Dumpling Soup","description":"Try this spin on an all-time favorite chicken and dumplings. This easy, one-pot meal can be made for a family or ready to serve a crowd.","ingredients":[{"name":"For the Soup","items":["2 tablespoons vegetable oil","2 cups carrots, chopped","1 cup onion, chopped","1 cup celery, chopped, including some leaves","8 cups chicken broth, fat free, low sodium","2 cups cooked chicken breast, shredded","1/2 teaspoon black peppercorns","1 teaspoon dried thyme","2 bay leaves","2 cups fresh spinach leaves, coarsely chopped"]},{"name":"For the Dumplings","items":["1 cup whole wheat flour","1 cup all-purpose flour","3/4 cup skim milk","1 egg, large"]}],"directions":[{"name":null,"steps":["Heat oil in Dutch oven or soup kettle over medium-high heat.","Sauté carrot, onion and celery for 5 minutes; stir in broth, chicken, peppercorns, thyme, and bay leaves.","Reduce heat to low; simmer, partially covered for 20 minutes.","Meanwhile, in small bowl, mix dumpling ingredients until well blended.","Drop small spoonsful of dumpling dough into simmering soup.","Cover soup and allow dumplings to cook for about 20 minutes (they will rise to the top of the soup as they cook).","Stir in spinach.","Remove bay leaves before serving soup."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"273.98 kcal","carbohydrateContent":"32.28 g","cholesterolContent":"59.72 mg","fiberContent":"3.63 g","proteinContent":"21.03 g","sodiumContent":"145.23 mg","sugarContent":"4.02 g","fatContent":"7.48 g","saturatedFatContent":"1.51 g"},"notes":null,"contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"chicken-and-dumplings","source_url":"https://www.myplate.gov/recipes/chicken-and-dumplings","name":"Chicken and Dumplings","description":"These easy dumplings only need 4 ingredients. Drop them into the hot chicken broth mixture and cook them for 15 minutes. What a simple and quick meal for a b...","ingredients":[{"name":null,"items":["2 tablespoons flour, all purpose","2 tablespoons water","1 cup chicken broth, low-sodium","1 cup chicken, cooked and diced","salt (optional, 1/4 teaspoon)","1 dash black pepper (1/16 of a teaspoon)"]},{"name":"Dumplings","items":["1/3 cup flour, all purpose","1/2 teaspoon baking powder","1/4 teaspoon salt","2 tablespoons non-fat milk"]}],"directions":[{"name":null,"steps":["Mix 2 tablespoons flour and water in a pan until smooth.","Slowly stir in broth.","Cook over medium heat until thickened.","Add chicken, salt (optional) and pepper."]},{"name":"Make Dumplings","steps":["Combine flour, baking powder, and salt in a small bowl. Stir in milk until dough forms.","Drop dumpling dough from a tablespoon onto gently boiling chicken mixture, making 4 dumplings.","Cover pan tightly and cook slowly for 15 minutes without lifting the lid."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"238.19 kcal","carbohydrateContent":"24.24 g","cholesterolContent":"67.14 mg","fiberContent":"0.78 g","proteinContent":"26.42 g","sodiumContent":"493.14 mg","sugarContent":"1.00 g","fatContent":"3.41 g","saturatedFatContent":"0.79 g"},"notes":null,"contributor":"Wellness Ways Resource Book, Adapted from recipe Easy Chicken and Dumplings\nUniversity of Illinois Extension Service"},
{"slug":"chicken-and-spanish-rice","source_url":"https://www.myplate.gov/recipes/chicken-and-spanish-rice","name":"Chicken and Spanish Rice","description":"This skillet dinner calls for cooked chicken. Use leftover chicken that has been properly handled or canned chicken to stretch your food dollars.","ingredients":[{"name":null,"items":["1 cup onion, chopped","1/4 cup green pepper, chopped","2 teaspoons vegetable oil (or cooking oil of choice)","1 can (8 ounces) tomato sauce, low sodium","1/3 tablespoon parsley, chopped (1 teaspoon)","1/2 teaspoon black pepper","1 1/4 teaspoons garlic, minced","5 cups cooked brown rice (cook rice in unsalted water)","3 1/2 cups cooked chicken breast, diced, skin and bone removed"]}],"directions":[{"name":null,"steps":["In a large skillet, sauté onions and green peppers in oil for 5 minutes on medium heat.","Add tomato sauce and spices. Heat through.","Add cooked rice and chicken. Heat through."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"437.49 kcal","carbohydrateContent":"56.19 g","cholesterolContent":"93.36 mg","fiberContent":"4.55 g","proteinContent":"35.20 g","sodiumContent":"60.80 mg","sugarContent":"3.69 g","fatContent":"7.30 g","saturatedFatContent":"1.53 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"chicken-apple-salad-sandwich","source_url":"https://www.myplate.gov/recipes/chicken-apple-salad-sandwich","name":"Chicken Apple Salad Sandwich","description":"Celery and apple give a delightful crunch to this easy to make sandwich filling.","ingredients":[{"name":null,"items":["1/4 pound cooked chicken (shredded)","1 celery stalk (chopped)","1 medium apple (chopped)","1/3 cup light mayonnaise","1 lemon, juiced","1 (1.5 ounces) box raisins","8 slices whole wheat bread","1 cup walnuts (chopped, optional)"]}],"directions":[{"name":null,"steps":["Combine all ingredients except for bread together in a bowl.","Create 4 sandwiches on whole wheat bread."]}],"yield":"4 Sandwiches","nutrition":{"@type":"NutritionInformation","servingSize":["1 sandwich","1/4 of recipe"],"calories":"329.42 kcal","carbohydrateContent":"49.97 g","cholesterolContent":"22.07 mg","fiberContent":"6.05 g","proteinContent":"15.27 g","sodiumContent":"514.69 mg","sugarContent":"17.40 g","fatContent":"7.96 g","saturatedFatContent":"1.42 g"},"notes":"May substitute approximately 3 tablespoons of lemon juice for 1 fresh lemon, juiced.\nSuggest serving sandwiches with lettuce and tomato.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"chicken-broccoli-alfredo","source_url":"https://www.myplate.gov/recipes/chicken-broccoli-alfredo","name":"Chicken Broccoli Alfredo","description":"Broccoli brings brightness to this recipe, while the Basic Soup and Sauce Mix gives this recipe a rich and creamy flavor.","ingredients":[{"name":null,"items":["8 ounces fettuccine noodles","1 cup broccoli, fresh or frozen, chopped","2 tablespoons butter","16 ounces chicken breast, boneless","1/3 Basic Soup and Sauce Mix","1 1/4 cups water","1/2 cup milk, non-fat","1/2 cup Parmesan cheese, grated","1/4 teaspoon pepper (optional)"]}],"directions":[{"name":null,"steps":["Cook fettuccine according to package directions. Add broccoli for the last 4 minutes of cooking time. Drain.","Heat butter in skillet. Add chicken and cook until browned, stirring often.","Combine sauce mix and water in saucepan. Bring to a boil and cook until thick. Add milk, cheese, pepper (if using), and fettuccine mixture and heat through.","Serve with additional Parmesan cheese."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"412.72 kcal","carbohydrateContent":"46.65 g","cholesterolContent":"80.57 mg","fiberContent":"2.80 g","proteinContent":"30.91 g","sodiumContent":"186.57 mg","sugarContent":"3.98 g","fatContent":"10.46 g","saturatedFatContent":"4.94 g"},"notes":"Recipe for Basic Soup and Sauce Mix. 1 serving = 1/3 cup.","contributor":"Utah State University Cooperative Extension"},
{"slug":"chicken-cacciatore","source_url":"https://www.myplate.gov/recipes/chicken-cacciatore","name":"Chicken Cacciatore","description":"This easy recipe features chicken cooked in a tomato base. It’s a classic favorite that is easy to make and full of flavor!","ingredients":[{"name":null,"items":["1 onion, chopped","1 cup canned tomatoes, low-sodium","1/2 cup tomato sauce, low-sodium","1/8 teaspoon garlic powder","1 teaspoon oregano","1/8 teaspoon black pepper","4 chicken pieces, skin removed (thighs, breasts, or legs)"]}],"directions":[{"name":null,"steps":["Peel and chop the onion.","Put the chopped onion in a saucepan.","Add the tomatoes, tomato sauce, garlic powder, oregano, and pepper.","Simmer on low heat for 3 minutes.","If needed, remove the chicken skin.","Add the chicken to the sauce pan and cover.","Cook over low heat for about 1 hour until the chicken is tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 piece chicken","1/4 of recipe"],"calories":"181.39 kcal","carbohydrateContent":"7.61 g","cholesterolContent":"90.02 mg","fiberContent":"2.45 g","proteinContent":"29.06 g","sodiumContent":"55.25 mg","sugarContent":"4.21 g","fatContent":"3.54 g","saturatedFatContent":"0.75 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"chicken-casserole","source_url":"https://www.myplate.gov/recipes/chicken-casserole","name":"Chicken Casserole","description":"This chicken casserole is a simple, satisfying main dish for lunch or dinner.","ingredients":[{"name":null,"items":["1 pound rotini or macaroni pasta (1 package)","1 can chicken (about 12 ounces)","1 can low-sodium tomato sauce (about 15 ounces)","1/2 can low-sodium green peas, drained (about 8 ounces)","3 slices pasteurized processed American cheese"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Cook rotini or macaroni according to package directions. Drain well.","In a large oven-safe dish, mix the chicken, tomato sauce, peas, and macaroni.","Add the 3 slices of cheese on top of the casserole.","Bake for 30 to 40 minutes.","Serve hot."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"389.08 kcal","carbohydrateContent":"56.37 g","cholesterolContent":"28.43 mg","fiberContent":"4.78 g","proteinContent":"23.08 g","sodiumContent":"334.56 mg","sugarContent":"4.19 g","fatContent":"7.41 g","saturatedFatContent":"2.56 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"chicken-club-salad","source_url":"https://www.myplate.gov/recipes/chicken-club-salad","name":"Chicken Club Salad","description":"This colorful chicken and pasta salad is served over lettuce or spinach to make a tasty lunch or dinner. Pick your favorite veggies to add to this salad.","ingredients":[{"name":null,"items":["1 cup whole wheat pasta, uncooked (macaroni or rotelle)","6 cups Romaine lettuce, washed and torn (or spinach)","2 cups green peppers, chopped (or a combination of bell peppers, celery, cauliflower florets, cucumber, carrots*)","2 cups tomatoes, chopped","1 1/2 cups cubed cooked skinless chicken (1/2 pound)","1/2 Lite Italian Dressing (about 1/2 of what the recipe makes)","1 egg, hard cooked (optional)","1/4 cup shredded cheese"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions; drain and cool.","Place 1 1/2 cups of the Romaine lettuce in each of 4 large bowls or plates.","Combine chopped vegetables, chicken, and pasta.","Add dressing; toss lightly to coat. Divide evenly among the 4 bowls.","Top each serving with a few egg slices, if desired, and 1 tablespoon of the shredded cheese."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3 cups (383g)","calories":"303.39 kcal","carbohydrateContent":"28.45 g","cholesterolContent":"57.51 mg","fiberContent":"5.59 g","proteinContent":"23.19 g","sodiumContent":"194.17 mg","sugarContent":"5.14 g","fatContent":"11.53 g","saturatedFatContent":"2.83 g"},"notes":"*2 cups of green bell peppers were used for cost analysis and nutrition calculations.","contributor":"Eat Better. Buy Better: Iowa State University Extension 2009 Calendar\nIowa State University Extension and Montana State University"},
{"slug":"chicken-mole","source_url":"https://www.myplate.gov/recipes/chicken-mole","name":"Chicken Mole","description":"Chili powder, cocoa, garlic powder, and peanut butter make a traditional Mexican chicken dish. Serve it with brown rice for a mid-week dinner.","ingredients":[{"name":null,"items":["1 fryer chicken, cut into pieces, skin and fat removed","5 cups water","4 tablespoons chili powder","1 teaspoon oregano","1 teaspoon cocoa, unsweetened","10 tablespoons flour","1 teaspoon black pepper","1 teaspoon garlic powder","1 cup water","1 tablespoon creamy peanut butter","1/4 cup water"]}],"directions":[{"name":null,"steps":["Place chicken in a large pot with the 1/4 cup of water. Cover and simmer until tender, about 45 minutes.","In a medium bowl, mix chili powder, oregano, cocoa, flour (1/2 cup plus 2 tablespoons), pepper, and garlic powder along with 1 cup of water.","Add mixture from step 2 to chicken in pot; mix well.","Add peanut butter and 5 cups of water to chicken in pot; mix well.","Bring to a boil.","Reduce heat to medium. Cook for 10 to 15 minutes.","Stir and serve immediately."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"237.77 kcal","carbohydrateContent":"14.17 g","cholesterolContent":"72.23 mg","fiberContent":"2.71 g","proteinContent":"26.35 g","sodiumContent":"244.92 mg","sugarContent":"0.73 g","fatContent":"8.33 g","saturatedFatContent":"2.11 g"},"notes":null,"contributor":"Pictorial Recipes\nOregon State University Cooperative Extension Service\nOregon Family Nutrition Program\nRecipe submitted by Lynn Myers Steele, 2000"},
{"slug":"chicken-noodle-soup-0","source_url":"https://www.myplate.gov/recipes/chicken-noodle-soup-0","name":"Chicken Noodle Soup","description":"This home-style chicken noodle soup makes a wonderful side dish. It tastes even better the next day if you have any leftovers.","ingredients":[{"name":null,"items":["1 pound chicken breasts, thawed, skin and bone removed from each piece","6 cups water","1/2 teaspoon salt","1/4 teaspoon black pepper","4 tablespoons egg mix (or 2 eggs)","2 cups all-purpose flour"]}],"directions":[{"name":null,"steps":["Cut up chicken breasts and place in a large pot with enough water to cover. Add salt and pepper.","Bring chicken and water to a boil. Reduce to medium heat and continue to cook for about 20 minutes.","Set aside 1/4 cup (about 1 ladle full) of the broth in a large bowl to cool down.","To make the noodles, combine egg mix and flour in a medium-size bowl. While mixing the egg and flour, slowly add the 1/4 cup cooled broth until a dough is formed.","Roll the dough on a clean, dry, floured surface. Add more flour as needed to keep it from sticking.","Cut dough into 1/2 inch wide strips that are about 6 inches long.","Gently put the strips into the pot with the chicken. Stir every 5 minutes.","Cook until done (about 15 to 20 minutes over medium heat).","Be careful! Pot may boil over if lid is fully closed."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"287.00"},"notes":"Tip for cooking chicken: The recommended sage minimum internal temperature for chicken is 165 degrees F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe submitted by Tod Robertson, Seminole Nation"},
{"slug":"chicken-noodle-soup","source_url":"https://www.myplate.gov/recipes/chicken-noodle-soup","name":"Chicken Noodle Soup","description":"Chicken, vegetables, and egg noodles combine for a hearty soup.","ingredients":[{"name":null,"items":["2 pounds chicken pieces, skin removed","1/2 teaspoon salt","1/4 teaspoon black pepper","1 onion, chopped","1 cup celery, chopped","3 large carrots, thinly sliced","4 cups egg noodles, dry","thyme or sage (optional)"]}],"directions":[{"name":null,"steps":["Thaw frozen chicken in refrigerator (about 24 hours), or thaw in microwave just before cooking soup.","Place chicken pieces in large kettle. Cover completely with water. Cover, bring to boil, reduce heat, and simmer 2 to 3 hours.","With soap and water, carefully wash your hands and any counter surfaces and equipment that came in contact with raw chicken.","Remove cooked chicken pieces from broth with tongs or slotted spoon. Cool 10 to 15 minutes before separating bones from meat. Break meat into bite-sized pieces. Remove any bones from broth.","Remove fat from broth by skimming with spoon, adding and removing ice cubes, or blotting top of broth with paper towels.","Put chicken meat, seasonings and vegetables into stock.","Bring broth to a boil, cover, reduce heat and cook about 15 to 20 minutes on medium heat until sliced carrots are crispy-tender.","Add noodles and boil uncovered for about 6 to 7 minutes, stirring occasionally to break up any noodles that might stick together.","Ladle into soup bowls.","Refrigerate or freeze leftovers within 2 hours of cooking. If refrigerated, use within 2 days. When reheating, bring to a boil."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"328.90 kcal","carbohydrateContent":"22.42 g","cholesterolContent":"118.94 mg","fiberContent":"2.37 g","proteinContent":"36.07 g","sodiumContent":"333.22 mg","sugarContent":"2.94 g","fatContent":"9.80 g","saturatedFatContent":"2.59 g"},"notes":null,"contributor":"Simply Good Eating Recipe Cards, Vol. 1, 2000\nUniversity of Minnesota Cooperative Extension Service"},
{"slug":"chicken-pasta-salad","source_url":"https://www.myplate.gov/recipes/chicken-pasta-salad","name":"Chicken Pasta Salad","description":"Colorful veggies, black beans, and pasta make this salad healthy, flavorful, and filling. Make it several hours ahead and let it chill in the refrigerat...","ingredients":[{"name":null,"items":["2 cups cooked small pasta","1 1/2 cups canned chicken, drained","1 cup diced bell pepper","1/2 cup sliced green onion","1 cup shredded yellow squash","1/2 cup canned corn kernels, low-sodium, drained","1/2 cup frozen peas, thawed","1 can (15 ounces) black beans, low-sodium, rinsed and drained","1/2 cup fat-free Italian dressing"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions, drain; rinse.","Combine first eight ingredients (pasta through black beans) in a large bowl.","Toss gently with salad dressing.","Chill for several hours to blend flavors."]}],"yield":"7 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/7 of recipe","calories":"233.90 kcal","carbohydrateContent":"29.79 g","cholesterolContent":"22.29 mg","fiberContent":"6.46 g","proteinContent":"18.57 g","sodiumContent":"494.44 mg","sugarContent":"4.01 g","fatContent":"4.47 g","saturatedFatContent":"1.20 g"},"notes":null,"contributor":"Color Me Healthy\nNorth Carolina Department of Public Health and North Carolina Cooperative Extension"},
{"slug":"chicken-posole","source_url":"https://www.myplate.gov/recipes/chicken-posole","name":"Chicken Posole","description":"Posole is a delicious side dish that can be served with several toppings. It can be eaten by itself, or it can be served with shredded cabbage, sliced radish...","ingredients":[{"name":null,"items":["1 onion, chopped","3 large carrots, chopped","3 celery stalks, chopped","1/2 tablespoon garlic, finely chopped","2 tablespoons vegetable oil","2 1/2 cups hominy (2 - 15 ounce cans)","1 can chicken (about 12 ounces)","4 cups water","1 teaspoon cayenne or jalapeño chilies, seeds removed and finely chopped (optional)","1/2 teaspoon chili powder (optional)","1/2 teaspoon oregano (optional)","1/2 teaspoon salt","1/4 teaspoon pepper"]}],"directions":[{"name":null,"steps":["In a medium-sized pot, brown onion, carrots, celery, and garlic in vegetable oil over medium heat for 10 minutes.","Add hominy, chicken, and water. If using cayenne pepper, jalapeño chilies, chili powder, or oregano, add that, too. Mix well.","Bring pot to a boil. Lower heat and cook for about 10 minutes.","Add salt and pepper. Serve hot."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"224.00"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"chicken-pot-pie","source_url":"https://www.myplate.gov/recipes/chicken-pot-pie","name":"Chicken Pot Pie","description":"Leftover chicken and frozen veggies help this chicken pot pie come together quickly.","ingredients":[{"name":null,"items":["1 2/3 cups frozen mixed vegetables, thawed","1 cup cooked chicken, diced","1 can (10.75 ounces) condensed cream of chicken soup, reduced-sodium","1 cup baking mix, reduced-fat","1/2 cup milk, fat-free","1 egg"]}],"directions":[{"name":null,"steps":["Pre-heat oven to 400 °F.","Mix vegetables, chicken, and soup in ungreased, 9-inch pie plate","Stir baking mix, milk, and egg in a mixing bowl with fork until blended. Pour over vegetables and chicken in pie plate.","Bake 30 minutes or until golden brown.","Let cool for 5 minutes and serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"208.13 kcal","carbohydrateContent":"25.86 g","cholesterolContent":"60.50 mg","fiberContent":"2.86 g","proteinContent":"12.61 g","sodiumContent":"497.23 mg","sugarContent":"5.29 g","fatContent":"5.65 g","saturatedFatContent":"1.56 g"},"notes":null,"contributor":"The Texas A&M University System, Adapted from Easy Chicken Pot Pie\nTexas Cooperative Extension Expanded Nutrition Program"},
{"slug":"chicken-pozole-soup","source_url":"https://www.myplate.gov/recipes/chicken-pozole-soup","name":"Chicken Pozole Soup","description":"This traditional Mexican soup has a deep flavor using a whole chicken. Hominy can be found in the canned food aisle of the grocery store.","ingredients":[{"name":null,"items":["1 whole chicken, skinned and cut into pieces","8 cups water","1/2 cup onion, chopped","1/4 teaspoon black pepper","4 tablespoons chili powder","1 can (8 ounces) tomato sauce, low-sodium","1/2 teaspoon dried oregano","5 cups canned hominy, white or yellow, rinsed and drained (2 - 15 ounce cans)","3 cups iceberg lettuce, shredded","1 lime (cut into 6 wedges)"]}],"directions":[{"name":null,"steps":["Put chicken pieces in a large pot and cover with the 8 cups of water. Simmer over medium heat for 1 hour.","Add the chopped onion, pepper, chili powder, tomato sauce, and oregano to simmering chicken.","After the chicken is thoroughly cooked take the pieces out of the pot and remove most of the bones from the chicken and the pot.","Return chicken to the pot.","Add the rinsed hominy to the pot of chicken and simmer for another 45 minutes.","Serve with lettuce and a wedge of lime."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"286.14 kcal","carbohydrateContent":"26.33 g","cholesterolContent":"72.23 mg","fiberContent":"6.42 g","proteinContent":"27.06 g","sodiumContent":"610.74 mg","sugarContent":"4.64 g","fatContent":"8.15 g","saturatedFatContent":"1.98 g"},"notes":"To make even healthier, use tomato sauce with no added salt. Chicken breasts or thighs can be substituted for the whole chicken.","contributor":"Pictorial Recipes\nOregon State University Cooperative Extension Service\nOregon Family Nutrition Program\nRecipe submitted by Lynn Myers Steele, 2000"},
{"slug":"chicken-ratatouille","source_url":"https://www.myplate.gov/recipes/chicken-ratatouille","name":"Chicken Ratatouille","description":"Chicken is added to this traditional vegetable dish of tomatoes, zucchini, and eggplant for a hearty and satisfying meal.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","2 medium boneless chicken breast","2 medium zucchini, unpeeled and sliced","1 small eggplant, peeled and cut into 1-inch cubes","1 medium onion, sliced","1 red or green bell pepper, cut into pieces","1/2 pound mushrooms, sliced","1 can (14.5 ounces) tomatoes, low-sodium, diced","1 garlic clove, minced","1 tablespoon fresh basil, chopped","1 tablespoon fresh parsley, minced","black pepper (to taste)"]}],"directions":[{"name":null,"steps":["Remove skin and fat from chicken and cut into 1-inch pieces","Heat oil in large non-stick skillet. Add chicken and sauté about 3 minutes, or until lightly browned.","Add zucchini, eggplant, onion, green pepper, and mushrooms. Cook about 15 minutes, stirring occasionally.","Add tomatoes, garlic, basil, parsley, and pepper; stir and continue cooking about 5 minutes, or until chicken is tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"184.74 kcal","carbohydrateContent":"15.92 g","cholesterolContent":"45.01 mg","fiberContent":"5.07 g","proteinContent":"18.21 g","sodiumContent":"43.39 mg","sugarContent":"9.43 g","fatContent":"5.98 g","saturatedFatContent":"1.00 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"chicken-rice-and-fruit-salad","source_url":"https://www.myplate.gov/recipes/chicken-rice-and-fruit-salad","name":"Chicken, Rice, and Fruit Salad","description":"Leftover rice? Use it in this fruit and chicken salad for a new spin on chicken salad. Serve the dish on lettuce leaves.","ingredients":[{"name":null,"items":["1 cup brown rice, cooked","2 teaspoons parsley, dried (or 2 Tablespoons fresh, finely chopped)","1/2 teaspoon ground black pepper","1/4 clove garlic, finely chopped","1 tablespoon ranch dressing, fat-free","2 tablespoons mayonnaise, fat-free","1 cup apple or cantaloupe, cut into chunks","1/3 cup grape halves, red or purple, cut into chunks","1/2 cup celery, chopped","1 1/4 cups chicken, cooked, cut into bite-size pieces","6 lettuce leaves"]}],"directions":[{"name":null,"steps":["If not using leftover or \"planned over\" rice, cook rice according to package directions without adding salt. Chill.","In a serving bowl, mix parsley, black pepper, garlic, dressing, and mayonnaise together.","Add cooled rice, apple, grapes, celery, and chicken. Stir gently.","Serve cold on a bed of clean lettuce leaves, if desired.","Cover and refrigerate leftovers within 2 hours."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 of recipe","calories":"227.16 kcal","carbohydrateContent":"29.87 g","cholesterolContent":"55.57 mg","fiberContent":"2.94 g","proteinContent":"19.69 g","sodiumContent":"176.79 mg","sugarContent":"9.12 g","fatContent":"2.95 g","saturatedFatContent":"0.67 g"},"notes":"A child could wash the fruit and help remove the seeds.\nNote: Recipe analysis was done using brown rice.","contributor":"Fix it Fresh! Recipe Series\nKansas State University Research and Extension"},
{"slug":"chicken-rice-salad","source_url":"https://www.myplate.gov/recipes/chicken-rice-salad","name":"Chicken Rice Salad","description":"Add fresh vegetables and seasonings to leftover chicken that has been properly handled and rice for a quick and delicious salad.","ingredients":[{"name":null,"items":["4 cups lettuce","2 cups brown rice, cooked","2 cups skinless chicken breast, roasted","1 tomato, cored and diced","1 green pepper, cored and diced","1 tablespoon olive oil (or cooking oil of choice)","1 lemon, juiced","2 tablespoons vinegar, flavored","hot pepper sauce (optional)","Italian herb mix and black pepper to taste (optional)"]}],"directions":[{"name":null,"steps":["Toss all ingredients together in a large salad bowl.","Use personal taste preferences to determine the amounts of seasonings.","Serve immediately. This salad looks great when served on a large plate with a few of the seasonings sprinkled on top."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cups prepared salad","calories":"280.28 kcal","carbohydrateContent":"28.99 g","cholesterolContent":"66.69 mg","fiberContent":"2.71 g","proteinContent":"24.11 g","sodiumContent":"45.76 mg","sugarContent":"2.22 g","fatContent":"7.07 g","saturatedFatContent":"1.35 g"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"chicken-rice-soup","source_url":"https://www.myplate.gov/recipes/chicken-rice-soup","name":"Chicken and Rice Soup","description":"Add your favorite veggies and brown rice to this yummy chicken soup for a warm meal on a cold night.","ingredients":[{"name":null,"items":["1 cup cooked chicken (diced)","6 cups low-sodium chicken broth","1 cup uncooked rice","1 3/4 cups mixed vegetables","1/2 teaspoon garlic powder","1/4 teaspoon black pepper","1/4 teaspoon salt","1 tablespoon dried parsley"]}],"directions":[{"name":null,"steps":["Use leftover cooked chicken or cook enough chicken to make 1 cup of chicken pieces.","Place the cooked chicken in a large saucepan.","Add the broth and uncooked rice. Cover the pan.","Bring the broth and rice to a boil.","Cover the pan and turn the heat to low.","Stir and simmer for 15 minutes.","Add the chopped onions, chopped vegetables, and seasonings.","Simmer for 10 to 15 minutes until the vegetables are tender."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cups prepared soup","calories":"175.73 kcal","carbohydrateContent":"27.65 g","cholesterolContent":"16.67 mg","fiberContent":"2.11 g","proteinContent":"11.87 g","sodiumContent":"151.71 mg","sugarContent":"1.52 g","fatContent":"1.95 g","saturatedFatContent":"0.53 g"},"notes":null,"contributor":"Adapted from Chicken Soup Recipe: Pennsylvania Nutrition Education Network"},
{"slug":"chicken-salad-and-peach-sandwich","source_url":"https://www.myplate.gov/recipes/chicken-salad-and-peach-sandwich","name":"Chicken Salad and Peach Sandwich","description":"Crunch into this chicken salad sandwich with crisp celery, apples, and red onion, rounded out by sweet peaches and soft, whole grain bread. Perfect for a pic...","ingredients":[{"name":null,"items":["4 slices of whole grain bread","1/2 cup cooked chicken (diced)","1/2 cup canned peach slices (drained and diced)","1 celery stalk","1/2 cup apples (Fuji, Gala, or Braeburn)","1 small onion","1 1/2 tablespoons mayonnaise (nonfat)","1 tablespoon chopped walnuts"]}],"directions":[{"name":null,"steps":["Mix together the chicken, apples, peaches, celery, onion, walnuts, and mayonnaise in a small bowl.","Spoon mixture onto 2 slices of the bread."]}],"yield":"2 Sandwiches","nutrition":{"@type":"NutritionInformation","servingSize":"1 sandwich","calories":"344.96 kcal","carbohydrateContent":"51.23 g","cholesterolContent":"33.34 mg","fiberContent":"7.78 g","proteinContent":"20.83 g","sodiumContent":"450.85 mg","sugarContent":"17.88 g","fatContent":"6.40 g","saturatedFatContent":"1.07 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"chicken-salad-ramen-noodles","source_url":"https://www.myplate.gov/recipes/chicken-salad-ramen-noodles","name":"Chicken Salad with Ramen Noodles","description":"Use up a large head of cabbage from the farmers'' market or grocery store with this recipe. The bell pepper and green onions bring a variety of flavors while ...","ingredients":[{"name":null,"items":["1 package (3 ounces) Ramen noodles (any flavor)","1 cup red or green bell pepper","1/4 cup scallions, minced","1/2 cup dry roasted peanuts, unsalted","2 cooked chicken breast, chilled and cut into cubes","8 cups cabbage, shredded (or cabbage salad mix)"]},{"name":"Salad Dressing","items":["2 teaspoons sugar","2 tablespoons olive oil (or cooking oil of choice)","1/2 cup vinegar, rice or white wine","1 teaspoon Ramen noodle flavor packet"]}],"directions":[{"name":null,"steps":["Break up noodles. Set aside.","In a large bowl, add peppers, scallions, unsalted peanuts, and other vegetables if you like. Add cooked chicken and cabbage.","In a small bowl make dressing with sugar, vinegar, olive oil, and flavor packet. Stir well.","Pour the dressing over the salad and combine. Sprinkle noodles on top.","Serve cold."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"204.42 kcal","carbohydrateContent":"16.58 g","cholesterolContent":"29.67 mg","fiberContent":"3.60 g","proteinContent":"13.83 g","sodiumContent":"169.05 mg","sugarContent":"5.18 g","fatContent":"9.62 g","saturatedFatContent":"1.52 g"},"notes":null,"contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"chicken-salad","source_url":"https://www.myplate.gov/recipes/chicken-salad","name":"Chicken Salad","description":"Onion and pickle relish spice up a traditional chicken salad.","ingredients":[{"name":null,"items":["2 1/2 cups cooked chicken breast, diced","1/2 cup celery, chopped","1/4 cup onion, chopped","3 packages pickle relish (2 tablespoons)","1/2 cup light mayonnaise"]}],"directions":[{"name":null,"steps":["Combine all ingredients.","Refrigerate until ready to serve.","Use within 1-2 days. Chicken salad does not freeze well.","How to use:","Make chicken salad sandwiches.","Make a pasta salad by mixing with 2 cups cooked pasta.","Kids will love this salad served in a tomato or a cucumber boat."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"150.67 kcal","carbohydrateContent":"4.36 g","cholesterolContent":"58.91 mg","fiberContent":"0.32 g","proteinContent":"17.35 g","sodiumContent":"244.12 mg","sugarContent":"2.57 g","fatContent":"6.66 g","saturatedFatContent":"1.16 g"},"notes":null,"contributor":"Adapted from: Any Day''s a Picnic Chicken Salad, University of Wisconsin Cooperative Extension Service\nA Family Living Program"},
{"slug":"chicken-soup-chiles","source_url":"https://www.myplate.gov/recipes/chicken-soup-chiles","name":"Chicken Soup with Chiles","description":"Flavorful and filling, this soup is packed with protein making it a full meal. Add extra chiles or a dash of red pepper flakes if you like a spicier soup.","ingredients":[{"name":null,"items":["3 pounds chicken pieces, skin removed","2 cups tomatoes, chopped","1 garlic clove, minced","1/2 cup onion, chopped","1/4 cup mild chiles, canned and diced","2 cups pinto or garbanzo beans, canned or cooked and drained","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Place chicken pieces in a large saucepan and add enough water to cover.","Cook over medium high heat until tender and chicken is cooked, about 25 minutes.","Remove chicken pieces from the broth.","Add tomatoes, garlic, onion, and chiles.","Remove chicken meat from the bones and return meat to broth.","Add beans and salt and pepper to taste. Simmer for about 15 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared soup","1/6 of recipe"],"calories":"345.29 kcal","carbohydrateContent":"18.88 g","cholesterolContent":"150.13 mg","fiberContent":"5.32 g","proteinContent":"51.57 g","sodiumContent":"291.90 mg","sugarContent":"2.86 g","fatContent":"6.04 g","saturatedFatContent":"1.30 g"},"notes":null,"contributor":"Pumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"chicken-soup-soul","source_url":"https://www.myplate.gov/recipes/chicken-soup-soul","name":"Chicken Soup for the Soul","description":"Green peas and carrots brighten up this traditional chicken soup!","ingredients":[{"name":null,"items":["1 stalk of celery, chopped","1 carrot, chopped","1 onion, chopped","1 cup frozen peas","5 1/2 cups of low-sodium chicken broth","1 cup cooked chicken, cubed, or canned (drained)","1/2 cup uncooked rice, macaroni, or small noodles"]}],"directions":[{"name":null,"steps":["Combine celery, carrots, onions, peas, and chicken broth in a pot. Bring to a boil.","Add chicken and reduce heat.","Add rice, macaroni, or noodles.","Simmer on low until rice, macaroni, or noodles are tender and flavors are mixed. Chicken should reach a final internal cook temperature of 165°F as measured with a food thermometer before serving."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"253.52 kcal","carbohydrateContent":"34.87 g","cholesterolContent":"33.34 mg","fiberContent":"3.28 g","proteinContent":"21.46 g","sodiumContent":"164.56 mg","sugarContent":"4.61 g","fatContent":"3.58 g","saturatedFatContent":"0.95 g"},"notes":null,"contributor":"Recipe adapted from First Nations Development Institute"},
{"slug":"chicken-spaghetti","source_url":"https://www.myplate.gov/recipes/chicken-spaghetti","name":"Chicken Spaghetti","description":"This colorful crowd-pleaser that incorporates vegetables, whole grains, protein, and dairy in one dish. Serve with some fresh, frozen, canned, or dried fruit...","ingredients":[{"name":null,"items":["4 sprays of vegetable oil spray","4 ounces spaghetti, whole wheat uncooked","1 teaspoon olive oil (or cooking oil of choice)","1 medium red bell pepper, thinly sliced","1 medium green bell pepper, thinly sliced","1 onion, chopped","2 cups cooked chicken breast, skinless and diced (8 ounces)","1 can (14.5 ounces) tomatoes, low-sodium, diced undrained","1 can (10.75 ounces) cream of chicken soup, low-sodium","1/2 cup cheddar cheese, reduced-fat shredded","1/4 cup Parmesan cheese, shredded or grated","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F. Lightly spray an 8-inch square baking dish with vegetable oil spray.","Prepare the spaghetti using the package directions, omitting the salt and oil. Drain well in a colander.","Meanwhile, in a large skillet, heat the oil over medium heat, swirling to coat the bottom. Cook the bell peppers and onion for 4 to 5 minutes, or until tender, stirring occasionally.","Pour into a large bowl. Stir in the remaining ingredients, including the spaghetti. Pour into a baking dish.","Bake, covered, for 20 minutes. Bake, uncovered for 10 minutes, or until the mixture is warmed through and light golden brown on top."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"397.68 kcal","carbohydrateContent":"42.97 g","cholesterolContent":"86.19 mg","fiberContent":"6.75 g","proteinContent":"33.81 g","sodiumContent":"473.94 mg","sugarContent":"7.32 g","fatContent":"10.87 g","saturatedFatContent":"3.94 g"},"notes":null,"contributor":"Power to End Stroke: 46 Healthy Soul Food Recipes Cookbook\nAmerican Heart Association"},
{"slug":"chicken-spanish-rice","source_url":"https://www.myplate.gov/recipes/chicken-spanish-rice","name":"Chicken Spanish Rice","description":"This flavorful rice uses canned tomatoes and chicken with fresh onion, green pepper, and celery. Chili powder and black pepper make it a perky main dish.","ingredients":[{"name":null,"items":["1/2 cup onion, chopped","1/2 cup green pepper, chopped","1/3 cup celery, sliced","1/2 cup rice, dry","1 teaspoon vegetable oil (or cooking oil of choice)","1 can (14.5 ounces) tomatoes, low-sodium","1 1/2 cups canned chicken","3/4 cup water","1/2 teaspoon chili powder","black pepper (optional, to taste)"]}],"directions":[{"name":null,"steps":["Cook onion, green pepper, celery, and rice in vegetable oil at medium heat in a large saucepan until soft, about 5 minutes.","Drain tomatoes and save the liquid.","Chop tomatoes into small pieces.","Add tomatoes, liquid, chicken, water, chili powder, and pepper to rice mixture.","Bring to a boil and stir. Cover and cook on low heat. Cook until rice is tender (about 25 minutes)."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"277.02 kcal","carbohydrateContent":"27.87 g","cholesterolContent":"38.44 mg","fiberContent":"3.07 g","proteinContent":"22.67 g","sodiumContent":"402.19 mg","sugarContent":"4.24 g","fatContent":"7.97 g","saturatedFatContent":"2.00 g"},"notes":null,"contributor":"Healthy Eating in Indian Country: Exercise\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"chicken-stew","source_url":"https://www.myplate.gov/recipes/chicken-stew","name":"Chicken Stew","description":"This classic stew can be made on the stove top and cooked in less than an hour. The vegetables and chicken make it a filling meal by itself.","ingredients":[{"name":null,"items":["8 boneless chicken breasts","1 cup water","2 garlic cloves, minced","1 medium onion, chopped","1 1/2 teaspoons salt","1/2 teaspoon black pepper","3 medium tomatoes, chopped","1/3 tablespoon parsley, chopped (1 teaspoon)","1/4 cup celery, finely chopped","2 medium potatoes, peeled and chopped","2 medium carrots, chopped","2 bay leaves"]}],"directions":[{"name":null,"steps":["Remove the skin from the chicken and any extra fat. In a large skillet combine chicken, water, garlic, onion, salt, pepper, tomatoes, and parsley. Tightly cover and cook over low heat for 25 minutes.","Add celery, potatoes, carrots, and bay leaves and continue to cook for 15 minutes or until chicken is cooked and vegetables are tender. Remove bay leaves before serving."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"210.90 kcal","carbohydrateContent":"14.27 g","cholesterolContent":"90.02 mg","fiberContent":"2.08 g","proteinContent":"29.64 g","sodiumContent":"510.74 mg","sugarContent":"3.03 g","fatContent":"3.41 g","saturatedFatContent":"0.74 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"chicken-stir-fry","source_url":"https://www.myplate.gov/recipes/chicken-stir-fry","name":"Chicken Stir-Fry","description":"This stir-fry is delicious for lunch or dinner. It is very quick to fix. It may also be served over spaghetti, rotini, and other macaroni products.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil","1/2 cup carrots, peeled, sliced thinly (or 1/2 can low-sodium carrots, about 8 ounces, drained)","1/2 cup celery, sliced thin","1/4 cup onion, cut into strips","1 green pepper, cut into strips","1 tablespoon garlic, finely chopped","1 tablespoon ginger, finely chopped (optional)","1 pound chicken, cooked, skin removed, sliced into strips","1/2 teaspoon sugar","3 tablespoons soy sauce, reduced sodium","3 cups white rice, cooked (or brown rice)"]}],"directions":[{"name":null,"steps":["Heat a large pan with vegetable oil over high heat.","Add vegetables and garlic to the hot pan. Stir until garlic is slightly brown. If using ginger, add that too.","Add the chicken and sugar to the pan, then add soy sauce.","Stir the food for about 1 minute in the pan.","Serve with cooked rice."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"248.16 kcal","carbohydrateContent":"26.58 g","cholesterolContent":"50.04 mg","fiberContent":"1.18 g","proteinContent":"18.77 g","sodiumContent":"328.94 mg","sugarContent":"1.93 g","fatContent":"6.80 g","saturatedFatContent":"1.11 g"},"notes":"Tip for cooking chicken: The recommended safe minimum internal temperature for chicken is 165 °F, as measured by a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"chicken-tortilla-casserole","source_url":"https://www.myplate.gov/recipes/chicken-tortilla-casserole","name":"Chicken Tortilla Casserole","description":"Add low-fat dairy to your dinner with this layered casserole that uses both milk and cheese.","ingredients":[{"name":null,"items":["1 can (10.5 ounces) cream of mushroom soup, reduced sodium","1 cup 1% milk","1 1/2 cups boneless, skinless chicken, cut into pieces","4 ounces canned chopped green chiles","1 (6-inch) corn tortilla, cut into strips","2 cups cheddar cheese, low-fat, shredded"]}],"directions":[{"name":null,"steps":["Mix mushroom soup, milk, chicken, and green chile peppers.","Pour 1/3 of the soup mixture into the bottom of a 2-quart baking dish that has been coated with oil or cooking spray","Layer half the tortilla strips.","Spread 1/3 of the soup mixture on top of the tortillas.","Sprinkle on half the cheese.","Repeat layers of tortilla strips and soup mix and end with cheese.","Baked at 350 °F for 1 hour."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"263.01"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"chicken-vegetable-soup-kale","source_url":"https://www.myplate.gov/recipes/chicken-vegetable-soup-kale","name":"Chicken Vegetable Soup with Kale","description":"Kale and carrots add lots of vitamin A to this hearty soup. It is a great recipe for using the beautiful kale from the farmers market.","ingredients":[{"name":null,"items":["2 teaspoons vegetable oil (or cooking oil of choice)","1/2 cup onion, chopped","1/2 cup carrots, chopped","1 teaspoon thyme, dried","2 garlic cloves, minced","2 cups water (or low-sodium chicken broth)","3/4 cup tomatoes, diced","1 cup chicken, cooked, skinned and cubed","1/2 cup brown rice, cooked (or white rice)","1 cup kale, chopped (about one large leaf)"]}],"directions":[{"name":null,"steps":["Heat oil in a medium sauce pan. Add onion and carrots. Sauté until vegetables are tender, about 5 to 8 minutes.","Add thyme and garlic. Sauté for one more minute.","Add water or broth, tomatoes, chicken, cooked rice, and kale.","Simmer for 5 to 10 minutes."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 of recipe","calories":"174.78 kcal","carbohydrateContent":"15.47 g","cholesterolContent":"44.46 mg","fiberContent":"2.41 g","proteinContent":"15.89 g","sodiumContent":"53.86 mg","sugarContent":"3.18 g","fatContent":"5.33 g","saturatedFatContent":"0.91 g"},"notes":null,"contributor":"Washington State University\nThe Washington Senior Farmers Market Nutrition Program\nPuyallup Research and Extension Center"},
{"slug":"chicken-waldorf-salad","source_url":"https://www.myplate.gov/recipes/chicken-waldorf-salad","name":"Chicken Waldorf Salad","description":"This recipe is a perfect way to use leftover chicken. With just 15 minutes of prep time, this recipe will be ready in a snap. No leftovers? Use the quick tip...","ingredients":[{"name":null,"items":["1/3 cup low-fat mayonnaise","1/3 cup low-fat plain yogurt (or non-fat)","2 teaspoons lemon juice","1/4 teaspoon salt","3 cups cooked chicken breast, chopped","1 medium red apple, diced","1 cup red or green grapes, halved","1 cup celery, sliced","1/2 cup chopped walnuts, divided (toasted if desired)"]}],"directions":[{"name":null,"steps":["Whisk mayonnaise, yogurt, lemon juice and salt in a large bowl.","Add chicken, apple, grapes, celery, and half of the walnuts. Stir to coat well.","Serve topped with the remaining walnuts."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"385.40 kcal","carbohydrateContent":"20.64 g","cholesterolContent":"104.54 mg","fiberContent":"2.88 g","proteinContent":"34.81 g","sodiumContent":"406.42 mg","sugarContent":"14.88 g","fatContent":"18.46 g","saturatedFatContent":"2.66 g"},"notes":"Quick Tip: If you want cooked chicken in a hurry, the easiest way to cook it is to poach it (one pound of raw boneless, skinless chicken breasts yields about 2 1/2 cups chopped or shredded cooked chicken).\nPlace boneless, skinless chicken breasts in a skillet or saucepan.\nAdd lightly salted water (or chicken broth) to cover and bring to a boil.\nCover, reduce heat to low, and simmer gently until the chicken is cooked through and no longer pink in the middle (approximately 10 to 15 minutes).","contributor":"EatingWell Magazine"},
{"slug":"chickpea-dip","source_url":"https://www.myplate.gov/recipes/chickpea-dip","name":"Chickpea Dip","description":"Make your own delicious chickpea dip! Yogurt and paprika add a new dimension to this hummus recipe.","ingredients":[{"name":null,"items":["3 garlic cloves","1/4 cup yogurt, plain, fat-free","1 tablespoon lemon juice, fresh","1 teaspoon olive oil (or cooking oil of choice)","1/4 teaspoon salt","1/4 teaspoon paprika","1/8 teaspoon black pepper","1 can (15 ounces) chickpeas, low-sodium, drained (garbanzo beans)"]}],"directions":[{"name":null,"steps":["Put all ingredients into a food processor and blend until smooth.","Serve at room temperature with pita chips, crackers, carrots, or other dipping vegetables."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"120.41 kcal","carbohydrateContent":"17.02 g","cholesterolContent":"0.31 mg","fiberContent":"4.97 g","proteinContent":"6.47 g","sodiumContent":"304.89 mg","sugarContent":"4.16 g","fatContent":"3.38 g","saturatedFatContent":"0.43 g"},"notes":null,"contributor":"More Matters Recipes\nUS Department of Health and Human Services\nCenters for Disease Control and Prevention (CDC)"},
{"slug":"chickpeas-and-spinach-saute","source_url":"https://www.myplate.gov/recipes/chickpeas-and-spinach-saute","name":"Chickpeas and Spinach Sauté","description":"Sautéed veggies simmered with a can of tomatoes, chickpeas and wilted spinach make up this colorful dish. This recipes calls for chickpeas and spinach but a...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1 yellow onion (peeled and chopped)","1 clove garlic (peeled and minced)","1 celery stalk (chopped)","1 carrot (chopped)","1 can (14.5 oz) diced tomatoes, no salt added (including liquid)","1 can (16 oz) low-sodium chickpeas (drained and rinsed with cold water)","1/4 cup water","1 package (10 oz) frozen spinach (kale can be used instead of spinach)","1 teaspoon fresh lemon juice (or red vinegar)","1/4 teaspoon crushed red pepper flakes"]}],"directions":[{"name":null,"steps":["Put a skillet on the stove on medium high heat. When the skillet is hot, add oil.","Add onion, garlic, celery and carrot and cook about 15 minutes until the mixture is soft and the onions are lightly browned.","Raise the heat to high and add the tomatoes, beans (white beans instead of chickpeas) and water and cook for 5 minutes. Lower the heat to low and top the mixture with the spinach (don’t worry about stirring). Cover and cook until the spinach has thawed and heated throughout, about 10 minutes. Stir well.","Add the lemon juice and red pepper flakes and stir thoroughly.","Serve with cooked quinoa or brown rice."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"192.64 kcal","carbohydrateContent":"27.30 g","cholesterolContent":"0.00 mg","fiberContent":"10.70 g","proteinContent":"9.72 g","sodiumContent":"243.85 mg","sugarContent":"8.25 g","fatContent":"6.61 g","saturatedFatContent":"0.87 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"chili-and-spice-seasoning","source_url":"https://www.myplate.gov/recipes/chili-and-spice-seasoning","name":"Chili and Spice Seasoning","description":"A combination of zesty herbs and spices add flavor without adding salt. Make this seasoning mix ahead of time and keep it in your pantry to use in soups, ste...","ingredients":[{"name":null,"items":["1/4 tablespoon paprika","2 tablespoons oregano (dried, crushed)","2 teaspoons chili powder","1 teaspoon garlic powder","1 teaspoon black pepper","1/2 teaspoon cayenne pepper","1/2 teaspoon dry mustard"]}],"directions":[{"name":null,"steps":["Mix together all ingredients.","Store in airtight container."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 tablespoon","calories":"18.06 kcal","carbohydrateContent":"3.89 g","cholesterolContent":"0.00 mg","fiberContent":"2.14 g","proteinContent":"0.74 g","sodiumContent":"40.28 mg","sugarContent":"0.29 g","fatContent":"0.48 g","saturatedFatContent":"0.10 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"chili-bean-dip","source_url":"https://www.myplate.gov/recipes/chili-bean-dip","name":"Chili Bean Dip","description":"This dip goes great with baked tortilla chips or raw vegetables at a party. You can experiment with the spices to get new flavors.","ingredients":[{"name":null,"items":["1 can (15.5 ounces) pinto beans, low-sodium (or 2 cups cooked dried beans)","2 tablespoons onion, chopped","1 teaspoon chili powder","1/2 cup cheddar cheese, shredded"]}],"directions":[{"name":null,"steps":["Mash beans in a bowl.","Add onion and chili powder and shredded cheese.","Serve warm or cold with raw vegetables or tortilla chips."]}],"yield":"15 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 Tablespoons prepared dip","calories":"40.44 kcal","carbohydrateContent":"4.74 g","cholesterolContent":"3.77 mg","fiberContent":"1.43 g","proteinContent":"2.26 g","sodiumContent":"72.58 mg","sugarContent":"0.40 g","fatContent":"1.47 g","saturatedFatContent":"0.76 g"},"notes":null,"contributor":"Healthy Snacks\nUniversity of Wisconsin Cooperative Extension Service"},
{"slug":"chili-cheese-hominy","source_url":"https://www.myplate.gov/recipes/chili-cheese-hominy","name":"Chili Cheese Hominy","description":"If you’ve never tried hominy before, you are in for a treat! This dish makes a great comfort food with a creamy texture and a spicy and flavorful flare.","ingredients":[{"name":null,"items":["1 teaspoon vegetable oil (or cooking oil of choice)","1/2 cup onion, chopped (about 1/2 medium onion)","4 cups instant white or yellow hominy, cooked","2 cans (4 ounces each) chopped green chiles, drained","1 cup non-fat sour cream","1 teaspoon chili powder","1/8 teaspoon black pepper","3/4 cup shredded cheddar cheese, divided"]}],"directions":[{"name":null,"steps":["Heat oil in a large skillet over medium high heat (350 °F in an electric skillet). Add onion and cook until tender, about 2 to 3 minutes.","Stir in hominy, green chiles, sour cream, chili powder and pepper. Add half of the cheese and mix well.","Reduce heat to medium (300 °F in an electric skillet). Cover and cook until heated through, about 3 to 5 minutes.","Sprinkle remaining cheese on top. Cover and cook until cheese melts, about 5 minutes."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"159.79 kcal","carbohydrateContent":"25.13 g","cholesterolContent":"13.29 mg","fiberContent":"1.74 g","proteinContent":"5.42 g","sodiumContent":"492.23 mg","sugarContent":"0.95 g","fatContent":"4.80 g","saturatedFatContent":"2.22 g"},"notes":"Try with different types of grated or crumbled cheese.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"chili-popcorn","source_url":"https://www.myplate.gov/recipes/chili-popcorn","name":"Chili Popcorn","description":"Make your own savory popcorn featuring chili and garlic flavors. Popcorn is one way to add whole grains and fiber into your diet.","ingredients":[{"name":null,"items":["4 cups popcorn","1 tablespoon margarine, melted","1 teaspoon chili powder","1/16 teaspoon (a dash) garlic powder"]}],"directions":[{"name":null,"steps":["Mix popcorn and margarine in a bowl.","Mix seasonings thoroughly and sprinkle over popcorn. Mix well.","Serve immediately and enjoy with family and friends."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"51.64 kcal","carbohydrateContent":"6.62 g","cholesterolContent":"0.04 mg","fiberContent":"1.40 g","proteinContent":"1.14 g","sodiumContent":"43.60 mg","sugarContent":"0.12 g","fatContent":"2.55 g","saturatedFatContent":"0.49 g"},"notes":null,"contributor":"Eat Smart. Play Hard.™\nUSDA Food and Nutrition Service"},
{"slug":"chili-tomato-macaroni","source_url":"https://www.myplate.gov/recipes/chili-tomato-macaroni","name":"Chili Tomato Macaroni","description":"You don’t have to use salt in this macaroni, tomato, and beef dish seasoned with the Eating Smart Seasoning Mix.","ingredients":[{"name":null,"items":["3/4 pound ground beef, 90% lean","1 1/2 cups water","1 cup macaroni, uncooked","1 can (14.5 ounces) diced tomatoes, low-sodium, undrained","2 teaspoons chili powder, mild","1/2 Eating Smart Seasoning Mix","salt (optional, to taste)","2 ounces cheddar cheese, reduced-fat, shredded"]}],"directions":[{"name":null,"steps":["Brown ground beef in a large skillet, drain the fat.","Add water, macaroni, tomatoes, chili powder, and seasoning mix. Stir.","Bring to a boil, reduce heat to low and simmer covered on low heat for 20 minutes or until macaroni is tender.","Taste, and add a small amount of salt if desired.","Top with shredded cheddar cheese. Put the lid back on for 1 minute until the cheese is melted."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"320.79 kcal","carbohydrateContent":"30.30 g","cholesterolContent":"61.43 mg","fiberContent":"3.90 g","proteinContent":"26.19 g","sodiumContent":"224.25 mg","sugarContent":"7.46 g","fatContent":"10.28 g","saturatedFatContent":"4.47 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"chilled-blueberry-soup","source_url":"https://www.myplate.gov/recipes/chilled-blueberry-soup","name":"Chilled Blueberry Soup","description":"This refreshing and beautiful quick, summer soup features a blend of blueberries, apple juice, and low-fat yogurt, and is garnished with fresh mint leaves.","ingredients":[{"name":null,"items":["2 cups fresh blueberries (about 2 6-oz containers)","1 cup 100% apple juice","1 1/2 cups plain low-fat yogurt","1 teaspoon cinnamon","Fresh mint leaves for garnish"]}],"directions":[{"name":null,"steps":["Rinse blueberries and set aside a few for garnishing.","Blend all ingredients in food processor or blender.","Serve immediately.","Garnish with mint leaves and blueberries, if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"132.00 kcal","carbohydrateContent":"24.87 g","cholesterolContent":"5.51 mg","fiberContent":"2.27 g","proteinContent":"5.46 g","sodiumContent":"68.23 mg","sugarContent":"20.21 g","fatContent":"1.83 g","saturatedFatContent":"0.96 g"},"notes":"Serving Suggestions: Serve with grilled salmon fish fillet (about 3 to 4 ounces), asparagus, and water with lemon slice.","contributor":"Produce for Better Health Foundation"},
{"slug":"chilled-cantaloupe-soup","source_url":"https://www.myplate.gov/recipes/chilled-cantaloupe-soup","name":"Chilled Cantaloupe Soup","description":"This cool, refreshing melon and citrus soup is perfect for a day when it is too hot to cook. Have it with a hearty, protein-filled sandwich on whole grain br...","ingredients":[{"name":null,"items":["1 cantaloupe, peeled, seeded, and cubed","2 cups orange juice","1 tablespoon lime juice","1/4 teaspoon ground cinnamon"]}],"directions":[{"name":null,"steps":["Place cantaloupe and 1/2 cup orange juice in a container of a blender or food processor.","Cover with lid and blend until smooth. Transfer to large bowl.","Stir in lime juice, cinnamon, and remaining orange juice.","Cover, and refrigerate for at least one hour.","Serve chilled."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"74.60 kcal","carbohydrateContent":"16.05 g","cholesterolContent":"0.00 mg","fiberContent":"1.05 g","proteinContent":"1.44 g","sodiumContent":"27.56 mg","sugarContent":"13.95 g","fatContent":"0.47 g","saturatedFatContent":"0.05 g"},"notes":null,"contributor":"Champions for Change Recipes\nArizona Nutrition Network"},
{"slug":"chimichurri-sauce","source_url":"https://www.myplate.gov/recipes/chimichurri-sauce","name":"Chimichurri Sauce","description":"Add some South American flair to your meal with this flavorful sauce, which can be used on meat, fish, or vegetables as a marinade or poured over your finish...","ingredients":[{"name":null,"items":["1 cup flat-leaf parsley, lightly packed and chopped without the stalks","4 garlic cloves, minced","1/8 teaspoon salt","1/4 teaspoon peppercorn, freshly ground","1/2 teaspoon chili pepper flakes","1 tablespoon dried oregano","2 tablespoons green onion, minced","1/2 cup olive oil","3/4 cup vinegar","3 tablespoons fresh lemon juice","1/4 cup water"]}],"directions":[{"name":null,"steps":["Place all the ingredients in a blender or food processor and pulse until well chopped, but not pureed.","Spoon the sauce over grilled meats, poultry, seafood, or vegetables. This sauce can also be used as a marinade."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3 Tablespoons (40g)","calories":"93.09 kcal","carbohydrateContent":"1.46 g","cholesterolContent":"0.00 mg","fiberContent":"0.48 g","proteinContent":"0.29 g","sodiumContent":"30.01 mg","sugarContent":"0.25 g","fatContent":"9.41 g","saturatedFatContent":"1.46 g"},"notes":null,"contributor":"Adapted from Argentinian Chimichurri Sauce\nDelicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"chocolate-chip-yogurt-cookies","source_url":"https://www.myplate.gov/recipes/chocolate-chip-yogurt-cookies","name":"Chocolate Chip Yogurt Cookies","description":"Add extra calcium to your cookies with yogurt. These cookies also use whole wheat flour which adds fiber and other nutrients.","ingredients":[{"name":null,"items":["1/2 cup sugar","1/2 cup brown sugar, firmly packed","1/2 cup margarine (1 stick)","1/2 cup plain yogurt, non-fat","1 1/2 teaspoons vanilla","3/4 cup all-purpose flour","1 cup whole wheat flour","1/2 teaspoon baking soda","1/2 cup chocolate chips (miniature, or carob chips)"]}],"directions":[{"name":null,"steps":["Heat oven to 375 °F.","In a large bowl combine sugar, brown sugar and margarine; beat until light and fluffy.","Add yogurt and vanilla; blend well. Stir in flour and baking soda; mix well. Stir in chocolate chips.","Drop dough by rounded teaspoonfuls 2 inches apart onto un-greased cookie sheets. Bake at 375 °F for 8 to 12 minutes or until light and golden brown.","Cool 1 minute, remove from cookie sheets."]}],"yield":"36 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cookie","calories":"77.55 kcal","carbohydrateContent":"12.46 g","cholesterolContent":"0.10 mg","fiberContent":"0.61 g","proteinContent":"1.04 g","sodiumContent":"42.43 mg","sugarContent":"7.74 g","fatContent":"2.92 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Eat Smart New York!\nCornell University Cooperative Extension"},
{"slug":"chocolate-peanut-butter-frozen-bars","source_url":"https://www.myplate.gov/recipes/chocolate-peanut-butter-frozen-bars","name":"Chocolate Peanut Butter Frozen Bars","description":"Keep these treats in your freezer for a special day. Peanut butter and chocolate pudding make a delicious coating for graham crackers.","ingredients":[{"name":null,"items":["2 packages (1.4 ounces each) low calorie chocolate pudding, instant (or cook and serve type)","3 1/2 cups skim milk","1/4 cup peanut butter","15 graham cracker rectangles (break crackers apart)"]}],"directions":[{"name":null,"steps":["Mix pudding according to package directions, except use 3 1/2 cups milk. Beat in peanut butter.","Line a 9x13 inch pan with half the graham crackers.","Spread pudding mixture over graham crackers. Top with remaining crackers.","Freeze for four hours.","Cut into squares and remove from pan.","Store in a plastic bag in the freezer."]}],"yield":"15 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 bar","calories":"130.11 kcal","carbohydrateContent":"19.58 g","cholesterolContent":"1.71 mg","fiberContent":"1.04 g","proteinContent":"4.20 g","sodiumContent":"270.41 mg","sugarContent":"7.08 g","fatContent":"3.94 g","saturatedFatContent":"0.76 g"},"notes":null,"contributor":"Cooking Healthy with Diabetes\nUniversity of Florida IFAS Extension"},
{"slug":"chocolate-squash-cake","source_url":"https://www.myplate.gov/recipes/chocolate-squash-cake","name":"Chocolate Squash Cake","description":"Incorporating squash into a chocolate cake adds flavor plus fiber, vitamin K, phosphorus, and folate.","ingredients":[{"name":null,"items":["1/2 cup vegetable oil (or cooking oil of choice)","1 package cake mix, dark chocolate","1 teaspoon ground cinnamon","3 eggs","1 1/4 cups water","1 cup squash, shredded or finely chopped","chopped walnuts (1/4 cup, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F. Grease and flour a 10-inch tube or bundt pan.","In a large bowl, combine cake mix and cinnamon.","Add eggs, water, and oil. Blend until combined, then beat with an electric mixer for 2 minutes on medium speed.","Fold in squash. Add nuts if you like.","Pour into prepared pan. Bake for 50 minutes to 1 hour, until cake springs back when lightly touched."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/12 of recipe"],"calories":"226.43 kcal","carbohydrateContent":"25.70 g","cholesterolContent":"51.38 mg","fiberContent":"0.93 g","proteinContent":"3.10 g","sodiumContent":"288.66 mg","sugarContent":"12.65 g","fatContent":"13.16 g","saturatedFatContent":"2.78 g"},"notes":"Other Ideas:\nUse a greased 9x13 inch pan. Bake for 45 minutes.\nTo lighten cake, try 6 egg whites in place of whole egg.\nReplace 1/2 cup oil with 1/2 cup applesauce.","contributor":"Adapted from: Aunt Barbara''s Chocolate Squash Cake, Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"chunky-garbanzo-bean-dip","source_url":"https://www.myplate.gov/recipes/chunky-garbanzo-bean-dip","name":"Chunky Garbanzo Bean Dip","description":"Lemon pepper and chopped onion make this a zesty dip that you can use with vegetables or other foods.","ingredients":[{"name":null,"items":["1 can (15 ounces) garbanzo beans, low-sodium","2 tablespoons vegetable oil","2 tablespoons chopped onions","lemon pepper (to taste)","salt (to taste)"]}],"directions":[{"name":null,"steps":["Drain and rinse the beans and mash in a small bowl with a fork or potato masher until most of the beans have been crushed. If you have a food processor, you can use it for this step.","Stir in oil and onion along with lemon pepper and salt to taste. The mixture will be chunky, not smooth."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"80.78 kcal","carbohydrateContent":"7.62 g","cholesterolContent":"0.00 mg","fiberContent":"2.46 g","proteinContent":"2.72 g","sodiumContent":"72.53 mg","sugarContent":"1.57 g","fatContent":"4.57 g","saturatedFatContent":"0.59 g"},"notes":"Suggest serving with vegetables like carrots, pea pods, and celery.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"cinnamon-raisin-almond-balls","source_url":"https://www.myplate.gov/recipes/cinnamon-raisin-almond-balls","name":"Cinnamon Raisin Almond Balls","description":"Throw cinnamon, raisins, and almonds together into a food processor and you have an easy and yummy breakfast on the go.","ingredients":[{"name":null,"items":["1 cup almonds","1 cup raisins","1 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Rinse the raisins and almonds with water.","Toss them in the food processor with the cinnamon. When sufficiently mixed, form into balls or bar shapes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 ball","calories":"216.87 kcal","carbohydrateContent":"26.57 g","cholesterolContent":"0.00 mg","fiberContent":"4.37 g","proteinContent":"5.88 g","sodiumContent":"7.21 mg","sugarContent":"18.42 g","fatContent":"11.80 g","saturatedFatContent":"0.92 g"},"notes":null,"contributor":"University of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"cinnamon-raisin-breakfast-mix","source_url":"https://www.myplate.gov/recipes/cinnamon-raisin-breakfast-mix","name":"Cinnamon-Raisin Breakfast Mix","description":"Try this quick and easy breakfast mix, made in the microwave. Scoop portions into small bags and serve with yogurt and a banana for a nutritious, on-the-go b...","ingredients":[{"name":null,"items":["1/4 cup sugar","1 teaspoon ground cinnamon","1/4 cup margarine, tub-style","1 1/2 cups square, whole-grain corn cereal","1 1/2 cups square, whole-grain rice cereal","1 1/2 cups square, whole-grain wheat cereal","1/2 cup raisins or dried cranberries"]}],"directions":[{"name":null,"steps":["In small bowl, mix sugar and cinnamon; set aside.","In large microwavable bowl, microwave butter uncovered on HIGH about 40 seconds, or until melted.","Stir in cereals until evenly coated. Microwave uncovered 2 minutes, stirring after 1 minute.","Sprinkle half of the sugar mixture evenly over cereals; stir. Sprinkle with remaining sugar mixture; stir.","Microwave uncovered 1 minute.","Stir in raisins or dried cranberries. Spread on paper towels to cool."]}],"yield":"10 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"one serving: 1/2 cup","calories":"139.17 kcal","carbohydrateContent":"25.28 g","cholesterolContent":"0.06 mg","fiberContent":"2.20 g","proteinContent":"1.90 g","sodiumContent":"161.31 mg","sugarContent":"11.90 g","fatContent":"3.74 g","saturatedFatContent":"0.73 g"},"notes":null,"contributor":"MyPlate National Strategic Partners\nThe Grain Chain (members include American Bakers Association, Wheat Food Council, Grains Food Foundation, National Pasta Association, USA Rice Federation, General Mills, and Kellogg''s)"},
{"slug":"cinnamon-sugared-pumpkin-pecan-muffins","source_url":"https://www.myplate.gov/recipes/cinnamon-sugared-pumpkin-pecan-muffins","name":"Cinnamon Sugared Pumpkin Pecan Muffins","description":"These muffins are made with whole grain bran cereal, pumpkin, pecans and spices. They are the perfect treat for a fall day or any time of year!","ingredients":[{"name":null,"items":["1/2 cup sugar, divided","2 teaspoons cinnamon, divided","1 cup bran flakes","1 cup skim milk","1 cup flour","1 tablespoon baking powder","1/2 teaspoon baking soda","1 cup canned pumpkin","1 egg","1 tablespoon vanilla","1/4 cup finely chopped pecans"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F. Spray 12 muffin cups with cooking spray.","Combine 2 tablespoons sugar and 1/2 teaspoon cinnamon in a small bowl; set aside.","In a large bowl, combine cereal and milk and set aside for 5 minutes.","Combine remaining sugar and cinnamon, flour, baking powder, and baking soda in a bowl. Whisk pumpkin, egg, and vanilla into cereal.","Fold in dry mixture; being careful not to over mix. Spoon into prepared pan and sprinkle with pecans and sugar-cinnamon mixture.","Bake for 20 to 25 minutes or until a toothpick comes out clean."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"137.33 kcal","carbohydrateContent":"24.58 g","cholesterolContent":"17.74 mg","fiberContent":"2.16 g","proteinContent":"3.41 g","sodiumContent":"205.17 mg","sugarContent":"11.32 g","fatContent":"2.82 g","saturatedFatContent":"0.49 g"},"notes":null,"contributor":"Ohio State University Cooperative Extension\nRoss County Extension Office"},
{"slug":"cinnamon-vanilla-granola","source_url":"https://www.myplate.gov/recipes/cinnamon-vanilla-granola","name":"Cinnamon Vanilla Granola","description":"If you''ve never made homemade granola, you might be surprised at how a few simple ingredients like oatmeal and honey turn into a tasty, satisfying, whole-gra...","ingredients":[{"name":null,"items":["2 tablespoons honey*","1/2 cup water","2 tablespoons vegetable oil (or cooking oil of choice)","1 teaspoon vanilla extract","1 teaspoon cinnamon","1/4 teaspoon salt","4 cups uncooked rolled oats (oatmeal)"]}],"directions":[{"name":null,"steps":["Preheat oven to 275 °F.","Mix honey, water, vegetable oil, vanilla extract, cinnamon, and salt in a large bowl.","Stir in oats; mix well.","Spread mixture on a cookie sheet, making a thin layer.","Bake for 20 minutes. Remove from oven, stir mixture well and return to oven.","Bake 20 minutes more and stir as before.","Bake 5 to 20 minutes more, until granola is golden brown.","Break into small pieces with spatula.","Cool and then store in a covered container."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/8 of recipe"],"calories":"200.61 kcal","carbohydrateContent":"31.53 g","cholesterolContent":"0.00 mg","fiberContent":"4.22 g","proteinContent":"5.31 g","sodiumContent":"77.05 mg","sugarContent":"4.57 g","fatContent":"6.11 g","saturatedFatContent":"0.92 g"},"notes":"* Children under the age of one should not consume honey.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"citrus-chicken","source_url":"https://www.myplate.gov/recipes/citrus-chicken","name":"Citrus Chicken","description":"Chicken thighs are coated in oregano, cumin, and lime juice and oven baked until tender and golden brown.","ingredients":[{"name":null,"items":["4 6-ounce chicken thighs (bone-in)","2 teaspoons dried oregano","1 teaspoon ground cumin","2 tablespoons fresh lime juice (about 1 lime)","1/2 teaspoon Kosher salt","1/4 teaspoon black pepper","1 orange, sliced (optional, for garnish)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 425 °F.","To trim the chicken, lay the chicken thighs on the cutting board, skin side up. Press down on the chicken to push out the excess fat. Use a sharp knife to cut excess fat.","Put the chicken, oregano, cumin, lime juice, salt, and pepper in the bowl and mix well. Proceed to the next step or cover and refrigerate up to overnight.","Put the contents of the bowl in the baking pan and transfer to the oven.","Bake about 1 hour until cooked throughout and well browned.","Serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"4 ounces","calories":"185.88 kcal","carbohydrateContent":"1.65 g","cholesterolContent":"132.57 mg","fiberContent":"0.52 g","proteinContent":"24.95 g","sodiumContent":"402.22 mg","sugarContent":"0.18 g","fatContent":"8.33 g","saturatedFatContent":"2.34 g"},"notes":"Orange or lemon juice can be used instead of lime juice.\nGarnish with orange slices or lime wedges.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"citrus-salad","source_url":"https://www.myplate.gov/recipes/citrus-salad","name":"Citrus Salad","description":"This recipe to can help make half your plate fruits and vegetables. Grapefruit sections are a great addition to fruit or green salads.","ingredients":[{"name":null,"items":["1 grapefruit, peeled","1 orange, peeled","10 cups fresh greens (lettuce)","1 small red onion, sliced thin"]},{"name":"Dressing","items":["2 tablespoons cider vinegar","1 tablespoon lime juice","1 tablespoon vegetable oil","1 tablespoon water","1/4 teaspoon black pepper","1/4 teaspoon cumin"]}],"directions":[{"name":null,"steps":["Cut fruit into bite size pieces.","Toss with lettuce and onion. Mix remaining ingredients for dressing. Drizzle over salad and toss just before serving."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"56.46 kcal","carbohydrateContent":"9.51 g","cholesterolContent":"0.00 mg","fiberContent":"1.91 g","proteinContent":"1.16 g","sodiumContent":"9.72 mg","sugarContent":"6.10 g","fatContent":"1.93 g","saturatedFatContent":"0.27 g"},"notes":null,"contributor":"Quick and Healthy, Vol.II\nScaleDown Publishing, Inc.\nBrenda Ponichtera, RD"},
{"slug":"citrus-salmon-fillets","source_url":"https://www.myplate.gov/recipes/citrus-salmon-fillets","name":"Citrus Salmon Fillets","description":"Try this sweet and savory salmon dish with nutty wild rice and a green salad!","ingredients":[{"name":null,"items":["1 pound salmon (3-4 fillets), pat dry","2 tablespoons vegetable oil","1 red onion, chopped","1 cup baby carrots (or sweet potato)","1/4 cup parsley, chopped","1 cup orange juice (divided)","1 tablespoon honey","Salt and pepper to taste","1 orange or lemon, cut into wedges (optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 degrees F.","In an oven safe skillet, heat oil on medium high heat.","Add onion, carrots (or sweet potato), parsley, and ½ cup of orange juice. Cook 5-8 minutes.","In a small bowl, mix ½ cup orange juice and honey.","In center of skillet, add salmon fillets and season with salt and pepper.","Pour orange juice and honey mixture over top.","Bake entire skillet in oven 16-18 minutes or until fish is flaky.","Garnish with orange or lemon wedges, if using"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"333.99 kcal","carbohydrateContent":"16.91 g","cholesterolContent":"60.73 mg","fiberContent":"1.75 g","proteinContent":"22.58 g","sodiumContent":"83.63 mg","sugarContent":"12.14 g","fatContent":"19.25 g","saturatedFatContent":"3.31 g"},"notes":"This recipe contains one or more ingredients considered to be traditional or indigenous to Native American communities in certain regions across North America.","contributor":"Recipe adapted from First Nations Development Institute"},
{"slug":"citrus-tuna-melt","source_url":"https://www.myplate.gov/recipes/citrus-tuna-melt","name":"Citrus Tuna Melt","description":"This warm toasted sandwich is easy to make. Our recipe uses one slice of bread per serving. An open-faced sandwich has less sodium and fewer calories.","ingredients":[{"name":null,"items":["1 can (about 12 ounces) tuna, drained","2 tablespoons lime (or lemon) juice","1/2 cup onion, diced","1/4 cup tomatoes, diced (or 2 tablespoons, about 2 ounces, low-sodium diced tomatoes, drained)","1/2 cup apple, diced","1/4 cup celery, diced","1/4 teaspoon black pepper","6 slices whole grain bread (or homemade bread)","1/4 cup fresh parsley or cilantro, chopped (optional)","1 tablespoon cayenne or jalapeño chilies, diced (optional)","3 slices pasteurized process American cheese, cut into halves","6 slices tomatoes","6 leaves lettuce"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a medium-sized bowl, combine tuna, lime juice, onion, tomatoes, apple, celery, and pepper. Mix well.","Toast the bread.","Place 6 slices of toasted bread on a cookie sheet. Put an even amount of tuna mixture on top of each slice. If using parsley and chilies, add these too.","Put 1/2 slice cheese on top of the tuna and bake for about 3 minutes.","Add an extra slice of tomato and lettuce on top if you like.","Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 open sandwich","calories":"185.42 kcal","carbohydrateContent":"21.06 g","cholesterolContent":"24.86 mg","fiberContent":"3.23 g","proteinContent":"14.91 g","sodiumContent":"422.62 mg","sugarContent":"5.04 g","fatContent":"4.78 g","saturatedFatContent":"2.08 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"citrus-vegetables","source_url":"https://www.myplate.gov/recipes/citrus-vegetables","name":"Citrus Vegetables","description":"Put a new twist on classic mixed vegetables with a splash of lime juice, some olive oil, and fresh oregano.","ingredients":[{"name":null,"items":["4 cups mixed vegetables (such as zucchini, corn, and tomatoes)","2 tablespoons fresh lime juice","1/2 tablespoon olive oil (or cooking oil of choice)","1/2 teaspoon fresh oregano, chopped"]}],"directions":[{"name":null,"steps":["Slice vegetables and steam in a small amount of water.","Drain, and place in a bowl to cool.","Mix lime juice with oil. Add oregano and combine.","Pour lime juice mixture over cool vegetables and mix well.","Serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"135.63 kcal","carbohydrateContent":"24.28 g","cholesterolContent":"0.00 mg","fiberContent":"8.07 g","proteinContent":"5.20 g","sodiumContent":"63.88 mg","sugarContent":"5.75 g","fatContent":"2.04 g","saturatedFatContent":"0.33 g"},"notes":null,"contributor":"US Department of Health and Human Services\nNational Cancer Institute"},
{"slug":"classic-honey-flan","source_url":"https://www.myplate.gov/recipes/classic-honey-flan","name":"Classic Honey Flan","description":"Flan is a delicious custard dessert enjoyed throughout the world. End a special meal with this treat.","ingredients":[{"name":null,"items":["1 large egg","1/2 cup egg substitute","2 sprays of non-stick cooking spray","1 1/2 cups fat-free milk","7 tablespoons honey*, divided","1 teaspoon vanilla","1/2 teaspoon lemon zest, grated","1/2 teaspoon ground cinnamon"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 degrees F.","Place saucepan with water on stove over medium-high heat and allow to come to a boil.","Spray four ovenproof custard cups with vegetable oil spray.","Combine the whole egg, egg substitute, milk, 5 tablespoons of honey, grated lemon zest, and vanilla. Beat until mixed but not foamy.","In a separate bowl, combine 2 tablespoons of honey and cinnamon, and mix to blend.","Place the custard cups in a baking dish large enough to accommodate them, plus the water bath. Spoon 1/2 tablespoon of honey and cinnamon into each custard cup. Divide the egg mixture equally into each custard cup.","Place the baking dish on the rack in the middle of the oven and pour the boiling water into the baking dish to a depth of 1 inch, taking care not to let the water splash the flan. Bake for 45 minutes or until the knife blade comes out clean when inserted.","Serve warm or cold. Before serving, loosen the edges with a knife or spatula and invert onto individual dessert plates."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"174.92 kcal","carbohydrateContent":"34.53 g","cholesterolContent":"54.12 mg","fiberContent":"0.27 g","proteinContent":"7.81 g","sodiumContent":"114.97 mg","sugarContent":"34.13 g","fatContent":"1.44 g","saturatedFatContent":"0.45 g"},"notes":"* Children under the age of one should not consume honey.","contributor":"Delicious Heart Healthy Latino Recipes\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"classic-macaroni-and-cheese","source_url":"https://www.myplate.gov/recipes/classic-macaroni-and-cheese","name":"Classic Macaroni and Cheese","description":"The ultimate comfort food! This healthier version of a family favorite uses non-fat evaporated milk and low-fat cheese to create its creamy sauce.","ingredients":[{"name":null,"items":["2 cups macaroni","2 sprays of cooking oil spray","1/2 cup onion, chopped","1/2 cup non-fat evaporated milk","1 large egg, beaten","1/4 teaspoon black pepper","1 1/4 cups finely shredded low-fat sharp cheddar cheese"]}],"directions":[{"name":null,"steps":["Cook macaroni according to directions. (Do not add salt to the cooking water.) Drain and set aside.","Spray a casserole dish with nonstick cooking oil spray.","Preheat oven to 350 °F.","Lightly spray saucepan with nonstick cooking oil spray.","Add onions to saucepan and sauté for about 3 minutes.","In another bowl, combine macaroni, onions, and the remaining ingredients and mix thoroughly.","Transfer mixture into casserole dish.","Bake for 25 minutes or until bubbly. Let stand for 10 minutes before serving."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/8 of recipe"],"calories":"183.45 kcal","carbohydrateContent":"23.20 g","cholesterolContent":"39.74 mg","fiberContent":"1.35 g","proteinContent":"10.65 g","sodiumContent":"138.29 mg","sugarContent":"2.64 g","fatContent":"4.92 g","saturatedFatContent":"2.57 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"cobb-salad-pears","source_url":"https://www.myplate.gov/recipes/cobb-salad-pears","name":"Cobb Salad with Pears","description":"Sweet and savory, this Cobb Salad is sure to delight with the addition of canned pears, carrots, and Parmesan cheese.","ingredients":[{"name":"For the Salad","items":["2 canned pear halves","6 cups mesclun mix baby greens","1/2 tablespoon Parmesan cheese","1 1/3 cups carrots, grated","3 tablespoons walnuts"]},{"name":"For the Dressing","items":["1/4 cup pear juice","1/4 teaspoon cider vinegar","1/4 teaspoon honey","1/4 teaspoon dijon mustard","1 dash salt and black pepper","1/4 teaspoon extra virgin olive oil"]}],"directions":[{"name":null,"steps":["For the dressing, mix pear juice, vinegar, honey, mustard, and salt and pepper and olive oil in a blender.","Put mixed greens in large mixing bowl, drizzle dressing over greens and mix together.","Add remaining chopped pear, walnuts, and grated carrots and toss lightly.","Portion out 1 cup of salad and top with 1/2 tablespoon grated Parmesan cheese."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"63.82 kcal","carbohydrateContent":"9.03 g","cholesterolContent":"0.36 mg","fiberContent":"1.89 g","proteinContent":"1.58 g","sodiumContent":"70.11 mg","sugarContent":"5.66 g","fatContent":"2.95 g","saturatedFatContent":"0.35 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"coffee-cooler","source_url":"https://www.myplate.gov/recipes/coffee-cooler","name":"Coffee Cooler","description":"This refreshing iced coffee smoothie is a delicious grown-up morning treat.","ingredients":[{"name":null,"items":["1/2 cup 1% milk","1/2 cup low-fat vanilla frozen yogurt","1/2 cup of coffee, cooled to room temperature (4 fluid ounces)","3 ice cubes","1 1/2 teaspoons sugar"]}],"directions":[{"name":null,"steps":["In a blender, combine all ingredients; purée until smooth.","Pour into a chilled glass and sprinkle with cinnamon, cocoa, or nutmeg if you like."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 drink","calories":"199.85 kcal","carbohydrateContent":"30.86 g","cholesterolContent":"45.25 mg","fiberContent":"0.00 g","proteinContent":"11.23 g","sodiumContent":"91.59 mg","sugarContent":"30.61 g","fatContent":"3.38 g","saturatedFatContent":"2.01 g"},"notes":null,"contributor":"Cooking For You or Two\nUniversity of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"collard-green-gumbo-ham-hock","source_url":"https://www.myplate.gov/recipes/collard-green-gumbo-ham-hock","name":"Collard Green Gumbo with Ham Hock","description":"Tender collard greens flavored with ham hock, onion, green pepper, celery, and red pepper make up this thick and flavorful gumbo. Serve over brown rice for a...","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil","1 large onion (peeled and diced)","3 celery stalks (chopped)","2 cloves garlic (peeled and minced)","1 teaspoon dried thyme","1/2 teaspoon chopped red pepper flakes","1/4 teaspoon salt","1/2 teaspoon dried oregano","2 tablespoons whole wheat flour","4 cups water","6 cups chopped collard greens","2 ham hocks","2 cups cooked brown rice"]}],"directions":[{"name":null,"steps":["Put a skillet on the stove and turn the heat to medium. When it is hot, add the oil. Add the onion, bell pepper, celery, garlic, thyme, red pepper flakes, salt, and oregano, and cook until golden, about 20 minutes.","Add the flour in small amounts, sprinkling a little bit at a time and stirring well, until it turns slightly brown, about 10 minutes.","Slowly add the water, stirring constantly. Add the ham hock. Raise the heat to high and when it comes to a boil reduce heat to low.","Add the collard greens and cook until tender, about 45 minutes.","Divide the brown rice between 4 shallow bowls and top each with about 1 cup of gumbo."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"354.51 kcal","carbohydrateContent":"37.00 g","cholesterolContent":"25.63 mg","fiberContent":"6.17 g","proteinContent":"12.21 g","sodiumContent":"560.94 mg","sugarContent":"3.02 g","fatContent":"18.31 g","saturatedFatContent":"4.77 g"},"notes":"One medium sized chicken sausage link can be substituted for a ham hock.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"colorful-quesadillas","source_url":"https://www.myplate.gov/recipes/colorful-quesadillas","name":"Colorful Quesadillas","description":"Use fresh or frozen spinach and red peppers, or try adding your own colorful vegetables in this dish.","ingredients":[{"name":null,"items":["8 ounces fat-free cream cheese","1/4 teaspoon garlic powder","8 flour tortillas, 6-inches across","1 cup sweet red pepper, chopped","1 cup low-fat shredded cheese","2 cups fresh spinach leaves (or 9 ounces frozen, thawed, and squeezed dry)"]}],"directions":[{"name":null,"steps":["In a small bowl, mix the cream cheese and garlic powder.","Spread about 2 tablespoons of the cheese mixture on each tortilla.","Sprinkle about 2 tablespoons bell pepper and 2 tablespoons cheese on one half of each tortilla.","Add spinach: 1/4 cup if using fresh leaves OR 2 tablespoons if using frozen. Fold tortillas in half.","Heat a large skillet over medium heat until hot. Put 2 folded tortillas in skillet and heat for 1 to 2 minutes on each side or until golden brown.","Remove quesadillas from skillet, place on platter and cover with foil to keep warm while cooking the remainder.","Cut each quesadilla into 4 wedges. Serve warm."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 quesadilla","calories":"182.27 kcal","carbohydrateContent":"20.20 g","cholesterolContent":"14.14 mg","fiberContent":"1.66 g","proteinContent":"11.41 g","sodiumContent":"538.35 mg","sugarContent":"3.63 g","fatContent":"5.90 g","saturatedFatContent":"2.94 g"},"notes":null,"contributor":"Iowa State University Extension and Outreach"},
{"slug":"confetti-bean-salsa","source_url":"https://www.myplate.gov/recipes/confetti-bean-salsa","name":"Confetti Bean Salsa","description":"This three-ingredient salsa is colorful and delicious. Serve it with whole grain chips or crackers for dipping.","ingredients":[{"name":null,"items":["1 can (15.5 ounces) black or red beans, low-sodium","1 can (15.2 ounces) corn, low-sodium","1 cup fresh tomato salsa"]}],"directions":[{"name":null,"steps":["Drain and rinse the beans. Drain the corn.","Combine beans, corn, and salsa in a medium-sized bowl. Mix."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"121.00 kcal","carbohydrateContent":"24.34 g","cholesterolContent":"0.00 mg","fiberContent":"6.79 g","proteinContent":"6.21 g","sodiumContent":"287.63 mg","sugarContent":"4.23 g","fatContent":"0.87 g","saturatedFatContent":"0.12 g"},"notes":"Like it hot? Add a few drops of hot sauce or chopped green chilis. Try chopped cilantro, parsley or green pepper, too.","contributor":"The Power of Choice\nUSDA Food and Nutrition Service and US Department of Health and Human Services Food and Drug Administration (FDA)"},
{"slug":"confetti-grain-salad","source_url":"https://www.myplate.gov/recipes/confetti-grain-salad","name":"Confetti Grain Salad","description":"Try this recipe with a variety of vegetables until you find what you and your family like best.","ingredients":[{"name":null,"items":["1 1/2 cups brown rice, uncooked","3 cups water","2 lemons, juiced","3 green onions (scallions)","1/4 cup fresh parsley, minced","1/2 teaspoon salt","1 dash black pepper","1/4 cup olive oil (or cooking oil of choice)","1 1/2 cups mixed vegetables, cut into small pieces"]}],"directions":[{"name":null,"steps":["Wash rice and put into a 2-quart pot with water. Bring to boil, then lower heat to simmer, and cook uncovered until all the water is absorbed (approximately 45 minutes)","Pour into medium sized bowl and allow to cool.","Pour lemon juice over rice and stir. When rice is cooled to lukewarm, add vegetables, salt, pepper, and oil.","Stir and chill at least 1 hour. This dish also can be served warm."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup prepared salad","1/6 of recipe"],"calories":"232.59 kcal","carbohydrateContent":"35.42 g","cholesterolContent":"0.00 mg","fiberContent":"3.60 g","proteinContent":"4.35 g","sodiumContent":"170.14 mg","sugarContent":"1.78 g","fatContent":"8.23 g","saturatedFatContent":"1.41 g"},"notes":null,"contributor":"Cent$ible Nutrition Cookbook\nUniversity of Wyoming Cooperative Extension\nCent$ible Nutrition Program"},
{"slug":"confetti-slaw","source_url":"https://www.myplate.gov/recipes/confetti-slaw","name":"Confetti Slaw","description":"Lighten up traditional cole slaw with yogurt and a splash of juice. Raisins and nuts add some sweetness and crunch.","ingredients":[{"name":null,"items":["1/4 head of green cabbage","2 carrots","1/4 cup raisins","1/4 cup peanuts","1/2 cup low-fat vanilla yogurt","1/16 cup orange juice (1 tablespoon)"]}],"directions":[{"name":null,"steps":["Slice and cut cabbage into thin strips. Place pieces in large mixing bowl.","Peel and grate carrots. Add to mixing bowl.","Add raisins and peanuts to mixing bowl.","Mix all ingredients together.","Combine yogurt and orange juice in small bowl.","Add yogurt mixture to cabbage mixture, stirring to combine ingredients thoroughly."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"67.51 kcal","carbohydrateContent":"9.42 g","cholesterolContent":"0.92 mg","fiberContent":"1.78 g","proteinContent":"2.74 g","sodiumContent":"41.76 mg","sugarContent":"6.72 g","fatContent":"2.71 g","saturatedFatContent":"0.56 g"},"notes":"Create-a-Flavor Changes\nCombine 1/8 head each red and green cabbage.\nAdd 2 tablespoons mini-marshmallows.\nTry a different flavor yogurt and juice.","contributor":"Cooking Up Fun -- A Pyramid of Snacks\nCornell Cooperative Extension\nDivision of Nutritional Sciences"},
{"slug":"cooked-beans","source_url":"https://www.myplate.gov/recipes/cooked-beans","name":"Cooked Beans","description":"A good, basic instructional recipe for cooking dry beans. Cooked beans are a great way to get more iron and fiber and can be eaten alone or added to salads a...","ingredients":[{"name":null,"items":["1 cup dried beans","10 cups water"]}],"directions":[{"name":null,"steps":["Sort: Before soaking beans, pick them over and remove any damaged beans, small stones or dirt.","Soak: Most beans will rehydrate to triple their dry size, so be sure to start with a large enough pot. Choose one of the methods to soak your beans.","Cook: Drain soaking water and rinse beans. Cover beans with fresh water. Simmer for 1 1/2 to 2 hours until tender.","Soaking Methods:","Hot Soak: Hot soaking helps reduce intestinal gas. For each pound (2 cups) of dry beans, add 10 cups hot water; heat to boiling and let boil 2 to 3 minutes. Remove from heat, cover and set aside for up to 4 hours.","Quick Soak: For each pound (2 cups) of dry beans, add 10 cups hot water; heat to boiling and let boil 2 to 3 minutes. Remove from heat, cover and set aside for at least one hour.","Overnight Soak: For each pound (2 cups) of dry beans, add 10 cups cold water and let soak overnight, or at least 8 hours."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"101.41 kcal","carbohydrateContent":"18.27 g","cholesterolContent":"0.00 mg","fiberContent":"6.66 g","proteinContent":"6.82 g","sodiumContent":"16.92 mg","sugarContent":"0.25 g","fatContent":"0.42 g","saturatedFatContent":"0.11 g"},"notes":"To avoid broken or mushy beans, boil gently and stir very little.\nTaste-test beans often for desired tenderness.\nFoods containing acid such as tomatoes, chili sauce, lemon juice, vinegar, or catsup will slow the cooking and softening of the beans. Add these items last so they will not add to the cooking time.\nAny of the following can be added during the last half hour of cooking: minced onion, garlic or green pepper, diced carrots or celery, chopped tomatoes, or cooked meat.","contributor":"Washington State WIC Program"},
{"slug":"cookie-cutter-appetizers","source_url":"https://www.myplate.gov/recipes/cookie-cutter-appetizers","name":"Cookie Cutter Appetizers","description":"Make these appetizers for your next get-together. If you don''t have a cookie cutter, just cut the tortilla into triangles. Add your favorite veggies to the f...","ingredients":[{"name":null,"items":["1 whole wheat tortilla, 10\"","2 tablespoons cream cheese, low-fat","1/2 teaspoon garlic powder","1 cup chopped vegetables (choose your favorite vegetables)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Cut out multiple shapes from 1 whole wheat tortilla using cookie cutters.","Spray a cookie sheet with non-stick cooking spray.","Place cut out tortilla shapes onto cookie sheet.","Bake in oven for 12 to 15 minutes or until golden brown.","While tortillas are baking, mix low-fat cream cheese with garlic powder. Set aside.","Wash and chop mixed vegetables.","Once tortilla cut outs are finished baking, let cool.","Spread the cream cheese mixture onto each cut out shape and decorate with mixed vegetables."]}],"yield":"2 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 tortilla with cream cheese and vegetables","calories":"201.44 kcal","carbohydrateContent":"29.81 g","cholesterolContent":"8.10 mg","fiberContent":"7.52 g","proteinContent":"7.34 g","sodiumContent":"305.17 mg","sugarContent":"4.57 g","fatContent":"5.90 g","saturatedFatContent":"3.13 g"},"notes":"You will need cookie cutters.","contributor":"Ohio State University Family Nutrition Program"},
{"slug":"corn-and-bean-medley","source_url":"https://www.myplate.gov/recipes/corn-and-bean-medley","name":"Corn and Bean Medley","description":"Chili powder and pepper flakes give a spicy twist to this classic bean and corn side dish.","ingredients":[{"name":null,"items":["1/4 cup onion, chopped","1 cup low-sodium whole-kernel canned corn","3/4 cup cooked kidney beans","3/4 teaspoon chili powder","hot pepper flakes (1/4 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Drain the canned corn, but reserve the liquid from the can.","Heat 3 tablespoons of liquid from canned corn in saucepan.","Cook onion in liquid until soft, about 2 minutes.","Add corn, kidney beans, chili powder, and hot red pepper flakes to onion mixture.","Cook over low heat for about 10 minutes."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"75.44 kcal","carbohydrateContent":"15.04 g","cholesterolContent":"0.00 mg","fiberContent":"3.60 g","proteinContent":"3.97 g","sodiumContent":"21.03 mg","sugarContent":"2.41 g","fatContent":"0.59 g","saturatedFatContent":"0.07 g"},"notes":null,"contributor":"USDA Food and Nutrition Service\nFood Distribution Program on Indian Reservations"},
{"slug":"corn-and-cucumber-salad","source_url":"https://www.myplate.gov/recipes/corn-and-cucumber-salad","name":"Corn and Cucumber Salad","description":"Spices and red wine vinegar dress up the vegetables in this recipe. Enjoy as a side dish with your favorite entree.","ingredients":[{"name":null,"items":["1 cup cucumber with peel, chopped","1 cup low-sodium canned corn","1 cup cherry tomatoes, chopped","1/8 cup red pepper, chopped (2 Tablespoons)","1/8 cup green pepper, chopped (2 Tablespoons)","2 tablespoons red wine vinegar","1/2 teaspoon garlic powder","1/2 teaspoon ground cumin","1/4 teaspoon dried cilantro or coriander","1/8 teaspoon ground black pepper"]}],"directions":[{"name":null,"steps":["Combine ingredients and mix well.","Serve cold."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared vegetables","1/7 of recipe"],"calories":"27.05 kcal","carbohydrateContent":"5.79 g","cholesterolContent":"0.00 mg","fiberContent":"0.98 g","proteinContent":"0.95 g","sodiumContent":"5.34 mg","sugarContent":"2.23 g","fatContent":"0.35 g","saturatedFatContent":"0.04 g"},"notes":null,"contributor":"ScaleDown Publishing, Inc."},
{"slug":"corn-and-green-chili-salad","source_url":"https://www.myplate.gov/recipes/corn-and-green-chili-salad","name":"Corn and Green Chili Salad","description":"Cilantro, lime juice, and green onions add a delightful taste to this corn side dish. Try using fresh corn when it is in season.","ingredients":[{"name":null,"items":["2 cups frozen corn, thawed","1 cup canned diced tomatoes, low-sodium","1/2 can (4 ounces) green chiles","1/2 tablespoon vegetable oil (or cooking oil of choice)","1 tablespoon lime juice","1/3 cup green onion, sliced","2 tablespoons fresh cilantro, chopped"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a medium bowl.","Mix well."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"99.08 kcal","carbohydrateContent":"19.57 g","cholesterolContent":"0.00 mg","fiberContent":"3.61 g","proteinContent":"2.86 g","sodiumContent":"64.93 mg","sugarContent":"4.32 g","fatContent":"2.51 g","saturatedFatContent":"0.35 g"},"notes":null,"contributor":"Healthy Latino Recipes Made with Love\nCalifornia Department of Health Services\nCalifornia Latino 5-A-Day Campaign"},
{"slug":"corn-and-pepper-cups","source_url":"https://www.myplate.gov/recipes/corn-and-pepper-cups","name":"Corn and Pepper Cups","description":"Use brown rice in this classic stuffed pepper dish to add more whole grains to your meal.","ingredients":[{"name":null,"items":["5 medium green peppers (cut in half, lengthwise)","1/2 small onion, chopped","1 1/2 cloves garlic, chopped","3 cups cooked brown rice","1 can (10 ounces) diced tomatoes with chiles, undrained","1 can (15.2 ounces) low-sodium canned corn, drained","1/2 cup cheddar cheese, shredded"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Remove seeds from peppers. Cook in boiling water 2 to 3 minutes. Drain. Set aside.","Cook onion and garlic in oil in medium skillet over medium-high heat for 3 minutes.","Combine rice, tomatoes, corn, and onion mixture. Mix well.","Spoon rice mixture into pepper halves. Places on baking sheets coated with cooking spray.","Bake at 350 °F for 10 minutes or until hot. Sprinkle with cheese.","Bake for 5 more minutes until cheese melts."]}],"yield":"10 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 pepper with filling","calories":"147.37 kcal","carbohydrateContent":"27.22 g","cholesterolContent":"5.65 mg","fiberContent":"2.55 g","proteinContent":"4.67 g","sodiumContent":"160.23 mg","sugarContent":"4.24 g","fatContent":"2.99 g","saturatedFatContent":"1.30 g"},"notes":null,"contributor":"University of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"corn-blueberry-and-wild-rice-salad","source_url":"https://www.myplate.gov/recipes/corn-blueberry-and-wild-rice-salad","name":"Corn, Blueberry, and Wild Rice Salad","description":"This savory dish features wild rice and blueberries, a fun way to add flavor and color to any salad!","ingredients":[{"name":null,"items":["6 ears sweet corn, husked (or 1 1/2 cups frozen corn or canned corn, drained)","1 cup frozen blueberries","1 small cucumber, finely chopped","1/4 cup finely chopped red onion","1/4 cup chopped fresh cilantro","1 cup wild rice, cooked","1 jalapeno pepper","4 tablespoons lime juice","4 tablespoons olive oil","2 tablespoons honey or maple syrup","1/2 teaspoon ground cumin","1/2 teaspoon salt"]}],"directions":[{"name":null,"steps":["In a large pot, bring salted water to a boil. Add corn. Cook covered for 5 minutes, or until tender. If using corn on the cob, remove corn from the cob after cooking.","In a serving bowl, combine corn, blueberries, cucumber, red onion, cilantro, wild rice, and jalapeno.","For dressing: In a screw-top jar, combine lime juice, oil, honey, cumin, and salt. Cover and shake well to combine. If you do not have a screw-top jar you can whisk ingredients in a small bowl.","Add dressing to salad and toss.","Salad is best enjoyed if covered and refrigerated overnight or up to 24 hours."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"185.94 kcal","carbohydrateContent":"27.84 g","cholesterolContent":"0.00 mg","fiberContent":"2.80 g","proteinContent":"3.82 g","sodiumContent":"162.17 mg","sugarContent":"11.75 g","fatContent":"8.35 g","saturatedFatContent":"1.38 g"},"notes":"This recipe contains one or more ingredients considered to be traditional or indigenous to Native American communities in certain regions across North America.","contributor":"Recipe adapted from First Nations Development Institute"},
{"slug":"corn-bread","source_url":"https://www.myplate.gov/recipes/corn-bread","name":"Corn Bread","description":"Make this corn bread recipe the classic way or jazz it up by adding chili powder, whole corn, or even blueberries to give a yummy twist to a basic recipe.","ingredients":[{"name":null,"items":["1 cup cornmeal","1 cup all-purpose flour","2 tablespoons sugar","1 tablespoon baking powder","1 egg","1/4 cup vegetable oil","1 cup non-fat (skim) milk"]}],"directions":[{"name":null,"steps":["Heat oven to 425 °F. Grease 8x9 inch pan.","Measure cornmeal, flour, sugar, and baking powder into a large mixing bowl. Stir to combine ingredients.","Crack egg into a small bowl and beat with a fork to combine white and yolk.","Add egg, oil, and milk to flour mixture. Mix until ingredients are well blended.","Pour batter into prepared pan.","Bake 20 to 25 minutes, until firm to touch or wooden pick inserted in the center comes out clean.","Create-a-Flavor Changes:","Buttermilk Corn Bread: Use only 2 teaspoons baking powder and add 1/4 teaspoon baking soda. Substitute 1 cup buttermilk for skim milk.","Whole Wheat Corn Bread: Use 1/2 cup all purpose flour and 1/2 cup whole wheat flour.","Corny Corn Bread: Add 1 cup kernels (fresh, frozen, or canned, well drained) with the milk.","Cheesy Corn Bread: Add 1/2 cup shredded cheddar cheese with the milk.","Chili Cheese Corn Bread: Add 1/2 teaspoon chili powder to the flour mixture. Drain one 4-ounce can chopped green chilies. Add chilies and 1/4 cup shredded Monterey jack cheese with the milk.","Blueberry Corn Bread: Fold 1 cup blueberries (fresh, frozen, or canned, well drained) into the batter.","Corn Bread Muffins: Pour batter into prepared muffin cups. Bake 20 minutes at 400 °F."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2\" square of cornbread","1/12 of recipe"],"calories":"138.56 kcal","carbohydrateContent":"19.20 g","cholesterolContent":"17.74 mg","fiberContent":"1.03 g","proteinContent":"3.12 g","sodiumContent":"139.40 mg","sugarContent":"3.21 g","fatContent":"5.57 g","saturatedFatContent":"0.85 g"},"notes":null,"contributor":"Cooking Up Fun - Muffins & More\nCornell University Cooperative Extension\nDivision of Nutritional Sciences"},
{"slug":"corn-casserole-0","source_url":"https://www.myplate.gov/recipes/corn-casserole-0","name":"Corn Casserole","description":"This family favorite casserole is good for breakfast or lunch. Add flavor by topping it with Fresh Tomato Salsa.","ingredients":[{"name":null,"items":["1/2 cup onion, chopped","1 1/2 teaspoons vegetable oil","1 can low-sodium cream style corn (about 15 ounces)","3/4 cup yellow cornmeal","1/2 cup 1% low-fat milk","4 tablespoons dried egg mix (or 2 eggs)","1/4 cup all-purpose flour","1/2 teaspoon baking powder","Nonstick cooking spray"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a saucepan, cook onions over medium heat in vegetable oil until tender (about 4 to 5 minutes).","Open canned corn and drain liquid into a measuring cup. If needed, add water to make 1 cup of liquid.","Add liquid and cornmeal to the cooked onions in the saucepan. Stir until the mixture boils.","Remove saucepan from heat. Mix in milk, corn, and dried egg mix.","In a mixing bowl, mix flour and baking powder. Add cornmeal mixture. Mix well.","Spray a 9-inch baking pan with nonstick cooking spray. Pour mixture into baking pan. Bake for 25 to 30 minutes. Cut into 6 servings."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 piece","calories":"168.87 kcal","carbohydrateContent":"30.78 g","cholesterolContent":"55.35 mg","fiberContent":"2.32 g","proteinContent":"5.42 g","sodiumContent":"72.51 mg","sugarContent":"3.96 g","fatContent":"3.73 g","saturatedFatContent":"0.92 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"corn-casserole","source_url":"https://www.myplate.gov/recipes/corn-casserole","name":"Corn Casserole","description":"This simple casserole can be served for breakfast, lunch, or a side dish. For a main dish, add 1 cup of cooked chicken or ground beef.","ingredients":[{"name":null,"items":["2 eggs","2 cans (15 ounces each) cream-style corn","1/2 cup minced onion","2 teaspoons sugar","1 cup bread crumbs"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Beat eggs in a bowl.","Add corn, minced onion, sugar, black pepper, and half the bread crumbs.","Stir and put into a greased 8x8 inch baking dish.","Sprinkle remaining bread crumbs on top of the casserole.","Baked at 350 °F for 30 minutes."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"154.70 kcal","carbohydrateContent":"30.74 g","cholesterolContent":"51.38 mg","fiberContent":"2.03 g","proteinContent":"5.28 g","sodiumContent":"388.24 mg","sugarContent":"5.71 g","fatContent":"2.41 g","saturatedFatContent":"0.64 g"},"notes":"For a main dish, add 1 cup cooked chicken or ground beef.\nFor variation, add a can of green chile peppers.\nCan use leftover cornbread or croutons for crumbs.\nTop with cheese if desired.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"corn-salad-fat-free-ranch-dressing","source_url":"https://www.myplate.gov/recipes/corn-salad-fat-free-ranch-dressing","name":"Corn Salad with Fat-free Ranch Dressing","description":"This corn salad is a great side dish that''s easy to make in advance and serve when needed.","ingredients":[{"name":null,"items":["2 cups whole kernel corn, fresh or frozen (cooked and drained)","3/4 cup tomato, chopped","1/2 cup green pepper, chopped","1/2 cup celery, chopped","1/4 cup onion, chopped","1/4 cup fat-free Ranch dressing"]}],"directions":[{"name":null,"steps":["In bowl, combine vegetables.","Stir in dressing.","Cover and refrigerate until ready to serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"69.08 kcal","carbohydrateContent":"14.61 g","cholesterolContent":"0.00 mg","fiberContent":"1.86 g","proteinContent":"2.36 g","sodiumContent":"107.45 mg","sugarContent":"5.39 g","fatContent":"1.13 g","saturatedFatContent":"0.25 g"},"notes":null,"contributor":"Kentucky Families on the Move: Food and Nutrition Calendar, 2005\nUniversity of Kentucky Cooperative Extension Service"},
{"slug":"corn-salad-fresh-basil-and-lemon","source_url":"https://www.myplate.gov/recipes/corn-salad-fresh-basil-and-lemon","name":"Corn Salad with Fresh Basil and Lemon","description":"This is a great way to use fresh corn when it''s in season. Make it the night before your next BBQ or family gathering.","ingredients":[{"name":null,"items":["6 ears of corn (about 3 cups)","2 tablespoons chopped red onion","2 tablespoons lemon juice","1/8 teaspoon sugar","2 tablespoons olive oil (or cooking oil of choice)","1 tablespoon chopped fresh basil (or 1 tsp dried basil)"]}],"directions":[{"name":null,"steps":["Cook corn in boiling water or in the microwave.","Cut corn from the cob. Add onion.","In a small bowl, whisk together lemon juice and sugar. Add oil and combine.","Stir the oil/lemon mixture and basil. And salt and pepper to taste (optional).","Refrigerate at least 30 minutes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"136.10 kcal","carbohydrateContent":"20.46 g","cholesterolContent":"0.00 mg","fiberContent":"2.23 g","proteinContent":"3.54 g","sodiumContent":"17.61 mg","sugarContent":"7.00 g","fatContent":"6.11 g","saturatedFatContent":"1.07 g"},"notes":"3 cups frozen corn can be substituted for fresh.","contributor":"University of Maryland Cooperative Extension\nFood Supplement Nutrition Education Program"},
{"slug":"corn-soup","source_url":"https://www.myplate.gov/recipes/corn-soup","name":"Corn Soup","description":"This popular soup is sure to please any hungry stomach.","ingredients":[{"name":null,"items":["1/2 pound ground beef","2 cups water","1 can reduced-sodium whole kernel corn (about 15 ounces)","2 cans no salt added cream style corn (about 30 ounces)","1 cup onions, diced","1 tablespoon garlic, finely chopped","1 tablespoon chili powder","1/2 teaspoon salt","1/2 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["In a large pot, brown ground beef over medium to high heat for 8 to 10 minutes. Drain off fat.","Add water, corn kernels, cream style corn, onion, garlic, chili powder, salt, and pepper to pot. Mix well.","Cook over low heat for about 15 minutes. Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cup of Corn Soup","calories":"223.62 kcal","carbohydrateContent":"39.69 g","cholesterolContent":"21.27 mg","fiberContent":"3.98 g","proteinContent":"10.76 g","sodiumContent":"273.08 mg","sugarContent":"8.96 g","fatContent":"4.96 g","saturatedFatContent":"1.55 g"},"notes":"Tip for cooking ground beef: The recommended safe minimum internal temperature for ground beef is 160 °F as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"corn-toasties","source_url":"https://www.myplate.gov/recipes/corn-toasties","name":"Corn Toasties","description":"Using corn meal that states \"whole corn\" or \"whole grain corn\" on the ingredient list means that you''ll get the goodness of whole grains when enjoying this r...","ingredients":[{"name":null,"items":["2 cups cornmeal","1 cup all-purpose flour, sifted","2 tablespoons sugar","1 1/2 tablespoons baking powder","1/4 teaspoon salt","1/2 teaspoon baking soda","3/4 cup buttermilk","1/4 cup dry egg mix, mixed with 1/4 cup water (or 1 egg)","2 tablespoons vegetable oil (or cooking oil of choice)"]}],"directions":[{"name":null,"steps":["In a large bowl, combine cornmeal, flour, sugar, baking powder, salt, and baking soda.","In another bowl, combine buttermilk, egg mix, and vegetable oil. Beat until well blended.","Add buttermilk mixture all at once to dry ingredients. Stir until well mixed.","Turn mixture onto a lightly floured board and knead only 10 times.","Roll out to a thickness of 1/4 inch and cut with a 3/4-inch-round cutter.","Cook on a warm ungreased griddle or frying pan for about 10 minutes on each side."]}],"yield":"18 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 toastie","calories":"107.82 kcal","carbohydrateContent":"17.93 g","cholesterolContent":"20.36 mg","fiberContent":"1.18 g","proteinContent":"2.71 g","sodiumContent":"210.84 mg","sugarContent":"1.99 g","fatContent":"2.97 g","saturatedFatContent":"0.66 g"},"notes":"Don''t have buttermilk on hand? Try using 2 teaspoons vinegar + 3/4 cup milk (made from non-fat dry milk powder).","contributor":"Healthy Eating In Indian Country: Diabetes\nUSDA Food and Nutrition Service\nFood Distribution Program on Indian Reservations"},
{"slug":"corn-tortillas","source_url":"https://www.myplate.gov/recipes/corn-tortillas","name":"Corn Tortillas","description":"Once you''ve enjoyed a warm, homemade corn tortilla, you might never go back to buying them in a bag! Look for masa harina in the baking aisle of your grocery...","ingredients":[{"name":null,"items":["2 cups cornmeal (masa harina, instant)","1/4 teaspoon salt","2 tablespoons unsalted butter, room temperature","1 1/2 cups warm water"]}],"directions":[{"name":null,"steps":["Measure the masa harina and salt into a large bowl. Cut the butter into tablespoon-sized pieces and work it into the dry ingredients using the back of a wooden spoon. Add the water and mix with a wooden spoon or with your hands until a soft dough forms. Cover the dough with a clean cloth and let rest for 5 minutes.","Divide the dough into 12 pieces and roll each piece into a ball.","To keep the dough from sticking to the tortilla press, put a piece of plastic wrap (or a plastic bag) on the bottom surface of the press. Put a ball of dough in the center of the plastic. Then place another piece of plastic wrap on the top of the dough. Press the dough flat in the press.","Pick up the tortilla with the plastic on both sides. Peel off one piece of plastic (which can be reused). Flip the tortilla off of the plastic onto a hot griddle. Cook for 1 to 2 minutes, until the bottom of the tortilla becomes golden. Flip the tortilla and press lightly with a spatula, which will make the tortilla puff slightly. Cook for one to two minutes more, until the tortilla appears to be done."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 tortilla","1/12 of recipe"],"calories":"56.04 kcal","carbohydrateContent":"8.26 g","cholesterolContent":"5.09 mg","fiberContent":"0.68 g","proteinContent":"0.93 g","sodiumContent":"54.86 mg","sugarContent":"0.17 g","fatContent":"2.32 g","saturatedFatContent":"1.25 g"},"notes":null,"contributor":"Cooking with Kids\nNew Mexico State University Cooperative Extension Service\nLynn Walters and Jane Stacey\nand USDA Food and Nutrition Service Food Stamp Nutrition Education Program"},
{"slug":"cornbread-dressing","source_url":"https://www.myplate.gov/recipes/cornbread-dressing","name":"Cornbread Dressing","description":"Some families call this \"dressing\" while others call it \"stuffing.\" Whatever your family prefers, there''s no denying that cornbread, broth, and savory herbs ...","ingredients":[{"name":null,"items":["1 teaspoon olive oil (or cooking oil of choice)","4 green onions, thinly sliced","1 celery stalk","1 1/2 cups chicken broth, low-sodium","1 teaspoon dried sage","1/4 teaspoon black pepper","4 cups crumbled cornbread","1/2 cup egg substitute","1/4 cup chopped pecans"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F. Lightly spray an 8-inch square baking pan with vegetable oil spray.","In a large skillet, heat the oil over medium heat, swirling to coat the bottom. Cook the green onions and celery for 4 to 5 minutes, or until tender, stirring occasionally. Stir in the broth, sage, and pepper.","Put the cornbread in a large bowl. Stir in the vegetable mixture, egg substitute, and pecans (the mixture will be moist). Transfer to the baking pan.","Bake for 30 minutes, or until cooked through and golden brown on top. Transfer to a serving bowl."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 serving","1/8 of recipe"],"calories":"172.70 kcal","carbohydrateContent":"21.15 g","cholesterolContent":"17.36 mg","fiberContent":"1.29 g","proteinContent":"5.78 g","sodiumContent":"264.41 mg","sugarContent":"3.77 g","fatContent":"7.53 g","saturatedFatContent":"1.22 g"},"notes":"For quick and easy cornbread for this recipe, select a cornbread mix with the lowest amounts of saturated fat, trans fat, and sodium available. Prepare using the package directions, substituting fat-free milk for whole milk and egg substitute for the egg. Omit any butter, margarine, oil, sugar, or salt called for. Bake according to the package directions. Let cool. Crumble 4 cups for the cornbread with your fingers and use as directed in the recipe.","contributor":"Power to End Stroke: 46 Healthy Soul Food Recipes Cookbook\nAmerican Heart Association"},
{"slug":"cornmeal-pancakes","source_url":"https://www.myplate.gov/recipes/cornmeal-pancakes","name":"Cornmeal Pancakes","description":"Mix up your breakfast routine with this recipe that uses cornmeal for a hearty and satisfying way to make pancakes.","ingredients":[{"name":null,"items":["2 cups cornmeal","1 teaspoon baking powder","1/2 teaspoon baking soda","1 teaspoon salt","1 teaspoon sugar","2 tablespoons butter (or margarine)","1 3/4 cups water","1 cup evaporated milk","1 tablespoon vinegar","1 egg"]}],"directions":[{"name":null,"steps":["Mix cornmeal, baking powder, baking soda, salt, and sugar in a bowl.","Add butter (or margarine) to cornmeal mixture.","Bring water to a boil and add to cornmeal mixture. Beat until well mixed.","Mix evaporated milk and vinegar in a small bowl.","Stir milk and vinegar mixture into cornmeal mixture. Beat to mix well. Beat in egg.","Heat griddle or frying pan over medium heat. (If electric frying pan is used, preheat it to 380 °F.) Pan is \"hot\" when a drop of water \"dances.\" Grease pan lightly.","Pour batter onto griddle or fry pan. Use about 3 tablespoons batter for each pancake. A 1/4 cup measure is handy to use for pouring. Stir the batter up from the bottom now and then to keep it well mixed. Cook until top is covered with bubbles and the bottom is brown. Loosen edges of each pancake all around. Turn pancakes over and brown other side."]}],"yield":"20 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 medium-sized pancake","1/20 of recipe"],"calories":"75.93 kcal","carbohydrateContent":"10.95 g","cholesterolContent":"16.98 mg","fiberContent":"0.89 g","proteinContent":"2.17 g","sodiumContent":"195.77 mg","sugarContent":"1.56 g","fatContent":"2.79 g","saturatedFatContent":"1.44 g"},"notes":null,"contributor":"Smart Shopper Recipes\nUSDA Consumer and Marketing Service\nFood Trades Staff"},
{"slug":"country-style-potato-salad","source_url":"https://www.myplate.gov/recipes/country-style-potato-salad","name":"Country Style Potato Salad","description":"This potato salad uses peas, onions, and celery for a bright crunch and a base that includes plain yogurt for a light, zesty flavor.","ingredients":[{"name":null,"items":["3 medium potatoes","1 cup celery, chopped","1/2 cup onion, minced","1 cup frozen peas, thawed","1 teaspoon mustard","1/2 cup low-fat mayonnaise","1/2 cup non-fat plain yogurt","black pepper (to taste)","lettuce and tomato (optional)"]}],"directions":[{"name":null,"steps":["Wash potatoes, leave skin on and cut in bite-sized chunks.","Place in pan and cover with water. Bring to a boil, lower to simmer and cook uncovered until potatoes are tender, about 20 minutes.","Drain in colander and sprinkle lightly with cold water.","In the mean time, put the rest of the ingredients in a large mixing bowl. Drain potatoes well and add to the bowl.","Mix well and refrigerate until ready to use.","Garnish with fresh lettuce and sliced tomatoes."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"128.18 kcal","carbohydrateContent":"20.44 g","cholesterolContent":"2.81 mg","fiberContent":"2.77 g","proteinContent":"3.80 g","sodiumContent":"181.16 mg","sugarContent":"4.17 g","fatContent":"3.69 g","saturatedFatContent":"0.60 g"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"couscous-peas-and-onions","source_url":"https://www.myplate.gov/recipes/couscous-peas-and-onions","name":"Couscous with Peas and Onions","description":"Couscous is cooked with sage, peas, and onions for a savory side dish. Look for couscous or whole grain couscous in the aisle near the rice.","ingredients":[{"name":null,"items":["1 teaspoon olive oil","1 cup onion, finely chopped","1 cup frozen green peas","1/2 teaspoon ground sage","1 1/3 cups water","1 cup couscous","salt (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Combine oil and onions in heavy skillet.","Sauté for 5 to 10 minutes until lightly browned.","Add the peas, sage, water, couscous, and salt if desired.","Cover and cook on medium heat for about 5 minutes or until peas are tender but still bright green and all of the water is absorbed.","Fluff with fork."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"181.11 kcal","carbohydrateContent":"35.10 g","cholesterolContent":"0.00 mg","fiberContent":"4.07 g","proteinContent":"6.69 g","sodiumContent":"39.40 mg","sugarContent":"3.57 g","fatContent":"1.50 g","saturatedFatContent":"0.26 g"},"notes":"Serve with lemon wedges or balsamic vinegar.","contributor":"CHOICES: Steps Toward Health\nUMass Extension Nutrition Education Program"},
{"slug":"cowboy-caviar-bean-salsa","source_url":"https://www.myplate.gov/recipes/cowboy-caviar-bean-salsa","name":"Cowboy Caviar (Bean Salsa)","description":"This salsa is a party favorite. Using pantry items liked canned beans, corn, and tomatoes, this recipe comes together quickly and can serve a crowd.","ingredients":[{"name":null,"items":["1 can (15.5 ounces) low-sodium kidney beans","1 can (15 ounces) low-sodium black beans, drained","1 can (15 ounces) low-sodium corn, drained","1 can (14.5 ounces) low-sodium crushed tomatoes","1 can (4 ounces) chopped green chilies","1/4 cup finely chopped onion","1 tablespoon oil","limes, juiced (3 limes, optional)","salt (to taste, optional)","black pepper (to taste, optional)","hot sauce (to taste, optional)"]}],"directions":[{"name":null,"steps":["Mix kidney beans, black beans, corn, tomatoes, chilies, and onion in a large bowl.","Add oil and lime juice (if using), toss gently to combine. Taste. Add small amount of salt and pepper if desired.","Serve by itself, with raw vegetables and/or corn chips."]}],"yield":"16 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"78.69 kcal","carbohydrateContent":"13.93 g","cholesterolContent":"0.00 mg","fiberContent":"4.43 g","proteinContent":"3.88 g","sodiumContent":"103.06 mg","sugarContent":"2.57 g","fatContent":"1.36 g","saturatedFatContent":"0.21 g"},"notes":"Be creative! Add any kind of beans you have. Make it spicier by adding hot sauce.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"cran-apple-crisp","source_url":"https://www.myplate.gov/recipes/cran-apple-crisp","name":"Cran-Apple Crisp","description":"This red and golden whole grain dessert is a perfect balance of sweet apples and tart cranberries.","ingredients":[{"name":null,"items":["4 medium apples (cored and thinly sliced)","1 can whole cranberry sauce (14 ounces)","2 tablespoons margarine (melted)","1 cup uncooked oats","1/3 cup brown sugar","1 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Wash apples, remove cores and slice thinly, keeping peel on.","In a bowl, combine the cranberries and apples. Pour into an 8x8 inch pan.","Combine melted margarine with oatmeal, brown sugar, and cinnamon until well blended. Sprinkle over apple/cranberry mixture.","Cover and bake for 15 minutes.","Uncover and bake 10 more minutes until the topping is crisp and brown.","Serve warm or cold."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup","calories":"219.97 kcal","carbohydrateContent":"47.77 g","cholesterolContent":"0.04 mg","fiberContent":"3.83 g","proteinContent":"1.96 g","sodiumContent":"28.38 mg","sugarContent":"33.78 g","fatContent":"2.97 g","saturatedFatContent":"0.57 g"},"notes":null,"contributor":"Pumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"cranberry-ham-slice","source_url":"https://www.myplate.gov/recipes/cranberry-ham-slice","name":"Cranberry Ham Slice","description":"Cranberry juice, raisins, allspice, and brown sugar give this dish a sweet and tangy sauce. Serve with your favorite veggies for an easy dinner.","ingredients":[{"name":null,"items":["1 cup brown sugar, firmly packed","1/2 tablespoon cornstarch","1/2 teaspoon allspice","2 cups cranberry juice","2 tablespoons lemon juice","1/4 cup seedless raisins","2 ham slices"]}],"directions":[{"name":null,"steps":["Combine brown sugar, cornstarch, and allspice in a saucepan.","Gradually add the next three ingredients and stir. Cook over medium heat until sauce thickens and boils.","Place one slice of ham in greased baking dish. Pour one half of the sauce over the ham slice. Top with second slice. Add remaining sauce.","Bake, covered in 350 °F oven for 45 minutes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"213.21 kcal","carbohydrateContent":"48.65 g","cholesterolContent":"10.80 mg","fiberContent":"0.44 g","proteinContent":"4.09 g","sodiumContent":"247.19 mg","sugarContent":"43.17 g","fatContent":"1.10 g","saturatedFatContent":"0.28 g"},"notes":null,"contributor":"University of the Virgin Islands Cooperative Extension Service\n4-H/Family & Consumer Sciences Program"},
{"slug":"cranberry-nut-bread","source_url":"https://www.myplate.gov/recipes/cranberry-nut-bread","name":"Cranberry Nut Bread","description":"Enjoy this bread for breakfast, lunch, or dinner. Use fresh cranberries when in season for a burst of flavor.","ingredients":[{"name":null,"items":["2 cups flour*","2/3 cup sugar","1 1/2 teaspoons baking powder","1 1/2 teaspoons baking soda","2 teaspoons grated orange peel","3/4 cup orange juice","4 tablespoons butter (1/4 cup), melted (or margarine)","1 egg (or 2 egg whites)","1 cup chopped cranberries","1/3 cup chopped walnuts","powdered sugar, optional (1/3 cup, for glaze)","water, optional (1 teaspoon, for glaze)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Mix flour, sugar, baking powder and baking soda in a large bowl.","Grate orange peeling, then squeeze juice from orange. Add additional orange juice to make 3/4 cup.","In a separate bowl, blend orange juice, butter, egg, and grated orange peel; add to flour mixture, stirring until just blended. Mix in cranberries and walnuts.","Pour batter into a 9x5 inch loaf pan, greased on bottom only.","Bake for 50 to 60 minutes or until a toothpick inserted in the center comes out clean. Cool in pan for 10 minutes; remove and cool completely on wire rack.","Optional: to make glaze, mix powdered sugar and water; add water as needed to make thin glaze. Drizzle over cooled loaf."]}],"yield":"15 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/15 of recipe"],"calories":"155.07 kcal","carbohydrateContent":"24.25 g","cholesterolContent":"21.84 mg","fiberContent":"0.93 g","proteinContent":"2.70 g","sodiumContent":"179.95 mg","sugarContent":"10.32 g","fatContent":"5.37 g","saturatedFatContent":"2.21 g"},"notes":"*You can substitute 1/2 to 1 cup of the flour with whole wheat flour.\nAll-purpose flour used for nutrition analysis and costing purposes.","contributor":"North Dakota State University Extension Service"},
{"slug":"cranberry-pumpkin-muffins","source_url":"https://www.myplate.gov/recipes/cranberry-pumpkin-muffins","name":"Cranberry Pumpkin Muffins","description":"Enjoy these delicious muffins for breakfast anytime of the year using canned pumpkin and frozen cranberries.","ingredients":[{"name":null,"items":["2 cups flour","3/4 cup sugar","3 teaspoons baking powder","1/2 teaspoon salt","1/2 teaspoon cinnamon","3/4 teaspoon allspice","1/3 cup vegetable oil (or cooking oil of choice)","2 eggs","3/4 cup pumpkin (canned)","2 cups fresh or frozen cranberries ( chopped)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Sift together dry ingredients (flour through allspice) and set aside.","Beat oil, eggs, and pumpkin together until well blended.","Add the wet ingredients (pumpkin mixture) to the dry ingredients all at once. Stir until moistened.","Fold in chopped cranberries.","Spoon into paper lined muffin cups.","Bake at 400 °F for 15 to 30 minutes."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"207.38 kcal","carbohydrateContent":"32.16 g","cholesterolContent":"34.25 mg","fiberContent":"1.69 g","proteinContent":"3.44 g","sodiumContent":"232.76 mg","sugarContent":"13.77 g","fatContent":"7.31 g","saturatedFatContent":"1.17 g"},"notes":"Serve with a glass of low-fat milk for a healthy snack.","contributor":"Pumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"cranberry-salad","source_url":"https://www.myplate.gov/recipes/cranberry-salad","name":"Cranberry Salad","description":"Sweet strawberry gelatin and tart cranberry sauce make a yummy dish. Make ahead and keep in the refrigerator until ready to eat.","ingredients":[{"name":null,"items":["3 packages strawberry gelatin (3 oz. packages, can also use raspberry)","4 cups water","1 can cranberry sauce","1/4 cup sugar","2 tablespoons orange peel rind (grated)","2 tablespoons lemon juice","1 cup crushed pineapple (drained)","2 cups diced celery","3/4 cup walnuts"]}],"directions":[{"name":null,"steps":["Make gelatin and refrigerate until partially set.","Beat cranberry sauce.","Grate orange peel into sugar and add to cranberry sauce with rest of ingredients.","Fold mixture into partially set gelatin. Refrigerate until set. Serve."]}],"yield":"10 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe","calories":"244.46 kcal","carbohydrateContent":"26.46 g","cholesterolContent":"0.00 mg","fiberContent":"1.76 g","proteinContent":"23.87 g","sodiumContent":"76.31 mg","sugarContent":"21.01 g","fatContent":"6.05 g","saturatedFatContent":"0.59 g"},"notes":"Suggested to serve with a mixture of instant lemon pudding mix and low-fat whipped topping.","contributor":"Utah State University Cooperative Extension"},
{"slug":"cranberry-wojapi","source_url":"https://www.myplate.gov/recipes/cranberry-wojapi","name":"Cranberry Wojapi","description":"Try this traditional Native American cranberry sauce which uses dried cranberries making it the perfect side dish to serve anytime of the year.","ingredients":[{"name":null,"items":["1 cup dried cranberries","2 cups water","4 tablespoons sugar","2 tablespoons cornstarch (mixed with 3/4 cup water)"]}],"directions":[{"name":null,"steps":["In a large saucepan, combine ingredients and bring to a boil. Reduce heat and simmer until mixture is thickened and cranberries are plumped."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"150.85 kcal","carbohydrateContent":"39.38 g","cholesterolContent":"0.00 mg","fiberContent":"1.72 g","proteinContent":"0.06 g","sodiumContent":"5.83 mg","sugarContent":"33.21 g","fatContent":"0.38 g","saturatedFatContent":"0.03 g"},"notes":"Cranberry Wojapi is a Native American dish.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"cream-broccoli-soup-ii","source_url":"https://www.myplate.gov/recipes/cream-broccoli-soup-ii","name":"Cream of Broccoli Soup II","description":"Using pantry staples and frozen broccoli, this hearty soup can be made in 10 minutes. Use 1% or fat-free milk to keep it even healthier.","ingredients":[{"name":null,"items":["1 package (10 oz) frozen, chopped broccoli (or fresh)","1 package (10 oz) frozen mixed vegetables, thawed","1 can (10.75 oz) cream of mushroom soup, low sodium","10 3/4 us fluid ounces 1% low fat milk","1/3 cup grated cheddar cheese, low fat (can use 1/4 to 1/2 cup)"]}],"directions":[{"name":null,"steps":["In saucepan, prepare broccoli according to directions. Drain off water.","Add mixed vegetables, cream of mushroom soup, and one soup can full of milk to the broccoli. Stir over low heat until steaming hot and vegetables are cooked. Add cheese, stirring until melted.","Serve hot.","Refrigerate leftovers."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"162.55"},"notes":null,"contributor":null},
{"slug":"cream-broccoli-soup","source_url":"https://www.myplate.gov/recipes/cream-broccoli-soup","name":"Cream of Broccoli Soup","description":"This creamy soup makes a perfect lunch or dinner. Keep it healthy using fat-free milk and fresh or frozen broccoli.","ingredients":[{"name":null,"items":["1 1/2 cups chicken broth, low-sodium","1/2 cup onion, chopped","2 cups broccoli, chopped","1/2 teaspoon dried thyme, crushed","2 bay leaves","garlic powder (dash, optional)","2 tablespoons vegetable oil (or cooking oil of choice)","2 tablespoons flour","1/4 teaspoon salt","pepper (dash, optional)","1 cup non-fat milk"]}],"directions":[{"name":null,"steps":["In a saucepan combine chicken broth, chopped onion, broccoli, thyme, bay leaf and garlic powder. Bring mixture to boiling. Reduce heat; cover and simmer for 10 minutes or until vegetables are tender. Remove bay leaf.","Place half of the mixture in a blender or food processor, cover and blend 30 to 60 seconds or until smooth. Pour into a bowl; repeat with remaining vegetable mixture, set all aside.","In the same saucepan warm the oil. Stir in flour, salt, and pepper. Add the milk all at once, stirring rapidly with a wire whisk. Cook and stir until mixture is thickened and bubbly. Stir in the blended broccoli mixture. Cook and stir until soup is heated through. Season to taste with additional salt and pepper."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/4 of recipe"],"calories":"139.68 kcal","carbohydrateContent":"12.06 g","cholesterolContent":"1.83 mg","fiberContent":"1.67 g","proteinContent":"5.74 g","sodiumContent":"217.47 mg","sugarContent":"4.71 g","fatContent":"7.83 g","saturatedFatContent":"1.19 g"},"notes":"Fresh or frozen broccoli can be used.","contributor":"Calcium -- It’s Not Just Milk\nUniversity of Nevada Cooperative Extension\nNevada Nutrition Network"},
{"slug":"creamy-chicken-hash","source_url":"https://www.myplate.gov/recipes/creamy-chicken-hash","name":"Creamy Chicken Hash","description":"This dish combines flavorful vegetables with chicken and seasonings to make a tasty lunch or dinner main dish.","ingredients":[{"name":null,"items":["1 medium (6 ounces) russet potato, scrubbed","2 tablespoons butter, divided (or canola oil)","1/2 small onion, finely chopped","1/4 cup green bell pepper, finely chopped","1/4 cup red bell pepper, finely chopped","1/4 cup celery, finely chopped","1 small garlic clove, finely chopped","2 sprays of canola cooking spray","2 cups skinless cooked chicken breast, diced","2 tablespoons 2% milk","1/8 teaspoon cayenne pepper (a pinch or to taste)","salt and freshly ground black pepper, to taste (optional)","4 tablespoons prepared barbecue sauce"]}],"directions":[{"name":null,"steps":["Shred the potato and set aside. (It will darken in color, but this will not affect hash.)","Heat 1 tablespoons butter or oil in a medium/large non-stick skillet. Add onion, bell peppers, celery and garlic. Sauté until lightly browned, 5 minutes. Push vegetables to one side of pan. Add remaining butter or oil. Add potatoes and mix with oil to coat them. Mix and combine well with the vegetables. Cook 3 minutes. If potatoes stick, scrape pan vigorously and move contents around pan to spray the bottom with cooking spray.","Mix in chicken, milk, cayenne, salt and pepper. Spread and flatten out the mixture into a thick cake. Use the edge of a pancake turner to cut it into 4 sections. (Or, hash can be broken into rough pieces while cooking.) Cover the pan. Cook until potatoes are tender and hash is lightly browned, 3 to 5 minutes, turning so bottom sides can also brown. (Spray pan with oil spray if necessary while turning hash.)","When hash is done, divide equally among four plates. Serve with barbecue sauce drizzled on top or around each portion. (If desired, sauce can first be thinned, by mixing 4 tablespoons sauce with 4 tablespoons milk.)"]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"249.74 kcal","carbohydrateContent":"19.85 g","cholesterolContent":"82.56 mg","fiberContent":"1.81 g","proteinContent":"22.56 g","sodiumContent":"223.37 mg","sugarContent":"8.11 g","fatContent":"8.65 g","saturatedFatContent":"4.23 g"},"notes":null,"contributor":"Recipe Corner\nAmerican Institute for Cancer Research"},
{"slug":"creamy-dill-dip","source_url":"https://www.myplate.gov/recipes/creamy-dill-dip","name":"Creamy Dill Dip","description":"There is no cooking required for this dish, and kids can pick their favorite veggies to go along with the creamy dip.","ingredients":[{"name":null,"items":["1 cup non-fat sour cream","1 cup non-fat plain yogurt","2 tablespoons dried dill"]}],"directions":[{"name":null,"steps":["Put the sour cream, yogurt, and dill in a medium bowl. Stir together.","Store the dip in a covered container if you don’t plan to eat it right away.","Keep the dip in the fridge until you serve it."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 Tablespoons prepared dip","1/16 of recipe"],"calories":"20.66 kcal","carbohydrateContent":"3.73 g","cholesterolContent":"1.66 mg","fiberContent":"0.05 g","proteinContent":"1.42 g","sodiumContent":"33.75 mg","sugarContent":"1.23 g","fatContent":"0.04 g","saturatedFatContent":"0.02 g"},"notes":"Serve with cucumber slices. If you want a creamy salad dressing, add a few tablespoons of water to the dip.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"creamy-italian-herb-dressing","source_url":"https://www.myplate.gov/recipes/creamy-italian-herb-dressing","name":"Creamy Italian Herb Dressing","description":"Serve this creamy dressing over salads or use as a dip for your favorite veggies.","ingredients":[{"name":null,"items":["1/4 cup low-fat plain yogurt","1/4 cup fat-free mayonnaise","1/4 cup fat-free (skim) milk","1/2 teaspoon dried Italian seasoning","1/2 clove garlic, minced"]}],"directions":[{"name":null,"steps":["In a small bowl, combine all the above ingredients.","Refrigerate in a covered container for at least an hour. Serve chilled."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 ounces","calories":"34.14 kcal","carbohydrateContent":"5.95 g","cholesterolContent":"1.84 mg","fiberContent":"0.44 g","proteinContent":"1.85 g","sodiumContent":"182.71 mg","sugarContent":"3.92 g","fatContent":"0.33 g","saturatedFatContent":"0.21 g"},"notes":null,"contributor":"Eat Smart New York!\nCornell University Cooperative Extension"},
{"slug":"creamy-peanut-dip","source_url":"https://www.myplate.gov/recipes/creamy-peanut-dip","name":"Creamy Peanut Dip","description":"With just three simple ingredients, this peanut dip is an easy way to make ordinary fruit or veggie sticks extraordinary!","ingredients":[{"name":null,"items":["1/4 cup creamy peanut butter","1/8 cup orange juice (2 tablespoons)","1/2 cup low-fat vanilla yogurt"]}],"directions":[{"name":null,"steps":["In a small bowl, mix the peanut butter and orange juice until smooth.","Stir in the vanilla yogurt.","Cover and put in the fridge until chilled."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons prepared dip","1/6 of recipe"],"calories":"85.59 kcal","carbohydrateContent":"4.93 g","cholesterolContent":"1.23 mg","fiberContent":"0.53 g","proteinContent":"3.48 g","sodiumContent":"59.75 mg","sugarContent":"3.56 g","fatContent":"5.78 g","saturatedFatContent":"1.28 g"},"notes":"Serve with fresh apples, pears, carrot sticks or celery sticks.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"creamy-vegetable-dip","source_url":"https://www.myplate.gov/recipes/creamy-vegetable-dip","name":"Creamy Vegetable Dip","description":"Combining yogurt or cottage cheese with savory herbs and spices makes this veggie dip cool and delicious.","ingredients":[{"name":null,"items":["2 cups low-fat plain yogurt (or small curd cottage cheese)","1/4 teaspoon black pepper","1/2 teaspoon garlic powder","2 tablespoons dried minced onion","1 tablespoon dried parsley flakes","salt (1/2 teaspoon, optional)","dill weed (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["In a medium-sized bowl, combine yogurt (or cottage cheese), pepper, garlic powder, dried onion, dried parsley, salt, and dill (if used). Beat until smooth.","Chill dip in refrigerator until ready to serve. Serve with raw vegetables."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 Tablespoons","1/12 of recipe"],"calories":"28.70 kcal","carbohydrateContent":"3.55 g","cholesterolContent":"2.45 mg","fiberContent":"0.11 g","proteinContent":"2.26 g","sodiumContent":"29.40 mg","sugarContent":"3.11 g","fatContent":"0.65 g","saturatedFatContent":"0.41 g"},"notes":"Serve with approximately 6 cups of vegetables, such as cauliflower florets, carrot sticks, celery sticks, jicama, sliced bell pepper, or sliced cucumber.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"creole-beans","source_url":"https://www.myplate.gov/recipes/creole-beans","name":"Creole Beans","description":"Try this recipe with red beans or other varieties and serve this main dish with cooked brown rice and a green salad for a complete meal. To learn how to cook...","ingredients":[{"name":null,"items":["1/2 cup celery, sliced","1/2 cup green pepper, chopped","1/2 cup onion, chopped","2 teaspoons vegetable oil (or cooking oil of choice)","1 can (14.5 ounces) low-sodium tomatoes","1/4 teaspoon garlic powder","1/8 teaspoon black pepper","2 1/2 cups cooked beans"]}],"directions":[{"name":null,"steps":["Cook celery, green pepper, and onion in vegetable oil in a large saucepan until soft, about 5 minutes.","Break up large pieces of tomatoes. Add tomatoes and seasonings to vegetable mixture.","Bring to a boil. Add beans and return to a boil.","Cover and cook over low heat until flavors are blended and liquid is cooked away, about 30 minutes. Stir once and a while to prevent sticking."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"196.03 kcal","carbohydrateContent":"32.97 g","cholesterolContent":"0.00 mg","fiberContent":"11.16 g","proteinContent":"11.10 g","sodiumContent":"26.06 mg","sugarContent":"4.61 g","fatContent":"3.24 g","saturatedFatContent":"0.45 g"},"notes":null,"contributor":"Healthy Eating In Indian Country: Do You Weigh Too Much?\nUSDA Food and Nutrition Service\nFood Distribution Program on Indian Reservations"},
{"slug":"crispy-oven-baked-fries","source_url":"https://www.myplate.gov/recipes/crispy-oven-baked-fries","name":"Crispy Oven Baked Fries","description":"Use your favorite spices to season these oven baked French fries. Endless possibilities with your favorite seasoning blends.","ingredients":[{"name":null,"items":["4 medium potatoes, cut into strips (great with sweet potatoes!)","2 tablespoons vegetable oil (or cooking oil of choice)"]}],"directions":[{"name":null,"steps":["Preheat oven to 450 °F. Lightly oil a 9x13 inch pan.","Wash and cut potatoes. Pat dry on towels.","Spread strips of potatoes in one layer in pan.","Distribute remaining oil evenly over potatoes.","Bake for 30 to 40 minutes until potatoes are golden brown and tender. Turn frequently.","Season to taste."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"112.09 kcal","carbohydrateContent":"18.20 g","cholesterolContent":"0.00 mg","fiberContent":"1.91 g","proteinContent":"2.16 g","sodiumContent":"8.90 mg","sugarContent":"1.02 g","fatContent":"3.61 g","saturatedFatContent":"0.51 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"crispy-oven-fried-chicken","source_url":"https://www.myplate.gov/recipes/crispy-oven-fried-chicken","name":"Crispy Oven-Fried Chicken","description":"Keep the flavor but cut down on the fat and sodium with this oven-fried chicken recipe. A welcome addition to your next family meal or potluck.","ingredients":[{"name":null,"items":["1/2 cup non-fat (skim) (or buttermilk)","1 teaspoon poultry seasoning","1 cup cornflakes, crumbled","1 1/2 tablespoons onion powder","1 1/2 tablespoons garlic powder","2 teaspoons black pepper","2 teaspoons crushed pepper flakes","1 teaspoon ground ginger","4 chicken breasts, skinless","4 chicken drumsticks, skinless","1/4 teaspoon paprika","1 teaspoon vegetable oil (to grease baking pan)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Add 1/2 teaspoon of poultry seasoning to milk.","Combine remaining 1/2 teaspoon of poultry seasoning and all other spices (except paprika) with cornflake crumbs and place in a plastic bag.","Dip chicken into milk, shake to remove excess, then quickly shake in bag with seasoning and crumbs.","Refrigerate for 1 hour.","Remove from refrigerator and sprinkle lightly with paprika for color.","Evenly space chicken on greased baking pan. Cover with aluminum foil and bake for 40 minutes.","Remove foil and continue baking for an additional 30 to 40 minutes or until the meat can be easily pulled away form the bone with a fork. The drumsticks may require less baking time than the breasts. Crumbs will form a crispy \"skin.\" (Do not turn chicken during baking.)"]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 breast or 2 small drumsticks","1/6 of recipe"],"calories":"201.95 kcal","carbohydrateContent":"9.36 g","cholesterolContent":"103.88 mg","fiberContent":"1.29 g","proteinContent":"28.32 g","sodiumContent":"118.67 mg","sugarContent":"1.70 g","fatContent":"5.04 g","saturatedFatContent":"1.13 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"crispy-taquitos","source_url":"https://www.myplate.gov/recipes/crispy-taquitos","name":"Crispy Taquitos","description":"Fresh pico de gallo, cooked chicken, veggies, and cheese combine to make these tasty taquitos that are baked, not fried, for a healthy meal or snack.","ingredients":[{"name":null,"items":["1 1/2 Pico de Gallo, divided","1/2 cup cooked chicken, finely chopped","1/2 cup canned corn, no salt added (or frozen, thawed)","1/4 cup green onion, chopped","1/4 cup green bell pepper, chopped","1/2 cup cheddar cheese, low-fat, shredded (or Monterey jack or queso fresco)","12 corn tortillas","2 teaspoons vegetable oil (or cooking oil of choice)"]}],"directions":[{"name":null,"steps":["Heat oven to 425 °F. In a medium bowl, combine 1 cup Pico de Gallo, chicken, corn, green onion, bell pepper, and cheese.","Soften tortillas on the stovetop or in the microwave oven, and spoon a heaping tablespoon of filling onto the center of each tortilla. Roll up tightly and secure each with a toothpick.","Place rolled tortillas seam side down on a baking sheet and brush each lightly with oil. Bake for 10 to 15 minutes or until crisp and lightly browned.","Place 3 taquitos on each plate and serve with remaining Pico de Gallo."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3 taquitos","calories":"321.92 kcal","carbohydrateContent":"48.22 g","cholesterolContent":"27.41 mg","fiberContent":"7.29 g","proteinContent":"15.31 g","sodiumContent":"212.84 mg","sugarContent":"5.11 g","fatContent":"8.57 g","saturatedFatContent":"2.66 g"},"notes":null,"contributor":"California Champions for Change Lunch Recipes\nCalifornia Department of Public Health\nNetwork for a Healthy California"},
{"slug":"crispy-walleye-patties","source_url":"https://www.myplate.gov/recipes/crispy-walleye-patties","name":"Crispy Walleye Patties","description":"Baked instead of fried, these walleye patties are full of flavor with less fat!","ingredients":[{"name":null,"items":["1 pound walleye fillets, minced (fresh or frozen) (2 8-ounce fillets)","1/2 cup onion, minced","1/2 cup celery, minced","2 tablespoons low-fat mayonnaise","1 cup crushed crackers, reduced sodium","1 egg (or 2 tablespoons dried egg mix + 1/4 cup water)","1/2 teaspoon garlic powder","1/2 teaspoon dill","1/2 teaspoon paprika","1/2 teaspoon salt","cooking spray","Note: \"Minced\" means cut up into tiny pieces."]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F. Place minced fish in a colander and press firmly to remove as much moisture as possible.","In a medium bowl, mix fish, onion, celery, mayonnaise, crackers, egg, garlic powder, dill, paprika, and salt. Let rest for 10 minutes.","Shape mixture into 8 patties. Spray baking sheet with cooking spray and place patties at least 1 inch apart on the pan.","Bake for 10 to 15 minutes, flip, and bake for another 10 minutes. Serve warm."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"93.48 kcal","carbohydrateContent":"6.43 g","cholesterolContent":"54.53 mg","fiberContent":"0.55 g","proteinContent":"9.89 g","sodiumContent":"390.42 mg","sugarContent":"0.83 g","fatContent":"2.92 g","saturatedFatContent":"0.62 g"},"notes":"Optional: Serve with a lemon wedge or tartar sauce.","contributor":"Recipe adapted from Marti Hunt, Lac du Flambeau Band of Lake Superior Chippewa Indians"},
{"slug":"crock-pot-vegetable-lentil-stew","source_url":"https://www.myplate.gov/recipes/crock-pot-vegetable-lentil-stew","name":"Crock Pot Vegetable Lentil Stew","description":"This lentil stew is full of wholesome vegetables, protein, and fiber. Although it can cook for several hours in the crockpot, the \"hands on\" preparation time...","ingredients":[{"name":null,"items":["2 tablespoons olive oil (or cooking oil of choice)","1 large onion, sliced","3 cloves garlic, minced","2 bay leaves","salt (optional, 2 teaspoons)","1 cup carrot, chopped","2 cups kale, chopped","2 cups chard, chopped","2 cups dried lentils","8 cups low-sodium vegetable broth (or stock)","1 can (14.5 ounces) low-sodium chopped tomatoes","low-fat plain yogurt (optional, 1 teaspoon per serving)"]}],"directions":[{"name":null,"steps":["Sauté onion and garlic with olive oil.","Combine sauté mix with the rest of the ingredients in a crock pot.","Cook on low for 8 hours or high for 4 hours.","Spoon stew into bowls to serve and top with a dollop of fat-free or low-fat plain yogurt (optional)."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"224.57 kcal","carbohydrateContent":"35.66 g","cholesterolContent":"0.00 mg","fiberContent":"13.24 g","proteinContent":"13.71 g","sodiumContent":"152.59 mg","sugarContent":"6.36 g","fatContent":"4.34 g","saturatedFatContent":"0.66 g"},"notes":null,"contributor":"Del Norte (California) Department of Health and Human Services\nand University of Kentucky Expanded Food and Nutrition Education Program (EFNEP)"},
{"slug":"crunchy-berry-parfait","source_url":"https://www.myplate.gov/recipes/crunchy-berry-parfait","name":"Crunchy Berry Parfait","description":"So quick, so easy, and so delicious! This parfait is a favorite among kids and adults alike. Use soy yogurt instead of regular yogurt for those who can''t hav...","ingredients":[{"name":null,"items":["1/2 cup yogurt, non-fat vanilla","1 cup blueberries or strawberries (fresh or frozen thawed)","1/2 cup low-fat granola (or crunchy cereal)"]}],"directions":[{"name":null,"steps":["Spoon yogurt into glass.","Top with fruit and granola."]}],"yield":"1 Parfait","nutrition":{"@type":"NutritionInformation","servingSize":"1 parfait","calories":"397.35 kcal","carbohydrateContent":"71.56 g","cholesterolContent":"2.45 mg","fiberContent":"7.67 g","proteinContent":"13.32 g","sodiumContent":"181.93 mg","sugarContent":"39.89 g","fatContent":"7.87 g","saturatedFatContent":"0.92 g"},"notes":"Can use fortified soy yogurt\n1/4 cup blueberries and 1/4 cup strawberries used for nutrition analysis.\nFrozen berries used for costing.","contributor":"Saint Joseph College SNAP-Ed Nutrition Education Team"},
{"slug":"crunchy-chicken-salad","source_url":"https://www.myplate.gov/recipes/crunchy-chicken-salad","name":"Crunchy Chicken Salad","description":"This main dish is a combination of chicken, vegetables, and fruit. Enjoy it as a cold salad or as the filling of a hearty sandwich or wrap.","ingredients":[{"name":null,"items":["2 cups cooked chicken, chunked","1/2 cup celery","1/4 cup green pepper","1/4 onion","1/2 cucumber","1/2 cup grapes, seedless","1 small apple, diced (leave the peel on)","1/4 cup yogurt, plain, low-fat"]}],"directions":[{"name":null,"steps":["Use leftover cooked chicken, or cook enough chicken to make 2 cups of chicken pieces.","Chop the celery and green pepper into small pieces.","Peel and chop 1/4 of an onion.","Peel and chop half of a cucumber.","Chop the apple into pieces. It’s okay to leave the peel on the apple.","Cut the grapes in half.","Put all the ingredients in a large bowl. Stir together."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup prepared salad","1/5 of recipe"],"calories":"134.84 kcal","carbohydrateContent":"10.52 g","cholesterolContent":"54.08 mg","fiberContent":"1.37 g","proteinContent":"17.59 g","sodiumContent":"45.35 mg","sugarContent":"8.28 g","fatContent":"2.24 g","saturatedFatContent":"0.57 g"},"notes":"Serve on lettuce, crackers, or bread.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"crunchy-vegetable-wraps","source_url":"https://www.myplate.gov/recipes/crunchy-vegetable-wraps","name":"Crunchy Vegetable Wraps","description":"Full of fresh and colorful veggies, these wraps are a great way to help meet your MyPlate goal of making half of your plate fruits and vegetables.","ingredients":[{"name":null,"items":["4 tablespoons low-fat cream cheese","1/3 tablespoon ranch dressing (1 teaspoon)","1/4 cup broccoli, chopped","1/4 cup carrot, peeled and grated","1/4 cup zucchini, cut into small strips","1/4 cup yellow (summer) squash, cut into small strips","1/2 tomato, diced","1/8 cup green bell pepper, seeded and diced","2 tablespoons chives, chopped fine","2 flour tortillas"]}],"directions":[{"name":null,"steps":["In a small bowl, stir ranch dressing into cream cheese; chill.","Wash and chop vegetables.","Steam broccoli in microwave for 1 minute with 1 tablespoon of water.","Spread cream cheese onto flour tortilla, staying one inch from edge. Sprinkle vegetables over cream cheese. Roll tortilla tightly.","Chill for 1 to 2 hours before serving (the wrap will hold its shape better). With a sharp knife slice into circles and serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 tortilla each","calories":"116.73 kcal","carbohydrateContent":"14.90 g","cholesterolContent":"8.42 mg","fiberContent":"1.58 g","proteinContent":"3.63 g","sodiumContent":"239.33 mg","sugarContent":"3.14 g","fatContent":"4.79 g","saturatedFatContent":"2.13 g"},"notes":"Be creative. Try different vegetables, herbs, and spices. For examples, try green beans, lettuce, radishes, corn; dill, oregano, basil, mint, curry, or chili powder.\nYou can substitute pre-made flavored cream cheeses, such as chive, herb, or vegetable.\nTry a sweet cream cheese and add fruit to your wrap for a different twist.\nThis wrap is great with soup or salad or served as a cool summer appetizer!","contributor":"Connecticut Food Policy Council"},
{"slug":"crustless-pumpkin-pie","source_url":"https://www.myplate.gov/recipes/crustless-pumpkin-pie","name":"Crustless Pumpkin Pie","description":"Using Master Mix Oregon saves time and money in this pumpkin pie recipe.","ingredients":[{"name":null,"items":["3/4 cup sugar","1/2 cup all-purpose baking mix for biscuits (or use Master Mix - see notes for link to recipe)","2 tablespoons vegetable oil (or cooking oil of choice)","1 can (14 ounces) evaporated milk, non-fat","2 egg","1 can (15 ounces) pumpkin","3 1/2 teaspoons pumpkin pie spice","2 teaspoons vanilla extract"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F and lightly grease a 9 or 10 inch pie plate.","Combine all ingredients in a medium mixing bowl or a blender.","Beat 2 minutes with a mixer until smooth, or blend in the blender on high for one minute.","Pour into the pie plate.","Bake until a knife inserted in the center comes out clean, about 50 to 55 minutes.","Cool slightly and keep refrigerated.","Serve with whipped topping or ice cream."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/8 of recipe"],"calories":"219.30 kcal","carbohydrateContent":"34.20 g","cholesterolContent":"53.43 mg","fiberContent":"1.82 g","proteinContent":"6.39 g","sodiumContent":"175.87 mg","sugarContent":"27.00 g","fatContent":"6.37 g","saturatedFatContent":"1.38 g"},"notes":"*Recipe for Master Mix","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"crusty-rice-tofu-and-vegetables","source_url":"https://www.myplate.gov/recipes/crusty-rice-tofu-and-vegetables","name":"Crusty Rice with Tofu and Vegetables","description":"This blend of tofu and cooked rice combines corn, peas, carrots, and seasonings pressed into a skillet and cooked into \"crispy\" goodness.","ingredients":[{"name":"For the rice","items":["2 cups water","1 cup brown rice"]},{"name":"For the tofu and vegetables","items":["3 cups prepared rice (ingredients above, step 1 in directions)","1 pound tofu","1 cup frozen corn (unthawed)","1 cup frozen peas (unthawed)","6 scallions (sliced including white and green parts)","1 carrot (shredded)","1/4 cup fresh basil leaves","1/4 teaspoon salt","2 tablespoons vegetable oil"]}],"directions":[{"name":null,"steps":["To make the rice, cook rice according to the directions on the package. Set aside to cool and dry out.","Put the tofu, corn, scallions, carrot, basil, and salt in the bowl and mix well.","When the rice has fully cooled, add it to the bowl with the tofu and mix well.","Put the skillet over medium high heat and when it is hot, add the oil.","Add the rice and tofu mixture; reduce heat to low and press down the rice mixture with a spatula. Cover and cook 10 minutes. Press down again to help form a crust. Flip portions of the rice so that you get chunks of crispy rice. Cook until crispy, up to 20 minutes."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cup","calories":"425.42 kcal","carbohydrateContent":"57.60 g","cholesterolContent":"0.00 mg","fiberContent":"7.43 g","proteinContent":"19.28 g","sodiumContent":"201.60 mg","sugarContent":"5.42 g","fatContent":"14.93 g","saturatedFatContent":"2.48 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"cuban-beans-and-rice","source_url":"https://www.myplate.gov/recipes/cuban-beans-and-rice","name":"Cuban Beans and Rice","description":"Vinegar, oregano, garlic, and onions kick up the flavor in this classic rice and bean recipe.","ingredients":[{"name":null,"items":["1 teaspoon olive oil","1 tablespoon garlic, minced","1 cup onion, chopped","1 cup green bell pepper, diced","3 cups black beans, canned, low-sodium (or cooked from dry)","2 cups chicken broth, low-sodium","1 tablespoon vinegar","1/2 teaspoon dried oregano","black pepper (to taste)","3 cups brown rice, cooked"]}],"directions":[{"name":null,"steps":["Heat the olive oil in a large nonstick skillet. Sauté the garlic, onion, and green bell pepper until golden, about 3 minutes.","Stir in the beans, broth, vinegar, and seasoning; bring to a boil then lower to a simmer. Cook covered for 5 minutes.","Spoon over cooked rice and serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups prepared beans and rice","1/4 of recipe"],"calories":"403.36 kcal","carbohydrateContent":"75.52 g","cholesterolContent":"0.00 mg","fiberContent":"16.04 g","proteinContent":"18.20 g","sodiumContent":"293.50 mg","sugarContent":"3.81 g","fatContent":"3.95 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"cuban-salad","source_url":"https://www.myplate.gov/recipes/cuban-salad","name":"Cuban Salad","description":"This classic salad blend of lettuce, tomatoes, onion, and radishes are brought to life with the refreshing dressing made with oil, lime juice, and seasonings...","ingredients":[{"name":"For the Dressing","items":["3 tablespoons vegetable oil","1/4 cup fresh lime juice (1 large or 2 small limes)","1 teaspoon garlic (peeled and minced)","1/4 teaspoon Kosher salt","1/4 teaspoon black pepper"]},{"name":"For the Salad","items":["1 head Romaine lettuce (washed, patted dry with paper towels, and torn into bite-sized pieces)","2 large tomatoes (diced)","1 red onion (finely diced)","6 radishes (thinly, sliced )"]}],"directions":[{"name":"To make the dressing","steps":["Put the oil, lime juice, garlic, salt, and pepper in the small bowl and mix well. Lemon juice can be used instead of lime juice."]},{"name":"To make the salad","steps":["Put the lettuce, tomatoes, onion, and radishes in the mixing bowl and toss to combine. White onion can be used instead of red onion.","Pour the dressing over the lettuce mixture and toss. Serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"141.76 kcal","carbohydrateContent":"10.09 g","cholesterolContent":"0.00 mg","fiberContent":"2.85 g","proteinContent":"2.30 g","sodiumContent":"182.38 mg","sugarContent":"4.89 g","fatContent":"10.92 g","saturatedFatContent":"1.50 g"},"notes":"For protein, add low-sodium canned tuna or salmon on top of the salad.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"cucumber-blueberry-salad","source_url":"https://www.myplate.gov/recipes/cucumber-blueberry-salad","name":"Cucumber Blueberry Salad","description":"A quick, simple and refreshing salad featuring fresh blueberries and crisp cucumber chunks with feta cheese, arugula, and a lime vinaigrette.","ingredients":[{"name":"Vinaigrette","items":["1 1/2 tablespoons extra virgin olive oil","2 tablespoons white balsamic (or other) vinegar","1 tablespoon lime juice, freshly squeezed or bottled","1 teaspoon sugar","1/4 teaspoon salt","1/8 teaspoon pepper"]},{"name":"Salad","items":["1 cup fresh blueberries","1 medium greenhouse-grown cucumber, cut into small chunks","4 cups fresh arugula","1/4 medium red onion, thinly sliced","1/4 cup crumbled reduced-fat Feta cheese","2 tablespoons coarsely chopped walnuts (toasted optional)","4 slices whole grain bread"]}],"directions":[{"name":null,"steps":["In a small bowl whisk together vinaigrette ingredients.","In a large bowl mix together all salad ingredients, except bread.","When ready to serve, add vinaigrette to salad and toss.","Toast bread, then cut into four pieces."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"232.39 kcal","carbohydrateContent":"26.65 g","cholesterolContent":"8.34 mg","fiberContent":"4.07 g","proteinContent":"7.55 g","sodiumContent":"423.94 mg","sugarContent":"8.35 g","fatContent":"11.32 g","saturatedFatContent":"2.61 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"cucumber-salad-tomatoes","source_url":"https://www.myplate.gov/recipes/cucumber-salad-tomatoes","name":"Cucumber Salad with Tomatoes","description":"Fresh tomatoes and cucumbers make this couscous salad a summer time treat.","ingredients":[{"name":null,"items":["2 cups cucumber, diced","1 cup tomato, seeded and diced","1/4 cup sweet onion, chopped","2 cups couscous, cooked (or rice)","2 teaspoons dill weed, chopped","1/2 cup Italian salad dressing, low-fat"]}],"directions":[{"name":null,"steps":["Toss together the cucumbers, tomatoes, onions, couscous (or rice), dill, and salad dressing.","Chill for 1 hour.","Serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"139.83 kcal","carbohydrateContent":"26.39 g","cholesterolContent":"0.00 mg","fiberContent":"2.20 g","proteinContent":"4.08 g","sodiumContent":"248.73 mg","sugarContent":"5.32 g","fatContent":"2.17 g","saturatedFatContent":"0.29 g"},"notes":null,"contributor":"Don’t Play With Your Food: Spring and Summer Cookbook\nArizona Nutrition Network"},
{"slug":"cucumber-salad","source_url":"https://www.myplate.gov/recipes/cucumber-salad","name":"Cucumber Salad","description":"This cucumber salad has a light and creamy dressing. Make it ahead of time and chill it in the refrigerator until you are ready to serve it.","ingredients":[{"name":null,"items":["1 large cucumber","2 tablespoons low-fat yogurt","1 tablespoon vinegar","1 tablespoon vegetable oil","1 tablespoon water","1 teaspoon dill weed","1 dash black pepper"]}],"directions":[{"name":null,"steps":["Peel and thinly slice cucumber.","Mix all other ingredients in the mixing bowl.","Add cucumber slices and stir until coated.","Chill until serving."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared salad","1/2 of recipe"],"calories":"90.61 kcal","carbohydrateContent":"5.09 g","cholesterolContent":"0.92 mg","fiberContent":"0.58 g","proteinContent":"1.56 g","sodiumContent":"14.44 mg","sugarContent":"2.78 g","fatContent":"7.37 g","saturatedFatContent":"1.15 g"},"notes":null,"contributor":"Eating Right Is Basic\nMichigan State University Cooperative Extension Service\nNutrition Education Program"},
{"slug":"cucumber-yogurt-and-cream-cheese-dip","source_url":"https://www.myplate.gov/recipes/cucumber-yogurt-and-cream-cheese-dip","name":"Cucumber Yogurt and Cream Cheese Dip","description":"Try this cool and tangy low-fat yogurt dip with your favorite vegetables.","ingredients":[{"name":null,"items":["1 cup low-fat plain yogurt","4 ounces low-fat cream cheese, softened","1 cup cucumber","1 clove garlic, chopped","salt and lemon pepper, to taste (optional)"]}],"directions":[{"name":null,"steps":["Stir yogurt and cream cheese until smooth.","Rinse the cucumber under running water.","Slice the cucumber in half the long way and run a spoon down the middle to remove the seeds.","Chop the cucumber into small pieces.","Stir the cucumber, chopped garlic, and seasonings (optional) into the yogurt mixture."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"50.57 kcal","carbohydrateContent":"3.96 g","cholesterolContent":"9.49 mg","fiberContent":"0.09 g","proteinContent":"2.84 g","sodiumContent":"72.69 mg","sugarContent":"3.24 g","fatContent":"2.66 g","saturatedFatContent":"1.60 g"},"notes":"To quickly soften cream cheese, microwave for approximately 20 seconds.","contributor":"Iowa Department of Public Health\nIowa Nutrition Network"},
{"slug":"cucumber-yogurt-and-herb-dip","source_url":"https://www.myplate.gov/recipes/cucumber-yogurt-and-herb-dip","name":"Cucumber, Yogurt and Herb Dip","description":"Lemon and dill combined with low-fat yogurt make this a flavorful and healthy dip. Serve it with your favorite vegetables.","ingredients":[{"name":null,"items":["2 medium cucumbers","2 cups low-fat plain yogurt","1/2 cup fat-free sour cream","1 tablespoon lemon juice","1 tablespoon fresh dill","1 clove garlic, chopped","1 cup cherry tomatoes","1 cup broccoli florets","1 cup baby carrots"]}],"directions":[{"name":null,"steps":["Peel, seed, and grate one cucumber. Slice other cucumber and set aside.","Mix yogurt, grated cucumber, sour cream, lemon juice, dill, and garlic in a serving bowl. Chill for 1 hour.","Arrange sliced cucumbers, tomatoes, broccoli, and carrots on a colorful platter. Serve with cucumber dip."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"97.49 kcal","carbohydrateContent":"15.65 g","cholesterolContent":"6.70 mg","fiberContent":"1.65 g","proteinContent":"6.21 g","sodiumContent":"107.86 mg","sugarContent":"8.93 g","fatContent":"1.54 g","saturatedFatContent":"0.87 g"},"notes":"Watch how to make this kid-friendly recipe on YouTube.","contributor":"More Matters Recipes\nUS Department of Health and Human Services\nCenters for Disease Control and Prevention (CDC)"},
{"slug":"cumin-lime-shrimp-over-creamy-cauliflower-risotto","source_url":"https://www.myplate.gov/recipes/cumin-lime-shrimp-over-creamy-cauliflower-risotto","name":"Cumin Lime Shrimp over Creamy Cauliflower Risotto","description":"Short on time? This better-for-you creamy cauliflower risotto makes for a quick and tasty dinner. Heart healthy avocado gives the dish its smooth, indulgent ...","ingredients":[{"name":null,"items":["2 tablespoons olive oil, divided","8 medium shrimp, peeled, deveined and tails removed","1 teaspoon cumin","1 fresh lime, zested and juiced","1/4 teaspoon salt","1 package (8-10 ounces) frozen “riced” cauliflower","1/2 cup white onion, finely chopped","1 clove garlic, minced","1 ripe, fresh avocado, halved, pitted, peeled and diced"]}],"directions":[{"name":null,"steps":["Microwave frozen “riced” cauliflower according to package directions, usually about 5-6 minutes; set aside.","Heat 1 Tbsp. olive oil in a medium nonstick pan over medium heat. Add the shrimp and cook 2 to 3 minutes per side until light pink and opaque. Place shrimp in a small bowl and season with cumin, lime zest, and salt.","Add remaining oil into the pan. Add onion and cook, stirring occasionally, until onion is soft, about 2 minutes. Add garlic and avocado and cook for one minute, until heated through.","Transfer avocado onion mixture into a blender or food processor and add lime juice. Cover and blend until smooth, stirring mixture with a spatula if needed.","Transfer heated “riced” cauliflower into the pan and top with pureed avocado onion mixture. Cook over medium heat, stirring gently until cauliflower has a beautiful green color.","Divide into two bowls and top with cooked shrimp."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup cauliflower risotto and 4 shrimp","calories":"317.40 kcal","carbohydrateContent":"19.69 g","cholesterolContent":"23.72 mg","fiberContent":"10.37 g","proteinContent":"7.18 g","sodiumContent":"351.93 mg","sugarContent":"4.18 g","fatContent":"25.91 g","saturatedFatContent":"3.90 g"},"notes":"Garnish with freshly chopped cilantro and additional avocado slices.\nFor more information, visit: https://loveonetoday.com/","contributor":"Created by Fresh Avocados Love One Today, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"curried-brown-rice-pumpkin-seeds-apricots","source_url":"https://www.myplate.gov/recipes/curried-brown-rice-pumpkin-seeds-apricots","name":"Curried Brown Rice with Pumpkin Seeds, Apricots and Spinach","description":"Brown rice gets a flavor burst when curry powder, onions, and dried apricots are added. Toasted pumpkin seeds add a nice crunch.","ingredients":[{"name":null,"items":["1 cup brown rice, short grain, uncooked","1 tablespoon olive oil (or cooking oil of choice)","2 cloves garlic cloves, chopped","1 medium red onion, peeled and finely chopped","1 tablespoon curry powder","2 cups low-sodium vegetable broth (or low-sodium chicken broth)","1 cup dried apricots, chopped","2 cups fresh spinach, chopped","1/2 cup pumpkin seeds toasted (pepitas)","salt & pepper (optional, to taste)"]}],"directions":[{"name":null,"steps":["Rinse the rice well.","Heat the oil over medium heat in a large heavy saucepan.","Add the onions and garlic and cook for 3 to 4 minutes, then stir in the curry powder.","Add the rice and broth and bring to a boil over high heat.","Reduce the heat, cover and simmer for 30 to 45 minutes until the liquid is absorbed.","Remove from heat and stir in the apricots and spinach.","Replace cover and let sit for 10 minutes.","Add the pumpkin seeds, salt, pepper (and more curry if desired) and fluff with a fork.","Serve immediately."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"447.45 kcal","carbohydrateContent":"73.20 g","cholesterolContent":"0.00 mg","fiberContent":"8.26 g","proteinContent":"11.98 g","sodiumContent":"168.61 mg","sugarContent":"24.10 g","fatContent":"14.26 g","saturatedFatContent":"2.52 g"},"notes":null,"contributor":null},
{"slug":"curried-chicken-raisins-and-mushrooms","source_url":"https://www.myplate.gov/recipes/curried-chicken-raisins-and-mushrooms","name":"Curried Chicken with Raisins and Mushrooms","description":"Savory chicken and mushrooms balanced with the sweetness of raisins and red bell peppers will make this curried one-pan recipe a family favorite.","ingredients":[{"name":null,"items":["1 1/2 teaspoons olive oil (extra virgin or virgin)","2 boneless, skinless chicken breasts (about 12 oz, diced into 1 inch cubes)","2 cups sliced fresh white mushrooms","2 cups sliced cremini mushrooms","1/2 medium red bell pepper (cut into 3/4\" squares)","2 cups low sodium chicken broth","1 cup raisins","2 cups instant whole-grain rice","1 1/2 tablespoons curry powder"]}],"directions":[{"name":null,"steps":["Heat olive oil in large sauté pan.","With heat on medium-high, place chicken in pan and cover with lid.","Cook chicken about 5 minutes.","Add mushrooms and peppers to pan and sauté 3 to 4 minutes.","Add chicken broth.","Gently mix in raisins, rice, and curry powder; bring to boil, reduce heat and cover.","Simmer until rice is done; fluff with fork and let sit 3 to 5 minutes before serving."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"374.14 kcal","carbohydrateContent":"62.37 g","cholesterolContent":"45.01 mg","fiberContent":"5.16 g","proteinContent":"22.31 g","sodiumContent":"76.89 mg","sugarContent":"28.32 g","fatContent":"5.43 g","saturatedFatContent":"1.11 g"},"notes":"Serving Suggestions: Add a side salad with light dressing and an 8 oz glass of fat-free milk.\nTime Saving Ideas: Purchase sliced mushrooms, fresh or frozen bell pepper strips, and pre-cooked, diced chicken.","contributor":"Produce for Better Health Foundation"},
{"slug":"curried-chicken-salad","source_url":"https://www.myplate.gov/recipes/curried-chicken-salad","name":"Curried Chicken Salad","description":"Shredded chicken is coated with yogurt, curry powder, and cilantro and combined with crisp celery and apples give this salad delicious flavor with a refreshi...","ingredients":[{"name":null,"items":["4 cooked cooled chicken thighs (about 3 cups shredded)","2 tablespoons vegetable oil","1/8 cup low-fat yogurt","1 tablespoon curry powder (or more to taste)","2 celery stalks (diced or sliced)","1 apple (cored and diced)","1/4 cup mandarin oranges, canned, drained","1/4 cup chopped fresh cilantro (and/or basil leaves)"]}],"directions":[{"name":null,"steps":["Put chicken in a bowl and add remaining ingredients. Mix to combine.","Cover and refrigerate at least one hour and up three days."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"247.43 kcal","carbohydrateContent":"10.94 g","cholesterolContent":"90.08 mg","fiberContent":"2.34 g","proteinContent":"17.85 g","sodiumContent":"258.12 mg","sugarContent":"8.29 g","fatContent":"14.95 g","saturatedFatContent":"3.03 g"},"notes":"If you do not have leftover chicken, you can poach chicken. Put 4 boneless, skinless chicken thighs in a pan and cover with cold water (about 4 cups) and bring to a boil over high heat. Lower the heat and cook for 10 minutes. Turn the heat off, turn the chicken pieces over and set aside for 20 minutes. Remove the thighs with a slotted spoon and set aside to cool completely. Shred and prepare recipe as directed.\nYou can also substitute 2 cans of drained light tuna, instead of chicken thighs.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"curried-chickpea-salad","source_url":"https://www.myplate.gov/recipes/curried-chickpea-salad","name":"Curried Chickpea Salad","description":"This dish can be served on whole wheat bread, on a bed of lettuce, or as a dip with your favorite veggies!","ingredients":[{"name":null,"items":["2 cans (15 ounces each) chickpeas, low-sodium, rinsed and drained","1/2 cup celery, diced","1/2 cup apple, diced","1/4 cup red onion, diced","1/4 cup cranberries, dried","1/4 cup mayonnaise, low fat","1 teaspoon dijon mustard","2 teaspoons curry powder","1/4 teaspoon thyme, dried","1/8 teaspoon black pepper, ground","salt (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Add the chickpeas to a large bowl and mash with a potato masher. You can mash them to be as smooth or coarse as you desire.","Add all of the remaining ingredients to the bowl and mix until everything is combined."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"187.53 kcal","carbohydrateContent":"29.13 g","cholesterolContent":"1.67 mg","fiberContent":"7.71 g","proteinContent":"7.54 g","sodiumContent":"297.44 mg","sugarContent":"10.82 g","fatContent":"5.41 g","saturatedFatContent":"0.68 g"},"notes":"Add the Curried Chickpea Salad to a sandwich and add spinach or lettuce if desired. Also, try topping tossed salad with it instead of salad dressing.","contributor":"Penn State Extension\nNutrition Links Program"},
{"slug":"curried-potatoes","source_url":"https://www.myplate.gov/recipes/curried-potatoes","name":"Curried Potatoes","description":"Serve these flavorful potatoes with roasted chicken and a salad for a filling and tasty dinner.","ingredients":[{"name":null,"items":["1 small onion, finely chopped","3 cups potatoes, cubed","1/4 cup margarine or butter","3/4 cup low-sodium chicken broth","1/2 tablespoon curry powder","1/2 tablespoon lemon juice"]}],"directions":[{"name":null,"steps":["Peel the onion, and chop it into small pieces.","Peel the potatoes, and chop them into 1 inch cubes.","Boil the potatoes in a medium saucepan until they are soft. Drain off the hot water.","Add ice cold water to cover the potatoes.","Melt the butter on medium heat in a frying pan or skillet.","Cook the onion in the butter until it turns yellow.","Drain the water from the potatoes and add them to the frying pan. Stir and cook until they absorb the butter.","Add the broth, curry powder, and lemon juice.","Cook until the potatoes have absorbed the broth."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared potatoes","1/6 of recipe"],"calories":"124.45 kcal","carbohydrateContent":"15.94 g","cholesterolContent":"0.10 mg","fiberContent":"2.05 g","proteinContent":"2.49 g","sodiumContent":"81.46 mg","sugarContent":"1.84 g","fatContent":"6.09 g","saturatedFatContent":"1.25 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"curried-quinoa-and-cauliflower","source_url":"https://www.myplate.gov/recipes/curried-quinoa-and-cauliflower","name":"Curried Quinoa and Cauliflower","description":"This flavorful dish has protein, vegetables, dairy, and lots of herbs and spices.","ingredients":[{"name":null,"items":["1 cup quinoa, rinsed","2 tablespoons olive oil (or cooking oil of choice)","4 teaspoons curry powder","1/2 teaspoon cumin","1 cup vegetable broth, low-sodium","2 garlic cloves, chopped","1 head of cauliflower, trimmed and cut into small florets (about 1 1/2 pounds)","1 cup frozen peas","1/3 cup plain yogurt, low fat","1/2 cup cashews, roasted without salt","1/4 cup cilantro, fresh, chopped","2 tablespoons green onion (scallion), chopped","2 tablespoons lime juice","salt (pinch, optional)"]}],"directions":[{"name":null,"steps":["Cook quinoa until just tender, according to package directions.","Heat oil in saucepan over medium-high heat. Add curry powder and cumin, and cook, about 30 seconds, or until fragrant.","Stir in broth and chopped garlic. Bring to a boil.","Add cauliflower, cover, and return to a boil. Reduce heat to medium and simmer 3 minutes.","Add frozen peas and cook until cauliflower is just tender, stirring occasionally. Remove from heat.","Stir in 2 tablespoons broth from cauliflower mixture into yogurt in small bowl.","Add yogurt mixture to cauliflower. Fold in quinoa, cashews, and cilantro.","Sprinkle with green onion and top with a little fresh lime juice.","Optional: Season with a pinch of salt."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (about 1 1/2 cups)","calories":"381.78 kcal","carbohydrateContent":"45.42 g","cholesterolContent":"1.21 mg","fiberContent":"9.56 g","proteinContent":"13.62 g","sodiumContent":"129.73 mg","sugarContent":"8.26 g","fatContent":"18.06 g","saturatedFatContent":"3.30 g"},"notes":null,"contributor":"USDA Supplemental Nutrition Assistance Program (SNAP)"},
{"slug":"curried-squash-stew","source_url":"https://www.myplate.gov/recipes/curried-squash-stew","name":"Curried Squash Stew","description":"Curry powder and cinnamon give unique flavor to this zucchini, butternut squash, tomato, and bean stew. Add raisins or dried cranberries for an added \"sweet ...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1 yellow onion (peeled and chopped)","2 cloves garlic (peeled and minced)","1 celery stalk (including leaves, chopped)","1/2 teaspoon ground cinnamon","1 large zucchini (or 2 small)","2 tablespoons curry powder","3 cups butternut squash","1 can (14.5 ounce) low-sodium diced tomatoes (including liquid)","1 can (15.5 ounce) low-sodium white beans or chickpeas (drained and rinsed)"]}],"directions":[{"name":null,"steps":["Heat a large pot on the stove over medium heat and add oil. Add the onion, garlic and celery and cook about 10 minutes, until the onion is tender.","Add zucchini and curry powder and cook for 10 minutes, stirring occasionally.","Add the butternut squash, tomatoes and chickpeas and cover. Continue cooking about 10 minutes.","Serve with cooked brown rice."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cup servings","calories":"240.23 kcal","carbohydrateContent":"41.69 g","cholesterolContent":"0.00 mg","fiberContent":"12.84 g","proteinContent":"11.01 g","sodiumContent":"213.40 mg","sugarContent":"10.16 g","fatContent":"5.13 g","saturatedFatContent":"0.82 g"},"notes":"For additional flavor, add 1/2 cup raisins.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"curry-dip","source_url":"https://www.myplate.gov/recipes/curry-dip","name":"Curry Dip","description":"Curry powder adds lots of flavor to this vegetable dip. Serve it with veggies or whole wheat pita for a satisfying snack.","ingredients":[{"name":null,"items":["1 cup fat-free sour cream","1 cup fat-free plain yogurt","1 tablespoon curry powder"]}],"directions":[{"name":null,"steps":["Mix the sour cream, yogurt, and curry powder.","Store the dip in a covered container if you don’t plan to eat it right away.","Keep the dip in the refrigerator until you serve it."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons prepared dip","1/16 of recipe"],"calories":"20.95 kcal","carbohydrateContent":"3.74 g","cholesterolContent":"1.66 mg","fiberContent":"0.21 g","proteinContent":"1.40 g","sodiumContent":"33.15 mg","sugarContent":"1.25 g","fatContent":"0.08 g","saturatedFatContent":"0.02 g"},"notes":"Serve with bite-sized raw vegetables, crackers, or pita bread.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"curry-vegetable-dip","source_url":"https://www.myplate.gov/recipes/curry-vegetable-dip","name":"Curry Vegetable Dip","description":"Turn the heat up on this vegetable dip by using hot curry powder or use regular curry powder for a more mild taste.","ingredients":[{"name":null,"items":["1 cup low-fat plain yogurt","1/4 cup carrots, shredded","2 tablespoons green onions, minced","1 tablespoon salad dressing (mayonnaise-type)","1 teaspoon sugar","1/4 teaspoon curry powder","1 dash black pepper"]}],"directions":[{"name":null,"steps":["Mix ingredients in a bowl.","Chill.","Serve with crisp raw vegetables pieces, such as celery, carrot, or summer squash sticks."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 cup","calories":"15.87 kcal","carbohydrateContent":"1.65 g","cholesterolContent":"1.16 mg","fiberContent":"0.09 g","proteinContent":"0.85 g","sodiumContent":"20.60 mg","sugarContent":"1.49 g","fatContent":"0.67 g","saturatedFatContent":"0.22 g"},"notes":null,"contributor":"Pyramid Snacks\nUSDA Food and Nutrition Service\nTeam Nutrition"},
{"slug":"curtido-salvadoreno-cabbage-salad","source_url":"https://www.myplate.gov/recipes/curtido-salvadoreno-cabbage-salad","name":"Curtido Salvadoreño (Cabbage Salad)","description":"This salad will make a great side dish for your next cookout.","ingredients":[{"name":null,"items":["1 head of cabbage, chopped","2 medium carrots, grated","1 small onion, sliced","red pepper flakes (optional, 1/2 teaspoon)","1/2 teaspoon oregano","1 teaspoon olive oil","1/2 teaspoon salt","1 teaspoon brown sugar","1/4 cup vinegar","1/2 cup water"]}],"directions":[{"name":null,"steps":["Blanch the cabbage with boiling water for 1 minute. Discard the water.","Place the cabbage in a large bowl and add grated carrots, sliced onion, red pepper, oregano, olive oil, salt, brown sugar, vinegar, and water.","Place in the refrigerator for at least 2 hours before serving."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared salad","1/8 of recipe (159g)"],"calories":"50.66 kcal","carbohydrateContent":"10.24 g","cholesterolContent":"0.00 mg","fiberContent":"3.60 g","proteinContent":"1.75 g","sodiumContent":"179.21 mg","sugarContent":"5.97 g","fatContent":"0.75 g","saturatedFatContent":"0.15 g"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"daves-herb-stuffed-mushrooms","source_url":"https://www.myplate.gov/recipes/daves-herb-stuffed-mushrooms","name":"Dave’s Herb-Stuffed Mushrooms","description":"Stuffing mushrooms just makes something wonderful even better! But what you stuff in these tasty little vegetables can make or break the dish. Typically, mus...","ingredients":[{"name":null,"items":["8 large mushrooms (approx. 3\" in diameter)","4 cloves garlic","3/4 cup white onions","3 teaspoons olive oil","1/2 teaspoon dried parsley","1/2 teaspoon dried sage","1/2 teaspoon dried rosemary","1/2 teaspoon dried thyme","1/4 cup bread crumbs (whole-wheat if available)","1/4 cup sun-dried tomatoes (chopped fine)","3/4 cup canned, drained, no-salt added chickpeas (garbanzo beans)","1 teaspoon lemon juice","cooking spray"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F.","Clean mushrooms with a paper towel or vegetable brush; remove stems to use for the filling.","While oven is warming, put mushroom caps (open side down) in oven for 10 minutes. This will prepare the caps for stuffing.","Chop the garlic and onions and sauté with 1 teaspoon of olive oil. One minute before they are finished, add the four herbs. After 1 minute, remove from heat.","In a large bowl, mash mushroom stems and chickpeas.","Add all other ingredients. Mix well.","Lightly spray a baking sheet and the mushroom caps.","Stuff the mushrooms with the mixture and place on baking sheet.","Bake for 15 to 18 minutes or until the stuffing is golden brown.","Remove from oven, sprinkle with an herb of your choice, and enjoy."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 portion (2 Dave''s Herb-Stuffed Mushrooms)","calories":"134.89 kcal","carbohydrateContent":"18.23 g","cholesterolContent":"0.00 mg","fiberContent":"3.81 g","proteinContent":"5.14 g","sodiumContent":"117.00 mg","sugarContent":"4.86 g","fatContent":"5.04 g","saturatedFatContent":"0.78 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion\nRecipe submitted by Dave, MyPlate Nutritionist and Webmaster"},
{"slug":"deep-dish-apple-cranberry-pie","source_url":"https://www.myplate.gov/recipes/deep-dish-apple-cranberry-pie","name":"Deep Dish Apple Cranberry Pie","description":"Cranberries and apples are the perfect combination for this delicious homemade dessert.","ingredients":[{"name":null,"items":["4 large apples, peeled, cored, and sliced","2 1/2 cups cranberries, fresh or frozen","3/4 cup sugar","1/4 cup flour","1 teaspoon apple pie spice","1 pie crust, prepared"]}],"directions":[{"name":null,"steps":["Stir all ingredients (except for the pie crust) together in a medium sized mixing bowl and place in a 10-inch deep dish pie pan.","Place one pie crust on top of the fruits. Cut 3 or 4 slits to allow the steam to escape.","Bake at 375 °F for about an hour. Serve warm. Refrigerate any leftovers."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/10 of recipe"],"calories":"155.35 kcal","carbohydrateContent":"36.17 g","cholesterolContent":"0.00 mg","fiberContent":"3.12 g","proteinContent":"0.77 g","sodiumContent":"12.48 mg","sugarContent":"27.88 g","fatContent":"0.99 g","saturatedFatContent":"0.28 g"},"notes":null,"contributor":"Food and Health Communications, Inc."},
{"slug":"delicious-greens","source_url":"https://www.myplate.gov/recipes/delicious-greens","name":"Delicious Greens","description":"This recipe combines traditional leafy greens with cabbage, garlic, and onions for a savory side dish that''s packed with flavor and nutrition.","ingredients":[{"name":null,"items":["3 1/2 cups mustard or collard greens (about 1/2 pound)","2 cups cabbage, shredded","1 tablespoon olive oil (or cooking oil of choice)","2 tablespoons garlic, minced","1 onion, chopped","1 tablespoon vinegar"]}],"directions":[{"name":null,"steps":["Rinse greens, remove stems, and tear in small pieces.","In a large saucepan, boil 3 quarts of water.","Add mustard greens, return to a boil and cook 3 minutes. Add cabbage and cook 1 more minute. Drain in colander.","Heat a large non-stick skillet over medium high heat. Add oil and sauté garlic and onion until light brown, about 3 minutes.","Add greens and vinegar and cook briefly, about 3 minutes. Serve hot."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups prepared greens","1/4 of recipe"],"calories":"76.25 kcal","carbohydrateContent":"9.35 g","cholesterolContent":"0.00 mg","fiberContent":"3.26 g","proteinContent":"2.52 g","sodiumContent":"19.27 mg","sugarContent":"3.64 g","fatContent":"3.78 g","saturatedFatContent":"0.58 g"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"delicious-lentil-stew","source_url":"https://www.myplate.gov/recipes/delicious-lentil-stew","name":"Delicious Lentil Stew","description":"Lentils are a great variety of dried legume! They are full of protein, fiber, and nutrients like iron; have a great taste; and cook faster than dried beans b...","ingredients":[{"name":null,"items":["2 tablespoons butter (or margarine)","1 cup onion, chopped","6 cups water","2 cups dry lentils, washed (soaking not necessary)","1 teaspoon Worcestershire sauce","1/2 teaspoon oregano","1/4 teaspoon garlic powder","6 large carrots, cut into 1/2-inch pieces","8 medium celery stalks","1 teaspoon salt","1 can (14.5 ounces) whole tomatoes, low-sodium, cut into pieces (or 3-4 fresh tomatoes cut in wedges)"]}],"directions":[{"name":null,"steps":["Melt butter in a large skillet.","Sauté onion until tender.","Add water, lentils, Worcestershire sauce, oregano, and garlic powder.","Cover, bring to a boil. Reduce heat, and simmer for 45 minutes.","Add carrots, celery, and salt.","Cover and simmer 30 minutes more or until the vegetables are tender.","Add tomatoes. Heat thoroughly and serve."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (394g)","calories":"226.77 kcal","carbohydrateContent":"37.17 g","cholesterolContent":"7.63 mg","fiberContent":"14.24 g","proteinContent":"13.88 g","sodiumContent":"382.10 mg","sugarContent":"7.31 g","fatContent":"3.74 g","saturatedFatContent":"1.92 g"},"notes":null,"contributor":"Go With Beans\nUniversity of Wisconsin Cooperative Extension Service\nEau Claire County"},
{"slug":"delicious-oven-french-fries","source_url":"https://www.myplate.gov/recipes/delicious-oven-french-fries","name":"Delicious Oven French Fries","description":"These oven fries are crisp and seasoned with pepper, allspice, garlic powder, onion powder, and salt.","ingredients":[{"name":null,"items":["2 large potatoes (about 2 pounds)","8 cups ice water","1 teaspoon garlic powder","1 teaspoon onion powder","1/4 teaspoon salt","1 teaspoon ground white pepper","1/4 teaspoon allspice","1 teaspoon hot pepper flakes","1 tablespoon vegetable oil"]}],"directions":[{"name":null,"steps":["Scrub potatoes and cut into 1/2 inch strips.","Place potato strips into ice water, cover, and chill for 1 hour or longer.","Preheat oven to 475 °F.","Remove potatoes and dry strips thoroughly.","Place garlic powder, onion powder, salt, white pepper, allspice, and pepper flakes in plastic bag.","Toss potatoes in spice mixture.","Brush potatoes with oil.","Place potatoes in nonstick shallow baking pan.","Cover with aluminum foil and place in preheated oven for 15 minutes.","Remove foil and continue baking uncovered for additional 15 to 20 minutes or until golden brown. Turn fries occasionally to brown on all sides."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"143.25 kcal","carbohydrateContent":"26.65 g","cholesterolContent":"0.00 mg","fiberContent":"3.12 g","proteinContent":"3.20 g","sodiumContent":"146.56 mg","sugarContent":"1.46 g","fatContent":"2.98 g","saturatedFatContent":"0.43 g"},"notes":null,"contributor":"US Department of Health and Human Services"},
{"slug":"delicious-tacos","source_url":"https://www.myplate.gov/recipes/delicious-tacos","name":"Delicious Tacos","description":"These vegetable filled corn tortilla tacos get a kick from diced jalapeno peppers and garlic. Serve these as a side dish or enjoy as a snack.","ingredients":[{"name":null,"items":["1 cup mushrooms","1/2 red pepper, medium","1/2 onion","1 tablespoon jalapeno pepper","1 clove garlic","1/2 teaspoon black pepper","1/2 teaspoon table salt","4 corn tortilla, medium"]}],"directions":[{"name":null,"steps":["Sauté onion, garlic and jalapeno, add cumin and black pepper. When everything is soft, add red pepper and mushrooms. Sauté for 2 more minutes.","Serve over tortilla and garnish with cut tomatoes and cilantro or cilantro sauce."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"68.68"},"notes":null,"contributor":"Make Every Day A Healthy Snack Day\nAlameda County Public Health Department"},
{"slug":"deviled-eggs","source_url":"https://www.myplate.gov/recipes/deviled-eggs","name":"Deviled Eggs","description":"A favorite dish at parties and potlucks, Deviled Eggs also make a great, protein-filled anytime snack!","ingredients":[{"name":null,"items":["6 large eggs, hard-boiled and peeled","1/4 cup mayonnaise","1/8 teaspoon salt","1/8 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Hard boil eggs by placing eggs in a saucepan and covering them with water. Bring to a boil.","Reduce heat to simmer; cook for 15 minutes.","Immediately rinse under cold water to stop cooking and to make it easy to peel off shells. Refrigerate peeled eggs (without shells) until ready for use.","Slice eggs into halves lengthwise. Remove yellow yolks and save whites.","Place yolks in a one-quart zip lock style bag along with the remaining ingredients (except the egg whites). Press out air.","Close bag and knead (mush together) until ingredients are well-blended. (Note: you could also put yolks in a bowl with other ingredients [except the egg whites] and mix together well until they look like a paste).","Push contents toward one corner of the bag. Cut about 1/2 inch off the corner of the bag. Squeezing the bag gently, fill reserved egg white hollows with the yolk mixture. (Note if you used a bowl, spoon the yolk mixture into the egg whites).","Chill to blend flavors."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 prepared egg halves","1/6 of recipe"],"calories":"133.96 kcal","carbohydrateContent":"0.56 g","cholesterolContent":"209.35 mg","fiberContent":"0.01 g","proteinContent":"6.29 g","sodiumContent":"173.87 mg","sugarContent":"0.15 g","fatContent":"11.84 g","saturatedFatContent":"2.67 g"},"notes":null,"contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"dilled-fish-fillets","source_url":"https://www.myplate.gov/recipes/dilled-fish-fillets","name":"Dilled Fish Fillets","description":"Use fish fillets from the freezer in this recipe to make a quick, weeknight seafood dinner.","ingredients":[{"name":null,"items":["1 pound frozen haddock or cod fillets","1 tablespoon lemon juice","1/8 teaspoon dried dill weed","1/8 teaspoon salt","black pepper (optional)"]}],"directions":[{"name":"Microwave Method","steps":["Thaw frozen fish in refrigerator overnight or thaw in microwave oven. Then, separate into 4 fillets or pieces","Place fish in a glass-baking dish. Cover with wax paper.","Cook at \"medium\" power in the microwave for 3 minutes. Remove cover, turn fish over, and sprinkle with lemon juice and seasonings.","Cover and continue cooking at \"medium\" power for 3 minutes or until fish flakes with a fork."]},{"name":"Skillet method","steps":["Wash hands with soap and water.","Separate into four fillets or pieces.","Place fish in heated fry pan. Sprinkle with lemon juice and seasonings.","Cover and cook over moderate heat until fish flakes when tested with a fork, about 5 minutes."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 4 oz. piece of fish","1/4 of recipe"],"calories":"66.66 kcal","carbohydrateContent":"0.29 g","cholesterolContent":"47.73 mg","fiberContent":"0.02 g","proteinContent":"16.00 g","sodiumContent":"181.68 mg","sugarContent":"0.10 g","fatContent":"0.21 g","saturatedFatContent":"0.04 g"},"notes":null,"contributor":"Microwave Recipes\nUniversity of Illinois Extension Service"},
{"slug":"dirty-rice","source_url":"https://www.myplate.gov/recipes/dirty-rice","name":"Dirty Rice","description":"Dirty rice is a flavorful way to spice up your main dishes. It is also a good way to serve leftovers; cooked chicken or ham can be used in place of ground be...","ingredients":[{"name":null,"items":["2 tablespoons dried egg mix (or 1 egg)","1/4 cup water","1/4 pound ground beef","1/2 onion, finely chopped","1/2 green pepper, chopped","2 tablespoons vegetable oil","1/2 can reduced-sodium peas, drained (about 8 ounces)","1/2 can low-sodium kidney beans, drained (about 8 ounces )","4 cups cooked rice, cold","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["In a small bowl, combine dried egg mix and water. Mix well and set aside.","In a large skillet, cook ground beef, onion, and green pepper in oil over medium heat for about 10 minutes.","Add dried egg mix to skillet. Scramble eggs over medium heat for about 5 minutes.","Add peas and beans to skillet. Cook for about 5 minutes.","Add rice and pepper to skillet. Stir to break up any clumps of rice. Cook for about 5 minutes. Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"284.22 kcal","carbohydrateContent":"42.13 g","cholesterolContent":"38.12 mg","fiberContent":"4.93 g","proteinContent":"10.33 g","sodiumContent":"68.57 mg","sugarContent":"2.36 g","fatContent":"8.26 g","saturatedFatContent":"1.84 g"},"notes":"Tip for cooking ground beef: The recommended safe minimum internal temperature for ground beef is 160 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"dried-bananas","source_url":"https://www.myplate.gov/recipes/dried-bananas","name":"Dried Bananas","description":"Looking for a healthy, crunchy snack? This recipe is super simple and can be made in bulk in advance.","ingredients":[{"name":null,"items":["1 banana","acidic fruit juice (lemon, lime, orange, pineapple) to reduce browning (optional)","cinnamon or other flavorings (optional)"]}],"directions":[{"name":null,"steps":["Slice bananas into 1/8 to 1/4-inch slices.","(Optional) Dip banana slices into fruit juice to reduce browning. Sprinkle with cinnamon or other flavorings if desired.","Dry until pieces bend like thick leather and no longer feel sticky.","Oven Instructions: Set oven to lowest temperature possible (175 to 200 °F). Use convection bake if available. Arrange banana slices in a single layer on a wire rack or baking sheet. A wire rack will help the banana dry faster. A baking sheet takes longer and pieces need to be turned part way through drying. Drying takes 1 to 3 hours.","Dehydrator Instructions: Arrange banana slices in a single layer on dehydrator racks. Set dehydrator to 135 °F. Drying takes 6 to 12 hours.","5. Cool. Store in an airtight container or bag."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 banana","calories":"61.11 kcal","carbohydrateContent":"14.30 g","cholesterolContent":"0.00 mg","fiberContent":"1.07 g","proteinContent":"0.47 g","sodiumContent":"0.00 mg","sugarContent":"9.95 g","fatContent":"0.18 g","saturatedFatContent":"0.07 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"drop-biscuits-better-baking-mix","source_url":"https://www.myplate.gov/recipes/drop-biscuits-better-baking-mix","name":"Drop Biscuits (from Better Baking Mix)","description":"Using our Better Baking Mix and getting rid of the rolling and cutting steps means you can enjoy the goodness of homemade biscuits even when you''re shor...","ingredients":[{"name":null,"items":["2 Better Baking Mix","1/4 cup vegetable oil","1/4 cup water"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F. Lightly grease baking sheet.","Add oil and water to the dry mix. Stir just until all ingredients are wet.","Drop spoonsful 4 inches apart on baking sheet.","Bake 10 to 12 minutes until lightly browned."]}],"yield":"10 Biscuits","nutrition":{"@type":"NutritionInformation","servingSize":["1 biscuit","1/10 of recipe"],"calories":"125.29 kcal","carbohydrateContent":"14.45 g","cholesterolContent":"0.40 mg","fiberContent":"1.02 g","proteinContent":"2.81 g","sodiumContent":"107.44 mg","sugarContent":"1.15 g","fatContent":"6.19 g","saturatedFatContent":"0.87 g"},"notes":"Try these variations on this recipe:\nHerb Biscuits - Add to dry ingredients: 1 teaspoon Italian herb mix.\nCheese Biscuits - Add to dry ingredients: 1/3 cup grated sharp cheese.\nFruit Scones - Add to the dry ingredients: 1/4 cup sugar, 1/2 cup raisins or dried cranberries, 1 teaspoon cinnamon, or the grated rind of an orange or lemon.","contributor":"Washington State University Extension"},
{"slug":"dutch-apple-yogurt-dessert","source_url":"https://www.myplate.gov/recipes/dutch-apple-yogurt-dessert","name":"Dutch Apple Yogurt Dessert","description":"This treat blends cool, tangy yogurt with the sweetness of apple sauce and spices for a smooth and satisfying dessert or snack!","ingredients":[{"name":null,"items":["1/2 cup fat-free vanilla yogurt","1/2 cup unsweetened applesauce","1 tablespoon seedless raisins","1/8 teaspoon ground cinnamon","1 teaspoon brown sugar, packed","1 tablespoon nuts (as topping or crunchy cereal)"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a small bowl.","Cover and refrigerate until chilled.","Eat and enjoy as a snack or as a dessert."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"117.10 kcal","carbohydrateContent":"20.58 g","cholesterolContent":"1.23 mg","fiberContent":"1.33 g","proteinContent":"4.55 g","sodiumContent":"63.01 mg","sugarContent":"17.82 g","fatContent":"2.56 g","saturatedFatContent":"0.42 g"},"notes":null,"contributor":"Fun Food News\nArizona Nutrition Network"},
{"slug":"dutch-green-beans","source_url":"https://www.myplate.gov/recipes/dutch-green-beans","name":"Dutch Green Beans","description":"Using canned green beans and other pantry items, this side dish is great when you don''t have much time. Adding the onion at the end kicks up the flavor a bit...","ingredients":[{"name":null,"items":["1 can (14.5 ounces) green beans, low-sodium","1 teaspoon cornstarch","1/3 cup vinegar","1/4 cup brown sugar","1 small onion, sliced"]}],"directions":[{"name":null,"steps":["Drain the beans, and save the liquid from the can in small bowl.","Pour 1/2 cup bean liquid into the saucepan.","Add the cornstarch in the bean liquid. Stir well.","Add the vinegar and brown sugar.","Put on medium heat and bring to a boil.","Turn the heat to low.","Add the green beans and onions. Heat and serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"78.58 kcal","carbohydrateContent":"17.59 g","cholesterolContent":"0.00 mg","fiberContent":"2.59 g","proteinContent":"1.57 g","sodiumContent":"7.16 mg","sugarContent":"11.24 g","fatContent":"0.51 g","saturatedFatContent":"0.12 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"eagle-nest","source_url":"https://www.myplate.gov/recipes/eagle-nest","name":"Eagle Nest","description":"Kids can enjoy making this healthy, fun, and easy after-school snack using peaches, cottage cheese, and raisins.","ingredients":[{"name":null,"items":["2 canned peach halves, packed in juice","2 tablespoons cottage cheese, low-fat (1 ounce)","1 tablespoon raisins"]}],"directions":[{"name":null,"steps":["Place one peach half, cut side up, in center of plate for nest.","Place 1 tablespoon of cottage cheese in center of nest.","Place raisins on cottage cheese to make eggs.","Enjoy your Eagle Nest."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"2 Eagle Nests","calories":"114.57 kcal","carbohydrateContent":"24.60 g","cholesterolContent":"3.39 mg","fiberContent":"2.25 g","proteinContent":"4.11 g","sodiumContent":"102.28 mg","sugarContent":"21.01 g","fatContent":"0.82 g","saturatedFatContent":"0.38 g"},"notes":"Adults: If preparing with children, use a can opener to open peaches. Drain juice and discard sharp edged lid.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nChickasaw Nation, Get Fresh! Nutrition Education Program"},
{"slug":"easiest-banana-ice-cream","source_url":"https://www.myplate.gov/recipes/easiest-banana-ice-cream","name":"Easiest Banana Ice Cream","description":"What should you do with over-ripe bananas? Don''t toss them! Freeze them and then throw them in the blender to make this delicious and creamy frozen dessert. ...","ingredients":[{"name":null,"items":["2 1/2 bananas (2-3 bananas)","3 tablespoons 1% milk","chocolate syrup (optional)"]}],"directions":[{"name":null,"steps":["When bananas have become very ripe, peel and slice them into medium size round pieces. Place on a plastic wrap covered baking sheet and put in freezer overnight.","Place frozen bananas in a food processor or blender with a small splash of milk (not over 1/4 cup total).","Pulse food processor or blender until bananas begin to break up. They will be tiny balls of bananas at this point.","Using a spoon or rubber spatula, scrape down the banana mixture. Continue running the food processor until the mixture is smooth and creamy. This may take a few minutes. The ice cream will look and tasted like soft serve ice cream when finished.","Serve in an ice cream cone or in a small bowl with a small ribbon of chocolate syrup on top (optional)."]}],"yield":"3 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 of recipe","calories":"108.41 kcal","carbohydrateContent":"24.62 g","cholesterolContent":"0.76 mg","fiberContent":"1.79 g","proteinContent":"1.29 g","sodiumContent":"5.95 mg","sugarContent":"17.35 g","fatContent":"0.44 g","saturatedFatContent":"0.20 g"},"notes":null,"contributor":"Alabama Cooperative Extension System"},
{"slug":"easy-and-healthy-black-bean-soup","source_url":"https://www.myplate.gov/recipes/easy-and-healthy-black-bean-soup","name":"Easy and Healthy Black Bean Soup","description":"This soup is full of flavor and is so easy to prepare. Using canned beans and salsa, along with cumin and cilantro, this soup is a great way to throw dinner ...","ingredients":[{"name":null,"items":["2 cans (15.5 ounces each) black beans, low-sodium, drained and rinsed","2 cups chicken broth, low-sodium (or low-sodium vegetable broth)","1 cup fresh salsa","1 teaspoon ground cumin","4 tablespoons sour cream, low-fat (or fat-free)","2 tablespoons fresh cilantro, chopped"]}],"directions":[{"name":null,"steps":["Lightly purée one can of black beans with broth, salsa, and cumin in a blender.","In a medium saucepan, combine puréed bean mixture with remaining beans and heat through.","To serve, ladle soup into 4 bowls.","Top each bowl with one tablespoon of sour cream and garnish with the cilantro."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"243.58"},"notes":null,"contributor":"Bronson Wellness Center\nBronson Healthcare - Michigan"},
{"slug":"easy-baked-acorn-squash","source_url":"https://www.myplate.gov/recipes/easy-baked-acorn-squash","name":"Easy Baked Acorn Squash","description":"This sweet and nutty squash pairs well with meats and other main dishes.","ingredients":[{"name":null,"items":["2 acorn squashes","4 tablespoons maple syrup or honey (can replace with 1/4 teaspoon ground black pepper per squash half for a savory flavor)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Cut acorn squash in half and scoop out seeds.","Fill a baking pan with about 1/2 inch of water.","Place the squash in the pan, flesh side up. If they are lopsided, slice the underside horizontally so the bottom sits flat on the pan.","Add 1 tablespoon maple syrup or honey (or ground pepper if you prefer a savory flavor) to each half and spread evenly across the flesh.","Bake for about 1 hour, or until flesh is tender.","Serve as a side with meat or another main dish."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"128.78 kcal","carbohydrateContent":"32.68 g","cholesterolContent":"0.00 mg","fiberContent":"5.18 g","proteinContent":"1.70 g","sodiumContent":"3.09 mg","sugarContent":"22.46 g","fatContent":"0.64 g","saturatedFatContent":"0.13 g"},"notes":"This recipe contains one or more ingredients considered to be traditional or indigenous to Native American communities in certain regions across North America.","contributor":"Recipe adapted from American Indian Health and Wellness Project"},
{"slug":"easy-beef-supper","source_url":"https://www.myplate.gov/recipes/easy-beef-supper","name":"Easy Beef Supper","description":"This is a favorite southwestern dish. Serve with vegetables for lunch or dinner.","ingredients":[{"name":null,"items":["1 pound ground beef","1 small onion, chopped","1 bell pepper, chopped","2 cans (about 30 ounces) no salt added diced tomatoes, drained","1 cup macaroni, uncooked","2 1/2 cups low-sodium tomato juice","1/4 teaspoon black pepper","1/2 teaspoon chili powder","1 teaspoon oregano (optional)","1 can (about 15 ounces) low-sodium kidney beans, drained"]}],"directions":[{"name":null,"steps":["In a large pan, cook ground beef over medium heat for 8 to 10 minutes. Drain fat.","Add onion, green pepper, and tomatoes to ground beef and cook until onion turns light brown.","Turn down the heat to a simmer. Add macaroni, tomato juice, spices, and beans to the pan. Stir well.","Cover the pan and simmer for about 20 minutes.","Remove pan from heat, stir, and serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup","calories":"306.43 kcal","carbohydrateContent":"37.10 g","cholesterolContent":"42.55 mg","fiberContent":"8.43 g","proteinContent":"21.24 g","sodiumContent":"207.71 mg","sugarContent":"9.42 g","fatContent":"8.50 g","saturatedFatContent":"2.96 g"},"notes":"Tip for cooking ground beef: The recommended safe minimum internal temperature for ground beef is 160 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe by Phyllis Blackbear, Cheyenne Arapaho Tribes FDP"},
{"slug":"easy-mix-pizza-better-baking-mix","source_url":"https://www.myplate.gov/recipes/easy-mix-pizza-better-baking-mix","name":"Easy-As-A-Mix Pizza (from Better Baking Mix)","description":"Making pizza at home has never been easier! Enjoy this recipe using our Better Baking Mix with adults or kids of all ages. Add veggie sticks and fruit for de...","ingredients":[{"name":null,"items":["1 Better Baking Mix","2 tablespoons vegetable oil","1/3 cup water","1/2 cup tomato sauce, low-sodium","2 tablespoons finely chopped onion","1/2 teaspoon oregano (or Italian herb mix)","1 cup mozzarella cheese, part-skim grated"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 °F. Grease a 12x15 inch or larger baking sheet, or 12-inch pizza pan.","Measure mix into a bowl. Add oil and water. Stir to form soft dough.","Transfer dough onto baking sheet. Sprinkle with flour. Dip fingers in flour and pat dough into a circle about 11-12 inches across.","Spread pizza crust with tomato sauce. Leave about 1/2 inch around edge with no sauce.","Sprinkle with onion, seasoning and cheese","Bake 10-12 minutes until edges are brown and cheese is melted and starting to brown.","Refrigerate any leftovers within 2 hours."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/4 of recipe"],"calories":"250.18 kcal","carbohydrateContent":"21.57 g","cholesterolContent":"18.87 mg","fiberContent":"1.92 g","proteinContent":"10.66 g","sodiumContent":"335.90 mg","sugarContent":"3.26 g","fatContent":"13.60 g","saturatedFatContent":"4.41 g"},"notes":"Use leftover tomato sauce from a can within 5 days, or freeze to use later.","contributor":"Washington State University Extension"},
{"slug":"easy-oven-fish-spinach-basil-dipping-sauce-spiced-apples","source_url":"https://www.myplate.gov/recipes/easy-oven-fish-spinach-basil-dipping-sauce-spiced-apples","name":"Easy Oven Fish with Spinach Basil Dipping Sauce & Spiced Apples","description":"Classic comfort foods with a modern twist, these easy-to-prepare fish sticks and spiced apples will please any finicky youngster''s palate.","ingredients":[{"name":"For the Spinach Basil Dipping Sauce","items":["1 cup frozen chopped spinach, thawed and drained","1/2 cup chopped fresh basil","1 clove garlic","3/4 cup fat-free plain yogurt","2 tablespoons vinegar","2 teaspoons honey"]},{"name":"For the Fish Sticks","items":["cooking spray","1 pound frozen pollock, or other white fish, such as haddock or cod (partially thawed)","1/2 cup flour","2 egg whites, beaten","3/4 cup bread crumbs (whole-wheat if available)","2 tablespoons grated Parmesan cheese","1/8 teaspoon ground black pepper"]},{"name":"For the Spiced Apples","items":["3 apples","1/2 cup raisins","1/4 cup chopped pecans","1/2 teaspoon cinnamon","2 teaspoons butter, unsalted"]}],"directions":[{"name":null,"steps":["Place rack in center and heat oven to 450 °F. Spray cookie sheet with cooking spray.","To make dipping sauce, place all ingredients in a blender or food processor; blend or process until smooth.","Cut pollock into strips 1-inch wide (easiest when fish is partially, rather than full, thawed) and place on prepared baking sheet.","Mix breading ingredients (bread crumbs, Parmesan cheese, and pepper) in a shallow dish or pie pan; place flour and egg whites in separate dishes.","Dip fish sticks in flour, then in egg whites, then breading mix, coating evenly.","Return coated fish sticks to baking sheet, spacing evenly. Cook fish until it is 145 °F, confirmed with a food thermometer, about 10 to 12 minutes, golden brown, turning as needed.","While fish sticks are baking, cut apples in quarters and core them; slice into smaller wedges (about 12 per apple).","Toss with raisins, pecans, and cinnamon.","Heat butter in medium sauce pan. Add fruit mix.","Sauté lightly about 3 to 5 minutes. Apples should still be slightly crisp."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"491.80 kcal","carbohydrateContent":"75.52 g","cholesterolContent":"55.88 mg","fiberContent":"8.23 g","proteinContent":"29.26 g","sodiumContent":"409.31 mg","sugarContent":"39.45 g","fatContent":"9.47 g","saturatedFatContent":"2.52 g"},"notes":"Serving Suggestions: Serve with 100% fruit juice and green beans or asparagus.","contributor":"Produce for Better Health Foundation"},
{"slug":"easy-oven-packet-caribbean-tilapia-pears-and-carnival-roasted-potatoes","source_url":"https://www.myplate.gov/recipes/easy-oven-packet-caribbean-tilapia-pears-and-carnival-roasted-potatoes","name":"Easy Oven Packet Caribbean Tilapia with Pears and Carnival Roasted Potatoes","description":"Enjoy a taste of the Caribbean with seasoned vegetables, tilapia and pears, baked in no-fuss foil or parchment packets.","ingredients":[{"name":"For the Carnival Roasted Potatoes","items":["2 small red potatoes","2 small Yukon potatoes","1/2 yellow bell pepper, cut into 1\" chunks","1 cup green beans (fresh, frozen, or canned)","1 Roma tomato, cut into wedges","2 tablespoons chopped white onion","1 clove garlic, minced","1/2 teaspoon cumin","1/4 teaspoon salt (optional)","1 tablespoon olive oil"]},{"name":"For the Tilapia Oven Packets","items":["1 pound tilapia fillets, fresh, or frozen (4-4-oz tilapia fillets)","1 tablespoon salt-free Caribbean citrus seasoning blend","2 teaspoons olive oil","3 D''Anjou pears (medium)","aluminum foil"]}],"directions":[{"name":null,"steps":["Heat oven to 425 °F.","Scrub potatoes under running water, cut into 1-inch chunks.","In a large bowl, toss potatoes with other vegetables, seasonings, and olive oil. Spread mix in a 2-quart baking dish and place in oven.","Roast until potatoes and other vegetables are tender, about 30 to 40 minutes.","About 15 minutes after the potato dish was placed in the oven, put in a baking sheet with fish packets, prepared as follows:","Brush fish with olive oil, coat with seasoning blend.","Place each filet in the center of a square of aluminum foil (or substitute foil with parchment paper).","Cut pears into quarters and core; slice into thin wedges (about 8 to 12 per pear).Top fish with pear wedges.","Bring the foil over the fish and fruit. Fold and pinch the seams.","Place foil packets on a baking sheet. Bake about 20 minutes, until tilapia is cooked to an internal temperature of 145 °F, confirmed with a food thermometer, and fruit is tender.","To serve, carefully open the packet, slide contents onto individual serving plates, and add roasted vegetables."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"378.23 kcal","carbohydrateContent":"53.00 g","cholesterolContent":"45.25 mg","fiberContent":"8.07 g","proteinContent":"25.53 g","sodiumContent":"217.05 mg","sugarContent":"17.21 g","fatContent":"8.52 g","saturatedFatContent":"1.75 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of non-fat milk.","contributor":"Produce for Better Health Foundation"},
{"slug":"eating-smart-seasoning-mix","source_url":"https://www.myplate.gov/recipes/eating-smart-seasoning-mix","name":"Eating Smart Seasoning Mix","description":"Keep this seasoning mix on hand and use it whenever you want to boost flavor without adding salt.","ingredients":[{"name":null,"items":["1 1/4 teaspoons black pepper","1 tablespoon garlic powder","2 tablespoons dried parsley flakes","3/4 cup dried minced onion","2 cups non-fat dried milk"]}],"directions":[{"name":null,"steps":["Combine all ingredients.","Store in airtight container.","Use in recipes as indicated."]}],"yield":"10 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup","calories":"68.76 kcal","carbohydrateContent":"11.62 g","cholesterolContent":"2.72 mg","fiberContent":"0.63 g","proteinContent":"5.57 g","sodiumContent":"75.73 mg","sugarContent":"8.69 g","fatContent":"0.16 g","saturatedFatContent":"0.08 g"},"notes":"Recipe makes about 2.5 cups, one serving size = 1/4 cup. This recipe is used in the Chili Tomato Macaroni and Beef & Potatoes recipes.","contributor":"Eating Smart Being Active Recipes\nColorado State University and University of California at Davis"},
{"slug":"egg-foo-young","source_url":"https://www.myplate.gov/recipes/egg-foo-young","name":"Egg Foo Young","description":"Make these egg patties with chicken or beef and top them off with a homemade sauce for an easy Chinese dinner. Serve with brown rice and a salad for a comple...","ingredients":[{"name":null,"items":["2 eggs","1 cup bean sprouts","1/2 cup cooked chicken, diced (can also use beef)","1/3 tablespoon dried minced onion","1 cup fresh or canned mushrooms","2 teaspoons cooking oil (or oil of your choice)"]},{"name":"Sauce Ingredients","items":["1/2 cup water","2 teaspoons low-sodium soy sauce","2 teaspoons cornstarch"]}],"directions":[{"name":null,"steps":["Beat eggs with electric mixer (or by hand) until very thick and light, about 5 minutes.","Fold in bean sprouts, chicken or beef, mushrooms, and onion.","Heat oil in frying pan over moderate heat.","Pour egg mixture by half cupsful into the pan. Brown on one side; turn and brown the other side. Keep warm while preparing the sauce.","Mix sauce ingredients in small saucepan until smooth.","Cook over low heat, stirring constantly, until thickened.","Serve sauce over patties."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"216.49 kcal","carbohydrateContent":"10.34 g","cholesterolContent":"238.84 mg","fiberContent":"2.80 g","proteinContent":"19.84 g","sodiumContent":"609.82 mg","sugarContent":"4.03 g","fatContent":"11.17 g","saturatedFatContent":"2.55 g"},"notes":"Use only clean eggs with no cracks in shells.","contributor":"Thrifty Recipes: Main Dishes\nUniversity of Maine Cooperative Extension"},
{"slug":"egg-salad","source_url":"https://www.myplate.gov/recipes/egg-salad","name":"Egg Salad","description":"Serve this creamy egg salad on a bed of lettuce or on whole wheat bread for a quick lunch.","ingredients":[{"name":null,"items":["4 hard boiled eggs, finely chopped","1 packet of pickle relish (2/3 tablespoon)","1/2 teaspoon salt","1 teaspoon mustard","1/4 cup mayonnaise"]}],"directions":[{"name":null,"steps":["Put the eggs in a pan of cold water. Simmer for 20 minutes.","Cool promptly in cold water, then in refrigerator, so the eggs will be easy to shell.","Remove the shells from eggs, and chop the eggs finely.","Mix all the ingredients together."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"168.79 kcal","carbohydrateContent":"1.41 g","cholesterolContent":"211.28 mg","fiberContent":"0.08 g","proteinContent":"6.39 g","sodiumContent":"478.90 mg","sugarContent":"0.85 g","fatContent":"15.32 g","saturatedFatContent":"3.21 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"eggplant-and-pepper-dip","source_url":"https://www.myplate.gov/recipes/eggplant-and-pepper-dip","name":"Eggplant and Pepper Dip","description":"Vegetables are roasted in the oven and then put in the blender to create a creamy and delicious low-fat dip.","ingredients":[{"name":null,"items":["1 medium eggplant","2 medium red pepper","1 small onion","1/4 teaspoon garlic powder","2 tablespoons vegetable oil","1 teaspoon oregano","1 teaspoon dried basil","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Use a vegetable peeler to remove the peel from the eggplant.","Chop the eggplant into 1-inch cubes.","Chop the red peppers.","Peel and chop the onion.","Put all the ingredients in a large bowl. Stir together.","Spread the ingredients on a baking tray.","Bake at 400 °F for 45 minutes. While vegetables are baking, stir it a few times.","When the eggplant is lightly browned and soft, take the vegetables out of the oven.","Let cool for at least 10 minutes.","Put the dip the blender. Blend until smooth.","Serve the dip cold or at room temperature."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"64.22 kcal","carbohydrateContent":"7.69 g","cholesterolContent":"0.00 mg","fiberContent":"2.72 g","proteinContent":"1.16 g","sodiumContent":"76.85 mg","sugarContent":"4.29 g","fatContent":"3.71 g","saturatedFatContent":"0.53 g"},"notes":"Try this low-fat dip with cut vegetables, toast, or as a spread on sandwiches.","contributor":"Pennsylvania Nutrition Education Network (original recipe)\nand SNAP4CT.org (photo)"},
{"slug":"eggplant-stir-fry","source_url":"https://www.myplate.gov/recipes/eggplant-stir-fry","name":"Eggplant Stir Fry","description":"Fresh vegetables are cooked in one pan to create a flavorful side dish.","ingredients":[{"name":null,"items":["2 eggplants, peeled and cubed","1 zucchini, thinly sliced","1 cup green bell pepper, cut into strips","2 onions, sliced","3 tablespoons Italian salad dressing, low fat","2 cups cherry tomatoes","2 cups cooked brown rice"]}],"directions":[{"name":null,"steps":["Place eggplant, zucchini, green bell pepper, onions and salad dressing into a skillet.","Stir lightly to combine and cook over low heat until tender.","Stir in cherry tomatoes and cook for 3-5 minutes. Serve over cooked brown rice."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (497g)","calories":"255.98 kcal","carbohydrateContent":"54.88 g","cholesterolContent":"0.00 mg","fiberContent":"11.83 g","proteinContent":"7.59 g","sodiumContent":"118.15 mg","sugarContent":"17.58 g","fatContent":"2.46 g","saturatedFatContent":"0.53 g"},"notes":null,"contributor":"Farm Fresh Summertime Recipes, Adapted from Easy Eggplant Stir Fry\nConnecticut Food Policy Council"},
{"slug":"eggs-over-kale-and-sweet-potato-grits","source_url":"https://www.myplate.gov/recipes/eggs-over-kale-and-sweet-potato-grits","name":"Eggs over Kale and Sweet Potato Grits","description":"A modern twist on a Southern classic, this baked breakfast dish features eggs and grits with sweet potatoes and kale.","ingredients":[{"name":null,"items":["1 large sweet potato (orange flesh)","2 cups fresh kale (chopped)","1 tablespoon vegetable oil (divided)","1 1/2 cups water","1 cup non-fat milk","3/4 cup grits (quick cooking)","1/4 teaspoon salt","4 eggs"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Coat 4 individual soufflé dishes with 1 tsp vegetable oil.","Make 3 to 4 slits in sweet potatoes; cook in microwave until just soft.","When sweet potatoes are cool enough to handle, peel, cut into chunks, and puree in food processor.","Heat remaining vegetable oil in sauce pan, and sauté kale about 5 minutes.","In a medium sauce pan, boil water and milk, add grits and sweet potatoes; cook for 5 minutes. Remove from heat; stir in sautéed kale.","Divide grits mixture evenly among 4 soufflé dishes (or place all in casserole dish).","Make 4 depressions in the grits mixture with the back of a large spoon. Carefully break one egg into each hollow.","Bake uncovered for 30 minutes until eggs are cooked. Let cool 10 minutes before serving."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe of Eggs over Kale and Sweet Potato Grits","calories":"182.24 kcal","carbohydrateContent":"16.04 g","cholesterolContent":"207.33 mg","fiberContent":"1.81 g","proteinContent":"9.85 g","sodiumContent":"354.32 mg","sugarContent":"5.07 g","fatContent":"8.97 g","saturatedFatContent":"2.18 g"},"notes":"Serving Suggestions: Serve with an 8-ounce glass of 100% grapefruit juice.","contributor":"Produce for Better Health Foundation"},
{"slug":"elaines-green-mash-potatoes","source_url":"https://www.myplate.gov/recipes/elaines-green-mash-potatoes","name":"Elaine’s Green-Mash Potatoes","description":"Since my family has an Irish ancestry, we first made this Green-Mash Potatoes Recipe for St. Patrick''s Day. However, everyone loved it so much that it''s now ...","ingredients":[{"name":null,"items":["7 potatoes (medium size, about 1 cup each)","1 cup skim milk (divided)","2 garlic cloves (peeled)","1 cup frozen peas","2 tablespoons soft (tub) margarine","1/8 teaspoon white pepper (optional)","1/4 teaspoon Kosher salt"]}],"directions":[{"name":null,"steps":["Simmer peeled, diced potatoes for about 10 minutes until soft when pierced with a fork.","Cook 1 cup peas in microwave for about 3 minutes; drain and reserve.","Heat milk until hot. Add garlic cloves to milk and let stand for 5 minutes.","Puree peas, 1/4 cup milk, and garlic cloves using a blender.","Drain potatoes and begin to mash.","Slowly add 3/4 cup milk while mashing.","Blend in the puréed peas and garlic, margarine, and white pepper (optional) to the mashed potatoes.","Place mashed potatoes in a serving dish and keep warm.","Just before serving, lightly sprinkle Kosher salt on top of potatoes."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 portion of Elaine''s Green-Mash Potatoes","calories":"186.90 kcal","carbohydrateContent":"36.46 g","cholesterolContent":"0.95 mg","fiberContent":"4.27 g","proteinContent":"5.91 g","sodiumContent":"140.07 mg","sugarContent":"4.22 g","fatContent":"2.37 g","saturatedFatContent":"0.50 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion\nRecipe submitted by Elaine, MyPlate Nutritionist"},
{"slug":"enchilada-bake","source_url":"https://www.myplate.gov/recipes/enchilada-bake","name":"Enchilada Bake","description":"Black beans mixed with cumin, onion, and garlic make the base for these vegetable enchiladas. Bake them in the oven and top them with cheese for a satisfying...","ingredients":[{"name":null,"items":["1 tablespoon oil","1 medium onion, chopped","3 cloves garlic, minced","2 cups black beans, cooked (or low-sodium canned)","1 cup kernel corn (1/2 of a 15.2 ounce can, low-sodium, drained and rinsed)","1 teaspoon cumin","2 cups prepared salsa, divided","8 corn tortillas","1/2 cup Monterey Jack cheese, shredded"]}],"directions":[{"name":null,"steps":["In a large skillet heat oil over medium-high heat; sauté onion and garlic 2 to 3 minutes.","Add beans, corn, cumin and 1/2 cup salsa. Cook 3-4 minutes, coarsely mashing beans with back of spoon.","Spoon 1/3 cup filling onto each tortilla; roll up.","Spoon 1/2 cup salsa into 11x7x2 inch baking dish. Arrange tortillas seam side down; top with remaining 1 cup sauce.","Cover and bake in 350 °F oven for 15 to 20 minutes.","Uncover; top with cheese. Bake 2 minutes longer or until cheese is melted."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 enchilada","calories":"197.49 kcal","carbohydrateContent":"30.96 g","cholesterolContent":"6.29 mg","fiberContent":"7.72 g","proteinContent":"8.51 g","sodiumContent":"481.55 mg","sugarContent":"3.44 g","fatContent":"5.23 g","saturatedFatContent":"1.81 g"},"notes":null,"contributor":"The Bold and Beautiful Book of Bean Recipes\nWashington State WIC Program"},
{"slug":"enchilada-casserole","source_url":"https://www.myplate.gov/recipes/enchilada-casserole","name":"Enchilada Casserole","description":"It’s the best of both worlds: the deliciousness of enchiladas with the ease of a casserole! This recipe is perfect for a satisfying weeknight dinner.","ingredients":[{"name":null,"items":["3 1/2 cups (28 ounce can) green enchilada sauce","1 can (15.5 ounces) low-sodium pinto beans, drained and rinsed","3 cups brown rice, cooked","1 1/2 cups frozen corn","12 (6-inch) corn tortillas","10 ounces low-fat Monterey Jack cheese (2 1/2 cups shredded)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","In a large bowl, mix enchilada sauce, beans, cooked rice, and corn.","Place half of mixture on the bottom of a 9x13-inch pan or split it between two 9-inch square or round pans.","Spread the corn tortillas evenly over the mixture. Place remaining mixture on top of tortillas.","Top mixture with cheese, and cover with foil. Bake for 15 to 20 minutes.","Remove foil and bake for 10 more minutes or until cheese is melted and sauce is bubbly.","Refrigerate leftovers within 2 hours. Eat within 3 to 5 days."]}],"yield":"8","nutrition":{"@type":"NutritionInformation","calories":"360.69"},"notes":"Cook rice according to package directions.\nIf you made two pans, you can freeze one of them before baking. Double-wrap in foil and it will keep for up to 1 month in the freezer.","contributor":"Eating Smart, Being Active\nColorado State University"},
{"slug":"enchilada-rice","source_url":"https://www.myplate.gov/recipes/enchilada-rice","name":"Enchilada Rice","description":"Add your favorite vegetables and any lean ground meat to create this easy dish.","ingredients":[{"name":null,"items":["1 pound 90% lean ground beef (or other ground meat)","1/2 cup onion (chopped, or 1 Tbsp onion powder)","1 can whole corn, low-sodium (15.2 ounce, or any low-sodium canned vegetable, drained)","4 tablespoons taco seasoning mix (dry, or dry enchilada sauce)","2 cups brown rice, cooked","1/2 cup cheese (grated)","mushrooms, olives or any favorite vegetable (1/2 cup sliced, optional)"]}],"directions":[{"name":null,"steps":["Cook meat and onion until onion juices are clear.","Drain juice and fat from cooked meat and onions.","Add corn, taco seasoning, and rice.","Simmer for 10 minutes.","Add grated cheese to top; cover and let set for 5 minutes.","Refrigerate leftovers within 2 hours."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (219g)","calories":"295.89 kcal","carbohydrateContent":"32.12 g","cholesterolContent":"53.23 mg","fiberContent":"3.33 g","proteinContent":"19.04 g","sodiumContent":"523.91 mg","sugarContent":"4.58 g","fatContent":"10.01 g","saturatedFatContent":"4.23 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"english-muffin-veggie-pizza","source_url":"https://www.myplate.gov/recipes/english-muffin-veggie-pizza","name":"English Muffin Veggie Pizza","description":"Create your own easy-to-make personal pizza and add your favorite veggie toppings. Choose whole wheat muffins to make this recipe even better!","ingredients":[{"name":null,"items":["1 cup broccoli (cooked chopped)","4 English muffins","1 cup pizza sauce (or spaghetti sauce)","1/2 cup mozzarella cheese, shredded, part skim","1/4 cup carrot (4 tablespoons, shredded)","1/3 tablespoon Parmesan cheese (1 teaspoon, grated)"]}],"directions":[{"name":null,"steps":["Cut the broccoli to make 1 cup of chopped broccoli.","Put the broccoli in a saucepan with water. Cook on medium until tender.","Drain the water from the saucepan. Let the broccoli cool.","Cut 4 English muffins in half. Toast the 8 muffin halves.","Shred the mozzarella cheese to make 1/2 cup of shredded cheese.","Peel and shred the carrots to make 3 tablespoons shredded carrots.","Spoon 2 tablespoons pizza sauce over each English muffin half.","Sprinkle 1 tablespoon shredded mozzarella cheese on top of each half.","Put 2 tablespoons broccoli and 1 teaspoon shredded carrots on top of each half.","Sprinkle each half with 1 teaspoon grated parmesan cheese.","Toast in the toaster oven for 2 minutes, until the cheese melts."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 pizzas (each made from 1/2 English muffin)","1/4 of recipe (185g)"],"calories":"220.65 kcal","carbohydrateContent":"33.72 g","cholesterolContent":"10.84 mg","fiberContent":"3.97 g","proteinContent":"10.20 g","sodiumContent":"636.98 mg","sugarContent":"6.56 g","fatContent":"5.04 g","saturatedFatContent":"2.27 g"},"notes":"Try making these pizzas with whole wheat muffins.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"european-salad","source_url":"https://www.myplate.gov/recipes/european-salad","name":"European Salad","description":"Delightful mix of fresh salad fixings topped with sautéed chicken and a light, flavorful raspberry vinaigrette. Save time by using a blender to make the vin...","ingredients":[{"name":null,"items":["12 ounces chicken breast (pre-sliced)","1/4 teaspoon salt","1/4 teaspoon ground black pepper","2 teaspoons olive oil","3 green onions (sliced)","1 large yellow bell pepper, cut in strips (about 1 1/2 cups)","16 cherry tomatoes","1 10-oz package European blend salad greens","1 1/2 cups croutons (whole grain if available, about 24 croutons)","fresh ground pepper, to taste"]},{"name":"For the vinaigrette","items":["3/4 cup frozen raspberries, thawed","1 tablespoon olive oil","2 tablespoons cider vinegar","1 teaspoon sugar","1/4 teaspoon garlic salt","1/4 teaspoon oregano","1/4 teaspoon ground black pepper"]}],"directions":[{"name":null,"steps":["Place all vinaigrette ingredients in a blender, blend until smooth; set aside. (Note: Vinaigrette can be made ahead and refrigerated.)","Season chicken with salt and pepper.","Heat olive oil in a large skillet.","Sauté chicken until cooked thoroughly; remove from pan, and let cool.","Slice onions.","Toss cut vegetables with European blend salad greens.","On individual serving plates, top salad with chicken and croutons, drizzle with dressing, and finish with fresh ground pepper, if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"294.81 kcal","carbohydrateContent":"20.24 g","cholesterolContent":"84.03 mg","fiberContent":"5.11 g","proteinContent":"29.81 g","sodiumContent":"365.07 mg","sugarContent":"6.28 g","fatContent":"10.31 g","saturatedFatContent":"1.80 g"},"notes":"Serving Suggestions: Serve with fruit, non-fat milk, and whole grain bread.","contributor":"Produce for Better Health Foundation"},
{"slug":"eves-tasty-turkey-tetrazzini","source_url":"https://www.myplate.gov/recipes/eves-tasty-turkey-tetrazzini","name":"Eve’s Tasty Turkey Tetrazzini","description":"Our family loves the savory flavors of a turkey dinner. However, after a few rounds of leftovers, it''s great to be able to taste new flavors and prepare an e...","ingredients":[{"name":null,"items":["8 ounces whole-wheat fettuccine, spaghetti, macaroni, or other noodles","4 tablespoons light butter (unsalted)","2 cups mushrooms, sliced (fresh or canned)","1 teaspoon dried thyme","1/2 cup all-purpose flour","2 cups reduced-sodium chicken broth","1 1/2 cups skim milk","4 cups chopped cooked turkey","1/2 cup slivered almonds, toasted","1 cup peas (frozen)","2 tablespoons grated Parmesan cheese"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F. Lightly grease a 9x9 inch baking dish.","Cook pasta in a large pot of boiling water until tender. (Check cooking time for pasta; remove pasta approximately 2 minutes early.)","While pasta is cooking, melt butter in a saucepan over medium heat. Add the mushrooms and thyme. Stir and cook until mushrooms are softened, about 5 minutes.","Stir in flour until well blended. (Note: Start with 1/3 cup flour and add more, if needed.)","While whisking, slowly add chicken broth and milk. Bring to a boil, reduce heat, and simmer until sauce is thickened and smooth, about 5 minutes.","Add turkey, toasted almonds, frozen peas, and cooked pasta. Gently mix together. Pour into the baking dish and sprinkle with Parmesan cheese.","Bake until the sauce is bubbling and the cheese is golden brown, 25 to 35 minutes. Let cool 15 minutes before serving."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Portion of Eve''s Tasty Turkey Tetrazzini","calories":"379.47 kcal","carbohydrateContent":"38.61 g","cholesterolContent":"61.60 mg","fiberContent":"5.57 g","proteinContent":"31.95 g","sodiumContent":"203.34 mg","sugarContent":"4.60 g","fatContent":"11.98 g","saturatedFatContent":"3.70 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion\nRecipe submitted by Eve, USDA Nutritionist"},
{"slug":"fabulous-fig-bars","source_url":"https://www.myplate.gov/recipes/fabulous-fig-bars","name":"Fabulous Fig Bars","description":"Fig bars are a great on-the-go snack. The sweet, nutty flavors in these bars are sure to be a hit with all ages.","ingredients":[{"name":null,"items":["2 cups dried figs (chopped, 16 ounces)","1/2 cup walnuts (chopped)","1/3 cup sugar","1/4 cup orange juice (juice from 1/2 orange)","2 tablespoons hot water","1/2 cup margarine (softened, or butter)","1 cup packed brown sugar","1 large egg","1 1/2 cups all-purpose flour","1/2 teaspoon baking soda","1 1/4 cups old fashioned rolled oats"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Lightly grease a 9x13 inch baking pan.","Combine figs, walnuts, sugar, orange juice, and hot water in a mixing bowl and set aside.","Mix together margarine or butter and brown sugar until creamy. Add egg and mix until smooth.","Mix flour and baking soda. Stir into egg mixture. Blend in oats to make soft dough.","Reserve 1 cup of dough for topping. With floured fingertips, press the remaining dough into a thin layer on the bottom of the baking pan.","Spread fig mixture evenly over the dough. Crumble reserved dough over top, allowing fig mixture to show.","Bake 30 minutes or until golden brown. Cool completely in baking pan. Cut into 24 bars (about 2 1/2 x 2 inches)."]}],"yield":"24","nutrition":{"@type":"NutritionInformation","calories":"185.41"},"notes":"No dried figs? Use 3 cups chopped fresh figs. Omit the hot water and orange juice, but add 1 teaspoon lemon or orange zest (grate the outer colored part of the peel).\nMargarine used for nutrition and cost analysis.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"fabulous-fruit-muffins","source_url":"https://www.myplate.gov/recipes/fabulous-fruit-muffins","name":"Fabulous Fruit Muffins","description":"Try these muffins for breakfast or as a snack during the day. Use fresh fruit when in season - frozen or canned fruit works too!","ingredients":[{"name":null,"items":["1 1/4 cups flour","1/4 cup sugar","1 teaspoon baking powder","1/2 teaspoon baking soda","3/4 cup low-fat buttermilk","2 tablespoons margarine, melted","1 egg, slightly beaten","1/2 teaspoon vanilla extract","1 cup frozen strawberries, unsweetened, coarsely chopped (or other fruit, fresh or frozen)"]}],"directions":[{"name":null,"steps":["Heat oven to 400 °F. Spray muffin tin with non-stick cooking spray.","In a large bowl, combine the flour, sugar, baking powder, and baking soda. Stir well until all ingredients are blended.","In another bowl, combine buttermilk, margarine, egg, and vanilla. Pour this mixture into the dry ingredients (made in step #3).","Using a large spoon, gently stir ingredients just until moist (do not over-mix). Add fruit and stir gently (do not over-mix).","Spoon batter evenly into 9 muffin cups.","Bake 20 to 25 minutes or until golden brown.","Serve hot or cold. Muffins may be frozen for later use."]}],"yield":"9 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/9 of recipe"],"calories":"124.94 kcal","carbohydrateContent":"21.53 g","cholesterolContent":"23.68 mg","fiberContent":"0.82 g","proteinContent":"3.24 g","sodiumContent":"183.21 mg","sugarContent":"7.49 g","fatContent":"2.84 g","saturatedFatContent":"0.72 g"},"notes":null,"contributor":"Fix it Fresh! Recipe Series\nKansas State University Research and Extension"},
{"slug":"falafel-yogurt-sandwich","source_url":"https://www.myplate.gov/recipes/falafel-yogurt-sandwich","name":"Falafel with Yogurt Sandwich","description":"Falafel is a pan-fried patty made from ground garbanzo beans (chickpeas) and Middle Eastern spices. It makes a healthy and delicious sandwich when served wit...","ingredients":[{"name":null,"items":["1 cup dry garbanzo beans/chickpeas (sorted and rinsed)","3 cups water","1/4 cup oil","1 garlic clove (crushed)","1 medium onion (chopped)","1/3 tablespoon parsley (1 sprig or about 1 teaspoon, chopped)","1/4 teaspoon salt","2 teaspoons lemon juice","1/3 teaspoon hot pepper sauce","1 cup plain yogurt, low-fat","1 medium onion (chopped)","4 whole wheat pita bread (pockets)","1/4 cup flour (as needed)","tomatoes (sliced, optional)","lettuce (optional)","bread crumbs (optional - see note)"]}],"directions":[{"name":null,"steps":["Put beans and water in large pot and soak by the overnight or quick-soak method.","Cook until tender, about 2 hours. Add more water if necessary. Drain.","Slowly heat oil and sauté garlic and 1 onion until tender (5 to 7 minutes).","Mash cooked beans, sautéed vegetables, parsley, salt, lemon juice and hot pepper sauce until smooth.","With floured hands, form ovals with bean mixture (about 1/4 cup each). Roll in flour.","Fry falafel, with the remaining oil in skillet, until golden brown. Drain on paper towel.","Combine yogurt with remaining onion.","Serve falafel in pocket bread topped with yogurt."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 sandwich (480g)","calories":"542.65 kcal","carbohydrateContent":"77.54 g","cholesterolContent":"3.68 mg","fiberContent":"12.91 g","proteinContent":"19.58 g","sodiumContent":"450.82 mg","sugarContent":"14.70 g","fatContent":"18.76 g","saturatedFatContent":"2.98 g"},"notes":"If the batter is too moist, add breadcrumbs to make it thicker. It may take up to a cup of breadcrumbs.","contributor":"The Bold and Beautiful Book of Bean Recipes\nWashington State WIC Program"},
{"slug":"fall-veggie-casserole","source_url":"https://www.myplate.gov/recipes/fall-veggie-casserole","name":"Fall Veggie Casserole","description":"Grab some fresh eggplant and tomatoes from the market and serve this veggie casserole with dinner that is topped off with Parmesan cheese.","ingredients":[{"name":null,"items":["5 1/2 cups eggplant, cubes (1 medium eggplant)","4 tomatoes","1 green pepper","1 onion","1 clove garlic","1 teaspoon salt","1/4 teaspoon black pepper","3 tablespoons vegetable oil (or cooking oil of choice)","2 tablespoons Parmesan cheese, grated"]}],"directions":[{"name":null,"steps":["Remove the skin from the eggplant. Cut the eggplant into cubes. Chop the tomatoes into small pieces.","Cut the green pepper in half. Remove the seeds and cut it into small pieces.","Chop the onion into small pieces.","Cut the garlic into tiny pieces.","Combine all of the ingredients (except for the cheese) and cook in a large skillet over medium heat until tender.","Top with the Parmesan cheese and serve."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"88.13 kcal","carbohydrateContent":"8.35 g","cholesterolContent":"1.08 mg","fiberContent":"2.55 g","proteinContent":"1.79 g","sodiumContent":"320.87 mg","sugarContent":"4.54 g","fatContent":"5.82 g","saturatedFatContent":"0.97 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"fantastic-french-toast","source_url":"https://www.myplate.gov/recipes/fantastic-french-toast","name":"French Toast","description":"Start your day with this classic breakfast recipe and serve it with fresh or canned fruit.","ingredients":[{"name":null,"items":["2 large eggs","1/2 cup non-fat (skim) milk","1/2 teaspoon vanilla extract","6 slices whole wheat bread","syrup or other toppings (optional)"]}],"directions":[{"name":null,"steps":["Preheat the griddle over medium heat, or set an electric frying pan at 375 °F.","Put eggs, milk, and vanilla in a pie pan or shallow bowl and beat with a fork until well mixed.","Grease the griddle or pan with a thin layer of oil or use nonstick spray.","Dip both sides of bread, one slice at a time, in the egg mixture and cook on the hot griddle or frying pan.","Cook on one side until golden brown. Turn the bread over to cook the other side. It will take about 4 minutes on each side.","Optional: serve with syrup, applesauce, fruit slices, or jam."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/6 of recipe"],"calories":"123.19 kcal","carbohydrateContent":"16.72 g","cholesterolContent":"69.11 mg","fiberContent":"2.16 g","proteinContent":"7.19 g","sodiumContent":"191.87 mg","sugarContent":"2.69 g","fatContent":"2.95 g","saturatedFatContent":"0.81 g"},"notes":null,"contributor":"Adapted from Fantastic French Toast, University of Wisconsin Cooperative Extension\nFamily Living Program"},
{"slug":"farmers-market-gazpacho","source_url":"https://www.myplate.gov/recipes/farmers-market-gazpacho","name":"Farmers Market Gazpacho","description":"Garlic, cumin, and lemon juice give a zesty flavor to this cold, blended vegetable soup. Cilantro added at the end leaves a refreshing pop of flavor.","ingredients":[{"name":null,"items":["2 medium cucumbers, diced into 1/4 inch pieces","3 medium red bell peppers, seeded and diced into 1/4 inch pieces","3 medium green peppers, seeded and diced into 1/4 inch pieces","4 medium celery stalks, diced into 1/4 inch pieces","2 medium tomatoes, diced into 1/4 inch pieces","1 medium onion, diced into 1/4 inch pieces","2 cups low-sodium tomato juice","3 garlic cloves, minced","1 tablespoon ground cumin","1 cup fresh cilantro, chopped","salt and pepper (to taste, optional)","2 lemons, juiced"]}],"directions":[{"name":null,"steps":["Combine all ingredients except salt, pepper, and lemons in a bowl.","Remove 2 cups of the mixture and reserve.","Using a blender or food processor, puree the remaining mixture in the bowl.","Add 2 cups of reserved mixture to the pureed mixture.","Season with salt, pepper (optional) and the juice from the lemons.","Cover mixture and refrigerate for at least 2 hours before serving.","Serve cold, garnished with chopped cilantro."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"137.96 kcal","carbohydrateContent":"30.11 g","cholesterolContent":"0.00 mg","fiberContent":"7.72 g","proteinContent":"5.43 g","sodiumContent":"121.24 mg","sugarContent":"16.04 g","fatContent":"1.75 g","saturatedFatContent":"0.27 g"},"notes":null,"contributor":"Veggin’ Out Recipe Book\nJohnson and Wales University and Rhode Island Department of Health WIC Program"},
{"slug":"farmers-market-salsa","source_url":"https://www.myplate.gov/recipes/farmers-market-salsa","name":"Farmers Market Salsa","description":"Lime, garlic, and fresh vegetables give this black bean and corn salsa a kick of flavor.","ingredients":[{"name":null,"items":["1/2 cup fresh corn, cooked (or frozen)","1 can (15 ounces) low-sodium black beans, drained and rinsed","1 cup tomatoes, diced","1/2 cup onions, diced (yellow or red)","1/2 cup green pepper, diced","2 tablespoons lime juice","2 garlic clove, finely chopped","1/2 cup picante sauce"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a large bowl. Chill until serving time.","Drain before serving.","Serve with low-fat baked tortilla chips or fresh vegetables."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"74.10 kcal","carbohydrateContent":"14.36 g","cholesterolContent":"0.00 mg","fiberContent":"4.78 g","proteinContent":"4.16 g","sodiumContent":"181.22 mg","sugarContent":"2.79 g","fatContent":"0.41 g","saturatedFatContent":"0.09 g"},"notes":"This salsa uses fresh vegetables that are available year-round and add flavor and beautiful color. Kids and grown-ups alike can''t resist how good it tastes. If you have a hand-held chopper, this is an easy task for kids in helping with the recipe.\nSafety Tip: If cutting the corn off the cob, adult supervision is a good idea.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"fat-free-apple-crumb-dessert","source_url":"https://www.myplate.gov/recipes/fat-free-apple-crumb-dessert","name":"Fat-Free Apple Crumb Dessert","description":"Oatmeal mixed with cinnamon and brown sugar is a delicious topping for this baked apple dessert.","ingredients":[{"name":null,"items":["4 apples (medium, baking)","1/2 cup oatmeal, quick cooking (uncooked)","1/4 cup brown sugar (light or dark)","2 teaspoons cinnamon (ground)","1/3 cup 100% apple juice","4 sprays of non-stick cooking spray"]}],"directions":[{"name":null,"steps":["Move the oven rack to the center of the oven. Then preheat the oven to 350 °F.","Spray the bottom and sides of a 9 inch square baking dish with nonstick cooking spray.","Wash and peel the apples. Cut them into thin slices.","Spread the apple slices evenly over the bottom of the baking dish.","In a small bowl, use a fork to mix the oatmeal, brown sugar and cinnamon.","Spread the oatmeal mix evenly over the apples in the baking dish.","Lightly pour the apple juice over the oatmeal mixture.","Cover the dish and bake for 20 to 30 minutes until apples are just starting to soften.","Uncover and bake for another 15 to 20 minutes until apples are soft."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"209.75 kcal","carbohydrateContent":"48.68 g","cholesterolContent":"0.00 mg","fiberContent":"5.94 g","proteinContent":"1.74 g","sodiumContent":"4.47 mg","sugarContent":"35.18 g","fatContent":"1.26 g","saturatedFatContent":"0.19 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"feather-rolls","source_url":"https://www.myplate.gov/recipes/feather-rolls","name":"Feather Rolls","description":"Whole wheat flour increases the fiber in these dinner rolls. Dough can be used immediately or stored in the refrigerator for several days until you are ready...","ingredients":[{"name":null,"items":["4 cups flour, whole wheat","3/4 cup flour, all-purpose","1 1/4 tablespoons yeast, dry active","1 cup non-fat dry milk powder","1 1/2 cups warm water","1/3 cup oil","3 tablespoons sugar (or honey)","2 eggs, large (or 4 egg whites)","1 teaspoon salt"]}],"directions":[{"name":null,"steps":["Mix 2 1/2 cups whole wheat flour, dry yeast, and non-fat dry milk in large mixer bowl. Add water, oil, and sugar (or honey). Mix well 1 to 2 minutes.","Turn off mixer, cover, and let dough sit for 10 minutes.","Add eggs and salt. Turn on mixer. Add remaining flour, 1 cup at a time, until dough begins to form a ball.","Knead for 5 to 6 minutes. Dough should be very soft and manageable. Stiff dough produces heavy, dry rolls. If dough stiffens while mixing, drizzle a little warm water over dough as it kneads.","Dough may be used immediately or covered and stored in the refrigerator for several days.","Lightly oil hands and counter top if needed. Shape immediately into rolls. Let rise until very light.","Bake at 350 °F for 18 to 20 minutes. Do not overbake."]}],"yield":"30 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 roll","1/30 of recipe"],"calories":"107.56 kcal","carbohydrateContent":"16.56 g","cholesterolContent":"14.15 mg","fiberContent":"1.93 g","proteinContent":"3.87 g","sodiumContent":"96.25 mg","sugarContent":"2.51 g","fatContent":"3.29 g","saturatedFatContent":"0.53 g"},"notes":"* Children under the age of one should not consume honey.","contributor":"USDA Supplemental Nutrition Assistance Program (SNAP)"},
{"slug":"festive-microwave-baked-apples","source_url":"https://www.myplate.gov/recipes/festive-microwave-baked-apples","name":"Festive Microwave Baked Apples","description":"Short on time? Fill cored apples with cinnamon, nutmeg, and raisins and bake the dish in the microwave for a quick and easy dessert.","ingredients":[{"name":null,"items":["1 apple (medium, skinned and cored (not cut into pieces))","1 teaspoon brown sugar","1/2 tablespoon nutmeg","1 tablespoon cinnamon","2 tablespoons raisins","1 tablespoon butter"]}],"directions":[{"name":null,"steps":["Place apple on plate with opening facing up (cored apples should have bottom intact).","Stir sugar, nutmeg, and cinnamon in a separate cup, and sprinkle into and onto apple.","Sprinkle raisins on and around apple.","Drop butter alternative spread onto apple and cover with plastic wrap or wax paper.","Microwave on HIGH for 2 1/2 to 3 minutes.","Let sit outside of microwave for at least 30 seconds before eating. It will be HOT."]}],"yield":"1 Apple","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"338.74 kcal","carbohydrateContent":"57.99 g","cholesterolContent":"30.53 mg","fiberContent":"9.97 g","proteinContent":"1.64 g","sodiumContent":"9.39 mg","sugarContent":"41.98 g","fatContent":"13.24 g","saturatedFatContent":"8.18 g"},"notes":"Fruit is naturally sweet so try making this without sugar.","contributor":"CSAAC (Community Services for Autistic Adults and Children)"},
{"slug":"fiesta-hummus","source_url":"https://www.myplate.gov/recipes/fiesta-hummus","name":"Fiesta Hummus","description":"This dip is full of protein and can be served with vegetables or whole wheat pita for a healthy snack. Make it as spicy as you like by adding more or less of...","ingredients":[{"name":null,"items":["1 can garbanzo beans, low-sodium","1/2 teaspoon cumin","1/4 teaspoon salt","1/8 teaspoon cayenne pepper","2 garlic cloves (minced)","1/2 cup yogurt (plain, non-fat)","1 tablespoon lime juice","1 tablespoon sesame oil","1 jalapeno pepper (finely chopped)","2 tablespoons cilantro (chopped)"]}],"directions":[{"name":null,"steps":["Drain and mash garbanzo beans in blender, food processor, or with fork. Add remaining ingredients.","Blend until smooth.","Chill one hour or overnight.","Serve on crackers or tortilla chips. Promptly refrigerate leftovers."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup","calories":"100.43 kcal","carbohydrateContent":"12.27 g","cholesterolContent":"0.41 mg","fiberContent":"3.37 g","proteinContent":"4.93 g","sodiumContent":"211.64 mg","sugarContent":"3.64 g","fatContent":"3.86 g","saturatedFatContent":"0.51 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"fiesta-lettuce-wraps-and-pepper-boats","source_url":"https://www.myplate.gov/recipes/fiesta-lettuce-wraps-and-pepper-boats","name":"Fiesta Lettuce Wraps and Pepper Boats","description":"Using bell peppers and lettuce for wraps is a fun way to increase vegetables on the plate. Lettuce leaves and mini peppers are perfect for a build-your-own S...","ingredients":[{"name":null,"items":["6 sweet, mini bell peppers","8 lettuce leaves","1 cup instant brown rice (dry)","1 pound tilapia filets, fresh or frozen (thawed)","2 teaspoons Southwest chipotle seasoning (no sodium)","2 tablespoons canola oil (divided)","1/4 teaspoon salt","2 limes (divided)","1/4 cup reduced-fat sour cream"]},{"name":"For the Salsa Fresca","items":["1/2 cup yellow corn (frozen or canned, no-salt added)","1 medium tomato","1 small onion","1 clove garlic (minced)","1 jalapeno pepper (minced)","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Slice peppers in half vertically. Arrange lettuce and 8 pepper halves on a serving platter.","Cook brown rice according to package directions.","To make salsa fresca, dice remaining pepper halves, tomato, and onion; mix with corn, garlic, jalapeño pepper, and 1/4 teaspoon salt.","Sprinkle both sides of tilapia filets with Southwest chipotle seasoning.","Heat 1 1/2 tablespoons canola oil in a large nonstick skillet over medium-high heat. Add fish to pan, and cook for 3 minutes on each side (cook fish until it is opaque, 145 ºF). Flake with a fork and place in a serving dish.","When rice is done, stir in remaining 1/2 tablespoon oil, juice from one lime, and ¼ tsp salt. Cut remaining lime into wedges.","To serve, set out pepper-lettuce platter, rice, fish, salsa fresca, sour cream, and lime, and let diners build their own boats and wraps"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"504.62 kcal","carbohydrateContent":"69.82 g","cholesterolContent":"50.50 mg","fiberContent":"5.91 g","proteinContent":"29.02 g","sodiumContent":"370.33 mg","sugarContent":"7.33 g","fatContent":"12.91 g","saturatedFatContent":"2.69 g"},"notes":"Serving Suggestion: Serve with an 8 ounce glass of fat-free (skim) milk. Substitute brown rice with another quick cooking grain, such as whole-wheat couscous if desired.","contributor":"Produce for Better Health Foundation"},
{"slug":"fiesta-mix","source_url":"https://www.myplate.gov/recipes/fiesta-mix","name":"Party Mix","description":"Serve this mix of cereal, raisins, peanuts, and coconut at your next get-together.","ingredients":[{"name":null,"items":["1 cup cereal with fruit (flakes with raisins type)","1 cup bran cereal (chex type)","1 cup cereal (\"O\" type)","1/4 cup raisins","1/4 cup peanuts","1/4 cup shredded coconut"]}],"directions":[{"name":null,"steps":["Mix cereals together in a large bowl.","Add raisins, peanuts, and coconut; mix well.","Eat it dry or with milk."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (49g)","calories":"237.77 kcal","carbohydrateContent":"38.28 g","cholesterolContent":"0.00 mg","fiberContent":"6.46 g","proteinContent":"6.79 g","sodiumContent":"209.56 mg","sugarContent":"13.51 g","fatContent":"7.46 g","saturatedFatContent":"2.49 g"},"notes":null,"contributor":"\"Fiesta Mix\"\nFood Hero\nOregon State University Cooperative Extension Service"},
{"slug":"fiesta-rice-salad","source_url":"https://www.myplate.gov/recipes/fiesta-rice-salad","name":"Fiesta Rice Salad","description":"This cool and refreshing salad is a great way to use leftover rice and turn it into dinner on a hot summer night.","ingredients":[{"name":null,"items":["1 cup brown rice (cooked)","1 carrot (shredded)","1 cup broccoli (chopped fine)","1 small red onion (chopped)","1 cup tomato (chopped)","1 sweet bell pepper, green, red, or yellow (chopped)","1 can kidney beans, low-sodium (15.5 ounce, drained, rinsed)","2 tablespoons cilantro (or other fresh herbs) (chopped fine)","2 tablespoons red wine vinegar (or white or cider)","1 tablespoon vegetable oil","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Wash and chop vegetables and mix with cooked rice.","In a small bowl, add vinegar, oil, dill, salt and pepper. (Or use your favorite dressing.) Pour over rice mixture.","Add beans and toss well. Serve cold and enjoy!"]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (49g)","calories":"225.93 kcal","carbohydrateContent":"38.01 g","cholesterolContent":"0.00 mg","fiberContent":"9.26 g","proteinContent":"8.75 g","sodiumContent":"152.69 mg","sugarContent":"7.26 g","fatContent":"4.70 g","saturatedFatContent":"0.81 g"},"notes":"Use your favorite vegetables – zucchini, summer squash, corn, greens, kohlrabi, cabbage, or string beans. Use frozen or canned when fresh is unavailable. Grate, chop, cut into small thin strips for different shapes.\nBe creative! Try different vinegars – cider, red or white wine, balsamic, rice or white – or flavored vinegars.\nUse low calorie salad dressing and leave out the vinegar and oil.\nTry a squeeze of lemon or lime juice in place of vinegar!\nTry different fresh herbs – cilantro, dill, basil, chives, tarragon, oregano, rosemary, or mint to name a few. Or use dried herbs – but use less.","contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"fiesta-stuffed-avocado","source_url":"https://www.myplate.gov/recipes/fiesta-stuffed-avocado","name":"Fiesta Stuffed Avocado","description":"Brighten up your snack selection with some fresh, fiesta flavor. Only five ingredients.","ingredients":[{"name":null,"items":["1/3 cup black beans, low sodium","1 tomato sliced and diced (~2 Tbsp tomatoes, diced)","1 tablespoon onion, diced","1 teaspoon lemon juice","1/2 ripe, fresh avocado, halved, pitted and peeled"]}],"directions":[{"name":null,"steps":["In a bowl, combine black beans, tomatoes and onion. Squeeze in fresh lemon juice.","Serve in fresh avocado half."]}],"yield":"1 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 avocado half","calories":"201.51 kcal","carbohydrateContent":"21.62 g","cholesterolContent":"0.00 mg","fiberContent":"10.95 g","proteinContent":"6.56 g","sodiumContent":"115.60 mg","sugarContent":"1.98 g","fatContent":"11.34 g","saturatedFatContent":"1.67 g"},"notes":"For more information, visit: https://loveonetoday.com/","contributor":"Created by Fresh Avocados Love One Today, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"fig-bars","source_url":"https://www.myplate.gov/recipes/fig-bars","name":"Fig Bars","description":"Fig bars are a great on-the-go snack. The sweet, nutty flavors in these bars are sure to be a hit with all ages.","ingredients":[{"name":null,"items":["2 cups dried figs (chopped, 16 ounces)","1/2 cup walnuts (chopped)","1/3 cup sugar","1/4 cup orange juice (juice from 1/2 orange)","2 tablespoons hot water","1/2 cup margarine (softened, or butter)","1 cup packed brown sugar","1 large egg","1 1/2 cups all-purpose flour","1/2 teaspoon baking soda","1 1/4 cups old fashioned rolled oats"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Lightly grease a 9x13 inch baking pan.","Combine figs, walnuts, sugar, orange juice, and hot water in a mixing bowl and set aside.","Mix together margarine or butter and brown sugar until creamy. Add egg and mix until smooth.","Mix flour and baking soda. Stir into egg mixture. Blend in oats to make soft dough.","Reserve 1 cup of dough for topping. With floured fingertips, press the remaining dough into a thin layer on the bottom of the baking pan.","Spread fig mixture evenly over the dough. Crumble reserved dough over top, allowing fig mixture to show.","Bake 30 minutes or until golden brown. Cool completely in baking pan. Cut into 24 bars (about 2 1/2 x 2 inches)."]}],"yield":"24 Bars","nutrition":{"@type":"NutritionInformation","servingSize":"1 bar","calories":"172.44 kcal","carbohydrateContent":"29.70 g","cholesterolContent":"8.61 mg","fiberContent":"2.11 g","proteinContent":"2.48 g","sodiumContent":"64.79 mg","sugarContent":"18.36 g","fatContent":"5.12 g","saturatedFatContent":"0.86 g"},"notes":"No dried figs? Use 3 cups chopped fresh figs. Omit the hot water and orange juice, but add 1 teaspoon lemon or orange zest (grate the outer colored part of the peel).\nMargarine used for nutrition and cost analysis.","contributor":"Original Recipe Name - Fabulous Fig Bars\nFood Hero\nOregon State University Cooperative Extension Service"},
{"slug":"fish-spinach","source_url":"https://www.myplate.gov/recipes/fish-spinach","name":"Fish with Spinach","description":"Cod fillets are pan-fried until golden brown and mixed with a rich tomato and spinach sauce for an easy seafood dish. Top with olives and serve with a favori...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1 pound skinless cod fillets","1 yellow onion (peeled and chopped into 1/4 inch pieces)","2 cloves garlic (peeled and minced)","2 cups canned low-sodium diced tomatoes (or fresh tomatoes)","1/2 cup water","2 cups frozen spinach (coarsely chopped)","1/4 cup Kalamata olives (or other Greek olives pitted and coarsely chopped)"]}],"directions":[{"name":null,"steps":["Put the skillet on the stove over high heat. When it is hot, add 1 1/2 teaspoons oil.","Add fish. Cook about 5 minutes per side, until deeply browned. Remove the fish to the plate and cover.","Reheat the skillet to medium heat. Add the remaining 1 1/2 teaspoons oil, onion, and garlic. Cook about 7 minutes. Add tomatoes and water. Cook about 10 minutes, until the mixture thickens and turns from bright red to an orange color.","Return fish to skillet with the tomato mixture. Cover with spinach and sprinkle with olives. Cover skillet. Cook about 2 minutes over low heat until the spinach is steamed. Serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"4 ounces","calories":"179.85 kcal","carbohydrateContent":"13.73 g","cholesterolContent":"47.73 mg","fiberContent":"7.08 g","proteinContent":"21.82 g","sodiumContent":"285.62 mg","sugarContent":"5.19 g","fatContent":"5.90 g","saturatedFatContent":"0.94 g"},"notes":"Try this recipe with another white fish, such as tilapia, haddock, or catfish.\nFresh tomatoes can be used instead of canned.\nSee how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"fish-tacos","source_url":"https://www.myplate.gov/recipes/fish-tacos","name":"Fish Tacos","description":"Fish tacos are a fun way to add fish to your meal. Green cabbage gives some crunch and extra nutrients.","ingredients":[{"name":null,"items":["1 red onion, chopped","1/2 cup cilantro, chopped","1 cup green cabbage, sliced and chopped","4 (4-ounces each) tilapia fillets (or any white fish)","1 teaspoon chili powder (more or less to taste)","8 small corn tortillas"]}],"directions":[{"name":null,"steps":["Clean and chop onion, cilantro, and cabbage. Mix in a bowl and set aside.","Coat the baking sheet with cooking spray. Lightly sprinkle fish fillets with chili powder and place on the baking pan.","Place in the oven about 6 inches from the broiler and cook for approximately 3 to 4 minutes, or until fish is fully cooked. You will know the fish is done when it \"flakes\" or pulls apart easily when separated with a fork.","Lightly fry tortillas on an oiled griddle or skillet, or heat tortillas in the microwave oven for just a few seconds until softened and hot.","Fill tortilla with fish, cabbage, onion, and cilantro and fold in half. Serve with salsa and citrus slices, if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 tacos","calories":"204.46 kcal","carbohydrateContent":"20.90 g","cholesterolContent":"46.28 mg","fiberContent":"3.75 g","proteinContent":"24.03 g","sodiumContent":"86.36 mg","sugarContent":"3.25 g","fatContent":"3.34 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Oklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"five-happiness-fried-noodles","source_url":"https://www.myplate.gov/recipes/five-happiness-fried-noodles","name":"Five Happiness Fried Noodles","description":"Enjoy carrots, bamboo shoots, mushrooms, bean sprouts, and green onions with fried noodles and a simple sauce.","ingredients":[{"name":null,"items":["10 cups water","1 pound egg noodles","1 tablespoon olive oil (or cooking oil of your choice, divided)","3 cups bean sprouts","1 cup bamboo shoots (julienned sliced thinly in strips)","1/2 cup carrots (shredded)","2 dried shiitake mushrooms (or about 1/2 cup, soaked, stems removed, and julienned)","2 green onions","1/2 teaspoon salt","1 teaspoon sugar","1 tablespoon reduced-sodium soy sauce"]}],"directions":[{"name":null,"steps":["In a large pot on high heat, bring 10 cups of water to boil. Cook noodles in boiling water until tender or “al dente,” approximately 5 to 7 minutes; drain and set aside.","Heat a non-stick wok or pan over high heat. Add 1/2 tablespoon oil, swirling to coat the pan, add noodles and pan-fry until noodles are golden, about 7 to 10 minutes. Remove noodles from wok.","Add remaining 1/2 tablespoon oil to wok, add vegetables, and stir-fry until just cooked, about 5 to 7 minutes.","Return noodles to the wok, add salt, sugar and soy sauce.","Stir to combine and serve."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cup","calories":"385.82 kcal","carbohydrateContent":"66.39 g","cholesterolContent":"69.34 mg","fiberContent":"4.63 g","proteinContent":"13.41 g","sodiumContent":"396.06 mg","sugarContent":"4.82 g","fatContent":"7.94 g","saturatedFatContent":"1.49 g"},"notes":null,"contributor":"EatFresh\nCalifornia Department of Social Services"},
{"slug":"flavored-water","source_url":"https://www.myplate.gov/recipes/flavored-water","name":"Flavored Water","description":"Try this refreshing flavor combination of watermelon and lime or create your own!","ingredients":[{"name":null,"items":["1 lime","1 cup watermelon","8 cups cold water (or less, depending on the amount of fruit added)"]}],"directions":[{"name":null,"steps":["Wash all produce.","Slice limes.","Cut watermelon into 1-inch cubes.","Add lime and watermelon, plus enough cold water to a fill a 2-quart pitcher. Chill overnight in the refrigerator for the most flavor, and store in the refrigerator until ready to drink. The fruit will stay fresh in the water for up to 48 hours after being prepared.","After you drink the water, you can eat the fruit or blend it into a smoothie!"]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"8.25 kcal","carbohydrateContent":"2.32 g","cholesterolContent":"0.00 mg","fiberContent":"0.31 g","proteinContent":"0.18 g","sodiumContent":"9.96 mg","sugarContent":"1.34 g","fatContent":"0.05 g","saturatedFatContent":"0.01 g"},"notes":"Try these refreshing flavor combinations, or create your own!\nWatermelon Lime\n1 cup watermelon\n1 lime\n5 mint leaves (optional)\nCucumber Lemon (or Lime)\n1/2 cucumber\n1 lemon or lime\nPineapple Grape\n1 cup canned diced pineapple\npineapple juice from can\n1 cup grapes\nBerry Kiwifruit (or Orange)\n10 strawberries or blackberries\n1 kiwifruit or 1 orange\nTips for releasing flavors of the produce:\nWatermelon: Cut into small pieces (1 to 2 inches).\nCitrus fruit (oranges, lemons, limes): Remove rinds, and slice into thin pieces.\nCucumber: Slice into thin pieces.\nMint: Tear leaves.\nGrapes: Slice in half.\nBerries: Remove top (strawberries only). Slice into small pieces.\nKiwifruit: Remove peel, and slice into thin pieces.\nCost and Nutrition analysis provided for Watermelon Lime Water.","contributor":"Eating Smart, Being Active\nColorado State University"},
{"slug":"flavorful-fried-rice","source_url":"https://www.myplate.gov/recipes/flavorful-fried-rice","name":"Fried Rice","description":"Add some protein and grains to your dinner with this yummy rice dish. Use brown rice for extra fiber.","ingredients":[{"name":null,"items":["2 tablespoons canola oil (or cooking oil of your choice)","1 cup white rice, uncooked","3 tablespoons onion, minced","1/2 cup carrot (chopped or grated)","2 cups water","4 whole eggs (beaten)","4 egg whites (beaten)","1/4 cup fat-free milk","1/2 cup peas","2 tablespoons reduced-sodium soy sauce"]}],"directions":[{"name":null,"steps":["In a large frying pan over medium heat, cook rice, minced onion, and carrots in oil, stirring often until lightly browned.","Slowly add water. Reduce heat, cover and simmer until liquid is absorbed and rice is tender, about 20 minutes.","Beat eggs and egg whites in a bowl. Stir in milk, peas, and soy sauce. Pour over hot rice mixture in fry pan.","Cook on medium heat. As mixture begins to thicken, gently draw a spatula across bottom and sides of pan. This allows egg mixture to cook. Continue until eggs are firm."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"246.60 kcal","carbohydrateContent":"31.52 g","cholesterolContent":"137.31 mg","fiberContent":"1.46 g","proteinContent":"10.67 g","sodiumContent":"301.37 mg","sugarContent":"2.16 g","fatContent":"8.36 g","saturatedFatContent":"1.47 g"},"notes":null,"contributor":"Adapted from Flavorful Fried Rice, University of Wisconsin Cooperative Extension Service\nFamily Living Program"},
{"slug":"flour-tortillas","source_url":"https://www.myplate.gov/recipes/flour-tortillas","name":"Flour Tortillas","description":"Skip the store-bought tortillas and make your own with this simple recipe. Swap out some of the all-purpose flour with whole wheat flour, a whole grain.","ingredients":[{"name":null,"items":["2 cups all-purpose flour (or 1 1/2 cup all purpose flour and 1/2 cup whole wheat flour)","1 teaspoon baking powder","1/2 teaspoon salt","2 tablespoons vegetable oil","1/2 cup water (warm, 105 to 110 °F)"]}],"directions":[{"name":null,"steps":["In a large bowl, combine flour, baking powder, and salt.","Add oil and mix until crumbly.","Start with 1/2 cup of water and add 1 tablespoon at a time until mixture forms a loose crumbly ball.","Turn onto a lightly floured surface; knead 6 to 8 times or until smooth.","Divide into 10 balls. Roll each piece into an 8 inch circle.","Heat a 12 inch dry skillet over medium-high heat. Place one tortilla at a time into skillet and cook until light brown spots appear on bottom. Turn over and cook on other side until lightly browned."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 tortilla","calories":"116.44 kcal","carbohydrateContent":"19.20 g","cholesterolContent":"0.00 mg","fiberContent":"0.68 g","proteinContent":"2.58 g","sodiumContent":"167.78 mg","sugarContent":"0.07 g","fatContent":"3.05 g","saturatedFatContent":"0.42 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Programs"},
{"slug":"food-group-funny-face","source_url":"https://www.myplate.gov/recipes/food-group-funny-face","name":"Food Group Funny Face","description":"Let your kids create their own funny face using ingredients from all five MyPlate food groups.","ingredients":[{"name":null,"items":["1 tablespoon peanut butter","1 graham cracker (large, or use whole grain or saltine crackers)","1 tablespoon cheddar cheese (shredded)","3 raisins","2 peas (large green)","1/2 grape (cut in half)"]}],"directions":[{"name":null,"steps":["Spread peanut butter on a cracker in the shape of a face.","Sprinkle grated cheese at top for hair.","Place raisins on cracker for mouth.","Use peas for eyes and 1/2 grape for nose."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 Funny Face Cracker","calories":"522.64 kcal","carbohydrateContent":"81.58 g","cholesterolContent":"7.06 mg","fiberContent":"19.19 g","proteinContent":"22.98 g","sodiumContent":"214.60 mg","sugarContent":"41.97 g","fatContent":"13.41 g","saturatedFatContent":"3.45 g"},"notes":"This snack is intended for children over age two. Do not serve to younger children who may choke.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"four-layer-casserole","source_url":"https://www.myplate.gov/recipes/four-layer-casserole","name":"Four Layer Casserole","description":"This dish can be baked in the oven or if you are short on time, pop it into the microwave. Use your favorite frozen or canned vegetables.","ingredients":[{"name":null,"items":["1 pound ground beef, 85% lean","4 potatoes","1 package frozen mixed vegetables, 10 ounces (or low-sodium canned mixed vegetables)","1/4 cup cheese, low-fat shredded (cheddar or colby jack)","1/4 cup milk, 1%","salt and pepper (optional, to taste)"]}],"directions":[{"name":null,"steps":["Cook ground beef in frying pan until brown. Rinse in warm water and drain to remove excess fat.","Scrub potatoes and cut into slices without peeling.","Place potatoes in a large baking or casserole dish. Top with vegetables, ground beef, and cheese.","Pour milk over the casserole. Add salt and pepper as desired.","Cover with a lid or foil. Bake at 350 °F for 1 hour or microwave in non-metal baking or casserole dish for 19 to 23 minutes on high."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/6 of recipe"],"calories":"275.02 kcal","carbohydrateContent":"31.08 g","cholesterolContent":"46.63 mg","fiberContent":"4.63 g","proteinContent":"18.33 g","sodiumContent":"102.13 mg","sugarContent":"3.35 g","fatContent":"8.38 g","saturatedFatContent":"3.40 g"},"notes":"Try other favorite vegetables in place of mixed vegetables such as carrots, broccoli, cauliflower, green beans, peas, or corn.\nCheddar cheese used for costing and nutrition analysis.","contributor":"Spend Smart. Eat Smart.\nIowa State University Extension"},
{"slug":"french-salad-dressing","source_url":"https://www.myplate.gov/recipes/french-salad-dressing","name":"French Salad Dressing","description":"This sweet and tangy dressing can be used as a salad dressing or as a veggie dip.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of choice)","1/4 cup ketchup","1 teaspoon sugar","1 tablespoon vinegar","1/2 teaspoon paprika","1 tablespoon onion, grated","1 tablespoon lemon juice"]}],"directions":[{"name":null,"steps":["Put all the ingredients in a jar or bottle with a lid.","Put on the lid. Shake well.","Chill in the fridge for at least 1 hour before serving."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"71.16 kcal","carbohydrateContent":"5.02 g","cholesterolContent":"0.00 mg","fiberContent":"0.18 g","proteinContent":"0.21 g","sodiumContent":"127.29 mg","sugarContent":"3.96 g","fatContent":"5.68 g","saturatedFatContent":"0.78 g"},"notes":"Try this dressing on cut vegetables or salad. After serving, keep any leftover dressing in the fridge.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"french-spinach-frittata","source_url":"https://www.myplate.gov/recipes/french-spinach-frittata","name":"French Spinach Frittata","description":"Scallions, spinach, and feta cheese are added to this classic oven-baked egg dish. Try substituting cheddar, Swiss, or ricotta cheese for variety.","ingredients":[{"name":null,"items":["8 eggs","1/2 teaspoon salt","1/2 teaspoon black pepper","2 cups spinach, finely chopped (if frozen spinach is used, thaw and squeeze out excess liquid)","4 scallions (white and green parts chopped into 1/4 inch-pieces)","1/4 cup crumbled feta cheese","2 teaspoons vegetable oil"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F.","Put the eggs, salt, and pepper in the mixing bowl and stir with a fork until well combined.","Add scallions, spinach, and feta cheese and mix well.","Put an 8-inch ovenproof skillet on the stove over medium heat and when hot, add oil.","Pour the egg mixture into the skillet and carefully transfer to the oven. Bake until the eggs are set and the top is golden, about 30 minutes.","Serve right away or cover and refrigerate overnight."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"131.70 kcal","carbohydrateContent":"1.94 g","cholesterolContent":"279.56 mg","fiberContent":"0.43 g","proteinContent":"9.58 g","sodiumContent":"363.72 mg","sugarContent":"0.40 g","fatContent":"9.61 g","saturatedFatContent":"3.19 g"},"notes":"Cheddar, Swiss, or ricotta cheese can be used instead of feta.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"fresh-fruit-cinnamon-yogurt-dip","source_url":"https://www.myplate.gov/recipes/fresh-fruit-cinnamon-yogurt-dip","name":"Fresh Fruit with Cinnamon Yogurt Dip","description":"Vanilla yogurt with cinnamon makes a delicious dip for your favorite fruits. Use low-fat yogurt for an even healthier option.","ingredients":[{"name":null,"items":["1 apple","1 banana","1 orange","1/4 cup orange juice","1 cup vanilla yogurt, low-fat","1/2 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Core and slice the apple.","Slice banana into thin circles.","Peel the orange and break it into sections.","Pour the orange juice into a small bowl.","Dip the fruit pieces into the orange juice to prevent browning.","Arrange on a plate.","Mix the yogurt and cinnamon in a small bowl.","Put the bowl of yogurt and cinnamon next to the fruit. Use it as a dip for the fruit."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"133.11 kcal","carbohydrateContent":"26.92 g","cholesterolContent":"3.68 mg","fiberContent":"2.65 g","proteinContent":"3.93 g","sodiumContent":"43.22 mg","sugarContent":"21.75 g","fatContent":"1.20 g","saturatedFatContent":"0.65 g"},"notes":"Try making this with other favorite fruits.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"fresh-salsa","source_url":"https://www.myplate.gov/recipes/fresh-salsa","name":"Fresh Salsa","description":"Fresh tomatoes with jalapeno peppers, cilantro, onions, and lime make this dish a light and easy summer time treat. Serve it with chicken and rice for a comp...","ingredients":[{"name":null,"items":["2 medium tomatoes, chopped","1/2 onion, chopped","3 jalapeno chiles, finely chopped, seeded if desired","1/4 cup cilantro, chopped","1/4 teaspoon salt","1 lime, juiced"]}],"directions":[{"name":null,"steps":["In a medium bowl, mix all ingredients.","Serve or store salsa in refrigerator for up to three days in a covered plastic or glass container."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup prepared salsa","calories":"26.34 kcal","carbohydrateContent":"5.91 g","cholesterolContent":"0.00 mg","fiberContent":"1.38 g","proteinContent":"0.90 g","sodiumContent":"151.58 mg","sugarContent":"3.44 g","fatContent":"0.27 g","saturatedFatContent":"0.04 g"},"notes":null,"contributor":"Healthy Latino Recipes Made with Love\nCalifornia Department of Health Services\nCalifornia Latino 5-A-Day Campaign"},
{"slug":"fresh-tomato-salsa","source_url":"https://www.myplate.gov/recipes/fresh-tomato-salsa","name":"Fresh Tomato Salsa","description":"Fresh salsa is a refreshing, cool addition to a meal or snack. Try something new by adding it to salads, baked fish, and tacos.","ingredients":[{"name":null,"items":["1 cup tomatoes, finely chopped (or 1/2 can, about 8 ounces, low-sodium diced tomatoes)","1/2 cup apple, peeled and finely chopped","1/4 cup onion, finely chopped","2 tablespoons lime or lemon juice","1 teaspoon garlic, finely chopped","1/2 teaspoon vegetable oil","1/4 teaspoon salt","1 teaspoon fresh parsley or cilantro, chopped (optional)","1 tablespoon cayenne pepper or jalapeño chilies, chopped (optional)"]}],"directions":[{"name":null,"steps":["In a medium-sized bowl, combine tomato, apple, onion, and lime juice (or lemon juice). Mix well.","Add garlic, vegetable oil, and salt to bowl. If using parsley, cilantro, cayenne pepper, or jalapeño chilies, add them too. Mix well.","Cover bowl and refrigerate for 15 minutes. Serve cold."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup","calories":"20.87 kcal","carbohydrateContent":"3.99 g","cholesterolContent":"0.00 mg","fiberContent":"0.74 g","proteinContent":"0.40 g","sodiumContent":"99.87 mg","sugarContent":"2.53 g","fatContent":"0.51 g","saturatedFatContent":"0.07 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"fresh-tomato-sauce","source_url":"https://www.myplate.gov/recipes/fresh-tomato-sauce","name":"Fresh Tomato Sauce","description":"Fresh vegetables are cooked with herbs to create a flavorful and savory sauce for pasta, and other dishes, too!","ingredients":[{"name":null,"items":["8 ripe tomatoes","1 tablespoon vegetable oil (or cooking oil of choice)","1/2 cup onion (chopped)","1/2 cup green pepper (chopped)","1/4 cup carrot (thinly sliced, or shredded)","2 teaspoons garlic, minced (or 1/2 teaspoon garlic powder)","1/2 teaspoon dried oregano","1 teaspoon dried basil","black pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Wash the ripe tomatoes. Cut out stem ends. Chop into small pieces and set aside in a large bowl.","In a large pan, heat the oil over medium high heat. Add onion, green pepper, carrots and garlic. Stir-fry until tender, about three minutes.","Add seasonings and tomatoes. Bring to a gentle boil.","Lower heat and simmer gently, uncovered, until tomatoes turn to a sauce, about 40 minutes. Serve over freshly cooked pasta."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"60.51 kcal","carbohydrateContent":"8.88 g","cholesterolContent":"0.00 mg","fiberContent":"1.69 g","proteinContent":"1.83 g","sodiumContent":"20.17 mg","sugarContent":"4.73 g","fatContent":"2.56 g","saturatedFatContent":"0.37 g"},"notes":null,"contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"fried-rice-0","source_url":"https://www.myplate.gov/recipes/fried-rice-0","name":"Fried Rice","description":"This delicious rice dish is packed with protein, veggies, and whole grain goodness.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","2 eggs (beaten)","3 1/2 cups brown rice, cooked (or white rice)","1 cup chicken breast, ham or pork, cooked (and chopped)","1 cup mixed vegetables, cooked (and chopped)","2 green onions (sliced)","soy sauce or hot sauce (optional, to taste)"]}],"directions":[{"name":null,"steps":["Heat pan. Add 1 teaspoon of oil. Add eggs and scramble.","Remove cooked eggs and set aside.","Add the rest of oil (2 teaspoons) to pan. Stir fry rice, breaking up lumps by pressing rice against pan.","Add cooked meat and/or vegetables. Stir fry until heated.","Add green onions, reserved eggs and sauce to taste. Serve hot.","Cover and refrigerate leftovers within 2 hours."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"339.54"},"notes":null,"contributor":"Food Hero, Adapted from Easy Fried Rice\nOregon State University Cooperative Extension Service"},
{"slug":"fried-rice-chicken-vegetables","source_url":"https://www.myplate.gov/recipes/fried-rice-chicken-vegetables","name":"Fried Rice with Chicken and Vegetables","description":"Low-sodium soy sauce and garlic powder create a delicious flavor for this brown rice, vegetable, and chicken dish.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (Or cooking oil of your choice)","3 cups cooked brown rice","1 carrot (cut into 1/4-inch slices)","1/2 bell pepper (chopped)","1/2 cup chopped onion","1/2 cup chopped broccoli","2 tablespoons low-sodium soy sauce","1/2 teaspoon black pepper","1 teaspoon garlic powder","2 medium eggs (beaten)","3/4 cup cooked bite-size pieces of chicken"]}],"directions":[{"name":null,"steps":["Heat oil in a large skillet over medium heat.","Add rice and stir for 5 minutes.","Stir in carrot, bell pepper, onion, broccoli, soy sauce, black pepper, and garlic powder. Cook until vegetables are tender.","Remove mixture from pan.","Pour eggs into pan and scramble.","Put vegetable mix and rice back in the pan and mix with scrambled eggs.","Add chicken and cook until hot.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/6 of recipe"],"calories":"233.10 kcal","carbohydrateContent":"29.15 g","cholesterolContent":"85.17 mg","fiberContent":"2.50 g","proteinContent":"10.99 g","sodiumContent":"236.25 mg","sugarContent":"1.74 g","fatContent":"7.97 g","saturatedFatContent":"1.58 g"},"notes":null,"contributor":"Adapted from Fried Rice, Colorado State University and University of California at Davis. Eating Smart Being Active Recipes."},
{"slug":"fried-rice","source_url":"https://www.myplate.gov/recipes/fried-rice","name":"Fried Rice","description":"This delicious rice dish is packed with protein, veggies, and whole grain goodness.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil, divided (or cooking oil of choice)","2 eggs, beaten","3 1/2 cups cooked brown rice","1 cup cooked chopped chicken breast (could also use cooked ham or pork)","1 cup frozen mixed vegetables","2 green onions","soy sauce or hot sauce (optional, to taste)"]}],"directions":[{"name":null,"steps":["Heat pan. Add 1 teaspoon of oil. Add eggs and scramble.","Remove cooked eggs and set aside.","Add the rest of oil (2 teaspoons) and rice to pan. Stir fry rice, breaking up lumps by pressing rice against pan.","Add cooked meat and vegetables. Stir fry until heated.","Add green onions, reserved eggs and sauce to taste. Serve hot.","Cover and refrigerate leftovers within 2 hours."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"363.00 kcal","carbohydrateContent":"50.22 g","cholesterolContent":"136.09 mg","fiberContent":"4.92 g","proteinContent":"19.48 g","sodiumContent":"72.85 mg","sugarContent":"2.04 g","fatContent":"8.92 g","saturatedFatContent":"2.00 g"},"notes":"Chicken breast was used to calculate the nutritional value of this recipe.","contributor":"Food Hero, Adapted from Easy Fried Rice\nOregon State University Cooperative Extension Service"},
{"slug":"frosted-cake","source_url":"https://www.myplate.gov/recipes/frosted-cake","name":"Frosted Cake","description":"Vanilla and orange peel are the secret to making this delicious cake with chocolate frosting. Serve at your next special occasion for a tasty treat.","ingredients":[{"name":null,"items":["2 1/4 cups cake flour","2 1/4 teaspoons baking powder","4 tablespoons margarine (soft tub)","1 1/4 cups sugar","4 eggs","1 teaspoon vanilla extract","1 tablespoon orange peel","3/4 cup skim/fat free milk","3 s sprays of cooking spray (for cake pan)"]},{"name":"Icing","items":["2 tablespoons skim/fat free milk","3 ounces low-fat cream cheese","6 tablespoons unsweetened cocoa powder","2 cups confectioners sugar (sifted)","1/2 teaspoon vanilla extract"]}],"directions":[{"name":"Cake","steps":["Preheat the oven to 325 °F.","Grease with small amount of cooking oil or use non-stick cooking oil spray on a 10-inch round pan (at least 2 1/2 inches high). Powder pan with flour. Tap out excess flour.","Sift together flour and baking powder.","In a separate bowl, beat together margarine and sugar until soft and creamy.","Beat in eggs, vanilla, and orange peel.","Gradually add the flour mixture alternating with milk, beginning and ending with flour.","Pour the mixture into the pan. Bake for 40-45 minutes or until done. Let cake cool for 5-10 minutes before removing from the pan. Let cool completely before icing."]},{"name":"Icing","steps":["Cream together cream cheese and milk until smooth. Add cocoa. Blend well.","Slowly add sugar until icing is smooth. Mix in vanilla.","Smooth icing over top and sides of cooled cake."]}],"yield":"16 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 slice","calories":"249.06 kcal","carbohydrateContent":"48.22 g","cholesterolContent":"54.68 mg","fiberContent":"1.06 g","proteinContent":"4.38 g","sodiumContent":"134.15 mg","sugarContent":"31.41 g","fatContent":"4.68 g","saturatedFatContent":"1.49 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"frozen-banana-pops","source_url":"https://www.myplate.gov/recipes/frozen-banana-pops","name":"Frozen Banana Pops","description":"Engage your kids in a fun activity by having them slice and dip ripe bananas in orange or lemon juice and place the bananas in the freezer for several hours ...","ingredients":[{"name":null,"items":["2 bananas, ripe","1/8 cup orange juice or lemon juice (2 Tablespoons)","Other Necessary Tools/Equipment","craft sticks","foil"]}],"directions":[{"name":null,"steps":["Peel each banana and cut in half (width-wise).","Insert craft stick into bottom of each banana half. Dip each banana half into juice.","Wrap in foil and freeze for two or more hours."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 banana pop","calories":"64.90 kcal","carbohydrateContent":"15.11 g","cholesterolContent":"0.00 mg","fiberContent":"1.10 g","proteinContent":"0.53 g","sodiumContent":"0.00 mg","sugarContent":"10.61 g","fatContent":"0.21 g","saturatedFatContent":"0.07 g"},"notes":"Optional Toppings: Dip in chocolate, then roll in chopped nuts, crushed cereal, shredded coconut, or sprinkles.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"frozen-fruit-cups","source_url":"https://www.myplate.gov/recipes/frozen-fruit-cups","name":"Frozen Fruit Cups","description":"Use your own combination of fresh, frozen or canned fruits to create this yummy dessert or snack. It''s perfect for a summer day.","ingredients":[{"name":null,"items":["3 medium bananas","24 ounces non-fat strawberry yogurt","1 cup strawberries, frozen, unsweetened (thawed and undrained)","1 cup crushed pineapple, juice packed (undrained, canned)"]}],"directions":[{"name":null,"steps":["Line 18 muffin-tin cups with paper baking cups.","Dice or mash bananas and place in a large mixing bowl.","Stir in remaining ingredients.","Spoon into muffin-tin cups and freeze at least 3 hours or until firm. Remove frozen cups and store in a plastic bag in freezer.","Before serving, remove paper cups and let stand 10 minutes."]}],"yield":"18 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 fruit cup","1/18 of recipe"],"calories":"61.08 kcal","carbohydrateContent":"12.84 g","cholesterolContent":"0.75 mg","fiberContent":"0.68 g","proteinContent":"2.17 g","sodiumContent":"27.83 mg","sugarContent":"9.98 g","fatContent":"0.15 g","saturatedFatContent":"0.06 g"},"notes":"Watch how to make this kid-friendly recipe on YouTube.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"frozen-fruit-pops","source_url":"https://www.myplate.gov/recipes/frozen-fruit-pops","name":"Frozen Fruit Pops","description":"These frozen fruit pops contain fruit, juice, and low-fat yogurt to create a refreshing treat on a summer day.","ingredients":[{"name":null,"items":["1 cup crushed pineapple, canned, juiced packed","1 cup yogurt, low-fat fruit (8 ounces)","6 us fluid ounces orange juice, frozen concentrate (thawed)"]}],"directions":[{"name":null,"steps":["Mix the ingredients in a medium-size bowl. Divide into 4 paper cups.","Freeze until slushy - about 60 minutes. Insert a wooden stick half way through the center of each fruit pop.","Freeze until hard or at least 4 hours. Peel away the paper cup before you eat the fruit pop."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 fruit pop","1/4 of recipe"],"calories":"163.83 kcal","carbohydrateContent":"35.36 g","cholesterolContent":"3.06 mg","fiberContent":"1.09 g","proteinContent":"4.42 g","sodiumContent":"46.04 mg","sugarContent":"30.31 g","fatContent":"1.05 g","saturatedFatContent":"0.58 g"},"notes":"You can mix ingredients and freeze in ice cube tray instead of cups, making great \"ice cubes\" in fruit juice. Try other fruits or juice concentrates for variety.","contributor":"The Power of Choice\nUSDA Food and Nutrition Service and US Department of Health and Human Services Food and Drug Administration (FDA)"},
{"slug":"frozen-pear-pops","source_url":"https://www.myplate.gov/recipes/frozen-pear-pops","name":"Frozen Pear Pops","description":"These frozen pear pops are a refreshing treat! Sweet pears mixed with orange juice and yogurt is a snack that is sure to please.","ingredients":[{"name":null,"items":["1 cup canned pears, drained","1 cup low fat yogurt","6 ounces frozen orange juice concentrate, thawed","ice cube tray or small paper cups","straws or popsicle sticks"]}],"directions":[{"name":null,"steps":["Cut canned pears into small pieces.","Add yogurt and orange juice to cut pears and mix well to combine.","Divide into 8 ice cubes squares (or 4 small paper cups).","Place in cut straws or popsicle sticks.","Freeze and enjoy!"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 yogurt pop cubes","calories":"146.07 kcal","carbohydrateContent":"30.55 g","cholesterolContent":"3.68 mg","fiberContent":"1.46 g","proteinContent":"4.65 g","sodiumContent":"49.72 mg","sugarContent":"26.48 g","fatContent":"1.13 g","saturatedFatContent":"0.65 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"fruit-and-peanut-butter-dip","source_url":"https://www.myplate.gov/recipes/fruit-and-peanut-butter-dip","name":"Fruit and Peanut Butter Dip","description":"Use yogurt, peanut butter, and vanilla to create a dip for your favorite fruits.","ingredients":[{"name":null,"items":["1 cup apple slices","1 cup banana slices","1 cup pear slices","1 cup grapes","1 cup strawberries","1 cup melon slices","1/2 cup yogurt, non-fat plain","1/2 teaspoon vanilla","1/3 cup peanut butter"]}],"directions":[{"name":null,"steps":["Prepare fruit by washing and slicing if necessary.","Arrange fruit on a plate around a small bowl.","To make dip, combine yogurt, vanilla, and peanut butter in a small bowl.","Mix well.","Chill dip in refrigerator until ready to serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup fruit","2 Tablespoons dip"],"calories":"186.96 kcal","carbohydrateContent":"25.46 g","cholesterolContent":"0.41 mg","fiberContent":"3.07 g","proteinContent":"5.12 g","sodiumContent":"84.43 mg","sugarContent":"18.90 g","fatContent":"7.50 g","saturatedFatContent":"1.51 g"},"notes":"Can use six cups of any washed fruit. Be creative! Spread dip on a tortilla, add banana, and roll up.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"fruit-and-yogurt-breakfast-shake","source_url":"https://www.myplate.gov/recipes/fruit-and-yogurt-breakfast-shake","name":"Fruit and Yogurt Breakfast Shake","description":"Shake up your day with this quick and easy breakfast. Make this recipe with any of your favorite fruits, especially when they are in season!","ingredients":[{"name":null,"items":["1 banana, medium, very ripe, (peeled)","3/4 cup pineapple juice","1/2 cup yogurt, low-fat vanilla","1/2 cup strawberries (remove stems and rinse)"]}],"directions":[{"name":null,"steps":["Blend banana with pineapple juice, yogurt, and strawberries in a blender.","Blend until smooth.","Divide shake between 2 glasses and serve immediately."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"168.24 kcal","carbohydrateContent":"35.17 g","cholesterolContent":"3.68 mg","fiberContent":"1.93 g","proteinContent":"4.16 g","sodiumContent":"47.26 mg","sugarContent":"27.25 g","fatContent":"1.30 g","saturatedFatContent":"0.67 g"},"notes":null,"contributor":"Recipes to Grow On\nUniversity of Illinois Extension Service"},
{"slug":"fruit-cole-slaw","source_url":"https://www.myplate.gov/recipes/fruit-cole-slaw","name":"Fruit Cole Slaw","description":"Honey and vinegar give a sweet and sour twist to this fruit and cabbage cole slaw.","ingredients":[{"name":null,"items":["1/2 cabbage head (shredded - 2 quarts)","1 can fruit cocktail (15 ounces, juice packed, drained)","1 cup yogurt, non-fat plain","1 lemon","1/2 cup honey","1/4 cup vinegar","1 banana (sliced)","1/2 teaspoon salt","1/8 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Shred cabbage.","Combine all ingredients in a large bowl."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"181.03 kcal","carbohydrateContent":"43.68 g","cholesterolContent":"0.82 mg","fiberContent":"2.96 g","proteinContent":"3.87 g","sodiumContent":"248.28 mg","sugarContent":"38.99 g","fatContent":"0.29 g","saturatedFatContent":"0.11 g"},"notes":"* Children under the age of one should not consume honey.","contributor":"Making It Fit: Piecing Together Your Food Needs\nUniversity of Vermont Extension"},
{"slug":"fruit-compote","source_url":"https://www.myplate.gov/recipes/fruit-compote","name":"Fruit Compote","description":"This compote has a thick and sweet sauce that is mixed with fruit for a delicious dessert.","ingredients":[{"name":null,"items":["1 cup pineapple chunks (8 ounce can, juice packed)","1 1/2 cups orange juice","1 tablespoon cornstarch","1 medium banana (peeled and sliced)","1 pear (sliced in cubes)","2 peaches (sliced in cubes)"]}],"directions":[{"name":null,"steps":["Drain the juice from the canned pineapple into a small saucepan.","Stir in orange juice and cornstarch. Blend until smooth.","Bring to a boil over medium heat, stirring constantly.","Let the juice mix cool to room temperature.","While the juice mix is cooling, peel and slice the banana. Wash the pear and peaches and cut them into cubes.","Pour the cooled juice mix into a large bowl. Add the pieces of pineapple, banana, pear, and peaches. Stir together."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared compote","1/5 of recipe"],"calories":"137.87 kcal","carbohydrateContent":"32.13 g","cholesterolContent":"0.00 mg","fiberContent":"3.07 g","proteinContent":"1.69 g","sodiumContent":"10.98 mg","sugarContent":"24.07 g","fatContent":"0.61 g","saturatedFatContent":"0.06 g"},"notes":"You can serve this compote in serving dishes, or over frozen yogurt or waffles.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"fruit-crisp","source_url":"https://www.myplate.gov/recipes/fruit-crisp","name":"Fruit Crisp","description":"Slightly sweetened apples topped with a mixture of flour, oats and brown sugar crumble baked until tender and golden brown. Substitute berries, peaches, or a...","ingredients":[{"name":"For the filling","items":["6 cups apples (peeled and diced)","1 tablespoon white whole wheat flour","3 tablespoons white sugar"]},{"name":"For the topping","items":["3/4 cup rolled oats","3 tablespoons white sugar","3/4 cup white whole wheat flour","1/2 teaspoon salt","1/4 cup brown sugar","1/3 cup canola oil (or unsalted butter, melted)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F. Lightly grease a baking dish with butter or oil.","Combine the apples, flour, and white sugar to make the filling.","To prepare the topping, mix the oats, whole wheat flour, white sugar, brown sugar, and salt. Add the oil (or butter) and stir into the dry ingredients.","Fill the baking pan with the fruit mixture and then cover with the crumble topping.","Transfer to the oven and bake until the fruit is tender and the topping is golden, about 45 minutes.","Serve right away or cover and refrigerate up to 2 days."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"265.02 kcal","carbohydrateContent":"41.51 g","cholesterolContent":"0.00 mg","fiberContent":"4.03 g","proteinContent":"2.76 g","sodiumContent":"149.60 mg","sugarContent":"25.22 g","fatContent":"10.20 g","saturatedFatContent":"0.77 g"},"notes":"Frozen unsweetened berries, like blueberries, can be used instead of apples.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"fruit-dip","source_url":"https://www.myplate.gov/recipes/fruit-dip","name":"Fruit Dip","description":"Lime juice and orange concentrate gives this yogurt dip a tangy and sweet flavor. Serve it with your favorite fruits.","ingredients":[{"name":null,"items":["1 cup yogurt, low-fat vanilla (8 oz)","1 us fluid ounce orange juice, 100% juice, frozen concentrate (thawed)","1 tablespoon lime juice","1 1/2 teaspoons brown sugar, unpacked (1/2 tablespoon)","2 red apples (cored and sliced)","1 pear (cored and sliced)","1 peach (pitted and sliced)"]}],"directions":[{"name":null,"steps":["In a small bowl, combine yogurt, orange juice concentrate, lime juice, and brown sugar.","Mix well.","Place bowl containing dip on a large plate and surround with fruit."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"168.08 kcal","carbohydrateContent":"36.04 g","cholesterolContent":"3.68 mg","fiberContent":"4.16 g","proteinContent":"4.03 g","sodiumContent":"48.90 mg","sugarContent":"29.47 g","fatContent":"1.27 g","saturatedFatContent":"0.65 g"},"notes":null,"contributor":"Discover the Secret to Healthy Living\nCalifornia Department of Health Services\nCalifornia Children’s 5-A-Day Power Play Campaign"},
{"slug":"fruit-dippers","source_url":"https://www.myplate.gov/recipes/fruit-dippers","name":"Fruit Dippers","description":"With just three ingredients and three steps, this snack recipe is perfect for kids or beginner cooks of all ages.","ingredients":[{"name":null,"items":["1/2 cup yogurt, low-fat vanilla","2 cups peanuts (chopped)","2 cups fruit (grapes, banana slices, apple wedges, strawberries)"]}],"directions":[{"name":null,"steps":["Combine yogurt and peanuts. Mix with a spoon.","Place a toothpick in the center of each fruit.","Dip fruit into the yogurt peanut mixture."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"502.38 kcal","carbohydrateContent":"24.45 g","cholesterolContent":"1.84 mg","fiberContent":"7.99 g","proteinContent":"22.46 g","sodiumContent":"258.93 mg","sugarContent":"13.86 g","fatContent":"38.94 g","saturatedFatContent":"6.66 g"},"notes":null,"contributor":"The Power of Choice\nUSDA Food and Nutrition Service and US Department of Health and Human Services Food and Drug Administration (FDA)"},
{"slug":"fruit-feta-salad","source_url":"https://www.myplate.gov/recipes/fruit-feta-salad","name":"Fruit & Feta Salad","description":"Enjoy this super-quick and refreshing salad featuring melon and feta cheese. You can substitute any of your favorite fresh-cut fruit items, such as grapes, m...","ingredients":[{"name":"For the Vinaigrette","items":["2 tablespoons balsamic vinegar","1 1/2 tablespoons olive oil","1 dash black pepper"]},{"name":"For the Salad","items":["2 cups watermelon chunks","2 cups cantaloupe chunks","1/4 cup medium red onion, thinly sliced","6 cups fresh spinach or arugula","1/2 cup reduced-fat feta cheese crumbles","1/4 cup pine nuts"]}],"directions":[{"name":null,"steps":["Whisk together vinaigrette ingredients.","Toss with remaining ingredients and serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"221.98 kcal","carbohydrateContent":"15.84 g","cholesterolContent":"16.69 mg","fiberContent":"2.02 g","proteinContent":"6.08 g","sodiumContent":"280.15 mg","sugarContent":"11.98 g","fatContent":"15.55 g","saturatedFatContent":"3.80 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"fruit-juice-slush","source_url":"https://www.myplate.gov/recipes/fruit-juice-slush","name":"Fruit Juice Slush","description":"Blending your favorite fruit juice concentrate with ice and water will give you a quick and refreshing drink on a warm day.","ingredients":[{"name":null,"items":["12 fluid ounces 100% fruit juice concentrate","12 fluid ounces water","3 cups ice"]}],"directions":[{"name":null,"steps":["In a blender, place juice concentrate, water, and half of ice.","To prevent spillage, do not pass the top line of the blender.","Blend while gradually adding remaining ice. Serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared slush","1/6 of recipe"],"calories":"106.56 kcal","carbohydrateContent":"25.34 g","cholesterolContent":"0.00 mg","fiberContent":"0.72 g","proteinContent":"1.73 g","sodiumContent":"9.64 mg","sugarContent":"21.38 g","fatContent":"0.18 g","saturatedFatContent":"0.04 g"},"notes":"Use any flavor of juice concentrate. If slush is too thick, add more water.","contributor":"Lifeskills in Food Education, Food Skills Cookbook\nUniversity of Hawaii at Manoa Cooperative Extension\nFood Stamps Nutrition Education Program"},
{"slug":"fruit-kabob","source_url":"https://www.myplate.gov/recipes/fruit-kabob","name":"Fruit Kabob","description":"Try this creative and easy way to enjoy your favorite fruit. Make and serve these fun fruit skewers as a dessert or snack.","ingredients":[{"name":null,"items":["1 1/2 cups ripe banana slices (about 16 slices)","1 1/2 cups watermelon cubes (about 16 cubes)","1 cup clementine sections (about 16 sections)"]}],"directions":[{"name":null,"steps":["Thread the fruit onto the skewers, alternating and arranging the pieces however you like.","Serve right away."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 kabobs","calories":"47.25 kcal","carbohydrateContent":"11.23 g","cholesterolContent":"0.00 mg","fiberContent":"1.09 g","proteinContent":"0.59 g","sodiumContent":"1.19 mg","sugarContent":"8.26 g","fatContent":"0.15 g","saturatedFatContent":"0.04 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"fruit-kabobs-yogurt-dip","source_url":"https://www.myplate.gov/recipes/fruit-kabobs-yogurt-dip","name":"Fruit Kabobs with Yogurt Dip","description":"Fruit kabobs make a colorful and fun snack that kids can help prepare.","ingredients":[{"name":null,"items":["1 cup watermelon chunks","1 cup pineapple chunks","1 cup grapes, seedless (red or green)","1 cup strawberries, stemmed","2 kiwifruits, peeled and cut into quarters","1 cup low-fat yogurt, strawberry","6\" bamboo skewers"]}],"directions":[{"name":null,"steps":["Place fruit chunks on bamboo skewers. Place fruit kabobs on platter.","Place light strawberry yogurt in bowl. Serve kabobs with yogurt on the side."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"74.88 kcal","carbohydrateContent":"16.05 g","cholesterolContent":"1.53 mg","fiberContent":"1.47 g","proteinContent":"2.11 g","sodiumContent":"23.49 mg","sugarContent":"12.50 g","fatContent":"0.63 g","saturatedFatContent":"0.29 g"},"notes":null,"contributor":"Food and Health Communications, Inc."},
{"slug":"fruit-milk-shakes","source_url":"https://www.myplate.gov/recipes/fruit-milk-shakes","name":"Fruit Milk Shakes","description":"This fruit shake is a great way to kick off your day. One minute in the blender and you''ll be on your way.","ingredients":[{"name":null,"items":["1 cup milk, fat-free (or water)","1/2 cup non-fat dry milk","2 ripe bananas (or 1/3 cup orange juice concentrate)","1/2 teaspoon vanilla","10 large ice cubes"]}],"directions":[{"name":null,"steps":["Place everything together into a blender.","Blend for 30 seconds to 1 minute."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"228.26 kcal","carbohydrateContent":"43.58 g","cholesterolContent":"7.06 mg","fiberContent":"2.14 g","proteinContent":"11.27 g","sodiumContent":"145.06 mg","sugarContent":"35.04 g","fatContent":"0.58 g","saturatedFatContent":"0.28 g"},"notes":null,"contributor":"Cooking with What You Have\nCornell Cooperative Extension of Onondaga County"},
{"slug":"fruit-pizza-go","source_url":"https://www.myplate.gov/recipes/fruit-pizza-go","name":"Fruit Pizza To Go","description":"Toasted whole wheat English muffins topped with fat-free cream cheese and fruit make this a quick and easy breakfast or snack.","ingredients":[{"name":null,"items":["1 English muffin (whole wheat)","2 tablespoons whipped fat-free strawberry cream cheese","2 strawberries, sliced","2 grapes, sliced","2 slices mandarin oranges"]}],"directions":[{"name":null,"steps":["Toast the English muffin until golden brown. Spread cream cheese on toasted muffin.","Arrange sliced strawberries, grapes, and orange slices on top of the cream cheese."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 fruit pizza","calories":"189.02 kcal","carbohydrateContent":"35.09 g","cholesterolContent":"3.60 mg","fiberContent":"3.55 g","proteinContent":"10.19 g","sodiumContent":"420.02 mg","sugarContent":"8.06 g","fatContent":"1.57 g","saturatedFatContent":"0.37 g"},"notes":"This recipe can be made with any flavor of cream cheese and any fruit you like.","contributor":"University of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"fruit-pizza","source_url":"https://www.myplate.gov/recipes/fruit-pizza","name":"Fruit Pizza","description":"The crust for this dessert cooks in the oven and is covered with a cream cheese mix and topped with strawberries. For variety, try using any combination of c...","ingredients":[{"name":"Cookie Crust","items":["1/2 cup margarine","1/2 cup sugar","1 teaspoon vanilla extract","1 egg","2 cups flour, all-purpose","2 teaspoons baking powder"]},{"name":"Cheese Spread","items":["8 ounces cream cheese, nonfat (or light)","1/2 cup sugar","1 teaspoon vanilla extract"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F.","For crust, cream margarine, sugar, vanilla, and egg until light and fluffy. Add flour and baking powder, mixing well.","Spread mixture about 1/8 inch thick on a pizza pan, baking sheet, or 9x13 inch pan.","Bake for 10 to 12 minutes or until lightly browned. Cool.","For spread, mix together cream cheese, sugar, and vanilla. Spread on cooled cookie crust.","Arrange fruit on top of pizza. Refrigerate until serving time."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"220.64 kcal","carbohydrateContent":"34.37 g","cholesterolContent":"19.49 mg","fiberContent":"0.56 g","proteinContent":"5.65 g","sodiumContent":"282.87 mg","sugarContent":"17.82 g","fatContent":"6.44 g","saturatedFatContent":"1.42 g"},"notes":"Fruit Topping Ideas: Sliced Strawberries, kiwi, bananas, pineapple, mandarin oranges, pears, peaches, blueberries, or grapes.","contributor":"Kansas Family Nutrition Program"},
{"slug":"fruit-salad-jicama","source_url":"https://www.myplate.gov/recipes/fruit-salad-jicama","name":"Fruit Salad with Jicama","description":"Mango and papaya add a tropical flavor to this fruit salad while chili powder gives it a kick. The jicama provides a refreshing crunch and the result is a fr...","ingredients":[{"name":null,"items":["3 cups jicama (small slices)","2 cups watermelon (cut into pieces)","1 mango","1 small papaya","1 lime, juiced","2 kiwifruit","1 teaspoon lime or orange juice","1/4 teaspoon salt","1/4 teaspoon chili powder"]}],"directions":[{"name":null,"steps":["Wash, peel, and cut the jicama into thin slices.","Wash, peel, and cut the rest of the fruit (including the lime) into slices or small pieces.","On a large plate, arrange the fruit. Sprinkle the lime or orange juice over the fruit.","In a small bowl, mix the salt and chili powder. Sprinkle over the fruit and serve.","Refrigerate leftovers within 2 hours."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/7 of recipe","calories":"89.86 kcal","carbohydrateContent":"21.96 g","cholesterolContent":"0.00 mg","fiberContent":"4.92 g","proteinContent":"1.43 g","sodiumContent":"95.14 mg","sugarContent":"13.69 g","fatContent":"0.47 g","saturatedFatContent":"0.09 g"},"notes":null,"contributor":"Pictorial Recipes\nOregon State University Cooperative Extension Service\nOregon Family Nutrition Program\nRecipe submitted by Lynn Myers Steele, 2000"},
{"slug":"fruit-salad-yogurt","source_url":"https://www.myplate.gov/recipes/fruit-salad-yogurt","name":"Fruit Salad with Yogurt","description":"This colorful salad combines sliced strawberries, pineapple chunks, and blueberries coated in pineapple juice. Serve topped with low-fat yogurt and slivered ...","ingredients":[{"name":null,"items":["2 cups strawberries (sliced)","1 cup blueberries (rinsed)","1 cup pineapple chunks (canned or fresh)","3 tablespoons pineapple juice","2 cups plain low-fat yogurt","1/8 cup almonds (sliced or slivered)"]}],"directions":[{"name":null,"steps":["Place fruit in a large bowl and mix with pineapple juice. Let stand for 15 minutes at room temperature.","Place 1 cup of fruit salad in a small bowl and top with 1/2 cup of yogurt.","Sprinkle almonds on top of each fruit salad. Serve immediately."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"186.89 kcal","carbohydrateContent":"29.75 g","cholesterolContent":"7.35 mg","fiberContent":"3.34 g","proteinContent":"8.47 g","sodiumContent":"96.35 mg","sugarContent":"24.64 g","fatContent":"4.56 g","saturatedFatContent":"1.42 g"},"notes":"Any 100% fruit juice can be used instead of pineapple juice.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"fruit-salad","source_url":"https://www.myplate.gov/recipes/fruit-salad","name":"Fruit Salad","description":"This semi-homemade recipe mixes canned fruit cocktail with fresh fruit and yogurt for a quick and tasty fruit salad.","ingredients":[{"name":null,"items":["1 can (15 ounces) fruit cocktail, drained","2 bananas, sliced","2 oranges, cut into bite-size pieces","2 apples, cut into bite-size pieces","1 (8 ounce) container of yogurt, low-fat piña colada"]}],"directions":[{"name":null,"steps":["Mix fruit in a large bowl.","Add yogurt and mix well.","Chill in refrigerator before serving."]}],"yield":"14 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared fruit salad","1/14 of recipe (109g)"],"calories":"74.84 kcal","carbohydrateContent":"17.02 g","cholesterolContent":"0.81 mg","fiberContent":"1.68 g","proteinContent":"1.27 g","sodiumContent":"13.50 mg","sugarContent":"13.64 g","fatContent":"0.37 g","saturatedFatContent":"0.18 g"},"notes":null,"contributor":"Easy and Nutritious Family Recipes, Adapted from Easy Fruit Salad\nUniversity of California Cooperative Extension\nFresno County"},
{"slug":"fruit-salsa","source_url":"https://www.myplate.gov/recipes/fruit-salsa","name":"Fruit Salsa","description":"A salsa that is different from what you may usually have, this fruit recipe can be a great way to help older kids and teens learn safe knife skills in the ki...","ingredients":[{"name":null,"items":["1 cup strawberries (diced)","1 banana (diced)","1 kiwifruit (peeled and diced)","1 apple (cored and diced)","2 tablespoons lemon juice","1/4 cup sugar","1/4 teaspoon nutmeg","1/4 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Combine fruits in a medium mixing bowl and add lemon juice.","Stir in sugar, nutmeg, and cinnamon. Mix well.","Refrigerate until serving time."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"138.75 kcal","carbohydrateContent":"33.12 g","cholesterolContent":"0.00 mg","fiberContent":"2.99 g","proteinContent":"0.81 g","sodiumContent":"6.71 mg","sugarContent":"27.32 g","fatContent":"0.43 g","saturatedFatContent":"0.09 g"},"notes":null,"contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"fruit-slush","source_url":"https://www.myplate.gov/recipes/fruit-slush","name":"Fruit Slush","description":"Serve this fruit slush as a drink or a dessert, and keep leftovers in the fridge for later. Pour it over fresh ice when you are ready to eat.","ingredients":[{"name":null,"items":["3 cups cantaloupe or watermelon, coarsely chopped, seeded, peeled","kiwifruit, coarsely chopped (optional, 2 small)","sugar (optional)","2 tablespoons lime juice","2 cups water","ice"]}],"directions":[{"name":null,"steps":["In a blender, puree fruit and lime juice until smooth. Add sugar if desired.","Combine fruit mixture and water in a large pitcher.","To eliminate the pulp pour through a strainer (optional).","Cover and refrigerate for up to a week.","To serve, stir well and pour into tall glasses over ice."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"46.11 kcal","carbohydrateContent":"10.14 g","cholesterolContent":"0.00 mg","fiberContent":"0.96 g","proteinContent":"0.99 g","sodiumContent":"39.83 mg","sugarContent":"9.29 g","fatContent":"0.21 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"fruit-smoothie-ii","source_url":"https://www.myplate.gov/recipes/fruit-smoothie-ii","name":"Strawberry and Banana Fruit Smoothie","description":"This quick and easy smoothie uses any of your favorite frozen fruits. It makes enough for 4 servings.","ingredients":[{"name":null,"items":["3 cups frozen unsweetened strawberries (or other frozen fruit)","2 cups 1% low-fat milk","1 medium banana","1 cup low-fat plain yogurt"]}],"directions":[{"name":null,"steps":["Defrost the frozen fruit just enough so that it will blend easily.","Pour the milk into the blender.","Add the pieces of frozen fruit to the milk in the blender.","Add the banana and yogurt.","Blend until smooth, about 30 to 45 seconds."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/4 of recipe"],"calories":"160.98 kcal","carbohydrateContent":"28.05 g","cholesterolContent":"9.78 mg","fiberContent":"2.90 g","proteinContent":"8.06 g","sodiumContent":"92.71 mg","sugarContent":"20.47 g","fatContent":"2.32 g","saturatedFatContent":"1.35 g"},"notes":"Strawberries, 1% milk, and low-fat vanilla yogurt used in nutrition analysis and costing.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"fruit-smoothie","source_url":"https://www.myplate.gov/recipes/fruit-smoothie","name":"Fruit Smoothie","description":"Have fun experimenting with different fruit and juices in this scrumptious smoothie.","ingredients":[{"name":null,"items":["1 medium banana","1 cup fresh peaches (or strawberries)","1 (8 ounce) container low-fat vanilla yogurt","1/2 cup 100% fruit juice"]}],"directions":[{"name":null,"steps":["Put all ingredients in a blender.","Blend on high until smooth.","Pour into 2 glasses. Serve right away."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"209.01 kcal","carbohydrateContent":"40.23 g","cholesterolContent":"6.78 mg","fiberContent":"2.36 g","proteinContent":"6.98 g","sodiumContent":"90.02 mg","sugarContent":"33.81 g","fatContent":"2.25 g","saturatedFatContent":"1.19 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"fruit-snake","source_url":"https://www.myplate.gov/recipes/fruit-snake","name":"Fruit Snake","description":"Make the youngest members of your family happy with this adorable snack. It''s perfect for a mid-morning or afterschool snack.","ingredients":[{"name":null,"items":["2 medium bananas","1/3 tablespoon raisins (4 raisins)"]}],"directions":[{"name":null,"steps":["Peel banana and use butter knife to cut banana in half lengthwise.","Place 2 banana halves on small plate end to end, in an \"s\" shape.","Add raisins to the top of banana as eyes.","Enjoy your Fruit Snake."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 fruit snake","calories":"127.15 kcal","carbohydrateContent":"29.91 g","cholesterolContent":"0.00 mg","fiberContent":"2.22 g","proteinContent":"0.99 g","sodiumContent":"0.43 mg","sugarContent":"20.98 g","fatContent":"0.36 g","saturatedFatContent":"0.14 g"},"notes":null,"contributor":"Chickasaw Nation Get Fresh! Nutrition Education Program"},
{"slug":"fruit-sorbet","source_url":"https://www.myplate.gov/recipes/fruit-sorbet","name":"Peach Sorbet","description":"Try this refreshing peach sorbet or create your own flavor combination!","ingredients":[{"name":null,"items":["2 cans sliced peaches in 100% juice (15-ounce cans)","banana, peeled (optional)"]}],"directions":[{"name":null,"steps":["Collect all ingredients and freeze cans before starting to prepare the recipe.","Place cans of fruit in freezer for at least 3 hours. Take out when fully frozen.*","Run frozen cans briefly under hot water, or let them sit on counter for 30 minutes to loosen contents. Remove fruit from the cans, and use a sharp knife to cut it into small pieces.","If using a banana, peel, and cut into slices. Banana does not need to be frozen.","Place frozen, chopped fruit (and banana, if using) in the blender, and blend until creamy.","Serve immediately.","Freeze any leftovers in a freezer-safe container or sealable plastic freezer bags.","*It is ok to freeze these cans overnight. They will not explode."]}],"yield":"7 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"49.82 kcal","carbohydrateContent":"12.52 g","cholesterolContent":"0.00 mg","fiberContent":"1.46 g","proteinContent":"0.55 g","sodiumContent":"7.29 mg","sugarContent":"10.80 g","fatContent":"0.12 g","saturatedFatContent":"0.01 g"},"notes":"Cost and nutrition analysis provided for Peach Sorbet.\nTry these refreshing flavor combinations, or create your own!\nPeach: 2 (15 ounce) cans sliced peaches in 100% fruit juice (makes 7 servings)\nPineapple: 1 (20 ounce) can crushed pineapple in 100% fruit juice (makes 5 servings)\nPineapple + Banana: 1 (20 ounce) can crushed pineapple in 100% fruit juice plus 1 banana (makes 7 servings)","contributor":"\"Fruit Sorbet\"\nEating Smart, Being Active\nColorado State University"},
{"slug":"fruit-yogurt-parfait","source_url":"https://www.myplate.gov/recipes/fruit-yogurt-parfait","name":"Fruit Yogurt Parfait","description":"Layer grapes, yogurt, bananas, and cereal for a sweet and crunchy snack.","ingredients":[{"name":null,"items":["1/2 cup yogurt, fruit-flavored (low-fat)","1/2 banana (medium)","1/2 cup grapes, seedless","1/4 cup dry crunchy cereal (Grape Nuts or granola cereals are good)"]}],"directions":[{"name":null,"steps":["Peel and slice the banana.","Spoon the grapes into a tall plastic cup.","Put 3 spoonsful of yogurt on top of the grapes.","Spoon sliced bananas on top of the yogurt.","Add the rest of the yogurt.","Sprinkle the cereal on top."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 parfait","calories":"337.39 kcal","carbohydrateContent":"64.17 g","cholesterolContent":"6.13 mg","fiberContent":"3.90 g","proteinContent":"9.42 g","sodiumContent":"125.40 mg","sugarContent":"42.38 g","fatContent":"5.55 g","saturatedFatContent":"1.55 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"fruit-yogurt-pops","source_url":"https://www.myplate.gov/recipes/fruit-yogurt-pops","name":"Fruit Yogurt Pops","description":"These pops are a fun warm-weather treat that needs only two ingredients. With no cooking, cutting, or special equipment required, kids can learn to make thes...","ingredients":[{"name":null,"items":["1 low fat yogurt, fruit flavored (8 ounces)","2 1/2 cups strawberries (sliced frozen, thawed)"]}],"directions":[{"name":null,"steps":["Combine ingredients. Pour into 3 ounce paper cups.","Freeze about 30 minutes; then stick a wooden popsicle/ craft stick in the center of each cup.","Freeze overnight until firm. To eat pops, peel off paper cups.","For variety, try other fruit flavored yogurts and frozen fruit or fruit juice concentrates."]}],"yield":"14 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 yogurt pop","1/14 of recipe"],"calories":"23.74 kcal","carbohydrateContent":"4.38 g","cholesterolContent":"0.81 mg","fiberContent":"0.50 g","proteinContent":"0.92 g","sodiumContent":"13.17 mg","sugarContent":"3.37 g","fatContent":"0.28 g","saturatedFatContent":"0.14 g"},"notes":null,"contributor":"Easy and Nutritious Family Recipes\nUniversity of California Cooperative Extension\nFresno County"},
{"slug":"fruity-homemade-oatmeal","source_url":"https://www.myplate.gov/recipes/fruity-homemade-oatmeal","name":"Fruity Homemade Oatmeal","description":"Start your day off right with a warm bowl of apple cinnamon oatmeal, a dish that is perfect for a chilly morning at home.","ingredients":[{"name":null,"items":["1 apple (cored and chopped)","1 teaspoon cinnamon","2 tablespoons raisins or currants","3/4 cup old-fashioned rolled oats","1 1/2 cups water"]}],"directions":[{"name":null,"steps":["Use a vegetable peeler to remove the skin from the apple.","Cut the core out of the apple. Chop the apple into small pieces.","Put the water in the saucepan.","Bring the water to a boil on medium heat.","Stir in oatmeal, raisins, chopped apple, and cinnamon.","Turn heat to low.","Cook 5 minutes, stirring often."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"207.81 kcal","carbohydrateContent":"44.09 g","cholesterolContent":"0.00 mg","fiberContent":"6.27 g","proteinContent":"4.51 g","sodiumContent":"11.73 mg","sugarContent":"18.95 g","fatContent":"2.15 g","saturatedFatContent":"0.38 g"},"notes":"To get more fiber, leave the skin on the apple.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"fruity-thai-pita-pockets","source_url":"https://www.myplate.gov/recipes/fruity-thai-pita-pockets","name":"Fruity Thai Pita Pockets","description":"Bored with the same old sandwich at lunch? Liven up packed lunches with this Thai-influenced pita pocket: a surprising blend of fruits, spinach, and peanut s...","ingredients":[{"name":null,"items":["1 can tropical fruit salad in 100% juice (15 ounces)","4 whole-grain pita pockets","4 cups fresh spinach (torn)","1/4 cup fresh cilantro (optional)"]},{"name":"For the Spread","items":["3 tablespoons reserved juice from tropical fruit salad","1/2 cup natural peanut butter, crunchy or chunky","3 tablespoons fat-free cream cheese","1 tablespoon low-sodium soy sauce"]}],"directions":[{"name":null,"steps":["In a colander over a bowl, drain fruit salad well; reserve 3 tablespoons juice.","In a small bowl, whisk together reserved juice, peanut butter, cream cheese, and soy sauce.","Place drained fruit, spinach, and cilantro (if desired) in a bowl; mix gently.","Add sauce and toss.","Slice a small portion off each pita. Tuck the slice inside the bottom of the pita.","Fill each pita pocket with the fruit-spinach mixture.","Wrap individually in plastic wrap and refrigerate. Will keep well overnight."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"425.70 kcal","carbohydrateContent":"53.87 g","cholesterolContent":"1.35 mg","fiberContent":"6.40 g","proteinContent":"16.08 g","sodiumContent":"635.42 mg","sugarContent":"17.75 g","fatContent":"17.70 g","saturatedFatContent":"3.45 g"},"notes":"Time-saving idea: Purchase pre-opened pita pockets","contributor":"Produce for Better Health Foundation"},
{"slug":"fudgy-fruit","source_url":"https://www.myplate.gov/recipes/fudgy-fruit","name":"Fudgy Fruit","description":"Fruit, nuts, and chocolate. Do we need to say more?","ingredients":[{"name":null,"items":["1/8 cup chocolate chips (or 2 tablespoons semi-sweet chips)","2 large bananas (peeled and cut into quarters)","8 large strawberries","1/4 cup unsalted peanuts (chopped)"]}],"directions":[{"name":null,"steps":["Place chocolate chips in a small microwave safe bowl. Heat on high for 10 seconds and stir. Repeat until chocolate is melted, about 30 seconds.","Place fruit on a small tray covered with a piece of waxed paper. Use a spoon to drizzle the melted chocolate on top of the fruit.","Sprinkle the fruit with chopped nuts.","Cover the fruit and place in the refrigerator for 10 minutes or until the chocolate hardens. Serve chilled."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 banana and 2 strawberries","calories":"162.37 kcal","carbohydrateContent":"23.66 g","cholesterolContent":"0.00 mg","fiberContent":"2.92 g","proteinContent":"3.23 g","sodiumContent":"4.95 mg","sugarContent":"16.31 g","fatContent":"6.98 g","saturatedFatContent":"2.08 g"},"notes":null,"contributor":"Healthy Recipes\nCalFresh Healthy Living"},
{"slug":"full-beans-hot-dish","source_url":"https://www.myplate.gov/recipes/full-beans-hot-dish","name":"Full of Beans Hot Dish","description":"Beans are unique foods that can be counted as either a vegetable or protein. This dish comes together quickly with canned beans but can also be made with dri...","ingredients":[{"name":null,"items":["1 pound lean ground beef (90%)","1 large onion (chopped)","1/4 cup brown sugar (packed)","1/2 cup ketchup","2 tablespoons vinegar","1/2 teaspoon black pepper","2 cans low-sodium kidney beans (15.5 ounce)","1 can pork and beans (15 ounce)","2 can low-sodium great northern beans (15.5 ounce)"]}],"directions":[{"name":null,"steps":["Preheat over to 350 °F.","Cook ground beef and onions. Drain fat.","Add remaining ingredients and mix.","Place in casserole dish.","Bake in the oven at 350 °F for 30 minutes."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (262g)","calories":"343.22 kcal","carbohydrateContent":"51.85 g","cholesterolContent":"32.86 mg","fiberContent":"11.43 g","proteinContent":"23.84 g","sodiumContent":"506.72 mg","sugarContent":"14.66 g","fatContent":"5.07 g","saturatedFatContent":"1.92 g"},"notes":"For convenience this recipe includes canned beans. To lower the sodium, feel free to use dried beans that have been prepared according to the package directions.","contributor":"University of Wisconsin Cooperative Extension Service\nFamily Living Program"},
{"slug":"garden-barley-soup","source_url":"https://www.myplate.gov/recipes/garden-barley-soup","name":"Garden Barley Soup","description":"Break out the barley to make a comforting vegetable soup on a cold or rainy day.","ingredients":[{"name":null,"items":["46 us fluid ounces tomato juice, low-sodium","1 can beef broth, reduced sodium (14.5 ounces)","1 cup regular barley","1/4 cup sugar","1 tablespoon Worcestershire sauce","1 bay leaf","1/2 teaspoon thyme leaves, fresh or dried (crushed)","1/4 teaspoon salt (optional)","2 cups zucchini (coarsely chopped)","1 medium tomato (chopped)","1/2 cup green pepper (chopped)"]}],"directions":[{"name":null,"steps":["In a Dutch oven or stock pot, combine tomato juice, beef broth, barley, sugar, Worcestershire sauce, bay leaf, thyme and salt (if using). Bring to boil; reduce heat.","Cover; simmer 1 hour.","Add zucchini, tomato, and green pepper. Return to boil; reduce heat.","Cover; simmer 15 to 20 minutes or until vegetables and barley are tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (381g)","calories":"266.80 kcal","carbohydrateContent":"58.60 g","cholesterolContent":"0.00 mg","fiberContent":"6.56 g","proteinContent":"6.44 g","sodiumContent":"333.18 mg","sugarContent":"17.00 g","fatContent":"1.50 g","saturatedFatContent":"0.23 g"},"notes":null,"contributor":"Wellness Ways Resource Book\nUniversity of Illinois Extension Service"},
{"slug":"garden-cannellini-bean-salad","source_url":"https://www.myplate.gov/recipes/garden-cannellini-bean-salad","name":"Garden Cannellini Bean Salad","description":"Chopped tomatoes, bell peppers, and cucumbers combine with cannellini (white) beans, almonds, and a simple vinaigrette for a delicious and satisfying salad. ...","ingredients":[{"name":"For the dressing","items":["1 tablespoon olive oil","2 teaspoons white wine vinegar","1/2 cup apple juice","1 tablespoon tomato basil garlic seasoning blend, no-salt"]},{"name":"For the Bean Salad","items":["1/2 cup almond slivers","2 tomatoes, coarsely chopped","1/2 yellow bell pepper, chopped","1/2 cucumber, peeled, chopped","3 green onions, sliced","2 15.5 oz cans cannellini (white) beans, low-sodium, drained, and rinsed","Large lettuce leaves (Boston, Bibb, or romaine)"]}],"directions":[{"name":null,"steps":["Whisk together dressing ingredients in a small bowl.","In a small sauté pan, toast almond slivers until golden.","Remove from pan and let cool.","In a medium bowl, toss dressing with all ingredients except lettuce.","Refrigerate until ready to serve.","To serve, place lettuce leaves on individual plates; top with salad."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of Garden Cannellini Bean Salad","calories":"408.62 kcal","carbohydrateContent":"55.88 g","cholesterolContent":"0.00 mg","fiberContent":"13.78 g","proteinContent":"20.20 g","sodiumContent":"382.41 mg","sugarContent":"9.00 g","fatContent":"13.39 g","saturatedFatContent":"1.51 g"},"notes":"Serving Suggestion: Serve with a glass of non-fat milk, 1 slice of whole-grain bread, and pear slices.","contributor":"Produce for Better Health Foundation"},
{"slug":"garden-chili","source_url":"https://www.myplate.gov/recipes/garden-chili","name":"Garden Chili","description":"This quick and easy one pan dish is full of veggies, spices, and flavor. Get your kids involved by letting them wash the vegetables.","ingredients":[{"name":null,"items":["3/4 pound ground beef (lean, 10% fat)","1/2 cup green pepper (chopped)","1/2 large onion (chopped)","1/2 cup celery (chopped)","2/3 cup kidney beans, canned, low-sodium (drained and rinsed)","1/2 cup corn (sweet)","1 can tomato sauce, low-sodium (8 oz)","1 cup fresh tomatoes (chopped)","1 dash black pepper","1/2 teaspoon garlic powder","2 teaspoons chili powder"]}],"directions":[{"name":null,"steps":["Place ground beef in a skillet sprayed with non-stick cooking spray. Brown meat over medium-high heat, stirring occasionally to break it into pieces. Drain fat and blot meat with paper towels. Transfer beef into a colander and rinse with very hot water to further remove fat.","Add green pepper, onion, and celery. Cook until softened.","Add beans, corn, tomato sauce, chopped tomatoes, pepper, garlic powder and chili powder.","Cook mixture over low heat for 20 minutes.","Serve hot in bowls. Or serve as a dip with baked tortilla chips or on a bun.","Cover and refrigerate leftovers within 2 hours."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"210.99 kcal","carbohydrateContent":"18.79 g","cholesterolContent":"49.29 mg","fiberContent":"5.05 g","proteinContent":"19.42 g","sodiumContent":"159.59 mg","sugarContent":"6.62 g","fatContent":"7.17 g","saturatedFatContent":"2.66 g"},"notes":null,"contributor":"Fix it Fresh! Recipe Series\nKansas State University Research and Extension"},
{"slug":"garden-frittata","source_url":"https://www.myplate.gov/recipes/garden-frittata","name":"Garden Frittata","description":"This frittata with its blend of colorful vegetables and fresh eggs makes a deliciously nutritious single-dish meal for breakfast, brunch, or supper.","ingredients":[{"name":null,"items":["4 large eggs","1/4 teaspoon ground black pepper","1/4 teaspoon salt","2 medium unpeeled red potatoes","1/2 tablespoon olive oil","4 cups Italian kale, or other kale variety","1/4 cup chopped onion","1/2 red bell pepper, chopped"]}],"directions":[{"name":null,"steps":["Beat eggs, pepper, and salt in large bowl; set aside.","Microwave potatoes until slightly soft, but not completely cooked; then cube. (Alternate method without microwave: Cube potatoes and boil 5 minutes until slightly soft; then drain.)","Chop remaining vegetables while potatoes cool. Mix vegetables together.","Heat oil in a 10-inch non-stick skillet. Sauté vegetables for 5 to 8 minutes; add to eggs and mix well.","Pour egg-vegetable mixture into the same skillet. Cook over low to medium heat until eggs are almost set, about 8 to 10 minutes.","Cover and let sit until eggs are completely set, about 5 minutes. Egg dishes should be cooked to 160 ºF."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"183.39 kcal","carbohydrateContent":"20.68 g","cholesterolContent":"205.50 mg","fiberContent":"3.15 g","proteinContent":"9.31 g","sodiumContent":"238.76 mg","sugarContent":"2.63 g","fatContent":"7.34 g","saturatedFatContent":"1.97 g"},"notes":"Serving Suggestions: Serve with 8-oz glass of fat-free (skim) milk and 1/2 sliced orange.","contributor":"Produce for Better Health Foundation"},
{"slug":"garden-orchard-salad","source_url":"https://www.myplate.gov/recipes/garden-orchard-salad","name":"Garden Orchard Salad","description":"Fresh veggies, peanuts, and apples give this crunchy salad a refreshing flavor, and it is coated with non-fat vanilla yogurt for creaminess.","ingredients":[{"name":null,"items":["1 1/2 cups broccoli florets (coarsely chopped)","1/2 cup carrots (grated)","1/2 cup cauliflower (coarsely chopped)","1/2 cup apple (chopped, cored and diced, not peeled)","1/4 cup green onion (sliced)","1/2 cup nonfat vanilla yogurt","1/4 cup unsalted, dry-roasted peanuts (chopped)"]}],"directions":[{"name":null,"steps":["Mix all ingredients together in a serving bowl.","Cover and refrigerate for 2 hours or longer to allow flavors to blend. Serve cold.","Cover and refrigerate leftovers within 2 hours."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (126g)","calories":"108.06 kcal","carbohydrateContent":"12.14 g","cholesterolContent":"0.61 mg","fiberContent":"2.76 g","proteinContent":"5.34 g","sodiumContent":"51.14 mg","sugarContent":"7.11 g","fatContent":"4.81 g","saturatedFatContent":"0.78 g"},"notes":null,"contributor":"Fix it Fresh! Recipe Series\nKansas State University Research and Extension"},
{"slug":"garden-pan-bread","source_url":"https://www.myplate.gov/recipes/garden-pan-bread","name":"Garden Pan Bread","description":"The bananas make this bread moist and add extra flavor. Serve with a salad or main dish, or eat anytime.","ingredients":[{"name":null,"items":["1/2 cup cornmeal","1/2 cup all-purpose flour","1 teaspoon baking powder","1/4 teaspoon salt","2 ripe bananas, mashed","1/2 cup water","1 tablespoon egg mix (or 1 egg)","1/4 cup raisins","1/4 cup walnuts, chopped","nonstick cooking spray"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a medium-sized bowl, combine cornmeal, flour, baking powder, and salt. Set aside.","In a small bowl, combine bananas, water, and egg mix. Stir until mixed well.","Stir banana mixture into cornmeal mixture. Mix until dry ingredients are moistened. Gently stir in raisins and walnuts.","Lightly spray medium-sized skillet or baking pan with nonstick cooking spray.","Spoon batter into skillet or baking pan.","Bake for 18 to 20 minutes or until bread is golden brown and pulls away from the edges. A wooden toothpick or clean fork inserted into the center of the bread should come out clean.","Cut into four equal slices and serve hot or cold."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 portion","calories":"260.15 kcal","carbohydrateContent":"47.24 g","cholesterolContent":"20.38 mg","fiberContent":"3.56 g","proteinContent":"5.39 g","sodiumContent":"284.99 mg","sugarContent":"16.82 g","fatContent":"6.34 g","saturatedFatContent":"0.83 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe submitted by Alicson Scott, Chickasaw Nation, Get Fresh! Nutrition Education Program"},
{"slug":"garden-pasta-salad","source_url":"https://www.myplate.gov/recipes/garden-pasta-salad","name":"Garden Pasta Salad","description":"Pasta salad is a cool and delightful addition to lunch or dinner. It goes with soup or a sandwich.","ingredients":[{"name":null,"items":["1/2 cup macaroni, cooked","1/4 cup onion, finely chopped","1/2 cup cucumber, finely chopped","1/4 cup green pepper, diced","1 tablespoon vinegar","1/2 tablespoon vegetable oil","1/4 teaspoon salt","1/4 teaspoon pepper","1 teaspoon parsley, chopped (optional)"]}],"directions":[{"name":null,"steps":["In a medium-sized bowl, combine macaroni, onions, cucumbers, and green peppers. Mix well.","In a separate bowl, mix vinegar, vegetable oil, salt, and pepper. If using parsley, add that too.","Pour the prepared dressing over the pasta. Mix well.","Cover bowl and refrigerate for 30 to 45 minutes. Serve cold."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup","calories":"34.98 kcal","carbohydrateContent":"4.90 g","cholesterolContent":"0.00 mg","fiberContent":"0.51 g","proteinContent":"0.86 g","sodiumContent":"99.10 mg","sugarContent":"0.78 g","fatContent":"1.30 g","saturatedFatContent":"0.19 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"garden-vegetable-soup","source_url":"https://www.myplate.gov/recipes/garden-vegetable-soup","name":"Garden Vegetable Soup","description":"Italian seasoning and garlic powder bring a punch of flavor to this delicious and easy vegetable soup. Serve it with a whole wheat roll for a satisfying lunc...","ingredients":[{"name":null,"items":["non-stick cooking spray","2 carrots, sliced","1 small onion, chopped","1/4 teaspoon garlic powder (or 1/2 garlic clove, minced)","3 cups chicken broth, low-sodium (or low-sodium beef or vegetable)","1 cup chopped green cabbage","1 can green beans, undrained, low-sodium (14 ounces)","1 can diced tomatoes, undrained, low-sodium (14.5 ounces)","1/2 teaspoon Italian seasoning","1 zucchini, chopped"]}],"directions":[{"name":null,"steps":["In a large saucepan sprayed with non-stick cooking spray, sauté the carrots, onion, and garlic over low heat about 5 minutes.","Add broth, cabbage, green beans, tomatoes, and Italian seasoning; bring to a boil.","Cover, lower heat. Simmer about 15 minutes or until carrots are tender.","Stir in zucchini and heat for 3 to 4 minutes. Serve hot.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"72.94 kcal","carbohydrateContent":"13.00 g","cholesterolContent":"0.00 mg","fiberContent":"4.27 g","proteinContent":"4.72 g","sodiumContent":"62.74 mg","sugarContent":"5.73 g","fatContent":"1.39 g","saturatedFatContent":"0.35 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"garlic-bok-choy","source_url":"https://www.myplate.gov/recipes/garlic-bok-choy","name":"Garlic Bok Choy","description":"This quick and simple bok choy recipe uses just garlic, salt, and vegetable oil to give bok choy a delicious flavor.","ingredients":[{"name":null,"items":["1 head of bok choy (1 pound)","5 cloves garlic (use 4-6 cloves, minced or 1 to 1 1/2 teaspoons of garlic powder)","2 teaspoons vegetable oil","1/2 teaspoon salt"]}],"directions":[{"name":null,"steps":["Cut bok choy crosswise into easy-to-eat pieces.","In a medium skillet over medium-high heat, sauté garlic in oil until fragrant. If using garlic powder, add with salt in the next step.","Add bok choy and stir quickly. Add salt. Stir until greens are wilted and stem pieces are tender-crisp. Serve hot."]}],"yield":"3 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"71.55 kcal","carbohydrateContent":"7.51 g","cholesterolContent":"0.00 mg","fiberContent":"2.94 g","proteinContent":"4.53 g","sodiumContent":"576.30 mg","sugarContent":"3.35 g","fatContent":"3.69 g","saturatedFatContent":"0.51 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"garlic-ginger-ramen-beef","source_url":"https://www.myplate.gov/recipes/garlic-ginger-ramen-beef","name":"Garlic Ginger Ramen with Beef","description":"Adding garlic and ginger to ramen is a game changer! This recipe has vegetables, lean protein, and lots of flavor!","ingredients":[{"name":null,"items":["1/2 pound lean ground beef (15% fat or less)","2 cups water","2 packages instant ramen-style noodles (3 ounces each, broken into small pieces)","1 package (16 ounces) frozen stir-fry vegetables (any type)","2 green onions (thinly sliced)","1 tablespoon fresh ginger (or 1/4 teaspoon ground ginger)","2 cloves garlic (minced or 1/2 teaspoon garlic powder)"]}],"directions":[{"name":null,"steps":["In a large skillet over medium-high heat (350 °F in an electric skillet), brown the ground beef. Drain fat from the skillet. Drain fat from the skillet. (See Notes.)","Add water and ONE seasoning packet to cooked beef and mix well.","Add vegetables, green onion, ginger, and garlic. Bring to a boil over high heat.","Add ramen noodles, reduce heat to low, and simmer 3 to 5 minutes until vegetables are tender, stirring occasionally."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"193.22 kcal","carbohydrateContent":"27.08 g","cholesterolContent":"21.27 mg","fiberContent":"2.85 g","proteinContent":"10.82 g","sodiumContent":"331.03 mg","sugarContent":"3.36 g","fatContent":"4.73 g","saturatedFatContent":"1.39 g"},"notes":"Try adding more seasonings such as red pepper flakes, cayenne pepper, or jalapeno pepper.\nPour fat from cooked meat into a metal container. Let it cool; then dispose of it in the garbage can.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"garlic-stuffed-chicken","source_url":"https://www.myplate.gov/recipes/garlic-stuffed-chicken","name":"Garlic Stuffed Chicken","description":"Jazz up your chicken dinner with garlic, lemon zest, and fresh parsley. Serve this dish with brown rice and a side salad for a complete meal.","ingredients":[{"name":null,"items":["2 cups water","8 cloves garlic clove (unpeeled)","6 tablespoons fresh parsley (chopped, divided)","1 teaspoon lemon zest (grated)","1 teaspoon sodium-free seasoning blend","4 chicken breast","1/4 cup reduced sodium chicken broth","2 tablespoons fresh lemon juice"]}],"directions":[{"name":null,"steps":["In a small saucepan, bring water to a boil. Add garlic; cook for 10 minutes. Drain garlic, peel and cut into thin slices. In a small bowl, combine garlic, 1/2 cup of chopped parsley, lemon zest, and seasoning. Mix well.","Loosen skin from each chicken breast to form a pocket. Place about 1 teaspoon of garlic mixture under skin of each breast. Heat a large nonstick skillet over medium-high heat.","Add chicken skin-side down; cook until golden, about 4 minutes. Turn chicken; reduce heat to medium.","Cover and cook until no longer pink in center, about 10 to 12 minutes. Transfer chicken to a plate. Wipe any fat away from the skillet.","Add remaining chopped parsley, broth, and lemon juice to pan. Bring to a boil; cook for 1 minute. Spoon mixture over chicken."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (231g)","calories":"209.71 kcal","carbohydrateContent":"3.84 g","cholesterolContent":"118.56 mg","fiberContent":"0.42 g","proteinContent":"37.43 g","sodiumContent":"71.75 mg","sugarContent":"0.34 g","fatContent":"4.44 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Seat Pleasant/ University of Maryland Health Partnership"},
{"slug":"gazpacho-soup","source_url":"https://www.myplate.gov/recipes/gazpacho-soup","name":"Gazpacho Soup","description":"This yummy chilled tomato soup makes a great addition to lunch or dinner.","ingredients":[{"name":null,"items":["1 large tomato","1 cucumber","2 green peppers","1/4 teaspoon garlic powder","1 1/2 cups tomato sauce, low-sodium","1 1/2 cups water","3 tablespoons red vinegar","2 tablespoons vegetable oil","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Chop the tomato, cucumber, and peppers into very small pieces.","Put all the ingredients in a large glass or plastic bowl.","Stir well with a wooden or plastic spoon.","Chill in the fridge for 1 to 2 hours before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared soup","1/6 of recipe (256g)"],"calories":"76.11 kcal","carbohydrateContent":"7.39 g","cholesterolContent":"0.00 mg","fiberContent":"2.05 g","proteinContent":"1.50 g","sodiumContent":"12.31 mg","sugarContent":"4.28 g","fatContent":"5.02 g","saturatedFatContent":"0.71 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"gazpacho","source_url":"https://www.myplate.gov/recipes/gazpacho","name":"Gazpacho","description":"Take a trip to Spain in your very own kitchen! Gazpacho, a Spanish favorite, is a cooling puréed vegetable soup topped with extra virgin olive oil for a smo...","ingredients":[{"name":"For the soup","items":["3 slices bread (crusts removed and discarded)","1 1/4 cups cold water (divided)","3 medium tomatoes (ripe, skinned, seeded, and roughly chopped, about 3 3/4 cup or 2 pounds)","1 small cucumber (peeled, seeded, and roughly chopped, about 1 1/2 cup)","1 green pepper (seeded and roughly chopped, about 1 cup)","2 teaspoons minced garlic (or 4 cloves fresh garlic, finely chopped)","1/4 cup extra virgin olive oil","1 tablespoon red wine vinegar","1/4 teaspoon low-sodium adobo seasoning"]},{"name":"For the garnish","items":["1 small tomato (seeded and finely chopped, about 1 cup)","1/2 small red onion (finely chopped, about 1/2 cup)","1/2 green bell pepper (seeded and finely chopped, about 1/2 cup)","1 hard-cooked egg (finely chopped)"]}],"directions":[{"name":null,"steps":["Tear bread into small pieces; transfer to medium bowl and cover with 1 cup water.","Soak until bread is saturated, about 15 minutes.","Squeeze water from bread, discarding soaking water.","In bowl of blender or food processor, add bread, tomatoes, cucumber, bell pepper, garlic, and 1/4 cup of water.","Blend until well combined, about 1 minute.","With motor running, add oil in steady stream until well blended.","Stir in vinegar, season with low-sodium adobo.","Strain puréed soup through small-hole strainer, into soup terrine, pressing firmly to pass all liquid through strainer, discard any solids.","Cover terrine; transfer to refrigerator.","Chill at least 1 hour, or up to 48 hours.","To serve, divide soup evenly among serving bowls.","Garnish with tomatoes, onions, peppers, and eggs."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"168.56 kcal","carbohydrateContent":"14.47 g","cholesterolContent":"34.25 mg","fiberContent":"2.25 g","proteinContent":"3.73 g","sodiumContent":"115.15 mg","sugarContent":"4.97 g","fatContent":"11.03 g","saturatedFatContent":"1.89 g"},"notes":"Serving Suggestions: Serve with Spanish Garlic Shrimp, Garlic and Spanish Rice, and a glass of non-fat milk to make the meal complete.","contributor":"The Best of La Cocina GOYA: Healthy, Tasty, Affordable Latin Cooking/ Lo Mejor de la Cocina GOYA: Cocina Latina Saludable, Rica y Económica\nGOYA Foods"},
{"slug":"ginger-bread-mix","source_url":"https://www.myplate.gov/recipes/ginger-bread-mix","name":"Ginger Bread Mix","description":"Make this mix ahead of time and use it as a base for the Ginger Orange Muffins recipe.","ingredients":[{"name":null,"items":["8 cups white flour","1 1/2 cups sugar","1 tablespoon baking soda","3 tablespoons ginger (dried, ground)","3 tablespoons cinnamon (dried, ground)","1 teaspoon cloves (dried, ground)","1 teaspoon salt"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a large bowl. Mix well.","Store mix in a covered jar until ready to use."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup prepared mix","calories":"495.88 kcal","carbohydrateContent":"109.33 g","cholesterolContent":"0.00 mg","fiberContent":"4.23 g","proteinContent":"10.58 g","sodiumContent":"617.17 mg","sugarContent":"30.32 g","fatContent":"1.20 g","saturatedFatContent":"0.22 g"},"notes":"Use this mix to make Ginger Orange Muffins.","contributor":"Pictorial Recipes\nOregon State University Cooperative Extension Service\nOregon Family Nutrition Program\nRecipe submitted by Lynn Myers Steele, 2000"},
{"slug":"ginger-orange-muffins","source_url":"https://www.myplate.gov/recipes/ginger-orange-muffins","name":"Ginger Orange Muffins","description":"Use our Ginger Bread Mix and make these muffins ahead of time for a quick and healthy breakfast on the go.","ingredients":[{"name":null,"items":["2 cups Ginger Bread Mix","1 cup bran cereal","1 egg (slightly beaten)","1/2 cup milk, 1%","1/4 cup orange juice concentrate","1/4 cup molasses","1/4 cup vegetable oil","1 teaspoon orange peel (grated)","raisins (optional, 1/4 cup)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Combine the Ginger Bread Mix and bran cereal in a bowl.","Beat the egg slightly in another bowl.","Add the egg and other ingredients to the gingerbread and cereal mixture.","Stir only until combined. Let stand for 15 minutes.","Fill 12 muffin cups (well-greased pans or paper liners) 2/3 full.","Bake 15 to 20 minutes or until done in the center."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"190.10 kcal","carbohydrateContent":"30.45 g","cholesterolContent":"17.63 mg","fiberContent":"1.64 g","proteinContent":"3.46 g","sodiumContent":"130.75 mg","sugarContent":"13.34 g","fatContent":"6.08 g","saturatedFatContent":"1.04 g"},"notes":"2 servings of Ginger Bread Mix = 2 cups","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"gingery-quinoa-green-beans","source_url":"https://www.myplate.gov/recipes/gingery-quinoa-green-beans","name":"Gingery Quinoa with Green Beans","description":"Fresh green beans work well when they’re in season. If they’re not, try frozen in this recipe that combines a whole grains and veggies into one satisfyin...","ingredients":[{"name":null,"items":["1 cup quinoa (uncooked)","1 1/2 cups water or low-sodium broth","2 cups green beans (trimmed into 1\" pieces)","1 tablespoon olive oil or cooking oil","1 tablespoon sesame oil","2 tablespoons reduced sodium soy sauce","2 1/2 tablespoons lemon juice","1/4 teaspoon ground ginger"]}],"directions":[{"name":null,"steps":["Toast quinoa in a dry skillet over medium heat, stirring constantly for about 3 minutes.","Transfer toasted quinoa to a medium pot and add water or broth.","Bring to a boil, then let simmer until all of the water is absorbed and quinoa is tender (10 to 15 minutes).","Set aside and leave uncovered to cool.","While quinoa is cooling, place green beans in a microwave-safe dish. Add a small amount of water, cover, and microwave for 4-6 minutes or until just tender.","Rinse green beans in cold water to stop the cooking process.","In a large bowl, combine the quinoa, green beans, olive oil or cooking oil, sesame oil, soy sauce, lemon juice, and ground ginger. Stir well.","Season with salt and pepper, as needed.","Serve warm or at room temperature."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Cup","calories":"217.70 kcal","carbohydrateContent":"28.42 g","cholesterolContent":"0.00 mg","fiberContent":"5.21 g","proteinContent":"6.51 g","sodiumContent":"299.89 mg","sugarContent":"2.53 g","fatContent":"9.22 g","saturatedFatContent":"1.32 g"},"notes":null,"contributor":"Bronson Wellness Center\nBronson Healthcare - Michigan"},
{"slug":"glazed-carrots","source_url":"https://www.myplate.gov/recipes/glazed-carrots","name":"Glazed Carrots","description":"Take care not to burn the carrots at the end of this recipe. They should be browned (but not blackened) for a tasty side dish.","ingredients":[{"name":null,"items":["2 tablespoons margarine or butter","1 1/2 pounds carrots","1 cup water","1/4 teaspoon black pepper","2 teaspoons sugar"]}],"directions":[{"name":null,"steps":["Peel the carrots. Cut in half lengthwise, then cut into 1 inch pieces.","Melt the margarine in a heavy saucepan on low heat.","Add the carrots. Stir to coat them with the margarine.","Add the water, salt, and pepper.","Cover and simmer for about 15 minutes until tender.","Drain the water.","Add the sugar.","Cover the pan.","Shake the pan back and forth on the burner for 1 minute.","Cook for 1 more minute, until the carrots are glazed but not brown."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (159g)","calories":"75.73 kcal","carbohydrateContent":"11.91 g","cholesterolContent":"0.05 mg","fiberContent":"3.06 g","proteinContent":"1.03 g","sodiumContent":"107.83 mg","sugarContent":"6.55 g","fatContent":"3.06 g","saturatedFatContent":"0.60 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"glazed-meatloaf","source_url":"https://www.myplate.gov/recipes/glazed-meatloaf","name":"Glazed Meatloaf","description":"This family favorite is flavored with garlic, thyme, tomato paste, and mustard then coated with a tangy glaze and a sprinkle of oats.","ingredients":[{"name":null,"items":["1 teaspoon vegetable oil","1 onion, chopped","1/2 green bell pepper, cored and diced","2 cloves garlic, peeled and diced","1 teaspoon dried thyme","2 tablespoons tomato paste","1/2 cup water","1 tablespoon yellow mustard","1/2 teaspoon salt","1/4 teaspoon black pepper","1 pound ground beef or turkey","1 large egg","1/2 cup rolled oats"]},{"name":"For the Glaze","items":["1 teaspoon tomato paste","1 teaspoon yellow mustard"]}],"directions":[{"name":null,"steps":["Preheat the oven to 325 °F. Lightly grease a baking sheet.","Put a skillet over medium heat and when it is hot, add the oil. Add the onion, bell pepper, garlic, and thyme and cook about 10 minutes until golden.","Lower the heat and add the water and tomato paste. Cook about 10 minutes until the onion is soft and most of the liquid has been absorbed. Set aside to cool. Add the mustard, salt and pepper.","While the onion mixture is cool, put the ground beef, 4 tablespoons rolled oats and the egg in the bowl and gently mix, by hand.","Add the cooled onion mixture and gently mix again until everything is thoroughly incorporated. Do not over mix.","Form the mixture into a loaf about 8x4 inches and put on the prepared baking sheet.","To make the glaze: Put the tomato paste and mustard in a small bowl and mix well. Rub on top of the meatloaf and sprinkle with the remaining 2 tablespoons rolled oats.","Put in the oven to cook about 1 hour until deep brown and cooked throughout. Serve right away or cover and refrigerate up to 2 days."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"259.36 kcal","carbohydrateContent":"14.10 g","cholesterolContent":"117.10 mg","fiberContent":"2.62 g","proteinContent":"23.90 g","sodiumContent":"434.51 mg","sugarContent":"3.39 g","fatContent":"11.74 g","saturatedFatContent":"4.00 g"},"notes":"When using ground turkey add an extra egg\nRecipe can also be used to make burger patties","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"golden-split-pea-soup","source_url":"https://www.myplate.gov/recipes/golden-split-pea-soup","name":"Golden Split Pea Soup","description":"This soup is great for lunch or dinner. Serve it with a salad and a whole wheat roll for a delicious meal.","ingredients":[{"name":null,"items":["2 teaspoons vegetable oil (or cooking oil of your choice)","1 cup chopped onion","4 potatoes (2 cups diced, with skin on)","1 1/2 cups yellow split peas","5 1/2 cups low-sodium chicken broth","1 cup water","1/2 teaspoon onion powder","1 teaspoon poultry seasoning"]}],"directions":[{"name":null,"steps":["Place the oil in a large pot or Dutch-oven style pan. Heat over medium-high.","Add the onion and sauté until golden, about 2 to 3 minutes.","Add the rest of the ingredients and mix well. Bring to a boil and then lower the heat to a simmer. Cook uncovered until the peas are tender, about 45 minutes. Serve hot."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared soup","1/8 (316g)"],"calories":"217.17 kcal","carbohydrateContent":"37.80 g","cholesterolContent":"0.00 mg","fiberContent":"9.39 g","proteinContent":"12.85 g","sodiumContent":"60.78 mg","sugarContent":"4.52 g","fatContent":"2.64 g","saturatedFatContent":"0.54 g"},"notes":null,"contributor":"Food and Health Communications, Inc."},
{"slug":"grandmas-stuffing","source_url":"https://www.myplate.gov/recipes/grandmas-stuffing","name":"Grandma''s Stuffing","description":"This stuffing has lots of crunch and flavor from the apples, celery, and onions. Whole wheat bread gives this recipe a boost of whole grains.","ingredients":[{"name":null,"items":["8 slices whole wheat bread, cubed (or white bread or buns, dry)","1/3 cup water","1/2 cup onion (chopped)","1/2 cup celery (chopped)","1 teaspoon parsley, dried (or 1 Tbsp fresh parsley chopped)","1/4 teaspoon salt","1/4 teaspoon black pepper","1 1/2 cups milk, fat free","1 egg (lightly beaten)","2 apples (optional - medium, pared, cored and chopped, or 1/4 cup raisins)","raisins (optional, 1/4 cup)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Put cubes in a large bowl. Set aside.","Put water in medium saucepan. Add onion, celery, parsley, salt, and pepper. Cook for 5 minutes. Do not drain. Pour over bread cubes.","Stir in milk and egg. Gently stir in apples, and raisins, if desired.","Spoon into a greased 2-quart baking dish.","Bake at 350 °F for 1 hour."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (123g)","calories":"121.35 kcal","carbohydrateContent":"19.07 g","cholesterolContent":"27.06 mg","fiberContent":"2.49 g","proteinContent":"6.96 g","sodiumContent":"269.70 mg","sugarContent":"4.44 g","fatContent":"1.97 g","saturatedFatContent":"0.49 g"},"notes":null,"contributor":"University of Wisconsin Cooperative Extension Service\nFamily Living Program"},
{"slug":"granola-bars","source_url":"https://www.myplate.gov/recipes/granola-bars","name":"Granola Bars","description":"Make your own granola bars at home. This recipe combines raisins, carrots, oats, and honey for a healthy snack or breakfast on-the-go.","ingredients":[{"name":null,"items":["1 cup honey","1 cup peanut butter","3 1/2 cups rolled oats","1/2 cup raisins","1/2 cup carrot (grated)","1/2 cup coconut"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Peel and grate the carrots.","Put the honey and peanut butter in a large saucepan. Cook on low heat until they melt.","Remove the pan from the heat. Turn off the burner.","Add oatmeal, raisins, carrots, and coconut to the saucepan. Stir well, and let it cool until you can safely touch it with your hands.","Put the mix into a 9x13 inch baking pan.","Press the mix firmly into the bottom of the pan.","Bake for 25 minutes.","Cut into 24 bars."]}],"yield":"24 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 bar","1/24 of recipe (43g)"],"calories":"170.14 kcal","carbohydrateContent":"24.41 g","cholesterolContent":"0.00 mg","fiberContent":"2.09 g","proteinContent":"4.17 g","sodiumContent":"49.86 mg","sugarContent":"14.58 g","fatContent":"6.82 g","saturatedFatContent":"1.74 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"granola-oatmeal-coconut-pecan","source_url":"https://www.myplate.gov/recipes/granola-oatmeal-coconut-pecan","name":"Granola with Oatmeal, Coconut, and Pecans","description":"Learn to make your own granola in an oven, skillet, or even the microwave. It''s easy and you can be creative with what you put in it.","ingredients":[{"name":null,"items":["3 cups oatmeal, uncooked","1/2 cup coconut, shredded or flaked","1 cup pecans, chopped (or try walnuts or peanuts)","1/4 cup honey","1/4 cup margarine, melted","1 1/2 teaspoons cinnamon","2/3 cup raisins"]}],"directions":[{"name":"Conventional Oven","steps":["Heat oven to 350 ºF. Combine all ingredients in a large bowl, except raisins, mix well.","Bake in 13x9 inch baking pan at 350 ºF for 25 to 30 minutes or until golden brown. Stir every 5 minutes.","Stir in raisins. Cool thoroughly. Store in tightly covered container."]},{"name":"Electric Skillet","steps":["Combine all ingredients except raisins in a large microwave safe bowl; mix well.","Set electric skillet at 300 ºF and stir mixture constantly until lightly browned.","Place in a bowl and stir in raisins. Cool thoroughly.","Store in tightly covered container."]},{"name":"Microwave","steps":["Combine all ingredients, except raisins in a large microwave safe bowl; mix well.","Place in 11x7 glass baking dish.","Cook at HIGH about 8 minutes or until golden brown, stirring after every 2 minutes of cooking; stir in raisins.","Place onto un-greased cookie sheet or aluminum foil to cool. Cool thoroughly. Store in a tightly covered container."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup (54g)","calories":"219.07 kcal","carbohydrateContent":"28.07 g","cholesterolContent":"0.05 mg","fiberContent":"3.70 g","proteinContent":"3.84 g","sodiumContent":"35.98 mg","sugarContent":"12.04 g","fatContent":"11.37 g","saturatedFatContent":"2.38 g"},"notes":"Honey should not be fed to children under 1 year of age.","contributor":"Adapted from: Awesome Granola\nTexas A&M Agrilife Extension Service\nExpanded Nutrition Program - Hidalgo County"},
{"slug":"grape-and-cashew-salad-sandwich","source_url":"https://www.myplate.gov/recipes/grape-and-cashew-salad-sandwich","name":"Grape and Cashew Salad Sandwich","description":"The creamy and tangy goodness of low-fat cottage cheese is the perfect balance to sweet grapes and cashews. Enjoy this salad as a sandwich filling or on a be...","ingredients":[{"name":null,"items":["3/4 cup dry roasted unsalted cashews, coarsely chopped","1 cup low-fat cottage cheese","1 1/2 cups red grapes, quartered","1 celery stalk, chopped","ground black pepper to taste","2 tablespoons fresh parsley, chopped","8 lettuce leaves","8 slices whole-grain bread"]}],"directions":[{"name":null,"steps":["In a medium bowl, mix cottage cheese, grapes, celery, cashews, parsley, and ground black pepper.","Toast bread and build sandwiches following steps 3 and 4.","Spread 1/4 salad mix on 4 of the bread slices.","Add two lettuce leaves to each sandwich; top with 2nd bread slice."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 sandwich","calories":"414.53 kcal","carbohydrateContent":"52.15 g","cholesterolContent":"6.78 mg","fiberContent":"5.90 g","proteinContent":"19.42 g","sodiumContent":"523.44 mg","sugarContent":"15.62 g","fatContent":"15.71 g","saturatedFatContent":"3.54 g"},"notes":"Serving Suggestions: Serve with a side of raw baby carrots and 1 cup of sparkling water with a lemon wedge.","contributor":"Produce for Better Health Foundation"},
{"slug":"grape-salsa","source_url":"https://www.myplate.gov/recipes/grape-salsa","name":"Grape Salsa","description":"A fruit-packed, refreshing twist on salsa. Perfect for topping tacos or scooping up with tortilla chips.","ingredients":[{"name":null,"items":["2 cups seedless grapes (cut up)","1/2 cup green onions (sliced)","1/2 cup Anaheim chili, fresh or canned (diced)","2 tablespoons cilantro (chopped)","2 tablespoons vinegar","1 clove garlic (minced or 1/4 teaspoon garlic powder)","1/2 teaspoon salt","1/8 teaspoon hot sauce"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a medium bowl and mix well. Let stand at least 1 hour. Drain off excess liquid before serving."]}],"yield":"16 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 Tablespoons","calories":"16.23 kcal","carbohydrateContent":"4.06 g","cholesterolContent":"0.00 mg","fiberContent":"0.36 g","proteinContent":"0.27 g","sodiumContent":"75.39 mg","sugarContent":"3.21 g","fatContent":"0.06 g","saturatedFatContent":"0.01 g"},"notes":"Try adding chopped cucumber for more crunch.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"grapefruit-spinach-salad","source_url":"https://www.myplate.gov/recipes/grapefruit-spinach-salad","name":"Grapefruit Spinach Salad","description":"Water chestnuts give this spinach salad a delightful crunch when served with the spicy and tangy dressing.","ingredients":[{"name":null,"items":["4 1/2 cups fresh spinach, washed and drained","1 can sliced mushrooms, drained (2 ounce cans)","1 cup water chestnuts, diced (5 oz can)","2 grapefruits, sectioned and diced","1/4 cup vegetable oil","1 tablespoon vinegar","2 us fluid ounces grapefruit juice","1 tablespoon soy sauce, low-sodium","1/4 teaspoon hot pepper sauce","1/4 teaspoon salt","1 teaspoon dry mustard"]}],"directions":[{"name":null,"steps":["Tear spinach coarsely and place in large salad bowl.","Add mushrooms, water chestnuts, and grapefruit.","Mix together oil, vinegar, grapefruit juice, soy sauce, hot pepper sauce, salt, and dry mustard.","Toss dressing with spinach mixture and serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 recipe (195g)","calories":"162.88 kcal","carbohydrateContent":"18.19 g","cholesterolContent":"0.00 mg","fiberContent":"3.27 g","proteinContent":"2.25 g","sodiumContent":"260.18 mg","sugarContent":"9.37 g","fatContent":"9.79 g","saturatedFatContent":"1.33 g"},"notes":null,"contributor":"North Dakota State University Extension Service"},
{"slug":"great-northern-bean-soup","source_url":"https://www.myplate.gov/recipes/great-northern-bean-soup","name":"Great Northern Bean Soup","description":"Great Northern beans are white beans that have a mild flavor.","ingredients":[{"name":null,"items":["2 cups great northern beans, dry","3 cups water","1/2 cup onion, chopped","1/2 pound chicken, thawed, cut up, and skin removed from each piece","4 ounces ham, chopped (1/4 pound)","2 tablespoons vegetable oil","8 cups water","1/4 teaspoon salt","1 cup tomatoes, diced (or 1/2-8 ounce can low-sodium diced tomatoes)","1 tablespoon distilled white vinegar"]}],"directions":[{"name":null,"steps":["In a medium-sized bowl, soak beans in 3 cups of water overnight.","Drain the water and rinse beans.","In a large pot, brown onion, chicken, and ham in oil over medium to high heat for about 5 minutes.","Add water, beans, and salt to pot. Mix well.","Bring pot to a boil and cook for 5 minutes.","Lower heat and cook for about 1 hour. Stir pot every 15 minutes.","Add tomatoes and vinegar to pot. Keep cooking over low heat for about 20 minutes. Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"338.87 kcal","carbohydrateContent":"40.56 g","cholesterolContent":"35.10 mg","fiberContent":"10.17 g","proteinContent":"26.76 g","sodiumContent":"368.24 mg","sugarContent":"2.38 g","fatContent":"8.11 g","saturatedFatContent":"1.60 g"},"notes":"Tip for cooking chicken: The recommended safe minimum internal temperature for chicken is 165 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"greek-pork-chops","source_url":"https://www.myplate.gov/recipes/greek-pork-chops","name":"Greek Pork Chops","description":"These pork chops are marinated in oregano and garlic and then pan-fried in a hot skillet until crispy. These tasty chops make an easy meal with quick clean u...","ingredients":[{"name":null,"items":["1 pound pork cutlets (or 4 thin-cut, boneless pork chops)","1 tablespoon vegetable oil","1 tablespoon red wine vinegar","1 tablespoon dried oregano","2 cloves garlic, peeled and minced","1/2 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Put the pork, oil, vinegar, oregano, and garlic in the glass or ceramic bowl, or in a sealed plastic bag and mix well. Cover bowl and refrigerate at least 4 hours or overnight.","Sprinkle the pork with the salt and pepper.","Place a large skillet on the stove over high heat. When hot, add the pork to the dry skillet, waiting about 30 seconds between each addition.","Cook about 7 minutes on each side until crispy. Serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cutlet","calories":"192.48 kcal","carbohydrateContent":"1.48 g","cholesterolContent":"63.99 mg","fiberContent":"0.65 g","proteinContent":"25.47 g","sodiumContent":"408.72 mg","sugarContent":"0.09 g","fatContent":"8.92 g","saturatedFatContent":"2.33 g"},"notes":"Lemon, lime, or orange juice can be used instead of red wine vinegar.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"greek-salad-chicken","source_url":"https://www.myplate.gov/recipes/greek-salad-chicken","name":"Greek Salad with Chicken","description":"A colorful salad loaded with lettuce, cucumbers, tomatoes, onions, and olives topped with chicken and a creamy yogurt dressing.","ingredients":[{"name":"For the dressing","items":["1/2 cup Greek yogurt, fat-free","2 teaspoons lemon juice","2 teaspoons olive oil","1 clove garlic","1 teaspoon oregano","1/4 teaspoon salt","1/4 teaspoon pepper"]},{"name":"For the salad","items":["1 head romaine lettuce","1/2 cup cherry tomatoes, cut in half","1 cucumber, diced","1/4 cup red onion, sliced","1/4 cup black olives, cut in half","1 cup cooked chicken breast, cubed","1/4 cup feta cheese, crumbled"]}],"directions":[{"name":null,"steps":["To make the dressing, add Greek yogurt, lemon juice, olive oil, garlic, oregano, salt, and pepper to a small bowl. Mix well to combine.","Cover dressing and refrigerate for at least 1 hour.","Wash lettuce and tear into bite-sized pieces. Place in large salad bowl and add tomatoes, cucumbers, red onion, olives, and chicken.","Sprinkle with feta cheese.","Top with yogurt dressing and enjoy."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"161.44 kcal","carbohydrateContent":"9.01 g","cholesterolContent":"43.22 mg","fiberContent":"2.31 g","proteinContent":"16.82 g","sodiumContent":"373.08 mg","sugarContent":"3.81 g","fatContent":"6.88 g","saturatedFatContent":"2.15 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"greek-salad","source_url":"https://www.myplate.gov/recipes/greek-salad","name":"Greek Salad","description":"While feta cheese is the star of any Greek salad, this recipe contains all of the must-have ingredients for a classic salad that is sure to please.","ingredients":[{"name":null,"items":["6 romaine lettuces leaves, torn into 1 1/2-inch pieces (Or more if desired)","1 medium cucumber (peeled and sliced)","1 medium tomato, chopped (Can also use cherry tomatoes)","1/2 cup sliced red onion","1/3 cup crumbled feta cheese","2 tablespoons olive oil (or oil of choice)","2 tablespoons lemon juice","1 teaspoon dried oregano","salt (optional 1/2 teaspoon, to taste)"]}],"directions":[{"name":null,"steps":["Combine lettuce, cucumber, tomato, onion, and cheese in large serving bowl. Whisk together oil, lemon juice, oregano, and salt in small bowl.","Pour over lettuce mixture; toss until coated. Serve immediately."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"81.72 kcal","carbohydrateContent":"4.37 g","cholesterolContent":"7.34 mg","fiberContent":"0.98 g","proteinContent":"1.90 g","sodiumContent":"100.73 mg","sugarContent":"2.07 g","fatContent":"6.59 g","saturatedFatContent":"1.85 g"},"notes":null,"contributor":"Healthy Recipes, Adapted from Easy Greek Salad\nOregon State University Cooperative Extension Service"},
{"slug":"green-bean-and-mushroom-medley","source_url":"https://www.myplate.gov/recipes/green-bean-and-mushroom-medley","name":"Green Bean and Mushroom Medley","description":"Lemon pepper seasoning and garlic salt give a flavor punch to this mushroom, carrot, and green bean side dish.","ingredients":[{"name":null,"items":["3 cups fresh green beans (cut into 1-inch lengths)","2 carrots (cut into thick strips)","3 tablespoons olive oil","1 large onion (sliced)","1 pound fresh mushrooms (sliced)","1 teaspoon lemon pepper seasoning","1/2 tablespoon garlic salt","1/4 cup almonds (toasted, slivered)"]}],"directions":[{"name":null,"steps":["Place green beans and carrots in 1 inch of boiling water. Cover, and cook until tender but still firm. Drain.","Add oil to heated skillet. Sauté onions and mushrooms until almost tender. Reduce heat, cover, and simmer 3 minutes.","Stir in green beans, carrots, lemon pepper, garlic salt, and toasted almonds. Cover and cook for 5 minutes over medium heat."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (160g)","calories":"113.05 kcal","carbohydrateContent":"8.63 g","cholesterolContent":"0.00 mg","fiberContent":"2.70 g","proteinContent":"3.41 g","sodiumContent":"235.99 mg","sugarContent":"3.82 g","fatContent":"7.76 g","saturatedFatContent":"1.03 g"},"notes":null,"contributor":"North Carolina Cooperative Extension\nWayne County"},
{"slug":"green-bean-and-rice-casserole","source_url":"https://www.myplate.gov/recipes/green-bean-and-rice-casserole","name":"Green Bean and Rice Casserole","description":"This no-fuss side dish is a great addition to any meal and can be prepared in a flash.","ingredients":[{"name":null,"items":["1/2 cup onion, chopped","2 teaspoons vegetable oil","1/2 cup rice, uncooked","1 can reduced-sodium green beans, drained (about 15 ounces)","1 can diced tomatoes, no salt added (about 15 ounces)","1 cup water"]}],"directions":[{"name":null,"steps":["In a medium-sized pan, cook onions in vegetable oil until they start to turn light brown.","Add the rice, green beans, tomatoes, and water.","Bring to a boil.","Cover the pot with a lid and cook over low heat for 10 minutes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"107.02 kcal","carbohydrateContent":"19.97 g","cholesterolContent":"0.00 mg","fiberContent":"3.02 g","proteinContent":"2.73 g","sodiumContent":"10.90 mg","sugarContent":"2.87 g","fatContent":"2.19 g","saturatedFatContent":"0.35 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nAdapted from a recipe in Healthy Diabetes Recipes and More\nSouth Dakota Diabetes Control Program"},
{"slug":"green-bean-saute","source_url":"https://www.myplate.gov/recipes/green-bean-saute","name":"Green Bean Sauté","description":"Jazz up green beans with mushrooms, onions, and garlic in a quick and easy vegetable side dish.","ingredients":[{"name":null,"items":["1 cup onion (chopped)","1 cup mushroom (sliced)","1 teaspoon garlic (minced)","1 can green beans, low sodium (14.5 ounce, drained, cut)"]}],"directions":[{"name":null,"steps":["Spray a skillet with non-stick cooking spray.","Sauté onions, mushrooms, and garlic.","Add green beans and heat thoroughly."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/6 of recipe (114g)"],"calories":"30.29 kcal","carbohydrateContent":"6.14 g","cholesterolContent":"0.00 mg","fiberContent":"1.88 g","proteinContent":"1.42 g","sodiumContent":"3.23 mg","sugarContent":"1.88 g","fatContent":"0.38 g","saturatedFatContent":"0.09 g"},"notes":null,"contributor":"Quick and Healthy, Vol.II\nScaleDown Publishing, Inc."},
{"slug":"green-beans-and-new-potatoes","source_url":"https://www.myplate.gov/recipes/green-beans-and-new-potatoes","name":"Green Beans and New Potatoes","description":"Frozen green beans and potatoes are boiled in a pot with onion and salt to make an easy side dish for dinner.","ingredients":[{"name":null,"items":["3 1/2 cups frozen green beans (16 oz bag)","8 small potatoes (washed, peeled, and halved)","1 medium spring onion/scallion (chopped)","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Add all ingredients to a large stock pot and cover with water.","Bring to a boil and reduce to medium heat.","Cook until green beans and potatoes are tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (259g)","calories":"195.26 kcal","carbohydrateContent":"44.18 g","cholesterolContent":"0.00 mg","fiberContent":"6.58 g","proteinContent":"5.86 g","sodiumContent":"118.74 mg","sugarContent":"3.77 g","fatContent":"0.38 g","saturatedFatContent":"0.09 g"},"notes":null,"contributor":"Healthy Cookbook for African American Populations"},
{"slug":"green-beans-tomatoes-and-basil","source_url":"https://www.myplate.gov/recipes/green-beans-tomatoes-and-basil","name":"Green Beans with Tomatoes and Basil","description":"Green beans get a flavor boost from fresh or dried parsley and basil, canned tomatoes, and onion.","ingredients":[{"name":null,"items":["6 cups green beans (about 1 pound, ends snipped)","1 tablespoon olive oil","1 medium onion (finely chopped)","1 can (14.5 ounces) tomatoes, low-sodium (drained and chopped)","1 tablespoon fresh basil (or 1/2 teaspoon dried)","1 tablespoon fresh parsley (1/2 teaspoon dried)","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Cook beans in a large saucepan of boiling water for 5 minutes; beans will still be crisp. Drain and rinse under cold running water. Set aside.","In a large frying pan, heat olive oil over medium heat. Add onion and cook 2-3 minutes until softened.","Add tomatoes, basil, and parsley. Cook 3 minutes to heat and combine flavors.","Stir beans into pan and cook 5-6 minutes. Season with salt and pepper (optional)."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"70.76 kcal","carbohydrateContent":"11.21 g","cholesterolContent":"0.00 mg","fiberContent":"4.25 g","proteinContent":"2.54 g","sodiumContent":"14.02 mg","sugarContent":"5.83 g","fatContent":"2.74 g","saturatedFatContent":"0.44 g"},"notes":null,"contributor":"University of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"green-onion-omelet","source_url":"https://www.myplate.gov/recipes/green-onion-omelet","name":"Green Onion Omelet","description":"In the spring, in areas where they grow, wild onions can be used in place of green onions. Yellow or white onions work as well.","ingredients":[{"name":null,"items":["1 can low-sodium sliced potatoes, drained (about 15 ounces)","1 tablespoon vegetable oil","1 whole egg","3 egg whites","3 tablespoons 1% low-fat milk","1/4 teaspoon salt","1/2 cup ham, diced","1/2 can no salt added tomatoes, drained (about 8 ounces)","1 tablespoon green onion (or wild onion), chopped"]}],"directions":[{"name":null,"steps":["Open and drain can of sliced potatoes. Cut sliced potatoes into strips.","In a large skillet over medium heat, lightly brown potatoes in the vegetable oil for 5 to 10 minutes.","In a mixing bowl, add egg, egg whites, milk, and salt. Mix well.","Stir in ham, tomatoes, and green (or wild) onions.","Pour egg mixture over potatoes in the skillet.","Cover skillet and continue to cook eggs over medium heat until firm, not runny (about 8 minutes).","Cut the omelet into four pieces and serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"155.47 kcal","carbohydrateContent":"17.27 g","cholesterolContent":"59.12 mg","fiberContent":"3.49 g","proteinContent":"9.38 g","sodiumContent":"401.57 mg","sugarContent":"2.72 g","fatContent":"5.84 g","saturatedFatContent":"1.21 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"green-tea-berry-banana-smoothie","source_url":"https://www.myplate.gov/recipes/green-tea-berry-banana-smoothie","name":"Green Tea Berry Banana Smoothie","description":"A small handful of ingredients makes a big splash in this smoothie. The smoothie looks deep purple, but you can definitely taste the green tea thanks to the ...","ingredients":[{"name":null,"items":["3 cups water","8 single-serving bags of green tea","3 cups frozen mixed berries (~16 ounces)","2 medium bananas, peeled, cut in half and frozen","1 cup fat-free plain Greek yogurt","2 teaspoons fresh grated peeled gingerroot (optional)","2 teaspoons vanilla extract (optional)","2 teaspoons chia or flax seeds (optional)"]}],"directions":[{"name":null,"steps":["Add the water to a small saucepan. Bring the water to a boil over high heat. Remove the pan from the heat.","Add the tea bags. (Be sure the tea bags are submerged.) Let steep for 4 minutes. Discard the tea bags.","Let the tea mixture cool for 30 minutes. Pour into a water pitcher. Refrigerate for 2 hours, or until chilled.","In a food processor or blender, process the tea, berries, bananas, yogurt, gingerroot and vanilla until smooth.","Pour into four glasses. Sprinkle with the chia seeds."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cup per serving","calories":"155.75 kcal","carbohydrateContent":"29.92 g","cholesterolContent":"3.06 mg","fiberContent":"8.38 g","proteinContent":"8.12 g","sodiumContent":"30.38 mg","sugarContent":"16.93 g","fatContent":"1.13 g","saturatedFatContent":"0.16 g"},"notes":null,"contributor":"Created by the Lipton Teas and Infusions & AHA, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"grilled-asparagus-and-shrimp-quinoa-salad-lemon-vinaigrette","source_url":"https://www.myplate.gov/recipes/grilled-asparagus-and-shrimp-quinoa-salad-lemon-vinaigrette","name":"Grilled Asparagus and Shrimp Quinoa Salad with Lemon Vinaigrette","description":"Grilling brings out the flavor in fresh vegetables like asparagus. Add shrimp, quinoa, and refreshing lemon vinaigrette, and you have a delicious and quick s...","ingredients":[{"name":null,"items":["2 cups fresh asparagus, large spears, cut into 1\" pieces","1/2 yellow or red bell pepper, cut into 1/2\" pieces","1 clove garlic, minced","1 14 ounce can quartered artichoke hearts, drained","12 ounces fresh or frozen large raw shrimp, peeled and deveined","1 1/2 cups dry quinoa (cooked according to package directions)"]},{"name":"For the vinaigrette","items":["1 teaspoon grated lemon peel (optional)","3 tablespoons fresh or bottled lemon juice","3 tablespoons olive oil","1 teaspoon Dijon mustard","1/2 teaspoon dried thyme leaves","1/2 teaspoon ground black pepper"]}],"directions":[{"name":null,"steps":["Place vinaigrette ingredients in a small bowl and whisk; set aside.","Cut vegetables as directed.","Heat grill and grilling tray.","Place vegetables and shrimp in a large bowl; add about 1/3 of the vinaigrette (about 3 tablespoons) and toss.","Spread shrimp-vegetable mixture over hot grilling tray.","Grill, turning shrimp and vegetables, until the flesh of the shrimp is an opaque color (about 5 to 6 minutes); remove from grill.","Serve grill mixture over cooked quinoa, and drizzle with vinaigrette."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"408.89 kcal","carbohydrateContent":"51.08 g","cholesterolContent":"84.05 mg","fiberContent":"11.97 g","proteinContent":"20.76 g","sodiumContent":"280.68 mg","sugarContent":"4.47 g","fatContent":"14.76 g","saturatedFatContent":"2.30 g"},"notes":"Serving Suggestions: Serve with non-fat milk and grapes.","contributor":"Produce for Better Health Foundation"},
{"slug":"grilled-cheese-peaches","source_url":"https://www.myplate.gov/recipes/grilled-cheese-peaches","name":"Grilled Cheese with Peaches","description":"This grilled cheese packs an unexpected twist with the sweetness of canned peaches! Not only is this sandwich a quick and easy lunch, but also a fun way to a...","ingredients":[{"name":null,"items":["8 slices whole grain bread, thin slice","1 15-oz can of peaches, drained","8 slices reduced fat cheddar cheese","1 10-oz bag spinach","4 teaspoons vegetable oil"]}],"directions":[{"name":null,"steps":["Heat the 4 teaspoons of vegetable oil in a large non-stick pan over medium heat.","Place 4 slices of whole grain bread in the pan.","Layer (in this order) one slice of cheese, a handful of spinach, 4 to 6 peach slices, another slice of cheese, and a slice of bread on top of each original slice of bread.","After 4 to 5 minutes, flip each sandwich and cook another 4 to 5 minutes."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"358.31 kcal","carbohydrateContent":"34.46 g","cholesterolContent":"31.92 mg","fiberContent":"5.20 g","proteinContent":"19.76 g","sodiumContent":"555.05 mg","sugarContent":"11.95 g","fatContent":"15.43 g","saturatedFatContent":"6.33 g"},"notes":"Try this recipe with other leafy greens, such as arugula, and other cheeses.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"grilled-chicken-and-avocado-quinoa-pilaf","source_url":"https://www.myplate.gov/recipes/grilled-chicken-and-avocado-quinoa-pilaf","name":"Grilled Chicken and Avocado Quinoa Pilaf","description":"This pilaf recipe pairs avocados and bell peppers with red quinoa and grilled chicken, for a satisfying, colorful meal.","ingredients":[{"name":null,"items":["2 tablespoons fresh or bottled lemon juice","1/4 cup fresh basil","3/4 teaspoon ground black pepper (divided)","1 avocado, cut into chunks","1 tablespoon olive oil (divided)","1/4 teaspoon salt","2 boneless, skinless chicken breasts (about 1 lb)","1 large red bell pepper","1/2 medium onion, chopped","1 clove garlic, minced","3 cups water","3 teaspoons low-sodium chicken bouillon","1 1/2 cups red quinoa, uncooked/dry"]}],"directions":[{"name":null,"steps":["Heat grill.","Peel and cut avocado into chunks; place in a medium bowl.","Mix lemon juice, basil, an 1/2 teaspoon black pepper. Drizzle over avocado chunks, toss, and set aside.","Cut chicken breasts in half crosswise.","Mix 1/2 tablespoons olive oil, salt, and remaining black pepper. Brush mixture on chicken and red bell pepper.","Grill chicken and pepper until done. Set chicken breasts aside. Cut pepper into thin strips.","While chicken and peppers are grilling, heat remaining olive oil in a large pan, add garlic and onion, and cook until tender, about 5 minutes.","Add water, bouillon, and quinoa to pan; bring to boil, cover, reduce heat, and simmer until liquid is absorbed and quinoa is cooked (about 15 to 20 minutes).","Place quinoa pilaf in a large bowl and add chicken, red peppers, and avocado. Toss gently."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"409.52 kcal","carbohydrateContent":"43.15 g","cholesterolContent":"59.53 mg","fiberContent":"7.88 g","proteinContent":"27.02 g","sodiumContent":"221.63 mg","sugarContent":"4.11 g","fatContent":"14.59 g","saturatedFatContent":"2.26 g"},"notes":"Serving Suggestions: Serve with non-fat milk and orange slices.","contributor":"Produce for Better Health Foundation"},
{"slug":"grilled-fish-tacos-peach-salsa","source_url":"https://www.myplate.gov/recipes/grilled-fish-tacos-peach-salsa","name":"Grilled Fish Tacos with Peach Salsa","description":"Set the stage for a delicious plate with these healthy fish tacos with peach salsa. Perfect for a summertime taco night!","ingredients":[{"name":"For the salsa","items":["1 can 15.25 ounces peach halves, drained and chopped (about 1 cup)","1/2 red bell pepper, finely chopped (about 1/2 cup)","1/4 red onion, finely chopped (about 1/4 cup)","1 whole jalapeno pepper, seeded, and finely chopped","1 tablespoon fresh cilantro, finely chopped","2 teaspoons lemon juice"]},{"name":"For the fish","items":["4 tilapia fillets (about 1 lb)","1 tablespoon chili powder","1/4 teaspoon low-sodium adobo seasoning","1 package low-sodium sazon seasoning","8 6\" flour tortillas, warmed"]}],"directions":[{"name":"Make the salsa","steps":["In a medium bowl, stir together chopped peaches, bell pepper, onions, jalapenos, cilantro, and lemon juice","Cover and refrigerate until ready to use."]},{"name":"For the fish","steps":["Heat grill or grill pan over medium-high heat. Using paper towels, pat fish dry, transfer to plate.","In a small bowl, stir together chili powder, low-sodium adobo and Sazon packet.","Rub fish with spice mixture to coat completely.","Place fish on hot greased grill grates.","Cook, flipping once until fish is opaque and flakes easily with a fork (145 °F), about 8 minutes.","Thinly slice fish.","To serve, fill each tortilla with 1/2 fish fillet and about 1/3 cup of salsa."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"364.32 kcal","carbohydrateContent":"46.68 g","cholesterolContent":"46.28 mg","fiberContent":"4.86 g","proteinContent":"27.69 g","sodiumContent":"751.60 mg","sugarContent":"13.43 g","fatContent":"7.89 g","saturatedFatContent":"2.77 g"},"notes":"Serving Suggestions: Serve with a Summer Corn Salad, chock full of vegetables, and a quick Mango Banana Shake for your best taco night yet!","contributor":"The Best of La Cocina GOYA: Healthy, Tasty, Affordable Latin Cooking/ Lo Mejor de la Cocina GOYA: Cocina Latina Saludable, Rica y Económica\nGOYA Foods"},
{"slug":"grilled-fruit","source_url":"https://www.myplate.gov/recipes/grilled-fruit","name":"Grilled Fruit","description":"Fruit kabobs cooked on the grill make a tasty and healthy dessert.","ingredients":[{"name":null,"items":["1 cup pineapple chunks (fresh or canned)","1 peach (cubed)","1 banana (sliced)"]}],"directions":[{"name":null,"steps":["Place fruit chunks on a skewer to make kabobs.","Grill or broil on low heat until the fruit is hot and slightly golden."]}],"yield":"3 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 of recipe","calories":"102.94 kcal","carbohydrateContent":"24.55 g","cholesterolContent":"0.00 mg","fiberContent":"2.12 g","proteinContent":"1.13 g","sodiumContent":"9.77 mg","sugarContent":"20.06 g","fatContent":"0.35 g","saturatedFatContent":"0.06 g"},"notes":"If using wooden skewers, thoroughly soak skewers in water prior to using to prevent burning (approximately 30 minutes).\nFor a twist, try changing the fruit. Other fruits that grill well are apples, figs, pears, plums, cantaloupe, honeydew, and watermelon.","contributor":"University of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"grilled-lamb-salad","source_url":"https://www.myplate.gov/recipes/grilled-lamb-salad","name":"Grilled Lamb Salad","description":"Grilled lamb is delightful with any green salad, especially this Asian-inspired version.","ingredients":[{"name":null,"items":["3 green onions, sliced","12 ounces boneless leg of lamb, cut into 1-inch cubes (if cubed lamb is not available, ask the butcher to prepare it for you)","bamboo skewers","6 cups shredded Savoy, Napa, or green cabbage","2 carrots, shredded","2 tablespoons black or white sesame seeds","1 small jicama, julienned (optional)"]},{"name":"For the marinade/dressing","items":["2 tablespoons sugar","2 tablespoons rice vinegar","3 tablespoons soy sauce, low sodium","1/4 cup water","1 tablespoon vegetable oil"]}],"directions":[{"name":null,"steps":["Mix marinade/dressing ingredients; divide evenly.","Place lamb cubes in a glass dish; pour half of the marinade/dressing over the lamb.","Cover and refrigerate at least two hours.","In a large bowl, toss cabbage, carrots, jicama (optional), onions, and sesame seeds.","Remove lamb and discard marinade.","Soak bamboo skewers in water for 30 minutes; divide lamb among the 4 skewers.","On hot grill, cook the lamb skewers 5 to 6 minutes per side (or to desired degree of doneness).","Remove lamb from skewers, add to salad, and toss.","To serve, divide salad evenly on four plates. Drizzle with remaining dressing."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"305.09 kcal","carbohydrateContent":"18.96 g","cholesterolContent":"60.71 mg","fiberContent":"5.06 g","proteinContent":"21.26 g","sodiumContent":"531.69 mg","sugarContent":"12.35 g","fatContent":"16.43 g","saturatedFatContent":"5.03 g"},"notes":"Serving Suggestions: Serve with nonfat milk and orange slices/wedges.\nTips on Cooking Lamb: Cooking temperature: 145 °F (medium-rare); 160 °F (medium); 170 °F (well-done)","contributor":"Produce for Better Health Foundation"},
{"slug":"grilled-pineapple-ginger-glazed-chicken-zucchini-and-peppers","source_url":"https://www.myplate.gov/recipes/grilled-pineapple-ginger-glazed-chicken-zucchini-and-peppers","name":"Grilled Pineapple Ginger Glazed Chicken with Zucchini and Peppers","description":"Fresh pineapple chunks and an easy glaze made with pineapple juice add tropical and zingy flavors to grilled chicken.","ingredients":[{"name":"For the glaze","items":["1 1/2 cups pineapple juice (12-ounce bottle)","1/4 cup apple cider vinegar","3 tablespoons brown sugar","1 1/2 tablespoons soy sauce, reduced sodium","1 tablespoon minced ginger","1 tablespoon Dijon mustard","1 cup whole wheat couscous, dry","1 pound chicken breast, boneless, skinless (cut into 4 portions)","1 tablespoon olive oil","1/8 teaspoon salt","1/4 teaspoon pepper","1 sweet yellow onion, cut into wedges","2 large zucchini, cut into chunks","1 red pepper, cut into 8 strips","1 orange pepper, cut into 8 strips","8 pineapple spears (2-1/2 x 1-1/4 inch, about 1 ounce each)","1 green onion, sliced"]}],"directions":[{"name":null,"steps":["To make the glaze, combine pineapple juice, vinegar, brown sugar, soy sauce, ginger and mustard in a medium saucepan set over medium-high heat.","Bring to a boil; boil for about 15 minutes.","Preheat grill to medium heat. Cook couscous according to package directions.","While couscous is cooking, toss chicken breast with oil, salt and pepper.","Grill chicken, for 2 minutes per side or until grill-marked. Continue to grill, basting and turning with Pineapple Ginger Glaze, for 5 to 6 minutes or until cooked.","Grill onion, zucchini, red pepper, orange pepper and pineapple spears, basting with Pineapple Ginger Glaze, for 3 to 5 minutes or until grill-marked and tender.","Serve chicken with vegetables and pineapple over couscous.","Garnish with green onions."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"441.06 kcal","carbohydrateContent":"63.62 g","cholesterolContent":"75.06 mg","fiberContent":"5.20 g","proteinContent":"30.77 g","sodiumContent":"389.72 mg","sugarContent":"28.45 g","fatContent":"7.16 g","saturatedFatContent":"1.31 g"},"notes":"Serve with 8 ounces non-fat milk.","contributor":"Produce for Better Health Foundation"},
{"slug":"grilled-shrimp-cantaloupe-avocado-salsa","source_url":"https://www.myplate.gov/recipes/grilled-shrimp-cantaloupe-avocado-salsa","name":"Grilled Shrimp with Cantaloupe Avocado Salsa","description":"Savory sweet salsa featuring cantaloupe and avocado is the perfect complement to grilled shrimp.","ingredients":[{"name":"For the salsa","items":["1 lime (divided, half for salsa and half for garnish)","1 avocado, cubed","2 cups diced cantaloupe","1/4 cup chopped red onion","1 cup canned black beans, low sodium, drained and rinsed","1/4 teaspoon salt","1/8 teaspoon black pepper","2 tablespoons chopped fresh cilantro"]},{"name":"For the shrimp","items":["1 pound large or jumbo shrimp, uncooked","1 tablespoon canola oil","1 clove diced garlic","bamboo skewers"]}],"directions":[{"name":null,"steps":["Preheat grill.","Slice lime in half. In a small bowl, squeeze juice from one half of lime; reserve other half for garnish.","Add remaining salsa ingredients and gently mix.","Peel shrimp, leaving the tails on.","Skewer shrimp on bamboo skewers.","In a small dish mix together canola oil and garlic. Coat shrimp with oil-garlic mix.","Grill 4 to 5 minutes or until cooked.","To serve, top shrimp with salsa, garnish with lime wedges."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"247.12 kcal","carbohydrateContent":"22.41 g","cholesterolContent":"112.07 mg","fiberContent":"7.54 g","proteinContent":"17.35 g","sodiumContent":"363.11 mg","sugarContent":"7.11 g","fatContent":"10.25 g","saturatedFatContent":"1.36 g"},"notes":"Serve with 8 ounces non-fat milk and brown rice.","contributor":"Produce for Better Health"},
{"slug":"grilled-steak-and-peppers-salad-pears","source_url":"https://www.myplate.gov/recipes/grilled-steak-and-peppers-salad-pears","name":"Grilled Steak and Peppers Salad with Pears","description":"Grill whole bell peppers along with steak, then add pear slices, and you have the foundation of a delicious and colorful Italian-influenced salad.","ingredients":[{"name":null,"items":["2 cups white-wheat rotini pasta, uncooked (about 4 oz)","1 yellow bell pepper","1 red bell pepper","1/2 teaspoon olive oil","12 ounces boneless choice beef top sirloin","2 pears","3 cups arugula","1/4 cup crumbled Gorgonzola cheese"]},{"name":"For the vinaigrette","items":["1 tablespoon olive oil","3 tablespoons distilled vinegar","1/4 cup 100% white grape juice or apple juice","1/4 teaspoon salt (optional)","1 tablespoon Italian herb blend, salt-free"]}],"directions":[{"name":null,"steps":["In a small bowl, whisk olive oil, vinegar, grape or apple juice, salt, and herb blend.","Boil water and cook pasta according to package instructions. Drain pasta, rinse in cool water.","Heat grill, rub peppers with 1/2 tsp olive oil. Grill whole peppers, turning as needed, until skin begins to brown and bubble. At the same time, grill beef sirloin to 145 °F, turning once. Remove from grill, let cool slightly.","Slice peppers into strips, discarding seeds and stem. Cut sirloin across the grain into thin slices. Slice pears into thin wedges.","Toss arugula and pasta in large bowl.","To serve, evenly divide pasta-arugula onto four plates, arrange beef, peppers, and pears on top, drizzle with vinaigrette, and sprinkle with crumbled Gorgonzola cheese."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"443.42 kcal","carbohydrateContent":"58.86 g","cholesterolContent":"58.80 mg","fiberContent":"8.80 g","proteinContent":"29.11 g","sodiumContent":"305.52 mg","sugarContent":"14.22 g","fatContent":"11.72 g","saturatedFatContent":"3.67 g"},"notes":"Serving Suggestions: Serve with a glass of non-fat milk.","contributor":"Produce for Better Health Foundation"},
{"slug":"grilled-vegetable-packets","source_url":"https://www.myplate.gov/recipes/grilled-vegetable-packets","name":"Grilled Vegetable Packets","description":"Veggies are wrapped in foil and cooked on the grill for an easy side dish to your cookout. Don''t have a grill? This recipe can also be made in the oven.","ingredients":[{"name":null,"items":["2 small zucchinis (sliced)","2 small yellow squashes (sliced)","4 small red potatoes (scrubbed well and sliced)","1/2 red onion (sliced)","1/2 red or green bell pepper (sliced)","1/4 cup light Italian salad dressing","salt and pepper (optional, to taste)"]}],"directions":[{"name":null,"steps":["Heat grill to medium heat or 350 °F.","Wash vegetables and slice.","Toss in a large bowl. Add dressing and toss until all vegetables are coated.","Tear 2 large squares of aluminum foil and place half of the vegetable mixture on each piece. Place an equal piece of foil over the top of vegetable mixture and fold bottom piece with top sheet to form a packet.","Place on heated grill for 20 to 30 minutes or until the potatoes are tender. If you don''t have a grill, bake Veggie Packets in the oven at 400 °F for 20 to 30 minutes.","Before you open the packets, poke holes in the foil with a fork. Be very careful opening the foil as the steam will be very hot and could burn you!","Empty vegetables onto serving plate or serve from foil packets."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup (316g)","calories":"145.17 kcal","carbohydrateContent":"31.65 g","cholesterolContent":"0.23 mg","fiberContent":"4.56 g","proteinContent":"4.87 g","sodiumContent":"150.39 mg","sugarContent":"7.78 g","fatContent":"0.75 g","saturatedFatContent":"0.22 g"},"notes":"Try different vegetables: Tomatoes, green beans, sweet potatoes, mushrooms, broccoli, carrots, corn... or your favorites.\nBe Creative! Use herbs or spices in place of dressing: Chili power, Italian seasoning, basil, oregano, curry powder, or your favorite seasoning!","contributor":"Connecticut Food Policy Council"},
{"slug":"grilled-vegetables","source_url":"https://www.myplate.gov/recipes/grilled-vegetables","name":"Grilled Vegetables","description":"Cooking out tonight? Try cooking vegetables coated in oil and garlic on the grill for a delicious side dish. If you don''t have a grill, you can make these ve...","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil","2 garlic cloves (finely chopped)","3 sweet potatoes (cut into 1-inch slices)","3 corn cobs (cut into 2-inch sections)","1 eggplant (cut into 1/2-inch slices)","12 green onions (trimmed)"]}],"directions":[{"name":null,"steps":["Mix oil and garlic in a large bowl. Add vegetables and toss.","Place vegetable on broiler pan or grill. Cook 10 minutes, turning twice until vegetables are tender.","Place vegetables on platter. Serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (254g)","calories":"147.98 kcal","carbohydrateContent":"23.65 g","cholesterolContent":"0.00 mg","fiberContent":"3.95 g","proteinContent":"3.50 g","sodiumContent":"31.63 mg","sugarContent":"7.79 g","fatContent":"5.55 g","saturatedFatContent":"0.85 g"},"notes":null,"contributor":"US Department of Health and Human Services\nCenters for Disease Control and Prevention (CDC)"},
{"slug":"ground-beef-stew","source_url":"https://www.myplate.gov/recipes/ground-beef-stew","name":"Ground Beef Stew","description":"Ground beef and canned tomato soup make a tasty base for the vegetables in this delicious and hearty stew.","ingredients":[{"name":null,"items":["1/2 pound ground beef, or ground turkey, or venison (lean)","salt (optional, 1/8 teaspoon)","black pepper (optional, 1/8 teaspoon)","1 can tomato soup, condensed, low-sodium (10 1/2 ounces)","10 1/2 us fluid ounces water (one soup can full)","6 medium carrots (diced or sliced)","2 medium potatoes (diced or sliced)","1 cup onion (diced)"]}],"directions":[{"name":null,"steps":["Brown meat. Drain fat, if any. Season lightly with salt and pepper (optional).","Add soup and 1 can of water to fry pan. Add vegetables.","Bring to a boil, then simmer, covered, about 25 minutes or until tender. Remove from heat, cover for last 10 minutes to thicken.","Serve. Refrigerate leftovers."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared stew","1/4 of recipe (412g)"],"calories":"252.79 kcal","carbohydrateContent":"40.40 g","cholesterolContent":"32.86 mg","fiberContent":"5.91 g","proteinContent":"14.62 g","sodiumContent":"117.86 mg","sugarContent":"12.95 g","fatContent":"3.92 g","saturatedFatContent":"1.48 g"},"notes":null,"contributor":"Simply Good Eating Recipe Cards, Vol. 1, 2000\nUniversity of Minnesota Cooperative Extension Service"},
{"slug":"harvest-vegetable-salad","source_url":"https://www.myplate.gov/recipes/harvest-vegetable-salad","name":"Harvest Vegetable Salad","description":"Chili powder and lime juice provide a zesty dressing to this salad, which is full of root vegetables.","ingredients":[{"name":null,"items":["2 cups romaine lettuce (washed)","1 cup cilantro leaves (washed)","1 cup parsnips (peeled)","1 cup carrots (peeled)","1 cup turnips (peeled)"]},{"name":"Dressing","items":["1/4 cup lime juice","1/2 teaspoon lime zest (grated)","1 teaspoon sugar","1/4 teaspoon chili powder","1 tablespoon olive oil"]}],"directions":[{"name":null,"steps":["Combine romaine lettuce and cilantro, and divide onto four plates.","Place parsnips, carrots, and turnips into 1 quart of boiling water. Return water to a simmer, cook vegetables for 2 minutes. Strain into a colander.","Mix ingredients for the dressing right before use.","Place hot vegetables on top of greens and top with homemade dressing."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (145g)","calories":"86.71 kcal","carbohydrateContent":"13.13 g","cholesterolContent":"0.00 mg","fiberContent":"3.16 g","proteinContent":"1.34 g","sodiumContent":"42.35 mg","sugarContent":"5.40 g","fatContent":"3.81 g","saturatedFatContent":"0.58 g"},"notes":null,"contributor":"5 A Day: Eat 5 to 9 Fruits and Vegetables\nUS Department of Health and Human Services\nCenters for Disease Control and Prevention (CDC)\nNational Center for Chronic Disease Prevention and Health Promotion"},
{"slug":"healthy-black-bean-soup","source_url":"https://www.myplate.gov/recipes/healthy-black-bean-soup","name":"Healthy Black Bean Soup","description":"This soup is full of flavor and is so easy to prepare. Using canned beans and salsa, along with cumin and cilantro, this soup is a great way to throw dinner ...","ingredients":[{"name":null,"items":["2 cans (15.5 ounces each) low-sodium black beans, drained and rinsed","2 cups low-sodium chicken broth (or low-sodium vegetable broth)","1 cup fresh salsa","1 teaspoon ground cumin","4 tablespoons low-fat sour cream (or fat-free)","2 tablespoons fresh cilantro, chopped"]}],"directions":[{"name":null,"steps":["Lightly purée one can of black beans with broth, salsa, and cumin in a blender.","In a medium saucepan, combine puréed bean mixture with remaining beans and heat through.","To serve, ladle soup into 4 bowls.","Top each bowl with one tablespoon of sour cream and garnish with the cilantro."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"255.25 kcal","carbohydrateContent":"42.13 g","cholesterolContent":"5.25 mg","fiberContent":"15.93 g","proteinContent":"16.75 g","sodiumContent":"428.75 mg","sugarContent":"2.43 g","fatContent":"3.23 g","saturatedFatContent":"1.41 g"},"notes":null,"contributor":"Adapted from \"Easy and Healthy Black Bean Soup\"\nBronson Wellness Center\nBronson Healthcare - Michigan"},
{"slug":"hearty-beef-soup","source_url":"https://www.myplate.gov/recipes/hearty-beef-soup","name":"Hearty Beef Soup","description":"This tasty and satisfying soup can be served for lunch or dinner. The leftovers can be frozen for later.","ingredients":[{"name":null,"items":["1/4 pound beef round roast, chopped","1 tablespoon vegetable oil","3 cups water","2 cups winter squash, chopped (or 2 cups cabbage, finely chopped)","1/2 cup onions, chopped","1 celery stalk, finely chopped","1 teaspoon garlic, finely chopped","1/2 teaspoon dried oregano","1 tablespoon parsley, chopped (optional)","1/4 cup macaroni, dry","1 large tomato, chopped (or 15-ounce can low-sodium diced tomatoes)","1/2 cup green pepper, finely chopped","1/2 teaspoon salt","1/2 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["In a large pot, brown beef in oil over medium to high heat for 8 to 10 minutes. Drain fat.","Add water, squash, onion, celery, garlic, and oregano. If using parsley, add that too. Mix well.","Bring pot to a boil. Lower heat and cook for 20 minutes.","Add macaroni, tomatoes, green pepper, salt, and pepper.","Keep cooking over low heat for 20 minutes. Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"82.60 kcal","carbohydrateContent":"8.73 g","cholesterolContent":"11.66 mg","fiberContent":"1.96 g","proteinContent":"5.33 g","sodiumContent":"220.65 mg","sugarContent":"2.84 g","fatContent":"3.19 g","saturatedFatContent":"0.62 g"},"notes":"Tip for cooking beef roast: The recommended safe minimum internal temperature for beef roast is 145 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"hearty-mashed-potatoes","source_url":"https://www.myplate.gov/recipes/hearty-mashed-potatoes","name":"Hearty Mashed Potatoes","description":"Turn ordinary mashed potatoes up a notch with garbanzo beans for extra protein and fiber!","ingredients":[{"name":null,"items":["4 potatoes (baking, peeled and cut in chunks, about 2 pounds)","1 can garbanzo beans, low-sodium (15 ounce, drained)","1/2 cup milk, non-fat (or fortified soy milk)","1/4 cup Parmesan cheese","1/2 teaspoon garlic powder","black pepper (to taste)"]}],"directions":[{"name":null,"steps":["Place the potatoes in a large sauce pan and cover with water. Bring to a boil over high heat then reduce to a simmer.","Add the garbanzo beans 10 minutes after potatoes start cooking. Continue cooking until potatoes are fork tender, about 20 minutes.","Drain water and place the sauce pan back on the stove. Mash the beans and potatoes using a potato masher or hand beaters.","Add the milk, cheese and seasonings.","Reheat if necessary. Serve hot."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared potatoes","1/6 of recipe (247g)"],"calories":"193.40 kcal","carbohydrateContent":"35.61 g","cholesterolContent":"3.48 mg","fiberContent":"5.79 g","proteinContent":"8.22 g","sodiumContent":"163.70 mg","sugarContent":"4.31 g","fatContent":"2.56 g","saturatedFatContent":"0.74 g"},"notes":null,"contributor":"Food and Health Communications, Inc."},
{"slug":"hearty-mexican-soup","source_url":"https://www.myplate.gov/recipes/hearty-mexican-soup","name":"Hearty Mexican Soup","description":"Easy to make and delicious to eat, this soup can be made in under an hour! Squeeze the other half of the lime over the soup before serving for extra flavor. ...","ingredients":[{"name":null,"items":["1 onion (small, chopped)","4 cloves garlic (minced)","1 can tomatoes, diced, low-sodium (14.5 ounce can)","2 cans black beans, low-sodium (15 ounce can, low sodium, drained and rinsed)","2 potatoes (large, peeled and diced)","4 cups water","1/2 cup cilantro (fresh, chopped)","1/2 lime (squeezed)","1/8 teaspoon cumin powder (a pinch)"]}],"directions":[{"name":null,"steps":["In a large pot cook onion, garlic and tomatoes on medium-high heat for 3 minutes. Stir often.","Add beans, potatoes and water. Bring to a boil, then reduce to low-medium heat. Cover and continue to cook slowly for 20 minutes.","Add cilantro, cumin and lime. Stir and continue to simmer for 10 minutes.","Serve warm; sprinkle cilantro on top."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of the recipe","calories":"249.46 kcal","carbohydrateContent":"49.48 g","cholesterolContent":"0.00 mg","fiberContent":"15.46 g","proteinContent":"13.18 g","sodiumContent":"260.35 mg","sugarContent":"4.67 g","fatContent":"0.85 g","saturatedFatContent":"0.20 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"hearty-salmon-skewers-over-brown-rice","source_url":"https://www.myplate.gov/recipes/hearty-salmon-skewers-over-brown-rice","name":"Hearty Salmon Skewers over Brown Rice","description":"Created for junior chefs, this simple and delicious recipe skewers just three ingredients -- omega-3-rich salmon, cherry tomatoes, and pineapple -- for a qui...","ingredients":[{"name":null,"items":["1 pound salmon","kosher salt, freshly ground pepper, and paprika (to taste)","3 cherry tomatoes (about 2 ounces)","1 cup pineapple, cubed","2 cups cooked brown rice","1 lemon, raw","skewers"]}],"directions":[{"name":null,"steps":["Cook rice according to package instructions and set aside.","Cut salmon into 24 1/2-inch cubes and coat all sides with topping of kosher salt, freshly ground pepper, paprika, or any desired spice.","Cut fruit into cubes and cut tomatoes in half. Set aside.","Slide piece of salmon onto skewer, then tomato, then fruit. Repeat 3 times on each skewer (or until skewer is full).","Heat 1/2 cup of canola oil in large skillet over medium-high heat for one minute.","Place skewers in pan and turn every 2 minutes per side. Squeeze lemon on skewers as they are cooking.","To serve, place 1/2 cup rice on plates and with 2 skewers on top. Squeeze a hint of lemon, if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 skewers","1/2 cup brown rice"],"calories":"345.41 kcal","carbohydrateContent":"32.25 g","cholesterolContent":"60.73 mg","fiberContent":"2.68 g","proteinContent":"24.48 g","sodiumContent":"64.80 mg","sugarContent":"4.97 g","fatContent":"12.96 g","saturatedFatContent":"2.58 g"},"notes":"Salmon skewers can be made in the oven or on the grill.\nCovering them while on the stove will steam them rather than sear them.","contributor":"Seafood Nutrition Partnership"},
{"slug":"hearty-vegetable-beef-soup","source_url":"https://www.myplate.gov/recipes/hearty-vegetable-beef-soup","name":"Hearty Vegetable Beef Soup","description":"Frozen vegetables, canned tomatoes, and chicken broth make this an easy soup to throw together on a cold work night. Noodles and beef make it extra hearty an...","ingredients":[{"name":null,"items":["3/4 can chicken broth, low-sodium (low sodium, 14.5 oz)","1/2 cup water","2 cups mixed vegetables (frozen, for soup)","1 can tomatoes, low-sodium (14.5 oz, broken up)","4 ounces beef (cooked and diced)","1 teaspoon thyme leaves (crushed)","1 dash black pepper","1/4 teaspoon salt","1 bay leaf","1 1/4 cups noodles (narrow-width, uncooked)"]}],"directions":[{"name":null,"steps":["Heat broth and water. Add vegetables, meat, and seasonings. Bring to boil. Reduce heat and boil gently, uncovered, for 15 minutes.","Add noodles. Cook until noodles are tender, about 10 minutes","Remove bay leaf. Serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/4 of recipe"],"calories":"177.42 kcal","carbohydrateContent":"24.33 g","cholesterolContent":"27.55 mg","fiberContent":"6.45 g","proteinContent":"11.57 g","sodiumContent":"227.29 mg","sugarContent":"5.66 g","fatContent":"4.35 g","saturatedFatContent":"1.45 g"},"notes":null,"contributor":"North Dakota State University Extension Service"},
{"slug":"hearty-vegetable-salad-herb-dressing","source_url":"https://www.myplate.gov/recipes/hearty-vegetable-salad-herb-dressing","name":"Hearty Vegetable Salad with Herb Dressing","description":"Make this vegetable salad ahead of time and allow the flavors to blend in the refrigerator for a few hours before serving.","ingredients":[{"name":null,"items":["3 cups cauliflower florets (fresh or frozen, thawed)","2 cups broccoli florets (fresh or frozen, thawed)","1 can red kidney beans, low-sodium (15 1/2 ounce, drained)","2 carrots, sliced diagonally (medium)","1 cup olives, large pitted (sliced)","2 green onion (sliced)","1/4 cup red wine vinegar","1/4 cup vegetable oil (or olive oil)","1 tablespoon cilantro or parsley (chopped)","1 clove garlic (minced)","1 teaspoon sugar","dried basil (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["In large bowl, combine all salad ingredients.","In a small jar with a tight fitting lid, combine all dressing ingredients and shake well.","Pour dressing over vegetables and stir to coat vegetables. Cover; refrigerate 1 to 4 hours to marinate, tossing occasionally."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/8 of recipe (170g)"],"calories":"157.75 kcal","carbohydrateContent":"15.04 g","cholesterolContent":"0.00 mg","fiberContent":"5.08 g","proteinContent":"4.61 g","sodiumContent":"220.22 mg","sugarContent":"3.48 g","fatContent":"9.28 g","saturatedFatContent":"1.48 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"heavenly-deviled-eggs","source_url":"https://www.myplate.gov/recipes/heavenly-deviled-eggs","name":"Heavenly Deviled Eggs","description":"Versatile and easy to prepare, these deviled eggs are great as an appetizer, side dish, or snack.","ingredients":[{"name":null,"items":["6 eggs (in shell)","2 tablespoons light mayonnaise","1 teaspoon mustard"]}],"directions":[{"name":null,"steps":["Put eggs into a saucepan. Cover with cold water.","Bring eggs to a simmer (small bubbles) and cook for 12 minutes.","Remove from the heat and drain.","Crack eggs under cold water and allow to cool. Remove shells.","Split eggs in half lengthwise and remove yolks.","Put yolks, dressing and mustard into a small zipper-lock plastic bag to mix. Cut a small hole in a lower corner of the bag.","Squeeze mixture into egg white halves. Garnish as desired."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 prepared egg halves","1/6 of recipe"],"calories":"84.45 kcal","carbohydrateContent":"1.00 g","cholesterolContent":"206.33 mg","fiberContent":"0.04 g","proteinContent":"6.25 g","sodiumContent":"116.67 mg","sugarContent":"0.30 g","fatContent":"6.16 g","saturatedFatContent":"1.78 g"},"notes":"Garnishes: paprika, cayenne pepper (if you like it hot), pickle relish, sliced scallions, sliced green or black olives.\n1/8 teaspoon each of salt and pepper may be substituted for 1 teaspoon of mustard.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"herb-broiled-beef","source_url":"https://www.myplate.gov/recipes/herb-broiled-beef","name":"Herb Broiled Beef","description":"Prepare this marinated beef the night before, and have dinner on the table in less than half an hour!","ingredients":[{"name":null,"items":["1/4 cup onion, chopped","2 tablespoons parsley","2 tablespoons white vinegar","3 teaspoons prepared mustard","1/4 teaspoon garlic powder","1/4 teaspoon basil, dried (or thyme)","1 pound boneless beef chuck shoulder steak, cut 1-inch thick"]}],"directions":[{"name":null,"steps":["Mix onion, parsley, vinegar, mustard, garlic powder, and basil or thyme.","Place meat in plastic bag and pour in marinade.","Close bag securely, place in a bowl and marinate in refrigerator six to eight hours or overnight, turning at least once.","Pour off marinade and discard. Place meat on rack in broiler.","Broil 15 to 20 minutes or until desired doneness, turning once.","Cut into thin slices to serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (134g)","calories":"193.11 kcal","carbohydrateContent":"1.42 g","cholesterolContent":"73.89 mg","fiberContent":"0.44 g","proteinContent":"21.13 g","sodiumContent":"88.94 mg","sugarContent":"0.69 g","fatContent":"11.42 g","saturatedFatContent":"4.47 g"},"notes":null,"contributor":"Eat for Health Toolkit\nRecipe by Missouri Nutrition Network"},
{"slug":"herb-potato-salad","source_url":"https://www.myplate.gov/recipes/herb-potato-salad","name":"Herb Potato Salad","description":"Dried herbs and spices make this zesty side dish a family favorite!","ingredients":[{"name":null,"items":["1/4 tablespoon salt","5 small potatoes (1 pound)","radish (1/2 sliced, optional)","1/2 teaspoon basil (dried)","1/4 teaspoon thyme (dried)","1/4 teaspoon onion powder","3 tablespoons yogurt, non-fat plain","1 tablespoon mayonnaise, reduced calorie","1 1/2 teaspoons prepared mustard","1/2 teaspoon garlic (chopped)"]}],"directions":[{"name":null,"steps":["Scrub potatoes and cut into cubes.","Place in medium saucepan and cover with water. Bring to a boil.","Cover, reduce heat, and simmer 12 minutes or until potatoes are done. Drain.","Mix dressing ingredients.","Combine hot potatoes, dressing, radishes, basil, thyme, and onion powder. Serve hot or cold."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (145g)","calories":"179.87 kcal","carbohydrateContent":"38.09 g","cholesterolContent":"0.85 mg","fiberContent":"4.02 g","proteinContent":"5.16 g","sodiumContent":"522.52 mg","sugarContent":"3.11 g","fatContent":"1.19 g","saturatedFatContent":"0.21 g"},"notes":"The mustard and seasoning make this a tasty potato salad. Try using new red potatoes for added color.","contributor":"University of Nebraska Recipe Collection\nStaff from the University of Nebraska-Lincoln Cooperative Extension"},
{"slug":"herb-spinach-bake","source_url":"https://www.myplate.gov/recipes/herb-spinach-bake","name":"Herb Spinach Bake","description":"This recipe is a quick and easy way to use up leftover brown rice!","ingredients":[{"name":null,"items":["1 cup spinach (15.5 ounce can)","2 cups cooked brown rice","3/4 cup cheddar cheese, low-fat shredded","2/3 cup milk, 1%","3 tablespoons butter, soft (or margarine)","salt (1 teaspoon, optional)","1/2 teaspoon Worcestershire sauce","1/2 teaspoon Thyme, dried","1/4 cup onion, diced"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Wash hands with soap and water.","Drain canned spinach to remove liquid.","Combine spinach with remaining ingredients in a large bowl.","Add to a 8x8 inch baking dish. You may also use a 9x3 inch baking dish, but the spinach bake will be thinner.","Cover with foil and bake for 20 minutes.","Uncover and bake an additional 5 minutes, or until set."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (145g)","calories":"148.91 kcal","carbohydrateContent":"15.29 g","cholesterolContent":"20.52 mg","fiberContent":"1.55 g","proteinContent":"5.79 g","sodiumContent":"168.25 mg","sugarContent":"1.52 g","fatContent":"7.29 g","saturatedFatContent":"4.29 g"},"notes":"Milk can be substituted with 4 tablespoons dry milk + 2/3 cup water.","contributor":"Food Bank of Delaware"},
{"slug":"herbed-dip","source_url":"https://www.myplate.gov/recipes/herbed-dip","name":"Herbed Dip","description":"A creamy, savory, dip that can be prepared in under 5 minutes! Enjoy!","ingredients":[{"name":null,"items":["1 cup cottage cheese, low-fat","4 tablespoons yogurt, low-fat plain (1/4 cup)","1 tablespoon onion (chopped, or chives)","1 teaspoon parsley (dried)","1/4 teaspoon dill (dried)"]}],"directions":[{"name":null,"steps":["Place all the ingredients in a blender.","Blend all the ingredients thoroughly.","Pour the mixture into a clean container.","Cover and chill."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe (29g)","calories":"22.98 kcal","carbohydrateContent":"1.53 g","cholesterolContent":"3.08 mg","fiberContent":"0.03 g","proteinContent":"2.83 g","sodiumContent":"77.12 mg","sugarContent":"1.42 g","fatContent":"0.62 g","saturatedFatContent":"0.35 g"},"notes":"Serve on crackers, or as dip for fresh raw vegetables.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"herbed-lentils-and-rice-casserole","source_url":"https://www.myplate.gov/recipes/herbed-lentils-and-rice-casserole","name":"Herbed Lentils and Rice Casserole","description":"Lentils and brown rice are combined with flavorful herbs and onions and topped with cheese for a delicious side dish.","ingredients":[{"name":null,"items":["2 2/3 cups low-sodium chicken broth","3/4 cup dry lentils (sorted and rinsed)","3/4 cup onion (chopped)","1/2 cup brown rice (dry)","1/4 cup water","1/2 teaspoon basil (fresh or dried)","1/2 teaspoon oregano","1/2 teaspoon thyme","1/2 cup part-skim mozzarella cheese (divided)"]}],"directions":[{"name":null,"steps":["Preheat over to 350 °F","In a 2 1/2 quart casserole dish add the chicken broth, lentils, onions, brown rice, water, spices, and 1/4 cup mozzarella cheese.","Stir to combine.","Cover with foil and bake at 350 °F for 2 hours,","Check casserole after 1 hour and add more broth if it seems dry.","Remove foil and top with remaining cheese.","Bake another 2 or 3 minutes until all the cheese is melted."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"296.32 kcal","carbohydrateContent":"46.43 g","cholesterolContent":"9.18 mg","fiberContent":"10.25 g","proteinContent":"18.47 g","sodiumContent":"154.44 mg","sugarContent":"3.81 g","fatContent":"5.05 g","saturatedFatContent":"2.22 g"},"notes":null,"contributor":"The Bold and Beautiful Book of Bean Recipes - Washington State WIC Program\nOriginal name - Kelly''s Herbed Lentils and Rice Casserole"},
{"slug":"herbed-spinach-quiche-portabella-caps","source_url":"https://www.myplate.gov/recipes/herbed-spinach-quiche-portabella-caps","name":"Herbed Spinach Quiche Portabella Caps","description":"Here''s a savory, healthful, time-saving twist to breakfast quiche. Use portabella mushroom caps instead of high-fat pie pastry to make individual quiches.","ingredients":[{"name":null,"items":["4 portabella mushrooms (3-inch diameter)","cooking spray","3 large eggs","6 egg whites","1/2 cup bread crumbs (whole-wheat if available)","1/4 cup nonfat milk","1 teaspoon low-sodium garlic & herb blend","1 cup frozen chopped spinach, cooked and drained","1/4 cup reduced-fat Parmesan cheese, divided"]}],"directions":[{"name":null,"steps":["Place oven rack in center of oven; preheat oven to 375 °F.","Remove portabella stems; wipe clean with damp paper towel.","Spray baking sheet with cooking spray, and place mushroom caps on baking sheet.","In a mixing bowl, whisk together all remaining ingredients, except 1 tbsp Parmesan cheese.","Coat 10-inch non-stick pan with cooking spray and heat over medium flame.","Cook and scramble egg mixture until it just starts to thicken. Remove from heat.","Using a large spoon, scoop partially cooked, hot egg mixture into portabella caps.","Sprinkle tops with remaining Parmesan cheese. Bake about 20 minutes.","Serve immediately."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"199.18 kcal","carbohydrateContent":"18.89 g","cholesterolContent":"158.16 mg","fiberContent":"3.88 g","proteinContent":"18.63 g","sodiumContent":"389.94 mg","sugarContent":"3.67 g","fatContent":"6.36 g","saturatedFatContent":"2.11 g"},"notes":"Serving Suggestions: Serve with strawberries and orange slices (or other fresh, frozen, or canned fruit), water with lime or lemon slice or wedge.","contributor":"Produce for Better Health Foundation"},
{"slug":"herbed-vegetables","source_url":"https://www.myplate.gov/recipes/herbed-vegetables","name":"Herbed Vegetables","description":"Serve this savory side dish with your favorite entree. This recipe can be made in minutes!","ingredients":[{"name":null,"items":["2 cups vegetables (any combination of fresh, frozen, or canned)","1/4 cup onion (chopped)","1/2 teaspoon Italian herbs, basil, or rosemary (dried, crushed)","1 tablespoon margarine or butter"]}],"directions":[{"name":null,"steps":["If using canned (low-sodium) vegetables, drain, saving 2 tablespoons liquid.","Cook onion, herbs, and garlic in the margarine/ butter in a small saucepan until onion is tender.","Stir in the vegetables and liquid or add water as needed.","Cook and stir until heated through."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"54.23 kcal","carbohydrateContent":"8.47 g","cholesterolContent":"0.02 mg","fiberContent":"2.76 g","proteinContent":"1.79 g","sodiumContent":"37.21 mg","sugarContent":"2.15 g","fatContent":"1.49 g","saturatedFatContent":"0.30 g"},"notes":null,"contributor":"Quick and Healthy Meals: Tips and Tools for Planning Meals for Your Family\nOhio State University Cooperative Extension\nCuyahoga County"},
{"slug":"hiding-rabbits","source_url":"https://www.myplate.gov/recipes/hiding-rabbits","name":"Hiding Rabbits","description":"A cute and easy way to get kids excited about eating their veggies!","ingredients":[{"name":null,"items":["2 celery stalks (each piece cut in half lengthwise)","4 small cauliflower florets (cut in half)","2 tablespoons peanut butter"]}],"directions":[{"name":null,"steps":["Place one piece of celery in center of plate with the center facing up.","Use a butter knife to spread peanut butter on top edges.","Place second piece of celery on top, forming a log. Cut log in half.","Repeat steps 1-3 with remaining 2 pieces of celery.","Place cauliflower florets on ends of each log, securing with remaining peanut butter.","Enjoy your Hiding Rabbits."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 hiding rabbit","calories":"114.34 kcal","carbohydrateContent":"6.05 g","cholesterolContent":"0.00 mg","fiberContent":"1.93 g","proteinContent":"4.38 g","sodiumContent":"108.44 mg","sugarContent":"2.71 g","fatContent":"8.32 g","saturatedFatContent":"1.67 g"},"notes":"Adults: If this recipe is being prepared by children, use a sharp knife to cut off the ends of celery, cut each celery stalk in half, and cut the cauliflower floret in half.","contributor":"Eagle Adventure Recipes\nChickasaw Nation Get Fresh! Nutrition Education Program\nEagle Adventure Team"},
{"slug":"homemade-bagels","source_url":"https://www.myplate.gov/recipes/homemade-bagels","name":"Homemade Bagles","description":"Did you know that you can make your own fresh, delicious, whole-grain rich bagels at home? This recipe makes enough to share with family and friends, or to f...","ingredients":[{"name":null,"items":["2 tablespoons sugar","1 tablespoon yeast","1 1/2 cups warm water","2 cups whole wheat flour","1 1/4 cups all-purpose flour","1 teaspoon canola oil (or cooking oil of your choice)","cinnamon (optional)","sugar (optional)","salt (optional)"]}],"directions":[{"name":null,"steps":["In a bowl mix sugar, yeast, water, and flours together to make dough.","Rub inside of another bowl with oil. Place dough in bowl and flip to coat with oil. Let rise 30 minutes.","Punch down dough and divide into 16 portions. Shape into a ball and poke a hole through the middle with your fingers.","Place on a well-greased baking sheet and cover with a clean dish towel to rise again for 15 to 20 minutes.","Put 2 inches of water in a pot and heat to boiling.","Using a slotted spoon, gently place each bagel into a rapidly boiling water for 1 minute on each side.","Remove and dry on a towel.","Place back on baking sheet. If desired, sprinkle bagels with cinnamon/sugar or salt.","Bake at 475 °F for 8 to 12 minutes."]}],"yield":"16 Bagels","nutrition":{"@type":"NutritionInformation","servingSize":"1 bagel","calories":"97.88 kcal","carbohydrateContent":"20.11 g","cholesterolContent":"0.00 mg","fiberContent":"2.07 g","proteinContent":"3.29 g","sodiumContent":"1.79 mg","sugarContent":"1.65 g","fatContent":"0.82 g","saturatedFatContent":"0.11 g"},"notes":null,"contributor":"Originally named \"Yummy Bagels\" Adapted from: Cooking For You or Two\nUniversity of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"homemade-cranberry-sauce","source_url":"https://www.myplate.gov/recipes/homemade-cranberry-sauce","name":"Homemade Cranberry Sauce","description":"A tangy and flavorful cranberry sauce that can be prepared in a flash!","ingredients":[{"name":null,"items":["3 cups fresh cranberries (12 ounces, can also use frozen)","1 orange","1 cup sugar"]}],"directions":[{"name":null,"steps":["Peel orange and remove seeds.","Place all ingredients in a blender and blend until mixed well.","Heat up and serve over turkey.","For thicker sauce to do not blend just heat and serve."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"127.13 kcal","carbohydrateContent":"31.67 g","cholesterolContent":"0.00 mg","fiberContent":"1.77 g","proteinContent":"0.35 g","sodiumContent":"1.77 mg","sugarContent":"28.28 g","fatContent":"0.16 g","saturatedFatContent":"0.01 g"},"notes":"1 cup white grape juice concentrate can be substituted for 1 cup sugar.","contributor":"Utah State University Cooperative Extension"},
{"slug":"homemade-mashed-potatoes","source_url":"https://www.myplate.gov/recipes/homemade-mashed-potatoes","name":"Homemade Mashed Potatoes","description":"A creamy comfort food that is quick and easy to prepare!","ingredients":[{"name":null,"items":["2 pounds potatoes (6 medium)","1 cup low-fat milk","3 tablespoons margarine or butter","1 teaspoon salt","1/2 teaspoon black pepper (ground)"]}],"directions":[{"name":null,"steps":["Peel the potatoes, and cut them into chunks.","Put the potatoes in a medium saucepan with enough water to cover them.","Cook the potatoes on medium heat for 15 minutes or until tender.","Remove the potatoes from the heat. Drain the water off the potatoes.","Mash the potatoes with a fork or potato masher.","Stir in enough milk to make the potatoes smooth and creamy.","Add the butter, salt and pepper."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared potatoes","1/8 of recipe (151g)"],"calories":"136.93 kcal","carbohydrateContent":"21.09 g","cholesterolContent":"1.53 mg","fiberContent":"2.07 g","proteinContent":"3.35 g","sodiumContent":"355.92 mg","sugarContent":"2.60 g","fatContent":"4.65 g","saturatedFatContent":"1.00 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"homemade-pizza-crust","source_url":"https://www.myplate.gov/recipes/homemade-pizza-crust","name":"Homemade Pizza Crust","description":"Enjoy the freshness of a homemade pizza crust and enjoy the delicious aromas that fill your kitchen as it bakes!","ingredients":[{"name":null,"items":["1 teaspoon rapid rise yeast","1/2 cup lukewarm water","1/4 teaspoon salt","1 teaspoon oil","1 cup bread flour (approximately)"]}],"directions":[{"name":null,"steps":["Mix yeast, water, salt, and oil. Add about 1 cup flour to make a stiff dough. The amount of flour may vary slightly.","Knead the dough until it is very elastic (will stretch and not make a hole).","Use a rolling pin or clean bottle to obtain even thickness.","Lay it on a greased baking sheet to rise while you prepare toppings for pizza.","Bake at 400 °F with desired toppings until crust is browned and top is bubbly."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"137.39 kcal","carbohydrateContent":"25.25 g","cholesterolContent":"0.00 mg","fiberContent":"1.09 g","proteinContent":"4.51 g","sodiumContent":"149.94 mg","sugarContent":"0.11 g","fatContent":"1.81 g","saturatedFatContent":"0.25 g"},"notes":"Pizza can be topped with sauce, mozzarella cheese, vegetables, and cooked meats.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"homemade-ranch-dressing","source_url":"https://www.myplate.gov/recipes/homemade-ranch-dressing","name":"Homemade Ranch Dressing","description":"What’s better than ranch dressing? Fresh, homemade ranch dressing! It’s the perfect addition to your salad, veggies, or just about anything you can dip! ...","ingredients":[{"name":null,"items":["2 teaspoons dried, minced onions","1/2 teaspoon salt","1/8 teaspoon garlic powder","1 tablespoon dried parsley","1 cup Greek yogurt, plain, fat-free","1 cup buttermilk"]}],"directions":[{"name":null,"steps":["Collect and measure all ingredients before starting to prepare the recipe.","Add the dried onion, salt, garlic powder, and dried parsley to a bowl, and stir gently to combine.","Add the Greek yogurt and buttermilk, and stir until spices are evenly distributed.","Chill before serving.","Keep leftovers refrigerated, and eat within 1 week."]}],"yield":"16 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 Tablespoons","calories":"19.37 kcal","carbohydrateContent":"1.49 g","cholesterolContent":"2.44 mg","fiberContent":"0.04 g","proteinContent":"2.11 g","sodiumContent":"95.79 mg","sugarContent":"1.31 g","fatContent":"0.57 g","saturatedFatContent":"0.31 g"},"notes":"Be creative! To make a thicker ranch dip, substitute another cup of plain Greek yogurt for the buttermilk.","contributor":"Eating Smart, Being Active\nColorado State University"},
{"slug":"homestyle-biscuits","source_url":"https://www.myplate.gov/recipes/homestyle-biscuits","name":"Homestyle Biscuits","description":"Light and flaky biscuits make excellent additions to holiday meals and family gatherings.","ingredients":[{"name":null,"items":["2 cups flour (all purpose)","2 teaspoons baking powder","1/4 teaspoon baking soda","1/4 teaspoon salt","2 tablespoons sugar","2/3 cup buttermilk (low-fat)","3 1/3 tablespoons vegetable oil"]}],"directions":[{"name":null,"steps":["Preheat oven to 450 °F.","In medium bowl, combine flour, baking powder, baking soda, salt, and sugar.","In small bowl, stir together buttermilk and oil. Pour over flour mixture and stir until well mixed.","On lightly floured surface, knead dough gently for 10 to 12 strokes. Roll or pat dough to ¾-inch thickness. Cut with a 2-inch round biscuit or cookie cutter, dipping cookie cutter in flour between cuts. Transfer biscuits to an ungreased baking sheet.","Bake for 12 minutes or until golden brown. Serve warm."]}],"yield":"15 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 biscuit (33g)","calories":"100.02 kcal","carbohydrateContent":"15.07 g","cholesterolContent":"0.44 mg","fiberContent":"0.45 g","proteinContent":"2.08 g","sodiumContent":"141.88 mg","sugarContent":"2.29 g","fatContent":"3.39 g","saturatedFatContent":"0.52 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"honey-baked-lentils","source_url":"https://www.myplate.gov/recipes/honey-baked-lentils","name":"Honey Baked Lentils","description":"This sweet and savory entree is packed with fiber, protein, and potassium!","ingredients":[{"name":null,"items":["2 cups lentils (uncooked, 1 pound)","bay leaf (1 small, optional)","5 cups water","1 cup carrots (chopped)","1/2 cup onions (chopped)","1 cup water","1/2 pound ground beef (90% lean)","1/3 cup honey*","1 teaspoon herbs (fresh or dried)"]}],"directions":[{"name":null,"steps":["Combine rinsed lentils, bay leaf, and 5 cups water in a large saucepan. Bring to a boil. Cover tightly and reduce heat. Simmer 30 minutes. Do not drain. After cooking, discard bay leaf.","Chop onion. Combine onions and carrots with 1 cup water. Add to lentils and stir into a 9x13 inch baking dish.","Brown ground beef (if using). Drain and discard fat. Add the meat to the lentil mixture.","Pour honey over entire casserole.","Add herbs if desired.","Cover tightly with foil and bake it for one hour at 350 °F."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/7 of recipe"],"calories":"287.43 kcal","carbohydrateContent":"47.25 g","cholesterolContent":"18.78 mg","fiberContent":"13.34 g","proteinContent":"20.30 g","sodiumContent":"41.10 mg","sugarContent":"16.53 g","fatContent":"3.05 g","saturatedFatContent":"1.03 g"},"notes":"* Children under the age of one should not consume honey.\nReplace 1 cup water with 2 tablespoons sugar, 1 teaspoon oregano, and 2 cups tomato sauce.\nOmit the ground beef for a meatless meal that is lower in calories and fat.","contributor":"Michigan State University Cooperative Extension Service"},
{"slug":"honey-glazed-turnips","source_url":"https://www.myplate.gov/recipes/honey-glazed-turnips","name":"Honey Glazed Turnips","description":"Cook turnips and honey on the stove to create an easy and healthy side dish for dinner.","ingredients":[{"name":null,"items":["3 turnips, medium, about 1 1/2 pounds (sliced or cubed)","2 tablespoons honey*","2 tablespoons canola oil","1/4 cup water","salt (1/4 teaspoon, to taste)","black pepper (1/4 teaspoon, to taste)"]}],"directions":[{"name":null,"steps":["Peel turnips.","Slice or cube turnips, 1/2 inch pieces.","In a medium saucepan, combine honey, canola oil and water and bring to a boil.","Add turnips, salt and black pepper, cover and bring to a boil.","Reduce to simmer and cook for about 10 minutes.","Uncover and continue to cook until turnips are golden and glazed, about 10 minutes."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"112.21 kcal","carbohydrateContent":"12.57 g","cholesterolContent":"0.00 mg","fiberContent":"1.73 g","proteinContent":"0.64 g","sodiumContent":"14.68 mg","sugarContent":"10.77 g","fatContent":"7.07 g","saturatedFatContent":"0.47 g"},"notes":"* Children under the age of one should not consume honey.","contributor":"Penn State Extension\nNutrition Links Program"},
{"slug":"honey-lemon-chicken","source_url":"https://www.myplate.gov/recipes/honey-lemon-chicken","name":"Honey Lemon Chicken","description":"Honey adds sweetness to this tangy chicken dish. Enjoy with a side of steamed vegetables and brown rice.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1 pound chicken (cut into 8 pieces)","1/2 cup flour (all purpose)","1 teaspoon salt","1/4 cup honey*","1/4 cup lemon juice","1 teaspoon rosemary (fresh or dried)"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F. Line a baking pan with foil for easy clean up. Lightly oil the foil.","Combine flour and salt in a plastic bag. Shake chicken pieces in flour mixture, remove from bag and place on prepared pan.","Bake for 45 minutes.","Combine honey, lemon, and rosemary. Spoon mixture over chicken to glaze chicken pieces. Bake another 15 minutes."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 chicken piece (average)","1/8 of recipe"],"calories":"155.74 kcal","carbohydrateContent":"14.66 g","cholesterolContent":"37.34 mg","fiberContent":"0.30 g","proteinContent":"13.01 g","sodiumContent":"333.61 mg","sugarContent":"8.35 g","fatContent":"4.95 g","saturatedFatContent":"1.11 g"},"notes":"*Children under the age of one should not consume honey.","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"honey-milk-balls","source_url":"https://www.myplate.gov/recipes/honey-milk-balls","name":"Honey Milk Balls","description":"Honey milk balls make a great afternoon snack – packed with protein and calcium. They taste like a treat, so be sure to save a few for yourself.","ingredients":[{"name":null,"items":["1/4 cup honey*","1/4 cup peanut butter","1/2 cup dry milk, non-fat","1/2 cup cereal (crushed)"]}],"directions":[{"name":null,"steps":["Mix honey and peanut butter.","Gradually add dry milk and mix well.","Chill for easier handling.","With greased hands, form into small balls.","Roll in crushed cereal flakes.","Chill until firm.","Refrigerate leftovers within 2 hours."]}],"yield":"20 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 honey milk balls","1/20 of recipe (10g)"],"calories":"41.57 kcal","carbohydrateContent":"5.40 g","cholesterolContent":"0.34 mg","fiberContent":"0.24 g","proteinContent":"1.44 g","sodiumContent":"26.78 mg","sugarContent":"4.54 g","fatContent":"1.69 g","saturatedFatContent":"0.34 g"},"notes":"*Children under the age of one should not consume honey.\nView this recipe on our MyPlate Kitchen YouTube channel.","contributor":"Oregon State University Cooperative Extension Service"},
{"slug":"honey-mustard-dressing","source_url":"https://www.myplate.gov/recipes/honey-mustard-dressing","name":"Honey Mustard Dressing","description":"Make your favorite salad dressing at home, in minutes!","ingredients":[{"name":null,"items":["1/4 cup vegetable oil","1/4 cup vinegar","2 tablespoons honey*","2 tablespoons dijon mustard","2 teaspoons lemon juice","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Put all the ingredients in a jar or bottle with a lid.","Put on the lid. Shake well.","Chill in the fridge for at least 1 hour before serving."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons","1/7 of recipe (28g)"],"calories":"94.59 kcal","carbohydrateContent":"5.15 g","cholesterolContent":"0.00 mg","fiberContent":"0.23 g","proteinContent":"0.21 g","sodiumContent":"48.17 mg","sugarContent":"4.81 g","fatContent":"8.15 g","saturatedFatContent":"1.11 g"},"notes":"*Children under the age of one should not consume honey.\nTry this dressing on cold cooked pasta and vegetables. After serving, keep any leftover dressing in the fridge.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"honey-mustard-pork-chops","source_url":"https://www.myplate.gov/recipes/honey-mustard-pork-chops","name":"Honey Mustard Pork Chops","description":"This family favorite can be made in minutes! Enjoy with a side salad and a whole grain biscuit or dinner roll.","ingredients":[{"name":null,"items":["4 top loin pork chops","1/3 cup orange juice","1 tablespoon reduced sodium soy sauce","2 tablespoons light honey mustard dressing"]}],"directions":[{"name":null,"steps":["Put the pork chops in the large non-stick skillet.","Cook over medium-high heat to brown one side of the pork chops.","Use the spatula to turn the chops.","Add the rest of the ingredients and stir.","Cover the pan and lower the heat.","Simmer for 6 to 8 minutes until chops are done."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 pork chop","1/4 of recipe"],"calories":"278.84 kcal","carbohydrateContent":"4.39 g","cholesterolContent":"104.39 mg","fiberContent":"0.15 g","proteinContent":"41.77 g","sodiumContent":"380.63 mg","sugarContent":"3.05 g","fatContent":"9.57 g","saturatedFatContent":"3.05 g"},"notes":"Pork chops are done when they reach an internal temperature of 145 °F.\nYou can substitute 2 tablespoons of honey mustard with 1 tablespoon of honey plus 1 tablespoon of mustard mixed together.\nChildren under the age of one should not consume honey.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"honey-pumpkin-bar","source_url":"https://www.myplate.gov/recipes/honey-pumpkin-bar","name":"Honey of a Pumpkin Bar","description":"Enjoy the scents and flavors of autumn, all year round with this delicious baked treat!","ingredients":[{"name":null,"items":["1/3 cup dry milk, non-fat","2 cups flour (all purpose)","1 teaspoon baking soda","2 1/2 teaspoons cinnamon","1/2 teaspoon cloves","1/2 teaspoon allspice","1/2 teaspoon nutmeg","1/3 cup vegetable oil","2/3 cup honey*","1/2 cup orange juice","2 tablespoons orange peel (grated)","2 eggs","1 cup pumpkin (mashed)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Lightly grease or spray with non-stick spray a 12x15 inch baking pan with sides.","In a small bowl, combine dry milk, flour, baking soda, and spices. Set aside.","In a large bowl, thoroughly mix oil, honey, juice, peel, eggs, and pumpkin.","Gradually add flour mixture to pumpkin mixture, stirring until smooth.","Spread batter onto prepared baking pan. Bake for 15 to 20 minutes, or until golden brown and cake springs back when lightly touched with your finger. Cool. Cut into squares."]}],"yield":"30 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 2x3\" piece","1/30 of recipe (35g)"],"calories":"87.72 kcal","carbohydrateContent":"14.08 g","cholesterolContent":"13.85 mg","fiberContent":"0.67 g","proteinContent":"1.71 g","sodiumContent":"51.28 mg","sugarContent":"6.90 g","fatContent":"2.95 g","saturatedFatContent":"0.49 g"},"notes":"*Children under the age of one should not consume honey.","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"honeydew-summer-salad-wedges","source_url":"https://www.myplate.gov/recipes/honeydew-summer-salad-wedges","name":"Honeydew Summer Salad Wedges","description":"This chilled fruit salad is perfect to enjoy on a hot summer day!","ingredients":[{"name":null,"items":["1 honeydew melon","1 package gelatin, lemon flavored (3 ounce)","1/2 cup water (boiling)","1/2 cup water (iced)","ice cubes","1 cup whole strawberries (hulled)"]}],"directions":[{"name":null,"steps":["Cut melon in half; scoop out seeds.","Pat the inside of the melon dry using paper towels.","Dissolve gelatin in boiling water.","Combine ice water and ice cubes to make one cup.","Add to gelatin and stir until slightly thickened.","Remove any un-melted ice.","Place each melon half in a small bowl to hold straight and firm.","Place half of strawberries in each melon half.","Pour gelatin mixture over berries.","Cover with plastic wrap and chill until firm, about 3 hours.","To serve, cut into wedges."]}],"yield":"8","nutrition":{"@type":"NutritionInformation","calories":"92.61"},"notes":null,"contributor":"Pick a Better Snack: A Social Marketing Campaign, 2003\nIowa Nutrition Network"},
{"slug":"hooked-salmon-sticks","source_url":"https://www.myplate.gov/recipes/hooked-salmon-sticks","name":"Hooked on Salmon Sticks","description":"A quick and easy kid favorite, this recipe is a creative way to use canned salmon and saltines!","ingredients":[{"name":null,"items":["1 can pink salmon (16 ounces, drained)","16 saltine crackers (crushed, about 1/2 cup)","1 egg","1 tablespoon vegetable oil","non-stick cooking spray"]}],"directions":[{"name":null,"steps":["In a large mixing bowl, combine salmon, cracker crumbs, and egg.","Divide mixture into 8 balls and shaped into sticks about 4 inches long.","Lightly coat a skillet with cooking spray. Add oil and preheat the skillet on medium for 1 to 2 minutes. Add fish sticks and cook for 3 minutes.","Flip over and cook about 3 minutes or until golden brown."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (66g)","calories":"121.17 kcal","carbohydrateContent":"4.50 g","cholesterolContent":"69.26 mg","fiberContent":"0.17 g","proteinContent":"14.26 g","sodiumContent":"262.97 mg","sugarContent":"0.09 g","fatContent":"5.10 g","saturatedFatContent":"0.93 g"},"notes":"Canned pink salmon contains soft bones that are a great source of calcium. Take out any large, hard bones, and then mash the small bones with a fork. You can do this and you will never know the bones are there once the fish is cooked. Pink salmon is \"swimming\" with omega-3 fatty acids -- a \"good\" thing for your heart. So it''s a good idea to get hooked on salmon.\nRinsing your hands in lemon juice and water will get rid of the fishy smell after preparing fish.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"hoppin-john-sausage-black-eyed-peas-and-rice","source_url":"https://www.myplate.gov/recipes/hoppin-john-sausage-black-eyed-peas-and-rice","name":"Hoppin'' John (Sausage, Black-Eyed Peas, and Rice)","description":"Spicy and satisfying, this recipe can be easily doubled for leftovers the next day! Yum!","ingredients":[{"name":null,"items":["1/2 cup brown rice, instant uncooked (or white rice)","1 teaspoon canola oil (or corn oil)","3 ounces low-fat smoked turkey sausage ring, quartered lengthwise and cut into 1/4-inch pieces (lowest fat and sodium available)","1/2 red bell pepper (medium, chopped)","1 jalapeño pepper, medium (seeded and finely chopped)","1 can black eyed peas (low-sodium, rinsed and drained, 15 ounces)","1/2 cup water","1 teaspoon salt"]}],"directions":[{"name":null,"steps":["Prepare the rice using the package directions, omitting the salt and butter/margarine.","Meanwhile, in a medium non-stick skillet, heat the oil over medium-high heat, swirling to coat the bottom. Cook the sausage for 3 minutes or until richly browned, stirring frequently.","Stir in the bell pepper and jalapeño pepper. Cook for 1 minute.","Stir in the peas, water, and salt. Cook for 2 minutes, or until the mixture is thickened slightly but some liquid remains. Remove from the heat.","Let stand, covered, for 5 minutes so the flavors bend. Stir in the rice. Transfer to a serving bowl."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/4 of recipe (225)"],"calories":"233.71 kcal","carbohydrateContent":"35.75 g","cholesterolContent":"19.56 mg","fiberContent":"5.01 g","proteinContent":"11.52 g","sodiumContent":"1056.56 mg","sugarContent":"0.82 g","fatContent":"5.14 g","saturatedFatContent":"1.07 g"},"notes":null,"contributor":"Power to End Stroke: 46 Healthy Soul Food Recipes Cookbook\nAmerican Heart Association"},
{"slug":"horchata","source_url":"https://www.myplate.gov/recipes/horchata","name":"Horchata","description":"A sweet and creamy beverage that pairs well with spicy food.","ingredients":[{"name":null,"items":["1 cup white rice, long-grain uncooked","5 cups water","1/2 cup milk, 1%","1/2 tablespoon vanilla extract","1/2 tablespoon ground cinnamon","2/3 cup sugar"]}],"directions":[{"name":null,"steps":["Pour the rice and water into the bowl of a blender; blend until the rice just begins to break up, about one minute. Let rice and water stand at room temperature for about three hours.","Strain the rice water into a pitcher and discard the rice. Stir the milk, vanilla, cinnamon, and sugar into the rice water.","Chill and stir before serving over ice."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe (322g)","calories":"271.57 kcal","carbohydrateContent":"60.86 g","cholesterolContent":"1.22 mg","fiberContent":"0.87 g","proteinContent":"3.92 g","sodiumContent":"20.86 mg","sugarContent":"28.20 g","fatContent":"0.65 g","saturatedFatContent":"0.23 g"},"notes":"Horchata is a traditional Mexican beverage made with rice and flavored with lime, cinnamon, or sugar.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"hot-cornmeal-cereal","source_url":"https://www.myplate.gov/recipes/hot-cornmeal-cereal","name":"Hot Cornmeal Cereal","description":"A hot, hearty, and savory breakfast cereal that the whole family will enjoy.","ingredients":[{"name":null,"items":["1 cup cornmeal","1 teaspoon salt","3 cups cold water","3 cups boiling water"]}],"directions":[{"name":null,"steps":["Mix the cornmeal, salt, and cold water.","Pour into the boiling water, stirring occasionally.","Cook until thickened, stirring often.","Cover and cook over low heat about 15 minutes.","Serve hot with milk and sugar."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (185g)","calories":"73.61 kcal","carbohydrateContent":"15.63 g","cholesterolContent":"0.00 mg","fiberContent":"1.48 g","proteinContent":"1.65 g","sodiumContent":"410.17 mg","sugarContent":"0.13 g","fatContent":"0.73 g","saturatedFatContent":"0.10 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"hot-n-spicy-seasoning","source_url":"https://www.myplate.gov/recipes/hot-n-spicy-seasoning","name":"Hot ''N Spicy Seasoning","description":"Turn up the heat, but not the sodium, with this powerful and flavorful seasoning blend!","ingredients":[{"name":null,"items":["1 1/2 teaspoons white pepper (ground)","1/2 teaspoon cayenne pepper","1/2 teaspoon black pepper","1/2 teaspoon onion powder","1 1/4 teaspoons garlic powder","1 tablespoon basil (dried)","1 1/2 tablespoons thyme (dried)"]}],"directions":[{"name":null,"steps":["Mix all ingredients together.","Store in airtight container."]}],"yield":"32 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 tsp (1.5g)","calories":"1.91 kcal","carbohydrateContent":"0.43 g","cholesterolContent":"0.00 mg","fiberContent":"0.20 g","proteinContent":"0.09 g","sodiumContent":"0.33 mg","sugarContent":"0.01 g","fatContent":"0.03 g","saturatedFatContent":"0.01 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"hot-wing-flavored-chicken-ranch-sauce","source_url":"https://www.myplate.gov/recipes/hot-wing-flavored-chicken-ranch-sauce","name":"Hot-Wing-Flavored Chicken with Ranch Sauce","description":"Enjoy this spicy chicken dish with a side salad or carrot and celery sticks.","ingredients":[{"name":null,"items":["2 teaspoons hot pepper sauce (or to taste)","1 tablespoon lemon juice, fresh","2 teaspoons olive oil","4 chicken breast, boneless and skinless, all visible fat discarded (about 4 ounces each) (halved)","1 cup cornflake crumbs (about 2 cups flakes)","1/4 cup sour cream, light (or fat-free)","1/4 cup buttermilk, 1% low-fat","1/2 teaspoon garlic powder","1/4 teaspoon dried dillweed (crumbled)"]}],"directions":[{"name":null,"steps":["Lávese las manos con agua y jabón.","In a large shallow bowl, stir together the hot pepper sauce, lemon juice, and olive oil.","Add the chicken and turn to coat. Cover and refrigerate for 30 minutes to 8 hours, turning occasionally if longer than 30 minutes. Discard the marinade.","Preheat the oven to 375 °F. Lightly spray an 8-inch square baking pan with vegetable oil spray.","Put the cornflake crumbs on a plate. Turn the chicken to coat both sides. Transfer to the baking pan.","Lightly spray the top of the chicken with vegetable oil spray. Bake for 30 minutes, or until the chicken reaches an internal temperature of 165 °F and the coating is crisp. Transfer to a serving plate.","Meanwhile, in a small bowl, whisk together the remaining ingredients. Cover and refrigerate until ready to serve. Spoon the sauce over the chicken or use as a dipping sauce."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"225.41 kcal","carbohydrateContent":"8.37 g","cholesterolContent":"95.89 mg","fiberContent":"0.33 g","proteinContent":"29.38 g","sodiumContent":"149.34 mg","sugarContent":"1.67 g","fatContent":"7.48 g","saturatedFatContent":"2.17 g"},"notes":null,"contributor":"Power to End Stroke: 46 Healthy Soul Food Recipes Cookbook\nAmerican Heart Association"},
{"slug":"huevos-motulenos","source_url":"https://www.myplate.gov/recipes/huevos-motulenos","name":"Huevos Motuleños","description":"A special breakfast when you have a little extra time.","ingredients":[{"name":null,"items":["1 cup pinto beans, dry","6 cups water","8 small corn tortillas","1 can reduced-sodium peas, drained (about 15 ounces)","1/2 cup ham, cooked and diced (about 3 ounces)","4 egg whites","2 teaspoons vegetable oil","1 fresh tomato salsa"]}],"directions":[{"name":null,"steps":["Soak the pinto beans in 3 cups of water overnight in the refrigerator. Drain. Boil the beans in 3 cups fresh water until they are soft. Drain the water and mash the beans into a paste.","Preheat oven to 350 °F.","Place tortillas on a cookie sheet and bake for 1 to 2 minutes. Remove cookie sheet from oven and let tortillas cool.","Spoon 1/4 cup of mashed beans on each tortilla. Drain peas and put 1/4 cup of peas on top of beans. Add 2 tablespoons of diced ham on top of peas.","Bake the tortillas for about 8 minutes.","In a mixing bowl, mix egg whites with vegetable oil.","Cook the egg whites in a nonstick pan over medium heat until firm. Cut the egg into 8 pieces.","Place baked tortillas on a plate. Cover ham and mashed beans with a piece of egg.","Add 2 tablespoons of salsa on each tortilla, and serve two tortillas per person."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 Tortillas Huevos Motuleños","calories":"389.40 kcal","carbohydrateContent":"63.83 g","cholesterolContent":"9.11 mg","fiberContent":"17.52 g","proteinContent":"23.65 g","sodiumContent":"392.36 mg","sugarContent":"7.98 g","fatContent":"5.67 g","saturatedFatContent":"1.00 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"huevos-rancheros-fresh-salsa","source_url":"https://www.myplate.gov/recipes/huevos-rancheros-fresh-salsa","name":"Huevos Rancheros with Fresh Salsa","description":"For breakfast, lunch, or dinner, this savory egg dish is fresh, healthy, and inexpensive.","ingredients":[{"name":null,"items":["4 corn tortillas (6 inch)","1/2 tablespoon vegetable oil (or cooking oil of your choice)","non-stick cooking spray","4 egg whites (medium)","4 eggs (medium)","1/8 teaspoon black pepper (ground)","1/4 cup reduced-fat shredded cheddar cheese","1 cup fresh salsa"]}],"directions":[{"name":null,"steps":["Preheat oven to 450 °F.","Wash hands with soap and water.","Lightly brush tortillas with oil on both sides and place on a baking sheet.","Bake for 5 to 10 minutes or until tortillas are crisp on the edges and starting to brown.","Remove from oven and set aside.","Spray a large skillet with non-stick cooking spray over medium heat.","Drop 4 egg whites into skillet, then, break whole eggs over whites to make 4 separate servings.","Cook for 2 to 3 minutes per side until eggs are cooked.","Place one egg on each tortilla shell and top each with 1 Tablespoon cheese","Place under the broiler for about 2 minutes until cheese is melted.","Spoon fresh salsa around the edge of each shell."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (248g)","calories":"198.16 kcal","carbohydrateContent":"16.20 g","cholesterolContent":"210.87 mg","fiberContent":"2.44 g","proteinContent":"13.70 g","sodiumContent":"442.05 mg","sugarContent":"1.88 g","fatContent":"9.06 g","saturatedFatContent":"2.87 g"},"notes":"Can add fresh lime and peppers as desired.","contributor":"California Department of Health Services\nCalifornia 5-A-Day For Better Health! Campaign"},
{"slug":"hummus","source_url":"https://www.myplate.gov/recipes/hummus","name":"Hummus","description":"This classic garbanzo bean dip is easy to make and a versatile dish. Serve hummus with fresh raw vegetables, on a piece of whole wheat pita bread or tortilla...","ingredients":[{"name":null,"items":["2 cups garbanzo beans, cooked (also known as chickpeas)","2 cloves garlic (minced)","1/4 cup lemon juice","1 tablespoon sesame tahini [sesame paste] (or substitute peanut butter for a sweet taste)","2 tablespoons olive oil"]}],"directions":[{"name":null,"steps":["Mash the garbanzo beans until smooth (if you have a blender, put the beans and lemon juice into it and blend).","Add the garlic, lemon juice, tahini and oil. Mix well."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"110.75 kcal","carbohydrateContent":"11.12 g","cholesterolContent":"0.00 mg","fiberContent":"3.53 g","proteinContent":"4.09 g","sodiumContent":"151.36 mg","sugarContent":"2.07 g","fatContent":"5.98 g","saturatedFatContent":"0.84 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"indian-vegetable-and-rice-skillet-meal","source_url":"https://www.myplate.gov/recipes/indian-vegetable-and-rice-skillet-meal","name":"Vegetable and Rice Skillet Meal","description":"An easy and delicious one-pot dish that makes plenty of leftovers to savor!","ingredients":[{"name":null,"items":["2 teaspoons vegetable oil (or cooking oil of your choice)","1 onion (chopped)","1 teaspoon ground ginger","1/2 teaspoon turmeric","1/2 teaspoon cumin","2 cups mixed vegetables (chopped cauliflower, peppers, carrots, or peas)","1 large baking potato (diced)","1 cup white rice (uncooked)","2 1/2 cups water","1 can low-sodium kidney beans (15.5 ounces, drained, rinsed)","salt (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Heat oil in a large skillet over medium heat.","Add onion, ginger, turmeric, and cumin, stir while cooking for 1 minute.","Add remaining ingredients. Bring to a boil, cover, and reduce heat.","Simmer 20 to 25 minutes. Serve hot.","Refrigerate leftovers with in 2 to 3 hours."]}],"yield":"10","nutrition":{"@type":"NutritionInformation","calories":"171.14"},"notes":null,"contributor":"Original Recipe Name - Indian Vegetables and Rice Skillet Meal\nHealthy Recipes\nOregon State University Cooperative Extension Service"},
{"slug":"instant-chocolate-mousse","source_url":"https://www.myplate.gov/recipes/instant-chocolate-mousse","name":"Instant Chocolate Mousse","description":"This dessert is quick and delicious!","ingredients":[{"name":null,"items":["1 box of instant chocolate pudding mix (3.9 ounce)","1 1/4 cups soy milk (cold)","1 package silken tofu (14 ounce)"]}],"directions":[{"name":null,"steps":["Blend the chocolate pudding mix and the soy milk on medium speed for about 15 seconds until the mixture is very smooth.","Add the silken tofu and blend again. Scrape the mixture down off the sides to be sure it’s all mixed in. Blend and scrape until well mixed and very smooth.","Pour mixture into 4 small serving dishes.","Place in the fridge. Chill for at least 2 hours before serving."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (175g)","calories":"183.06 kcal","carbohydrateContent":"23.91 g","cholesterolContent":"0.00 mg","fiberContent":"1.09 g","proteinContent":"10.39 g","sodiumContent":"472.19 mg","sugarContent":"17.92 g","fatContent":"5.75 g","saturatedFatContent":"0.97 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"italian-bean-patties","source_url":"https://www.myplate.gov/recipes/italian-bean-patties","name":"Italian Bean Patties","description":"Combine your favorite beans with herbs and spices to make a delicious patty for dinner tonight!","ingredients":[{"name":null,"items":["2 cups low-sodium canned beans, canned (or cooked from dry)","1 egg (beaten)","1/2 teaspoon garlic powder","1/2 teaspoon onion powder","2 teaspoons Italian seasoning","1 cup bread crumbs (dry, or cracker crumbs)","1/8 cup cornmeal (or all purpose flour)","2 tablespoons vegetable oil (or cooking oil of your choice)"]}],"directions":[{"name":null,"steps":["In a large bowl, mash beans. Add egg and spices and stir to mix evenly.","Stir in bread crumbs. If mixture seems too wet add more breadcrumbs, 1 tablespoon at a time until mixture resembles meatloaf.","Shape into little sausages or patties. Roll in cornmeal or flour.","Fry slowly in vegetable oil over medium heat until crusty and golden brown."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (175g)","calories":"156.69 kcal","carbohydrateContent":"21.49 g","cholesterolContent":"25.69 mg","fiberContent":"4.93 g","proteinContent":"6.40 g","sodiumContent":"190.60 mg","sugarContent":"1.01 g","fatContent":"5.09 g","saturatedFatContent":"0.90 g"},"notes":"Serve in place of hamburgers and add toppings.\nServe in place of breakfast sausage.","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"italian-bean-soup","source_url":"https://www.myplate.gov/recipes/italian-bean-soup","name":"Italian Bean Soup","description":"Three beans combine with savory vegetables in a rich, tomato-based broth for this Italian Bean Soup. Served with a whole wheat roll, this recipe makes a sati...","ingredients":[{"name":null,"items":["1 can (15.5 ounces) great northern beans, low-sodium","1 can (15.5 ounces) red kidney beans, low-sodium","2 cans (15.5 ounces) pinto beans, low-sodium","46 us fluid ounces tomato juice, low-sodium (or V-8 brand juice)","1 can (14.5 ounces) Italian style or stewed tomatoes, low-sodium","1 can (14.5 ounces) vegetable broth, low-sodium","1 can (15 ounces) green beans, low-sodium (drained)","1 1/2 tablespoons Italian seasoning","1 medium onion (chopped)","1/4 teaspoon black pepper","2 garlic cloves"]}],"directions":[{"name":null,"steps":["In a large pot, combine all ingredients.","Cover and simmer for 30 minutes.","Serve with Italian or French bread or whole-wheat rolls."]}],"yield":"18 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"117.95 kcal","carbohydrateContent":"22.27 g","cholesterolContent":"0.00 mg","fiberContent":"6.04 g","proteinContent":"6.49 g","sodiumContent":"202.63 mg","sugarContent":"4.53 g","fatContent":"0.86 g","saturatedFatContent":"0.17 g"},"notes":"Freeze leftovers in plastic sealed containers with 1/2-inch air space under the lid.","contributor":"Choices: Steps Toward Health\nUniversity of Massachusetts\nExtension Nutrition Education Program"},
{"slug":"italian-broccoli-and-pasta","source_url":"https://www.myplate.gov/recipes/italian-broccoli-and-pasta","name":"Italian Broccoli and Pasta","description":"Broccoli and tomatoes add color and flavor to this savory pasta dish. Use spaghetti, linguine, or fettuccini for the pasta.","ingredients":[{"name":null,"items":["6 ounces spaghetti noodles (uncooked)","3 tablespoons onion (chopped)","2 cups broccoli (chopped)","1/2 teaspoon thyme (dried)","1/2 teaspoon oregano (dried)","1/2 teaspoon black pepper","1 can low-sodium stewed tomatoes (14.5 ounce)","2/3 tablespoon Parmesan cheese (grated)"]}],"directions":[{"name":null,"steps":["Cook noodles according to package instructions (do not include oil or salt), and drain.","Spray a medium skillet with non-stick cooking spray; stir-fry onion and broccoli for 3 minutes over medium heat.","Add seasonings (but not the Parmesan cheese) and tomatoes; simmer until heated through.","Spoon vegetable mixture over noodles and top with Parmesan cheese."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/4 cups prepared pasta","1/4 of recipe (201g)"],"calories":"231.11 kcal","carbohydrateContent":"44.41 g","cholesterolContent":"0.72 mg","fiberContent":"5.61 g","proteinContent":"9.37 g","sodiumContent":"41.29 mg","sugarContent":"4.08 g","fatContent":"1.81 g","saturatedFatContent":"0.42 g"},"notes":null,"contributor":"Discover the Secret to Healthy Living\nCalifornia Department of Health Services\nCalifornia Children’s 5-A-Day Power Play Campaign"},
{"slug":"italian-inspired-summer-squash","source_url":"https://www.myplate.gov/recipes/italian-inspired-summer-squash","name":"Italian Inspired Summer Squash","description":"Fresh sweet basil and cheese give summer squash a burst of flavor.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of choice), divided","1 medium summer squash, thinly sliced","1 tablespoon water","salt and pepper (optional, to taste)","1 tablespoon fresh basil","6 tablespoons Parmesan cheese or Romano cheese, grated"]}],"directions":[{"name":null,"steps":["Using a large, oven-proof frying pan, heat 1 tablespoon of oil on medium-high.","Arrange squash in pan, add water, and season lightly with salt, pepper, if using, and basil.","Cover and cook over medium heat for 5 minutes, or until tender crisp.","Sprinkle with cheese and drizzle with remaining oil. Place under a preheated broiler and broil until cheese melts and browns slightly."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/4 recipe"],"calories":"102.61 kcal","carbohydrateContent":"2.31 g","cholesterolContent":"6.45 mg","fiberContent":"0.50 g","proteinContent":"2.79 g","sodiumContent":"107.55 mg","sugarContent":"1.31 g","fatContent":"9.31 g","saturatedFatContent":"2.23 g"},"notes":"Tip: Add cut up fresh tomatoes, green peppers, green beans, eggplant, onions, or other vegetables in season.","contributor":"Adapted from Summer Squash, Italian Style\nFarm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"italian-pasta-salad","source_url":"https://www.myplate.gov/recipes/italian-pasta-salad","name":"Italian Pasta Salad","description":"Fresh and crunchy broccoli, carrot, bell pepper, and green onion, make this easy and delicious pasta salad burst with flavor! This pasta salad would be an ex...","ingredients":[{"name":null,"items":["4 cups pasta (cooked)","2 cups broccoli (blanched, cut in pieces)","1 cup carrot (cooked, sliced)","1/2 cup red pepper (strips)","1/4 cup green onion (chopped)","1/2 cup Italian salad dressing, light or reduced fat (can use more if desired)"]}],"directions":[{"name":null,"steps":["Mix all ingredients together in a large bowl.","Refrigerate for about 30 minutes before serving."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (153g)","calories":"142.69 kcal","carbohydrateContent":"26.61 g","cholesterolContent":"0.00 mg","fiberContent":"2.51 g","proteinContent":"4.98 g","sodiumContent":"140.44 mg","sugarContent":"3.12 g","fatContent":"1.70 g","saturatedFatContent":"0.26 g"},"notes":"For a more hearty salad, add strips of cooked ham, a can of cooked red beans or sprinkle with grated cheese.","contributor":"Oregon’s Healthy Harvest Recipes\nOregon State University Cooperative Extension Service"},
{"slug":"italian-style-vegetables","source_url":"https://www.myplate.gov/recipes/italian-style-vegetables","name":"Italian Style Vegetables","description":"Enjoy this fresh and flavorful dish during the summer when the zucchini, green beans, fresh tomatoes, and corn are all at their peak flavor and freshness. Th...","ingredients":[{"name":null,"items":["2 zucchini (small, cut into 1/2 inch pieces)","2 cups green beans (snapped into pieces)","1/2 head of cabbage (small, sliced thin or shredded)","2 cups corn kernels (or combination of favorite vegetables)","1 medium onion, sliced","garlic (1 clove, minced, optional)","2 tablespoons olive oil","1 cup tomatoes (chopped)","1/2 teaspoon oregano (dry)"]}],"directions":[{"name":null,"steps":["Wash and trim vegetables. Slice zucchini into 1/2 inch pieces; snap beans into pieces; thinly slice or shred cabbage.","Heat oil in frying pan; cook onion over medium heat until soft.","Add vegetables and oregano.","Cook over medium heat for 5 to 7 minutes or until tender. Add chopped tomatoes at the last minute of cooking. Stir occasionally.","Serve immediately.","Refrigerate leftovers within 2 hours."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"108.00 kcal","carbohydrateContent":"16.82 g","cholesterolContent":"0.00 mg","fiberContent":"3.85 g","proteinContent":"3.42 g","sodiumContent":"23.05 mg","sugarContent":"7.69 g","fatContent":"4.35 g","saturatedFatContent":"0.76 g"},"notes":"If using fresh green beans, cook for 2 minutes before adding onion.","contributor":"Pictorial Recipes\nOregon State University Cooperative Extension Service"},
{"slug":"italian-vegetables","source_url":"https://www.myplate.gov/recipes/italian-vegetables","name":"Italian Vegetables","description":"This recipe can be made in minutes! Cauliflower and broccoli add crunch and fiber to this veggie filled pasta dish! If you have extra basil leftover from thi...","ingredients":[{"name":null,"items":["2 cups water","1 cup broccoli florets","1 cup cauliflower florets","2 zucchini, small (sliced)","1 onion, small (diced)","3 celery stalks (chopped)","1 can tomato sauce, low-sodium (8 ounces)","2 teaspoons basil","salt (1 teaspoon, optional)","1 pound package of pasta, any shape (cooked)"]}],"directions":[{"name":null,"steps":["Put 1 cup of hot water in a saucepan.","Add vegetables and cook for 5 minutes.","Add tomato sauce, remaining cup of water, basil and salt.","Simmer until heated thoroughly.","Serve with cooked pasta.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"389.70 kcal","carbohydrateContent":"76.86 g","cholesterolContent":"0.00 mg","fiberContent":"7.24 g","proteinContent":"15.18 g","sodiumContent":"45.30 mg","sugarContent":"7.33 g","fatContent":"2.56 g","saturatedFatContent":"0.53 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"jamaican-jerk-chicken","source_url":"https://www.myplate.gov/recipes/jamaican-jerk-chicken","name":"Jamaican Jerk Chicken","description":"Turn up the heat with this spicy and savory chicken dish! Packed with aromatics and spices this chicken dish is bursting with flavor! Serve with a side of ri...","ingredients":[{"name":null,"items":["1/2 teaspoon cinnamon (ground)","1 1/2 teaspoons allspice (ground)","1 1/2 teaspoons black pepper (ground)","1 tablespoon hot pepper (chopped)","1 teaspoon hot pepper (crushed, dried)","2 teaspoons oregano (crushed)","2 teaspoons thyme","1/2 teaspoon salt","6 garlic cloves (finely chopped)","1 cup onions (puréed or finely chopped)","1/4 cup vinegar","9 teaspoons brown sugar (3 tablespoons)","8 pieces of chicken, skinless (4 drumsticks, 4 breasts)"]}],"directions":[{"name":null,"steps":["Combine all ingredients except chicken in large bowl. Rub seasonings over chicken and marinate in refrigerator for 6 hours or longer.","Preheat oven to 350 °F.","Space chicken evenly on non-stick or lightly greased baking pan.","Cover with aluminum foil and bake for 40 minutes. Remove foil and continue baking for an additional 30 to 40 minutes or until the meat can easily be pulled away from the bone with a fork."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 breast or 2 small drumsticks (104g)","calories":"148.78 kcal","carbohydrateContent":"7.26 g","cholesterolContent":"72.02 mg","fiberContent":"0.92 g","proteinContent":"22.62 g","sodiumContent":"156.40 mg","sugarContent":"4.80 g","fatContent":"2.69 g","saturatedFatContent":"0.59 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"jeans-banana-pudding-parfait","source_url":"https://www.myplate.gov/recipes/jeans-banana-pudding-parfait","name":"Jean’s Banana Pudding Parfait","description":"Try my “makeover” banana pudding parfait recipe and enjoy your dessert without feeling over-stuffed. My version has half the calories and twice as much d...","ingredients":[{"name":null,"items":["8 ginger snap cookies, crushed (about 1 1/4 cups)","7 medium ripe bananas, sliced thin","1 cup nonfat milk","1 1-oz box instant sugar-free, fat-free vanilla pudding","1 1/4 cups low-fat vanilla yogurt","1 teaspoon vanilla extract","1 cup fat-free frozen whipped topping, thawed","1/4 teaspoon cinnamon for garnish (optional)","parfait cups or drinking glasses"]}],"directions":[{"name":null,"steps":["In a large bowl, whisk together the milk and pudding mix; blend well (about 2 minutes).","Add yogurt and vanilla extract; blend until smooth.","Stir the thawed whipped topping into the mixture.","Line the bottom of the parfait cups with a teaspoon of crumbled ginger snaps.","Layer 6 banana slices on top of the cookies; then 2 tablespoons of the yogurt mixture on top. Repeat with another layer of the ginger snaps, bananas, and yogurt mixture.","Top with cinnamon or crushed cookie for garnish.","Cover and chill in refrigerator."]}],"yield":"10 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 glass of Jean''s Banana Pudding Parfait","calories":"210.86 kcal","carbohydrateContent":"40.81 g","cholesterolContent":"2.72 mg","fiberContent":"1.91 g","proteinContent":"4.20 g","sodiumContent":"231.39 mg","sugarContent":"23.21 g","fatContent":"3.31 g","saturatedFatContent":"1.65 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion\nRecipe submitted by Jean, USDA Nutritionist"},
{"slug":"jiffy-oatmeal-crunch","source_url":"https://www.myplate.gov/recipes/jiffy-oatmeal-crunch","name":"Jiffy Oatmeal Crunch","description":"A crunchy and sweet dessert that everyone will love -- and it can be made in minutes! This recipe makes 30 servings, and leftovers freeze well! The qui...","ingredients":[{"name":null,"items":["1/2 cup margarine or butter","3/4 cup brown sugar (firmly packed)","1 teaspoon vanilla","1/2 teaspoon baking soda","2 cups quick oats (uncooked)","1 cup raisins"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F and grease a 9x13 inch baking pan.","In large skillet, melt butter and brown sugar.","Remove from heat and stir in remaining ingredients.","Spread into pan and bake for 15 to 20 minutes. Cool; cut into squares."]}],"yield":"30 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 piece 1 1/3 x 3\"","1/30 of recipe (20g)"],"calories":"77.36 kcal","carbohydrateContent":"13.29 g","cholesterolContent":"0.04 mg","fiberContent":"0.78 g","proteinContent":"0.89 g","sodiumContent":"49.40 mg","sugarContent":"8.88 g","fatContent":"2.59 g","saturatedFatContent":"0.52 g"},"notes":null,"contributor":"Creative Recipes for Less Familiar USDA Commodities Used by Household Programs (recipe)\nUSDA Food and Nutrition Service\nFood Distribution Service\nCook it QUICK! (photo)\nUniversity of Nebraska Cooperative Extension"},
{"slug":"jollof-rice","source_url":"https://www.myplate.gov/recipes/jollof-rice","name":"Jollof Rice","description":"Flavors abound in this chicken, veggie, and rice dish! This recipe makes 12 servings, which will provide you with plenty of tasty leftovers the next da...","ingredients":[{"name":null,"items":["2 pounds cooked meat, cut into 1-inch cubes (use chicken, bacon, shrimp, or smoked pork)","1 tablespoon olive oil (or cooking oil of your choice)","1/2 cup onion (finely chopped)","1/2 cup green peppers (finely chopped)","1/2 teaspoon ground ginger","1 can low-sodium whole tomatoes (14.5 ounce )","2 cans no-salt added tomato paste (6 ounces each)","8 cups water (2 quarts)","1/2 teaspoon black pepper","1/2 teaspoon thyme","1 teaspoon crushed red pepper","2 cups white rice","2 1/2 cups low-sodium chicken broth","2 1/2 cups water"]}],"directions":[{"name":null,"steps":["Sauté cooked meat in oil until slightly brown.","In a large kettle, sauté yellow onion, green pepper, and ginger in vegetable oil until onions are soft.","Add whole tomatoes and simmer for five minutes.","Add tomato paste, 2 quarts water, salt, black pepper, thyme, and red pepper.","Add cooked meat, simmer 20 minutes longer.","In a 2-quart saucepan, cook rice in chicken stock and water until tender.","Add salt and pepper to taste.","Pour the rice in a deep bowl and arrange the meat in the center."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe (514g)","calories":"282.21 kcal","carbohydrateContent":"35.17 g","cholesterolContent":"49.79 mg","fiberContent":"2.52 g","proteinContent":"21.38 g","sodiumContent":"93.21 mg","sugarContent":"4.92 g","fatContent":"6.13 g","saturatedFatContent":"1.54 g"},"notes":"Jollof Rice is a Liberian dish.\nChicken used in nutrition and cost calculations.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"julias-sauteed-steamed-collards","source_url":"https://www.myplate.gov/recipes/julias-sauteed-steamed-collards","name":"Julia’s Sautéed & Steamed Collards","description":"Collards are an all-time favorite side to any meal. This recipe starts with tender collards and adds a hint of “heat” from hot pepper flakes. Try this ea...","ingredients":[{"name":null,"items":["16 cups chopped collards (small leaves)","2 tablespoons olive oil","4 garlic cloves","1/2 teaspoon hot pepper flakes","1 teaspoon salt-free seasoning"]}],"directions":[{"name":null,"steps":["Cut bottom stems from collards.","Wash and cut collards into bite-sized pieces. Place in colander to drain.","Chop garlic cloves into small pieces.","Place olive oil into large skillet. Place on high heat to start.","Place collards in skillet. Keep on high heat, turning collards as they saute, about 1 minute in the uncovered skillet. (You will not need to add water because of the water already on the washed collards.)","Add garlic cloves and red pepper flakes.","Place cover on the skillet to allow collards to steam until they are half their original volume.","Turn heat to low and continue steaming until the collards are tender."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"62.45 kcal","carbohydrateContent":"5.85 g","cholesterolContent":"0.00 mg","fiberContent":"3.71 g","proteinContent":"2.81 g","sodiumContent":"15.86 mg","sugarContent":"0.43 g","fatContent":"4.05 g","saturatedFatContent":"0.59 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion\nRecipe submitted by Julia"},
{"slug":"kale-and-cranberry-stir-fry","source_url":"https://www.myplate.gov/recipes/kale-and-cranberry-stir-fry","name":"Kale and Cranberry Stir-Fry","description":"For this take on stir-fry, add some fun flavor to kale using onions, cranberries, and orange juice. The versatility of this dish can make it a hit at any mea...","ingredients":[{"name":null,"items":["1 teaspoon vegetable oil","1/4 cup onion (chopped or 1/4 medium onion)","1/4 cup dried cranberries","1 clove minced garlic or 1/4 teaspoon garlic powder","6 cups kale, chopped (leaf portion, no stems)","1/4 cup freshly squeezed orange juice (1/2 orange)"]}],"directions":[{"name":null,"steps":["Add oil and onion to large skillet. Stir and sauté over medium-high heat (350 °F in an electric skillet) until onion is clear.","Add cranberries and garlic. Continue to sauté for 2 to 3 minutes.","Add kale. Pour or squeeze orange juice over top of kale. Continue to stir fry for about 5 minutes until kale is wilting and hot.","Serve immediately."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"58.16 kcal","carbohydrateContent":"10.35 g","cholesterolContent":"0.00 mg","fiberContent":"2.07 g","proteinContent":"1.28 g","sodiumContent":"19.55 mg","sugarContent":"7.44 g","fatContent":"1.61 g","saturatedFatContent":"0.20 g"},"notes":"1 bunch fresh kale (about 8 cups, chopped)","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"kale-chips","source_url":"https://www.myplate.gov/recipes/kale-chips","name":"Kale Chips","description":"A crunchy chip that you can customize to your liking! Make sure kale is washed and thoroughly dried to ensure kale chips are crispy and not soggy.","ingredients":[{"name":null,"items":["1 cup kale (or chard, spinach, or collards)","1 1/2 tablespoons olive oil (or oil of your choice)","seasonings of your choice"]}],"directions":[{"name":null,"steps":["Preheat oven to 300 °F.","Line a cookie sheet with parchment paper (optional).","Wash and dry kale. With a knife or kitchen scissors, carefully remove the leaves from the thick stems.","Tear into bite-sized pieces and place kale pieces on cookie sheet.","Drizzle oil over kale and then sprinkle with seasonings of choice.","Bake 10 to 15 minutes or until kale is crisp and edges are brown but not burned."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"33.62 kcal","carbohydrateContent":"0.22 g","cholesterolContent":"0.00 mg","fiberContent":"0.20 g","proteinContent":"0.14 g","sodiumContent":"2.67 mg","sugarContent":"0.04 g","fatContent":"3.57 g","saturatedFatContent":"0.55 g"},"notes":"Seasoning suggestions: salt, pepper, onion powder, garlic powder, chili powder, cumin, turmeric, and Parmesan cheese.","contributor":"Del Norte (California) Department of Health and Human Services\nand University of Kentucky Expanded Food and Nutrition Education Program (EFNEP)"},
{"slug":"kale-nuts-and-raisins","source_url":"https://www.myplate.gov/recipes/kale-nuts-and-raisins","name":"Kale with Nuts and Raisins","description":"Nuts and raisins add protein and fiber to this bright green dish.","ingredients":[{"name":null,"items":["1/4 cup nuts, chopped","2 tablespoons vegetable oil (or oil of your choice)","2 cloves garlic (minced)","2 cups kale (stems removed, leaves chopped)","1/2 cup raisins","salt (optional, to taste)"]}],"directions":[{"name":null,"steps":["Heat oven to 350 °F.","On a baking sheet, toast nuts for 5 minutes.","Heat oil in frying pan on medium heat.","Add garlic and kale to frying pan and cook for 4 minutes.","Add raisins and nuts and cook for 1 minute more.","Add salt to taste (optional)"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (96g)","calories":"184.98 kcal","carbohydrateContent":"18.80 g","cholesterolContent":"0.00 mg","fiberContent":"2.22 g","proteinContent":"2.93 g","sodiumContent":"41.03 mg","sugarContent":"13.58 g","fatContent":"12.03 g","saturatedFatContent":"1.68 g"},"notes":"Walnuts used for costing and nutrition analysis.","contributor":"Eat Smart. Be Fit.\nUniversity of Maryland Extension"},
{"slug":"kale-salad-yogurt-dressing","source_url":"https://www.myplate.gov/recipes/kale-salad-yogurt-dressing","name":"Kale Salad with Yogurt Dressing","description":"This recipe redefines what a kale salad can be. By massaging the kale first, you break down the fibers leaving the greens tender and delicious!","ingredients":[{"name":null,"items":["4 cups kale (1 bunch)","2 tablespoons olive oil (or oil of your choice, divided)","1 lemon (zested and juiced - save zest for dressing)","1 lime (zested and juiced - save zest for dressing)"]},{"name":"Dressing","items":["1 cup Greek yogurt (plain, fat-free)","salt and pepper (optional, to taste)","1/2 cup pumpkin seeds, toasted (pepitas)","1/2 cup cilantro (chopped or torn, stems included)","1 jalapeño chile pepper (seeds removed and diced, optional)"]}],"directions":[{"name":null,"steps":["Wash and dry kale. Remove stems and tear into bite-sized pieces.","Season kale with salt, pepper, 1 tablespoon of olive oil, lemon juice, and lime juice.","With your hands, massage kale until the leaves just start to wilt.","Make the dressing - in a small bowl, add the salt and pepper to the yogurt.","Add the lemon and lime zest and remaining 1 tablespoon of oil.","Mix in cilantro and jalapeno pepper, if desired.","With a spoon, mix massaged kale with yogurt dressing.","Toss pumpkin seeds over salad."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"223.27 kcal","carbohydrateContent":"9.53 g","cholesterolContent":"3.06 mg","fiberContent":"3.23 g","proteinContent":"12.74 g","sodiumContent":"123.10 mg","sugarContent":"3.31 g","fatContent":"16.44 g","saturatedFatContent":"2.73 g"},"notes":null,"contributor":"USDA Supplemental Nutrition Assistance Program (SNAP)"},
{"slug":"kibbeh-khamoustah","source_url":"https://www.myplate.gov/recipes/kibbeh-khamoustah","name":"Kibbeh Khamoustah","description":"This traditionally Kurdish dish is delicious, fresh, and flavorful! The beef dumplings are enjoyed in a soup that is loaded with Swiss Chard. This will ...","ingredients":[{"name":null,"items":["1 pound ground beef, 85% lean (coarsely ground, if available)","1 tablespoon salad oil","1 cup matzo meal","1 1/2 cups semolina","1 cup water","1 teaspoon salt","6 cloves garlic, chopped (use 6-7 cloves)","10 scallions, chopped","6 cups Swiss Chard (2 bunches)","lemon juice (optional)"]}],"directions":[{"name":null,"steps":["Fry ground beef in a small amount of oil.","Prepare the dough by mixing matzo meal, semolina, water, and salt.","Wet hands and shape into walnut-sized pieces.","Roll out dough into a small circle and fill with 1 Tablespoon of meat.","Seal the dough. Continue until all the dough and meat is used.","In a large pot, heat a small amount of oil and fry garlic until golden.","Add the scallions and Swiss chard. Mix well.","Cook about 10 minutes.","Cover with water and continue to cook until boiling.","Add lemon juice, to taste (optional).","Add stuffed dough to soup and cook 15 more minutes."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (173g)","calories":"290.95 kcal","carbohydrateContent":"39.20 g","cholesterolContent":"31.91 mg","fiberContent":"2.63 g","proteinContent":"15.05 g","sodiumContent":"385.33 mg","sugarContent":"0.84 g","fatContent":"7.82 g","saturatedFatContent":"2.38 g"},"notes":"Kibbeh Khamoustah is a Kurdish dish. Kibbeh, or dumplings, are stuffed with meat, traditionally lamb or beef, and served with soup.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"kid-friendly-taco-cups","source_url":"https://www.myplate.gov/recipes/kid-friendly-taco-cups","name":"Kid-Friendly Taco Cups","description":"This recipe features crispy, baked taco cups filled with seasoned ground pork, cheese, and fresh toppings. These fun and easy-to-make mini tacos are perfect ...","ingredients":[{"name":null,"items":["1/2 cup low-fat shredded cheddar cheese","1/2 tablespoon vegetable oil","1 small white onion, chopped","1 tablespoon garlic, minced","1 pound ground pork","1/2 yellow bell pepper, seeded and diced","1/2 green bell pepper, seeded and diced","1 cup baby spinach, shredded","1 teaspoon chili powder","1 teaspoon salt","1/2 teaspoon ground cumin","1/2 teaspoon paprika (smoked, if available)","1/2 teaspoon ground black pepper","1 cup heirloom cherry tomatoes, quartered","1 lime, juiced","4 tablespoons fresh cilantro, chopped"]}],"directions":[{"name":null,"steps":["In a large skillet over medium heat, add oil and chopped onion. Stir occasionally until softened, about 5 minutes. Add garlic, ground pork, peppers and spinach. Stir to crumble meat, cook until no longer pink, about 6 minutes.","Return to heat and add seasonings, stirring to combine. Brown meat 2–3 minutes more and until internal temperature reaches 160 degrees F. Remove from heat and set aside.","In a small bowl, combine tomatoes with lime juice and fresh cilantro. Season with salt if desired.","Arrange 12 serving cups on a platter and fill with cooked pork mixture. Top with your choice of toppings and tomatoes. Serve immediately."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"110.56 kcal","carbohydrateContent":"3.15 g","cholesterolContent":"28.09 mg","fiberContent":"0.80 g","proteinContent":"8.68 g","sodiumContent":"259.17 mg","sugarContent":"1.56 g","fatContent":"7.13 g","saturatedFatContent":"2.59 g"},"notes":"Optional ingredients: Avocado, corn, jalapeños, black beans, salsa, nonfat Greek yogurt","contributor":"Created by the National Pork Board, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"layered-black-bean-dip","source_url":"https://www.myplate.gov/recipes/layered-black-bean-dip","name":"Layered Black Bean Dip","description":"Looking for a healthy snack for game day? This Layered Black Bean Dip is colorful, wholesome, and tasty. Kids in the kitchen can help with the mashing, mixin...","ingredients":[{"name":null,"items":["1 can black beans, low-sodium (15 ounce, drained and rinsed)","1/4 teaspoon onion powder","1/4 teaspoon dried oregano","1/8 teaspoon garlic powder","1/8 teaspoon cayenne pepper","1/2 cup salsa (thick and chunky)","1/2 cup sour cream (light)","1/4 cup green onion (chopped)","2 ounces cheddar cheese, reduced fat (grated)"]}],"directions":[{"name":null,"steps":["Mash beans and mix with onion powder, dried oregano, garlic powder, and cayenne pepper. Spread on a serving dish.","Top with salsa, sour cream, green onions, and grated cheese."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 tablespoons (39g)","calories":"47.69 kcal","carbohydrateContent":"5.49 g","cholesterolContent":"5.32 mg","fiberContent":"1.99 g","proteinContent":"2.93 g","sodiumContent":"98.69 mg","sugarContent":"0.29 g","fatContent":"1.61 g","saturatedFatContent":"0.97 g"},"notes":"Serve as a dip for raw vegetables such as celery, carrot sticks, and pepper slices.","contributor":"Good Food Cookbook\nCornell Cooperative Extension of Onondaga County"},
{"slug":"leaf-finger-salad","source_url":"https://www.myplate.gov/recipes/leaf-finger-salad","name":"Leaf Finger Salad","description":"Light and flavorful, this salad is easily doubled for entertaining or for introducing children to new vegetables! Bright and colorful beets, with crunchy car...","ingredients":[{"name":null,"items":["4 iceberg lettuce leaves (large)","1 cucumber (sliced)","1 beet (shredded)","1 carrot, medium (shredded)","6 tablespoons sunflower seeds","2 teaspoons olive oil","2 teaspoons balsamic vinegar"]}],"directions":[{"name":null,"steps":["Lay lettuce leaves on a flat surface. Top each leaf with all ingredients: cucumbers, carrots, beets, and sunflower seeds.","Drizzle each leaf with olive oil and balsamic vinegar.","Slowly roll the leaf with all ingredients."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 wraps","1/2 of recipe"],"calories":"245.04 kcal","carbohydrateContent":"17.27 g","cholesterolContent":"0.00 mg","fiberContent":"5.62 g","proteinContent":"6.91 g","sodiumContent":"182.02 mg","sugarContent":"6.77 g","fatContent":"18.22 g","saturatedFatContent":"2.18 g"},"notes":null,"contributor":"University of California at Davis\nChildren''s Garden Program"},
{"slug":"leafy-tofu","source_url":"https://www.myplate.gov/recipes/leafy-tofu","name":"Leafy Tofu","description":"Spinach, tofu, and sesame seeds are a fun and delicious combination, and can be made in minutes! A quick and delicious side dish!","ingredients":[{"name":null,"items":["1 package firm tofu (14 ounces)","1 tablespoon oil","4 cups fresh spinach (2 bunches)","2 tablespoons soy sauce, reduced sodium","1/3 tablespoon sesame seeds (1 teaspoon, toasted)"]}],"directions":[{"name":null,"steps":["Drain tofu.","Dice tofu into 1-inch cubes.","Tear spinach into bite-sized pieces.","In a large pan, heat oil and saute tofu cubes for a few minutes. Move tofu to the center of the pan.","Add spinach, and soy sauce. Mix.","Cover pan and cook until spinach is wilted.","Sprinkle toasted sesame seeds."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (217g)","calories":"85.97 kcal","carbohydrateContent":"1.53 g","cholesterolContent":"0.00 mg","fiberContent":"0.99 g","proteinContent":"7.61 g","sodiumContent":"211.06 mg","sugarContent":"0.56 g","fatContent":"6.19 g","saturatedFatContent":"0.98 g"},"notes":"You may use other dark green leafy vegetables.","contributor":"Lifeskills in Food Education, Food Skills Cookbook\nUniversity of Hawaii at Manoa Cooperative Extension\nFood Stamps Nutrition Education Program"},
{"slug":"leftover-turkey-casserole","source_url":"https://www.myplate.gov/recipes/leftover-turkey-casserole","name":"Leftover Turkey Casserole","description":"Leftover turkey, is jazzed up with cheese, cream of mushroom soup, and celery in this hearty casserole dish! Use leftover turkey that has been properly handl...","ingredients":[{"name":null,"items":["6 slices whole wheat bread","4 ounces cooked turkey (cubed or shredded)","1/2 cup onion (chopped)","1/2 cup celery (chopped)","1/2 teaspoon black pepper","2 eggs, lightly beaten","1 1/2 cups low-fat milk","1 can reduced-sodium cream of mushroom soup (10.75 ounces)","2 slices whole wheat bread","2 teaspoons unsalted butter","1/2 cup reduced-fat shredded cheddar cheese","1/2 cup reduced fat mayonnaise"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 °F.","Lightly coat a 9x9x2 inch baking dish with vegetable spray. Cut 6 slices of bread (fresh or day-old) into 1-inch cubes and place half into the bottom of a baking dish.","In a bowl, combine turkey, onion, celery, mayonnaise, and pepper. Spoon mixture over bread crumbs.","Place remaining bread cubes over turkey mixture and press down slightly with spoon.","Combine eggs and milk and pour mixture over cubes. Cover and refrigerate overnight.","When ready to bake, preheat oven to 325 °F.","Spoon soup over top of casserole.","Spread one teaspoon margarine on side of each slice of bread. Cut buttered bread into 1/2-inch cubes and sprinkle on top of casserole.","Bake for 60 minutes or until knife inserted in middle comes out clean.","Remove from oven and sprinkle cheese over top. Let stand 15 minutes before cutting and serving."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (273g)","calories":"313.26 kcal","carbohydrateContent":"31.88 g","cholesterolContent":"98.73 mg","fiberContent":"3.61 g","proteinContent":"19.02 g","sodiumContent":"719.13 mg","sugarContent":"7.70 g","fatContent":"12.03 g","saturatedFatContent":"3.69 g"},"notes":"See how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"Wellness Ways Resource Book\nUniversity of Illinois Extension Service"},
{"slug":"lemon-corn-cake","source_url":"https://www.myplate.gov/recipes/lemon-corn-cake","name":"Lemon Corn Cake","description":"A light and flavorful cake, packed with sweet and tangy lemon flavor! The lemon glaze takes this cake to the next level!","ingredients":[{"name":null,"items":["1 cup yellow corn meal","1 cup flour","1/2 cup sugar","1 tablespoon baking powder","1 teaspoon salt","3/4 cup yogurt, low-fat lemon (about 6 oz)","2 teaspoons lemon peel (finely grated)","1 tablespoon oil","1 egg yolk","2/3 cup non-fat milk","3 egg whites","non-stick cooking spray","3 tablespoons lemon juice","1/2 cup powdered sugar"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Mix first five ingredients together in mixing bowl.","Combine yogurt, lemon peel, oil, egg yolk, and milk together and stir into dry ingredients just until blended.","Whip egg whites with mixer until stiff. Fold into corn meal mixture.","Pour into round 9 inch cake pan coated with nonstick cooking spray.","Bake for 20 to 25 minutes or until corn cake tests done.","For optional lemon glaze: Over low heat blend lemon juice together with powdered sugar. Pierce cake top repeatedly with fork. Slowly pour glaze evenly over the top."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe (73g)","calories":"164.26 kcal","carbohydrateContent":"32.03 g","cholesterolContent":"16.63 mg","fiberContent":"1.09 g","proteinContent":"4.28 g","sodiumContent":"353.90 mg","sugarContent":"15.63 g","fatContent":"2.31 g","saturatedFatContent":"0.52 g"},"notes":null,"contributor":"Celebrate Health with a Lowfat Fiesta\nCalifornia Department of Health Services\nCalifornia Project LEAN"},
{"slug":"lemon-dill-brussels-sprouts","source_url":"https://www.myplate.gov/recipes/lemon-dill-brussels-sprouts","name":"Lemon Dill Brussels Sprouts","description":"Try this different way to eat Brussels sprouts. The Greek yogurt combined with the dill makes the perfect creamy, fresh vegetable dish.","ingredients":[{"name":null,"items":["1 cup plain Greek yogurt, fat free (or low-fat)","1 teaspoon dill weed","1 teaspoon lemon juice","1/2 teaspoon salt","2 cups Brussels sprouts, trimmed and halved lengthwise (1 pound)","2 teaspoons margarine or butter","1/4 cup water"]}],"directions":[{"name":null,"steps":["In a small bowl, mix yogurt, dill weed, lemon juice, and salt. Set aside.","In a large skillet over medium-high heat, sauté sprouts (cut side down) in margarine or butter until they begin to brown.","Stir sprouts and add water. Cover the pan and steam until the water is gone and sprouts are tender crisp, about 3 to 5 minutes.","Mix sprouts with lemon dill sauce. Serve warm."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"71.35 kcal","carbohydrateContent":"6.92 g","cholesterolContent":"3.09 mg","fiberContent":"1.92 g","proteinContent":"8.05 g","sodiumContent":"346.93 mg","sugarContent":"3.16 g","fatContent":"1.82 g","saturatedFatContent":"0.39 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"lemon-pepper-salmon-patties","source_url":"https://www.myplate.gov/recipes/lemon-pepper-salmon-patties","name":"Lemon Pepper Salmon Patties","description":"With a mix of flaked salmon, breadcrumbs, mayonnaise, and egg, a simple fillet transforms into a tasty pan-seared patty!","ingredients":[{"name":null,"items":["3/4 cup breadcrumbs","1/4 cup light mayonnaise","1 egg, slightly beaten (can also use dried egg mix)","1/2 teaspoon lemon pepper","7 ounces frozen salmon, thawed, drained, and finely chopped (optional to remove the skin)","Cooking spray"]}],"directions":[{"name":null,"steps":["Mix breadcrumbs, mayonnaise, egg, and lemon pepper in a medium bowl. Add salmon and mix.","Measure 1/3 cup of salmon mixture (packed) and form into a round patty. Repeat until you have five salmon patties.","Spray a skillet with cooking spray and set stove to medium heat.","Place the salmon patties in the skillet and cook until light brown, 5–7 minutes. Flip the patties and cook on the other side until brown. Salmon should reach a final internal cook temperature of 145°F as measured with a food thermometer before serving."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"177.54 kcal","carbohydrateContent":"12.91 g","cholesterolContent":"64.35 mg","fiberContent":"0.73 g","proteinContent":"10.90 g","sodiumContent":"287.44 mg","sugarContent":"1.47 g","fatContent":"8.80 g","saturatedFatContent":"1.76 g"},"notes":null,"contributor":"Recipe adapted from Chickasaw Nation Nutrition Services, Get Fresh Initiative"},
{"slug":"lemon-potatoes","source_url":"https://www.myplate.gov/recipes/lemon-potatoes","name":"Lemon Potatoes","description":"Potatoes are cut and coated with a blend of lemon juice, garlic, and oil and then baked until flaky and golden brown. Brush potatoes with remaining lemon mix...","ingredients":[{"name":null,"items":["3 medium potatoes","1 lemon, juiced (about 1/4 cup)","1 clove garlic, minced","2 tablespoons vegetable oil"]}],"directions":[{"name":null,"steps":["Heat the oven to 375 °F.","Combine lemon juice, garlic clove, and oil. Set aside 1 tablespoon.","Peel the potatoes and cut into 1-inch pieces.","Pour the lemon juice mixture in a casserole dish or small baking pan to coat the bottom of the dish.","Place the potatoes in the baking dish and coat with the lemon juice mixture.","Bake about 30 minutes, until potatoes are tender.","After removing from the oven, brush the remaining lemon juice mixture on the potatoes. Serve warm."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"206.87 kcal","carbohydrateContent":"33.44 g","cholesterolContent":"0.00 mg","fiberContent":"2.32 g","proteinContent":"3.03 g","sodiumContent":"7.51 mg","sugarContent":"2.85 g","fatContent":"7.18 g","saturatedFatContent":"1.01 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"lemon-spinach","source_url":"https://www.myplate.gov/recipes/lemon-spinach","name":"Lemon Spinach","description":"This tangy spinach side dish can be prepared in a flash! Lemon juice adds extra flavor to this dish. Enjoy as a side to your favorite entree!","ingredients":[{"name":null,"items":["8 cups spinach (1 pound, fresh)","1/4 teaspoon black pepper","1 tablespoon lemon juice"]}],"directions":[{"name":null,"steps":["Wash the spinach. Trim off the stems.","Put the spinach, black pepper, and lemon juice in a pan.","Cook over medium heat. Let the spinach boil for about 3 minutes, until just tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/4 cup","1/4 of recipe"],"calories":"13.77 kcal","carbohydrateContent":"1.51 g","cholesterolContent":"0.00 mg","fiberContent":"0.80 g","proteinContent":"1.35 g","sodiumContent":"49.57 mg","sugarContent":"0.25 g","fatContent":"0.28 g","saturatedFatContent":"0.03 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"lemon-velvet-supreme","source_url":"https://www.myplate.gov/recipes/lemon-velvet-supreme","name":"Lemon Velvet Supreme","description":"Light and refreshing, this tasty dessert, packed with fat-free vanilla yogurt, graham crackers, and mandarin oranges, can be made in minutes! This recipe dou...","ingredients":[{"name":null,"items":["2 cups yogurt (vanilla, fat-free)","1 ounce pudding mix (instant, lemon, 3 Tablespoons)","8 graham crackers (rectangles, crushed)","1 cup mandarin orange (4 ounce, slices, drained or your favorite fruit)"]}],"directions":[{"name":null,"steps":["Combine vanilla yogurt and pudding mix; gently stir together.","Layer bottom of individual dishes with crushed graham crackers. Reserve a few crumbs to sprinkle on top.","Pour pudding mixture over cracker crumbs.","Top with mandarin orange slices or your favorite fruit. Sprinkle with remaining crumbs."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup (111g)","calories":"172.87 kcal","carbohydrateContent":"32.45 g","cholesterolContent":"1.63 mg","fiberContent":"0.97 g","proteinContent":"6.13 g","sodiumContent":"229.43 mg","sugarContent":"17.08 g","fatContent":"2.31 g","saturatedFatContent":"0.42 g"},"notes":null,"contributor":"Choices: Steps Toward Health\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"lemonade","source_url":"https://www.myplate.gov/recipes/lemonade","name":"Lemonade","description":"A fresh, single serving of lemonade that is perfect for a hot summer day. Only one lemon is needed for this recipe. Enjoy!","ingredients":[{"name":null,"items":["1 lemon","3/4 cup water","1 tablespoon sugar"]}],"directions":[{"name":null,"steps":["Cut lemon in half crosswise.","Place lemon half on juicer. Push and twist to squeeze out the juice.","Pour juice into glass. Add about 3/4 cup water.","Add sugar, stirring to mix ingredients.","Create-a-Flavor Changes","Squeeze one-half each lemon and lime.","Squeeze one-half each lemon and orange.","Add 1/4 cup apple juice concentrate and leave out the sugar.","Use 1/4 cup seltzer water and 1/2 cup water."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 glass lemonade approx. 1 cup (248g)","calories":"60.47 kcal","carbohydrateContent":"15.69 g","cholesterolContent":"0.00 mg","fiberContent":"0.14 g","proteinContent":"0.16 g","sodiumContent":"7.80 mg","sugarContent":"13.66 g","fatContent":"0.15 g","saturatedFatContent":"0.02 g"},"notes":null,"contributor":"Cooking Up Fun -- A Pyramid of Snacks\nCornell Cooperative Extension\nDivision of Nutritional Sciences"},
{"slug":"lentil-barley-soup","source_url":"https://www.myplate.gov/recipes/lentil-barley-soup","name":"Lentil Barley Soup","description":"A big pot of lentils, tomatoes, and pearl barley simmer into this hearty soup. A great \"make ahead\" for quick meals and easy clean up.","ingredients":[{"name":null,"items":["2 cups dried lentils (rinsed)","4 scallions","5 carrots (chopped)","2 teaspoons dried oregano","1/2 cup pearl barley","12 cups water","1 can 14.5 ounce low-sodium whole peeled tomatoes (coarsely chopped)","1 tablespoon red wine vinegar","1/2 teaspoon salt"]}],"directions":[{"name":null,"steps":["Place a large soup pot on the stove and add lentils, scallions, carrots, celery, oregano, barley, and water. Bring to a boil.","Reduce the heat to low and simmer, uncovered, for one hour.","Add the tomatoes and continue cooking about 45 minutes. Just before serving, add vinegar."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cup","calories":"329.64 kcal","carbohydrateContent":"63.60 g","cholesterolContent":"0.00 mg","fiberContent":"20.31 g","proteinContent":"19.38 g","sodiumContent":"263.61 mg","sugarContent":"7.80 g","fatContent":"1.32 g","saturatedFatContent":"0.20 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"lentil-chili","source_url":"https://www.myplate.gov/recipes/lentil-chili","name":"Lentil Chili","description":"Lentils, tomatoes, and ground beef are a winning combination in the lentil chili. This recipe packs 9 grams of fiber per serving. Flavorful and filling.","ingredients":[{"name":null,"items":["1/2 pound ground beef (15% fat)","1 1/2 cups onion (chopped)","1 clove garlic (crushed)","2 cups lentils (cooked, drained)","2 cans tomatoes, low-sodium, diced or crushed (29 ounce or 2 cans 14 1/2 ounce)","1 tablespoon chili powder","cumin, ground (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["In a large saucepan, brown beef over medium-high heat, breaking it into bite sized pieces. Drain fat.","Add onion and garlic and cook until softened.","Add lentils, tomatoes, chili powder, and cumin. Cook for about 1 hour until flavors are blended.","Serve hot, topped with your favorite chili toppings."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/6 of recipe"],"calories":"170.61 kcal","carbohydrateContent":"21.38 g","cholesterolContent":"21.27 mg","fiberContent":"8.53 g","proteinContent":"13.38 g","sodiumContent":"74.99 mg","sugarContent":"6.37 g","fatContent":"4.36 g","saturatedFatContent":"1.47 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"lentil-minestrone","source_url":"https://www.myplate.gov/recipes/lentil-minestrone","name":"Lentil Minestrone","description":"This soup starts with plenty of vegetables - carrots, celery, sweet potato, zucchini, and tomatoes and hearty lentils simmered to make a rich and tasty meal ...","ingredients":[{"name":null,"items":["1 tablespoon olive or vegetable oil","1 onion, chopped","2 cloves garlic, minced","3 carrots, diced into 1/4-inch pieces","1 celery stalk, diced into 1/4-inch pieces","1 sweet potato, peeled and diced into 1/4-inch pieces","1 zucchini, diced into 1/4-inch pieces (or 1 cup of frozen zucchini)","2 cups canned diced tomatoes, no salt added (or fresh tomatoes)","1/2 cup lentils (brown or red)","8 cups water","1 cube low-sodium chicken bouillon","4 cups kale, chopped"]}],"directions":[{"name":null,"steps":["Put a soup pot on the stove over medium-high heat. When the pot is hot, add the oil. Add onion and garlic and cook about 7 minutes until golden.","Add carrots, celery, sweet potato, and zucchini and cook about 10 minutes until slightly tender.","Add tomatoes, lentils, water, and chicken bouillon cube and bring to a boil over high heat. Turn the heat down to low, cover and cook 40 minutes.","Add the kale and cook an additional 20 minutes. Serve right away or cover and refrigerate for up to 3 days."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cups","calories":"143.50 kcal","carbohydrateContent":"23.50 g","cholesterolContent":"0.08 mg","fiberContent":"8.25 g","proteinContent":"6.82 g","sodiumContent":"72.61 mg","sugarContent":"7.58 g","fatContent":"3.32 g","saturatedFatContent":"0.52 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"lentil-soup","source_url":"https://www.myplate.gov/recipes/lentil-soup","name":"Lentil Soup","description":"This wholesome lentil soup is simple yet satisfying. Using vegetable broth makes it a delicious vegetarian option.","ingredients":[{"name":null,"items":["2 tablespoons olive oil (or cooking oil of choice)","1 large red, yellow, or white onion, chopped","3 medium carrots, finely diced","1/4 teaspoon red pepper flakes","3 garlic cloves, minced","1 can (14 1/2 ounces) diced tomatoes","1 bay leaf","1 teaspoon salt","1 teaspoon black pepper","2 cups lentils, rinsed (1 pound)","8 cups low-sodium chicken broth or vegetable broth"]}],"directions":[{"name":null,"steps":["Sauté onions, carrots, red pepper flakes, and garlic in oil until soft.","Add tomatoes, bay leaf, salt and pepper and stir well.","Add rinsed lentils and broth and simmer until lentils are soft, about 30 minutes. Keep checking lentils until they are done.","Season with additional salt and pepper, if desired."]}],"yield":"10 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 serving","1/10 of recipe"],"calories":"206.01 kcal","carbohydrateContent":"29.54 g","cholesterolContent":"0.00 mg","fiberContent":"10.45 g","proteinContent":"14.59 g","sodiumContent":"356.12 mg","sugarContent":"4.75 g","fatContent":"4.55 g","saturatedFatContent":"0.86 g"},"notes":null,"contributor":"Bronson Wellness Center, Adapted from Easy Lentil Soup\nBronson Healthcare - Michigan"},
{"slug":"lentil-spaghetti-sauce","source_url":"https://www.myplate.gov/recipes/lentil-spaghetti-sauce","name":"Lentil Spaghetti Sauce","description":"Enjoy this hearty spaghetti sauce over your favorite pasta for a quick, easy, and delicious dinner!","ingredients":[{"name":null,"items":["1 pound ground beef, 90% lean","1 cup onion (chopped)","1 garlic clove (crushed, or 1/2 teaspoon garlic powder)","1 1/2 cups lentils (cooked, drained)","28 ounces spaghetti sauce, low-sodium (1 jar, can use 28-32 ounces)"]}],"directions":[{"name":null,"steps":["In a large sauce pan brown meat. Drain.","Add onion and garlic to drained meat. Cook until onions are soft but not brown.","Add cooked lentils and spaghetti sauce and bring to a boil. Lower heat and cook gently for 15 minutes.","Serve sauce over hot cooked spaghetti noodles."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup sauce","1/6 of recipe"],"calories":"201.63 kcal","carbohydrateContent":"18.72 g","cholesterolContent":"43.82 mg","fiberContent":"6.03 g","proteinContent":"19.13 g","sodiumContent":"55.85 mg","sugarContent":"6.66 g","fatContent":"6.17 g","saturatedFatContent":"2.27 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"lentil-stew","source_url":"https://www.myplate.gov/recipes/lentil-stew","name":"Lentil Stew","description":"Lentils, carrots, and tomatoes are a savory and satisfying combination in this delicious and easy to prepare stew. Enjoy with a side of your favorite citrus ...","ingredients":[{"name":null,"items":["2 teaspoons olive oil (or canola oil)","1 onion (large, chopped)","1 teaspoon garlic powder","1 1/2 10-ounce packages of frozen sliced carrots","1 cup dry lentils (rinsed and drained)","3 cans diced tomatoes, low-sodium (14.5 ounces each)","3 cups water","1 teaspoon chili powder"]}],"directions":[{"name":null,"steps":["Heat the oil in a large pot over medium heat.","Add chopped onion.","Cook for 3 minutes, or until tender.","Stir in garlic powder, carrots, lentils, tomatoes, water, and chili powder.","Simmer, uncovered, for about 20 minutes or until lentils are tender."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"116.68 kcal","carbohydrateContent":"20.56 g","cholesterolContent":"0.00 mg","fiberContent":"8.49 g","proteinContent":"6.58 g","sodiumContent":"53.24 mg","sugarContent":"6.59 g","fatContent":"1.71 g","saturatedFatContent":"0.22 g"},"notes":null,"contributor":"2009 Recipe Calendar\nUniversity of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"lentil-tacos","source_url":"https://www.myplate.gov/recipes/lentil-tacos","name":"Lentil Tacos","description":"Lentils and raisins are an surprising and delicious duo in these sweet and savory tacos. Green peppers add extra flavor and texture. Enjoy with a tossed sala...","ingredients":[{"name":null,"items":["1 1/2 cups dry lentils (sorted and rinsed)","4 cups water","1/2 green pepper (chopped)","4 cloves garlic (minced)","hot pepper flakes (1/2 teaspoon, optional)","1 teaspoon chili powder","1 teaspoon cumin","1/2 teaspoon basil","2/3 cup tomato paste, low-sodium","1/4 cup raisins (optional)"]}],"directions":[{"name":null,"steps":["Cook lentils in 3 cups water for 10 minutes.","Add remaining ingredients and simmer for 30 minutes. Add more water if necessary.","Serve with corn tortillas. Can also be served over rice or noodles."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (281g)","calories":"193.19 kcal","carbohydrateContent":"35.12 g","cholesterolContent":"0.00 mg","fiberContent":"12.64 g","proteinContent":"14.17 g","sodiumContent":"40.96 mg","sugarContent":"6.43 g","fatContent":"0.86 g","saturatedFatContent":"0.12 g"},"notes":"Alternate seasoning: 2 tablespoons taco seasoning instead of the other spices.","contributor":"Washington State WIC Program"},
{"slug":"lentil-vegetable-salad","source_url":"https://www.myplate.gov/recipes/lentil-vegetable-salad","name":"Lentil Vegetable Salad","description":"Lentils, potatoes, carrots, and peas are combined with seasonings and olive oil to make this savory side dish. This salad pairs well with your favorite baked...","ingredients":[{"name":null,"items":["1/2 cup lentils (washed)","2 cups potatoes, sliced (15 ounce can, low-sodium)","1 cup peas (frozen)","2 carrots (large, shredded)","1 tablespoon parsley","2 tablespoons red wine vinegar","3 teaspoons mustard","1/4 cup olive oil"]}],"directions":[{"name":null,"steps":["Boil 1 cup water in a saucepan.","Add the lentils. Cook for 20 minutes over low heat until tender, then drain.","Cook the peas for 3 minutes in another saucepan. Then remove from heat.","Rinse and drain the peas.","Wash, peel, and shred the carrots.","Put the cooked lentils, sliced potatoes, peas, and shredded carrots in a bowl.","Put the parsley, vinegar, mustard, and olive oil in another bowl. Stir well.","Pour the dressing over the lentil vegetable salad."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (147g)","calories":"206.71 kcal","carbohydrateContent":"23.66 g","cholesterolContent":"0.00 mg","fiberContent":"7.05 g","proteinContent":"6.72 g","sodiumContent":"65.41 mg","sugarContent":"3.38 g","fatContent":"9.84 g","saturatedFatContent":"1.53 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"lentil-vegetable-soup","source_url":"https://www.myplate.gov/recipes/lentil-vegetable-soup","name":"Lentil Vegetable Soup","description":"Enjoy this hearty vegetable and lentil soup -- packed with lentils, celery, onion, and tomato sauce -- on a cold winter''s evening.","ingredients":[{"name":null,"items":["1 cup lentils (dry)","5 cups water","2 tablespoons vegetable oil","1 tablespoon onion (finely chopped)","1 cup canned tomato sauce, low-sodium","1/2 teaspoon garlic powder (or 1 garlic clove)","1 teaspoon salt","1/4 teaspoon black pepper","1 bay leaf","1 celery stalk (chopped)","2 tablespoons vinegar"]}],"directions":[{"name":null,"steps":["Sort lentils.","Place lentils in deep pot with water. Bring to a boil and add all ingredients except vinegar.","Reduce heat and cover.","Cook slowly for 1 hour, adding more water if necessary.","Add vinegar.","Remove garlic and bay leaf before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (316g)","calories":"162.64 kcal","carbohydrateContent":"21.45 g","cholesterolContent":"0.00 mg","fiberContent":"8.15 g","proteinContent":"8.95 g","sodiumContent":"413.81 mg","sugarContent":"3.31 g","fatContent":"5.16 g","saturatedFatContent":"0.71 g"},"notes":null,"contributor":"Recipe Collection\nUniversity of Nebraska at Lincoln\nNebraska Nutrition Education Program"},
{"slug":"lickety-split-banana-split","source_url":"https://www.myplate.gov/recipes/lickety-split-banana-split","name":"Lickety Split Banana Split","description":"This fun, kid-friendly breakfast is a healthy twist on an ice cream classic.","ingredients":[{"name":null,"items":["1 banana","1/2 cup non-fat strawberry yogurt","1/2 cup whole-grain cereal","1/4 cup seedless grapes, halved","1/4 cup strawberries, sliced"]}],"directions":[{"name":null,"steps":["Peel and cut the banana in half, lengthwise.","Place the banana on a plate.","Top banana with yogurt and sprinkle with cereal and fruit."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"353.15 kcal","carbohydrateContent":"75.38 g","cholesterolContent":"2.45 mg","fiberContent":"8.40 g","proteinContent":"10.09 g","sodiumContent":"238.95 mg","sugarContent":"46.98 g","fatContent":"1.31 g","saturatedFatContent":"0.33 g"},"notes":null,"contributor":"Nebraska SNAP-Ed"},
{"slug":"light-feather-whole-wheat-pancakes","source_url":"https://www.myplate.gov/recipes/light-feather-whole-wheat-pancakes","name":"Light as a Feather Whole Wheat Pancakes","description":"Adding more whole grains to your diet is easy with this tasty pancake recipe.","ingredients":[{"name":null,"items":["1 1/3 cups whole wheat flour","1 1/2 teaspoons baking powder","1/4 teaspoon salt","1/4 teaspoon baking soda","1 egg, large","3 teaspoons brown sugar (1 tablespoon, packed)","1 1/3 cups buttermilk, 1%","1 tablespoon oil"]}],"directions":[{"name":null,"steps":["Preheat griddle. In medium bowl, stir or sift dry ingredients together.","In a separate bowl, beat egg, buttermilk, brown sugar, and oil together. Stir into dry ingredients just until moistened; batter should be slightly lumpy.","Pour 1/4 cup batter for each pancake onto sprayed or seasoned hot griddle.","Flip the pancake when bubbles appear on surface; turn only once."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 4\" pancake","1/12 of recipe (48g)"],"calories":"77.21 kcal","carbohydrateContent":"12.20 g","cholesterolContent":"18.21 mg","fiberContent":"1.42 g","proteinContent":"3.17 g","sodiumContent":"182.50 mg","sugarContent":"2.63 g","fatContent":"2.20 g","saturatedFatContent":"0.53 g"},"notes":null,"contributor":"Now Serving Whole Grains\nNorth Dakota State University Extension Service"},
{"slug":"lime-marinated-flank-steak-stuffed-poblano-peppers","source_url":"https://www.myplate.gov/recipes/lime-marinated-flank-steak-stuffed-poblano-peppers","name":"Lime-Marinated Flank Steak with Stuffed Poblano Peppers","description":"A simply marinated lean beef flank steak grilled alongside poblano peppers stuffed with whole-grain brown rice, black beans and tomatoes. A tasty, comp...","ingredients":[{"name":null,"items":["1 1/2 pounds beef flank steak","1 1/2 cans diced tomatoes with green chiles (14 1/2 ounces)","3/4 cup chopped fresh cilantro, divided","1/3 cup fresh lime juice for marinade","2 tablespoons olive oil for marinade","2 cups cooked brown rice","1 can low sodium black beans, drained and rinsed (15 ounces)","6 medium poblano chile peppers (about 4 inches long)","optional toppings: toasted, shelled pepitas (pumpkin seeds), lime wedges, crumbled queso fresco"]}],"directions":[{"name":null,"steps":["Drain tomatoes, reserving juice for marinade. Set aside diced tomatoes with green chiles.","Combine reserved tomato juice, 1/2 cup cilantro, lime juice and olive oil in medium bowl. Cover and refrigerate 1/3 cup marinade for rice. Place beef Flank Steak and remaining marinade in food-safe plastic bag; turn steak to coat. Close bag securely and marinate in refrigerator 6 hours or as long as overnight, turning occasionally.","Combine rice, reserved 1/3 cup marinade, diced tomatoes, black beans and remaining 1/4 cup cilantro in medium bowl. Season with salt and pepper, as desired. Set aside. Cook''s Tip: Two cups leftover cooked rice or 1 package (8.8 ounces) ready-to-serve whole grain brown rice can be substituted.","Cut slit lengthwise down 1 side of each poblano pepper to create pocket, leaving stem and tip intact. Make another small crosswise cut just below the stem to form T-shaped opening. Remove and discard seeds and membranes, being careful to keep peppers intact. Spoon rice mixture evenly into peppers. Wrap each tightly in aluminum foil to seal.","Remove steak from marinade; discard marinade. Place steak in center grid over medium, ash-covered coals; arrange peppers around steak. Grill steak, covered, 11 to 16 minutes (over medium heat on preheated gas grill 16 to 21 minutes) for medium rare to medium doneness, turning occasionally. Grill peppers, covered, 25 to 30 minutes (20 to 25 minutes on gas grill) or until peppers are tender and filling is heated through, turning occasionally.","Carve steak across grain into thin slices. Remove peppers from foil. Serve peppers with steaks and toppings as desired."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"342.43 kcal","carbohydrateContent":"33.26 g","cholesterolContent":"69.96 mg","fiberContent":"6.38 g","proteinContent":"31.30 g","sodiumContent":"448.54 mg","sugarContent":"1.27 g","fatContent":"9.13 g","saturatedFatContent":"2.43 g"},"notes":"Cook''s Tip: Two cups leftover cooked rice or 1 package (8.8 ounces) ready-to-serve whole grain brown rice can be substituted.\nFor more information on degree of doneness, safe food handling, and beef safety, visit: https://www.beefitswhatsfordinner.com","contributor":"Created by the National Cattlemen''s Beef Association, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"lite-fried-okra","source_url":"https://www.myplate.gov/recipes/lite-fried-okra","name":"Lite Fried Okra","description":"Try this healthier version of a soul food favorite.","ingredients":[{"name":null,"items":["2 cups fresh okra, sliced","3/4 teaspoon vegetable oil (or cooking oil of choice)","1/8 teaspoon salt","1/8 teaspoon black pepper","nonstick cooking spray (as needed)"]}],"directions":[{"name":null,"steps":["In a bowl, mix sliced okra, oil, salt, and pepper.","Coat a large fry pan with cooking spray.","Heat over medium heat, and add okra mixture, turning often with a wooden spoon or spatula.","Cook until okra is browned, about 10 minutes.","Serve with hot sauce or favorite relish."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"24.21 kcal","carbohydrateContent":"3.74 g","cholesterolContent":"0.00 mg","fiberContent":"1.59 g","proteinContent":"0.96 g","sodiumContent":"80.21 mg","sugarContent":"0.73 g","fatContent":"0.97 g","saturatedFatContent":"0.13 g"},"notes":null,"contributor":"Champions for Change Recipes\nArizona Nutrition Network"},
{"slug":"lite-italian-dressing","source_url":"https://www.myplate.gov/recipes/lite-italian-dressing","name":"Lite Italian Dressing","description":"Making your own salad dressings is a simple way to add a fresh, homemade taste. Try this one today!","ingredients":[{"name":null,"items":["1/2 teaspoon garlic powder (or 1 fresh clove, minced)","1 teaspoon Italian herb mix","1 tablespoon Parmesan cheese","1/4 teaspoon black pepper","1/2 teaspoon celery salt","1/2 cup vinegar","1/4 cup vegetable oil","1/2 cup water"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a pint sized jar with tight fitting lid.","Shake vigorously to blend ingredients.","Store refrigerated."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 tablespoons","calories":"55.64 kcal","carbohydrateContent":"0.30 g","cholesterolContent":"0.43 mg","fiberContent":"0.03 g","proteinContent":"0.18 g","sodiumContent":"100.18 mg","sugarContent":"0.05 g","fatContent":"5.75 g","saturatedFatContent":"0.85 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"louisiana-green-beans","source_url":"https://www.myplate.gov/recipes/louisiana-green-beans","name":"Louisiana Green Beans","description":"Jazz up canned green beans with peppers, onions, and tomatoes!","ingredients":[{"name":null,"items":["1/4 cup onion, chopped","1/4 cup green pepper, chopped","1/2 cup celery, chopped","2 cans (14.5 ounces each) low-sodium green beans, drained","1 can (14.5 ounce) low-sodium tomatoes"]}],"directions":[{"name":null,"steps":["Peel and chop the onion.","Chop the green pepper and celery.","Drain the liquid from the green beans. Rinse with water.","Put the green beans in a saucepan. Add enough water to cover them","Cook the green beans on low heat until tender. Then drain off the water.","Combine all the ingredients in a skillet.","Cook over medium heat for 15 minutes, until the celery is tender and the food is hot."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"70.29 kcal","carbohydrateContent":"14.43 g","cholesterolContent":"0.00 mg","fiberContent":"6.38 g","proteinContent":"3.41 g","sodiumContent":"26.98 mg","sugarContent":"5.14 g","fatContent":"1.26 g","saturatedFatContent":"0.25 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"low-calorie-dressing","source_url":"https://www.myplate.gov/recipes/low-calorie-dressing","name":"Low Calorie Dressing","description":"This dressing is low in calories but not flavor. Dress up any salad with this tasty dressing.","ingredients":[{"name":null,"items":["1/2 cup tomato juice, low-sodium","2 tablespoons lemon juice (or vinegar)","1/3 tablespoon onion, grated (1 teaspoon)","1/2 teaspoon Worcestershire sauce","1/4 teaspoon salt","1/4 teaspoon prepared mustard"]}],"directions":[{"name":null,"steps":["Combine all ingredients. Whisk or stir together.","Store in refrigerator."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons dressing","1/4 of recipe"],"calories":"9.49 kcal","carbohydrateContent":"1.99 g","cholesterolContent":"0.00 mg","fiberContent":"0.21 g","proteinContent":"0.32 g","sodiumContent":"179.50 mg","sugarContent":"1.03 g","fatContent":"0.11 g","saturatedFatContent":"0.01 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"low-fat-creamy-dressing","source_url":"https://www.myplate.gov/recipes/low-fat-creamy-dressing","name":"Low Fat Creamy Dressing","description":"A cool and tangy dressing or dip that’s perfect for your next salad or veggie tray.","ingredients":[{"name":null,"items":["1/2 cup light mayonnaise","1/2 cup plain non-fat yogurt","1/4 teaspoon dill weed","1/2 teaspoon celery salt"]}],"directions":[{"name":null,"steps":["Mix and stir all ingredients in small container.","Store covered in refrigerator and use within 1 week."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons dressing","1/8 of recipe (29g)"],"calories":"45.84 kcal","carbohydrateContent":"2.64 g","cholesterolContent":"2.81 mg","fiberContent":"0.00 g","proteinContent":"0.94 g","sodiumContent":"256.07 mg","sugarContent":"1.73 g","fatContent":"3.50 g","saturatedFatContent":"0.56 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"low-fat-ranch-dip","source_url":"https://www.myplate.gov/recipes/low-fat-ranch-dip","name":"Low Fat Ranch Dip","description":"A blender transforms canned beans, herbs, and spices into this delectable ranch style dip!","ingredients":[{"name":null,"items":["1 can great northern beans (15 ounce, rinsed and drained, low sodium)","1/4 cup water","1/2 cup yogurt, low-fat plain","1/2 teaspoon garlic powder","1/8 teaspoon cayenne pepper","1/4 teaspoon black pepper","1 tablespoon chives (fresh, chopped)","1 tablespoon parsley (fresh, chopped)","1/4 teaspoon tarragon (dried)","1/4 teaspoon salt","1 tablespoon lemon juice"]}],"directions":[{"name":null,"steps":["Blend the beans and garlic in a blender, adding enough water for the desired consistency.","Blend for 2 minutes to make it silky smooth.","Use a spatula to scrape the mixture into a medium bowl.","Stir in the yogurt, cayenne, chives, parsley, and tarragon, salt, and lemon juice. Serve in a bowl."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared dip","1/4 of recipe (158g)"],"calories":"143.83 kcal","carbohydrateContent":"25.27 g","cholesterolContent":"1.84 mg","fiberContent":"5.40 g","proteinContent":"9.62 g","sodiumContent":"359.58 mg","sugarContent":"3.75 g","fatContent":"0.92 g","saturatedFatContent":"0.44 g"},"notes":null,"contributor":"National Cancer Institute (NCI)\n5 A Day for Better Health Program"},
{"slug":"low-fat-tartar-sauce","source_url":"https://www.myplate.gov/recipes/low-fat-tartar-sauce","name":"Low-Fat Tartar Sauce","description":"A cost-effective alternative to store-bought tartar sauce. Use this sauce with your favorite seafood at home and it will not disappoint.","ingredients":[{"name":null,"items":["1/2 cup low-fat plain yogurt (or low-fat sour cream)","1/16 cup (1 tablespoon) pickle relish","1 tablespoon onion, minced (or 2 teaspoons dried minced onion)","1 teaspoon dried parsley (or 1 tablespoon chopped fresh parsley)","1 teaspoon mustard","2 drops hot pepper sauce (optional)"]}],"directions":[{"name":null,"steps":["In a small bowl, combine all the ingredients.","Serve immediately or cover and refrigerate until used."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"26.27"},"notes":"Try making with plain Greek yogurt.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"mac-and-beans-medley","source_url":"https://www.myplate.gov/recipes/mac-and-beans-medley","name":"Mac and Beans Medley","description":"Bell peppers, tomatoes, and beans add color and flavor to this meal, while the red pepper flakes add a little bit of heat.","ingredients":[{"name":null,"items":["4 garlic cloves","1 bell pepper (green, red, yellow, or orange)","2 tablespoons cooking oil","1 can (14.5 ounces) low-sodium tomatoes, diced","1/2 teaspoon red pepper flakes, crushed","1 can (15.5 ounces) low-sodium beans, drained and rinsed (black, kidney, pinto or other)","2 cups cooked macaroni, without salt or fat added (or other pasta)"]}],"directions":[{"name":null,"steps":["Peel and finely chop the garlic. Core, seed, and finely chop the bell pepper.","Heat oil in large skillet over medium-high heat. Add garlic and bell pepper. Cook for one minute. Do not let garlic brown. Add diced tomatoes (do not drain) and red pepper flakes.","Cover the skillet and lower heat. Cook for 10 minutes or until sauce is slightly thickened.","Add beans and cooked macaroni to skillet and cook 5 minutes or until heated through.","Serve hot."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"302.95 kcal","carbohydrateContent":"46.27 g","cholesterolContent":"0.00 mg","fiberContent":"11.35 g","proteinContent":"11.96 g","sodiumContent":"163.79 mg","sugarContent":"4.22 g","fatContent":"8.29 g","saturatedFatContent":"1.22 g"},"notes":null,"contributor":"Champions for Change Recipes\nArizona Nutrition Network"},
{"slug":"macaroni-cheese-broccoli","source_url":"https://www.myplate.gov/recipes/macaroni-cheese-broccoli","name":"Macaroni & Cheese with Broccoli","description":"Broccoli gives flavor, texture, and nutrients to this creamy spin-off of the traditional mac and cheese dish. Try this with roasted squash or sweet potatoes ...","ingredients":[{"name":null,"items":["2 cups uncooked elbow macaroni","4 tablespoons all-purpose flour","2 cups 1% milk","2 cups low-fat cheddar cheese, shredded","1/2 teaspoon black pepper","2 cups cooked broccoli, chopped"]}],"directions":[{"name":null,"steps":["Cook macaroni, following the instructions on the package.","Drain the cooked macaroni and return to the pan.","While the macaroni is still warm, sprinkle in the flour and stir thoroughly.","Over medium heat, slowly stir the milk into the macaroni.","Add the cheese and pepper.","Stir over medium heat until the milk and cheese thicken into a creamy sauce, approximately 7-10 minutes.","Stir in the broccoli; heat thoroughly.","Taste; add a small amount of salt, if needed.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/6 of recipe"],"calories":"326.29 kcal","carbohydrateContent":"39.11 g","cholesterolContent":"32.69 mg","fiberContent":"3.60 g","proteinContent":"20.51 g","sodiumContent":"276.39 mg","sugarContent":"5.54 g","fatContent":"9.38 g","saturatedFatContent":"5.39 g"},"notes":"Fresh or frozen broccoli can be used.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"macaroni-chick-pea-soup","source_url":"https://www.myplate.gov/recipes/macaroni-chick-pea-soup","name":"Macaroni Chick-Pea Soup","description":"This savory soup is packed with tomatoes, green beans, and chickpeas. The recipe also doubles easily if leftovers are desired or if you are making it for a l...","ingredients":[{"name":null,"items":["3 1/2 cups low-sodium chicken broth","1 cup water","1 3/4 cups dry macaroni","1/2 teaspoon celery flakes (or onion powder)","1/2 teaspoon oregano","1 cup low-sodium stewed tomatoes","1 cup green beans","1 can (15 ounces) low-sodium chickpeas, drained (garbanzo beans)","1/4 teaspoon garlic powder"]}],"directions":[{"name":null,"steps":["In a large saucepan, bring broth and water to a boil. Reduce heat to low.","Add macaroni, celery flakes, and oregano. Simmer 4 minutes, stirring occasionally.","Add stewed tomatoes, green beans, chickpeas, and garlic powder.","Simmer 5 minutes, or until macaroni and beans are tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups prepared soup","1/4 of recipe"],"calories":"326.31 kcal","carbohydrateContent":"56.15 g","cholesterolContent":"0.00 mg","fiberContent":"8.77 g","proteinContent":"17.10 g","sodiumContent":"219.63 mg","sugarContent":"6.06 g","fatContent":"4.66 g","saturatedFatContent":"0.84 g"},"notes":null,"contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"magic-crust-quiche","source_url":"https://www.myplate.gov/recipes/magic-crust-quiche","name":"Magic Crust Quiche","description":"This main dish is magically delicious. Use whatever vegetables you have on hand for this fun recipe.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1/2 cup onion (chopped)","2 cups vegetables, frozen, no salt added (or use fresh or leftovers)","1 cup cheddar cheese, low-fat (shredded)","3 eggs","1 1/2 cups milk, 1%","3/4 cup baking mix (like Bisquick)"]}],"directions":[{"name":null,"steps":["Cook onion in oil (or cook with vegetables).","Cook vegetables (or use leftovers). Drain well.","Grease round pie pan or 8x8 inch baking dish.","Spread cooked vegetables in pan. Spread cheese on top of vegetables.","Mix milk, eggs, and baking mix. Pour over vegetables and cheese.","Bake at 350 °F for 35 minutes, until a safe internal temperature has been reached and a knife inserted into the middle comes out clean."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"255.44 kcal","carbohydrateContent":"23.12 g","cholesterolContent":"120.43 mg","fiberContent":"3.21 g","proteinContent":"13.46 g","sodiumContent":"400.23 mg","sugarContent":"7.43 g","fatContent":"11.81 g","saturatedFatContent":"4.50 g"},"notes":"Suggest preparing with frozen broccoli (shown) or spinach.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"magic-mix","source_url":"https://www.myplate.gov/recipes/magic-mix","name":"Magic Mix","description":"Whip up this recipe ahead of time and use it in just about any recipe that calls for baking mix.","ingredients":[{"name":null,"items":["3 cups dry milk, nonfat","1 cup flour","1/3 cup margarine","1 salt (optional)"]}],"directions":[{"name":null,"steps":["Combine dry milk, flour, and salt in a large bowl.","Cut in margarine with two knives until the mixture looks like cornmeal.","Store in a dry, closed container in the refrigerator for up to 6 weeks."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/4 of recipe (103)"],"calories":"396.87 kcal","carbohydrateContent":"50.53 g","cholesterolContent":"10.38 mg","fiberContent":"0.84 g","proteinContent":"21.72 g","sodiumContent":"398.03 mg","sugarContent":"26.60 g","fatContent":"11.75 g","saturatedFatContent":"2.54 g"},"notes":null,"contributor":"Recipe Collection\nUniversity of Nebraska at Lincoln\nNebraska Nutrition Education Program"},
{"slug":"magical-fruit-salad","source_url":"https://www.myplate.gov/recipes/magical-fruit-salad","name":"Magical Fruit Salad","description":"The whole family will love making this as much as they love eating it! Pineapple, grapes, and bananas add flavor and texture to this creamy and delicious des...","ingredients":[{"name":null,"items":["1 can (20 ounces) pineapple chunks, juice packed","1 cup seedless grapes, red or green","2 medium bananas","1 3/4 cups fat-free (skim) milk (or low-fat)","1 package (3.5 ounces) instant pudding mix, lemon or vanilla"]}],"directions":[{"name":null,"steps":["Drain off the juice from the canned pineapples. Put chunks in a large bowl.","Rinse the grapes and drain. Add the grapes to the bowl.","Peel the bananas and cut into bite-sized pieces. Add to the bowl.","Pour the milk over the fruit. While slowly stirring the fruit mixture, sprinkle in the pudding mix.","Let the mixture stand for 5 minutes and serve.","Refrigerate leftovers within 2 hours."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"94.88 kcal","carbohydrateContent":"22.21 g","cholesterolContent":"1.07 mg","fiberContent":"0.85 g","proteinContent":"1.67 g","sodiumContent":"132.23 mg","sugarContent":"20.06 g","fatContent":"0.21 g","saturatedFatContent":"0.09 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"main-dish-salad","source_url":"https://www.myplate.gov/recipes/main-dish-salad","name":"Main Dish Salad","description":"Crunchy and colorful, this salad is packed with vegetables, flavor, and vitamins C and A.","ingredients":[{"name":null,"items":["1/2 head of red cabbage","1/2 head of romaine lettuce","3 carrot (medium)","1 cucumber","1 green pepper","2 broccoli stalks","3 tomatoes (medium)","3 cans kidney beans or garbanzo beans, low-sodium (15.5 ounce)","6 ounces cheese, grated low-fat cheddar","1/4 cup salad dressing, non-fat"]}],"directions":[{"name":null,"steps":["Wash and drain all vegetables well.","Thickly slice red cabbage, tear lettuce into pieces, peel and grate (or slice) carrots and cucumber, cut broccoli into florets and tomato into wedges.","Combine all salad ingredients in a bowl.","Add salad dressing and toss together lightly just before serving."]}],"yield":"12","nutrition":{"@type":"NutritionInformation","calories":"185.33"},"notes":null,"contributor":"Wellness Ways Resource Book\nUniversity of Illinois Extension Service"},
{"slug":"mango-berry-rotini-salad","source_url":"https://www.myplate.gov/recipes/mango-berry-rotini-salad","name":"Mango Berry Rotini Salad","description":"Mango, berries, spinach, and feta cheese make for a colorful twist on pasta salad, with the perfect balance of sweet and tangy.","ingredients":[{"name":null,"items":["1 cup (4 oz) whole-wheat rotini pasta, uncooked","1 ripe mango","1 cup raspberries","1 cup blueberries","2 cups fresh baby spinach","1/2 cup reduced-fat feta cheese"]},{"name":"For the vinaigrette","items":["3 tablespoons extra virgin olive oil","2 tablespoons raspberry vinegar","1 teaspoon sugar","1 teaspoon poppy seeds","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["In a small bowl, whisk vinaigrette ingredients; set aside.","Boil water and cook rotini according to package instructions. Drain cooked rotini and rinse in cool water.","While rotini is cooking, cut mango into chunks, removing peel and pit.","Place salad ingredients in a large bowl; drizzle with vinaigrette. Toss gently."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"325.22 kcal","carbohydrateContent":"39.47 g","cholesterolContent":"16.69 mg","fiberContent":"7.04 g","proteinContent":"8.15 g","sodiumContent":"379.93 mg","sugarContent":"14.22 g","fatContent":"16.57 g","saturatedFatContent":"4.38 g"},"notes":"Serving Suggestion: Serve with an 8 ounce glass of non-fat milk.","contributor":"Produce for Better Health Foundation"},
{"slug":"mango-cucumber-soup","source_url":"https://www.myplate.gov/recipes/mango-cucumber-soup","name":"Mango Cucumber Soup","description":"Sweet, ripe mangoes are the basis for this refreshing and quick chilled summer soup. It''s a no-stove recipe that''s perfect when outdoor temperatures rise.","ingredients":[{"name":null,"items":["2 ripe mangoes, divided","1 English cucumber, divided","2 tablespoons chopped onion","1 jalapeño pepper, finely diced (optional)","lime, juiced","1/2 cup water","2 6-oz containers plain, non-fat Greek yogurt","1/4 cup fresh chopped cilantro"]}],"directions":[{"name":null,"steps":["Cut all but one half of mango into chunks, removing peel and pit; chill remaining mango half for use with garnish.","Slice off 1/4 of the cucumber and chill for use with garnish. Coarsely chop remaining 3/4 of the cucumber.","Place chopped mango, cucumber, onion, and pepper (optional) in blender or food processor with lime juice and water. Purée until smooth.","Blend in yogurt. Chill until ready to serve.","About 15 to 30 minutes before serving, prepare garnish. Dice chilled mango half, removing peel and pit; dice remaining cucumber. Mix mango and cucumber dices with cilantro. To serve, top bowls of soup with garnish."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of Mango Cucumber Soup","calories":"122.78 kcal","carbohydrateContent":"21.12 g","cholesterolContent":"4.25 mg","fiberContent":"2.04 g","proteinContent":"10.01 g","sodiumContent":"34.36 mg","sugarContent":"18.30 g","fatContent":"0.78 g","saturatedFatContent":"0.21 g"},"notes":"Serving Suggestions: Serve with a glass of 100% apple juice.","contributor":"Produce for Better Health Foundation"},
{"slug":"mango-salsa","source_url":"https://www.myplate.gov/recipes/mango-salsa","name":"Mango Salsa","description":"This sweet and tangy salsa pairs perfectly with grilled or baked fish or chicken. The recipe doubles easily if making for a crowd.","ingredients":[{"name":null,"items":["1 mango, peeled, pitted, and diced (or 1 cup thawed frozen chunks)","1 tablespoon red onion, diced","fresh cilantro (1 tablespoon, optional)","1/4 teaspoon salt","2 tablespoons lime juice (bottled or fresh)"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a bowl.","Serve with baked tortilla chips."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 Tablespoons","1/8 of recipe"],"calories":"17.19 kcal","carbohydrateContent":"4.37 g","cholesterolContent":"0.00 mg","fiberContent":"0.46 g","proteinContent":"0.24 g","sodiumContent":"74.12 mg","sugarContent":"3.73 g","fatContent":"0.10 g","saturatedFatContent":"0.02 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"mango-salsa1","source_url":"https://www.myplate.gov/recipes/mango-salsa1","name":"Mango Salsa","description":"The sweetness of fresh mango combined with savory pepper and onion and the zest of lime give this salsa a balance of flavors that are refreshing and crisp. S...","ingredients":[{"name":null,"items":["1 mango, peeled and chopped","1/4 cup green bell pepper, chopped","1 green onion, chopped","1 lime, juiced (1-2 tablespoons)"]}],"directions":[{"name":null,"steps":["Peel and chop the mango, be sure to remove the seed.","Cut the pepper and onion into small pieces.","Mix all the ingredients together."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"37.33 kcal","carbohydrateContent":"9.51 g","cholesterolContent":"0.00 mg","fiberContent":"1.14 g","proteinContent":"0.63 g","sodiumContent":"1.63 mg","sugarContent":"7.69 g","fatContent":"0.23 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"Iowa Department of Public Health, Adapted from Easy Mango Salsa\nIowa Nutrition Network"},
{"slug":"mango-shake","source_url":"https://www.myplate.gov/recipes/mango-shake","name":"Mango Shake","description":"Have a fruity and frosty treat! Banana, mango, and milk are blended together to make this delicious drink.","ingredients":[{"name":null,"items":["2 cups 1% low-fat milk","1 fresh pitted mango (or 4 Tablespoons of frozen mango juice)","1 medium banana","2 ice cubes"]}],"directions":[{"name":null,"steps":["Put all ingredients into a blender.","Blend until foamy.","Serve immediately."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup","calories":"114.52 kcal","carbohydrateContent":"21.35 g","cholesterolContent":"6.10 mg","fiberContent":"1.38 g","proteinContent":"4.79 g","sodiumContent":"48.51 mg","sugarContent":"18.22 g","fatContent":"1.45 g","saturatedFatContent":"0.78 g"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"manhattan-clam-chowder","source_url":"https://www.myplate.gov/recipes/manhattan-clam-chowder","name":"Manhattan Clam Chowder","description":"Try this hearty chowder full of carrots, tomatoes, potatoes, and clams that can be easily made in a slow cooker.","ingredients":[{"name":null,"items":["1 1/2 cups potatoes, sliced","3 medium celery stalks, washed & sliced","1 large onion, chopped","1/2 cup low-sodium tomato puree","1 1/2 cups carrots, washed and sliced","2 cans (6.5 ounces each) clams, chopped and drained","1 1/2 teaspoons dried thyme","1 bay leaf","2 dashs black peppercorns","1 1/2 cups water","2 cups low-sodium tomato juice","1 tablespoon dried parsley flakes"]}],"directions":[{"name":null,"steps":["Scrub potatoes well to remove any eyes or blemishes.","In a slow cooker, combine all ingredients; stir.","Cover and cook on low for 8 to 10 hours or until the vegetables are tender.","Remove bay leaf and peppercorns before serving."]}],"yield":"9 servings","nutrition":{"@type":"NutritionInformation","servingSize":"8 ounces (1 cup)","calories":"96.71 kcal","carbohydrateContent":"13.24 g","cholesterolContent":"15.54 mg","fiberContent":"2.05 g","proteinContent":"9.15 g","sodiumContent":"91.24 mg","sugarContent":"3.94 g","fatContent":"0.83 g","saturatedFatContent":"0.14 g"},"notes":null,"contributor":"Eat Smart New York!\nCornell University Cooperative Extension"},
{"slug":"maple-sweet-potatoes","source_url":"https://www.myplate.gov/recipes/maple-sweet-potatoes","name":"Maple Sweet Potatoes","description":"Sweet potatoes, maple syrup, orange juice, and yogurt are a winning combination in this easy dish that can be made in the microwave.","ingredients":[{"name":null,"items":["2 large sweet potatoes","2 tablespoons non-fat yogurt","1 tablespoon maple syrup","1/16 cup orange juice (1 tablespoon)"]}],"directions":[{"name":null,"steps":["Prick potato skins with a fork. Microwave on high for 3 to 4 minute until soft and easily pierced with a knife.","Scoop out the pulp into a medium bowl.","Mash the pulp and stir in the yogurt, maple syrup, and orange juice.","Transfer to a microwave safe serving bowl and microwave for 1 to 2 minutes to heat through."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 or recipe (162g)","calories":"129.70 kcal","carbohydrateContent":"29.60 g","cholesterolContent":"0.31 mg","fiberContent":"3.38 g","proteinContent":"2.98 g","sodiumContent":"49.45 mg","sugarContent":"14.39 g","fatContent":"0.21 g","saturatedFatContent":"0.07 g"},"notes":null,"contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"marinara-sauce","source_url":"https://www.myplate.gov/recipes/marinara-sauce","name":"Marinara Sauce","description":"Canned tomatoes and fresh spinach come together beautifully in this quick and tasty marinara recipe.","ingredients":[{"name":null,"items":["2 teaspoons vegetable oil (or cooking oil of choice)","2 onions, diced","1/2 teaspoon garlic powder","2 carrots, diced","3/4 cup celery, diced","4 cans (14.5 ounce) crushed tomatoes, low sodium","1 tablespoon Italian seasoning","salt and pepper to taste","2 cups raw spinach, roughly chopped"]}],"directions":[{"name":null,"steps":["Wash the vegetables.","Collect, dice, and measure all ingredients before starting to prepare the recipe.","Heat the oil in a large pot over medium heat.","Add the onion and garlic powder. Cook for about 10 minutes or until the onion is clear.","Add the carrots and celery and cook for 5 minutes until slightly soft.","Add the tomatoes and Italian seasoning. Stir until all ingredients are mixed together. Taste, and add a little bit of salt and pepper if desired.","Turn the heat to medium-high and bring sauce to a boil.","Once boiling, reduce the heat to low. Simmer uncovered for at least 30 minutes.","Stir in the spinach and cook for 2 minutes until spinach wilts.*","Refrigerate leftovers within 2 hours. Eat within 3 to 5 days.","* For a smoother sauce, blend in a blender or food processor."]}],"yield":"16 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"33.99 kcal","carbohydrateContent":"6.30 g","cholesterolContent":"0.00 mg","fiberContent":"2.61 g","proteinContent":"1.22 g","sodiumContent":"23.58 mg","sugarContent":"3.84 g","fatContent":"0.90 g","saturatedFatContent":"0.12 g"},"notes":"This recipe freezes well. Defrost in the refrigerator overnight, then reheat and eat!","contributor":"Colorado State University Extension, Adapted from Easy Marinara Sauce"},
{"slug":"marinated-beef","source_url":"https://www.myplate.gov/recipes/marinated-beef","name":"Marinated Beef","description":"Tangy, marinated beef is full of flavor and pairs well with roasted potatoes, steamed broccoli, and fresh, sliced tomatoes.","ingredients":[{"name":null,"items":["12 ounces beef round steak","1 garlic clove","2 tablespoons lemon juice","4 tablespoons vegetable oil, divided (or cooking oil of choice)","1/2 teaspoon salt","1/2 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Using a cutting board and sharp knife, cut round steak across the grain into thin strips about 1/2 inch wide and 2 to 3 inches long.","In a medium glass mixing bowl, combine garlic, lemon juice, 2 tablespoons of vegetable oil, salt, and pepper.","Add beef strips and stir to coat with the oil mixture (marinade sauce). Cover bowl with plastic wrap and refrigerate for about 2 hours.","In a medium skillet over medium-high heat, heat 2 tablespoons of the oil for 1-2 minutes until hot.","Drain marinade from beef. Put beef in skillet, stir and cook for 5 to 7 minutes or until meat is thoroughly browned."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"231.96 kcal","carbohydrateContent":"0.93 g","cholesterolContent":"52.47 mg","fiberContent":"0.12 g","proteinContent":"18.44 g","sodiumContent":"341.56 mg","sugarContent":"0.20 g","fatContent":"16.65 g","saturatedFatContent":"3.02 g"},"notes":null,"contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"marinated-three-bean-salad","source_url":"https://www.myplate.gov/recipes/marinated-three-bean-salad","name":"Marinated Three-Bean Salad","description":"Beans, celery, and onion make for a delicious marinated salad that the whole family will enjoy. Try it with our Lite Italian Dressing.","ingredients":[{"name":null,"items":["1/2 can low-sodium cannellini (white) beans (15.5 ounce can)","1/2 can low-sodium cut green beans (14.5 ounce can)","1/2 can low-sodium red kidney beans (15.5 ounce can)","1 medium onion (chopped)","1/2 cup celery (chopped)","1 Light Italian Dressing Recipe"]}],"directions":[{"name":null,"steps":["Drain the canned beans. To reduce the sodium rinse the beans under running water","Peel and chop the onion.","In a large bowl, combine the cannellini beans, green beans, kidney beans, onion, and celery.","Pour the Italian dressing over the vegetables and toss lightly.","Cover the bowl and marinate in the refrigerator for at least one hour. The salad can be left in the refrigerator over night.","Drain before serving."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/3 cup","calories":"146.47 kcal","carbohydrateContent":"25.19 g","cholesterolContent":"0.11 mg","fiberContent":"7.37 g","proteinContent":"7.83 g","sodiumContent":"196.80 mg","sugarContent":"4.53 g","fatContent":"2.13 g","saturatedFatContent":"0.42 g"},"notes":"Double the recipe to use the entire can of beans.\nGarnish with parsley if desired.","contributor":"The Texas A&M University System\nTexas Cooperative Extension Expanded Nutrition Program"},
{"slug":"mashed-parsnips-and-potatoes","source_url":"https://www.myplate.gov/recipes/mashed-parsnips-and-potatoes","name":"Mashed Parsnips and Potatoes","description":"A twist on a classic comfort food, this combination of parsnips and potatoes is sure to hit the spot. This dish can be made with substitutions: like using yo...","ingredients":[{"name":null,"items":["2 cups parsnips, chopped","3 medium potatoes, chopped","1/2 cup low-fat 1% milk","1/2 teaspoon salt","1/4 teaspoon black pepper","1/2 teaspoon garlic powder","1 tablespoon butter"]}],"directions":[{"name":null,"steps":["Scrub parsnips and potatoes under running water and peel.","Cut into similar size pieces.","In a medium saucepan, cover the vegetables pieces with cold water. Bring the water to a boil and simmer until vegetables are soft, 15 to 20 minutes.","Drain the vegetables and mash. Stir in milk, salt, pepper, garlic powder and margarine. Serve hot.","Refrigerate leftovers within 2 hours."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"140.45 kcal","carbohydrateContent":"27.42 g","cholesterolContent":"6.11 mg","fiberContent":"3.63 g","proteinContent":"3.53 g","sodiumContent":"218.65 mg","sugarContent":"4.27 g","fatContent":"2.37 g","saturatedFatContent":"1.36 g"},"notes":"Try other seasonings such as parsley, thyme or nutmeg.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"mashed-sweet-potatoes","source_url":"https://www.myplate.gov/recipes/mashed-sweet-potatoes","name":"Mashed Sweet Potatoes","description":"Mashed sweet potatoes are an easy and nutritious side dish that can accompany any entrée. A great idea to try in place of traditional mashed potatoes.","ingredients":[{"name":null,"items":["4 medium sweet potatoes","3/4 teaspoon dried thyme","1/4 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Wash and peel the potatoes. Cut them into slices that are 3/4 inch thick.","Put them in a saucepan with enough water to cover the potatoes.","Bring the water to a boil on medium heat.","Cook the potatoes for 20 to 25 minutes until they’re soft.","Drain the water. Put the potatoes in a medium bowl.","Use a fork or potato masher to mash the potatoes.","Mix in the thyme, salt, and pepper."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"92.71 kcal","carbohydrateContent":"21.23 g","cholesterolContent":"0.00 mg","fiberContent":"3.49 g","proteinContent":"2.07 g","sodiumContent":"184.18 mg","sugarContent":"6.57 g","fatContent":"0.18 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"mashed-taters","source_url":"https://www.myplate.gov/recipes/mashed-taters","name":"Mashed Taters","description":"This is a very quick and easy side dish. This three-step dish can be ready in minutes.","ingredients":[{"name":null,"items":["4 1/2 cups water","4 1/2 teaspoons light buttery spread","4 1/2 cups dehydrated potatoes","1/4 cup low-fat milk","1/2 tablespoon garlic powder (optional)"]}],"directions":[{"name":null,"steps":["Over medium to high heat, combine water and light buttery spread in a medium-sized pot, and bring it to a boil.","Turn off heat; add potatoes and mix well.","Add milk to potatoes and mix well. If using garlic powder, add that too."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"210.94 kcal","carbohydrateContent":"44.52 g","cholesterolContent":"0.61 mg","fiberContent":"3.56 g","proteinContent":"4.93 g","sodiumContent":"79.59 mg","sugarContent":"2.42 g","fatContent":"1.93 g","saturatedFatContent":"0.52 g"},"notes":"Tip: Change the recipe by adding fresh onion, green pepper, blended American and skim cheese, or substitute chicken broth for a rich flavor with less fat. Remember that adding chicken broth will increase the sodium.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe submitted by Alicson Scott, Chickasaw Nation, Get Fresh! Nutrition Education Program"},
{"slug":"masoor-dal-red-lentils-onion","source_url":"https://www.myplate.gov/recipes/masoor-dal-red-lentils-onion","name":"Red Lentils with Onion | Masoor Dal","description":"Dal is a lentil-based dish commonly eaten in India as a part of a more complex meal. This version is an aromatic red lentil dish, flavored by turmeric, cumin...","ingredients":[{"name":null,"items":["1/2 cup dried red lentils","1 teaspoon vegetable oil","1/2 teaspoon salt","1 1/2 cups water","1/2 teaspoon turmeric powder","1/2 teaspoon cumin powder","1 teaspoon sugar","5 teaspoons vegetable oil","2 chili peppers","1/2 onion, large chopped"]}],"directions":[{"name":null,"steps":["Rinse the lentils in a strainer under running water two to three times.","In a bowl, combine the washed lentils, 1 teaspoon oil, and 1/2 teaspoon salt.","Boil lentils in 1 1/2 cups water until they turn yellow and soft. Add turmeric powder, cumin powder, and sugar to the boiled lentils and mix them well.","In a separate pan, add rest of the oil and allow it to heat.","Split the chili peppers in half and add to the heated oil.","Add onion to the oil and stir until it starts to turn light brown.","Add 2 tablespoons boiled lentils (mixed with spices) into the fried onion and stir well for 1 minute.","Add the rest of the boiled lentil mix and stir.","Add 1 cup of water and allow it to boil for two minutes. Serve over white rice. Add parsley garnish if desired."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (139g)","calories":"106.54 kcal","carbohydrateContent":"11.80 g","cholesterolContent":"0.00 mg","fiberContent":"4.07 g","proteinContent":"4.44 g","sodiumContent":"201.39 mg","sugarContent":"2.30 g","fatContent":"4.93 g","saturatedFatContent":"0.68 g"},"notes":"This is a very common food item in Bengali as well as in Pakistani and Indian communities. Generally, lunch or dinner is started with this item followed by two to three main courses. On special occasions, or when preparing this for someone special, one may garnish it with coconut flakes or cilantro leaves.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"master-mix-oregon","source_url":"https://www.myplate.gov/recipes/master-mix-oregon","name":"Master Mix Oregon","description":"This baking mix is an ingredient in several recipes such as this recipe for Crustless Pumpkin Pie.","ingredients":[{"name":null,"items":["4 cups all-purpose flour","4 cups whole wheat flour","1 1/3 cups nonfat dry milk","1/4 tablespoon baking powder","1 teaspoon salt","1 1/2 cups shortening"]}],"directions":[{"name":null,"steps":["In a large bowl combine all-purpose flour, whole wheat flour, dry milk, baking powder, and salt.","Mix thoroughly.","Cut in shortening with pastry blender or two knives until mixture looks like course cornmeal.","Store in covered containers in the refrigerator."]}],"yield":"11 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/11 of recipe","calories":"575.19 kcal","carbohydrateContent":"70.45 g","cholesterolContent":"1.64 mg","fiberContent":"5.90 g","proteinContent":"13.44 g","sodiumContent":"294.67 mg","sugarContent":"4.58 g","fatContent":"27.78 g","saturatedFatContent":"6.85 g"},"notes":"The final product of this recipe is intended to be used as an ingredient in other recipes. It is not intended as a ready-to-eat product.","contributor":"Oregon State University Cooperative Extension Service"},
{"slug":"matzo-meal-kugel-pudding","source_url":"https://www.myplate.gov/recipes/matzo-meal-kugel-pudding","name":"Matzo Meal Kugel (Pudding)","description":"Kugel is a baked pudding or casserole. Matzo meal kugel is traditionally served on the Jewish holiday of Passover. This dish is easy to make and can be serve...","ingredients":[{"name":null,"items":["4 eggs","1 cup sugar","4 cups milk, 1%","5 tablespoons butter, melted","2 cups matzo meal","1 teaspoon salt"]}],"directions":[{"name":null,"steps":["Combine eggs and sugar; beat well.","Add milk and melted butter; mix well.","Stir in matzo meal and salt.","Pour into buttered 11x13 inch pan.","Bake at 350 °F for 1 hour (don''t over bake).","Cut into slices. Can be served hot or cold."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe (121g)","calories":"244.43 kcal","carbohydrateContent":"37.16 g","cholesterolContent":"85.29 mg","fiberContent":"0.58 g","proteinContent":"6.80 g","sodiumContent":"250.76 mg","sugarContent":"20.76 g","fatContent":"7.56 g","saturatedFatContent":"4.03 g"},"notes":null,"contributor":"Osteoporosis Facts and Recipes\nUniversity of Illinois Extension Service"},
{"slug":"meatball-soup","source_url":"https://www.myplate.gov/recipes/meatball-soup","name":"Meatball Soup","description":"Mixed vegetables, meatballs, and brown rice make a delicious and hearty soup that will warm you up on a cold winter night.","ingredients":[{"name":null,"items":["6 cups water","1/3 cup brown rice, uncooked","3 low-sodium beef or chicken bouillon cubes (or 1 tablespoon low-sodium bouillon powder)","1 tablespoon oregano","8 ounces 90% lean ground beef (or turkey or chicken)","1 medium tomato, finely chopped","1/2 medium onion, peeled and finely chopped","1 large egg","1/2 teaspoon salt","2 cups fresh vegetable mix, chopped (carrots, celery, and spinach)"]}],"directions":[{"name":null,"steps":["In a large pot, combine water, rice, bouillon cubes, and oregano. Bring to a boil over high heat.","Stir to dissolve bouillon. Reduce heat to low and simmer.","Meanwhile, in a large bowl, mix ground meat, tomato, onion, egg, and salt. Form into 12 meatballs.","Add meatballs to broth mixture and simmer 30 minutes.","Add vegetables. Cook 10 to 15 minutes or until meatballs are cooked and rice and vegetables are tender.","Serve hot."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup broth mixture and 3 large meatballs","calories":"246.66 kcal","carbohydrateContent":"30.39 g","cholesterolContent":"84.59 mg","fiberContent":"5.87 g","proteinContent":"16.42 g","sodiumContent":"421.74 mg","sugarContent":"4.85 g","fatContent":"6.53 g","saturatedFatContent":"2.33 g"},"notes":null,"contributor":"California Champions for Change Lunch Recipes\nCalifornia Department of Public Health\nNetwork for a Healthy California"},
{"slug":"meatloaf-mug","source_url":"https://www.myplate.gov/recipes/meatloaf-mug","name":"Meatloaf in a Mug","description":"Enjoy this flavorful meatloaf without ever turning on your oven. This delicious single serving meal can be prepared in the microwave.","ingredients":[{"name":null,"items":["1/4 pound 85% lean ground beef (or leaner)","2 tablespoons quick cooking oats","1 tablespoon ketchup","2 teaspoons low-fat 1% milk","1 teaspoon dry onion mix"]}],"directions":[{"name":null,"steps":["Combine all ingredients and stir to mix.","Spray microwave-safe mug with cooking spray.","Pat beef mixture into mug. Make a small hold in center, all the way to the bottom.","Microwave on HIGH (100%) for 3 minutes or until done."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup","1 meatloaf"],"calories":"244.40 kcal","carbohydrateContent":"13.53 g","cholesterolContent":"64.33 mg","fiberContent":"1.23 g","proteinContent":"20.74 g","sodiumContent":"423.12 mg","sugarContent":"4.37 g","fatContent":"11.46 g","saturatedFatContent":"4.22 g"},"notes":"Cooking time will increase if more than one meat loaf is placed in the microwave at a time.\nLeftover dry onion mix can be used as a seasoning for baked or microwaved vegetables.\nFood Safety Note: Cook until the internal temperature is 160 °F when measured with a meat thermometer.","contributor":"Spend Smart. Eat Smart.\nIowa State University Extension"},
{"slug":"meatloaf","source_url":"https://www.myplate.gov/recipes/meatloaf","name":"Meatloaf","description":"This meatloaf is very moist and simple to make for lunch or dinner. Serve with vegetables, rice, pasta, or potatoes, or slice to make sandwiches.","ingredients":[{"name":null,"items":["1 pound ground beef","1 can (about 15 ounces) low-sodium cream style corn","1/2 cup onion, diced","1 teaspoon garlic, finely chopped","1/2 cup water","1/2 cup yellow cornmeal","2 tablespoons dried egg mix (or 1 egg)","1/4 teaspoon salt","1/4 teaspoon black pepper","Nonstick cooking spray"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F.","In a large pan, cook ground beef over medium heat for 8 to 10 minutes. Drain fat.","Add corn, onions, and garlic to pan, and cook for an additional 10 minutes.","Add water, cornmeal, egg mix, salt, and pepper to the beef mixture. Stir well and cook for 15 minutes.","Use a large iron skillet or loaf pan. Spray pan with nonstick cooking spray. Form beef and cornmeal mixture into a loaf in a pan.","Cover pan with an oven-safe lid or foil and bake for 35 to 40 minutes."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"292.00"},"notes":"Tip for cooking ground beef: The recommended safe minimum internal temperature for ground beef is 160 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"meaty-stuffed-potatoes","source_url":"https://www.myplate.gov/recipes/meaty-stuffed-potatoes","name":"Meaty Stuffed Potatoes","description":"Here is a delicious recipe for potatoes stuffed with meat, vegetables, and cheese that will become a favorite at your home. Enjoy this dish with a side or de...","ingredients":[{"name":null,"items":["3 medium potatoes","8 ounces turkey, diced and cooked (or use cooked chicken, beef, or pork)","1 cup broccoli, coarsely chopped","1/2 cup onion, chopped","1/2 cup carrot, thinly sliced","3/4 cup hot water","3/4 cup fat-free (skim) milk","1 tablespoon flour","1/4 teaspoon black pepper","1/2 cup low-fat cheese, shredded"]}],"directions":[{"name":null,"steps":["Scrub potatoes. Remove any bad spots. Do not peel. Cut each in half, lengthwise.","In a covered saucepan, boil potatoes in just enough water to cover the pieces. When they are fork-tender (about 15 to 20 minutes), remove from heat and drain. Set aside. (Note: you can also pierce whole potatoes with a knife or fork in several places and cook in microwave without water until fork tender, then cut each in half, lengthwise).","Meanwhile, in a large skillet sprayed with non-stick cooking spray, combine cooked meat, broccoli, onion, carrots and water.","Boil until vegetables are fork tender - about 5 minutes. Reduce heat to low.","In a jar with a tight fitting lid, combine milk, flour and pepper. Shake well.","Stir flour mixture into meat mixture until well blended.","Stir in cheese. Cook over low heat about 5 minutes longer or until sauce thickens, stirring frequently.","To serve, place 2 potato halves on each plate and mash the middle somewhat. Spoon about one third cup of the meat mixture over each potato half","Cover and refrigerate leftovers within 2 hours."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 prepared potato","1/3 of recipe"],"calories":"365.02 kcal","carbohydrateContent":"48.31 g","cholesterolContent":"61.34 mg","fiberContent":"5.67 g","proteinContent":"30.26 g","sodiumContent":"275.13 mg","sugarContent":"7.66 g","fatContent":"5.55 g","saturatedFatContent":"2.84 g"},"notes":null,"contributor":"Fix it Fresh! Recipe Series\nKansas State University Research and Extension"},
{"slug":"mediterranean-chicken-and-white-bean-salad","source_url":"https://www.myplate.gov/recipes/mediterranean-chicken-and-white-bean-salad","name":"Mediterranean Chicken and White Bean Salad","description":"This refreshing salad starts with cooked chicken, white beans, cucumber, and onion with a splash of fresh lemon juice, oil and seasonings for a delicious com...","ingredients":[{"name":null,"items":["1 cup skinless chicken, cooked and diced into 1/2 inch pieces","1 15.5 ounce can low-sodium white beans, drained and rinsed","1 cucumber, peeled and diced into 1/2 inch pieces","1/4 red or white onion, chopped into 1/2 inch pieces","2 tablespoons vegetable oil","1/4 cup lemon juice","1 tablespoon dried basil or parsley leaves","1/4 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Put everything in the bowl and gently toss.","Serve right away, or cover and refrigerate for up to 2 days."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"255.62 kcal","carbohydrateContent":"26.45 g","cholesterolContent":"33.34 mg","fiberContent":"6.19 g","proteinContent":"18.86 g","sodiumContent":"357.80 mg","sugarContent":"3.13 g","fatContent":"8.74 g","saturatedFatContent":"1.40 g"},"notes":"2 (5-ounce) cans of tuna in water can be used instead of chicken.\nGreat Northern, chickpeas, cannellini, or navy beans can be used.\nAdd 1/2 cup chopped fresh tomatoes.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"mediterranean-roasted-eggplant-tomato-sauce","source_url":"https://www.myplate.gov/recipes/mediterranean-roasted-eggplant-tomato-sauce","name":"Mediterranean Roasted Eggplant with Tomato Sauce","description":"A wonderful recipe to enjoy in the summer when eggplant is in season. Top this side dish with freshly ground black pepper if desired.","ingredients":[{"name":null,"items":["2 medium eggplants","vegetable oil spray, as needed","1 cup low-sodium pizza or spaghetti sauce","1/2 cup low-fat plain yogurt","1 garlic clove (finely chopped)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 degrees F.","Wash and remove the stem end, and slice the eggplants into 1/2-inch slices.","Spray a baking pan with vegetable oil spray and lay the eggplant in the pan in a single layer.","Spoon low-sodium pizza or spaghetti sauce on each slice.","Bake 30 minutes in the preheated oven.","Stir the yogurt and garlic together.","Drizzle the sauce in thin lines on each of the eggplant slices before serving. You can do this easily by putting the sauce in a plastic squirt bottle or using a spoon.","Serve immediately as an entrée or side dish."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 recipe","calories":"98.72 kcal","carbohydrateContent":"20.47 g","cholesterolContent":"1.84 mg","fiberContent":"8.48 g","proteinContent":"4.87 g","sodiumContent":"34.28 mg","sugarContent":"13.26 g","fatContent":"1.11 g","saturatedFatContent":"0.43 g"},"notes":null,"contributor":"Adapted from Do Yourself a Flavor by Graham Kerr\nArizona Health Zone"},
{"slug":"mediterranean-tuna-antipasti-salad","source_url":"https://www.myplate.gov/recipes/mediterranean-tuna-antipasti-salad","name":"Mediterranean Tuna Antipasti Salad","description":"Try this fresh take on tuna salad. It''s delicious with walnuts, garbanzo beans, veggies, and a lemony vinaigrette dressing.","ingredients":[{"name":null,"items":["2/3 cup walnuts, coarsely chopped","1/2 cup red onion, finely chopped","1/2 cup red bell pepper, chopped","10 ounces water-packed chunk tuna (2 5-ounce cans)","1 15.5-ounce can garbanzo beans, low sodium, drained and rinsed","2 tablespoons lemon juice","2 tablespoons extra virgin olive oil","2 tablespoons fresh parsley, chopped","4 cups romaine hearts, shredded"]}],"directions":[{"name":null,"steps":["Place walnuts, onion, bell pepper, parsley, tuna, and garbanzo beans in a large bowl and mix lightly.","Whisk together lemon juice and olive oil and drizzle over salad; stir lightly to coat ingredients with dressing. Season with salt and pepper, if desired.","Place lettuce on a platter or divide between 8 salad bowls. Top with equal amounts of salad."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup antipasti salad + 1 cup lettuce","calories":"371.47 kcal","carbohydrateContent":"22.11 g","cholesterolContent":"25.52 mg","fiberContent":"7.45 g","proteinContent":"22.84 g","sodiumContent":"312.64 mg","sugarContent":"5.80 g","fatContent":"23.07 g","saturatedFatContent":"2.72 g"},"notes":null,"contributor":"Created by the California Walnut Commission, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"melissas-slow-cooker-stuffing","source_url":"https://www.myplate.gov/recipes/melissas-slow-cooker-stuffing","name":"Melissa’s Slow Cooker Stuffing","description":"My family’s recipes are a sacred tradition, especially our slow cooker stuffing. Rather than take away “unhealthy” ingredients, I wanted to make my ver...","ingredients":[{"name":null,"items":["3/4 stick of light butter","2 cups chopped celery","1 cup chopped onion","2 1/2 teaspoons dried parsley","2 cups fresh mushrooms, sliced","16 slices 100% whole-wheat bread, cubed","1/2 cup dried cranberries","1 cup chopped apple","1 teaspoon poultry seasoning","1 1/2 teaspoons dried sage","1 teaspoon dried thyme","1 teaspoon garlic powder","1/2 teaspoon ground black pepper","3 cups low-sodium chicken broth","1 egg, beaten","2 egg whites, beaten","1 cup water"]}],"directions":[{"name":null,"steps":["Melt butter in a large pan over medium heat. Add onion, celery, mushrooms, and parsley to pan. Stir often until veggies are tender.","Combine bread cubes, cranberries, and apple in a large bowl. Pour veggies over bread cubes and mix gently.","Season with poultry seasoning, sage, thyme, garlic powder, and pepper. Pour in broth (just enough to moisten) and gently mix in eggs.","Transfer mixture to slow cooker and cover.","Set slow cooker to High for 45 minutes; then reduce heat to Low and cook for 4 to 8 hours."]}],"yield":"16 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"162.01 kcal","carbohydrateContent":"23.58 g","cholesterolContent":"18.41 mg","fiberContent":"3.20 g","proteinContent":"6.88 g","sodiumContent":"224.30 mg","sugarContent":"7.06 g","fatContent":"4.91 g","saturatedFatContent":"2.28 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion\nRecipe submitted by Melissa, USDA Nutritionist"},
{"slug":"melon-and-mint","source_url":"https://www.myplate.gov/recipes/melon-and-mint","name":"Melon and Mint","description":"In the mood for a refreshing snack? The combination of mint and lime on this fruit makes it a refreshing treat.","ingredients":[{"name":null,"items":["1 tablespoon lime juice","1/4 cup fresh mint leaves","6 teaspoons packed brown sugar (2 tablespoons)","3 cups watermelon cubes","3 cups honeydew cubes"]}],"directions":[{"name":null,"steps":["Blend lime juice, mint leaves, and brown sugar together in a small food processor.","Place melon cubes in a bowl. Drizzle dressing over melon and toss gently."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup","calories":"52.52 kcal","carbohydrateContent":"13.34 g","cholesterolContent":"0.00 mg","fiberContent":"0.77 g","proteinContent":"0.71 g","sodiumContent":"12.30 mg","sugarContent":"11.70 g","fatContent":"0.18 g","saturatedFatContent":"0.04 g"},"notes":"Try with other types of melon such as cantaloupe or crenshaw melons.\nTry omitting the brown sugar and adding crumbled feta cheese.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"melon-salsa","source_url":"https://www.myplate.gov/recipes/melon-salsa","name":"Melon Salsa","description":"Exploding with delicious summer flavors, this salsa recipe is amazing with whatever melon you have on hand.","ingredients":[{"name":null,"items":["2 cups fresh melon, seeded and chopped (use one kind or a combination of honeydew, cantaloupe, or watermelon)","1 cup cucumber, peeled, seeded, and chopped","1/4 cup onion, red or white, chopped","fresh cilantro or mint (optional 2 tablespoon, chopped)","1/2 jalapeño, seeded and finely chopped (or hot sauce to taste)","1/4 cup lime juice or lemon juice","1 tablespoon sugar"]}],"directions":[{"name":null,"steps":["In a medium size bowl, stir together all ingredients.","Taste and season with more lemon or lime juice, sugar if needed.","Cover and chill for at least 30 minutes. Serve with grilled or broiled fish or chicken."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup","calories":"17.54 kcal","carbohydrateContent":"4.42 g","cholesterolContent":"0.00 mg","fiberContent":"0.35 g","proteinContent":"0.25 g","sodiumContent":"5.76 mg","sugarContent":"3.60 g","fatContent":"0.07 g","saturatedFatContent":"0.02 g"},"notes":"Caution: When handling hot peppers, the oils can cause burning and skin irritation. You can wear clean kitchen gloves or wash hands thoroughly after preparing. KEEP HANDS AWAY FROM EYES.","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"mexican-pinwheels","source_url":"https://www.myplate.gov/recipes/mexican-pinwheels","name":"Vegetable Pinwheels","description":"Have kids help mix the ingredients and spread the cream cheese mixture on the tortillas for this fun and flavorful snack.","ingredients":[{"name":null,"items":["2 ounces cream cheese, softened","1/8 cup corn (2 tablespoons)","2 tablespoons chopped green chilies, drained","2/3 tablespoon chopped onion (2 teaspoons)","2 tablespoons salsa","3 large flour tortillas, 10-inches across"]}],"directions":[{"name":null,"steps":["Drain the corn and green chilis. Collect, chop, and measure all ingredients before starting to prepare the recipe.","Mix cream cheese, corn, green chilies, onions, and salsa together in a bowl.","Spread mixture on tortillas, roll up tightly, and wrap in plastic wrap.","Cut in 1-inch slices, and serve immediately, or store in the refrigerator until ready to serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 tortilla wrap","1/6 of recipe"],"calories":"146.37 kcal","carbohydrateContent":"19.08 g","cholesterolContent":"9.54 mg","fiberContent":"1.43 g","proteinContent":"3.66 g","sodiumContent":"324.85 mg","sugarContent":"2.05 g","fatContent":"6.15 g","saturatedFatContent":"2.96 g"},"notes":"Be creative! Add washed, chopped fresh cilantro or spices like cumin and chili powder in step #2.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"microwave-baked-apple","source_url":"https://www.myplate.gov/recipes/microwave-baked-apple","name":"Microwave Baked Apple","description":"Here is a sweet apple treat that you can prepare in minutes in the microwave.","ingredients":[{"name":null,"items":["4 medium baking apples","1/4 cup brown sugar","1 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Wash apples and remove core.","Cut a thin slice off bottom of each apple to form a flat surface. Place apples in a microwave-safe baking dish.","Mix brown sugar and cinnamon in a small dish. Spoon mixture into center of apples.","Cover wax paper and microwave on high power 6 to 10 minutes or until apples are soft."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 baked apple","calories":"158.04 kcal","carbohydrateContent":"39.01 g","cholesterolContent":"0.00 mg","fiberContent":"4.55 g","proteinContent":"0.38 g","sodiumContent":"2.60 mg","sugarContent":"33.00 g","fatContent":"0.31 g","saturatedFatContent":"0.06 g"},"notes":"One pound apples = 3 medium apples = 3 cups sliced apples. This is good information to know at the grocery store.\nFavorite varieties of apples for baking are Jonathan, Granny Smith, Braeburn, and Golden Delicious. Any tart apple works well.\nArrange the apples around the outside edge of the dish for more even cooking in the microwave.\nSafety Tips: Wash the apples in clear running water before coring. If you have apples left, keep in the fridge for a handy snack later on.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"microwave-baked-potato","source_url":"https://www.myplate.gov/recipes/microwave-baked-potato","name":"Microwave Baked Potato","description":"This dish is a great way to enjoy a piping hot baked potato, without even turning on your oven.","ingredients":[{"name":null,"items":["1 potato"]}],"directions":[{"name":null,"steps":["Number of Potatoes\nTime\n1\n7 to minutes or until soft\n2 or 3\n10 to 12 minutes or until soft\n4 or 5\n14 to 18 minutes or until soft","Wash hands with soap and water.","Scrub potato. Prick several times with a fork or knife.","Place on microwave-safe plate.","Cook according to table above.","Turn halfway through cooking.","Let potato rest for 1 to 3 minutes","Add seasonings and toppings as desired."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 potato (299g)","calories":"161.18 kcal","carbohydrateContent":"36.40 g","cholesterolContent":"0.00 mg","fiberContent":"3.81 g","proteinContent":"4.32 g","sodiumContent":"17.81 mg","sugarContent":"2.05 g","fatContent":"0.23 g","saturatedFatContent":"0.05 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"microwave-cauliflower-and-peas-cream-sauce","source_url":"https://www.myplate.gov/recipes/microwave-cauliflower-and-peas-cream-sauce","name":"Microwave Cauliflower and Peas in Cream Sauce","description":"Prepare cauliflower, peas, and onion in a flavorful cream sauce without even turning on your stove.","ingredients":[{"name":null,"items":["2 cups cauliflower","1 cup fresh or frozen peas","2 tablespoons water","1/4 cup onion, chopped","1 1/2 teaspoons butter (or margarine)","1 tablespoon all-purpose flour","1/2 cup fat-free (skim) milk","pimiento (1 tablespoon, chopped, optional)","1/2 teaspoon parsley flakes","1/2 teaspoon chicken bouillon","1/8 teaspoon salt","1 dash ground black pepper"]}],"directions":[{"name":null,"steps":["Combine cauliflower, peas, and water in a 1-quart casserole. Cover. Microwave at High 6 to 8 minutes, or until fork-tender, stirring after half the time. Let stand, covered.","Place onion and butter or margarine in 2-cup measure. Microwave at High 1 to 1 1/2 minutes, or until onion is tender.","Stir in flour. Microwave a few seconds until flour mixture starts to bubble.","Add remaining ingredients. Microwave at High 1 1/2 to 2 minutes, or until thickened, stirring every minute.","Drain vegetables. (Freeze drained liquid for use in soups later.) Pour sauce over vegetables and stir to coat."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"54.04 kcal","carbohydrateContent":"8.32 g","cholesterolContent":"3.32 mg","fiberContent":"2.12 g","proteinContent":"3.04 g","sodiumContent":"130.64 mg","sugarContent":"3.23 g","fatContent":"1.25 g","saturatedFatContent":"0.72 g"},"notes":"Options: Vegetables may be boiled or steamed and sauce prepared on top of a range if a microwave is not available.\nVariations: Use other combinations of vegetables, such as green beans and cauliflower; broccoli and carrots; or peas and carrots.\nAdd lime as a garnish if desired.","contributor":"Creative Vegetable Cookery\nNorth Dakota State University Extension Service"},
{"slug":"microwave-denver-scramble-slider","source_url":"https://www.myplate.gov/recipes/microwave-denver-scramble-slider","name":"Microwave Denver Scramble Slider","description":"This quick egg scramble sandwich is made fast in the microwave for a great on-the-go breakfast, lunch, or snack.","ingredients":[{"name":null,"items":["2 tablespoons red or green bell peppers, chopped","1 tablespoon onion, chopped","1 egg","1 thin slice deli ham, chopped","1 tablespoon water","1 slider-sized bun or whole wheat English muffin, split and toasted"]}],"directions":[{"name":null,"steps":["Place peppers and onions in 8 ounce ramekin or custard cup, or in a small bowl. Microwave on high 30 seconds; stir. Add egg, ham, and water, beat until egg is blended.","Microwave on high 30 seconds; stir. Microwave until egg is almost set, 30 to 45 seconds longer. Season with salt and pepper, if desired.","Serve in bun."]}],"yield":"1 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"185.27 kcal","carbohydrateContent":"15.58 g","cholesterolContent":"216.98 mg","fiberContent":"1.45 g","proteinContent":"13.56 g","sodiumContent":"503.79 mg","sugarContent":"1.55 g","fatContent":"7.83 g","saturatedFatContent":"2.34 g"},"notes":"Don''t overcook. Scrambled eggs will continue to cook and firm up after removed from microwave.\nMicrowave ovens vary. Cook time may need to be adjusted.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"microwave-potato-corn-chowder","source_url":"https://www.myplate.gov/recipes/microwave-potato-corn-chowder","name":"Microwave Potato Corn Chowder","description":"Make this tasty soup in your microwave in minutes. Enjoy it with a fresh salad and a side of fruit for a light meal.","ingredients":[{"name":null,"items":["1/4 cup margarine (or butter)","1/4 cup all-purpose flour","1/4 teaspoon salt","1/8 teaspoon black pepper","2 cups 1% low-fat milk","2 potatoes, peeled and diced","1 cup water","1 can (16 ounces) low-sodium corn, drained"]}],"directions":[{"name":null,"steps":["Melt margarine in glass bowl on HIGH for 30 to 50 seconds.","Stir in flour, salt and pepper until smooth.","Blend milk into flour-margarine mixture.","Cook on HIGH for 6 to 8 minutes, until thickened, stirring well each minute. Set aside.","In a separate microwave safe bowl, cook 2 potatoes in 1 cup water. When potatoes are done add potatoes and cooking water to white sauce.","Stir in one 16 ounce can of corn. Cook 2 to 3 minutes or until steaming hot."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"307.63 kcal","carbohydrateContent":"46.75 g","cholesterolContent":"6.24 mg","fiberContent":"4.08 g","proteinContent":"9.39 g","sodiumContent":"315.01 mg","sugarContent":"11.92 g","fatContent":"10.62 g","saturatedFatContent":"2.52 g"},"notes":"Shredded cheese, crumbled bacon, chopped ham, or onion may be added. Add clams for clam chowder.","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"migas-crumbs","source_url":"https://www.myplate.gov/recipes/migas-crumbs","name":"Migas \"Crumbs\"","description":"Eggs, tortillas, pepper, onion, and cheese are a tasty combination in this quick and easy recipe.","ingredients":[{"name":null,"items":["4 large (10\" across) tortillas","3 tablespoons canola oil","1/4 cup bell pepper","1/4 cup onion","4 egg, lightly beaten","4 tablespoons low-fat cheddar cheese, grated"]}],"directions":[{"name":null,"steps":["Tear tortillas into small pieces.","Heat oil in a medium-sized pan.","Add tortillas and stir until pieces begin to brown.","Add peppers and onion; sauté until soft.","Add eggs; stir until the eggs are cooked.","Remove from heat and sprinkle on the grated cheese.","Cover the pan and let cheese melt.","Serve immediately."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 recipe","calories":"412.11 kcal","carbohydrateContent":"37.28 g","cholesterolContent":"210.87 mg","fiberContent":"2.76 g","proteinContent":"14.15 g","sodiumContent":"632.00 mg","sugarContent":"3.46 g","fatContent":"22.62 g","saturatedFatContent":"5.26 g"},"notes":null,"contributor":"The Texas A&M University System\nTexas Cooperative Extension Expanded Nutrition Program"},
{"slug":"minestrone-soup","source_url":"https://www.myplate.gov/recipes/minestrone-soup","name":"Minestrone Soup","description":"Prepare delicious soup in a snap! Canned beans and frozen veggies make this dish perfect for busy weeknights.","ingredients":[{"name":null,"items":["1 package (10 ounces) frozen vegetables, any type","2 cans (14.5 ounces each) low-sodium stewed tomatoes","2 cans (14.5 ounces each) low-sodium broth, any flavor","1 can (15.5 ounces) low-sodium beans, any type","1 cup dry pasta, any type"]}],"directions":[{"name":null,"steps":["This recipe is developed for a child to help an adult in the kitchen. Directions are written to different audiences.","Adult and child: Wash hands with soap and water.","Child: In a large pot, combine frozen vegetables, tomatoes, broth and beans.","Adult: Bring the soup to a boil and add the pasta. Then reduce to low heat. Let simmer for 6 to 8 minutes or until the pasta and vegetables are tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/6 of recipe"],"calories":"189.88 kcal","carbohydrateContent":"37.42 g","cholesterolContent":"0.00 mg","fiberContent":"10.52 g","proteinContent":"9.34 g","sodiumContent":"203.23 mg","sugarContent":"5.95 g","fatContent":"1.02 g","saturatedFatContent":"0.19 g"},"notes":null,"contributor":"Food Wise Learn at Home Print Materials\nRutgers Cooperative Extension"},
{"slug":"mini-caprese-bites","source_url":"https://www.myplate.gov/recipes/mini-caprese-bites","name":"Mini Caprese Bites","description":"These fun, bite-sized snacks are a great way to use basil and tomatoes from a SNAP-Ed garden. They can also help kids learn to like veggies.","ingredients":[{"name":"toothpicks","items":["1 part-skim cheese stick","4 cherry tomatoes","8 fresh basil leaves","1 teaspoon olive oil, or cooking oil of choice","1 teaspoon balsamic vinegar (or other vinegar)"]}],"directions":[{"name":null,"steps":["Slice string cheese into 4 equal parts.","On a toothpick, skewer one cherry tomato, 2 basil leaves, and 1 piece string cheese.","Drizzle finished kebabs evenly with olive oil and balsamic vinegar."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 mini kebab","calories":"35.37 kcal","carbohydrateContent":"1.04 g","cholesterolContent":"4.61 mg","fiberContent":"0.22 g","proteinContent":"1.85 g","sodiumContent":"50.35 mg","sugarContent":"0.58 g","fatContent":"2.67 g","saturatedFatContent":"1.02 g"},"notes":null,"contributor":null},
{"slug":"mixed-fruit-salad","source_url":"https://www.myplate.gov/recipes/mixed-fruit-salad","name":"Mixed Fruit Salad","description":"Fresh and canned fruit make this juicy salad a wonderful snack or dessert.","ingredients":[{"name":null,"items":["1 can mandarin oranges in light syrup (11 ounce can - drained)","1 can fruit cocktail (15 ounce can - drained)","1 can pineapple chunks (20 ounce can - drained)","2 medium apples (chopped)","1 medium banana (sliced)"]}],"directions":[{"name":null,"steps":["Mix all ingredients together.","Cover and chill until ready to serve.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/6 of recipe"],"calories":"159.65 kcal","carbohydrateContent":"39.93 g","cholesterolContent":"0.00 mg","fiberContent":"3.51 g","proteinContent":"1.31 g","sodiumContent":"11.34 mg","sugarContent":"34.68 g","fatContent":"0.35 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"mixed-grain-bread","source_url":"https://www.myplate.gov/recipes/mixed-grain-bread","name":"Mixed Grain Bread","description":"Using cornmeal, rye, and whole wheat flour gives this chewy and delicious bread a wonderful texture and flavor.","ingredients":[{"name":null,"items":["1/4 cup yellow cornmeal","1/4 cup brown sugar, packed","1 teaspoon salt","2 tablespoons vegetable oil","1/4 cup boiling water","1 packet active dry yeast","1/4 cup warm water, 105 - 115 degrees","1/3 cup whole wheat flour","1/4 cup rye flour","2 1/4 cups all-purpose flour"]}],"directions":[{"name":null,"steps":["Mix cornmeal, brown sugar, salt and oil with boiling water, cool to lukewarm (105 to 115 degrees F).","Dissolve yeast in 1/4 cup warm water; stir into cornmeal mixture. Add whole wheat and rye flours and mix well. Stir in enough all purpose flour to make dough stiff enough to knead.","Turn dough onto lightly floured surface. Knead until smooth and elastic, about 5 to 10 minutes.","Place dough in lightly oiled bowl, turning oil top. Cover with clean towel; let rise in warm place until double, about 1 hour.","Punch dough down; turn onto clean surface. Cover with clean towel; let rest 10 minutes. Shape dough and place in greased 9x5-inch pan. Cover with clean towel; let rise until almost double, about 1 hour.","Preheat oven to 375 degrees F. Bake 35 to 45 minutes or until bread sounds hollow when tapped. Cover with aluminum foil during baking if bread is browning too quickly. Remove bread from pan and cool on wire rack."]}],"yield":"20 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/20 of recipe"],"calories":"92.11 kcal","carbohydrateContent":"17.14 g","cholesterolContent":"0.00 mg","fiberContent":"0.95 g","proteinContent":"2.13 g","sodiumContent":"120.11 mg","sugarContent":"2.74 g","fatContent":"1.69 g","saturatedFatContent":"0.24 g"},"notes":null,"contributor":"Cooking Up Fun - Yeast Breads\nCornell University Cooperative Extension\nDivision of Nutritional Sciences"},
{"slug":"mock-sour-cream","source_url":"https://www.myplate.gov/recipes/mock-sour-cream","name":"Mock Sour Cream","description":"Did you know cottage cheese, skim milk, and lemon juice can be thrown in a blender and taste just like sour cream? Enjoy this quick and easy recipe.","ingredients":[{"name":null,"items":["1 cup low-fat cottage cheese (or fat-free)","2 tablespoons fat-free (skim) milk","1 tablespoon lemon juice"]}],"directions":[{"name":null,"steps":["Combine all in the blender and blend until smooth."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 Tablespoons","calories":"19.83 kcal","carbohydrateContent":"1.21 g","cholesterolContent":"2.80 mg","fiberContent":"0.01 g","proteinContent":"2.60 g","sodiumContent":"74.17 mg","sugarContent":"1.10 g","fatContent":"0.52 g","saturatedFatContent":"0.29 g"},"notes":null,"contributor":"Creative Vegetable Cookery\nNorth Dakota State University Extension Service"},
{"slug":"mock-southern-sweet-potato-pie","source_url":"https://www.myplate.gov/recipes/mock-southern-sweet-potato-pie","name":"Mock Southern Sweet Potato Pie","description":"Full of sweet potato flavor, this delicious pie will be a hit at your next holiday meal.","ingredients":[{"name":"Crust","items":["1 1/4 cups all-purpose flour","1/4 teaspoon sugar","1/3 cup fat-free (skim) milk","2 tablespoons vegetable oil"]},{"name":"Filling","items":["1/4 cup white sugar","1/4 cup brown sugar, packed","1/2 teaspoon salt","1/4 teaspoon nutmeg","3 large eggs, beaten","1/4 cup fat-free evaporated milk, canned","1 teaspoon vanilla extract","3 cups cooked sweet potatoes, skin removed and mashed"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F."]},{"name":"Crust","steps":["Combine the flour and sugar in a bowl.","Add milk and oil to the flour mixture.","Stir with fork until well mixed and then form pastry into a smooth ball with your hands.","Roll the ball between two 12-inch squares of waxed paper using short, brisk strokes until pastry reaches edge of paper.","Peel off top paper and invert crust into pie plate."]},{"name":"Filling","steps":["Combine sugars, salt, spices, and eggs.","Add milk and vanilla. Stir.","Add sweet potatoes and mix well.","Pour mixture into pie shell.","Bake in preheated oven for 60 minutes or until crust is golden brown.","Cool and cut into 16 slices."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/16 of recipe"],"calories":"138.64 kcal","carbohydrateContent":"24.53 g","cholesterolContent":"38.84 mg","fiberContent":"1.82 g","proteinContent":"3.59 g","sodiumContent":"110.53 mg","sugarContent":"10.34 g","fatContent":"2.88 g","saturatedFatContent":"0.60 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"mousse-la-banana","source_url":"https://www.myplate.gov/recipes/mousse-la-banana","name":"Mousse a la Banana","description":"This sweet, creamy, and fruity treat is low in fat and rich in flavor.","ingredients":[{"name":null,"items":["2 tablespoons low-fat 1% milk","4 teaspoons sugar","1 teaspoon vanilla","1 medium banana, cut into quarters","1 cup low-fat plain yogurt","8 slices banana, 1/4-inch each"]}],"directions":[{"name":null,"steps":["Place milk, sugar, vanilla, and banana in blender. Process 15 seconds at high speed until smooth.","Pour mixture into a small bowl; fold in yogurt. Chill. Spoon into four dessert dishes; garnish each with two banana slices just before serving."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"103.93 kcal","carbohydrateContent":"18.90 g","cholesterolContent":"4.06 mg","fiberContent":"0.74 g","proteinContent":"3.80 g","sodiumContent":"45.99 mg","sugarContent":"15.89 g","fatContent":"1.16 g","saturatedFatContent":"0.70 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"mouth-watering-oven-fried-fish","source_url":"https://www.myplate.gov/recipes/mouth-watering-oven-fried-fish","name":"Mouth-Watering Oven-Fried Fish","description":"This spicy and savory oven-fried fish will be a hit in your home. Enjoy it with seasonal vegetables and a side of your favorite fruit.","ingredients":[{"name":null,"items":["2 pounds cod fish fillets (or other white fish)","1 tablespoon fresh lemon juice","1/4 cup low-fat 1% buttermilk","1 teaspoon fresh garlic, minced","2 dashs hot sauce","1/4 teaspoon ground white pepper","1/4 teaspoon salt","1/4 teaspoon onion powder","1/2 cup corn flakes, crumbled (or regular breadcrumbs)","1 tablespoon vegetable oil (or cooking oil of choice)","1 fresh lemon, cut into wedges"]}],"directions":[{"name":null,"steps":["Preheat oven to 475 degrees F.","Clean and rinse fish. Wipe fillets with lemon juice and pat dry.","Combine buttermilk, garlic, and hot sauce in a medium bowl.","Combine pepper, salt, and onion powder with crumbs and place on plate.","Let fillets sit briefly in milk. Remove and coat fillets on both sides with seasoned crumbs. Let stand briefly until coating sticks to each side of fish.","Arrange on lightly oiled shallow baking dish.","Bake for 20 minutes on middle rack without turning.","Cut into 6 pieces. Serve with fresh lemon wedges."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 piece of fish","calories":"127.27 kcal","carbohydrateContent":"4.01 g","cholesterolContent":"64.05 mg","fiberContent":"0.47 g","proteinContent":"22.01 g","sodiumContent":"272.60 mg","sugarContent":"1.11 g","fatContent":"2.78 g","saturatedFatContent":"0.45 g"},"notes":"Atlantic cod used for nutritional analysis.\nMay substitute black pepper for white pepper.\nOptional - add parsley as a garnish.","contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"mozz-totz","source_url":"https://www.myplate.gov/recipes/mozz-totz","name":"Mozz Totz","description":"A healthy twist on a deep-fried appetizer, these breaded and baked Mozz Totz are a favorite of kids and adults alike. Served with warm marinara sauce for dip...","ingredients":[{"name":null,"items":["12 ounces fat-free mozzarella string cheese","1/2 cup low-fat 1% milk","1/2 teaspoon dried oregano","1/2 teaspoon dried basil","1/2 cup breadcrumbs","1/2 cup marinara sauce, warmed","non-stick cooking spray"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Line a baking sheet with foil and spray lightly with cooking spray.","Remove cheese from package and cut into bite size pieces.","In a small non-stick skillet mix oregano and basil with breadcrumbs.","Cook over medium heat, stirring occasionally until crumbs are lightly browned, about 5 minutes.","Dip each piece of cheese in milk and then into toasted bread crumbs, coating completely.","Place on baking sheet about 1 1/2-inches apart.","Spray string cheese lightly with non-stick cooking spray.","Bake 5 to 6 minutes or until heated through. (Cheese may melt slightly and lose shape. Simply press it back into place).","Dip in warmed marinara sauce and enjoy."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"67.98 kcal","carbohydrateContent":"5.71 g","cholesterolContent":"5.83 mg","fiberContent":"0.96 g","proteinContent":"10.10 g","sodiumContent":"293.00 mg","sugarContent":"1.80 g","fatContent":"0.50 g","saturatedFatContent":"0.13 g"},"notes":null,"contributor":"Champions for Change Recipes\nArizona Nutrition Network"},
{"slug":"mozzarella-chicken-garlic-spinach","source_url":"https://www.myplate.gov/recipes/mozzarella-chicken-garlic-spinach","name":"Mozzarella Chicken with Garlic Spinach","description":"Chicken, mozzarella, and spinach seasoned with garlic make this an easy and delicious dinner.","ingredients":[{"name":null,"items":["8 small chicken breast halves, skin and bone removed","1/2 cup Italian seasoned breadcrumbs, crushed","8 ounces part skim mozzarella cheese, shredded","1 tablespoon canola oil (or cooking oil of choice)","4 cloves garlic, minced","2 packages (10 ounces each) spinach leaves"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 degrees F.","Place chicken between 2 sheets of plastic wrap; pound chicken to 1/4 inch thick.","Coat chicken with breadcrumbs and place on foil-covered baking sheet. Discard remaining breadcrumbs. Bake 10 minutes.","Top chicken with cheese; bake 4 to 5 minutes until cheese is melted and chicken reaches an internal temperature of 165 °F.","Meanwhile, heat oil in a large skillet on medium heat. Add garlic and stir 1 minute.","Add half the spinach and cook 1 minute.","Add remaining spinach. Cook until wilted, turning occasionally. Serve with chicken."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"294.44 kcal","carbohydrateContent":"8.24 g","cholesterolContent":"108.45 mg","fiberContent":"1.38 g","proteinContent":"37.33 g","sodiumContent":"360.91 mg","sugarContent":"1.21 g","fatContent":"11.51 g","saturatedFatContent":"4.25 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"muffins-better-baking-mix","source_url":"https://www.myplate.gov/recipes/muffins-better-baking-mix","name":"Muffins (from Better Baking Mix)","description":"Try the original recipe using our Better Baking Mix, or try one of the variations with fruit and spice for a wonderful fresh baked treat.","ingredients":[{"name":null,"items":["2 Better Baking Mix","1/2 cup sugar","1 egg","1/4 cup vegetable oil","2/3 cup water"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 degrees F.","Grease 12-cup muffin pan.","Mix the Better Baking Mix and sugar in a bowl.","Beat the egg with a fork.","Add egg, oil, and water to dry ingredients. Stir just until all ingredients are wet.","Spoon into the prepared muffin pan."]}],"yield":"12 muffins","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"143.78 kcal","carbohydrateContent":"20.38 g","cholesterolContent":"17.46 mg","fiberContent":"0.85 g","proteinContent":"2.86 g","sodiumContent":"95.33 mg","sugarContent":"9.28 g","fatContent":"5.60 g","saturatedFatContent":"0.86 g"},"notes":"Blueberry muffins: Gently stir 1 cup fresh or frozen blueberries into batter.\nApple muffins: Add 1 teaspoon cinnamon to the dry ingredients. Reduce water to 1/2 cup. At the end of mixing, gently stir in 1 cup finely chopped fresh apples.","contributor":"Washington State University Extension"},
{"slug":"mushroom-barley-soup","source_url":"https://www.myplate.gov/recipes/mushroom-barley-soup","name":"Mushroom Barley Soup","description":"Prepare this hearty soup with vegetable broth if you desire it to be vegetarian or vegan.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","1 medium onion, chopped","2 medium celery stalks, sliced thin","2 medium carrots, peeled and sliced thin","2 cups mushrooms, sliced","1 cup potatoes, cut into pieces","1/2 cup quick cooking barley","1 teaspoon garlic powder","1/2 teaspoon ground thyme","3 cups low-sodium chicken broth","2 cups water","1 tablespoon fresh parsley, chopped"]}],"directions":[{"name":null,"steps":["Heat oil in large soup pot over high heat. Sauté onion, celery, carrots, and mushrooms until golden, about 4 minutes.","Add the rest of the ingredients except for the parsley and bring to a boil.","Lower heat to a simmer and cook until the barley is tender, about 20 minutes.","Sprinkle parsley on top of soup and serve hot."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"250.91 kcal","carbohydrateContent":"44.82 g","cholesterolContent":"0.00 mg","fiberContent":"6.58 g","proteinContent":"8.46 g","sodiumContent":"105.10 mg","sugarContent":"4.73 g","fatContent":"5.32 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"mushroom-beef-sloppy-joes","source_url":"https://www.myplate.gov/recipes/mushroom-beef-sloppy-joes","name":"Mushroom Beef Sloppy Joes","description":"Chopped mushrooms, when sautéed, blend seamlessly with ground meats. Swapping or adding mushrooms to a recipe can add an extra serving of vegetables to the ...","ingredients":[{"name":null,"items":["1/2 pound white button mushrooms","1/2 pound cremini mushrooms","1/4 pound 90% lean ground beef","1 1/2 tablespoons canola oil","1/2 cup chopped onions","1 clove garlic, minced","1 8-ounce can no-salt-added tomato sauce","1 tablespoon chili powder","3 teaspoons brown sugar","1 teaspoon cider vinegar","1/8 teaspoon ground black pepper","4 whole-wheat buns"]}],"directions":[{"name":null,"steps":["Chop mushrooms to approximate size and texture of cooked ground beef.","Heat a sauté pan over medium-high heat.","Add ground beef and mushrooms, and cook.","Sauté until ground beef is done.","Remove mushroom-beef mixture from pan.","Add onions and garlic to pan; cook until golden.","Return mushroom-beef mixture to pan, along with remaining ingredients.","Simmer about 10 minutes; remove from heat."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"274.29 kcal","carbohydrateContent":"32.42 g","cholesterolContent":"16.43 mg","fiberContent":"4.56 g","proteinContent":"12.86 g","sodiumContent":"311.30 mg","sugarContent":"7.96 g","fatContent":"10.89 g","saturatedFatContent":"1.94 g"},"notes":"Serving Suggestions: Serve with a glass of non-fat milk and a slice of watermelon.","contributor":"Produce for Better Health Foundation"},
{"slug":"mushroom-steak-fajitas","source_url":"https://www.myplate.gov/recipes/mushroom-steak-fajitas","name":"Mushroom Steak Fajitas","description":"Bring another serving of vegetables and important nutrients to your plate with this veggie-filled twist on classic fajitas. We''ve upped the vegetables ante b...","ingredients":[{"name":null,"items":["12 ounces sirloin or other boneless steak (about 3/4-inch thick)","3 cups sliced cremini mushrooms","1 tablespoon no-salt fiesta lime seasoning (divided)","1 tablespoon olive oil","1 cup green bell pepper, sliced into strips","1 medium red bell pepper, sliced into strips","1 medium yellow bell pepper, sliced into strips","8 whole-wheat tortillas, 6-inch","1 medium tomato, diced","2 cups shredded iceberg lettuce","4 tablespoons non-fat sour cream"]}],"directions":[{"name":null,"steps":["Slice beef across the grain into 1/4-inch strips. Place in a medium bowl with 1/2 tablespoon fiesta lime seasoning; toss to coat.","Place mushrooms, peppers, and onion and remaining fiesta lime seasoning in a large bowl; toss to coat.","Heat oil in large, non-stick skillet. Add beef strips; cook about 3 to 4 minutes. Remove from skillet.","Place coated vegetables in skillet and sauté until vegetables are slightly tender, about 5 to 8 minutes.","Add beef back to skillet and sauté mixture 1 to 2 more minutes.","Assemble fajitas by dividing beef-vegetable mixture evenly on each tortilla, top with remaining ingredients and roll up."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"450.88 kcal","carbohydrateContent":"43.41 g","cholesterolContent":"57.59 mg","fiberContent":"9.01 g","proteinContent":"29.19 g","sodiumContent":"474.64 mg","sugarContent":"7.73 g","fatContent":"18.35 g","saturatedFatContent":"6.81 g"},"notes":"Serving Suggestions: Serve with a glass of non-fat milk and side of mango chunks.","contributor":"Produce for Better Health Foundation"},
{"slug":"naan","source_url":"https://www.myplate.gov/recipes/naan","name":"Naan","description":"Enjoy the amazing smell coming from your grill as you make this delicious naan. Be sure to savor the delicious flavor and texture while it is still warm!","ingredients":[{"name":null,"items":["1 packet of active dry yeast (1/4 ounce)","1 cup warm water","1/4 cup sugar","3 tablespoons low-fat 1% milk","1 egg, beaten","2 teaspoons salt","4 1/2 cups bread flour","garlic, minced (2 teaspoons, optional)","4 tablespoons butter, melted (1/4 cup)"]}],"directions":[{"name":null,"steps":["In a large bowl, dissolve yeast in warm water and let stand about 10 minutes, or until frothy.","Stir in sugar, milk, egg, salt, and enough flour to make a soft dough.","Knead for 6 - 8 minutes on a lightly floured surface or until smooth.","Let it rise 1 hour until the dough has doubled in volume.","Punch down dough and knead in garlic.","Pinch off small handfuls of dough about the size of a golf ball.","Roll into balls and place on a tray.","Cover with a towel and allow to rise until doubled in size, about 30 minutes.","During the second rising, preheat grill to high heat.","At grill side, roll one ball of dough out into a thin circle.","Lightly oil grill. Place dough on grill and cook for 2 - 3 minutes or until puffy and lightly browned.","Brush uncooked side with butter and turn over.","Brush cooked side with butter and cook until browned, another 2 to 4 minutes.","Remove from grill and continue the process until all the naan has been prepared."]}],"yield":"40 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 piece","1/40 of recipe"],"calories":"73.70 kcal","carbohydrateContent":"12.57 g","cholesterolContent":"8.25 mg","fiberContent":"0.42 g","proteinContent":"2.12 g","sodiumContent":"120.90 mg","sugarContent":"1.36 g","fatContent":"1.56 g","saturatedFatContent":"0.80 g"},"notes":null,"contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"neopolitan-tuna-fettuccine","source_url":"https://www.myplate.gov/recipes/neopolitan-tuna-fettuccine","name":"Neopolitan Tuna Fettuccine","description":"Did you know that canned tomatoes have more lycopene and B vitamins than fresh tomatoes? That’s because the canning process seals in food’s natural goodn...","ingredients":[{"name":null,"items":["8 ounces whole grain fettuccine pasta","1 tablespoon olive oil","1 small onion, diced","2 cloves garlic, minced","1 can no salt added diced tomatoes (14.5 oz. can)","2 teaspoons capers","5 ounces canned tuna packed in water, drained","1/4 cup sliced ripe olives, drained (or 1 2.2-ounce can)","Salt and ground pepper to taste"]}],"directions":[{"name":null,"steps":["Cook fettuccine as label directs. Reserve 1 cup cooking liquid; drain.","Meanwhile, in 10-inch skillet over medium heat, in hot oil, cook onion and garlic, about 5 minutes until just softened. Add diced tomatoes and capers; simmer 5 minutes. Add tuna, olives, salt, and pepper to taste.","Toss fettuccine with tuna mixture to mix well. Serve immediately. If necessary, add reserved cooking liquid."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"344.93 kcal","carbohydrateContent":"56.15 g","cholesterolContent":"12.76 mg","fiberContent":"9.08 g","proteinContent":"17.71 g","sodiumContent":"288.33 mg","sugarContent":"5.42 g","fatContent":"8.00 g","saturatedFatContent":"1.28 g"},"notes":null,"contributor":"Cans Get You Cooking"},
{"slug":"new-orleans-red-beans","source_url":"https://www.myplate.gov/recipes/new-orleans-red-beans","name":"New Orleans Red Beans","description":"Spice up your week with these delicious New Orleans Red Beans. Season with hot sauce if desired.","ingredients":[{"name":null,"items":["1 pound dry red beans","8 cups water (2 quarts)","1 1/2 cups onions, chopped","1 cup celery, chopped","4 bay leaves","1 cup green peppers, chopped","3 tablespoons garlic, chopped","3 tablespoons fresh parsley, chopped","2 teaspoons dried thyme, crushed","1 teaspoon salt","1 teaspoon ground black pepper"]}],"directions":[{"name":null,"steps":["Pick through beans to remove bad beans; rinse thoroughly.","In a large pot combine beans, water, onion, celery, and bay leaves. Bring to a boil; reduce heat. Cover and cook over low heat for about 1-1/2 hours until beans are tender. Stir. Mash beans against side of pan.","Add green pepper, garlic, parsley, thyme, salt, and black pepper. Cook, uncovered, over low heat until creamy (about 30 minutes). Remove bay leaves.","Serve with hot cooked brown rice, if desired."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup","calories":"197.25 kcal","carbohydrateContent":"36.75 g","cholesterolContent":"0.00 mg","fiberContent":"11.37 g","proteinContent":"12.62 g","sodiumContent":"322.85 mg","sugarContent":"2.53 g","fatContent":"0.84 g","saturatedFatContent":"0.14 g"},"notes":null,"contributor":"Stay Young at Heart: Cooking the Heart-Healthy Way\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"no-bake-breakfast-cookies","source_url":"https://www.myplate.gov/recipes/no-bake-breakfast-cookies","name":"No Bake Breakfast Cookies","description":"Sweet breakfast cookies that can be prepared in advance for breakfast on the go.","ingredients":[{"name":null,"items":["1/2 cup honey* (or light corn syrup)","1/2 cup creamy peanut butter","1/2 cup non-fat dry milk","2 1/2 cups crushed flaked cereal","1/2 cup raisins (or chopped dates)"]}],"directions":[{"name":null,"steps":["Heat honey and peanut butter in a medium saucepan over low heat. Stir until blended.","Remove from heat. Stir in dry milk.","Fold in cereal and raisins. Drop by heaping tablespoons onto waxed paper to form mounds.","Cool to room temperature. Store in refrigerator."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cookies","calories":"161.70 kcal","carbohydrateContent":"25.09 g","cholesterolContent":"0.57 mg","fiberContent":"1.06 g","proteinContent":"4.09 g","sodiumContent":"107.12 mg","sugarContent":"18.48 g","fatContent":"5.59 g","saturatedFatContent":"1.11 g"},"notes":"*Children under the age of one should not consume honey.","contributor":"Buy Better. Eat Better.\nMontana State University Extension Service\nNutrition Education Program"},
{"slug":"no-bake-cookies","source_url":"https://www.myplate.gov/recipes/no-bake-cookies","name":"No-Bake Cookies","description":"Boiled instead of baked, these chewy cookies are full of peanut butter, cocoa, oats, and raisins. Yum!","ingredients":[{"name":null,"items":["2 cups sugar","3 tablespoons unsweetened cocoa powder","1/2 teaspoon salt","1/2 cup margarine","1 cup peanut butter","1/2 cup water","4 cups rolled oats","1 cup non-fat dry milk","1 cup raisins","1 teaspoon vanilla"]}],"directions":[{"name":null,"steps":["In large sauce pan, bring the first six ingredients to a full, rolling boil for 1 minute, stirring as needed.","Remove from heat. Add oats, dry milk, raisins, and vanilla to boiled mixture.","Mix well.","Drop by tablespoons onto waxed paper and let stand until cool, about 15 to 20 minutes."]}],"yield":"36 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cookie or 1/36 of recipe","calories":"161.68 kcal","carbohydrateContent":"23.46 g","cholesterolContent":"0.41 mg","fiberContent":"1.59 g","proteinContent":"3.69 g","sodiumContent":"96.40 mg","sugarContent":"15.83 g","fatContent":"6.19 g","saturatedFatContent":"1.24 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"oat-bran-muffins","source_url":"https://www.myplate.gov/recipes/oat-bran-muffins","name":"Oat Bran Muffins","description":"Full of fruit and oat bran, these tasty muffins can be enjoyed as a snack or a dessert.","ingredients":[{"name":null,"items":["2 1/4 cups oat bran","1/4 cup brown sugar, firmly packed","1 1/2 teaspoons cinnamon","1 tablespoon baking powder","1 large egg","1/2 cup orange juice","3/4 cup non-fat (skim) milk","2 tablespoons canola oil","3/4 cup unsweetened applesauce","1 medium banana, mashed","2 tablespoons raisins, dates, or other dried fruit"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 degrees F.","In a large bowl, mix the first four dry ingredients. Set aside.","In another bowl, mix the egg with orange juice, milk, and oil.","In small bowl, mix fruit and blend with dry ingredients.","Add the liquid ingredients to the dry until it is moist.","Spray muffin tin with a non-stick coating. Pour batter into muffin tins.","Bake for 15 to 17 minutes. Remove muffins from pan after 10 minutes. Cool on a rack. Freeze muffins for later use."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"120.79 kcal","carbohydrateContent":"24.01 g","cholesterolContent":"17.58 mg","fiberContent":"3.34 g","proteinContent":"4.35 g","sodiumContent":"136.29 mg","sugarContent":"10.51 g","fatContent":"4.09 g","saturatedFatContent":"0.55 g"},"notes":null,"contributor":"Utah State University Cooperative Extension"},
{"slug":"oat-snack-cakes","source_url":"https://www.myplate.gov/recipes/oat-snack-cakes","name":"Oat Snack Cakes","description":"These oat snack cakes are full of whole grains and flavor, making them perfect for sharing with friends and family.","ingredients":[{"name":null,"items":["6 cups uncooked oatmeal","2 cups whole wheat flour","1 cup all-purpose flour","1 cup sugar","1 teaspoon baking soda","1/2 teaspoon salt","1 teaspoon cinnamon","3/4 cup margarine, softened","1/2 cup vegetable oil","2 teaspoons vanilla flavoring","2 egg whites, beaten","1 tablespoon water","1 cup raisins"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 degrees F. Mix together oatmeal, flour, sugar, baking soda, salt, and cinnamon in a large bowl.","Cut in margarine until mixture resembles coarse meal.","Combine oil, vanilla, egg whites, and water. Stir into dry ingredients and add raisins, mixing only until it holds together.","Wash hands thoroughly, then dip in cornmeal or flour. Pinch off pieces of dough and form into balls about 1 inch in diameter.","Place balls on baking pan (sprayed with non-stick cooking spray) and press out slightly to about 1/4-inch in thickness.","Bake 15 to 20 minutes or until lightly browned. Cool, then store in an airtight container."]}],"yield":"60 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cake","1/60 of recipe"],"calories":"105.65 kcal","carbohydrateContent":"15.42 g","cholesterolContent":"0.03 mg","fiberContent":"1.44 g","proteinContent":"2.01 g","sodiumContent":"62.70 mg","sugarContent":"5.19 g","fatContent":"4.20 g","saturatedFatContent":"0.71 g"},"notes":null,"contributor":"Healthy Futures\nVirginia Cooperative Extension"},
{"slug":"oatmeal-bread","source_url":"https://www.myplate.gov/recipes/oatmeal-bread","name":"Oatmeal Bread","description":"Packed with whole grains, this tasty bread is perfect as a snack topped with jam or peanut butter.","ingredients":[{"name":null,"items":["1 cup rolled oats","1 teaspoon salt","1 1/2 cups boiling water","1 packet active dry yeast","1/4 cup warm water (105 to 115 degrees F)","1/4 cup molasses","1 1/2 tablespoons vegetable oil","2 cups whole wheat flour","2 cups all-purpose flour"]}],"directions":[{"name":null,"steps":["Combine rolled oats and salt in a large mixing bowl. Stir in boiling water; cool to lukewarm (105 to 115 degrees F).","Dissolve yeast in 1/4 cup warm water in small bowl.","Add yeast water, molasses, and oil to cooled oatmeal mixture. Stir in whole wheat flour and 1 cup all-purpose flour. Add additional all-purpose flour to make a dough stiff enough to knead.","Knead dough on lightly floured surface until smooth and elastic, about 5 minutes.","Place dough in lightly oiled bowl, turning to oil top. Cover with clean towel; let rise in warm place until double, about 1 hour.","Punch dough down; turn onto clean surface. Shape dough and place in greased 9x5 inch pan. Cover with clean towel; let rise in a warm place until almost double, about 1 hour.","Preheat oven to 375 degrees F. Bake 50 minutes or until bread sounds hollow when tapped. Cover with aluminum foil during baking if bread is browning too quickly. Remove bread from pan and cool on wire rack."]}],"yield":"20 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/20 of recipe"],"calories":"123.68 kcal","carbohydrateContent":"24.02 g","cholesterolContent":"0.00 mg","fiberContent":"2.12 g","proteinContent":"3.55 g","sodiumContent":"121.27 mg","sugarContent":"3.11 g","fatContent":"1.76 g","saturatedFatContent":"0.26 g"},"notes":null,"contributor":"Cooking Up Fun - Yeast Breads\nCornell University Cooperative Extension\nDivision of Nutritional Sciences"},
{"slug":"oatmeal-raisin-muffins","source_url":"https://www.myplate.gov/recipes/oatmeal-raisin-muffins","name":"Oatmeal Raisin Muffins","description":"What''s better than a toasty muffin right out of the oven? Enjoy these oatmeal raisin muffins with your breakfast or as a snack or dessert.","ingredients":[{"name":null,"items":["1 egg","1 cup fat-free (skim) milk","1/3 cup vegetable oil","1 1/4 cups all-purpose flour","1 cup oatmeal","1/3 cup sugar","1 teaspoon baking powder","1 teaspoon salt","1/2 cup raisins","1 teaspoon margarine or butter, to grease the muffin cups"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 degrees F.","Put the milk, egg, and oil in a small mixing bowl. Slowly stir them together.","In a large mixing bowl, mix the flour, oatmeal, sugar, baking powder, salt, and raisins. Stir until they are mixed.","Pour the milk-egg-oil mix into the large bowl with the dry ingredients.","Stir until the dry ingredients are barely moistened. Do not over-mix (the batter should be lumpy).","Grease each cup in the muffin pans with some margarine or butter.","Spoon the batter into the cups in each muffin pan, until each cup is half-full with batter.","Bake for 20 to 25 minutes, or until the muffins are golden brown."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"185.24 kcal","carbohydrateContent":"26.36 g","cholesterolContent":"17.74 mg","fiberContent":"1.33 g","proteinContent":"3.66 g","sodiumContent":"256.14 mg","sugarContent":"10.97 g","fatContent":"7.42 g","saturatedFatContent":"1.14 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"okra-and-greens","source_url":"https://www.myplate.gov/recipes/okra-and-greens","name":"Okra and Greens","description":"Spicy and flavorful, this is an amazing side dish that doubles easily. Double up and enjoy it with a crowd during the summer months when okra is in season.","ingredients":[{"name":null,"items":["1 small onion, finely chopped","2 tablespoons corn oil (or cooking oil of choice)","6 cups greens, shredded (1 pound)","16 okra pods","4 chili peppers, finely chopped and crushed","1/4 cup water","1 lemon, juiced"]}],"directions":[{"name":null,"steps":["In a large heavy pan sauté onions in oil until golden brown.","Add remaining ingredients, except for lemon juice. Simmer over low heat, covered, until greens are tender.","Squeeze on lemon juice before serving."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"97.78 kcal","carbohydrateContent":"10.07 g","cholesterolContent":"0.00 mg","fiberContent":"4.15 g","proteinContent":"2.88 g","sodiumContent":"14.47 mg","sugarContent":"2.86 g","fatContent":"6.10 g","saturatedFatContent":"0.82 g"},"notes":"You can substitute about 2 cups of cut/frozen okra in place of whole okra.","contributor":"Ohio Commission on Minority Health"},
{"slug":"old-fashioned-bread-pudding","source_url":"https://www.myplate.gov/recipes/old-fashioned-bread-pudding","name":"Old Fashioned Bread Pudding","description":"This old fashioned bread pudding can be made in the microwave so you don''t have to turn on the oven. Enjoy!","ingredients":[{"name":null,"items":["5 slices whole wheat bread","2 tablespoons margarine or butter","1/4 teaspoon cinnamon","1/3 cup sugar","1/2 cup raisins","3 eggs (or 1 egg + 2 egg whites)","1 1/2 cups non-fat (skim) milk","1/4 teaspoon salt","1 teaspoon vanilla extract"]}],"directions":[{"name":null,"steps":["Spread one side of bread with margarine or butter. Sprinkle with cinnamon.","Cut into 1-inch cubes.","In lightly sprayed casserole dish, combine bread, sugar, and raisins. Then follow microwave or oven method below."]},{"name":"Microwave method","steps":["In bowl, blend eggs, milk, salt and vanilla. Pour liquid over bread mixture; lightly blend.","Cover, microwave on HIGH for 5 minutes. Turn dish 1/4 turn. Microwave on HIGH for 3-5 minutes longer (pudding is done when edges are firm and center is almost set).","Let sit covered for 10 minutes before serving. Serve warm or cold. Refrigerate leftovers."]},{"name":"Oven method","steps":["Preheat oven to 350 degrees F. In bowl, blend eggs, 2 cups milk (instead of 1 1/2 cups for microwaving), salt, and vanilla. Pour liquid over bread mixture; lightly blend.","Bake uncovered for 1 hour (pudding is done when a table knife inserted in the pudding comes out clean).","Serve warm or cold. Refrigerate leftovers."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/6 of recipe"],"calories":"243.82 kcal","carbohydrateContent":"37.92 g","cholesterolContent":"104.63 mg","fiberContent":"2.46 g","proteinContent":"9.33 g","sodiumContent":"325.73 mg","sugarContent":"24.22 g","fatContent":"6.46 g","saturatedFatContent":"1.63 g"},"notes":null,"contributor":"Simply Good Eating Recipe Cards, Vol. 1, 2000\nUniversity of Minnesota Cooperative Extension Service"},
{"slug":"old-fashioned-dressing","source_url":"https://www.myplate.gov/recipes/old-fashioned-dressing","name":"Old Fashioned Dressing","description":"Some call it dressing, while others call it stuffing. Either way, you''ll call it delicious! Enjoy this old fashioned dressing with your next holiday meal or ...","ingredients":[{"name":null,"items":["8 slices whole wheat bread, cubed","4 tablespoons margarine or butter","2 cups celery, diced","1 cup onion, chopped","2 tablespoons fresh parsley, chopped","1/4 cup mushroom, sliced","1 teaspoon ground sage","3/4 teaspoon poultry seasoning","1 teaspoon black pepper","3 cups low-sodium chicken broth (or turkey)"]}],"directions":[{"name":null,"steps":["Toast bread cubes and set aside for later use.","Melt margarine or butter in medium size fry pan.","Add celery and onion; cook until tender, about 10 minutes.","Add parsley, mushrooms, seasonings, and broth. Cook for 5 minutes.","Remove from heat and add the toasted bread cubes. Cover and let stand 10 minutes. Serve immediately.","Refrigerate leftovers within 2 hours."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe","calories":"140.43 kcal","carbohydrateContent":"18.33 g","cholesterolContent":"0.06 mg","fiberContent":"2.86 g","proteinContent":"6.13 g","sodiumContent":"234.60 mg","sugarContent":"2.65 g","fatContent":"5.10 g","saturatedFatContent":"1.09 g"},"notes":null,"contributor":"Oregon State University Cooperative Extension Service"},
{"slug":"one-dish-roasted-potatoes-and-apples-chicken-sausage","source_url":"https://www.myplate.gov/recipes/one-dish-roasted-potatoes-and-apples-chicken-sausage","name":"One-Dish Roasted Potatoes and Apples with Chicken Sausage","description":"A scrumptious and easy one-dish baked meal that''s perfect for chilly fall and winter evenings.","ingredients":[{"name":null,"items":["3 red potatoes or your favorite potato variety (about 1 pound)","1 tablespoon canola oil","2 red apples (Fuji, Pink Lady, Honeycrisp, Gala, etc.)","1 yellow onion","4 chicken herb link sausages (12 ounces)","2 tablespoons cider vinegar","1/2 teaspoon ground mustard","1 tablespoon honey"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 °F.","Cut potatoes into chunks, place in 2-quart baking dish.","Drizzle with canola oil. Toss to coat.","Roast potatoes in oven for about 20 minutes.","While potatoes are roasting, cut apples and onions into chunks, and sausage into 1/2-inch slices.","Remove baking dish from oven and reduce heat to 375 °F. Add all remaining ingredients to baking dish and toss.","Return baking dish to oven and roast an additional 30 minutes until apples and potatoes are tender."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"359.98 kcal","carbohydrateContent":"43.58 g","cholesterolContent":"69.00 mg","fiberContent":"4.63 g","proteinContent":"17.73 g","sodiumContent":"543.27 mg","sugarContent":"19.30 g","fatContent":"13.08 g","saturatedFatContent":"2.56 g"},"notes":null,"contributor":"Produce for Better Health"},
{"slug":"one-pan-potatoes-chicken","source_url":"https://www.myplate.gov/recipes/one-pan-potatoes-chicken","name":"One Pan Potatoes & Chicken","description":"This is an easy and flavorful one pan meal. Salsa adds an extra kick to the dish.","ingredients":[{"name":null,"items":["4 medium potatoes","16 ounces chicken breasts, boned and skinned","2 tablespoons vegetable oil (or cooking oil of choice)","1 cup salsa","1 can (15.2 ounces) low-sodium whole kernel corn, drained"]}],"directions":[{"name":null,"steps":["Cut potatoes into 3/4 in cubes.","Microwave potatoes for 8-10 minutes until tender OR cook potatoes on the stovetop. To cook on the stovetop, place potatoes in water, bring to a boil and then reduce heat to a simmer until potatoes are tender, about 15 minutes. Drain potatoes.","Cut chicken into 3/4-inch cubes","In a large skillet, brown chicken in oil on high for 5 minutes.","Add potatoes; cook until potatoes are lightly browned.","Add salsa and corn. Cook until heated through."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"286.02 kcal","carbohydrateContent":"36.48 g","cholesterolContent":"50.04 mg","fiberContent":"4.28 g","proteinContent":"20.10 g","sodiumContent":"222.99 mg","sugarContent":"5.43 g","fatContent":"7.27 g","saturatedFatContent":"1.13 g"},"notes":null,"contributor":"Kentucky Families on the Move: Food and Nutrition Calendar, 2005\nUniversity of Kentucky Cooperative Extension Service"},
{"slug":"one-pan-spaghetti","source_url":"https://www.myplate.gov/recipes/one-pan-spaghetti","name":"One Pan Spaghetti","description":"Perfect for a busy weeknight, this one pan spaghetti dish has grains, vegetables, meat, and dairy. Enjoy it with a side of fruit.","ingredients":[{"name":null,"items":["1 pound 90% lean ground beef","1 medium onion, chopped","3 1/2 cups water","1 can (15 ounces) low-sodium tomato sauce","1/2 teaspoon sugar","2 teaspoons dried oregano","1/2 teaspoon garlic powder","1/2 teaspoon rosemary","1/4 teaspoon black pepper","16 ounces spaghetti noodles, broken","1 cup Parmesan cheese, shredded"]}],"directions":[{"name":null,"steps":["Brown meat and onions in a large skillet over medium-high heat (300 degrees F in an electric skillet). Drain fat.","Stir in water, tomato sauce, sugar, and spices; bring to a boil.","Add spaghetti, cover pan, and simmer 10 to 15 minutes, stirring often to prevent sticking.","When spaghetti is tender, top with grated cheese.","Refrigerate leftovers with in 2 hours."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"317.48 kcal","carbohydrateContent":"44.44 g","cholesterolContent":"33.17 mg","fiberContent":"3.39 g","proteinContent":"18.43 g","sodiumContent":"145.85 mg","sugarContent":"3.12 g","fatContent":"6.99 g","saturatedFatContent":"2.89 g"},"notes":"For 16 ounces of broken spaghetti noodles, use about 1/3 of a one pound box.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"one-pan-taco-rice","source_url":"https://www.myplate.gov/recipes/one-pan-taco-rice","name":"One Pan Taco Rice","description":"Try this quick one-pan meal may soon become a family favorite.","ingredients":[{"name":null,"items":["1 pound 85% lean ground turkey (or lean ground beef)","1 cup onion, chopped","4 tablespoons Chili and Spice Seasoning","2 cans (10 ounces each) tomatoes and green chiles","3 cups brown rice, cooked","1/2 cup low-fat shredded cheese"]}],"directions":[{"name":null,"steps":["In a large skillet or pot, brown ground turkey and cook onion. When done, use paper towel to soak up any grease.","Add remaining ingredients, except cheese, and mix together.","Heat until very hot.","Top with cheese before serving."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"322.76 kcal","carbohydrateContent":"33.66 g","cholesterolContent":"63.25 mg","fiberContent":"3.45 g","proteinContent":"19.98 g","sodiumContent":"515.09 mg","sugarContent":"1.58 g","fatContent":"12.52 g","saturatedFatContent":"3.95 g"},"notes":"Low-fat cheddar cheese used for nutritional analysis and costing.","contributor":"Adapted from Spanish Rice, Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"orange-and-honey-glazed-brussel-sprouts","source_url":"https://www.myplate.gov/recipes/orange-and-honey-glazed-brussel-sprouts","name":"Orange and Honey Glazed Brussel Sprouts","description":"This spin on a classic dish combines 100% orange juice and Brussels sprouts to help replenish essential nutrients like vitamin C, potassium and folate. Great...","ingredients":[{"name":null,"items":["5 cups Brussels sprouts, trimmed and halved (about 1 pound)","2 tablespoons olive oil or oil of choice","1/4 teaspoon salt","1/4 teaspoon ground black pepper","1/2 cup 100% orange juice","1 tablespoon apple cider vinegar","1 tablespoon honey","1 teaspoon chili paste","2 teaspoons of grated lemon zest (optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 450ºF with a large, rimmed baking sheet placed on the middle rack.","Add Brussels sprouts to a large bowl, and toss with oil, salt and pepper.","Remove baking sheet from oven, and carefully arrange Brussels sprouts cut side down on the sheet. Return to oven, and roast until golden, about 20 minutes, flipping halfway through.","While the sprouts are baking, in a small saucepan over medium-high heat, combine orange juice, apple cider vinegar, honey and chili paste.","Bring to a boil and cook for 5 to 10 minutes, until reduced and syrupy. Remove from heat and allow to cool slightly.","Place sauce in a large bowl and add roasted Brussels sprouts. Toss to combine. Transfer to a serving plate and top with lemon zest."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"143.60 kcal","carbohydrateContent":"17.70 g","cholesterolContent":"0.00 mg","fiberContent":"4.45 g","proteinContent":"4.12 g","sodiumContent":"195.21 mg","sugarContent":"9.29 g","fatContent":"7.46 g","saturatedFatContent":"1.16 g"},"notes":"You may substitute 1/2 teaspoon chili powder for 1 teaspoon chili paste.","contributor":"Created by the Florida Department of Citrus, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"orange-banana-frosty","source_url":"https://www.myplate.gov/recipes/orange-banana-frosty","name":"Orange Banana Frosty","description":"The perfect treat to end a hot summer day. Toss the ingredients in the blender and enjoy!","ingredients":[{"name":null,"items":["1 medium banana, frozen","1/2 cup low-fat plain yogurt","1/2 cup orange juice"]}],"directions":[{"name":null,"steps":["Put all ingredients in a blender and mix well.","Add more liquid if you want the drink thinner."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"128.84 kcal","carbohydrateContent":"24.81 g","cholesterolContent":"3.68 mg","fiberContent":"1.26 g","proteinContent":"4.18 g","sodiumContent":"42.88 mg","sugarContent":"19.28 g","fatContent":"1.35 g","saturatedFatContent":"0.69 g"},"notes":null,"contributor":"Recipe Collection\nUniversity of Nebraska at Lincoln\nNebraska Nutrition Education Program"},
{"slug":"orange-cow","source_url":"https://www.myplate.gov/recipes/orange-cow","name":"Orange Cow","description":"This cold orange drink can be enjoyed for breakfast or at any time of the day.","ingredients":[{"name":null,"items":["16 us fluid ounces orange juice","2 cups cold water","1/3 cup fat-free dry milk","1 teaspoon vanilla","1 cup ice"]}],"directions":[{"name":null,"steps":["Place all ingredients in blender or food processor.","Secure lid and blend until smooth. Serve immediately."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"8 ounces","calories":"81.61 kcal","carbohydrateContent":"15.45 g","cholesterolContent":"1.12 mg","fiberContent":"0.37 g","proteinContent":"3.04 g","sodiumContent":"37.31 mg","sugarContent":"13.07 g","fatContent":"0.49 g","saturatedFatContent":"0.04 g"},"notes":"Substitute 1 cup milk and 1 cup water for 2 cups water and 1/3 cup nonfat dry milk.","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"orange-delight-juice","source_url":"https://www.myplate.gov/recipes/orange-delight-juice","name":"Orange Delight Juice","description":"Fruity and flavorful, this delightful juice is full of fruit, honey, and cinnamon. Enjoy!","ingredients":[{"name":null,"items":["1 cup orange juice","1/2 medium banana","1 cup 100% apple juice","1 teaspoon honey*","1 teaspoon cinnamon","1 cup crushed ice"]}],"directions":[{"name":null,"steps":["Blend at high speed in blender until frothy."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"80.85 kcal","carbohydrateContent":"18.68 g","cholesterolContent":"0.00 mg","fiberContent":"0.93 g","proteinContent":"0.71 g","sodiumContent":"5.63 mg","sugarContent":"15.14 g","fatContent":"0.43 g","saturatedFatContent":"0.04 g"},"notes":"*Children under the age of one should not consume honey.","contributor":"USDA Food Distribution Program on Indian Reservations"},
{"slug":"orange-glazed-skinless-chicken-wings","source_url":"https://www.myplate.gov/recipes/orange-glazed-skinless-chicken-wings","name":"Orange Glazed Skinless Chicken Wings","description":"Orange marmalade seasons these delightful skinless chicken wings. Enjoy this appetizer with brown rice and grilled or roasted veggies.","ingredients":[{"name":null,"items":["10 medium chicken wings","3 tablespoons butter","1 teaspoon seasoned salt","8 tablespoons orange marmalade (1/2 cup)"]}],"directions":[{"name":null,"steps":["Rinse chicken wings and dry on paper toweling. Tuck the wing tip under the larger joint to form a triangle.","Heat butter in skillet (200 degrees F on temperature-controlled gas burner).","Sprinkle wings with seasoned salt and place in heated butter. Sauté on temperature-controlled gas burner (325 degrees F) until evenly brown on both sides, about 20 minutes.","Spread with orange marmalade, continuing to sauté while basting frequently for another 20 minutes.","Remove from skillet. Serve hot.","Hold at serving temperature on automatic burner or in ''Keep-Warm'' oven set at 170 degrees F. They will be glazed and \"sticky\" good."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 wings","1/5 of recipe"],"calories":"241.06 kcal","carbohydrateContent":"21.22 g","cholesterolContent":"60.72 mg","fiberContent":"0.22 g","proteinContent":"15.36 g","sodiumContent":"536.89 mg","sugarContent":"19.21 g","fatContent":"10.97 g","saturatedFatContent":"5.43 g"},"notes":"Leg pieces or whole chicken may be prepared this way and served as an entrée.","contributor":"University of the Virgin Islands, Cooperative Extension Service\n4-H/Family & Consumer Sciences Program"},
{"slug":"orange-honeyed-acorn-squash","source_url":"https://www.myplate.gov/recipes/orange-honeyed-acorn-squash","name":"Orange Honeyed Acorn Squash","description":"Orange juice, honey, butter, and spices are the perfect pairing for acorn squash. Enjoy this recipe with your favorite protein foods.","ingredients":[{"name":null,"items":["3 small acorn squash","1/8 cup orange juice (2 tablespoons)","1/4 cup honey*","2 tablespoons butter or margarine","nutmeg (1/8 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 degrees F.","Cut squash in half. Remove seeds and place halves in shallow baking pan.","Combine orange juice and honey. Mix well. Put some of the orange juice/honey mixture in each squash cavity.","Add 1 tablespoon of the margarine to each squash half. Sprinkle with nutmeg, if desired.","Cover pan with aluminum foil to keep steam in and speed cooking.","Bake 30 minutes. Remove foil and continue baking 30 minutes more, or until squash is tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/6 of recipe"],"calories":"144.97 kcal","carbohydrateContent":"27.74 g","cholesterolContent":"10.18 mg","fiberContent":"5.19 g","proteinContent":"1.76 g","sodiumContent":"3.45 mg","sugarContent":"17.43 g","fatContent":"4.50 g","saturatedFatContent":"2.52 g"},"notes":"*Children under the age of one should not consume honey.","contributor":"University of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"orange-pork-chops","source_url":"https://www.myplate.gov/recipes/orange-pork-chops","name":"Orange Pork Chops","description":"Sweet potatoes and oranges are a wonderful pairing to pork chops. Enjoy this flavorful dish with a side of brown rice.","ingredients":[{"name":null,"items":["2 pork chops","1 medium sweet potato, peeled","1/2 medium orange, sliced","cinnamon (dash, optional)","salt (dash, optional)","black pepper (dash, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","In a medium skillet, brown pork chops in a small amount of oil.","Cut sweet potato into 1/2-inch slices.","Place meat and sweet potato slices in a baking dish and top with orange slices; sprinkle with seasonings if desired.","Cover and bake for 1 hour until meat is tender.","Cook pork to 145 degrees F."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 prepared pork chop","1/2of recipe"],"calories":"316.48 kcal","carbohydrateContent":"15.03 g","cholesterolContent":"104.39 mg","fiberContent":"2.53 g","proteinContent":"42.54 g","sodiumContent":"203.83 mg","sugarContent":"6.73 g","fatContent":"8.86 g","saturatedFatContent":"3.02 g"},"notes":null,"contributor":"Simply Seniors Cookbook\nUtah State University Cooperative Extension"},
{"slug":"oven-baked-potato-pancakes","source_url":"https://www.myplate.gov/recipes/oven-baked-potato-pancakes","name":"Oven-Baked Potato Pancakes","description":"These potato pancakes are easily baked in the oven and offer a healthier version of a traditional Hanukkah recipe.","ingredients":[{"name":null,"items":["2 tablespoons olive oil (or cooking oil of your choice)","3 tablespoons whole wheat flour (or all-purpose flour)","1 teaspoon baking powder","3/4 teaspoon salt","2 large russet potatoes (or Yukon Gold potatoes)","1 onion, small peeled","1 large egg","applesauce and yogurt (plain low-fat or Greek) (optional)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 425 °F. Lightly oil the baking sheets by spreading the oil around with your clean hand or a paper towel.","Mix the flour, baking powder, and salt in a small bowl.","Use the large holes on your grater to grate the potato, then grate the onion too.","Put the potato and onion mixture in the colander inside the sink. Using a paper towel, press the potato mixture down to squeeze out and blot up some of the extra moisture. Stir it and blot again.","Put the potato mixture in the large bowl, add the egg, and stir well. Add the flour mixture and stir it very well.","Use a spoon or your fingers to pluck a clump of the potato mixture from the bowl and spread it into a round, flat nest on the oiled baking sheet: it should make a circle that''s about 3 inches wide and 1/4 inch thick. Repeat to fill the sheet. (You don''t need to leave space between them.)","Bake until the bottoms are deeply golden, 15 to 20 minutes, then turn the pancakes over and put them back in the over for 10 more minutes.","Serve the latkes with applesauce and yogurt (optional)."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 latke","1/12 of recipe (76g)"],"calories":"85.02 kcal","carbohydrateContent":"13.16 g","cholesterolContent":"17.13 mg","fiberContent":"1.51 g","proteinContent":"2.15 g","sodiumContent":"199.29 mg","sugarContent":"1.13 g","fatContent":"2.87 g","saturatedFatContent":"0.52 g"},"notes":"These Hanukkah favorites are traditionally fried in oil to celebrate the oil of the eight nights of lights (like a menorah, which is a special Hanukkah candle holder, does). Our potato pancakes are actually oven-baked, which makes them easier, crunchier, and healthier.","contributor":"ChopChop Family"},
{"slug":"oven-baked-sweet-potato-fries","source_url":"https://www.myplate.gov/recipes/oven-baked-sweet-potato-fries","name":"Oven Baked Sweet Potato Fries","description":"Sweet potato fries are a quick and delicious way to add flavor and color to your dinner plate.","ingredients":[{"name":null,"items":["3 medium sweet potatoes, 5\" long","3 tablespoons olive oil (or cooking oil of choice)"]},{"name":"Optional Seasonings","items":["salt and pepper (to taste)","paprika (1/2 teaspoon, optional)","garlic powder (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Wash and peel sweet potatoes. Cut into 1/4-inch slices.","In a large bowl, toss slices in olive oil until coated. Sprinkle with salt and pepper if desired.","Spread in a single layer on a baking sheet.","Bake at 425 degrees F until tender and golden brown (about 20 minutes), turning occasionally to brown evenly."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"108.81 kcal","carbohydrateContent":"10.49 g","cholesterolContent":"0.00 mg","fiberContent":"1.68 g","proteinContent":"1.02 g","sodiumContent":"18.37 mg","sugarContent":"3.28 g","fatContent":"7.08 g","saturatedFatContent":"1.11 g"},"notes":null,"contributor":"University of Maryland Cooperative Extension\nFood Supplement Nutrition Education Program"},
{"slug":"oven-fried-fish","source_url":"https://www.myplate.gov/recipes/oven-fried-fish","name":"Oven Fried Fish","description":"Oven fried fish pairs well with fresh summer vegetables or hearty root vegetables in the winter.","ingredients":[{"name":null,"items":["1 large egg, slightly beaten","salt (optional, 1/2 teaspoon)","1/2 teaspoon ground black pepper","1/2 cup bread crumbs","1 pound tilapia fillets, fresh or thawed (4 fillets)","1 tablespoon butter, melted","fresh lime or lemon (sliced, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","In a small bowl, add egg, salt (if desired), and pepper and beat together.","Place the bread crumbs in a separate bowl. Dip fish fillets in the egg mixture, then dip in the bread crumbs to coat.","Melt butter in a shallow 9x13 inch baking pan for 1 minute in the oven. Tilt pan to coat with butter.","Arrange fish fillets in the pan.","Bake uncovered for 15 to 20 minutes, until fish flakes easily with a fork. Serve topped with lime or lemon slices (optional)."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 filet","1/4 of recipe"],"calories":"198.98 kcal","carbohydrateContent":"10.02 g","cholesterolContent":"104.25 mg","fiberContent":"0.68 g","proteinContent":"24.17 g","sodiumContent":"159.85 mg","sugarContent":"0.87 g","fatContent":"6.95 g","saturatedFatContent":"3.10 g"},"notes":"Instead of bread crumbs, 1/2 cup crushed, unsweetened cereal or 1/2 cup crushed saltine crackers can be used.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"oven-fried-yucca","source_url":"https://www.myplate.gov/recipes/oven-fried-yucca","name":"Oven-Fried Yucca","description":"Yucca is a starchy vegetable with a taste and texture similar to while potatoes. Enjoy this yucca side dish with one of your favorite protein- or vegetable-b...","ingredients":[{"name":null,"items":["1 pound yucca (cassava) peeled and cut into 3-inch sections (or 1 pound peeled frozen yucca)","1 spray non-stick cooking spray, as needed"]}],"directions":[{"name":null,"steps":["In a large pot, combine the yucca with enough cold water to cover it by 1 inch. Bring the water to a boil and slowly simmer the yucca for 20 to 30 minutes, or until it is tender.","Preheat oven to 350 degrees F.","Transfer the yucca with a slotted spoon to a cutting board. Let it cool and cut it lengthwise into 3/4-inch wide wedges, discarding the thin woody core.","Spray cookie sheet with the nonstick cooking oil spray. Spread yucca wedges on cookie sheet and spray wedges with cooking oil spray. Cover with foil paper and bake for 8 minutes. Uncover and return to oven to bake for an additional 7 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 piece (2 1/2 inches long)","calories":"121.36 kcal","carbohydrateContent":"28.78 g","cholesterolContent":"0.00 mg","fiberContent":"1.36 g","proteinContent":"1.03 g","sodiumContent":"10.61 mg","sugarContent":"1.29 g","fatContent":"0.25 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"Stay Young at Heart: Cooking the Heart-Healthy Way\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"oven-roasted-chicken","source_url":"https://www.myplate.gov/recipes/oven-roasted-chicken","name":"Oven Roasted Chicken","description":"A simple, roasted chicken is perfect for dinner any time of the year.","ingredients":[{"name":null,"items":["1 chicken, broiler/fryer (thawed, if frozen)","2 tablespoons Italian dressing, low-fat (or olive oil)","1 teaspoon garlic salt","1 lemon, quartered (or orange)"]}],"directions":[{"name":null,"steps":["If chicken is frozen, thaw in the refrigerator 24 hours before cooking.","Place chicken on a pan or plate while thawing in the refrigerator.","Preheat oven to 375 degrees F.","Remove necks and giblets from chicken cavity, if present before cooking. Reserve for another use.","Place chicken, breast side up, in a roasting pan.","Brush chicken skin with Italian dressing and sprinkle with garlic salt.","Stuff lemon or orange into chicken cavity.","Roast 1 1/4 to 1 1/2 hours or until meat thermometer inserted into chicken thigh registers 165 degrees F.","Let chicken set for 15 minutes after removing from the oven before carving."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"214.74 kcal","carbohydrateContent":"1.48 g","cholesterolContent":"96.89 mg","fiberContent":"0.30 g","proteinContent":"31.63 g","sodiumContent":"295.42 mg","sugarContent":"0.70 g","fatContent":"8.41 g","saturatedFatContent":"2.26 g"},"notes":null,"contributor":"University of Illinois Extension\nIllinois Nutrition Education Program"},
{"slug":"oven-roasted-vegetables","source_url":"https://www.myplate.gov/recipes/oven-roasted-vegetables","name":"Oven-Roasted Vegetables","description":"This simple and delicious vegetable dish is perfect with your favorite entrée.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of choice)","1 tablespoon lemon juice","1/2 teaspoon Italian seasoning","1/4 teaspoon salt","1/4 teaspoon black ground pepper","3 cups fresh vegetables (potatoes, broccoli, carrots, cauliflower, or red peppers)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 450 degrees F.","In a small bowl, mix the oil, lemon juice, Italian seasoning, salt, and pepper.","Wash, peel, and cut the fresh vegetables to get 3 cups cut-up vegetables.","Spread vegetables on baking sheet pan.","Pour the oil mixture over the vegetables and mix together.","Bake for 20 minutes. Stir after the first 10 minutes of baking.","Serve the vegetables while they are still hot."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared vegetables","1/6 of recipe"],"calories":"101.48 kcal","carbohydrateContent":"11.97 g","cholesterolContent":"0.00 mg","fiberContent":"4.00 g","proteinContent":"2.59 g","sodiumContent":"130.23 mg","sugarContent":"2.87 g","fatContent":"4.81 g","saturatedFatContent":"0.67 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"overnight-oatmeal-berries","source_url":"https://www.myplate.gov/recipes/overnight-oatmeal-berries","name":"Overnight Oatmeal with Berries","description":"A mixture of milk, yogurt, and raspberries combine with dry oats to become a smooth make-ahead breakfast. Just mix and refrigerate overnight for the next day...","ingredients":[{"name":null,"items":["1/2 cup low-fat milk (or less for thicker oatmeal)","1/4 cup Greek yogurt, fat-free","2 teaspoons honey","1/4 teaspoon cinnamon","1/4 teaspoon vanilla extract","1/2 cup uncooked rolled oats","1/4 cup raspberries, frozen"]}],"directions":[{"name":null,"steps":["Combine milk, Greek yogurt, honey, cinnamon, and vanilla extract in a container or jar with a lid.","Add oats and mix well.","Top with raspberries or gently fold into oat mixture.","Cover and refrigerate 8 hours to overnight.","Enjoy cold, or heat as desired."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"304.86 kcal","carbohydrateContent":"51.73 g","cholesterolContent":"9.16 mg","fiberContent":"6.85 g","proteinContent":"16.23 g","sodiumContent":"73.10 mg","sugarContent":"21.20 g","fatContent":"4.25 g","saturatedFatContent":"1.22 g"},"notes":"Frozen blueberries or strawberries may be used in place of raspberries.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"overnight-oatmeal","source_url":"https://www.myplate.gov/recipes/overnight-oatmeal","name":"Overnight Oatmeal","description":"Overnight soaking cuts down on prep time in the morning, so you can enjoy a healthy and hearty, cooked breakfast, even after hitting the snooze button.","ingredients":[{"name":null,"items":["1 cup dry oats","2 1/2 cups water","1/2 cup dried fruit (raisins, cranberries, or apricots)","1/4 cup walnuts, lightly chopped (or pecans)"]}],"directions":[{"name":null,"steps":["Put all ingredients in a cooking pot and cover. Let sit overnight in refrigerator.","In the morning, put on a stove burner and cook on medium heat until simmering, then turn on low and heat for 10 to 15 minutes more or less depending on type of oats -- quick (5 minutes), regular, or steel cut.","Serve warm with a little milk (or milk alternative), a drizzle of maple syrup, and a side of fresh fruit, if desired."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"368.90 kcal","carbohydrateContent":"60.58 g","cholesterolContent":"0.00 mg","fiberContent":"6.97 g","proteinContent":"8.47 g","sodiumContent":"27.50 mg","sugarContent":"27.31 g","fatContent":"12.64 g","saturatedFatContent":"1.40 g"},"notes":"1/2 cup raisins and 1/4 cup walnuts used in nutrient analysis and costing.","contributor":"Lake Family Resource Center\nBe-Fresh Program"},
{"slug":"pan-roasted-tilapia-tomatillo-salsa","source_url":"https://www.myplate.gov/recipes/pan-roasted-tilapia-tomatillo-salsa","name":"Pan Roasted Tilapia with Tomatillo Salsa","description":"Tilapia fillets are pan-fried until golden brown and served with a fresh salsa made from roasted tomatillos, serrano peppers, lime, and cilantro.","ingredients":[{"name":null,"items":["1 pound tomatillos","1/2 cup yellow onion, finely chopped","2 serrano or other chiles, finely chopped","3 cloves garlic, minced","3 teaspoons vegetable oil","1/4 teaspoon Kosher salt","1 tablespoon Fresh lime juice (about 1/2 lime)","1/4 cup fresh cilantro leaves, chopped","4 - 4oz tilapia fillets (patted dry with a paper towel)"]}],"directions":[{"name":"To make the tomatillo salsa","steps":["Preheat the oven to 450 °F.","To prepare the tomatillos, peel back the husk from the smooth green tomatillo skin. Rinse the tomatillos with warm water and cut into quarters.","Place the husked tomatillos, onion, chilies, garlic, and 1 teaspoon oil in the baking pan, stir well and transfer to the oven. Roast about 20 minutes until the tomatillos are soft and dark green. Set aside to cool.","Transfer the mixture to the blender; add the salt, lime juice, and cilantro. Purée."]},{"name":"To cook the tilapia","steps":["Place the skillet on the stove over high heat and when it is hot, carefully add 2 teaspoons oil.","Put the tilapia fillets in the pan, waiting about 30 seconds between additions. Cook about 5 to 6 minutes, until golden brown on both sides.","Transfer the tilapia to the serving plate and top with generous amounts of salsa. Serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"186.71 kcal","carbohydrateContent":"10.07 g","cholesterolContent":"46.28 mg","fiberContent":"2.77 g","proteinContent":"22.83 g","sodiumContent":"196.34 mg","sugarContent":"5.75 g","fatContent":"6.88 g","saturatedFatContent":"1.42 g"},"notes":"Canned tomatillo salsa can be used instead of fresh.\nTilapia can be substituted with any inexpensive white fish.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"pancakes-better-baking-mix","source_url":"https://www.myplate.gov/recipes/pancakes-better-baking-mix","name":"Pancakes (from Better Baking Mix)","description":"Using a pre-made baking mix -- like our Better Baking Mix -- is a great shortcut to making homemade pancakes!","ingredients":[{"name":null,"items":["2 Better Baking Mix","1 cup water","2 tablespoons vegetable oil","2 eggs (beaten)"]}],"directions":[{"name":null,"steps":["Put all the ingredients in a bowl.","Stir just enough to moisten dry ingredients.","Preheat skillet on medium-high heat. The skillet is ready when drops of water \"dance\" on the dry surface. Add a teaspoon of vegetable oil or use cooking oil spray. For each pancake, pour 3 to 4 tablespoons of batter onto hot skillet.","Cook slowly until the surface is covered with bubbles. Turn and cook until second side is lightly browned."]}],"yield":"12 Pancakes","nutrition":{"@type":"NutritionInformation","servingSize":["2 pancakes","1/6 of recipe"],"calories":"95.32 kcal","carbohydrateContent":"12.12 g","cholesterolContent":"34.59 mg","fiberContent":"0.85 g","proteinContent":"3.38 g","sodiumContent":"100.89 mg","sugarContent":"0.97 g","fatContent":"3.65 g","saturatedFatContent":"0.67 g"},"notes":"Try applesauce or other fruit on pancakes instead of syrup.","contributor":"Washington State University Extension"},
{"slug":"panned-cabbage","source_url":"https://www.myplate.gov/recipes/panned-cabbage","name":"Panned Cabbage","description":"A quick, delicious, cruciferous delight. Try this recipe with green or purple cabbage, or a mixture of the two.","ingredients":[{"name":null,"items":["1 1/2 teaspoons butter (or margarine)","1 cup cabbage, finely shredded","1/8 teaspoon salt","black pepper (to taste)","2 tablespoons water","1 tablespoon lemon juice"]}],"directions":[{"name":null,"steps":["Melt butter or margarine in a heavy saucepan or skillet.","Add cabbage and sprinkle with salt and pepper. Add water.","Cover pan with a tight-fitting lid to hold in steam.","Cook over low heat until cabbage is tender (6 to 8 minutes), stirring occasionally to prevent sticking.","Add lemon juice and serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"19.74 kcal","carbohydrateContent":"1.52 g","cholesterolContent":"4.03 mg","fiberContent":"0.59 g","proteinContent":"0.32 g","sodiumContent":"82.15 mg","sugarContent":"0.78 g","fatContent":"1.55 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Creative Vegetable Cookery\nNorth Dakota State University Extension Service"},
{"slug":"parmesan-chive-biscuits","source_url":"https://www.myplate.gov/recipes/parmesan-chive-biscuits","name":"Parmesan Chive Biscuits","description":"Enjoy these savory biscuits with your favorite holiday meal.","ingredients":[{"name":null,"items":["2 cups biscuit mix","2/3 cup 2% reduced fat milk","4 tablespoons butter, melted (1/4 cup)","3/4 cup Parmesan cheese, freshly grated","1/2 tablespoon fresh chives, finely chopped"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a large bowl.","Stir together to mix well. Do not over mix.","Turn out onto a floured board. Roll to a 1-inch thick square.","Cut into 12 squares. Bake on a cookie sheet, spaced slightly apart, in a 400 degrees F oven for 12 to 15 minutes."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 biscuit","calories":"152.69 kcal","carbohydrateContent":"14.62 g","cholesterolContent":"15.99 mg","fiberContent":"0.45 g","proteinContent":"3.70 g","sodiumContent":"348.05 mg","sugarContent":"3.17 g","fatContent":"8.82 g","saturatedFatContent":"4.21 g"},"notes":null,"contributor":"University of Arkansas Cooperative Extension Service\nExpanded Food and Nutrition Education Program (EFNEP)"},
{"slug":"parmesan-peas","source_url":"https://www.myplate.gov/recipes/parmesan-peas","name":"Parmesan Peas","description":"Give (these) peas a chance! Try varying this recipe by using other types of cheese or adding different seasonings.","ingredients":[{"name":null,"items":["1 1/2 teaspoons unsalted butter (or cooking oil of your choice)","2 cans of reduced-sodium peas, drained and rinsed (15 ounce cans or 16 ounces frozen peas)","1 1/2 teaspoons lemon juice","1/4 teaspoon black pepper","1/3 cup grated parmesan cheese"]}],"directions":[{"name":null,"steps":["Heat butter in a medium skillet over medium heat.","Add peas and cook 2 to 3 minutes or until peas are heated through.","Add lemon juice and pepper and mix well. Sprinkle with parmesan cheese and serve warm."]}],"yield":"7 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/7 of recipe","calories":"101.99 kcal","carbohydrateContent":"15.54 g","cholesterolContent":"4.56 mg","fiberContent":"5.01 g","proteinContent":"6.26 g","sodiumContent":"95.92 mg","sugarContent":"4.89 g","fatContent":"1.96 g","saturatedFatContent":"0.93 g"},"notes":"Try other types of cheese or a blend!\nFreeze extra lemon juice to use later.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"parsley-almond-and-lemon-pesto","source_url":"https://www.myplate.gov/recipes/parsley-almond-and-lemon-pesto","name":"Parsley, Almond, and Lemon Pesto","description":"Instead of basil, this recipe uses fresh parsley to make a pesto that is simply delicious!","ingredients":[{"name":null,"items":["6 tablespoons sliced almonds","6 tablespoons Parmesan cheese","1 cup fresh parsley","1/2 lemon, juiced","1/4 cup olive oil (or cooking oil of choice)","salt & pepper to taste, optional"]}],"directions":[{"name":null,"steps":["In a food processor, combine the almonds, cheese, parsley, and lemon juice.","Slowly pour in oil and mix it into the rest of the ingredients.","Season with salt and pepper, if using."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 Tablespoons","calories":"242.02 kcal","carbohydrateContent":"5.05 g","cholesterolContent":"6.45 mg","fiberContent":"2.13 g","proteinContent":"5.49 g","sodiumContent":"144.12 mg","sugarContent":"0.99 g","fatContent":"23.10 g","saturatedFatContent":"3.95 g"},"notes":null,"contributor":"Bronson Wellness Center\nBronson Healthcare - Michigan"},
{"slug":"parsnip-soup","source_url":"https://www.myplate.gov/recipes/parsnip-soup","name":"Parsnip Soup","description":"If you''re looking for delicious ideas for turnips, you''ve come to the right place! This recipe is full of vegetables and flavor, blended together to create a...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","2 cups onion, chopped","1/2 cup celery, chopped","3 cloves garlic, chopped (or 3/4 teaspoon garlic powder)","1/2 teaspoon salt","1/2 teaspoon black pepper","3 cups parsnips, chopped (about 1 pound)","1 cup potato, peeled and cubed","4 cups low-sodium vegetable broth","1 cup water","1 tablespoon unsalted margarine or butter"]}],"directions":[{"name":null,"steps":["Heat the oil in a large saucepan over medium heat. Add the onion and celery and cook until soft, about 5 minutes.","Add the garlic, salt, and pepper; cook for1 minute.","Stir in the parsnips, potato, broth, and water. Bring to a boil, then reduce heat to simmer for 20 minutes or until the parsnips and potatoes are soft.","Stir in the margarine or butter and let the soup sit uncovered for 5 minutes.","Purée the soup in batches in a blender, using the manufacturer''s directions for puréeing hot liquids.","Heat the soup before serving, stirring in water if it seems too thick."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"125.92 kcal","carbohydrateContent":"23.25 g","cholesterolContent":"0.00 mg","fiberContent":"4.12 g","proteinContent":"2.21 g","sodiumContent":"308.17 mg","sugarContent":"6.62 g","fatContent":"3.54 g","saturatedFatContent":"0.59 g"},"notes":"Make this soup your own with more seasoning. Start with 2 to 3 teaspoons ginger, curry powder, smoked paprika, cumin, or thyme.\nMargarine used for nutrition and cost analysis.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"party-time-pasta","source_url":"https://www.myplate.gov/recipes/party-time-pasta","name":"Party-Time Pasta","description":"A tasty and colorful dish that the whole family will enjoy. Use whatever frozen veggies you have on hand.","ingredients":[{"name":null,"items":["1/2 pound 85% lean ground turkey","1 teaspoon paprika","1 can (14 1/2 ounces) low-sodium crushed tomatoes","2 cups low-sodium chicken broth","2 cups bow-tie pasta, uncooked","3 cups frozen vegetables such as carrots, broccoli, and cauliflower, thawed"]},{"name":"Tasty Topping","items":["1/2 cup fresh parsley, chopped (or 2 tablespoons dried parsley)","1/4 cup dry seasoned bread crumbs","1/4 cup Parmesan cheese, grated"]}],"directions":[{"name":null,"steps":["Heat a large nonstick pan over medium heat. Add ground turkey and paprika. Cook and stir until meat is brown and no longer pink, about 5 minutes.","Stir in tomatoes, chicken broth and pasta. Bring mixture to a boil. Reduce heat to medium-low. Cover and simmer until pasta is almost tender, about 10 to 15 minutes.","Remove lid. Place vegetables on top of pasta. Replace lid. Cook until vegetables are tender, about 5 minutes.","Prepare the Tasty Topping. Mix parsley, bread crumbs and Parmesan cheese. Sprinkle over vegetables in skillet. Cover and let sit for 3 minutes before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared pasta","1/6 of recipe"],"calories":"322.00 kcal","carbohydrateContent":"45.80 g","cholesterolContent":"30.96 mg","fiberContent":"7.37 g","proteinContent":"18.24 g","sodiumContent":"240.91 mg","sugarContent":"5.52 g","fatContent":"7.52 g","saturatedFatContent":"2.19 g"},"notes":null,"contributor":"Kids… Get Cooking!\nCalifornia Department of Health Services\nCalifornia Children’s 5-A-Day Power Play Campaign"},
{"slug":"passover-rhubarb-cobbler","source_url":"https://www.myplate.gov/recipes/passover-rhubarb-cobbler","name":"Passover Rhubarb Cobbler","description":"Passover is a Jewish holiday observed in the springtime, but this fruity and delectable dessert is good any time of the year. If you do not wish to eat corns...","ingredients":[{"name":null,"items":["1 3/4 cups sugar, divided","1/4 cup cornstarch*","4 cups rhubarb pieces, 1/2-inch","1 cup fresh raspberries","2 tablespoons lemon juice","1 cup matzo meal","1 stick (1/2 cup) unsalted butter (or margarine)","1/8 teaspoon ground nutmeg","lemon sorbet or whipped cream (optional)"]}],"directions":[{"name":null,"steps":["In a shallow 2-quart baking dish, combine 1 1/4 cups sugar and cornstarch*. Add rhubarb, raspberries, and lemon juice - mixing gently but thoroughly.","Meanwhile, in a food processor or a bowl, whirl or rub together with your fingers the matzo meal, the remaining 1/2 cup sugar, margarine, and nutmeg to create fine crumbs.","Squeeze matzo mixture to compact into lumps, then crumble over rhubarb mixture.","Baked in oven at 375 degrees F until cobbler is bubbling in center and top is golden brown, about 1 hour. Let cool 15 minutes.","Spoon cobbler into bowls and top with sorbet or whipped cream (optional).","*If you do not wish to eat cornstarch feel free to substitute instant tapioca pudding in equal amounts."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"372.64 kcal","carbohydrateContent":"64.61 g","cholesterolContent":"30.37 mg","fiberContent":"2.82 g","proteinContent":"2.37 g","sodiumContent":"5.91 mg","sugarContent":"45.27 g","fatContent":"12.06 g","saturatedFatContent":"7.21 g"},"notes":null,"contributor":"Prairie Fare\nNorth Dakota State University Extension Service"},
{"slug":"pasta-bolognese","source_url":"https://www.myplate.gov/recipes/pasta-bolognese","name":"Pasta Bolognese","description":"This rich red sauce combines ground beef, carrots, celery, onion, and tomatoes with a touch of milk for added creaminess. This sauce is slow simmered and del...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1 carrot, diced into 1/4-inch pieces","1 celery stalk, diced into 1/4-inch pieces","1 yellow onion, chopped into 1/4 inch pieces","3/4 pound lean ground beef (80-85% lean)","1 cup water","2 14.5-ounce cans no salt added crushed or diced tomatoes (including liquid)","1/4 cup no salt added tomato paste","1 cup 2% milk","8 ounces whole wheat pasta","1/4 cup grated Parmesan cheese"]}],"directions":[{"name":"To make the Bolognese sauce","steps":["Put skillet on the stove over medium heat and when it is hot, add oil.","Add carrot, celery, and onion and cook about 10 minutes, stirring occasionally, until the vegetables begin to brown.","Raise the heat to high. Pinch off tablespoon-sized pieces of the beef and add a few at a time, stirring well between additions. Cook, breaking the meat apart until it is no longer raw, starts to give off liquid, and no longer clumps together, about 10 minutes.","Add the water, tomatoes, and tomato paste, stirring well. Cook about 10 minutes until the sauce begins to thicken.","Slowly stir in the milk, a little bit at a time. Turn the heat down to low and cook 45 minutes until all the liquid has been absorbed."]},{"name":"To make the pasta","steps":["Fill a large pot halfway with water. Bring it to a boil over high heat.","Add the pasta and about 12 minutes cook until just tender.","Drain the pasta and divide into 4 bowls.","Top each bowl with about 3/4 cup Bolognese and sprinkle with 1 tablespoon Parmesan cheese.","Serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"508.88 kcal","carbohydrateContent":"66.88 g","cholesterolContent":"58.47 mg","fiberContent":"12.04 g","proteinContent":"30.85 g","sodiumContent":"196.56 mg","sugarContent":"13.83 g","fatContent":"15.78 g","saturatedFatContent":"4.92 g"},"notes":"One portion equals 1 cup cooked pasta + 3/4 cup sauce.\nFreeze leftover sauce for up to 1 month.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"pasta-chickpeas-tomato-and-spinach","source_url":"https://www.myplate.gov/recipes/pasta-chickpeas-tomato-and-spinach","name":"Pasta with Chickpeas, Tomato, and Spinach","description":"Chickpeas, tomatoes, spinach, and a hint of rosemary make this delicious pasta dish. Served warm with a sprinkle of Parmesan, this quick and easy recipe make...","ingredients":[{"name":null,"items":["1 small yellow onion, chopped into 1/4 pieces","8 ounces whole wheat pasta (such as rotini or shells)","1 tablespoon vegetable oil","2 cloves garlic, minced","2 carrots, diced into 1/4-inch pieces","1 celery stalk, diced into 1/4-1/2-inch pieces","1/2 teaspoon dried rosemary","1 16-ounce can low sodium chickpeas, drained and rinsed","1 14.5-ounce can no salt added diced tomatoes (including the liquid)","2 cups spinach, chopped","1/2 teaspoon chopped red pepper flakes (optional)","1/4 cup grated Parmesan cheese"]}],"directions":[{"name":null,"steps":["To cook the pasta, fill a pot with water and bring to a boil over high heat. When the water is boiling, add the pasta and cook until just tender, about 12 minutes. Just before draining, reserve 1 1/2 cups of the pasta water. Drain the pasta and set aside.","While the pasta is cooking, prepare the sauce: Put a skillet on the stove over medium-low heat and when it is hot, add the oil. Add the garlic, onion, carrots, celery, and rosemary and cook until the garlic is golden, about 10 minutes.","Add the chickpeas and using a fork, lightly mash half of them. Add the reserved pasta water and tomatoes and cook 10 minutes.","Add the pasta and spinach to the skillet mixture and cook until the spinach is tender and most of the liquid has been absorbed by the pasta, about 10 minutes. Add the red pepper flakes, if desired.","Mix well and serve immediately, garnished with Parmesan cheese."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"437.24 kcal","carbohydrateContent":"74.24 g","cholesterolContent":"4.30 mg","fiberContent":"14.94 g","proteinContent":"18.46 g","sodiumContent":"273.79 mg","sugarContent":"9.82 g","fatContent":"10.29 g","saturatedFatContent":"1.98 g"},"notes":"Kale can be used instead of spinach.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"pasta-frittata-peas","source_url":"https://www.myplate.gov/recipes/pasta-frittata-peas","name":"Pasta Frittata with Peas","description":"Perfect for any meal of the day, this easy and flavorful frittata is quick and easy to prepare.","ingredients":[{"name":null,"items":["4 ounces whole grain spaghetti, regular or thin","4 eggs, lightly beaten","dash nutmeg (optional)","1/8 teaspoon black pepper","salt, 1/8 teaspoon (optional)","2/3 cup cheese, shredded","1 cup frozen peas, thawed (or 1 cup chopped tomatoes)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Cook pasta according to package directions. Drain and place in a 9-inch pie plate that has been sprayed with nonstick cooking spray.","Combine eggs, seasonings, cheese, and peas. Spread the egg mixture over the top of the spaghetti so the mixture covers the frittata and some of it sinks between the spaghetti strands.","Bake for 20 minutes or until a knife inserted near the center comes out clean. Let frittata stand 5 minutes before serving.","Tomato Variation:\nInstead of mixing 1 cup of peas with the egg, seasonings, and cheese mixture, sprinkle the chopped tomatoes evenly over the top of the frittata before putting it in the oven."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"239.54 kcal","carbohydrateContent":"24.59 g","cholesterolContent":"179.54 mg","fiberContent":"3.97 g","proteinContent":"13.97 g","sodiumContent":"176.52 mg","sugarContent":"2.02 g","fatContent":"10.31 g","saturatedFatContent":"4.36 g"},"notes":"Salt omitted from nutrition analysis.","contributor":"Healthy Eating Recipes\nUniversity of Nebraska Cooperative Extension"},
{"slug":"pasta-greens-beans-and-chicken","source_url":"https://www.myplate.gov/recipes/pasta-greens-beans-and-chicken","name":"Pasta with Greens, Beans, and Chicken","description":"Loaded with protein and fiber, this delicious dish can be made quickly. Enjoy with a side of your favorite fruit.","ingredients":[{"name":null,"items":["16 ounces whole wheat pasta","1 tablespoon vegetable oil (or cooking oil of choice)","1/2 medium onion, chopped","3 cloves garlic, chopped","2 cups cooked chicken cubes (or 3 chicken sausages, chopped)","6 cups spinach, chopped (or 1 bunch Swiss chard)","1 can (15.5 ounces) low-sodium cannellini beans, rinsed and drained (can also use great northern or navy beans)","2 cups low-sodium chicken broth (or vegetable broth)","1 teaspoon Italian seasoning","salt and pepper (optional, to taste)","Parmesan cheese, grated (1/2 cup, optional)"]}],"directions":[{"name":null,"steps":["Cook the pasta according to directions on box, and drain.","On medium heat, add vegetable oil and onion to a large pan.","Cook for 5 minutes, add garlic and cook for 1 minute more.","Stir in chopped chicken and cook until heated through.","Add spinach (or chard), beans, chicken or vegetable stock, and Italian seasoning.","Add in cooked pasta and stir to combine.","Cook for 5 minutes, until pasta is heated through.","Add salt and pepper, to taste (optional), and garnish with Parmesan cheese before serving (optional)."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"518.53 kcal","carbohydrateContent":"82.17 g","cholesterolContent":"44.46 mg","fiberContent":"12.46 g","proteinContent":"34.18 g","sodiumContent":"205.32 mg","sugarContent":"3.34 g","fatContent":"8.49 g","saturatedFatContent":"1.43 g"},"notes":null,"contributor":"Eat Smart. Be Fit.\nUniversity of Maryland Extension"},
{"slug":"pasta-primavera-ii","source_url":"https://www.myplate.gov/recipes/pasta-primavera-ii","name":"Pasta Primavera II","description":"This recipe is quick and easy to prepare and will become a favorite in your home.","ingredients":[{"name":null,"items":["3 cups uncooked pasta (any shape )","1 10-ounce packages frozen mixed vegetables","1 jar spaghetti sauce, low-sodium (24 ounces)","4 tablespoons grated Parmesan cheese (1/4 cup)"]}],"directions":[{"name":null,"steps":["Prepare pasta according to package directions. Add frozen vegetables during the last 5 minutes of cooking time.","Drain pasta and vegetables and set aside.","Bring the spaghetti sauce to a boil over medium heat.","Stir in the pasta and vegetables.","Top with grated Parmesan cheese."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"423.72"},"notes":"May substitute any type of pasta for the rotini. Do not overcook the pasta and vegetables. Maybe substitute other types of canned or bottled Italian sauces.","contributor":"Oklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"pasta-primavera-salad","source_url":"https://www.myplate.gov/recipes/pasta-primavera-salad","name":"Pasta Primavera Salad","description":"Use whole grain pasta to boost the fiber in this tasty spring salad.","ingredients":[{"name":null,"items":["12 ounces uncooked pasta","1 package (10 ounces) frozen mixed vegetables","1 cup low-fat salad dressing","1/2 cup reduced-fat cheese (shredded)","3 hard boiled eggs, sliced"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions. Rinse in cold water to stop cooking and prevent sticking. Drain.","Cook vegetables until just tender. Drain and cool.","Combine cold pasta, vegetables, and salad dressing.","Top with sliced eggs and cheese.","Refrigerate until time to serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"366.66 kcal","carbohydrateContent":"59.22 g","cholesterolContent":"109.64 mg","fiberContent":"5.21 g","proteinContent":"16.74 g","sodiumContent":"559.45 mg","sugarContent":"5.88 g","fatContent":"6.41 g","saturatedFatContent":"2.54 g"},"notes":"Low-fat cheddar cheese used for nutrition analysis and costing.","contributor":"Oklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"pasta-primavera-spaghetti-sauce","source_url":"https://www.myplate.gov/recipes/pasta-primavera-spaghetti-sauce","name":"Pasta Primavera in Spaghetti Sauce","description":"This recipe is quick and easy to prepare and will become a favorite in your home.","ingredients":[{"name":null,"items":["3 cups pasta, uncooked","1 (10 ounce) package frozen mixed vegetables","1 (24 ounce) jar low-sodium spaghetti sauce","4 tablespoons grated Parmesan cheese"]}],"directions":[{"name":null,"steps":["Prepare pasta according to package directions. Add frozen vegetables during the last 5 minutes of cooking time.","Drain pasta and vegetables and set aside.","Bring the spaghetti sauce to a boil over medium heat.","Stir in the pasta and vegetables.","Top with grated Parmesan cheese."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"412.57 kcal","carbohydrateContent":"78.32 g","cholesterolContent":"4.30 mg","fiberContent":"9.18 g","proteinContent":"16.75 g","sodiumContent":"116.07 mg","sugarContent":"9.37 g","fatContent":"3.84 g","saturatedFatContent":"1.26 g"},"notes":"May substitute any type of pasta for the rotini. Do not overcook the pasta and vegetables. Maybe substitute other types of canned or bottled Italian sauces.","contributor":"Oklahoma Nutrition Information and Education, Adapted from Pasta Primavera\nONIE Project"},
{"slug":"pasta-primavera","source_url":"https://www.myplate.gov/recipes/pasta-primavera","name":"Pasta Primavera","description":"A flavorful spring recipe that you and your family will savor. Use your favorite spring vegetables from your garden or local farmers market: kohlrabi, sugar ...","ingredients":[{"name":null,"items":["1 cup pasta, uncooked","1 tablespoon vegetable oil","2 cups mixed vegetables, chopped","1 cup tomatoes, chopped","1 tablespoon margarine","1/4 teaspoon garlic powder","1/8 teaspoon black pepper","3 tablespoons Parmesan cheese"]}],"directions":[{"name":null,"steps":["Cook noodles according to package directions.","While noodles are cooking, heat oil in a large skillet over medium heat.","Add vegetables and sauté until tender; stir constantly.","Add tomato and sauté 2 more minutes.","Toss vegetables with noodles and margarine.","Add seasonings; sprinkle with Parmesan cheese."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 of recipe","calories":"314.34 kcal","carbohydrateContent":"45.28 g","cholesterolContent":"4.35 mg","fiberContent":"7.62 g","proteinContent":"10.45 g","sodiumContent":"147.47 mg","sugarContent":"5.83 g","fatContent":"10.06 g","saturatedFatContent":"2.24 g"},"notes":null,"contributor":"Utah State University Cooperative Extension"},
{"slug":"pasta-salad-herb-vinaigrette","source_url":"https://www.myplate.gov/recipes/pasta-salad-herb-vinaigrette","name":"Pasta Salad with Herb Vinaigrette","description":"This recipe starts with whole wheat pasta and includes fresh broccoli, tomatoes, carrots, and hard-cooked eggs. Tossed with a refreshing vinaigrette flavored...","ingredients":[{"name":null,"items":["6 ounces uncooked whole wheat pasta, cooked, drained","1 cup chopped fresh broccoli","3/4 cup chopped tomato","1/2 cup shredded carrots","6 hard-cooked eggs, cut into wedges"]},{"name":"For the Dressing","items":["1/4 cup white wine vinegar","2 tablespoons olive oil","2 tablespoons water","1 teaspoon dried basil leaves","1 teaspoon dried oregano leaves","3/4 teaspoon garlic salt"]}],"directions":[{"name":null,"steps":["Whisk dressing ingredients in a small bowl until blended.","Combine pasta, broccoli, tomato, and carrot in a large bowl; toss. Pour dressing over pasta mixture; toss until evenly coated. Add eggs; toss briefly.","Refrigerate, covered, at least 4 hours to blend flavors."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"257.66 kcal","carbohydrateContent":"28.39 g","cholesterolContent":"205.50 mg","fiberContent":"2.57 g","proteinContent":"11.58 g","sodiumContent":"199.70 mg","sugarContent":"1.88 g","fatContent":"10.55 g","saturatedFatContent":"2.49 g"},"notes":"For a different flavor or to reduce cost, use any other vinegar you have on hand for the dressing.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"pasta-salad","source_url":"https://www.myplate.gov/recipes/pasta-salad","name":"Pasta Salad","description":"Easy and delicious, make this tasty pasta salad for your next picnic.","ingredients":[{"name":null,"items":["3 cups pasta, uncooked","1/2 cup celery, chopped","1 medium bell pepper, chopped","1/2 cup carrots, diced","1/2 cup broccoli, chopped","1/3 cup mayonnaise","1 1/2 tablespoons garlic powder","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions.","Drain and place in large bowl or pan.","Add the rest of the ingredients and mix well.","Cool in refrigerator before serving."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/12 of recipe"],"calories":"153.13 kcal","carbohydrateContent":"22.15 g","cholesterolContent":"2.54 mg","fiberContent":"1.77 g","proteinContent":"4.26 g","sodiumContent":"49.02 mg","sugarContent":"1.02 g","fatContent":"5.18 g","saturatedFatContent":"0.84 g"},"notes":null,"contributor":"Easy and Nutritious Family Recipes\nUniversity of California Cooperative Extension\nFresno County"},
{"slug":"pasta-vegetable-salad","source_url":"https://www.myplate.gov/recipes/pasta-vegetable-salad","name":"Pasta Vegetable Salad","description":"Try this tasty salad with whole grain pasta in your favorite shape. Enjoy with family and friends at your next gathering.","ingredients":[{"name":null,"items":["2 cups cooked pasta","1 cup cucumber, diced","1 large tomato, chopped","1/2 medium green pepper, diced","1/4 medium onion, diced","1/2 cup frozen peas, thawed","1/4 cup Italian salad dressing"]}],"directions":[{"name":null,"steps":["Mix all ingredients in a medium-sized bowl.","Cover and refrigerate for at least 1 hour.","Mix again before serving.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"119.15 kcal","carbohydrateContent":"20.05 g","cholesterolContent":"0.00 mg","fiberContent":"2.07 g","proteinContent":"3.87 g","sodiumContent":"109.04 mg","sugarContent":"3.39 g","fatContent":"2.64 g","saturatedFatContent":"0.40 g"},"notes":null,"contributor":"Eating Smart Being Active Recipes\nColorado State University and University of California at Davis"},
{"slug":"pasta-vegetables","source_url":"https://www.myplate.gov/recipes/pasta-vegetables","name":"Pasta with Vegetables","description":"Combine fresh veggies from your garden or the farmers'' market with pasta to make this your new favorite summer recipe.","ingredients":[{"name":null,"items":["12 cherry tomatoes (cut in half)","1 tablespoon garlic (minced)","1/2 onion, medium (finely chopped)","1/2 green pepper (finely chopped)","3 tablespoons fresh basil (chopped)","1/2 teaspoon dried oregano","1 tablespoon olive oil (or oil of your choice)","salt and pepper (optional, to taste)","6 cups pasta (cooked)","6 tablespoons Parmesan cheese (grated)"]}],"directions":[{"name":null,"steps":["Chop tomatoes and mix with all the remaining ingredients in a large bowl.","Let the mixture stand at room temperature for about 20 minutes. Toss with cooked pasta and top with grated cheese."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups (386g)","calories":"278.96 kcal","carbohydrateContent":"47.08 g","cholesterolContent":"4.30 mg","fiberContent":"3.45 g","proteinContent":"10.23 g","sodiumContent":"73.84 mg","sugarContent":"2.68 g","fatContent":"5.22 g","saturatedFatContent":"1.46 g"},"notes":"Add a can of white or black beans, drained, for extra protein before tossing with pasta.\nFeel free to add other vegetables that you have on hand.\nSalt and pepper not included in analysis.","contributor":"Originally named Uncooked Tomato Sauce\nFarm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"pea-guacamole","source_url":"https://www.myplate.gov/recipes/pea-guacamole","name":"Pea Guacamole","description":"While avocados tend to get all the guacamole glory, sometimes they’re not available, not ripe, or just too expensive! Check out this tasty, bright, and sat...","ingredients":[{"name":null,"items":["2 cups frozen peas, thawed","2 tablespoons lime juice","1/2 cup grape tomatoes, halved","1/4 cup red onion, chopped","1 can (4 ounces) diced green chilies, drained","3 tablespoons cilantro, chopped","1 clove fresh garlic, minced","salt (to taste, optional)","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Mash peas until smooth.","Add the lime juice, tomato, onion, green chilies, cilantro, garlic, salt (if using), and black pepper. Mix well.","Serve with an assortment of raw vegetables and whole-grain tortilla chips."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup","calories":"26.79 kcal","carbohydrateContent":"5.15 g","cholesterolContent":"0.00 mg","fiberContent":"1.55 g","proteinContent":"1.57 g","sodiumContent":"57.39 mg","sugarContent":"1.61 g","fatContent":"0.13 g","saturatedFatContent":"0.02 g"},"notes":null,"contributor":"Westmoreland County Pennsylvania SNAP-Ed Program"},
{"slug":"pea-pesto","source_url":"https://www.myplate.gov/recipes/pea-pesto","name":"Pea Pesto","description":"Enjoy this gorgeous, bright green pesto on your favorite protein food or pasta.","ingredients":[{"name":null,"items":["1 cup frozen peas (can also use fresh or canned)","1/2 cup grated Parmesan cheese","1 cup basil leaves","1 cup fresh spinach (or can use frozen or canned)","1/2 cup walnuts","2 cloves garlic","1/4 cup water","1/4 cup extra virgin olive oil (or cooking oil of choice)","1/4 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["For the pesto, add peas, Parmesan cheese, basil, spinach, walnuts and garlic into a food processor or blender.","Add in water, oil, salt and pepper. Blend until the ingredients are combined to form a thick sauce.","Place pesto in an airtight container.","Refrigerate until needed."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"151.08 kcal","carbohydrateContent":"4.71 g","cholesterolContent":"4.30 mg","fiberContent":"1.54 g","proteinContent":"3.91 g","sodiumContent":"162.59 mg","sugarContent":"1.12 g","fatContent":"13.43 g","saturatedFatContent":"2.38 g"},"notes":"If using canned peas and spinach, remember to rinse them to lower salt content.\nGreat served over vegetables or pasta - serve hot or cold.\nSwitch out mayonnaise for pesto on sandwiches.\nTry as a dip with carrots and broccoli.","contributor":"Cooking Matters Colorado"},
{"slug":"peach-apple-crisp","source_url":"https://www.myplate.gov/recipes/peach-apple-crisp","name":"Peach Apple Crisp","description":"This delicious dessert is the perfect ending to any meal. This recipe is simple to prepare and the dish is satisfying to taste.","ingredients":[{"name":null,"items":["1 1/3 cans (20 ounces total) peaches, in light syrup, drained and sliced","2 medium tart apples, peeled and sliced","1/2 teaspoon vanilla","1/4 teaspoon ground cinnamon","3/4 cup flour","1/4 cup brown sugar, packed","3 tablespoons chilled margarine"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F. Lightly grease 9x9x2-inch casserole dish.","Combine peaches, apples, vanilla, and cinnamon in a bowl. Toss well and spread evenly in greased casserole dish.","Combine flour and sugar in small bowl. Cut in margarine with two knives until the mixture resembles coarse meal.","Sprinkle flour mixture evenly over fruit.","Bake until lightly browned and bubbly, about 20 minutes."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/8 of recipe"],"calories":"157.21 kcal","carbohydrateContent":"30.51 g","cholesterolContent":"0.05 mg","fiberContent":"2.26 g","proteinContent":"1.63 g","sodiumContent":"41.82 mg","sugarContent":"19.07 g","fatContent":"3.40 g","saturatedFatContent":"0.68 g"},"notes":null,"contributor":"Recipes and Tips for Healthy, Thrifty Meals\nUSDA Center for Nutrition Policy and Promotion"},
{"slug":"peach-cooler","source_url":"https://www.myplate.gov/recipes/peach-cooler","name":"Peach Cooler","description":"On a hot summer day, freeze the drained peaches (or fresh) for at least 45 minutes before preparing this sweet and tangy drink.","ingredients":[{"name":null,"items":["2 cups 1% low-fat milk","1 cup canned peaches packed in juice, drained (or1 cup of sliced fresh peaches)","1/2 teaspoon lemon juice","nutmeg (dash, optional)"]}],"directions":[{"name":null,"steps":["Put the ingredients in a blender. Blend well.","Sprinkle with nutmeg if you like.","Serve cold."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/2 recipe"],"calories":"155.36 kcal","carbohydrateContent":"25.33 g","cholesterolContent":"12.20 mg","fiberContent":"1.48 g","proteinContent":"8.80 g","sodiumContent":"102.82 mg","sugarContent":"23.01 g","fatContent":"2.44 g","saturatedFatContent":"1.40 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"peach-crisp","source_url":"https://www.myplate.gov/recipes/peach-crisp","name":"Peach Crisp","description":"The perfect dessert when peaches are in season. Simple to prepare but absolutely scrumptious.","ingredients":[{"name":null,"items":["4 medium peaches (about 4 cups sliced)","2 tablespoons margarine","3/4 cup quick-cooking oats","1/2 cup sugar","1/4 cup flour","2 teaspoons cinnamon","1 teaspoon lemon juice"]}],"directions":[{"name":null,"steps":["Preheat the oven to 375 degrees F.","Slice the peaches.","Spread the peach slices on the bottom of a 9x9-inch baking pan.","Melt the margarine in a saucepan.","In a small bowl, mix everything but the peaches. Stir until the mix is well blended.","Sprinkle the oat mix on top of the peaches.","Bake for 20 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"196.85 kcal","carbohydrateContent":"38.23 g","cholesterolContent":"0.05 mg","fiberContent":"3.12 g","proteinContent":"2.81 g","sodiumContent":"45.62 mg","sugarContent":"25.17 g","fatContent":"3.83 g","saturatedFatContent":"0.71 g"},"notes":"Serve the peach crisp either hot or cold. To remove the peach fuzz, you can rub the washed peach gently with a paper towel.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"peach-sauce","source_url":"https://www.myplate.gov/recipes/peach-sauce","name":"Peach Sauce","description":"This simple peach sauce recipe is the perfect complement to your favorite dishes. Sweet peaches and aromatic cinnamon enhance savory dishes when topped on gr...","ingredients":[{"name":null,"items":["2 15-ounce cans of peaches, juice packed (with liquid)","1 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Drain peaches and reserve liquid. Pour peaches into a medium saucepan with cinnamon.","Cook on low to medium heat for 20 minutes, stirring every few minutes.","Mash to desired consistency with either a potato masher or wooden spoon. Add reserved peach liquid as needed."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"88.79 kcal","carbohydrateContent":"22.43 g","cholesterolContent":"0.00 mg","fiberContent":"2.90 g","proteinContent":"0.98 g","sodiumContent":"12.82 mg","sugarContent":"18.92 g","fatContent":"0.22 g","saturatedFatContent":"0.02 g"},"notes":"Use as a topping for plain, nonfat yogurt or whole-grain waffles, pancakes, as preserves on toast, or as sauce to top grilled chicken.\nFor a thicker consistency, cook for 25 to 30 minutes to allow more time for the sauce to reduce.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"peachy-peanut-butter-pita-pockets","source_url":"https://www.myplate.gov/recipes/peachy-peanut-butter-pita-pockets","name":"Peachy Peanut Butter Pita Pockets","description":"Packed with fresh fruit, this pita pocket makes a wonderful breakfast, lunch, or snack. If you don''t have peaches, try with plums or nectarines.","ingredients":[{"name":null,"items":["2 medium whole wheat pita pockets","1/4 cup low-fat peanut butter (smooth or chunky)","1/2 medium apple, cored and thinly sliced","1/2 medium banana, thinly sliced","1/2 medium peach, thinly sliced"]}],"directions":[{"name":null,"steps":["Cut pitas in half to make 4 pockets and warm in the microwave for about 10 seconds to make them more flexible.","Carefully open each pocket and spread a thin layer of peanut butter on the inside walls.","Fill with a combination of apple, banana, and peach slices. Serve at room temperature."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 pita pocket","calories":"197.02 kcal","carbohydrateContent":"30.80 g","cholesterolContent":"0.00 mg","fiberContent":"3.64 g","proteinContent":"7.27 g","sodiumContent":"208.82 mg","sugarContent":"9.39 g","fatContent":"6.06 g","saturatedFatContent":"1.01 g"},"notes":null,"contributor":"SNAP4CT\nUConn Health SNAP-Ed"},
{"slug":"peachy-pops","source_url":"https://www.myplate.gov/recipes/peachy-pops","name":"Peachy Pops","description":"Peachy pops will be the perfect partner to your playful summer picnic. Enjoy these frosty treats on a hot day.","ingredients":[{"name":null,"items":["2 medium peaches","2/3 cup low-fat vanilla yogurt","2 cups orange juice","6 paper cups","6 spoons"]}],"directions":[{"name":null,"steps":["Use a knife to remove the skin and chop the peaches.","Spoon peaches into each of the 6 paper cups.","Place yogurt in a medium mixing bowl.","Slowly pour and stir the orange juice into the yogurt. Mix well.","Pour some of the juice and yogurt mix into each cup to cover the peaches.","Place a spoon in the center of each cup.","Cut 6 squares of aluminum foil big enough to cover the tops of cups. Stab each spoon handle through each piece of foil. The foil will hold the spoon in the center of the cup.","Place cups in the freezer for at least 4 hours.","Just before serving, peel the paper cups away from the pops to eat."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 pop","1/6 of recipe"],"calories":"81.82 kcal","carbohydrateContent":"16.00 g","cholesterolContent":"1.64 mg","fiberContent":"1.00 g","proteinContent":"2.52 g","sodiumContent":"25.10 mg","sugarContent":"13.56 g","fatContent":"0.85 g","saturatedFatContent":"0.28 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"peanut-butter-and-apple-wraps","source_url":"https://www.myplate.gov/recipes/peanut-butter-and-apple-wraps","name":"Peanut Butter and Apple Wraps","description":"Quick, filling, and delicious, these wraps can be made in a flash and enjoyed right away or packed away for lunch at school or work.","ingredients":[{"name":null,"items":["1 (7-inch across) whole wheat tortilla","1/4 cup low-fat peanut butter","2 tablespoons granola cereal","1/2 medium apple, sliced (suggest Red Delicious apple)"]}],"directions":[{"name":null,"steps":["Lay tortilla flat and spread peanut butter over 2/3 of the tortilla leaving edges at sides","Sprinkle 2 tablespoons granola over peanut butter.","Cut apple slices into small chunks and place them on top of the granola.","Fold over the edges of the tortilla and roll up \"burrito style.\"","Eat and Enjoy."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"295.53 kcal","carbohydrateContent":"33.75 g","cholesterolContent":"0.00 mg","fiberContent":"5.43 g","proteinContent":"11.24 g","sodiumContent":"322.69 mg","sugarContent":"11.09 g","fatContent":"14.04 g","saturatedFatContent":"3.05 g"},"notes":"This recipe could use other apples, such as Golden Delicious, Granny Smith, or Fuji. However, Red Delicious apples are the crispiest and their flavor balances the savory taste of the peanut butter.\nThe combination of fruit, granola, and peanut butter makes this snack packed with protein, iron, fiber, and calcium. The whole wheat tortilla and reduced-fat peanut butter keep it lower in fat.\nWatch how to make this kid-friendly recipe on YouTube.","contributor":"CSAAC (Community Services for Autistic Adults and Children)"},
{"slug":"peanut-butter-banana-breakfast-shake","source_url":"https://www.myplate.gov/recipes/peanut-butter-banana-breakfast-shake","name":"Peanut Butter Banana Breakfast Shake","description":"Hurried in the morning? Need breakfast to be made at breakneck speed? Toss all of the ingredients in the blender and enjoy this shake on the go.","ingredients":[{"name":null,"items":["1 cup fat-free (skim) milk (or 1% milk)","1/2 cup banana slices, frozen","1 tablespoon peanut butter","1/4 teaspoon ground cinnamon","1/2 teaspoon vanilla extract","cocoa powder (as needed, optional)"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a blender and blend until smooth and creamy.","Pour into a tall glass and garnish with a sprinkle of cocoa powder, if desired."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 shake","calories":"301.98 kcal","carbohydrateContent":"41.90 g","cholesterolContent":"7.32 mg","fiberContent":"3.03 g","proteinContent":"12.83 g","sodiumContent":"168.93 mg","sugarContent":"32.06 g","fatContent":"8.70 g","saturatedFatContent":"1.86 g"},"notes":null,"contributor":"University of Nebraska Cooperative Extension"},
{"slug":"peanut-butter-banana-smoothie","source_url":"https://www.myplate.gov/recipes/peanut-butter-banana-smoothie","name":"Peanut Butter Banana Smoothie","description":"This delicious blend of bananas, milk, yogurt, and peanut butter makes for a filling breakfast on-the-go. Cocoa powder lends a touch of sweet that also hits ...","ingredients":[{"name":null,"items":["2 bananas","1 cup skim milk","1 1/2 tablespoons creamy peanut butter","1/2 tablespoon unsweetened cocoa powder","1/2 cup low fat vanilla yogurt","1 1/2 cups ice"]}],"directions":[{"name":null,"steps":["Peel bananas, chop into small pieces and place in freezer until hard.","Gather all ingredients and put all ingredients in a blender.","Blend on high until smooth.","Pour into 2 glasses. Serve right away."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"287.94 kcal","carbohydrateContent":"44.02 g","cholesterolContent":"7.34 mg","fiberContent":"3.18 g","proteinContent":"11.18 g","sodiumContent":"146.71 mg","sugarContent":"33.37 g","fatContent":"7.68 g","saturatedFatContent":"2.11 g"},"notes":"Watch how to make this kid-friendly recipe on YouTube.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"peanut-butter-bananas","source_url":"https://www.myplate.gov/recipes/peanut-butter-bananas","name":"Peanut Butter Bananas","description":"This treat can be made with your kids in the morning, then frozen for an afterschool snack.","ingredients":[{"name":null,"items":["2 bananas","1/4 cup peanut butter","1/4 cup crushed nuts"]}],"directions":[{"name":null,"steps":["Peel bananas. Spread the entire outside of each banana with peanut butter.","Roll the bananas in crushed nuts, sprinkles or other items.","Cut the bananas in one inch slices.","Store in the refrigerator or freezer until ready to serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 banana","1/4 of recipe"],"calories":"217.04 kcal","carbohydrateContent":"19.73 g","cholesterolContent":"0.00 mg","fiberContent":"2.51 g","proteinContent":"5.81 g","sodiumContent":"96.42 mg","sugarContent":"12.04 g","fatContent":"13.11 g","saturatedFatContent":"2.36 g"},"notes":"Walnuts used in nutrition analysis and for costing purposes. A cheaper option would be to use peanuts.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"peanut-butter-bread","source_url":"https://www.myplate.gov/recipes/peanut-butter-bread","name":"Peanut Butter Bread","description":"For a peanut butter extravaganza, spread smooth or chunky peanut butter on top of a slice of this delicious bread! Top with banana or strawberry slices.","ingredients":[{"name":null,"items":["2 large eggs","1 1/2 cups 1% low-fat milk","1/3 cup granulated sugar","1 cup peanut butter","1 3/4 cups all-purpose flour","1 tablespoon baking powder","1/2 teaspoon salt"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F. Lightly grease or spray with non-stick spray, a loaf pan.","In large bowl, beat eggs. Add milk, sugar, and peanut butter. Mix well.","In a separate bowl combine flour, baking powder, and salt. Mix thoroughly.","Add dry ingredients to wet ingredients. Mix only enough to moisten all ingredients.","Pour into prepared pan. Pan will be half full. Bake for 1 hour."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/10 of recipe"],"calories":"300.44 kcal","carbohydrateContent":"31.35 g","cholesterolContent":"42.93 mg","fiberContent":"1.82 g","proteinContent":"10.50 g","sodiumContent":"401.82 mg","sugarContent":"11.17 g","fatContent":"14.66 g","saturatedFatContent":"3.15 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"peanut-butter-cereal-bars","source_url":"https://www.myplate.gov/recipes/peanut-butter-cereal-bars","name":"Peanut Butter Cereal Bars","description":"These bars make a great on the go snack to satisfy a sweet tooth. Trying adding pumpkin seeds, chia seeds, or chopped nuts to add a little extra crunch.","ingredients":[{"name":null,"items":["1/2 cup honey* (see Notes)","1 cup peanut butter","2 cups rice cereal","2 cups quick oats","1 cup raisins or other dried fruit"]}],"directions":[{"name":null,"steps":["In a large saucepan, bring honey to a boil.","Reduce heat to low and stir in peanut butter.","Add cereal, oats and raisins; mix well. Remove from heat","Lightly grease an 8x8 inch baking pan. Press mixture into pan. When cool, cut into 16 bars.","Store in an airtight container for up to a week."]}],"yield":"16 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 bar","calories":"211.63 kcal","carbohydrateContent":"29.00 g","cholesterolContent":"0.00 mg","fiberContent":"2.26 g","proteinContent":"5.50 g","sodiumContent":"88.02 mg","sugarContent":"16.82 g","fatContent":"8.89 g","saturatedFatContent":"1.75 g"},"notes":"* Honey is not recommended for children under 1 year old.\nTry this recipe with 4 cups of unsweetened cereal flakes instead of the rice cereal and oats.\nTo avoid peanuts or peanut butter, try sunflower seeds or sunflower seed butter.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"peanut-butter-muffins","source_url":"https://www.myplate.gov/recipes/peanut-butter-muffins","name":"Peanut Butter Muffins","description":"Enjoy these nutty muffins with a touch of jelly or jam for a satisfying dessert.","ingredients":[{"name":null,"items":["3/4 cup chunky peanut butter","1/2 tablespoon honey","2 eggs","1 cup fat-free (skim) milk","1 1/2 cups flour","1/2 cup cornmeal","3 tablespoons sugar","2 teaspoons baking powder","1/2 teaspoon salt"]}],"directions":[{"name":null,"steps":["Preheat the oven to 375 degrees F.","Line 12 muffin cups with paper baking cups (or grease the bottom of each cup with butter or margarine).","Put the peanut butter and honey in a mixing bowl. Beat until well blended.","Add the eggs 1 at a time, beating well after each egg.","Add the milk, and mix well.","Add the flour, cornmeal, sugar, baking powder, and salt. Stir just until they are moistened. Don’t stir them too much.","Fill each muffin cup 2/3 full.","Bake for 20 to 25 minutes until golden brown.","Put on a wire rack.","Cool for at least 10 minutes before serving."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"211.82 kcal","carbohydrateContent":"24.49 g","cholesterolContent":"34.86 mg","fiberContent":"1.56 g","proteinContent":"7.36 g","sodiumContent":"269.51 mg","sugarContent":"6.60 g","fatContent":"9.37 g","saturatedFatContent":"1.94 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"peanut-butter-n-fruit-wich","source_url":"https://www.myplate.gov/recipes/peanut-butter-n-fruit-wich","name":"Peanut Butter ''n Fruit-wich","description":"A filling, fruity, and nutty sandwich that you and your children will enjoy.","ingredients":[{"name":null,"items":["1 slice whole wheat bread","2 tablespoons peanut butter","1/4 medium apple, thinly sliced (or banana)","carrot, grated (2 tablespoons, optional)"]}],"directions":[{"name":null,"steps":["Spread 2 tablespoons peanut butter on bread.","Place fruit slices on top.","Optional: Top with grated carrot."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 open-faced sandwich","calories":"326.42 kcal","carbohydrateContent":"30.05 g","cholesterolContent":"0.00 mg","fiberContent":"4.75 g","proteinContent":"11.71 g","sodiumContent":"299.28 mg","sugarContent":"11.00 g","fatContent":"17.71 g","saturatedFatContent":"3.51 g"},"notes":"Instead of whole wheat bread try crunchy graham crackers or roll up the filling in a soft tortilla. Instead of fresh fruit use canned, drained pineapple.","contributor":"The Power of Choice\nUSDA Food and Nutrition Service and US Department of Health and Human Services Food and Drug Administration (FDA)"},
{"slug":"peanut-peach-n-pineapple-wrap","source_url":"https://www.myplate.gov/recipes/peanut-peach-n-pineapple-wrap","name":"Peanut, Peach, N Pineapple Wrap","description":"Inspired by an all-time favorite, peanut butter and jelly sandwiches, this wrap is easy and fun for kids to make. With the sweet flavor of fruit and the cris...","ingredients":[{"name":null,"items":["1 can sliced peaches (15 oz, drained)","1 can pineapple tidbits in juice (drained)","1/2 cup red or green bell pepper (chopped)","1 teaspoon cinnamon","4 whole wheat tortillas","1/2 cup chunky peanut butter","3 cups lettuce (shredded)"]}],"directions":[{"name":null,"steps":["In a medium bowl, combine peaches, pineapple, bell pepper, and cinnamon.","Warm the tortillas.","Spread 2 tablespoons of peanut butter on one side of each tortilla, leaving room on the edges.","Spoon equal portions of the peach mixture over peanut butter, then top with lettuce.","Fold the side and bottom edges of each tortilla toward the middle over the filling, then roll so the tortilla covers the filling."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"464.53 kcal","carbohydrateContent":"58.11 g","cholesterolContent":"0.00 mg","fiberContent":"9.26 g","proteinContent":"13.16 g","sodiumContent":"432.48 mg","sugarContent":"30.82 g","fatContent":"21.13 g","saturatedFatContent":"5.47 g"},"notes":"Mix the drained juices with your breakfast juice if you like.\nTo make them more pliable before wrapping, warm the tortillas: 10 to 15 seconds on high heat in the microwave, 3 to 5 minutes at 350 ºF in aluminum foil in the oven, or 15 seconds per side over medium-high on the stove top.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"peanut-stew","source_url":"https://www.myplate.gov/recipes/peanut-stew","name":"Peanut Stew","description":"A hearty stew combining creamy peanut butter, hearty vegetables, and spices. Perfect for a chilly evening, it brings the warmth of garlic, ginger, and cumin ...","ingredients":[{"name":null,"items":["1 yellow onion, diced","1 tablespoon olive oil","1 tablespoon ginger, minced","1 tablespoon garlic, minced","1 teaspoon ground cumin","1/2 teaspoon salt","1/2 cup peanut butter","1/2 cup tomato paste","1 can diced tomatoes (about 15 oz)","4 cups low sodium vegetable broth","2 pounds whole yellow or red potatoes, peeled, halved, and cut into quarters (about 6 potatoes)","2 cups kale, roughly chopped","1/4 cup peanuts, chopped","1 whole lime, zest and juice"]}],"directions":[{"name":null,"steps":["Heat oil over medium heat in a pot and add onions. Cook for a few minutes.","Add ginger and garlic. Cook for 1-2 minutes. Add cumin and salt.","Add peanut butter, tomato paste, diced tomatoes, and vegetable broth.","Bring to a boil and add potatoes.","Simmer for 15-20 minutes or until potatoes are fork-tender and cooked through.","Add kale, and continue to cook for 1-2 minutes,","Serve garnished with lime zest, lime juice, and crushed peanuts; drizzle with Sriracha for a spicy kick (optional)"]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"352.77 kcal","carbohydrateContent":"41.77 g","cholesterolContent":"0.00 mg","fiberContent":"7.17 g","proteinContent":"11.52 g","sodiumContent":"496.72 mg","sugarContent":"10.99 g","fatContent":"17.16 g","saturatedFatContent":"3.17 g"},"notes":"Yellow and red potatoes will stay fork tender in this stew. Russet potatoes may fall apart and get mushy.","contributor":"Created by Potatoes USA, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"peanutty-stew","source_url":"https://www.myplate.gov/recipes/peanutty-stew","name":"Peanutty Stew","description":"A spicy and savory one pot dish that the whole family will enjoy. Add some cayenne pepper for an extra kick.","ingredients":[{"name":null,"items":["1 cup instant brown rice","2 cups low-sodium chicken broth","1 teaspoon dehydrated onion, minced","1 teaspoon garlic powder","1/2 teaspoon ground ginger","cayenne pepper (optional )","1 medium sweet potato, peeled and diced (about 2 cups)","1 can (14.5 ounces) low-sodium tomatoes, not drained","salt (optional)","1/2 cup reduced-fat creamy peanut butter","1 1/4 cups fat-free milk","3 cups baby spinach (coarsely chopped)","1/4 cup chopped peanuts (optional)","green onion (optional, thinly sliced for garnish)"]}],"directions":[{"name":null,"steps":["Combine first 9 ingredients in a soup pot. Bring to boil, then turn down to medium low, cover and simmer for 10 minutes.","Stir in peanut butter and milk. Return to gentle simmer and cook uncovered for 5 minutes.","Stir in spinach and cook until wilted, 2 to 3 minutes. Remove from heat.","Ladle stew into bowls and top with peanuts and green onion, if desired."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"230.48 kcal","carbohydrateContent":"34.44 g","cholesterolContent":"1.14 mg","fiberContent":"3.88 g","proteinContent":"9.89 g","sodiumContent":"144.56 mg","sugarContent":"6.30 g","fatContent":"6.79 g","saturatedFatContent":"1.29 g"},"notes":"Substitute 12 ounces frozen spinach for fresh.\nFlavor boosters: chopped cilantro, red and green peppers, raisins.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"pear-kabobs-strawberry-dipping-sauce","source_url":"https://www.myplate.gov/recipes/pear-kabobs-strawberry-dipping-sauce","name":"Pear Kabobs with Strawberry Dipping Sauce","description":"Fruity kabobs that you can enjoy for a snack or dessert. Try experimenting with different patterns and fruits.","ingredients":[{"name":null,"items":["1 cup low-fat vanilla yogurt","4 tablespoons strawberry preserves","2 medium pears, cored and cut into 1-inch cubes","2 cups strawberries, stems removed","2 medium bananas, cut into 1-inch slices","1 can (20 ounces) pineapple chunks, drained"]}],"directions":[{"name":null,"steps":["In a small bowl, combine the vanilla yogurt and strawberry preserves. Set aside.","Thread the fruits by alternating the pears, strawberries, bananas, and pineapple onto the skewers.","Serve the fruit skewers with a dollop of the strawberry sauce on the side."]}],"yield":"6 Kabobs","nutrition":{"@type":"NutritionInformation","servingSize":["1 kabob","1/6 of recipe"],"calories":"205.88 kcal","carbohydrateContent":"47.19 g","cholesterolContent":"2.45 mg","fiberContent":"4.38 g","proteinContent":"3.40 g","sodiumContent":"42.61 mg","sugarContent":"36.30 g","fatContent":"1.06 g","saturatedFatContent":"0.47 g"},"notes":"Other materials needed:\nSix wooden skewers\nsmall bowl\ncutting board\ncan opener\nparing knife\nmeasuring spoons\nplatter or large plate","contributor":"USA Pears (recipe) and Pear Bureau Northwest (photo)"},
{"slug":"pear-orange-sauce","source_url":"https://www.myplate.gov/recipes/pear-orange-sauce","name":"Pear in Orange Sauce","description":"Sweet and simple, this warm and cozy dessert is the perfect end to a fall or winter meal.","ingredients":[{"name":null,"items":["4 medium pears","3/4 cup 100% orange juice","4 teaspoons sugar"]}],"directions":[{"name":null,"steps":["Peel the pears and cook in a double boiler for 15 minutes.","Mix sugar and orange juice and cook over low flame for 5 minutes. Cool for 5 minutes.","Place steamed pears on individual plates. Pour 1/4 of the juice mixture over each and serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 pear","calories":"144.90 kcal","carbohydrateContent":"36.19 g","cholesterolContent":"0.00 mg","fiberContent":"5.72 g","proteinContent":"1.04 g","sodiumContent":"5.44 mg","sugarContent":"25.46 g","fatContent":"0.45 g","saturatedFatContent":"0.04 g"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"pear-party-salsa","source_url":"https://www.myplate.gov/recipes/pear-party-salsa","name":"Pear Party Salsa","description":"Scrumptious, sweet salsa that will be a party favorite. Use a tart apple variety for best results.","ingredients":[{"name":null,"items":["1 medium pear, cored and finely chopped","1 medium apple, cored and finely chopped","2 kiwifruits, cored and finely chopped","1 medium orange, peeled and finely chopped","2 tablespoons honey*","1 teaspoon lemon juice","cinnamon graham crackers (optional)"]}],"directions":[{"name":null,"steps":["Combine pear, apple, kiwifruit, and orange in a medium-sized bowl.","Pour honey and lemon juice over fruit and gently toss.","Scoop up bites of fruit salsa using bites of cinnamon graham crackers (optional)."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"130.98 kcal","carbohydrateContent":"32.36 g","cholesterolContent":"0.00 mg","fiberContent":"4.44 g","proteinContent":"1.04 g","sodiumContent":"5.18 mg","sugarContent":"25.49 g","fatContent":"0.36 g","saturatedFatContent":"0.04 g"},"notes":"*Children under the age of one should not consume honey.\nFrozen or canned fruit (such as pears) can be substituted for fresh\nOther materials needed:\nparing knife\nmeasuring spoons\ncutting board\nfruit peeler\nslotted spoon\nmedium-sized bowl","contributor":"USA Pears and Pear Bureau Northwest"},
{"slug":"pear-pbj-bouquet","source_url":"https://www.myplate.gov/recipes/pear-pbj-bouquet","name":"Pear PB&J Bouquet","description":"Beautiful, nutritious, and delicious, this open-faced sandwich is worth the extra effort.","ingredients":[{"name":null,"items":["8 slices whole grain wheat bread","1 medium pear","8 teaspoons peanut butter","1 1/3 tablespoons strawberry preserves (4 teaspoons)"]}],"directions":[{"name":null,"steps":["Use a flower-shaped cookie cutter to cut each slide of bread. If bread sticks to cutter, gently push the petals out with your fingers.","Wash the pear and dry it with a paper towel. Cut the pear in half, and remove the core. Cut each pear half into four slices, then cut each slice into five pieces. You will only use the center three pieces of each slice, so go ahead and eat the end pieces.","Spread 1 teaspoon of peanut butter in a circle in the center of each of the flowers. Place 3 pieces of pear on the peanut butter on each flower. Arrange the pears so the skin is facing out and the white centers are touching in the middle.","Drizzle 1/2 teaspoon of strawberry preserves in the center of each flower and over the pears."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 pear flower","1/4 of recipe"],"calories":"147.64 kcal","carbohydrateContent":"22.45 g","cholesterolContent":"0.00 mg","fiberContent":"3.15 g","proteinContent":"5.72 g","sodiumContent":"186.55 mg","sugarContent":"6.04 g","fatContent":"4.04 g","saturatedFatContent":"0.81 g"},"notes":"Other materials needed:\nparing knife\ndeep cookie cutter, flower-shaped\nmeasuring spoons\nsqueeze bottle (optional)","contributor":"The Pear Dish\nUSA Pears"},
{"slug":"pear-quesadillas","source_url":"https://www.myplate.gov/recipes/pear-quesadillas","name":"Pear Quesadillas","description":"An easy way to add more fruit to your day is to incorporate them into your meals. Canned pears and cheese go well together in this quesadilla, with added fla...","ingredients":[{"name":null,"items":["2 flour tortillas (8\" diameter)","1/2 cup shredded pepper jack cheese","1/2 cup shredded mozzarella cheese","1 tablespoon dried basil","2 tablespoons chopped onion","2 canned pear halves, sliced thin","2 teaspoons olive oil"]}],"directions":[{"name":null,"steps":["Sprinkle cheeses, basil, and onion on half of each tortilla.","Place pear slices on top of other ingredients in each tortilla.","Fold over filled tortilla and brush each side with olive oil.","Heat the filled tortillas in a non-stick skillet until cheese melts, about 2 to 3 minutes on each side.","Cut quesadilla into four pieces and serve immediately."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 pieces","calories":"209.22 kcal","carbohydrateContent":"18.15 g","cholesterolContent":"21.75 mg","fiberContent":"1.97 g","proteinContent":"9.07 g","sodiumContent":"352.44 mg","sugarContent":"5.89 g","fatContent":"11.37 g","saturatedFatContent":"5.40 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"pear-rabbit","source_url":"https://www.myplate.gov/recipes/pear-rabbit","name":"Pear Rabbit","description":"A cute and fruity \"rabbit\" snack that kids can help make.","ingredients":[{"name":null,"items":["3 canned pear halves","1 tablespoon raisins"]}],"directions":[{"name":null,"steps":["Place 2 pear halves, flat side down, on a small plate to make the body.","Use butter knife to cut a tail, ears and feet from another pear half. Add each part to the body.","Use butter knife to cut one raisin in half and place on small end for eyes.","Enjoy your pear rabbit!"]}],"yield":"1 Pear Rabbit","nutrition":{"@type":"NutritionInformation","servingSize":"1 pear rabbit","calories":"151.40 kcal","carbohydrateContent":"39.79 g","cholesterolContent":"0.00 mg","fiberContent":"4.50 g","proteinContent":"0.95 g","sodiumContent":"16.10 mg","sugarContent":"33.52 g","fatContent":"0.21 g","saturatedFatContent":"0.04 g"},"notes":"Adults: If cooking with kids, use can opener, open pear halves and discard sharp-edged lid.","contributor":"Chickasaw Nation Get Fresh! Nutrition Education Program"},
{"slug":"pear-salad","source_url":"https://www.myplate.gov/recipes/pear-salad","name":"Pear Salad","description":"Get your servings of fruits and veggies in one dish! This salad is sweet and tangy with a yogurt and orange juice dressing. Serve it as a side salad to compl...","ingredients":[{"name":"For the Salad","items":["2 cups salad greens","1/4 cup sliced tomato","1/4 cup sliced carrots","1/4 cup sliced cucumbers","1/4 cup green beans, sliced into bite size pieces","1 cup canned pears, drained and chopped","2 tablespoons walnuts","2 tablespoons raisins"]},{"name":"For the Dressing","items":["1 1/2 teaspoons white vinegar","1/4 cup non-fat plain yogurt","1 tablespoon orange juice"]}],"directions":[{"name":null,"steps":["Place salad greens, sliced vegetables, pears, walnuts, and raisins in a large bowl.","In a small bowl, whisk together vinegar, yogurt, and orange juice to prepare dressing.","Top salad with dressing and mix gently. Serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"90.06 kcal","carbohydrateContent":"15.84 g","cholesterolContent":"0.31 mg","fiberContent":"2.24 g","proteinContent":"2.44 g","sodiumContent":"30.44 mg","sugarContent":"12.22 g","fatContent":"2.67 g","saturatedFatContent":"0.28 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"pears-pod","source_url":"https://www.myplate.gov/recipes/pears-pod","name":"Pears in a Pod","description":"Creamy peanut butter, crunchy celery, and juicy pears make the perfect snack for kids and adults.","ingredients":[{"name":null,"items":["4 medium celery stalks, cleaned and cut into 3-inch long pieces","1/2 cup creamy peanut butter","2 medium pears, cored and cut into chunks"]}],"directions":[{"name":null,"steps":["Spread the peanut butter into the center of the celery pieces.","Place the pear chunks on top of the peanut butter.","Serve on a plate and enjoy with your friends."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"263.18 kcal","carbohydrateContent":"22.00 g","cholesterolContent":"0.00 mg","fiberContent":"4.97 g","proteinContent":"7.81 g","sodiumContent":"171.98 mg","sugarContent":"12.65 g","fatContent":"16.56 g","saturatedFatContent":"3.27 g"},"notes":"Other materials needed:\nParing knife\nSmall spatula or table knife\nCutting board\nMeasuring cups","contributor":"USA Pears and Pear Bureau Northwest"},
{"slug":"peppers-stuffed-rice-beans","source_url":"https://www.myplate.gov/recipes/peppers-stuffed-rice-beans","name":"Peppers Stuffed with Rice and Beans","description":"These simple stuffed peppers are fun and flavorful. Use yellow, red, green, and orange peppers for a colorful dish.","ingredients":[{"name":null,"items":["1 cup uncooked brown rice","1 can low-sodium black beans (15 ounce can)","6 bell peppers (any color)","1 cup reduced-fat cheddar cheese (shredded)","1 tomato (chopped)","1 cup salsa","salt (optional to taste)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 °F.","Cook brown rice according to package directions.","Wash the peppers under running water.","Cut the tops off the peppers and spoon out the seeds.","Cut up two peppers and leave four to fill with the rice mixture.","Drain and rinse the black beans.","Combine the chopped up peppers, beans, rice, salsa, tomato and salt (optional).","Spoon about 3 tablespoons of the mixture into the bottom of each pepper.","Sprinkle with 2 tablespoons of cheese.","Repeat steps 8 and 9 to fill the pepper completely, but do not top with cheese.","Bake peppers for 30 minutes.","Top each pepper with 2 tablespoons of cheese and continue baking for 15 minutes more."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"439.39 kcal","carbohydrateContent":"72.77 g","cholesterolContent":"21.47 mg","fiberContent":"12.75 g","proteinContent":"20.67 g","sodiumContent":"602.79 mg","sugarContent":"8.14 g","fatContent":"8.03 g","saturatedFatContent":"4.12 g"},"notes":"Green bell peppers used for nutritional analysis.\nUse homemade salsa to lower the sodium of this recipe.","contributor":"Adapted from Simple Stuffed Peppers, Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"perfect-pear-and-brussels-sprout-salad","source_url":"https://www.myplate.gov/recipes/perfect-pear-and-brussels-sprout-salad","name":"The Perfect \"Pear\" and Brussels Sprout Salad","description":"This sweet and savory salad is fresh and light and sure to please! This salad \"pears\" perfectly as a side dish at your holiday gathering. This dish is kid-te...","ingredients":[{"name":null,"items":["3 cups shredded Brussels sprouts","1 large pear, diced (approx. 1 1/2 cup)","1/3 cup dried cranberries","1/4 cup sliced almonds","1 1/2 tablespoons extra virgin olive oil","1/4 teaspoon salt","1/4 teaspoon garlic powder","1/4 teaspoon dried thyme","1/8 teaspoon nutmeg","1/8 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["In a large mixing bowl, add the pear, Brussels sprouts, and all other ingredients and mix until well incorporated.","Serve and enjoy!"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"195.99 kcal","carbohydrateContent":"26.00 g","cholesterolContent":"0.00 mg","fiberContent":"5.85 g","proteinContent":"4.39 g","sodiumContent":"166.80 mg","sugarContent":"15.84 g","fatContent":"10.10 g","saturatedFatContent":"1.23 g"},"notes":null,"contributor":"Created by Brighter Bites, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"perfect-pumpkin-pancakes","source_url":"https://www.myplate.gov/recipes/perfect-pumpkin-pancakes","name":"Perfect Pumpkin Pancakes","description":"Fluffy, pumpkin pancakes will delight your taste buds at breakfast or dinner. Top with sliced banana or applesauce.","ingredients":[{"name":null,"items":["2 cups all-purpose flour","6 teaspoons brown sugar (2 tablespoons)","1 tablespoon baking powder","1 1/4 teaspoons pumpkin pie spice","1 teaspoon salt","1 large egg","1/2 cup canned pumpkin","1 3/4 cups 1% low-fat milk","2 tablespoons vegetable oil"]}],"directions":[{"name":null,"steps":["Combine flour, brown sugar, baking powder, pumpkin pie spice, and salt in a large mixing bowl.","In a medium bowl, combine egg, canned pumpkin, milk, and vegetable oil; mix well.","Add wet ingredients to flour mixture, stirring just until moist. Batter may be lumpy. (For thinner batter, add more milk.)","Lightly coat a griddle or skillet with cooking spray and heat on medium.","Using a 1/4 cup measure, pour batter onto hot griddle. Cook until bubbles begin to burst, then flip pancakes and cook until golden brown, 1 1/2 to 2 1/2 minutes. Repeat with remaining batter. Makes about 1 dozen 3 1/2 inch pancakes."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 pancake","1/12 of recipe"],"calories":"131.52 kcal","carbohydrateContent":"21.30 g","cholesterolContent":"18.90 mg","fiberContent":"0.89 g","proteinContent":"4.00 g","sodiumContent":"339.54 mg","sugarContent":"4.41 g","fatContent":"3.34 g","saturatedFatContent":"0.72 g"},"notes":"If you don''t have pumpkin spice on hand, don''t worry -- it''s just a combination of cinnamon, nutmeg, ginger, and cloves. In this recipe, you can substitute 3/4 teaspoon cinnamon, 1/4 teaspoon nutmeg, and 1/8 teaspoon each of ginger and cloves for the pumpkin pie spice.\nSafety Tip: You can be sure your skillet or griddle is hot enough for pancakes without burning your hand. Just sprinkle a few (3 or 4) drops of water on the surface. If they dance and sizzle, you are ready to cook. Be sure handles of skillets and pans are always turned toward the center or back of the stove, to prevent the pan from catching on hands or clothes and causing burns.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"peter-pumpkin-squares","source_url":"https://www.myplate.gov/recipes/peter-pumpkin-squares","name":"Peter Pumpkin Squares","description":"A perfect treat for pumpkin lovers. A seasonal treat for the holidays or any time of year that you''re craving pumpkin.","ingredients":[{"name":null,"items":["1 can pumpkin (15 ounces)","1 1/2 cups brown sugar (packed)","4 large eggs","3/4 cup cooking oil","1 1/2 cups all-purpose flour","1 1/2 cups rolled oats","1 tablespoon ground cinnamon","2 teaspoons baking powder","1 teaspoon baking soda","1 teaspoon margarine or butter (to grease the pan)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a medium bowl, stir together the pumpkin, brown sugar, eggs, and oil. Mix well.","In a large bowl, mix the flour, oats, cinnamon, baking powder, and baking soda.","Add the pumpkin mix to the flour mix. Stir well.","Grease a 9x13-inch baking pan with butter or margarine.","Pour the batter into the greased baking pan.","Bake for 30 minutes."]}],"yield":"24 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 bar","calories":"182.62 kcal","carbohydrateContent":"24.72 g","cholesterolContent":"34.25 mg","fiberContent":"1.40 g","proteinContent":"2.73 g","sodiumContent":"110.36 mg","sugarContent":"14.02 g","fatContent":"8.40 g","saturatedFatContent":"1.34 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"picadillo-0","source_url":"https://www.myplate.gov/recipes/picadillo-0","name":"Picadillo","description":"This recipe starts with seasoned and browned ground beef simmered with tomatoes and beans and is finished with a mix of olives and raisins. Served over rice,...","ingredients":[{"name":null,"items":["1 cup uncooked brown rice","2 cups water","2 teaspoons vegetable oil","1 onion, diced","1 bell pepper, diced","2 cloves garlic, minced","1 1/2 teaspoons dried oregano","1 teaspoon ground cumin","1/4 teaspoon black pepper","1/4 teaspoon Kosher salt","3/4 pound lean ground turkey or beef","1 14.5 ounce can low-sodium diced tomatoes (including liquid)","1 15 ounce can low-sodium black beans, drained and rinsed","1/4 cup green olives, chopped","1/4 cup raisins"]}],"directions":[{"name":"Prepare the Rice","steps":["Cook as instructed on the package.","Set aside."]},{"name":"Prepare the Picadillo","steps":["Place the skillet on the stove over medium heat and when hot, add oil. Add the onion, pepper, and garlic. Cook and stir about 10 minutes until the onion is softened and lightly browned.","Add oregano, cumin, pepper, and salt, and stir well.","Add beef, in small amounts. Stir well and cook about 10 minutes until the beef is cooked throughout.","Add beans and tomatoes and simmer about 15 minutes until mixture blends together.","Add olives and raisins. Stir well and cook about 2 minutes until heated through.","Serve over rice or refrigerate in an airtight container for up to 3 days. Serve with avocado, if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cup","calories":"547.11 kcal","carbohydrateContent":"75.83 g","cholesterolContent":"63.11 mg","fiberContent":"13.77 g","proteinContent":"27.79 g","sodiumContent":"434.68 mg","sugarContent":"12.30 g","fatContent":"16.01 g","saturatedFatContent":"3.81 g"},"notes":"Dried cranberries can be used instead of raisins.\nSee how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"picadillo","source_url":"https://www.myplate.gov/recipes/picadillo","name":"Picadillo","description":"A fun flavorful dish that is full of veggies and lean protein and can be made in a flash.","ingredients":[{"name":null,"items":["1 pound 85% lean ground turkey","1 medium onion, chopped","5 medium carrots, diced","2 medium zucchinis (or other squash)","2 medium potatoes, diced","1 teaspoon salt","black pepper (optional, to taste)","1/2 teaspoon cumin","1 1/4 cups low-sodium canned tomatoes","1 teaspoon cornstarch"]}],"directions":[{"name":null,"steps":["Brown ground turkey in a non-stick frying pan.","Add onions, carrots, zucchini, potatoes, salt, pepper, and cumin. Sauté for about 5 minutes.","Add tomatoes and just enough water to cover. Bring to a boil, then lower heat and simmer, uncovered, until vegetables are tender.","Dissolve cornstarch in about 1 tablespoon of cold water, add to mixture, bring back to a boil until gravy thickens. Serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/6 of recipe"],"calories":"241.88 kcal","carbohydrateContent":"23.50 g","cholesterolContent":"56.10 mg","fiberContent":"4.66 g","proteinContent":"16.58 g","sodiumContent":"486.90 mg","sugarContent":"6.99 g","fatContent":"9.81 g","saturatedFatContent":"2.53 g"},"notes":null,"contributor":"California Health Department, Los Angeles County\nEs Facil Campaign"},
{"slug":"pico-de-gallo","source_url":"https://www.myplate.gov/recipes/pico-de-gallo","name":"Pico de Gallo","description":"A fantastic recipe to try when your garden or market is overflowing with fresh, flavorful tomatoes!","ingredients":[{"name":null,"items":["2 cups ripe tomatoes, chopped","1 1/2 cups onion, chopped","1/3 cup cilantro, chopped","3 jalapeno pepper, seeded and chopped","2 tablespoons lime juice","2 cloves garlic, minced","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Combine all ingredients in a medium bowl.","Serve immediately or cover and refrigerate for up to 3 days."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"32.67 kcal","carbohydrateContent":"7.13 g","cholesterolContent":"0.00 mg","fiberContent":"1.64 g","proteinContent":"1.05 g","sodiumContent":"102.29 mg","sugarContent":"4.36 g","fatContent":"0.26 g","saturatedFatContent":"0.04 g"},"notes":"Use to season your family meals or serve with tortilla chips.","contributor":"Healthy Latino Recipes Made with Love\nCalifornia Department of Health Services\nCalifornia Latino 5-A-Day Campaign"},
{"slug":"pineapple-angel-food-cake","source_url":"https://www.myplate.gov/recipes/pineapple-angel-food-cake","name":"Pineapple Angel Food Cake","description":"Fluffy and fruity, this airy cake is delicate and sweet, the perfect after dinner treat.","ingredients":[{"name":null,"items":["12 large egg whites (about 1 1/2 cups)","1 teaspoon cream of tartar","1 1/2 cups sugar","1 teaspoon vanilla extract","1/4 teaspoon salt","1 cup flour, sifted","1 cup crushed pineapple in 100% juice (do not drain)","whipped topping (optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a large mixing bowl, beat the egg whites until they are foamy.","Add the cream of tartar and beat until stiff, but not dry. Gradually beat in the sugar.","Add the vanilla and salt and then gently fold in the flour.","Add the pineapple to the cake mix.","Pour into an ungreased 13x9-inch pan.","Bake for 25 to 35 minutes, until golden brown or an inserted toothpick comes out clean.","Let cool and serve with whipped topping (optional)."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"166.78 kcal","carbohydrateContent":"36.32 g","cholesterolContent":"0.00 mg","fiberContent":"0.45 g","proteinContent":"4.70 g","sodiumContent":"105.40 mg","sugarContent":"27.56 g","fatContent":"0.21 g","saturatedFatContent":"0.02 g"},"notes":null,"contributor":"Ohio State University Cooperative Extension"},
{"slug":"pineapple-avocado-chicken-salad","source_url":"https://www.myplate.gov/recipes/pineapple-avocado-chicken-salad","name":"Pineapple Avocado Chicken Salad","description":"Delicious sandwich, wrap, or pita filling featuring chunks of avocado, pineapple, and chicken. Avocado helps make a creamy, luscious dressing.","ingredients":[{"name":null,"items":["1 avocado (divided)","2 tablespoons non-fat plain Greek yogurt","1 tablespoon rice vinegar","1/4 teaspoon salt","1/8 teaspoon black pepper","1 cup fresh pineapple chunks","1 red bell pepper, chopped","1/2 cup shredded carrots (about 2 carrots)","1/2 cup shredded cabbage","1 green onion, sliced","2 cups cooked, cubed chicken breast (about 8 oz.)","4 6 1/2-inch whole wheat pita pockets (or 8 4-inch pita pockets)"]}],"directions":[{"name":null,"steps":["Mash 1/2 avocado in a small dish; add yogurt, rice vinegar, salt, and pepper.","Cut remaining avocado into small chunks and mix together with pineapple, bell pepper, carrots, cabbage, green onion, and chicken.","Add dressing; mix gently.","Fill pita pockets and serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"362.98 kcal","carbohydrateContent":"45.00 g","cholesterolContent":"67.07 mg","fiberContent":"8.01 g","proteinContent":"28.55 g","sodiumContent":"440.41 mg","sugarContent":"8.63 g","fatContent":"9.11 g","saturatedFatContent":"1.48 g"},"notes":"Serve with 8 ounce non-fat milk.","contributor":"Produce for Better Health"},
{"slug":"pineapple-chicken","source_url":"https://www.myplate.gov/recipes/pineapple-chicken","name":"Pineapple Chicken","description":"Serve this tangy chicken dish with brown rice. Add brightly colored vegetables for a tasty and simple meal!","ingredients":[{"name":null,"items":["2 1/2 pounds boneless skinless chicken breast","1/4 teaspoon salt","1/8 teaspoon black pepper","1 can (20 ounces) pineapple, crushed or chunks","2 us fluid ounces water"]}],"directions":[{"name":null,"steps":["Coat frying pan with nonstick cooking spray and set heat to low.","Once pan heats up, add chicken. Sprinkle with salt and pepper.","Cook uncovered until chicken begins to brown, then add crushed pineapple and water.","Cover chicken until chicken is tender.","May serve over rice."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"301.22 kcal","carbohydrateContent":"13.87 g","cholesterolContent":"150.13 mg","fiberContent":"0.92 g","proteinContent":"46.77 g","sodiumContent":"196.73 mg","sugarContent":"12.81 g","fatContent":"5.53 g","saturatedFatContent":"1.18 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"pineapple-orange-frozen-yogurt","source_url":"https://www.myplate.gov/recipes/pineapple-orange-frozen-yogurt","name":"Pineapple Orange Frozen Yogurt","description":"A fruity and tropical treat to keep you cool during the dog days of summer.","ingredients":[{"name":null,"items":["1 cup fat-free vanilla yogurt","1 cup pineapple chunks, fresh or canned","1/2 cup orange juice"]}],"directions":[{"name":null,"steps":["Place yogurt and pineapple in large plastic bag and flatten. Freeze overnight.","Combine yogurt, pineapple, and juice in food processor or blender and blend until smooth.","Serve immediately or place back in the freezer to harden until ready to serve, up to 1 hour, stirring occasionally. Stir before serving."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 of recipe","calories":"100.83 kcal","carbohydrateContent":"19.83 g","cholesterolContent":"1.63 mg","fiberContent":"0.89 g","proteinContent":"5.17 g","sodiumContent":"61.80 mg","sugarContent":"17.25 g","fatContent":"0.36 g","saturatedFatContent":"0.10 g"},"notes":null,"contributor":"Food and Health Communications, Inc."},
{"slug":"pineapple-pork","source_url":"https://www.myplate.gov/recipes/pineapple-pork","name":"Pineapple Pork","description":"Savory and sweet, delicious pineapple pork chops are a fast and flavorful meal. Enjoy over brown rice or quinoa.","ingredients":[{"name":null,"items":["1 medium green pepper","1 tablespoon vegetable oil (or cooking oil of your choice)","4 boneless pork chops (about 1 pound)","1/8 teaspoon salt","1 cup canned pineapple chunks, undrained (8 ounces)","1/4 teaspoon ground ginger","1/4 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Cut the green pepper into strips.","Heat the oil in a large skillet.","Place pork chops on the heated skillet. Sprinkle the salt on top.","Cook the pork chops for 5 minutes on low heat on each side.","Cook pork chops until they reache an internal temperature of 145 degrees F.","Remove the cooked pork from the skillet. Place it in a serving dish and keep warm.","Put the green pepper slices in the skillet.","Stir in the pineapple chunks with their juice.","Add the ginger and cinnamon.","Simmer for about 3 to 5 minutes.","Spoon the pineapple mixture over cooked pork."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3 oz. prepared pork","1/4 of recipe"],"calories":"321.16 kcal","carbohydrateContent":"9.61 g","cholesterolContent":"104.39 mg","fiberContent":"0.94 g","proteinContent":"41.72 g","sodiumContent":"263.85 mg","sugarContent":"7.85 g","fatContent":"12.37 g","saturatedFatContent":"3.48 g"},"notes":"Serve with cooked rice.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"pineapple-rice-bake","source_url":"https://www.myplate.gov/recipes/pineapple-rice-bake","name":"Pineapple Rice Bake","description":"A cozy and creamy dessert that your whole family will enjoy.","ingredients":[{"name":null,"items":["4 large eggs","1 cup 1% low-fat milk","1/2 cup sugar","1 cup pineapple, crushed, undrained (8 ounce can)","1/2 teaspoon cinnamon","1/2 teaspoon nutmeg","1 teaspoon vanilla","3 cups cooked rice"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Lightly coat an oven safe 2 quart casserole dish with nonstick spray or oil.","In a large mixing bowl, beat together eggs, milk, and sugar.","Add undrained crushed pineapple, cinnamon, nutmeg, and vanilla.","Stir in cooked rice. Pour into prepared casserole dish.","Bake for 50 to 60 minutes or until a knife inserted in center of pudding comes out clean."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"257.66 kcal","carbohydrateContent":"46.62 g","cholesterolContent":"139.03 mg","fiberContent":"0.80 g","proteinContent":"7.83 g","sodiumContent":"61.66 mg","sugarContent":"23.47 g","fatContent":"4.10 g","saturatedFatContent":"1.41 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"pineapple-zucchini-cake","source_url":"https://www.myplate.gov/recipes/pineapple-zucchini-cake","name":"Pineapple Zucchini Cake","description":"Stuffed with fruits and veggies, this hearty cake can be shared after a light lunch or dinner.","ingredients":[{"name":null,"items":["3 eggs","2 cups sugar","2 teaspoons vanilla","1 cup vegetable oil","2 cups zucchini (peeled, grated)","1 teaspoon baking powder","1 teaspoon salt","1 teaspoon baking soda","3 cups flour (all purpose)","1 cup pineapple, crushed, drained","1/2 cup raisins (optional)","1 cup chopped pecans (optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Grease or lightly spray with non-stick cooking spray, a 9x13 inch pan.","In a large bowl, beat eggs, sugar, vanilla, and oil. Add zucchini.","In a separate bowl, combine baking powder salt, baking soda, and flour. Add dry ingredients to creamed mixture.","Stir in fruit and nuts, if using.","Bake for 45 to 50 minutes, or until cake springs back when lightly pressed with your finger."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 3x3.25 inch piece of cake","1/12 of recipe (135g)"],"calories":"448.57 kcal","carbohydrateContent":"60.45 g","cholesterolContent":"51.38 mg","fiberContent":"1.20 g","proteinContent":"5.10 g","sodiumContent":"361.73 mg","sugarContent":"36.25 g","fatContent":"20.41 g","saturatedFatContent":"3.02 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"pink-party-salad","source_url":"https://www.myplate.gov/recipes/pink-party-salad","name":"Pink Party Salad","description":"Pretty in pink! Enjoy this colorful and flavorful salad at a picnic or cookout with family and friends.","ingredients":[{"name":null,"items":["4 potatoes (washed and cut in half)","3 cups beets, cooked (peeled and diced)","1 cup peas, green, fresh or frozen","3 eggs, hard boiled","1 apple","1 teaspoon lemon juice","2 tablespoons olive oil","3 tablespoons vinegar","1 tablespoon sugar"]}],"directions":[{"name":null,"steps":["Boil the potatoes in 2 cups of water in a deep kettle. Cover and cook over moderate heat for about 20 minutes, until the potatoes are tender.","When thoroughly cool, dice potatoes and place in a big bowl.","Add diced beets and mix with the potatoes.","Set aside 1/4 cup of peas for garnishing and add the rest to the bowl.","Save 1 egg to use as a garnish. Chop the rest and add to the bowl.","Peel the skin off the apple and remove the core. Cut the apple into small pieces, place in a small bowl, and sprinkle with lemon juice. Add apple to the salad.","Add the vinegar, olive oil, and sugar.","Mix thoroughly. Chill and serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (246g)","calories":"274.89 kcal","carbohydrateContent":"43.91 g","cholesterolContent":"102.75 mg","fiberContent":"6.92 g","proteinContent":"8.84 g","sodiumContent":"133.37 mg","sugarContent":"14.74 g","fatContent":"7.59 g","saturatedFatContent":"1.61 g"},"notes":"The skin can be left on the apple to increase fiber and save time.","contributor":"From the Farm to the Table\nUniversity of Connecticut Cooperative Extension\nHispanic Health Council"},
{"slug":"pizza-eggburger","source_url":"https://www.myplate.gov/recipes/pizza-eggburger","name":"Pizza Eggburger","description":"Teach your teenagers how to make this tasty and easy recipe as an afterschool snack.","ingredients":[{"name":null,"items":["1 egg","1 hamburger bun (whole wheat)","1 tablespoon mozzarella cheese (part skim)","pepperoni (3 slices, optional)","1 tablespoon pizza sauce"]}],"directions":[{"name":null,"steps":["Spray a small non-stick skillet with non-stick cooking spray.","Over medium heat, break egg into pan; break yolk.","When egg is done turn over sprinkle with cheese and top with pepperoni (optional). Cook until cheese is melted.","Open bun, spread with pizza sauce and top with cooked egg."]}],"yield":"1 Pizza Eggburger","nutrition":{"@type":"NutritionInformation","servingSize":"1 pizza eggburger","calories":"231.71 kcal","carbohydrateContent":"25.96 g","cholesterolContent":"207.10 mg","fiberContent":"2.40 g","proteinContent":"13.14 g","sodiumContent":"457.54 mg","sugarContent":"1.95 g","fatContent":"8.50 g","saturatedFatContent":"2.41 g"},"notes":null,"contributor":"Ohio State University Cooperative Extension\nRoss County Extension Office"},
{"slug":"pizza-meat-loaf","source_url":"https://www.myplate.gov/recipes/pizza-meat-loaf","name":"Pizza Meat Loaf","description":"There are microwave and oven directions for this recipe, so that you can make this meal in a way that is quick and convenient for you and your family. Enjoy ...","ingredients":[{"name":null,"items":["1 pound ground turkey (85% lean)","3/4 cup spaghetti sauce","1/4 cup mozzarella cheese, part-skim","1/2 cup green pepper (chopped)","1/4 cup onion (minced)"]}],"directions":[{"name":null,"steps":["Lightly grease 9 inch pie plate with vegetable oil. Pat turkey into pie plate.","Cover turkey with waxed paper. Cook in microwave on high; rotate plate 1/4 turn after 3 minutes. Cook until turkey reaches an internal temperature of 160 °F, about 5 more minutes. Drain excess liquid. OR - Place turkey in 350 °F oven; bake until turkey reaches an internal temperature of 160 °F, about 30 to 35 minutes. Drain any excess liquid.","Top cooked turkey with vegetables, spaghetti sauce, and cheese.","Return turkey to either the microwave or oven and heat until cheese is melted, about 1 to 2 minutes."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/4 of meat loaf","1/4 of recipe (199g)"],"calories":"258.12 kcal","carbohydrateContent":"5.95 g","cholesterolContent":"89.71 mg","fiberContent":"1.37 g","proteinContent":"22.54 g","sodiumContent":"321.76 mg","sugarContent":"3.84 g","fatContent":"16.05 g","saturatedFatContent":"4.55 g"},"notes":null,"contributor":"Ohio State University Cooperative Extension"},
{"slug":"plantain-cups-shredded-chicken-mofonguitos","source_url":"https://www.myplate.gov/recipes/plantain-cups-shredded-chicken-mofonguitos","name":"Plantain Cups with Shredded Chicken | Mofonguitos","description":"Mofonguitos are a delicious Puerto Rican inspired dish consisting of small, plantain cups filled with savory, seasoned chicken.","ingredients":[{"name":"Chicken filling","items":["1 small can chicken (10 ounces, drained or 1 cup cooked diced chicken)","1/3 cup onion (chopped)","1 tablespoon olive oil (or cooking oil of your choice)","1/2 teaspoon cumin","1/2 teaspoon garlic powder","1/4 teaspoon black pepper","1/4 teaspoon salt"]},{"name":"Plantain cups","items":["2 large green plantains","2 tablespoons olive oil (Or cooking oil of your choice)","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["In a skillet, heat oil over medium heat. Add shredded chicken and onions. Cook for about 1-2 minutes.","Add spices to the mixture and cook, stirring often, for about 5 minutes. Set aside for later.","Wash and scrub plantains. Cut off each end and make 3 vertical cuts along the side of the plantain. Using your thumb, peel the skin away from the flesh of the plantain and cut into 1-inch chunks.","Heat the oil over medium heat in a skillet for about 1 minute. Add the plantain chunks and sprinkle the salt on top. Cook on all sides of the chunks (about 5-6 minutes on each side). Using tongs, be sure to turn the plantain pieces on their sides so the insides cook throughout, and they turn a golden color.","Turn the heat down to low and remove the plantain chunks from the pan.","Take 2 plantain chunks at a time and shape them into a cup using either your hands, a small pestle and mortar, or a lemon squeezer.","Fill the plantain cups with the chicken mixture and top with a low-fat yogurt dip (optional).","Serve immediately."]}],"yield":"10 plantain cups","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"145.30 kcal","carbohydrateContent":"11.75 g","cholesterolContent":"17.01 mg","fiberContent":"0.71 g","proteinContent":"9.15 g","sodiumContent":"283.91 mg","sugarContent":"6.25 g","fatContent":"7.11 g","saturatedFatContent":"1.42 g"},"notes":null,"contributor":"University of Rhode Island SNAP-Education"},
{"slug":"pocket-fruit-pies","source_url":"https://www.myplate.gov/recipes/pocket-fruit-pies","name":"Pocket Fruit Pies","description":"A fun recipe to make with kids. Use your favorite fruit and whole grain tortillas, and enjoy!","ingredients":[{"name":null,"items":["4 flour tortillas (8 inch)","2 peaches, pears, or apples (medium)","1/4 teaspoon cinnamon (ground)","6 teaspoons brown sugar, packed (2 Tablespoons)","1/8 teaspoon nutmeg (ground)","2 tablespoons milk (fat-free)","sugar (optional)"]}],"directions":[{"name":null,"steps":["Warm tortillas in microwave or oven to make them easier to handle.","Peel and chop fruit into pieces.","Place 1/4 of the fruit on half of each tortilla.","In a small bowl, stir together brown sugar, cinnamon, and nutmeg. Sprinkle over fruit.","Roll up the tortillas, starting at the end with the fruit.","Place on an greased baking sheet and make small slashes to allow steam to escape. Brush with milk and sprinkle with additional sugar, if desired.","Back at 350 °F in oven for 8 to 12 minutes or until lightly brown.","Serve warm or cool."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 prepared fruit pie","1/4 of recipe (109g)"],"calories":"201.79 kcal","carbohydrateContent":"37.12 g","cholesterolContent":"0.23 mg","fiberContent":"2.80 g","proteinContent":"4.65 g","sodiumContent":"346.04 mg","sugarContent":"15.05 g","fatContent":"3.83 g","saturatedFatContent":"1.35 g"},"notes":"This easy snack helps work fruit into a daily diet. Tortillas, with a variety of toppings, make great snack builders.\nSafety Tip: Allow pie to cool slightly before tasting -- the steam and sugar can burn.","contributor":"Kansas State University Cooperative Extension"},
{"slug":"polenta-pepper-and-cheese","source_url":"https://www.myplate.gov/recipes/polenta-pepper-and-cheese","name":"Polenta with Pepper and Cheese","description":"Enjoy this creamy and flavorful dish, packed with cheese, beans, peppers, and corn.","ingredients":[{"name":null,"items":["4 cups water","1 1/2 cups corn meal (or polenta, uncooked)","1 can whole kernel corn mixed with green and red peppers (11 ounces, drained)","2 cans green chiles (7 - 8 ounces)","1/2 teaspoon salt","1 tablespoon margarine or butter","6 ounces cheese, cheddar, reduced fat, shredded","1 can black or pinto beans, low-sodium (15 ounces, rinsed)"]},{"name":"Garnish","items":["cilantro sprigs (optional)","1 red bell pepper (cut into rings)"]}],"directions":[{"name":null,"steps":["In a medium sauce pan, bring the water to a boil. Gradually add the cornmeal or polenta. Reduce heat to low.","Continue stirring, add the corn, chilies, and the salt. Cook 6 to 8 minutes or until mixture thickens, stirring occasionally.","Gently stir in the margarine, cheese, and beans.","Remove from the heat and transfer to a serving dish.","Garnish with red bell pepper rings and cilantro."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared polenta","1/8 of recipe"],"calories":"246.79 kcal","carbohydrateContent":"36.26 g","cholesterolContent":"16.18 mg","fiberContent":"6.14 g","proteinContent":"12.15 g","sodiumContent":"627.45 mg","sugarContent":"0.95 g","fatContent":"6.70 g","saturatedFatContent":"3.10 g"},"notes":null,"contributor":"California Health Department, Los Angeles County\nEs Facil Campaign\nRecipe submitted by Gloria Vargas"},
{"slug":"popcorn-treats","source_url":"https://www.myplate.gov/recipes/popcorn-treats","name":"Popcorn Treats","description":"A great snack for adults and kids. A crunchy and sweet treat, enjoy this snack by yourself or double the recipe and share it with a group of friends.","ingredients":[{"name":null,"items":["2 tablespoons margarine (melted, or butter)","5 cups popcorn (popped)","3/4 cup raisins","1 cup shredded wheat (bite-size)","1 tablespoon sugar (brown or white)","1 1/4 teaspoons cinnamon"]}],"directions":[{"name":null,"steps":["Pop popcorn.","Mix popped corn, raisins, and cereal in a large bowl.","Mix sugar and cinnamon in small dish.","Drizzle melted margarine or butter over mixture.","Add sugar and cinnamon mixture.","Shake or stir until all ingredients are evenly distributed."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe (129g)","calories":"440.95 kcal","carbohydrateContent":"87.40 g","cholesterolContent":"0.14 mg","fiberContent":"9.38 g","proteinContent":"7.34 g","sodiumContent":"112.20 mg","sugarContent":"45.63 g","fatContent":"9.85 g","saturatedFatContent":"1.91 g"},"notes":null,"contributor":"Montana State University Extension\nNutrition Education Programs"},
{"slug":"popping-pomegranate-salsa","source_url":"https://www.myplate.gov/recipes/popping-pomegranate-salsa","name":"Popping Pomegranate Salsa","description":"This is the perfect dish for winter. It is bright and fresh and has a \"pop\" that makes every bite exciting. This recipe is great as an appetizer with whole w...","ingredients":[{"name":null,"items":["1 cup pomegranate seeds (approximately 1 pomegranate)","2 large pears, diced","2 tablespoons shallots, finely diced","1/4 cup cilantro, finely chopped","1 lime, juiced","1 ounce pomegranate juice (about 2 tablespoons)","1/4 teaspoon salt","1/8 teaspoon garlic powder","1/8 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Add all of the ingredients into a bowl and mix until well incorporated. Serve over chicken or fish or as a snack with whole wheat pita chips."]}],"yield":"3 Cups","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"76.80 kcal","carbohydrateContent":"19.99 g","cholesterolContent":"0.00 mg","fiberContent":"3.96 g","proteinContent":"0.64 g","sodiumContent":"202.00 mg","sugarContent":"12.04 g","fatContent":"0.21 g","saturatedFatContent":"0.03 g"},"notes":null,"contributor":"Created by Brighter Bites, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"pork-loin-roast-veggies","source_url":"https://www.myplate.gov/recipes/pork-loin-roast-veggies","name":"Pork Loin Roast with Veggies","description":"A perfect recipe for meat and potatoes fans. Enjoy this recipe with a fresh side salad and a piece of fruit for dessert.","ingredients":[{"name":null,"items":["2 cups onions, cut in wedges (about 1/2 pound or 2 medium )","2 cups potatoes, diced (about 12 ounces or medium)","2 cups baby carrots (or 3/4 pound regular carrots, sliced)","2 tablespoons vegetable oil (divided)","1 1/4 pounds pork loin","3 teaspoons brown sugar (1 Tablespoon)","1/2 teaspoon garlic powder","1/2 teaspoon black pepper","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","In a bowl mix veggies with 1 tablespoon oil, salt, and pepper.","Lay veggies around the edge of a 9x13 inch pan and put in oven.","Use a small bowl to make the rub. Mix the brown sugar, garlic, 1/2 teaspoon pepper, and 1/4 teaspoon salt in the bowl.","Sprinkle the rub over the loin. Press gently so the rub sticks to the roast. Wash your hands after handling the raw meat.","Heat the remaining 1 tablespoon vegetable oil in a large skillet over medium high heat. Add the loin. Brown the sides of meat. Turn after about 2 to 3 minutes per side.","Transfer the pork to the center of the pan with veggies. Bake for about 40 minutes. A meat thermometer should read 145 °F. Check the temperature after 30 minutes in the oven.","Remove from oven. Let set for 5 minutes. Slice and serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["Approx. 3 oz. meat and 1 cup veggies","1/6 of recipe"],"calories":"255.59 kcal","carbohydrateContent":"19.79 g","cholesterolContent":"53.32 mg","fiberContent":"2.95 g","proteinContent":"23.05 g","sodiumContent":"225.96 mg","sugarContent":"6.80 g","fatContent":"9.34 g","saturatedFatContent":"2.21 g"},"notes":"Wash and cut potatoes and onion into chunks about the same size as baby carrots.\nUse a meat thermometer. Cooked pork can be pink even when the meat has reached a safe temperature.\nFor safety and quality, allow meat to rest for at least three minutes before slicing.","contributor":"Spend Smart. Eat Smart.\nIowa State University Extension"},
{"slug":"pork-power-bowl","source_url":"https://www.myplate.gov/recipes/pork-power-bowl","name":"Pork Power Bowl","description":"The Pork Power Bowl combines savory, tender pork tenderloin with a colorful mix of vegetables and grains, creating a balanced and nutritious meal. This dish ...","ingredients":[{"name":null,"items":["2 medium purple or orange carrots, ribbon peeled","3 radishes, sliced","1/2 cup rice wine vinegar","1 clove garlic, minced","1/4 teaspoon salt (or ½ tsp. kosher salt)","1 teaspoon honey","1/2 cup warm water","1 pound pork tenderloin, cut into 1½ inch cubes","2 tablespoons lime juice","1 tablespoon olive oil","1 teaspoon paprika","1/2 teaspoon ground cumin","1 cup quinoa","2 cups low sodium vegetable stock","2 cups kale","1 15.5 oz can low sodium black beans, drained and rinsed","1 red bell pepper, cut into strips","1/2 avocado, peeled, seeded, sliced"]},{"name":"Dressing (optional)","items":["3 tablespoons olive oil","1 tablespoon lime juice","1/2 avocado, peeled, seeded, sliced","1/4 cup nonfat honey Greek yogurt","1 green onion, sliced","1 tablespoon chopped fresh cilantro, plus more for garnish"]}],"directions":[{"name":null,"steps":["In a large mason jar add the carrots, radish, rice wine vinegar, garlic, salt, honey and water, shake to combine. Let sit for 30 minutes.","In a medium bowl toss the pork, 2 Tbsp. lime juice, 1 Tbsp. olive oil, paprika and cumin. Cover and marinate for 15 minutes. Preheat the grill to medium-high heat.","Place the quinoa, stock and kale in a medium saucepan and bring to a boil. Reduce heat to low, cover and simmer for 15 minutes. Turn off the heat and let sit for 5 minutes. Season with salt and pepper.","Thread the pork onto skewers and grill over medium-high heat, turning frequently, until pork reaches an internal temperature of 145 degrees F. Let pork rest for 3 minutes.","Divide the quinoa between four bowls. Arrange the beans, peppers, avocado, carrots and radishes on top of the quinoa. Remove the pork from the skewers and place it on top of the bowls. Drizzle with dressing and garnish with additional cilantro, if desired."]},{"name":"Dressing (optional)","steps":["In a food processor, add yogurt, 3 Tbsp. olive oil, 1 Tbsp. lime juice, ½ an avocado, green onion and cilantro. Puree until smooth, season with salt and pepper. Thin dressing with cold water, if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"489.61 kcal","carbohydrateContent":"51.74 g","cholesterolContent":"63.99 mg","fiberContent":"14.17 g","proteinContent":"38.12 g","sodiumContent":"511.99 mg","sugarContent":"6.32 g","fatContent":"14.48 g","saturatedFatContent":"3.17 g"},"notes":"Dressing nutrition not included.","contributor":"Created by The National Pork Board, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"pot-roasted-beef","source_url":"https://www.myplate.gov/recipes/pot-roasted-beef","name":"Pot Roasted Beef","description":"This is a tender and satisfying roast beef dinner. Serve with a green salad and bread.","ingredients":[{"name":null,"items":["1 pound beef round roast, thawed","1/4 teaspoon salt","1/4 teaspoon black pepper","1/2 teaspoon vegetable oil","8 red potatoes, peeled and quartered (or 2 cans, low-sodium sliced potatoes, drained)","2 turnips, peeled and quartered (or 1 can low-sodium sweet potatoes, drained)","1/2 cup onion, chopped in 1-inch pieces","1/2 cup carrots, chopped in 1-inch pieces","1/2 cup low-sodium tomato juice"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Season the roast with salt and pepper.","In a large pan, brown the roast in the oil over medium to high heat for 10 to 12 minutes. Drain fat.","Use a large iron skillet or roasting pan. Put the roast in the middle of the pan. Add the potatoes, turnips, onions, and carrots around the roast.","Pour the tomato juice over the roast and vegetables.","Cover the pan with a lid or foil and bake for 1 hour or until potatoes are cooked.","If desired, cut roast into one inch chunks. Mix and serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup","calories":"276.98 kcal","carbohydrateContent":"41.01 g","cholesterolContent":"46.64 mg","fiberContent":"4.67 g","proteinContent":"21.21 g","sodiumContent":"186.69 mg","sugarContent":"5.31 g","fatContent":"3.13 g","saturatedFatContent":"1.12 g"},"notes":"Tip for cooking beef roast: The recommended safe minimum internal temperature for beef roast is 145 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"potato-beef-casserole","source_url":"https://www.myplate.gov/recipes/potato-beef-casserole","name":"Potato Beef Casserole","description":"A casserole perfect for meat and potato lovers. Savor this recipe with a fresh green salad on the side and piece of fruit for dessert.","ingredients":[{"name":null,"items":["1 onion (diced)","1/2 pound ground beef (85% lean)","5 potatoes (or 1 package hash browns)","1 can cream of mushroom soup, reduced sodium (10.75 ounces)","5 ounces water"]}],"directions":[{"name":null,"steps":["Peel onion and dice into 1/4-inch pieces.","Cook ground beef and onions in a skillet until the meat is browned. Drain of fat.","Add mushroom soup and 1/2 can water.","Use a brush to scrub potatoes under cold running water. Slice potatoes into 1/2-inch thick pieces and places in the bottom of a casserole dish.","Spread meat and soup mixture over potatoes.","Bake at 350 °F for 45 minutes until potatoes are tender and casserole is bubbly and browned."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"274.55 kcal","carbohydrateContent":"44.00 g","cholesterolContent":"27.32 mg","fiberContent":"4.68 g","proteinContent":"12.84 g","sodiumContent":"272.50 mg","sugarContent":"4.57 g","fatContent":"5.52 g","saturatedFatContent":"2.00 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"potato-black-bean-kale-skillet","source_url":"https://www.myplate.gov/recipes/potato-black-bean-kale-skillet","name":"Potato, Black Bean, & Kale Skillet","description":"A lively Southwestern skillet dish featuring diced potatoes, kale, and black beans, spiced up with garlic, chili, and cayenne, and topped with a dollop of no...","ingredients":[{"name":null,"items":["4 red potatoes","2 1/2 cups kale (curly Italian or other variety, approx. 6 oz.)","2 tablespoons olive oil","1 clove garlic, minced","1/4 cup chopped onion","1 teaspoon chili powder","1/4 teaspoon salt","1/8 teaspoon cayenne pepper","1 15 oz. can low sodium black beans, drained and rinsed","1/2 cup nonfat plain Greek yogurt"]}],"directions":[{"name":null,"steps":["Dice potatoes into 1/4 inch pieces.","Chop kale.","Heat oil, in large skillet over medium heat, Add garlic and onions; cook 2 to 3 minutes until just starting to brown.","Add diced potatoes, chili, salt, and pepper to skillet, cover with lid and cook 8 to 10 minutes, stirring occasionally.","Add chopped kale and black beans. Cook about 3 to 5 more minutes, stirring gently.","Serve with Greek yogurt."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"354.09 kcal","carbohydrateContent":"57.44 g","cholesterolContent":"1.53 mg","fiberContent":"12.37 g","proteinContent":"14.67 g","sodiumContent":"352.89 mg","sugarContent":"3.92 g","fatContent":"8.03 g","saturatedFatContent":"1.31 g"},"notes":"Serve with 8 ounce glass of non-fat milk, chicken breast, and orange slices.","contributor":"Produce for Better Health Foundation"},
{"slug":"potato-cakes","source_url":"https://www.myplate.gov/recipes/potato-cakes","name":"Potato Cakes","description":"Enjoy these potato cakes with fat-free sour cream or fat-free yogurt and chives.","ingredients":[{"name":null,"items":["2 cups potatoes (cold, mashed, made from instant potato flakes)","1/2 cup flour (all-purpose, unsifted)","2 tablespoons onion (finely chopped)","2 tablespoons vegetable oil"]}],"directions":[{"name":null,"steps":["Prepare potatoes according to package.","Put mashed potatoes into a bowl.","Add flour and onion. Mix well.","Pat potato mixture on a lightly floured board until 1/2 inch thick.","Cut with a 3-inch round cutter.","Place on a baking sheet, cover and refrigerate until just before cooking.","Heat oil in a frying pan or griddle.","Fry cakes over medium heat, turning to brown on both sides. Serve immediately."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 3\" pancake (96g)","calories":"130.33 kcal","carbohydrateContent":"21.00 g","cholesterolContent":"0.00 mg","fiberContent":"1.42 g","proteinContent":"2.38 g","sodiumContent":"13.50 mg","sugarContent":"0.72 g","fatContent":"4.16 g","saturatedFatContent":"0.59 g"},"notes":null,"contributor":"USDA Food and Nutrition Service\nFood Distribution Program on Indian Reservations"},
{"slug":"potato-nachos","source_url":"https://www.myplate.gov/recipes/potato-nachos","name":"Potato Nachos","description":"How can you make nachos better? Combine them with potatoes! Change up your toppings or trying new seasonings when cooking the ground turkey.","ingredients":[{"name":null,"items":["6 small red potatoes, skins on (1 pound)","2 teaspoons vegetable oil or cooking spray","8 ounces lean ground turkey (15% fat or less)","1/2 teaspoon chili powder","1/2 cup reduced-fat shredded cheddar cheese","1 cup shredded lettuce","1 tomato, diced","3/4 cup peeled and diced cucumber","1 tablespoon chopped cilantro","3/4 cup salsa"]}],"directions":[{"name":null,"steps":["Slice potatoes into small circles about 1/4 inch thick.","Lightly coat the potato slices with oil (or spray for 3 seconds with cooking spray).","Arrange slices on a baking sheet in a single layer. Bake in the oven at 450 °F for 25 to 30 minutes, depending on desired darkness.","Meanwhile, add ground turkey and chili powder to a skillet. Cook, stirring over medium heat (300 °F in an electric skillet) for 8 to10 minutes or until turkey browns.","Remove potatoes from the oven.","Transfer baked potatoes to an oven-safe dish. Top with turkey and sprinkle with cheese. Put back in the oven to melt the cheese, about 2 minutes.","Remove from oven and top with lettuce, tomato, cucumber, cilantro, and salsa."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"304.08 kcal","carbohydrateContent":"38.41 g","cholesterolContent":"42.25 mg","fiberContent":"4.58 g","proteinContent":"15.89 g","sodiumContent":"284.93 mg","sugarContent":"3.76 g","fatContent":"10.13 g","saturatedFatContent":"3.21 g"},"notes":"Try other toppings, such as guacamole or reduced-fat sour cream or plain yogurt.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"potato-salad-0","source_url":"https://www.myplate.gov/recipes/potato-salad-0","name":"Potato Salad","description":"A creamy yogurt, olive oil, and mustard sauce is tossed with tender potatoes and celery then topped with scallions and parsley to make up this favorite class...","ingredients":[{"name":null,"items":["15 new potatoes, quartered","2 tablespoons plain nonfat Greek yogurt","2 tablespoons vegetable oil","6 teaspoons yellow mustard (or Dijon mustard)","3 celery stalks, chopped","2 scallions, whites and greens, chopped","1/2 cup fresh parsley leaves, chopped"]}],"directions":[{"name":null,"steps":["Place potatoes in a pot and cover with cold water.","Bring to a boil over high heat and cook until potatoes are tender.","Drain and set aside to cool to room temperature.","While potatoes are cooling, mix the yogurt, olive oil, and mustard in a small bowl.","Add the yogurt mixture to the cooled potatoes and mix gently.","Stir in the celery, scallions, and parsley.","Serve right away or cover and refrigerate up to 2 days."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"292.08 kcal","carbohydrateContent":"51.16 g","cholesterolContent":"0.38 mg","fiberContent":"4.63 g","proteinContent":"6.08 g","sodiumContent":"125.54 mg","sugarContent":"4.82 g","fatContent":"7.63 g","saturatedFatContent":"1.08 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"potato-salad","source_url":"https://www.myplate.gov/recipes/potato-salad","name":"Potato Salad","description":"Perfect for your next cookout or picnic, this simple potato salad will be enjoyed by your friends and family.","ingredients":[{"name":null,"items":["4 potatoes (about 1 pound)","1 cup onion (diced)","1/2 cup celery (chopped)","1/2 cup mayonnaise, low-fat","1/4 cup sweet pickle relish"]}],"directions":[{"name":null,"steps":["Scrub the potatoes, and peel them.","Cut the potatoes into 1-inch cubes.","Put the potatoes into a saucepan. Cover with water.","Bring the potatoes to a boil on medium heat.","Let the potatoes simmer for 15 minutes until they’re soft.","Drain the hot water, and let the potatoes cool.","While the potatoes are cooling, peel and chop some onions until you have 1 cup of chopped onions.","Chop the celery until you have 1/2 cup of chopped celery.","Put the chopped onion and celery in a medium mixing bowl.","Add the mayonnaise and pickle relish. Stir together.","Add the cooled potatoes. Stir again.","Cover the bowl. Put in the fridge for at least 2 hours before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup potato salad","1/6 of recipe (140g)"],"calories":"181.57 kcal","carbohydrateContent":"32.25 g","cholesterolContent":"3.33 mg","fiberContent":"3.27 g","proteinContent":"3.29 g","sodiumContent":"273.53 mg","sugarContent":"6.70 g","fatContent":"4.86 g","saturatedFatContent":"0.77 g"},"notes":"Leave on the potato peels for more fiber and other nutrients.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"potato-skins-buffalo-chicken","source_url":"https://www.myplate.gov/recipes/potato-skins-buffalo-chicken","name":"Potato Skins with Buffalo Chicken","description":"This lively dish gives a nod to buffalo chicken wings but without extra fat and calories. Start with a foundation of nutritious potatoes -- which are natural...","ingredients":[{"name":null,"items":["12 ounces boneless, skinless chicken breast","1 cup water","4 medium russet potatoes (about 1 1/2 pounds)","9 teaspoons hot pepper sauce","1/4 cup non-fat milk","1/4 cup light sour cream","2 tablespoons margarine","1/4 cup crumbled blue cheese","2 green onions","2 medium tomatoes","4 celery stalks"]}],"directions":[{"name":null,"steps":["Center oven rack and preheat oven to 425 °F.","Place chicken in a sauté pan, add water, and cover. Simmer for 20 minutes and remove from pan; let cool slightly. When chicken is cool enough to handle, shred using two forks, one in each hand.","While chicken is simmering, wash and scrub potatoes with a clean vegetable brush under running water and slit each one lengthwise about 1-inch deep.","Place potatoes in a microwave-safe dish and microwave on high, uncovered, for about 10 minutes. Let cool slightly.","Slice each potato in half length-wise, scoop out potato, leaving a 1/4 inch shell. Mash potato together with hot pepper sauce, sour cream, margarine, and milk. Fold in blue cheese and shredded chicken.","Spoon mixture into potato skins slightly denting center (to hold fresh toppings after baking).","Place filled potato skins on a 9x13 inch baking sheet and bake about 15 to 20 minutes until tops are golden brown.","Dice tomatoes and green onions. Cut celery stalks into four inch sticks.","To serve, top potatoes with onions and tomatoes. Serve celery sticks on the side for scooping potato contents."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"413.85 kcal","carbohydrateContent":"42.83 g","cholesterolContent":"96.13 mg","fiberContent":"5.47 g","proteinContent":"34.16 g","sodiumContent":"336.01 mg","sugarContent":"5.26 g","fatContent":"11.82 g","saturatedFatContent":"4.18 g"},"notes":"Serving Suggestions: Serve with a glass of non-fat milk and apple slices.","contributor":"Produce for Better Health Foundation"},
{"slug":"potato-soup-0","source_url":"https://www.myplate.gov/recipes/potato-soup-0","name":"Potato Soup","description":"This rich-tasting and hearty potato soup is full of flavor and perfect for lunch or dinner.","ingredients":[{"name":null,"items":["1 cup onion, chopped","1 tablespoon garlic, finely chopped","1 tablespoon vegetable oil","1/4 pound chicken, cut up, and skin removed (thaw if frozen)","4 cups water","6 small red potatoes, chopped (or canned low-sodium sliced potatoes)","1/4 cup white rice, uncooked (or brown rice)","1/2 teaspoon chili powder (or paprika)","1 cup peas (or canned low-sodium green peas)","1/2 teaspoon cayenne or jalapeño chilies, diced (optional)","1/2 cup fresh parsley or cilantro, chopped (optional)"]}],"directions":[{"name":null,"steps":["In a large pot, brown onion and garlic in oil over medium to high heat for 5 minutes.","Add chicken to pot and brown for about 5 minutes.","Add water, potatoes, rice, and chili powder to pot.","Bring pot to a boil, and cook for 15 minutes.","Lower heat and cook for about 15 to 20 minutes. Stir pot every 10 minutes.","Add peas and cook for about 8 minutes. If using cayenne or jalapeño chilies, add that too. Mix well.","Remove pot from heat. If using parsley or cilantro, add that now.","Mix well and cover for 5 minutes. Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups of Potato Soup","calories":"231.02 kcal","carbohydrateContent":"40.16 g","cholesterolContent":"12.45 mg","fiberContent":"4.51 g","proteinContent":"9.57 g","sodiumContent":"72.24 mg","sugarContent":"4.51 g","fatContent":"3.81 g","saturatedFatContent":"0.71 g"},"notes":"Tip for cooking chicken: The recommended safe minimum internal temperature for chicken is 165 °F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"potato-soup","source_url":"https://www.myplate.gov/recipes/potato-soup","name":"Potato Soup","description":"Warm up a cold winter night with this cozy soup. Enjoy with dark green vegetables and broiled fish, meat, or tofu.","ingredients":[{"name":null,"items":["1/2 cup onion (chopped)","1/2 cup celery (chopped)","6 potatoes (diced)","2 tablespoons margarine","1/2 teaspoon salt","1/8 teaspoon black pepper","1 cup non-fat dry milk","3 cups water","2 tablespoons flour"]}],"directions":[{"name":null,"steps":["Peel and chop the onion.","Chop the celery.","Peel the potatoes, and cut them into small cubes.","Melt the margarine in a large saucepan on low heat.","Add the onion and celery. Cook for a few minutes.","Add the potatoes, salt, pepper, and 1 1/2 cups water.","Cook for 15 minutes until the potatoes are tender.","In a small bowl, stir together the dry milk and flour.","Add 1 1/2 cups water slowly, stirring as you add it.","Add the milk mix to the potatoes.","Cook until the soup is heated and slightly thickened.","Adjust the seasonings."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared soup","1/6 of recipe"],"calories":"243.43 kcal","carbohydrateContent":"45.90 g","cholesterolContent":"2.31 mg","fiberContent":"4.28 g","proteinContent":"8.92 g","sodiumContent":"320.03 mg","sugarContent":"8.65 g","fatContent":"3.16 g","saturatedFatContent":"0.69 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"potato-spinach-casserole","source_url":"https://www.myplate.gov/recipes/potato-spinach-casserole","name":"Potato Spinach Casserole","description":"This casserole would be wonderful for brunch or dinner. Top with fresh tomatoes or your favorite salsa!","ingredients":[{"name":null,"items":["1 2/3 cups frozen hash browns, country style (about 12 ounces, thawed)","1/2 cup green pepper (finely chopped, divided)","1/2 cup onion (finely chopped, divided)","1/2 teaspoon salt","1/2 teaspoon black pepper","1 can evaporated milk, nonfat (12 ounces)","6 egg whites from large eggs (3/4 cup)","1/2 cup cheese, reduced-fat sharp cheddar, shredded","1/2 cup cheese, reduced fat Monterey Jack, shredded","1 cup spinach (washed and chopped, fresh)","1/2 cup tomatoes (chopped, fresh)"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 °F.","Wash your hands and work area.","In large bowl, combine hash browns, green pepper, 1/4 cup onion, salt, and 1/4 teaspoon pepper.","Spray a 8x8 inch baking dish with non-stick cooking spray. Press potato mixture into bottom.","Bake until lightly browned around edges, 20 to 25 minutes.","In large bowl, stir together evaporated milk, egg whites, 1/4 teaspoon pepper, cheeses, spinach, remaining 1/4 cup onion, and tomatoes.","Reduce oven temperature to 350 °F.","Pour mixture over potato crust. Bake uncovered until center is set, 40 to 45 minutes.","Cover and let stand for 10 minutes. Cut into 6 pieces. Serve hot. Cover and refrigerate leftovers within 2 hours."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 1/2\" x 4\" piece","1/6 of recipe (216g)"],"calories":"234.71 kcal","carbohydrateContent":"23.63 g","cholesterolContent":"15.80 mg","fiberContent":"2.00 g","proteinContent":"15.20 g","sodiumContent":"640.16 mg","sugarContent":"8.90 g","fatContent":"9.28 g","saturatedFatContent":"3.01 g"},"notes":null,"contributor":"Fix it Fresh! Recipe Series\nKansas State University Research and Extension"},
{"slug":"potato-spinach-lasagna","source_url":"https://www.myplate.gov/recipes/potato-spinach-lasagna","name":"Potato Spinach Lasagna","description":"A unique and flavorful meat-free lasagna layered with sliced potatoes instead of noodles.","ingredients":[{"name":null,"items":["7 small red potatoes","1/2 cup onion, chopped","2 cloves garlic, minced","1 tablespoon olive oil","3 ounces fresh, baby spinach (about 3 1/2 cups)","3/4 cup non-fat ricotta cheese (or cottage cheese)","3/4 cup part-skim mozzarella cheese, shredded","2 tablespoons Parmesan cheese, grated","1 egg, beaten","1 1/2 cups no salt added pasta sauce (about 1/2 of 24-oz jar)"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F.","Bring water to a boil in large sauce pan.","Thinly slice potatoes, add to boiling water and cook 5 minutes, drain and rinse with cool water; drain again.","Heat olive oil in medium skillet, add onions and garlic; sauté about 2 to 3 minutes until just starting to brown.","Add spinach, sauté 1 more minute.","Remove from heat and drain off liquid.","In a medium bowl, mix cheese with egg until well blended.","Add layers to 8 inch square baking dish as follows, using about 1/4 of each: pasta sauce, potato slices, sautéed spinach mixture and cheese mixture.","Repeat layers until all ingredients are used.","Cover with foil.","Bake about 35 to 40 minutes.","Remove foil and bake an additional 10 minutes until cheese is melted."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"433.33 kcal","carbohydrateContent":"58.54 g","cholesterolContent":"81.60 mg","fiberContent":"6.41 g","proteinContent":"20.10 g","sodiumContent":"305.73 mg","sugarContent":"8.22 g","fatContent":"14.21 g","saturatedFatContent":"6.26 g"},"notes":"Serve with sparkling water, lemon slice, and a slice of rustic grain bread.","contributor":"Produce for Better Health Foundation"},
{"slug":"pretzel-shapes","source_url":"https://www.myplate.gov/recipes/pretzel-shapes","name":"Pretzel Shapes","description":"Have fun with the kids making pretzel shapes! A great snack for the whole family.","ingredients":[{"name":null,"items":["1 teaspoon dry yeast","1/2 cup water (warm)","1 teaspoon honey*","1 1/3 cups flour","1 teaspoon salt"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 °F.","In a small bowl, dissolve yeast in warm water, add honey and let set for a few minutes.","In a large mixing bowl, measure flour and salt.","Add yeast mixture to flour mixture and stir until it forms a smooth ball. Add a little more flour if the dough is sticky.","Knead dough on countertop or dough board until it forms a smooth ball. Add a little flour if the dough is sticky.","Divide dough into 12 pieces about the size of a walnut. Roll each ball into a snake and then twist to make a pretzel, letter, or other fun shape.","Place pretzels on a baking sheet lightly coated with cooking spray. Bake for 10 to 12 minutes until golden brown."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 pretzel","1/12 of recipe (25g)"],"calories":"53.20 kcal","carbohydrateContent":"11.17 g","cholesterolContent":"0.00 mg","fiberContent":"0.46 g","proteinContent":"1.57 g","sodiumContent":"197.59 mg","sugarContent":"0.49 g","fatContent":"0.16 g","saturatedFatContent":"0.03 g"},"notes":"*Children under the age of one should not consume honey.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"pulled-pork-sandwich-red-cabbage-and-carrot-slaw","source_url":"https://www.myplate.gov/recipes/pulled-pork-sandwich-red-cabbage-and-carrot-slaw","name":"Pulled Pork Sandwich with Red Cabbage and Carrot Slaw","description":"Pork shoulder is slow cooked and served on a whole wheat roll with tangy red cabbage and carrot slaw.","ingredients":[{"name":null,"items":["1 1/2 pound boneless pork roast (or half pork shoulder)","1 1/2 cups cider or white vinegar (or a combination of both)","1 teaspoon black pepper","1 teaspoon crushed red pepper flakes","1/2 teaspoon salt","8 whole wheat dinner rolls or slider buns"]},{"name":"For the Carrot Slaw","items":["1 head red cabbage, shredded","2 carrots, shredded","1/4 cup canola oil","1/4 cup vinegar","1/4 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":"Pulled Pork","steps":["Put everything in the slow cooker and turn the heat to medium. Cook, undisturbed, for 8 hours or until it is fork-tender (about 190 °F with a meat thermometer).","Remove the pork from the slow cooker but keep the liquid. While still hot, use two forks to shred the meat. Remove any fat found between the shreds.","Skim as much fat as possible from the liquid in the slow cooker. Add about 1 cup of the cooking liquid to the shredded pork."]},{"name":"Red Cabbage and Carrot Slaw","steps":["Put the shredded cabbage and carrots in a bowl.","Mix the canola oil, vinegar, salt, and pepper in a small bowl and stir well.","Add the dressing to the cabbage mixture and coat thoroughly.","Add 1/2 cup of pulled pork to each roll or bun and top with 1/2 cup cabbage and carrot slaw. Serve right away."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"310.78 kcal","carbohydrateContent":"29.80 g","cholesterolContent":"34.54 mg","fiberContent":"4.48 g","proteinContent":"17.01 g","sodiumContent":"508.08 mg","sugarContent":"5.65 g","fatContent":"13.20 g","saturatedFatContent":"2.17 g"},"notes":"1 bag coleslaw mix can be used instead of red cabbage.\nLeftovers can be served with brown rice or wrapped in a whole wheat tortilla.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"pumpkin-and-bean-soup","source_url":"https://www.myplate.gov/recipes/pumpkin-and-bean-soup","name":"Pumpkin and Bean Soup","description":"Pumpkin and bean lovers alike will savor this fast and flavorful soup that is packed with fiber.","ingredients":[{"name":null,"items":["1 can white beans","1 onion (small, finely chopped)","1 cup water","1 can pumpkin (15 ounce)","1 1/2 cups 100% apple juice","1/2 teaspoon cinnamon","1/8 teaspoon nutmeg, allspice, or ginger","1/2 teaspoon black pepper","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Blend white beans, onion, and water with a potato masher or blender till smooth.","In a large pot, add the pumpkin, juice, cinnamon, nutmeg, black pepper, and salt. Stir.","Add the blended bean mix to the pot.","Cook over low heat for 15 to 20 minutes, until warmed through."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared soup","1/6 of recipe (255g)"],"calories":"188.05 kcal","carbohydrateContent":"38.00 g","cholesterolContent":"0.00 mg","fiberContent":"8.05 g","proteinContent":"9.05 g","sodiumContent":"360.34 mg","sugarContent":"11.17 g","fatContent":"0.82 g","saturatedFatContent":"0.28 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"pumpkin-angel-food-cake","source_url":"https://www.myplate.gov/recipes/pumpkin-angel-food-cake","name":"Pumpkin Angel Food Cake","description":"Wonderful for holidays or any time that you want the light airy texture of angel food cake and the earthy spicy flavor of pumpkin.","ingredients":[{"name":null,"items":["12 large egg whites (about 1 1/2 cups)","1 teaspoon cream of tartar","1 1/2 cups sugar","1 teaspoon vanilla extract","1/4 teaspoon salt","1 cup flour, sifted","1 tablespoon flour","1 teaspoon pumpkin pie spice","3/4 cup canned pumpkin","1 cup cold water"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a large mixing bowl, beat the egg whites until they are foamy.","Add the cream of tartar and beat until stiff, but not dry. Gradually beat in the sugar","Add the vanilla and salt and then gently fold in the sifted flour (1 cup).","Add the remaining ingredients (1 Tablespoon of flour - water) and beat with an electric mixer on low speed for 30 seconds. Then, beat on medium speed for 1 minute.","Pour into an ungreased 10-inch angel food cake pan.","Bake 37 to 47 minutes or until golden brown and cracks are dry.","Remove from oven and immediately turn pan upside down until cooled."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/12 of recipe","calories":"165.04 kcal","carbohydrateContent":"35.66 g","cholesterolContent":"0.00 mg","fiberContent":"0.76 g","proteinContent":"4.85 g","sodiumContent":"106.23 mg","sugarContent":"25.77 g","fatContent":"0.25 g","saturatedFatContent":"0.05 g"},"notes":"Angel food cake pan can be turned upside down onto a glass bottle. Suggest serving with whipped topping.","contributor":"Ohio State University Cooperative Extension"},
{"slug":"pumpkin-bread","source_url":"https://www.myplate.gov/recipes/pumpkin-bread","name":"Pumpkin Bread","description":"Sweet and spicy, this pumpkin bread makes a wonderful holiday treat.","ingredients":[{"name":null,"items":["1 can pumpkin (15 ounce)","1 cup sugar","1/4 cup vegetable oil","1 cup yogurt, low-fat plain","1 1/2 cups flour (all purpose)","1 1/2 cups whole wheat flour","2 teaspoons baking powder","2 teaspoons baking soda","2 teaspoons cinnamon","1/2 teaspoon salt","1 cup raisins"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a large mixing bowl, beat together pumpkin, sugar, oil, and yogurt.","In a medium bowl, combine the flours, baking powder, soda, cinnamon, and salt. Add to pumpkin mixture, stirring until just moistened.","Stir in raisins.","Pour into 2 greased 9x5x3 inch loaf pans and bake for about 1 hour.","Cool on a wire rack for 10 minutes; remove from pan and cool completely."]}],"yield":"32 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/32 of recipe (46g)"],"calories":"106.11 kcal","carbohydrateContent":"20.53 g","cholesterolContent":"0.46 mg","fiberContent":"1.46 g","proteinContent":"2.07 g","sodiumContent":"153.65 mg","sugarContent":"10.52 g","fatContent":"2.14 g","saturatedFatContent":"0.37 g"},"notes":"Substituting yogurt for eggs and oil reduces fat and cholesterol.","contributor":"Food for Fitness and Fun\nIowa State University Extension"},
{"slug":"pumpkin-cheese-pie","source_url":"https://www.myplate.gov/recipes/pumpkin-cheese-pie","name":"Pumpkin Cheese Pie","description":"A great option for cheesecake lovers. Less fat and saturated fat than a standard cheesecake but all of the flavor.","ingredients":[{"name":null,"items":["8 ounces cream cheese, reduced fat","8 ounces cream cheese, non-fat","2 eggs","4 egg whites","1 1/4 cups sugar","2 cans pumpkin (29 ounces)","1 teaspoon ginger","1 tablespoon cinnamon","2 graham cracker pie crusts (9 inch)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Place the cream cheeses, eggs, and sugar in a large mixing bowl. Mix at medium speed until creamed. Add the remaining ingredients and mix at medium speed until ingredients are well mixed.","Spoon the mixture evenly in each pie crust and place both in the oven for approximately 50 minutes until pies look firm in the middle."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/16 of recipe (141g)"],"calories":"154.29 kcal","carbohydrateContent":"24.78 g","cholesterolContent":"35.04 mg","fiberContent":"1.86 g","proteinContent":"5.76 g","sodiumContent":"189.75 mg","sugarContent":"19.60 g","fatContent":"3.91 g","saturatedFatContent":"1.82 g"},"notes":null,"contributor":"California Health Department, Los Angeles County\nEs Facil Campaign\nRecipe submitted by Maria Pallares"},
{"slug":"pumpkin-chili","source_url":"https://www.myplate.gov/recipes/pumpkin-chili","name":"Pumpkin Chili","description":"Canned or puréed pumpkin adds a hearty and nutritious flavor to this savory chili recipe.","ingredients":[{"name":null,"items":["2 teaspoons olive oil","1 small yellow onion (chopped)","1 green bell pepper (cored, seeded and chopped )","2 jalapeño peppers (seeded and finely chopped)","2 cloves garlic (finely chopped or 1/2 teaspoon garlic powder )","1 pound ground turkey","1 can diced tomatoes with juice, low-sodium","1 can pumpkin purée","1 cup water","1 teaspoon cumin, ground","1 tablespoon chili powder","salt and pepper (to taste, optional)","1 can kidney beans, low-sodium (or other beans if desired)"]}],"directions":[{"name":null,"steps":["Heat oil in a large pot over medium high heat.","Add onion, bell pepper, jalapenos and garlic and cook, stirring frequently until tender, about 5 minutes.","Add turkey and cook until browned.","Add tomatoes, pumpkin, water, chili powder, cumin, salt, and pepper and bring to a boil.","Reduce heat to medium low then add beans.","Cover and simmer, stirring occasionally, for 30 minutes more.","Ladle chili into bowls and serve."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Cup","calories":"201.52 kcal","carbohydrateContent":"18.07 g","cholesterolContent":"42.07 mg","fiberContent":"6.40 g","proteinContent":"14.45 g","sodiumContent":"137.64 mg","sugarContent":"5.59 g","fatContent":"8.85 g","saturatedFatContent":"2.21 g"},"notes":null,"contributor":"Bronson Wellness Center"},
{"slug":"pumpkin-chocolate-muffins","source_url":"https://www.myplate.gov/recipes/pumpkin-chocolate-muffins","name":"Pumpkin Chocolate Muffins","description":"This dense, moist chocolate muffin contains no fats or oils. The secret ingredient is canned (or puréed) pumpkin that binds the ingredients together for a t...","ingredients":[{"name":null,"items":["2 cups all-purpose flour","3/4 cup sugar","1 teaspoon baking powder","1/2 teaspoon baking soda","1/2 cup cocoa powder","1 can pumpkin","1 cup water","1/2 cup chocolate chips"]}],"directions":[{"name":null,"steps":["Whisk all the dry ingredients together. Add pumpkin and water.","Fold the wet ingredients into the dry ingredients until just combined. Fold in chocolate chips.","Place batter into 24 prepared muffin tins and bake at 350 °F for 10 to 12 minutes."]}],"yield":"24 Muffins","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/24 of recipe"],"calories":"95.41 kcal","carbohydrateContent":"19.62 g","cholesterolContent":"0.00 mg","fiberContent":"1.69 g","proteinContent":"1.79 g","sodiumContent":"48.96 mg","sugarContent":"9.43 g","fatContent":"1.81 g","saturatedFatContent":"1.01 g"},"notes":null,"contributor":"With Veggies, More Matters!\nMichigan State University Extension - Midland County"},
{"slug":"pumpkin-cookies","source_url":"https://www.myplate.gov/recipes/pumpkin-cookies","name":"Pumpkin Cookies","description":"Bake these cookies the night before and enjoy a delicious treat on busy mornings.","ingredients":[{"name":null,"items":["1 3/4 cups pumpkin (puréed, cooked)","1 1/2 cups brown sugar","2 eggs","1/2 cup vegetable oil","1 1/2 cups flour","1 1/4 cups whole wheat flour","1 tablespoon baking powder","2 teaspoons cinnamon","1 teaspoon nutmeg","1/2 teaspoon salt","1/4 teaspoon ground ginger","1 cup raisins","1 cup walnuts (chopped)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Mix pumpkin, brown sugar, eggs, and oil thoroughly.","Blend dry ingredients and add to pumpkin mixture.","Add raisins and nuts.","Drop by teaspoonfuls on greased cookie sheet.","Bake 10 to 12 minutes until golden brown."]}],"yield":"48 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cookie","calories":"104.99 kcal","carbohydrateContent":"15.90 g","cholesterolContent":"8.56 mg","fiberContent":"1.09 g","proteinContent":"1.68 g","sodiumContent":"61.20 mg","sugarContent":"9.23 g","fatContent":"4.34 g","saturatedFatContent":"0.59 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"pumpkin-mac-cheese-one","source_url":"https://www.myplate.gov/recipes/pumpkin-mac-cheese-one","name":"Pumpkin Mac & Cheese for One","description":"To make this dish even faster, use leftover cooked pasta, preferably whole grain, to make this meal in under 5 minutes.","ingredients":[{"name":null,"items":["3/4 cup cooked pasta (in any shape)","1 1/2 tablespoons cheddar cheese soup (from can)","1/8 cup pumpkin purée","1 1/2 tablespoons milk, 1%","1 tablespoon cheese, low-fat","1 teaspoon deli mustard"]}],"directions":[{"name":null,"steps":["Stir the \"wet\" ingredients (soup, pumpkin purée, milk, and mustard), and heat in microwave for 45 to 60 seconds; stir again until creamy.","Add cooked pasta to cream and sprinkle cheese on top. Heat another 30 to 45 seconds or until cheese melts."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 recipe","calories":"228.04 kcal","carbohydrateContent":"38.55 g","cholesterolContent":"7.92 mg","fiberContent":"3.30 g","proteinContent":"9.84 g","sodiumContent":"197.95 mg","sugarContent":"3.88 g","fatContent":"3.60 g","saturatedFatContent":"1.71 g"},"notes":"Low-fat cheddar cheese used in nutrition analysis and for costing purposes.\nWhy add pumpkin? Adding pumpkin mixture in addition to the cheese soup lowers the total calories and boosts nutritional fiber and vitamin A.","contributor":"CSAAC (Community Services for Autistic Adults and Children)"},
{"slug":"pumpkin-pudding","source_url":"https://www.myplate.gov/recipes/pumpkin-pudding","name":"Pumpkin Pudding","description":"No cooking required for this tasty pumpkin pudding. Kids can help prepare with supervision.","ingredients":[{"name":null,"items":["1 can pumpkin, 15 ounces (or 2 cups cooked mashed squash such as Hubbard)","2 teaspoons pumpkin pie spice (or 1 teaspoon cinnamon, 1/2 teaspoon ginger, 1/4 teaspoon nutmeg and 1/4 teaspoon cloves)","1/8 teaspoon salt","1 1/2 cups milk (1% low-fat)","1 vanilla pudding, instant, 3.5 ounce (small box)"]}],"directions":[{"name":null,"steps":["In a large bowl mix pumpkin, salt and pumpkin spice together.","Slowly stir in milk and mix well. Add instant pudding mix and stir for 2 minutes until it thickens. Refrigerate until serving time."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup (150g)","calories":"114.47 kcal","carbohydrateContent":"24.62 g","cholesterolContent":"3.05 mg","fiberContent":"2.14 g","proteinContent":"2.87 g","sodiumContent":"309.78 mg","sugarContent":"20.74 g","fatContent":"0.95 g","saturatedFatContent":"0.56 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"pumpkin-ricotta-stuffed-shells","source_url":"https://www.myplate.gov/recipes/pumpkin-ricotta-stuffed-shells","name":"Pumpkin Ricotta Stuffed Shells","description":"Welcome the flavors of fall with these pumpkin ricotta stuffed shells! Rich in vitamins, minerals, and antioxidants, pumpkin adds a nutritious twist to tradi...","ingredients":[{"name":null,"items":["6 ounces jumbo pasta shells (about 12 jumbo pasta shells)","1 1/4 cups ricotta cheese, part skim","3/4 cup pumpkin","1/2 teaspoon garlic powder (or 2 cloves garlic, minced)","2 tablespoons basil","1/4 teaspoon sage, dried","1/2 teaspoon salt","1/2 teaspoon black pepper","1/2 cup grated parmesan cheese, divided","1 cup spaghetti sauce (low sodium)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Cook pasta shells according to package directions. Drain and place each on a baking sheet to cool.","In a medium bowl, stir together ricotta, pumpkin, spices, and all but 1 tablespoon of the cheese. Reserve the 1 tablespoon cheese for topping.","Spread pasta sauce in the bottom of a baking dish that holds all the shells in a single layer. Fill each shell with about 3 tablespoons of pumpkin mixture and place shells close together on top of the sauce.","Cover pan with foil and bake for 30 minutes. Remove foil, sprinkle with remaining cheese, and bake for 15 minutes more."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Stuffed Shell","calories":"126.93 kcal","carbohydrateContent":"16.68 g","cholesterolContent":"11.57 mg","fiberContent":"1.52 g","proteinContent":"6.93 g","sodiumContent":"200.25 mg","sugarContent":"1.55 g","fatContent":"3.68 g","saturatedFatContent":"2.02 g"},"notes":"Freeze unused pumpkin and add to soup, chili or pancake recipes.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"pumpkin-soup-0","source_url":"https://www.myplate.gov/recipes/pumpkin-soup-0","name":"Pumpkin Soup","description":"Canned pumpkin tastes good and is easy to use. The blend of ingredients in this soup gives it a hint of sweetness.","ingredients":[{"name":null,"items":["3 cups water","1/4 pound beef round roast, sliced thinly (thaw if frozen)","2 cans pumpkin without salt (about 30 ounces)","2 tablespoons maple syrup (or brown sugar)","1/4 teaspoon black pepper","1/2 teaspoon cinnamon (optional)","1/4 cup onions, diced"]}],"directions":[{"name":null,"steps":["In a medium-sized pot, bring water to a boil.","Add beef roast to boiling water. Boil for 5 to 10 minutes.","Add pumpkin, maple syrup, and pepper to pot. If using cinnamon, add that too. Mix well.","Lower heat and cook for about 10 minutes.","Put 2 teaspoons of onion on top of each bowl of soup. Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"91.61 kcal","carbohydrateContent":"16.74 g","cholesterolContent":"11.66 mg","fiberContent":"4.36 g","proteinContent":"5.71 g","sodiumContent":"23.06 mg","sugarContent":"9.10 g","fatContent":"1.00 g","saturatedFatContent":"0.46 g"},"notes":"Tip for cooking beef roast: The recommended safe minimum internal temperature for beef roast is 145 °F, as measured with a food thermometer.\nSee how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"pumpkin-soup","source_url":"https://www.myplate.gov/recipes/pumpkin-soup","name":"Pumpkin Soup","description":"Get pumped for this pumpkin soup. This soup pairs well with a spinach salad topped with a scoop of tuna or egg salad.","ingredients":[{"name":null,"items":["1 can white beans (15 ounce, rinsed and drained)","1 onion (small, or 2 teaspoons onion powder)","1 cup water","1 can pumpkin (15 ounces, plain)","1 can vegetable or chicken broth, low-sodium (14.5 ounces)","1/2 teaspoon thyme (or tarragon)","salt and pepper (optional, to taste)"]}],"directions":[{"name":null,"steps":["Blend white beans, onion, and water.","In a soup pot, mix bean puree with pumpkin, broth, and spices.","Cover and cook over low heat about 15 to 20 minutes until warmed through."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups prepared soup","1/4 of recipe (392g)"],"calories":"238.07 kcal","carbohydrateContent":"46.98 g","cholesterolContent":"0.00 mg","fiberContent":"11.69 g","proteinContent":"13.46 g","sodiumContent":"441.76 mg","sugarContent":"7.79 g","fatContent":"0.97 g","saturatedFatContent":"0.38 g"},"notes":null,"contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"pupusas-revueltas","source_url":"https://www.myplate.gov/recipes/pupusas-revueltas","name":"Pupusas Revueltas","description":"This recipe is lower in saturated fat than traditional pupusas, but are still loaded with flavor! Enjoy these pupusas with curtido (cabbage salad).","ingredients":[{"name":null,"items":["16 ounces chicken breast, ground","1 tablespoon vegetable oil","1/2 pound cheese, part-skim mozzarella, grated","1/2 onion (small, finely diced)","1 garlic clove (minced)","1 green pepper (medium, seeded and minced)","1 tomato (small, finely chopped)","1/2 teaspoon salt","5 cups masa harina (corn flour, instant)","6 cups water"]}],"directions":[{"name":null,"steps":["In a non-stick skillet over low heat, sauté chicken in oil until chicken turns white. Constantly stir the chicken to keep it from sticking.","Add onion, garlic, green pepper, and tomato. Cook until chicken mixture is cooked through. Remove skillet from stove and let mixture cool in the refrigerator.","While the chicken mixture is cooling, place the flour in a large mixing bowl and stir in enough water to make a stiff tortilla-like dough.","When the chicken mixture has cooled, mix in the cheese.","Divide the dough into 24 portions. With your hands, roll the dough into balls and flatten each ball into a 1/2 ich thick circle. Put a spoonful of the chicken mixture in the middle of each circle of dough and bring the edges to the center. Flatten the ball of dough again until it is 1/2 inch thick.","In a very hot, iron skillet, cook the pupusas on each side until golden brown.","Serve hot."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 pupusas","1/12 of recipe (250g)"],"calories":"224.87 kcal","carbohydrateContent":"23.13 g","cholesterolContent":"36.83 mg","fiberContent":"2.00 g","proteinContent":"14.24 g","sodiumContent":"267.99 mg","sugarContent":"1.57 g","fatContent":"8.80 g","saturatedFatContent":"3.23 g"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"purple-cow","source_url":"https://www.myplate.gov/recipes/purple-cow","name":"Purple Cow","description":"Kids are going to love this purple treat, which is perfect for a hot summer day. They will never know that it is high in vitamin C!","ingredients":[{"name":null,"items":["6 us fluid ounces grape juice (frozen)","1 cup water (cold)","1/3 cup milk (nonfat, dry)","1 teaspoon vanilla","1 cup ice (or more)"]}],"directions":[{"name":null,"steps":["Place all ingredients in blender or food processor.","Secure lid and blend until smooth. Serve immediately."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":"8 ounces (317g)","calories":"72.03 kcal","carbohydrateContent":"13.80 g","cholesterolContent":"1.50 mg","fiberContent":"0.12 g","proteinContent":"2.82 g","sodiumContent":"50.26 mg","sugarContent":"12.87 g","fatContent":"0.23 g","saturatedFatContent":"0.06 g"},"notes":"Substitute 1 cup milk and 1 cup water for 2 cups water and 1/3 cup nonfat dry milk","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"quesadilla-con-huevos","source_url":"https://www.myplate.gov/recipes/quesadilla-con-huevos","name":"Quesadilla con Huevos","description":"Tortillas, eggs, cheese, and salsa can be enjoyed at any meal. Enjoy this main dish with a salad and a piece of fruit for a well balanced lunch.","ingredients":[{"name":null,"items":["1/2 cup cheddar or colby jack cheese (grated - cojack)","2 eggs (scrambled)","4 flour tortillas (6 to 8 inch)","salsa (4 tablespoons, optional)"]}],"directions":[{"name":null,"steps":["Put 2 tablespoons cheese and 1/4 of the scrambled eggs on each tortilla.","Heat 2 quesadillas at a time in microwave on high for 30 to 45 seconds or until cheese melts.","Top with salsa and fold tortilla in half to serve.","Add parsley if desired."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 Quesadilla con Huevos","1/4 of the recipe (85g)"],"calories":"231.22 kcal","carbohydrateContent":"22.81 g","cholesterolContent":"116.88 mg","fiberContent":"1.58 g","proteinContent":"10.08 g","sodiumContent":"455.83 mg","sugarContent":"1.77 g","fatContent":"10.89 g","saturatedFatContent":"4.83 g"},"notes":"Kids can make these as plain as they like or can add ingredients such as peppers, tomatoes, mushrooms, or onions. Quesadillas make a great breakfast or lunch that''s easy and quick. Instead of using a microwave, you can heat the tortillas on a skillet or griddle until the cheese melts.\nSafety Tips: The melted cheese is hot, so wait a minute before eating. Use a knife or pizza wheel to cut the quesadilla into wedges for serving.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"quick-and-easy-baked-potato-salad","source_url":"https://www.myplate.gov/recipes/quick-and-easy-baked-potato-salad","name":"Quick and Easy Baked Potato Salad","description":"If you love baked potatoes but associate them primarily with the colder winter months, this Baked Potato Salad will fill that void come summer. With reduced-...","ingredients":[{"name":null,"items":["1 1/2 pounds red potatoes","1 cup non-fat plain yogurt","1/3 cup minced onion","1/2 cup shredded, reduced-fat cheddar cheese","4 tablespoons snipped fresh chives","3 tablespoons real bacon bits or pieces","1/4 teaspoon salt","freshly ground pepper to taste","chopped fresh parsley (optional)"]}],"directions":[{"name":null,"steps":["Place whole potatoes (do not poke holes) into microwave-safe dish.","Cover dish. (If covering dish with plastic wrap, poke small holes in plastic.)","Microwave on high for 10 to 12 minutes depending on strength of microwave.","Use oven mitts or a towel to remove dish from microwave. Carefully remove cover from dish due to steam build up and let cool.","Cut potatoes into bite-sized pieces and place in a large bowl with remaining ingredients. Stir and mix well."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"222.27 kcal","carbohydrateContent":"33.38 g","cholesterolContent":"15.67 mg","fiberContent":"2.78 g","proteinContent":"12.03 g","sodiumContent":"363.17 mg","sugarContent":"7.53 g","fatContent":"4.55 g","saturatedFatContent":"2.37 g"},"notes":"This salad may be served right away, but is best if refrigerated for at least one hour to allow flavors to blend.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"quick-and-easy-pizza","source_url":"https://www.myplate.gov/recipes/quick-and-easy-pizza","name":"Quick and Easy Pizza","description":"This recipe uses a traditional pizza dough recipe with yeast, but only needs 15 minutes for the dough to rise. Once you try this fresh, homemade pizza, you m...","ingredients":[{"name":null,"items":["2 cups all-purpose flour (divided in half)","1 tablespoon instant yeast","1 tablespoon sugar","2/3 cup warm water + 2 tablespoons (110 to 115 °F)","2 sprays of nonstick cooking spray","1 cup marinara sauce","6 ounces part-skim mozzarella cheese, shredded (1 1/2 cups)","Toppings of your choice"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F.","Collect, shred, and measure all ingredients before starting to prepare the recipe.","In a medium bowl, mix 1 cup flour, yeast, sugar, and water with a spoon.","Gradually stir in the other cup of flour until the mixture forms a ball.","Dust a cutting board or clean countertop surface with flour. Put the ball of dough on the surface, then use your clean hands to knead the dough on the surface for about 5 minutes.","Spray a bowl with nonstick cooking spray. Put the dough in the bowl, and cover it with a clean dishtowel. Put the bowl on the oven while it is preheating (but not on a burner that is turned on), and let it sit for 10 to 15 minutes (preheating the oven will cause the stovetop to be slightly warm and will help the dough rise).","Spray a 12-inch x 16-inch baking sheet with nonstick cooking spray. Spread the dough into an even layer on the baking sheet. Spread the dough into an even layer on the baking sheet. For a thicker crust, use a smaller baking sheet.","Add a thin layer of the Easy Marinara Sauce from the Eating Smart, Being Active Let''s Cook! Cookbook, leaving a 1/2 inch crust on all edges.","Add the shredded cheese and pizza toppings. Be careful not to put too many toppings on the pizza, or it will be soggy.","Bake for approximately 15 minutes until the crust is brown and the cheese melts and is slightly browned in spots.","Refrigerate leftovers within 2 hours. Eat within 3 to 5 days."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of pizza","calories":"409.99 kcal","carbohydrateContent":"59.19 g","cholesterolContent":"28.94 mg","fiberContent":"3.66 g","proteinContent":"18.66 g","sodiumContent":"574.11 mg","sugarContent":"7.63 g","fatContent":"10.61 g","saturatedFatContent":"5.22 g"},"notes":"*Make it whole grain! To make whole grain pizza crust, substitute 1 cup of 100% whole wheat flour for 1 cup of the all-purpose flour. Increase the water to 1 cup, and increase the baking time to 20 minutes.","contributor":"Eating Smart, Being Active\nColorado State University Extension"},
{"slug":"quick-and-easy-potato-casserole","source_url":"https://www.myplate.gov/recipes/quick-and-easy-potato-casserole","name":"Quick and Easy Potato Casserole","description":"This potato dish packs lots of flavor with reduced-fat cheddar cheese, onions, Italian herb seasoning, and Dijon mustard.","ingredients":[{"name":null,"items":["3 1/2 Yukon Gold potatoes, very thinly sliced","1 cup onion, quartered and thinly sliced","1 cup shredded reduced-fat sharp cheddar cheese","1/2 teaspoon Italian herb seasoning","1/2 cup stock or low-sodium broth","1 1/2 teaspoons Dijon mustard","1/2 teaspoon garlic salt","nonstick cooking spray"]}],"directions":[{"name":null,"steps":["Spray an 8-inch microwave-safe baking dish with nonstick cooking spray. Place 1/3 of the potatoes and 1/2 of the onions on the bottom of the dish and sprinkle with 1/3 the cheese and 1/2 the herbs.","Repeat layers, then top with the last 1/3 of the potatoes, layering potatoes so that there is a solid layer of potatoes with no gaps; sprinkle with remaining cheese.","Stir together stock, Dijon mustard, and garlic salt, and pour over the potatoes.","Cover with plastic wrap and microwave on HIGH until internal temperature registers 165 °F on a food thermometer, about 20 minutes.","Use oven mitts or a towel to remove dish from microwave; carefully remove cover due to steam build-up and serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"168.29 kcal","carbohydrateContent":"24.54 g","cholesterolContent":"14.31 mg","fiberContent":"2.73 g","proteinContent":"8.42 g","sodiumContent":"229.51 mg","sugarContent":"2.42 g","fatContent":"4.16 g","saturatedFatContent":"2.45 g"},"notes":"Use regular salt and a dash of garlic powder in place of garlic salt if you like.\nTo make a Tex-Mex potato casserole, omit Dijon mustard and garlic salt. Layer potatoes with 1 (4 ounce) can diced green chilies and 1/2 cup canned black beans. Use reduced fat cheddar or Mexican cheese blend. Add 1 teaspoon chili powder, 1 teaspoon dried cilantro, and 1/2 teaspoon ground cumin to broth. Cook as directed above. Delicious served with avocado wedges.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"quick-and-healthy-black-eyed-peas","source_url":"https://www.myplate.gov/recipes/quick-and-healthy-black-eyed-peas","name":"Quick and Healthy Black-Eyed Peas","description":"Tasty turkey bacon and frozen black-eyed peas are the star ingredients in this recipe. Add a little chipotle pepper and sauce, cayenne pepper, or jalapeños ...","ingredients":[{"name":null,"items":["4 slices turkey bacon (chopped)","2 cups black-eyed peas, frozen (about 2 pounds)","2 cups water","1/4 teaspoon black pepper","1 tablespoon sugar"]}],"directions":[{"name":null,"steps":["Over medium high heat cook bacon for 3 to 4 minutes.","Add the rest of the ingredients and bring to a boil.","Reduce heat to simmer and allow to cook until the peas are tender, about 30 minutes.","Serve hot."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"110.61"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"quick-black-bean-salad","source_url":"https://www.myplate.gov/recipes/quick-black-bean-salad","name":"Quick Black Bean Salad","description":"This simple corn and bean salad can be made in minutes. Enjoy it on top of eggs, on whole grain tortilla, or on pita chips.","ingredients":[{"name":null,"items":["1 can black beans, low-sodium (15.5 ounces)","1 1/2 10-ounce packages frozen corn","1/2 cup salsa"]}],"directions":[{"name":null,"steps":["Leave frozen corn in the fridge overnight to defrost. If you forget to do this ahead of time, defrost it in the microwave.","Drain and rinse the black beans.","Combine all ingredients together and serve as a side dish."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"127.62 kcal","carbohydrateContent":"26.51 g","cholesterolContent":"0.00 mg","fiberContent":"6.98 g","proteinContent":"6.36 g","sodiumContent":"190.55 mg","sugarContent":"2.77 g","fatContent":"0.72 g","saturatedFatContent":"0.13 g"},"notes":null,"contributor":null},
{"slug":"quick-black-eyed-peas","source_url":"https://www.myplate.gov/recipes/quick-black-eyed-peas","name":"Quick Black-Eyed Peas","description":"Tasty turkey bacon and frozen black-eyed peas are the star ingredients in this recipe. Add a little chipotle pepper and sauce, cayenne pepper, or jalapeños ...","ingredients":[{"name":null,"items":["4 slices turkey bacon (chopped)","2 cups black-eyed peas, frozen (about 2 pounds)","1/2 cup onions (chopped)","2 cups water","1/4 teaspoon black pepper","1 tablespoon sugar"]}],"directions":[{"name":null,"steps":["Over medium high heat cook bacon and onions for 3 to 4 minutes.","Add the rest of the ingredients and bring to a boil.","Reduce heat to simmer and allow to cook until the peas are tender, about 30 minutes.","Serve hot."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups","1/6 of recipe (239g)"],"calories":"115.73 kcal","carbohydrateContent":"17.16 g","cholesterolContent":"11.22 mg","fiberContent":"3.88 g","proteinContent":"7.13 g","sodiumContent":"154.75 mg","sugarContent":"5.48 g","fatContent":"2.30 g","saturatedFatContent":"0.62 g"},"notes":null,"contributor":"Adapted from Quick and Healthy Black-Eyed Peas\nCooking Demo II\nFood and Health Communications, Inc."},
{"slug":"quick-chicken-vegetable-soup","source_url":"https://www.myplate.gov/recipes/quick-chicken-vegetable-soup","name":"Quick Chicken & Vegetable Soup","description":"A great way to use properly stored and handled leftover chicken. Using frozen veggies helps cut down prep time.","ingredients":[{"name":null,"items":["1 tablespoon onion (chopped)","1 medium red pepper (chopped)","1 cup chopped potatoes","2 cans low-sodium chicken broth (14.5 ounce cans)","1/2 cup cooked chicken (chopped or shredded)","1 package mixed vegetables (10 ounce frozen or vegetables of your choice)","1/4 teaspoon thyme","1/8 teaspoon ground black pepper","salt to taste (optional)"]}],"directions":[{"name":null,"steps":["Put the tomatoes, potatoes and broth in the pot. Cook on medium heat until they boil.","Add the onion. Turn the heat to low, and simmer for 10 minutes.","Add the remaining ingredients.","Cover the pan.","Cook for at least 5 more minutes over low heat until vegetables are tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared soup","1/4 of recipe (302g)"],"calories":"144.36 kcal","carbohydrateContent":"20.38 g","cholesterolContent":"16.67 mg","fiberContent":"4.24 g","proteinContent":"12.34 g","sodiumContent":"98.78 mg","sugarContent":"4.21 g","fatContent":"2.05 g","saturatedFatContent":"0.54 g"},"notes":"Use only cooked chicken for this recipe.\nThis easy recipe has much less sodium than canned soups.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"quick-chili","source_url":"https://www.myplate.gov/recipes/quick-chili","name":"Quick Chili","description":null,"ingredients":[{"name":null,"items":["1/2 pound ground beef, 90% lean","1 can kidney beans, low-sodium (15 1/2 ounces, with liquid)","1 cup tomato sauce, low-sodium","1 tablespoon onion, instant minced","1 1/2 tablespoons chili powder"]}],"directions":[{"name":null,"steps":["Thoroughly cook ground beef in skillet until browned (internal temperature of 160 °F). Do not undercook ground beef. Carefully wash your hands and any surfaces that have come in contact with raw meat.","Drain off fat into container.","Stir in kidney beans with liquid, tomato sauce, onion, and chili powder.","Bring to a boil. Reduce heat, cover, and simmer for 10 minutes.","Refrigerate or freeze leftovers within 2 hours of cooking. Use refrigerated leftovers within 4 days."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup prepared chili","1/4 of recipe (233g)"],"calories":"195.00 kcal","carbohydrateContent":"21.76 g","cholesterolContent":"32.86 mg","fiberContent":"7.87 g","proteinContent":"16.81 g","sodiumContent":"250.80 mg","sugarContent":"4.76 g","fatContent":"5.19 g","saturatedFatContent":"1.88 g"},"notes":null,"contributor":"Simply Good Eating Recipe Cards, Vol. 1, 2000\nUniversity of Minnesota Cooperative Extension Service"},
{"slug":"quick-easy-bean-dip","source_url":"https://www.myplate.gov/recipes/quick-easy-bean-dip","name":"Quick and Easy Bean Dip","description":"Beans make delicious dips for delectable snacks and side dishes.","ingredients":[{"name":null,"items":["1/3 cup beans, low-sodium canned or cooked (pinto beans work great)","1/3 tablespoon yogurt, non-fat plain (1 teaspoon)","1 tablespoon salsa"]}],"directions":[{"name":null,"steps":["Place beans in a small, resealable plastic bag. Squeeze out extra air and seal. Mash beans with fingers.","Add yogurt and salsa. Seal bag and mix with fingers.","Open bag or cut off corner of bag and squeeze out dip."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"70.32 kcal","carbohydrateContent":"12.97 g","cholesterolContent":"0.10 mg","fiberContent":"3.81 g","proteinContent":"4.04 g","sodiumContent":"185.97 mg","sugarContent":"1.52 g","fatContent":"0.47 g","saturatedFatContent":"0.10 g"},"notes":"Enjoy dip with your favorite veggies, corn chips, pita bread wedges, or whole-wheat crackers.\nCanned pinto beans used for costing and nutrition analysis.","contributor":"Originally named: Yummy Bean Dip\nAdapted from: University of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"quick-n-cool-summer-salad","source_url":"https://www.myplate.gov/recipes/quick-n-cool-summer-salad","name":"Quick ''N Cool Summer Salad","description":"Try this fun macaroni salad that combines vegetables, tuna, onions, cheese, and pickles with a creamy dressing. It''s great for your next cookout or picnic wi...","ingredients":[{"name":null,"items":["14 ounces elbow macaroni","1 can green beans, low-sodium (14.5 ounce, drained, or other vegetable)","1 can tuna packed in water (6.5 ounces, drained and flaked)","1 cup cheese (diced)","1/2 cup sweet pickles (diced)","1/2 cup onion (diced)","1 cup yogurt, plain, low-fat","1/2 cup mayonnaise, light","1 1/2 tablespoons lemon juice","1/4 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Prepare elbow macaroni according to package directions and drain.","Add vegetables, tuna, onions, cheese, and pickles.","Mix yogurt, salad dressing, lemon juice, salt, and seasoned pepper.","Toss with macaroni mixture.","Chill before serving.","Refrigerate leftovers promptly.","* Add chopped carrots if desired."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (186g)","calories":"372.04 kcal","carbohydrateContent":"52.49 g","cholesterolContent":"23.64 mg","fiberContent":"3.82 g","proteinContent":"16.53 g","sodiumContent":"396.07 mg","sugarContent":"6.35 g","fatContent":"10.46 g","saturatedFatContent":"3.91 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"quick-peach-cobbler","source_url":"https://www.myplate.gov/recipes/quick-peach-cobbler","name":"Quick Peach Cobbler","description":"A tasty dessert that can be enjoyed on its own or with added fruit.","ingredients":[{"name":null,"items":["1 can sliced peaches, packed in juice (15 ounce)","1 egg","1/3 cup sugar","1/2 cup flour","1/2 teaspoon baking powder","1/4 teaspoon salt","1 tablespoon margarine (softened)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 375 °F.","Open the can of peaches. Pour the peaches and their juice into the casserole dish. Heat them on the stovetop until they bubble.","Slightly beat 1 egg.","In a mixing bowl, mix the egg, sugar, flour, baking powder, salt, and margarine.","Drop spoonsful of this mixture on top of the hot, bubbling peaches.","Use pot holders to carefully remove the casserole dish from the stove.","Put the casserole dish in the oven. Bake for about 30 to 40 minutes."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (163g)","calories":"203.47 kcal","carbohydrateContent":"39.62 g","cholesterolContent":"51.41 mg","fiberContent":"1.70 g","proteinContent":"3.65 g","sodiumContent":"255.07 mg","sugarContent":"25.99 g","fatContent":"3.65 g","saturatedFatContent":"0.86 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"quick-skillet-lasagna","source_url":"https://www.myplate.gov/recipes/quick-skillet-lasagna","name":"Quick Skillet Lasagna","description":"This lasagna can be prepared entirely on the stovetop and uses Parmesan and cottage cheese. Add fresh veggies like green peppers, spinach, or whatever you ha...","ingredients":[{"name":null,"items":["1/2 cup onion (chopped)","1/2 pound ground beef (90% lean)","1 can tomatoes, low-sodium (14.5 ounce)","1 can tomato paste, low-sodium (6 ounce)","parsley, fresh (1 Tablespoon, optional)","1 1/2 cups water","garlic powder (1 teaspoon, optional)","2 cups egg noodles (cooked)","3/4 cup cottage cheese, low-fat","1/4 cup Parmesan cheese"]}],"directions":[{"name":null,"steps":["Chop onion. Cook beef and onion, in a large frying pan until beef is brown and onion is tender. Drain off excess fat.","Add tomatoes, tomato paste, parsley, water, and garlic powder to the beef mixture. Bring to a boil and simmer until sauce is thick, about 25 minutes.","Cook noodles in a separate saucepan according to package directions. Drain.","Add cooked, drained noodles to the beef mixture. Stir to prevent sticking.","Mix cheeses and drop by spoonfuls into the frying pan.","Cover and heat over low heat about 5 minutes.","Refrigerate leftovers."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared lasagna","1/7 of recipe (256g)"],"calories":"174.30 kcal","carbohydrateContent":"21.34 g","cholesterolContent":"24.14 mg","fiberContent":"3.03 g","proteinContent":"13.11 g","sodiumContent":"157.70 mg","sugarContent":"6.17 g","fatContent":"4.41 g","saturatedFatContent":"1.83 g"},"notes":"To decrease fat and cholesterol, omit the beef and add vegetables such as broccoli or zucchini to the sauce.","contributor":"Eating Right Is Basic\nMichigan State University Cooperative Extension Service\nNutrition Education Program"},
{"slug":"quick-tuna-casserole","source_url":"https://www.myplate.gov/recipes/quick-tuna-casserole","name":"Quick Tuna Casserole","description":"This creamy casserole can be easily prepped in advance. Enjoy it with roasted sweet potatoes or winter squash for a colorful meal.","ingredients":[{"name":null,"items":["1 cup water","5 ounces egg noodles (wide)","1 can cream of mushroom soup, low-sodium (10.75 ounce)","1/3 cup skim milk","1 can tuna (6.5 ounces, packed in water, drained)","1 cup green peas (frozen)","bread crumbs (1 cup, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Bring 1 quart of water to a boil in a large pot and cook the egg noodles in the water for 2 minutes.","Cover the pot, remove from heat, and let stand for 10 minutes.","In the meantime, mix the water, soup, and milk together in a bowl.","Combine tuna and peas with the mixture and pour into a 1-quart casserole dish.","Drain the noodles well and combine with the tuna mixture.","Sprinkle the top with bread crumbs if desired.","Bake for 30 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"152.85 kcal","carbohydrateContent":"24.06 g","cholesterolContent":"26.85 mg","fiberContent":"2.25 g","proteinContent":"8.89 g","sodiumContent":"261.85 mg","sugarContent":"3.16 g","fatContent":"2.39 g","saturatedFatContent":"0.59 g"},"notes":"To lower sodium content, use reduced-sodium cream of mushroom soup.","contributor":"Healthy Cookbook for African American Populations\nRecipe by Tara Caulder, Soaad Ali, and Laide Bello\n(Supervised by Dr. Mira Mehta and Terri Kieckhefer)"},
{"slug":"quinoa-and-black-bean-salad","source_url":"https://www.myplate.gov/recipes/quinoa-and-black-bean-salad","name":"Quinoa and Black Bean Salad","description":"Quinoa (pronounced \"KEEN-wah\") is a whole grain with origins in South America. It is combined in this recipe with black beans, savory vegetables, and spices ...","ingredients":[{"name":null,"items":["1/2 cup quinoa (dry)","1 1/2 cups water","1 1/2 tablespoons olive oil","3 teaspoons lime juice","1/4 teaspoon cumin","1/4 teaspoon coriander (ground, dried cilantro seeds)","2 tablespoons cilantro (chopped)","2 scallions (medium, minced)","1 can black beans, low-sodium (15.5 ounce can, rinsed and drained)","2 cups tomato (chopped)","1 red bell pepper (medium, chopped)","1 green bell pepper (medium, chopped)","2 green chiles (minced, to taste)","black pepper (to taste)"]}],"directions":[{"name":null,"steps":["Rinse the quinoa in cold water. Boil water in a saucepan, and then add the quinoa.","Return to boil, and then simmer until the water is absorbed, 10 to 15 minutes. Cool for 15 minutes.","While quinoa is cooking, mix olive oil, lime juice, cumin, coriander, chopped cilantro, and scallions in a small bowl, and set aside.","Combine chopped vegetables with the black beans in a large bowl, and set aside.","Once quinoa has cooled, combine all ingredients and mix well.","Cover and refrigerate until ready to serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup (254g)","calories":"166.84 kcal","carbohydrateContent":"25.32 g","cholesterolContent":"0.00 mg","fiberContent":"7.84 g","proteinContent":"7.05 g","sodiumContent":"111.25 mg","sugarContent":"3.78 g","fatContent":"4.74 g","saturatedFatContent":"0.73 g"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"rainbow-bell-pepper-boats-garbanzo-beans-and-kale","source_url":"https://www.myplate.gov/recipes/rainbow-bell-pepper-boats-garbanzo-beans-and-kale","name":"Rainbow Bell Pepper Boats with Garbanzo Beans and Kale","description":"Red, orange, and yellow bell peppers stuffed with garbanzo beans, kale, walnuts, and brown rice make a delicious Mediterranean-influenced vegetarian dish.","ingredients":[{"name":null,"items":["2 cups instant brown rice, cooked","4 medium bell peppers (red, yellow, and orange)","2 cups kale, chopped","1 15 oz can garbanzo beans, low-sodium","1/2 cup walnuts, chopped","1/4 teaspoon salt","1/8 teaspoon pepper"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F.","Cook rice according to package directions.","Slice bell peppers in half vertically and remove seeds.","Reserve about half of garbanzo beans; mash remaining portion with a fork.","Mix rice with kale, garbanzo beans (mashed and whole), nuts, salt, and pepper.","Fill peppers with mix; place in baking dish and cover.","Bake about 30 minutes.","Remove lid and bake more 5 more minutes."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"347.48 kcal","carbohydrateContent":"49.57 g","cholesterolContent":"0.00 mg","fiberContent":"9.16 g","proteinContent":"11.58 g","sodiumContent":"306.06 mg","sugarContent":"7.15 g","fatContent":"13.03 g","saturatedFatContent":"1.36 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"rainbow-veggie-salad","source_url":"https://www.myplate.gov/recipes/rainbow-veggie-salad","name":"Rainbow Veggie Salad","description":"This easy and colorful salad tastes best after marinating it overnight. Enjoy it as a side dish at lunch or dinner.","ingredients":[{"name":null,"items":["1 can (15.5 ounces) red kidney beans, low-sodium (drained and rinsed)","1 can (15.5 ounces) black beans, low-sodium (drained and rinsed)","3 carrots (scrubbed and sliced)","1 medium yellow squash (washed and sliced)","1 medium zucchini (washed and sliced)","1/2 cup light Italian dressing","1/2 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Mix all the vegetables together in a large bowl.","Pour dressing over vegetables.","Sprinkle with pepper.","Stir gently, coating all vegetables.","Cover and refrigerate at least 8 hours."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2/3 cup (106g)","calories":"95.87 kcal","carbohydrateContent":"17.99 g","cholesterolContent":"0.23 mg","fiberContent":"6.36 g","proteinContent":"5.68 g","sodiumContent":"257.01 mg","sugarContent":"3.87 g","fatContent":"0.55 g","saturatedFatContent":"0.17 g"},"notes":null,"contributor":"2009 Recipe Calendar\nUniversity of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"ratatouille-0","source_url":"https://www.myplate.gov/recipes/ratatouille-0","name":"Ratatouille","description":"Simmer eggplant, zucchini, red peppers, and tomatoes with onion, garlic, and seasonings for a delicious flavor in this classic dish.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1 large yellow onion (peeled and chopped into 1/4 inch pieces)","4 cloves garlic (peeled and minced)","1 medium eggplant (peeled and diced into 1/4-1/2 inch pieces)","2 zucchini (diced into 1/4-1/2 inch pieces or use 2 cups of frozen zucchini)","1 red bell pepper (cored, seeded, and diced into 1/4 inch pieces)","1 teaspoon dried basil","1/2 teaspoon dried oregano","3 1/2 cups canned low-sodium tomatoes (including the juice or fresh tomato)","1 lemon (quartered)","1/4 cup chopped fresh basil leaves"]}],"directions":[{"name":null,"steps":["Put the pot on the stove over medium-low heat and when it is hot, add the oil. Add the onion and garlic and cook until golden, about 10 minutes.","Add the eggplant, zucchini, bell pepper, basil, and oregano and cook, covered, until the eggplant is very, very soft, about 40 minutes.","Add the tomatoes and cook, uncovered, for 20 minutes. Serve right away, garnished with lemon quarters and basil, or cover and refrigerate up to 3 days."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"72.76 kcal","carbohydrateContent":"12.73 g","cholesterolContent":"0.00 mg","fiberContent":"5.04 g","proteinContent":"2.51 g","sodiumContent":"15.91 mg","sugarContent":"7.78 g","fatContent":"2.35 g","saturatedFatContent":"0.36 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"ratatouille","source_url":"https://www.myplate.gov/recipes/ratatouille","name":"Ratatouille","description":"Here is the perfect recipe to make when your garden or market is overflowing with peppers, eggplant, and tomatoes. Add cooked chicken or tofu to make this si...","ingredients":[{"name":null,"items":["2 tablespoons canola oil","1 yellow onion (sliced)","3 garlic cloves (minced)","2 bell peppers (green, red, or yellow)","1 eggplant (peeled and cut into 1 inch cubes)","1 can (14.5 ounces) diced tomatoes, low-sodium (undrained)","1 teaspoon dried basil","1/2 teaspoon black pepper","1/2 cup chopped parsley"]}],"directions":[{"name":null,"steps":["Heat oil in a large saucepan and sauté onion, garlic, bell peppers, and eggplant until tender, about 15 minutes.","Add tomatoes and basil, cook about 10 minutes. Add pepper and parsley before serving.","Serve hot. Cover and refrigerate within 2 hours."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"74.84 kcal","carbohydrateContent":"9.89 g","cholesterolContent":"0.00 mg","fiberContent":"3.78 g","proteinContent":"1.73 g","sodiumContent":"10.42 mg","sugarContent":"5.29 g","fatContent":"3.86 g","saturatedFatContent":"0.30 g"},"notes":"Optional: Use a bag of frozen vegetables. It will be more economical than fresh vegetables and contain less sodium than canned vegetables.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"red-bean-quesadilla","source_url":"https://www.myplate.gov/recipes/red-bean-quesadilla","name":"Red Bean Quesadilla","description":"Whole grain tortillas filled with mashed red beans, spinach, cheese, and avocado are heated until and warm, melted, and golden brown.","ingredients":[{"name":null,"items":["4 8-inch whole wheat tortilla","1 cup frozen spinach (thawed and squeezed to remove excess liquid)","1/2 cup shredded Monterey Jack or Cheddar cheese","1 avocado (peeled pitted chopped)","1 can 15.5 ounce low-sodium red kidney beans (drained and rinsed with cold water)","garlic powder or dry herbs (optional)"]}],"directions":[{"name":null,"steps":["Using a fork, mash beans in a bowl until slightly chunky. Add no-salt seasonings such as garlic powder and dried or fresh herbs, if desired.","Place 1 tortilla on a plate and top with half the mashed beans.","Top the beans with 1/2 cup of the spinach.","Top the spinach with half the cheese.","Top the cheese with half the avocado. (optional)","Put the other tortilla on top of the avocado, gently pressing it down so the top half sticks.","Repeat with the remaining 2 tortillas.","Place a nonstick skillet on the stove over medium and heat until warm, then place 1 quesadilla in the dry skillet. Cook until golden brown, about 1 to 2 minutes on each side. (Or put the plate in the microwave and heat until the cheese melts, about 45 seconds.)","Repeat with the remaining quesadilla.","Cut each quesadilla into quarters. Serve warm."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 quesadilla","calories":"359.49 kcal","carbohydrateContent":"42.82 g","cholesterolContent":"12.57 mg","fiberContent":"14.74 g","proteinContent":"16.49 g","sodiumContent":"545.44 mg","sugarContent":"3.72 g","fatContent":"15.05 g","saturatedFatContent":"5.92 g"},"notes":"Black beans or white cannellini beans can be used instead of kidney beans.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"red-beans-and-rice-0","source_url":"https://www.myplate.gov/recipes/red-beans-and-rice-0","name":"Red Beans and Rice","description":"Red kidney beans and tomatoes and flavored with garlic, onions, peppers, and seasonings and simmered until tender. Serve the bean mixture over rice and top w...","ingredients":[{"name":null,"items":["1 cup uncooked brown rice","2 teaspoons vegetable oil","2 cloves garlic (peeled and minced)","1 small yellow onion (chopped)","1 bell pepper (cored, seeded, and chopped)","1 1/2 ounces water","1 fresh tomato (coarsely chopped)","1/4 teaspoon salt","1/8 teaspoon ground cumin","2 cans (15.5 ounce) low-sodium red kidney beans (drained and rinsed)","1 1/2 cups water","1 avocado (peeled, pitted and chopped)","2 tablespoons fresh cilantro (chopped, optional)"]}],"directions":[{"name":"To prepare the rice","steps":["Put the rice and water in the pot and bring to a boil over high heat.","Turn the heat down to low and cook, covered, until the rice is tender, about 45 minutes."]},{"name":"To prepare the beans","steps":["Place the large skillet on the stove over medium-high heat. When it is hot, add the oil. Add the garlic, onion, bell pepper, and 2 tablespoons water. Cook until the mixture is golden, about 10 minutes.","Add the tomato, salt, cumin, beans, and water and cook until the beans are very soft, about 20 to 30 minutes.","Divide the cooked rice among 4 bowls or plates, and top with equal amounts of the bean mixture.","Top with avocado and sprinkle with cilantro, if using.","Serve right away, or cover and refrigerate up to 3 days."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"479.21 kcal","carbohydrateContent":"82.28 g","cholesterolContent":"0.00 mg","fiberContent":"17.87 g","proteinContent":"17.52 g","sodiumContent":"423.39 mg","sugarContent":"7.86 g","fatContent":"10.28 g","saturatedFatContent":"1.84 g"},"notes":"For a less expensive option, leave out the avocado.\nInstead of brown rice, try quinoa, barley, or farro.\nAdd cayenne pepper if more spice is desired.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"red-beans-and-rice","source_url":"https://www.myplate.gov/recipes/red-beans-and-rice","name":"Red Beans and Rice","description":"This flavorful dish is a Monday night tradition in many homes. This vegetarian recipe uses dry beans, onion, pepper, and spices.","ingredients":[{"name":null,"items":["2 cups red beans, dry","8 cups water","1 1/2 cups onion (chopped)","1 cup celery (chopped)","4 bay leaves","3 tablespoons garlic (chopped)","parsley (optional)","2 teaspoons thyme (crushed, dried)","1 teaspoon salt","1 teaspoon black pepper","1 cup red bell pepper (chopped - could also use green pepper)","2 cups cooked brown rice"]}],"directions":[{"name":null,"steps":["Pick through beans to remove shriveled or broken beans. Rinse beans thoroughly.","In a 5-quart pot, mix beans, water, onion, celery, and bay leaves. Bring to boiling; reduce heat.","Cover and cook over low heat for about 1 to 1/2 hours or until beans are tender. Stir and mash beans against side of pan.","Add garlic, parsley, thyme, salt, black pepper, and red or green pepper.","Cook uncovered, over low heat, until creamy, about 30 minutes. Remove bay leaves. Serve over hot cooked rice."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (359g)","calories":"224.25 kcal","carbohydrateContent":"43.29 g","cholesterolContent":"0.00 mg","fiberContent":"10.22 g","proteinContent":"11.71 g","sodiumContent":"323.53 mg","sugarContent":"2.77 g","fatContent":"1.17 g","saturatedFatContent":"0.25 g"},"notes":"See how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"Food and Drug Administration (FDA)\nUS Department of Health and Human Services"},
{"slug":"red-beans-and-rice1","source_url":"https://www.myplate.gov/recipes/red-beans-and-rice1","name":"Red Beans and Rice","description":"This flavorful dish is traditionally eaten on Monday nights in many homes and uses dry beans, onion, pepper, and spices.","ingredients":[{"name":null,"items":["cooking oil spray, as needed (non-stick)","1 medium onion, peeled and chopped","1 medium green bell pepper, washed, seeded and chopped","1 teaspoon garlic powder","2 cans (14.5 ounces) low-sodium diced tomatoes","1 can (15.5 ounces) low-sodium kidney beans, drained and rinsed","6 cups cooked brown rice (no salt added)"]}],"directions":[{"name":null,"steps":["Spray skillet with cooking oil spray, if using.","Cook onion and pepper over medium heat for 5 minutes or until tender.","Add garlic powder, tomatoes, and kidney beans.","Bring mixture to a boil.","Reduce heat to low and simmer for 5 minutes.","Serve over rice."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/8 of recipe"],"calories":"253.01 kcal","carbohydrateContent":"52.03 g","cholesterolContent":"0.00 mg","fiberContent":"7.74 g","proteinContent":"8.09 g","sodiumContent":"81.93 mg","sugarContent":"5.24 g","fatContent":"1.92 g","saturatedFatContent":"0.50 g"},"notes":"See how to make this recipe and more on USDA’s MyPlate Kitchen YouTube website.","contributor":"Adapted from Easy Red Beans and Rice\nUConn Husky Nutrition & Sport"},
{"slug":"red-chile-stew","source_url":"https://www.myplate.gov/recipes/red-chile-stew","name":"Red Chile Stew","description":"Spicy and savory, this four ingredient stew is simple and delicious.","ingredients":[{"name":null,"items":["3 dried red chiles (more or less depending on taste)","1 cup water","2 pounds pork top loin (cut into pieces)","1 teaspoon oregano","1/2 teaspoon garlic powder","salt (optional)"]}],"directions":[{"name":null,"steps":["Wash chilies, removing stems and seeds. Place in blender with 1 cup water and blend into paste","Brown pork lightly in non-stick skillet. Add the chili paste and mix well, adding water if mixture is too thick. Add oregano and garlic powder. Cover and simmer slowly for one hour."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"157.26 kcal","carbohydrateContent":"0.73 g","cholesterolContent":"63.99 mg","fiberContent":"0.24 g","proteinContent":"25.37 g","sodiumContent":"114.53 mg","sugarContent":"0.28 g","fatContent":"5.39 g","saturatedFatContent":"1.84 g"},"notes":null,"contributor":"A River of Recipes: Native American Recipes Using Commodity Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"red-hot-fusilli","source_url":"https://www.myplate.gov/recipes/red-hot-fusilli","name":"Red Hot Fusilli","description":"Spice up your weeknight dinner plans with this Red Hot Fusilli. Loaded with juicy tomatoes, this dish is wonderful with or without the optional chicken!","ingredients":[{"name":null,"items":["1 tablespoon olive oil (or cooking oil of choice)","2 cloves garlic, minced","1/4 cup fresh parsley, minced","4 cups ripe tomatoes, chopped","1 tablespoon fresh basil, chopped (1 tsp dried basil)","1 tablespoon oregano leaves, crushed (1 tsp dried oregano)","1/4 teaspoon salt","ground red pepper (or cayenne, to taste)","cooked chicken breast (1/2 pound diced into 1/2-inch pieces, optional)","8 ounces fusilli pasta (uncooked, 4 cups cooked)"]}],"directions":[{"name":null,"steps":["Heat oil in a medium saucepan. Saute garlic and parsley until golden.","Add tomatoes and spices. Cook uncovered over low heat 15 minutes or until thickened, stirring frequently. If desired, add chicken and continue cooking for 15 minutes until chicken is heated through and sauce is thick.","Cook pasta firm in unsalted water.","To serve, spoon sauce over pasta and sprinkle with coarsely chopped parsley. Serve hot as a main dish and cold for the next day''s lunch.","*Cost estimate and nutritional analysis does not include chicken."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"318.82 kcal","carbohydrateContent":"57.13 g","cholesterolContent":"0.00 mg","fiberContent":"4.72 g","proteinContent":"11.07 g","sodiumContent":"169.07 mg","sugarContent":"4.81 g","fatContent":"5.25 g","saturatedFatContent":"0.89 g"},"notes":"If pre-cooked chicken is not available, cook 3/4 pound raw chicken and chop into 1/2 inch pieces when cooled down.","contributor":"Stay Young at Heart: Cooking the Heart-Healthy Way\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"red-lentil-latkes","source_url":"https://www.myplate.gov/recipes/red-lentil-latkes","name":"Red Lentil Latkes","description":"Traditionally, latkes are pancakes made from potatoes, but these latkes also include lentils, cheese, and hot sauce. Flavorful and tasty, this dish makes a g...","ingredients":[{"name":null,"items":["1/2 cup dry red lentils","1 medium potato, grated (about 1/2 pound, peeling is optional)","1 large egg","1 garlic clove, finely sliced","Parmesan cheese, grated (optional, 2 tablespoons, or other cheese)","hot sauce (optional, 1 or 2 dashes)","1/4 teaspoon salt","black pepper (optional, to taste)","2 tablespoons canola oil"]}],"directions":[{"name":null,"steps":["Add the lentils to a medium saucepan and add water to cover by about an inch. Bring to a boil, then lower heat to a simmer and cook until tender, about 15 minutes. Drain and set aside.","Meanwhile, remove the excess water from the potato: you can either squeeze it by the handful, or put the entire pile on a clean tea towel and wring it out.","Crack the egg in a medium bowl and beat it lightly. Add the potato, cooked lentils, garlic, and green onion. Add cheese and hot sauce if you''re using them. Add the salt and a good grinding of black pepper and stir until combined.","Heat a large skillet over medium heat, then add a generous drizzle of oil (1-2 tablespoons). Working in batches, so as not to crowd the pan, add clumps of the potato-lentil mixture (about the size of a golf ball or slightly larger works well), and flatten each as soon as it''s in the pan, making them about a half inch thick.","Cook for about 4 to 5 minutes per side, until the latkes are deeply golden brown and cooked through. Add a little more oil to the pan for each additional batch. Serve immediately or keep the latkes warm in a 200 °F oven for up to an hour."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"202.49 kcal","carbohydrateContent":"23.39 g","cholesterolContent":"51.38 mg","fiberContent":"6.49 g","proteinContent":"8.94 g","sodiumContent":"169.77 mg","sugarContent":"1.79 g","fatContent":"8.57 g","saturatedFatContent":"0.91 g"},"notes":null,"contributor":"The Big Book of Lentils Cookbook\nCanadian Lentils"},
{"slug":"red-monster-smoothie","source_url":"https://www.myplate.gov/recipes/red-monster-smoothie","name":"Red Monster Smoothie","description":"This smoothie has two cups of fruit per serving and kale for an added veggie boost. Try it for breakfast or as a snack.","ingredients":[{"name":null,"items":["1 cup kale or spinach","1 cup water (optional almond milk or coconut milk)","1 cup strawberries","1 medium banana","1 cup blueberries","1 cup pineapple","1 medium orange (peeled and sliced)","1 cup ice"]}],"directions":[{"name":null,"steps":["Using a blender, mix the greens and the liquid of your choice.","Gradually add in the rest of the ingredients, blending after each addition.","Separate into two cups and reserve one serving for later."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"215.24 kcal","carbohydrateContent":"51.34 g","cholesterolContent":"0.00 mg","fiberContent":"7.58 g","proteinContent":"3.02 g","sodiumContent":"28.38 mg","sugarContent":"36.55 g","fatContent":"0.98 g","saturatedFatContent":"0.14 g"},"notes":null,"contributor":"UConn Husky Nutrition & Sport"},
{"slug":"red-potato-and-cabbage-colcannon","source_url":"https://www.myplate.gov/recipes/red-potato-and-cabbage-colcannon","name":"Red Potato and Cabbage (Colcannon)","description":"Hearty, delicious, and sure to please any crowd. This recipe is filling enough to stand alone or could make a great side dish.","ingredients":[{"name":null,"items":["3 1/2 cups red potatoes (about 1 pound)","1 tablespoon margarine (or butter)","1/2 cup onion, chopped","6 cups green cabbage, thinly sliced (about 1/2 head)","1 cup 1% milk (or fat-free )","1 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Scrub potatoes, but do not peel. Cut into quarters. Cook in boiling water or steam until tender, about 15 to 20 minutes.","While potatoes cook, heat butter or margarine in a large skillet over medium high heat. Add onion and cook until it becomes clear, about 3 to 5 minutes.","Add cabbage and cook, stirring occasionally, until cabbage begins to brown, about 4 to 6 minutes.","Reduce heat to low. Add milk, salt, and pepper. Cover and cook until cabbage is tender, about 6 to 8 minutes.","Drain potatoes. Add cabbage mixture to potatoes. Mash with a potato masher or large fork to reach desired texture. Serve warm."]}],"yield":"11 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/11 of recipe","calories":"65.29 kcal","carbohydrateContent":"12.30 g","cholesterolContent":"1.12 mg","fiberContent":"2.06 g","proteinContent":"2.36 g","sodiumContent":"245.50 mg","sugarContent":"3.53 g","fatContent":"1.09 g","saturatedFatContent":"0.32 g"},"notes":"Use any all-purpose potatoes such as yellow or white. Russet potatoes are also good but you may want to peel through the rough skin after scrubbing them.\nTry adding cilantro on top for more flavor.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"red-potato-salad","source_url":"https://www.myplate.gov/recipes/red-potato-salad","name":"Red Potato Salad","description":"This all-time favorite mix of tender potatoes, celery, and onions has been updated with a tangy yogurt sauce. This classic side is sure to please a hungry fa...","ingredients":[{"name":null,"items":["1 cup yogurt, plain fat-free","1/4 cup mayonnaise, low-fat","1 tablespoon yellow mustard","4 medium red potatoes (about 1 pound)","1/2 cup celery, chopped","1/4 cup onion, finely chopped","1/2 teaspoon salt","1/4 teaspoon pepper"]}],"directions":[{"name":null,"steps":["To prepare sauce, combine yogurt, mayonnaise and mustard in a small bowl. Mix well and refrigerate.","Wash potatoes and place in pot. Cover with water about 1 inch above potatoes.","Bring water and potatoes to a boil and simmer until potatoes are fork tender.","Drain potatoes and set aside to cool.","When potatoes are cooled, cut into bite-sized cubes. Place cut potatoes into large bowl.","Add celery, onions, salt, and pepper to potatoes. Top with sauce and mix well.","Garnish with parsley and enjoy."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"230.65 kcal","carbohydrateContent":"41.62 g","cholesterolContent":"3.73 mg","fiberContent":"3.71 g","proteinContent":"7.92 g","sodiumContent":"545.86 mg","sugarContent":"8.41 g","fatContent":"4.00 g","saturatedFatContent":"0.70 g"},"notes":"Red or white potatoes can be used.\nDijon mustard can be substituted for yellow mustard.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"refried-beans","source_url":"https://www.myplate.gov/recipes/refried-beans","name":"Refried Beans","description":"This traditional side dish is versatile, flavorful, and delicious. There are different ways to prepare refried beans. This recipe uses dry beans, oil, garlic...","ingredients":[{"name":null,"items":["1 1/2 cups dry pinto beans (sorted and rinsed)","1 tablespoon cooking oil of choice","2 garlic cloves, minced","1/4 cup onions, chopped","1 teaspoon ground cumin"]}],"directions":[{"name":null,"steps":["Cook beans and reserve some of the cooking liquid before draining.","Sauté onions and garlic in oil until onions become clear. Add a little water if vegetables stick.","Mash half of the beans, and add to onion and garlic. Continue to sauté for 10 minutes, stirring frequently. Allow some of the mashed beans to brown.","Add cumin. Add remaining beans and continue cooking until they are warmed through.","Water or liquid from beans may be added to keep the beans soft and mushy."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 recipe","calories":"188.70 kcal","carbohydrateContent":"30.87 g","cholesterolContent":"0.00 mg","fiberContent":"10.34 g","proteinContent":"10.44 g","sodiumContent":"2.52 mg","sugarContent":"0.69 g","fatContent":"3.18 g","saturatedFatContent":"0.49 g"},"notes":null,"contributor":"The Bold and Beautiful Book of Bean Recipes\nWashington State WIC Program"},
{"slug":"rhubarb-blueberry-crisp","source_url":"https://www.myplate.gov/recipes/rhubarb-blueberry-crisp","name":"Rhubarb Blueberry Crisp","description":"A great twist on a classic dish, this is the perfect mix of sweet and tart. Whether you are making this for an event or for your family at home, this treat i...","ingredients":[{"name":"Topping","items":["1/4 cup packed brown sugar","1/2 cup all-purpose flour","1/2 cup old fashioned rolled oats","1/4 cup unsalted butter (melted)"]},{"name":"Fruit Filling","items":["3 cups chopped rhubarb","3 cups blueberries","2 tablespoons cornstarch","1/4 cup sugar","1 cup 100% fruit juice (any type)","1 teaspoon vanilla"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","In a medium bowl, stir together brown sugar, flour and oats.","Stir in the butter and set aside.","Spread the rhubarb and blueberries in an 8x8 inch baking dish and set aside.","In a medium saucepan, mix cornstarch and sugar and stir in the juice. Cook over medium heat, stirring all the time, until the mixture has thickened. Turn off the heat.","Stir in vanilla and pour the mixture over the rhubarb and blueberries.","Crumble oat mixture on top of the fruit.","Bake for 45 minutes or until topping is browned and fruit is bubbling at edges. Serve warm or cold."]}],"yield":"9 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"191.77 kcal","carbohydrateContent":"34.06 g","cholesterolContent":"13.56 mg","fiberContent":"2.64 g","proteinContent":"2.15 g","sodiumContent":"7.12 mg","sugarContent":"20.03 g","fatContent":"5.77 g","saturatedFatContent":"3.29 g"},"notes":"Try strawberries instead of blueberries.\nTry apple, orange, or cranberry blend 100% fruit juice.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"rice-bowl-breakfast-fruit-and-nuts","source_url":"https://www.myplate.gov/recipes/rice-bowl-breakfast-fruit-and-nuts","name":"Rice Bowl Breakfast with Fruit and Nuts","description":"The sweet and savory combination of ingredients in this rice bowl makes it a great start to your day. Rice, fruit, and nuts come together to create a nutriti...","ingredients":[{"name":null,"items":["1 cup cooked brown rice","1/2 cup fat free (skim) milk, or 1%","1/2 teaspoon cinnamon","1 cup chopped fruit (try a mixture - apples, bananas, raisins, berries, peaches)","2 tablespoons chopped nuts (try walnuts or almonds)"]}],"directions":[{"name":null,"steps":["Combine cooked rice, milk and cinnamon in a microwave-safe bowl. Microwave on HIGH for 45 seconds. Stir and heat for another 45 to 60 seconds, or until rice mixture is heated through.","Divide rice mixture between two bowls. Top with fruit and nuts. Serve warm.","Refrigerate leftovers within 2 hours."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"229.08 kcal","carbohydrateContent":"38.69 g","cholesterolContent":"1.83 mg","fiberContent":"3.73 g","proteinContent":"6.04 g","sodiumContent":"29.30 mg","sugarContent":"11.09 g","fatContent":"5.98 g","saturatedFatContent":"0.77 g"},"notes":"Use any combination of fresh, canned, frozen, and dried fruit in this recipe.\nYou can use any leftover cooked grain in this recipe. Try white or wild rice, quinoa, barley, or oatmeal.\nSkim milk, apples, and walnuts were used for nutrition and cost analysis.\nLearn more about fruits and what''s in season now.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"rice-chicken-arroz-con-pollo","source_url":"https://www.myplate.gov/recipes/rice-chicken-arroz-con-pollo","name":"Rice with Chicken | Arroz con Pollo","description":"This stewed chicken and rice dish comes together with tomatoes and traditional seasonings. This one-pan meal is an all-time favorite.","ingredients":[{"name":null,"items":["4 6-ounce chicken thighs (bone-in, skin removed)","1/2 teaspoon Kosher salt","1/2 teaspoon black pepper","1 yellow onion (peeled and chopped)","1 bell pepper (cored, seeded, and chopped)","3 garlic cloves (peeled and minced)","1 teaspoon ground cumin","1 teaspoon dried oregano","1 cup long-grain white rice (uncooked)","1 can (14.5 oz) low-sodium diced tomatoes (including liquid)","2 cups water","1 cube low sodium chicken bouillon"]}],"directions":[{"name":null,"steps":["To trim, lay chicken thighs on the cutting board, skin side up. Push the chicken down so the excess fat is on the cutting board (the excess is the part that isn’t right on top of the chicken). Using kitchen scissors or a sharp knife, cut off excess fat and discard. Pat chicken dry with paper towels, and discard towels.","Place the skillet over medium high heat and when it is hot, add the chicken thighs, skin side down and cook until browned, then flip, about 5 minutes on each side.","Turn the heat off, carefully remove the chicken from the skillet and transfer to the plate. Pour off all but 1 tablespoon fat.","Reheat the skillet over low heat and add the onion, pepper, garlic, cumin, and oregano and cook until the onion is softened, about 10 minutes.","Add the uncooked rice and tomatoes and stir well.","Add the water and bouillon cube and bring to a boil over high heat. Return chicken to pan, skin side down, turn the heat down to low and cover.","Cook chicken for 20 minutes and then carefully flip so that the skin side is up.","Cover and cook for an additional 20 minutes. Serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"6 ounces","calories":"414.54 kcal","carbohydrateContent":"51.11 g","cholesterolContent":"132.68 mg","fiberContent":"3.90 g","proteinContent":"30.50 g","sodiumContent":"430.75 mg","sugarContent":"5.37 g","fatContent":"9.20 g","saturatedFatContent":"2.53 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"rice-crusted-pizza","source_url":"https://www.myplate.gov/recipes/rice-crusted-pizza","name":"Rice-Crusted Pizza","description":"A fun and unique twist on pizza using rice as the crust. Enjoy this main dish with all of your favorite toppings!","ingredients":[{"name":null,"items":["2 cups rice (cooked)","16 ounces mozzarella cheese, part skim","1 egg","1/4 teaspoon salt","2 cups tomato purée, low-sodium"]}],"directions":[{"name":null,"steps":["Heat oven to 350 °F. Grease a 12-inch pizza pan or baking sheet.","Cook rice following directions on the package; set aside.","Grate cheese; set aside.","Crack egg and place in mixing bowl, stirring to blend. Measure and add 2 cups cooked rice, 1 cup grated cheese, and salt. Mix well to combine ingredients.","Spread rice mixture in prepared pan, pressing firmly and making outer edge slightly raised.","Spread tomato purée evenly over rice mixture.","Place pan in oven. Bake for 25 minutes.","Remove pan from oven sprinkle pizza with remaining cheese. Bake 5 minutes longer or until cheese melts.","Remove pizza from oven. Cut into 12 slices.","Create-a-Flavor Changes:","Try different kinds of rice.","Try different kinds of cheese.","Use sliced or chopped green peppers, onions, mushrooms, or other vegetables as toppings."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/12 of recipe (110g)"],"calories":"161.83 kcal","carbohydrateContent":"11.31 g","cholesterolContent":"41.70 mg","fiberContent":"0.72 g","proteinContent":"10.67 g","sodiumContent":"323.57 mg","sugarContent":"2.16 g","fatContent":"8.32 g","saturatedFatContent":"4.59 g"},"notes":null,"contributor":"Cooking Up Fun - A Pyramid of Snacks\nCornell University Cooperative Extension\nDivision of Nutritional Sciences"},
{"slug":"rice-dessert","source_url":"https://www.myplate.gov/recipes/rice-dessert","name":"Rice Dessert","description":"Easy, delicious, and full of fruit, Rice Dessert is a nice way to end a good meal.","ingredients":[{"name":null,"items":["1 cup crushed pineapple in juice (8 ounce can)","1 cup cooked brown rice, chilled","1 cup low-fat plain yogurt (or vanilla)","1 cup applesauce","1/4 cup raisins"]}],"directions":[{"name":null,"steps":["Put aside 1/4 cup of drained pineapple.","Mix all other ingredients together in a medium-sized bowl.","Serve in small dishes.","Top with the remaining crushed pineapple."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"130.59 kcal","carbohydrateContent":"28.99 g","cholesterolContent":"0.82 mg","fiberContent":"1.65 g","proteinContent":"3.70 g","sodiumContent":"37.00 mg","sugarContent":"18.30 g","fatContent":"0.52 g","saturatedFatContent":"0.16 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"rice-pudding","source_url":"https://www.myplate.gov/recipes/rice-pudding","name":"Rice Pudding","description":"Serve this recipe fresh off the stove or after it has chilled in the refrigerator.","ingredients":[{"name":null,"items":["1 cup whole milk","1 cup water","1 cup rice, uncooked","2 eggs","1 cup evaporated milk, divided","1 teaspoon vanilla","1/4 cup sugar","1/8 teaspoon ground cinnamon"]}],"directions":[{"name":null,"steps":["In sauce pan, heat milk and water.","Add rice, bring to boil, lower heat to simmer; stir mixture every 10 minutes. Cook uncovered until rice is tender, about 30 minutes.","In large bowl, mix eggs, 3/4 cup evaporated milk, vanilla, and sugar. Set aside.","Add remaining 1/4 cup evaporated milk to rice mixture.","Spoon 1 cup of rice mixture into egg mixture and stir. Pour egg-rice mixture into remaining rice.","Heat pudding until it boils, stirring continuously. Remove from heat, and sprinkle with cinnamon."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/4 cup prepared rice","1/8 of recipe"],"calories":"197.83 kcal","carbohydrateContent":"31.08 g","cholesterolContent":"64.17 mg","fiberContent":"0.31 g","proteinContent":"6.61 g","sodiumContent":"63.22 mg","sugarContent":"10.98 g","fatContent":"4.82 g","saturatedFatContent":"2.47 g"},"notes":null,"contributor":"Recipes and Tips for Healthy, Thrifty Meals\nUSDA Center for Nutrition Policy and Promotion"},
{"slug":"rice-pudding1","source_url":"https://www.myplate.gov/recipes/rice-pudding1","name":"Rice Pudding","description":"Enjoy this classic rice pudding recipe that uses cinnamon and raisins, or any other favorite dried fruit, to make a wholesome dessert that has just the right...","ingredients":[{"name":null,"items":["2/3 cup uncooked white rice","3 cups warm water, divided","1 teaspoon butter or margarine","1/2 cup non-fat dry milk","2 tablespoons sugar","1/2 teaspoon vanilla","1/2 teaspoon cinnamon","1/2 cup raisins (or other dried fruit)"]}],"directions":[{"name":null,"steps":["Combine rice, 2 cups of water, and butter or margarine in large microwave safe dish. Cover loosely, so steam will escape.","Cook in microwave on high for 5 minutes or until mixture comes to a boil. Reduce setting to defrost (50% power), and cook an additional 10 minutes.","Mix dry milk, sugar, vanilla, cinnamon, 1 cup water, and raisins together while rice is cooking.","Without allowing rice to cool, remove cover and quickly stir the dry milk mixture into hot rice. Cover loosely again and continue cooking on defrost (50% power) for 10 minutes. After cooking time is finished, let pudding sit, covered, for 10 minutes.","Stir gently and put in individual serving dishes.","Eat warm or cover and refrigerate immediately. Enjoy the refrigerated pudding within 2 days."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2/3 cup","1/4 of recipe"],"calories":"250.81 kcal","carbohydrateContent":"53.73 g","cholesterolContent":"4.39 mg","fiberContent":"1.46 g","proteinContent":"6.33 g","sodiumContent":"59.23 mg","sugarContent":"23.82 g","fatContent":"1.42 g","saturatedFatContent":"0.77 g"},"notes":"A 9-10 year-old child can learn how to use measuring spoons and cups while helping make this recipe.","contributor":"Simply Good Eating Recipe Cards, Vol. 1, 2000, Adapted from Easy Rice Pudding\nUniversity of Minnesota Cooperative Extension Service"},
{"slug":"rice-salad","source_url":"https://www.myplate.gov/recipes/rice-salad","name":"Rice Salad","description":"Enjoy this versatile recipe with family and friends. You can substitute other frozen and fresh veggies than the ones listed in the ingredients depending on w...","ingredients":[{"name":null,"items":["2 cups cooked brown rice","1/2 cup frozen green peas, cooked","1 cup diced celery","1/2 cup diced bell peppers","1/4 cup raisins","2 tablespoons mayonnaise","2 tablespoons French dressing","salt (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Mix rice, vegetables, and raisins in a medium-sized bowl.","Mix mayonnaise, dressing and salt in a small bowl. Stir into rice/vegetable mixture.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/6 of recipe"],"calories":"168.44 kcal","carbohydrateContent":"25.96 g","cholesterolContent":"1.93 mg","fiberContent":"2.60 g","proteinContent":"3.03 g","sodiumContent":"94.07 mg","sugarContent":"6.59 g","fatContent":"6.21 g","saturatedFatContent":"1.05 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"rise-and-shine-cobbler","source_url":"https://www.myplate.gov/recipes/rise-and-shine-cobbler","name":"Rise and Shine Cobbler","description":"This cobbler can be made quickly in the microwave. Enjoy this tasty treat for breakfast or as a sweet dessert.","ingredients":[{"name":null,"items":["1 cup peaches (canned, drained and sliced)","1 cup pear halves (canned, drained and sliced)","6 prunes (pitted, each cut in half)","1/4 teaspoon vanilla extract","1 orange","1 cup granola, low-fat"]}],"directions":[{"name":null,"steps":["In a large microwave-safe bowl, mix peaches, pears, prunes, and vanilla extract.","Rub an orange against a grater to remove 1 teaspoon of the orange peel. Then, cut the orange in half and squeeze 1/4 cup orange juice. Add orange peel and juice to fruit mixture. Stir.","Top with granola.","Microwave on high for 5 minutes. Let stand for 2 minutes.","Spoon into 4 bowls and serve warm."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (201g)","calories":"216.98 kcal","carbohydrateContent":"44.32 g","cholesterolContent":"0.00 mg","fiberContent":"5.39 g","proteinContent":"3.73 g","sodiumContent":"52.82 mg","sugarContent":"25.73 g","fatContent":"3.78 g","saturatedFatContent":"0.40 g"},"notes":null,"contributor":"Kids… Get Cooking!\nCalifornia Department of Health Services\nCalifornia Children’s 5-A-Day Power Play Campaign"},
{"slug":"roast-chicken","source_url":"https://www.myplate.gov/recipes/roast-chicken","name":"Roast Chicken","description":"Roasted chicken is a simple and classic recipe that will never go out of style. Experiment with different seasonings, if you''d like. Try it with your favorit...","ingredients":[{"name":null,"items":["1 chicken, whole","1 tablespoon olive oil (or canola oil)","1 teaspoon Italian seasoning","1 teaspoon garlic powder","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 °F.","Combine Italian seasoning, garlic powder, salt, and pepper (optional).","Rub chicken with oil, then rub with spice mixture.","Place chicken, breast side down, in roasting pan or Dutch oven.","Bake, uncovered, until internal temperature reaches at least 165 °F.","Let chicken rest for 10 minutes before cutting."]}],"yield":"7 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/7 of recipe","calories":"196.76 kcal","carbohydrateContent":"0.32 g","cholesterolContent":"83.05 mg","fiberContent":"0.04 g","proteinContent":"27.07 g","sodiumContent":"80.55 mg","sugarContent":"0.01 g","fatContent":"8.92 g","saturatedFatContent":"2.21 g"},"notes":"For more flavor, try other seasonings like 1 teaspoon rosemary or thyme.\nServe with mashed sweet potatoes.","contributor":"University of Minnesota Extension"},
{"slug":"roast-turkey-breast-rosemary-sage-and-thyme","source_url":"https://www.myplate.gov/recipes/roast-turkey-breast-rosemary-sage-and-thyme","name":"Roast Turkey Breast with Rosemary, Sage, and Thyme","description":"Perfect for a holiday gathering, this roast turkey breast can be prepated in less time than a whole turkey. Enjoy!","ingredients":[{"name":null,"items":["3 pounds turkey breast half (with skin and bones)","1 onion, large quartered","1 carrot, large quartered","1 teaspoon dried sage","1 teaspoon dried thyme","1 teaspoon rosemary","3 tablespoons olive oil","salt and pepper (to taste, optional)","chicken broth, low sodium (or margarine, for basting, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Place turkey breast in roasting pan along with onion and carrot.","Mix spices with olive oil. Rub turkey with olive oil.","Roast turkey at 400 °F for 15 minutes. Baste with margarine and chicken broth (optional).","Reduce turkey temperature to 350 °F and roast turkey, basting every 20 minutes with pan juices (or margarine and chicken broth), about 1 hour and 15 minutes, or until meat thermometer inserted in thick part of meat registers 165 °F.","Remove to carving board and let rest for 10 minutes."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"296.94 kcal","carbohydrateContent":"2.61 g","cholesterolContent":"130.36 mg","fiberContent":"0.63 g","proteinContent":"49.70 g","sodiumContent":"254.02 mg","sugarContent":"1.13 g","fatContent":"8.85 g","saturatedFatContent":"1.85 g"},"notes":null,"contributor":"Utah State University Cooperative Extension"},
{"slug":"roasted-bell-peppers","source_url":"https://www.myplate.gov/recipes/roasted-bell-peppers","name":"Roasted Bell Peppers","description":"Roasting brings out the natural sweetness of the bell peppers. Modify this recipe by trying other seasonings, such as oregano or dried basil.","ingredients":[{"name":null,"items":["4 bell peppers","2 teaspoons vegetable oil","1/2 teaspoon Italian seasoning","1/2 teaspoon garlic powder","1/4 teaspoon salt","1/4 teaspoon black peppeer"]}],"directions":[{"name":null,"steps":["Preheat oven to 450 degrees F.","Wash bell peppers and remove tops and seeds. Cut peppers in half and rub with vegetable oil.","Place cut side up on a rimmed baking sheet and sprinkle with Italian seasoning, garlic powder, salt, and pepper.","Roast until peppers are tender and blistered in spots, about 30 to 35 minutes."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 pepper halves","calories":"54.90 kcal","carbohydrateContent":"8.09 g","cholesterolContent":"0.00 mg","fiberContent":"1.45 g","proteinContent":"1.14 g","sodiumContent":"150.11 mg","sugarContent":"3.69 g","fatContent":"2.57 g","saturatedFatContent":"0.36 g"},"notes":"No Italian seasoning? Use 1 teaspoon dried oregano, 1 teaspoon dried basil, and 1/2 teaspoon garlic powder.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"roasted-brussels-sprouts-potatoes-and-chicken","source_url":"https://www.myplate.gov/recipes/roasted-brussels-sprouts-potatoes-and-chicken","name":"Roasted Brussels Sprouts, Potatoes, and Chicken","description":"A versatile, fall, baked dish, our tasty version features potatoes and Brussels sprouts. Other fall vegetables -- such as parsnips, carrots, and cabbage -- c...","ingredients":[{"name":null,"items":["3 cups Brussels sprouts (fresh or frozen halved vertically, about 3/4 pound)","4 small red potatoes (cut into chunks)","1/2 cup chopped onion","2 cloves garlic (minced)","2 tablespoons olive oil","1/4 teaspoon salt","1/8 teaspoon pepper","1/2 cup non-fat ricotta cheese (or cottage cheese)","1/4 cup part-skim mozzarella cheese (shredded)","2 tablespoons non-fat milk","1 pound boneless chicken breast (4 portions)"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 °F.","In a 2 quart baking dish coated with cooking spray, toss Brussels sprouts, potatoes, onion, and garlic with 1 tablespoon olive oil, salt, and pepper.","In a small bowl, mix cheese with milk.","Coat chicken breasts with remaining olive oil.","Nest among vegetables in baking dish.","Top with cheese mix.","Cover with foil and bake for 40 to 45 minutes or until chicken is done."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"415.61 kcal","carbohydrateContent":"38.46 g","cholesterolContent":"89.42 mg","fiberContent":"5.76 g","proteinContent":"34.65 g","sodiumContent":"304.57 mg","sugarContent":"5.12 g","fatContent":"14.04 g","saturatedFatContent":"4.12 g"},"notes":"Serve with 8 ounce non-fat milk and orange slices.","contributor":"Produce for Better Health Foundation"},
{"slug":"roasted-brussels-sprouts","source_url":"https://www.myplate.gov/recipes/roasted-brussels-sprouts","name":"Roasted Brussels Sprouts","description":"Roasting Brussels sprouts creates a warm, flavorful, and versatile vegetable dish. This recipe is simple and does not require many ingredients.","ingredients":[{"name":null,"items":["6 cups Brussels sprouts","1 tablespoon vegetable oil (or cooking oil of choice)","1/8 teaspoon salt","1/8 teaspoon black pepper","1 teaspoon lemon juice"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 degrees F.","Wash and trim Brussels sprouts. Cut large Brussels sprouts in half from top to bottom; leave small Brussels sprouts whole.","In a large bowl, toss Brussels sprouts with the oil, salt, and pepper.","Place Brussels sprouts in a single layer on a large baking sheet. Lining the baking sheet with foil or baking parchment will help with clean-up.","Roast for 20 to 30 minutes, stirring once after 10 to 15 minutes. Sprouts should be tender and browned.","Remove from oven and drizzle with lemon juice."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"65.60 kcal","carbohydrateContent":"9.24 g","cholesterolContent":"0.00 mg","fiberContent":"3.85 g","proteinContent":"3.46 g","sodiumContent":"77.17 mg","sugarContent":"2.27 g","fatContent":"2.64 g","saturatedFatContent":"0.38 g"},"notes":"Try adding other seasonings with the lemon juice such as red pepper flakes or parmesan cheese.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"roasted-cauliflower-steaks","source_url":"https://www.myplate.gov/recipes/roasted-cauliflower-steaks","name":"Roasted Cauliflower Steaks","description":"Cauliflower steaks are a fun way to get in some of your daily vegetables! This simple recipe spices up cauliflower using lemon juice and garlic powder.","ingredients":[{"name":null,"items":["1 medium head cauliflower","1 tablespoon vegetable oil (or cooking oil of choice)","2 tablespoons lemon juice","1 teaspoon garlic powder","1/2 teaspoon salt","1/4 teaspoon black pepper","paprika (1/2 teaspoon, optional)","grated parmesan cheese (1/4 cup, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 degrees F.","Lightly grease a large baking sheet.","Slice cauliflower from top to bottom through the core into 1- to 1 1/2- inch thick steaks. Put steaks on the baking sheet along with end pieces, flat side down.","In a small bowl, mix the rest of the ingredients, except cheese.","Spoon on and spread or brush the cauliflower with half the mixture. Roast for 20 minutes.","Remove baking sheet from the oven, carefully turn the steaks and spread the rest of the mixture. Roast for 15 to 20 minutes or until the cauliflower is browned and tender.","Sprinkle with cheese, if desired, and serve."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"48.88 kcal","carbohydrateContent":"5.71 g","cholesterolContent":"0.00 mg","fiberContent":"2.09 g","proteinContent":"2.01 g","sodiumContent":"227.07 mg","sugarContent":"2.03 g","fatContent":"2.63 g","saturatedFatContent":"0.46 g"},"notes":"Try other seasonings such as cumin, oregano, and cayenne pepper or basil, thyme, and red pepper flakes.\nServe steaks topped with tomato or other sauce.\nFreeze extra lemon juice to use later.\nTo roast florets rather than steaks: In a large bowl, mix all ingredients and pour onto a large baking sheet. Roast 20 to 30 minutes or until browned and tender.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"roasted-cauliflower","source_url":"https://www.myplate.gov/recipes/roasted-cauliflower","name":"Roasted Cauliflower","description":"Oven-roasted cauliflower sprinkled with cheese is a simple and delicious side dish that pairs well with any entrée.","ingredients":[{"name":null,"items":["1 medium cauliflower head","2 tablespoons olive oil (or cooking oil of choice)","1/4 teaspoon salt","1/4 teaspoon black pepper","1/2 cup shredded Parmesan cheese"]}],"directions":[{"name":null,"steps":["Remove outer leaves of cauliflower. Cut florets off the stem. Wash and drain.","Combine oil, salt, and pepper in a large bowl. Toss the cauliflower florets in the oil mixture.","Spread cauliflower on a large rimmed baking sheet.","Roast in the oven at 450 degrees F for 15 to 20 minutes until the cauliflower starts to soften and begins to brown.","Sprinkle with cheese. Continue to roast for 5 to 10 minutes."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"70.88 kcal","carbohydrateContent":"4.15 g","cholesterolContent":"4.30 mg","fiberContent":"1.52 g","proteinContent":"2.93 g","sodiumContent":"166.33 mg","sugarContent":"1.43 g","fatContent":"5.15 g","saturatedFatContent":"1.46 g"},"notes":null,"contributor":"University of Maryland Cooperative Extension\nFood Supplement Nutrition Education Program"},
{"slug":"roasted-chickpeas-garbanzo-beans","source_url":"https://www.myplate.gov/recipes/roasted-chickpeas-garbanzo-beans","name":"Roasted Chickpeas (Garbanzo Beans)","description":"These crunchy chickpeas make a great on-the-go snack or a healthy topping to your favorite salad. Experiment with different spices to see which ones you like...","ingredients":[{"name":null,"items":["1 can (15 ounces) low-sodium garbanzo beans, drained and rinsed","1 tablespoon canola oil (or cooking oil of choice)","1/8 teaspoon salt","spices of your choice, optional (try garlic, paprika, sage, etc.)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 degrees F.","Drain and rinse the beans until there is no foamy residue. Pick out the skins and discard. Wrap the drained beans in a clean towel to dry thoroughly.","Measure oil into a 9x13-inch baking dish or foil lined pan. Pour beans into dish, sprinkle with salt and spices. Mix oil and spices well to coat all the beans.","Bake for 45 to 60 minutes, stirring or shaking every 15 minutes. Longer makes more crunch, but watch to prevent burning!"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup","calories":"128.17 kcal","carbohydrateContent":"14.82 g","cholesterolContent":"0.00 mg","fiberContent":"4.83 g","proteinContent":"5.40 g","sodiumContent":"221.72 mg","sugarContent":"2.85 g","fatContent":"5.64 g","saturatedFatContent":"0.45 g"},"notes":"Cool thoroughly before storing in a tightly covered container.\nEat by the 1/4 cup handful, or sprinkle on salads and other dishes for a nice crunch!\nOptional: Sprinkle with Parmesan cheese during the last 10 minutes of baking. But don’t do this earlier, as it can cause chickpeas to burn.","contributor":"USDA Supplemental Nutrition Assistance Program (SNAP)"},
{"slug":"roasted-herb-potatoes","source_url":"https://www.myplate.gov/recipes/roasted-herb-potatoes","name":"Roasted Herb Potatoes","description":"Rosemary adds a delicious flavor and aroma to these potatoes. Enjoy your herb roasted potatoes as a side to your favorite protein food entrée.","ingredients":[{"name":null,"items":["vegetable cooking spray","1 pound potatoes (3 medium or 3 cups cubed)","2 teaspoons vegetable oil (or cooking oil of choice)","1/2 teaspoon rosemary","1/2 teaspoon salt"]}],"directions":[{"name":null,"steps":["Preheat the oven to 450 degrees F.","Coat a baking sheet with vegetable cooking spray.","Wash and peel the potatoes.","Cut the potatoes into 1/2-inch cubes, and put them in a large bowl.","Put the oil, rosemary, and salt in a small bowl. Stir together.","Pour the oil mix over the potatoes. Stir to coat the potatoes evenly.","Spread the potatoes on the baking sheet.","Bake for 25 to 30 minutes, or until lightly browned."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared potatoes","1/6 of recipe"],"calories":"71.29 kcal","carbohydrateContent":"12.93 g","cholesterolContent":"0.00 mg","fiberContent":"1.36 g","proteinContent":"1.53 g","sodiumContent":"203.06 mg","sugarContent":"0.73 g","fatContent":"1.64 g","saturatedFatContent":"0.23 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"roasted-pork-tacos-pico-de-gallo","source_url":"https://www.myplate.gov/recipes/roasted-pork-tacos-pico-de-gallo","name":"Roasted Pork Tacos with Pico de Gallo","description":"Enjoy the bold flavors of roasted pork steak tacos, perfectly complemented by a fresh and zesty pico de gallo. This vibrant dish brings together tender meat ...","ingredients":[{"name":"Tacos","items":["1 pound pork tenderloin","2 tablespoons olive oil","2 teaspoons paprika","1 teaspoon onion powder","1 teaspoon garlic powder","1 teaspoon salt","1 teaspoon black pepper","12 corn tortilla (4\" across)"]},{"name":"Pico de Gallo","items":["3 tomatoes, cut into small cubes","1/2 cup fresh cilantro, chopped","1/2 cup red onion, cut into small cubes","2 serrano peppers, chopped","2 lemons, juiced","Salt and pepper to taste"]}],"directions":[{"name":null,"steps":["Pico de gallo: In a bowl, mix all the ingredients. Season to taste with salt and pepper.","Seasoning: In a small bowl, mix the paprika, onion powder, garlic powder, salt and pepper.","Remove the silver skin from the pork tenderloin, rub it with oil and coat the entire loin with the seasoning.","Place the pork tenderloin on the grill at medium/high heat (400˚F), over indirect heat, for approximately 6 minutes on each side, 18 minutes total.","Cook until it reaches internal temperature of 145˚F with a 3-minute rest. Then chop it into small pieces.","To make the tacos, heat the tortillas and place some pork tenderloin and pico de gallo on top."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"126.03 kcal","carbohydrateContent":"11.24 g","cholesterolContent":"21.33 mg","fiberContent":"1.95 g","proteinContent":"9.96 g","sodiumContent":"244.93 mg","sugarContent":"1.72 g","fatContent":"4.82 g","saturatedFatContent":"1.08 g"},"notes":null,"contributor":"Created by the National Pork Board, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"roasted-potatoes","source_url":"https://www.myplate.gov/recipes/roasted-potatoes","name":"Roasted Potatoes","description":"Everyone loves these roasted potatoes, and they are easy to make.","ingredients":[{"name":null,"items":["3 cups potatoes, chopped into 1-inch cubes","1/2 cup onion, chopped into 1-inch cubes","1/2 cup green pepper, chopped into 1-inch cubes","1 teaspoon garlic, finely chopped","1 teaspoon vegetable oil","1/4 teaspoon salt","1/4 teaspoon pepper","1 tablespoon parsley, finely chopped (optional)","1/2 teaspoon paprika (optional)"]}],"directions":[{"name":null,"steps":["In a medium-sized bowl, mix potatoes, onions, green peppers, and garlic.","Add vegetable oil, salt, and pepper to bowl. If using parsley and paprika, add that too. Mix well.","Cover bowl and refrigerate for 15 minutes.","Preheat oven to 350 °F.","Spread potato mixture evenly on a cookie sheet. Bake for about 35 minutes. Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup","calories":"73.89 kcal","carbohydrateContent":"15.17 g","cholesterolContent":"0.00 mg","fiberContent":"1.76 g","proteinContent":"1.84 g","sodiumContent":"105.58 mg","sugarContent":"1.68 g","fatContent":"0.90 g","saturatedFatContent":"0.14 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"roasted-pumpkin-seed-snack-mix","source_url":"https://www.myplate.gov/recipes/roasted-pumpkin-seed-snack-mix","name":"Roasted Pumpkin Seed Snack Mix","description":"A quick and tasty snack mix that can be tossed together and enjoyed instantly while you are on the go, no cooking required.","ingredients":[{"name":null,"items":["2 cups crispy rice or wheat cereal squares","1/2 cup roasted whole pumpkin seeds","1/3 cup slivered almonds","1/2 cup dried cranberries","1/2 cup raisins"]}],"directions":[{"name":null,"steps":["Mix all ingredients together and serve."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["approx. 1/2 cup","1/8 of recipe"],"calories":"137.45 kcal","carbohydrateContent":"23.69 g","cholesterolContent":"0.00 mg","fiberContent":"2.30 g","proteinContent":"2.95 g","sodiumContent":"77.85 mg","sugarContent":"14.59 g","fatContent":"4.59 g","saturatedFatContent":"0.51 g"},"notes":null,"contributor":"Regional Mental Health Center Cookbook\nRegional Mental Health Center"},
{"slug":"roasted-root-vegetables","source_url":"https://www.myplate.gov/recipes/roasted-root-vegetables","name":"Roasted Root Vegetables","description":"A variety of root vegetables like sweet potatoes, beets, and turnips make this colorful dish festive and nutritious.","ingredients":[{"name":null,"items":["4 root vegetables (choose a variety from potatoes, rutabagas, turnips, parsnips, beets, sweet potatoes, etc.) (medium)","2 carrot (chopped)","1 onion (medium, chopped)","1/4 cup vegetable oil","3 tablespoons Parmesan cheese"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Cut vegetables into large chunks.","Place in a medium-sized bowl and pour oil over top. Add seasonings or Parmesan and mix well.","Spread an even layer on a baking sheet or pan.","Bake for 1 hour or until tender. Check a few vegetables to see if they are tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (297g)","calories":"329.37 kcal","carbohydrateContent":"42.94 g","cholesterolContent":"3.23 mg","fiberContent":"5.25 g","proteinContent":"6.11 g","sodiumContent":"91.60 mg","sugarContent":"4.99 g","fatContent":"15.41 g","saturatedFatContent":"2.61 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"roasted-tomatoes-herbs","source_url":"https://www.myplate.gov/recipes/roasted-tomatoes-herbs","name":"Roasted Tomatoes with Herbs","description":"For a delicious way to enjoy heirloom tomatoes in peak season, here is a great recipe to celebrate your tomato harvest.","ingredients":[{"name":null,"items":["cooking oil spray, as needed","6 medium tomatoes","2 tablespoons olive oil, divided (or cooking oil of choice)","1/2 teaspoon black pepper","1 tablespoon dried parsley","1 tablespoon garlic, minced","2 tablespoons Parmesan cheese"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 degrees F.","Spray a large baking sheet with cooking oil spray.","Cut each tomato in half. Place tomatoes on the sheet, cut side up.","Drizzle tomatoes with 1 tablespoon of oil and season with pepper.","Cook for 30 minutes, or until tomatoes are beginning to brown on the bottom.","Mix the remaining oil, parsley, garlic, and cheese in a small bowl.","Remove tomatoes from the oven and sprinkle the herb mixture over the tomatoes.","Return to oven for another 10 minutes, or until spices begin to brown."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 tomato","calories":"71.26 kcal","carbohydrateContent":"5.05 g","cholesterolContent":"1.43 mg","fiberContent":"0.90 g","proteinContent":"1.69 g","sodiumContent":"36.60 mg","sugarContent":"2.69 g","fatContent":"5.29 g","saturatedFatContent":"1.03 g"},"notes":null,"contributor":"2009 Recipe Calendar\nUniversity of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"round-steak-casserole","source_url":"https://www.myplate.gov/recipes/round-steak-casserole","name":"Round Steak Casserole","description":"A hearty, savory, and delicious dish that is packed with meat, potatoes, and tomatoes that can be easily prepared in a slow cooker.","ingredients":[{"name":null,"items":["2 pounds round steak, cut 1/2 inch thick","1 teaspoon garlic salt","1 medium onion, thinly sliced","3 medium potatoes, peeled and quartered","1 can (14.5 ounces) low-sodium French-style green beans, drained","1 can (10.5 ounces) low-sodium tomato soup","1 can (14.5 ounces) low-sodium tomatoes, peeled and whole"]}],"directions":[{"name":null,"steps":["Season round steak lightly with garlic salt, salt and pepper.","Cut into serving pieces and place in crock pot with sliced onion, which has been separated into rings.","Add potatoes and green beans.","Top with tomato soup and tomatoes.","Cover and cook on Low for 8 hours.","Remove cover during last half-hour if there is too much liquid.","To cook in 2-quart crock pot, reduce ingredients slightly."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"248.63 kcal","carbohydrateContent":"24.47 g","cholesterolContent":"69.96 mg","fiberContent":"4.15 g","proteinContent":"27.86 g","sodiumContent":"203.55 mg","sugarContent":"6.33 g","fatContent":"4.18 g","saturatedFatContent":"1.61 g"},"notes":"Menu Idea: round steak casserole, canned pears, lowfat milk","contributor":"For Cooking Without Looking, Use a Crock Pot\nUniversity of Wisconsin Cooperative Extension Service\nDunn County UW-Extension Nutrition Education Program"},
{"slug":"salad-pineapple-nuts-and-raisins","source_url":"https://www.myplate.gov/recipes/salad-pineapple-nuts-and-raisins","name":"Salad with Pineapple, Nuts, and Raisins","description":"This dish is overflowing with fresh veggies and fun flavors. Pineapple adds extra tang.","ingredients":[{"name":null,"items":["2 cups mixed salad greens","1 cup vegetables, chopped (tomatoes, cucumbers, carrots, green beans)","1 cup canned pineapple chunks (in juice), drained (or fresh orange segments)","1 1/2 teaspoons white vinegar","1/16 cup orange juice (1 tablespoon)","1/4 cup fat-free fruit-flavored yogurt","2 tablespoons nuts, chopped","2 tablespoons raisins (or dried cranberries)"]}],"directions":[{"name":null,"steps":["Put mixed salad greens on a large platter or in a salad bowl.","In a large bowl, mix chopped vegetables and pineapple or orange segments. Spoon onto the mixed greens.","Mix vinegar, orange juice, and yogurt in a small bowl and pour dressing over salad greens and vegetables.","Top with nuts and raisins. Serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared salad","1/4 of recipe"],"calories":"98.02 kcal","carbohydrateContent":"17.33 g","cholesterolContent":"0.31 mg","fiberContent":"1.83 g","proteinContent":"2.76 g","sodiumContent":"38.26 mg","sugarContent":"13.96 g","fatContent":"2.69 g","saturatedFatContent":"0.38 g"},"notes":"Tomatoes used in nutrition and cost analysis for vegetables.","contributor":"California 5 A Day, It’s So Easy, Adapted from Oprah''s Outtasight Salad\nContra Costa Health Services"},
{"slug":"salata-ma-jibna-salad-parmesan-cheese","source_url":"https://www.myplate.gov/recipes/salata-ma-jibna-salad-parmesan-cheese","name":"Salata Ma Jibna (Salad with Parmesan Cheese)","description":"Onions, carrots, and cabbage give this dish a crunchy and crisp texture. Lemon juice and vinegar give the veggies a tangy flavor. Enjoy along side of your fa...","ingredients":[{"name":null,"items":["1 cup onions, cut into slivers or thin slices","1 cup cabbage, cut into slivers or thin slices","1/2 cup carrots, cut into very thin slices","1 cup tomatoes, diced","1/4 cup olive oil","1/4 cup lemon juice","2 tablespoons white vinegar","1 teaspoon salt","1/4 teaspoon black pepper","1 clove garlic, minced","1/4 cup parmesan cheese, grated"]}],"directions":[{"name":null,"steps":["In a salad bowl, combine onions, cabbage, carrots, and tomatoes.","Toss with olive oil, lemon juice, vinegar, salt, and pepper.","Sprinkle garlic and Parmesan over salad."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (83g)","calories":"94.11 kcal","carbohydrateContent":"4.80 g","cholesterolContent":"2.15 mg","fiberContent":"1.18 g","proteinContent":"1.38 g","sodiumContent":"340.65 mg","sugarContent":"2.61 g","fatContent":"7.84 g","saturatedFatContent":"1.52 g"},"notes":"Salata Ma Jibna is a Sudanese dish.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"salmon-burgers-and-sweet-potato-oven-fries","source_url":"https://www.myplate.gov/recipes/salmon-burgers-and-sweet-potato-oven-fries","name":"Salmon Burgers and Sweet Potato Oven Fries","description":"A colorful, casual meal that''s surprising simple to prepare.","ingredients":[{"name":"For the Sweet Potato Oven Fries","items":["4 large low sodium sweet potatoes (yams)","1 1/2 tablespoons canola oil"]},{"name":"For the Salmon Burgers","items":["1 can 14.75-ounce pink or red salmon","2 green onions, chopped","1/2 cup chopped red bell pepper","8 crackers, unsalted tops (saltine-like), crushed","2 teaspoons lemon juice","2 egg whites from 2 eggs, whisked","2 tablespoons plain low-fat yogurt","1/4 teaspoon ground black pepper","cooking spray","4 whole-wheat buns","8 leaves Bibb lettuce","2 medium tomatoes (sliced)","1 tablespoon lemon pepper seasoning blend (low sodium)"]}],"directions":[{"name":null,"steps":["Place oven rack in center, heat oven to 425 °F.","Wash and scrub sweet potatoes, slice into wedges, length-wise.","In a large bowl, toss potato wedges with canola oil and seasoning.","Spread on cookie sheet. Roast in the oven, turning occasionally, until tender and golden brown, about 30 to 40 minutes.","While sweet potatoes are roasting, prepare salmon burgers. Drain salmon; place in a medium mixing bowl and flake.","Fold in green onions and red pepper, crushed crackers, lemon juice, egg whites, and yogurt.","Shape into 4 patties.","Coat large nonstick skillet lightly with cooking spray; heat.","Cook salmon burgers until golden brown, turn, and continue cooking until other side is golden brown.","Serve burgers with sliced tomatoes and lettuce, and sweet potato oven fries."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"540.02 kcal","carbohydrateContent":"71.70 g","cholesterolContent":"87.61 mg","fiberContent":"10.38 g","proteinContent":"36.74 g","sodiumContent":"735.84 mg","sugarContent":"19.19 g","fatContent":"12.72 g","saturatedFatContent":"1.90 g"},"notes":"Serving Suggestions: Serve with a glass of 100% berry juice blend.","contributor":"Produce for Better Health Foundation"},
{"slug":"salmon-burgers","source_url":"https://www.myplate.gov/recipes/salmon-burgers","name":"Salmon Burgers","description":"This simple recipe makes good use of canned salmon, or you can also use leftover salmon if you have some on-hand. Out of both? Try canned tuna!","ingredients":[{"name":null,"items":["1 2/3 cups cracker crumbs, coarse","1 small onion, chopped","1 can (16 ounces) salmon (OR two 5 oz cans of tuna in water, drained)","2/3 cup low-fat milk","2 eggs, well beaten","celery (1/2 cup chopped, optional)","salt & pepper (to taste)"]}],"directions":[{"name":null,"steps":["In a large bowl, mix all ingredients together. Mixture will be moist.","Spray a large skillet with non-stick cooking spray. Heat skillet.","Drop fish mixture onto the skillet using a 1/3 or 1/2 cup measuring cup. Brown on both sides."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 burger","calories":"198.29 kcal","carbohydrateContent":"13.96 g","cholesterolContent":"127.96 mg","fiberContent":"0.81 g","proteinContent":"21.74 g","sodiumContent":"427.93 mg","sugarContent":"2.99 g","fatContent":"6.09 g","saturatedFatContent":"1.45 g"},"notes":"*Dry bread crumbs, crushed unsweetened cereal, or uncooked oatmeal can be used instead of cracker crumbs.","contributor":"University of Nebraska at Lincoln\nNebraska Nutrition Education Program"},
{"slug":"salmon-loaf","source_url":"https://www.myplate.gov/recipes/salmon-loaf","name":"Salmon Loaf","description":"This delicate salmon loaf is lower in calories than traditional meat loaf, and pairs well with steamed spinach or broccoli and roasted sweet potatoes.","ingredients":[{"name":null,"items":["1 can (16 ounces) salmon","2 cups bread crumbs, soft","1 large onion, chopped","1 tablespoon margarine, melted","1/4 cup celery, diced","1 cup 1% low fat milk","1 tablespoon lemon juice","1 teaspoon dried parsley","2 large eggs"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 degrees F.","Drain salmon and remove skin if desired. Mash bones with meat.","Add the other ingredients.","Add enough milk so that the mixture is moist but not runny.","Place in a lightly oiled 9x5 inch loaf pan.","Bake for 45 minutes.","Serve."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"226.92 kcal","carbohydrateContent":"23.16 g","cholesterolContent":"96.49 mg","fiberContent":"1.61 g","proteinContent":"19.36 g","sodiumContent":"439.97 mg","sugarContent":"4.10 g","fatContent":"6.26 g","saturatedFatContent":"1.51 g"},"notes":null,"contributor":"Wellness Ways Resource Book\nUniversity of Illinois Extension Service"},
{"slug":"salmon-patties","source_url":"https://www.myplate.gov/recipes/salmon-patties","name":"Salmon Patties","description":"Tasty patties cooked in a skillet that are perfect topped with fresh lettuce, tomato, and a side of fresh or canned pineapple.","ingredients":[{"name":null,"items":["1 can salmon, 16 oz","1 tablespoon lemon juice","cold water","minced celery (1/4 cup, optional)","green pepper (1 tablespoon, optional)","1/2 medium onion","2 large eggs","1/3 cup bread crumbs or cracker crumbs","2 tablespoons all-purpose flour","1/8 teaspoon black pepper","1 tablespoon vegetable oil"]}],"directions":[{"name":null,"steps":["Wash fresh vegetables (if using).","Collect, mince, and measure all ingredients before starting to prepare the recipe.","Open salmon, and drain liquid into a liquid measuring cup. Add lemon juice and cold water to the salmon liquid to make 1/2 cup liquid total, and set aside.","Put the salmon in a separate mixing bowl. Mix in the celery (if using), green pepper (if using), and onion.","In another small bowl, beat the eggs. Then, add them to the salmon mixture.","Add the bread or cracker crumbs, flour, pepper, and the salmon liquid mixture to the salmon mixture, and stir until all ingredients are mixed together.","Use 1/3 cup measuring cup to measure salmon mixture. Shape into a 1/2 inch thick patty, and place on a plate. Repeat to make 6 patties.","Heat the oil in a skillet over medium heat, then add 3 patties.","Cook for about 2 to 3 minutes (or until golden brown) on each side.","Remove patties from skillet, and place on a clean paper towel-lined plate to drain. Cook remaining 3 patties, then serve immediately. Refrigerate leftovers within 2 hours. Eat within 3 to 5 days."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 patty","calories":"178.48 kcal","carbohydrateContent":"7.76 g","cholesterolContent":"126.60 mg","fiberContent":"0.58 g","proteinContent":"20.50 g","sodiumContent":"330.77 mg","sugarContent":"0.97 g","fatContent":"7.30 g","saturatedFatContent":"1.29 g"},"notes":"Other optional additions to patties: 1/2 teaspoon lemon pepper, 1/4 cup finely minced celery, 1 tablespoon finely minced bell pepper, 1/3 cup chopped onion, and/or 4 green onions, finely chopped.\nBe Creative! Top with salsa or Pico de Gallo!","contributor":"Eat for Health Toolkit\nRecipe by Missouri Nutrition Network\nOptional additions from ONIE Project & Colorado State University Extension"},
{"slug":"salmon-spread","source_url":"https://www.myplate.gov/recipes/salmon-spread","name":"Salmon Spread","description":"A zesty spread that is perfect as a snack. Serve with whole grain bread, crackers, or rice cakes.","ingredients":[{"name":null,"items":["1 can (16 ounces) salmon","1 tablespoon lemon juice","1 tablespoon horseradish","1 cup fat free plain yogurt","1 tablespoon dill weed, dried","4 green onion, chopped (or 1/4 cup onion, or onion powder to taste)","parsley, for garnish"]}],"directions":[{"name":null,"steps":["Drain salmon and flake with a fork into a bowl.","Mix in all other ingredients.","Serve on bread, crackers, or a rice cake.","Sprinkle chopped parsley to garnish."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/4 cup prepared spread","1/7 of recipe"],"calories":"106.58 kcal","carbohydrateContent":"3.96 g","cholesterolContent":"50.50 mg","fiberContent":"0.36 g","proteinContent":"17.04 g","sodiumContent":"265.06 mg","sugarContent":"3.11 g","fatContent":"2.64 g","saturatedFatContent":"0.50 g"},"notes":null,"contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"salsa-pinto-beans","source_url":"https://www.myplate.gov/recipes/salsa-pinto-beans","name":"Salsa Pinto Beans","description":"Spicy, savory beans make a great fiber-filled side dish.","ingredients":[{"name":null,"items":["1 tablespoon olive oil (or cooking oil of choice)","1 medium onion, chopped","1 clove garlic, minced (or 1/8 teaspoon garlic powder)","2 cans (15 ounces each) low-sodium pinto beans, drained and rinsed","1 cup salsa"]}],"directions":[{"name":null,"steps":["Heat the oil in a skillet over medium heat.","Add the onion and garlic and cook until tender.","Stir in the beans and salsa.","Cook for 10 minutes.","Serve over rice, pasta, or baked potato."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"135.86 kcal","carbohydrateContent":"22.43 g","cholesterolContent":"0.00 mg","fiberContent":"6.52 g","proteinContent":"6.28 g","sodiumContent":"336.16 mg","sugarContent":"2.91 g","fatContent":"2.77 g","saturatedFatContent":"0.48 g"},"notes":null,"contributor":"2009 Recipe Calendar\nUniversity of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"salsa1","source_url":"https://www.myplate.gov/recipes/salsa1","name":"Salsa","description":"This fresh tasting salsa is easy to whip up for your next get together.","ingredients":[{"name":null,"items":["2 cans (14.5 ounces) low-sodium diced tomatoes, drained","1 can (4.5 ounces) diced green chiles, drained","1/4 cup green onion, sliced","1/4 cup fresh cilantro, chopped","2 tablespoons lemon or lime juice","1/8 teaspoon black pepper","1 garlic clove, minced"]}],"directions":[{"name":null,"steps":["In a large bowl, stir together all the ingredients until well mixed. Cover and chill at least 4 hours.","Serve with Baked Tortilla Chips or raw vegetables."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 Cup","calories":"35.23 kcal","carbohydrateContent":"7.78 g","cholesterolContent":"0.00 mg","fiberContent":"3.71 g","proteinContent":"1.64 g","sodiumContent":"107.83 mg","sugarContent":"4.48 g","fatContent":"0.51 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"Nebraska SNAP-Ed, Adapted from Easy No-Cook Salsa"},
{"slug":"salt-free-all-purpose-blend","source_url":"https://www.myplate.gov/recipes/salt-free-all-purpose-blend","name":"Salt-free All Purpose Blend","description":"There are endless options for where you would want to add this seasoning blend -- rice, meat, fish, vegetables, and more! Try on your favorite dish to boost ...","ingredients":[{"name":null,"items":["2 tablespoons dried onion","2 tablespoons garlic powder","1 tablespoon paprika","1 1/2 teaspoons thyme","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Mix all ingredients in a small bowl, using a spoon.","Place mix into a container that allows you to shake to dispense."]}],"yield":"68 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 teaspoon","calories":"1.69 kcal","carbohydrateContent":"0.37 g","cholesterolContent":"0.00 mg","fiberContent":"0.08 g","proteinContent":"0.07 g","sodiumContent":"0.28 mg","sugarContent":"0.06 g","fatContent":"0.02 g","saturatedFatContent":"0.00 g"},"notes":null,"contributor":"Eat Smart New York!\nCornell University Cooperative Extension"},
{"slug":"sanchico-tuna-salad","source_url":"https://www.myplate.gov/recipes/sanchico-tuna-salad","name":"Sanchico Tuna Salad","description":"This tuna salad gets its creamy flavor from the avocado and a slight punch from the crushed red pepper.","ingredients":[{"name":null,"items":["1 can chunk light tuna (in water, 6.5 ounce can)","1 large avocado (diced)","1 cup Roma tomatoes (diced)","1/4 cup red onion (diced)","2 teaspoons lime juice","1 teaspoon crushed red pepper","1/4 teaspoon salt","1/2 large firm mango (diced)"]}],"directions":[{"name":null,"steps":["Drain tuna. Transfer to a mixing bowl and mix well with avocado for texture.","Add tomatoes, onion, lime juice, crushed red pepper, salt, and mango."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"114.88 kcal","carbohydrateContent":"10.29 g","cholesterolContent":"10.35 mg","fiberContent":"3.90 g","proteinContent":"6.89 g","sodiumContent":"215.35 mg","sugarContent":"5.65 g","fatContent":"6.03 g","saturatedFatContent":"0.90 g"},"notes":null,"contributor":"Houston Food Bank\nChef Jose Montoya"},
{"slug":"sarahs-green-bean-casserole","source_url":"https://www.myplate.gov/recipes/sarahs-green-bean-casserole","name":"Sarah’s Green Bean Casserole","description":"This is a healthier version of my mom’s green bean casserole recipe. My version has more vegetables and almost half the sodium per portion. The secret...","ingredients":[{"name":null,"items":["4 cups fresh green beans (trimmed)","1 cup onion (diced)","2 cups mushrooms (diced)","1 tablespoon butter","2 tablespoons flour","1 cup skim milk","1 tablespoon Worcestershire sauce","1/8 teaspoon black pepper","1/8 teaspoon garlic powder","3/4 teaspoon salt","16 low sodium whole wheat crackers","1 teaspoon olive oil","1/2 teaspoon onion powder"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 °F.","Blanch the green beans in boiling water for about 4 minutes for crisper beans or longer for a softer texture. Then plunge in ice water. Drain and set aside.","Place diced onions and mushrooms in a microwaveable bowl and microwave for about 2 1/2 minutes on high to soften. Set aside.","Melt the butter over medium heat. Once melted, stir in flour with a whisk and cook for about 1 minute (continuously whisking).","Whisk in the milk and cook over low heat until you have a thick white sauce.","Stir in Worcestershire sauce, garlic powder, black pepper, and salt.","Stir the drained green beans, onions, and mushrooms into the white sauce (including any liquid with the onions and mushrooms).","Pour into a casserole dish sprayed with nonstick spray. Crush the crackers and toss cracker crumbs with olive oil and onion powder. Sprinkle over the top of the casserole.","Bake at 350 °F for about 30 minutes or until crackers are golden brown."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 portion of Sarah''s Green Bean Casserole","calories":"109.37 kcal","carbohydrateContent":"16.18 g","cholesterolContent":"4.73 mg","fiberContent":"2.88 g","proteinContent":"3.70 g","sodiumContent":"283.44 mg","sugarContent":"4.47 g","fatContent":"3.97 g","saturatedFatContent":"1.38 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion\nRecipe submitted by Sarah, MyPlate Nutritionist"},
{"slug":"sarahs-spicy-curry-turkey-soup","source_url":"https://www.myplate.gov/recipes/sarahs-spicy-curry-turkey-soup","name":"Sarah’s Spicy Curry Turkey Soup","description":"This turkey curry soup is a fun and flavorful dish to make with turkey dinner leftovers. You can use your leftover cranberry sauce to garnish the soup. A spo...","ingredients":[{"name":null,"items":["1 tablespoon olive oil","1 tablespoon butter","1 cup onion (diced)","1 cup celery (diced)","1/4 teaspoon salt","1/8 teaspoon pepper","2 tablespoons flour","3/4 tablespoon curry powder","1/4 teaspoon cinnamon","4 cups low-sodium chicken broth","2 cups carrots (chopped)","2 cups spinach (chopped)","3 small red potatoes (diced)","3 cups cooked turkey (skin removed, diced)","Optional garnish: cranberry sauce"]}],"directions":[{"name":null,"steps":["Heat the olive oil and butter in a large pot over medium heat. Add the onion and celery and cook for about 7 minutes, stirring occasionally.","Stir in flour, curry powder, and cinnamon and cook for 2 to 3 minutes, stirring constantly.","Pour in chicken broth and scrape up any brown bits at the bottom of the pan.","Bring to a simmer. Then add carrots, spinach, potatoes, and turkey.","Bring to a boil. Then reduce the heat to low.","Simmer (covered) for about 30 minutes, stirring occasionally.","Serve in bowls and garnish with a spoonful of cranberry sauce."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup of Sarah''s Spicy Curry Turkey Soup","calories":"262.00 kcal","carbohydrateContent":"24.92 g","cholesterolContent":"56.82 mg","fiberContent":"3.77 g","proteinContent":"25.81 g","sodiumContent":"305.42 mg","sugarContent":"4.47 g","fatContent":"7.06 g","saturatedFatContent":"2.33 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion\nRecipe submitted by Sarah, MyPlate Nutritionist"},
{"slug":"sardine-cucumber-and-tomato-sandwich","source_url":"https://www.myplate.gov/recipes/sardine-cucumber-and-tomato-sandwich","name":"Sardine, Cucumber, and Tomato Sandwich","description":"Toasted whole grain bread is stacked with cucumbers, sardines, tomato, and sliced red onion. Try canned tuna or salmon as tasty alternatives for sardines.","ingredients":[{"name":null,"items":["8 slices whole-wheat or multigrain bread (toasted)","1 cucumber (peeled, if desired, thinly sliced)","2 cans sardines, water packed (4 oz cans, drained)","1/4 cup lemon juice","1 large tomato (thinly sliced)","1 red or white onion (peeled and thinly sliced)"]}],"directions":[{"name":null,"steps":["Put 4 slices toasted bread on the cutting board. Arrange cucumber slices on top of each slice.","Distribute the sardines evenly on top of the cucumber and using the fork, gently mash them. Spread the mashed sardines to cover the cucumber. Squeeze the lemon juice over the sardines.","Put the tomato slices on top of the sardines. Add the red onion. Top with the remaining slices of toast and press down gently to hold the sandwich together.","Cut the sandwich in half and serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"individual sandwich","calories":"326.89 kcal","carbohydrateContent":"44.14 g","cholesterolContent":"53.25 mg","fiberContent":"6.52 g","proteinContent":"20.77 g","sodiumContent":"508.47 mg","sugarContent":"7.83 g","fatContent":"7.52 g","saturatedFatContent":"1.25 g"},"notes":"Canned tuna or salmon can be used instead of sardines","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"sauteed-beet-greens","source_url":"https://www.myplate.gov/recipes/sauteed-beet-greens","name":"Sautéed Beet Greens","description":"Don’t throw away your beet greens! The leafy tops of beets can be so tasty. In this recipe, lemon juice, vegetable oil, and seasonings give them a bold fla...","ingredients":[{"name":null,"items":["2 teaspoons vegetable oil (or cooking oil of choice)","4 cups chopped beet greens (2 bunches with stems removed)","2 cloves garlic, minced (or 1/2 teaspoon garlic powder)","1 teaspoon lemon juice","1/8 teaspoon red pepper flakes","1 pinch salt"]}],"directions":[{"name":null,"steps":["Heat oil in a medium-sized pan over medium heat.","Add the beet greens and garlic to the pan. Stir until just wilted, then reduce the heat to low and stir occasionally until soft, about 5 to 8 minutes.","Stir in lemon juice, red pepper flakes, and salt. Serve right away or use in another recipe."]}],"yield":"3 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/3 cup","calories":"49.49 kcal","carbohydrateContent":"3.84 g","cholesterolContent":"0.00 mg","fiberContent":"2.22 g","proteinContent":"2.05 g","sodiumContent":"65.35 mg","sugarContent":"0.95 g","fatContent":"3.40 g","saturatedFatContent":"0.43 g"},"notes":"No beet greens? Use other leafy greens such as mustard greens or chard.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"sauteed-cabbage-and-onion","source_url":"https://www.myplate.gov/recipes/sauteed-cabbage-and-onion","name":"Sautéed Cabbage and Onion","description":"Cabbage, onion, and caraway seeds make this simple and inexpensive side dish a flavorful way to eat more veggies.","ingredients":[{"name":null,"items":["1 teaspoon vegetable oil","1 onion (sliced)","4 1/2 cups cabbage (sliced)","1/4 teaspoon salt","1/4 teaspoon black pepper","1 teaspoon caraway seeds"]}],"directions":[{"name":null,"steps":["Heat oil in a large sauté pan.","Sauté onion over medium heat, until light brown, about 5 to 6 minutes.","Add sliced cabbage, salt, black pepper, and caraway seeds.","Stir and cook for 30 minutes.","Serve immediately."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"52.79 kcal","carbohydrateContent":"9.70 g","cholesterolContent":"0.00 mg","fiberContent":"3.40 g","proteinContent":"1.82 g","sodiumContent":"167.15 mg","sugarContent":"4.81 g","fatContent":"1.38 g","saturatedFatContent":"0.22 g"},"notes":null,"contributor":"\"Cabbage Comfort\"\nNational Cancer Institute (NCI)\n5 A Day for Better Health Program"},
{"slug":"sauteed-cauliflower-rice","source_url":"https://www.myplate.gov/recipes/sauteed-cauliflower-rice","name":"Sautéed Cauliflower Rice","description":"Cauliflower can be made into a rice alternative with just a few simple ingredients. Make this fresh-tasting side dish by pairing cauliflower with garlic, oni...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1/2 cup diced onion","1 clove garlic, minced (or 1/4 teaspoon garlic powder)","1 medium cauliflower (grated or finely chopped, 4 to 5 cups)","1/2 teaspoon salt","1/4 teaspoon black pepper","1 tablespoon lemon juice or lime juice (optional)","2 tablespoons chopped fresh parsley or cilantro (optional)"]}],"directions":[{"name":null,"steps":["Heat oil in a large skillet or saucepan on medium heat. Add onion and cook until soft, 3 to 5 minutes.","Add garlic, cauliflower, salt, and pepper. Stir until cauliflower is tender, 3 to 5 minutes.","Stir in lemon juice and sprinkle with parsley, if desired. Serve warm."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"78.14 kcal","carbohydrateContent":"9.56 g","cholesterolContent":"0.00 mg","fiberContent":"3.40 g","proteinContent":"3.13 g","sodiumContent":"341.01 mg","sugarContent":"3.69 g","fatContent":"3.94 g","saturatedFatContent":"0.69 g"},"notes":"Use as a side dish or as a base for stir-fries, chili, or anything you might eat with rice.\nAdd any sautéed or roasted vegetables.\nTop with grated or crumbled cheese.\nFreeze extra lemon or lime juice to use later.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"sauteed-walleye-tarragon","source_url":"https://www.myplate.gov/recipes/sauteed-walleye-tarragon","name":"Sautéed Walleye with Tarragon","description":"This pan-seared walleye recipe uses fresh herbs and lemon to bring out the mild flavor and flaky texture of this omega-3-rich white fish.","ingredients":[{"name":null,"items":["2 walleye fillets (4–6 ounces each), thawed and patted dry","salt and ground pepper","1 teaspoon chopped fresh tarragon or parsley (or 1/2 teaspoon dried)","2 tablespoons butter","fresh lemon wedges (optional)"]}],"directions":[{"name":null,"steps":["Season walleye on the flesh side with salt and pepper.","Sprinkle with tarragon or parsley and press lightly into the flesh to help it stick.","Melt the butter in a pan over medium high heat.","Place the fillets seasoned side down in the pan, tilting the pan to make sure the butter surrounds the fillets, and cook for about 3 minutes.","Gently flip the fillets and cook on the second side, about 2 minutes. Walleye should reach a final internal cook temperature of 145 °F as measured with a food thermometer before serving.","Plate and serve immediately with lemon wedges."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"190.18 kcal","carbohydrateContent":"0.41 g","cholesterolContent":"86.97 mg","fiberContent":"0.06 g","proteinContent":"16.89 g","sodiumContent":"312.92 mg","sugarContent":"0.01 g","fatContent":"13.25 g","saturatedFatContent":"7.48 g"},"notes":"This recipe contains one or more ingredients considered to be traditional or indigenous to Native American communities in certain regions across North America.","contributor":"Recipe adapted from Red Lake Nation Fishery"},
{"slug":"savory-bread-pudding-kale-and-butternut-squash","source_url":"https://www.myplate.gov/recipes/savory-bread-pudding-kale-and-butternut-squash","name":"Savory Bread Pudding with Kale and Butternut Squash","description":"Bread, cheese, and kale make up this savory bread pudding. Bake ahead of time and slice for quick meals and snacks.","ingredients":[{"name":null,"items":["1 teaspoon vegetable oil","1 yellow onion (peeled and chopped)","4 large eggs","2 cups low-fat milk","1/2 cup shredded low-sodium mozzarella or cheddar cheese","4 cups bread (stale or dried)","3 cups chopped raw kale","2 cups frozen butternut squash","1/4 teaspoon Kosher salt"]}],"directions":[{"name":null,"steps":["Preheat the oven to 375 °F. Lightly grease a 2-quart baking pan.","Put a skillet over medium heat and when it is hot, add the oil. Add the onion and cook about 10 minutes, until tender.","While the onion is cooking, put eggs and milk in a bowl and mix until combined.","Add the cheese, bread, kale, squash, and salt and mix well. Let the mixture stand at least 15 minutes until the bread absorbs most of the milk.","When the onion has finished cooking, add it to the bread mixture and mix well.","Pour the mixture into the prepared pan and transfer to the oven.","Bake uncovered for 50 to 60 minutes until lightly browned and set. Let stand 15 minutes before serving."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"5-6 ounce serving","calories":"327.24 kcal","carbohydrateContent":"36.63 g","cholesterolContent":"219.23 mg","fiberContent":"4.13 g","proteinContent":"19.57 g","sodiumContent":"466.65 mg","sugarContent":"12.17 g","fatContent":"11.73 g","saturatedFatContent":"4.42 g"},"notes":"It is important to use stale bread that has dried out. If you don’t have stale bread, put fresh bread in a preheated 250 °F oven and bake until dried, usually about 15 minutes.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"savory-meatloaf-muffins","source_url":"https://www.myplate.gov/recipes/savory-meatloaf-muffins","name":"Savory Meatloaf Muffins","description":"These savory meatloaf muffins are full of flavor and have a beautiful presentation. Enjoy one with a side of steamed spinach, kale, or a fresh green sal...","ingredients":[{"name":null,"items":["1 large egg","1/2 cup fat free milk","3/4 cup oats","1 pound lean ground beef","3 tablespoons onion, chopped","1/2 teaspoon salt","1/2 cup grated cheese (any variety)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Combine all ingredients and mix well.","Spoon mixture and divide evenly into 12 greased muffin cups.","Bake for 1 hour, or until temperature in center of meatloaf is 160 °F.","Cool slightly before removing from muffin cups."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 muffin meatloaves","1/6 of recipe"],"calories":"203.66 kcal","carbohydrateContent":"8.55 g","cholesterolContent":"88.09 mg","fiberContent":"1.10 g","proteinContent":"18.45 g","sodiumContent":"317.33 mg","sugarContent":"1.39 g","fatContent":"10.28 g","saturatedFatContent":"4.38 g"},"notes":"Combine meatloaf ingredients until well mixed, but don''t over mix; too much mixing can make a meatloaf tough.\nSafety Tip: Cook your meatloaves to 160 °F. Use a meat thermometer to test the temperature. You will know that your loaves will be completely and safely cooked without being dried out from overheating.","contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"savory-spicy-ground-beef-succotash","source_url":"https://www.myplate.gov/recipes/savory-spicy-ground-beef-succotash","name":"Savory and Spicy Ground Beef & Succotash","description":"Ground beef is the surprise ingredient in this savory and spicy succotash dish.","ingredients":[{"name":null,"items":["8 ounces lean ground beef","1 cup frozen lima beans, cooked and drained","1 3/4 cups low-sodium corn (15 1/2 ounce can, drained)","1 can (14.5 ounces) low-sodium tomatoes, broken up","1/4 teaspoon salt","1/4 teaspoon black pepper","1/8 teaspoon nutmeg"]}],"directions":[{"name":null,"steps":["Brown ground beef in 9-inch skillet. Drain excess liquid.","Stir in remaining ingredients except nutmeg. Cover and simmer 5 minutes or until thoroughly heated.","Sprinkle with nutmeg before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"132.96 kcal","carbohydrateContent":"15.44 g","cholesterolContent":"21.27 mg","fiberContent":"3.80 g","proteinContent":"9.62 g","sodiumContent":"152.34 mg","sugarContent":"4.30 g","fatContent":"4.24 g","saturatedFatContent":"1.45 g"},"notes":null,"contributor":"A River of Recipes: Native American Recipes Using Commodity Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"scallion-rice","source_url":"https://www.myplate.gov/recipes/scallion-rice","name":"Scallion Rice","description":"A perfect side dish to your favorite stir-fry recipe. Enjoy the added flavor from the scallions.","ingredients":[{"name":null,"items":["4 1/2 cups brown rice, cooked in unsalted water","1 1/2 teaspoons low-sodium bouillon granules","1/4 cup scallions, chopped"]}],"directions":[{"name":null,"steps":["Cook rice according to directions on the package.","Combine the cooked rice, bouillon granules, and scallions and mix well.","Measure 1-cup portions and serve."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"220.23 kcal","carbohydrateContent":"45.68 g","cholesterolContent":"0.10 mg","fiberContent":"2.95 g","proteinContent":"5.04 g","sodiumContent":"16.45 mg","sugarContent":"0.65 g","fatContent":"1.81 g","saturatedFatContent":"0.49 g"},"notes":null,"contributor":"DASH Eating Plan: Lower Your Blood Pressure\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"scalloped-potatoes-and-chicken-fennel","source_url":"https://www.myplate.gov/recipes/scalloped-potatoes-and-chicken-fennel","name":"Scalloped Potatoes and Chicken with Fennel","description":"We''ve turned scalloped potatoes into a one-dish meal with the addition of chicken and fennel that''s big in flavor but low in fat. The potatoes are first par-...","ingredients":[{"name":null,"items":["4 medium red potatoes (about 1.5 to 2 pounds)","1 fennel bulb with fronds","2 garlic cloves (minced)","2 large chicken breasts","cooking spray","1 1/2 tablespoons margarine or butter (melted)","2 tablespoons flour","1 1/2 cups fat-free (skim) milk (divided)","1/4 teaspoon salt","1/8 teaspoon pepper","1/2 cup reduced-fat sour cream","2 tablespoons Parmesan cheese"]}],"directions":[{"name":null,"steps":["Place rack in center of oven and preheat to 350 °F.","Leaving skin on, thinly slice potatoes.","Cut stalks and fronds from fennel bulb. Discard stalk. Thinly slice fennel bulb. Chop fennel fronts and set aside.","Place potato and fennel slices in 2-quart covered baking dish, and add water to cover vegetables. Cover with lid and microwave on high for about 5 minutes. Let cool slightly and drain vegetables into a colander.","Wipe baking dish dry and spray with cooking spray. Add vegetables back to dish and sprinkle with minced garlic.","Cut chicken breasts in half (total of four pieces). Place atop the potato-fennel mix.","In a bowl, mix melted margarine and flour into a smooth paste. Add 1 1/4 cups skim milk, salt, and pepper, stir until smooth. Pour over chicken, potatoes, and fennel. Cover baking dish and place in oven. Bake about 30 minutes.","Mix remaining milk with sour cream. Increases oven temperature to 425 °F. Remove dish from oven. Spread with sour cream mixture and sprinkle with Parmesan cheese and fennel fronds. Return to oven uncovered and bake an additional 10 minutes until top is golden and bubbling. Internal temperature of chicken should be 165 °F."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"369.01 kcal","carbohydrateContent":"48.42 g","cholesterolContent":"60.46 mg","fiberContent":"5.09 g","proteinContent":"24.02 g","sodiumContent":"354.03 mg","sugarContent":"9.50 g","fatContent":"9.15 g","saturatedFatContent":"3.55 g"},"notes":"Serving Suggestions: Serving with 8 ounce glass of sparkling water and 1/2 orange, sliced.","contributor":"Produce for Better Health Foundation"},
{"slug":"scalloped-potatoes-ii","source_url":"https://www.myplate.gov/recipes/scalloped-potatoes-ii","name":"Scalloped Potatoes II","description":"Enjoy this classic potato dish along side green or orange veggies to keep your plate colorful.","ingredients":[{"name":null,"items":["6 russet potatoes, medium, 3 to 4 inch (peeled and sliced into 1/4 inch slices)","1 cup onion (chopped raw)","2 tablespoons margarine","4 tablespoons flour","1 teaspoon salt","1 dash black pepper","2 cups milk, non-fat"]}],"directions":[{"name":"Quickest Method","steps":["Prepare a large casserole baking pan by coating lightly with oil or cooking oil spray.","Place a layer of potatoes in pan, using approximately 1/4 of potatoes.","Sprinkle layer with 1/4 cup chopped raw onion, 1/2 tablespoon margarine, 1 tablespoon flour, 1/4 teaspoon salt, and sprinkling of black pepper.","Repeat layers, making a total of 4.","Meanwhile heat milk over low heat.","Pour warm milk over all ingredients in casserole dish.","Bake at 350 °F for 1 hour.","Refrigerate leftovers within 2 hours."]},{"name":"Creamiest Method","steps":["Wash hands with soap and water.","Prepare a large casserole baking pan by coating lightly with oil or cooking oil spray.","Make a white sauce by melting margarine in a small pan. Stir in flour. Gradually add milk, stirring constantly.","Cook, stirring constantly, until slightly thickened. Remove from heat.","Add salt and pepper.","Place a layer of potatoes and onion in a prepared casserole pan, using approximately 1/4 of the potatoes and 1/4 cup onion.","Spread with 1/2 cup of the sauce prepared in steps 2 and 3.","Repeat layers, making a total of 4.","Bake at 350 °F for 1 hour.","Refrigerate leftovers within 2 hours."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (315g)","calories":"182.13 kcal","carbohydrateContent":"35.01 g","cholesterolContent":"1.87 mg","fiberContent":"3.31 g","proteinContent":"5.91 g","sodiumContent":"357.32 mg","sugarContent":"5.78 g","fatContent":"2.37 g","saturatedFatContent":"0.51 g"},"notes":"Leave potato skins on for more nutrition!","contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"scalloped-potatoes","source_url":"https://www.myplate.gov/recipes/scalloped-potatoes","name":"Scalloped Potatoes","description":"A hearty side dish that would go well with a flavorful fish recipe and a fresh green salad.","ingredients":[{"name":null,"items":["6 cups potatoes","2 tablespoons margarine","1 cup onions, sliced","3 tablespoons flour","1/4 teaspoon black pepper","2 cups whole milk"]}],"directions":[{"name":null,"steps":["Wash potatoes; peel and slice into thin slices.","Melt 1 tablespoon of margarine in heavy, deep skillet. Remove skillet from heat; spread half of potato slices in skillet.","Cover potatoes with onions. Sprinkle half of flour and pepper over potato mixture.","Add remaining potato slices, flour, and pepper. Cut 1 tablespoon of margarine into small pieces and place on top of potato mixture.","Pour milk over potato mixture; bring to boil over high heat. Reduce heat to medium low, cover, and cook until potatoes are tender, about 15 minutes."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups prepared potatoes","1/4 of recipe (390g)"],"calories":"319.72 kcal","carbohydrateContent":"52.47 g","cholesterolContent":"14.71 mg","fiberContent":"4.90 g","proteinContent":"9.62 g","sodiumContent":"114.14 mg","sugarContent":"9.74 g","fatContent":"8.43 g","saturatedFatContent":"3.20 g"},"notes":"Leave potato skins on for more nutrition!","contributor":"Recipes and Tips for Healthy, Thrifty Meals\nUSDA Center for Nutrition Policy and Promotion"},
{"slug":"scrambled-eggs-vegetables-cheese","source_url":"https://www.myplate.gov/recipes/scrambled-eggs-vegetables-cheese","name":"Scrambled Eggs with Vegetables and Cheese","description":"This zucchini recipe brings you a flavorful dish loaded with vegetables and low-fat dairy.","ingredients":[{"name":null,"items":["2 cups zucchini (chopped)","1/2 cup onion (diced)","1/4 green or red pepper","1 egg","1/4 cup low-fat milk","2 tablespoons canola oil","1 tablespoon garlic and herb seasoning mix","1/4 cup Parmesan cheese","1/4 cup cheese, low-fat shredded (use your favorite)"]}],"directions":[{"name":null,"steps":["Wash and chop zucchini, measure out about 2 cups.","Dice the onion and pepper, set aside along with the zucchini.","Stir the egg and milk together and set aside.","Sauté the vegetables in oil on medium heat. Remove from the pan.","Scramble the egg mixture until cooked thoroughly. Stir in the vegetable mixture and fold together.","Cook together until temperature reaches 145 °F.","Sprinkle the seasoning and cheese on top. When the cheese is melted, serve warm.","Add fresh or other dried herbs as desired."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"151.28"},"notes":null,"contributor":"Original recipe name - Zucchini Recipe"},
{"slug":"scrambled-eggs-with-vegetables-cheese","source_url":"https://www.myplate.gov/recipes/scrambled-eggs%20with-vegetables-cheese","name":"Scrambled Eggs with Vegetables and Cheese","description":"This zucchini recipe brings you a flavorful dish loaded with vegetables and low-fat dairy.","ingredients":[{"name":null,"items":["2 cups zucchini (chopped)","1/2 cup onion (diced)","1/4 green or red pepper","1 egg","1/4 cup low-fat milk","2 tablespoons canola oil","1 tablespoon garlic and herb seasoning mix","1/4 cup Parmesan cheese","1/4 cup cheese, low-fat shredded (use your favorite)"]}],"directions":[{"name":null,"steps":["Wash and chop zucchini, measure out about 2 cups.","Dice the onion and pepper, set aside along with the zucchini.","Stir the egg and milk together and set aside.","Sauté the vegetables in oil on medium heat. Remove from the pan.","Scramble the egg mixture until cooked thoroughly. Stir in the vegetable mixture and fold together.","Cook together until temperature reaches 145 °F.","Sprinkle the seasoning and cheese on top. When the cheese is melted, serve warm.","Add fresh or other dried herbs as desired."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"151.28"},"notes":null,"contributor":null},
{"slug":"scrambled-eggs-zucchini","source_url":"https://www.myplate.gov/recipes/scrambled-eggs-zucchini","name":"Scrambled Eggs and Zucchini","description":"This zucchini recipe brings you a flavorful dish loaded with vegetables and low-fat dairy.","ingredients":[{"name":null,"items":["2 cups zucchini (chopped)","1/2 cup onion (diced)","1/4 green or red pepper","1 egg","1/4 cup low-fat milk","2 tablespoons canola oil","1 tablespoon garlic and herb seasoning mix","1/4 cup Parmesan cheese","1/4 cup cheese, low-fat shredded (use your favorite)"]}],"directions":[{"name":null,"steps":["Wash and chop zucchini, measure out about 2 cups.","Dice the onion and pepper, set aside along with the zucchini.","Stir the egg and milk together and set aside.","Sauté the vegetables in oil on medium heat. Remove from the pan.","Scramble the egg mixture until cooked thoroughly. Stir in the vegetable mixture and fold together.","Cook together until temperature reaches 145 °F.","Sprinkle the seasoning and cheese on top. When the cheese is melted, serve warm.","Add fresh or other dried herbs as desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"149.99 kcal","carbohydrateContent":"5.65 g","cholesterolContent":"61.03 mg","fiberContent":"0.99 g","proteinContent":"6.45 g","sodiumContent":"150.92 mg","sugarContent":"3.39 g","fatContent":"11.55 g","saturatedFatContent":"2.82 g"},"notes":null,"contributor":"Original recipe name - Zucchini Recipe"},
{"slug":"scrambled-tofu","source_url":"https://www.myplate.gov/recipes/scrambled-tofu","name":"Scrambled Tofu","description":"Scrambled tofu is a powerful protein packed dish for any meal of the day. Add your favorite veggies for increased flavor and crunch.","ingredients":[{"name":null,"items":["1 package tofu (14 ounces)","1 tablespoon butter","2 cups bean sprouts (10 ounces)","2 eggs","salt and pepper (optional, to taste)"]}],"directions":[{"name":null,"steps":["Drain tofu.","In small bowl, dice or mash tofu. For optional ingredients, crush garlic and/or slice watercress, mushrooms, cheese, bell peppers, and green onions.","In a pan, melt butter. Add tofu. Add bean sprouts and optional ingredients. Saute over medium heat until lightly browned.","Beat eggs and add to tofu mixture. Cook until firm.","Sprinkle with salt and pepper to taste.","Stir and cook until firm."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"157.06 kcal","carbohydrateContent":"4.09 g","cholesterolContent":"110.38 mg","fiberContent":"1.80 g","proteinContent":"14.40 g","sodiumContent":"39.31 mg","sugarContent":"2.62 g","fatContent":"10.67 g","saturatedFatContent":"3.53 g"},"notes":"Optional ingredients: garlic, watercress, mushrooms, cheese, bell peppers, green onions, and chop suey mix.","contributor":"University of Hawaii at Manoa Cooperative Extension"},
{"slug":"seared-greens","source_url":"https://www.myplate.gov/recipes/seared-greens","name":"Seared Greens","description":"This quick and delicious way to cook greens will give you a tasty side dish in minutes.","ingredients":[{"name":null,"items":["8 cups kale or collard greens (1 1/2 pounds)","2 tablespoons vegetable oil (or cooking oil of choice)","4 garlic cloves, chopped","1 cup water","1/4 teaspoon salt","1 teaspoon black pepper","2 tablespoons cider vinegar"]}],"directions":[{"name":null,"steps":["Clean the greens thoroughly and cut stems away. Dry well and tear into salad pieces or slice across leaf into 1/2 inch pieces.","In a large deep pot or skillet with a cover, sauté garlic in oil over medium heat.","Add greens in pan with 1 cup water.","Cover pan and steam for 4 minutes.","Uncover, stir constantly until greens shrink. Add salt and pepper and continue to stir on high until mixture is thoroughly wet.","Sprinkle cider vinegar on mixture. Cover.","Turn off heat. Let stand until ready to serve."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"63.79 kcal","carbohydrateContent":"2.60 g","cholesterolContent":"0.00 mg","fiberContent":"1.77 g","proteinContent":"1.32 g","sodiumContent":"121.43 mg","sugarContent":"0.36 g","fatContent":"5.28 g","saturatedFatContent":"0.72 g"},"notes":"You can also try this recipe using turnip greens, mustard greens, spinach, swiss chard, or beet greens.","contributor":"USDA Food and Nutrition Service\nTeam Nutrition"},
{"slug":"seasoned-roasted-vegetables","source_url":"https://www.myplate.gov/recipes/seasoned-roasted-vegetables","name":"Seasoned Roasted Vegetables","description":"Italian salad dressing brings flavor to this veggie dish that cooks in just half and hour in the oven. Pairs well with fish, chicken, or tofu.","ingredients":[{"name":null,"items":["2 medium zucchinis, washed and sliced","2 medium yellow squashes, washed and sliced","4 medium potatoes, scrubbed and sliced","1/2 onion, peeled and sliced","1/2 medium bell pepper (green or red), washed, seeded, and sliced","1/4 cup fat free Italian salad dressing"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Stir vegetables and dressing in large bowl.","Spread vegetables in the center sheet of aluminum foil on top of baking sheet.","Bring together and seal to make packet.","Bake for 20 to 30 minutes."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup","calories":"170.85 kcal","carbohydrateContent":"37.62 g","cholesterolContent":"0.23 mg","fiberContent":"5.07 g","proteinContent":"5.52 g","sodiumContent":"153.17 mg","sugarContent":"7.76 g","fatContent":"0.77 g","saturatedFatContent":"0.22 g"},"notes":null,"contributor":"University of Maryland Cooperative Extension\nSNAP-Ed Program"},
{"slug":"sensational-six-layer-dinner","source_url":"https://www.myplate.gov/recipes/sensational-six-layer-dinner","name":"Sensational Six-Layer Dinner","description":"Savor this delicious casserole that will satisfy your comfort food cravings. This is a great weeknight dinner that''s perfect to serve your family or your gue...","ingredients":[{"name":null,"items":["2 potatoes (medium, sliced)","2 cups carrot (sliced)","1/4 teaspoon black pepper","1/2 cup onion (sliced)","1 pound ground beef, 90% lean (browned and drained)","1 1/2 cups green beans","1 can tomato soup, low-sodium"]}],"directions":[{"name":null,"steps":["Lightly oil or spray baking dish with cooking spray.","Layer ingredients in order given. Cover.","Bake at 350 °F for 45 minutes or until tender and thoroughly heated.","Uncover and bake 15 more minutes."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"218.29"},"notes":"For variation, use peas or corn instead of green beans. Use your favorite cream soup instead of tomato soup.","contributor":"One Dish Meals\nUniversity of Wisconsin Cooperative Extension Service\nA Family Living Program"},
{"slug":"sesame-turnips-and-carrots","source_url":"https://www.myplate.gov/recipes/sesame-turnips-and-carrots","name":"Sesame Turnips and Carrots","description":"This quick and easy recipe uses carrots and turnips for a warm, fall flavor. Garlic and honey (or brown sugar) work together to create a sweet and savory ble...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","2 medium turnips, cut into 1/4-inch cubes","2 medium carrots, cut into 1/4-inch cubes","1/8 teaspoon salt","4 cloves garlic, minced (or 1 teaspoon garlic powder)","2 tablespoons sesame seeds","3 tablespoons honey* (or brown sugar)"]}],"directions":[{"name":null,"steps":["In a large skillet on medium-high heat, add oil and sauté turnips, carrots, and salt until vegetables begin to soften.","Stir in garlic and sesame seeds and cook until vegetables begin to brown.","Stir in honey. Serve warm."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"87.38 kcal","carbohydrateContent":"12.88 g","cholesterolContent":"0.00 mg","fiberContent":"1.68 g","proteinContent":"1.16 g","sodiumContent":"72.40 mg","sugarContent":"10.29 g","fatContent":"4.05 g","saturatedFatContent":"0.57 g"},"notes":"*Children under the age of one should not consume honey.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"shake-pudding","source_url":"https://www.myplate.gov/recipes/shake-pudding","name":"Shake-A-Pudding","description":"A quick and easy dessert that kids will love making. Experiment with different flavors of pudding and fruit combinations.","ingredients":[{"name":null,"items":["2 cups fat-free milk (or 1% low-fat)","1 carton (3.4 ounces) instant vanilla pudding mix","2 bananas, peeled and sliced (or other sliced fruit)"]}],"directions":[{"name":null,"steps":["Place 2 cups of milk in a quart jar with tight-fitting lid.","Add one small package of instant vanilla pudding mix to the jar; screw lid on jar.","Shake until mixture is smooth.","Place pieces of fruit in a serving bowl or paper cups.","Pour pudding over fruit and chill."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"97.95 kcal","carbohydrateContent":"21.65 g","cholesterolContent":"1.83 mg","fiberContent":"0.54 g","proteinContent":"2.33 g","sodiumContent":"198.26 mg","sugarContent":"19.55 g","fatContent":"0.21 g","saturatedFatContent":"0.12 g"},"notes":null,"contributor":"UMass Extension Nutrition Education Program"},
{"slug":"shepherds-pie","source_url":"https://www.myplate.gov/recipes/shepherds-pie","name":"Shepherd''s Pie","description":"This shepherd''s pie recipe is a twist on the classic comfort food. Using frozen veggies helps you get it on the dinner table quickly.","ingredients":[{"name":null,"items":["2 large potatoes, diced","1/3 cup fat-free milk","1/2 pound 85% lean ground turkey","2 tablespoons flour","1 package (10 ounces) frozen mixed vegetables","1 can (14.5 ounces) low-sodium vegetable broth","shredded cheese (optional)"]}],"directions":[{"name":null,"steps":["Place diced potatoes in saucepan. Cover with water and bring to a boil. Reduce heat and simmer (about 15 minutes).","Drain potatoes and mash. Stir in milk and set aside.","Preheat oven to 375 degrees F.","Brown turkey in a large skillet. Stir in flour and cook for 1 minute, stirring constantly.","Add vegetables and broth. Bring to a slow boil.","Spoon vegetable-meat mixture into an 8-inch square baking dish. Spread potatoes over mixture. Bake 25 minutes.","Serve hot. Garnish with shredded cheese (optional)."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"207.56 kcal","carbohydrateContent":"30.39 g","cholesterolContent":"28.45 mg","fiberContent":"4.36 g","proteinContent":"11.22 g","sodiumContent":"90.66 mg","sugarContent":"3.63 g","fatContent":"4.85 g","saturatedFatContent":"1.26 g"},"notes":null,"contributor":"Oklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"shirini","source_url":"https://www.myplate.gov/recipes/shirini","name":"Shirini","description":"A tasty pumpkin dessert that will delight your dinner companions. Be cautious when making the syrup as it will be extremely hot.","ingredients":[{"name":null,"items":["1 1/4 cups granulated sugar","1/2 cup water","4 winter squash (1 1/4 pounds of butternut, acorn, or pumpkin)","1/2 cup chopped walnuts","1/2 teaspoon cinnamon (optional)"]}],"directions":[{"name":null,"steps":["Boil the sugar and water until it forms a thick syrup in a medium saucepan.","Wash the pumpkin, peel it, remove the seeds, cut into pieces, and cook in the syrup until it is very thick and almost all absorbed.","Arrange the pumpkin on a plate and decorate with walnuts and cinnamon (optional)."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"262.46 kcal","carbohydrateContent":"50.06 g","cholesterolContent":"0.00 mg","fiberContent":"3.01 g","proteinContent":"2.24 g","sodiumContent":"2.43 mg","sugarContent":"44.47 g","fatContent":"6.93 g","saturatedFatContent":"0.67 g"},"notes":"Shirin means \"sweet\" in Kurdish. Shirini is a dessert commonly made with milk, dates, cashews, cardamom, and butter.\nFood Safety Tips: Always wash squash, melons, or gourds even if the rind is not to be used. When cut, dirt and microorganisms on the outside could transfer inside to the flesh.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"shorba-lamb-and-peanut-soup","source_url":"https://www.myplate.gov/recipes/shorba-lamb-and-peanut-soup","name":"Shorba (Lamb and Peanut Soup)","description":"A hearty and delightful stew to warm your family''s table. Enjoy this cozy stew with a grapefruit or orange for dessert.","ingredients":[{"name":null,"items":["3 pounds lamb bones (or lean beef ribs)","8 cups water (2 quarts)","salt (2 teaspoons, optional)","1 1/2 cups onions, slightly chopped","1/2 pound carrots, peeled and cut into chunks (3-4 medium carrots or 12 baby carrots)","1 cabbage, cut into small wedges","3 cups string beans, trimmed","3 cloves garlic, chopped finely","4 tablespoons peanut butter (1/4 cup)","1 lemon, juiced (approximately 3 tablespoons)","cooked rice (1/2 cup, optional)"]}],"directions":[{"name":null,"steps":["In a 6-quart saucepan, simmer bones in 2 quarts of water and 2 teaspoons of salt (optional) for one hour.","Add onions, carrots, cabbage, string beans, and garlic.","Simmer for one hour until vegetables are thoroughly cooked.","Remove lamb bones and purée the mixture.","Add 4 tablespoons peanut butter thinned with lemon juice.","Add cooked rice (optional).","Add salt and pepper to taste."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (365g)","calories":"270.41 kcal","carbohydrateContent":"16.87 g","cholesterolContent":"51.61 mg","fiberContent":"5.46 g","proteinContent":"20.10 g","sodiumContent":"116.12 mg","sugarContent":"8.29 g","fatContent":"14.29 g","saturatedFatContent":"4.93 g"},"notes":"Shorba is a Sudanese dish based around lamb. In Sudan, lamb bones commonly are used to flavor the soup-like dish.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"short-cut-lasagna","source_url":"https://www.myplate.gov/recipes/short-cut-lasagna","name":"Short Cut Lasagna","description":"No need to precook the noodles in this easy lasagna. Add a layer of extra veggies if you desire. Spinach would make a fantastic addition.","ingredients":[{"name":null,"items":["1 (24 ounce) jar low-sodium spaghetti sauce","8 ounces dry lasagna noodles","1 (15 ounce) container part-skim ricotta cheese (or cottage cheese)","2 cups part-skim mozzarella cheese, shredded","1/4 cup Parmesan cheese, grated"]}],"directions":[{"name":null,"steps":["Spready 1/2 the sauce on the bottom of a 2-quart baking dish or pan.","Layer half the dry noodles, ricotta, and Parmesan.","Top with 1 cup sauce and layer rest of the noodles, ricotta, and mozzarella.","Top with remaining spaghetti sauce.","Bake 60 minutes at 350 °F. Remove and let is set for 20 minutes. Top with Parmesan cheese."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"418.61 kcal","carbohydrateContent":"44.54 g","cholesterolContent":"49.32 mg","fiberContent":"3.63 g","proteinContent":"25.53 g","sodiumContent":"393.87 mg","sugarContent":"5.55 g","fatContent":"15.58 g","saturatedFatContent":"8.69 g"},"notes":"Add browned, drained meat or cooked vegetables if desired. Mix with middle layer of sauce. Spinach would make a fantastic addition.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"shrimp-confetti-salad-sandwich-grapes","source_url":"https://www.myplate.gov/recipes/shrimp-confetti-salad-sandwich-grapes","name":"Shrimp Confetti Salad Sandwich with Grapes","description":"Grapes are a natural balance to this sweet and savory shrimp salad. Enjoy as a sandwich or over lettuce.","ingredients":[{"name":null,"items":["1/2 pound frozen cooked cocktail shrimp (thawed, peeled, and deveined)","1 8-oz can yellow corn kernels (reduced sodium, drained)","1 cup canned black beans (low sodium, drained and rinsed)","1 stalk celery (diced)","2 tablespoons chopped onion","2 tablespoons reduced-fat mayonnaise","1/2 tablespoon salt-free Caribbean citrus seasoning","8 slices whole-grain bread","2 tomatoes (sliced)","4 leaves Bibb lettuce or other leaf lettuce"]}],"directions":[{"name":null,"steps":["Chop shrimp coarsely.","Mix together shrimp salad ingredients (everything except for the bread, tomato slices, and lettuce).","Divide salad evenly among 4 slices of bread; spread to edges of bread.","Top with tomato slices, lettuce, and second bread slice."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"361.65 kcal","carbohydrateContent":"54.25 g","cholesterolContent":"91.63 mg","fiberContent":"10.55 g","proteinContent":"24.21 g","sodiumContent":"576.65 mg","sugarContent":"8.24 g","fatContent":"5.89 g","saturatedFatContent":"1.10 g"},"notes":"Serving Suggestions: Serve with a glass of non-fat milk and a red grape cluster.\nTips for selecting and storing grapes:\nGrapes are fully ripe when they arrive at the supermarket.\nLook for plump grapes with pliable green stems.\nKeep grapes unwashed and refrigerated in a plastic bag until ready for use. Then rinse with cold water and serve, or add to recipes.","contributor":"Produce for Better Health Foundation"},
{"slug":"simmered-beans","source_url":"https://www.myplate.gov/recipes/simmered-beans","name":"Simmered Beans","description":"Savory simmered beans are simple and satisfying. Enjoy as a side to your favorite entrée.","ingredients":[{"name":null,"items":["2 cups dried beans, rinsed (pinto, black, or pink)","8 cups water","1 onion, chopped","1 bay leaf","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Place beans, water, onion, and bay leaf in a large pot.","Cover and bring to a boil over high heat.","Reduce heat to low. Simmer for 1 to 1 1/2 hours or until beans are tender.","Remove bay leaf and stir in salt. Cook 15 minutes longer.","Top each serving of simmered beans with 1/2 cup fresh salsa, or store beans in refrigerator for up to 3 days in a covered plastic or glass container."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared beans","1/12 of recipe"],"calories":"112.98 kcal","carbohydrateContent":"21.02 g","cholesterolContent":"0.00 mg","fiberContent":"6.98 g","proteinContent":"6.95 g","sodiumContent":"56.99 mg","sugarContent":"0.78 g","fatContent":"0.51 g","saturatedFatContent":"0.11 g"},"notes":null,"contributor":"Healthy Latino Recipes Made with Love\nCalifornia Department of Health Services\nCalifornia Latino 5-A-Day Campaign"},
{"slug":"simple-fish-tacos","source_url":"https://www.myplate.gov/recipes/simple-fish-tacos","name":"Simple Fish Tacos","description":"Seasoned chunks of cod topped with fresh diced tomatoes, shredded cabbage, a squeeze of lime, and a dollop of cilantro-infused sour cream are all served on t...","ingredients":[{"name":null,"items":["1/2 cup fat-free sour cream","1/4 cup fat-free mayonnaise","1/2 cup fresh cilantro, chopped","1/2 packet taco seasoning, divided","1 pound cod or white fish fillets, cut into 1-inch pieces","1 tablespoon olive oil (or cooking oil of choice)","2 tablespoons lemon juice","12 corn tortillas, 6-inch, warmed","2 cups red and green cabbage, shredded","2 cups tomato, diced","lime wedges (for serving, optional)"]}],"directions":[{"name":null,"steps":["In a small bowl, combine sour cream, mayonnaise, cilantro, and 2 tablespoons seasoning mix.","In a medium bowl, combine cod, oil, lemon juice, and remaining seasoning mix; pour into large skillet. Cook stirring constantly, over medium-high heat for 4 to 5 minutes or until cod flakes easily when tested with a fork.","Fill warm tortillas with fish mixture.","Top with cabbage, tomato, sour cream mixture, lime wedges, and taco sauce."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"238.62 kcal","carbohydrateContent":"36.13 g","cholesterolContent":"33.62 mg","fiberContent":"5.48 g","proteinContent":"15.56 g","sodiumContent":"385.87 mg","sugarContent":"4.37 g","fatContent":"4.30 g","saturatedFatContent":"0.67 g"},"notes":null,"contributor":"US Department of Health and Human Services\nCenters for Disease Control and Prevention (CDC)"},
{"slug":"simple-green-smoothie","source_url":"https://www.myplate.gov/recipes/simple-green-smoothie","name":"Simple Green Smoothie","description":"Add kale or spinach to this fruit smoothie for a quick and delicious breakfast or snack.","ingredients":[{"name":null,"items":["1 cup kale or spinach","1 medium banana","1 cup low-fat milk (or fortified soy, coconut, or almond milk)","1 cup plain low-fat yogurt","1 medium apple (cored and sliced)","1 cup frozen fruit (all one fruit or a combination of mixed frozen fruit)","flax seeds, 1 tablespoon (optional)","chia seeds, 1 tablespoon (optional)"]}],"directions":[{"name":null,"steps":["Add the kale or spinach and the liquid of your choice to a blender. Blend.","Add in the rest of the ingredients, blending after each item.","Serve and enjoy, cold.","Reserve the leftover smoothie in the refrigerator for later in the day or the next day."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"283.37 kcal","carbohydrateContent":"51.44 g","cholesterolContent":"13.45 mg","fiberContent":"5.26 g","proteinContent":"11.88 g","sodiumContent":"141.46 mg","sugarContent":"40.25 g","fatContent":"3.65 g","saturatedFatContent":"2.05 g"},"notes":"Consume within 24 hours.","contributor":"Northern Valley Catholic Social Service"},
{"slug":"simple-stuffed-peppers","source_url":"https://www.myplate.gov/recipes/simple-stuffed-peppers","name":"Simple Stuffed Peppers","description":"These simple stuffed peppers are fun and flavorful. Use yellow, red, green, and orange peppers for a colorful dish.","ingredients":[{"name":null,"items":["1 cup brown rice, uncooked","1 can black beans, low sodium (15 ounces)","4 bell peppers (any color)","1 cup cheddar cheese, shredded (reduced fat)","1 tomato, sliced","1 cup salsa","salt (to taste, optional)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 °F.","Cook brown rice according to package directions.","Wash the peppers under running water.","Cut the tops off the peppers and spoon out the seeds.","Drain and rinse the black beans.","Combine the beans, rice, salsa, and salt (optional).","Spoon about 3 tablespoons of the mixture into the bottom of each pepper.","Place a slice of tomato on top of the mixture and sprinkle with 2 tablespoons of cheese.","Repeat steps 8 and 9 to fill the pepper completely, but do not top with cheese.","Bake peppers for 30 minutes.","Top each pepper with 2 tablespoons of cheese and continue baking for 15 minutes more."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"387.82"},"notes":"Green bell peppers used for nutritional analysis and costing purposes.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"simply-satisfying-kale-and-tuna-salad","source_url":"https://www.myplate.gov/recipes/simply-satisfying-kale-and-tuna-salad","name":"Simply Satisfying Kale and Tuna Salad","description":"Even the youngest junior chefs love massaging the kale in this simple salad recipe, which adds canned tuna, tomatoes, and homemade dressing for a refreshing ...","ingredients":[{"name":null,"items":["2 cans tuna (5 ounce cans)","1 bunch kale (or 1 bag)","2 ounces cherry tomatoes","1 lemon, raw","1/4 cup extra virgin olive oil","1/8 cup balsamic vinegar","kosher salt (to taste)","freshly ground pepper (to taste)"]}],"directions":[{"name":null,"steps":["Wash kale. Set aside to drain water off.","Cut tomatoes in half and lightly toss in bowl with balsamic vinegar, oil, and pinch of salt and pepper. Set aside.","In a salad bowl, mix tuna and juice from the can gently with the squeeze of 1/2 lemon and a pinch of pepper.","Massage kale for about 3 minutes to soften it.","Add the kale and 1/2 the tomatoes to the tuna. Gently toss until all is coated with dressing.","Add remaining tomatoes.","Squeeze remaining lemon all over and serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cups","calories":"215.34 kcal","carbohydrateContent":"5.96 g","cholesterolContent":"20.70 mg","fiberContent":"2.26 g","proteinContent":"13.30 g","sodiumContent":"139.04 mg","sugarContent":"1.61 g","fatContent":"15.49 g","saturatedFatContent":"2.42 g"},"notes":null,"contributor":"Seafood Nutrition Partnership"},
{"slug":"skillet-braised-chicken","source_url":"https://www.myplate.gov/recipes/skillet-braised-chicken","name":"Skillet-Braised Chicken","description":"You only need a few simple ingredients to create this delicious, tender chicken. This recipe will yield the perfect chicken every time. Pair with your favori...","ingredients":[{"name":null,"items":["1 medium chicken breast, about 1-inch thick, skinless","1 tablespoon vegetable oil (or cooking oil of choice)","seasoning, such as salt, pepper, seasoning salt, onion powder or garlic powder (optional)"]}],"directions":[{"name":null,"steps":["Season the chicken. In a lightly oiled medium skillet over medium-high heat, sauté the chicken for one minute on each side until lightly browned.","Cover the skillet with a tight-fitting lid. Reduce the heat to low. Cook for 10 minutes. Do not lift the lid.","Turn off the heat. Let the chicken rest for 10 minutes. Do not remove the lid.","The chicken is safely cooked when the internal temperature is at least 165 degrees F. Check in the thickest part with a food thermometer. If not done, cover and return to low heat for 3 to 5 minutes and check for doneness."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 chicken breast","calories":"160.38 kcal","carbohydrateContent":"0.00 g","cholesterolContent":"59.28 mg","fiberContent":"0.00 g","proteinContent":"18.27 g","sodiumContent":"29.09 mg","sugarContent":"0.00 g","fatContent":"9.13 g","saturatedFatContent":"1.42 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"skillet-catfish","source_url":"https://www.myplate.gov/recipes/skillet-catfish","name":"Skillet Catfish","description":"Catfish fillets are coated in a spicy cornmeal rub and pan-fried until browned to perfection. Try substituting with cod or tilapia for delicious variety.","ingredients":[{"name":"For the cornmeal rub","items":["1/8 cup cornmeal","1 teaspoon dried oregano","1/2 teaspoon cayenne pepper","1 teaspoon dried thyme","1 teaspoon paprika","1/2 teaspoon salt","1/2 teaspoon black pepper"]},{"name":"For the catfish","items":["4 4-ounce catfish filets","2 teaspoons vegetable oil","1 lemon or lime (quartered)"]}],"directions":[{"name":null,"steps":["Make the spice rub. Put the cornmeal, oregano, cayenne pepper, thyme, paprika, salt, and pepper on a plate and combine well.","Dredge both sides of the catfish in the spice mixture.","Put the skillet on the stove and turn the heat to high.","When the skillet is hot, add the oil. Add the fish and cook about 4 minutes on each side, until browned and cooked throughout.","Serve right away garnished with lemon or lime wedges."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"4 ounce","calories":"159.50 kcal","carbohydrateContent":"5.72 g","cholesterolContent":"52.39 mg","fiberContent":"1.46 g","proteinContent":"15.32 g","sodiumContent":"392.02 mg","sugarContent":"0.52 g","fatContent":"8.36 g","saturatedFatContent":"1.64 g"},"notes":"Use cod or tilapia instead of catfish.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"skillet-lasagna","source_url":"https://www.myplate.gov/recipes/skillet-lasagna","name":"Skillet Lasagna","description":"An easy lasagna; you don''t even have to turn on your oven! Enjoy with a side salad and seasonal fruit.","ingredients":[{"name":null,"items":["8 ounces lasagna noodles (or 4 cups of any other type of pasta, uncooked)","1 container of ricotta cheese, part-skim, 15 ounces (or cottage cheese)","1/2 cup Parmesan cheese (grated)","1 1/4 tablespoons Italian seasoning","1 jar spaghetti sauce, low-sodium (24 ounces)","1 package frozen spinach, thawed & squeezed dry (10 ounces, or chopped broccoli)","2 cups mozzarella cheese, part-skim shredded"]}],"directions":[{"name":null,"steps":["Cook the noodles as directed on the package. Drain and set aside.","In a small bowl, mix the ricotta cheese (or cottage cheese), 1/4 cup Parmesan cheese, and Italian seasoning.","Spray a large skillet well with cooking spray. Do NOT place skillet on heat until all ingredients are in skillet.","Spread half of the jar of sauce in skillet. Top with half the cooked noodles (4 lasagna noodles).","Spread half of the cheese mixture over the noodles. Top with half the spinach or broccoli.","Sprinkle half the mozzarella cheese over the vegetables.","Repeat with the remaining noodles, the remaining cheese mixture, the remaining vegetables, the remaining sauce, and the remaining mozzarella cheese.","Sprinkle with the rest of the Parmesan cheese. Cover.","Turn on the stove top to medium-low until the cheese is melted (approximately 20 minutes). Allow to stand for 5 minutes before serving.","Refrigerate leftovers within 2 hours. Eat within 3 to 5 days."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/8 of recipe"],"calories":"336.34 kcal","carbohydrateContent":"35.31 g","cholesterolContent":"39.14 mg","fiberContent":"4.04 g","proteinContent":"21.32 g","sodiumContent":"364.61 mg","sugarContent":"4.35 g","fatContent":"12.71 g","saturatedFatContent":"6.98 g"},"notes":"Thaw spinach in the refrigerator overnight or in the microwave on low power. Once thawed, wrap the spinach in a clean towel, and twist to wring out the water.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"skillet-meals","source_url":"https://www.myplate.gov/recipes/skillet-meals","name":"Skillet Meals","description":"A hearty and tasty one-pot dish that can be made in under half an hour. Use leftover brown rice for this recipe.","ingredients":[{"name":null,"items":["1 package broccoli (10 ounce, frozen, can also use mustard greens, collard greens or spinach)","2 cans stewed tomatoes, low sodium (about 30 oz)","1 cup brown rice (cooked)","1 can white beans (15 ounces, rinsed and drained)","black pepper (to taste)","oregano, basil, or hot pepper (other spices to taste, optional)"]}],"directions":[{"name":null,"steps":["Steam greens in the stewed tomatoes using a small pan, pot, or electric skillet on medium-high heat.","Cook greens 10 to 20 minutes, until they are as soft as you like them. Stir gently.","Add the rice, canned beans, and seasonings.","Cook until heated through."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups","1/4 of recipe (453g)"],"calories":"297.12 kcal","carbohydrateContent":"57.31 g","cholesterolContent":"0.00 mg","fiberContent":"14.73 g","proteinContent":"17.02 g","sodiumContent":"409.57 mg","sugarContent":"8.68 g","fatContent":"1.70 g","saturatedFatContent":"0.40 g"},"notes":"Learn morre about:\nBroccoli\nTomatoes\nHerbs","contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"skillet-noodles-and-beef","source_url":"https://www.myplate.gov/recipes/skillet-noodles-and-beef","name":"Skillet Noodles and Beef","description":"A quick and easy weeknight entrée. If you want to give this dish an extra kick, spice with your favorite hot sauce or red pepper flakes.","ingredients":[{"name":null,"items":["1/2 pound lean ground beef","1/2 cup onion, chopped","1 can (15 ounces) low-sodium tomato sauce","1 1/2 cups water","1/4 teaspoon garlic powder","1/4 teaspoon oregano","1/4 teaspoon basil","3 cups noodles, uncooked, 1/2-inch wide","1 package (10 ounces) frozen chopped spinach","1 cup fat-free cottage cheese","1/2 cup part-skim mozzarella cheese, shredded"]}],"directions":[{"name":null,"steps":["Brown ground beef in a large skillet. Drain and rinse to remove fat.","Add onion, tomato sauce, water, and spices. Cover and bring to a boil.","Add noodles. Cover and simmer for 5 minutes.","Defrost spinach in the microwave. Stir spinach into skillet mixture. Cover and simmer for 5 minutes.","Stir mixture. Spoon cottage cheese on top and sprinkle with shredded mozzarella. Cover and simmer for 10 minutes. Add water if mixture gets too dry."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups","1/8 of recipe"],"calories":"154.74 kcal","carbohydrateContent":"16.50 g","cholesterolContent":"33.18 mg","fiberContent":"2.78 g","proteinContent":"12.37 g","sodiumContent":"175.78 mg","sugarContent":"3.12 g","fatContent":"4.84 g","saturatedFatContent":"1.92 g"},"notes":null,"contributor":"University of New Hampshire Cooperative Extension"},
{"slug":"skillet-pasta-dinner","source_url":"https://www.myplate.gov/recipes/skillet-pasta-dinner","name":"Skillet Pasta Dinner","description":"A quick and delicious one-pot meal that is sure to please the whole family. Add your favorite frozen or fresh veggies to this dish.","ingredients":[{"name":null,"items":["1/2 pound 85% lean ground turkey (or ground sausage or beef)","1 medium onion, chopped","2 garlic cloves, minced (approximately 1 teaspoon)","1 can (8 ounces) tomato sauce","1 cup water","8 ounces uncooked tube pasta (ziti, penne, or macaroni)","2 cups fresh or frozen vegetables (try zucchini and carrots)"]}],"directions":[{"name":null,"steps":["Brown the ground meat, onion, and garlic in a large skillet or heavy saucepan. Drain off any grease.","Add the tomato sauce, water, and uncooked pasta.","Cover and simmer for 10 minutes.","Add the fresh or frozen vegetables. Stir and continue cooking until the pasta and vegetables are tender, about 10 more minutes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"296.13 kcal","carbohydrateContent":"45.35 g","cholesterolContent":"28.05 mg","fiberContent":"5.59 g","proteinContent":"15.33 g","sodiumContent":"51.92 mg","sugarContent":"4.87 g","fatContent":"5.84 g","saturatedFatContent":"1.45 g"},"notes":"Frozen vegetables used for nutritional analysis and costing purposes.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"skinny-pizza","source_url":"https://www.myplate.gov/recipes/skinny-pizza","name":"Skinny Pizza","description":"Next time they ask for pizza, you can feel good about saying \"yes!\" Flour tortillas make for a crispy crust, perfect for loading with low-sodium tomato sauce...","ingredients":[{"name":null,"items":["4 6\" flour tortillas","1/2 teaspoon extra virgin olive oil","2 cups sliced mushrooms (white button or baby portobello)","1 green bell pepper, thinly sliced (about 1 cup)","1 red onion, thinly sliced (about 1 cup)","2 teaspoons minced garlic","1/2 cup tomato sauce, no salt added","1/2 cup shredded fat-free mozzarella cheese","2 teaspoons grated reduced-fat Parmesan cheese"]}],"directions":[{"name":null,"steps":["Heat oven to 400°F.","Place tortillas on 2 large baking sheets.","Cook, flipping once, until crisp (about 10 minutes). Set aside.","Meanwhile, heat oil in large skillet over medium heat. Add mushrooms, peppers, onions, and garlic.","Cook until all vegetables are soft and tender (about 10 minutes). Set aside.","Spread tortilla crust with 2 tablespoons tomato sauce, 1/4 cup vegetable mixture, 2 tablespoons mozzarella cheese, and 1/2 teaspoon of Parmesan cheese. Repeat with remaining crusts and topping ingredients.","Transfer pizzas to same baking sheets.","Cook until cheese is melted and edges of tortillas are golden brown (about 10 minutes)."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 pizza","calories":"211.05 kcal","carbohydrateContent":"32.07 g","cholesterolContent":"3.14 mg","fiberContent":"3.64 g","proteinContent":"10.68 g","sodiumContent":"459.94 mg","sugarContent":"6.12 g","fatContent":"4.67 g","saturatedFatContent":"1.56 g"},"notes":"MyPlate Tip: To make \"personalized pizzas,\" set up a pizza-making station in the kitchen. Use low-fat cheese and cut up vegetables or fruits for toppings. Let kids choose their own favorites then pop pizzas into the oven to cook.\nServing Suggestion: Serve pizzas with Citrus Salad for a surprisingly refreshing meal.","contributor":"The Best of La Cocina GOYA: Healthy, Tasty, Affordable Latin Cooking/ Lo Mejor de la Cocina GOYA: Cocina Latina Saludable, Rica y Económica\nGOYA Foods"},
{"slug":"sloppy-garden-joes","source_url":"https://www.myplate.gov/recipes/sloppy-garden-joes","name":"Sloppy Garden Joes","description":"Full of fresh veggie flavor, these sloppy garden joes will be a fast favorite in your home. Serve on a whole wheat bun with a side salad for a complete meal....","ingredients":[{"name":null,"items":["1 medium yellow onion, chopped","1 medium carrot, chopped or shredded","1 medium green pepper, chopped","1 pound 85% lean ground turkey (or chicken)","1 can (8 ounces) low-sodium tomato sauce","1 can (14.5 ounces) whole tomatoes, crushed","4 cans (2 ounces each) mushrooms, drained","1/4 cup barbecue sauce","6 whole wheat buns, split in half to make 12"]}],"directions":[{"name":null,"steps":["Sauté onions, carrots, green pepper, and ground turkey or chicken in a large pan over medium heat for 5 minutes.","Add tomato sauce, crushed tomatoes, mushrooms, barbecue sauce, and bring to boil.","Reduce heat and simmer for 10 minutes, stirring occasionally.","Uncover and cook for an additional 3 minutes or until thick.","Serve open-faced on toasted or plain whole-wheat buns.","Refrigerate leftovers within 2 hours."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 sandwich","calories":"173.35 kcal","carbohydrateContent":"19.69 g","cholesterolContent":"28.05 mg","fiberContent":"2.89 g","proteinContent":"10.05 g","sodiumContent":"342.89 mg","sugarContent":"5.35 g","fatContent":"6.53 g","saturatedFatContent":"1.64 g"},"notes":"You can also use 8 ounce of fresh mushrooms instead of canned.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"slow-cook-barbecue","source_url":"https://www.myplate.gov/recipes/slow-cook-barbecue","name":"Slow-Cook Barbecue","description":"Vinegar, brown sugar, and garlic come together to give this slow cook beef barbecue a sweet and tangy flavor. Serve with a side salad.","ingredients":[{"name":null,"items":["1 1/2 pounds boneless chuck steak, boneless, 1 1/2-inches thick","1 garlic clove, peeled and minced","1/4 cup red wine vinegar","1 tablespoon brown sugar","2 tablespoons Worcestershire sauce","1/4 cup ketchup (add more ketchup if desired)","salt (1 teaspoon, optional)","1 teaspoon dry or prepared mustard","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Cut the beef on a diagonal, across the grain into slices 1 inch wide and place in a slow cooker.","Combine the remaining ingredients and pour over the meat.","Mix the meat and sauce together.","Cover and cook on low for 3 to 5 hours.","Serve on toasted hamburger buns with a mixed green salad."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"269.32 kcal","carbohydrateContent":"7.15 g","cholesterolContent":"89.98 mg","fiberContent":"0.13 g","proteinContent":"31.03 g","sodiumContent":"269.79 mg","sugarContent":"5.39 g","fatContent":"12.59 g","saturatedFatContent":"4.78 g"},"notes":null,"contributor":"Putting Your Crock Pot to Work\nUniversity of Kentucky Cooperative Extension Service"},
{"slug":"slow-cooker-beans","source_url":"https://www.myplate.gov/recipes/slow-cooker-beans","name":"Slow Cooker Beans","description":"These tangy beans cook in a slow-cooker. Serve this dish at your next potluck dinner.","ingredients":[{"name":null,"items":["1 pound pinto beans (16 ounce dried, rinsed)","4 cups hot water","2 onions (chopped)","1 tablespoon chili powder","3/4 cup barbecue sauce","1/2 cup ketchup","1 1/2 tablespoons mustard","2 dashs hot sauce"]}],"directions":[{"name":null,"steps":["Mix beans, water, onion, and chili powder in slow cooker.","Cover and cook on low for 7 hours or until tender. Drain.","Stir in barbecue sauce, ketchup, mustard, and pepper sauce.","Cook on high for 15 minutes or until hot through."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (339g)","calories":"377.42 kcal","carbohydrateContent":"75.72 g","cholesterolContent":"0.00 mg","fiberContent":"11.38 g","proteinContent":"17.71 g","sodiumContent":"652.75 mg","sugarContent":"19.05 g","fatContent":"1.54 g","saturatedFatContent":"0.32 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"slow-cooker-beef-stew","source_url":"https://www.myplate.gov/recipes/slow-cooker-beef-stew","name":"Slow Cooker Beef Stew","description":"Prepare this in the morning and let it cook all day, so that you can enjoy a healthy and hearty dinner as soon as you walk in the door.","ingredients":[{"name":null,"items":["2 pounds stew meat, cut into 1-inch cubes","1/4 cup flour","salt and pepper (optional, to taste)","2 cups water","2 teaspoons beef bouillon (2 cubes)","1 garlic clove, finely chopped","3 medium carrots, sliced","3 medium potatoes, diced","1 onion, chopped","1 celery stalk, sliced","add herbs as desired (bay leaf, basil, oregano, etc.) (optional)"]}],"directions":[{"name":null,"steps":["Place meat in slow cooker.","Mix flour, salt, and pepper in a medium bowl, and pour over meat; stir to coat.","Add remaining ingredients and stir to mix.","Cover and cook on low for 8 to 10 hours or high for 4 to 6 hours.","Stir stew thoroughly before serving. If using bay leaf, discard before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"307.00 kcal","carbohydrateContent":"27.73 g","cholesterolContent":"93.36 mg","fiberContent":"3.39 g","proteinContent":"36.04 g","sodiumContent":"345.89 mg","sugarContent":"3.68 g","fatContent":"5.01 g","saturatedFatContent":"2.04 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"slow-cooker-cheesy-swiss-steak","source_url":"https://www.myplate.gov/recipes/slow-cooker-cheesy-swiss-steak","name":"Slow Cooker Cheesy Swiss Steak","description":"This crock-pot recipe can be cooked for 8-10 hours on the low setting, or for 4-5 hours on the high setting.","ingredients":[{"name":null,"items":["2 pounds beef round roast (1-inch thick)","1/4 cup flour","1/2 teaspoon salt","2 carrots, chopped","1/4 cup onion, chopped","1/2 teaspoon Worcestershire sauce","1 can (8 ounces) tomato sauce, low-sodium","1/2 cup American cheese, shredded"]}],"directions":[{"name":null,"steps":["Cut the beef roast into 4 pieces.","In a small bowl, mix the flour and salt.","Dip each piece of meat into the mix of flour and salt. Coat it on all sides with the mix.","Put the meat in the crock pot.","Add the chopped carrots and onion.","Add the Worcestershire sauce and tomato sauce.","Cover and cook on low for 8-10 hours, OR on high for 4-5 hours.","Just before serving, sprinkle the cheese on top."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"190.58 kcal","carbohydrateContent":"6.88 g","cholesterolContent":"76.38 mg","fiberContent":"1.02 g","proteinContent":"26.59 g","sodiumContent":"333.42 mg","sugarContent":"2.24 g","fatContent":"5.65 g","saturatedFatContent":"2.62 g"},"notes":null,"contributor":"Adapted from: Cheesy Swiss Steak\nPennsylvania Nutrition Education Network"},
{"slug":"slow-cooker-hamburger-stew","source_url":"https://www.myplate.gov/recipes/slow-cooker-hamburger-stew","name":"Slow Cooker Hamburger Stew","description":"Enjoy this hearty stew on a chilly autumn or winter evening. Add black pepper for an extra kick.","ingredients":[{"name":null,"items":["1 pound 90% lean ground beef","1/2 cup onion, chopped","1 cup carrot, chopped","2 cups potatoes, chopped","1 cup celery, chopped","1 can (14.5 ounces) tomatoes","4 cups water","oregano, basil, or other herbs (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Brown ground beef in a medium fry pan. Drain fat.","Place beef, chopped vegetables, tomatoes, and water in slow cooker.","Cook on low 8 to 10 hours or on high for 4 to 6 hours."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"256.94 kcal","carbohydrateContent":"21.90 g","cholesterolContent":"65.73 mg","fiberContent":"4.92 g","proteinContent":"22.75 g","sodiumContent":"237.34 mg","sugarContent":"5.95 g","fatContent":"8.83 g","saturatedFatContent":"3.36 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"slow-cooker-lentil-soup","source_url":"https://www.myplate.gov/recipes/slow-cooker-lentil-soup","name":"Slow Cooker Lentil Soup","description":"Quick to make but rich and delicious flavors of carrots, onion, and celery flavor in this slow cooker lentil soup. Add your favorite spices if you want to ad...","ingredients":[{"name":null,"items":["6 cups water","1/4 cup fresh parsley, chopped (or 2 tablespoons dried)","2 teaspoons beef bouillon (or 2 cubes beef bouillon)","1 1/2 cups dry lentils","2 medium carrots, sliced","1 medium onion, chopped","2 medium celery stalks, sliced"]}],"directions":[{"name":null,"steps":["Mix all ingredients together in slow cooker.","Cook on low for 8 to 10 hours or high for 4 to 5 hours.","Serve hot with crackers or bread."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"182.92 kcal","carbohydrateContent":"32.77 g","cholesterolContent":"0.09 mg","fiberContent":"12.28 g","proteinContent":"13.27 g","sodiumContent":"264.25 mg","sugarContent":"4.80 g","fatContent":"0.72 g","saturatedFatContent":"0.13 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"slow-cooker-pork-stew-over-brown-rice","source_url":"https://www.myplate.gov/recipes/slow-cooker-pork-stew-over-brown-rice","name":"Slow Cooker Pork Stew over Brown Rice","description":"Apple juice and dried fruit add a touch of sweetness to this stew. This dish can be put together in minutes and then left to simmer in your slow cooker. Serv...","ingredients":[{"name":null,"items":["2 pounds lean pork stew meat","3 cups baby carrots","1 large onion, sliced","1 1/2 teaspoons dried thyme leaves","1/2 teaspoon coarse ground black pepper","1/4 teaspoon salt","1 clove garlic, minced","1 1/2 cups complete bran and wheat flakes ready-to-eat cereal (crushed to 3/4 cup)","1 cup dried tart cherries","3/4 cup 100% apple juice or apple cider","4 cups hot cooked brown rice"]}],"directions":[{"name":null,"steps":["Trim fat from pork.","Spray large pan with non-stick cooking spray. Cook half of the pork at a time until browned.","In a 4 to 6 quart crockery cooker, layer carrots, onion, thyme, pepper, salt, and garlic. Sprinkle with cereal and cherries.","Top with pork and pour apple juice or cider over contents in the cooker.","Cover and cook on low for 7 to 8 hours or on high for 3 1/2 to 4 hours.","Prepare the brown rice according to package directions toward the end of the stew cooking time. (Brown rice typically takes about 40 to 45 minutes to cook.)","Stir pork mixture and serve over 1/2 cup brown rice."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"one serving: 1 cup","calories":"412.17 kcal","carbohydrateContent":"56.86 g","cholesterolContent":"63.99 mg","fiberContent":"5.70 g","proteinContent":"29.76 g","sodiumContent":"279.93 mg","sugarContent":"20.29 g","fatContent":"6.87 g","saturatedFatContent":"2.17 g"},"notes":null,"contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"smoked-ham-hocks-lima-beans","source_url":"https://www.myplate.gov/recipes/smoked-ham-hocks-lima-beans","name":"Smoked Ham Hocks with Lima Beans","description":"Try this traditional Southern dish as a soup or serve the beans and meat over a whole grain like brown rice for a more hearty meal.","ingredients":[{"name":null,"items":["1/2 medium onion","2 cloves garlic","2 smoked ham hocks","8 cups water","1 pound frozen lima beans","1/2 teaspoon ground black pepper"]}],"directions":[{"name":null,"steps":["Peel, rinse, and chop onion. Peel and mince garlic.","In a large pot over high heat, add ham hocks and water. Bring to a boil. Reduce heat to a simmer. Add onion and garlic. Cover and cook until meat is tender and internal temperature registers 145°F on a food thermometer, about 30 to 40 minutes.","Transfer ham hocks to a clean cutting board. Let cool.","Add lima beans to pot. Cook according to package directions.","When ham hocks are cool, shred meat from the bone, removing any fat. Return to pot. Stir in pepper. If using salt, stir in now."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"120.95 kcal","carbohydrateContent":"12.38 g","cholesterolContent":"12.81 mg","fiberContent":"3.23 g","proteinContent":"6.73 g","sodiumContent":"230.50 mg","sugarContent":"1.40 g","fatContent":"5.08 g","saturatedFatContent":"1.78 g"},"notes":"Ham hocks may be salty enough already. Taste the dish before adding optional salt.\nServe this traditional southern dish like a soup or use a slotted spoon to take out the beans and meat. Serve over brown rice.\nFor extra flavor and color, add diced carrots and celery.\nUse a leftover meaty ham bone or smoked neck bones in place of the ham hocks.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"smoky-mustard-maple-salmon","source_url":"https://www.myplate.gov/recipes/smoky-mustard-maple-salmon","name":"Smoky Mustard-Maple Salmon","description":"It doesn’t get much easier -- or more delicious -- than this ultra-fast salmon. The sweetness of the maple balances the tangy mustard; smoked paprika or gr...","ingredients":[{"name":null,"items":["3 tablespoons whole-grain or Dijon mustard","1 tablespoon pure maple syrup","1/4 teaspoon smoked paprika or ground chipotle pepper","1/4 teaspoon freshly ground pepper","1/8 teaspoon salt","1 pound salmon (skinless, about 4-ounces per fillet)"]}],"directions":[{"name":null,"steps":["Preheat oven to 450 °F.","Line a baking sheet with foil and coat with cooking spray.","Combine mustard, maple syrup, paprika (or chipotle), pepper, and salt in a small bowl.","Place salmon fillets on the prepared baking sheet.","Spread the mustard mixture evenly on the salmon.","Roast until just cooked through (approximately 8 to 12 minutes)."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"220.09 kcal","carbohydrateContent":"4.12 g","cholesterolContent":"60.73 mg","fiberContent":"0.57 g","proteinContent":"21.82 g","sodiumContent":"260.00 mg","sugarContent":"3.20 g","fatContent":"12.31 g","saturatedFatContent":"2.35 g"},"notes":"Smoked paprika is made from smoke-dried, red peppers and adds earthy, smoky flavor. It can be used in many types of savory dishes. Look for different types of paprika at large supermarkets or online.\nWild-caught salmon from the Pacific (Alaska and Washington) are more sustainably fished and have a larger, more stable population.","contributor":"EatingWell Magazine"},
{"slug":"smothered-greens","source_url":"https://www.myplate.gov/recipes/smothered-greens","name":"Smothered Greens","description":"These greens are delicious. They''re especially wonderful in the cooler months when greens are easily found in your garden or market.","ingredients":[{"name":null,"items":["14 cups mustard greens, or turnip, collard, kale, or mixture (about 2 pounds)","3 cups water","1/4 pound smoked turkey breast, skinless","3 teaspoons hot peppers, freshly chopped","1/4 teaspoon cayenne pepper","1/4 teaspoon ground cloves","2 cloves garlic, crushed","1/2 teaspoon dried thyme","1 scallion stalk, chopped","1 teaspoon ground ginger","1/4 cup onion, chopped"]}],"directions":[{"name":null,"steps":["Prepare greens by washing thoroughly and removing stems.","Tear or slice leaves into bite-sized pieces.","To make the turkey stock, place all ingredients except greens into large saucepan and bring to a boil.","Add greens to turkey stock. Cook 20 to 30 minutes until tender."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup prepared greens","1/5 of recipe"],"calories":"78.30 kcal","carbohydrateContent":"8.46 g","cholesterolContent":"17.38 mg","fiberContent":"4.92 g","proteinContent":"10.89 g","sodiumContent":"68.54 mg","sugarContent":"2.38 g","fatContent":"1.12 g","saturatedFatContent":"0.17 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"snappy-cole-slaw","source_url":"https://www.myplate.gov/recipes/snappy-cole-slaw","name":"Snappy Cole Slaw","description":"Make this coleslaw in a snap. This tasty coleslaw can be doubled easily and made a day in advance to let the flavors blend.","ingredients":[{"name":null,"items":["2 cups cabbage, shredded","1/4 cup cider vinegar","1/4 cup water","2 tablespoons sugar","1/2 teaspoon mustard","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Wash and shred the cabbage with a knife or grater. Put in a mixing bowl.","Bring the vinegar and water to a boil in the saucepan. Remove from heat and add the sugar, mustard, and black pepper to the saucepan.","Continue to cook this mixture in the saucepan until the sugar is dissolved and hot, then pour over the shredded cabbage.","Toss. Refrigerate until chilled to blend flavors."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup coleslaw","1/4 of recipe"],"calories":"40.25 kcal","carbohydrateContent":"9.10 g","cholesterolContent":"0.00 mg","fiberContent":"1.19 g","proteinContent":"0.62 g","sodiumContent":"16.42 mg","sugarContent":"7.75 g","fatContent":"0.09 g","saturatedFatContent":"0.02 g"},"notes":"Refrigeration is needed before serving.","contributor":"Eating Right Is Basic\nMichigan State University Cooperative Extension Service\nNutrition Education Program"},
{"slug":"snappy-rice-dish","source_url":"https://www.myplate.gov/recipes/snappy-rice-dish","name":"Snappy Rice Dish","description":"This recipe can be made in a microwave. Perfect for busy weekdays, this vegetable side dish is full of fiber.","ingredients":[{"name":null,"items":["1 cup vegetables, frozen or fresh, cut into bite-sized pieces","1/2 cup low-sodium chicken broth (or use water)","1 cup brown rice, cooked","1/2 can (15.5 ounces) low-sodium kidney beans (or other canned beans)","dill weed, optional (fresh snipped or dry, to taste)","black pepper, optional (to taste)"]}],"directions":[{"name":null,"steps":["Cook the vegetables in the chicken broth (or water) using a small pan, pot, or electric skillet, on medium-high heat.*","Cook the vegetables the way you like them (firm or soft), stirring gently. Add more broth as needed to keep the vegetables moist.","Add the rice, canned beans, and seasonings. Cook until heated through.","* Microwave version: Follow the same steps above. Use a microwave-safe, covered dish. Stir the vegetables every 2 to 3 minutes. Just before they are cooked, add the rice, beans, and herbs. Cook until heated. Rotate the dish and stir gently."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"276.82 kcal","carbohydrateContent":"53.64 g","cholesterolContent":"0.00 mg","fiberContent":"11.36 g","proteinContent":"12.18 g","sodiumContent":"182.42 mg","sugarContent":"5.15 g","fatContent":"1.83 g","saturatedFatContent":"0.53 g"},"notes":"Try this recipe with peas, corn, carrots, or whatever veggies you like!","contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"soft-chicken-taco","source_url":"https://www.myplate.gov/recipes/soft-chicken-taco","name":"Soft Chicken Taco","description":"Tacos can be served for lunch or dinner. This recipe uses fresh tomato salsa.","ingredients":[{"name":null,"items":["2 chicken breasts, thawed, skin and bone removed from each piece","1/2 teaspoon vegetable oil","1 teaspoon garlic, finely chopped","1/4 teaspoon salt","1/4 teaspoon black pepper","2/3 tablespoon taco seasoning or chili powder (optional)","1 green pepper, sliced","1 medium onion, sliced","4 soft tortillas, 6-inch size","1/4 head Romaine lettuce, sliced thin","1/4 cup tomatoes, diced","4 fresh tomato salsa","1 tablespoon parsley or cilantro, chopped (optional)"]}],"directions":[{"name":null,"steps":["In a large bowl, mix chicken, vegetable oil, garlic, salt, and pepper.","If using taco seasoning or chili powder, add that too.","Cover the bowl with plastic wrap, and place it in the refrigerator for about 30 minutes.","While the chicken is in the refrigerator, cook the pepper and onion on a stovetop over medium heat until done (about 12 minutes).","Cook the chicken over medium heat. Cook each side about 10 to 15 minutes.","Place chicken on a plate. Let it cool for 5 minutes. Cut the chicken into strips.","To make the tacos, put chicken on the tortilla first. Add peppers and onion strips next. Top with lettuce, tomato, and salsa. If using parsley or cilantro, add that too."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 taco","calories":"172.80 kcal","carbohydrateContent":"19.80 g","cholesterolContent":"45.01 mg","fiberContent":"3.31 g","proteinContent":"16.68 g","sodiumContent":"199.92 mg","sugarContent":"3.44 g","fatContent":"3.22 g","saturatedFatContent":"0.60 g"},"notes":"Tip for cooking chicken: The recommended safe minimum internal temperature for chicken is 165°F, as measured by a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"soft-pretzels","source_url":"https://www.myplate.gov/recipes/soft-pretzels","name":"Soft Pretzels","description":"A great snack to make with kids. Perfect to dip in mustard for a savory pretzel, or a low-fat vanilla yogurt for a sweet treat.","ingredients":[{"name":null,"items":["1 tablespoon yeast","1 1/2 cups warm water (100 to 110 °F)","2 cups all-purpose flour","1 1/2 cups whole wheat flour","1 tablespoon sugar","1/2 teaspoon salt","1 egg","sesame seeds (2 tablespoons, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 degrees F. Lightly grease 2 baking sheets.","In large bowl, sprinkle yeast over warm water (if water is too hot, it will kill the yeast). Stir until well blended.","Combine white and wheat flour in a separate bowl.","Stir in sugar, salt and 2 1/2 to 3 cups flour to make a soft, sticky dough. Turn dough onto well-floured surface.","To knead, fold dough in half and push dough flat with heels of hands. Turn dough 1/4 turn. Repeat for 5 to 7 minutes. If needed, add more flour until dough is smooth and elastic. Dough should not stick to hands or counter.","Cut dough into 12 even pieces (about golf-ball sized)."]},{"name":"To Form Pretzels","steps":["Roll one piece of dough into 15 inch long rope.","Cross left side over middle, creating loop.","Fold right side of rope up and over first loop to form pretzel shape."]},{"name":"To Bake","steps":["Place pretzels 3 inches apart on baking sheet. Enlarge holes in pretzels by inserting finger into holes. This will prevent them from closing during baking.","In small bowl, mix egg and 1 tablespoon water together. Brush on pretzels. Sprinkle with sesame seeds.","Bake for 15 to 20 minutes or until golden brown. Best if eaten warm."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 pretzel","calories":"140.22 kcal","carbohydrateContent":"28.18 g","cholesterolContent":"17.13 mg","fiberContent":"2.44 g","proteinContent":"5.05 g","sodiumContent":"106.17 mg","sugarContent":"1.17 g","fatContent":"1.07 g","saturatedFatContent":"0.24 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"somali-summer-salad","source_url":"https://www.myplate.gov/recipes/somali-summer-salad","name":"Somali Summer Salad","description":"A delicious summer salad to serve when summer vegetables are at their peak. Great with grilled meat, fish, and tofu.","ingredients":[{"name":null,"items":["3 tablespoons olive oil (or oil of your choice)","1 tablespoon lemon juice","3 medium apples","2 green peppers","3 medium tomatoes","2 cucumbers","salt and pepper (optional)"]}],"directions":[{"name":null,"steps":["In a large bowl, combine oil and lemon juice.","Dice all the fruits and vegetables and then add to the bowl.","Add salt and pepper to taste (optional).","Serve chilled.","Best served within 24 hours."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (211g)","calories":"116.20 kcal","carbohydrateContent":"16.31 g","cholesterolContent":"0.00 mg","fiberContent":"2.91 g","proteinContent":"1.10 g","sodiumContent":"4.35 mg","sugarContent":"11.89 g","fatContent":"5.62 g","saturatedFatContent":"0.89 g"},"notes":null,"contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"soul-healthy-cornbread","source_url":"https://www.myplate.gov/recipes/soul-healthy-cornbread","name":"Soul-Healthy Cornbread","description":"Serve this sweet cornbread with your favorite savory entrée.","ingredients":[{"name":null,"items":["1 cup cornmeal","1 cup flour (all purpose)","1/2 cup sugar","2 teaspoons baking powder","1/2 teaspoon salt","1 cup low-fat buttermilk","1/2 cup applesauce, unsweetened","4 egg whites (1/2 cup)","2 tablespoons vegetable oil"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F. Lightly spray and 8 inch square pan with vegetable oil cooking spray.","Mix dry ingredients in an medium-sized mixing bowl.","Add the rest of the ingredients and mix well by hand.","Pour the batter into the sprayed pan and shake to make it level.","Bake until a toothpick inserted in the center comes out clean, about 25 minutes.","Allow to cool, then cut into 12 squares."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 2x2 2/3\" piece","1/12 of recipe (76g)"],"calories":"147.72 kcal","carbohydrateContent":"26.67 g","cholesterolContent":"0.82 mg","fiberContent":"1.14 g","proteinContent":"3.77 g","sodiumContent":"232.16 mg","sugarContent":"10.54 g","fatContent":"3.06 g","saturatedFatContent":"0.52 g"},"notes":null,"contributor":"Food and Health Communications, Inc."},
{"slug":"south-border-salad","source_url":"https://www.myplate.gov/recipes/south-border-salad","name":"South of the Border Salad","description":"Make this corn, black bean, and tomato salad in the morning and let it marinate in the refrigerator all day and enjoy it for dinner.","ingredients":[{"name":null,"items":["3 cups low-sodium canned corn (15.25 ounces each - drained and rinsed)","2 cans low-sodium black beans (15.5 ounces each - drained and rinsed)","1 can diced tomatoes with green chilies (10 ounces)","1 medium onion (chopped)"]},{"name":"Dressing Ingredients","items":["3 tablespoons olive oil (or cooking oil of your choice)","1/3 cup fresh squeezed lemon juice (can also use lime juice)","1/2 teaspoon black pepper","ground cumin (1 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Mix the salad ingredients in a large bowl.","Mix the dressing ingredients in a small bowl.","Pour dressing over corn mixture and mix well.","Cover and refrigerate for at least 2 hours."]}],"yield":"9 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup (224g)","calories":"222.44 kcal","carbohydrateContent":"35.16 g","cholesterolContent":"0.00 mg","fiberContent":"11.19 g","proteinContent":"10.22 g","sodiumContent":"473.64 mg","sugarContent":"3.97 g","fatContent":"5.61 g","saturatedFatContent":"0.89 g"},"notes":null,"contributor":"2009 Recipe Calendar\nUniversity of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"south-border","source_url":"https://www.myplate.gov/recipes/south-border","name":"South of the Border Dip","description":"This quick dip can be prepared in under 1 minute, making it perfect for last-minute gatherings.","ingredients":[{"name":null,"items":["1 cup fat-free sour cream","1 cup fat-free plain yogurt","1 cup salsa"]}],"directions":[{"name":null,"steps":["Mix the sour cream, yogurt, and salsa.","Store the dip in a covered container if you don’t plan to eat it right away.","Keep the dip in the fridge until you serve it."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons prepared dip","1/16 of recipe"],"calories":"22.23 kcal","carbohydrateContent":"4.07 g","cholesterolContent":"1.66 mg","fiberContent":"0.17 g","proteinContent":"1.45 g","sodiumContent":"99.39 mg","sugarContent":"1.55 g","fatContent":"0.05 g","saturatedFatContent":"0.02 g"},"notes":"Serve with baked tortilla chips, crackers, or bite-sized vegetables.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"southern-banana-pudding","source_url":"https://www.myplate.gov/recipes/southern-banana-pudding","name":"Southern Banana Pudding","description":"Sweet and delicious, this dessert will soon become a family favorite.","ingredients":[{"name":null,"items":["3 3/4 cups fat-free milk, divided","2 (3.4 ounces each) boxes instant vanilla pudding and pie-filling mix","2 cups light frozen whipped topping","32 vanilla wafers","2 medium bananas, sliced"]}],"directions":[{"name":null,"steps":["Mix 3 1/2 cups of the milk with the pudding mixes. Beat the pudding mixture with a wire whisk for 2 minutes until it is well blended. Let stand for 5 minutes.","Fold 1 cup of the whipped topping into the pudding mix.","Arrange a layer of wafers on the bottom and sides of a 2-quart serving bowl. Drizzle 2 tablespoons of the remaining milk over the wafers. Add a layer of banana slices and top with one-third of the pudding.","Repeat layers, drizzling each wafer layer with remaining milk and ending with pudding. Spread the remaining whipped topping over the pudding.","Refrigerate for at least 3 hours before serving."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup","calories":"222.04 kcal","carbohydrateContent":"41.45 g","cholesterolContent":"4.20 mg","fiberContent":"0.63 g","proteinContent":"4.40 g","sodiumContent":"367.12 mg","sugarContent":"35.03 g","fatContent":"4.33 g","saturatedFatContent":"2.40 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"southwestern-pepper-cups","source_url":"https://www.myplate.gov/recipes/southwestern-pepper-cups","name":"Southwestern Pepper Cups","description":"Delicious stuffed peppers that will soon become a staple in your home.","ingredients":[{"name":null,"items":["5 medium green bell pepper, halved and seeded (or use red or yellow peppers)","1/3 cup onion, chopped","1 1/2 garlic clove, chopped","3 cups brown rice, cooked","1 can (10.5 ounces) tomatoes with chilies, diced and undrained","1/2 can (15.2 ounces) low-sodium whole kernel corn, drained","vegetable cooking spray","1/3 cup cheese, cheddar, shredded"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Blanch peppers in boiling water 2 to 3 minutes. Drain. Set aside.","Cook onion and garlic in oil in medium skillet over medium-high heat for 3 minutes.","Combine rice, tomatoes with chilies, corn, and onion mixture. Mix well.","Spoon into pepper halves, place on baking sheet coated with cooking spray.","Bake at 350 degrees F for 10 minutes or until hot. Sprinkle with cheese.","Bake again at 350 degrees F for 5 to 10 minutes or until hot and cheese melts."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 prepared pepper","calories":"124.40 kcal","carbohydrateContent":"23.75 g","cholesterolContent":"3.73 mg","fiberContent":"2.12 g","proteinContent":"3.74 g","sodiumContent":"144.77 mg","sugarContent":"3.18 g","fatContent":"2.16 g","saturatedFatContent":"0.91 g"},"notes":null,"contributor":"Don’t Play With Your Food: Spring and Summer Cookbook\nArizona Nutrition Network"},
{"slug":"soy-marinated-chicken","source_url":"https://www.myplate.gov/recipes/soy-marinated-chicken","name":"Soy Marinated Chicken","description":"A delicious and simple chicken dish. Enjoy with a fresh salad and brown rice, or a whole grain roll.","ingredients":[{"name":null,"items":["4 chicken breasts, boneless & skinless","1 large orange","2 tablespoons soy sauce, low-sodium"]}],"directions":[{"name":null,"steps":["Slice the orange to make round slices and set aside.","Place 4 chicken breasts in a 1-gallon sized plastic zipper bag.","Add the liquid to the bag with the chicken.","Zipper the bag closed and gently massage to mix the liquids and evenly cover the chicken inside the bag.","Let the chicken marinate in the bag in the refrigerator for 4 or more hours.","Preheat oven to 350 °F.","Spray shallow oven-proof baking dish with non-stick spray large enough to place chicken in single layer in the baking dish.","Remove the chicken from the bag, place in a single layer in the baking dish. Throw away the zipper bag from the chicken.","Bake chicken uncovered for 20 minutes.","Turn the chicken over, cover with orange slices that were set aside, and bake 15 more minutes (total of 35 minutes).","Check with a food thermometer. Temperature should reach 165 °F.","Serve chicken topped with an orange slice from the baking dish if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 chicken breast","1/4 of recipe"],"calories":"218.57 kcal","carbohydrateContent":"4.99 g","cholesterolContent":"118.55 mg","fiberContent":"0.90 g","proteinContent":"37.61 g","sodiumContent":"347.71 mg","sugarContent":"3.49 g","fatContent":"4.34 g","saturatedFatContent":"0.93 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"spaghetti-and-spinach-pesto","source_url":"https://www.myplate.gov/recipes/spaghetti-and-spinach-pesto","name":"Spaghetti and Spinach Pesto","description":"This pesto spaghetti dish is made with spinach for a unique spin on a classic. Top with feta and serve with a side salad for a colorful meal.","ingredients":[{"name":null,"items":["1 pound whole wheat spaghetti, uncooked (or your favorite pasta shape)","1 package 10-ounce frozen spinach, thawed, well drained","2 tablespoons canola oil","1/4 cup grated Parmesan cheese","2 tablespoons chopped parsley","2 cloves garlic","1/2 teaspoon salt","1/2 teaspoon dried basil","2 tablespoons tub margarine","1/3 cup water","2 ounces crumbled feta cheese"]}],"directions":[{"name":null,"steps":["In a blender (or food processor), combine spinach, oil, Parmesan cheese, parsley, garlic, salt, and basil. Mix at medium speed until finely chopped.","Melt margarine in water. With blender or processor running, gradually pour in melted margarine mixture until blended.","Cook pasta according to package directions.","Toss pesto with cooked pasta.","Sprinkle feta on top and serve."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"331.00 kcal","carbohydrateContent":"50.62 g","cholesterolContent":"8.49 mg","fiberContent":"7.67 g","proteinContent":"12.85 g","sodiumContent":"328.99 mg","sugarContent":"1.41 g","fatContent":"10.89 g","saturatedFatContent":"2.45 g"},"notes":"Serving Suggestion: Serve with grilled chicken, side salad, skim milk, and apple slices.","contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"spaghetti-quick-meat-sauce","source_url":"https://www.myplate.gov/recipes/spaghetti-quick-meat-sauce","name":"Spaghetti with Quick Meat Sauce","description":"Instead of opening a jar of sauce, try this easy spaghetti with meat sauce on a weeknight. Serve with steamed broccoli, garlic bread, and roasted pears for d...","ingredients":[{"name":null,"items":["1 pound whole wheat spaghetti","2 teaspoons extra virgin olive oil","1 large onion, finely chopped","1 large carrot, finely chopped","1 celery stalk, finely chopped","4 cloves garlic, minced","1 tablespoon Italian seasoning","1 pound lean ground beef (90% or leaner)","1 14-ounce can crushed tomatoes","1/4 cup chopped flat-leaf parsley","1/2 cup grated Parmesan cheese","1/2 teaspoon salt"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions. Drain.","Meanwhile, heat oil in a large skillet over medium heat.","Add onion, carrot, and celery and cook, stirring occasionally, until the onion is beginning to brown, 5 to 8 minutes.","Stir in garlic and Italian seasoning; cook until fragrant, about 30 seconds.","Add beef and cook, stirring and breaking up with a spoon, until no longer pink, 3 to 5 minutes.","Increase heat to high. Stir in tomatoes and cook until thickened, 4 to 6 minutes.","Stir in parsley and salt. Serve the sauce over the pasta, sprinkled with cheese."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"371.11 kcal","carbohydrateContent":"53.41 g","cholesterolContent":"37.16 mg","fiberContent":"7.95 g","proteinContent":"21.79 g","sodiumContent":"323.75 mg","sugarContent":"3.76 g","fatContent":"9.71 g","saturatedFatContent":"3.06 g"},"notes":null,"contributor":"EatingWell Magazine"},
{"slug":"spaghetti-squash-tomatoes-basil-and-parmesan","source_url":"https://www.myplate.gov/recipes/spaghetti-squash-tomatoes-basil-and-parmesan","name":"Spaghetti Squash with Tomatoes, Basil, and Parmesan","description":"Here is a delicious late summer side dish bursting with fresh flavors. This dish would go well with a grilled entrée.","ingredients":[{"name":null,"items":["1 1/2 pounds spaghetti squash (about 1 squash)","1 tablespoon olive oil","3 tablespoons Parmesan cheese","1/4 teaspoon dried oregano","2 teaspoons dried basil (or 1/2 cup fresh basil, chopped)","1 cup cherry tomatoes (thinly sliced)","salt and pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Place the 2 squash halves, cut side down, in glass baking dish. Add about 1/4 cup water and cover with plastic wrap. Microwave on high 12 minutes or until soft when pressed. Let stand covered for 3 minutes.","In a large bowl, whisk oil, basil, oregano and 2 tablespoons Parmesan cheese. Stir in tomatoes and season lightly with salt and pepper to taste.","Scrape squash out with a fork, add strands to tomato mixture, and toss until combined. Sprinkle with remaining 1 tablespoon Parmesan cheese."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"111.54 kcal","carbohydrateContent":"15.33 g","cholesterolContent":"3.23 mg","fiberContent":"4.91 g","proteinContent":"2.95 g","sodiumContent":"56.74 mg","sugarContent":"5.98 g","fatContent":"5.26 g","saturatedFatContent":"1.29 g"},"notes":null,"contributor":"Eat Smart. Be Fit.\nUniversity of Maryland Extension"},
{"slug":"spanish-baked-fish","source_url":"https://www.myplate.gov/recipes/spanish-baked-fish","name":"Spanish Baked Fish","description":"This delicious fish will pair well with spaghetti squash when in season, and whole wheat pasta or brown rice the rest of the year.","ingredients":[{"name":null,"items":["1 pound perch fillets, fresh or frozen","1 small onion","1 cup low-sodium tomato sauce","1/2 teaspoon garlic powder","2 teaspoons chili powder","1 teaspoon oregano","1/8 teaspoon ground cumin"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 degrees F.","Lightly grease baking dish (9 x 13-inch) with butter or margarine.","Separate the fish into 4 fillets or pieces.","Put the fish pieces in the baking dish.","Peel the onion and cut it into slices.","Stir the onion, tomato sauce, and spices together in a small bowl.","Pour the onion-spice mix evenly over the fish pieces.","Bake about 10 to 20 minutes, until the fish flakes easily with a fork."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3 oz. prepared fish","1/4 of recipe"],"calories":"122.14 kcal","carbohydrateContent":"8.02 g","cholesterolContent":"56.44 mg","fiberContent":"2.25 g","proteinContent":"18.03 g","sodiumContent":"358.31 mg","sugarContent":"3.88 g","fatContent":"2.13 g","saturatedFatContent":"0.38 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"spanish-frittata","source_url":"https://www.myplate.gov/recipes/spanish-frittata","name":"Spanish Frittata","description":"This versatile recipe combines eggs, potatoes, and onion going from stovetop to oven for the finishing touch. Cut into wedges as part of a delicious breakfas...","ingredients":[{"name":null,"items":["2 russet potatoes (scrubbed)","6 eggs","2 teaspoons vegetable oil","1 medium yellow onion (peeled and chopped)","1/2 teaspoon Kosher salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 °F.","Put the potatoes in a non-stick skillet on the stove and cover with cold water. Turn the heat to medium-high and cook about 15 minutes until the potatoes are easily pierced with a knife.","Drain the potatoes well and set aside to cool. Then peel and cut into 1-inch cubes.","Put the eggs, salt, and pepper in the bowl and mix well with a whisk.","Return the skillet on the stove and turn the heat to medium-high. Add the oil. Add onion and cook about 5 minutes until soft. Add the cubed potatoes.","Pour the egg mixture over the potatoes and onions. Press down with a spatula to make an even layer and shake gently to prevent sticking. Lower to medium heat and cook about 7 minutes.","Transfer the skillet to the oven and cook until the frittata is completely set, about 5 minutes.","Gently loosen frittata from the pan. Place a serving plate over the skillet and carefully invert the frittata onto the plate.","Slice into 4 wedges. Serve warm."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"4 ounce","calories":"224.04 kcal","carbohydrateContent":"22.48 g","cholesterolContent":"308.25 mg","fiberContent":"2.57 g","proteinContent":"11.88 g","sodiumContent":"402.29 mg","sugarContent":"2.74 g","fatContent":"9.96 g","saturatedFatContent":"2.76 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"spanish-omelet","source_url":"https://www.myplate.gov/recipes/spanish-omelet","name":"Spanish Omelet","description":"This recipe can be enjoyed for any meal of the day. Spice it up with your favorite hot sauce.","ingredients":[{"name":null,"items":["5 small potatoes, peeled and sliced","1 tablespoon olive oil (or cooking oil of choice, or non-stick cooking spray)","1/2 medium onion, minced","1 medium zucchini, sliced","1 1/2 cups green/red peppers, sliced thin","5 medium mushrooms, sliced","3 eggs","5 egg whites","black pepper and garlic salt with herbs (to taste)","3 ounces part skim mozzarella cheese, shredded","1 tablespoon Parmesan cheese"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 degrees F.","Cook potatoes in boiling water until tender.","In a nonstick pan, add oil or vegetable spray and warm at medium heat.","Add the onion and sauté until brown. Add vegetables and sauté until tender but not brown.","In a medium mixing bowl, slightly beat the eggs and egg whites, pepper, garlic salt, and mozzarella cheese. Stir egg cheese mixture into the cooked vegetables.","Oil or spray a 10-inch pie pan or ovenproof skillet. Transfer potatoes and eggs mixture to pan. Spread with parmesan cheese and bake omelet until firm and brown on top, about 20 to 30 minutes."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of omelet","calories":"298.38 kcal","carbohydrateContent":"37.25 g","cholesterolContent":"135.22 mg","fiberContent":"4.36 g","proteinContent":"16.48 g","sodiumContent":"244.98 mg","sugarContent":"5.60 g","fatContent":"10.00 g","saturatedFatContent":"3.65 g"},"notes":null,"contributor":"Control Your Diabetes for Life: Recipes and Meal Planner Guide\nUS Department of Health and Human Services\nCenters for Disease Control and Prevention (CDC)\nNational Diabetes Education Program"},
{"slug":"spanish-rice","source_url":"https://www.myplate.gov/recipes/spanish-rice","name":"Spanish Rice","description":"Enjoy this rice dish filled with vegetables and spices with your favorite chicken, fish, or bean dish.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of choice)","1/2 cup green pepper, chopped","1/4 cup onion, chopped","1 teaspoon garlic powder","1 teaspoon chili powder","1 teaspoon ground red pepper","1 teaspoon salt","1/8 teaspoon ground black pepper","1 cup rice, uncooked","1 can (14.5 ounces) low-sodium chopped tomatoes, undrained","2 cups water"]}],"directions":[{"name":null,"steps":["In a large skillet cook green pepper and onion in oil until tender over medium heat.","Stir in the spices, rice, tomatoes with juice, and water.","Cover and cook over low heat for 20 minutes or until rice is done."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 recipe","calories":"186.22 kcal","carbohydrateContent":"31.36 g","cholesterolContent":"0.00 mg","fiberContent":"2.32 g","proteinContent":"3.43 g","sodiumContent":"418.30 mg","sugarContent":"2.51 g","fatContent":"5.21 g","saturatedFatContent":"0.76 g"},"notes":null,"contributor":"USDA Food Distribution Program on Indian Reservations"},
{"slug":"speedy-burritos","source_url":"https://www.myplate.gov/recipes/speedy-burritos","name":"Speedy Burritos","description":"These speedy potato and egg burritos are great for breakfast, lunch, or dinner. Enjoy them with your favorite fruit on the side.","ingredients":[{"name":null,"items":["4 cups potatoes (finely chopped)","1 onion (chopped)","1 bell pepper (red or green, chopped)","3 garlic cloves (pressed or finely chopped)","2 eggs (beaten)","1 teaspoon black pepper","1/2 teaspoon salt","1 tablespoon vegetable oil","cheddar cheese (1/2 cup grated, optional)","hot sauce (as needed, or salsa)","9 tortillas (flour or corn)"]}],"directions":[{"name":null,"steps":["In a large skillet, heat oil on medium-high setting.","Add onion, green pepper, potatoes, and garlic. Cook until potatoes are tender, about 10 minutes. Raw potatoes may need longer; check if done with a fork.","Reduce heat to medium setting, spread potato mix out to the sides of the skillet, leaving a space in the middle for the eggs. Add the eggs and scramble them until cooked (do not mix potatoes until eggs are cooked firm). Stir all ingredients together.","Wrap tortillas around the filling and top with salsa and cheese."]}],"yield":"9","nutrition":{"@type":"NutritionInformation","calories":"183.88"},"notes":null,"contributor":"Eat Better, Eat Together\nWashington State University"},
{"slug":"spiced-baked-squash","source_url":"https://www.myplate.gov/recipes/spiced-baked-squash","name":"Spiced Baked Squash","description":"This side dish is perfect for a fall or winter meal. Squash cooked with cinnamon, nutmeg, and ginger creates a simple dish to accompany your favorite entrée...","ingredients":[{"name":null,"items":["vegetable cooking spray","1 acorn squash","1 dash salt","2 tablespoons margarine","3 tablespoons brown sugar","1 teaspoon cinnamon","1/4 teaspoon nutmeg","1/4 teaspoon ginger"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 degrees F.","Coat the baking sheet with vegetable cooking spray.","Wash the squash. Cut it in half lengthwise. Remove the seeds. Cut the squash into 1/2 inch slices.","Place the squash on the baking sheet. Sprinkle with salt.","Melt the margarine on low heat in a small saucepan.","Add the brown sugar, cinnamon, nutmeg, and ginger to the saucepan.","Spread the margarine mix on the squash.","Bake for 20 to 25 minutes, or until tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/4 of prepared squash","1/4 of recipe"],"calories":"99.38 kcal","carbohydrateContent":"15.40 g","cholesterolContent":"0.07 mg","fiberContent":"2.95 g","proteinContent":"0.87 g","sodiumContent":"89.02 mg","sugarContent":"9.59 g","fatContent":"4.57 g","saturatedFatContent":"0.95 g"},"notes":null,"contributor":"Spicy Baked Squash, Pennsylvania Nutrition Education Network"},
{"slug":"spicy-baked-fish-ii","source_url":"https://www.myplate.gov/recipes/spicy-baked-fish-ii","name":"Spicy Baked Fish II","description":"Make dinner in a flash. This fast and easy fish is delicious and perfect for a busy evening. A fresh green salad and a whole grain roll or brown rice would m...","ingredients":[{"name":null,"items":["1 pound cod fillets, fresh or frozen, skinless and thawed (or other white fleshed fish)","1/4 cup green bell pepper (chopped)","1/2 can tomatoes, canned, low-sodium (about 8 ounces)","1/4 teaspoon oregano","1/4 cup onion (chopped)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F. Oil or spray a baking dish with vegetable spray.","Cut fish into four pieces and place in baking dish.","Top fish with onions, green peppers, tomatoes, and seasoning. Bake about 20 minutes or until fish flakes."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"87.97"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"spicy-baked-fish","source_url":"https://www.myplate.gov/recipes/spicy-baked-fish","name":"Spicy Baked Fish","description":"Roast your favorite seasonal veggies while baking this fish for a wonderful dinner any time of the year.","ingredients":[{"name":null,"items":["16 ounces salmon (fresh or frozen, or any white fish)","1/4 teaspoon paprika","1/4 teaspoon onion powder","1/4 teaspoon garlic powder","1/8 teaspoon black pepper","1/8 teaspoon oregano (dried)","1/8 teaspoon thyme (dried)","1 tablespoon lemon juice","1 1/2 tablespoons margarine (soft melted)"]}],"directions":[{"name":null,"steps":["If using frozen fish, thaw in refrigerator according to package directions.","Preheat oven to 350 °F.","Separate (or cut) fish into 4 pieces. Place fish in a 13x9x2 inch baking pan.","Combine paprika, garlic and onion powders, pepper, oregano, and thyme in a small bowl.","Sprinkle herb mixture (from previous step) and lemon juice evenly over the fish. Then drizzle melted margarine on top.","Bake until fish flakes easily with a fork, about 20 to 25 minutes."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"239.17"},"notes":null,"contributor":"Pumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"spicy-baked-squash","source_url":"https://www.myplate.gov/recipes/spicy-baked-squash","name":"Spicy Baked Squash","description":"This side dish is perfect for a fall or winter meal. Squash cooked with cinnamon, nutmeg, and ginger creates a simple dish to accompany your favorite entrée...","ingredients":[{"name":null,"items":["vegetable cooking spray","1 acorn squash","1 dash salt","2 tablespoons margarine","3 tablespoons brown sugar","1 teaspoon cinnamon","1/4 teaspoon nutmeg","1/4 teaspoon ginger"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 °F.","Coat the baking sheet with vegetable cooking spray.","Wash the squash. Cut it in half lengthwise. Remove the seeds. Cut the squash into 1/2 inch slices.","Place the squash on the baking sheet. Sprinkle with salt.","Melt the margarine on low heat in a small saucepan.","Add the brown sugar, cinnamon, nutmeg, and ginger to the saucepan.","Spread the margarine mix on the squash.","Bake for 20 to 25 minutes, or until tender."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"96.15"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"spicy-carrots-and-squash","source_url":"https://www.myplate.gov/recipes/spicy-carrots-and-squash","name":"Spicy Carrots and Squash","description":"This side dish is an excellent way to get your orange vegetables. Vinegar, brown sugar, and spicy mustard combine to give this dish a sweet and tangy taste. ...","ingredients":[{"name":null,"items":["2 cups carrots, cut into 2-inch sticks","1 1/2 cups squash, cut into 2-inch sticks","1/8 cup low-sodium vegetable broth (or low-sodium chicken broth)","1 teaspoon vinegar","1 teaspoon brown sugar","1 1/2 teaspoons Dijon or spicy mustard"]}],"directions":[{"name":null,"steps":["Wash, peel, and cut carrots. Wash and cut up squash.","Combine carrots and broth in a large saucepan. Cover and cook over medium heat about 5 minutes.","Add squash and cook 5 more minutes or until vegetables are just tender. Add more broth, if necessary, to keep from burning.","Stir vinegar, brown sugar, and mustard into vegetables.","Cook for a few minutes over medium heat until most of the liquid cooks off."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"37.24 kcal","carbohydrateContent":"8.25 g","cholesterolContent":"0.00 mg","fiberContent":"2.11 g","proteinContent":"1.07 g","sodiumContent":"66.33 mg","sugarContent":"5.01 g","fatContent":"0.32 g","saturatedFatContent":"0.06 g"},"notes":"Try this recipe without brown sugar.","contributor":"Connecticut Food Policy Council"},
{"slug":"spicy-chicken-and-potato-soup","source_url":"https://www.myplate.gov/recipes/spicy-chicken-and-potato-soup","name":"Spicy Chicken and Potato Soup","description":"This rich-tasting and hearty potato soup is full of flavor and perfect for lunch or dinner.","ingredients":[{"name":null,"items":["1 cup onion, chopped","1 tablespoon garlic, finely chopped","1 tablespoon vegetable oil (or cooking oil of choice)","1/4 pound chicken, thawed, cut up, and skin removed","4 cups water","6 small red potatoes, chopped (or 1 can, about 15 ounces, low-sodium sliced potatoes)","1/4 cup white rice, uncooked (or brown rice)","1/2 teaspoon chili powder (or paprika)","1 cup fresh peas (or 1/2 can, about 8 ounces, low-sodium green peas)","cayenne or jalapeño chilies, diced (1/2 teaspoon, optional)","parsley or cilantro, chopped (1/2 cup, optional)"]}],"directions":[{"name":null,"steps":["In a large pot, brown onion and garlic in oil over medium to high heat for 5 minutes.","Add chicken to pot and brown for about 5 minutes.","Add water, potatoes, rice, and chili powder to pot.","Bring pot to a boil, and cook for 15 minutes.","Lower heat and cook for about 15 to 20 minutes. Stir pot every 10 minutes.","Add peas and cook for about 8 minutes. If using cayenne or jalapeño chilies, add that too. Mix well.","Remove pot from heat. If using parsley or cilantro, add that now.","Mix well and cover for 5 minutes. Serve hot."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"239.86 kcal","carbohydrateContent":"42.23 g","cholesterolContent":"12.45 mg","fiberContent":"5.08 g","proteinContent":"9.85 g","sodiumContent":"69.93 mg","sugarContent":"4.17 g","fatContent":"3.78 g","saturatedFatContent":"0.70 g"},"notes":"Tip for cooking chicken: The recommended safe minimum internal temperature for chicken is 165 °F, as measured with a food thermometer.","contributor":null},
{"slug":"spicy-cucumber-orange-salad","source_url":"https://www.myplate.gov/recipes/spicy-cucumber-orange-salad","name":"Spicy Cucumber & Orange Salad","description":"Chili powder and lime juice are the secret ingredients in this cucumber and orange salad.","ingredients":[{"name":null,"items":["2 medium cucumbers","2 medium oranges","1 medium lemon or lime, juiced","1/2 teaspoon chili powder","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Wash the cucumbers, oranges and lemon or lime under cold running water.","Slice the cucumbers. Peel and cut the oranges into small pieces.","Place cucumber slices and orange pieces in a medium size bowl. Add chili powder, lemon or lime juice and salt."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"57.04 kcal","carbohydrateContent":"13.69 g","cholesterolContent":"0.00 mg","fiberContent":"2.35 g","proteinContent":"1.44 g","sodiumContent":"162.42 mg","sugarContent":"8.89 g","fatContent":"0.29 g","saturatedFatContent":"0.07 g"},"notes":null,"contributor":"Recipe Adapted from: A Simple Mexican Salad, Oregon State University Cooperative Extension Service"},
{"slug":"spicy-fruit-cup","source_url":"https://www.myplate.gov/recipes/spicy-fruit-cup","name":"Spicy Fruit Cup","description":"A touch of cinnamon and nutmeg make the flavors of this fruit medley pop.","ingredients":[{"name":null,"items":["2 cups fresh strawberries","1 can (11 ounces) mandarin orange sections","1 can (16 ounces) pears","1 cup pineapple chunks, in its own juice","1 cup orange juice","1/4 teaspoon ground cinnamon","1/4 teaspoon ground nutmeg"]}],"directions":[{"name":null,"steps":["Cut the strawberries in half.","Open the can of mandarin oranges. Drain off the syrup.","Open the can of pears. Drain off the juice. Slice the pears.","Open the can of pineapple, but don’t drain off the juice.","Put the undrained pineapple, orange juice, cinnamon, and nutmeg in a mixing bowl. Stir together.","Carefully stir in the mandarin oranges, pears, and strawberries.","Refrigerate for 1 to 4 hours before serving."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"81.30 kcal","carbohydrateContent":"19.80 g","cholesterolContent":"0.00 mg","fiberContent":"2.14 g","proteinContent":"1.00 g","sodiumContent":"9.60 mg","sugarContent":"16.75 g","fatContent":"0.31 g","saturatedFatContent":"0.03 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"spicy-okra","source_url":"https://www.myplate.gov/recipes/spicy-okra","name":"Spicy Okra","description":"Okra cooked with tomatoes, onions, and hot peppers creates the perfect spicy side dish for your favorite entrée.","ingredients":[{"name":null,"items":["2 packages (10 ounces each) frozen cut okra","1 tablespoon vegetable oil (or cooking oil of choice)","1 medium onion, coarsely chopped","1 can (14.5 ounces) low-sodium tomatoes, diced","1 fresh jalapeño pepper, pierced 3 times with fork (or habanero pepper)","1/2 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Rinse okra in a colander under hot water.","Heat oil in a 10-inch heavy skillet over moderately high heat. Sauté onion for about 3 minutes.","Add tomatoes (including juice) and jalapeño (or habanero) pepper, and boil. Stir the mixture for 8 minutes.","Add okra and cook, gently stirring, until okra is tender, about 5 minutes.","Stir in salt and pepper and discard the jalapeño (or habanero) pepper."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"42.26 kcal","carbohydrateContent":"6.60 g","cholesterolContent":"0.00 mg","fiberContent":"2.28 g","proteinContent":"1.44 g","sodiumContent":"124.70 mg","sugarContent":"3.37 g","fatContent":"1.66 g","saturatedFatContent":"0.25 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"spicy-oven-baked-chicken","source_url":"https://www.myplate.gov/recipes/spicy-oven-baked-chicken","name":"Spicy Oven-Baked Chicken","description":"Chicken thighs coated in hot sauce, mustard, thyme, and garlic are oven-baked for a tender and simple chicken dish.","ingredients":[{"name":null,"items":["8 large chicken thighs, trimmed","2 tablespoons hot sauce","2 teaspoons yellow mustard","2 teaspoons dried thyme","2 cloves garlic, minced","1 teaspoon salt","1 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Put chicken thighs, hot sauce, mustard, thyme, and garlic in the bowl and mix well.","Cover and refrigerate at least one hour or up to 24 hours.","Heat the oven to 450°F.","Put the chicken on a baking sheet and sprinkle with the salt and pepper.","Place in the oven and bake about 50 minutes until crispy and crackling. Serve right away."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 chicken thigh (2-3 ounces)","calories":"182.87 kcal","carbohydrateContent":"0.72 g","cholesterolContent":"132.57 mg","fiberContent":"0.30 g","proteinContent":"24.92 g","sodiumContent":"440.17 mg","sugarContent":"0.04 g","fatContent":"8.25 g","saturatedFatContent":"2.33 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"spicy-southern-barbecued-chicken","source_url":"https://www.myplate.gov/recipes/spicy-southern-barbecued-chicken","name":"Spicy Southern Barbecued Chicken","description":"This recipe is spiced up using cayenne pepper, ginger, and garlic combined with the sweetness of honey, molasses, and ketchup to create a tasty comfort food....","ingredients":[{"name":null,"items":["5 tablespoons low-sodium tomato paste","1/3 tablespoon ketchup (1 teaspoon)","2 teaspoons honey*","1/3 tablespoon molasses (1 teaspoon)","1 teaspoon Worcestershire sauce","4 teaspoons white vinegar","3/4 teaspoon cayenne pepper","1/8 teaspoon ground black pepper","1/4 teaspoon onion powder","2 garlic cloves (minced)","1/8 teaspoon ginger (grated)","1 1/2 pounds chicken (skinless breasts or drumsticks)"]}],"directions":[{"name":null,"steps":["Combine all ingredients except chicken in saucepan.","Simmer for 15 minutes.","Place chicken on large platter and brush with half the sauce mixture.","Cover with plastic wrap and marinate in refrigerator for 1 hour.","Remove plastic wrap from chicken. Place chicken on baking sheet lined with aluminum foil and broil for 10 minutes on each side to seal in juices.","Remove from broiler and add remaining sauce to chicken. Cover with aluminum foil and bake at 350 °F for 30 minutes.","* Children under the age of one should not consume honey."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 breast or 2 small drumsticks (89g)","calories":"103.40 kcal","carbohydrateContent":"6.15 g","cholesterolContent":"36.33 mg","fiberContent":"0.73 g","proteinContent":"12.49 g","sodiumContent":"64.13 mg","sugarContent":"4.59 g","fatContent":"3.10 g","saturatedFatContent":"0.85 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"spinach-and-meat-cakes","source_url":"https://www.myplate.gov/recipes/spinach-and-meat-cakes","name":"Spinach and Meat Cakes","description":"Enjoy these spinach and meat cakes over brown rice and with a side of roasted sweet potatoes.","ingredients":[{"name":null,"items":["1 pound 93% lean ground beef (or lean turkey)","2 cups frozen spinach, chopped (may substitute with 2 bunches of fresh spinach)","1/2 small onion, finely chopped","2 garlic cloves, minced","1/2 teaspoon salt","black pepper (to taste)","3 cups cooked brown rice"]}],"directions":[{"name":null,"steps":["Preheat large frying pan (no oil).","Combine all ingredients except brown rice in a large mixing bowl. Mix well.","Form mixture into 12 small balls. Place in frying pan and flatten into patties using a spatula.","Cook over medium heat until cooked on both sides.","Serve over brown rice."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 meat cakes","1/6 of recipe"],"calories":"245.31 kcal","carbohydrateContent":"29.81 g","cholesterolContent":"43.82 mg","fiberContent":"4.47 g","proteinContent":"19.09 g","sodiumContent":"308.22 mg","sugarContent":"1.13 g","fatContent":"5.76 g","saturatedFatContent":"2.09 g"},"notes":null,"contributor":"California Health Department, Los Angeles County\nEs Facil Campaign"},
{"slug":"spinach-and-mushroom-enchilada-casserole","source_url":"https://www.myplate.gov/recipes/spinach-and-mushroom-enchilada-casserole","name":"Spinach and Mushroom Enchilada Casserole","description":"Banana peppers add a kick to these delicious enchiladas -- and are in season the same time as bell peppers.","ingredients":[{"name":null,"items":["2 teaspoons olive oil (or oil of your choice)","1 medium onion (chopped)","2 garlic cloves (minced)","3 yellow banana peppers (seeded, deveined, and minced)","3 pounds mushrooms (sliced)","1 cup green enchilada sauce (approximately one 10 oz can)","8 corn tortillas (6 inch, cut in half)","1/4 teaspoon salt","1/2 teaspoon oregano leaves (dried)","2 packages frozen chopped spinach (10 ounce box, thawed)","6 1/2 ounces reduced fat Monterey jack cheese (grated)"]}],"directions":[{"name":null,"steps":["Heat oil in a very large non-stick skillet. Add onion, garlic, and peppers and stir. Add mushrooms and cook about 15 to 20 minutes, until liquid evaporates. (If pan is not large enough, cook mushrooms in batches.)","Pour half of the enchilada sauce into a 13x9 inch baking dish.","Arrange 8 tortilla halves over the sauce in the baking dish. Preheat the oven to 350 °F. When mushrooms are cooked, stir in the salt and crumble in the oregano leaves. Drain the spinach, squeeze it dry, and mix it thoroughly with the mushroom mixture. Spoon half the mushroom mixture into the baking dish, carefully covering tortillas.","Set aside 1/4 cup (about 1 ounce) of grated cheese. Sprinkle the rest of the cheese on top of the mushroom mixture. Layer with the remaining 8 tortilla halves, then the remaining mushroom mixture and enchilada sauce. Sprinkle top of casserole with the remaining 1/4 cup cheese. Cover baking dish with aluminum foil and bake for 30 minutes, or until casserole is steaming hot in the center."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3 1/4\" x 4 1/2\" piece","1/8 of recipe (371g)"],"calories":"241.92 kcal","carbohydrateContent":"27.44 g","cholesterolContent":"14.97 mg","fiberContent":"7.46 g","proteinContent":"16.34 g","sodiumContent":"636.85 mg","sugarContent":"6.06 g","fatContent":"8.48 g","saturatedFatContent":"3.74 g"},"notes":"Allow casserole to stand at room temperature 5 minutes before serving. Serve with pinto or black beans and salad.","contributor":"California’s Chefs Cook Lean\nCalifornia Department of Health Services\nCalifornia Project LEAN"},
{"slug":"spinach-black-bean-salad","source_url":"https://www.myplate.gov/recipes/spinach-black-bean-salad","name":"Spinach Black Bean Salad","description":"This tasty salad is packed with protein and fiber. Add your favorite salad toppings to make it a fast favorite.","ingredients":[{"name":null,"items":["2 tablespoons vinegar","1 tablespoon vegetable oil (or cooking oil of choice)","1 tablespoon dijon mustard","1 teaspoon garlic powder","1/2 teaspoon dried oregano","1/2 teaspoon dried basil","ground nutmeg (1/8 teaspoon, optional)","2 cups fresh spinach","1 1/2 cups canned low-sodium black beans, drained and rinsed","2 medium tomatoes, chopped","1 small red onion, chopped"]}],"directions":[{"name":null,"steps":["In a large bowl, combine vinegar, oil, mustard, garlic, oregano, basil, and nutmeg.","Wash, drain, and chop spinach.","Add spinach, black beans, tomatoes, and onions to vinegar and oil. Toss well and serve."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"201.42 kcal","carbohydrateContent":"29.23 g","cholesterolContent":"0.00 mg","fiberContent":"10.91 g","proteinContent":"9.28 g","sodiumContent":"244.30 mg","sugarContent":"5.55 g","fatContent":"5.61 g","saturatedFatContent":"0.81 g"},"notes":"Top your salad with other vegetables, such as mushrooms, peppers, cucumbers, zucchini, yellow squash, or red onions.\nAdd cooked chicken, egg, or tuna for more protein.\nAdd cubes of cheddar, Swiss, or smoked Gouda cheese.\nFruit makes a great addition! Try dried cranberries, cherries, raisins, or apricots or fresh berries in season.","contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"spinach-potato-pancakes","source_url":"https://www.myplate.gov/recipes/spinach-potato-pancakes","name":"Spinach Potato Pancakes","description":"This versatile veggie dish makes a tasty snack or appetizer. Serve with applesauce on the side.","ingredients":[{"name":null,"items":["2 cups zucchini, shredded","1 medium potato, peeled and shredded","1/4 cup medium onion, finely chopped","1/4 teaspoon salt","1/4 cup whole wheat flour","1 1/2 cups spinach leaves, chopped and steamed","1/2 teaspoon black pepper","1/4 teaspoon ground nutmeg","1 egg, beaten","applesauce (optional)"]}],"directions":[{"name":null,"steps":["Combine the first eight ingredients in a bowl.","Stir in egg and mix well.","Drop batter in 1/4 cup sizes onto a well-greased hot griddle and flatten to form patties.","Fry until golden brown; turn and cook until the second side is lightly browned. Drain on paper towels and serve with applesauce, if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"101.33 kcal","carbohydrateContent":"17.95 g","cholesterolContent":"51.38 mg","fiberContent":"2.73 g","proteinContent":"4.62 g","sodiumContent":"180.60 mg","sugarContent":"2.51 g","fatContent":"1.77 g","saturatedFatContent":"0.54 g"},"notes":null,"contributor":"University of Maine Cooperative Extension"},
{"slug":"spinach-rice-salad","source_url":"https://www.myplate.gov/recipes/spinach-rice-salad","name":"Spinach Rice Salad","description":"Try this hearty, cold rice salad that could be served with fresh fruit and your favorite protein foods.","ingredients":[{"name":null,"items":["1/2 cup Lite Italian Dressing","2 teaspoons reduced-sodium soy sauce","1/2 teaspoon sugar","3 cups cooked brown rice, chilled","2/3 cup fresh spinach, washed and cut into thin strips","2/3 cup sliced celery","1/2 cup green onion, thinly sliced (including tops)","bacon bits (optional)"]}],"directions":[{"name":null,"steps":["Combine dressing, soy sauce, and sugar. Stir into chilled rice.","Cover and chill salad.","Add spinach, celery, and onion before serving.","Shake on bacon bits if desired."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"246.55 kcal","carbohydrateContent":"39.93 g","cholesterolContent":"0.43 mg","fiberContent":"3.11 g","proteinContent":"4.92 g","sodiumContent":"225.02 mg","sugarContent":"1.52 g","fatContent":"7.25 g","saturatedFatContent":"1.25 g"},"notes":null,"contributor":"University of Connecticut"},
{"slug":"spinach-salad-apples-and-eggs","source_url":"https://www.myplate.gov/recipes/spinach-salad-apples-and-eggs","name":"Spinach Salad with Apples and Eggs","description":"Enjoy a simply delicious spinach salad with hard-boiled eggs, apples, and dried figs.","ingredients":[{"name":null,"items":["4 large eggs","2 apples","8 cups fresh spinach","1 cup dried figs (about 16 figs or one 7-ounce package)","1 cup croutons (whole grain if available)","1/2 cup light honey mustard or poppy seed dressing"]}],"directions":[{"name":null,"steps":["To hard boil eggs: Place eggs in saucepan large enough to hold them in a single layer. Add cold water to cover eggs by 1 inch. Heat over high heat just to boiling. Remove from heat and cover. Let eggs stand in hot water about 12 minutes. Drain and fill pan with cold water; let sit 10 to 15 minutes. Peel and slice. (If making ahead, refrigerate cooked unpeeled eggs.)","Prepare other ingredients while eggs are cooking and cooling.","Wash, slice, and core apples.","Cut apples and dried figs into bite-sized chunks.","Wash and drain spinach.","To plate, divide ingredients evenly among four plates, top spinach with apples, eggs, dried figs, and croutons. Drizzle with dressing."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"349.43 kcal","carbohydrateContent":"56.05 g","cholesterolContent":"205.50 mg","fiberContent":"7.44 g","proteinContent":"10.30 g","sodiumContent":"386.65 mg","sugarContent":"37.06 g","fatContent":"9.30 g","saturatedFatContent":"2.08 g"},"notes":"Serving Suggestions: Serve with a glass of 100% grape juice together with vanilla or lemon low-fat yogurt.","contributor":"Produce for Better Health Foundation"},
{"slug":"spinach-salad-apples-and-raisins","source_url":"https://www.myplate.gov/recipes/spinach-salad-apples-and-raisins","name":"Spinach Salad with Apples and Raisins","description":"Enjoy this tasty, sweet fall salad with a savory and seasonal entrée. Use Granny Smith or your favorite kind of apples. Try leaving out the sugar for a more...","ingredients":[{"name":"Salad","items":["1 package (10 ounces) baby spinach, washed (or kale or other greens)","1 1/2 medium apples, chopped (can use 1-2 apples)","1 cup raisins"]},{"name":"Dressing","items":["1/4 cup canola oil (or cooking oil of choice)","1/4 cup apple cider vinegar","1/4 cup sugar","1/16 teaspoon garlic powder"]}],"directions":[{"name":null,"steps":["Combine spinach, apples, and raisins.","Mix all dressing ingredients and pour over salad just prior to serving."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"242.61 kcal","carbohydrateContent":"38.10 g","cholesterolContent":"0.00 mg","fiberContent":"3.01 g","proteinContent":"2.32 g","sodiumContent":"59.98 mg","sugarContent":"31.99 g","fatContent":"9.79 g","saturatedFatContent":"0.68 g"},"notes":"Granny Smith apples are recommended for salad, but any apple on hand will work. Try decreasing or cutting out the sugar if you like your salad less sweet.","contributor":"Eat Smart. Be Fit.\nUniversity of Maryland Extension"},
{"slug":"spinach-stuffed-potatoes","source_url":"https://www.myplate.gov/recipes/spinach-stuffed-potatoes","name":"Spinach Stuffed Potatoes","description":"These tasty, twice-baked potatoes are stuffed with veggies, cheese, tofu, and sour cream for a delicious and filling dish.","ingredients":[{"name":null,"items":["1 package (10 ounces) frozen spinach, thawed and drained","6 medium potatoes","1/4 cup green onion","1/4 cup light sour cream","1/4 cup silken soft tofu","1/4 teaspoon ground black pepper","1/2 cup low-fat cheddar cheese, grated","1 teaspoon salt free seasoning"]}],"directions":[{"name":null,"steps":["Thaw the spinach before you cook this recipe! After it thaws, drain any extra water from the spinach.","Preheat the oven to 350 degrees F.","Wash and scrub the potatoes.","Bake the potatoes in for 1 hour till they’re tender and you can pierce them with a fork.","Wash and chop the green onion until you get 1/4 cup onion.","Put the sour cream, tofu, spinach, onion, pepper, and cheese in a mixing bowl. Mix well.","When the potatoes are baked, let them cool. Then use a spoon to scoop out the inside of the potato. Add the inside of the potato to the sour cream mix. Stir together.","Stuff the potato skin shells with the mixture. Sprinkle the potatoes with the seasoning.","Bake the potatoes for 20 to 25 minutes until they’re a little brown. Add extra cheese on top if desired."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 stuffed potato","calories":"228.53 kcal","carbohydrateContent":"40.78 g","cholesterolContent":"10.66 mg","fiberContent":"5.72 g","proteinContent":"9.97 g","sodiumContent":"132.37 mg","sugarContent":"2.50 g","fatContent":"4.01 g","saturatedFatContent":"2.03 g"},"notes":"You can use part-skim mozzarella cheese in place of low-fat cheddar cheese.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"spinach-tomatoes-and-corn","source_url":"https://www.myplate.gov/recipes/spinach-tomatoes-and-corn","name":"Spinach, Tomatoes, and Corn","description":"Canned veggies make this dish easy to prepare at any time of the year! No fresh veggies necessary.","ingredients":[{"name":null,"items":["1 cup canned spinach","1 can (15.5 ounces) low-sodium diced tomatoes","1 can (15.2 ounces) low-sodium corn, drained","3 cups water","1 tablespoon margarine"]}],"directions":[{"name":null,"steps":["Place all ingredients in a large saucepan. Cover.","Heat thoroughly over medium-high heat, about 10 minutes. Add seasonings to taste."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"95.03 kcal","carbohydrateContent":"17.22 g","cholesterolContent":"0.03 mg","fiberContent":"4.15 g","proteinContent":"3.68 g","sodiumContent":"182.55 mg","sugarContent":"6.12 g","fatContent":"2.81 g","saturatedFatContent":"0.47 g"},"notes":null,"contributor":"Creative Recipes for Less Familiar USDA Commodities Used by Household Programs\nUSDA Food and Nutrition Service\nFood Distribution Service"},
{"slug":"splendid-fruit-salad","source_url":"https://www.myplate.gov/recipes/splendid-fruit-salad","name":"Splendid Fruit Salad","description":"Yogurt pulls all the flavors together in this splendid fruit salad! Use seasonal fruit if you have it on hand.","ingredients":[{"name":null,"items":["2 apples, medium (chopped)","1 banana (chopped)","3/4 container yogurt, low-fat vanilla (6 ounces)","1/4 teaspoon cinnamon","1/16 cup orange juice (1 tablespoon)"]}],"directions":[{"name":null,"steps":["Mix yogurt, cinnamon, and orange juice in a medium bowl.","Wash and chop the fruit and add","to the yogurt mixture. Stir and serve."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"100.54"},"notes":null,"contributor":"Iowa Department of Public Health\nIowa Nutrition Network"},
{"slug":"split-pea-soup-0","source_url":"https://www.myplate.gov/recipes/split-pea-soup-0","name":"Split Pea Soup","description":"A hearty soup of split peas, flavored with onion, carrots, celery, and thyme. This one-pot meal is sure to feed a hungry family.","ingredients":[{"name":null,"items":["2 teaspoons vegetable oil","1 Spanish onion, chopped","3 carrots, chopped","2 celery stalks, chopped","1 teaspoon dried thyme","2 1/4 cups split peas, sorted and rinsed","4 cups low-sodium chicken or vegetable broth","6 cups water","1/8 cup lemon juice"]}],"directions":[{"name":null,"steps":["Put soup pot on the stove over medium heat. Add oil when the pot is hot.","Add onion, carrots, celery, and thyme and cook 10 to 15 minutes, until tender.","Add split peas, stock, and 4 cups water. Raise the heat to high and bring to a boil.","Lower the heat to low and cook about 2 hours, partially covered, until the peas have fallen apart.","Check the soup during cooking - if more water is needed, add up to 2 cups. Skim off any foam that forms.","Serve right away or refrigerate up to three days. Stir in the lemon juice just before serving."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cups soup","calories":"334.20 kcal","carbohydrateContent":"55.43 g","cholesterolContent":"0.00 mg","fiberContent":"19.84 g","proteinContent":"22.82 g","sodiumContent":"113.36 mg","sugarContent":"9.77 g","fatContent":"4.04 g","saturatedFatContent":"0.75 g"},"notes":"If you serve this soup on the following day, you may need to add more water, as it will thicken overnight.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"split-pea-soup","source_url":"https://www.myplate.gov/recipes/split-pea-soup","name":"Split Pea Soup","description":"Simmering this soup for hours keeps your kitchen warm on a cold winter day. Add ham for an even heartier soup. Enjoy this soup with a fresh salad and warm wh...","ingredients":[{"name":null,"items":["1 large onion, chopped","3 tablespoons margarine or butter","1 1/2 cups dry split peas","6 cups water","1 teaspoon salt"]}],"directions":[{"name":null,"steps":["Cook chopped onions in margarine in a large pan until tender over medium heat.","Wash and drain split peas.","Add water, split peas, and salt to onion. Bring to boiling.","Lower heat and cover pan. Simmer about 2 hours, until thickened."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup prepared soup","1/6 of recipe"],"calories":"189.65 kcal","carbohydrateContent":"27.94 g","cholesterolContent":"0.07 mg","fiberContent":"10.40 g","proteinContent":"10.38 g","sodiumContent":"453.90 mg","sugarContent":"4.55 g","fatContent":"4.69 g","saturatedFatContent":"0.92 g"},"notes":"Optional: Cook a ham bone or pieces of ham in the soup. Remove bone and serve meat in soup.","contributor":"Wellness Ways Resource Book\nUniversity of Illinois Extension Service"},
{"slug":"spring-vegetable-saute","source_url":"https://www.myplate.gov/recipes/spring-vegetable-saute","name":"Spring Vegetable Sauté","description":"Bursting with delicious spring flavors, this delicious sauté is perfect with a side of roasted chicken, fish, or tofu.","ingredients":[{"name":null,"items":["1 teaspoon olive oil (or cooking oil of choice)","1/2 cup medium sweet onion, sliced","1 garlic clove, finely chopped","3 small new potatoes, quartered","3/4 cup carrots, sliced","3/4 cup asparagus pieces","3/4 cup sugar snap peas, or green beans","1/2 cup radishes, quartered","1/4 teaspoon salt","1/4 teaspoon black pepper","1/2 teaspoon dried dill"]}],"directions":[{"name":null,"steps":["Heat the oil in a large skillet over medium heat. Cook the onion for 2 minutes, then add the garlic and cook another minute","Stir in the potatoes and carrots. Cover, turn the heat to low, and cook until almost tender, about 4 minutes.","If the vegetables start to brown, add a tablespoon or two of water.","Now add the asparagus, peas, radishes, salt, pepper, and dill. Cook, stirring often, until just tender -- about 4 minutes more.","Serve immediately."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"138.10 kcal","carbohydrateContent":"28.49 g","cholesterolContent":"0.00 mg","fiberContent":"4.39 g","proteinContent":"4.09 g","sodiumContent":"181.02 mg","sugarContent":"4.33 g","fatContent":"1.46 g","saturatedFatContent":"0.25 g"},"notes":null,"contributor":"US Department of Health and Human Services\nNational Cancer Institute"},
{"slug":"spring-vegetable-soup","source_url":"https://www.myplate.gov/recipes/spring-vegetable-soup","name":"Spring Vegetable Soup","description":"Enjoy this tasty soup with your favorite whole grain bread sandwich. The recipe doubles easily if you need to accommodate a large family or group.","ingredients":[{"name":null,"items":["1 tablespoon extra virgin olive oil (or cooking oil of choice)","1/4 head of red cabbage, finely shredded (about 2 cups)","2 medium ripe tomatoes, seeded and chopped","1/2 cup canned artichoke hearts, drained and chopped","1 cup green peas, frozen or fresh","2 1/2 cups low-sodium vegetable juice","1 cup water","2 teaspoons dried basil","salt and pepper (freshly ground black pepper, optional, to taste)"]}],"directions":[{"name":null,"steps":["In large soup pot, heat oil over medium heat. Sauté cabbage, tomatoes, artichoke hearts, and peas for 10 minutes.","Add vegetable juice and water. Bring to boil. Reduce heat, add basil, and simmer for 10 minutes, or until all vegetables are tender and soup is piping hot.","Serve in individual serving bowls. Season to taste with salt and pepper."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"137.17 kcal","carbohydrateContent":"21.26 g","cholesterolContent":"0.00 mg","fiberContent":"5.37 g","proteinContent":"5.42 g","sodiumContent":"179.31 mg","sugarContent":"9.30 g","fatContent":"4.30 g","saturatedFatContent":"0.65 g"},"notes":null,"contributor":"American Institute for Cancer Research"},
{"slug":"springtime-cereal","source_url":"https://www.myplate.gov/recipes/springtime-cereal","name":"Springtime Cereal","description":"This delicious cereal combines sunflower seeds, almonds, fruits and yogurt for a hearty breakfast. Try with fresh strawberries from your garden or the market...","ingredients":[{"name":null,"items":["3/4 cup wheat and barley nugget cereal","1/4 cup 100% bran cereal","2/3 tablespoon (2 teaspoons) sunflower seeds, toasted","2/3 tablespoon (2 teaspoons) almonds, sliced and toasted","1 tablespoon raisins","1/2 cup bananas, sliced","1 cup strawberries, sliced, divided","1 cup low-fat strawberry yogurt (or raspberry)"]}],"directions":[{"name":null,"steps":["Mix the wheat and barley nugget cereal, bran cereal, sunflower seeds, and almonds in a medium bowl.","Add the raisins, the bananas, and half of the strawberries.","Gently stir in the yogurt and divide between two bowls.","Scatter the remaining strawberries over the top and enjoy!"]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"347.60 kcal","carbohydrateContent":"62.44 g","cholesterolContent":"6.13 mg","fiberContent":"8.44 g","proteinContent":"10.81 g","sodiumContent":"228.46 mg","sugarContent":"35.50 g","fatContent":"6.51 g","saturatedFatContent":"1.70 g"},"notes":null,"contributor":"US Department of Health and Human Services"},
{"slug":"spunky-vegetable-pizza","source_url":"https://www.myplate.gov/recipes/spunky-vegetable-pizza","name":"Spunky Vegetable Pizza","description":"Enjoy fresh, delicious pizza made at home. You can spice this up with red pepper flakes or garlic powder. Try with whatever vegetables you have on hand.","ingredients":[{"name":null,"items":["3/4 cup pizza sauce","1 Italian pizza shell (large)","1 cup broccoli (chopped)","1 cup carrots (shredded)","1/2 cup bell pepper (red or green, sliced)","5 ounces mozzarella cheese, part skim (shredded)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 450 °F.","Spoon pizza sauce on pizza shell.","Put pizza shell on a cookie sheet. Arrange vegetables over sauce. Sprinkle on the cheese.","Bake for 10 minutes.","When baked, cool pizza for 3 minutes before slicing. Cut into 8 wedges."]}],"yield":"8","nutrition":{"@type":"NutritionInformation","calories":"212.85"},"notes":null,"contributor":"California 5 A Day, It’s So Easy\nContra Costa Health Services"},
{"slug":"squash-apple-casserole","source_url":"https://www.myplate.gov/recipes/squash-apple-casserole","name":"Squash-Apple Casserole","description":"What a delicious autumn side dish! Use your favorite varieties of apples and winter squash for this tasty recipe.","ingredients":[{"name":null,"items":["2 1/2 cups winter squash (such as acorn, butternut, or Hubbard)","1 1/2 cups apples (cooking, such as Macintosh, Granny Smith, or Rome)","1/2 teaspoon nutmeg","1 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Wash and prepare squash and apples (for extra fiber, keep peel on apples).","Alternate layers of squash and apples in 8x8 inch pan; end with apples.","Sprinkle spices over top layer.","Cover with aluminum foil.","Bake at 350 °F for 45 to 60 minutes, until squash is tender."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"34.71"},"notes":null,"contributor":"Pumpkin Post and Banana Beat Newsletters\nUniversity of Massachusetts Extension\nNutrition Education Program"},
{"slug":"squash-salsa","source_url":"https://www.myplate.gov/recipes/squash-salsa","name":"Squash Salsa","description":"Summer squash is the secret ingredient in this fun summer salsa. Enjoy with your favorite whole grains.","ingredients":[{"name":null,"items":["1 can (15 ounces) low-sodium black beans, rinsed","6 medium tomatoes, seeded and diced","1/2 medium green pepper, seeded and diced","1 medium red onion, minced","1 medium summer squash, peeled, seeds removed, diced","2 tablespoons red wine vinegar","1 teaspoon Adobo seasoning (combination or garlic, coriander, salt, and cumin)","lemon or lime juice (2 tablespoons, optional)","4 tablespoons part-skim mozzarella cheese, grated","fresh cilantro or dried parsely (optional)"]}],"directions":[{"name":null,"steps":["Combine all ingredients except cheese in a large bowl. Let sit for 30 minutes.","Spoon over tortilla chips, cooked rice, or noodles.","Top with grated, part-skim mozzarella cheese and cilantro (optional). Serve hot or cold!"]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/12 of recipe"],"calories":"61.10 kcal","carbohydrateContent":"10.44 g","cholesterolContent":"1.53 mg","fiberContent":"3.66 g","proteinContent":"3.52 g","sodiumContent":"128.60 mg","sugarContent":"3.09 g","fatContent":"0.84 g","saturatedFatContent":"0.35 g"},"notes":"Out of season idea - Use 1 can diced tomatoes in place of fresh tomatoes.\nQuick salsa - Combine black beans, chopped summer squash, and a jar or your favorite salsa.\nHot Salsa - Add chopped, fresh hot peppers or canned jalapeño peppers. Remember to wash your hands well after handling hot peppers.\nNutrient analysis and costing for recipe does not include cooked rice, tortilla chips, or noodles.","contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"squash-soup","source_url":"https://www.myplate.gov/recipes/squash-soup","name":"Squash Soup","description":"Try this delicious soup with acorn squash, pumpkin, butternut squash, crookneck, or a unique variety of winter squash that you grow in your garden or can fin...","ingredients":[{"name":null,"items":["1 tablespoon olive oil (or cooking oil of choice)","2 medium onions, chopped","2 medium carrots, chopped","2 garlic cloves, minced","1 cup no salt added canned tomato sauce","5 cups low-sodium chicken or vegetable broth","4 cups winter squash, cooked","1 1/2 tablespoons dried oregano","1 1/2 tablespoons dried basil"]}],"directions":[{"name":null,"steps":["In a large saucepan, heat oil over medium heat.","Stir in onions, carrots, and garlic.","Cook for about 5 minutes, covered.","Stir in the tomato sauce, chicken broth, cooked squash, and herbs.","Bring soup to a simmer and cook, covered, for 30 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"126.82 kcal","carbohydrateContent":"19.43 g","cholesterolContent":"0.00 mg","fiberContent":"5.26 g","proteinContent":"6.25 g","sodiumContent":"81.19 mg","sugarContent":"8.23 g","fatContent":"4.13 g","saturatedFatContent":"0.87 g"},"notes":null,"contributor":"From the Farm to the Table\nUniversity of Connecticut Cooperative Extension"},
{"slug":"squash-squares","source_url":"https://www.myplate.gov/recipes/squash-squares","name":"Squash Squares","description":"This side dish is great for a big holiday meal or potluck. Try it with different veggies for a fun twist.","ingredients":[{"name":null,"items":["4 eggs (beaten lightly)","1/4 cup oil","3 cups thinly sliced squash (use zucchini or yellow squash)","1/4 cup chopped onion","1 cup biscuit mix","1 teaspoon dried parsley (or 2 tablespoons chopped fresh parsley)","1/3 cup grated cheddar cheese","1 cup grated carrots"]}],"directions":[{"name":null,"steps":["Mix all ingredients thoroughly and pour into a greased 13x9 baking dish.","Bake 25 minutes, or until bubbly and brown, in a 350 °F oven.","Serve in squares while warm."]}],"yield":"8","nutrition":{"@type":"NutritionInformation","calories":"190.53"},"notes":"To freeze: Cool, and cut into squares. Freeze squares on a cookie sheet. when they are frozen, put into freezer bags. When ready to use, take out of the freezer bag, place in microwaveable covered container. Reheat in microwave at medium setting.\nTry 8 egg whites in place of whole egg for less cholesterol and fat.\nAdd other thinly chopped fresh veggies into the mix -- green or red sweet peppers, spinach, broccoli.\nTry using the Better Baking Mix recipe instead of biscuit mix.","contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"stewed-cauliflower-tomatoes-onions","source_url":"https://www.myplate.gov/recipes/stewed-cauliflower-tomatoes-onions","name":"Stewed Cauliflower, Tomatoes, and Onions","description":"This is a delicious and filling side dish that goes well with your favorite sandwich or salad.","ingredients":[{"name":null,"items":["1 medium head of cauliflower","1 medium onion","2 large tomatoes","1 tablespoon vegetable oil (or cooking oil of choice)","1/4 teaspoon garlic powder","1/2 teaspoon ground black pepper","1 tablespoon dried parsley","1/4 cup Parmesan cheese, grated"]}],"directions":[{"name":null,"steps":["Chop the cauliflower into 2-inch pieces.","Peel the onion and chop it into small pieces.","Chop the tomatoes into small pieces.","Put the cauliflower in a medium saucepan and add 1 inch of water. Cook over medium heat, and let it boil for 3 minutes. Drain cauliflower.","In a large pan, heat the oil, and add the onion. Cook over medium heat for 3 to 5 minutes.","Add the garlic and cauliflower. Cook while stirring for 3 minutes, until lightly browned.","Add the tomatoes and pepper. Cook for 5 more minutes.","Serve with a sprinkle of parsley and cheese."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared cauliflower","1/6 of recipe"],"calories":"77.48 kcal","carbohydrateContent":"9.29 g","cholesterolContent":"2.87 mg","fiberContent":"2.80 g","proteinContent":"3.61 g","sodiumContent":"82.86 mg","sugarContent":"3.85 g","fatContent":"3.66 g","saturatedFatContent":"1.02 g"},"notes":null,"contributor":"Adapted from Spanish Cauliflower\nPennsylvania Nutrition Education Network"},
{"slug":"stir-fried-beef","source_url":"https://www.myplate.gov/recipes/stir-fried-beef","name":"Stir Fried Beef","description":"Enjoy this quick and tasty meal on a cold winter night. Add spinach, steamed in the microwave as well as an apple or orange to serve on the side.","ingredients":[{"name":null,"items":["1 1/2 pounds sirloin steak","2 teaspoons vegetable oil (or cooking oil of choice)","1 garlic clove, minced","1 teaspoon vinegar","1/8 teaspoon salt","1/8 teaspoon ground black pepper","2 large onions, sliced","1 large tomato, sliced","3 cups potatoes, diced & boiled"]}],"directions":[{"name":null,"steps":["Trim fat from steak and cut steak into small, thin pieces.","In a large skillet, heat oil and sauté garlic until garlic is golden.","Add steak, vinegar, salt, and pepper. Cook for 6 minutes, stirring beef until brown.","Add onion and tomato. Cook until onion is transparent. Serve with boiled potatoes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup","calories":"292.26 kcal","carbohydrateContent":"18.34 g","cholesterolContent":"74.99 mg","fiberContent":"2.33 g","proteinContent":"27.87 g","sodiumContent":"110.78 mg","sugarContent":"3.26 g","fatContent":"12.04 g","saturatedFatContent":"4.24 g"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"stir-fry-chicken-noodles","source_url":"https://www.myplate.gov/recipes/stir-fry-chicken-noodles","name":"Stir-Fry with Chicken and Noodles","description":"This recipe is quick to make and adaptable to your own taste! You could make it vegetarian by removing the chicken or add some extra crunch by using crunchy ...","ingredients":[{"name":null,"items":["4 cups water","2 packages (3 ounces each) ramen-style noodles","1/4 cup peanut butter","2 tablespoons low-sodium soy sauce","1/2 cup water","1 tablespoon vegetable oil (or cooking oil of choice)","2 chicken breasts, boneless, skinless, cut into strips","1 teaspoon red pepper flakes","1 teaspoon fresh ginger, finely chopped (or 1/2 teaspoon ground ginger)","2 medium carrots, thinly sliced (about 2 cups)","1/2 medium head of cabbage, thinly sliced (about 6 cups)","1/4 cup green onions, thinly sliced"]}],"directions":[{"name":null,"steps":["Bring 4 cups water to boil in a 2 to 3 quart saucepan. Add noodles, cover, and remove from heat (do not add flavor packets). Wait one minute. Drain noodles and set aside.","In a small saucepan, combine peanut butter, soy sauce and 1/2 cup water. Heat over low heat, stirring until smooth. Remove from heat.","Heat oil in a large skillet over medium-high heat (350 degrees F in an electric skillet). Add chicken and cook until no longer pink when cut, about 3 to 5 minutes.","Add red pepper, ginger, and carrots and cook for 2 to 3 minutes. Add cabbage and cook 3 to 4 minutes or until cabbage is crisp-tender.","Stir in green onion, cooked noodles, and peanut sauce. Toss and serve right away."]}],"yield":"10 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe","calories":"168.37 kcal","carbohydrateContent":"16.97 g","cholesterolContent":"23.71 mg","fiberContent":"2.24 g","proteinContent":"11.47 g","sodiumContent":"296.82 mg","sugarContent":"3.02 g","fatContent":"6.18 g","saturatedFatContent":"1.05 g"},"notes":"To avoid peanuts or peanut butter, try this stir-fry with sunflower seeds or sunflower seed butter.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"stir-fry-vegetables-and-beef","source_url":"https://www.myplate.gov/recipes/stir-fry-vegetables-and-beef","name":"Stir Fry Vegetables and Beef","description":"Looking to add more vegetables into a family-friendly meal? This recipe does the job. With a rainbow of colorful vegetables that are cooked until tender but ...","ingredients":[{"name":null,"items":["1/2 teaspoon ground ginger","1/8 teaspoon garlic powder","1 teaspoon low-sodium soy sauce","1/3 cup water","1 cup carrots (grated)","2 cups fresh mushrooms (sliced)","2 cups broccoli (chopped)","1 medium red or yellow bell pepper (sliced)","1 medium onion, chopped","2 tablespoons vegetable oil (or cooking oil of choice)","8 ounces sliced beef chuck roast"]}],"directions":[{"name":null,"steps":["Mix spices, soy sauce, and water; set aside.","Wash vegetables. Shred carrots and slice mushrooms. Chop broccoli, peppers, and onions.","Heat oil in large frying pan and add meat when oil is hot; stir until brown.","Push meat to the side and in the middle of the pan add carrots, onions, and peppers. Cook them for one minute.","Add mushrooms and broccoli. Cook until they are tender.","Add liquid mixture and cook until bubbly.","Reduce heat, cover pan, and cook for two more minutes.","Serve over whole wheat pasta or brown rice."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"219.97 kcal","carbohydrateContent":"12.72 g","cholesterolContent":"36.94 mg","fiberContent":"3.27 g","proteinContent":"13.62 g","sodiumContent":"112.55 mg","sugarContent":"5.50 g","fatContent":"13.08 g","saturatedFatContent":"3.26 g"},"notes":null,"contributor":"Texas Cooperative Extension Expanded Nutrition Program\nThe Texas A&M University System"},
{"slug":"stove-top-casserole","source_url":"https://www.myplate.gov/recipes/stove-top-casserole","name":"Stove Top Casserole","description":"An easy, meatless meal made with potatoes, cabbage, nuts of your choice, and cheese.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil","1 onion (small, coarsely chopped)","4 potatoes (medium, peeled and sliced 1/4 inch thick)","1 1/2 cups chicken stock, low-sodium","2 cups green cabbage (shredded)","1 cup Swiss cheese, shredded","1/4 cup nuts (chopped)"]}],"directions":[{"name":null,"steps":["Heat oil in large skillet or Dutch oven. Add onions and stir over medium heat until golden.","Add potatoes and chicken stock. Cover tightly, reduce heat to low and simmer until potatoes are almost tender.","Add cabbage, cover and simmer for another 5 minutes.","Remove cover, sprinkle with cheese and nuts.","Let stand just until cheese is melted, about 2 minutes."]}],"yield":"5","nutrition":{"@type":"NutritionInformation","calories":"305.39"},"notes":null,"contributor":"Oregon’s Healthy Harvest Recipes\nOregon State University Cooperative Extension Service"},
{"slug":"stove-top-green-chile-chicken-enchiladas","source_url":"https://www.myplate.gov/recipes/stove-top-green-chile-chicken-enchiladas","name":"Stove Top Green Chile Chicken Enchiladas","description":"Make these delicious enchiladas without even turning on your oven. A quick and hearty meal.","ingredients":[{"name":null,"items":["1 tablespoon olive oil (or cooking oil of choice)","2/3 medium onion, chopped","1/4 cup flour","2 1/2 cups canned diced green chilies","2 cups low-sodium chicken broth","2 cups chicken breast, cooked & shredded","1/2 teaspoon garlic powder","1 tablespoon cornstarch","8 (6-inch) corn tortillas","1 1/2 cups extra-sharp cheddar cheese, finely shredded"]}],"directions":[{"name":null,"steps":["Heat the oil in a medium saucepan.","Saute the chopped onion in the oil. Add the flour and cook for 1 minute.","Add the chilies, chicken broth, chicken and garlic powder. Simmer uncovered for 5 minutes.","Mix the cornstarch into about 1/4 cup of cold water until all the lumps are gone. Add to the chile and chicken mixture. Cook for 2 more minutes.","Tear the tortillas into strips and divide into thirds. Add them to the pan and cook until they are hot, stirring with a spoon from time to time.","Sprinkle the cheese over the enchiladas. Cover the pan and cook until the cheese has melted. Serve immediately."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"347.45 kcal","carbohydrateContent":"27.89 g","cholesterolContent":"72.71 mg","fiberContent":"3.79 g","proteinContent":"25.19 g","sodiumContent":"478.40 mg","sugarContent":"1.25 g","fatContent":"15.31 g","saturatedFatContent":"6.48 g"},"notes":null,"contributor":"New Mexico State University Cooperative Extension"},
{"slug":"stove-top-potato-and-cabbage-casserole","source_url":"https://www.myplate.gov/recipes/stove-top-potato-and-cabbage-casserole","name":"Stove Top Potato and Cabbage Casserole","description":"An easy, meatless meal made with potatoes, cabbage, nuts of your choice, and cheese.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","1 small onion, coarsely chopped","4 medium potatoes, peeled and sliced 1/4 inch thick","1 1/2 cups low-sodium chicken stock","2 cups green cabbage, shredded","1 cup Swiss cheese, shredded","1/4 cup nuts, chopped"]}],"directions":[{"name":null,"steps":["Heat oil in large skillet or Dutch oven. Add onions and stir over medium heat until golden.","Add potatoes and chicken stock. Cover tightly, reduce heat to low and simmer until potatoes are almost tender.","Add cabbage, cover and simmer for another 5 minutes.","Remove cover, sprinkle with cheese and nuts.","Let stand just until cheese is melted, about 2 minutes."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"314.39 kcal","carbohydrateContent":"36.65 g","cholesterolContent":"20.09 mg","fiberContent":"5.00 g","proteinContent":"12.90 g","sodiumContent":"105.63 mg","sugarContent":"4.46 g","fatContent":"13.98 g","saturatedFatContent":"5.05 g"},"notes":null,"contributor":"Adapted from Stove Top Casserole\nOregon’s Healthy Harvest Recipes\nOregon State University Cooperative Extension Service"},
{"slug":"stovetop-tamale-pie","source_url":"https://www.myplate.gov/recipes/stovetop-tamale-pie","name":"Stovetop Tamale Pie","description":"One skillet beef and bean tamale pie that cooks on the stovetop. For an extra kick, add your favorite hot sauce to this tasty tamale pie.","ingredients":[{"name":"Quick Chili","items":["1/2 pound 90% lean ground beef","1 can (15.5 ounces) low-sodium kidney beans, drain and save liquid","1/3 cup bean liquid*","1 cup canned tomato purée","1 tablespoon onion, minced","1/8 tablespoon chili powder","1 can (15.2 ounces) whole kernel corn, not drained"]},{"name":"Tamale Pie","items":["1/2 cup yellow cornmeal","1 dash salt","1 1/4 cups cold water","1/8 teaspoon chili powder"]}],"directions":[{"name":"Prepare Chili","steps":["Cook beef in large, hot skillet until lightly browned. Drain off fat.","Stir in remaining ingredients. Bring to a boil.","Reduce heat, cover, and simmer 10 minutes.","Stir in corn."]},{"name":"Prepare Tamale Pie","steps":["Place chili in a 10-inch skillet. Heat thoroughly.","As chili heats, mix cornmeal and salt with water in a medium sauce pan. Cook over medium heat, stirring constantly until thickened, about 2 minutes.","Spread cornmeal mixture over hot chili to form a crust. Sprinkle with chili powder.","Cover and cook over low heat, with lid slightly ajar, until topping is set, about 10 minutes.","Optional - Top with light sour cream or low-fat yogurt."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"312.00 kcal","carbohydrateContent":"46.89 g","cholesterolContent":"32.86 mg","fiberContent":"10.11 g","proteinContent":"20.07 g","sodiumContent":"442.77 mg","sugarContent":"9.08 g","fatContent":"6.66 g","saturatedFatContent":"2.16 g"},"notes":"*Bean liquid is not included in the nutrition or cost analysis.","contributor":"University of Illinois Extension Service"},
{"slug":"strawberries-watermelon-pineapple-salad","source_url":"https://www.myplate.gov/recipes/strawberries-watermelon-pineapple-salad","name":"Strawberries, Watermelon, and Pineapple Salad","description":"Toss this fruit salad together in a flash. Doubles and triples easily for a large group.","ingredients":[{"name":null,"items":["1 cup fresh strawberries, diced (or frozen)","1 cup watermelon, cubed","1 cup fresh pineapple chunks, or canned packed in natural juice (do not drain)"]}],"directions":[{"name":null,"steps":["Stir fruit together in a medium-sized bowl.","Cover and chill. Serve as soon as possible."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup fruit salad","1/4 of recipe"],"calories":"45.38 kcal","carbohydrateContent":"11.19 g","cholesterolContent":"0.00 mg","fiberContent":"1.41 g","proteinContent":"0.70 g","sodiumContent":"4.55 mg","sugarContent":"8.47 g","fatContent":"0.19 g","saturatedFatContent":"0.01 g"},"notes":"Refrigerate leftovers (or try freezing for a slush).","contributor":"University of Nebraska-Lincoln Cooperative Extension"},
{"slug":"strawberries-white-bean-and-edamame-salad","source_url":"https://www.myplate.gov/recipes/strawberries-white-bean-and-edamame-salad","name":"Strawberries, White Bean, and Edamame Salad","description":"A flavorful, enticing mix of fresh strawberries, white beans, and edamame in a light vinaigrette nested on a baby spinach and topped with crumbled feta chees...","ingredients":[{"name":"For the Vinaigrette","items":["1 1/2 cups strawberries","1 1/2 tablespoons extra virgin olive oil","2 tablespoons balsamic vinegar","1/4 cup apple juice","1/4 teaspoon salt","1/8 teaspoon pepper"]},{"name":"For the Salad","items":["1 1/2 cups shelled edamame","1 15-ounce can low sodium white beans, drained and rinsed","1/2 cup red onion, chopped","2 tablespoons fresh basil, chopped","1/2 cup crumbled feta cheese","6 cups baby spinach"]}],"directions":[{"name":null,"steps":["Cook edamame according to package directions, while preparing remaining ingredients.","Rinse under cool water and drain.","In a small bowl, whisk vinaigrette ingredients.","In a medium bowl, toss all ingredients except spinach and vinaigrette.","Serve on individual plates by nesting strawberry, white bean and edamame mix atop spinach.","Drizzle with dressing."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"294.64 kcal","carbohydrateContent":"28.32 g","cholesterolContent":"16.69 mg","fiberContent":"9.18 g","proteinContent":"15.06 g","sodiumContent":"557.76 mg","sugarContent":"9.74 g","fatContent":"14.17 g","saturatedFatContent":"3.84 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"strawberry-banana-parfait","source_url":"https://www.myplate.gov/recipes/strawberry-banana-parfait","name":"Strawberry Banana Parfait","description":"Enjoy the flavors of layered strawberries, crispy cereal flakes, and creamy yogurt in this delicious parfait. Serve as a fruit-filled breakfast option or a b...","ingredients":[{"name":null,"items":["1/2 medium ripe banana, mashed","1/8 teaspoon vanilla","1/3 cup plain non-fat yogurt","1/2 cup sliced fresh strawberries","1/2 cup bran and wheat flakes ready-to-eat cereal"]}],"directions":[{"name":null,"steps":["Stir banana and vanilla into yogurt and combine well.","In a 10 to 12 ounce glass, alternately layer the yogurt-banana mixture, strawberries, and cereal.","Serve immediately and enjoy."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 strawberry banana parfait","calories":"224.46 kcal","carbohydrateContent":"45.05 g","cholesterolContent":"1.62 mg","fiberContent":"7.55 g","proteinContent":"7.99 g","sodiumContent":"216.05 mg","sugarContent":"24.06 g","fatContent":"1.09 g","saturatedFatContent":"0.21 g"},"notes":null,"contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"strawberry-kiwi-yogurt-pops","source_url":"https://www.myplate.gov/recipes/strawberry-kiwi-yogurt-pops","name":"Strawberry Kiwi Yogurt Pops","description":"Cool off with frozen pops that are fun to make! Mix different yogurt and fruit combinations to find your favorite.","ingredients":[{"name":null,"items":["1 cup low-fat vanilla yogurt","1 kiwi","4 large strawberries (about 1/2 cup chopped)","ice cube tray or small paper cups","paper straws or popsicle sticks"]}],"directions":[{"name":null,"steps":["Cut kiwi and strawberries into small pieces.","Add yogurt to chopped fruit and mix well to combine.","Divide into 8 ice cube squares (or 4 small paper cups).","Place in cut paper straws or popsicle sticks.","Freeze and enjoy!"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 yogurt pop cubes","calories":"63.01 kcal","carbohydrateContent":"10.01 g","cholesterolContent":"3.68 mg","fiberContent":"0.89 g","proteinContent":"3.43 g","sodiumContent":"44.39 mg","sugarContent":"8.66 g","fatContent":"1.05 g","saturatedFatContent":"0.60 g"},"notes":"Create your own yogurt pops and experiment with different flavors or try out one of these recipes:\nBanana Cocoa Yogurt Pops\nStrawberry Yogurt Pops\nTropical Yogurt Pops","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"strawberry-mango-feta-toast-points","source_url":"https://www.myplate.gov/recipes/strawberry-mango-feta-toast-points","name":"Strawberry Mango Feta Toast Points","description":"Diced strawberries, mango, and fat-free feta cheese provide the perfect balance of sweet, savory, and tangy for these quick and colorful brunch or lunch toas...","ingredients":[{"name":null,"items":["1 mango, ripe, divided","2 cups strawberries, divided","1/2 cup fat-free feta cheese crumbles","2 tablespoons balsamic vinegar","1 cup basil leaves (plus 2 tablespoons for topping)","2 tablespoons olive oil","4 slices whole wheat bread"]}],"directions":[{"name":null,"steps":["Peel and pit mango. Dice 3/4 of mango and 3/4 of strawberries; place in large bowl with feta cheese. Put remaining fruit, 1/4 cup basil, vinegar, and oil in a blender and blend.","Pour blended vinaigrette over fruit-feta mix and toss gently.","Chop remaining basil leaves.","Toast bread slices and cut each slice diagonally.","Top toast points with dressed fruit-feta mix and chopped basil."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"264.83 kcal","carbohydrateContent":"30.07 g","cholesterolContent":"16.69 mg","fiberContent":"4.45 g","proteinContent":"8.19 g","sodiumContent":"384.53 mg","sugarContent":"12.83 g","fatContent":"12.71 g","saturatedFatContent":"3.89 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"strawberry-smores","source_url":"https://www.myplate.gov/recipes/strawberry-smores","name":"Strawberry S''Mores","description":"No campfire required for these fruity graham cracker snacks!","ingredients":[{"name":null,"items":["2 strawberries","1/8 cup (2 tablespoons) low-fat vanilla yogurt","1 graham cracker, broken in half"]}],"directions":[{"name":null,"steps":["Rinse the strawberries in water.","Slice the strawberries.","Add the yogurt and strawberries to 1/2 of graham cracker.","Top with the other 1/2 of graham cracker.","Enjoy immediately."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 strawberry s''more","calories":"100.35 kcal","carbohydrateContent":"17.53 g","cholesterolContent":"1.91 mg","fiberContent":"1.16 g","proteinContent":"2.86 g","sodiumContent":"102.66 mg","sugarContent":"8.77 g","fatContent":"2.15 g","saturatedFatContent":"0.55 g"},"notes":"Substitute any desired low-fat yogurt flavor.\nTry other fruits like blueberries, bananas, etc.","contributor":"University of Maryland Cooperative Extension\nFood Supplement Nutrition Education Program\nThe University of Connecticut, SNAP4CT (photo)"},
{"slug":"strawberry-yogurt-pops","source_url":"https://www.myplate.gov/recipes/strawberry-yogurt-pops","name":"Strawberry Yogurt Pops","description":"Strawberries and yogurt are all you need for this healthy frozen pop! They''re a great after school snack or sweet treat.","ingredients":[{"name":null,"items":["1 cup low-fat strawberry yogurt","6 large strawberries, fresh or frozen","ice cube tray or small paper cups","paper straws or popsicle sticks"]}],"directions":[{"name":null,"steps":["Cut strawberries into small pieces.","Place strawberries and yogurt into blender and mix until smooth.","Pour into 8 ice cube squares (or 4 small paper cups) and place in cut paper straws or popsicle sticks.","Freeze and enjoy!"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 yogurt pop cubes","calories":"63.96 kcal","carbohydrateContent":"10.94 g","cholesterolContent":"3.06 mg","fiberContent":"0.55 g","proteinContent":"3.03 g","sodiumContent":"42.51 mg","sugarContent":"8.79 g","fatContent":"0.90 g","saturatedFatContent":"0.54 g"},"notes":"Create your own yogurt pops and experiment with different flavors or try out one of these recipes:\nBanana Cocoa Yogurt Pops\nTropical Yogurt Pops\nStrawberry Kiwi Yogurt Pops","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"stuffed-baked-potatoes","source_url":"https://www.myplate.gov/recipes/stuffed-baked-potatoes","name":"Stuffed Baked Potatoes","description":"Pair these delicious stuffed potatoes with grilled or baked meat, fish, or tofu.","ingredients":[{"name":null,"items":["4 medium baking potatoes","3/4 cup low-fat cottage cheese","1/4 cup 1% low-fat milk","2 tablespoons margarine, soft tub","1 teaspoon dill weed","3/4 teaspoon herb seasoning","1/4 teaspoon hot pepper sauce (or to taste)","2 tablespoons Parmesan cheese"]}],"directions":[{"name":null,"steps":["Prick potatoes with fork. Bake at 425 degrees F for 60 minutes or until fork is easily inserted.","Cut potatoes in half lengthwise. Carefully scoop out potato, leaving about 1/2 inch of pulp inside shell. Mash pulp in large bowl.","Mix remaining ingredients with the mashed potato, except Parmesan cheese. Spoon mixture into potato shells.","Sprinkle top of each stuffed potato with Parmesan cheese.","Place on baking sheet and return to oven. Bake 15 to 20 minutes or until tops are golden brown."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 potato","calories":"125.39 kcal","carbohydrateContent":"19.71 g","cholesterolContent":"4.03 mg","fiberContent":"1.92 g","proteinContent":"5.15 g","sodiumContent":"122.29 mg","sugarContent":"2.27 g","fatContent":"3.13 g","saturatedFatContent":"0.97 g"},"notes":null,"contributor":"Adapted from \"Wonderful Stuffed Potatoes\"\nA Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"stuffed-bell-peppers","source_url":"https://www.myplate.gov/recipes/stuffed-bell-peppers","name":"Stuffed Bell Peppers","description":"Peppers stuffed with a combination of ground beef, brown rice, veggies, and spices create a filling dish. Try using red, green, yellow, and orange bell peppe...","ingredients":[{"name":null,"items":["5 bell peppers (red, orange, yellow, or green)","1 pound 90% lean ground beef","3/4 cup brown rice","1/2 can (14.5 ounces) low-sodium diced tomatoes","3 tablespoons lemon juice","1/4 teaspoon cinnamon","1/4 teaspoon allspice","1/4 teaspoon ground black pepper"]}],"directions":[{"name":null,"steps":["Cut a circular hole in the tops of the bell peppers. Remove seeds and membrane and set aside.","In a large bowl, combine remaining ingredients and stir until completely mixed. Fill the bell peppers with meat mixture.","Place the stuffed bell peppers in large stock pot on stove, with the tops facing up. Add 1-inch water to bottom of pot and cover.","Place heat on medium, keeping covered for 30 to 40 minutes until rice is done. Serve."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 stuffed pepper","1/5 of recipe"],"calories":"282.97 kcal","carbohydrateContent":"33.65 g","cholesterolContent":"52.58 mg","fiberContent":"3.84 g","proteinContent":"19.78 g","sodiumContent":"59.59 mg","sugarContent":"5.09 g","fatContent":"7.94 g","saturatedFatContent":"2.92 g"},"notes":"See how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"stuffed-green-peppers","source_url":"https://www.myplate.gov/recipes/stuffed-green-peppers","name":"Stuffed Green Peppers","description":"These tasty stuffed peppers make a delicious and filling entrée. Use brown rice to increase your whole grains.","ingredients":[{"name":null,"items":["4 large green bell pepper, washed","1 pound 85% lean ground turkey","1 cup uncooked rice","1/2 cup onion, peeled and chopped","1 1/2 cups low-sodium tomato sauce","ground black pepper (to taste)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 350 degrees F.","Cut around the stem of the green bell peppers. Remove the seeds and the pulpy part of the peppers.","Wash, and then cook peppers in boiling water for five minutes. Drain well.","In saucepan, brown turkey. Add rice, onion, 1/2 cup tomato sauce, and black pepper.","Stuff each pepper with the mixture and place in casserole dish.","Pour the remaining tomato sauce over the green peppers.","Cover and bake for 30 minutes at 350 degrees F."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"451.65"},"notes":null,"contributor":"From Pyramid to the Plate: Healthy Eating by Timing, Combining, and Planning\nAdopted from: Eating Right is Basic\nMichigan State University Extension"},
{"slug":"stuffed-pasta-shells","source_url":"https://www.myplate.gov/recipes/stuffed-pasta-shells","name":"Stuffed Pasta Shells","description":"Spinach, a mixture of low-fat cheeses, and herbs combine for a delicious filling in these stuffed shells.","ingredients":[{"name":null,"items":["1 package (10 ounces) frozen chopped spinach, thawed","12 ounces low-fat cottage cheese","1 1/2 cups part skim mozzarella cheese, shredded, divided","1 1/2 teaspoons dried oregano","1/4 teaspoon black pepper","1 (24 ounce) jar low-sodium spaghetti sauce","1 cup water","6 ounces large pasta shells, uncooked"]}],"directions":[{"name":null,"steps":["Preheat oven to 375 degrees F. Lightly coat a 13x9x2-inch baking dish with cooking spray. Set aside.","Drain spinach by placing in a sieve or colander over the sink, or in a bowl and pressing with a spool to remove as much liquid as possible or squeeze out liquid with clean hands. Place spinach in medium bowl.","Add the cottage cheese, 1 cup of the mozzarella cheese, oregano, and pepper to the spinach. Stir to mix thoroughly.","Pour half of the spaghetti sauce into prepared baking dish. Add water and stir into the mix.","Spoon about 3 tablespoons cheese mixture into each uncooked pasta shell. Arrange in a single layer over top.","Pour remaining sauce over top.","Sprinkle with remaining 1/2 cup mozzarella cheese evenly over sauce.","Cover tightly with foil. Bake for 1 hour or until shells are tender. Let stand 10 minutes before serving."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup","1/8 of recipe"],"calories":"225.86 kcal","carbohydrateContent":"27.79 g","cholesterolContent":"18.87 mg","fiberContent":"3.84 g","proteinContent":"15.65 g","sodiumContent":"330.18 mg","sugarContent":"5.69 g","fatContent":"6.44 g","saturatedFatContent":"3.22 g"},"notes":"Try this recipe for a potluck or make-ahead dinner. If desired, refrigerate the ready-to-bake casserole.\nTo lower sodium, use reduced sodium spaghetti sauce.","contributor":"Spend Smart. Eat Smart, Adapted from Easy Stuffed Pasta Shells\nIowa State University Extension"},
{"slug":"stuffed-summer-squash","source_url":"https://www.myplate.gov/recipes/stuffed-summer-squash","name":"Stuffed Summer Squash","description":"Summer squash stuffed with brown rice, fresh basil, beans, cheese, and veggies make a hearty and filling dish. Try this tasty recipe when summer squash are a...","ingredients":[{"name":null,"items":["2 medium summer squash","3 cups cooked brown rice","1 cup diced tomatoes","1 cup white beans, drained and rinsed","1 tablespoon fresh basil","4 tablespoons Parmesan cheese"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Wash and cut both squash in half, lengthwise. Remove the large seeds.","Steam the squash, skin side down, in a small amount of water in a fry pan or skillet until slightly tender (but not mushy).","Scoop out a good amount of pulp (1 cup), place in a bowl and mix with other ingredients (brown rice through Parmesan cheese).","Place the squash shells in a baking dish. Stuff the squash with the stuffing mixture.","Top with grated Parmesan cheese. Bake in preheated oven for about 30 minutes."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"299.67 kcal","carbohydrateContent":"56.55 g","cholesterolContent":"4.30 mg","fiberContent":"6.85 g","proteinContent":"11.81 g","sodiumContent":"240.33 mg","sugarContent":"4.83 g","fatContent":"3.44 g","saturatedFatContent":"1.37 g"},"notes":"Other Stuffing Options:\nRice + Turkey Stuffing: 1 cup squash pulp, 1 pound cooked ground turkey, 2 cups cooked brown rice, 1 can low-sodium condensed cream of mushroom soup, 2 tablespoons shredded cheddar cheese\nCornbread Stuffing: 2 cups squash pulp, 2 cups cornbread stuffing from a mix, dry, 1 cup diced cook chicken or ham, 1/4 cup raisins, 1/4 cup almonds or other nuts","contributor":"Connecticut Food Policy Council"},
{"slug":"stuffed-tomatoes","source_url":"https://www.myplate.gov/recipes/stuffed-tomatoes","name":"Stuffed Tomatoes","description":"Stuffed tomatoes make a delicious side dish to the Baked Chicken with Vegetables, both dishes bake at 400 °F, add the stuffed tomatoes to the oven for the l...","ingredients":[{"name":null,"items":["1 small onion","3 large tomatoes","1 cup unseasoned bread crumbs","2 teaspoons dried parsley","2 teaspoons dried basil","1/2 teaspoon black pepper","1/4 teaspoon garlic powder","1 tablespoon vegetable oil (or cooking oil of choice)","1/4 cup water, or more as needed"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 degrees F.","Peel the onion. Chop it into small pieces.","Cut each tomato in half. Remove the part with the stem.","Gently squeeze each tomato half over the sink to remove the seeds.","Put the breadcrumbs into medium bowl. Add the spices and oil.","Mix well, slowly adding water to moisten the crumbs.","Use a spoon to press the crumb mixture into the tomato halves.","Lightly oil a baking pan. Place the tomatoes on the pan, with the cut side up.","Bake for 15 to 20 minutes, until the crumbs are browned and the tomatoes are soft."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 stuffed tomato","1/6 of recipe"],"calories":"114.03 kcal","carbohydrateContent":"17.92 g","cholesterolContent":"0.00 mg","fiberContent":"1.88 g","proteinContent":"3.37 g","sodiumContent":"140.24 mg","sugarContent":"3.51 g","fatContent":"3.41 g","saturatedFatContent":"0.57 g"},"notes":"If you don’t have a box of breadcrumbs, make your own. Toast 4 slices of bread. Crush with a rolling pin or the side of a jar to make breadcrumbs. If you don’t have breadcrumbs or bread, crush 3 cups of a flaked cereal instead.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"sugar-and-spice-cookies-better-baking-mix","source_url":"https://www.myplate.gov/recipes/sugar-and-spice-cookies-better-baking-mix","name":"Sugar and Spice Cookies (from Better Baking Mix)","description":"Use our Better Baking Mix for this quick and easy recipe. You can double the recipe if baking for a crowd.","ingredients":[{"name":null,"items":["1 Better Baking Mix","1/2 cup brown sugar, packed (or white sugar)","1 teaspoon cinnamon","raisins (1/3 cup, optional)","1/4 cup vegetable oil (or cooking oil of choice)","1 egg","1/2 teaspoon vanilla"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F. Lightly grease baking sheet.","In a mixing bowl, combine baking mix, sugar, cinnamon, and raisins (optional). Stir to mix.","Put oil, egg, and vanilla in a small bowl. Beat with a fork to mix.","Add oil and egg mix to the dry ingredients.","Stir to combine. Dough will be thick.","Measure level tablespoons of dough. Drop on cookie sheet about 2 inches apart. Dough will spread 2 1/2 to 3-inch wide cookies as it bakes.","Bake 10 to 12 minutes or until edges start to turn brown. Be careful not to overbake.","Remove cookies from baking sheet while still warm."]}],"yield":"18 Cookies","nutrition":{"@type":"NutritionInformation","servingSize":["1 cookie","1/18 of recipe"],"calories":"76.69 kcal","carbohydrateContent":"10.17 g","cholesterolContent":"11.53 mg","fiberContent":"0.36 g","proteinContent":"1.14 g","sodiumContent":"35.10 mg","sugarContent":"6.27 g","fatContent":"3.55 g","saturatedFatContent":"0.55 g"},"notes":null,"contributor":"Washington State University Extension"},
{"slug":"summer-breeze-smoothie","source_url":"https://www.myplate.gov/recipes/summer-breeze-smoothie","name":"Summer Breeze Smoothie","description":"A delicious smoothie makes the perfect summer snack or dessert.","ingredients":[{"name":null,"items":["1 cup fat-free plain yogurt","6 medium strawberries","1 cup crushed pineapple, canned in juice","1 medium banana","1 teaspoon vanilla extract","4 ice cubes"]}],"directions":[{"name":null,"steps":["Place all ingredients in blender and purée until smooth.","Serve in frosted glass."]}],"yield":"3 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"130.61 kcal","carbohydrateContent":"25.93 g","cholesterolContent":"1.63 mg","fiberContent":"2.13 g","proteinContent":"5.52 g","sodiumContent":"68.23 mg","sugarContent":"20.43 g","fatContent":"0.41 g","saturatedFatContent":"0.15 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"summer-fruit-salad","source_url":"https://www.myplate.gov/recipes/summer-fruit-salad","name":"Summer Fruit Salad","description":"Toss this fruit salad together in a flash. Doubles and triples easily for a large group.","ingredients":[{"name":null,"items":["1 cup fresh strawberries, diced (or frozen)","1 cup watermelon, cubed","1 cup fresh pineapple chunks, or canned packed in natural juice (do not drain)"]}],"directions":[{"name":null,"steps":["Stir fruit together in a medium-sized bowl.","Cover and chill. Serve as soon as possible."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"45.31"},"notes":"Refrigerate leftovers (or try freezing for a slush).","contributor":"University of Nebraska-Lincoln Cooperative Extension"},
{"slug":"summer-italian-vegetables","source_url":"https://www.myplate.gov/recipes/summer-italian-vegetables","name":"Summer Italian Vegetables","description":"Fresh tomatoes, summer squash, green peppers, and onions give this cheesy side dish a boost to any summer meal. Use any vegetables that you have on hand or f...","ingredients":[{"name":null,"items":["1 medium onion, diced","1 medium yellow squash (or zucchini), diced","1 medium tomato, diced","1 medium green bell pepper, chopped","1/2 teaspoon oregano","1 can (8 ounces) low-sodium tomato sauce","1/2 cup part-skim mozzarella cheese, shredded"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Combine onion, squash, tomato, and green pepper in a baking dish.","Sprinkle with oregano.","Pour the tomato sauce over the vegetables.","Bake, uncovered at 350 degrees F for 20 to 30 minutes.","Top with cheese and bake another 4 to 5 minutes until cheese is melted.","Refrigerate leftovers."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 serving","1/6 of recipe"],"calories":"61.49 kcal","carbohydrateContent":"7.95 g","cholesterolContent":"6.12 mg","fiberContent":"1.73 g","proteinContent":"3.67 g","sodiumContent":"74.94 mg","sugarContent":"4.48 g","fatContent":"2.22 g","saturatedFatContent":"1.17 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"summer-salad","source_url":"https://www.myplate.gov/recipes/summer-salad","name":"Summer Salad","description":"This salad can be tossed together, lightening fast. Walnuts give this salad a delightful crunch. Enjoy as a tasty side dish.","ingredients":[{"name":null,"items":["2 cups salad greens","6 green onions, thinly sliced","6 fresh large mushrooms, thinly sliced","1/4 cup walnuts, coarsely chopped","3/4 cup fresh parsley, finely chopped","3/4 Tangy Dressing"]}],"directions":[{"name":null,"steps":["Wash and dry greens. Tear into bite-sized pieces and place in large salad bowl.","Add onion, mushrooms, walnuts, and parsley. Just before serving, toss with dressing."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 serving","1/8 of recipe"],"calories":"68.04 kcal","carbohydrateContent":"9.34 g","cholesterolContent":"0.38 mg","fiberContent":"1.16 g","proteinContent":"2.59 g","sodiumContent":"21.72 mg","sugarContent":"6.65 g","fatContent":"2.70 g","saturatedFatContent":"0.31 g"},"notes":null,"contributor":"Creative Vegetable Cookery\nNorth Dakota State University Extension Service"},
{"slug":"summer-squash-italian-style","source_url":"https://www.myplate.gov/recipes/summer-squash-italian-style","name":"Summer Squash, Italian Style","description":"Fresh sweet basil and cheese give summer squash a burst of flavor.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil","1 summer squash (medium, thinly sliced)","1 tablespoon water","salt and pepper (optional, to taste)","1 tablespoon sweet basil, fresh","6 tablespoons Parmesan cheese or Romano cheese (grated)"]}],"directions":[{"name":null,"steps":["Using a large, oven-proof frying pan, heat 1 tablespoon of oil on medium-high.","Arrange squash in pan, add water, and season lightly with salt, pepper, and basil.","Cover and cook over medium heat for 5 minutes, or until tender crisp.","Sprinkle with cheese and drizzle with remaining oil. Place under a preheated broiler and broil until cheese melts and browns slightly.","Tip: Add cut up fresh tomatoes, green peppers, green beans, eggplant, onions, or other vegetables in season."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"97.64"},"notes":null,"contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"summer-squash-medley","source_url":"https://www.myplate.gov/recipes/summer-squash-medley","name":"Summer Squash Medley","description":"Garlic powder and onion give summer veggies a nice flavor. Combined with canned tomatoes, this dish can be eaten as a side dish or serve over whole grain pas...","ingredients":[{"name":null,"items":["1 tablespoon olive oil (or cooking oil of choice)","1 1/2 medium zucchini, sliced","1 1/2 medium yellow summer squash, sliced","1 small onion, sliced","1 can (14.5 ounces) diced Italian tomatoes","1/4 teaspoon garlic powder","salt and pepper (to taste, optional)","2 tablespoons Parmesan cheese, grated"]}],"directions":[{"name":null,"steps":["In large skillet, heat oil.","To heated oil, add yellow squash, zucchini, and onion. Cook on medium heat until tender, about 10 minutes, stirring often.","Add tomatoes and simmer 5 minutes.","Season with garlic powder to taste. Add salt and pepper (optional), if desired.","Serve warm, topped with Parmesan cheese."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 serving","1/6 of recipe"],"calories":"66.22 kcal","carbohydrateContent":"8.26 g","cholesterolContent":"1.43 mg","fiberContent":"2.71 g","proteinContent":"2.39 g","sodiumContent":"108.00 mg","sugarContent":"5.37 g","fatContent":"3.30 g","saturatedFatContent":"0.75 g"},"notes":null,"contributor":"University of Maryland Cooperative Extension\nFood Supplement Nutrition Education Program"},
{"slug":"summer-squash-squares","source_url":"https://www.myplate.gov/recipes/summer-squash-squares","name":"Summer Squash Squares","description":"This side dish is great for a big holiday meal or potluck. Try it with different veggies for a fun twist.","ingredients":[{"name":null,"items":["4 eggs, beaten lightly","1/4 cup vegetable oil (or cooking oil of choice)","3 cups thinly sliced zucchini (or yellow squash)","1/4 cup chopped onion","1 cup biscuit mix","1 teaspoon dried parsley (or 2 tablespoons chopped fresh parsley)","1/3 cup grated cheddar cheese","1 cup grated carrots"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Mix all ingredients thoroughly and pour into a greased 13x9-inch baking dish.","Bake in preheated oven for 25 minutes, or until bubbly and brown.","Cut into 8 squares and serve while warm."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"201.80 kcal","carbohydrateContent":"13.81 g","cholesterolContent":"107.73 mg","fiberContent":"1.26 g","proteinContent":"6.13 g","sodiumContent":"279.31 mg","sugarContent":"3.93 g","fatContent":"13.70 g","saturatedFatContent":"3.33 g"},"notes":"To freeze: Cool, and cut into squares. Freeze squares on a cookie sheet. when they are frozen, put into freezer bags. When ready to use, take out of the freezer bag, place in microwaveable covered container. Reheat in microwave at medium setting.\nTry 8 egg whites in place of whole egg for less cholesterol and fat.\nAdd other thinly chopped fresh veggies into the mix -- green or red sweet peppers, spinach, broccoli.\nTry using the Better Baking Mix recipe instead of biscuit mix.","contributor":"Adapted from Squash Squares, Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"summer-squash-stir-fry","source_url":"https://www.myplate.gov/recipes/summer-squash-stir-fry","name":"Summer Squash Stir Fry","description":"Jazz up this summer dish by adding cumin, garlic powder, or fresh basil.","ingredients":[{"name":null,"items":["1 tablespoon olive oil (or cooking oil of choice)","1 small onion, chopped","1 cup carrots, thinly sliced","2 cups summer squash, washed and sliced","seasonings, to taste, optional (suggested seasonings: garlic powder, pepper, cumin, thyme, basil, or oregano)"]}],"directions":[{"name":null,"steps":["In a large skillet, heat oil on medium-high heat.","Add onion and stir fry until onion is clear and begins to brown.","Add carrots and stir until carrots are tender and crisp. Add squash and cook for about 2 minutes. Lower heat.","Add seasonings of choice. Cook for 2 more minutes. Serve as a side dish."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/4 of recipe"],"calories":"68.05 kcal","carbohydrateContent":"8.14 g","cholesterolContent":"0.00 mg","fiberContent":"1.99 g","proteinContent":"1.28 g","sodiumContent":"24.09 mg","sugarContent":"4.41 g","fatContent":"3.77 g","saturatedFatContent":"0.61 g"},"notes":null,"contributor":"Connecticut Food Policy Council"},
{"slug":"summer-vegetable-spaghetti","source_url":"https://www.myplate.gov/recipes/summer-vegetable-spaghetti","name":"Summer Vegetable Spaghetti","description":"This tasty pasta dish is packed full of delicious veggies. Enjoy with fruit on the side.","ingredients":[{"name":null,"items":["2 cups small yellow onions, chopped","2 cups fresh tomatoes, peeled and chopped (about 1 pound)","2 cups summer squash, thinly sliced (about 1 pound)","1 1/2 cups fresh green beans (about 1/2 pound)","2/3 cup water","2 tablespoons fresh parsley, minced","1 clove garlic, minced","1/2 teaspoon chili powder","1/4 teaspoon salt","1 dash black pepper","1 can (6 ounces) low-sodium tomato paste","1 pound uncooked spaghetti","1/2 cup Parmesan cheese, grated","3 leaves basil, raw (optional, for garnish)"]}],"directions":[{"name":null,"steps":["Combine first 10 ingredients (onions - black pepper) in large saucepan. Cook for 10 minutes over medium heat, then stir in tomato paste. Cover and cook over medium heat for 15 minutes, stirring occasionally until vegetables are tender.","Cook spaghetti in unsalted water according to package directions.","Spoon sauce over drained hot spaghetti and sprinkle Parmesan cheese over top.","Garnish with basil if desired."]}],"yield":"9 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup spaghetti and 3/4 cup sauce","calories":"293.07 kcal","carbohydrateContent":"55.49 g","cholesterolContent":"3.82 mg","fiberContent":"5.18 g","proteinContent":"11.97 g","sodiumContent":"154.67 mg","sugarContent":"7.27 g","fatContent":"2.96 g","saturatedFatContent":"1.08 g"},"notes":null,"contributor":"Stay Young at Heart: Cooking the Heart-Healthy Way\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"sunshine-rice","source_url":"https://www.myplate.gov/recipes/sunshine-rice","name":"Sunshine Rice","description":"Hot sauce and almonds make this rice dish explode with flavor. Only one pot is needed making this an easy and delicious side dish.","ingredients":[{"name":null,"items":["1 1/2 tablespoons vegetable oil (or cooking oil of choice)","1 1/4 cups celery, finely chopped, with leaves","1 1/2 cups onion, finely chopped","1 cup water","1/2 cup orange juice","2 tablespoons lemon juice","1 dash hot sauce","1 cup long-grain white rice, dry","1/4 cup almonds, slivered"]}],"directions":[{"name":null,"steps":["Heat oil in medium saucepan. Add celery and onions and saute until tender, about 10 minutes.","Add water, orange and lemon juice, and hot sauce. Bring to a boil. Stir in rice and bring back to a boil. Let stand covered until rice is tender and liquid is absorbed.","Stir in almonds. Serve immediately as a side dish for a fish entree."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 serving","1/4 of recipe"],"calories":"328.40 kcal","carbohydrateContent":"52.32 g","cholesterolContent":"0.00 mg","fiberContent":"3.45 g","proteinContent":"6.90 g","sodiumContent":"38.94 mg","sugarContent":"6.12 g","fatContent":"10.29 g","saturatedFatContent":"1.21 g"},"notes":null,"contributor":"Stay Young at Heart: Cooking the Heart-Healthy Way\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"sunshine-salad","source_url":"https://www.myplate.gov/recipes/sunshine-salad","name":"Sunshine Salad","description":"Oranges help to brighten up this tasty veggie salad. It is quick and easy to make. Top it off with your favorite vinaigrette.","ingredients":[{"name":null,"items":["5 cups spinach leaves, packed, washed, and dried well","1/2 medium red onion, sliced thin","1/2 medium red bell pepper, sliced","1 medium cucumber, sliced","2 medium oranges, peeled and chopped into bite-sized pieces","1/3 cup \"lite\" vinaigrette dressing (around 15 calories per tablespoon or less)"]}],"directions":[{"name":null,"steps":["Toss all ingredients together in a large bowl. Add dressing and toss again.","Serve immediately."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"89.52 kcal","carbohydrateContent":"13.18 g","cholesterolContent":"0.00 mg","fiberContent":"2.46 g","proteinContent":"1.85 g","sodiumContent":"185.66 mg","sugarContent":"9.33 g","fatContent":"3.61 g","saturatedFatContent":"0.51 g"},"notes":null,"contributor":"US Department of Health and Human Services"},
{"slug":"sure-please-baked-eggs-cheese","source_url":"https://www.myplate.gov/recipes/sure-please-baked-eggs-cheese","name":"Sure to Please Baked Eggs & Cheese","description":"Add your favorite veggies to dress up this cheese and egg dish, or serve with fresh salsa.","ingredients":[{"name":null,"items":["1 tablespoon oil","6 eggs","1/2 cup non-fat milk","1/2 cup low-fat cheese (grated)","1 teaspoon garlic powder","1 1/2 teaspoons oregano"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Put oil in a medium baking dish or small cake pan and heat in the oven for a few minutes.","In a bowl, beat eggs. Mix in remaining ingredients. Pour into hot pan.","Bake 20 minutes or until eggs are firm. Serve immediately.","* 4 eggs and 4 egg whites may be used instead of 6 eggs to reduce fat and cholesterol (nutrient analysis reflects this modification)."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"162.91"},"notes":null,"contributor":"Healthy Snacks\nUniversity of Wisconsin Cooperative Extension Service"},
{"slug":"surfs-tacos","source_url":"https://www.myplate.gov/recipes/surfs-tacos","name":"Surf''s Up Tacos","description":"This fish taco recipe is a time and money saver, using canned tuna and a mix of canned and fresh veggies.","ingredients":[{"name":null,"items":["1 can (6.5 ounces) tuna, drained","1 can (15.5 ounces) low-sodium kidney beans, rinsed and drained","1 cup low-sodium canned corn, drained","1/3 cup low-fat mayonnaise","2 tablespoons taco seasoning","2 tablespoons lime juice or juice from one lime","2 cups lettuce, shredded","1 1/2 cups reduced-fat cheddar cheese","1/2 cup salsa","12 whole grain tortillas or hard taco shells (10 inches across)"]}],"directions":[{"name":null,"steps":["In a medium bowl, flake tuna with fork. Stir in beans, corn, mayonnaise, taco seasoning*, and lime juice.","Place lettuce, cheese, and salsa in separate bowls.","Place tortillas or taco shells on microwave safe plate. Microwave on high for 1 minute.**","To eat, layer tuna mixture, lettuce, and cheese on tortilla. Top with salsa."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"678.54"},"notes":"* Taco seasoning can be saved for 12 months once opened. Store in an airtight bag or container for later use.\n**Microwaves may vary in power, so you may have to change the cooking time.","contributor":null},
{"slug":"sweet-acorn-squash","source_url":"https://www.myplate.gov/recipes/sweet-acorn-squash","name":"Sweet Acorn Squash","description":"Squash baked in the oven and then seasoned with cinnamon and nutmeg give this dish a taste of fall.","ingredients":[{"name":null,"items":["2 acorn squash","1/2 cup orange juice","1 teaspoon cinnamon","1/4 teaspoon nutmeg"]}],"directions":[{"name":null,"steps":["Put each squash in the microwave. Heat for 1 1/2 minutes on high. This will soften the squash and make it easier to cut.","Cut each squash in half. Remove the seeds and loosen fibers in the middle.","Place the squash on an ungreased baking pan. The cut side of the squash should be face-up, and the uncut part of the squash should touch the pan.","Pour 2 tablespoons of juice into each half of the squash. Spread it evenly on the inside of each squash.","Bake at 400 degrees F for 30 to 45 minutes, until tender.","Season with cinnamon and nutmeg and serve."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 of one prepared squash","1/4 of recipe"],"calories":"84.88 kcal","carbohydrateContent":"19.90 g","cholesterolContent":"0.00 mg","fiberContent":"5.61 g","proteinContent":"1.92 g","sodiumContent":"2.38 mg","sugarContent":"8.57 g","fatContent":"0.81 g","saturatedFatContent":"0.17 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"sweet-and-juicy-raisin-tapenade","source_url":"https://www.myplate.gov/recipes/sweet-and-juicy-raisin-tapenade","name":"Sweet and Juicy Raisin Tapenade","description":"Traditional tapenades can be high in sodium, but not this version, with its base of raisins. Spread on crackers or pita bread as a snack or appetizer, or inc...","ingredients":[{"name":null,"items":["1 cup California raisins","1/4 cup pitted Kalamata olives, drained","2/3 tablespoon walnuts","1 tablespoon balsamic vinegar","2 teaspoons olive oil","1 large whole grain pita bread (approximately 16 wedges or melba rounds)"]}],"directions":[{"name":null,"steps":["Place tapenade ingredients in food processor.","Run until raisins, olives, and walnuts are finely chopped.","Can be made ahead and refrigerated.","Serve with melba rounds or pita wedges."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of the recipe","calories":"215.07 kcal","carbohydrateContent":"44.32 g","cholesterolContent":"0.00 mg","fiberContent":"3.32 g","proteinContent":"3.66 g","sodiumContent":"162.14 mg","sugarContent":"26.74 g","fatContent":"4.54 g","saturatedFatContent":"0.71 g"},"notes":"Serving Suggestions: Serve with a glass of 100% apple juice and hummus with cucumber slices and carrot or celery sticks.\nNotes on Raisins:\nRaisins are fat- and cholesterol-free, naturally low in sodium, and loaded with antioxidants.\nJust 1/4 cup of raisins is equivalent to 1/2 cup of fruit.\nRaisins are the most economical fruit per serving.","contributor":"Produce for Better Health Foundation"},
{"slug":"sweet-and-sour-cabbage","source_url":"https://www.myplate.gov/recipes/sweet-and-sour-cabbage","name":"Sweet and Sour Cabbage","description":"This tangy cabbage dish requires no cooking. Chill for several hours and serve as a side dish for lunch or dinner.","ingredients":[{"name":null,"items":["1/2 medium head of cabbage (about 4 cups when chopped)","1/2 teaspoon salt","1/2 teaspoon celery seed","2 tablespoons sugar","3 tablespoons vinegar"]}],"directions":[{"name":null,"steps":["Cut the cabbage in half and rinse it with water.","Chop the cabbage into very thin bit-sized slices.","In a large bowl, combine ingredients and mix well.","Cover the bowl.","Chill in the fridge for several hours before serving."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared cabbage","1/8 of recipe"],"calories":"28.27 kcal","carbohydrateContent":"6.48 g","cholesterolContent":"0.00 mg","fiberContent":"1.42 g","proteinContent":"0.74 g","sodiumContent":"158.18 mg","sugarContent":"4.94 g","fatContent":"0.10 g","saturatedFatContent":"0.02 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"sweet-and-sour-dressing","source_url":"https://www.myplate.gov/recipes/sweet-and-sour-dressing","name":"Sweet and Sour Dressing","description":"Only three ingredients in this fast and easy dressing. Served chilled over your favorite salad.","ingredients":[{"name":null,"items":["1/2 cup sugar","1 tablespoon cornstarch","1/2 cup vinegar"]}],"directions":[{"name":null,"steps":["In a small saucepan, combine sugar and cornstarch.","Stir in vinegar.","Cook over medium heat until slightly thickened and clear.","Chill before serving. Store refrigerated."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons prepared dressing","1/4 of recipe (57g)"],"calories":"114.17 kcal","carbohydrateContent":"27.00 g","cholesterolContent":"0.00 mg","fiberContent":"0.02 g","proteinContent":"0.01 g","sodiumContent":"1.93 mg","sugarContent":"25.07 g","fatContent":"0.08 g","saturatedFatContent":"0.00 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"sweet-and-sour-vegetables","source_url":"https://www.myplate.gov/recipes/sweet-and-sour-vegetables","name":"Sweet and Sour Vegetables","description":"Lemon juice, honey, soy sauce, and pineapple juice make the base of this delicious sweet and sour sauce. This dish is great over pasta or brown rice. En...","ingredients":[{"name":null,"items":["1 tablespoon honey","1 tablespoon lemon juice","1 teaspoon low-sodium soy sauce","1/4 teaspoon fresh ginger","1 cup canned pineapple chunks","1 tablespoon cornstarch (for thickness)","2 teaspoons vegetable oil (or cooking oil of choice)","1 package (16 ounces) frozen stir-fry vegetables"]}],"directions":[{"name":null,"steps":["Combine all ingredients except vegetables into bowl; mix and set aside.","Heat 2 teaspoons of oil in large skillet and add frozen vegetables. Cook for 3 to 4 minutes or until vegetables are crisp-tender.","Add sweet and sour sauce and cook for another 2 minutes or until mixture comes to a boil. Add water if it seems too thick.","Serve immediately."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"86.11 kcal","carbohydrateContent":"16.52 g","cholesterolContent":"0.00 mg","fiberContent":"2.56 g","proteinContent":"1.86 g","sodiumContent":"138.09 mg","sugarContent":"10.14 g","fatContent":"1.82 g","saturatedFatContent":"0.26 g"},"notes":"Infants and children under the age of 1 should not eat honey or recipes with honey in them.","contributor":"Cooking Healthy with Diabetes\nUniversity of Florida IFAS Extension"},
{"slug":"sweet-cornmeal-pudding-ginger-cinnamon","source_url":"https://www.myplate.gov/recipes/sweet-cornmeal-pudding-ginger-cinnamon","name":"Sweet Cornmeal Pudding with Ginger and Cinnamon","description":"This baked pudding combines milk and cornmeal with spices to produce a custard-like dessert that you can serve on special occasions.","ingredients":[{"name":null,"items":["2 1/2 cups non-fat milk","1/2 cup cornmeal","1/2 cup non-fat milk (cold)","1 tablespoon margarine","1/2 cup molasses","1/2 teaspoon ginger","1/2 teaspoon cinnamon"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 °F. Lightly grease 1-quart baking pan.","In a saucepan, heat 2 1/2 cups of milk to a simmer.","In a bowl, mix together the other 1/2 cup cold milk with cornmeal.","Add cornmeal mixture to warm milk, stir well.","Cook 20 minutes over low-medium heat. Stir often to prevent scorching. Cook until thickened.","Remove pudding from heat. Stir in margarine, molasses, ginger and cinnamon.","Pour into the greased baking pan.","Bake for 55 to 60 minutes. When a knife is inserted and comes out clean, the pudding is done.","Cut into 8 squares before serving. Serve warm."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 square","1/8 of recipe (114g)"],"calories":"126.82 kcal","carbohydrateContent":"25.53 g","cholesterolContent":"2.76 mg","fiberContent":"0.66 g","proteinContent":"3.78 g","sodiumContent":"59.43 mg","sugarContent":"19.62 g","fatContent":"1.42 g","saturatedFatContent":"0.30 g"},"notes":null,"contributor":"Honor the Gift of Food: Learn at Home Lessons\nIndian Health Service Division of Diabetes Treatment and Prevention"},
{"slug":"sweet-potato-and-apple-bake","source_url":"https://www.myplate.gov/recipes/sweet-potato-and-apple-bake","name":"Sweet Potato and Apple Bake","description":"Enjoy the taste of fall with the combination of sweet potatoes and apples in this delicious side dish. Serve with roasted chicken or turkey, and a large gree...","ingredients":[{"name":null,"items":["3 1/2 cups canned sweet potatoes, drained (save 2 tablespoons of the liquid)","2 cups apples, peeled, cored, and cut into bite-sized pieces","6 teaspoons brown sugar (2 tablespoons, packed)","1/3 cup chopped nuts (pecans, walnuts or any other type)","2 tablespoons flour","2 tablespoons unsalted butter, melted"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Put sweet potatoes and apples in baking dish.","Pour the reserved, 2 tablespoons of the sweet potato liquid over the mixture.","Mix brown sugar, nuts, flour, and melted butter together in a small bowl.","Sprinkle over the top of the sweet potato and apple mix.","Bake for 20 to 30 minutes, until the top is golden brown and bubbly."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup","1/6 of recipe"],"calories":"257.89 kcal","carbohydrateContent":"44.15 g","cholesterolContent":"10.18 mg","fiberContent":"4.09 g","proteinContent":"3.28 g","sodiumContent":"79.19 mg","sugarContent":"17.02 g","fatContent":"8.22 g","saturatedFatContent":"2.82 g"},"notes":"Granny Smith apples tend to work best in this recipe.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"sweet-potato-casserole-0","source_url":"https://www.myplate.gov/recipes/sweet-potato-casserole-0","name":"Sweet Potato Casserole","description":"Sweet potato casserole is rich is flavor and low in fat.","ingredients":[{"name":null,"items":["2 tablespoons 1% low fat milk","1 1/2 teaspoons brown sugar","1 teaspoon ground cinnamon","1/4 cup quick cooking oats, dry","2 3/4 cups low-sodium sweet potatoes, drained and chopped (about 15 ounces)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350°F.","In a small bowl, combine milk, brown sugar, cinnamon, and oatmeal. Mix well and set aside.","In a medium-sized baking pan, add the sweet potatoes so that they cover the bottom of the pan.","Add the oatmeal mixture on top of the sweet potatoes.","Bake for 20 minutes. Serve hot or refrigerate and serve cold."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 cup serving","calories":"123.43 kcal","carbohydrateContent":"27.76 g","cholesterolContent":"0.25 mg","fiberContent":"2.64 g","proteinContent":"2.52 g","sodiumContent":"63.20 mg","sugarContent":"6.75 g","fatContent":"0.50 g","saturatedFatContent":"0.11 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"sweet-potato-casserole","source_url":"https://www.myplate.gov/recipes/sweet-potato-casserole","name":"Sweet Potato Casserole","description":"Cinnamon, nutmeg, and ginger combined with vanilla extract are a delicious backdrop for sweet potatoes. Use canned sweet potatoes if you don''t have whole swe...","ingredients":[{"name":null,"items":["4 sweet potatoes (about 1 lb)","3 egg whites","1/2 cup sugar","1 can evaporated milk, nonfat (12 ounce)","1 tablespoon vanilla extract","1 teaspoon cinnamon","1/2 teaspoon nutmeg","1/2 teaspoon ginger"]}],"directions":[{"name":null,"steps":["Rinse sweet potatoes in cold running water and pierce with a fork.","Microwave sweet potatoes on full power until tender, about 15 minutes. Turn them half way during baking.","Preheat oven to 400 degrees. Remove skin from sweet potatoes and mash with hand beaters or food processor. Add the rest of the ingredients and mix until smooth.","Pour mixture in an 8 inch baking dish. Bake until casserole is firm in the center, about 40 minutes.","Remove pan from oven. Allow to stand for 5 minutes then cut into 10 squares.","Serve hot. Refrigerate leftovers."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe (101g)","calories":"116.65 kcal","carbohydrateContent":"23.38 g","cholesterolContent":"1.51 mg","fiberContent":"1.52 g","proteinContent":"4.75 g","sodiumContent":"74.77 mg","sugarContent":"17.16 g","fatContent":"0.22 g","saturatedFatContent":"0.10 g"},"notes":"You may want to experiment with using canned sweet potatoes.","contributor":"Food and Health Communications, Inc."},
{"slug":"sweet-potato-cheesecake","source_url":"https://www.myplate.gov/recipes/sweet-potato-cheesecake","name":"Sweet Potato Cheesecake","description":"Make this delicious and creamy cheesecake full of fall spice flavor for your next holiday celebration.","ingredients":[{"name":null,"items":["1 cup gingersnaps, finely crumbed (or graham crackers)","3 tablespoons unsalted butter, melted","8 ounces light cream cheese, softened","1 cup sweet potatoes, peeled, cooked, and mashed","5 egg whites","1/3 cup sugar","1 1/2 teaspoons pumpkin pie spice","1 teaspoon orange peel, finely shredded","1 teaspoon vanilla","1 cup reduced fat (2%) evaporated milk"]}],"directions":[{"name":"Crust","steps":["Combine crumbs and butter.","Press mixture into bottom and 1 inch up sides of an 8-inch spring form pan. Set aside."]},{"name":"Filling","steps":["In a large mixing bowl, beat cream cheese, sweet potatoes, egg white, sugar, pumpkin pie spice, orange peel, and the vanilla until combined. DO NOT OVER BEAT.","Stir in milk. Carefully pour into prepared pan.","Bake at 350 degrees F for 60 to 70 minutes until center appears set.","Cool on wire rack for 45 minutes. Cover and chill thoroughly.","Remove sides of pan and serve."]}],"yield":"14 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/14 of recipe"],"calories":"140.02 kcal","carbohydrateContent":"16.99 g","cholesterolContent":"16.73 mg","fiberContent":"0.57 g","proteinContent":"4.61 g","sodiumContent":"139.37 mg","sugarContent":"10.20 g","fatContent":"6.02 g","saturatedFatContent":"3.35 g"},"notes":null,"contributor":"Eat Smart New York!\nCornell University Cooperative Extension"},
{"slug":"sweet-potato-custard","source_url":"https://www.myplate.gov/recipes/sweet-potato-custard","name":"Sweet Potato Custard","description":"This custard is sweet and creamy and is a wonderful dessert or a sweet treat as a snack.","ingredients":[{"name":null,"items":["1 cup cooked sweet potato, mashed","1/2 cup banana, mashed","1 cup fat-free evaporated milk","1/8 cup brown sugar (2 tablespoons, packed)","2 egg yolks, beaten (or 1/3 cup egg substitute)","1/2 teaspoon salt","1 nonstick cooking spray (as needed)","1/4 cup raisins","1 tablespoon sugar","1 teaspoon ground cinnamon"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 degrees F.","In a medium bowl, stir together sweet potato and banana.","Add milk, blending well.","Add brown sugar, egg yolks, and salt, mixing thoroughly.","Spray casserole dish with nonstick cooking spray. Transfer sweet potato mixture to casserole dish.","Bake in preheated oven for 35 minutes. Remove from oven.","Combine raisins, sugar, and cinnamon, sprinkle over top of sweet potato mixture.","Return to oven and bake 10 more minutes."]}],"yield":"6","nutrition":{"@type":"NutritionInformation","calories":"130.08"},"notes":null,"contributor":"US Department of Health and Human Services"},
{"slug":"sweet-potato-harvest-salad","source_url":"https://www.myplate.gov/recipes/sweet-potato-harvest-salad","name":"Sweet Potato Harvest Salad","description":"This salad has all of the warmth, sweetness, and crunch in a salad to keep you wanting more! This dish goes well in a lunchbox with a sandwich or pairs perfe...","ingredients":[{"name":null,"items":["4 cups sweet potatoes, diced (about 2-3 sweet potatoes)","1 cup red apple, diced","1/4 cup pomegranate seeds","4 tablespoons unsalted pumpkin seeds (pepitas)","1 tablespoon apple cider vinegar","2 1/2 teaspoons extra virgin olive oil","1/4 teaspoon salt","1/8 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Drizzle diced sweet potatoes with 1 teaspoon of olive oil and roast in the oven on a baking sheet for 10 minutes.","Once sweet potatoes are cooked, remove from the oven and allow them to cool.","In a large mixing bowl, combine the sweet potato, apples, pomegranate seeds, and pepitas.","Whisk the remaining 1/2 tablespoon of olive oil, apple cider vinegar, salt, and pepper in a separate bowl.","Once mixed, add to sweet potato mixture and toss until the salad is lightly coated."]}],"yield":"4 cups","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"196.96 kcal","carbohydrateContent":"28.97 g","cholesterolContent":"0.00 mg","fiberContent":"4.89 g","proteinContent":"4.90 g","sodiumContent":"228.04 mg","sugarContent":"11.83 g","fatContent":"7.51 g","saturatedFatContent":"1.28 g"},"notes":null,"contributor":"Created by Brighter Bites, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"sweet-potato-hash-egg","source_url":"https://www.myplate.gov/recipes/sweet-potato-hash-egg","name":"Sweet Potato Hash with Egg","description":"The unique hash is made with sweet potatoes sautéed with chicken sausage, onion, bell pepper, and garlic. Top with a pan-fried egg for a delicious breakfast...","ingredients":[{"name":null,"items":["2 large sweet potatoes (cut into cubes, about 4 cups)","1 cup water","1 tablespoon vegetable oil","2 chicken sausages","1 small yellow onion, peeled and diced","1 bell pepper, cored and diced","2 cloves garlic, peeled and minced","1 teaspoon vegetable oil","4 large eggs"]}],"directions":[{"name":null,"steps":["Put sweet potatoes and water in a skillet and bring to a boil over high heat.","Reduce heat to low and cook about 20 minutes, stirring occasionally, until the water has been absorbed by the sweet potatoes.","Add oil, sausage, onion, bell pepper and garlic to the skillet with the sweet potatoes. Cook about 20 minutes, stirring occasionally, until the onion is lightly browned and the sweet potatoes are tender.","Divide the hash between 4 plates and return the skillet to the stove.","Reheat the skillet over medium high heat and when it is hot, add the remaining 1 teaspoon oil.","Add the eggs, one at a time, and cook about 3 to 5 minutes until the whites are solid and the yolks begin to thicken but are not hard. Flip the egg and cook for one more minute.","Top sweet potato hash with an egg and serve right away."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"317.09 kcal","carbohydrateContent":"31.01 g","cholesterolContent":"240.00 mg","fiberContent":"4.91 g","proteinContent":"16.68 g","sodiumContent":"375.88 mg","sugarContent":"10.21 g","fatContent":"14.50 g","saturatedFatContent":"3.44 g"},"notes":"See how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"sweet-potato-pancakes-balsamic-maple-mushrooms","source_url":"https://www.myplate.gov/recipes/sweet-potato-pancakes-balsamic-maple-mushrooms","name":"Sweet Potato Pancakes with Balsamic Maple Mushrooms","description":"This healthful version of pancakes features the delicious goodness of mashed sweet potatoes and whole grains, artfully balanced with sweet savory sautéed mu...","ingredients":[{"name":"For Sweet Potato Pancakes","items":["3 medium sweet potatoes or yams (orange flesh)","1 cup non-fat milk","1 egg, beaten","2 tablespoons vegetable oil","1 cup whole wheat flour","2 teaspoons baking powder","1/4 teaspoon salt","cooking spray, as needed"]},{"name":"For Balsamic Maple Mushrooms","items":["1 pound cremini and/or white button mushrooms, quartered","1 tablespoon vegetable oil","1/3 cup maple syrup","1 tablespoon balsamic vinegar"]}],"directions":[{"name":null,"steps":["Microwave sweet potatoes until soft; let cool. Peel and mash potatoes, using an electric mixer.","Add milk, egg, and vegetable oil to potatoes; mix. Sift together dry ingredients and add to potato mixture. Mix on low until just blended.","Heat non-stick skillet or griddle over medium heat; coat skillet with cooking spray.","Use 1/4 cup of batter per pancake, ladling into hot skillet. Wait until pancake bubbles and looks slightly dry on top before flipping over.","While pancakes are cooking, heat 1 tablespoon vegetable oil in another skillet (do not use non-stick) over medium flame.","Add quartered mushrooms and toss coat with oil. Let simmer, stirring occasionally, until juices run.","Add maple syrup and balsamic vinegar to pan. Let simmer until sauce reduces and thickens.","To serve, stack 2 or 3 pancakes, alternating with balsamic maple mushrooms."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"408.21 kcal","carbohydrateContent":"63.77 g","cholesterolContent":"53.21 mg","fiberContent":"6.73 g","proteinContent":"12.13 g","sodiumContent":"482.79 mg","sugarContent":"21.31 g","fatContent":"13.04 g","saturatedFatContent":"2.09 g"},"notes":"Serving Suggestions: Serve with 8 ounces non-fat milk and 1 cup of field greens dressed with olive oil and vinegar.","contributor":"Produce for Better Health Foundation"},
{"slug":"sweet-potato-pancakes","source_url":"https://www.myplate.gov/recipes/sweet-potato-pancakes","name":"Sweet Potato Pancakes","description":"Jazz up traditional pancakes by adding spices and sweet potatoes. Increase your fruits by topping with homemade applesauce.","ingredients":[{"name":null,"items":["1 cup complete pancake and waffle mix (or 1 8-ounce package)","1 teaspoon pumpkin pie spice","1 teaspoon vanilla","3 teaspoons brown sugar (1 tablespoon, packed)","1/2 cup mashed sweet potatoes, baked or canned (or winter squash or pumpkin)","3/4 cup water","chopped nuts (1/4 cup, optional)"]}],"directions":[{"name":null,"steps":["Combine all ingredients and stir just until large lumps disappear. Note: Over-stirring will result in tough pancakes.","Pour slightly less than 1/4 cup batter for each pancake onto skillet or electric griddle heated to 350 to 375 degrees F.","When pancakes bubble around edges and towards center, sprinkle with chopped nuts (if you choose). Then, flip pancakes.","Pancake is done when bottoms are golden brown.","Serve with applesauce or syrup."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["3 pancakes (4-inches each)","1/4 of recipe"],"calories":"145.23 kcal","carbohydrateContent":"30.88 g","cholesterolContent":"0.00 mg","fiberContent":"2.61 g","proteinContent":"3.46 g","sodiumContent":"335.76 mg","sugarContent":"6.15 g","fatContent":"0.58 g","saturatedFatContent":"0.11 g"},"notes":null,"contributor":"USDA Supplemental Nutrition Assistance Program (SNAP)"},
{"slug":"sweet-potato-patties","source_url":"https://www.myplate.gov/recipes/sweet-potato-patties","name":"Sweet Potato Patties","description":"Mashed sweet potatoes are coated in bread crumbs and lightly fried in a pan for an easy side dish. Enjoy with a fresh green salad, and whole grain toast, or ...","ingredients":[{"name":null,"items":["3 medium sweet potatoes","1 cup breadcrumbs, crushed","1 tablespoon vegetable oil"]}],"directions":[{"name":null,"steps":["Wash the sweet potatoes.","Bake the sweet potatoes in a microwave until they are soft.","Remove the peels from the sweet potatoes.","Put the sweet potatoes in a medium bowl. Mash them with a fork.","Crush the breadcrumbs on a cutting board with a rolling pin or jar.","Put the crushed breadcrumbs in a small bowl.","Shape sweet potato into 6 small patties.","Roll each patty in the crushed crumbs.","Heat the oil in a medium frying pan on medium heat.","Brown each patty on both sides in the oil."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 sweet potato patty","1/6 of recipe"],"calories":"137.91 kcal","carbohydrateContent":"23.44 g","cholesterolContent":"0.00 mg","fiberContent":"2.49 g","proteinContent":"3.42 g","sodiumContent":"149.99 mg","sugarContent":"4.40 g","fatContent":"3.36 g","saturatedFatContent":"0.56 g"},"notes":"For variety, add some finely chopped apple.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"sweet-potato-pie","source_url":"https://www.myplate.gov/recipes/sweet-potato-pie","name":"Sweet Potato Pie","description":"A delicious holiday favorite! You can use canned sweet potato if you don''t have time to roast and mash your own!","ingredients":[{"name":null,"items":["4 large egg whites","1/4 cup fresh orange juice","1 teaspoon ground cinnamon","1/4 teaspoon ground nutmeg","1/4 teaspoon ground allspice","3/4 cup packed brown sugar","1/2 teaspoon orange zest","1/2 cup fat-free milk","2 tablespoons unsalted butter (melted)","1 pinch salt","2 cups canned sweet potatoes, mashed (not canned in syrup)","1 unbaked pie crust, 9-inch"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Beat egg whites well.","Add orange juice, spices, brown sugar, orange zest, non-fat milk, butter, and salt.","Add mashed sweet potatoes and mix thoroughly.","Pour into pie shell and bake in preheated oven for 1 hour or until firm."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 piece","1/8 of recipe"],"calories":"264.07 kcal","carbohydrateContent":"47.64 g","cholesterolContent":"1.00 mg","fiberContent":"2.07 g","proteinContent":"4.81 g","sodiumContent":"191.27 mg","sugarContent":"25.55 g","fatContent":"6.48 g","saturatedFatContent":"2.15 g"},"notes":"Use extra egg yolks in this recipe Sweet Potato Custard.","contributor":"Opening the Door to Good Health Cookbook: Healthy Recipes from Around the World\nOhio Commission on Minority Health"},
{"slug":"sweet-potato-pone","source_url":"https://www.myplate.gov/recipes/sweet-potato-pone","name":"Sweet Potato Pone","description":"Ground ginger and molasses are combined with mashed sweet potatoes and cooked in the oven for a delicious dessert.","ingredients":[{"name":null,"items":["3 cups grated sweet potatoes","1 cup molasses (or dark cane syrup)","2 teaspoons ground ginger","2 teaspoons baking powder","1 teaspoon salt","1/3 cup vegetable oil"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 degrees F.","Combine all ingredients in a 3-quart saucepan.","Simmer slowly, stirring constantly, for 10 minutes.","Pour into well-greased 9-inch baking pan.","Bake for 30 minutes, stirring every five minutes for the first 20 minutes.","Smooth down the top and allow to brown.","Cut into squares and serve hot or cold."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe","calories":"189.14 kcal","carbohydrateContent":"30.85 g","cholesterolContent":"0.00 mg","fiberContent":"1.08 g","proteinContent":"0.66 g","sodiumContent":"356.72 mg","sugarContent":"25.93 g","fatContent":"7.49 g","saturatedFatContent":"1.04 g"},"notes":"Sweet Potato Pone is a Liberian dish often served as a dessert following a family meal.","contributor":"North Dakota Food and Culture: A Taste of World Cuisine\nNorth Dakota State University Extension Service"},
{"slug":"sweet-savory-peanut-butter-dip","source_url":"https://www.myplate.gov/recipes/sweet-savory-peanut-butter-dip","name":"Sweet and Savory Peanut Butter Dip","description":"This creamy dip is a great after-school snack! In addition to celery, you can serve it with apples, carrots, jicama, or bell peppers.","ingredients":[{"name":null,"items":["3 tablespoons creamy peanut butter","2 tablespoons apple butter","2 tablespoons 1% low-fat milk","1 tablespoon reduced sodium soy sauce (reduced sodium)","1 1/2 teaspoons lime juice"]}],"directions":[{"name":null,"steps":["Combine peanut butter, apple butter, milk, soy sauce, and lime juice in a small bowl.","Whisk together until very smooth.","Store tightly, sealed in refrigerator.","Serve with celery or other crunchy fruits and vegetables."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"80.02 kcal","carbohydrateContent":"6.17 g","cholesterolContent":"0.31 mg","fiberContent":"0.61 g","proteinContent":"2.69 g","sodiumContent":"159.99 mg","sugarContent":"4.18 g","fatContent":"5.00 g","saturatedFatContent":"1.01 g"},"notes":null,"contributor":"University of Arkansas\nDivision of Agriculture"},
{"slug":"sweet-sour-salad-dressing","source_url":"https://www.myplate.gov/recipes/sweet-sour-salad-dressing","name":"Sweet and Sour Salad Dressing","description":"Vegetable oil is used to make this sweet and sour salad dressing.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of choice)","3 tablespoons red wine vinegar","2 teaspoons low-sodium soy sauce","6 teaspoons brown sugar (2 tablespoons)","2 tablespoons lemon juice","1/2 teaspoon garlic powder"]}],"directions":[{"name":null,"steps":["Mix all ingredients and stir or shake well.","Chill in the fridge for at least 1 hour before serving. Store in the fridge in a bottle or container."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/5 of recipe","calories":"69.27 kcal","carbohydrateContent":"4.31 g","cholesterolContent":"0.00 mg","fiberContent":"0.09 g","proteinContent":"0.28 g","sodiumContent":"79.93 mg","sugarContent":"3.64 g","fatContent":"5.61 g","saturatedFatContent":"0.77 g"},"notes":"Try this dressing on cut vegetables or salad. After serving, keep any leftover dressing in the fridge.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"sweetened-condensed-milk","source_url":"https://www.myplate.gov/recipes/sweetened-condensed-milk","name":"Sweetened Condensed Milk","description":"Make your own sweetened condensed milk for your holiday dessert needs.","ingredients":[{"name":null,"items":["1 cup hot water (8 fluid ounces)","2 cups sugar","2 tablespoons margarine","4 cups dry, fat-free milk powder"]}],"directions":[{"name":null,"steps":["In order listed, put ingredients into a blender and blend until smooth.","Store in the refrigerator for up to one week."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons","1/12 of recipe"],"calories":"228.16 kcal","carbohydrateContent":"45.01 g","cholesterolContent":"4.56 mg","fiberContent":"0.00 g","proteinContent":"8.21 g","sodiumContent":"138.13 mg","sugarContent":"45.05 g","fatContent":"1.68 g","saturatedFatContent":"0.40 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"swiss-chard-and-cranberries","source_url":"https://www.myplate.gov/recipes/swiss-chard-and-cranberries","name":"Swiss Chard and Cranberries","description":null,"ingredients":[{"name":null,"items":["2 tablespoons olive oil (or cooking oil of choice)","1 medium onion (chopped)","6 cups swiss chard (1 pound stems chopped and leaves sliced)","1/4 cup dried cranberries"]}],"directions":[{"name":null,"steps":["In a skillet, heat oil over medium heat. Add onions and cook until softened.","Add the Swiss chard stems and continue to sauté until beginning to soften.","Increase the heat to high and add the Swiss chard leaves and dried cranberries.","Once the chard is wilted, turn off the heat and cover the skillet, letting it rest for a few minutes before serving.","For softer greens, let them rest a little longer."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"118.12 kcal","carbohydrateContent":"13.43 g","cholesterolContent":"0.00 mg","fiberContent":"2.02 g","proteinContent":"1.31 g","sodiumContent":"116.03 mg","sugarContent":"10.00 g","fatContent":"7.25 g","saturatedFatContent":"1.13 g"},"notes":"Rinse, soak, and rinse the Swiss chard again to make it easier to remove all dirt and grit.\nSubstitute raisins for cranberries for a different flavor.","contributor":"Virginia Cooperative Extension - www.eatsmartmovemoreva.org"},
{"slug":"taco-flavored-potatoes","source_url":"https://www.myplate.gov/recipes/taco-flavored-potatoes","name":"Taco Flavored Potatoes","description":"Potatoes are coated with taco seasoning and corn meal then baked in the oven until golden brown.","ingredients":[{"name":null,"items":["4 medium potatoes","2 tablespoons olive oil (or cooking oil of your choice)","2 tablespoons taco seasoning (1/2 package)","1/4 cup corn meal"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Wash and scrub potatoes well. Cut the potatoes in half, lengthwise and then into wedges.","Place potatoes in large mixing bowl, toss with the olive oil until potatoes are well coated.","Sprinkle the seasonings and corn meal over potatoes, toss again until coated.","Arrange the potatoes on a baking sheet.","Bake for approximately 30 minutes until potatoes are golden brown."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":["6 potato wedges","1/5 of recipe (133g)"],"calories":"212.44 kcal","carbohydrateContent":"35.79 g","cholesterolContent":"0.00 mg","fiberContent":"3.95 g","proteinContent":"4.10 g","sodiumContent":"262.84 mg","sugarContent":"2.05 g","fatContent":"6.00 g","saturatedFatContent":"0.94 g"},"notes":null,"contributor":"California Health Department, Los Angeles County\nEs Facil Campaign"},
{"slug":"taco-salad-ii","source_url":"https://www.myplate.gov/recipes/taco-salad-ii","name":"Taco Salad II","description":"Ground beef and beans are flavored with cumin and chili powder and served over lettuce and other veggies for an easy weeknight dinner. Top with cheese and dr...","ingredients":[{"name":null,"items":["1/4 pound lean ground beef","cumin, ground (1 1/2 teaspoons, optional)","1 tablespoon chili powder","1 cup kidney or pinto beans (dry-cooked or canned, drained)","1/2 head of lettuce (torn)","1 small onion (diced)","2 medium fresh tomatoes (cut up)","1 can corn (15.2 oz, drained)","1/2 cup cheddar cheese (shredded)","2 cups light tortilla chips (broken)","1/2 cup non-fat yogurt","1/2 cup salsa, chunky"]}],"directions":[{"name":null,"steps":["Brown ground beef and drain any fat.","Add beans, cumin, and chili powder and heat through.","Toss lettuce, tomatoes, onion, and cheese in large bowl.","Spoon on meat and bean mixture and top with broken tortilla chips.","Prepare dressing by mixing yogurt and salsa. Serve on the side of the salad","Refrigerate leftovers within two hours."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 cups salad","1/6 of recipe (230g)"],"calories":"361.07 kcal","carbohydrateContent":"52.55 g","cholesterolContent":"31.17 mg","fiberContent":"9.78 g","proteinContent":"20.12 g","sodiumContent":"644.21 mg","sugarContent":"14.81 g","fatContent":"9.62 g","saturatedFatContent":"3.98 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"taco-salad","source_url":"https://www.myplate.gov/recipes/taco-salad","name":"Taco Salad","description":"Ground beef and beans are flavored with cumin and chili powder and served over lettuce and other veggies for an easy weeknight dinner. Top with cheese and dr...","ingredients":[{"name":null,"items":["1/4 pound lean ground beef","cumin, ground (1 1/2 teaspoons, optional)","1 tablespoon chili powder","1 cup kidney or pinto beans (dry-cooked or canned, drained)","1/2 head of lettuce (torn)","1 small onion (diced)","2 medium fresh tomatoes (cut up)","1 can corn (15.2 oz, drained)","1/2 cup cheddar cheese (shredded)","2 cups light tortilla chips (broken)","1/2 cup non-fat yogurt","1/2 cup salsa, chunky"]}],"directions":[{"name":null,"steps":["Brown ground beef and drain any fat.","Add beans, cumin, and chili powder and heat through.","Toss lettuce, tomatoes, onion, and cheese in large bowl.","Spoon on meat and bean mixture and top with broken tortilla chips.","Prepare dressing by mixing yogurt and salsa. Serve on the side of the salad","Refrigerate leftovers within two hours."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 cups salad","1/6 of recipe (230g)"],"calories":"361.07 kcal","carbohydrateContent":"52.55 g","cholesterolContent":"31.17 mg","fiberContent":"9.78 g","proteinContent":"20.12 g","sodiumContent":"644.21 mg","sugarContent":"14.81 g","fatContent":"9.62 g","saturatedFatContent":"3.98 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"taco-soup","source_url":"https://www.myplate.gov/recipes/taco-soup","name":"Taco Soup","description":"Top this ground beef and bean taco soup with shredded lettuce and fat-free sour cream or nonfat yogurt for the full taco experience.","ingredients":[{"name":null,"items":["1 pound lean ground beef","2 cans diced tomatoes (14.5 oz)","3 cups corn (2-15.5 oz low-sodium cans, rinsed and drained)","2 cans red kidney beans, low-sodium (15.5 oz each, rinsed and drained)","1 1/2 teaspoons chili powder","3/4 teaspoon cumin powder","3/4 teaspoon garlic powder","1/3 cup water"]}],"directions":[{"name":null,"steps":["Brown meat in a pot over medium heat.","Put meat in a strainer to drain fat. Rinse with hot water.","Mix all the ingredients in the same pot and cook on low for an hour."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup (298g)","calories":"183.50 kcal","carbohydrateContent":"23.72 g","cholesterolContent":"26.29 mg","fiberContent":"7.29 g","proteinContent":"14.29 g","sodiumContent":"239.68 mg","sugarContent":"5.97 g","fatContent":"4.38 g","saturatedFatContent":"1.50 g"},"notes":null,"contributor":"2009 Recipe Calendar\nUniversity of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"tangy-crisp-vegetable-and-pasta-salad","source_url":"https://www.myplate.gov/recipes/tangy-crisp-vegetable-and-pasta-salad","name":"Tangy Crisp Vegetable and Pasta Salad","description":"Use your favorite pasta and veggies to make this salad a family favorite. Make a day ahead and allow to chill in the refrigerator overnight so the flavors bl...","ingredients":[{"name":null,"items":["1/2 cup pasta (such as bowties, shells, macaroni, etc.)","1/4 cup vinegar","1 tablespoon sugar","1/2 teaspoon garlic powder","1/8 teaspoon ground black pepper","1/2 cucumber (peeled, seeded, and coarsely chopped)","1/2 medium carrot (thinly sliced)","1/2 red pepper (sliced, could use green or yellow)","1/2 cup broccoli florets (coarsely chopped)","2 tablespoons onion, green or red (sliced)","1 tablespoon dried parsley (can use fresh if available)"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions, but do not add salt to cooking water.","Drain, rinse with cool water, and drain again.","In a small saucepan, combine vinegar, sugar, garlic powder, and black pepper.","Stir over medium heat until sugar is dissolved, but do not boil. Let cool.","Rinse, drain, and chop remaining ingredients. Combine in a shallow container.","Add cooked pasta and vinegar mixture. Mix gently.","Cover and refrigerate overnight to allow flavors to blend.","Top with parsley and serve cold.","Cover and refrigerate leftovers within 2 hours."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (77g)","calories":"56.84 kcal","carbohydrateContent":"11.45 g","cholesterolContent":"0.00 mg","fiberContent":"1.13 g","proteinContent":"1.82 g","sodiumContent":"8.96 mg","sugarContent":"3.32 g","fatContent":"0.30 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"Fix it Fresh! Recipe Series\nKansas State University Research and Extension"},
{"slug":"tangy-jicama-slaw","source_url":"https://www.myplate.gov/recipes/tangy-jicama-slaw","name":"Tangy Jicama Slaw","description":"Jicama provides a wonderful crunchy texture for this tasty and tangy slaw.","ingredients":[{"name":null,"items":["2 cups jicama (peeled and chopped)","1 cup canned Mandarin oranges (in light syrup)","1 1/2 tablespoons lime juice (juice of one lime)","salt (to taste, optional)","cilantro (optional)"]}],"directions":[{"name":null,"steps":["Cut the jicama in half so you have a flat side for stability.","Peel the jicama using a small sharp knife.","Cut the jicama in small strips or grate it using a large hand grater.","Stir all the ingredients together in a bowl and enjoy."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"32.54 kcal","carbohydrateContent":"8.06 g","cholesterolContent":"0.00 mg","fiberContent":"2.42 g","proteinContent":"0.58 g","sodiumContent":"3.85 mg","sugarContent":"4.47 g","fatContent":"0.05 g","saturatedFatContent":"0.01 g"},"notes":null,"contributor":"Iowa Department of Public Health\nIowa Nutrition Network"},
{"slug":"tangy","source_url":"https://www.myplate.gov/recipes/tangy","name":"Tangy Dressing","description":"This tasty, tangy dressing compliments salads that feature citrus fruit. Nutmeg adds an extra kick.","ingredients":[{"name":null,"items":["1/2 cup milk (evaporated skim)","6 us fluid ounces juice concentrate (frozen orange/pineapple, thawed)","1 teaspoon ground nutmeg (pinch)"]}],"directions":[{"name":null,"steps":["Mix milk, concentrate, and nutmeg.","Shake well before using."]}],"yield":"20 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 tablespoon","calories":"21.48 kcal","carbohydrateContent":"4.57 g","cholesterolContent":"0.25 mg","fiberContent":"0.13 g","proteinContent":"0.74 g","sodiumContent":"8.02 mg","sugarContent":"3.93 g","fatContent":"0.08 g","saturatedFatContent":"0.04 g"},"notes":"Use this dressing on your favorite salad, as a dip, or as an ingredient in this Summer Salad!","contributor":"Creative Vegetable Cookery\nNorth Dakota State University Extension Service"},
{"slug":"tartar-sauce","source_url":"https://www.myplate.gov/recipes/tartar-sauce","name":"Tartar Sauce","description":"A cost-effective alternative to store-bought tartar sauce. Use this sauce with your favorite seafood at home and it will not disappoint.","ingredients":[{"name":null,"items":["1/2 cup low-fat plain yogurt (or low-fat sour cream)","1/16 cup (1 tablespoon) pickle relish","1 tablespoon onion, minced (or 2 teaspoons dried minced onion)","1 teaspoon dried parsley (or 1 tablespoon chopped fresh parsley)","1 teaspoon mustard","hot pepper sauce (2 drops, optional)"]}],"directions":[{"name":null,"steps":["In a small bowl, combine all the ingredients.","Serve immediately or cover and refrigerate until used."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"26.15 kcal","carbohydrateContent":"3.76 g","cholesterolContent":"1.84 mg","fiberContent":"0.17 g","proteinContent":"1.73 g","sodiumContent":"64.97 mg","sugarContent":"3.38 g","fatContent":"0.54 g","saturatedFatContent":"0.31 g"},"notes":"Try making with plain Greek yogurt.","contributor":"Food Hero, Adapted from Low-Fat Tartar Sauce\nOregon State University Cooperative Extension Service"},
{"slug":"tastee-burgers","source_url":"https://www.myplate.gov/recipes/tastee-burgers","name":"Tastee Burgers","description":"These yummy vegetarian burgers are made from lentils and are loaded with protein.","ingredients":[{"name":null,"items":["1 1/4 cups dry lentils","3 cups water","1 cup onion (chopped)","1 cup carrot (grated)","3 cups bread crumbs","1 egg","1 teaspoon garlic powder","1/2 teaspoon oregano","1/2 teaspoon salt","3 tablespoons margarine or butter","4 ounces cheddar cheese (sliced)"]}],"directions":[{"name":null,"steps":["Place lentils in a colander, rinse in cold water, and drain.","In a medium saucepan, bring water to a boil. Add lentils, reduce heat to low, cover, and cook for 15 minutes.","Add onion and carrots. Cook 15 minutes more or until lentils are tender.","Remove from heat and cool slightly.","Stir in bread crumbs, egg, garlic powder, oregano, and salt.","Melt margarine or butter in large skillet. Drop lentil mixture by rounded 1/2 cupsful into hot margarine. Flatten mounds into patties and cook until firm and golden brown on both sides.","Top each patty with a thin slice of cheese.","Serve immediately.","Refrigerate leftovers within two hours."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 prepared burger","1/8 of recipe (238g)"],"calories":"370.73 kcal","carbohydrateContent":"50.66 g","cholesterolContent":"39.92 mg","fiberContent":"9.54 g","proteinContent":"17.75 g","sodiumContent":"596.63 mg","sugarContent":"5.67 g","fatContent":"11.12 g","saturatedFatContent":"4.10 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"tasty-chicken-and-veggie-packets","source_url":"https://www.myplate.gov/recipes/tasty-chicken-and-veggie-packets","name":"Tasty Chicken and Veggie Packets","description":"Fast and flavorful. Choose your favorite vegetables and try this quick and delicious dish on a busy weeknight. Serve with brown rice or quinoa.","ingredients":[{"name":null,"items":["4 chicken breast (boneless and skinless)","salt (to taste, optional)","pepper (to taste, optional)","1/4 red onion (julienned)","1 carrot (julienned)","1 red pepper (julienned)","1 celery stalk (julienned)","1/2 zucchini (julienned)","1 clove garlic (minced)","2 tablespoons basil (fresh, chopped)","thyme (fresh sprigs, optional)","parsley (chopped, optional)","ginger (minced, optional)","2 teaspoons olive oil (or oil of your choice - divided)","4 teaspoons lemon juice (freshly squeezed (1 tablespoon + 1 teaspoon, divided))"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Cut four large rectangles of parchment paper or aluminum foil and fold in half to create a crease. Unfold.","Place each chicken breast in the middle of the foil or parchment paper and season with salt and pepper (if desired).","Top chicken with your choice of vegetables and seasonings.","Drizzle each packet with 1/2 teaspoon oil and 1 teaspoon lemon juice.","Fold the parchment paper or foil in half and then crimp around the edges tightly in 1/4-inch folds to create a half moon shape.","Using a spatula, transfer the packets to a baking sheet. Bake until the chicken is cooked to an internal temperature of 165 °F, about 20 minutes, depending the thickness of the chicken breast."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 packet","1/4 of recipe (195g)"],"calories":"241.72 kcal","carbohydrateContent":"5.91 g","cholesterolContent":"118.56 mg","fiberContent":"1.37 g","proteinContent":"37.48 g","sodiumContent":"78.49 mg","sugarContent":"3.26 g","fatContent":"6.81 g","saturatedFatContent":"1.33 g"},"notes":"For a video demonstration of the preparation of this recipe, see Nutrition.gov.\nOptional ingredients are not included in the nutrient or cost analysis.","contributor":"USDA Food and Nutrition Information Center"},
{"slug":"tasty-fish-and-veggie-packets","source_url":"https://www.myplate.gov/recipes/tasty-fish-and-veggie-packets","name":"Tasty Fish and Veggie Packets","description":"Full of flavor, this easy fish recipe will quickly become a favorite. Make this different each time by adding in whatever vegetables you have at home. Serve ...","ingredients":[{"name":null,"items":["4 cod fillets (4 ounces each, can also use tilapia, sole, hake, flounder, or other white fish)","salt (to taste, optional)","pepper (to taste, optional)","1/4 onion (chopped)","1 carrot (chopped)","1 red pepper (sliced)","1 celery stalk (chopped)","1 clove garlic (minced)","2 tablespoons parsley (chopped)","thyme (fresh sprigs, optional)","basil (chopped, optional)","ginger (minced, optional)","2 teaspoons olive oil (or oil of your choice, divided)","4 teaspoons lemon juice (divided)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Cut four large rectangles of parchment paper or aluminum foil and fold in half to crease. Unfold.","Put each fish fillet on the foil or parchment paper and season with salt and pepper.","Top fish with your choice of vegetables and seasonings.","Drizzle each packet with 1/2 teaspoon oil and 1 teaspoon lemon juice.","Fold the parchment paper or foil in half and then crimp around the edges tightly in 1/4-inch folds to create a half moon shape.","Using a spatula, transfer the packets to a baking sheet. Bake until the fish is cooked to an internal temperature of 145 °F, about 10 to 12 minutes, depending the thickness of the fish."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (195g)","calories":"110.24 kcal","carbohydrateContent":"5.16 g","cholesterolContent":"48.82 mg","fiberContent":"1.16 g","proteinContent":"17.04 g","sodiumContent":"127.37 mg","sugarContent":"2.63 g","fatContent":"2.68 g","saturatedFatContent":"0.43 g"},"notes":"See a video demonstration of the preparation of this recipe on Youtube.\nOptional ingredients are not included in the nutrient or cost analysis.","contributor":"USDA Food and Nutrition Information Center"},
{"slug":"tasty-low-fat-cream-soup","source_url":"https://www.myplate.gov/recipes/tasty-low-fat-cream-soup","name":"Tasty Low-Fat Cream Soup","description":"Try this soup on a cold evening as a start to your meal. Or enjoy this soup with a side of salad, fruit, and whole grain bread.","ingredients":[{"name":null,"items":["2 tablespoons onion (chopped)","1/4 cup celery (chopped)","1 1/2 cups low-sodium chicken broth (divided)","2/3 cup non-fat dry milk powder","1 1/3 tablespoons flour","black pepper (to taste)"]}],"directions":[{"name":null,"steps":["Peel and chop the onion.","Chop the celery into small pieces.","Put the celery and onion in a saucepan.","Add 1/2 cup chicken broth (save the other cup of chicken broth for later).","Cook these ingredients on low heat. Let the broth simmer for 2 to 3 minutes.","In a small bowl, mix the dry milk, flour, and pepper. Add them into the 1 cup of chicken broth that hasn''t been cooked yet. Beat till smooth.","Add this mix to the celery, onion, and broth.","Cook over medium heat till the soup thickens."]}],"yield":"2 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/4 cup soup","1/2 of recipe (231g)"],"calories":"136.28 kcal","carbohydrateContent":"19.35 g","cholesterolContent":"4.56 mg","fiberContent":"0.55 g","proteinContent":"12.60 g","sodiumContent":"188.39 mg","sugarContent":"12.72 g","fatContent":"1.34 g","saturatedFatContent":"0.46 g"},"notes":null,"contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"tasty-veggie-dip","source_url":"https://www.myplate.gov/recipes/tasty-veggie-dip","name":"Tasty Veggie Dip","description":"Enjoy this tasty dip with carrots, radishes, celery, bell peppers, jicama, or whatever veggies you have on hand.","ingredients":[{"name":null,"items":["1 container of non-fat yogurt (8 oz)","2 tablespoons Chili and Spice Seasoning"]}],"directions":[{"name":null,"steps":["Mix together ingredients.","Keep this simple dip in the fridge."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"40.67 kcal","carbohydrateContent":"6.28 g","cholesterolContent":"1.13 mg","fiberContent":"1.07 g","proteinContent":"3.61 g","sodiumContent":"63.65 mg","sugarContent":"4.48 g","fatContent":"0.34 g","saturatedFatContent":"0.12 g"},"notes":"A tasty addition to fresh veggies or a good sauce for tacos.","contributor":"Iowa Department of Public Health\nIowa Nutrition Network"},
{"slug":"ten-minute-corn-chowder","source_url":"https://www.myplate.gov/recipes/ten-minute-corn-chowder","name":"Ten Minute Corn Chowder","description":"Try this quick, easy, and creamy corn soup when you''re short on time.","ingredients":[{"name":null,"items":["1 teaspoon vegetable oil (or oil of your choice)","1/2 medium onion (chopped)","1 teaspoon garlic (minced)","4 tablespoons flour","3 cups non-fat milk","2 teaspoons mustard","1/4 teaspoon thyme (dried)","black pepper (to taste)","2 cups corn kernels (frozen)","4 tablespoons cheddar cheese (shredded, reduced fat - divided)"]}],"directions":[{"name":null,"steps":["Heat a large non-stick skillet over medium-high heat. Add the oil and sauté the onion and garlic until golden, about 2 minutes.","Meanwhile, place the flour, milk, mustard, and seasonings in a small bowl and mix well.","Add the milk mixture to the skillet followed by the corn; mix well until the mixture comes to a boil and thickens, for about 3 minutes. Stir frequently to keep the mixture from burning.","Divide into four bowls and top each with 1 tablespoon of shredded cheese."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/4 cup chowder","1/4 of recipe (305g)"],"calories":"205.81 kcal","carbohydrateContent":"32.82 g","cholesterolContent":"10.86 mg","fiberContent":"2.36 g","proteinContent":"12.12 g","sodiumContent":"160.68 mg","sugarContent":"15.28 g","fatContent":"4.06 g","saturatedFatContent":"1.44 g"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"teriyaki-lettuce-wraps","source_url":"https://www.myplate.gov/recipes/teriyaki-lettuce-wraps","name":"Teriyaki Lettuce Wraps","description":"Lettuce wraps make great appetizers, or enjoy two for an entree. Pairs well with fresh or canned pineapple.","ingredients":[{"name":null,"items":["1/4 cup water","1 tablespoon cornstarch","1/2 cup teriyaki sauce (reduced sodium)","1 pound lean ground turkey","1 cup water chestnuts (chopped)","1 tablespoon vegetable oil (or cooking oil of your choice)","6 lettuce leaves"]}],"directions":[{"name":null,"steps":["Mix the water, cornstarch, and teriyaki sauce.","Add meat and water chestnuts.","Heat oil in a skillet or heavy saucepan and add meat and sauce mixture; stir until cooked through.","Serve in a lettuce leaf."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"203.26 kcal","carbohydrateContent":"9.83 g","cholesterolContent":"56.10 mg","fiberContent":"1.16 g","proteinContent":"15.01 g","sodiumContent":"429.92 mg","sugarContent":"4.13 g","fatContent":"11.61 g","saturatedFatContent":"2.58 g"},"notes":"Ground or thinly sliced beef or pork can be substituted for turkey.","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"terrific-bean-taco","source_url":"https://www.myplate.gov/recipes/terrific-bean-taco","name":"Terrific Bean Taco","description":"Quick and easy tacos, perfect for an easy weeknight meal. You can use homemade refried beans or canned refried beans for this recipe.","ingredients":[{"name":null,"items":["1 small onion (chopped)","2 teaspoons vegetable oil (or cooking oil of choice)","2 cups refried beans","8 taco shells (or flour tortillas)","1/4 head of lettuce (chopped)","2 medium tomatoes (chopped)","1 cup cheddar cheese (shredded)","taco sauce (optional)"]}],"directions":[{"name":null,"steps":["Heat oil in skillet over medium heat. Add onion and cook until soft.","Add refried beans to skillet. Heat thoroughly.","Spread refried bean mixture in taco shells or on tortillas.","Sprinkle with shredded cheese, lettuce, chopped tomatoes, and taco sauce, as desired."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe (155g)","calories":"262.60 kcal","carbohydrateContent":"29.26 g","cholesterolContent":"14.13 mg","fiberContent":"5.43 g","proteinContent":"8.79 g","sodiumContent":"390.52 mg","sugarContent":"2.52 g","fatContent":"12.47 g","saturatedFatContent":"4.93 g"},"notes":null,"contributor":"University of Wisconsin Cooperative Extension Service\nFamily Living Program"},
{"slug":"tex-mex-skillet","source_url":"https://www.myplate.gov/recipes/tex-mex-skillet","name":"Tex-Mex Skillet","description":"This dish is packed with lean protein in the form of black beans and lean ground beef. Chili powder, cumin, and fresh salsa add bold flavor to this Mexican-i...","ingredients":[{"name":null,"items":["1/2 medium head lettuce","1 medium green bell pepper","1 large tomato","1 small jalapeño pepper","1 medium red onion","2 cloves garlic","2 ounces reduced fat cheddar cheese","1 can of low-sodium black beans","1 pound lean ground beef (or ground turkey or chicken)","2 2/3 cups frozen corn","1/2 cup water","3/4 teaspoon chili powder","1/4 teaspoon salt","1/4 teaspoon ground cumin","8 whole wheat flour tortillas (6 inch)","ground black pepper"]}],"directions":[{"name":null,"steps":["Rinse lettuce, bell pepper, tomato, and jalapeño. Rinse and peel onion. Peel garlic.","Chop or shred lettuce into bite-sized pieces. Mince garlic. Cut the jalapeño and bell peppers in half. Remove seeds with the tip of a knife. Dice peppers.","Over a small bowl, grate tomato and onion using the coarse side of a box grater. Collect all pulp and juices.","Grate cheddar cheese.","In a colander, drain and rinse beans.","In a large skillet over medium-high heat, cook meat, bell pepper, and garlic until meat is lightly browned. Drain to remove fat.","Stir in frozen corn, beans, water, and spices. Bring mixture to a boil. Lower heat and cover. Simmer for 10 minutes, or until most liquid is gone.","While meat mixture is simmering, make a salsa. Add jalapeño and a pinch of salt to the grated tomato and onion. Stir and set aside.","Divide the meat mixture evenly among the 8 tortillas. Top each with grated cheese, salsa, and lettuce. Roll up and serve."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"319.26 kcal","carbohydrateContent":"39.40 g","cholesterolContent":"38.25 mg","fiberContent":"9.46 g","proteinContent":"20.56 g","sodiumContent":"441.02 mg","sugarContent":"5.16 g","fatContent":"9.57 g","saturatedFatContent":"4.27 g"},"notes":"Use any type of cooked beans in place of the black beans.\nFor a vegetarian option, use an extra can of drained and rinsed beans in place of the meat.\nTo increase heat, leave a few seeds from the jalapeño in the salsa. Or, season with an extra pinch of cayenne pepper.\nTop with rinsed and chopped tomatoes, green onions, low-fat sour cream, or low-fat plain yogurt, if you like.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"thai-pineapple-and-chicken","source_url":"https://www.myplate.gov/recipes/thai-pineapple-and-chicken","name":"Thai Pineapple and Chicken","description":"A deliciously sweet and savory dish featuring chicken, fresh pineapple, and red bell peppers.","ingredients":[{"name":null,"items":["4 cups cooked brown rice (regular or instant)","2 tablespoons canola or peanut oil, divided","1 pound boneless, skinless chicken breast, cut into 1\" cubes","2 cloves garlic, minced","1 red bell pepper, cut into chunks","1 medium onion, cut into chunks","2 cups cut broccoli florets and stems","2 cups fresh pineapple chunks","1 fresh lime, divided","1 tablespoon Thai fish sauce","2 tablespoons Thai chili sauce","1/4 cup chopped cilantro"]}],"directions":[{"name":null,"steps":["Cook rice according to package directions.","Heat 1 tablespoon oil in a large skillet. Add cubed chicken, stir fry 4 to 5 minutes until chicken is done. Remove from skillet.","Heat remaining oil. Add garlic and cook 1 minute.","Add bell pepper, onion, and broccoli; cook 5 minutes.","Add pineapple; cook an additional 3 to 4 minutes.","Return chicken to skillet and stir in juice from 1/2 lime, fish sauce, chili sauce, and cilantro. Cook 1 more minute.","Serve over brown rice with lime wedges."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"532.97 kcal","carbohydrateContent":"75.21 g","cholesterolContent":"75.06 mg","fiberContent":"7.15 g","proteinContent":"31.27 g","sodiumContent":"208.21 mg","sugarContent":"14.73 g","fatContent":"12.00 g","saturatedFatContent":"1.62 g"},"notes":"Serve with 8 ounces non-fat milk.","contributor":"Produce for Better Health Foundation"},
{"slug":"thousand-island-dressing","source_url":"https://www.myplate.gov/recipes/thousand-island-dressing","name":"Thousand Island Dressing","description":"Try this sweet and tangy dressing on your favorite salad or as a dip for veggies.","ingredients":[{"name":null,"items":["1/2 cup plain non-fat yogurt","1/2 cup light mayonnaise","1/4 cup chili sauce","3 sweet pickle relish packets (2/3 tablespoon packets each)","1 tablespoon onion (finely chopped)","1 tablespoon celery, finely chopped","1 teaspoon lemon (or lime) juice","1/8 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Mix ingredients together.","Chill and serve over vegetables or on a salad."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons dressing","1/8 of recipe (46g)"],"calories":"58.78 kcal","carbohydrateContent":"5.68 g","cholesterolContent":"2.81 mg","fiberContent":"0.29 g","proteinContent":"1.18 g","sodiumContent":"283.21 mg","sugarContent":"3.94 g","fatContent":"3.54 g","saturatedFatContent":"0.56 g"},"notes":null,"contributor":"Food Wise Learn at Home Print Materials\nRutgers University Cooperative Extension"},
{"slug":"three-bean-salad","source_url":"https://www.myplate.gov/recipes/three-bean-salad","name":"Three Bean Salad","description":"This tasty salad pairs excellently with a tuna salad sandwich on whole grain bread and a piece of fruit. Make ahead of time and chill overnight in the refrig...","ingredients":[{"name":null,"items":["1 cup kidney beans (cooked)","1 cup green beans, cut (canned or fresh cooked)","2 cups yellow wax beans (canned or fresh cooked)","1 green pepper (diced)","2/3 cup onion (chopped)","1/2 cup celery (chopped)","2 garlic cloves, whole","1/2 cup wine vinegar","1/4 cup vegetable oil (or cooking oil of your choice)","1/4 cup sugar","1/4 teaspoon oregano","1 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Mix beans, vegetables and garlic cloves in a large bowl.","Mix vinegar, oil, and sugar in a saucepan. Heat until sugar dissolves. Cool slightly.","Stir seasonings into vinegar mixture. Pour over vegetables. Toss lightly. Chill overnight.","Remove garlic before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 recipe (250g)","calories":"188.83 kcal","carbohydrateContent":"21.58 g","cholesterolContent":"0.00 mg","fiberContent":"4.40 g","proteinContent":"3.89 g","sodiumContent":"471.89 mg","sugarContent":"11.47 g","fatContent":"9.75 g","saturatedFatContent":"1.36 g"},"notes":null,"contributor":"The Bold and Beautiful Book of Bean Recipes\nWashington State WIC Program"},
{"slug":"three-grain-peanut-bread","source_url":"https://www.myplate.gov/recipes/three-grain-peanut-bread","name":"Three-Grain Peanut Bread","description":"Enjoy this scrumptious snack with your family. Use another nut butter if a member of your family suffers from a peanut allergy.","ingredients":[{"name":null,"items":["1 cup flour","1/2 cup oatmeal (quick cooking)","1/2 cup cornmeal","1/2 cup non-fat dry milk powder","1/2 cup sugar","1 tablespoon baking powder","3/4 teaspoon salt","2/3 cup peanut butter","1 egg","1 1/2 cups non-fat milk"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 °F.","Combine dry ingredients in a large bowl.","Using two knives, cut peanut butter into dry ingredients until it appears coarse and crumbly.","In a small bowl, beat together egg white and milk. Add to dry ingredients and mix well.","Spread mixture into a greased loaf pan. Bake at 325 °F for 1 hour and 10 minutes.","Cool for 10 minutes and remove from pan."]}],"yield":"20 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 ounce slice","1/20 of recipe (50g)"],"calories":"132.54 kcal","carbohydrateContent":"17.36 g","cholesterolContent":"11.16 mg","fiberContent":"1.01 g","proteinContent":"4.64 g","sodiumContent":"219.64 mg","sugarContent":"7.76 g","fatContent":"4.98 g","saturatedFatContent":"1.01 g"},"notes":null,"contributor":"Healthy Futures: Choosing Healthy Foods\nVirginia Cooperative Extension"},
{"slug":"three-sisters-soup","source_url":"https://www.myplate.gov/recipes/three-sisters-soup","name":"Three Sisters Soup","description":"A true comfort recipe to warm you up year-round. Make it your own by using any vegetables or beans that you have on hand.","ingredients":[{"name":null,"items":["1 1/2 tablespoons vegetable oil (or cooking oil of your choice)","3/4 cup carrot (diced)","1 cup onion (chopped)","4 cloves garlic (minced or 1 teaspoon garlic powder)","2 cups summer or winter squash (diced - fresh or frozen)","1 1/2 cups corn (fresh or frozen or a 15-oz can (drained and rinsed))","1 1/2 cups cooked beans (any type or a 15-oz can (low-sodium, drained and rinsed))","1 can low-sodium diced tomatoes (14.5 ounces or 2 cups diced fresh)","3 cups any flavor broth (low-sodium )","1 teaspoon cumin","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Heat oil in a large pan on medium heat. Add carrot and onion and sauté until onions have begun to turn slightly brown, about 8 to 10 minutes.","Add garlic, squash, and corn and continue to stir for another 3 to 4 minutes.","Add beans, tomatoes, broth, cumin, and pepper.","Allow soup to come to a boil and then turn heat down to a simmer until all vegetables are tender to taste (15 to 30 minutes, depending on the vegetables used)."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"122.60 kcal","carbohydrateContent":"20.45 g","cholesterolContent":"0.00 mg","fiberContent":"4.94 g","proteinContent":"4.56 g","sodiumContent":"130.35 mg","sugarContent":"6.86 g","fatContent":"3.71 g","saturatedFatContent":"0.59 g"},"notes":"Try This: Change the vegetables and beans based on what you have on hand. Instead of cumin, try 2 to 3 teaspoons of Italian seasoning or 1 tablespoon of curry powder.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"three-sisters-stew","source_url":"https://www.myplate.gov/recipes/three-sisters-stew","name":"Three Sisters Stew","description":"This hearty stew is great for dinner and even better the next day. It uses different ingredients like sweet potatoes and quick-cooking oats.","ingredients":[{"name":null,"items":["1/2 pound ground beef","1 cup onions, diced","3 cups water","3 cups red potatoes, cubed (or 1 1/2 cans, about 24 ounces, low-sodium sliced potatoes, drained)","2 tomatoes, diced (or 1 can, about 15 ounces, low-sodium diced tomatoes, drained)","1 can (15 ounces) tomato sauce, no salt added","1/2 cup frozen corn kernels (or 1/4 can, about 4 ounces, low-sodium whole kernel corn, drained)","1/2 cup yellow squash, diced (or 1/4 can, about 4 ounces, low-sodium sweet potatoes, drained and diced)","1/2 cup green squash, diced (or 1/4 can, about 4 ounces, low-sodium carrots, drained)","1/2 can low-sodium kidney beans, drained (about 8 ounces)","1/2 can low-sodium black beans (about 8 ounces)","1/4 cup quick cooking oats","2 cloves garlic, finely chopped","1/4 teaspoon black pepper","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["In a small skillet, brown ground beef and onions over medium to high heat for 8 to 10 minutes. Drain fat.","In a large pot, combine cooked ground beef, water, and red potatoes.","Bring the pot to a boil and cook for 15 minutes.","Add all the other ingredients to the pot and bring to a boil. Lower heat and simmer for about 25 minutes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup stew","calories":"230.80 kcal","carbohydrateContent":"36.77 g","cholesterolContent":"21.91 mg","fiberContent":"8.15 g","proteinContent":"14.57 g","sodiumContent":"236.02 mg","sugarContent":"7.12 g","fatContent":"3.76 g","saturatedFatContent":"1.31 g"},"notes":"Tip for cooking ground beef: The recommended safe minimum internal temperature for ground beef is 160 °F, as measured with a food thermometer.\nSee how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations\nAdapted from a recipe submitted by Alicson Scott, Chickasaw Nation, Get Fresh! Nutrition Education Program"},
{"slug":"tic-tac-toe-veggie-pizza","source_url":"https://www.myplate.gov/recipes/tic-tac-toe-veggie-pizza","name":"Tic Tac Toe Veggie Pizza","description":"Let kids build mini pizzas. Top a whole-grain pita with sauce and criss-cross of low-fat mozzarella cheese and vegetables for a quick, fun dinner.","ingredients":[{"name":null,"items":["1 medium carrot","1/2 red bell pepper","1 medium summer squash","4 whole wheat pita rounds (about 6\" diameter)","3/4 cup pasta sauce, no salt added","4 sticks part skim mozzarella string cheese"]}],"directions":[{"name":null,"steps":["Place rack in middle of oven and pre-heat to 400 °F.","For Xs, cut carrot and bell pepper into small sticks about 2 inches long. For Os, cut summer squash into 12 slices. For grid, pull apart each cheese stick to make 4 strips.","Place pita rounds on baking sheet and spread pasta sauce on each.","Let kids build tic tac toe pizzas with cheese and vegetables.","Bake about 10 minutes or until cheese is bubbling."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 pita pizza","calories":"262.80 kcal","carbohydrateContent":"39.57 g","cholesterolContent":"18.43 mg","fiberContent":"5.23 g","proteinContent":"13.65 g","sodiumContent":"455.73 mg","sugarContent":"6.21 g","fatContent":"7.10 g","saturatedFatContent":"3.50 g"},"notes":null,"contributor":"Produce for Better Health Foundation"},
{"slug":"tofu-broccoli","source_url":"https://www.myplate.gov/recipes/tofu-broccoli","name":"Tofu with Broccoli","description":"Tofu cooked until golden brown, and broccoli sautéed in a soy and scallion sauce make up this one-skillet meal. Serve with a side of brown rice for a quick ...","ingredients":[{"name":null,"items":["1 pound firm tofu","4 teaspoons vegetable oil, divided","2 cloves garlic, minced","2 scallions, chopped","1 head broccoli, chopped","1/4 cup water","1 tablespoon reduced sodium soy sauce","1/2 teaspoon crushed red pepper flakes","1 tablespoon chopped fresh cilantro (or basil leaves)"]}],"directions":[{"name":null,"steps":["Put the tofu on a cutting board and cut it in half and then cut each half into 4 equal pieces.","Put 2 layers of paper towel on a cutting board and put the tofu on top. Let drain at least 20 minutes (and up to 2 hours).","Place a skillet over medium heat and when hot, add 2 teaspoons oil. Add the tofu, one piece at a time, and cook until golden, about 3 minutes per side. Remove the tofu to a plate and set aside.","Reheat the skillet and when hot, add remaining 2 teaspoons oil. Add garlic and scallions and cook until just golden, about 2 minutes. Add the broccoli and water and raise the heat to high. Cook until the broccoli is tender, about 4 minutes.","Return the tofu to the pan and add the remaining ingredients. Stir well.","Serve with a side of brown rice."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"4 ounce serving","calories":"206.14 kcal","carbohydrateContent":"12.60 g","cholesterolContent":"0.00 mg","fiberContent":"5.34 g","proteinContent":"15.99 g","sodiumContent":"207.77 mg","sugarContent":"3.23 g","fatContent":"11.20 g","saturatedFatContent":"1.75 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"tofu-salad","source_url":"https://www.myplate.gov/recipes/tofu-salad","name":"Tofu Salad","description":"Searching for a good vegetarian lunch option? Enjoy this tofu and vegetable salad on whole grain bread, with a piece of fruit for a satisfying and tasty meal...","ingredients":[{"name":null,"items":["3/4 pound firm tofu","2 tablespoons reduced-fat mayonnaise","3 teaspoons brown mustard","1/2 teaspoon low-sodium soy sauce","1/2 cup celery (diced)","1 tablespoon onion (diced)","1/2 green pepper (seeded and diced)","1 tablespoon parsley (minced)"]}],"directions":[{"name":null,"steps":["Prepare tofu by draining the water from the package and placing tofu between two plates. Put a heavy object on top and let stand for 10 to 15 minutes. Drain the water that collects on the bottom plate every few minutes.","In a small bowl, mix the mayonnaise, mustard, and soy sauce.","In a medium bowl, combine the diced tofu, celery, onion, pepper, and parley; stir in the mayonnaise mixture and toss gently to coat.","Refrigerate covered until the flavors are blended -- at least one hour.","Use as a sandwich filling or on top of whole grain crackers."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup prepared salad","1/4 of recipe"],"calories":"98.51 kcal","carbohydrateContent":"3.37 g","cholesterolContent":"1.25 mg","fiberContent":"1.58 g","proteinContent":"9.02 g","sodiumContent":"146.16 mg","sugarContent":"1.65 g","fatContent":"6.39 g","saturatedFatContent":"1.08 g"},"notes":"You may substitute yellow mustard for brown mustard.","contributor":"University of Connecticut Family Nutrition Program\nSenior Nutrition Awareness Project (SNAP) Newsletters"},
{"slug":"tofu-tomato-and-spinach-soup","source_url":"https://www.myplate.gov/recipes/tofu-tomato-and-spinach-soup","name":"Tofu, Tomato, and Spinach Soup","description":"This vegetable and tofu soup is a delicious way to end your day. You can use fresh or frozen spinach and top with cilantro for a satisfying soup.","ingredients":[{"name":null,"items":["1 teaspoon vegetable oil","1/2 cup onion (chopped)","1 garlic clove (minced)","6 cups water (or low-sodium chicken broth)","1 package tofu, silken, firm or extra firm (14 ounce - patted dry and cut into ½ inch cubes)","2 tomatoes (chopped)","green onions, chopped (3 stalks, optional)","4 cups spinach leaves, fresh (washed and dried, or 1- 10 ounce box frozen chopped spinach, thawed and squeezed dry)","1 tablespoon soy sauce, reduced sodium","1/4 teaspoon ground black pepper","cilantro leaves (1/4 cup, optional)"]}],"directions":[{"name":null,"steps":["Heat a 3 quart saucepan over medium heat; add oil and chopped onion. Cook onion until softened, but not brown. Stir in garlic and cook just until fragrant.","Add chicken broth. Bring to a boil. Add tomatoes and tofu. Lower heat and simmer until tomatoes are soft but not mushy (this takes just a couple of minutes).","Stir in green onions (optional), spinach, ground pepper and cilantro. Cook just until spinach is wilted.","Remove from heat. Taste for seasoning. Serve hot."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe (605g)","calories":"120.53 kcal","carbohydrateContent":"6.30 g","cholesterolContent":"0.00 mg","fiberContent":"2.16 g","proteinContent":"11.71 g","sodiumContent":"193.50 mg","sugarContent":"3.00 g","fatContent":"6.62 g","saturatedFatContent":"1.11 g"},"notes":"Add extra vegetables that you have on hand, such as peppers, spinach, avocado, kale, etc. for more flavor and nutrients!","contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"tomato-and-cucumber-salad","source_url":"https://www.myplate.gov/recipes/tomato-and-cucumber-salad","name":"Tomato and Cucumber Salad","description":"This refreshing salad is an excellent source of vitamin C and a great way to take advantage of the vegetables’ summer growing season.","ingredients":[{"name":"Salad","items":["4 large tomatoes (cubed)","1 large cucumber (chopped)","1 cup red onion (chopped)","1 cup green pepper (chopped)","1/3 cup parsley (chopped)"]},{"name":"Dressing","items":["1/3 cup apple cider vinegar","1 tablespoon olive oil (or oil of your choice)","2 cloves garlic (minced)","1/2 teaspoon salt","1/2 teaspoon ground black pepper","1/2 teaspoon sugar"]}],"directions":[{"name":null,"steps":["In a large bowl, combine the salad ingredients.","In a small bowl, mix the dressing ingredients together.","Pour the dressing over the salad. Mix well.","Refrigerate for at least 1 hour before serving."]}],"yield":"12 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup","calories":"32.54 kcal","carbohydrateContent":"4.54 g","cholesterolContent":"0.00 mg","fiberContent":"1.11 g","proteinContent":"0.76 g","sodiumContent":"102.25 mg","sugarContent":"2.67 g","fatContent":"1.36 g","saturatedFatContent":"0.22 g"},"notes":null,"contributor":"University of Nebraska at Lincoln\nNebraska Nutrition Education Program"},
{"slug":"tomato-and-garlic-omelet","source_url":"https://www.myplate.gov/recipes/tomato-and-garlic-omelet","name":"Tomato and Garlic Omelet","description":"Toasted garlic bread and mozzarella cheese combine with tomatoes and basil to give this easy omelet delicious, fresh flavor. Add a piece of fruit on the side...","ingredients":[{"name":null,"items":["1/2 slice whole wheat bread","1/2 teaspoon olive oil (or cooking oil of your choice)","1 garlic clove (finely chopped)","non-stick cooking spray (as needed)","3/4 cup egg substitute","2 tablespoons mozzarella cheese (part skim, grated)","10 plum tomatoes, raw (cut in half)","1 teaspoon basil (fresh or dried)"]}],"directions":[{"name":null,"steps":["Preheat oven to 300 °F.","Cut the bread into cubes; toss with oil and garlic in a small bowl. Spread the cubes in a single layer on a baking sheet and toast in the oven for 15 to 25 minutes, or until golden brown, tossing once or twice. Transfer to a plate to cool.","Spray a medium pan with nonstick cooking spray and heat over medium-high heat. Pour in egg substitute.","When the egg begins to set, spread evenly across the bottom of the pan and reduce the heat to low.","Once the top layer of egg is almost cooked, sprinkle the cheese and basil on top and scatter the tomatoes and bread over half of the omelet; fold the unfilled omelet half over the filling. Slide the omelet on a plate and serve."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 omelet (407g)","calories":"322.48 kcal","carbohydrateContent":"37.74 g","cholesterolContent":"9.18 mg","fiberContent":"8.89 g","proteinContent":"29.00 g","sodiumContent":"563.55 mg","sugarContent":"20.48 g","fatContent":"7.78 g","saturatedFatContent":"2.36 g"},"notes":null,"contributor":"California Champions for Change: Breakfast Recipes\nCalifornia Department of Public Health\nNetwork for a Healthy California"},
{"slug":"tomato-basil-and-bean-pasta-salad","source_url":"https://www.myplate.gov/recipes/tomato-basil-and-bean-pasta-salad","name":"Tomato Basil and Bean Pasta Salad","description":"Beans, tomatoes, and basil are mixed with pasta and a tasty vinaigrette to give you a easy and tasty meal. Bring this pasta salad to your next cookout or gat...","ingredients":[{"name":null,"items":["1 pound pasta (ziti, bow tie or other shaped pasta)","2 tablespoons vegetable oil (or cooking oil of your choice)","1/4 cup vinegar","2 teaspoons Dijon mustard","1/4 teaspoon ground black pepper","1 cup fresh basil leaves (chopped)","3 large tomatoes (or cherry tomatoes)","1 cup kidney beans (cooked or low-sodium canned drained, or try garbanzo beans or black beans)","mozzarella cheese, fat-free (cubed or shredded cheese, optional)","walnuts (chopped, optional)"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions. Drain and cool.","In a small mixing bowl, whisk together vegetable oil, vinegar, Dijon-style mustard, and pepper to make vinaigrette.","In a large mixing bowl, combine pasta, beans, basil, and tomatoes. Pour vinaigrette over top and toss together. Cover and chill at least 1 hour.","If desired, add nuts and cheese just before serving, tossing again to combine."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup (184g)","calories":"218.07 kcal","carbohydrateContent":"38.06 g","cholesterolContent":"0.00 mg","fiberContent":"3.59 g","proteinContent":"7.84 g","sodiumContent":"58.68 mg","sugarContent":"1.92 g","fatContent":"3.55 g","saturatedFatContent":"0.56 g"},"notes":"Optional ingredients, walnuts and mozzarella, are not included in nutrition analysis and cost estimate.\nAdd other fresh chopped vegetables such as cucumbers, peppers, small summer squash, carrots, broccoli, or cauliflower.\nUse your favorite salad dressing instead of making your own.","contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"tomato-basil-bruschetta","source_url":"https://www.myplate.gov/recipes/tomato-basil-bruschetta","name":"Tomato Basil Bruschetta","description":"This delicious appetizer is a great way to use ripe tomatoes and basil from your garden. Serve with toasted bread on the side for a quick and delicious appet...","ingredients":[{"name":null,"items":["8 tomatoes (ripe, Roma plum, chopped)","2 garlic clove (minced)","1/2 large onion (chopped)","6 basil leaves (fresh)","2 tablespoons olive oil (or cooking oil of your choice)","salt (optional, to taste)","black pepper (optional, to taste)","2 French bread baguette (or Italian, cut into 1/2 inch diagonal slices)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F.","Combine tomatoes, garlic, onion, basil, and olive oil in a bowl. Season with salt and freshly ground black pepper, to taste (optional). Set aside.","Arrange bread on a baking sheet in a single layer. Bake about 5 to 7 minutes until it begins to brown slightly.","Remove bread from oven and transfer to a serving platter.","Serve the tomato mixture in a bowl with a serving spoon and let everyone help themselves. Or place some on each slice of bread before serving. If adding the tomato mixture yourself, add it at the last minute or the bread may become soggy."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 piece (69g)","calories":"101.02 kcal","carbohydrateContent":"15.43 g","cholesterolContent":"0.00 mg","fiberContent":"1.16 g","proteinContent":"3.16 g","sodiumContent":"154.31 mg","sugarContent":"2.59 g","fatContent":"3.08 g","saturatedFatContent":"0.51 g"},"notes":null,"contributor":"Healthy Eating Recipes\nUniversity of Nebraska Cooperative Extension"},
{"slug":"tomato-basil-soup","source_url":"https://www.myplate.gov/recipes/tomato-basil-soup","name":"Tomato Basil Soup","description":"This creamy soup can be prepared using pantry staples such as canned tomatoes and non-fat dry milk. Garlic and onion give this delicious soup an extra kick o...","ingredients":[{"name":null,"items":["1 medium onion (chopped)","1 tablespoon olive oil (or cooking oil of your choice)","2 garlic cloves (crushed, or 1/4 teaspoon garlic powder)","1 can low-sodium tomatoes (14 1/2 ounce, chopped)","1/8 teaspoon red pepper (or to taste)","1 teaspoon basil (dried)","2/3 cup non-fat dry milk (+ 2 cups water or substitute 2 cups non-fat milk)","salt and pepper (optional, to taste)"]}],"directions":[{"name":null,"steps":["In a medium saucepan, cook onion in oil over medium heat, stirring frequently until golden brown, about 4 minutes.","Add garlic and cook 1 minute longer. Add chopped tomatoes.","Cook uncovered over medium heat for 10 minutes.","Spoon 3/4 of mixture into food processor or blender container; puree until smooth. Return to saucepan.","Add red pepper, basil, and reconstituted milk to the soup.","Heat until hot, but do not boil.","Season to taste with salt and pepper (optional).","Serve immediately."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup soup","1/4 of recipe (282g)"],"calories":"107.13 kcal","carbohydrateContent":"13.58 g","cholesterolContent":"2.28 mg","fiberContent":"2.79 g","proteinContent":"5.52 g","sodiumContent":"73.33 mg","sugarContent":"10.13 g","fatContent":"3.90 g","saturatedFatContent":"0.65 g"},"notes":null,"contributor":"USDA’s Collection of Nonfat Dry Milk Recipes\nUSDA Food and Nutrition Service\nFood Distribution Service"},
{"slug":"tomato-n-cheese-pasta","source_url":"https://www.myplate.gov/recipes/tomato-n-cheese-pasta","name":"Tomato N'' Cheese Pasta","description":"Pasta and tomato sauce are topped with cheese and cooked in the oven. Double this recipe for a family of 4. Add a tossed salad for a hearty meal.","ingredients":[{"name":null,"items":["1 cup whole grain pasta (shell, penne, or ziti)","1/4 cup onion (chopped)","2 garlic cloves (minced)","1 tablespoon olive oil (or cooking oil of your choice)","1 can diced tomatoes (14.5 ounces, un-salted)","1/2 teaspoon basil (fresh or dried)","1/2 teaspoon oregano","1/4 teaspoon sugar","1/4 teaspoon black pepper","1/4 cup part-skim mozzarella (shredded)","1 tablespoon Parmesan cheese (grated)"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions; drain.","In a small saucepan, cook onion and garlic in oil until tender.","Stir in tomatoes, basil, oregano, sugar, and pepper.","Bring to a boil. Reduce heat. Simmer uncovered for 15 minutes. Add pasta to sauce.","Transfer to a greased 1-quart baking dish.","Top with cheeses.","Bake, uncovered at 375 °F for 10 to 15 minutes or until cheese is melted."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"356.78 kcal","carbohydrateContent":"50.59 g","cholesterolContent":"11.33 mg","fiberContent":"9.77 g","proteinContent":"13.99 g","sodiumContent":"161.62 mg","sugarContent":"7.91 g","fatContent":"13.39 g","saturatedFatContent":"3.55 g"},"notes":null,"contributor":"Cooking For You or Two\nUniversity of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"tortellini-soup","source_url":"https://www.myplate.gov/recipes/tortellini-soup","name":"Tortellini Soup","description":"Peas, lentils, and beans combined with spices and veggies provide this pasta soup with flavor and fiber. Enjoy this hearty soup on a chilly night.","ingredients":[{"name":null,"items":["1 cup dry Great Northern beans","1/4 cup dry brown lentils","1/4 cup dry green split peas","2 tablespoons dry parsley flakes","3 teaspoons chicken broth granules","1 can low-sodium tomatoes","2 tablespoons Parmesan cheese, grated","1 teaspoon onion powder","1/16 teaspoon minced garlic, instant (pinch)","1/2 teaspoon dry thyme","3/4 cup tortellini, uncooked","1 cup carrot, coarsely chopped","1 cup celery, coarsely chopped","2 tablespoons basil (optional)"]}],"directions":[{"name":null,"steps":["Rinse beans. Put into a 4 or 5 quart heavy pot with 8 cups of water. Bring to a boil, reduce heat to medium, cover, and simmer until the beans are tender (1 1/4 to 1 1/2 hours).","Add 4 cups water and remaining ingredients to beans. Return to boil. Reduce heat to low, cover and simmer 1/2 hour, until tortellini and vegetables are tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups soup","1/6 of recipe"],"calories":"234.30 kcal","carbohydrateContent":"40.45 g","cholesterolContent":"7.56 mg","fiberContent":"10.98 g","proteinContent":"14.80 g","sodiumContent":"335.80 mg","sugarContent":"4.57 g","fatContent":"2.39 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Food and Health Communications, Inc."},
{"slug":"tortilla-pizzas","source_url":"https://www.myplate.gov/recipes/tortilla-pizzas","name":"Tortilla Pizzas","description":"These mini pizzas combine the flavors of tacos with the fun and variety of pizza. A favorite for kids and adults alike.","ingredients":[{"name":null,"items":["12 (4-inch) corn tortillas (or flour tortillas)","1 teaspoon vegetable oil (or cooking oil of choice or margarine)","1 can (16 ounces) low-sodium, fat-free refried beans","1/4 cup onion, chopped","2 ounces fresh or canned green chili peppers, diced","3 tablespoons red taco sauce","3 cups vegetables, chopped (try broccoli, mushrooms, spinach, and red bell pepper, or use your favorite veggies)","1/2 cup part-skim mozzarella cheese, shredded","cilantro (1/2 cup chopped, fresh, optional)"]}],"directions":[{"name":null,"steps":["Brush one side of two tortillas with water. Press the wet sides of the tortillas together to form a thick crust for the pizza.","Brush the outside of the tortillas with a small amount of oil or margarine. Evenly brown both sides in a heated frying pan. Repeat with the rest of the tortillas. Set aside.","Heat refried beans, onion, and half of the chili peppers together in a medium saucepan, stirring occasionally. Remove from heat.","Spread about 1/3 cup of the bean mixture on each tortilla pizza. Sprinkle with 1/2 tablespoon taco sauce, then top with 1/2 cup of the chopped vegetables, 1 teaspoon chili peppers, and 1 tablespoon cheese for each pizza.","Return to frying pan and heat until cheese melts. Top with cilantro, if desired. Serve immediately."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 prepared pizza","1/6 of recipe"],"calories":"203.72 kcal","carbohydrateContent":"30.66 g","cholesterolContent":"6.12 mg","fiberContent":"6.46 g","proteinContent":"9.44 g","sodiumContent":"285.94 mg","sugarContent":"1.82 g","fatContent":"5.48 g","saturatedFatContent":"1.88 g"},"notes":"Corn tortillas used for nutrient analysis. Using flour tortillas will change nutrition information.","contributor":"Healthy Latino Recipes Made with Love\nCalifornia Department of Health Services\nCalifornia Latino 5-A-Day Campaign"},
{"slug":"tortilla","source_url":"https://www.myplate.gov/recipes/tortilla","name":"Tortilla Chips and Bean Dip","description":"Prepare this layered dip with beans, salsa, sour cream, and cheese for your next party. Make your own tortilla chips to serve on the side. Fill up on fiber w...","ingredients":[{"name":null,"items":["4 (6-inch) corn tortillas","1 can (15.5 ounces) low-sodium kidney beans","1/4 salsa recipe (1/2 cup)","1/4 cup fat-free sour cream","1/2 cup cheddar cheese, shredded","1 cup lettuce, shredded"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 degrees F.","Place tortillas in a stack on cutting board. With a sharp knife, cut stack into eight pieces, forming triangles or wedges.","Lay tortillas pieces out in single layer on baking sheet. Set aside while making dip.","Open canned beans. Pour beans in colander; rinse and drain. Place beans in a small mixing bowl and mash with a potato masher. Spread beans over bottom of baking dish.","Measure salsa and spread over beans.","Measure sour cream and spread over beans.","Grate and measure cheese; sprinkle over bean mixture.","Place lettuce wedge on cutting board. Slice into thin strips; set aside.","Place both the baking sheet with tortilla pieces and the dip in preheated oven. Bake about 8 minutes or until tortilla pieces are crisp and dip is bubbly. Sprinkle lettuce over dip and serve with tortilla chips."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"221.90 kcal","carbohydrateContent":"32.09 g","cholesterolContent":"15.48 mg","fiberContent":"7.87 g","proteinContent":"11.27 g","sodiumContent":"262.95 mg","sugarContent":"2.69 g","fatContent":"6.04 g","saturatedFatContent":"2.99 g"},"notes":"Flavor Change Options:\nUse Monterey Jack or another cheese.\nSubstitute black beans for kidney beans.\nSubstitute 1/4 cup chopped fresh tomatoes for taco sauce.\nSpread one small can chopped green chilis over beans.","contributor":"Cooking Up Fun - A Pyramid of Snacks\nCornell Cooperative Extension\nCornell University Division of Nutritional Sciences"},
{"slug":"tostadas-delgadas","source_url":"https://www.myplate.gov/recipes/tostadas-delgadas","name":"Tostadas Delgadas","description":"Crisp tortillas, refried beans, and layers of fresh veggies make this a tasty and healthy vegetarian option.","ingredients":[{"name":null,"items":["8 tortillas (corn or flour)","2 cups refried beans (fat-free)","2 cups lettuce (shredded)","1 cup tomatoes (diced)","1 cup cheese (shredded)","green onions (chopped, optional)"]}],"directions":[{"name":null,"steps":["Turn on oven to 350 °F.","Place tortillas on a cookie sheet and put in oven for 10 minutes or until crispy.","Wash lettuce and tomatoes. Shred lettuce and dice tomatoes","Spread two large tablespoons of refried beans on each tortilla.","Top with lettuce, tomatoes, and cheese. Add green onions if desired.","Serve immediately and refrigerate leftovers."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 tostada (160g)","calories":"246.41 kcal","carbohydrateContent":"31.42 g","cholesterolContent":"14.13 mg","fiberContent":"4.62 g","proteinContent":"10.33 g","sodiumContent":"628.17 mg","sugarContent":"2.69 g","fatContent":"8.74 g","saturatedFatContent":"4.09 g"},"notes":null,"contributor":"The Texas A&M University System\nTexas A&M AgriLife Extension Service\nExpanded Food and Nutrition Education Program"},
{"slug":"tostadas","source_url":"https://www.myplate.gov/recipes/tostadas","name":"Tostadas","description":"A toasty tortilla with beans and melted cheese, topped with cool fresh veggies!","ingredients":[{"name":null,"items":["6 flour tortillas","chili powder (2 teaspoons, optional)","2 cups refried beans (fat-free, low-sodium)","1 cup cheddar cheese (shredded)","1 cup romaine lettuce (shredded)","1 tomato ( large, chopped)","salsa (to taste)","light sour cream (optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","On a baking sheet, arrange tortillas in a single layer. Spray both sides with non-stick cooking spray and bake for 4 minutes or until crisp.","If desired mix chili powder into refried beans.","Spoon 1/3 cup of refried beans on each tostada. Sprinkle with cheese.","Bake for 10 minutes or until cheese is melted.","Top each one with lettuce and tomato.","Serve with salsa and sour cream (optional)."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 Tostados","calories":"253.66 kcal","carbohydrateContent":"28.52 g","cholesterolContent":"18.83 mg","fiberContent":"4.42 g","proteinContent":"11.30 g","sodiumContent":"478.00 mg","sugarContent":"2.31 g","fatContent":"10.71 g","saturatedFatContent":"5.09 g"},"notes":null,"contributor":"University of Nebraska\nNebraska Nutrition Education Program"},
{"slug":"trail-mix-bars","source_url":"https://www.myplate.gov/recipes/trail-mix-bars","name":"Trail Mix Bars","description":"You can adjust this recipe to accommodate food allergies. Try with sunflower seed butter or almond butter if you are working with a peanut allergy.","ingredients":[{"name":null,"items":["3 cups crispy rice cereal","3 cups toasted oat cereal","1 1/2 cups raisins","1/2 cup sunflower seeds, no salt","1 cup honey*","3/4 cup sugar","1 (16 ounce) jar chunky peanut butter","1 teaspoon vanilla"]}],"directions":[{"name":null,"steps":["Combine dry ingredients in bowl.","Combine honey and sugar in pan and bring to a boil.","Add peanut butter and vanilla, stir until peanut butter melts.","Pour mixture over cereal and mix well.","Press into a 13x9 inch pan and cool."]}],"yield":"28 Bars","nutrition":{"@type":"NutritionInformation","servingSize":["1 bar","1/28 of the recipe (50g)"],"calories":"224.57 kcal","carbohydrateContent":"30.64 g","cholesterolContent":"0.00 mg","fiberContent":"1.82 g","proteinContent":"5.04 g","sodiumContent":"106.22 mg","sugarContent":"23.07 g","fatContent":"9.85 g","saturatedFatContent":"1.82 g"},"notes":"* Children under one year of age should not consume honey.","contributor":"University of Wisconsin Cooperative Extension Service"},
{"slug":"trail-treat","source_url":"https://www.myplate.gov/recipes/trail-treat","name":"Trail Treat","description":"Throw together this quick treat full of dried fruit, nuts, and delicious grains. Enjoy it as a snack on your next walk through the park or hike.","ingredients":[{"name":"Choose Two of These","items":["pretzels (1 cup)","square corn, rice, or wheat cereal (1 cup)","1 cup round oat cereal","1 cup popcorn","goldfish crackers (1 cup)"]},{"name":"Choose Two of These","items":["1/4 cup raisins","dried cranberries (1/4 cup)","dried banana chips (1/4 cup)","dried pineapple (1/4 cup)","1/4 cup peanuts","soy nuts (1/4 cup)"]}],"directions":[{"name":null,"steps":["Choose the ingredients you want to use.","Measure the suggested amounts of chosen ingredients and add to mixing bowl.","Mix ingredients using stirring spoon and divide evenly into 4 storage bags.","Enjoy your Trail Treat!"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"125.45 kcal","carbohydrateContent":"17.18 g","cholesterolContent":"0.00 mg","fiberContent":"2.39 g","proteinContent":"4.06 g","sodiumContent":"79.47 mg","sugarContent":"8.55 g","fatContent":"5.41 g","saturatedFatContent":"0.89 g"},"notes":"Ingredients used for costing and nutritional analysis:\nround oat cereal\npopcorn\nraisins\npeanuts","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"tropical-morning-treat","source_url":"https://www.myplate.gov/recipes/tropical-morning-treat","name":"Tropical Morning Treat","description":"Enjoy this tasty fruit dish in the morning or as a snack anytime of the day.","ingredients":[{"name":null,"items":["1/4 cup orange juice","1 apple","1 orange","1 banana"]}],"directions":[{"name":null,"steps":["Place orange juice in bowl.","Wash apple and dry. Remove the seeds and dice. Coat apple surfaces with orange juice to prevent browning.","Peel orange and break into sections. Cut sections into small pieces.","Peel and slice banana into 1/4 inch circles.","Combine all fruit and orange juice lightly in a bowl and mix together. Chill or serve immediately."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup","1/4 of recipe (114g)"],"calories":"87.59 kcal","carbohydrateContent":"20.64 g","cholesterolContent":"0.00 mg","fiberContent":"2.48 g","proteinContent":"0.80 g","sodiumContent":"1.54 mg","sugarContent":"15.73 g","fatContent":"0.27 g","saturatedFatContent":"0.06 g"},"notes":null,"contributor":"University of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"tropical-overnight-oatmeal","source_url":"https://www.myplate.gov/recipes/tropical-overnight-oatmeal","name":"Tropical Overnight Oatmeal","description":"Breakfast is a snap with a quick step the night before. Mix oats, milk, and yogurt and refrigerate overnight. Add bananas and pineapple chunks in the morning...","ingredients":[{"name":null,"items":["2/3 cup old fashion oats, uncooked","2/3 cup non-fat milk","2/3 cup non-fat Greek yogurt","1/8 teaspoon ground allspice","1 cup fresh pineapple chunks","1 medium banana, sliced","2 tablespoons sliced almonds"]}],"directions":[{"name":null,"steps":["Mix oats, milk, yogurt, and allspice in two bowls or glass jars.","Cover and refrigerate overnight.","Just before serving, add pineapple, banana, and almonds."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"331.50 kcal","carbohydrateContent":"52.25 g","cholesterolContent":"6.56 mg","fiberContent":"6.06 g","proteinContent":"17.58 g","sodiumContent":"65.68 mg","sugarContent":"25.54 g","fatContent":"6.80 g","saturatedFatContent":"0.84 g"},"notes":null,"contributor":"Produce for Better Health"},
{"slug":"tropical-yogurt-pops","source_url":"https://www.myplate.gov/recipes/tropical-yogurt-pops","name":"Tropical Yogurt Pops","description":"Enjoy a tropical treat with these frozen yogurt pops! They are fun to make and have 1/4 cup of fruit per serving.","ingredients":[{"name":null,"items":["1 cup low-fat vanilla yogurt","1/2 cup mango pieces, fresh or frozen","1/2 cup pineapple pieces, fresh, canned, or frozen","1/4 cup coconut water","ice cube tray or small paper cups","paper straws or popsicle sticks"]}],"directions":[{"name":null,"steps":["Place all ingredients into blender.","Blend on high until smooth.","Pour into 8 ice cube squares (or 4 small paper cups) and place in cut paper straws or popsicle sticks.","Freeze and enjoy!"]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 yogurt pop cubes","calories":"70.10 kcal","carbohydrateContent":"12.45 g","cholesterolContent":"3.68 mg","fiberContent":"0.62 g","proteinContent":"3.43 g","sodiumContent":"45.96 mg","sugarContent":"11.46 g","fatContent":"1.03 g","saturatedFatContent":"0.61 g"},"notes":"Create your own yogurt pops and experiment with different flavors or try out one of these recipes:\nBanana Cocoa Yogurt Pops\nStrawberry Yogurt Pops\nStrawberry Kiwi Yogurt Pops","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"tuna-apple-salad-sandwich","source_url":"https://www.myplate.gov/recipes/tuna-apple-salad-sandwich","name":"Tuna Apple Salad Sandwich","description":"Liven up your lunch-time sandwich with a refreshing mix of tuna, apples, raisins, and walnuts.","ingredients":[{"name":null,"items":["1 apple (such as Fuji or Pink Lady Washington)","1 12-ounce can chunk light tuna, drained","2 tablespoons low-fat plain yogurt","2 tablespoons light mayonnaise","1/2 cup raisins (or chopped figs)","1/4 cup chopped walnuts","1/8 teaspoon ground black pepper","2 tablespoons chopped fresh parsley (optional)","1/2 teaspoon curry powder (optional)","8 leaves lettuce (Bibb, Romaine, green, or red leaf)","8 slices whole-grain bread"]}],"directions":[{"name":null,"steps":["Cut apple in quarters; remove core and chop.","In a medium-sized bowl, mix all salad ingredients, except tuna.","Gently fold in tuna.","Make sandwiches using lettuce and whole-grain bread (toasted, if desired), and fill with tuna apple salad."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 sandwich","calories":"422.00 kcal","carbohydrateContent":"57.44 g","cholesterolContent":"32.33 mg","fiberContent":"7.13 g","proteinContent":"27.69 g","sodiumContent":"592.77 mg","sugarContent":"23.48 g","fatContent":"10.26 g","saturatedFatContent":"1.56 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of 100% orange juice.","contributor":"Produce for Better Health Foundation"},
{"slug":"tuna-apple-salad","source_url":"https://www.myplate.gov/recipes/tuna-apple-salad","name":"Tuna Apple Salad","description":"Pita bread stuffed with salad greens, tuna, veggies, and fruit makes an easy and flavorful lunch or dinner.","ingredients":[{"name":null,"items":["1 can tuna, packed in water (12 ounces)","2 tablespoons red onions (minced)","1 medium apple (cored and chopped)","1 cup celery (chopped)","1 cup golden raisins","5 tablespoons light Italian dressing","2 cups salad greens","2 pita bread, whole wheat (cut in half)"]}],"directions":[{"name":null,"steps":["In a small bowl, stir together tuna, onion, apple, celery, raisins, and 2 tablespoons of dressing.","In another bowl, toss together salad greens with remaining dressing.","Carefully open pita breads and fill with equal amounts of greens and tuna salad."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 pita","1/4 of recipe (221g)"],"calories":"296.26 kcal","carbohydrateContent":"58.41 g","cholesterolContent":"23.30 mg","fiberContent":"5.47 g","proteinContent":"17.01 g","sodiumContent":"499.50 mg","sugarContent":"35.35 g","fatContent":"1.52 g","saturatedFatContent":"0.32 g"},"notes":"See how to make this recipe and more on USDA’s MyPlate Kitchen YouTube site.","contributor":"Discover the Secret to Healthy Living\nCalifornia Department of Health Services\nCalifornia Children’s 5-A-Day Power Play Campaign"},
{"slug":"tuna-melt-burger","source_url":"https://www.myplate.gov/recipes/tuna-melt-burger","name":"Tuna Melt Burger","description":"Delicious and easy, this tuna melt makes a yummy lunch or dinner. Each sandwich bakes in it''s own foil package, so there''s an added bonus of easy cleanup.","ingredients":[{"name":null,"items":["1 can tuna, water packed (5 ounce)","2 celery (medium stalks, chopped)","1/2 cup American cheese (shredded)","1/4 cup light mayonnaise","1 tablespoon instant minced onion","1/4 teaspoon salt","1/8 teaspoon black pepper","12 whole wheat bread (slices)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Drain tuna and break the meat apart with a fork.","Wash and chop the celery and shred the cheese.","Mix tuna, celery, cheese, light mayonnaise, dried onion, salt, and pepper into a medium mixing bowl with a wooden spoon.","Divide tuna mixture into six portions, place one portion on six slices of whole wheat bread. Then place a single slice of bread on top of each. (you will make a total of 6 sandwiches).","Wrap each sandwich on a square of aluminum foil, folding edges securely.","Bake about 20 minutes or until hot in the middle. Cool slightly before serving.","Remove from oven. Pierce foil to release steam before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 sandwich (120g)","calories":"260.95 kcal","carbohydrateContent":"33.56 g","cholesterolContent":"17.14 mg","fiberContent":"4.60 g","proteinContent":"14.31 g","sodiumContent":"703.47 mg","sugarContent":"4.34 g","fatContent":"7.73 g","saturatedFatContent":"2.46 g"},"notes":null,"contributor":"Texas Cooperative Extension Expanded Nutrition Program\nThe Texas A&M University System"},
{"slug":"tuna-pasta-casserole","source_url":"https://www.myplate.gov/recipes/tuna-pasta-casserole","name":"Tuna Pasta Casserole","description":"This hearty pasta dish uses pantry staples such as canned tuna and cream soup along with a few fresh veggies to make a dish full of protein and flavor.","ingredients":[{"name":null,"items":["12 ounces pasta shells, or other pasta","1/2 cup onion (chopped)","1/2 cup green pepper (chopped)","1/2 tablespoon oil","1 can cream of mushroom soup, reduced sodium (10.75 ounces, or cream of celery, or chicken)","1 can low-sodium diced tomatoes (14.5 ounce)","2 cans water packed tuna (5 ounces each)","shredded cheese (optional)","parsley (chopped, optional)"]}],"directions":[{"name":null,"steps":["Cook pasta according to package directions and drain.","In a large skillet or pot, cook onion and pepper in oil.","Add cream soup, diced tomatoes and tuna to onion and pepper.","Mix with pasta. Put in baking dish.","Cook at 350 °F for 25 minutes until bubbly.","Top with cheese and parsley if desired and return to oven for 5 minutes to melt."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"341.12 kcal","carbohydrateContent":"57.87 g","cholesterolContent":"15.29 mg","fiberContent":"4.87 g","proteinContent":"17.95 g","sodiumContent":"283.72 mg","sugarContent":"4.65 g","fatContent":"4.06 g","saturatedFatContent":"0.83 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"tuna-pasta","source_url":"https://www.myplate.gov/recipes/tuna-pasta","name":"Tuna Pasta","description":"Loaded with protein-packed tuna, nutritious veggies and fresh cooked pasta, this dish makes a delicious meal.","ingredients":[{"name":null,"items":["8 ounces uncooked spaghetti (or other pasta)","1 tablespoon vegetable oil (or canola oil)","1 small onion (chopped)","1/2 cup broccoli (or zucchini, chopped)","1 1/2 cups tomato-based pasta sauce","1 can water packed tuna (5 ounces, drained)","salt (to taste, optional)","Parmesan cheese (optional)","black pepper (to taste, optional)"]}],"directions":[{"name":null,"steps":["Cook spaghetti according to package; drain.","Heat oil in a large skillet or pan over medium heat. Add onion and broccoli (or zucchini). Cook until softened.","Stir in tomato-based pasta sauce. Bring to a boil. Turn heat to low and simmer for 3 minutes.","Add drained tuna into the sauce mixture. Stir just enough to heat the tuna.","Add salt and pepper to taste (optional). Add cooked spaghetti to the sauce. Stir the pasta and sauce mixture until mixed together uniformly.","Optional: Add 2 tablespoons Parmesan cheese to cooked mixture of pasta and sauce.","Serve hot."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"349.99 kcal","carbohydrateContent":"58.49 g","cholesterolContent":"10.35 mg","fiberContent":"5.19 g","proteinContent":"16.54 g","sodiumContent":"80.72 mg","sugarContent":"5.90 g","fatContent":"5.60 g","saturatedFatContent":"0.89 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"tuna-quesadillas","source_url":"https://www.myplate.gov/recipes/tuna-quesadillas","name":"Tuna Quesadillas","description":"This quesadilla can be cooked quickly in the microwave or on the stove. Serve with a fresh salad and an apple for a complete meal.","ingredients":[{"name":null,"items":["1 can tuna fish, packed in water (5 ounces, drained)","1 tablespoon light mayonnaise","4 flour tortillas (8 inch)","1/2 cup reduced-fat cheddar cheese (shredded)"]}],"directions":[{"name":null,"steps":["Mix tuna with mayonnaise.","Microwave\nSpoon filing onto half of each tortilla. Top filling with cheese and fold tortilla in half. Microwave on high for 60 seconds. Turn the plate halfway through cooking time.","OR","Stovetop\nDivide mixture onto two tortillas. Top with cheese and the remaining two tortillas. Spray a skillet with non-stick cooking spray. Brown quesadillas on both sides.","Cut before serving."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 prepared tortilla","1/4 of recipe (89g)"],"calories":"216.05 kcal","carbohydrateContent":"22.99 g","cholesterolContent":"21.71 mg","fiberContent":"1.58 g","proteinContent":"13.04 g","sodiumContent":"515.12 mg","sugarContent":"1.85 g","fatContent":"7.61 g","saturatedFatContent":"3.29 g"},"notes":null,"contributor":"Utah State University Cooperative Extension"},
{"slug":"tuna-salad-grapes","source_url":"https://www.myplate.gov/recipes/tuna-salad-grapes","name":"Tuna Salad with Grapes","description":"Grapes make this tuna salad both savory and sweet. Serve this salad over lettuce leaves for a quick and easy lunch.","ingredients":[{"name":null,"items":["2 cans water packed tuna (5 ounce cans, drained)","1 cup celery (chopped)","1/8 cup mayonnaise (2 Tablespoons)","1/8 cup yogurt, low-fat plain (2 Tablespoons)","1 cup grapes, seedless (cut in half)","7 lettuce leaves, (washed and separated)"]}],"directions":[{"name":null,"steps":["In a medium-sized bowl, combine drained tuna, celery, mayonnaise and yogurt and stir.","Add grapes to mixture and stir gently.","Cover and chill until ready to serve.","Serve over lettuce leaves."]}],"yield":"7 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/7 of recipe","calories":"76.80 kcal","carbohydrateContent":"4.94 g","cholesterolContent":"13.82 mg","fiberContent":"0.54 g","proteinContent":"6.90 g","sodiumContent":"117.23 mg","sugarContent":"3.93 g","fatContent":"3.52 g","saturatedFatContent":"0.62 g"},"notes":"Optional:\nTry apples or mandarin oranges instead of grapes.\nAdd shredded carrots.\nMay also serve on crackers, tortillas, or bread.","contributor":"Adapted from Tuna Salad, Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"tuna-salad-greens","source_url":"https://www.myplate.gov/recipes/tuna-salad-greens","name":"Tuna Salad on Greens","description":"Tuna salad served on a bed of lettuce and veggies with a whole grain crackers on the side makes this an easy and delicious lunch. Have a piece of fruit as a ...","ingredients":[{"name":null,"items":["4 whole grain crackers","4 cups romaine lettuce (chopped)","1 tomato (chopped)","1/4 red onion (chopped)","1 tablespoon olive oil","3 tablespoons vinegar (red wine)","1 teaspoon Italian seasoning","1 dash black pepper","5 ounces tuna, canned in water (drained)","1/3 cup mayonnaise, low-fat","1/4 cup celery (chopped)","1 carrot (peeled and grated)","1/4 cup green onion (chopped)"]}],"directions":[{"name":null,"steps":["Toss lettuce, vegetables, oil, vinegar and herbs in a large salad bowl.","Mix ingredients for tuna salad in another medium sized mixing bowl.","Assemble salad by placing greens on a large plate. Top with a scoop of tuna salad.","Serve crackers on the side."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 cups","1/4 of recipe (203g)"],"calories":"241.36 kcal","carbohydrateContent":"9.35 g","cholesterolContent":"55.05 mg","fiberContent":"1.90 g","proteinContent":"28.72 g","sodiumContent":"550.81 mg","sugarContent":"3.37 g","fatContent":"9.97 g","saturatedFatContent":"1.60 g"},"notes":null,"contributor":"Cooking Demo II\nFood and Health Communications, Inc."},
{"slug":"tuna-salad-ii","source_url":"https://www.myplate.gov/recipes/tuna-salad-ii","name":"Tuna Salad with Grapes","description":"Grapes make this tuna salad both savory and sweet. Serve this salad over lettuce leaves for a quick and easy lunch.","ingredients":[{"name":null,"items":["2 cans water packed tuna (5 ounce cans, drained)","1 cup celery (chopped)","1/8 cup mayonnaise (2 Tablespoons)","1/8 cup yogurt, low-fat plain (2 Tablespoons)","1 cup grapes, seedless (cut in half)","7 lettuce leaves, (washed and separated)"]}],"directions":[{"name":null,"steps":["In a medium-sized bowl, combine drained tuna, celery, mayonnaise and yogurt and stir.","Add grapes to mixture and stir gently.","Cover and chill until ready to serve.","Serve over lettuce leaves."]}],"yield":"7","nutrition":{"@type":"NutritionInformation","calories":"89.85"},"notes":"Optional:\nTry apples or mandarin oranges instead of grapes.\nAdd shredded carrots.\nMay also serve on crackers, tortillas, or bread.","contributor":"Eating Smart, Being Active\nColorado State University and University of California at Davis"},
{"slug":"tuna-slider-green-chiles","source_url":"https://www.myplate.gov/recipes/tuna-slider-green-chiles","name":"Tuna Slider with Green Chiles","description":"For a touch of spice and everything nice, add some canned green chilies to tuna sliders. You won''t believe how much flavor this canned staple packs in! With ...","ingredients":[{"name":null,"items":["5 ounces canned tuna, packed in water (drained and flaked)","1 can chopped green chilies (4 oz. can)","1/4 cup diced celery","1/4 cup diced red onion","1/4 cup light mayonnaise","2 tablespoons chopped fresh cilantro or parsley","6 slider rolls, split","lettuce leaves"]}],"directions":[{"name":null,"steps":["In large bowl, combine tuna, green chilies, celery, red onion, mayonnaise, and chopped cilantro; toss to mix well.","Add lettuce leaves to the bottom half of each roll.","Top with some tuna mixture.","Add top half of roll and enjoy!"]}],"yield":"3 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 sliders","calories":"250.80 kcal","carbohydrateContent":"31.50 g","cholesterolContent":"20.34 mg","fiberContent":"2.20 g","proteinContent":"14.47 g","sodiumContent":"706.28 mg","sugarContent":"2.54 g","fatContent":"7.35 g","saturatedFatContent":"1.15 g"},"notes":null,"contributor":"Cans Get You Cooking"},
{"slug":"tuna-veggie-antipasto","source_url":"https://www.myplate.gov/recipes/tuna-veggie-antipasto","name":"Tuna Veggie Antipasto","description":"Herbs really give this salad a real zest. Marinate overnight in the refrigerator to allow flavors to blend. If you don''t have the vegetables listed, substitu...","ingredients":[{"name":null,"items":["1/2 cup red onion (raw, chopped or any of your favorite raw veggies)","2 1/2 cups celery (raw, chopped or any of your favorite raw veggies)","1 can tuna, in water (5 ounce light, drained and flaked)","1 can white beans (15 ounces, or your favorite beans)","2 tablespoons Parmesan cheese (grated)","1/4 cup vinegar (or juice of 2 lemons)","1 tablespoon vegetable oil","1/2 teaspoon dried dill (or 1 tablespoon fresh dill)","1 teaspoon garlic (chopped)"]}],"directions":[{"name":null,"steps":["Wash and trim vegetables. Chop into bite-sized pieces. Place in large bowl.","Combine vinegar, dill (or other herbs), garlic, and oil. Pour over vegetables.","Drain and rinse beans. Break up tuna into smaller chunks.","Combine vegetables, beans, and tuna; toss gently.","Marinate salad overnight to combine flavors.","Chill and serve as a light summer lunch or as a picnic side dish."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup (203g)","calories":"182.76 kcal","carbohydrateContent":"25.77 g","cholesterolContent":"8.33 mg","fiberContent":"6.33 g","proteinContent":"12.58 g","sodiumContent":"358.91 mg","sugarContent":"3.01 g","fatContent":"3.51 g","saturatedFatContent":"0.79 g"},"notes":"Use salad to fill a pita for a crunchy sandwich.\nServe on fresh, washed leafy lettuce.\nAdd cooked rice or pasta.\nTry balsamic vinegar or 1/2 cup of your favorite salad dressing.\nBe creative and try different herbs and veggie combinations!","contributor":"Farm Fresh Summertime Recipes\nConnecticut Food Policy Council"},
{"slug":"tuna-veggie-picnic-sandwich","source_url":"https://www.myplate.gov/recipes/tuna-veggie-picnic-sandwich","name":"Tuna Veggie Picnic Sandwich","description":"It''s time to raise the bar on the good ol’ tuna sandwich. Boost flavor with lemon juice and Dijon. Seasonal veggies in the mix do double-duty – taste and...","ingredients":[{"name":null,"items":["12 ounces albacore tuna","1/4 cup low-fat mayonnaise","2 tablespoons Dijon mustard","2 teaspoons lemon juice","1/4 cup carrots, shredded","1/4 cup red bell peppers, thinly sliced","1/4 cup celery, diced","6 romaine lettuce leaves, torn in half","12 slices whole wheat bread"]}],"directions":[{"name":null,"steps":["In a small bowl, mix together tuna, mayonnaise, Dijon mustard, and lemon juice.","Stir in carrots, red bell peppers, and celery. Place 6 torn leaves of romaine lettuce on half of the slices of whole wheat bread.","Spoon tuna mixture on top of the lettuce slices.","Place another torn lettuce slice on each tuna sandwich and cover with another slice of bread.","Wrap sandwiches in colorful plastic wrap or wax paper and keep chilled.","Your sandwiches are now picnic ready!"]}],"yield":"6 sandwiches","nutrition":{"@type":"NutritionInformation","servingSize":"1 sandwich","calories":"266.02 kcal","carbohydrateContent":"33.80 g","cholesterolContent":"22.08 mg","fiberContent":"5.06 g","proteinContent":"20.21 g","sodiumContent":"600.68 mg","sugarContent":"4.33 g","fatContent":"5.63 g","saturatedFatContent":"1.03 g"},"notes":null,"contributor":"Created by the Grain Foods Foundation, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"turkey-and-cucumber-sandwich","source_url":"https://www.myplate.gov/recipes/turkey-and-cucumber-sandwich","name":"Turkey and Cucumber Sandwich","description":"These sandwiches, flavored with herbs and spices, are sure to hit the spot. With whole grains, lean protein, and dairy, this well-rounded MyPlate meal will k...","ingredients":[{"name":null,"items":["4 slices whole wheat bread","4 slices enriched white bread","1/2 cup plain fat free yogurt","2 fresh dill sprigs, chopped","1/2 cup cucumbers, chopped","1/4 cup onion, chopped","1/8 teaspoon black pepper","8 ounces turkey breast, thinly sliced (or fat free, low-sodium deli turkey)","additional cucumber slices, as desired","1/8 teaspoon salt (optional)"]}],"directions":[{"name":null,"steps":["Mix the yogurt, dill, onion, pepper, and chopped cucumbers.","Divide the yogurt/ cucumber mixture on all 8 slices of bread.","Top the whole wheat bread with turkey and cucumber slices.","Cover with the white bread slices."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"269.11 kcal","carbohydrateContent":"33.09 g","cholesterolContent":"44.07 mg","fiberContent":"3.07 g","proteinContent":"25.48 g","sodiumContent":"479.03 mg","sugarContent":"6.27 g","fatContent":"3.54 g","saturatedFatContent":"0.88 g"},"notes":null,"contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"turkey-burgers","source_url":"https://www.myplate.gov/recipes/turkey-burgers","name":"Turkey Burgers","description":"Lemon juice give these zesty burgers a real treat for your next cookout. Serve with tomatoes, lettuce, onion, and a whole wheat bun to boost your veggie and ...","ingredients":[{"name":null,"items":["1 pound ground turkey (85% lean)","2 medium onions (chopped)","3 tablespoons lemon juice (or 1 lemon juiced)","1/4 teaspoon Worcestershire sauce","1/4 teaspoon parsley, dried (or fresh chopped)"]}],"directions":[{"name":null,"steps":["Combine onions, turkey, lemon juice, Worcestershire sauce, and parsley. Mix well.","Shape mixture into four patties.","Fry in a pan on medium heat or grill until internal temperature reaches 165 °F."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"237.37 kcal","carbohydrateContent":"7.83 g","cholesterolContent":"84.14 mg","fiberContent":"1.31 g","proteinContent":"20.80 g","sodiumContent":"75.11 mg","sugarContent":"3.47 g","fatContent":"13.96 g","saturatedFatContent":"3.66 g"},"notes":null,"contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"turkey-gravy","source_url":"https://www.myplate.gov/recipes/turkey-gravy","name":"Turkey Gravy","description":"This gravy uses chicken or turkey broth to create an easy and fast gravy. Perfect for a big holiday meal.","ingredients":[{"name":null,"items":["2 tablespoons margarine (or butter)","3 tablespoons flour","1/4 teaspoon salt","1 1/2 cups chicken or turkey broth, low-sodium","2 1/2 ounces giblets (cooked and chopped, approximately 1/2 cup)"]}],"directions":[{"name":null,"steps":["Melt margarine in skillet over low heat. Mix in flour and salt. Stir and heat until bubbly.","Add broth slowly, stirring constantly. Cook over low heat for 5 to 10 minutes.","Add the cooked giblets. Heat a few minutes to blend flavors.","Store leftovers in refrigerator within 2 hours."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (72g)","calories":"52.71 kcal","carbohydrateContent":"3.28 g","cholesterolContent":"25.28 mg","fiberContent":"0.11 g","proteinContent":"2.77 g","sodiumContent":"356.15 mg","sugarContent":"0.27 g","fatContent":"3.13 g","saturatedFatContent":"0.62 g"},"notes":null,"contributor":"Pictorial Recipes\nOregon State University Cooperative Extension Service\nOregon Family Nutrition Program\nRecipe submitted by Lynn Myers Steele, 2000"},
{"slug":"turkey-meatloaf","source_url":"https://www.myplate.gov/recipes/turkey-meatloaf","name":"Turkey Meatloaf","description":"Toss some sweet potatoes in the oven when you''re baking this meatloaf, and pair this dinner with a tossed salad for a tasty and delicious meal!","ingredients":[{"name":null,"items":["1 pound ground turkey (85% lean)","1/2 cup oats (regular, dry)","1 egg","1 tablespoon onion (dehydrated, or one small onion, minced)","1/4 cup ketchup","2 celery stalks (chopped)","2 garlic cloves (minced)","1/2 green pepper (seeded and diced)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Combine all ingredients and mix well.","Bake in 9x5 loaf pan for 25 minutes or until it reaches an internal temperature of 165 °F. Check the temperature with a meat thermometer.","Cut into five slices and serve."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 slice (3 ounces) (129g)","calories":"232.91 kcal","carbohydrateContent":"11.37 g","cholesterolContent":"108.41 mg","fiberContent":"1.34 g","proteinContent":"18.75 g","sodiumContent":"206.95 mg","sugarContent":"3.88 g","fatContent":"12.70 g","saturatedFatContent":"3.32 g"},"notes":null,"contributor":"Delicious Heart-Healthy Latino Recipes/ Platillos Latinos Sabrosos y Saludables\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"turkey-patties","source_url":"https://www.myplate.gov/recipes/turkey-patties","name":"Turkey Patties","description":"Enjoy these tasty patties with fresh tomato slices and your favorite condiments on a whole grain bun.","ingredients":[{"name":null,"items":["1 1/4 pounds ground turkey (85% lean)","1 cup bread crumbs","1 egg","1/4 cup green onion (chopped)","3 teaspoons prepared mustard","nonstick cooking spray"]}],"directions":[{"name":null,"steps":["Mix ground turkey, bread crumbs, egg, onions, and mustard in a large bowl. Shape into 4 patties, about 1/2 inch thick.","Spray a large skillet with cooking spray. Add patties and cook, turning once to brown other side. Cook until golden brown outside and white inside, about 10 minutes. Remove."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 patty","1/4 of recipe (221g)"],"calories":"385.11 kcal","carbohydrateContent":"20.21 g","cholesterolContent":"156.55 mg","fiberContent":"1.54 g","proteinContent":"30.34 g","sodiumContent":"340.36 mg","sugarContent":"1.90 g","fatContent":"20.13 g","saturatedFatContent":"5.27 g"},"notes":null,"contributor":"Quick and Healthy Meals: Tips and Tools for Planning Meals for Your Family\nOhio State University Cooperative Extension\nCuyahoga County"},
{"slug":"turkey-pinwheel-appetizers","source_url":"https://www.myplate.gov/recipes/turkey-pinwheel-appetizers","name":"Turkey Pinwheel Appetizers","description":"Colorful tomatoes and spinach make these appetizers festive enough for your next party or potluck.","ingredients":[{"name":null,"items":["8 ounces cream cheese, low-fat (garlic and herb)","6 flour tortillas (8 inch)","6 slices turkey (low sodium)","3 Roma tomatoes (medium, chopped)","3 cups baby spinach leaves"]}],"directions":[{"name":null,"steps":["Place tortillas on microwaveable plate or paper towel; microwave uncovered on HIGH 10 to 15 seconds to soften.","Spread about 2 tablespoons cream cheese over each tortilla. Top with a slice of turkey, chopped tomatoes, and spinach.","Roll up lightly; then wrap in plastic wrap. Refrigerate 2 to 3 hours to blend flavors.","Cut each roll into eight 1-inch slices. Arrange with cut side down on serving plate."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3 pinwheels (59g)","calories":"94.77 kcal","carbohydrateContent":"10.29 g","cholesterolContent":"12.80 mg","fiberContent":"0.80 g","proteinContent":"4.28 g","sodiumContent":"244.79 mg","sugarContent":"1.86 g","fatContent":"3.98 g","saturatedFatContent":"1.88 g"},"notes":null,"contributor":"Ohio State University Cooperative Extension"},
{"slug":"turkey-potato-salad","source_url":"https://www.myplate.gov/recipes/turkey-potato-salad","name":"Turkey Potato Salad","description":"Green pepper, onions, and celery give this salad a delicious crunch. Serve chilled on a bed of lettuce or whole grain bread.","ingredients":[{"name":null,"items":["6 ounces turkey (cooked and diced)","1/4 cup celery (chopped)","1 cup potato (cooked, peeled, and diced)","1 tablespoon onion, chopped","1/4 cup green pepper (chopped)","2 tablespoons mayonnaise","1/4 teaspoon prepared mustard","1/8 teaspoon salt"]}],"directions":[{"name":null,"steps":["Mix turkey, celery, potato, onion, and green pepper.","Mix mayonnaise, mustard and salt. Stir lightly into turkey mixture.","Chill."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe (173g)","calories":"248.65 kcal","carbohydrateContent":"15.47 g","cholesterolContent":"69.08 mg","fiberContent":"2.01 g","proteinContent":"26.75 g","sodiumContent":"438.39 mg","sugarContent":"2.37 g","fatContent":"8.60 g","saturatedFatContent":"1.59 g"},"notes":null,"contributor":"University of Maine Cooperative Extension"},
{"slug":"turkey-salad-orange-vinaigrette","source_url":"https://www.myplate.gov/recipes/turkey-salad-orange-vinaigrette","name":"Turkey Salad with Orange Vinaigrette","description":"Fresh orange juice and Dijon mustard give this vinaigrette a bright and zesty flavor to top this turkey and orange salad.","ingredients":[{"name":"Dressing","items":["1/4 cup orange juice","2 tablespoons white wine vinegar","2 tablespoons onion (finely chopped)","1/4 teaspoon salt","1 dash black pepper","1 tablespoon vegetable oil (or oil of your choice)","2 teaspoons Dijon mustard"]},{"name":"Salad","items":["4 cups salad greens (torn)","2 cups cooked turkey breast","1 cup mandarin orange sections (drained)","1/2 cup celery (chopped)","other vegetables as desired"]}],"directions":[{"name":null,"steps":["In a jar with tight-fitting lid, combine all vinaigrette ingredients; shake well. If you don''t have a container with a tight-fitting lid, place ingredients in a small mixing bowl and mix together with a whisk.","In large bowl, combine all salad ingredients; toss gently.","Serve with vinaigrette."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cups salad","1/4 of recipe (251g)"],"calories":"169.37 kcal","carbohydrateContent":"9.42 g","cholesterolContent":"51.73 mg","fiberContent":"1.33 g","proteinContent":"20.93 g","sodiumContent":"304.38 mg","sugarContent":"7.56 g","fatContent":"5.19 g","saturatedFatContent":"0.91 g"},"notes":"You can substitute 1 1/2 teaspoons dried chopped onion for the chopped fresh onion or as recommended on the dried onion container. Prepare the dressing at least 10 minutes before you need it to allow the dried onion to re-hydrate from the fluids in the dressing.\nUse white meat leftovers if you''ve prepared a whole turkey and not just the breast portion.\nAnother way to add crunch to your salad would be to use 4 tablespoons chopped walnuts instead of the celery.","contributor":"Cook it QUICK!\nUniversity of Nebraska Cooperative Extension"},
{"slug":"turkey-stew","source_url":"https://www.myplate.gov/recipes/turkey-stew","name":"Turkey Stew","description":"This hearty stew of turkey, potatoes, and vegetables will warm up a cold winter night. You can replace the cooked turkey with cooked chicken.","ingredients":[{"name":null,"items":["2 teaspoons vegetable oil (or oil of your choice)","1/2 cup onion (chopped)","1 clove garlic (finely chopped, or 1/2 teaspoon garlic powder)","4 carrots (chopped)","2 celery stalks (chopped)","2 medium potatoes (chopped)","1 can diced tomatoes (14.5 oz)","2 cups water","2 cups turkey (cooked, chopped or chicken)","salt and pepper (optional, to taste)","Italian seasoning ( or fresh herbs as desired)"]}],"directions":[{"name":null,"steps":["Heat oil in medium saucepan. Add onion, garlic, carrots, and celery and stir for 2 minutes.","Add potatoes, tomatoes, and water to pan. Bring to a boil, then lower heat and simmer 30 minutes or until vegetables are tender. Add turkey and cook another five minutes or until heated.","Season to taste before serving."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"248.35 kcal","carbohydrateContent":"29.96 g","cholesterolContent":"51.73 mg","fiberContent":"6.15 g","proteinContent":"23.52 g","sodiumContent":"286.84 mg","sugarContent":"7.49 g","fatContent":"4.30 g","saturatedFatContent":"0.81 g"},"notes":null,"contributor":"Montana State University Extension Service"},
{"slug":"turkey-stuffed-cabbage","source_url":"https://www.myplate.gov/recipes/turkey-stuffed-cabbage","name":"Turkey Stuffed Cabbage","description":"Turkey and ground beef stuffed cabbage leaves are cooked and topped with a sweet and savory sauce of veggies, lemon juice, and brown sugar.","ingredients":[{"name":"Cabbages","items":["1 head of cabbage","1/2 pound ground beef (90% lean)","1/2 pound ground turkey (85% lean)","1 small onion (minced)","1 slice whole wheat bread (stale, crumbled)","1 tablespoon lemon juice","1 cup water","1/8 teaspoon black pepper","1 can diced tomatoes, low-sodium (14.5 oz)","1 onion (small, sliced)","1 cup water","1 carrot (medium, sliced)"]},{"name":"Final Sauce","items":["1 tablespoon lemon juice","2 tablespoons brown sugar","1 tablespoon corn starch"]}],"directions":[{"name":null,"steps":["Rinse and core cabbage. Carefully remove 10 outer leaves, place in saucepan, and cover with boiling water. Simmer 5 minutes. Remove and drain cooked cabbage leaves on paper towels.","Shred 1/2 cup of raw cabbage and set aside.","Brown ground beef and turkey and minced onion in skillet. Drain fat.","Place cooked and drained meat mixture, bread crumbs, water, and pepper into mixing bowl.","Drain tomatoes, reserving liquid, and add 1/2 cup of tomato juice from can to meat mixture. Mix well; then place 1/4 cup of filling on each parboiled, drained cabbage leaf. Place folded side down in large skillet.","In skillet top cabbages with tomatoes, sliced onion, water, shredded cabbage, and carrot. Cover and simmer about 1 hour (or until cabbage is tender), basting occasionally.","Remove cabbage rolls to serving platter; keep warm.","Mix lemon juice, brown sugar, and cornstarch together in small bowl. Add to vegetables and liquid in skillet, and cook, stirring occasionally, until thickened and clear. Serve over cabbage rolls."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 rolls each (454g)","calories":"279.05 kcal","carbohydrateContent":"30.31 g","cholesterolContent":"59.95 mg","fiberContent":"7.91 g","proteinContent":"20.51 g","sodiumContent":"140.40 mg","sugarContent":"16.67 g","fatContent":"9.61 g","saturatedFatContent":"2.94 g"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"turkey-tostadas","source_url":"https://www.myplate.gov/recipes/turkey-tostadas","name":"Turkey Tostadas","description":"These tostadas are layered with refried beans, turkey, and cheese to create a delicious and easy dinner. Top with tomatoes, lettuce, and onions to increase y...","ingredients":[{"name":null,"items":["2 cups cooked turkey (cut into bite-sized pieces, or 2 cups ground turkey, browned in a skillet and drained)","2 tablespoons taco seasoning","1 1/2 cups water","4 corn tortillas","1/4 cup refried beans (low-fat or fat-free)","1/4 cup cheddar or Monterey Jack cheese (shredded, low-fat)","1/2 cup tomatoes (chopped)","1/2 cup lettuce (shredded)","2 tablespoons onion (chopped)","8 tablespoons taco sauce (1/2 cup)","plain yogurt (low-fat or fat-free, optional)","guacamole (or mashed avacado, optional)"]}],"directions":[{"name":null,"steps":["Preheat oven to 375° F.","Wash and prepare vegetables.","In a large skillet over medium heat, combine turkey, taco seasoning, and water.","Bring mixture to boil, reduce heat and simmer 5 minutes, stirring occasionally.","Place tortillas on a baking sheet. Bake at 375° for 4 to 7 minutes or until tortillas are crispy.","Spread tortillas with a tablespoon of beans. Top with 1/4 meat mixture and cheese.","Return tortillas to oven to cook for 2 to 3 minutes or until cheese is melted.","Top with tomatoes, lettuce, onions, and taco sauce. Garnish with yogurt and guacamole, if desired."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 tostada (276g)","calories":"213.47 kcal","carbohydrateContent":"18.74 g","cholesterolContent":"57.10 mg","fiberContent":"3.55 g","proteinContent":"24.74 g","sodiumContent":"701.59 mg","sugarContent":"1.75 g","fatContent":"4.00 g","saturatedFatContent":"1.47 g"},"notes":"Recipe analysis includes light meat turkey without skin.","contributor":"University of Massachusetts Extension\nNutrition Education Program"},
{"slug":"turnip-pancakes","source_url":"https://www.myplate.gov/recipes/turnip-pancakes","name":"Turnip Pancakes","description":"A great way to try turnips. Full of vegetables and packed with flavor, turnip pancakes will satisfy audiences of all ages.","ingredients":[{"name":"Pancakes","items":["1 cup all-purpose flour","1/2 teaspoon black pepper","1 egg","2 cloves garlic, minced","1 tablespoon low-sodium soy sauce","3/4 cup water","2 cups grated turnip","1 cup grated carrot","1/2 cup thinly sliced green onion","2 tablespoons vegetable oil (for cooking)"]},{"name":"Dipping Sauce","items":["2 tablespoons low-sodium soy sauce","2 tablespoons rice vinegar","2 teaspoons packed brown sugar","2 tablespoons thinly sliced green onion"]}],"directions":[{"name":null,"steps":["In a large bowl, mix flour, pepper, egg, garlic, soy sauce, and water in a bowl until smooth.","Stir in the turnip, carrot, and green onion","Heat half of oil in a large skillet over medium heat (350 °F in an electric skillet). Pour about 1/4 cup of batter for each pancake into skillet. Flatten with a fork into a 3-inch circle.","Cook until edges look dry and bottom is golden, about 3 to 4 minutes. Turn once. Cook until bottom is golden and crispy. Repeat with remaining batter, adding remaining oil as needed. Pancakes will be moist in the center.","Combine dipping sauce ingredients in a small bowl. Serve with warm pancakes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 pancakes","calories":"163.42 kcal","carbohydrateContent":"23.06 g","cholesterolContent":"34.25 mg","fiberContent":"2.32 g","proteinContent":"4.66 g","sodiumContent":"322.69 mg","sugarContent":"4.01 g","fatContent":"5.83 g","saturatedFatContent":"0.96 g"},"notes":"No rice vinegar? Try apple cider vinegar instead.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"turtle-apple","source_url":"https://www.myplate.gov/recipes/turtle-apple","name":"Turtle Apple","description":"This simple and fun snack is created using only fresh apples and canned oranges.","ingredients":[{"name":null,"items":["1 apple (small or medium)","10 slices of mandarin oranges, drained"]}],"directions":[{"name":null,"steps":["Wash apple. Cut in half (see notes).","Place apple half in center of small plate.","Put mandarin oranges next to apple for arms, legs, and head.","Enjoy your Turtle Apple."]}],"yield":"2 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"75.80 kcal","carbohydrateContent":"18.63 g","cholesterolContent":"0.00 mg","fiberContent":"2.38 g","proteinContent":"0.42 g","sodiumContent":"2.00 mg","sugarContent":"15.65 g","fatContent":"0.16 g","saturatedFatContent":"0.03 g"},"notes":"Adults: Make sure you use sharp knife to cut apple in half, remove core, and discard. Then, using a can opener, open mandarin oranges, and discard sharp-edged lid.","contributor":"Chickasaw Nation Get Fresh! Nutrition Education Program"},
{"slug":"tuscan-potato-skillet","source_url":"https://www.myplate.gov/recipes/tuscan-potato-skillet","name":"Tuscan Potato Skillet","description":"Lemon zest, garlic, and rosemary add a delightful Tuscan twist to this green bean, potato, and chicken skillet. The best part? Only having to use one pan to ...","ingredients":[{"name":null,"items":["10 petite red potatoes","1/2 teaspoon salt","1/4 teaspoon pepper","1 pound chicken pieces","2 tablespoons extra virgin olive, divided","1 tablespoon chopped fresh rosemary (or 1 teaspoon dried rosemary)","4 cloves garlic, minced","2 1/2 cups frozen green beans, thawed (12 oz. bag)","1 lemon, zested and juiced"]}],"directions":[{"name":null,"steps":["Cut each potato into 4 wedges. Place in a large microwave-safe bowl and season with salt and pepper. Microwave on HIGH for 4 minutes. Stir and microwave for 4 minutes more.","While potatoes are cooking, cut each chicken tenderloin into 4 equal pieces.","Heat 1 tablespoon oil in a large skillet over medium-high heat. Add chicken and cook for 5 minutes or until nicely browned, stirring frequently.","Add remaining oil and potatoes; cook and stir for 5 minutes more to brown potatoes and fully cook chicken.","Stir in rosemary, garlic, green beans, lemon zest and juice. Cook for a few minutes more to heat through. Season to taste with salt and pepper."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"330.73 kcal","carbohydrateContent":"32.71 g","cholesterolContent":"75.06 mg","fiberContent":"5.16 g","proteinContent":"27.67 g","sodiumContent":"349.38 mg","sugarContent":"3.81 g","fatContent":"10.11 g","saturatedFatContent":"1.78 g"},"notes":"Use whatever type of potatoes you have on hand, are on sale, or offer the best price.","contributor":"Meeting Your MyPlate Goals on a Budget\nMyPlate National Strategic Partners Toolkit"},
{"slug":"two-bean-chili","source_url":"https://www.myplate.gov/recipes/two-bean-chili","name":"Two Bean Chili","description":"This no-fuss chili is a great way to use ground beef and beans to make a tasty main dish. Chili can be served by itself, with crackers, cooked rice, or baked...","ingredients":[{"name":null,"items":["1/2 pound ground beef","1/2 can (about 8 ounces) low-sodium kidney beans, drained","1/2 can (about 8 ounces) low-sodium vegetarian beans","1/2 cup onion, diced","1 teaspoon chili powder","2 1/2 cups low-sodium tomato juice","1/4 teaspoon pepper"]}],"directions":[{"name":null,"steps":["In a medium-sized pot, brown ground beef over medium to high heat for 8 to 10 minutes. Drain fat.","Add kidney beans, vegetarian beans, onions, chili powder, tomato juice, and pepper.","Cook over low heat for about 40 minutes. Serve hot."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup serving","calories":"218.61 kcal","carbohydrateContent":"25.94 g","cholesterolContent":"32.86 mg","fiberContent":"7.81 g","proteinContent":"17.59 g","sodiumContent":"277.07 mg","sugarContent":"6.02 g","fatContent":"5.10 g","saturatedFatContent":"1.81 g"},"notes":"Tip for cooking with ground beef: The recommended safe minimum internal temperature for ground beef is 160 °F, as measured with a food thermometer.\nTip: USDA Foods macaroni products such as spaghetti, rotini, and macaroni are great additions to chili.","contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"vegetable-and-rice-skillet-meal","source_url":"https://www.myplate.gov/recipes/vegetable-and-rice-skillet-meal","name":"Vegetable and Rice Skillet Meal","description":"An easy and delicious one-pot dish that makes plenty of leftovers to savor!","ingredients":[{"name":null,"items":["2 teaspoons vegetable oil (or cooking oil of your choice)","1 onion (chopped)","1 teaspoon ground ginger","1/2 teaspoon turmeric","1/2 teaspoon cumin","2 cups mixed vegetables (chopped cauliflower, peppers, carrots, or peas)","1 large baking potato (diced)","1 cup white rice (uncooked)","2 1/2 cups water","1 can low-sodium kidney beans (15.5 ounces, drained, rinsed)","salt (1/2 teaspoon, optional)"]}],"directions":[{"name":null,"steps":["Heat oil in a large skillet over medium heat.","Add onion, ginger, turmeric, and cumin, stir while cooking for 1 minute.","Add remaining ingredients. Bring to a boil, cover, and reduce heat.","Simmer 20 to 25 minutes. Serve hot.","Refrigerate leftovers with in 2 to 3 hours."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup (168g)","calories":"176.85 kcal","carbohydrateContent":"35.25 g","cholesterolContent":"0.00 mg","fiberContent":"5.13 g","proteinContent":"5.82 g","sodiumContent":"71.18 mg","sugarContent":"2.96 g","fatContent":"1.40 g","saturatedFatContent":"0.27 g"},"notes":null,"contributor":"Original Recipe Name - Indian Vegetables and Rice Skillet Meal\nHealthy Recipes\nOregon State University Cooperative Extension Service"},
{"slug":"vegetable-and-turkey-stir-fry","source_url":"https://www.myplate.gov/recipes/vegetable-and-turkey-stir-fry","name":"Vegetable and Turkey Stir Fry","description":"Cooked turkey combined with your favorite frozen veggies means you can throw this stir fry together quickly for a healthy weekday dinner.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","2 thin slices of ginger root, minced","1 garlic clove, peeled and minced","16 ounces cooked turkey, cut into 1/2 inch cubes","2 packages (10 ounces each) frozen vegetables, chopped (or fresh)","1/2 teaspoon salt","1/2 teaspoon sugar","water (if needed)"]},{"name":"Optional Gravy","items":["1 tablespoon cornstarch","2 teaspoons low-sodium soy sauce","1/2 cup low-sodium chicken stock"]}],"directions":[{"name":null,"steps":["Heat oil in a large frying pan on high heat.","Add ginger, garlic, turkey, vegetables, and salt. Stir fry about 1 minute to coat with oil.","Adjust heat to prevent scorching. Add sugar. If vegetables are tender, stop cooking at this time.","If the vegetables are firm, add 1 to 2 tablespoons of water, cover and cook for 2 minutes or until tender.","Serve at once, or if you wish to add a gravy, mix the gravy ingredients well, pour over vegetables and turkey, cook for 30 seconds."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"300.86 kcal","carbohydrateContent":"21.75 g","cholesterolContent":"86.91 mg","fiberContent":"6.33 g","proteinContent":"37.90 g","sodiumContent":"616.04 mg","sugarContent":"5.02 g","fatContent":"6.27 g","saturatedFatContent":"1.25 g"},"notes":null,"contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"vegetable-cheese-soup","source_url":"https://www.myplate.gov/recipes/vegetable-cheese-soup","name":"Vegetable Cheese Soup","description":"Swiss cheese, vegetables, and curry powder make this thick and creamy soup a filling meal on a cold night this winter. Serve with whole wheat toast on the si...","ingredients":[{"name":null,"items":["3 cups water, divided","3 cups mixed vegetables, frozen or fresh, chopped","1/4 cup onions, chopped","1 teaspoon salt (optional)","1/2 teaspoon curry powder (optional)","1 cup non-fat dry milk","1 1/2 tablespoons cornstarch","1/2 cup Swiss cheese, cut into small pieces","green onions, optional"]}],"directions":[{"name":null,"steps":["Bring 2 cups water to a boil. Add vegetables, onions, salt, and curry powder, if using. Reduce heat, cover and cook until almost tender.","Mix remaining 1 cup water, dry milk, and cornstarch together in a small bowl. Add to partially cooked vegetables.","Cook over medium heat, stirring often, until thickened.","Add cheese and stir until melted. Add more water if too thick.","Top with green onions if desired."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"218.05 kcal","carbohydrateContent":"30.31 g","cholesterolContent":"15.96 mg","fiberContent":"6.16 g","proteinContent":"13.78 g","sodiumContent":"171.53 mg","sugarContent":"13.48 g","fatContent":"4.53 g","saturatedFatContent":"2.59 g"},"notes":"Store leftovers covered in the refrigerator.","contributor":"University of Nebraska at Lincoln\nNebraska Nutrition Education Program"},
{"slug":"vegetable-chili","source_url":"https://www.myplate.gov/recipes/vegetable-chili","name":"Vegetable Chili","description":"Chunks of zucchini, sweet potatoes, and frozen corn add a creative twist to this chili dish. Combined with canned beans and diced tomatoes this tasty one-pot...","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil","2 yellow onions, peeled and coarsely chopped","2 zucchinis, cubed","2 sweet potatoes, cubed","3 cloves garlic, minced","2 teaspoons ground cumin","2 tablespoons chili powder","2 teaspoons dried oregano","3 16-ounce cans low-sodium dark red kidney beans, drained and rinsed","2 14.5-ounce cans no salt added diced tomatoes","2 cups frozen corn"]}],"directions":[{"name":null,"steps":["Put the pot over medium heat and when it is hot, add the oil. Add the onions, zucchini, sweet potatoes, garlic, and spices and cook, stirring from time to time, for 20 minutes.","Add the kidney beans and tomatoes. Stir and cook, covered, until the squash is tender, about 30 minutes.","Add the corn and cook until warmed throughout.","Serve right away or transfer to a container once cooled. Refrigerate up to 5 days."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 cups","calories":"435.33 kcal","carbohydrateContent":"77.18 g","cholesterolContent":"0.00 mg","fiberContent":"23.40 g","proteinContent":"19.85 g","sodiumContent":"440.51 mg","sugarContent":"18.59 g","fatContent":"8.48 g","saturatedFatContent":"1.44 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"vegetable-dipping-sauce","source_url":"https://www.myplate.gov/recipes/vegetable-dipping-sauce","name":"Vegetable Dipping Sauce","description":"Honey and brown mustard are the secret ingredients in this dip, the perfect compliment for raw veggies. Whip this up today, and start snacking.","ingredients":[{"name":null,"items":["1/4 cup non-fat plain yogurt","1/4 cup light sour cream","2 teaspoons honey*","2 teaspoons spicy brown mustard"]}],"directions":[{"name":null,"steps":["Mix together all ingredients in a bowl.","Serve with your favorite vegetables."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"40.83 kcal","carbohydrateContent":"5.12 g","cholesterolContent":"5.56 mg","fiberContent":"0.11 g","proteinContent":"1.52 g","sodiumContent":"51.87 mg","sugarContent":"3.98 g","fatContent":"1.70 g","saturatedFatContent":"1.01 g"},"notes":"*Children under the age of one should not consume honey.\nServing suggestion:\nGood with carrot sticks, broccoli, cauliflower, tomatoes, or any of your favorite vegetables.","contributor":"University of Illinois Extension Service"},
{"slug":"vegetable-fried-rice","source_url":"https://www.myplate.gov/recipes/vegetable-fried-rice","name":"Vegetable Fried Rice","description":"This rice dish blends the flavors of soy sauce, pepper, and vegetables for a quick meal. It''s cooked in one pan so clean up is quick too.","ingredients":[{"name":null,"items":["2 cups cooked white rice","1/2 cup celery (chopped)","1/4 cup onion (chopped)","2 tablespoons vegetable oil (or cooking oil of choice)","1 package (10 ounces) frozen mixed vegetables","1 tablespoon low-sodium soy sauce","1 dash black pepper"]}],"directions":[{"name":null,"steps":["Make 2 cups of cooked white rice. Use the package directions to make the rice.","Chop 1/2 cup of celery and 1/4 cup of onion.","Heat the oil in a skillet or large frying pan.","Add the celery and onion. Stir fry for 2 minutes.","Add the vegetables to the pan. Keep stirring the vegetables until they are tender-crisp.","Add the cooked rice.","Sprinkle with soy sauce and pepper.","Stir fry for 2 minutes until the rice is heated and the flavors are blended."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup fried rice","1/4 of recipe"],"calories":"220.22 kcal","carbohydrateContent":"33.13 g","cholesterolContent":"0.00 mg","fiberContent":"3.89 g","proteinContent":"4.73 g","sodiumContent":"182.36 mg","sugarContent":"2.90 g","fatContent":"7.38 g","saturatedFatContent":"1.06 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"vegetable-medley-salsa-dip","source_url":"https://www.myplate.gov/recipes/vegetable-medley-salsa-dip","name":"Vegetable Medley with Salsa Dip","description":"Use this colorful veggie plate at your next party or gathering.","ingredients":[{"name":null,"items":["2 medium carrots, cut into 3-inch sticks","2 medium celery stalks, cut into 3-inch sticks","1 cup green bell pepper (or other color)","1 cup fat-free sour cream","1 cup fresh salsa (see recipe below)"]},{"name":"Fresh Salsa","items":["1 lime, juiced","2 medium tomatoes, chopped","1/2 medium onion, chopped","3 jalapeno chiles, finely chopped, seeded if desired","1/4 cup fresh cilantro, chopped","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Arrange vegetables on a platter.","In a small bowl, mix sour cream and salsa. Serve."]},{"name":"Fresh Salsa Preparation","steps":["In a medium bowl, mix lime juice, tomatoes, onions, jalapeño chiles, cilantro, and salt.","Store salsa in refrigerator for up to three days in a covered plastic or glass container."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 cup vegetables and 1/2 cup salsa dip","1/4 of recipe"],"calories":"103.54 kcal","carbohydrateContent":"22.70 g","cholesterolContent":"5.40 mg","fiberContent":"3.84 g","proteinContent":"3.92 g","sodiumContent":"539.81 mg","sugarContent":"7.54 g","fatContent":"0.52 g","saturatedFatContent":"0.09 g"},"notes":"Feel free to serve with whatever vegetables you have on hand. Could also be served with crackers.","contributor":"California 5 A Day, It’s So Easy\nContra Costa Health Services"},
{"slug":"vegetable-pizza","source_url":"https://www.myplate.gov/recipes/vegetable-pizza","name":"Vegetable Pizza","description":"Enjoy fresh, delicious pizza made at home. You can spice this up with red pepper flakes or garlic powder. Try with whatever vegetables you have on hand.","ingredients":[{"name":null,"items":["3/4 cup low-sodium pizza sauce","1 large (12-inch) Italian pizza shell","1 cup broccoli, chopped","1 cup carrots, shredded","1/2 cup green bell pepper, sliced (or red bell pepper)","5 ounces part-skim mozzarella cheese, shredded"]}],"directions":[{"name":null,"steps":["Preheat the oven to 450 degrees F.","Spoon pizza sauce on pizza shell.","Put pizza shell on a cookie sheet. Arrange vegetables over sauce. Sprinkle on the cheese.","Bake for 10 minutes.","When baked, cool pizza for 3 minutes before slicing. Cut into 8 wedges."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 slice","1/8 of recipe"],"calories":"159.77 kcal","carbohydrateContent":"17.48 g","cholesterolContent":"11.52 mg","fiberContent":"1.78 g","proteinContent":"8.12 g","sodiumContent":"340.53 mg","sugarContent":"2.89 g","fatContent":"6.59 g","saturatedFatContent":"2.41 g"},"notes":null,"contributor":"Adapted from Spunky Vegetable Pizza, California 5 A Day, It’s So Easy\nContra Costa Health Services"},
{"slug":"vegetable-rice-tomatoes","source_url":"https://www.myplate.gov/recipes/vegetable-rice-tomatoes","name":"Vegetable Rice with Tomatoes","description":"Rice, vegetables, and seasoning are a winning flavor combination in this tasty side dish.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of choice)","2 cups long-grain white rice, uncooked","3 cups low-sodium chicken broth","1 1/2 cups white onion, finely chopped","2 teaspoons garlic, minced","1 can (14.5 ounces) low-sodium Mexican or Italian style tomatoes","1/2 teaspoon salt","green bell pepper, optional (if using: seeded and chopped)"]}],"directions":[{"name":null,"steps":["Heat oil in medium-sized saucepan over medium heat.","Cook the rice until just golden brown, about 5 minutes.","Add 1/2 cup of chicken broth if moisture is needed.","Add onions and garlic and cook for a minute or two.","Stir in the tomatoes and their juice, the rest of the chicken broth, salt, and bell pepper (if using). Bring to a boil.","Reduce heat to low. Cover and simmer for about 20 to 25 minutes, or until the broth is absorbed."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/8 of recipe","calories":"252.86 kcal","carbohydrateContent":"46.17 g","cholesterolContent":"0.00 mg","fiberContent":"2.10 g","proteinContent":"6.45 g","sodiumContent":"182.73 mg","sugarContent":"2.78 g","fatContent":"4.61 g","saturatedFatContent":"0.79 g"},"notes":null,"contributor":"Celebrate Health with a Lowfat Fiesta\nCalifornia Department of Health Services\nCalifornia Project LEAN"},
{"slug":"vegetable-salad","source_url":"https://www.myplate.gov/recipes/vegetable-salad","name":"Vegetable Salad","description":"This tasty, marinaded veggie salad uses canned veggies and can be enjoyed at any time of the year. Use fresh vegetables if you have them on hand.","ingredients":[{"name":null,"items":["1 can (15 ounces) whole kernel corn, drained","1 can (14.5 ounces) low-sodium carrots, drained","1 can (15 ounces) low-sodium chickpeas, drained (garbanzo beans)","1 can (14.5 ounces) low-sodium diced tomatoes (reserve 1/3 cup liquid)","1 cup red pepper, chopped","1 tablespoon onion, finely chopped","1/4 cup vegetable oil (or cooking oil of choice)","1/3 cup vinegar","1/8 teaspoon black pepper","2 tablespoons honey"]}],"directions":[{"name":null,"steps":["Drain corn, carrots, and chickpeas. Throw away liquid. Rinse vegetables and drain again.","Drain tomatoes but save 1/3 cup of the liquid.","Mix corn, carrots, chickpeas, tomatoes, onion, and red pepper in a large bowl.","Mix together all other ingredients in a separate bowl.","Pour over vegetables.","Cover and set aside for at least 3 hours in the refrigerator."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup salad","1/12 of recipe"],"calories":"126.87 kcal","carbohydrateContent":"16.76 g","cholesterolContent":"0.00 mg","fiberContent":"3.89 g","proteinContent":"3.24 g","sodiumContent":"138.24 mg","sugarContent":"7.60 g","fatContent":"5.99 g","saturatedFatContent":"0.83 g"},"notes":"Feel free to add other vegetables like green beans to the recipe. Instead of canned vegetables you could also use a 16 ounce bag of frozen vegetables. However, analysis was done with ingredients as specified in the recipe.","contributor":"University of Wyoming Cooperative Extension"},
{"slug":"vegetable-snake","source_url":"https://www.myplate.gov/recipes/vegetable-snake","name":"Vegetable Snake","description":"Get creative with your fresh veggie snacks. This recipe calls for cucumber and tomatoes, but you can use your favorite veggies for this snack.","ingredients":[{"name":null,"items":["1 medium cucumber","1 small tomato (or 2 grape tomatoes)"]}],"directions":[{"name":null,"steps":["Wash ingredients.","Put cucumber slices (see notes) on a small plate to form a snake.","Add 2 slices of tomatoes for eyes.","Enjoy your Vegetable Snake."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 of recipe","calories":"27.50 kcal","carbohydrateContent":"6.16 g","cholesterolContent":"0.00 mg","fiberContent":"1.25 g","proteinContent":"1.16 g","sodiumContent":"4.50 mg","sugarContent":"3.31 g","fatContent":"0.30 g","saturatedFatContent":"0.06 g"},"notes":"Adults: Use a sharp knife to slice the cucumber and tomato into thin slices crosswise.","contributor":"Chickasaw Nation Get Fresh! Nutrition Education Program"},
{"slug":"vegetable-soup-chicken","source_url":"https://www.myplate.gov/recipes/vegetable-soup-chicken","name":"Vegetable Soup with Chicken","description":"This soup can be prepared quickly in one pot for lunch or dinner.","ingredients":[{"name":null,"items":["1 can chicken (about 12 ounces)","3 cups water","3 ears corn (or 1 can low-sodium whole kernel corn)","1 can low-sodium peas (about 15 ounces)","1 pound fresh carrots, peeled and diced (or 1 can low-sodium carrots, about 15 ounces)","2 pounds potatoes, peeled and diced (or 2 cans low-sodium sliced potatoes, about 15 ounces each)"]}],"directions":[{"name":null,"steps":["In a large pot, heat the chicken and water over medium to high heat until hot.","Cut the kernels off the ears of corn.","Add the corn kernels and all other ingredients to the pot and boil for 10 seconds.","Lower the heat and simmer for about 30 minutes."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cups","calories":"341.84 kcal","carbohydrateContent":"51.83 g","cholesterolContent":"28.35 mg","fiberContent":"8.70 g","proteinContent":"22.65 g","sodiumContent":"356.47 mg","sugarContent":"11.04 g","fatContent":"5.91 g","saturatedFatContent":"1.55 g"},"notes":"Tip for cooking chicken: The recommended safe minimum internal temperature for chicken is 165 degrees F, as measured with a food thermometer.","contributor":"A Harvest of Recipes with USDA Foods\nAdapted from a recipe by Natalie Gibson, San Pasqual Reservation"},
{"slug":"vegetable-stew","source_url":"https://www.myplate.gov/recipes/vegetable-stew","name":"Vegetable Stew","description":"The green chili pepper adds delicious spice and flavor to this potato, corn, and summer squash stew.","ingredients":[{"name":null,"items":["3 cups water","1 cube low-sodium vegetable bouillon","2 cups white potatoes, cut into 2-inch strips","2 cups carrots, sliced","4 cups summer squash, cut into 1-inch chunks","1 cup summer squash, cut into 4 chunks","1 3/4 cups canned low-sodium sweet corn, rinsed and drained (or 2 ears of fresh corn, cut off the cob)","1 teaspoon thyme","2 garlic cloves, minced","1 medium green onion, chopped","1/2 small green chili pepper, chopped","1 cup onion, coarsely chopped","1 cup tomatoes, diced"]}],"directions":[{"name":null,"steps":["Put water and bouillon in large pot and bring to a boil.","Add potatoes and carrots and simmer for 5 minutes.","Add remaining ingredients, except for tomatoes, and continue cooking for 15 minutes over medium heat.","Remove 4 chunks of squash and purée in blender.","Return puréed mixture to pot and let cook for 10 minutes more.","Add tomatoes and cook for another 5 minutes.","Remove from heat and let sit for 10 minutes to allow stew to thicken."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup","calories":"92.28 kcal","carbohydrateContent":"20.40 g","cholesterolContent":"0.06 mg","fiberContent":"3.46 g","proteinContent":"3.14 g","sodiumContent":"42.91 mg","sugarContent":"6.67 g","fatContent":"0.74 g","saturatedFatContent":"0.14 g"},"notes":null,"contributor":"Heart Healthy Home Cooking: African American Style\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"vegetable-stroganoff","source_url":"https://www.myplate.gov/recipes/vegetable-stroganoff","name":"Vegetable Stroganoff","description":"This stroganoff has onion, garlic, carrots, zucchini, red bell pepper, and basil combined with a creamy tomato paste and yogurt sauce. Mixed with shaped past...","ingredients":[{"name":null,"items":["1/2 pound medium shaped whole wheat pasta (cooked)","1 tablespoon vegetable oil","1 red onion","2 cloves garlic, minced","2 carrots, diced","1 medium zucchini, diced","1 red bell pepper, chopped","1 tablespoon dried basil","1 14.5-ounce can diced tomatoes, no salt added (including the liquid)","2 tablespoons tomato paste, no salt added","1/2 cup plain low-fat yogurt (or light or heavy cream)"]}],"directions":[{"name":null,"steps":["To cook the pasta, fill a pot halfway with water. Bring it to a boil over high heat. When it has boiled, add the pasta and cook until just tender, about 12 minutes. Drain the pasta and set aside.","While the pasta is cooking, cook the stroganoff: Put a skillet over medium heat and when it is hot, add the oil. Add the onion, garlic, carrots, zucchini, peppers, and dried basil and cook until soft and golden, about 20 minutes.","Add the tomatoes and cook until the sauce comes together, about 20 minutes.","Put the yogurt and tomato paste in the bowl, stirring until smooth.","Turn the heat off and move the vegetables in the skillet to one side. Gradually add the tomato paste mixture to the other side of the skillet, stirring all the while. Turn the heat to low and cook about 5 minutes, until heated through.","Add the cooked pasta and stir until mixed."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/4 cup serving","calories":"359.96 kcal","carbohydrateContent":"66.11 g","cholesterolContent":"1.84 mg","fiberContent":"11.29 g","proteinContent":"14.16 g","sodiumContent":"68.51 mg","sugarContent":"12.47 g","fatContent":"7.36 g","saturatedFatContent":"1.31 g"},"notes":null,"contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"vegetable-tacos","source_url":"https://www.myplate.gov/recipes/vegetable-tacos","name":"Vegetable Tacos","description":"These vegetable filled corn tortilla tacos get a kick from diced jalapeno peppers and garlic. Serve these as a side dish or enjoy as a snack.","ingredients":[{"name":null,"items":["1/2 medium onion","1 clove garlic","1 tablespoon jalapeno pepper","1 teaspoon cumin","1/2 teaspoon table salt","1/2 teaspoon black pepper","1/2 medium red pepper","1 cup mushrooms","4 (6-inch) corn tortilla","1 plum tomato, chopped","1 tablespoon cilantro, chopped"]}],"directions":[{"name":null,"steps":["Sauté onion, garlic and jalapeno, add cumin, salt, and black pepper. When everything is soft, add red pepper and mushrooms. Sauté for 2 more minutes.","Serve over tortilla and garnish with cut tomatoes and cilantro or cilantro sauce."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 taco","calories":"85.58 kcal","carbohydrateContent":"17.33 g","cholesterolContent":"0.00 mg","fiberContent":"2.81 g","proteinContent":"2.75 g","sodiumContent":"311.81 mg","sugarContent":"2.51 g","fatContent":"1.12 g","saturatedFatContent":"0.17 g"},"notes":null,"contributor":"Adapted from \"Delicious Tacos\"\nMake Every Day A Healthy Snack Day\nAlameda County Public Health Department"},
{"slug":"vegetarian-chili","source_url":"https://www.myplate.gov/recipes/vegetarian-chili","name":"Vegetarian Chili","description":"This delicious chili packed full of veggies, beans, and spices is fast enough for a weeknight dinner. Top with cilantro for a boost of flavor.","ingredients":[{"name":null,"items":["2 tablespoons vegetable oil (or cooking oil of choice)","2 large onions, cut into 1/4-inch pieces","1 medium green bell pepper, cut into 1/4-inch pieces","3 garlic cloves, chopped","2 jalapeno chilis, diced","1 tablespoon chili powder","1 tablespoon ground cumin","1 cup cilantro, chopped, divided","salt and pepper (to taste, optional)","2 cans (14.5 ounces each) low-sodium whole tomatoes, cut into 1/4-inch pieces (or 8 medium fresh tomatoes)","2 medium zucchini, cut into 1/4-inch pieces","2 medium summer squash, cut in to 1/4-inch pieces","1 can (15.5 ounces) low-sodium kidney beans, rinsed"]}],"directions":[{"name":null,"steps":["Add oil to a large pot and sauté onions, bell pepper, garlic, and jalapeno over medium-high heat for about 5 minutes, stirring often.","Add chili powder, cumin, half of the chopped cilantro, salt, and pepper, and continue cooking for another 3 minutes, stirring occasionally.","Add the tomatoes, zucchini, and squash. Bring mixture to a simmer.","Simmer for 15 minutes, stirring occasionally.","Add beans, and continue to simmer for another 5 minutes.","Serve the mixture hot. Put remaining cilantro on top."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"276.38 kcal","carbohydrateContent":"42.17 g","cholesterolContent":"0.00 mg","fiberContent":"14.52 g","proteinContent":"11.51 g","sodiumContent":"225.45 mg","sugarContent":"17.07 g","fatContent":"9.39 g","saturatedFatContent":"1.45 g"},"notes":null,"contributor":"Veggin’ Out Recipe Book\nJohnson and Wales University and Rhode Island Department of Health WIC Program"},
{"slug":"vegetarian-collard-greens","source_url":"https://www.myplate.gov/recipes/vegetarian-collard-greens","name":"Vegetarian Collard Greens","description":"Want to add more leafy greens to your diet but aren’t sure how to start? Check out this recipe for collard greens. A healthy and tasty side dish to accompa...","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of choice)","1 tablespoon butter","1/2 medium onion, chopped","1/2 teaspoon red pepper flakes (increase to 1 teaspoon if you like food spicy)","1/8 teaspoon garlic powder","2 1/2 cups collard greens, stems removed and chopped*","2 cups low-sodium vegetable broth","2 medium tomatoes, seeds removed and chopped**","salt and black pepper (to taste)"]}],"directions":[{"name":null,"steps":["Wash all vegetables,* and remove seeds from the tomatoes.**","Collect, chop, and measure all ingredients before starting to prepare the recipe.","Heat the oil and butter in a large pot over medium heat.","Add the onion, and cook for about 2 minutes until slightly soft.","Add the red pepper flakes and garlic, and cook for 1 minute. Add the chopped collard greens, and cook for another minute.","Add the broth, cover, and bring to a simmer. Cook for about 40 minutes until the greens are tender.","Add tomatoes.","Taste, and add a small amount of salt and black pepper if desired.","Serve hot.","Refrigerate leftovers within 2 hours. Eat within 3 to 5 days."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 cup","calories":"57.34 kcal","carbohydrateContent":"4.34 g","cholesterolContent":"5.09 mg","fiberContent":"1.30 g","proteinContent":"1.07 g","sodiumContent":"46.25 mg","sugarContent":"1.80 g","fatContent":"4.42 g","saturatedFatContent":"1.54 g"},"notes":"* Preparing collard greens: First, remove any damaged outer leaves. Fill a large bowl with cold water, and dunk the greens. Swish them around for a few minutes to help loosen any dirt on the leaves. Pour out the dirty water and fill the bowl with clean water. Swish the leaves under the clean water again to remove any additional dirt. Continue this process until the water in the bowl remains clear. To cut collard greens, fold each leaf in half with the stem at the fold crease. Either cut or tear the stem off. Stack several leaves on top of each other and roll the leaves up. Cut the roll of leaves into 1-inch thick pieces.\n** Removing tomato seeds: Turn the tomato on its side so the stem faces to the right. Cut the tomato down the center and use a 1/4 teaspoon to spoon out the seeds.","contributor":"Eating Smart, Being Active\nColorado State University Extension"},
{"slug":"vegetarian-matzo-ball-soup","source_url":"https://www.myplate.gov/recipes/vegetarian-matzo-ball-soup","name":"Vegetarian Matzo Ball Soup","description":"This savory, vegetable matzo ball soup is a delicious and quick meal on a cold evening.","ingredients":[{"name":"Ingredients for Matzo Balls","items":["2 eggs, lightly beaten","2 tablespoons olive oil (or cooking oil of choice)","1/8 cup low-sodium vegetable broth","1/2 cup unsalted matzo meal","1 tablespoon fresh dill","salt (1/2 teaspoon, optional)"]},{"name":"Ingredients for Broth","items":["6 cups low-sodium vegetable broth","4 medium carrots, cut into 1/4-inch slices","2 medium onions, coarsely chopped","1 1/2 cups medium parsnips, sliced","3 tablespoons fresh dill","salt and pepper (to taste, optional)"]}],"directions":[{"name":"To Make Matzo Balls","steps":["Stir together eggs, oil, and vegetable stock in a small bowl. Add matzo meal, dill, and salt. Stir until evenly combined. Cover and refrigerate 15 minutes to 8 hours.","Bring large pot of water to a boil; add a dash of salt. Using oiled hands, form dough into 12 1-inch balls.","Drop the balls one at a time into the boiling water. Reduce heat and simmer for 30 minutes."]},{"name":"To Make Broth","steps":["While matzo balls are simmering, make soup by adding all broth ingredients and bringing to a boil.","Reduce heat and simmer for 20 minutes.","To serve, spoon 2 cooked matzo balls into a bowl and ladle 1 cup of soup over them."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 cooked matzo balls with 1 cup soup","1/6 of recipe"],"calories":"170.40 kcal","carbohydrateContent":"24.67 g","cholesterolContent":"68.50 mg","fiberContent":"3.54 g","proteinContent":"4.51 g","sodiumContent":"172.13 mg","sugarContent":"6.59 g","fatContent":"6.74 g","saturatedFatContent":"1.33 g"},"notes":"Recipe cost can be reduced by substituting dried dill for fresh dill.","contributor":"Boston University Sargent Choice Nutrition Center"},
{"slug":"vegetarian-spaghetti-sauce","source_url":"https://www.myplate.gov/recipes/vegetarian-spaghetti-sauce","name":"Vegetarian Spaghetti Sauce","description":"Combine oregano and basil with fresh and canned veggies to make your own spaghetti sauce, perfect for any pasta dish.","ingredients":[{"name":null,"items":["2 tablespoons olive oil (or cooking oil of choice)","2 medium onions, chopped","3 cloves garlic, chopped","1 1/4 cups zucchini, sliced","1 tablespoon dried oregano","1 tablespoon dried basil","1 can (8 ounces) low-sodium tomato sauce","1 can (6 ounces) low-sodium tomato paste","2 medium tomatoes, chopped","1 cup water"]}],"directions":[{"name":null,"steps":["In a medium skillet, heat oil. Cook onions, garlic, and zucchini in oil for 5 minutes on medium heat.","Add remaining ingredients and simmer covered for 45 minutes. Serve over pasta."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3/4 cup","calories":"110.83 kcal","carbohydrateContent":"15.61 g","cholesterolContent":"0.00 mg","fiberContent":"3.76 g","proteinContent":"3.16 g","sodiumContent":"30.68 mg","sugarContent":"8.45 g","fatContent":"5.15 g","saturatedFatContent":"0.85 g"},"notes":null,"contributor":"DASH Eating Plan: Lower Your Blood Pressure\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"vegetarian-stuffed-peppers","source_url":"https://www.myplate.gov/recipes/vegetarian-stuffed-peppers","name":"Vegetarian Stuffed Peppers","description":"Exploding with tomatoes and basil, these delicious stuffed peppers are a great side dish to any entrée.","ingredients":[{"name":null,"items":["4 medium red, yellow, or green bell peppers","2 cups cherry tomatoes","1 medium onion","1 cup fresh basil leaves","3 garlic cloves","2 teaspoons olive oil (or cooking oil of choice)","1/4 teaspoon salt","1/4 teaspoon black pepper"]}],"directions":[{"name":null,"steps":["Preheat oven to 425 degrees F. Lightly oil a large shallow baking pan.","Cut peppers in half lengthwise and remove seeds. Arrange peppers cut sides up in baking pan and lightly oil cut edges of stems.","Halve cherry tomatoes and chop onion and basil. Finely chop garlic.","In a bowl, toss tomatoes, onion, basil, garlic, and olive oil. Add salt and pepper to taste.","Spoon equal portions of mixture into peppers and roast in upper third of oven until peppers are tender, about 20 minutes."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 pepper half","calories":"43.41 kcal","carbohydrateContent":"7.57 g","cholesterolContent":"0.00 mg","fiberContent":"1.37 g","proteinContent":"1.27 g","sodiumContent":"80.24 mg","sugarContent":"4.29 g","fatContent":"1.37 g","saturatedFatContent":"0.22 g"},"notes":"Add any type of beans to add protein to this recipe.","contributor":"US Department of Health and Human Services\nCenters for Disease Control and Prevention (CDC)"},
{"slug":"veggie-bean-wrap","source_url":"https://www.myplate.gov/recipes/veggie-bean-wrap","name":"Veggie Bean Wrap","description":"These delicious wraps are packed full of flavor and fiber. Mango, cilantro, and avocado add a fresh and flavorful topping to these wraps.","ingredients":[{"name":null,"items":["2 medium green or red bell peppers, seeded and chopped","1 medium onion, peeled and sliced","1 can (15 ounces) low-sodium black beans, drained and rinsed","2 mangos, peeled and chopped","1 lime, juiced","1/2 cup fresh cilantro, chopped","1 avocado, peeled and diced","4 (10-inch) flour tortillas"]}],"directions":[{"name":null,"steps":["In a nonstick pan, sauté bell peppers and onion for 5 minutes over medium heat. Add beans, stir well. Reduce heat to low and simmer about 5 minutes.","In a small bowl, combine mangoes, lime juice, cilantro, and avocado. Set aside 1/2 of this mango mixture for topping.","Fill warmed tortillas with 1/4 bean mixture and 1/4 mango mixture.","Fold ends of the tortillas over. Roll up to make wraps. Top veggie bean wraps with remaining mango mixture."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 prepared wrap","1/4 of recipe"],"calories":"474.03 kcal","carbohydrateContent":"77.47 g","cholesterolContent":"0.00 mg","fiberContent":"19.91 g","proteinContent":"15.98 g","sodiumContent":"592.29 mg","sugarContent":"20.22 g","fatContent":"13.32 g","saturatedFatContent":"4.48 g"},"notes":null,"contributor":"Healthy Latino Recipes Made with Love\nCalifornia Department of Health Services\nCalifornia Latino 5-A-Day Campaign"},
{"slug":"veggie-burgers","source_url":"https://www.myplate.gov/recipes/veggie-burgers","name":"Veggie Burgers","description":"Vegetarian burgers can be made ahead of time and stored in the freezer. They can be served any time. To add some spice, top with salsa.","ingredients":[{"name":null,"items":["1 can (about 15 ounces) low-sodium whole kernel corn, finely chopped","1/2 cup cornmeal","1/2 cup onion, finely chopped","1/2 cup green pepper, finely chopped","1/2 cup cooked white rice","1/4 teaspoon chili powder","1/4 teaspoon salt","1/4 teaspoon black pepper","1 teaspoon cayenne or jalapeño chilies, seeds removed and finely chopped, (optional)","nonstick cooking spray","6 flour tortillas, 6-inch size"]}],"directions":[{"name":null,"steps":["In a large bowl, combine corn and cornmeal.","Add onions, green pepper, rice, chili powder, and pepper. If using cayenne and jalapeño chilies, add them too. Mix well.","Form the burger mixture into 6 equal patties about 1/2 inch thick, and refrigerate for 1 hour.","Preheat the oven to 350 °F.","Spray both sides of the patties with nonstick cooking spray.","In a large pan, brown both sides of the patties over medium to high heat for 5 to 8 minutes.","Bake the patties in the oven for 10 minutes.","Toast the flour tortillas in the oven for 8 minutes.","Place patty on half of tortilla and fold tortilla over to serve like a taco."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 patty","calories":"211.69 kcal","carbohydrateContent":"40.74 g","cholesterolContent":"0.00 mg","fiberContent":"3.68 g","proteinContent":"5.68 g","sodiumContent":"358.35 mg","sugarContent":"5.47 g","fatContent":"3.69 g","saturatedFatContent":"1.10 g"},"notes":null,"contributor":"A Harvest of Recipes with USDA Foods\nUSDA Food Distribution Program on Indian Reservations"},
{"slug":"veggie-chow-mein","source_url":"https://www.myplate.gov/recipes/veggie-chow-mein","name":"Veggie Chow Mein","description":"This noodle dish combines the crunch of fresh veggies with the flavors of onion, garlic, and soy sauce to create a delicious and easy stir fry. Make it a fam...","ingredients":[{"name":null,"items":["6 ounces spaghetti noodles (or thin flat egg noodles)","4 teaspoons oil","1 medium onion, finely chopped","2 garlic cloves, finely chopped","1 cup carrots, grated","2 teaspoons low-sodium chicken bouillon","1 teaspoon hot pepper sauce","1 cup broccoli, cut into small pieces","1 cup celery, chopped","1 cup green or red bell peppers, finely chopped","4 teaspoons reduced-sodium soy sauce"]}],"directions":[{"name":null,"steps":["Prepare noodles according to package directions. Drain and set aside.","Cook onion and garlic with oil in a large frying pan for 1 minute over medium/high heat.","Add carrot, chicken bouillon, and pepper sauce. Stir.","Add broccoli, celery, and bell pepper and continue to stir.","Reduce heat to low and add noodles and soy sauce. Mix well over low heat for 3 to 5 minutes.","Add salt and pepper to taste."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"195.14 kcal","carbohydrateContent":"33.07 g","cholesterolContent":"0.11 mg","fiberContent":"3.45 g","proteinContent":"6.39 g","sodiumContent":"180.31 mg","sugarContent":"3.81 g","fatContent":"4.20 g","saturatedFatContent":"0.64 g"},"notes":"Add other vegetables as desired. Top with chives.","contributor":"University of Illinois Extension Service"},
{"slug":"veggie-dip","source_url":"https://www.myplate.gov/recipes/veggie-dip","name":"Veggie Dip","description":"Cottage cheese is the key to this easy veggie dip. Try with different spices to suit your taste.","ingredients":[{"name":null,"items":["1 cup cottage cheese","1 tablespoon onion, chopped very fine","1/4 teaspoon salt","1/4 teaspoon garlic powder","2 teaspoons parsley flakes"]}],"directions":[{"name":null,"steps":["Measure cottage cheese and put in bowl or blender.","Beat with a fork or mixer, or in a blender, until cottage cheese is smooth.","Add the other ingredients. Stir together.","Store the dip in the fridge for 1 to 2 hours to let the flavors blend."]}],"yield":"8 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons dip","1/8 of recipe"],"calories":"26.89 kcal","carbohydrateContent":"1.13 g","cholesterolContent":"4.46 mg","fiberContent":"0.06 g","proteinContent":"2.97 g","sodiumContent":"157.10 mg","sugarContent":"0.78 g","fatContent":"1.14 g","saturatedFatContent":"0.45 g"},"notes":"Serve with slices of raw vegetables such as carrots, celery, cucumbers, zucchini, broccoli, turnips, cauliflower, or green peppers.\nTry adding 1/4 teaspoon of black pepper and 1/2 teaspoon dried dill week for extra flavor.","contributor":"Eating Smart, Being Active\nColorado State University"},
{"slug":"veggie-loaded-mashed-potato-bowl","source_url":"https://www.myplate.gov/recipes/veggie-loaded-mashed-potato-bowl","name":"Veggie Loaded Mashed Potato Bowl","description":"With every forkful, you will experience the comforting creaminess of mashed potatoes mingling with the vibrant, zesty notes of a cucumber and tomato salad, t...","ingredients":[{"name":null,"items":["1 medium russet potato","4 tablespoons Greek yogurt","2 tablespoons olive oil","1/2 teaspoon granulated garlic","1/4 teaspoon salt","1/2 teaspoon pepper","1/2 7.5-ounce can chickpeas, low sodium, drained and rinsed","2 teaspoons curry powder","1 cup broccoli florets","2 teaspoons paprika","1/2 English cucumber, diced","1/2 large tomato, diced (or 1/2 cup cherry tomatoes)","2 tablespoons feta cheese (optional)","fresh parsley, chopped (optional)","lemon wedge (optional)"]}],"directions":[{"name":null,"steps":["Wash and scrub the potato with a vegetable brush. Cut into 2-inch pieces and place in a small pot. Cover the diced potatoes with cold water. Place the pot on the stove and turn the heat to high. Once the water comes to a boil, reduce the heat to a simmer. Cook the potato pieces until they are fork-tender but not falling apart, about 15 to 20 minutes. Remove from heat and drain the potatoes. Return the potatoes to the stove for about 30 seconds to ensure all the water is removed from the pan and the potatoes are dry.","While the potatoes are boiling, roast the chickpeas and broccoli in the air fryer. Toss the chickpeas with 1 tablespoon olive oil and the curry powder, lay them out on a baking tray in an even layer, and place in a 400 °F air fryer for 10 minutes, until crispy. Toss the broccoli with 1 tablespoon of olive oil and the paprika, and roast in an air fryer at 400 °F for 10 minutes. This can be done simultaneously if your air fryer has the space for both.","Remove the potatoes from the heat and add the Greek yogurt, olive oil, and granulated garlic. Mash the potatoes using a potato masher or a sturdy wire whisk. Do not over mix the potatoes, or they can become gluey. Adjust the seasoning with the salt and pepper.","While everything is roasting, prepare the cucumber-tomato salad. Dice 1/2 of a large cucumber and 1 large tomato. Combine in a bowl and toss.","To serve, add the mashed potatoes on the bottom, followed by the roasted chickpeas, broccoli, and cucumber-tomato salad. Top with optional garnishes and enjoy!"]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"373.91 kcal","carbohydrateContent":"43.41 g","cholesterolContent":"3.06 mg","fiberContent":"10.53 g","proteinContent":"13.15 g","sodiumContent":"481.32 mg","sugarContent":"7.56 g","fatContent":"17.75 g","saturatedFatContent":"2.93 g"},"notes":null,"contributor":"Created by Potatoes USA, a member of the MyPlate National Strategic Partnership Program"},
{"slug":"veggie-noodles","source_url":"https://www.myplate.gov/recipes/veggie-noodles","name":"Veggie Noodles","description":"Clean out your cupboards with this quick and easy veggie recipe. Use whatever fresh or canned vegetables you have on hand and mix with noodles, sauce, and ch...","ingredients":[{"name":null,"items":["1 pound pasta, uncooked","2 cups vegetables (fresh, frozen or canned, drained*)","1 cup spaghetti sauce","1/2 cup cheese, grated or shredded"]}],"directions":[{"name":null,"steps":["Boil water in a cooking pot. Add the pasta. Turn down the heat to medium-low; cook according to box directions. Pour pasta and water into colander to drain.","Add vegetables and spaghetti sauce to cooking pot. Cook over medium-low heat just until the vegetables are hot.","Return cooked, drained pasta back to cooking pot and mix together.","Sprinkle with cheese just before serving."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"413.89 kcal","carbohydrateContent":"75.19 g","cholesterolContent":"6.60 mg","fiberContent":"6.20 g","proteinContent":"16.22 g","sodiumContent":"427.44 mg","sugarContent":"5.29 g","fatContent":"4.92 g","saturatedFatContent":"1.63 g"},"notes":"* Fresh or frozen vegetables can be used. Just cook them before tossing with pasta.","contributor":"The Power of Choice\nUSDA Food and Nutrition Service and US Department of Health and Human Services Food and Drug Administration (FDA)"},
{"slug":"veggie-omelet-mug","source_url":"https://www.myplate.gov/recipes/veggie-omelet-mug","name":"Veggie Omelet in a Mug","description":"Making a veggie omelet has never been so easy! Combine all of your ingredients in a mug, pop it in the microwave, and breakfast is ready!","ingredients":[{"name":null,"items":["2 eggs","2 tablespoons fat-free (skim) milk","1 pinch salt","1 pinch black pepper","1/4 cup finely chopped mushrooms (or your favorite vegetables)","2 tablespoons low-fat cheddar cheese, shredded (or your favorite cheese)"]}],"directions":[{"name":null,"steps":["Lightly grease the inside of a 12-ounce microwave-safe mug.","Use a fork to combine the eggs, milk, salt and pepper in the mug and stir well. Mix in the vegetables and cheese.","Microwave on HIGH for 45 seconds. Stir. Return to the microwave and cook on HIGH until the mixture has puffed and set, 60 to 90 seconds. The omelet may look wet on the top but it will dry as it cools.","Refrigerate leftovers within 2 hours."]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 recipe","calories":"203.26 kcal","carbohydrateContent":"3.56 g","cholesterolContent":"422.65 mg","fiberContent":"0.18 g","proteinContent":"17.79 g","sodiumContent":"385.97 mg","sugarContent":"2.09 g","fatContent":"12.92 g","saturatedFatContent":"5.00 g"},"notes":"To make a meal, serve with a slice of whole grain toast and fruit.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"veggie-pizza-pita-pockets","source_url":"https://www.myplate.gov/recipes/veggie-pizza-pita-pockets","name":"Veggie Pizza Pita Pockets","description":"Don''t want to turn on your oven or stove today? This veggie pizza pita is a delicious option that is made in the microwave. Top pizza with your favorite vegg...","ingredients":[{"name":null,"items":["1 pita, whole wheat (cut around the sides, into flats)","2 tablespoons low-sodium tomato sauce","1 slice part-skim mozzarella cheese"]},{"name":"Pick two from the following vegetables","items":["green and red bell peppers, sliced","mushrooms, chopped","1/16 cup broccoli, chopped (1 tablespoon)","1 tablespoon red onion, chopped","spinach, shredded"]}],"directions":[{"name":null,"steps":["Place one pita round on a plate.","Spread 2 tablespoons of tomato sauce on pizza.","Sprinkle various chopped vegetable over sauce.","Layer one slice of cheese on top of sauce.","Cover with the other half of pita round.","Microwave 35 to 45 seconds, or until cheese melts.","Slice in half, let cool, and enjoy!"]}],"yield":"1 Serving","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"225.08 kcal","carbohydrateContent":"35.71 g","cholesterolContent":"13.65 mg","fiberContent":"4.24 g","proteinContent":"11.19 g","sodiumContent":"392.57 mg","sugarContent":"3.61 g","fatContent":"5.38 g","saturatedFatContent":"2.60 g"},"notes":"1 tablespoon each of broccoli and red onion used for costing and nutrition analysis.\nTips:\nLayering the cheese over the raw veggies will help them cook; the melting cheese essentially steams the veggies in the microwave. If you prefer softer veggies, they can be steamed before being put on the pizza.\nA tomato sauce with added flavors will be a nice kick to this pizza; also, mild salsa will add a different flavor.\nMany sliced cheeses come in low-fat varieties and could be substituted for mozzarella. Or you could mix and match.\nVeggie pizza is a great way to get your daily servings of veggies. A mix of veggies such as greens (spinach, broccoli), seeded (zucchini, peppers, tomatoes), and roots/fungi (onion, garlic, mushroom) will complement each other if used in variety.","contributor":"Adapted from CSAAC (Community Services for Autistic Adults and Children)"},
{"slug":"veggie-quesadillas","source_url":"https://www.myplate.gov/recipes/veggie-quesadillas","name":"Veggie Quesadillas","description":"This dish, full of veggies and cheese, is made with whole wheat tortillas. Top with salsa and use whatever veggies you have on hand.","ingredients":[{"name":null,"items":["cooking oil spray","1 medium zucchini, chopped","1/2 broccoli head, chopped","1 medium green bell pepper, seeded and chopped","1 medium onion, peeled and chopped","1 medium carrot, shredded","4 medium whole wheat tortillas","1 cup low-fat cheddar cheese, shredded","1/2 cup of fresh salsa"]}],"directions":[{"name":null,"steps":["Wash vegetables.","Spray pan with cooking oil spray.","Cook vegetables on medium heat for 4 to 5 minutes, stirring frequently. Remove from pan.","Spray pan with cooking spray. Place tortilla in the pan. Sprinkle with half the vegetables and half of the cheese.","Place the other tortilla on top. Cook on medium heat for 4 to 6 minutes or until the cheese starts to melt and the bottom tortilla starts to brown.","Flip quesadilla. Cook for 4 minutes or until tortilla browns.","Repeat steps 4 - 5.","Cut each quesadilla in half. Serve with salsa."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 quesadilla","calories":"304.00 kcal","carbohydrateContent":"36.29 g","cholesterolContent":"21.47 mg","fiberContent":"8.53 g","proteinContent":"15.73 g","sodiumContent":"535.84 mg","sugarContent":"7.59 g","fatContent":"10.76 g","saturatedFatContent":"5.87 g"},"notes":"Other Ideas\nTry a variety of vegetables: eggplant, tomatoes, mushrooms, green beans, cauliflower, garlic, corn, or spinach.\nSeason with fresh herbs: parsley, basil, cilantro, oregano, or dill.\nSprinkle dry herbs: Italian seasoning, chili powder, cumin, or your favorite.\nTop with your favorite spicy salsa.","contributor":"University of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"veggie-stir-fry-turkey","source_url":"https://www.myplate.gov/recipes/veggie-stir-fry-turkey","name":"Veggie Stir-Fry with Turkey","description":"Okra, corn, and onions mixed with squash give this veggie stir-fry crunch and flavor. Serve as a side dish with your favorite chicken or fish recipe.","ingredients":[{"name":null,"items":["1 pound 85% lean ground turkey","1 cup red bell peppers, diced","1/2 medium onion, chopped","1 3/4 cups low-sodium canned corn (or frozen, or cut from cob)","10 okra pods, sliced","3 medium yellow squash, sliced"]}],"directions":[{"name":null,"steps":["In a large frying pan over medium heat, cook ground turkey until no longer pink.","Add red peppers, onions, corn, okra, and squash and cook for 5 minutes until tender."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1/2 cup prepared stir-fry","1/6 of recipe"],"calories":"203.42 kcal","carbohydrateContent":"14.73 g","cholesterolContent":"56.10 mg","fiberContent":"2.96 g","proteinContent":"16.09 g","sodiumContent":"58.33 mg","sugarContent":"6.58 g","fatContent":"10.02 g","saturatedFatContent":"2.56 g"},"notes":null,"contributor":"University of Kentucky Cooperative Extension Service"},
{"slug":"veggie-stuffed-pita","source_url":"https://www.myplate.gov/recipes/veggie-stuffed-pita","name":"Veggie Stuffed Pita","description":"Mini whole wheat pitas are stuffed with veggies and topped with cheese. Use family favorite veggies that you have on hand to make this easy lunch or dinner. ...","ingredients":[{"name":null,"items":["2 cups broccoli, chopped","15 baby carrots or 4 regular","2 medium zucchinis","12 ounces low-fat cheddar cheese","1/2 teaspoon oregano","1/4 teaspoon black pepper","1/4 teaspoon garlic powder","1/4 teaspoon onion powder","2 tablespoons vegetable oil (or oil of your choice)","12 (4-inch) whole wheat mini pitas"]}],"directions":[{"name":null,"steps":["Wash vegetables.","Remove the broccoli flowers from stems, cut the flowers into small florets, and put into mixing bowl.","Chop carrots into bite size pieces, add to into mixing bowl.","Slice the zucchini into thin slices. Cut each slice into quarters and put into bowl.","Grate the cheese and put into a separate bowl.","Measure oregano, pepper, garlic powder, and onion powder; mix together.","Heat oil in a large skillet over medium heat. Put the spices in the heated oil and then add the mixture of vegetables to the pan. Stir vegetables with a wooden spoon and sauté about 5 minutes. When the vegetables are slightly tender, remove from heat.","Spoon vegetable mixture into the pita. Top the hot vegetables with 1-ounce grated cheese."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 prepared pita","1/12 of recipe"],"calories":"201.47 kcal","carbohydrateContent":"19.82 g","cholesterolContent":"21.55 mg","fiberContent":"2.80 g","proteinContent":"11.41 g","sodiumContent":"311.47 mg","sugarContent":"2.53 g","fatContent":"8.78 g","saturatedFatContent":"3.99 g"},"notes":"Substitute green pepper, mushrooms, or onions in place of listed vegetables.","contributor":"Wellness Ways Resource Book\nUniversity of Illinois Extension Service"},
{"slug":"very-berry-muesli","source_url":"https://www.myplate.gov/recipes/very-berry-muesli","name":"Very Berry Muesli","description":"Berry delicious! This is the perfect breakfast to prep the night before then grab and go on a busy morning.","ingredients":[{"name":null,"items":["1 cup low-fat fruit yogurt","1 cup old fashioned rolled oats, uncooked","1/2 cup fat-free (skim) milk, or 1% milk","1/2 cup dried fruit (try raisins, apricots, dates)","1/2 cup apples, chopped (about 1/3 of a medium apple)","1/2 cup frozen blueberries","1/4 cup toasted walnuts, chopped"]}],"directions":[{"name":null,"steps":["In medium bowl, mix oats, yogurt, and milk.","Cover and refrigerate for 6 to 12 hours.","Add dried and fresh fruit, and mix gently.","Serve scoops of muesli in small dishes. Sprinkle each serving with chopped nuts."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 serving","1/5 of recipe"],"calories":"214.74 kcal","carbohydrateContent":"36.22 g","cholesterolContent":"3.18 mg","fiberContent":"3.50 g","proteinContent":"6.59 g","sodiumContent":"48.20 mg","sugarContent":"20.82 g","fatContent":"5.86 g","saturatedFatContent":"1.02 g"},"notes":"Muesli makes a delicious breakfast. Try drizzling with milk.\nSubstitute any frozen, canned and drained, or fresh chopped fruit for apples and blueberries.\nFlavor boosters: cinnamon or grated orange peel.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"very-berry-smoothie","source_url":"https://www.myplate.gov/recipes/very-berry-smoothie","name":"Very Berry Smoothie","description":"This refreshing pineapple, banana, and berry blend smoothie has 2 cups of fruit per serving.","ingredients":[{"name":null,"items":["1 cup frozen strawberries","1 cup frozen raspberries","1 cup pineapple chunks","1 banana","1 cup skim milk (or almond milk)","1 1/2 cups ice"]}],"directions":[{"name":null,"steps":["Peel and slice the banana.","Gather all ingredients and combine in a blender.","Cover and blend until smooth.","Serve right away or pour into ice cube trays and freeze. During the week, pop out the cubes for a quick on-the-go breakfast."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"209.09 kcal","carbohydrateContent":"46.88 g","cholesterolContent":"3.66 mg","fiberContent":"8.68 g","proteinContent":"6.32 g","sodiumContent":"60.30 mg","sugarContent":"30.98 g","fatContent":"0.94 g","saturatedFatContent":"0.16 g"},"notes":"Get an additional food group in your smoothie by adding 1 cup of spinach or kale.","contributor":"USDA Center for Nutrition Policy and Promotion"},
{"slug":"vidalia-onion-and-tomato-salad-grilled-tuna","source_url":"https://www.myplate.gov/recipes/vidalia-onion-and-tomato-salad-grilled-tuna","name":"Vidalia Onion and Tomato Salad with Grilled Tuna","description":"Sweet Vidalia onions come into season in mid-April. Pair them with tomatoes for this light summer salad that''s topped with grilled ahi tuna. Perfect for a ba...","ingredients":[{"name":"For the Salad","items":["1/2 pound ahi (yellowfin) tuna steak (fresh or frozen)","1/2 teaspoon olive oil","2 tomatoes, cut into wedges","1 large head lettuce (Boston, Romaine or Bibb) (washed, dried, and torn into bite-sized pieces)","1/2 Vidalia onion, thinly sliced"]},{"name":"For the Dressing","items":["1 1/2 tablespoons olive oil","1/4 cup lemon juice, fresh or bottled","2 teaspoons white wine vinegar","1 teaspoon Dijon mustard","1/4 teaspoon salt","1/8 teaspoon black pepper","1/4 teaspoon thyme","1/4 teaspoon marjoram"]}],"directions":[{"name":null,"steps":["Heat grill.","Whisk together dressing ingredients in a small bowl.","Cut tuna into 1-inch chunks and skewer and place on two or three 3-inch skewers; brush lightly with olive oil. Season lightly with salt and pepper.","Grill skewered tuna until fish is opaque and flakes with a fork (145 °F); remove from grill.","In a large bowl, toss dressing with all vegetable ingredients. To serve, divide salad on four individual plates; top with tuna."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"133.48 kcal","carbohydrateContent":"6.10 g","cholesterolContent":"18.65 mg","fiberContent":"1.66 g","proteinContent":"12.93 g","sodiumContent":"199.65 mg","sugarContent":"3.18 g","fatContent":"6.43 g","saturatedFatContent":"1.04 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of non-fat milk and a slice of whole-grain bread.","contributor":"Produce for Better Health Foundation"},
{"slug":"vinaigrette-salad-dressing","source_url":"https://www.myplate.gov/recipes/vinaigrette-salad-dressing","name":"Vinaigrette Salad Dressing","description":"Making your own salad dressing is quick and easy. You can start out with this basic recipe and adapt as needed to fit the ingredients of your salad and your ...","ingredients":[{"name":"Basic Vinaigrette","items":["6 tablespoons vegetable oil (olive, canola, avacado, or cooking oil of choice)","4 tablespoons vinegar (cider, balsamic, or red wine vinegar)","1/4 teaspoon salt","1/4 teaspoon black pepper","1/4 teaspoon mustard (yellow, dijon, or brown mustard)"]}],"directions":[{"name":null,"steps":["Mix all ingredients together.","Serve."]}],"yield":"5 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 tablespoons","calories":"154.18 kcal","carbohydrateContent":"0.20 g","cholesterolContent":"0.00 mg","fiberContent":"0.04 g","proteinContent":"0.02 g","sodiumContent":"121.41 mg","sugarContent":"0.05 g","fatContent":"16.81 g","saturatedFatContent":"2.30 g"},"notes":"Variations\nSweet Vinaigrette (Basic Vinaigrette recipe plus)\n1/4 teaspoon sugar\nItalian Vinaigrette (Basic Vinaigrette plus)\n1 teaspoon garlic powder\n1 teaspoon Italian seasoning\n1/8 teaspoon red pepper flakes, crushed\nHoney Mustard Vinaigrette (Basic Vinaigrette plus)\n1 teaspoon Dijon or spice mustard\n2 teaspoons honey*\n*Children under the age of one should not consume honey.","contributor":"USDA Supplemental Nutrition Assistance Program (SNAP)"},
{"slug":"waldorf-salad","source_url":"https://www.myplate.gov/recipes/waldorf-salad","name":"Waldorf Salad","description":"Extra apples from the market? Try this Waldorf Salad with walnuts and crunchy fall apples.","ingredients":[{"name":null,"items":["1/4 cup walnuts, chopped","2 medium apples, cored and diced","1 cup celery, diced","1/2 cup raisins","1/4 cup fat-free plain yogurt","1/2 teaspoon sugar","1 teaspoon lemon juice"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 degrees F.","Place chopped walnuts on a baking sheet and bake for 12 to 15 minutes. Stir occasionally until they are evenly toasted.","Combine nuts, apples, celery, and raisins.","Stir together yogurt, sugar, and lemon juice. Pour over apple mixture and toss lightly.","Refrigerate leftovers within 2 hours."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"2/3 cup","calories":"123.30 kcal","carbohydrateContent":"22.90 g","cholesterolContent":"0.20 mg","fiberContent":"2.66 g","proteinContent":"2.04 g","sodiumContent":"27.64 mg","sugarContent":"18.30 g","fatContent":"3.45 g","saturatedFatContent":"0.36 g"},"notes":"Serve this dish with a whole wheat roll for a hearty meal.","contributor":"Food Hero\nOregon State University Cooperative Extension Service"},
{"slug":"walleye-chowder","source_url":"https://www.myplate.gov/recipes/walleye-chowder","name":"Walleye Chowder","description":"Add a cup of hominy or corn to bulk up this creamy chowder.","ingredients":[{"name":null,"items":["4 slices bacon, cooked and chopped","3 tablespoons butter","1/2 cup celery, chopped","1 yellow onion, chopped","1/4 cup all-purpose flour","4 cups cold milk (low-fat or nonfat)","2 cups red potatoes","1 pound walleye, thawed, cut into chunks (2 8-ounce fillets)","2 tablespoons fresh parsley or green onions, chopped","Salt and pepper to taste"]}],"directions":[{"name":null,"steps":["Heat butter in a large pot over medium-high heat. Add celery and onions and sauté until softened.","Stir in flour to form a roux -- which is a mixture of fat and flour used to thicken sauces or soups. Slowly whisk in the milk.","Add the potatoes and bacon and stir gently. Reduce heat and simmer for 30 minutes or until potatoes are cooked through.","Add fish chunks and cook for an additional 6 to 8 minutes or until fish reaches the appropriate internal temperature.","Season to taste with salt and pepper. Garnish with parsley or green onions and serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"391.24 kcal","carbohydrateContent":"34.63 g","cholesterolContent":"98.26 mg","fiberContent":"2.24 g","proteinContent":"29.38 g","sodiumContent":"567.06 mg","sugarContent":"14.84 g","fatContent":"14.63 g","saturatedFatContent":"7.14 g"},"notes":"If you want to cut back on sodium, swap the bacon for turkey bacon or ham, or prepare the recipe without it.\nOptional: Add a cup of traditional hominy or scorched corn\nThis recipe contains one or more ingredients considered to be traditional or indigenous to Native American communities in certain regions across North America.","contributor":"Recipe adapted from Joe Van Alstine, Little Traverse Bay Bands of Odawa Indians"},
{"slug":"watermelon-gazpacho","source_url":"https://www.myplate.gov/recipes/watermelon-gazpacho","name":"Watermelon Gazpacho","description":"Watermelon can be combined with a savory ingredients for a surprising and refreshing twist in this simple and quick gazpacho recipe.","ingredients":[{"name":null,"items":["4 cups cubed, seeded watermelon (divided)","1 cucumber (peeled, coarsely chopped, divided)","1 clove garlic (minced)","2 tablespoons chopped onion","2 teaspoons lime juice","1 teaspoon olive oil","1 tablespoon chopped fresh basil","1/8 teaspoon ground black pepper","1/2 jalapeño pepper, seeded and chopped (optional)"]}],"directions":[{"name":null,"steps":["In a small bowl, mix 1 cup of cubed watermelon and 1/2 of chopped cucumber; set aside.","Process remaining ingredients in a food processor or blender until puréed.","Transfer all ingredients to a large bowl and stir.","Refrigerate until ready to serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"68.48 kcal","carbohydrateContent":"14.44 g","cholesterolContent":"0.00 mg","fiberContent":"1.02 g","proteinContent":"1.41 g","sodiumContent":"2.85 mg","sugarContent":"10.79 g","fatContent":"1.47 g","saturatedFatContent":"0.24 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of non-fat milk and whole-grain pita bread/chips with hummus.","contributor":"Produce for Better Health Foundation"},
{"slug":"wheat-berry-chili","source_url":"https://www.myplate.gov/recipes/wheat-berry-chili","name":"Wheat Berry Chili","description":"Wheat berries add a unique texture to this flavor-packed chili recipe. This hearty, colorful one pot meal is sure to be a crowd pleaser.","ingredients":[{"name":null,"items":["1 cup wheat berries","3 cups water","1 large onion, chopped","1/2 green pepper, chopped","1/2 yellow pepper, chopped","4 teaspoons chili powder, or to taste","1/4 teaspoon hot pepper sauce","1/8 teaspoon black pepper","1 8-ounce can tomato sauce, no salt added","2 14.5-ounce cans diced tomatoes","2 cups beef broth, 99% fat free, reduced sodium","1 15-ounce can kidney beans, low sodium","1 15-ounce can white beans, low sodium"]}],"directions":[{"name":null,"steps":["Cook wheat berries in 3 cups of water for 1 hour until tender; add more water if necessary; drain.","Rinse with cool water and drain thoroughly.","In the microwave on medium heat, cook onions and green and yellow peppers for 1 minute, or until desired softness.","In a 4-quart pot, combine remaining ingredients with wheat berries and microwaved vegetables.","On stovetop, bring to a boil and simmer uncovered 1 hour or until desired consistency is reached, stirring occasionally."]}],"yield":"8 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"232.01 kcal","carbohydrateContent":"45.67 g","cholesterolContent":"0.00 mg","fiberContent":"11.63 g","proteinContent":"12.76 g","sodiumContent":"452.42 mg","sugarContent":"8.91 g","fatContent":"1.56 g","saturatedFatContent":"0.30 g"},"notes":null,"contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"white-bean-bruschetta","source_url":"https://www.myplate.gov/recipes/white-bean-bruschetta","name":"White Bean Bruschetta","description":"Try this tasty bruschetta with crispy bread topped with white beans, tomatoes, and spices. Served as a side dish or an appetizer, it is sure to be a crowd pl...","ingredients":[{"name":null,"items":["1 whole-wheat French baguette, cut into 12 thin slices along the bias","1/4 cup olive oil, divided","1 cup white onion, chopped","4 cloves garlic, minced","1 teaspoon dried basil","1 teaspoon dried oregano","1 cup canned navy beans, rinsed and drained","2 tomatoes, cored and cubed","2 tablespoons balsamic vinegar"]}],"directions":[{"name":null,"steps":["Slice the baguette on the diagonal into thin slices (about 12 slices for a baguette).","In a large sauté pan, heat 2 tablespoons of the olive oil over medium heat.","Place the bread slices in the pan and cook on medium high heat until sizzling and golden. Before flipping the bread, add an additional tablespoon of olive oil to the pan and cook the second side until golden.","For the topping, cook the onions and the remaining tablespoon of olive oil over medium heat until the onions are soft, about 7 minutes.","Add the garlic, basil, and oregano and cook another minute or two, until fragrant.","Add beans and continue cooking for another five minutes on low heat. Add the tomatoes and turn off the heat, allowing tomatoes to warm without cooking.","Drizzle the balsamic vinegar into the pan and gently stir.","Scoop heaping spoonsful of the tomato-bean mixture onto the grilled bread and enjoy."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"3 slices","calories":"341.37 kcal","carbohydrateContent":"41.30 g","cholesterolContent":"0.00 mg","fiberContent":"5.91 g","proteinContent":"10.24 g","sodiumContent":"389.70 mg","sugarContent":"6.11 g","fatContent":"15.46 g","saturatedFatContent":"2.51 g"},"notes":null,"contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"white-chicken-chili","source_url":"https://www.myplate.gov/recipes/white-chicken-chili","name":"White Chicken Chili","description":"Get three food groups in one delicious and hearty soup.","ingredients":[{"name":null,"items":["2 tablespoons olive oil (or cooking oil of choice)","1 medium onion, finely chopped","1 can (4 ounces) green chilies, drained","2 cans (15.5 ounces each) low-sodium Great Northern Beans","1 can (14.5 ounces) low-sodium chicken broth","2 teaspoons garlic powder","1/2 teaspoon black pepper","2 teaspoons ground cumin","1 1/2 cups cooked chicken, cubed","1/2 cup mozzarella cheese, shredded","fresh parsley (optional for garnish)"]}],"directions":[{"name":null,"steps":["Heat oil in a large saucepan.","Add onion and cook until tender.","Add green chilies, beans (do not drain), chicken broth, garlic powder, pepper, ground cumin, and chicken. Bring to a boil.","Reduce heat and simmer for 10 minutes or until desired thickness.","Serve hot, topped with cheese. Add parsley if desired."]}],"yield":"6 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 1/2 cups","calories":"318.24 kcal","carbohydrateContent":"35.48 g","cholesterolContent":"39.46 mg","fiberContent":"7.92 g","proteinContent":"25.08 g","sodiumContent":"431.92 mg","sugarContent":"3.35 g","fatContent":"9.03 g","saturatedFatContent":"2.41 g"},"notes":"To reduce sodium content of soups, drain and rinse canned beans, use low-sodium broth, and add your own spices instead of using a seasoning packet.","contributor":"University of Nebraska at Lincoln\nNebraska Nutrition Education Program"},
{"slug":"white-chili","source_url":"https://www.myplate.gov/recipes/white-chili","name":"White Chili","description":"Looking for a new twist on chili? Try this white chili with chicken and milk and you''re in for a treat.","ingredients":[{"name":null,"items":["1 tablespoon olive oil (or cooking oil of choice)","2 medium red bell peppers, chopped","1 large onion, chopped","1 chopped green chili (can adjust to taste)","3 garlic cloves, minced","1 tablespoon chili powder","1 teaspoon cumin","1 teaspoon oregano","2 cups low-sodium chicken broth","2 cups 1% low-fat milk","4 cups white beans, cooked*","12 ounces cooked chicken, cubed","1/4 cup cilantro","6 corn tortillas (toasted and cut into 1 inch squares)"]}],"directions":[{"name":null,"steps":["Sauté peppers and onion in oil.","Add green chili, garlic, spices, and chicken broth. Simmer for 20 minutes.","Add milk, cooked beans, and cooked chicken. Allow to thicken before adding cilantro. Heat through.","Top chili with crisp tortillas before serving."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/10 of recipe","calories":"272.05 kcal","carbohydrateContent":"36.80 g","cholesterolContent":"36.05 mg","fiberContent":"7.22 g","proteinContent":"22.33 g","sodiumContent":"330.83 mg","sugarContent":"5.91 g","fatContent":"4.50 g","saturatedFatContent":"1.09 g"},"notes":"*See our recipe to learn how to cook beans.","contributor":"The Bold and Beautiful Book of Bean Recipes\nWashington State WIC Program"},
{"slug":"white-sauce-thin","source_url":"https://www.myplate.gov/recipes/white-sauce-thin","name":"White Sauce - Thin","description":"Add a creamy texture to your soups and stews with this easy sauce.","ingredients":[{"name":null,"items":["1 tablespoon butter","1 tablespoon flour","salt and pepper (optional, to taste)","1 cup fat-free (skim) milk*"]}],"directions":[{"name":null,"steps":["In a small pot, melt butter over low heat.","Add flour, salt, and pepper to mixture.","Add milk gradually.","Heat to boiling, stir constantly until mixture is smooth and bubbly. (The consistency should be like thin cream.)","Remove from heat."]}],"yield":"1 serving","nutrition":{"@type":"NutritionInformation","servingSize":["variable","label is for entire recipe"],"calories":"213.21 kcal","carbohydrateContent":"17.98 g","cholesterolContent":"37.85 mg","fiberContent":"0.21 g","proteinContent":"9.30 g","sodiumContent":"101.76 mg","sugarContent":"12.35 g","fatContent":"11.79 g","saturatedFatContent":"7.30 g"},"notes":"* Substitute low-fat (skim) milk with 1/3 cup powdered milk and water to equal 1 cup.\nUse for cream soups and stews.","contributor":"Lifeskills in Food Education, Food Skills Cookbook\nUniversity of Hawaii at Manoa Cooperative Extension\nFood Stamps Nutrition Education Program"},
{"slug":"whole-grain-strawberry-pancakes","source_url":"https://www.myplate.gov/recipes/whole-grain-strawberry-pancakes","name":"Whole Grain Strawberry Pancakes","description":"Whole wheat flour adds a nutty flavor and texture to these great-tasting pancakes. Dish these up with berries and a glass of milk on the side for a wholesome...","ingredients":[{"name":null,"items":["1 1/2 cups whole wheat flour","3 tablespoons sugar","1 teaspoon baking powder","1/2 teaspoon baking soda","1/2 teaspoon salt","3 eggs","1 container vanilla low-fat yogurt (6 oz)","3/4 cup water","3 tablespoons canola oil"]},{"name":"For the topping","items":["1 3/4 cups sliced fresh strawberries","1 container strawberry low-fat yogurt (6 oz)"]}],"directions":[{"name":null,"steps":["Heat griddle to 375 °F or heat 12-inch skillet over medium heat. Grease with canola oil if necessary (or spray with cooking spray before heating).","In large bowl, mix flour, sugar, baking powder, baking soda, and salt; set aside.","In medium bowl, beat eggs, vanilla yogurt, water, and oil with egg beater or wire whisk until well blended.","Pour egg mixture all at once into flour mixture; stir until moistened.","For each pancake, pour slightly less than 1/4 cup batter from cup or pitcher onto hot griddle.","Cook pancakes 1 to 2 minutes or until bubbly on top, puffed and dry around edges. Turn; cook other sides 1 to 2 minutes or until golden brown.","Top each serving (2 pancakes) with 1/4 cup sliced strawberries and 1 to 2 tablespoons strawberry yogurt."]}],"yield":"7 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"2 pancakes","calories":"246.37 kcal","carbohydrateContent":"33.00 g","cholesterolContent":"90.74 mg","fiberContent":"3.45 g","proteinContent":"8.66 g","sodiumContent":"393.47 mg","sugarContent":"12.80 g","fatContent":"9.58 g","saturatedFatContent":"1.64 g"},"notes":null,"contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"whole-wheat-garlic-bread-sticks","source_url":"https://www.myplate.gov/recipes/whole-wheat-garlic-bread-sticks","name":"Whole Wheat Garlic Bread Sticks","description":"These easy and delicious garlic bread sticks are a great side dish for our Chicken Spaghetti or as a snack.","ingredients":[{"name":null,"items":["6 slices 100% whole wheat bread","2 tablespoons olive oil (or cooking oil of choice)","1/2 teaspoon garlic powder","1 teaspoon Italian seasoning"]}],"directions":[{"name":null,"steps":["Preheat oven to 300 degrees F.","Spread each slice of bread with one teaspoon oil.","Sprinkle with garlic powder and Italian seasoning.","Cut each slice into 3 equal parts.","Bake in preheated oven for about 25 minutes or until crisp and lightly browned."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"3 slices","calories":"134.30 kcal","carbohydrateContent":"15.70 g","cholesterolContent":"0.00 mg","fiberContent":"2.18 g","proteinContent":"4.47 g","sodiumContent":"162.25 mg","sugarContent":"1.59 g","fatContent":"5.95 g","saturatedFatContent":"0.99 g"},"notes":null,"contributor":"Eat Smart New York!\nCornell University Cooperative Extension"},
{"slug":"whole-wheat-muffins","source_url":"https://www.myplate.gov/recipes/whole-wheat-muffins","name":"Whole Wheat Muffins","description":"Start your day off with these whole wheat muffins topped with cinnamon and sugar. Make these ahead of time for a quick and easy breakfast.","ingredients":[{"name":null,"items":["1 tablespoon sugar","1/2 teaspoon ground cinnamon","1 cup all purpose flour","1 cup whole wheat flour","1/2 teaspoon salt","2 teaspoons baking powder","1/4 cup brown sugar, firmly packed","1 cup 1% low-fat milk","2 large eggs","vanilla (1 teaspoon, optional)","1/4 cup margarine or butter, melted (or 1/4 cup vegetable oil)"]}],"directions":[{"name":null,"steps":["Preheat oven to 400 °F. Lightly oil or coat with non-stick spray the cups of a 12 cup muffin pan, or use paper muffin cups.","Mix together white sugar and cinnamon for topping and set aside.","In a large bowl, stir together flour, salt, baking powder, and brown sugar. In a glass liquid measuring cup, measure milk, then add eggs, vanilla (if using), and melted margarine or oil. Mix with a fork until egg is well combined with other ingredients.","Pour milk mixture over flour mixture and stir with a spoon, about 20 strokes, until flour is just moistened. Batter will be lumpy and thick.","Fill prepared muffin cups about 2/3 full with batter. Sprinkle about 1/4 teaspoon of cinnamon/ sugar topping over each muffin.","Bake in oven for 20 to 25 minutes until golden brown. Serve warm. Leftovers may be frozen."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 muffin","1/12 of recipe"],"calories":"139.72 kcal","carbohydrateContent":"22.15 g","cholesterolContent":"35.31 mg","fiberContent":"1.41 g","proteinContent":"4.14 g","sodiumContent":"231.48 mg","sugarContent":"6.58 g","fatContent":"4.17 g","saturatedFatContent":"1.01 g"},"notes":null,"contributor":"Montana State University Extension Service\nNutrition Education Program"},
{"slug":"wild-rice-muffins","source_url":"https://www.myplate.gov/recipes/wild-rice-muffins","name":"Wild Rice Muffins","description":"These flavorful and nutty wild rice muffins come together as part of a healthy breakfast or snack.","ingredients":[{"name":null,"items":["cooking spray","1 1/2 cups bakery mix","1/4 cup sugar","2 teaspoons cinnamon","2 bananas, mashed","3/4 cup milk","1/4 cup applesauce","1 cup wild rice, cooked","walnuts, chopped (optional)"]}],"directions":[{"name":null,"steps":["Preheat the oven to 400 °F. Spray a 12-cup muffin pan with cooking spray.","In a medium bowl, mix bakery mix, sugar, and cinnamon.","In a separate bowl, mix bananas, milk, and applesauce.","Add banana mixture to dry mixture and stir.","Fold in wild rice and nuts.","Spoon 1/4 cup of the batter into each muffin cup. Bake for 20 to 25 minutes."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 muffin","calories":"129.08 kcal","carbohydrateContent":"23.69 g","cholesterolContent":"1.08 mg","fiberContent":"1.23 g","proteinContent":"2.52 g","sodiumContent":"210.71 mg","sugarContent":"10.69 g","fatContent":"2.74 g","saturatedFatContent":"0.75 g"},"notes":"This recipe contains one or more ingredients considered to be traditional or indigenous to Native American communities in certain regions across North America.","contributor":"Recipe adapted from Chickasaw Nation Nutrition Services, Get Fresh Initiative"},
{"slug":"winter-crisp","source_url":"https://www.myplate.gov/recipes/winter-crisp","name":"Winter Crisp","description":"What is that sweet cinnamon scent, wafting from your kitchen? It''s this apple and cranberry winter crisp.","ingredients":[{"name":null,"items":["1/2 cup sugar","3 tablespoons all purpose flour","1 teaspoon lemon peel, grated","5 cups apple, unpeeled and sliced","1 cup fresh cranberries","2/3 cup rolled oats","1/3 cup brown sugar, packed","1/4 cup whole wheat flour","2 tablespoons cinnamon","3 tablespoons margarine"]}],"directions":[{"name":"Filling","steps":["Combine sugar, flour, and lemon peel in a medium bowl and mix well.","Stir in apples and cranberries.","Spoon into a 6-cup baking dish."]},{"name":"Topping","steps":["Combine oats, brown sugar, flour, and cinnamon in a small bowl.","Stir in melted margarine.","Sprinkle topping over filling.","Bake at 375 degrees F for 40 minutes or until filling is bubbly and top is brown.","Serve warm or at room temperature."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"292.99 kcal","carbohydrateContent":"60.72 g","cholesterolContent":"0.07 mg","fiberContent":"5.75 g","proteinContent":"2.63 g","sodiumContent":"52.06 mg","sugarContent":"41.88 g","fatContent":"5.20 g","saturatedFatContent":"1.02 g"},"notes":null,"contributor":"Stay Young at Heart: Cooking the Heart-Healthy Way\nUS Department of Health and Human Services\nNational Heart, Lung, and Blood Institute"},
{"slug":"wobbly-wonders","source_url":"https://www.myplate.gov/recipes/wobbly-wonders","name":"Wobbly Wonders","description":"This geletain and pudding combination are perfect for young children or the young at heart!","ingredients":[{"name":null,"items":["3 tablespoons flavored gelatin, choose your favorite","2 cups boiling water","1 1/2 cups 1% low-fat milk","1 package (3.5 ounces) vanilla instant pudding"]}],"directions":[{"name":null,"steps":["In a medium bowl, dissolve gelatin in boiling water. Cool at least 30 minutes.","Pour milk into large mixing bowl and add pudding mix. Using an electric mixer, beat 1 minute.","Gradually add and beat in gelatin mixture. Pour into a 9x13 inch baking pan. Chill in fridge for several hours.","Cut fun shapes with cookie cutters or knife. Store in refrigerator."]}],"yield":"20 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/20 of recipe","calories":"30.05 kcal","carbohydrateContent":"5.55 g","cholesterolContent":"0.92 mg","fiberContent":"0.00 g","proteinContent":"1.52 g","sodiumContent":"79.46 mg","sugarContent":"5.51 g","fatContent":"0.20 g","saturatedFatContent":"0.13 g"},"notes":null,"contributor":"Kids a Cookin’\nKansas Family Nutrition Program"},
{"slug":"wonderful-stuffed-potatoes","source_url":"https://www.myplate.gov/recipes/wonderful-stuffed-potatoes","name":"Wonderful Stuffed Potatoes","description":"Pair these delicious stuffed potatoes with grilled or baked meat, fish, or tofu.","ingredients":[{"name":null,"items":["4 potatoes (medium, baking)","3/4 cup cottage cheese (low-fat)","1/4 cup milk (low-fat 1%)","2 tablespoons margarine (soft tub)","1 teaspoon dill weed","3/4 teaspoon herb seasoning","1/4 teaspoon hot pepper sauce (or ~ 4 dashes)","2 tablespoons Parmesan cheese"]}],"directions":[{"name":null,"steps":["Prick potatoes with fork. Bake at 425 °F for 60 minutes or until fork is easily inserted.","Cut potatoes in half lengthwise. Carefully scoop out potato, leaving about 1/2 inch of pulp inside shell. Mash pulp in large bowl.","Mix in by hand remaining ingredients except Parmesan cheese. Spoon mixture into potato shells.","Sprinkle top with 1/4 teaspoon of Parmesan cheese.","Place on baking sheet and return to oven. Bake 15 to 20 minutes or until tops are golden brown."]}],"yield":"8","nutrition":{"@type":"NutritionInformation","calories":"134.31"},"notes":null,"contributor":"A Healthier You: Based on the Dietary Guidelines for Americans\nUS Department of Health and Human Services\nOffice of Disease Prevention and Health Promotion"},
{"slug":"yellow-potato-and-red-pepper-shrimp-saute","source_url":"https://www.myplate.gov/recipes/yellow-potato-and-red-pepper-shrimp-saute","name":"Yellow Potato and Red Pepper Shrimp Sauté","description":"This dish is reminiscent of shrimp scampi but is veggie-centric with its mix of potatoes, bell peppers, onions, and zucchini. The potatoes are partially cook...","ingredients":[{"name":null,"items":["3 medium yellow potatoes","2 tablespoons olive oil","2 cloves garlic (minced)","1 small onion (chopped)","1 medium red bell pepper (coarsely chopped)","1/2 cup white grape juice","1/2 cup water","1 teaspoon vinegar","12 ounces frozen jumbo shrimp (peeled and deveined, no sodium-added)","1 medium fresh zucchini (cut in small chunks)","1 teaspoon Italian seasoning (no sodium)","1/4 teaspoon ground black pepper","1 lemon (divided)","1/4 cup Parmesan cheese"]}],"directions":[{"name":null,"steps":["Pierce the skin of each potato with a fork; microwave potatoes on high for 2 minutes. Turn potatoes over and microwave 2 more minutes. Remove from microwave and let cool slightly.","While potatoes are cooling, heat olive oil in large saucepan. Add garlic, onion, and bell pepper, and cook about 3 to 4 minutes.","Cube potatoes. Add juice, water, and vinegar to saucepan; bring to boil. Add shrimp, zucchini, potatoes, and seasoning. Return to boil, and simmer 5 to 8 minutes, until shrimp, potatoes, and zucchini are done. The flesh of the shrimp should be an opaque color.","Cut the lemon in half; squeeze juice from half the lemon into the saucepan.","Serve the Parmesan cheese and lemon wedges cut from the remaining lemon half."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"311.44 kcal","carbohydrateContent":"42.30 g","cholesterolContent":"88.35 mg","fiberContent":"4.92 g","proteinContent":"15.37 g","sodiumContent":"171.10 mg","sugarContent":"10.50 g","fatContent":"9.67 g","saturatedFatContent":"2.20 g"},"notes":"Serving Suggestions: Serve with an 8 ounce glass of fat-free (skim) milk, one slice whole-grain bread, and 1/2 peach, sliced.","contributor":"Produce for Better Health Foundation"},
{"slug":"yogurt-berry-parfait","source_url":"https://www.myplate.gov/recipes/yogurt-berry-parfait","name":"Yogurt Berry Parfait","description":"Enjoy this hearty snack or dessert, abounding with fresh fruit, granola, and any flavor of low-fat yogurt.","ingredients":[{"name":null,"items":["2 cups low fat yogurt (or fat-free, any flavor*)","1 cup banana (sliced)","1/2 cup blueberries (fresh)","1/2 cup strawberries (fresh, sliced)","other optional fruit (raspberries, peaches, pineapple and/or mangos)","1 cup granola"]}],"directions":[{"name":null,"steps":["Line up 4 parfait or other tall glasses.","Spoon 1/2 cup of yogurt into each glass.","Sprinkle with granola.","Top with about 1/4 cup of fruit."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 parfait","1/4 of recipe (214g)"],"calories":"258.55 kcal","carbohydrateContent":"43.23 g","cholesterolContent":"7.35 mg","fiberContent":"3.46 g","proteinContent":"9.47 g","sodiumContent":"129.64 mg","sugarContent":"26.93 g","fatContent":"5.63 g","saturatedFatContent":"1.60 g"},"notes":"*Low-fat vanilla yogurt used for costing and nutrient analysis.\nNote: Optional ingredients are not included in the nutrient or cost analysis.","contributor":"USDA Food and Nutrition Information Center"},
{"slug":"yogurt-fruit-salad","source_url":"https://www.myplate.gov/recipes/yogurt-fruit-salad","name":"Yogurt Fruit Salad","description":"Yogurt pulls all the flavors together in this splendid fruit salad! Use seasonal fruit if you have it on hand.","ingredients":[{"name":null,"items":["3/4 cup (6 ounces) low-fat vanilla yogurt","1/4 teaspoon cinnamon","1/16 cup (1 Tablespoon) orange juice","2 medium apples, chopped","1 banana, chopped"]}],"directions":[{"name":null,"steps":["Mix yogurt, cinnamon, and orange juice in a medium bowl.","Wash and chop the fruit and add to the yogurt mixture. Stir and serve."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"124.64 kcal","carbohydrateContent":"26.62 g","cholesterolContent":"2.54 mg","fiberContent":"2.73 g","proteinContent":"2.60 g","sodiumContent":"28.91 mg","sugarContent":"21.55 g","fatContent":"0.89 g","saturatedFatContent":"0.48 g"},"notes":null,"contributor":"Adapted from Splendid Fruit Salad, Iowa Department of Public Health\nIowa Nutrition Network"},
{"slug":"yogurt-pops","source_url":"https://www.myplate.gov/recipes/yogurt-pops","name":"Yogurt Pops","description":"A quick, easy, and delicious frozen dessert made with your favorite fruit juice and yogurt.","ingredients":[{"name":null,"items":["3/4 cup yogurt, fat-free (flavored or plain)","3/4 cup 100% fruit juice"]}],"directions":[{"name":null,"steps":["Put the yogurt and juice in a bowl.","Stir together well.","Pour the mix into paper cups.","Stick a popsicle stick in the center of the mix in the cup.","Place the yogurt pops in the freezer until they turn solid."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 pop","1/4 of recipe"],"calories":"52.64 kcal","carbohydrateContent":"10.03 g","cholesterolContent":"0.92 mg","fiberContent":"0.09 g","proteinContent":"2.60 g","sodiumContent":"36.78 mg","sugarContent":"9.47 g","fatContent":"0.20 g","saturatedFatContent":"0.06 g"},"notes":"Here are some good flavor mixes for yogurt pops:\nLemon yogurt with orange juice\nVanilla yogurt with raspberry juice\nYou can buy popsicle sticks in a crafts store, or in the crafts department of a discount store.\nYou can also use a popsicle mold.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"yogurt-popsicles","source_url":"https://www.myplate.gov/recipes/yogurt-popsicles","name":"Yogurt Popsicles","description":"This is a refreshing and flavorful frozen treat that would be perfect on a hot day -- or even on a cold day.","ingredients":[{"name":null,"items":["6 us fluid ounces frozen orange juice concentrate, thawed","2 cups low-fat vanilla yogurt"]},{"name":"Other Items Needed","items":["paper cups (3-ounce)","wooden sticks","aluminum foil"]}],"directions":[{"name":null,"steps":["In a medium bowl, combine thawed juice concentrate and yogurt. Stir until smooth.","Place paper cups close together on a baking sheet.","Pour yogurt/juice mixture into paper cups.","Cover the cups with a sheet of aluminum foil.","Insert stick for each freezer pop by making a slit in foil over the center of each cup. The aluminum foil serves to keep the sticks in place as the juice/yogurt mixture freezes.","Freeze popsicles until firm.","Run warm water on the outside of each cup to loosen each popsicle from the cup.","Store leftovers in a sealed container in the freezer."]}],"yield":"12 popsicles","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"56.45 kcal","carbohydrateContent":"10.35 g","cholesterolContent":"2.45 mg","fiberContent":"0.18 g","proteinContent":"2.51 g","sodiumContent":"29.03 mg","sugarContent":"9.36 g","fatContent":"0.66 g","saturatedFatContent":"0.41 g"},"notes":null,"contributor":"Eating Smart, Being Active\nColorado State University"},
{"slug":"yogurt-smoothie-bag","source_url":"https://www.myplate.gov/recipes/yogurt-smoothie-bag","name":"Yogurt Smoothie in a Bag","description":"No time? No blender? No problem! Grab a bag and get your smoothie started.","ingredients":[{"name":null,"items":["1/4 cup vanilla yogurt (non-fat or plain)","1 tablespoon low-fat milk (or skim)","2/3 tablespoon frozen fruit juice concentrated (2 teaspoons, thawed)"]}],"directions":[{"name":null,"steps":["Place ingredients in a sandwich size zip-top plastic bag.","Squish the bag until all ingredients are mixed, then stick a straw in a bag to drink the smoothie."]}],"yield":"1","nutrition":{"@type":"NutritionInformation","calories":"77.32"},"notes":"Orange juice concentrate used for costing and nutrition analysis.","contributor":"Purdue University Extension"},
{"slug":"yummy-bagels","source_url":"https://www.myplate.gov/recipes/yummy-bagels","name":"Homemade Bagles","description":"Did you know that you can make your own fresh, delicious, whole-grain rich bagels at home? This recipe makes enough to share with family and friends, or to f...","ingredients":[{"name":null,"items":["2 tablespoons sugar","1 tablespoon yeast","1 1/2 cups warm water","2 cups whole wheat flour","1 1/4 cups all-purpose flour","1 teaspoon canola oil (or cooking oil of your choice)","cinnamon (optional)","sugar (optional)","salt (optional)"]}],"directions":[{"name":null,"steps":["In a bowl mix sugar, yeast, water, and flours together to make dough.","Rub inside of another bowl with oil. Place dough in bowl and flip to coat with oil. Let rise 30 minutes.","Punch down dough and divide into 16 portions. Shape into a ball and poke a hole through the middle with your fingers.","Place on a well-greased baking sheet and cover with a clean dish towel to rise again for 15 to 20 minutes.","Put 2 inches of water in a pot and heat to boiling.","Using a slotted spoon, gently place each bagel into a rapidly boiling water for 1 minute on each side.","Remove and dry on a towel.","Place back on baking sheet. If desired, sprinkle bagels with cinnamon/sugar or salt.","Bake at 475 °F for 8 to 12 minutes."]}],"yield":"16","nutrition":{"@type":"NutritionInformation","calories":"97.57"},"notes":null,"contributor":"Originally named \"Yummy Bagels\" Adapted from: Cooking For You or Two\nUniversity of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"yummy-bean-dip","source_url":"https://www.myplate.gov/recipes/yummy-bean-dip","name":"Quick and Easy Bean Dip","description":"Beans make delicious dips for delectable snacks and side dishes.","ingredients":[{"name":null,"items":["1/3 cup beans, low-sodium canned or cooked (pinto beans work great)","1/3 tablespoon yogurt, non-fat plain (1 teaspoon)","1 tablespoon salsa"]}],"directions":[{"name":null,"steps":["Place beans in a small, resealable plastic bag. Squeeze out extra air and seal. Mash beans with fingers.","Add yogurt and salsa. Seal bag and mix with fingers.","Open bag or cut off corner of bag and squeeze out dip."]}],"yield":"1","nutrition":{"@type":"NutritionInformation","calories":"52.19"},"notes":"Enjoy dip with your favorite veggies, corn chips, pita bread wedges, or whole-wheat crackers.\nCanned pinto beans used for costing and nutrition analysis.","contributor":"Originally named: Yummy Bean Dip\nAdapted from: University of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"zesty-citrus-coleslaw","source_url":"https://www.myplate.gov/recipes/zesty-citrus-coleslaw","name":"Zesty Citrus Coleslaw","description":"This coleslaw is big on flavor with nuts, Mandarin oranges, and soy sauce!","ingredients":[{"name":null,"items":["4 cups shredded cabbage (or 16 ounce bag of coleslaw mix)","1 1/2 cups canned Mandarin oranges, drained","peanuts (optional)"]},{"name":"Dressing Ingredients","items":["2/3 cup fat-free Italian dressing","2 tablespoons low-sodium soy sauce"]}],"directions":[{"name":null,"steps":["Mix together the coleslaw mix, Mandarin oranges, and peanuts (if using) in a large bowl.","Stir in the Italian salad dressing and soy sauce."]}],"yield":"12 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/2 cup","calories":"26.41 kcal","carbohydrateContent":"5.95 g","cholesterolContent":"0.26 mg","fiberContent":"1.06 g","proteinContent":"0.94 g","sodiumContent":"248.67 mg","sugarContent":"4.83 g","fatContent":"0.16 g","saturatedFatContent":"0.05 g"},"notes":null,"contributor":"2009 Recipe Calendar\nAdapted from: Asian Coleslaw\nUniversity of Maryland Extension\nFood Supplement Nutrition Education Program"},
{"slug":"zesty-herb-salad-dressing","source_url":"https://www.myplate.gov/recipes/zesty-herb-salad-dressing","name":"Zesty Herb Salad Dressing","description":"Vinegar, orange juice, and herbs combine to give this dressing a sweet and tangy flavor. Season to your taste.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of your choice)","2 tablespoons vinegar","1/3 cup orange juice","1/2 teaspoon oregano","1/2 teaspoon basil","1/4 teaspoon black pepper","1/4 teaspoon salt"]}],"directions":[{"name":null,"steps":["Put all the ingredients in a jar or bottle with a lid.","Put on the lid. Shake well.","Chill in the fridge for at least 1 hour before serving."]}],"yield":"5 servings","nutrition":{"@type":"NutritionInformation","servingSize":["2 tablespoons dressing","1/5 of recipe"],"calories":"35.24 kcal","carbohydrateContent":"1.99 g","cholesterolContent":"0.00 mg","fiberContent":"0.21 g","proteinContent":"0.19 g","sodiumContent":"118.84 mg","sugarContent":"1.37 g","fatContent":"2.87 g","saturatedFatContent":"0.39 g"},"notes":"Try this dressing on cut vegetables or salad. After serving, keep any leftover dressing in the fridge.","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"zesty-lemon-fish","source_url":"https://www.myplate.gov/recipes/zesty-lemon-fish","name":"Zesty Lemon Fish","description":"Lemon pepper combined with lemon juice, onions, and parsley give this entrée loads of flavor and takes less than 30 minutes to cook. Pairs well with a salad...","ingredients":[{"name":null,"items":["1/2 pound fish fillets (whitefish, cod, or halibut)","1/2 onion, small (sliced)","2 tablespoons lemon juice","1/2 teaspoon canola oil (or cooking oil of your choice)","3/4 teaspoon lemon pepper seasoning","1/2 teaspoon dried parsley","dried paprika (optional)"]}],"directions":[{"name":null,"steps":["Separate fish into two serving size pieces. Place on an ungreased baking sheet.","Top with onion slices.","Drizzle lemon juice and oil evenly over fish.","Sprinkle lemon pepper, parsley, and dust with paprika (optional).","Cover and let stand for 5 minutes. Bake at 350 °F for 20 minutes, or until fish flakes easily with fork."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"94.06 kcal","carbohydrateContent":"4.41 g","cholesterolContent":"47.73 mg","fiberContent":"0.77 g","proteinContent":"16.49 g","sodiumContent":"230.66 mg","sugarContent":"1.81 g","fatContent":"1.42 g","saturatedFatContent":"0.14 g"},"notes":"Cod used for costing and nutrition analysis. Use other herbs or seasonings as desired.","contributor":"Cooking For You or Two\nUniversity of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"zesty-orange-carrots","source_url":"https://www.myplate.gov/recipes/zesty-orange-carrots","name":"Zesty Orange Carrots","description":"Colorful and flavorful, this carrot, honey, and cinnamon side dish will make your plate pop with color.","ingredients":[{"name":null,"items":["16 ounces carrots (peeled and cut into strips)","1/4 teaspoon ground cinnamon","1/2 orange","1 tablespoon honey","1 tablespoon butter alternative spread (0 g trans fat)","parsley, fresh (1 tablespoon, for appearance, optional)"]}],"directions":[{"name":null,"steps":["Bring about 2 cups of water to a gentle boil in saucepan.","Add carrots and cinnamon. Cook for about 10 minutes, until just tender.","While carrots are cooking, wash an orange and cut in half.","Squeeze juice out of the orange (remove seeds).","Use a sharp paring knife to carefully remove the orange ''zest'' from the peel. Try not to get any of the white part as it will taste bitter. Cut the zest into small slices.","When carrots are done, drain well.","Add the honey, margarine, and orange zest and toss into mix. Serve while hot."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"88.88 kcal","carbohydrateContent":"16.97 g","cholesterolContent":"0.04 mg","fiberContent":"3.55 g","proteinContent":"1.22 g","sodiumContent":"99.32 mg","sugarContent":"10.98 g","fatContent":"2.38 g","saturatedFatContent":"0.46 g"},"notes":"Could also use baby carrots","contributor":"Simple Healthy Recipes\nOklahoma Nutrition Information and Education\nONIE Project"},
{"slug":"zesty-pasta-primavera-salad","source_url":"https://www.myplate.gov/recipes/zesty-pasta-primavera-salad","name":"Zesty Pasta Primavera Salad","description":"Whole grain rotini and colorful vegetables elevate this pasta salad! Add canned chicken or tuna for a complete meal.","ingredients":[{"name":null,"items":["2 cups whole grain rotini pasta, uncooked*","3 tablespoons vegetable oil","3 tablespoons lemon juice","2 1/2 teaspoons Italian seasoning","1/8 teaspoon red pepper flakes","1 1/2 cups cucumber, chopped","1/2 cup cherry tomatoes, halved","1/2 cup carrots, sliced","1/4 cup red onion, minced","3 tablespoons Parmesan cheese","*Other types of whole grain pasta may be used in place of the whole grain rotini."]}],"directions":[{"name":null,"steps":["Cook pasta according to the package directions.","Drain and set aside.","In a large bowl, whisk oil, lemon juice, Italian seasoning, and red pepper flakes.","Add cooked pasta, cucumber, tomato, carrots, red onion, and Parmesan cheese to the dressing.","Mix well and chill for 2 hours before serving."]}],"yield":"10 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"129.97 kcal","carbohydrateContent":"17.82 g","cholesterolContent":"1.29 mg","fiberContent":"2.50 g","proteinContent":"3.83 g","sodiumContent":"29.18 mg","sugarContent":"1.52 g","fatContent":"5.58 g","saturatedFatContent":"0.96 g"},"notes":null,"contributor":"Recipe adapted from Chickasaw Nation Get Fresh! Nutrition Education Program"},
{"slug":"zesty-skillet-zucchini","source_url":"https://www.myplate.gov/recipes/zesty-skillet-zucchini","name":"Zesty Skillet Zucchini","description":"Tomato juice brings all of the flavors of the onion, mushrooms, tomatoes, and zucchini together in this summer dish.","ingredients":[{"name":null,"items":["1/2 cup tomato juice, low-sodium","1/4 teaspoon black pepper","1 medium onion","1 medium fresh tomato","1 cup mushroom (canned)","2 zucchini (medium)","1 teaspoon basil"]}],"directions":[{"name":null,"steps":["Peel the onion. Chop it into small pieces.","Chop the tomato.","Drain the water from the can of mushrooms.","Cut each zucchini into slices.","Put the tomato juice and pepper in a skillet or pan. Cook on high heat for 3 minutes.","Add the onion, tomato, and mushrooms.","Reduce the heat to medium-high. Cover and cook for 5 minutes.","Add the zucchini. Cover and cook for another 5 to 7 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (161g)","calories":"36.49 kcal","carbohydrateContent":"7.64 g","cholesterolContent":"0.00 mg","fiberContent":"2.01 g","proteinContent":"1.87 g","sodiumContent":"128.80 mg","sugarContent":"4.34 g","fatContent":"0.38 g","saturatedFatContent":"0.09 g"},"notes":"Serve this dish over rice or noodles, or eat it “as is.”","contributor":"Pennsylvania Nutrition Education Network"},
{"slug":"zingy-lemon-chicken-pasta","source_url":"https://www.myplate.gov/recipes/zingy-lemon-chicken-pasta","name":"Zingy Lemon Chicken Pasta","description":"This creamy pasta dish with a hint of lemon is sure to be a family favorite. Packed with chicken and topped with crunchy almonds, it can be baked and ready t...","ingredients":[{"name":null,"items":["8 ounces whole wheat spaghetti, uncooked","1 tablespoon tub margarine","1 tablespoon olive oil","1 1/4 lbs. boneless, skinless chicken breast (cut into 3/4-inch pieces)","5 green onions (scallions), sliced","1 clove large garlic, minced","1/4 cup all-purpose flour","1/4 teaspoon salt","1/8 teaspoon black pepper","1/8 teaspoon cayenne pepper","1 1/3 cups chicken broth","2/3 cup skim milk","2 teaspoons prepared mustard","1/4 cup freshly squeezed lemon juice"]},{"name":"For Topping","items":["1/4 cup chopped almonds","2 tablespoons chopped chives or green onions (scallions)","1/4 teaspoon paprika (optional)"]}],"directions":[{"name":null,"steps":["Combine flour, salt, pepper, and cayenne in a saucepan; gradually add chicken broth and skim milk, stirring with a wire whisk until smooth.","Place over medium heat and cook, stirring constantly, until thickened. Add mustard and lemon juice. Allow to cool.","Heat margarine and oil in a skillet. Add chicken pieces, green onions, and garlic. Sauté until chicken is just firm and cooked through, about 10 minutes.","Prepare pasta according to package directions and drain. Combine sauce, chicken, and pasta mixture.","Put into a 2 1/2 quart casserole dish. Sprinkle top with almonds, chopped chives, and paprika (if using).","Bake at 375 °F for 10 minutes or until heated through."]}],"yield":"4 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1 serving","calories":"560.72 kcal","carbohydrateContent":"61.70 g","cholesterolContent":"95.09 mg","fiberContent":"8.40 g","proteinContent":"44.79 g","sodiumContent":"299.32 mg","sugarContent":"4.52 g","fatContent":"16.83 g","saturatedFatContent":"2.61 g"},"notes":"Serving Suggestions: Serve with steamed broccoli, skim milk, and apple slices.","contributor":"MyPlate National Strategic Partners\nThe Grain Chain"},
{"slug":"zucchini-and-tomatoes","source_url":"https://www.myplate.gov/recipes/zucchini-and-tomatoes","name":"Zucchini And Tomatoes","description":"Spend less time cooking and more time enjoying your summer with this fast and delicious summer veggie side dish. Pairs well with grilled meat, fish, or tofu....","ingredients":[{"name":null,"items":["2 tablespoons butter (or cooking oil of your choice)","1/4 cup onion (chopped)","1 garlic clove (minced)","1 pound zucchini (sliced)","2 tomatoes (peeled and diced, or a 16 ounce can of diced tomatoes, drained)","1/4 teaspoon salt","black pepper (to taste)","1 teaspoon sugar"]}],"directions":[{"name":null,"steps":["Melt butter or oil in a saucepan over medium heat.","Add onion and garlic.","Cook until tender, about 5 to 7 minutes.","Add zucchini, tomatoes, and seasonings.","Cover pan, reduce heat, and cook until vegetables are tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/4 of recipe","calories":"91.77 kcal","carbohydrateContent":"8.16 g","cholesterolContent":"15.27 mg","fiberContent":"2.07 g","proteinContent":"2.08 g","sodiumContent":"160.13 mg","sugarContent":"6.12 g","fatContent":"6.33 g","saturatedFatContent":"3.70 g"},"notes":null,"contributor":"University of Wyoming Cooperative Extension"},
{"slug":"zucchini-au-gratin","source_url":"https://www.myplate.gov/recipes/zucchini-au-gratin","name":"Zucchini Au Gratin","description":"A fast and delicious way to prepare the zucchini or yellow squash flooding your garden or market this summer.","ingredients":[{"name":null,"items":["4 cups zucchini (thinly sliced)","1/2 cup onion (sliced)","2 tablespoons water","1 tablespoon margarine","black pepper (to taste)","3 tablespoons Parmesan cheese (grated)"]}],"directions":[{"name":null,"steps":["Wash and slice vegetables. Place zucchini, onion, water, margarine, and pepper in a frying pan. Cover and cook over medium heat for one minute.","Remove cover and cook until crisp-tender, about 10 minutes.","Turn with large spoon to cook evenly.","Sprinkle with cheese; toss lightly.","Serve at once."]}],"yield":"7 servings","nutrition":{"@type":"NutritionInformation","servingSize":["3/4 cup","1/7 of recipe"],"calories":"35.29 kcal","carbohydrateContent":"3.46 g","cholesterolContent":"1.86 mg","fiberContent":"0.84 g","proteinContent":"1.46 g","sodiumContent":"47.23 mg","sugarContent":"2.18 g","fatContent":"2.01 g","saturatedFatContent":"0.65 g"},"notes":"Can be served over rice or noodles.\nGreen pepper can be used instead of onion.\nSummer squash can be used instead of zucchini.","contributor":"Eating Right Is Basic\nMichigan State University Cooperative Extension Service\nNutrition Education Program"},
{"slug":"zucchini-bread","source_url":"https://www.myplate.gov/recipes/zucchini-bread","name":"Zucchini Bread","description":"This tasty zucchini bread can be eaten as a dessert or snack. Serve warm or cooled.","ingredients":[{"name":null,"items":["3 eggs","1 cup sugar","1/4 cup vegetable oil (or cooking oil of your choice)","2 cups zucchini (grated)","1/2 teaspoon vanilla","1 1/2 cups flour (all-purpose)","1 1/2 cups whole wheat flour","1 teaspoon salt","2 teaspoons baking soda","2 teaspoons cinnamon","1/2 teaspoon baking powder","1/2 cup raisins"]}],"directions":[{"name":null,"steps":["Preheat oven to 325 °F","Lightly grease and flour a 9x5 loaf pan.","In a large mixing bowl, beat eggs lightly. Add sugar, oil, zucchini, and vanilla and beat.","In a separate bowl, measure dry ingredients and stir to combine. Add raisins.","Add dry ingredients to the egg mixture. Stir just until all ingredients are moistened.","Spoon into loaf pan.","Bake at 325 °F for 50 minutes. Test for doneness by inserting a toothpick in the center. It should come out dry.","Allow loaf to cool 5 to 10 minutes before turning out onto a cooling rack.","Serve warm or allow to cool before slicing."]}],"yield":"16 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"194.60 kcal","carbohydrateContent":"34.34 g","cholesterolContent":"38.53 mg","fiberContent":"2.06 g","proteinContent":"4.19 g","sodiumContent":"334.80 mg","sugarContent":"16.22 g","fatContent":"4.93 g","saturatedFatContent":"0.86 g"},"notes":null,"contributor":"Favorite Recipes for Family Meals\nWashington State University Extension"},
{"slug":"zucchini-casserole","source_url":"https://www.myplate.gov/recipes/zucchini-casserole","name":"Zucchini Casserole","description":"Full of delicious summer vegetables combined with sausage and potatoes, this is a hearty main dish or an easy meal. Try using fresh tomatoes and Italian herb...","ingredients":[{"name":null,"items":["16 ounces ground sausage (1 pound)","1 small onion (diced)","3 small zucchinis (diced)","3 small yellow squashes (diced)","3 medium potatoes (peeled and diced)","1 can low-sodium canned tomatoes (14.5 oz Italian stewed)"]}],"directions":[{"name":null,"steps":["Preheat oven to 350 °F.","Brown sausage and onion together in a skillet; drain.","Mix all ingredients together and place in a casserole dish.","Cover with foil and bake at 350 °F for 45 minutes."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe (292g)","calories":"381.28 kcal","carbohydrateContent":"30.63 g","cholesterolContent":"65.02 mg","fiberContent":"5.58 g","proteinContent":"19.07 g","sodiumContent":"641.62 mg","sugarContent":"9.78 g","fatContent":"21.44 g","saturatedFatContent":"6.90 g"},"notes":"Instead of using the Italian stewed tomatoes, you could use fresh diced tomatoes with some Italian spices added.","contributor":"Ross County Recipes\nOhio State University Cooperative Extension"},
{"slug":"zucchini-coleslaw","source_url":"https://www.myplate.gov/recipes/zucchini-coleslaw","name":"Zucchini Coleslaw","description":"This colorful dish is a delicious alternative to the sweet coleslaw and a great way to eat your veggies.","ingredients":[{"name":null,"items":["2 cups zucchini (coarsely shredded)","2 cups cabbage (shredded)","1 medium carrot (shredded)","2 green onions (scallions) (sliced)","1/2 cup radishes (thinly sliced)","1/3 cup low-fat mayonnaise","1/3 cup mild salsa"]}],"directions":[{"name":null,"steps":["Drain zucchini by pressing between layers of paper towels.","Put zucchini in large bowl; add cabbage, carrots, onions, and radishes.","In a small bowl, combine remaining ingredients.","Pour over vegetables and toss well.","Cover and chill at least one hour."]}],"yield":"6 servings","nutrition":{"@type":"NutritionInformation","servingSize":"1/6 of recipe","calories":"56.22 kcal","carbohydrateContent":"6.34 g","cholesterolContent":"2.20 mg","fiberContent":"1.84 g","proteinContent":"1.24 g","sodiumContent":"192.09 mg","sugarContent":"3.46 g","fatContent":"3.27 g","saturatedFatContent":"0.52 g"},"notes":null,"contributor":"Kentucky Families on the Move: Food and Nutrition Calendar, 2005\nUniversity of Kentucky Cooperative Extension Service"},
{"slug":"zucchini-pancakes","source_url":"https://www.myplate.gov/recipes/zucchini-pancakes","name":"Zucchini Pancakes","description":"Try this veggie side dish with different variations by adding combinations of your favorite veggies. Grated carrots, spinach, cauliflower, or broccoli all wo...","ingredients":[{"name":null,"items":["2 cups zucchini (grated)","1 tablespoon onion (finely chopped)","1 egg, beaten","1 1/2 tablespoons flour","1 tablespoon Parmesan cheese","1/4 teaspoon dried parsley","1/2 teaspoon garlic powder","salt and pepper (to taste, optional)","1 tablespoon olive oil (or cooking spray)"]}],"directions":[{"name":null,"steps":["Grate zucchini and mix with the other ingredients, except the oil. Blend well.","Form the mixture into patties 3 to 4 inches in diameter.","Heat the oil. Cook pancakes for 3 to 4 minutes per side. Remove and drain on paper towels."]}],"yield":"2 Servings","nutrition":{"@type":"NutritionInformation","servingSize":"1","calories":"154.76 kcal","carbohydrateContent":"9.82 g","cholesterolContent":"104.90 mg","fiberContent":"1.45 g","proteinContent":"5.87 g","sodiumContent":"73.90 mg","sugarContent":"3.26 g","fatContent":"10.61 g","saturatedFatContent":"2.40 g"},"notes":null,"contributor":"University of Wyoming Extension\nCent$ible Nutrition Program"},
{"slug":"zucchini-recipe","source_url":"https://www.myplate.gov/recipes/zucchini-recipe","name":"Zucchini Recipe","description":"This zucchini recipe brings you a flavorful dish loaded with vegetables and low-fat dairy.","ingredients":[{"name":null,"items":["2 cups zucchini (chopped)","1/2 cup onion (diced)","1/4 green or red pepper","1 egg","1/4 cup low-fat milk","2 tablespoons canola oil","1 tablespoon garlic and herb seasoning mix","1/4 cup Parmesan cheese","1/4 cup cheese, low-fat shredded (use your favorite)"]}],"directions":[{"name":null,"steps":["Wash and chop zucchini, measure out about 2 cups.","Dice the onion and pepper, set aside along with the zucchini.","Stir the egg and milk together and set aside.","Sauté the vegetables in oil on medium heat. Remove from the pan.","Scramble the egg mixture until cooked thoroughly. Stir in the vegetable mixture and fold together.","Cook together until temperature reaches 145 °F.","Sprinkle the seasoning and cheese on top. When the cheese is melted, serve warm.","Add fresh or other dried herbs as desired."]}],"yield":"4","nutrition":{"@type":"NutritionInformation","calories":"151.28"},"notes":null,"contributor":null},
{"slug":"zucchini-stir-fry","source_url":"https://www.myplate.gov/recipes/zucchini-stir-fry","name":"Zucchini Stir Fry","description":"Enjoy your zucchini bumper crop or farmers market bounty with this quick and easy vegetable side dish.","ingredients":[{"name":null,"items":["1 tablespoon vegetable oil (or cooking oil of your choice)","1 medium onion","1 medium yellow squash","1 medium zucchini","1 red pepper","1/2 teaspoon black pepper","1/4 teaspoon basil","1/4 teaspoon oregano"]}],"directions":[{"name":null,"steps":["Peel and chop the onion.","Cut the yellow squash and zucchini into small pieces.","Chop the red pepper into small pieces.","Heat the oil in a frying pan. Add the onion.","Cook over medium heat, stirring quickly for 1 minute.","Add the spices and stir a few times.","Add remaining vegetables and cook for 3 to 5 minutes until vegetables are just tender."]}],"yield":"4 servings","nutrition":{"@type":"NutritionInformation","servingSize":["1 1/2 cup prepared stir fry","1/4 of recipe"],"calories":"72.69 kcal","carbohydrateContent":"9.04 g","cholesterolContent":"0.00 mg","fiberContent":"2.11 g","proteinContent":"1.79 g","sodiumContent":"6.98 mg","sugarContent":"5.41 g","fatContent":"3.90 g","saturatedFatContent":"0.59 g"},"notes":null,"contributor":"Pennsylvania Nutrition Education Network"}
]'::jsonb) as x(
  slug text, source_url text, name text, description text, ingredients jsonb, directions jsonb, yield text, nutrition jsonb, notes text, contributor text
)
on conflict (slug) do update set
  source_url = excluded.source_url,
  name = excluded.name,
  description = excluded.description,
  ingredients = excluded.ingredients,
  directions = excluded.directions,
  yield = excluded.yield,
  nutrition = excluded.nutrition,
  notes = excluded.notes,
  contributor = excluded.contributor;
